(window.GIM_TUR_P=window.GIM_TUR_P||{})["SCM.11"]={"from":388,"s":[["\u0003הלכות מאבד ממון חבירו בידים ומוסר ומלשין\u0004\nהַמַּזִּיק \u0010y0\u0011 מָמוֹן \u0010c0\u0011 חֲבֵרוֹ וְאֵינוֹ יוֹדֵע מַה הִזִּיק, נִשְׁבָּע הַנִּזָּק וְנוֹטֵל. כֵּיצַד, לָקַח כִּיס \u0010c1\u0011 חֲבֵרוֹ וְהִשְׁלִיכוֹ לַמַּיִם אוֹ לָאֵשׁ אוֹ שֶׁמְּסָרוֹ לְיַד אַנָּס, וְאָבַד, בַּעַל הַכִּיס אוֹמֵר: זְהוּבִים הָיָה מָלֵא, וְהַמַּזִּיק אוֹמֵר: אֵינִי יוֹדֵעַ מֶה הָיָה בּוֹ, שֶׁמָּא עָפָר אוֹ תֶּבֶן הָיָה מָלֵא, הֲרֵי הַנִּזָּק נִשְׁבָּע בִּנְקִיטַת חֵפֶץ וְנוֹטֵל. וְהוּא שֶׁיִּטְעֹן דְּבָרִים שֶׁהוּא אָמוּד בָּהֶם \u0010c2\u0011 אוֹ אָמוּד לְהַפְקִידָם אֶצְלוֹ וְדַרְכָּן לְהַנִּיחָם בְּכִיס וְכַיּוֹצֵא בּוֹ. \u0010y1\u0011 \u0005אַרְנָקִי בְּשַׂק, אִם הוּא שַׁבָּת וְיו\"ט, מִקְרֵי דַּרְכּוֹ בְכָךְ, וְכָל כַּיּוֹצֵא בְזֶה (מָרְדְּכַי פֶּרֶק הַכּוֹנֵס)\u0006. \u0010y2\u0011 אֲבָל אִם אֵין דַּרְכָּם לְהַנִּיחָם בִּכְלִי זֶה, \u0010c3\u0011 הוּא פָּשַׁע בְּעַצְמוֹ \u0005וּפָטוּר הַמַּזִּיק.\u0006 כֵּיצַד, \u0010c4\u0011 הֲרֵי שֶׁחָטַף חֵמֶת אוֹ סַל מְלֵאִים וּמְחֻפִּים וְהִשְׁלִיכָם לַיָּם אוֹ שְׂרָפָם, וְטָעַן הַנִּזָּק שֶׁמַּרְגָּלִיּוֹת הָיוּ בְּתוֹכָהּ, \u0010c5\u0011 אֵינוֹ נֶאֱמָן. \u0005וְיֵשׁ אוֹמְרִים דַּאֲפִלּוּ הָיוּ עֵדִים שֶׁהָיוּ שָׁם, פָּטוּר, הוֹאִיל וּפָשַׁע, כְּמוֹ שֶׁנִּתְבָּאֵר (הַמַּגִּיד פ\"ז דְּחוֹבֵל בְּשֵׁם תוס' וע\"ל ס\"ק ו')\u0006. \u0010c6\u0011 וְאִם תָּפַס, אֵין מוֹצִיאִין מִיָּדוֹ. \u0010c7\u0011 \u0005וְיֵשׁ חוֹלְקִין (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. וְיִשָּׁבַע שֶׁמַּרְגָּלִיּוֹת הָיָה בְּתוֹכוֹ, וְנוֹטֵל מַה שֶּׁיֵּשׁ אֶצְלוֹ, וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0010c8\u0011 וְאִם יָדַע הַמַּזִּיק שֶׁהַכִּיס הָיָה בּוֹ זְהוּבִים, אֲבָל אֵינוֹ יוֹדֵעַ כַּמָּה הָיוּ, אִם הַנִּזָּק אוֹמֵר: אֶלֶף, נוֹטֵל אֶלֶף בְּלֹא שְׁבוּעָה, וְהוּא שֶׁיִּהְיֶה אָמוּד, שֶׁהֲרֵי הַמַּזִּיק מְחֻיָּב שְׁבוּעָה וְאֵינוֹ יָכוֹל \u0010c9\u0011 לִשָּׁבַע. \u0005וְיֵשׁ אוֹמְרִים דְּנִשְׁבַּע הַנִּזָּק וְנוֹטֵל, וְכֵן עִקָּר (טוּר סִימָן צ' בְּשֵׁם הָרַאֲבַ\"ד וְהַמַּגִּיד פֶּרֶק הַנַּ\"ל וְהָרֹא\"שׁ)\u0006. \u0010c10\u0011\nהַמּוֹסֵר מָמוֹן בִּידֵי אַנָּס, בֵּין אַנָּס גּוֹי בֵּין אַנָּס יִשְׂרָאֵל, חַיָּב לְשַׁלֵּם \u0010y3\u0011 \u0010c11\u0011 מֵהַיָּפֶה שֶׁבִּנְכָסָיו כָּל מַה שֶּׁלָּקַח הָאַנָּס, אַף עַל פִּי שֶׁלֹּא נָשָׂא הַמּוֹסֵר, וְלֹא נָתַן בְּיָדוֹ \u0010y4\u0011 \u0010c12\u0011 אֶלָּא הִרְגִּיל בִּלְבַד. \u0010c13\u0011 וְאִם מֵת, גּוֹבִים מִיּוֹרְשָׁיו כִּשְׁאָר כָּל הַמַּזִּיקִים. \u0010c14\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּדַוְקָא שֶׁעָמַד בַּדִּין; אֲבָל אִם לֹא עָמַד בַּדִּין, אֵין הַיּוֹרְשִׁין חַיָּבִין לְשַׁלֵּם. וְאִשָּׁה שֶׁמָּסְרָה, מְשַׁמְּתִינָן לָהּ. וְאִם יֵשׁ לָהּ מָמוֹן שֶׁאֵין לַבַּעַל רְשׁוּת בּוֹ, מְשַׁלֶּמֶת. וְאִם יֵשׁ לָהּ נִכְסֵי מְלוֹג, \u0010y5\u0011 \u0010c15\u0011 הַבַּעַל אוֹכֵל פֵּרוֹת כָּל יְמֵי חַיֶּיהָ, וְאִם מֵתָה חַיָּב לְשַׁלֵּם לַנִּמְסָר, וְכֵן לִשְׁאָר \u0010c16\u0011 נִזָּק, וְאֵין הַבַּעַל \u0010y6\u0011 לְעִנְיַן זֶה רַק כְּיוֹרֵשׁ שֶׁחַיָּב לְשַׁלֵּם (מָרְדְּכַי פֶּרֶק הַחוֹבֵל)\u0006. בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁהֶרְאָה הַמּוֹסֵר מֵעַצְמוֹ. אֲבָל אִם אֲנָסוּהוּ גּוֹיִים אוֹ יִשְׂרָאֵל אַנָּס לְהַרְאוֹת, וְהֶרְאָה, הֲרֵי זֶה פָּטוּר מִתַּשְׁלוּמִין. \u0005וְאִם אָנְסוֹ לְהַרְאוֹת שֶׁלּוֹ \u0010y7\u0011 \u0010c17\u0011 וְהֶרְאָה [שֶׁלּוֹ וְ] שֶׁל חֲבֵרוֹ, חַיָּב (טוּר ס\"א)\u0006. וְאִם נָשָׂא וְנָתַן בְּיָד, אַף עַל פִּי שֶׁהוּא אָנוּס, חַיָּב לְשַׁלֵּם, שֶׁהַמַּצִּיל עַצְמוֹ בְּמָמוֹן \u0010y8\u0011 \u0010c18\u0011 חֲבֵרוֹ חַיָּב. כֵּיצַד, \u0010c19\u0011 הֲרֵי שֶׁגָּזַר הַמֶּלֶךְ לְהָבִיא לוֹ יַיִן אוֹ תֶבֶן וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ, וְעָמַד מוֹסֵר וְאָמַר: הֲרֵי יֵשׁ לִפְלוֹנִי אוֹצַר יַיִן אוֹ תֶבֶן בְּמָקוֹם פְּלוֹנִי, וְהָלְכוּ וּלְקָחוּהוּ, חַיָּב לְשַׁלֵּם. \u0005הַגָּה: \u0010c20\u0011 וַאֲפִלּוּ יִסְּרוּהוּ, וְלֹא אָמְרוּ לוֹ עַל מָה, וְהֶרְאָה מָמוֹן חֲבֵרוֹ, חַיָּב (טוּר שָׁם)\u0006 ; וְלֹא מִקְרֵי אוֹנֶס, אֶלָּא הַכָּאוֹת וְיִסּוּרִין, \u0010c21\u0011 אֲבָל לֹא אֹנֶס מָמוֹן \u0005(מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא וּתְשׁוּבַת מַיְמוֹנִי דִנְזִיקִין סי\"ב וְנ\"י)\u0006. \u0010y9\u0011 הָיָה רוֹאֶה נֶזֶק בָּא עָלָיו, מֻתָּר לְהַצִּיל עַצְמוֹ אַף עַל פִּי שֶׁעַל יְדֵי זֶה בָּא הַנֶּזֶק לְאַחֵר \u0010y10\u0011 \u0010c22\u0011 \u0005(נִמּוּקֵי יוֹסֵף פֶּרֶק הַשֻּׁתָּפִין)\u0006.\nאֲנָסוֹ הַמֶּלֶךְ לְמוֹסֵר זֶה עַד שֶׁיַּרְאֶה לוֹ מָמוֹן חֲבֵרוֹ שֶׁהוּא בּוֹרֵחַ מִלְּפָנָיו, \u0010y11\u0011 וְהֶרְאָה לוֹ מִפְּנֵי הָאֹנֶס, הֲרֵי זֶה פָּטוּר, שֶׁאִם לֹא יַרְאֶה לוֹ יַכֵּהוּ אוֹ יְמִיתֵהוּ. \u0010c23\u0011\nנָשָׂא מָמוֹן חֲבֵרוֹ בְּיָדוֹ וּנְתָנוֹ לָאַנָּס, חַיָּב לְשַׁלֵּם \u0010y12\u0011 מִכָּל מָקוֹם, אַף עַל פִּי שֶׁהַמֶּלֶךְ אֲנָסוֹ לְהָבִיא. \u0005ב' שֻׁתָּפִים שֶׁהָיָה לָהֶן חוֹב בְּיַחַד, וְאָנַס שַׂר לְאֶחָד לִפְטֹר הַחוֹב, פָּטוּר, \u0010y13\u0011 \u0010c24\u0011 דְּזֶה לֹא מִקְרֵי נָתַן בְּיָד (מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁאִם אֲנָסוֹ לְהָבִיא וְהֵבִיא חַיָּב, כְּשֶׁלֹא הִגִּיעַ הַמָּמוֹן לִרְשׁוּת הָאַנָּס; אֲבָל אַנָּס שֶׁאָנַס אֶת יִשְׂרָאֵל עַד שֶׁהֶרְאָהוּ, וְעָמַד הָאֲנָס עַל הַמָּמוֹן וְנַעֲשָׂה בִּרְשׁוּתוֹ \u0005דְּהַיְנוּ שֶׁיּוּכַל לִשְׁלֹט עָלָיו וְלִטְּלוֹ (הַמַּגִּיד פ\"ח דְּחוֹבֵל)\u0006, וְאָנַס אֶת יִשְׂרָאֵל עַד שֶׁהוֹלִיכוּ לְמָקוֹם אַחֵר, וַאֲפִלּוּ הוֹלִיכוֹ זֶה הַמּוֹסֵר שֶׁהֶרְאָהוּ, הֲרֵי זֶה פָּטוּר, \u0010y14\u0011 שֶׁכֵּיוָן שֶׁעָמַד הָאַנָּס בְּצַד הָאוֹצָר כְּבָר אָבַד כָּל מַה שֶּׁיֵּשׁ בּוֹ, וּכְאִלּוּ נִשְׂרַף:\nבַּעֲלֵי דִין שֶׁהָיְתָה בֵינֵיהֶם מְרִיבָה עַל הַקַּרְקַע אוֹ עַל מִטַּלְטְלִין, זֶה אוֹמֵר: שֶׁלִּי, וְזֶה אוֹמֵר: שֶׁלִּי, עָמַד אֶחָד מֵהֶם \u0010y15\u0011 וּמְסָרָהּ בְּיַד גּוֹיִים, מְנַדִּין אוֹתוֹ עַד שֶׁיַּחֲזִיר הַדָּבָר לִכְמוֹת שֶׁהָיָה, וִיסַלֵּק יַד אַנָּס מִבֵּינֵיהֶם וְיַעֲשׂוּ דִּין בְּיִשְׂרָאֵל. \u0005הַגָּה: \u0010c25\u0011 מִכָּל מָקוֹם אֵין לוֹ דִּין מוֹסֵר, אַף עַל פִּי שֶׁהִפְסִיד חֲבֵרוֹ עַל יְדֵי זֶה הַרְבֵּה, דְּלָא מִקְרֵי מוֹסֵר אֶלָּא בְּמִתְכַּוֵּן לְהַזִּיק, אֲבָל לֹא בְּמִתְכַּוֵּן לְהוֹצִיא אֶת שֶׁלּוֹ (תְּשׁוּבַת מיי' דִּנְזִיקִין סִימָן כ\"א וּמָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא בְּשֵׁם ר\"א)\u0006. וְיֵשׁ חוֹלְקִין \u0010y16\u0011 וּסְבִירָא לְהוּ דְּמִקְּרֵי מוֹסֵר וְחַיָּב לְשַׁלֵּם לוֹ כָּל הֶזֵּקוֹ, אִם לֹא הָיָה חֲבֵרוֹ סַרְבָן; וְכָל שֶׁכֵּן אִם הִתְרוּ בּוֹ תְּחִלָּה שֶׁלֹּא יִדּוֹנוּ בִּפְנֵי גּוֹיִם, וְעָבַר, שֶׁיֵּשׁ לוֹ דִין מוֹסֵר \u0005(מָרְדְּכַי פֶּרֶק הַגּוֹזֵל קַמָּא בְּשֵׁם מַהֲרַ\"ם וּפֶרֶק הַמַּנִיחַ וּתְשׁוּבַת הָרֹא\"שׁ כְּלָל י\"ז סִימָן ד' וּמַהֲרִי\"ק שֹׁרֶשׁ קנ\"ד וקס\"א)\u0006. \u0010c26\u0011\nמִי שֶׁנִּתְפַּס עַל חֲבֵרוֹ, וְלָקְחוּ גוֹיִים מָמוֹן מִמֶּנּוּ בִּגְלַל \u0010y17\u0011 חֲבֵרוֹ, אֵין חֲבֵרוֹ חַיָּב לְשַׁלֵּם. אֵין לְךָ מִי שֶׁנִּתְפַּס עַל חֲבֵרוֹ וְיִהְיֶה חֲבֵרוֹ חַיָּב לְשַׁלֵּם לוֹ, חוּץ מֵהַנִּתְפַּס \u0010y18\u0011 מִפְּנֵי הַמַּס הַקָּצוּב עַל כָּל אִישׁ וְאִישׁ בְּכָל שָׁנָה, אוֹ הַנִּתְפַּס עַל הַתְּשׁוּרָה שֶׁנּוֹתֵן כָּל אִישׁ לַמֶּלֶךְ בְּעָבְרוֹ עֲלֵיהֶם אוֹ חַיָּלוֹתָיו, הֲרֵי זֶה חַיָּב לְשַׁלֵּם לוֹ; וְהוּא שֶׁיִּקְּחוּ מִמֶּנּוּ בְּפֵרוּשׁ בִּגְלַל פְּלוֹנִי, בִּפְנֵי עֵדִים; וְנִתְבָּאֵר עוֹד בְּסִימָן קכ\"ח. \u0010y19\u0011 \u0010c27\u0011\nמִי שֶׁיֵּשׁ עָלָיו עֵדִים שֶׁמָּסַר מָמוֹן חֲבֵרוֹ, כְּגוֹן שֶׁהֶרְאָה מֵעַצְמוֹ \u0010c28\u0011 אוֹ שֶׁנֶּאֱנַס \u0010c29\u0011 וְנָשָׂא וְנָתַן, וְלֹא יָדְעוּ הָעֵדִים כַּמָּה הִפְסִידוֹ בִּמְסִירָתוֹ, וְהַנִּמְסָר אוֹמֵר: כָּךְ וְכָךְ הִפְסִידָנִי, \u0010c30\u0011 וְהַמּוֹסֵר כּוֹפֵר בַּמֶּה שֶׁטָּעֲנוֹ, \u0010y20\u0011 \u0010c31\u0011 אִם תָּפַס הַנִּמְסַר אֵין מוֹצִיאִין מִיָּדוֹ, אֶלָּא נִשְׁבָּע בִּנְקִיטַת חֵפֶץ וְזוֹכֶה בַּמֶּה שֶׁתָּפַס. \u0010c32\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּבִסְפֵיקָא דְדִינָא לָא מְהַנֵּי תְּפִיסָה (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006 \u0005(וע\"ל ס\"ק ל\"ב)\u0006. וְאִם לֹא תָּפַס, אֵין מוֹצִיאִין מִן הַמּוֹסֵר אֶלָּא \u0010c33\u0011 בִּרְאָיָה בְּרוּרָה. \u0005וְאִם [לֹא] יָדְעוּ בֵּרוּר הַדְּבָרִים, \u0010y21\u0011 \u0010c34\u0011 רַק שֶׁהֻצְרַךְ לְהִתְפַּשֵּׁר עִם הַשַּׂר בְּכָךְ וְכָךְ, הַנִּמְסַר נִשְׁבָּע וְנוֹטֵל. (מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006 \u0010c35\u0011 וְיֵשׁ \u0010c36\u0011 מִי שֶׁאוֹמֵר, שֶׁאִם הַמּוֹסֵר אוֹמֵר: \u0010c37\u0011 אֵינִי יוֹדֵעַ כַּמָּה הִפְסַדְתָּ עַל יָדִי, יִשָּׁבַע הַנִּמְסַר וְיִטֹּל. \u0005הַגָּה: (וע\"ל ס\"ק \u0010c38\u0011 ל\"ז)\u0006 וְכָל זֶה בְּמוֹסֵר מָמוֹן; אֲבָל מָסַר גּוּפוֹ שֶׁל חֲבֵרוֹ \u0005(לַאֲנָסִים)\u0006, הַנִּמְסַר נִשְׁבָּע וְנוֹטֵל. וְכֵן אִם גָּרַם לוֹ תְּפִיסָה, \u0010y22\u0011 דְּהָוֵי כְּמַזִּיק בְּיָדַיִם וְצָרִיךְ לְשַׁלֵּם לוֹ כָּל הֶזֵּקוֹ \u0005(מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006. \u0010y23\u0011 \u0010c39\u0011 הָאוֹמֵר לַחֲבֵרוֹ: מְסַרְתַּנִי, וְהוּא כּוֹפֵר, יִשָּׁבַע לוֹ הֶסֵּת \u0005(הַגָּהוֹת אֲשֵׁירִי)\u0006. וְיֵשׁ אוֹמְרִים דְּצָרִיךְ לִשָּׁבַע לוֹ לִפְנֵי הַשַּׂר שֶׁלֹּא מְסָרוֹ לוֹ \u0005(מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006. \u0010c40\u0011 וְאֵין צָרִיךְ לַעֲשׂוֹת נְקִיּוּת זוֹ, אֶלָּא עַל פִּי אֶחָד הַמֵּעִיד שֶׁמְּסָרוֹ, אֲבָל אֵין הַגּוֹיִים נֶאֱמָנִים בְּכָךְ \u0005(מָרְדְּכַי פֶּרֶק הַחוֹבֵל וּפֶרֶק הַפָּרָה וּפִסְקֵי מהרא\"י סִימָן פ\"ג וּתְשׁוּבַת רַשְׁבָּ\"א סִימָן אֶלֶף \u0010c41\u0011 צ\"ח)\u0006. שְׁנַיִם שֶׁמָּסְרוּ בְּיַחַד, כָּל אֶחָד מְשַׁלֵּם הַחֵצִי, וְאִם בְּזֶה אַחַר זֶה, הָאַחֲרוֹן פָּטוּר, \u0010c42\u0011 דְּכָל זְמַן שֶׁלֹּא נִפְטַר מִמְּסִירָה הָרִאשׁוֹנָה הַנֶּזֶק בָּא מִגְּרַם הָרִאשׁוֹן \u0005(מָרְדְּכַי פֶּרֶק הַפָּרָה)\u0006. \u0010y24\u0011 \u0010c43\u0011 וַאֲפִלּוּ לֹא מְסָרוֹ, רַק רָאָה אַנָּס אוֹ גוֹיִים שֶׁיַּגִּידוּ לַשַּׂר \u0010c44\u0011 \u0005(מַהֲרַ\"ם מֵרִיזְבּוּרְק)\u0006. יֵשׁ אוֹמְרִים דְּאָדָם הַמֻּכֶּה מֵחֲבֵרוֹ יָכוֹל לֵילֵךְ לִקְבֹּל לִפְנֵי גוֹיִים, אַף עַל פִּי דְגוֹרֵם לַמַּכֶּה הֶזֵּק גָּדוֹל \u0005(מָרְדְּכַי הַנַּ\"ל ומהרי\"ו סִימָן כ\"ח וּתְשׁוּבַת מַיְמוֹנִי דִנְזִיקִין סִימָן ס\"ו וּמַהֲרַ\"ם מֵרִיזְבּוּרְק)\u0006.\nאֵין מַשְׁבִּיעִין אֶת הַמּוֹסֵר שֶׁהֶרְאָה מֵעַצְמוֹ, לֹא שְׁבוּעָה חֲמוּרָה וְלֹא שְׁבוּעַת הֶסֵת, מִפְּנֵי שֶׁהוּא רָשָׁע וְאֵין לְךָ פָּסוּל יוֹתֵר מִזֶּה. \u0010c45\u0011 \u0005וַאֲפִלּוּ לֹא מְסָרוֹ \u0010c46\u0011 עֲדַיִן, רַק שֶׁאוֹמֵר: אֵלֵךְ וְאֶמְסֹר, אִם אוֹמֵר כָּךְ בְּפַרְהֶסְיָא \u0010c47\u0011 נִפְסָל לְעֵדוּת, וְלֹא אַמְרִינָן בִּכְהַאי גַוְנָא עָבִיד אִינַשׁ דְּגָזִים וְלֹא עָבִיד (מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006. וְיֵשׁ חוֹלְקִין אֶלָּא אִם כֵּן מֻחְזָק בְּכָךְ \u0005(מָרְדְּכַי שָׁם בְּפ' הַנִּשְׁבָּעִין)\u0006. וַאֲפִלּוּ לֹא יוֹדְעִין \u0010c48\u0011 אִם רָגִיל בְּכָךְ אוֹ לֹא, מִכָּל מָקוֹם יוּכַל זֶה שֶׁכְּנֶגְדּוֹ לַעֲמֹד וּלְהַצִיל עַצְמוֹ עַל יְדֵי גוֹיִים, אַף עַל פִּי שֶׁיַּגִּיעַ נֶזֶק לָזֶה \u0005(מַהֲרַ\"ם מֵרִיזְבּוּרְק וּתְשׁוּבַת רַשְׁבָּ\"א סִימָן קפ\"א וְהָרֹא\"שׁ כְּלָל ט\"ז)\u0006. אֲבָל הַמּוֹסֵר \u0010y25\u0011 \u0010c49\u0011 שֶׁאֲנָסוּהוּ לְהַרְאוֹת אוֹ לְהָבִיא, וְנָתַן וְנָשָׂא בְיַד, אַף עַל פִּי שֶׁהוּא חַיָּב לְשַׁלֵּם, אֵינוֹ רָשָׁע, וּבֶן תַּשְׁלוּמִין הוּא בִּלְבַד, \u0005(וּמַשְׁבִּיעִין אוֹתוֹ)\u0006 כִּשְׁאָר הַכְּשֵׁרִים. \u0005הַגָּה: וְכֵן אִם הוֹדָה שֶׁמָּסַר, וְאֵין עֵדִים בַּדָּבָר, אַף עַל פִּי שֶׁאֵינוֹ נִפְסָל בְּהוֹדָאַת עַצְמוֹ, \u0010c50\u0011 מִכָּל מָקוֹם חַיָּב לְשַׁלֵּם (מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006.\nאָסוּר לִמְסֹר לְיִשְׂרָאֵל בְּיַד גּוֹיִים, בֵּין בְּגוּפוֹ בֵין בְּמָמוֹנוֹ; וַאֲפִלּוּ הָיָה רָשָׁע וּבַעַל \u0010y26\u0011 עֲבֵרוֹת; וַאֲפִלּוּ הָיָה מֵצֵר לוֹ וּמְצַעֲרוֹ. \u0005הַגָּה: וְדַוְקָא בִּדְבָרִים בְּעָלְמָא; אֲבָל אִם מְסָרוֹ, מֻתָּר לְמָסְרוֹ, דְּהֲרֵי יוּכַל לְהָרְגוֹ בַדִּין \u0010c51\u0011 בְּמָקוֹם שֶׁיֵּשׁ חֲשָׁשׁ שֶׁיַּחֲזֹר וְיִמְסְרֶנּוּ (הָרֹא\"שׁ כְּלָל י\"ו סִימָן א' וב' וּתְשׁוּבַת רַשְׁבָּ\"א סִימָן קפ\"א)\u0006 ; אוֹ אִם אִי אֶפְשָׁר לְהַצִּיל עַצְמוֹ בְּדֶרֶךְ אַחֵר; אֲבָל אִם אֶפְשָׁר לְהַצִּיל עַצְמוֹ בְּדֶרֶךְ אַחֵר, הָוֵי כִּשְׁנַיִם שֶׁמָּסְרוּ זֶה אֶת זֶה וְכָל מִי שֶׁהִפְסִיד חֲבֵרוֹ יוֹתֵר חַיָּב לְשַׁלֵּם הַמּוֹתָר בְּנֶזֶק שָׁלֵם \u0005(מָרְדְּכַי פֶּרֶק הַנַּ\"ל וּתְשׁוּבַת מַיְמוֹנִי הנ\"ל)\u0006. \u0010c52\u0011 וְכָל הַמּוֹסֵר יִשְׂרָאֵל בְּיַד גּוֹיִים, בֵּין בְּגוּפוֹ בֵּין בְּמָמוֹנוֹ, אֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא. \u0010y27\u0011\nמֻתָּר לַהֲרֹג הַמּוֹסֵר אֲפִלּוּ בַּזְּמַן הַזֶּה. \u0010c53\u0011 וּמֻתָּר לְהָרְגוֹ קֹדֶם שֶׁיִּמְסֹר, אֶלָּא כְּשֶׁאָמַר: הֲרֵינִי מוֹסֵר פְּלוֹנִי \u0010y28\u0011 בְּגוּפוֹ אוֹ בְּמָמוֹנוֹ, אֲפִלּוּ מָמוֹן קַל, הִתִּיר עַצְמוֹ לַמִּיתָה, וּמַתְרִין בּוֹ וְאוֹמְרִים לוֹ: אַל תִּמְסֹר, אִם הֵעִיז פָּנָיו וְאָמַר: לֹא כִּי אֶלָּא אֶמְסְרֶנּוּ, מִצְוָה לְהָרְגוֹ, וְכָל הַקֹּדֶם לְהָרְגוֹ, זָכָה. \u0005הַגָּה: וְאִם אֵין פְּנַאי לְהַתְרוֹת בּוֹ, אֵין צָרִיךְ הַתְרָאָה (הַמַּגִּיד פ\"ח דְּחוֹבֵל)\u0006. וְיֵשׁ אוֹמְרִים דְּאֵין לַהֲרֹג הַמּוֹסֵר אֶלָּא אִם כֵּן אִי אֶפְשָׁר לְהִנָּצֵל מִמֶּנּוּ בְּאֶחָד מֵאֵבָרָיו, אֲבָל אִם אֶפְשָׁר לְהַצִּיל בְּאֶחָד מֵאֵבָרָיו, כְּגוֹן לַחְתֹּךְ לְשׁוֹנוֹ אוֹ לְסַמּוֹת עֵינָיו, אָסוּר לְהָרְגוֹ, דַּהֲרֵי לֹא גָּרַע מִשְּׁאָר רוֹדֵף \u0005(תְּשׁוּבַת מַיְמוֹנִי הַנַּ\"ל וּמָרְדְּכַי הַנַּ\"ל בְּשֵׁם מהר\"מ)\u0006. \u0010c54\u0011\nעָשָׂה הַמּוֹסֵר אֲשֶׁר זָמַם, וּמָסַר, אָסוּר \u0010c55\u0011 לְהָרְגוֹ, אֶלָּא \u0010c56\u0011 \u0010c57\u0011 אִם כֵּן הֻחְזַק לִמְסֹר, שֶׁהֲרֵי זֶה יֵהָרֵג שֶׁמָּא יִמְסֹר אֲחֵרִים. \u0010c58\u0011\nכָּל הַמּוֹסֵר הַצִּבּוּר וּמְצַעֲרָן, מֻתָּר לְמָסְרוֹ בְּיַד גּוֹיִים לְהַכּוֹתוֹ וּלְאָסְרוֹ וּלְקָנְסוֹ; אֲבָל \u0010y29\u0011 \u0010c59\u0011 מִפְּנֵי צַעַר יָחִיד אָסוּר לְמָסְרוֹ. \u0005הַגָּה: (וְע\"ל סִימָן תכ\"ה ס\"א)\u0006. מִי שֶׁעוֹסֵק בְּזִיּוּפִים וְכַדּוֹמֶה, וְיֵשׁ לָחוּשׁ שֶׁיַּזִּיק רַבִּים, מַתְרִין בּוֹ שֶׁלֹּא יַעֲשֶׂה, וְאִם אֵינוֹ מַשְׁגִּיחַ, יְכוֹלִין לְמָסְרוֹ וְלוֹמַר שֶׁאֵין אַחֵר מִתְעַסֵּק בּוֹ אֶלָּא זֶה לְבַד. מִי שֶׁרוֹצֶה לִבְרֹחַ וְלֹא לְשַׁלֵּם לַגּוֹי מַה שֶּׁחַיָּב, וְאַחֵר גִּלָּה הַדָּבָר, אֵין לוֹ דִּין מוֹסֵר, שֶׁהֲרֵי לֹא הִפְסִידוֹ רַק שֶׁהֻצְרַךְ לְשַׁלֵּם מַה שֶּׁחַיָּב, מִכָּל מָקוֹם בְּרָעָה עָשָׂה דְּהָוֵי כְּמֵשִׁיב \u0010y30\u0011 \u0010c60\u0011 אֲבֵדָה לְגוֹי; וְאִם גָּרַם לוֹ הֶזֵּק, חַיָּב לְשַׁלֵּם לוֹ מַה שֶּׁגָּרַם לוֹ \u0005(מַהֲרַ\"ם \u0010c61\u0011 מֵרִיזְבּוּרְק)\u0006.\nאָסוּר לְאַבֵּד מָמוֹנוֹ שֶׁל מוֹסֵר אַף עַל פִּי שֶׁמֻּתָּר לְאַבֵּד גּוּפוֹ, \u0010y31\u0011 שֶׁהֲרֵי מָמוֹנוֹ רָאוּי לְיוֹרְשָׁיו. \u0005(וע\"ל סי' ק\"ח ס\"ב)\u0006 \u0010y32\u0011 \u0010c62\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּמֻתָּר לִטֹּל מָמוֹנוֹ לְעַצְמוֹ, דְּאֵינוֹ אָסוּר אֶלָּא לְאַבְּדוֹ\u0006 \u0005(מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006.\nמוֹסֵר, \u0010y33\u0011 מְקַבְּלִים עֵדוּת שֶׁלֹּא בְפָנָיו. \u0005הַגָּה: \u0010c63\u0011 וְאֵין צְרִיכִין לְכַוֵּן הָעֵדוּת כָּל כָּךְ (טוּר)\u0006.\nמִי שֶׁמֻחְזָק שֶׁשְּׁלֹשָׁה פְעָמִים מָסַר יִשְׂרָאֵל אוֹ מָמוֹנָם בְּיַד גּוֹיִים, הָיוּ מְבַקְּשִׁים עֵצָה וְתַחְבּוּלָה \u0010y34\u0011 לְבַעֲרוֹ מֵהָעוֹלָם, \u0005הַגָּה: \u0010c64\u0011 עַל יְדֵי גְרָמָא, \u0010c65\u0011 אַף עַל פִּי שֶׁאָסוּר לְהָרְגוֹ (בְּיָדַיִם)\u0006. מִי שֶׁמְּדַבֵּר בִּפְנֵי קָהָל וְעֵדָה דִבְרֵי מְסִירוּת, וְעַל יְדֵי זֶה נִשְׁמַע לַשַּׂר וְגָרַם הֶזֵּק, אַף עַל פִּי שֶׁאֵין לוֹ דִּין מָסוֹר מִכָּל מָקוֹם מַעֲנִישִׁין אוֹתוֹ לְפִי רְאוֹת עֵינֵי הַדַּיָּנִים \u0005(רִיבָ\"שׁ סִימָן רל\"ט וּתְשׁוּבַת רַמְבַּ\"ן סִימָן ר\"מ)\u0006. מִי שֶׁשָּׁלַח שָׁלִיחַ \u0010c66\u0011 לִמְסֹר, אִם הַשָּׁלִיחַ הֻחְזַק לַעֲשׂוֹת, חַיָּב הַמְשַׁלְּחוֹ, וְאֵין לוֹמַר אֵין שָׁלִיחַ לִדְבַר עֲבֵרָה, הוֹאִיל וְהֻחְזַק בְּכָךְ. \u0010y35\u0011 \u0010c67\u0011 \u0010c68\u0011 \u0010c69\u0011 \u0010c70\u0011 \u0010c71\u0011 \u0010c72\u0011 \u0010c73\u0011 \u0010c74\u0011 וְכֵן אִם מָסַר שְׁטָר פָּרוּעַ לְגוֹי, וְיוֹדֵעַ שֶׁיִּתְּנוֹ לַשַּׂר וְיָכֹף הַיִּשְׂרָאֵל לִפְרֹעַ שֵׁנִית, חַיָּב לְשַׁלֵּם \u0005(בֵּית יוֹסֵף בְּשֵׁם רשב\"ץ וּמַהֲרַ\"ם מֵרִיזְבּוּרְק)\u0006.\nהוֹצָאוֹת שֶׁעָשׂוּ לְבַעֵר מוֹסֵר, כָּל הַדָּרִים בָּעִיר חַיָּבִים לִפְרֹעַ בָּהֶם, אֲפִלּוּ אוֹתָם שֶׁפּוֹרְעִים מַס בְּמָקוֹם אַחֵר:",["\u0003ממון חבירו כו'. \u0004 לשון הטור כמו שהנגזל נשבע ונוטל כו' ועיין בסי' צ' סי\"ו ובדברי המחב' שם שכ' שם ג\"כ שהניזק נשבע ונוטל:","\u0003ארנקי בשק כו'. \u0004 נראה דצ\"ל הג\"ה זו מקומה כאן שכ' וכיוצא בזה כו' ודלא כמ\"ש בס\"י ודו\"ק:","\u0003אבל אם אין דרכם להניח בכלי זה כו'. \u0004 בגמ' הוא איבעי' דלא איפשט' ז\"ל מי מנחי מעות בכלי כזה או לא ופירשו הרמב\"ם והטור והמחבר דאפי' אי ודאי אין דרך אדם להניח שם מבעיא ליה אי אזלינן בתר דרך בני אדם ופטור וה\"ק מי מנחי בתמיה וכיון דאין דרך להניח שם והיה הסל מחופה פי' מכוסה דלא ראוהו פטור דלא עלתה על דעת המזיק שיש שם מעות או נימ' דנאמן הניזק בשבועה שהניח שם מעות וחייב המזיק משום דמאי הוה לזה להכלי להשליכו במים ופסק הרמב\"ם בזה דהמע\"ה ואם תפס אין מוציאין מידו וכמ\"ש המחב' והרא\"ש ס\"ל כיון דספיק' דדינא הוא לא מהני ביה תפיסה והו' דעת החולקים דכ' מוהר\"ם בסמוך דין מוסר:","\u0003מהיפה שבנכסיו. \u0004 בטור כתב כדין מזיק וכ\"כ בסימן שפ\"ה דהיינו דוקא כשמשלם מקרקעות אבל כשמשלם ממטלטלים אפי' בסובין הרשות בידו:","\u0003אלא הרגיל בלבד \u0004 פי' דיבר לאנס דממונו של זה במקום פלוני הוא:","\u0003הבעל אוכל פירות כל ימי חייה. \u0004 נ\"ע מ\"ש מחבלה באחרים דכ' הטור ומור\"ם לקמן בס\"ס תכ\"ד וכתבו ג\"כ המחב' בחבלה בבעלה דצריכ' למוכרן בטובת הנאה ולשלם ממנו דמי החבלה ואפשר דבמסירה דלא הזיקה בידים הקילו דשם קנס עליו גם מה\"ט במת קודם שעמד בדין אמרי' בסמוך דאין היורשים חייבים לשלם בעדו אבל במידי דאינו קנס כגון הלואה ושאלה וגניבה וחבלה ונשאת מוכח ל' סי' תכ\"ד דאם יש לה בכ\"מ או נצ\"ב או תוספת כתובה על כתובה דאורייתא דמחוייב' היא למכר' בטובת הנאה ולשלמם וכן כתבתי ל' בס\"ס שמ\"ו ע\"ש ובדרישה שם הארכתי ומ\"ש \"המרדכי דהא דאמרו דנשים ועבדים שחבלו באחרים פגיעתן רעה דעכ\"פ משמתינן ומלקינן אותן דאל\"כ כל אשה ועבד יחבלו ויסמכו על זה כו' ע\"ש אפשר דלא כ\"כ כ\"א כשלית לה נ\"מ:","\u0003לענין זה רק כיורש. \u0004 פי' אע\"ג דבעלמא הבעל מחשב כלוקח ראשון ה\"מ גבי לקוחות דאינהו אפסידו אנפשיהו דלא ה\"ל ללקח' מידה כיון דידעו שיש לה בעל משא\"כ בזה דאיהי גרמה להן היזק זה:","\u0003ה\"ג והראה לו שלו ושל חבירו חייב \u0004 כ\"כ בטור בסי' זה ובסי' שע\"ה ס\"ה ע\"ש:","\u0003כיצד הרי שגזר המלך להביא לו יין כו' \u0004 האי כיצד לאו אדסמיך לי' קאי אלא אמ\"ש לפניו וללמדינו דבכה\"ג אף שלא נשא ונתן ביד כיון שמסרו בלא אונס יסורין חייב לשלם לו הזיקו ושם ברמב\"ם כתב אחר זה ז\"ל אנסו המלך למוסר זה עד שיראה לו אוצרות יין או תבן או עד שיראה לו ממון חבירו שהוא בורח מלפניו כו' והמחבר תפס סוף דברי הרמב\"ם כמ\"ש בסעיף שאחר זה ז\"ל אנסו המלך כו' וממ\"ש ריש דברי הרמב\"ם נלמד דל\"ד קאמר דפטור כשאנסו להראות ממון חבירו \"שברח \"מלפניו אלא אורחא דמלתא נקט שאין דרך האנסין הוא לאנוס להראות לו ממון של אחרים סתם אם לא שיש לו טענה על א' מהן כגון \"שברח \"מלפניו שאז דרכו לפרטו בשמו ומאנס לו עד שיראה לו ממונו דאותו פלוני וק\"ל:","\u0003הי' רואה נזק בא עליו כו'. \u0004 שם בנ\"י סיים וכ' דאם כבר בא עליו אסור לסלקו ממנו בשגורם בזה היזק לחבירו:","\u0003אנסו המלך למוסר זה כו' \u0004 אבל אם אין לאותו איש ממון ואנס לזה שיראהו להאיש ורצונו לתופסו עד שיפדנו הקהל או קרוביו וזה הנאנס הי' יכול לפטור נפשו ג\"כ מהאנס מיסורים אם היה רוצה ליתן להאנס ממון כזה נראה דאסור לגרום היזק לקהל או יחידים קרוביו:","\u0003והראה לו מפני האונס ה\"ז פטור. \u0004 יש לדקדק מלשון הרמב\"ם והמחבר מדכתבו לשון \"פטור ולא כתבו \"דמותר להראותו כיון דנאנס ע\"ז די\"ל דלכתחל' לא יראהו אלא שאם הראהו פטור מהתשלומין:","\u0003אע\"ג שהמלך אנסו להביא ול\"ד למ\"ש בגמרא וכתבו הטור והמחבר בסי' רצ\"ב ס\"ח דהמפקיד אצל חבירו ממון אוכלים ואינו אמוד הנפקד ובאו עליו גנבים וקדם ונתן להם הפקדון להציל עצמו דכיון דאינו אמוד חזקה דלא באו אלא בשביל הפקדון ופטור וכ\"ש כאן דאנסוהו בהדיא ליתן לו ממון חבירו דשאני התם כיון דאינו אמוד מסתמא אונס' דמתיליד לי' לא הוי אלא בשביל הפקדון ואם לא הי' הפקדון אצלו לא הוו אתו עליה אבל כאן שמאנסין אותו שיביא ממון ראובן מבית ראובן ריע מזלו גרם לו זה דאל\"כ איך באים אצלו שיתן לו מעות ראובן שאינו בידו ולהכי נסתחפה שדהו וחייב אפי' אנסוהו גם על ההבאה כ\"כ ר\"ן אבל הראב\"ד השיג על הרמב\"ם גם בזה וכ' דאף שנשא ונתן ביד מ\"מ כיון שאנסוהו על ההבא' אין לך דבר שעומד בפני פקוח נפש והואיל ויחדו לו בפירוש אינו מחוייב שימות בשביל ממון חבירו וממילא ג\"כ נפטר מהתשלומין דאח\"כ ע\"ש שכ\"כ בשם גאון ועיין בנ\"י בהגוזל בתרא מ\"ש בדין זה וד\"מ הביאו ועד\"ר:\u0004","\u0003דזה לא מיקרי נתן ביד. \u0004 פי' אלא גרמא בעלמ' מ\"מ מסיק שם דאי עשה כן מדעתו בלא אונס חייב:","\u0003שכיון שעמד האנס כו'. \u0004 לשון הטור שעל מה שהראהו לו פטור כיון שהוא אנוס וגם לא עשה מעשה ועל מה שנטלו ונתנו לו אח\"כ פטור דכיון שראוהו האנס ויכול ליטלו חשיב כאלו נטלו ועד\"ר מ\"ש בד\"ה ואפי' בזה כתב א\"א הרא\"ש ז\"ל: הג\"ה וכתב מהר\"מ מריזיבורק ראובן לקח חפץ א' משמעון למוכרו לשר ואח\"כ החזירו לשמעון בפני עבד השר ואח\"כ לקח השר החפץ משמעון בחזקה בלא דמים ראובן חייב לשלם לשמעון דהיה לו לחזו' בינו לבין עצמו ולא מהני מה שאמר לא כוונתי להזיקך עכ\"ל ד\"מ ס\"ס זה:","\u0003ומסרה ביד אנס מנדין כו'. \u0004 ☜וכתב הריב\"ש סי' פ' באחד שביזה החכם ועמד החכם ונתן העונש שלו לשר העיר וכתב שם דהוי קרוב למסירה עכ\"ל ד\"מ ב':","\u0003דמיקרי מוסר וחייב לשלם כל הזיקו וכת' בתשוב' מיימוני ספר נזקין סי' י\"ד על אחד שרצה לתפוס את חבירו ולהכריחו למשפט ומתוך שלא רצה להניח לתפוס עצמו הכהו והרגו השופט ודן מהר\"ם על התובע דין רוצח וע\"ש סי' קי\"א בתשובת מהרי\"ו ד\"מ ד':\u0004","\u0003אין חבירו חייב לשלם \u0004 דריע מזלו גרם לו שיהא נתפס עבורו אף שנפטר חבירו ע\"י כך מחובו יכול לומר מפייסינא הוינא ליה עד דפטרני בלא דמים וכמ\"ש בריש סי' קכ\"ח:","\u0003מפני המס הקצוב \u0004 הטעם דחוק מלך ונימוסו הוא כן להיות נתפס אחד על חבירו כי אין עליו לטרוח לגבות מכל אחד בפני עצמו וכמ\"ש בסי' קכ\"ח ושס\"ט בטור ובדברי המחבר:","\u0003מי שיש עליו עדים כו'. \u0004 אבל אם אין עליו עדים ישבע לו היסת שלא מסרו כ\"כ הג\"א ד\"מ סי' צ' סי\"ד:","\u0003אם תפס הנמסר כו'. \u0004 דאיבעיא דלא איפשטא הוא בגמרא אי עשו תקנה בנמסר להיות נאמן בשבועתו ליטול כמו שתקנו בנגזל ולא איפשט' וס\"ל להרמב\"ם דמהני ביה תפיסה ור\"י והרא\"ש ס\"ל דלא מהני כיון דהוא ספיקא דדינא ועד\"ר ר\"ס זה מ\"ש:","\u0003רק שהוצרך להתפשר \u0004 פי' שיש לנמסר עדים ע\"ז שהוצרך לפשר עם השר בכך וכך אף שהמוסר כופר ואומר לא בשביל המסירה לחוד פשרת עם השר ליתן לו כך וכך הנמסר נאמן בשבועה כיון דיש לו עדים עכ\"פ שהוצרך לפשר עם השר בכך וכך וגם ידוע שמסרו:","\u0003הוי כמזיק בידים כו' \u0004 וסיים שם אף שטוען שלא תפסוהו משום שהכהו אלא משום שברח אפי' הכי חייב:","\u0003האומר לחבירו מסרתני. \u0004 וכ' הרשב\"א בתשוב' סי' תקע\"ו מוסר שהודה במקצת משלם מה שהודה ואינו משלם השאר ואפי' אומר נ' ידענא ונ' לא ידענא לא אמרי' מתוך שאיל\"מ מאחר שלא ה\"ל למידע כמה הזיקו עכ\"ל ד\"מ ג':","\u0003ואפי' מסרו רק כו'. \u0004 ר\"ל אם ראה השר מעצמו או עכו\"ם ראוהו דאז מסתמא יגידו להשר מה שראו שעשה ראובן כגון שהכה לשמעון אף שהלך לוי והגיד לשר על ראובן פטור לוי דבלא הגדתו ודאי יודע להשר ע\"י העכו\"ם:","\u0003שאנסוהו להראות כו'. \u0004 פי' אף שנשא ונתן אח\"כ ביד (וכדמסיק) דאז חייב לשלם אפ\"ה אינו נקרא רשע כו' א\"נ ה\"ק ל\"מ אם לא אנסוהו אלא להראות והראהו ולא נשא ונתן ביד דאינו נקרא רשע דהרי בכה\"ג אפי' בר תשלומין ליכא אלא אפי' אנסוהו להביא והוצרך לישא וליתן באונס אף דבר תשלומין הוא כנ\"ל אפ\"ה אינו נקרא רשע כו':","\u0003ואפי' הי' מצר לו ומצער \u0004 בגמרא יליף לה מדאמר דוד אמרתי אשמרה דרכי מחטא בלשוני אשמרה לפי מחסום בעוד רשע לנגדי דר\"ל אף שרשע לנגדי ומצערני ועוד אמר דום לה' והתחולל לו כו' דר\"ל שידום ויסבול והשם יפילם לפניו חללים חללים:","\u0003מותר להרוג כו' \u0004 וכ' הריב\"ש סי' רל\"ו מי שנתפס בעד גופו לדון אותו מפני שהוא מוסר או שאמר דברים שמתחייב בנפשו ורוצה ליתן ערבות מספיקין שלא יברח אין מקבלין ממנו דמה יעשה לערבים אם יברח הוא עכ\"ל ד\"מ י\"ג:","\u0003בגופו או בממונו. \u0004 דמוסר אף דאינו מזיק ממון חבירו בידים גרע ממזיק וילפי' לה בגמרא מדכתיב בניך עלפו שכבו בראש כל חוצות כתוא מכמר מה תוא זה כשנפל למכמר שוב אין מרחמין עליו כן ממונם של ישראל כיון שנפל ליד עכו\"ם אין מרחמין עליו ומעלילין עליו עלילות כל כך עד שהרבה פעמים יבא ע\"י לידי סכנת נפשות מ\"ה יש להמוסר דין רודף מיהו לא גרע מרודף דאחר שעבר עבירה אין הורגין אותו בלא התראה ובדין ב\"ד דוקא כן המוסר אחר שמסר אם לא שהוחזק למסור וכדמסיק המחבר בסי' י\"א:","\u0003מפני צער יחיד אסור למסרו. \u0004 והיינו דוקא מפני צער דעלמא אבל אם מסרו בממון וכ\"ש אם יסרו במכות ועונשי הגוף מותר כמ\"ש בס\"ט בהג\"ה ועד\"מ ס\"ט וע' בטור בסי' תכ\"ה ס\"ב:","\u0003ואם גרם לו היזק. \u0004 נראה דר\"ל היזק יותר ממה שחייב להעכו\"ם אם בא לו ע\"י שגילה לעכו\"ם מבריחותו אבל בכדי מה שחייב לו אינו נקרא היזק:","\u0003שהרי ממונו ראוי ליורשיו. \u0004 פי' וכתיב יכין רשע וצדיק ילבש:","\u0003דמותר ליטול ממונו כו'. \u0004 דלא עדיף ממונו מגופי דהוא הפקר והרי עדיין לא זכו בניו בחייו בממונו:","\u0003מקבלין עדות שלא בפניו. \u0004 ל' תשובת הרא\"ש הביאו הטור בס\"ס זה ואף שלא בשעת מעשה כשדנין עליו להורגו ביד עכו\"ם א\"צ לקבל העדות בפניו כי הדבר ידוע מי שהוא מוחזק למוסר העכו\"ם מקרבין אותו בשביל הנאתן ואילו רצה לקבל העדות בפניו ולדרוש ולחקור בדינו לעולם לא יעשו לו דין כי ינצל ע\"י עכו\"ם כי אפי' כשאינו בסכנה מוסר יחידים ורבים כ\"ש כשיראה עצמו בסכנת גופו כו':","\u0003לבערו מהעולם \u0004 ע\"י גרמא אע\"פ שאסור להורגו. כ\"כ בתשובת הרא\"ש הביאו הטור בס\"ס זה בשם ר\"ח דשלא בשעת מעשה אע\"פ שהוחזק למסור אינו מותר אלא ע\"י גרמא והיינו שמורידין אותו לבור ושם ימות מעצמו ואם הוא כבר ירד בסולם לבור מעצמו מסלקין הסולם משם וכיוצא באלו. וכן מותר להשתדל מיתתו ע\"י עכו\"ם דהוה כמו הורדה לבור כו' ע\"ש ועפ\"ר ושם כתבתי דלדעת הרמב\"ם והר\"ר אשר מלוניל מותר להורגו אפי' בידים לאחר שהוחזק להיות מוסר ג\"פ ואפילו שלא בשעת מעשה ושמדברי הבעל העיטור מוכח דס\"ל כר\"ח הנ\"ל:","\u0003וכן אם מסר שטר פרוע כו'. ואפי' מסרו בין שאר שטרות ואמר דלא ידע מזה מ\"מ חייב דה\"ל למידע רשב\"ץ שם:\u0004"],["\u0003 ואינו יודע מה הזיק כו' \u0004 משמע הא אם המזיק יודע מה היזק ומכחישו אין הניזק נשבע ונוטל ועיין מ\"ש לקמן סימן תי\"ח סי\"ג עיין בתשו' מהרש\"ך ס\"ג סי' פ\"א:","\u0003 והשליכו למים כו'. \u0004 ל' המרדכי פ' הכונס ההוא גברא דבטש בכספתא כו' כ' רבינו אבי העזרי וז\"ל ש\"מ דכל מי שמפסיד לחברו בפשיעתו ויש לו עדים שאבד על ידו ממונו או בידו או ע\"י פשיעתו שישבע כמה הפסידו ויטול כו' ומהרש\"ל כ' שם בפ' הכונס סי' ל\"ב וז\"ל וראבי\"ה כ' אפי' מי שמפסיד ממון לחברו בפשיעתו כו' ולא נ\"ל דלא עשו תקנת נגזל אלא כעין נגזל במזיק בידים אבל בפשיעה דאינו מזיק בידים לא ולא עוד אלא אפי' במזיק בידים נ\"ל דלא עשו תקנת נגזל אלא דומיא דנגזל במזיד ובכונה אבל המזיק בידים בשוגג לא עשו תקנה גביה וכן יראה לי מדברי הרמב\"ם שכ' המזיק ממון כו' כיצד לקח כיס חבירו והשליכו למים כו' עכ\"ל ולי נראה כדברי ראבי\"ה ומזיק בפשיעתו דקאמר היינו מזיק במזיד בפשיעתו דהיינו דלא תימא דוקא משליכו בידים למים אלא אפילו זרקו לארץ ומכח זריקתו נתגלגל ונפל למים או שהי' ביד חברו ודחפו מיד חברו וממילא נפל למים וכה\"ג חייב והיינו דאמרינן בש\"ס ההוא גברא דבטש בכספתא דחבריה שדייה בנהר' כו' ומדלא קאמרי' בקצור ההוא גברא דשדייה כספתא דחבריה בנהרא משמע שהמעש' הי' שלא השליכו בידים לנהר רק דבטש ביה ומכח דחיפתו שדייה בנהר' ומ\"ש הרמב\"ם והשליכו למים נמי יש לפרש דבריו כן גם בהג\"ה מיי' סוף פ\"ז מה' חובל הבי' דברי ראבי\"ה הנ\"ל על דברי הרמב\"ם וע\"ש מיהו בהזיק בשוגג נראה כדברי מהרש\"ל ונראה דאף ראבי\"ה מודה בזה:","\u0003 או אמוד להפקידם. \u0004 וצריך לברר טענתו מי הפקידו אצלו כ\"כ מהרש\"ל שם:","\u0003 הוא פשע בעצמו כו'. \u0004 משמע לכאורה מלשון זה דהטעם הוא משום דלא ה\"ל למזיק לאסוקי אדעתי' שיש שם דברים אלו וכ\"כ בעיר שושן להדיא א\"כ קשה מ\"ש אח\"כ אינו נאמן וגם בס' לחם משנה הניח בצ\"ע וצ\"ל דה\"ק אינו נאמן וגם אינו מועיל שבועתו וכן משמע ברמב\"ם שמסיים ואין משביעין אותו על כך שאין דרך בני אדם כו' דאל\"כ הוא כפל ל' ומ\"ש אח\"כ ואם תפס כו' היינו משום שגם זה בכלל הבעי' דדלמא לא מיקרי פשיעה ומהני שבועתו אך מדברי הרב המ' שם נרא' שהבין שהרמב\"ם מודה דכשיש עדים חייב וכ\"כ מהרש\"ל פ' הכונס סי' ל\"ב להדיא לדעת הרמב\"ם וכן נראה מדברי הרב ממ\"ש וי\"א כו' וקשה לדבריהם דהא כ' הוא פשע בעצמו וצ\"ל לדבריהם דה\"ק פשע בעצמו שהרי העולם לא יאמינו לו שעשה כן:","\u0003 הרי שחטף חמת כו'. \u0004 ומהרש\"ל שם כ' דבכה\"ג פשיטא דאינו נאמן ולא מבעיא אלא בארגז שמניחי' בו כספים וטען שהי' בו מרגליות כמו שפירש\"י ע\"ש:","\u0003 אינו נאמן \u0004 משמע לכאורה הא אם יש עדים מה הי' בתוכו חייב וע\"כ כ' הרב וי\"א דאפי' היו עדים פטור:","מיהו הרב המגיד מסיק וז\"ל ומ\"מ אם יש עדים שאותו דבר שהוא טוען שהי' שם אע\"פ שאין דרך להניחה גובין מן המזיק ונותני' לנזקין [לניזק] בלא שבועה כך העלה הרשב\"א בזה שלא כדברי בעלה הלכות עכ\"ל ומביאו ב\"י (וביש ספרים איתא בה' המגיד שלא כדברי התוס' ונוסח' זו עיקר כי כן הוא באמת דעת התוס' ס\"פ הכונס וכן הגה' אשר\"י שם) ונראה מהרב המ' שגם דעת הרמב\"ם כן וכ\"כ מהרש\"ל פ' הכונס סי' ל\"ב שדעת הרמב\"ם כהרשב\"א וכ\"נ דעת הרא\"ש ס\"פ הכונס וכ\"נ דעת הטור וכן דעת ראבי\"ה בהג\"ה מיי' פ\"ז מה' חובל ובמרדכי פ' הכונס וכן נראה בשלט\"ג ס\"פ המפקיד דף פ\"ו ע\"ב וכ\"פ מהרש\"ל פ' הכונס סי' ל\"ב וכן נר' עיקר (וכן מוכח בירושלמי שהבאתי לקמן):","אלא שלא מצאתי בדבריהם ישוב ברור למה שהקשו התו' דא\"כ מה הוא אומר לאו היינו מתני' כו' וגם מהרש\"ל שם כתב אבל ר\"י פי' אפי' יש עדים שהי' בו מרגניתא כו' ולכאורה נראה כפי' ר\"י כי לפי פירוש הרשב\"א והרמב\"ם פשיט ליה רב אחא מתקנת נגזל באשו וזה לא הוזכר במשנה כו' מ\"מ נ\"ל כפירוש' דלפי' התוס' ה\"ל לסדר בעי' זו אחר מלתא דרבא הנותן דינר זהב לאשה כו' ולא כ' ישוב ע\"ז דפשיט ממתני' ונלפע\"ד דס\"ל להפשטן כהירוש' שהביא הרא\"ש ס\"פ הכונס דביש עדים לא פליגי ר' יודא ורבנן במתני' אלא פליגי באין עדים אי עשו תקנת נגזל ע\"ש א\"כ ע\"כ ומודים חכמים דקתני היינו כשהוא דרך להניח שם מודים דעשו תקנת נגזל ואפשר שזהו דאי' בש\"ס התם לר' יודא דמחייב על נזקי טמון באש עשו תקנת נגזל באשו שכתבו התוס' דלאו דוקא לר' יודא דלרבנן נמי הוי מצי למימר כן בדבר שדרכו ע\"ש וזה דוחק ולפמ\"ש נראה דדוקא נקט לר' יודא לאשמועי' דלר' יודא אף בטמון עשו תקנת נגזל אבל במבעיר בשל חבירו בדבר שדרכו לא אצטריך לאשמועי' דהיינו מתני' דמודים חכמים לר' יודא דעשו תקנת נגזל ודוק כי כל זה נ\"ל ברור (אחר זמן מצאתי כדברי בס' המלחמות להרמב\"ם ס\"פ הכונס ונהניתי):","\u0003 ואם תפס \u0004 אפי' בעדים:","\u0003 ויש חולקין \u0004 דתפיסה בעדים ל\"מ בספיקא דדינא אבל בלא עדים פשיטא דנאמן ודוק וכבר הארכתי בזה בספרי תקפו כהן ע\"ש:","\u0003 ואם ידע המזיק כו'. \u0004 עיין בספר א\"א דף ק\"ד וע\"ל סי' צ' ס\"י מ\"ש בזה עיין בתשובת מהרשד\"ם סי' קמג:","\u0003 ויש אומרים דנשבע הניזק ונוטל כו' \u0004 דבדבר דלא ה\"ל לידע לא אמרינן דה\"ל מ\"ש ואי\"ל משלם וכבר הארכתי בזה לעיל סי' ע\"ב סי\"ב ס\"ק נ\"א והעליתי דבכל גווני הוי משואיל\"מ וא\"כ כאן העיקר כדברי הרמב\"ם והמחב' וגם ר' ירוחם נל\"א ח\"ב כ' כדברי הרמב\"ם כאן בסתם וכן הסמ\"ג עשין ע' דף קמ\"ח ע\"ב אף שכ' הסמ\"ג בעשין קצ\"ה דף קפ\"ה ע\"ד דלא אמרינן משואיל\"מ אלא בדבר דה\"ל לידע וע\"ש:","\u0003 המוסר ממון כו' \u0004 וה\"ה בקרקע שייך דין מוסר וכדלעיל ס\"ס שע\"א וע\"ש:","\u0003 מהיפה שבנכסיו \u0004 כלו' מן העידית כשאר מזיק ואף דדיני דגרמי רבנן כעין דאורייתא תקון והכי אמרי' לעיל סי' שפה ס\"ק ב' גבי מטמא ומדמע ומנסך מיהו היינו דוקא כשאין לו מטלטלין אבל כשמשלם לו מטלטלין יכול לסלקו אפי' בסובין דכל מילי מיטב נינהו כדלקמן סי' תי\"ט וכ\"כ הרב המגיד ופשוט הוא:","\u0003 אלא הרגיל בלבד \u0004 כלו' הראה או דיבר לאנס וגרם שנמסר ממונו של זה ביד האנס:","\u0003 ואם מת גובים מיורשיו \u0004 היינו משום דס\"ל דמוסר דינא הוא ולא קנס' דרבנן וכ\"כ ה\"ה והבאתיו לעיל ריש סי' שפ\"ו וא\"כ אפי' לא עמד בדין גובה מיורשיו והי\"א דס\"ל דדוקא כשעמד בדין ס\"ל דמוסר דמחייב משום דינא דגרמי דרבנן הוא וכמ\"ש בר\"ס שפ\"ו ולפ\"ז במוסר שנשא ונתן ביד גם להי\"א גובים מהיורשים אף שלא עמד בדין ופשוט הוא ועמ\"ש לעיל סי' שפ\"ה ס\"ק ג' עיין בתשו' מהר\"ם אלשיך סי' קל\"ד:","\u0003 וי\"א דדוקא כשעמד בדין כו'. \u0004 לשון הד\"מ וכתב הרמב\"ם ואם מת גובה מיורשיו וכתב המ\"מ שכן כתב רב האי והרמב\"ם והרשב\"א כו' וכן הוא תשובת מהר\"מ במרדכי פ' החובל דצריכי' היורשים לשלם אבל אם לא הספיק לעמוד בדין עד שמת אין היורשים צריכין לשלם כו' עכ\"ל ואין דבריו נכונים דודאי תשובת מהר\"מ חולק דלהמ\"מ מוסר הוא דינא ולא קנסא כדאיתא בדבריו להדיא וכן הוא בדינא דגרמי להרמב\"ן וגובה מיורשי' אף שלא עמד בדין ולתשובת מהר\"מ לדעת ריצב\"א הוא קנסא ע\"ש ודוק כי זה ברור:","\u0003 הבעל אוכל פירות כו'. \u0004 כ' הסמ\"ע צ\"ע מ\"ש מחבלה באחרים דכ' הטור והר\"ב לקמן ס\"ס תפ\"ד וכתבו ג\"כ המחבר בחבלה בבעלה דצריכה למוכרן בטובת הנאה ולשלם ממנו דמי החבלה ואפשר דבמסירה דלא הזיק' בידים הקילו דשם קנס עליו כו' עכ\"ל ולא ידענ' מה קשיא ליה דודאי הכא אם הוא רוצה שתמכור נ\"מ שלה בטובת הנא' מחויבת לעשו' כן וכמ\"ש הוא עצמו בסי' תכ\"ד סס\"ק ט\"ז דגם בהלואה ובהשאלה ובכל דבר הדין כן אע\"פ שלא הוזכר שם כן וא\"כ ה\"ה הכא ואדרבה הכא אשמועי' גדולה מזה דהנכסים מיד בחזק' הנמסר רק שהבעל אוכל פירות כל ימי חייה וחייב לשלם אחר מיתתה ואדרבה איפכא קשיא דהכא חייב לשלם לאחר מיתתה ובסי' תכ\"ד לא מחייבים לה אלא למכור נ\"מ בטובת הנאה פי' דאם תמות ירשנה הבעל כמ\"ש הטור שם הרי דאין הבעל חייב לשלם לאחר מיתתה ונ\"ל לתרץ משום דהתוס' ס\"ס י\"נ הקשו הא אפי' לאחר תקנת אושא אמרי' דבמקום פסידא לאחריני הוי בעל יורש וא\"כ תיזבין נ\"מ שלה ותיתב ליה ותרצו בשם רשב\"א דכיון שתקנו דלוקח הוא לא פלוג אפי' איכא פסידא כיון דלא שכיח שיהא פסידא לאחריני וכן תירץ הרמב\"ן שם בחדושיו וז\"ל א\"נ משום חבלות דמלתא דלא שכיחא הוא לא פלוג רבנן בתקנתא דבעל עכ\"ל י\"ל דבמסירה דשכיח דהא דיני דחבלות לא דיינינן בזמן הזה משום דלא שכיחי ודיני מסור' דיינינן וכמו שנתבאר בסי' א' מיהו ודאי אם היא רוצה למכור נ\"מ שלה בטובת הנאה לשלם להנמסר דסגי בהכי אלא דאדרב' אפי' אין כאן מי שרוצ' לקנות או שלא יעלה כ\"כ מחויב הבעל לשלם אפי' מתה ואם אינו רוצה לשלם אז גוף הקרקע וגם הפירות לנמסר וכדאי' במרדכי ודלא כסמ\"ע שכ' לתרץ דבמסורו' הקילו דאדרב' החמירו וכמ\"ש ועוד דהא כ' הר\"ב וכן לשאר ניזק מיהו צ\"ל דשאר ניזק דכ' הר\"ב היינו דומיא דמסורת דשכיח מיהו לתרוצ' קמא שכ' הרמב\"ן שם דאיכא למימר לפסיד' דידיה חשו רבנן ותקנו הכי לפסידא דלכל מאן דאתי בתר בעל לא חששו עכ\"ל משמע דאפי' בפסידא דשכיח הוי כלוקח וכן יש לכוין דברי התוס' שם ע\"ש ודוק וא\"כ במסור אין הבעל חייב לשלם כי יש לו דין לוקח רק תמכור נ\"מ שלה בטובת הנאה ותשלם ואפי' לתירוצא בתרא דהרמב\"ן י\"ל דמסירה כחבלות דיינינן לה לענין זה ומהר\"מ במרדכי שם דפסק דהבעל חייב לשלם י\"ל דס\"ל כשנויא קמא דהתוס' שם דהמ\"ל ולטעמיך ע\"ש ודוק:","שוב ראיתי במהרש\"ל פ' החובל סי' ל' פסק כהרשב\"א בתוס' די\"נ והעלה דבין חבלה ובין מסירה בעל לוקח הוי ולא יורש ואינו חייב לשלם לאחר מותה רק שכייפינן למכור כתובתה בטובת הנאה אם יש מי שיקנה ע\"ש:","\u0003 ואין הבעל לענין זה רק כיורש כו'. \u0004 כבר כתבתי דיש חולקין בזה וס\"ל דבעל לוקח הוי לענין זה ופטור לשלם וכ\"פ מהרש\"ל פ' החובל סי' ל' ע\"ש:","\u0003 והראה שלו ושל חבירו. \u0004 אע\"פ שהראה זה בכלל שלו חייב כדלעיל ס\"ס שע\"א:","\u0003 כיצד כו' \u0004 אלעיל קאי במוסר בלא אונס דחייב כיצד הרי שגזר המלך כו' ולא אנס כו' ועמד מוסר ואמר כו' עיין בתשובת מבי\"ט ח\"א בשאלות השניות סי' נ\"ז דקכ\"ו ועיין בתשובת ן' לב סי' ב' סי' נ\"ד ובתשובת מהר\"ם אלשיך סי' ס\"ו ובתשובות מהרשד\"ם סי' שד\"מ ושנ\"ח:","\u0003 הרי שגזר המלך להביא לו כו'. \u0004 היינו בענין שאין בו דינא דמלכותא כגון שגזר על איש ידוע וכה\"ג וכדלעיל סי' שס\"ט ס\"ח וע\"ש:","\u0003 ואפי' יסרוהו ולא א\"ל על מה והראה ממון חבירו חייב. \u0004 באמת כ\"כ הטור אבל לא ידעתי מנ\"ל הא ומן הסברא נראה דפטו' שיכול לו' הייתי סבור שמוסרין אותו להראות להם ממון ואולי האמת כך היה ולא יהא אלא ספק אמאי יתחייב מספק וכן בש\"ש איתא ישראל שאנסוהו עכו\"ם והראה ממון חברו פטור ולא הוזכר שאנסוהו להראות ממון ומ\"ש הב\"י שהטור הוציא כן מעובדא דכסא דכספא לא נהירא דהתם נטל ונתן ביד הוי וכן השיג עליו הב\"ח גם מ\"ש הב\"ח דהטור הוציא כן מהא דקאמר בש\"ס דאחויי אחויי אין ראיה משם דמאן לימא לן דהתם אנסוהו ונראה דהטור מיירי כשנכרין הדברים שלא יסרוהו מתחלה בשביל ממון ודוק:","\u0003 אבל לא אונס ממון \u0004 כ\"כ הב\"י בשם תשובת מיי' וכתב דפשוט הוא אמנם בתשובת רשב\"א סי' תתק\"פ לא משמע כן שכתב דהסוגיא מיירי באונס ממון ואף שכתבו לקמן ס\"ד ס\"ק כ\"ד דאין נ\"ל כתשובת רשב\"א בזה היינו במה שמפרש הסוגיא באונס ממון דוקא אלא הסוגיא מיירי אף באונס נפשות אבל מ\"מ במה דס\"ל להרשב\"א דבהראה פטור אף באונס ממון אין הכרח בש\"ס ופוסקים נגדו וגם מצאתי בס' החנוך להרא\"ה פרשת קדושים מצוה רמ\"ג וז\"ל וכדתניא ישראל שאנסוהו והראה ממון פטור דכל מראה ע\"י אונס פטור ופי' מורינו דלא סוף דבר אנסוהו בגופו אלא אפי' אנסוהו בממון שיקחו לו ממון אם לא יראה ממון חברו והראוהו פטור ואינו חייב אלא במראה מעצמו וכן כ' הרמב\"ם ז\"ל עכ\"ל ואף שמ\"ש וכן כ' הרמב\"ם ז\"ל צ\"ע דאף שהרמב\"ם כ' בתחלת דבריו בד\"א כשהראם המוסר מעצמו כו' מ\"מ ממ\"ש בסוף דבריו ה\"ז פטור שאם לא יראה יכהו או ימיתהו משמע דדוקא באונס הגוף פטור ואולי גירסא אחרת היה לו בדברי הרמב\"ם מ\"מ כיון דידוע דמורו של הרא\"ה היה הרמב\"ן וא\"כ הרמב\"ן והרשב\"א והרא\"ה סוברים דאף באונס ממון פטור כשהראה נראה לי דיכול לו' קיים לי כותייהו:","\u0003 אנסו המלך כו' \u0004 עיין בתשובת מהרשד\"ם סי' נ\"ה וסי' קל\"ה וסי' ר\"ז:","\u0003 נשא כו'. \u0004 חייב לשלם מ\"מ כו' והראב\"ד השיג על זה וז\"ל ע\"ד הרב הוא הולך ואין הגאון מודה לו וכן הדין שאין לך דבר שעומד בפני פקוח נפש ומאין מתחייב לו שימות בשביל ממון חברו הואיל ויחדו לו בפי' וכבר הרחבנו בדברים אלו בפי' ב\"ק עכ\"ל והרב המגיד כ' שראיות הרי\"ף נכונות ביותר ושכן העלה הרשב\"א ז\"ל ובאמת הרי\"ף האריך בראיות וגם הבעל המאור הודה לו וגם הרמב\"ן בס' המלחמות האריך עוד בראיות להרי\"ף וכן דעת הרא\"ה והרא\"ש והסמ\"ג והמרדכי והטור והמחבר ושאר פוסקים וכ\"כ מהרש\"ל פ' הגוזל בתרא סי' מ\"ז וכ\"כ הב\"ח אבל בספרי הארכתי בזה ודחיתי כל ראיות הרי\"ף ובעל המאור והרמב\"ן והעליתי דדוקא אם אנסוהו על ממון סתם אז אף שאנסוהו להביא חייב כשנשא ונתן ביד דזה מיקרי מציל עצמו בממון חברו ודמי לנרדף ששבר הכלים לעיל סי' ש\"פ ס\"ג משא\"כ הכא שאנסוהו להביא ממון פלוני א\"כ האונס הוא מתחלה על אותו הפלוני ואין זה נקרא מציל עצמו בממון חברו אלא שמוכרח לעשות כמו שאומר לו האנס ואם לא יעשה כן נמצא יציל הוא ממון חברו בנפשו ואין לך דבר שעומד בפני פקוח נפש ובההוא עובדא דאמטי ודרי בהדן לא אנסוהו אחר כך רק מתחלה אנסוהו להראות ואח\"כ אמרו לו כן ודוק ותשכח שבזה נדחין כל דברי הרי\"ף והרמב\"ן ועיין בבעל העיטור דף מ\"ח ע\"ב וב\"י ודוק והך דפקיע זה או עמיר זה מה שתי' הבעל לחם משנה בו אינו נכון כלל וגם נראה דאשתמיטתיה דברי בעל העיטו' והנ\"י ע\"ש וגם מה שתי' הבעל העיטור בזה דהתם ליכא אונס' כיון דקאי בתרי עברי דנהרי ומצי לאשתמוטי מיני' ואחריו נמשכו הב\"י והש\"ג והמעד\"מ בתירץ זה ואינו מחוור בעיני דא\"כ המקש' הי' סבור דאיכא אונסא ועיקר התירוץ דמשני דליכא אונסא הוא חסר מן הספ' וגם קמשני לישנא אריכא דלא צריך והל\"ל בקצור הב\"ע דליכא אונסא ועוד דאם איתא דהמקשן היה סבור דפקיע או עמיר מיירי בדאונסיה א\"כ אמאי פריך אטעמא דקלייה בלאו הכי ה\"ל לאקשויי לגופא דברייתא אמאי חייב הלא אנסוהו על ממון פלוני פטור דאין לך דבר שעומד בפני פקוח נפש אבל באמת נלפע\"ד שלחנם דחקו בעל העיטו' והנמשכים אחריו בזה אלא נרא' דבין להמקשן ובין להתרצן מיירי בשאין האנס מאנסו אלא שא\"ל האנס והיינו דקתני אמר לו אנס הושיט לי פקיע זה ולא קתני אנסו להושיט לו פקיע זה ופריך דלדידך דאמרת קלייה ולאו כלום עבד א\"כ ה\"נ באמר לו הושיט לי ואע\"ג דאינו מאנסו כלל נימא כיון דקלייה לאו כלום עבד ומשני דקאי בתרי עברא דנהרא רלא מצי אנס למשקליה וכמו שפירש\"י ומיירי כפשוטו דאף דקאי בתרי עברי דנהרי מצי למאנס ליה אלא דאינו מאנסו ואשמועי' ברייתא בין להמקשן בין להתרצן דאע\"ג דאנס הוא לא אמרינן דאמירת אנס אונס הוא אלא כל כמה דלא מאנס ליה בהדיא דהיינו שאומר לו אם לא תושיט לי אהרגך רק א\"ל הושיט לי חייב כן נ\"ל ברור:","מ\"מ אם אנסוהו בפי' להביא לו ממון פלו' והביא לו ביד פטור וכן דעת רב האי גאון ור\"ח גאון ופשיטא דאין לחלוק על דברי הגאונים אם לא בראייה ברורה מן הש\"ס וכ\"ש כאן שנראה כדבריהם וכן דעת ה\"ר אפרים ובע\"ה וגם הנ\"י כת' שדברי הראב\"ד נ\"ל נכון מאד וכ\"כ בתשו' הרשב\"א סי' תתק\"פ (ואף שבמ\"ש בתשו' רשב\"א שם שהסוגיא מיירי באונס ממון אין נ\"ל כן מ\"מ במה דס\"ל כהראב\"ד לדינא נראה כן וע\"ש) וגם הירושלמי ס\"פ החובל אע\"פ שדחקו הרמב\"ן בספר המלחמות והרא\"ש מפרשו בדרכים אחרים מ\"מ נ\"ל עיקר דירוש' מיירי כפשוטו דאם אנסוהו להביא ממון פלו' פטור וכר\"ח גאון וגם מצאתי בביאורי מהר\"א שטיין על הסמ\"ג דף קמ\"ח ע\"ב וז\"ל ובאבי\"ה סי' אלף ומ' הביא דברי האלפס עם כל ראיות שלו ושם מביא דברי רבי שב\"ט שסותר ראיות של הרב אלפס וגם מביא שם הירושלמי ופי' ר\"ח שהכל חולקין על האלפסי והאריך מאד וקצרתי עכ\"ל וכן ראיתי בפסקי מהר\"מ רקנטי סי' תע\"ג שכ\"כ בשם ראבי\"ה ובשם רשב\"ט וגם בתשובת מהרשד\"ם סנ\"ה כ' כיון דדבר זה פלוגתא דרבוותא היא קמאי ובתראי לא מפקינן ממונא ע\"ש וגם בש\"ג פ' הגוזל בתרא משמע דספיקא דרבוותא הוי ע\"ש ולדידי לאו ספיקא הוא אלא העיקר כהפוטרין וכמ\"ש בספרי (עיין בתשובת הר\"ב סי\"א דף כ\"ג ע\"ב):","\u0003 דזה לא מיקרי נשא ונתן ביד. \u0004 ונראה דאם הי' להם משכון בשותפות על החוב ונתנו להשר דזה מיקרי נשא ונתן ביד וכן מוכח בתשו' מהר\"מ שבמרדכי שם שכ' וז\"ל ואי עביד הכי מדעתיה בלא אונס חייב כמו שורף שטרותיו של חברו אבל באונס פטור ואע\"ג דאמרי' פ' א' דיני ממונות כיון דא\"ל פטור אתה כמי שנשא ונתן ביד דמי הא אתותב עכ\"ל בפ' א' דיני ממונות שם (בדף ל\"ג ע\"ג) בתר דאתותב קמתרץ רבי' דמיירי בשנשא ונתן ביד והא דזיכה את החייב מיירי כגון שהיה לו בידו משכון ונטלו ממנו דה\"ל נשא ונתן ביד ע\"ש:","\u0003 אין לו דין מוסר כו'. \u0004 בתשו' מהר\"מ מלובלין סכ\"ו כתב ואף שיש חולקים בזה נראה שכך הלכה עכ\"ל ולא נהירא להכריע נגד מהר\"מ ב\"ב דלא היה בדורו כמותו כדאיתא בפסקי מהרא\"י סי' קמ\"ב ועוד דהא הסברא ראשונה היא רק סברת יחיד רבי אליעזר מטול' במרדכי ס\"פ הגוזל בתרא ובתשו' מיימוני סוף ספר נזיקין והרי במרדכי פ' המניח משמע דרבוותא פליגי עלה דכתב שם ומעשה הי' בקולניא\"ה בא' שהפקיד אצל חבירו פקדון לימים כפר לו ולקח המפקיד את שלו בידי עכו\"ם ומתוך כך העלילו על הנפקד והפסיד הרבה ופסק הרב דאם אפשר למפקיד להציל את שלו בענין אחר חייב כמו הי' לו לשמטו ולא שמטו וכ\"פ רבינו יקר עכ\"ל וכ\"כ באגודה שם שכן פסקו הגדולים וכן בד\"מ מסיק כפוסקי' אלו וגם מהרש\"ל פרק הגוזל בתרא סי' מ\"ט כתב שאין נראה דברי ר\"א מטול' לענין פטור ממון וחלילה להורות כן שיבא כמה חילול השם מזה ע\"ש וקרוב אצלי דאף ר\"א מטול' לא קאמר אלא כשלא הי' אפשר לו להציל בענין אחר ואפ\"ה כתב שם דכשאין לו מגו לאו כל כמיניה והיינו מטעמא דכיון שהוא מחוייב להחזיר א\"כ שלא כדין עבד מה שתפס ולא יוכל לומר להציל שלי נתכוונתי והיינו דהמרדכי והאגודה אע\"פ שבפ' המניח כתבו כפסק הגדולים כתבו בס\"פ הגוזל בתרא בסתם דברי ר\"א מטול' ע\"ש ודו\"ק. וע' בתשובות מהר\"ם מלובלין ס\" ק\"ך ובתשו' הר\"ב סי' פ\"ו דף קע\"ב ובתשו' מהרי\"ט ס\"ס מ\"ה:","\u0003 מי שנתפס כו'. \u0004 זה נתבאר לעיל סי' קכ\"ב ס\"ב ועיין בתשובת מהרשד\"ם סי' רי\"ד:","\u0003 מי שיש עליו עדים כו'. \u0004 עיין בתשו' מהרש\"ך ספר ג' סי' פ\"ו ופ\"ח באריכות מדיני מוסר:","\u0003 או שנאנס ונש' ונתן ביד כו'. \u0004 באמת כ\"כ הרמב\"ם וכן הוא בע\"ש דמבעיא ולא איפשטא אבל קשה לי בנאנס ונשא ונתן ביד היכא נימא דהוא בעיא דלא איפשטא הא לא מבעיא בש\"ס אלא במוסר למאן דדאין דינא דגרמי אבל בנאנס ונשא ונתן ביד מזיק בידים ולאו גרמי הוא ופשיטא דלא שייך תקנת נגזל דהא אנוס הוא וא\"כ כיון שהוא מכחישו בברי נשבע זה שנאנס ופטור דהא אינו נפסל כיון שנאנס ויכול הוא לישבע כן נ\"ל ברור ודברי הרמב\"ם והמחבר והע\"ש צלע\"ג:","\u0003 ונשא ונתן כו'. \u0004 ואם נשא ונתן ביד בלא אונס פשיטא דעשו תקנת נגזל דהוי גזלן ממש וכ\"כ מהרש\"ל פ' הכונס סימן ל' בשם תשובת מהרי\"ל (והוא בתשו' מהרי\"ל שהבאתי לקמן ס\"ק ל\"ו) ושאר פוסקים והסכים כן ופשוט הוא:","\u0003 והמוסר כופר כו'. \u0004 כ' הרב המגיד ומביאו ב\"י שמדברי הרמב\"ם אלו משמע שסובר כר\"ת דאם אין המוסר כופר אלא שאינו יודע כמה הפסידו נשבע הנמסר ונוטל והוא היש מי שאומר שהביא המחבר לקמן) ואחריו נמשך מהרש\"ל פרק הבונה סי' צ' וכ' שכוונת הרמב\"ם כר\"ת ואין נ\"ל כן דדין זה של ר\"ת דין מחודש הוא וה\"ל להרמב\"ם לכתוב ההפוך דאם אינו כופר נשבע הנמסר ונוטל אלא נראה דהרמב\"ם לטעמיה אזיל דס\"ל דכל מודה מקצת ועל השאר אומר איני יודע ה\"ל משואיל\"מ אף בדבר דלא ה\"ל לידע וכמו שנתבאר לעיל סי' ע\"ב ס\"ק נ\"א באריכות לכך הוכרח לכתו' כאן שהמוסר כופר דאלו אומר איני יודע כמה הוה ליה משואיל\"מ וכשנגדו נוטל בלא שבועה לכך לא הוצרך לכתוב ההפוך דין זה פשוט בלאו הכי ואינו תלוי בכאן כלל. כן נ\"ל ברור לדעת הרמב\"ם ודו\"ק:","\u0003 אם תפס אפי' בעדים. \u0004 ל' מהרש\"ל פרק הכונס סי' ל' ואם העמיד העכו\"ם על ממון של חבירו דהוה כמוסר בידים וכל כה\"ג או שמוסר לאדם בגופו נשבע הנמס' ונוטל עכ\"ל ולא ירדתי לסוף דעתו אמאי בהעמיד לעכו\"ם על ממון חבירו הוי כמוסר בידים ס\"ס לא הוי אלא גרמי כיון שלא נשא ונתן ביד כדמוכח בסוף הגוזל בתרא ע\"ש:","\u0003 וי\"א דבספיקא כו'. \u0004 בב\"י כתב שכ\"כ התוס' והרא\"ש ס\"פ הכונס ולא דק אלא כוונת הטור למ\"ש הרא\"ש פרק כיצד הרגל דתפיס' לא מהני בספיקא דדינ' ועיין בספרי תקפו כהן:","\u0003 בראייה ברורה. \u0004 ולא באומדנא ועיין ב\"ח:","\u0003 רק שהוצרך להתפשר עם השר בכך וכך \u0004 ואולי הערים או היה אפשר להתפשר בפחות ועיין בתשו' מהר\"מ מינץ סי' מ\"ד:","\u0003 ויש מי שאומר \u0004 בטור ובתו' והרא\"ש ומרדכי וסמ\"ג ושאר פוסקים הביאו מחלוקת ר\"ת ור\"י בזה שר\"ת הוא היש מי שאומר ור\"י חולק והרא\"ש והטור הסכימו לר\"י ויש לי לדקדק דתיפוק להו בלאו הכי הא כיון שהמוסר מודה שהפסידו ואינו יודע כמה הוה ליה מודה מקצת ועל השאר אינו יודע דקי\"ל דה\"ל משואיל\"מ ושכנגדו אפי' שבועה לא בעי. ואמת שמצאתי בתשובת מיי' לספר משפטים סי' ס\"א כ' וז\"למנה לי בידך והלה אומר נ' ידענא ונ' לא ידענא דאמרי' משואיל\"מ שכנגדו צריך לכל הפחות לישבע אבל לא יטול בלא שבועה וכן משמע מתוך דברי ר\"ת בס\"פ הכונס דפי' דאם המוסר אומר איני יודע כמה הפסדת ע\"י שכנגדו נשבע ונוטל אלמא בכל כהאי גוונא שכנגדו נשבע ונוטל כו' עכ\"ל אבל אין נ\"ל כן דפשיטא דבנ' ידענא ונ' לא ידענא שכנגדו נוטל בלא שבועה והוא מוסכם מכל הפוסקים בדוכתי טובי וכן הפוסקים הנ\"ל שהביאו מחלוקת ר\"ת ור\"י במוסר כתבו בדוכתי טובי בנ' ידענא ונ' לא ידענא שכנגדו נוטל בלא שבועה ועוד דא\"כ מאי טעמיה דר\"י דחולק אר\"ת גם יתר דברי תשובות מיימוני ההיא שם גבי עד מסייע ע\"ש מגומגמים ואין כאן מקום להאריך בזה ונ\"ל לתרץ דאפשר דר\"ת ור\"י סוברים כמ\"ש לעיל סי' שפ\"ו ס\"ק י' בשם הרמב\"ן דבכל דיני דגרמי אין נשבעין שבועות התורה. א\"נ כמ\"ש לעיל סי' שפ\"ו ס\"ק א' דס\"ל לר\"י ישאר בעלי התוס' דדינא דגרמי דרבנן א\"כ לא שייך לומר משואיל\"מ וכמ\"ש מהרש\"ל פ' הכונס סי' ל' ול\"א דלמ\"ד דהוי דרבנן לא שייך ש\"ד כלל והבאתיו לעיל סי' שפ\"ו סס\"ק י' אך תירוץ זה א\"א לומר בהרא\"ש וסמ\"ג שהם פסקו דינא דגרמי דאורייתא עי\"ל דמיירי דאומר המוסר הילך על מה שהפסידו או שיש לו כנגדו ביד הנמסר אכן מתוך דברי הרשב\"א בתשו' והרא\"ש ס\"פ הכונס למדתי תירוץ אחר דכיון דלא ה\"ל למוסר לידע כמה הפסידו לא שייך לומר דהוי מחוייב שבועה דז\"ל הרשב\"א בתשובה סי' תתקע\"א ואפילו היא מודה בקצת הפסד ע\"י מסירתה על שאר טענות שאינה יודעת עליו להביא ראיה ואינו דומה לנ' לא ידענא ונ' לא ידענא דהתם הו\"ל למידע וכיון שאינו יודע ה\"ל משואיל\"מ ובא חברו ונוטל בלא שבועה כו' אבל כאן אינה מחויבת לדעת והו\"ל כאותו של שק צרור דירושלמי גם מה שראיתי למקצת רבנים שאמרו ישבע ויטול אינו נראה לי כלל כו' ועוד דבפ' הכונס איבעיא לן אי עשו תקנת נגזל במוסר ולא איפשיטא מספיקא לא מפקינן ממונא עכ\"ל ונ\"ל כוונתו דאע\"ג דבההיא דשק צרור של ירושל' שכנגדו נוטל בשבועה וכדאיתא בירושל' וכ\"כ ה\"ה להדיא בשם הרשב\"א בס\"פ ה' מה' שאלה וכבר נתבאר זה על נכון בסי' ע\"ב מ\"מ הכא אף בשבועה אינו נוטל משום דדוקא התם עשו תקנת נגזל אבל במוסר דדינא דגרמי הוא מבעיא ליה אי עשו תקנת נגזל מספיק' לא מפקינן ממוצא וכן מצאתי בהרא\"ש ס\"פ הכונס שמתחלה הביא דברי ר\"ת ור\"י והכריע כר\"י דבעיא דמוסר היינו אפילו המוסר אינו יודע ואח\"כ הביא הירושלמי הנ\"ל דשק צרור והקשה עליו אמאי לא הוי משואיל\"מ ויטול בלא שבועה ותירץ דכיון דלא הוה ליה לידע מה הפקיד אצלו לא הוה ליה מחיוב שבועה ואיל\"מ אלא שעשו תקנת נגזל בפקדון כיון שהנפקד אינו יודע שישבע המפקיד ואהא מייתי לה בירושלמי והא דסלקא בתיקו אם עשו תקנת נגזל במוסר ולא פשיט ליה מפקדון משום דמוסר דינא דגרמי הוא ובדבור' בעלמא הוא דאפסדיה עכ\"ל הרי משמע להדי' כמ\"ש עוד נ\"ל לתרץ אפי' למה שהעליתי לעיל סי' ע\"ב ס\"ק נ\"א כהרמב\"ם וסייעתו דאף בדבר שלא ה\"ל לידע אמרי' משואיל\"מ י\"ל דר\"ת ור\"י בתוס' ופוסקי' מיירי כאן שהנמסר מודה שהמוסר אינו יודע דבכה\"ג כתבתי שם דלכ\"ע לא אמרינן משוא\"י ל\"מ:","וראיתי בב\"ח סי' נ' סי\"ד שכתב וז\"ל ול\"נ דאע\"ג דר\"י והרא\"ש חלקו על ר\"ת דמדמה מוסר לנגזל דטפי מסתברא לדמותו למבעיר כמ\"ש הרא\"ש בס\"פ הכונס מ\"מ מטעם אחר נ\"ל דדברי ר\"ת עיקר דכיון דהמוסר מוד' שהפסיד על ידו אלא שאינו יודע כמה הפסיד ה\"ל כנ' ידענא ונ' לא ידענא דמתוך שאיל\"מ וכיון דלשם אין התובע צריך לישבע הכי נמי במוסר ודאי גם הנמסר מדינא א\"צ לישבע אלא דר\"ת הוא דכתב ונראה דמשביעין אותו מטעם חומרא ולא מדינא וכל זה דלא כתשובת רשב\"א בסי' תקע\"א עכ\"ל ונ\"ל שלא ירד לעומקו ולא ראה רק תחלת דברי הרא\"ש דס\"פ הכונס שהרי בסוף דברי הרא\"ש מוכח דלא הוי משואיל\"מ מטעם דלא הוי לו לידע וכמ\"ש הרשב\"א בתשו' סי' תקע\"א גם בד\"מ ובסמ\"ע ס\"ק כ\"ד הביאו דברי תשובת הרשב\"א סי' תקע\"א הנ\"ל בסתם וכבר מבואר מחלוקת הפוסקים בזה ומביאם הב\"ח עצמו לעיל סימן צ' סי\"ט וס\"ס רצ\"ח במסקנתו דבדבר דלא ה\"ל לידע לא הוי משואיל\"מ. וגם מ\"ש הב\"ח דר\"ת הוא דכ' דישבע מטעם חומרא כו' לא נהירא דאם איתא דהוי משואיל\"מ אפי' בלא מוסר א\"כ כ\"ש דבמוסר א\"צ לישבע. והיאך שייך כלל להחמירעל הנמסר במוסר יותר מבעלמא ולענין הלכה היה נראה לכאור' לפסוק כאן דה\"ל משואיל\"מ כיון דכבר העליתי לעיל סע\"ב ס\"ק נ\"א כהרמב\"ם וסייעתו דאף בדבר דלא ה\"ל לידע הוי משואיל\"מ אם לא שהתובע מודה שהנתבע אינו יודע אך שצ\"ע בכאן מטעם אחר דהרמב\"ם ס\"ל דאין נשבעין ש\"ד אכל דיני דגרמי והבאתיו לעיל סי' שפ\"ו ס\"ק י' וגם יש פוסקים דדינא דגרמי הוא דרבנן ולדידהו לא שייכא ש\"ד כלל וכמ\"ש שם:","\u0003 מי שאומר כו' \u0004 לכאורה קשה על המחבר מאחר שכבר העתיק ל' הרמב\"ם והמוסר כופר כו' דמשמע מיניה דאם אינו כופר נשבע הנמסר ונוטל וכמ\"ש הב\"י שכן דקדק הרב המגיד מדבריו שסובר כר\"ת א\"כ היאך חזר לכתוב כאן דין זה בשם יש מי שאומר. ונראה דמתחלה כתב והמוסר כופר ולפי שההפוך לא נזכר בפירוש ואפשר לדחוק ולומר דלאו דוקא כופר אלא ה\"ה אומר איני יודע לכך כתב כן כאן בפירוש דיש מי שאומר דבאומר איני יודע נשבע ונוטל. וכן יש לפרש דברי הסמ\"ג דף קמ\"ח ריש ע\"ג דבתחלה כתב כדברי הרמב\"ם ואח\"כ מחלוקת ר\"ת ור\"י ודלא כמהרש\"ל פרק הכונס סי' ל' שתמה על הסמ\"ג בזה: עוד י\"ל בדעת המחבר והסמ\"ג דמתחלה כתבו והמוסר כופר לאפוקי אם אומר איני יודע בענין שאפשר שידע דאז ה\"ל משואיל\"מ וכמ\"ש לעיל ס\"ק ל\"ג וכאן מיירי כשהנמסר בעצמו מודה שהמוסר אינו יודע דבהא לא שייך מחויב שבועה כלל וכמ\"ש בס\"ק שלפני זה ופשיטא דמחלוקת ר\"ת ור\"י מיירי אף בכה\"ג דהא מיירי דומי' דעשו תקנת נגזל באשו ובזה מיושב ג\"כ מה שהקשה מהרש\"ל על הסמ\"ג גם מה שפסק מהרש\"ל שם כר\"ת אין נ\"ל דפשט' דסוגיא משמע כר\"י וכמ\"ש הרא\"ש שם דמיירי דומי' דתקנת נגזל באשו וכן נראה מסקנת הסמ\"ג שם וכן מסיק הנ\"י וכן נראה מתשובת הרשב\"א סתקע\"א שהבאתי בס\"ק שלפני זה וכן נראה מתשובת מהר\"מ במרדכי בכמה תשובות וכדלקמן ס\"ק ל\"ט. ועוד דנראה ממהרש\"ל שם שפסק כן כיון שנראה דעת הרמב\"ם כן וכבר כתבתי לעיל ס\"ק ל\"ג דאין נ\"ל כן דעת הרמב\"ם הלכך נראין דברי ר\"י עיקר. ואף שבס\"ק שלפני זה כתבתי שצ\"ע לדינא היינו היכא שאפשר לר שהמוסר יודע אבל היכא שידוע בודאי שהמוסר אינו יודע או שהנמסר בעצמו מודה שאין המוסר יודע דבכה\"ג לא שייכא שבועה על המוסר כלל רק דשייכא פלוגתא דר\"ת ור\"י אי עשו תקנת נגזל בהא נראה עיקר כר\"י דגם בזה מבעי' לש\"ס אי עשו תקנת נגזל או לא ומספיקא לא מפקי' ממונא כן נ\"ל:","\u0003 איני יודע כמה הפסדת כו' \u0004 וכתב הרשב\"א בתשובה סי' תקע\"א גבי אחד שמסר את חברו ואינו יודע כמה הפסידו דאם תפס מטלטלים שלא בעדים אין לו עליו כי אם חרם סתם כל מה שנטל ממנו שלא כדין עכ\"ל ונראה דדין זה אמת אפי' למ\"ד בספיקא דדינא לא מהני תפיסה דאע\"ג דלמ\"ד דלא מהני תפיסה אפילו תפס שלא בעדים לא מהני וכמ\"ש בספרי תקפו כהן היינו בשאר ספיקא דדינא אבל הכא דמטעם נאמנות אתינן עלה דמספקינן אם יהא נאמן בשבוע' ליטול והלכך כיון דתפס שלא בעדים ודאי נאמן מכח מגו והא דאינו נשבע וכמ\"ש לעיל סי' ע\"ב סעיף י\"ז ס\"ק ס\"ז דאפי' בטוען שכנגדו שמא צריך לישבע כדי ליטול צ\"ל דהרשב\"א מיירי שהנמסר רוצה להחזיק במטלטלים ואינו חפץ שיפדם המוסר ושיגבה מהם חובו ובכה\"ג כתבתי שם בס\"ק ע\"א דא\"צ לישבע ולכך כ' הרשב\"א דאין עליו רק חרם סתם. כן נ\"ל:","\u0003 וכל זה במוכר ממון אבל מסר גופו של חבירו כו'. \u0004 דין זה אף שפסקו מהרי\"ל לא נהירא לי ולפי שראיתי גם מהרש\"ל פ' הכונס סי' ל' ומהר\"מ מלובלין בתשובה סי' ס\"א נמשכו אחרי תשו' מהרי\"ל ופסקו כדבריו לכן צריך אני להאריך קצת וז\"ל מהרי\"ל בתשו' סי' פ\"ו ובדפוס האנווא סי' צ' והשתא כיון דר' דוד מוסר גמור דנתיהו בתפיסה אחרונה ישבע ר' ישי ויטול מר' דוד כל מה שברור לו שהזיקתו תפיס' אחרונה אע\"ג דרוב רבותינו פסקו דתיקו לקולא ולא עשו תקנת נגזל במוכר ה\"מ במוכר דהוי דינא דגרמי כגון אחוי אחויי שהראה ממון חבירו אבל המזיק ממון חבירו בידים עשו תקנת נגזל כאשו וכאן מזיק בידים כמו שכתבו רבותינו בפי' במיימוני פ\"ז במי שמוסר בידי' דעשו תקנת נגזל בההוא מוסר וכן באור זרוע וכן נ\"ל שצריך ליישב שכ' המרדכי בשם מהר\"מ בפ' הכונס דפסק כרבינו תם כשאין המוסר מכחישו דנשבע ונוטל דבאינך פירקי מייתי כמה תשובו' שפסק בהדי' דתיקו לקול' ואפי' אין מכחישו אלא היכא דמסר בידים כי האי דמכר גופו דחשיב מזיק בידים כדפסק ר' אפרים שלהי הגוזל קמא דכשמוסר גופו הוי מזיק ממש דאפי' רבנן מודו דהוי כחובל ובההי' תשוב' דאלכסנרי נמי קרי ליה מזיק ופשיטא דמזיק עשו תקנת נגזל כדפי' ור' ישי ישבע בנק\"ח ויטול והני תשובות מן הגוזל בתרא מן הערב ומן בעל הסעודה כל הני הוה מסירת ממון ואין שם מסירת הגוף עכ\"ל ולפע\"ד דלא נהיר' כלל לחלק בין מוסר ממונו או גופו או כגון שגרם לו תפיסה דס\"ס לא עביד מעשה אלא דיבורא הוא ולא מיחייב אלא משום דינא דגרמי והוי בכלל מה דקאמר בש\"ס כי תבעי לך אליבא דמאן דדאין דינא דגרמי כו' ומ\"ש וכן נראה לי שצריך ליישב שכתב המרדכי בשם מהר\"מ פ' הכונס דפסק כרבינו תם כו' בדקתי בכל ספרי המרדכי ולית' שם דפסק מהר\"מ כר\"ת רק איתא שם דפסק מהר\"מ בתיקו לקולא ע\"ש ואם איתא בשום מרדכי בע\"כ ט\"ס הוא או צריך ליישב בענין אחר דמ\"ש מהרי\"ל דהך פ' הכונס מיירי במסירת הגוף הוא תמוה דהא ס\"ל דמסירת הגוף הוי כמזיק בידים דפשיטא דעשו תקנת נגזל כאשו א\"כ בהא פשיטא דלא פליגי ר\"ת ור\"י וקאי התם אמאי דמבעי' ליה לש\"ס דהיינו בדינא דגרמי אבל במזיק בידים לאו גרמי הוא ולא מבעי' ליה לש\"ס כלל וגם מ\"ש מהרי\"ל כדפסקי ר' אפרים שלהי הגוזל קמא דכשמוכר גופו הוי מזיק ממש דאפי' רבנן מודו דהוי כחובל כו' ר\"ל כמ\"ש המרדכי פרק הגוזל קמא וז\"ל ודוקא פטרי רבנן מראה ממון ישראל משום גרמא אבל אם היה מוכר גוף חבירו בידי עכו\"ם עד שיפדה עצמו מן העכו\"ם אפי' רבנן מודו ודמי לחובל בחבירו שמשלם ריפוי דחשיב ליה כאלו הפסיד ממונו ממש כשגרם לו ריפוי ה\"נ הואיל ומסר גופו בידי עכו\"ם כאלו מסר ממונו בידים ותדע שיש חילוק בין נזקי גופו לנזקי ממונו בכה\"ג ומשום ה\"ט דפריך שהרי שבת דאדם אם סגרו בחדר ובטלו ממלאכתו חייב שהרי ד' דברים שייכי באדם ושבת אחד מהם ואם סגר בהמה בבית ובטלה ממלאכת' פטור לד\"ה עכ\"ל וכן מהרש\"ל פ' הכונס סי' ל' הביא דברי מהרי\"ל הנ\"ל ודברי המרדכי אלו וכ' שכן יראה מדברי המרדכי אלו ולע\"ד אין נראה מהמרדכי כלום דבמרדכי מיירי כשמוסר גופו של חבירו בידים דהיינו שנוטל גופו בידו ומוליכו בחזקה לתפיסה לעכו\"ם ולאפוקי דלא תימא כיון דס\"ס אינו נוטל ממונו בידו ונותנו לעכו\"ם לא תהוי אלא גרמי אלא כיון דמוסר גופו בידים ומרמת זה נפסד לו ממון כל הזיק דממונו ה\"ל כאלו הזיקו בעצמו ובזה יש חילוק בין נזקי ממונו לנזקי גופו וקאי אמרדכי שם אמ\"ש שם בתחילה וז\"ל ויש לחלק בין נזקי גופו לנזקי ממונו שכשמזיק לגופו יש לו ליתן לרופא כו' אבל כשהזיק לממונו ומחמת אותו ממון נפסד ממון אחר כגון חובל בהמה ומחמת הבהמה נפסד ממון שיש לו ליתן לרופא זהו גרמא דלאו בגופו הוא אלא בממונו מ\"ה פטור והיינו טעמא דמודה ר' מאיר בזורק מטבע כו' דמחמת הממון נפסד ממון אחר בכה\"ג מודה ר' מאיר ודוקא פטרי רבנן מראה ממון ישראל משום גרמא אבל אם היה מוסר גוף חבירו כו' עכ\"ל המרדכי אלמא דכוונתו כדפי' והיינו שכ' שהרי שבת דאדם אם סגרו בחדר ובטלו ממלאכתו חייב כו' אלמא דמיירי במסרו בידו והוליכו לתפיס' לעכו\"ם דומי' דסגרו בחדר ובדברי מהרש\"ל פ' הכונס סי' ל' היה אפשר לדחוק ולו' דמיירי ג\"כ במוסר גופו בידים אבל בתשו' מהרי\"ל שם שממנו הוציא מהרש\"ל שם דבריו לא משמע כן וגם משמע שם להדיא דלא היה ר' דוד מוסרו רק בדבורו וכן משמע מדברי הר\"ב ועוד מבואר כן יותר מדבריו שכ' וכן אם גרם לו תפיסה כו' וכן משמע להדיא בתשו' מהר\"מ מלובלין סי' ס\"א דהתם בעובדא דיליה לא עביד מידי רק בדבוריה ופסק שם כיון דע\"פ דבורו היו תופסים אותו המושל והוא הציל עצמו מהתפיסה והוצרך להוציא הוצאות ע\"ז חייב לשלם לו כל הוצאתיו ע\"פ שבועתו דהנמסר והביא כל תשו' מהרש\"ל הנ\"ל ולמד ממנה כן. וכבר כתבתי דאין זה נראה לפע\"ד (ועוד מטעמים אחרים יש לי לדון על פסק מהר\"מ מלובלין שם וע\"ש ואין להאריך) גם מ\"ש מהרי\"ל ובההיא תשו' דאלכסנדרי נמי קרי ליה מזיק כו' ההיא תשו' דאלכסנדרי היא בתשו' מיי' לספר נזיקין סי' י\"ד תשו' מהר\"מ לענין שאלכסנדרי צריך כפרה במה שעל ידו נהרג ישראל שמסרו אלכסנדרי ורצו עכו\"ם לתפסו ולא הניח עצמו לתפוס מתוך כך נהרג וכ' מהר\"מ שם פושע הוא ומזיק הוא וגירי דיליה נינהו ובלא שום עדות כי אם על פיו נ\"ל דצריך כפרה כו' אבל לענין שיקרא מזיק בידים לענין היזק ממון שיגיע ע\"י זה ולא גרמי לא שמענו כלל הלכך נראה ברור כמ\"ש דבין מסר ממונו או גופו אם לא עשה מעשה בידיו כגון שהוליכו בעצמו לתפיס' ולא עביד אלא דבורו לא מיחייב אלא משום דינא דגרמי והוא בכלל מה דבעי' לש\"ס אי עשו תקנת נגזל במסור למאן דדאין דינא דגרמי כנ\"ל ברור ולא הוצרכתי להאריך רק מפני שגדול הדור מהרי\"ל לא פסק כן ונמשכו אחריו מהרש\"ל והר\"ב ומהר\"ם מלובלין ושאר אחרונים ולע\"ד הוא כשגגה היוצא מלפני השליטים האלו:","\u0003 שאומר לחבירו מסרתני כו' \u0004 וכ' הרשב\"א בתשו' סי' תקע\"א מוסר שהודה במקצת ישלם מה שהודה ואינו משלם השאר ואפי' או' נ' ידענא ונ' לא ידענא לא אמרינן מתוך שאיל\"מ מאחר שלא ה\"ל לידע כמה הזיקו עכ\"ל ד\"מ ג' עכ\"ל סמ\"ע ס\"ק כ\"ד ותשו' רשב\"א שם כ' ע\"ז והוה ליה כאותו של שק צרור דירושלמי עכ\"ל וסבירא ליה להרשב\"א בההיא דירושלמי כהרא\"ש וסייעתו שהביא הטור סי' רצ\"ח וכן כ' הרב המגיד ספ\"ה מהלכות שאלה בשם הרשב\"א ולפ\"ז למ\"ש הרמב\"ם והמחבר לעיל סי' צ' ס\"י וסי' רצ\"ח ס\"א באותו של שק צרור דירושלמי דה\"ל משואיל\"מ אע\"ג דלא ה\"ל לידע א\"כ ה\"ה הכא ודו\"ק וגם בב\"ח סי' צ' ס\"ס י\"ד כתב דלא כתשו' רשב\"א סי' תקע\"א ע\"ש וכן העליתי לעיל סי' ע\"ב סעיף י\"ב ס\"ק נ\"א דבכל ענין ה\"ל משאיל\"מ אם לא שהתובע מודה שהנתבע אינו יודע וע\"ש ודו\"ק:","\u0003 ואין צריך לעשות נקיות זו אלא ע\"פ עד א' כו'. \u0004 כ\"כ בד\"מ דכן משמע בתשו' מהר\"מ במרדכי פ' החובל ופ' שור שנגח הפרה וכן משמע בפסקי מהרא\"י סי' פ\"ג דא\"צ לעשות נקיות זו ע\"פ עכו\"ם עכ\"ל ובאמת המעיין שם יראה דלא משמע מידי ואני ראיתי בהג\"ה אשר\"י ס\"פ הכונס ומרדכי (ואגודה) פ' הגוזל בתרא כתבו וז\"ל והיכא ששני ישראלים דרים יחד בישוב ואין להם עדים ואתי חד וקצווח על חבריה דמסרו לעכו\"ם או לשלטון והלה אומר להד\"ם זה היה מעשה והורה ה\"ר אליעזר ממיץ בשם ר\"ת שיש לו לישבע לפני השלטון שלא דבר לשלטון על שכנגדו שום דבר רע המביאו לידי הפסד עכ\"ל ומביאו בד\"מ גופיה לעיל מיניה מיד הרי משמע להדיא דאף שלא היה עד אחד צריך לישבע לפני השלטון ונרא' דאף הר\"ב לא קאמר אלא לאפוקי שאין העכו\"ם נאמנים בכך לענין שיעשה נקיות זו בפניהם וזה באמת משמע לכאור' בתשו' מהר\"מ ופסקי מהרא\"י שם אבל אה\"נ אם הנמסר טוען ברי שמסרו צריך לעשות נקיות זו בפני השלטון אף שאין שם עד כלל והך עובדא דרבינו תם הי' הנמסר טוען ברי ומה שכתב הר\"ב ואין צריך לעשות נקיות זו אלא ע\"פ עד אחד כו' היינו כשאין הנמסר טוען ברי. שוב ראיתי בתשוב' מהרי\"ל סי' צ' משמע כדברי דאפי' בלא עד יש להשביעו בפני השר וכמ\"ש וע\"ש:","\u0003 שנים שמסרו ביחד כל א' משלם החצי \u0004 אפי' אין לחבירו לשלם א\"צ לשלם רק החצי כן הוא בהגהות מיימוני פי\"ב מהל' נזקי ממון ובמרדכי פרק הפרה בשם תשו' מהר\"ם ואזדא לטעמי' דלקמן ס\"ס ת\"י ועיין מ\"ש שם ובסוף ס' שארית יוסף כ' בכאן דברים שאינן מבוררין וע\"ש ומסיים בתשו' מהר\"מ במרדכי שם אמנם אם אתם רגילים לפטור המוסר לפי שהיה מוכה ואין אדם נתפס על צערו אז ירא' לי ששמעון המוסר השני חייב כל ההיזק אם יש עדים שמסרו שניהם ביחד כר' נתן דכל היכא דליכא לאשלומי מהאי משתלם מהאי ע\"כ:","\u0003 דכל זמן שלא נפטר ממסירה הראשונ' כו'. \u0004 ואם יש ספק בדבר אם נפטר ממסירה הראשונה מספיק' לא מפקינן ממונא והאחרון פטור כן הוא בתשובת מהר\"מ שם. ולפ\"ז לעולם אין חייב האחרון אלא כשידוע בבירור שכבר נפטר ממסירה הראשונה ואע\"ג דכתב בתשובת מהרי\"ל ר\"ס צ' וז\"ל כדפסיק מהר\"מ במרדכי אע\"ג דהתם כבר הי' פטור מן השופט וחזר עליו ע\"י מסירת שמעון כ\"ש הכא דלא נפטר ר' דוד כלל עדיין כו' עכ\"ל אין ר\"ל דהיה פטור לגמרי בבירור מן השופט רק שיצא מלפני השופט וכדאיתא בתשו' מהר\"מ שם ולפי הנראה היה פטור ממנו אבל אם נפטר ממנו בבירור האחרון חייב דמסירה חדשה היא וכמו שנראה מדברי הר\"ב:","\u0003 ואפי' לא מסרו כו' \u0004 כלו' אפי' לא מסר הראשון רק ראה השר או עכו\"ם שיגידו לשר פטור המוסר דהא בלא\"ה יודע לשר וכן כתב בדרכי משה בשם מהר\"מ מריזבורק וז\"ל ועוד כתב על שהכה חבירו ועכו\"ם ראוהו והלך אחד והגיד פטור דהא בלאו הכי ראוהו עכו\"ם ובודאי יגידו עד כאן:","\u0003 י\"א דאדם המוכה כו' \u0004 כתב בד\"מ וז\"ל וכ\"כ מהר\"מ מריזבורק וכתב דאם רגיל להכות הבריות מותר לקצץ ידו ע\"י עכו\"ם או להפסיד ממונו או להציל בא' מאבריו עכ\"ל וע\"ש שהאריך בדינים אלו ואין דבריו נראין דהא אפי' מוסר גמור אסור לאבד ממונו וכ\"ש זה כנ\"ל עכ\"ל ד\"מ ולא ירדתי לסוף דעת הר\"ב דז\"ל מהר\"מ מריזבורק מצוה לכל אדם להגיד לשופט פלוני הכה פלו'. ועוד הולכים בכעסם תעשה כך שלא יוסיף עוד ואם יעליל השופט עליו ויקח כל אשר לו פטור המגיד דאל\"כ אין לך אדם מציל את חברו מיד מכהו ודאי אם יכול להצילו בא' מאבריו יעשה כרב הונא דקץ ידא או שמא יותר טוב שיגיד לשופט ויפסיד ממון מלחסרו אחד מאיבריו והא רפיא עכ\"ל וא\"כ ל\"ק ממוסר דהכא להציל הוא בא וא\"א להצילו אם לא שיגיד לשופט וע\"י כך הוא מפסיד ממון ופשיטא דאם יכולים להציל הנמסר ע\"י שיפסיד המוסר ממון דשרי ומצוה הוא ועוד דממון מוסר דוקא לאבדו ביד אסור אבל להפסיד ע\"י גרמי מותר:","\u0003 ואפי' לא מסרו כו' \u0004 עיין בס' א\"א דף ע\"ז ע\"א:","\u0003 רק שאומר אלך כו' \u0004 ע\"ל סי' ל\"ד סעיף כ':","\u0003 נפסל לעדות כו' \u0004 עיין בתשובת הר\"ב סי' י\"ב דף כ\"ח ע\"ב ועיין בתשובת ן' לב ס' א' כלל י\"ז סי' כ\"ז וריש כלל כ' סי' ק\"ו ובתשוב' מבי\"ט ח\"א סי' ל\"ח:","\u0003 אם רגיל בכך כו'. \u0004 עיין בס' גדולת מרדכי פ' הגוזל בתרא:","\u0003 שאנסוהו להראות כו'. \u0004 פירוש אף שנשא ונתן אח\"כ ביד וכדמסיק וכן פירש בסמ\"ע ס\"ק כ\"ו מתחלה ועיקר:","\u0003 מ\"מ חייב לשלם. \u0004 ל' מהרש\"ל פ' הגוזל בתרא ס\"ס נ' ואם הודה המוסר מעצמו כ\"כ בהגוזל קמא גבי דינא דגרמי שאינו קנס וא\"כ ממילא חייב לשלם בהודאתו וכן נמצא בשם הר\"י מקורבי\"ל בעל הסמ\"ק להדיא עכ\"ל ולא נהירא דאף דהוי קנס מ\"מ לא אמרינן מודה בקנס פטור רק גבי קנס דאורייתא ולא בקנס דרבנן וכן משמע בפוסקים וכן בתשו' מהרי\"ל סי' צ' גבי מסירת ר' דוד ור' ישי כ' דהוי מדרבנן ואפ\"ה כתב בסוף התשובה דאם מודה ר' דוד ישלם וכן הוא להדיא במרדכי פרק הגוזל בתרא וז\"ל ואם הודו כמה גרמו להם להפסיד חייבים לפרוע כל מה שהודו דאף על גב דמודה בקנס פטור ודינא דגרמי הוי קנסא דרבנן ה\"מ בקנס דאורייתא משום דכתיב אשר ירשיעון אלקי' פרט למרשיע עצמו אבל קנסא דרבנן מחייב בהודאת עצמו ושלו' אביגדור ברבי אליה הכהן עכ\"ל והוא פשוט:","\u0003 במקום שיש חשש שיחזור וימסרנו אם א\"א להציל עצמו בדרך אחר כו'. \u0004 כן צ\"ל:","\u0003 לכל המוסר כו' אין לו חל\"ה. \u0004 ואמרינן נמי בפ\"ק דר\"ה (דף י\"ז ע\"א) דהמסורות יורדים לגיהנם ונידונין לדורי דורות וגופן כלה ונשמתן כלה כו' ע\"ש ועוד הבאתי לקמן ס\"ק ס' בשם התוס' והגהת אשרי שהוכיחו דגריע מהשומדים. ובי\"ד סי' ב' סעיף ט' בהג\"ה נתבאר דיש פוסלין שחיטת מוסר כמו שחיטת מומר ובי\"ד סי' רפ\"א ס\"ג נתבאר דס\"ת שכתבו מוסר או עכו\"ם או ישראל מומר פסולה:","\u0003 ומותר להורגו כו'. \u0004 כשאומר הריני מוסר כו' היינו כשניכר שיעשה כן וע' בתשו' רשב\"א סי' קפ\"א:","\u0003 עשה המוסר אשר זמם כו'. \u0004 ובמרדכי ס\"פ הגוזל בתרא הביא תשו' מהר\"מ בר ברוך שכ' וז\"ל שוב מצאתי שהוכיח רבינו שמחה שהרי\"ף חולק על הרמב\"ם שהרי\"ף הביא ראיה דממון מוסר אסור לאבדו ביד מדמבעי' בפ' הכונס אם עשו תקנת נגזל במוסר או לא וסלקא בתיקו ואי ס\"ל להרי\"ף סברת הרמב\"ם מאחר שעשה המוס' כאשר זמם דאסור להורגו וא\"כ ה\"ה לאבד ממונו דאסו' דהא מיניה יליף ומה מביא ראיה דלמא הא דבפרק הכונס איירי כגון שעשה המוסר אשר זמם ומ\"ה אסור לאבדו אלא ש\"מ דלית ליה האי סברא עכ\"ד ועיין במהרש\"ל פרק הגוזל בתרא סי' נ' שהשיב ע\"ז ובספרי השגתי עליו והוכחתי שהעיקר מהש\"ס דפ' הגוזל בתרא כר' שמח' שאפילו בפעם אח' נקרא מוסר ומותר להורגו וכן משמע מהתוס' ופסקי תוס' פרק הגוזל בתרא אך הרבה פוסקים נמשכו לדעת הרמב\"ם בזה:","\u0003 אא\"כ הוחזק למוסר \u0004 שהרי זה יהרג שמא ימסור אחרים ומעשים בכל יום בערי המערב להרוג המוסרי' שהוחזקו למסור ממון של ישראל ולמסור המוסרים ביד העכו\"ם להרגם ולהכותם כפי רשעיהם עכ\"ל רמב\"ם פ\"ח מה' חובל דין י\"א והביאו בתשו' מהר\"מ בר ברוך שהביא המרדכי ס\"פ הגוזל בתרא ע\"ש וכ\"כ הסמ\"ג דף קמ\"ח ע\"ג בשם הרמב\"ם בקצרה משמע דהורגים אותו בידים וכן משמע מל' פסקי תוס' פ\"ב דעכו\"ם סי' מ\"א שכתבו מוסר מותר להרגו אפי' מסר כבר עכ\"ל וכן מוכח להדיא מתשובות מהר\"מ ב\"ב שהשיב להרשב\"א שהביא הב\"י ס\"ס זה וכן פסק הרשב\"א להדיא בתשו' ששלח לחכמי צרפת ולמלך וכתב וז\"ל המינים והמסורות מורידין ולא מעלין ואפי' להורגן בידים וכן עושים מעשה במוסר מוחזק להורגן בידים ברוב מקומות ישראל וכן העיד הרמב\"ם ז\"ל בחבורו כו' עכ\"ל והא דמורידים ולא מעלין (ברייתא בפ\"ב דעכו\"ם דף כ\"ז ע\"ב) אין מפרשים הרמב\"ם וסייעתו כמ\"ש הרא\"ש בתשו' בטור בשם ר\"ח דדוקא מורידין ולא הורגים בידים אלא ה\"ה להורגו בידים אלא דקא' מורידי' היכא דא\"א להורגו ויש לסבב הריגתו ע\"י הורד' וכן נראה מדברי הרמב\"ם פ\"ד מה' רוצח ועיין בי\"ד סי' קנ\"ח ס\"ב וכן נ\"ל עיקר בש\"ס מדקאמ' סוף פרק הגוזל בתרא ממון מוסר חד אמר מותר לאבדו ביד לא יהא ממונו חמור עליו מגופו משמע דגופו מותר לאבדו ביד:","ושוב ראיתי במהרש\"ל פרק הגוזל בתרא סי' נ' כתב בזה דנוכל לפרש דה\"ק מאחר שמותר להרוג המוסר ע\"י הורדה א\"כ כ\"ש שהממון מותר לאבדו בידים ע\"כ ולא נהירא לי דמ\"מ מאי ק\"ו הוא זה ועוד דלישנא דש\"ס לא משמע הכי וגם מ\"ש מהרש\"ל שם דמהרי\"ף נראה קצת דאוסר להרוג המוסר בידים כיון דהשמיט עובדא דרב כהנא דשמטיה לקועי' כו' אלמא שסובר רב כהנא עשה שלא כדין שהרגו כו' לא נהירא לי שחלילה שהרי\"ף יחשוב על רב כהנא שעש' שלא כדין וגם פשט' דש\"ס לא משמע הכי אלא נראה דמאחר שהביא הרי\"ף בסוף הפרק לא יהא ממונו חמור מגופו לא הוצרך להאריך ולהביא עובדא דרב כהנא וגם יתר דברי מהרש\"ל שם אינם מוכרחים לפע\"ד והנלפע\"ד כתבתי ועיין מ\"ש לקמן סעיף ט\"ו ס\"ק ס\"ו:","\u0003 הוחזק למסו' כו' \u0004 כ' בתשובת רשב\"א שהביא ב\"י מחודש ח' שהשיב לחכמי צרפת ולמלך ואיזו מוחזק כל שנודע לרבים שהוא כן לא שהוחזק בב\"ד של כ\"ג ושקבלו עדיו בפניו שא\"כ אין לך מוחזק עכשיו שאין לנו מומחים והרי החכמים מחברי הספרים שהעידו וכתבו שהמוסר המוחזק הורגים אותו בכ\"ז וכל הנעשה ענוותן ומרחם על אלו נעשה אכזר על דורו ע\"כ ובתשו' מהר\"מ ב\"ב שהשיב להרשב\"א שהביא בב\"י ס\"ס זה כ' הוחזק היינו ג' פעמים דאתחזק בין לר' בין לרשב\"ג ולא הרגשנו בו צד תשובה כל הקודם להורגו זכה דגדולה חזקה דהא סוקלין ושורפים על החזקות ע\"כ וכן הוא בתשו' הרא\"ש בטור ס\"ס זה והמחבר לקמן סעיף ט\"ו מי שמוחזק ששלשה פעמים מסר כו' וע' בש\"ס פרק הבא על יבמתו (סוף יבמות דף ס\"ד) ובסנהדרין פרק הנשרפים (סנהדרין דף פ\"א ע\"ב) במי שלקה ושינה שלישית מכניסים אותו לכיפה כו' ובהרמב\"ם פי\"ח מהלכות סנהדרין דין ד':","\u0003 שהרי זה יהרג וכו'. \u0004 וכ' הריב\"ש סי' רצ\"ו דמי שנתפס מפני שחייב מיתה אין מקבלין ממנו ערבית דמה נעשה לערבים אם יברח והביאוהו האחרונים:","\u0003 כל המוסר כו'. \u0004 כן הוא בכל ספרי המחבר ובעיר שושן וטעות הוא וצ\"ל כל המיצר וכן הוא בטור ורמב\"ם:","\u0003 מפני צער יחיד כו' \u0004 דווקא צער יחיד (וע\"ל ס\"ק מ\"ג דמי שרגיל להכות מותר למוסרו להציל שלא יכה עוד) אבל במוסר ליחיד דינו כמוסר לצבור מיהו אפשר דלהרמב\"ם דס\"ל דאם כבר מסר אין הורגין אותו אא\"כ הוחזק במוסר ס\"ל דבמוסר לצבור אפי' לא הוחזק מותר למוסרו ביד עכו\"ם:","\u0003 ואם גרם לו היזק. \u0004 יותר ממה שחייב להעכו\"ם:","\u0003 אסור לאבד ממונו של מוסר ביד. \u0004 אבל ע\"י גרמא או גרמי מותר טור בשם בעל העיטור ומהרי\"ו סי' ק\"ס ולמסור ממונו לעכו\"ם אסור כ\"כ מהרש\"ל פ' הגוזל בתרא ס\"ס נ' וע\"ש שהביא ראי' מעובדא דמסירות ר' יואל ור' אפרים במרדכי ולפ\"ז משמע דאם חזר ומסר ממונו חייב לשלם לו מה שהפסידו כדאי' במרדכי שם בההיא עובדא וכדלעיל סעיף ט' בהג\"ה ע\"ש ודוק:","ונראה דמי שמוחזק למסור ונראה שאין דבריו נשמעין רק מחמת עשרו וכשיעני לא יהיו דבריו נשמעים מותר לאבד ממונו או למוסרו לעכו\"ם שהרי במה שמאבדין ממונו מצילים אחרים. בתוס' פ\"ב דעכו\"ם דף כ\"ו ע\"ב נסתפקו אי משיבין אבדתו וכתבו דמוסר גרע ממומר ובכ\"מ שונה מוסר אצל מין ולא אתרבי אצל אבדה ושמא מאן דאית ליה ממון מוסר אסור לאבדו ביד אית להו נמי דמשיבין אבדתו ומטעמא דיכין רשע וצדיק ילבש עכ\"ל ובהגהת אשר\"י ס\"פ אלו מציאות כתבו דמוסר הוי כמו מומר להכעיס דאסור להחזיר אבדתו וע\"ש:","\u0003 וי\"א דמותר כו'. \u0004 והרי\"ף וסייעתו בע\"כ לא ס\"ל הכי וכן משמע במרדכי שם שבעל סברא זו חולק על הרי\"ף ומהרש\"ל שם סי' ן' פסק דאסור ליטול ממונו לעצמו וכן עיקר וכן משמע להדיא מתשו' רש\"י שבמרדכי פ\"ק דקידושין והביא' ב\"י לעיל ר\"ס רפ\"ג מחודש ב' ע\"ש:","\u0003 ואין צריכין לכוין העדות כל כך. \u0004 כלומר דאע\"ג דדיני נפשות צריך דרישה וחקירה כדלעיל סי' ל' במוסר אין מדקדקים כל כך כן הוא בטור סי\"ג בשם תשו' הרא\"ש וז\"ל ואלו רצו לקבל העדות לפניו ולדרוש ולחקור בדינו לעולם לא יעשה לו דין כי יציל ע\"י עכו\"ם כו' ויסכן כל ישראל כו':","\u0003 ע\"י גרמא. \u0004 כגון ע\"י הורדה לבור או ע\"י עכו\"ם כן הוא בטור בתשו' הרא\"ש והובא בסמ\"ע ס\"ק ל\"ה ומהרש\"ל פ' הגוזל בתרא סי' ן' חולק ופסק דע\"י עכו\"ם הוי כאלו הורגו בעצמו דהעכו\"ם יש שליח לד\"ע לחומרא ודוקא הורדה לבור שרי אבל ע\"י עכו\"ם אסור ואין דבריו מוכרחים גם שאר דברים שכ' שם אינם מוכרחים וע' מ\"ש בס\"ק שאח\"ז:","\u0003 אע\"פ שאסור להורגו. \u0004 באמת כ\"כ הטור תשו' הרא\"ש בשם ר\"ח אבל תימה על הר\"ב שכתב כן בפשיטות שהרי מדברי המחבר לעיל סעיף י\"א מבואר שיש להורגו וכן הבאתי לעיל ס\"ק נ\"ו שהוא דעת הרמב\"ם והרשב\"א ושאר הרבה פוסקים והבאתי ראיות לדבריהם ע\"ש ובסמ\"ע ס\"ק ל\"ה כ' שמדברי בעל העיטור מוכח דס\"ל כר\"ח ולפעד\"נ דבע\"ה לא קאי רק אממון ע\"ש:","\u0003 אם השליח הוחזק לעשות חייב המשלח כו'. \u0004 דין זה שכתבו הר\"ב והר\"ש בן צמח לא נהירא לי וז\"ל הרשב\"ץ ולא תימא אין שליח לד\"ע דלא מיפטר בה\"ט אלא בישראל אבל אם הוחזק במוסר ובאנס לאו ישראל הוא וכמו שכתב הרמב\"ם הל' עדות המוסרים הם פחותים מן העכו\"ם וכיון שכן אין למשלח טענה לפטור משום דברי הרב וכו' שזה מפורסם שאינו שומע דברי הרב עכ\"ל הביאו ב\"י ס\"ס זה ואין דבריו נכונים בעיני ולא מבעי' למה שפסקו הרמ\"ה והרא\"ש והנימוקי יוסף ושאר הרבה פוסקים כרב סמא בפ\"ק דמציעא לעולם אין שליח לד\"ע אפי' השליח לאו בר חיובא הוא כיון דאי בעי עביד ואי לא בעי לא עביד א\"כ פשיטא הכא פטור המשלח דהא הכא נמי אי בעי המוסר עביד אי בעי לא עביד תדע דהא כתבו הפוסקים הנ\"ל דלעולם לא משכחת שליח לד\"ע אלא חצר ואם איתא הא משכחת נמי מוחזק בכך אלא ודאי כמ\"ש אלא אפי' לרבינא דס\"ל דהיכא דהשליח לאו בר חיובא הוא מיחייב שולחו פטור הכא דס\"ס זה ישראל הוא ובר חיובא הוא ולא כתב הרמב\"ם דהם פחותים מן העכו\"ם אלא לענין דפסולים לעדות אבל מ\"מ ישראל הוא ובר חיובא הוא ומה בכך שהוחזק במוסר ס\"ס בר חיובא הוא והכי מוכח מדברי כל הפוסקים בכמה דוכתי שכתבו וסתמו אין שליח לד\"ע ולא חלקו בין שהשליח מוחזק בכך או לא. ועוד נראה דהרב לטעמיה אזיל דס\"ל לעיל ר\"ס קפ\"ב דהכל תלוי כשהשליח בר חיובא אבל כבר חלקתי שם עליו ע\"ש ונראה דגם הרשב\"ץ לא פסק כן בתשובה אלא משום שצירף עוד טעמים שם לזה וז\"ל ועוד שזה דומה לשליחות יד דחייבה רחמנא ע\"י שליח ועוד יש לחייבו כאילו מסרו אל האנס עצמו ואין אנו צריכין לבא עליו מדין שליח שכיון שהוחזק הזקן מוסר המוסר בידו כמוסר ביד האנס כו' עכ\"ל לפי עניות דעתי גם זה אינו נכון דנהי דשליחות יד חייב אף ע\"י שליח היינו בשולח יד בממון אבל כאן מה שליחות יד שייך ועוד דשולח יד הוי גזלן וכבר כתבתי לעיל סי' שפ\"ו ס\"ק י\"ג דשטרות אימעטי מגזלה ועוד דכיון דכתבתי לקמן בס\"ק שאח\"ז דאפילו מסר הוא עצמו השטרות להעכו\"ם פטור דלאו מידי עבד א\"כ כ\"ש כשמסרם למסור שימסרם לעכו\"ם. כן נראה לי ברור:","\u0003 וכן אם מסר שטר פרוע כו'. \u0004 ג\"ז מהרשב\"ץ ולא נהירא לי כלל ואפילו מסרו לשר גופיה פטור דליכא כאן גרמ' גם מ\"ש הרשב\"ץ בסוף דבריו וגדולה מזאת שאפילו היה ראובן המלוה ושמעון מסר שטרו ביד מוסר והפסיד חובו מיחייב שמעון מדין מוסר כו' עכ\"ל לא נהירא לי דאדרבא איפכא מסתברא בהך דראובן הוא המלוה דוקא חייב ולא מטעם מוסר אלא מטעם דכיון שהוא הפקידו אצלו והוא מוסרו למוסר קלייה לשטריה והוי כשורף שטורותיו של חברו דחייב מדינא דגרמי וכדאיתא בתשובת הרא\"ש כלל ל\"ט סי' ב' ונתבא' לעיל סי' ס\"ו ס\"ק קכ\"ז וסי' שפ\"ו ס\"ק כ\"ב אבל כשמס' שטרות פרועי' שלו לעכו\"ם ליכא כאן גרמי וכמ\"ש הרשב\"א להדיא בתשובה והביאו הב\"י לעיל סי' שפ\"ו מחו' א' והרב בד\"מ שם וז\"ל רואה אני לפטו' את שמעון אם עבר והחזיר השטר לעכו\"ם וכל שאינו זוכה מיד אינו קרוי דינא דגרמי אלא גרמא בניזקין ופטו' עכ\"ל וכ\"כ בתשובות מהר\"י לבית לוי סי' ל\"ד ובתשובת מהר\"ם אלשיך סי' קי\"ב דברי תשו' רשב\"א זו לפסק הלכה וכן בתשו' מהר\"מ מלובלין סי' ס\"א וכן בתשובת משאת בנימן סי' פ\"ה. שוב ראיתי בד\"מ שכתב ע\"ז וז\"ל וע\"ל סימן שפ\"ו דיש חולקין בזו ונראה דר\"ל תשו' הרשב\"א דלעיל שהביא בד\"מ שם. וא\"כ כ\"ש שיש לתמוה על הר\"ב שכתב כאן בסתם כדברי הרשב\"ץ וגם לענין דינא נ\"ל דברי הרשב\"א עיקר וכמ\"ש:"],"\u0003הלכות מאבד ממון חבירו בידים ומוסר ומלשין\u0004\n\u0010g0\u0011 \u0010r0\u0011 הַמַּזִּיק \u0010y0\u0011 מָמוֹן \u0010c0\u0011 חֲבֵרוֹ וְאֵינוֹ \u0010t0\u0011 יוֹדֵע מַה הִזִּיק, נִשְׁבָּע הַנִּזָּק וְנוֹטֵל. \u0010g1\u0011 כֵּיצַד, לָקַח כִּיס \u0010c1\u0011 \u0010t1\u0011 חֲבֵרוֹ וְהִשְׁלִיכוֹ לַמַּיִם \u0010r1\u0011 אוֹ לָאֵשׁ \u0010r2\u0011 אוֹ שֶׁמְּסָרוֹ לְיַד אַנָּס, וְאָבַד, בַּעַל הַכִּיס אוֹמֵר: זְהוּבִים הָיָה מָלֵא, וְהַמַּזִּיק אוֹמֵר: אֵינִי יוֹדֵעַ מֶה הָיָה בּוֹ, \u0010r3\u0011 שֶׁמָּא עָפָר אוֹ תֶּבֶן הָיָה מָלֵא, הֲרֵי \u0010g2\u0011 הַנִּזָּק נִשְׁבָּע \u0010r4\u0011 בִּנְקִיטַת חֵפֶץ וְנוֹטֵל. \u0010g3\u0011 וְהוּא שֶׁיִּטְעֹן דְּבָרִים שֶׁהוּא אָמוּד בָּהֶם \u0010c2\u0011 אוֹ אָמוּד \u0010t2\u0011 לְהַפְקִידָם אֶצְלוֹ \u0010r5\u0011 וְדַרְכָּן לְהַנִּיחָם בְּכִיס וְכַיּוֹצֵא בּוֹ. \u0010y1\u0011 \u0005אַרְנָקִי בְּשַׂק, אִם הוּא שַׁבָּת וְיו\"ט, מִקְרֵי דַּרְכּוֹ בְכָךְ, וְכָל כַּיּוֹצֵא בְזֶה (מָרְדְּכַי פֶּרֶק הַכּוֹנֵס)\u0006. \u0010y2\u0011 \u0010g4\u0011 \u0010g5\u0011 \u0010r6\u0011 אֲבָל אִם אֵין דַּרְכָּם לְהַנִּיחָם בִּכְלִי זֶה, \u0010c3\u0011 \u0010t3\u0011 \u0010r7\u0011 הוּא פָּשַׁע בְּעַצְמוֹ \u0010r8\u0011 \u0005וּפָטוּר הַמַּזִּיק.\u0006 כֵּיצַד, \u0010c4\u0011 הֲרֵי שֶׁחָטַף \u0010t4\u0011 חֵמֶת אוֹ סַל מְלֵאִים וּמְחֻפִּים וְהִשְׁלִיכָם לַיָּם אוֹ שְׂרָפָם, וְטָעַן הַנִּזָּק שֶׁמַּרְגָּלִיּוֹת הָיוּ בְּתוֹכָהּ, \u0010c5\u0011 אֵינוֹ נֶאֱמָן. \u0005וְיֵשׁ אוֹמְרִים דַּאֲפִלּוּ הָיוּ עֵדִים שֶׁהָיוּ שָׁם, פָּטוּר, הוֹאִיל וּפָשַׁע, כְּמוֹ שֶׁנִּתְבָּאֵר (הַמַּגִּיד פ\"ז דְּחוֹבֵל בְּשֵׁם תוס' וע\"ל ס\"ק ו')\u0006. \u0010c6\u0011 \u0010r9\u0011 וְאִם \u0010t5\u0011 תָּפַס, אֵין מוֹצִיאִין מִיָּדוֹ. \u0010c7\u0011 \u0005וְיֵשׁ חוֹלְקִין (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. וְיִשָּׁבַע שֶׁמַּרְגָּלִיּוֹת הָיָה בְּתוֹכוֹ, וְנוֹטֵל מַה שֶּׁיֵּשׁ אֶצְלוֹ, וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0010c8\u0011 \u0010g6\u0011 וְאִם \u0010t6\u0011 יָדַע הַמַּזִּיק שֶׁהַכִּיס הָיָה בּוֹ זְהוּבִים, אֲבָל אֵינוֹ יוֹדֵעַ כַּמָּה הָיוּ, אִם הַנִּזָּק אוֹמֵר: אֶלֶף, נוֹטֵל אֶלֶף בְּלֹא שְׁבוּעָה, \u0010r10\u0011 וְהוּא שֶׁיִּהְיֶה אָמוּד, שֶׁהֲרֵי הַמַּזִּיק מְחֻיָּב שְׁבוּעָה וְאֵינוֹ יָכוֹל \u0010c9\u0011 לִשָּׁבַע. \u0005וְיֵשׁ אוֹמְרִים דְּנִשְׁבַּע \u0010t7\u0011 הַנִּזָּק וְנוֹטֵל, וְכֵן עִקָּר (טוּר סִימָן צ' בְּשֵׁם הָרַאֲבַ\"ד וְהַמַּגִּיד פֶּרֶק הַנַּ\"ל וְהָרֹא\"שׁ)\u0006. \u0010c10\u0011 \u0010g7\u0011 \u0010t8\u0011\nהַמּוֹסֵר מָמוֹן בִּידֵי אַנָּס, בֵּין אַנָּס \u0010r11\u0011 גּוֹי בֵּין אַנָּס יִשְׂרָאֵל, חַיָּב לְשַׁלֵּם \u0010y3\u0011 \u0010c11\u0011 \u0010g8\u0011 \u0010r12\u0011 מֵהַיָּפֶה שֶׁבִּנְכָסָיו כָּל מַה שֶּׁלָּקַח הָאַנָּס, \u0010g9\u0011 \u0010r13\u0011 אַף עַל פִּי שֶׁלֹּא נָשָׂא הַמּוֹסֵר, וְלֹא נָתַן בְּיָדוֹ \u0010y4\u0011 \u0010c12\u0011 \u0010r14\u0011 אֶלָּא \u0010g10\u0011 הִרְגִּיל בִּלְבַד. \u0010c13\u0011 \u0010g11\u0011 \u0010r15\u0011 וְאִם מֵת, גּוֹבִים מִיּוֹרְשָׁיו כִּשְׁאָר כָּל הַמַּזִּיקִים. \u0010c14\u0011 \u0010r16\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּדַוְקָא \u0010r17\u0011 שֶׁעָמַד \u0010t9\u0011 בַּדִּין; אֲבָל אִם לֹא עָמַד בַּדִּין, אֵין הַיּוֹרְשִׁין חַיָּבִין לְשַׁלֵּם. \u0010r18\u0011 וְאִשָּׁה שֶׁמָּסְרָה, מְשַׁמְּתִינָן לָהּ. \u0010r19\u0011 וְאִם יֵשׁ לָהּ מָמוֹן שֶׁאֵין לַבַּעַל רְשׁוּת בּוֹ, מְשַׁלֶּמֶת. \u0010r20\u0011 וְאִם יֵשׁ לָהּ נִכְסֵי מְלוֹג, \u0010y5\u0011 \u0010c15\u0011 \u0010r21\u0011 הַבַּעַל אוֹכֵל פֵּרוֹת כָּל יְמֵי \u0010t10\u0011 חַיֶּיהָ, וְאִם מֵתָה חַיָּב לְשַׁלֵּם לַנִּמְסָר, וְכֵן לִשְׁאָר \u0010c16\u0011 נִזָּק, וְאֵין הַבַּעַל \u0010y6\u0011 לְעִנְיַן זֶה רַק כְּיוֹרֵשׁ שֶׁחַיָּב לְשַׁלֵּם (מָרְדְּכַי פֶּרֶק הַחוֹבֵל)\u0006. \u0010g12\u0011 בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁהֶרְאָה הַמּוֹסֵר מֵעַצְמוֹ. אֲבָל אִם אֲנָסוּהוּ גּוֹיִים אוֹ יִשְׂרָאֵל אַנָּס לְהַרְאוֹת, וְהֶרְאָה, הֲרֵי זֶה פָּטוּר מִתַּשְׁלוּמִין. \u0010r22\u0011 \u0005וְאִם אָנְסוֹ לְהַרְאוֹת שֶׁלּוֹ \u0010y7\u0011 \u0010c17\u0011 וְהֶרְאָה [שֶׁלּוֹ וְ] שֶׁל חֲבֵרוֹ, חַיָּב (טוּר \u0010g13\u0011 ס\"א)\u0006. וְאִם נָשָׂא וְנָתַן בְּיָד, \u0010r23\u0011 אַף עַל פִּי שֶׁהוּא אָנוּס, חַיָּב לְשַׁלֵּם, \u0010r24\u0011 שֶׁהַמַּצִּיל עַצְמוֹ בְּמָמוֹן \u0010y8\u0011 \u0010c18\u0011 \u0010g14\u0011 \u0010t11\u0011 \u0010r25\u0011 חֲבֵרוֹ חַיָּב. כֵּיצַד, \u0010c19\u0011 הֲרֵי שֶׁגָּזַר הַמֶּלֶךְ \u0010t12\u0011 לְהָבִיא לוֹ יַיִן אוֹ תֶבֶן וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ, וְעָמַד מוֹסֵר וְאָמַר: הֲרֵי יֵשׁ לִפְלוֹנִי אוֹצַר יַיִן אוֹ תֶבֶן בְּמָקוֹם פְּלוֹנִי, וְהָלְכוּ וּלְקָחוּהוּ, חַיָּב לְשַׁלֵּם. \u0010g15\u0011 \u0005הַגָּה: \u0010c20\u0011 \u0010r26\u0011 וַאֲפִלּוּ יִסְּרוּהוּ, וְלֹא אָמְרוּ לוֹ עַל מָה, וְהֶרְאָה מָמוֹן \u0010g16\u0011 \u0010t13\u0011 חֲבֵרוֹ, חַיָּב (טוּר שָׁם)\u0006 \u0010r27\u0011 ; וְלֹא מִקְרֵי אוֹנֶס, אֶלָּא הַכָּאוֹת וְיִסּוּרִין, \u0010c21\u0011 אֲבָל לֹא \u0010t14\u0011 אֹנֶס מָמוֹן \u0005(מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא וּתְשׁוּבַת מַיְמוֹנִי דִנְזִיקִין סי\"ב וְנ\"י)\u0006. \u0010y9\u0011 \u0010r28\u0011 הָיָה רוֹאֶה נֶזֶק בָּא עָלָיו, מֻתָּר לְהַצִּיל עַצְמוֹ אַף עַל פִּי שֶׁעַל יְדֵי זֶה בָּא הַנֶּזֶק \u0010t15\u0011 לְאַחֵר \u0010y10\u0011 \u0010c22\u0011 \u0010g17\u0011 \u0005(נִמּוּקֵי יוֹסֵף פֶּרֶק הַשֻּׁתָּפִין)\u0006.\nאֲנָסוֹ הַמֶּלֶךְ לְמוֹסֵר זֶה עַד שֶׁיַּרְאֶה לוֹ מָמוֹן \u0010t16\u0011 חֲבֵרוֹ שֶׁהוּא בּוֹרֵחַ מִלְּפָנָיו, \u0010y11\u0011 וְהֶרְאָה לוֹ מִפְּנֵי \u0010t17\u0011 הָאֹנֶס, הֲרֵי זֶה פָּטוּר, \u0010r29\u0011 שֶׁאִם לֹא יַרְאֶה לוֹ יַכֵּהוּ אוֹ יְמִיתֵהוּ. \u0010c23\u0011 \u0010g18\u0011 \u0010r30\u0011\nנָשָׂא מָמוֹן חֲבֵרוֹ בְּיָדוֹ וּנְתָנוֹ לָאַנָּס, \u0010t18\u0011 חַיָּב לְשַׁלֵּם \u0010y12\u0011 מִכָּל מָקוֹם, אַף עַל פִּי שֶׁהַמֶּלֶךְ אֲנָסוֹ לְהָבִיא. \u0010r31\u0011 \u0005ב' שֻׁתָּפִים שֶׁהָיָה לָהֶן חוֹב בְּיַחַד, וְאָנַס שַׂר לְאֶחָד לִפְטֹר הַחוֹב, פָּטוּר, \u0010y13\u0011 \u0010c24\u0011 דְּזֶה לֹא מִקְרֵי נָתַן \u0010t19\u0011 בְּיָד (מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁאִם אֲנָסוֹ לְהָבִיא וְהֵבִיא חַיָּב, כְּשֶׁלֹא הִגִּיעַ הַמָּמוֹן לִרְשׁוּת הָאַנָּס; \u0010g19\u0011 אֲבָל אַנָּס שֶׁאָנַס אֶת יִשְׂרָאֵל עַד שֶׁהֶרְאָהוּ, וְעָמַד הָאֲנָס עַל הַמָּמוֹן וְנַעֲשָׂה בִּרְשׁוּתוֹ \u0010r32\u0011 \u0005דְּהַיְנוּ שֶׁיּוּכַל לִשְׁלֹט עָלָיו וְלִטְּלוֹ (הַמַּגִּיד פ\"ח \u0010g20\u0011 דְּחוֹבֵל)\u0006, וְאָנַס אֶת יִשְׂרָאֵל עַד שֶׁהוֹלִיכוּ לְמָקוֹם אַחֵר, וַאֲפִלּוּ הוֹלִיכוֹ זֶה הַמּוֹסֵר שֶׁהֶרְאָהוּ, הֲרֵי זֶה פָּטוּר, \u0010y14\u0011 שֶׁכֵּיוָן שֶׁעָמַד הָאַנָּס \u0010t20\u0011 בְּצַד הָאוֹצָר כְּבָר אָבַד כָּל מַה שֶּׁיֵּשׁ בּוֹ, וּכְאִלּוּ נִשְׂרַף: \u0010g21\u0011\nבַּעֲלֵי דִין שֶׁהָיְתָה בֵינֵיהֶם מְרִיבָה עַל הַקַּרְקַע אוֹ עַל מִטַּלְטְלִין, זֶה אוֹמֵר: שֶׁלִּי, וְזֶה אוֹמֵר: שֶׁלִּי, עָמַד אֶחָד מֵהֶם \u0010y15\u0011 וּמְסָרָהּ בְּיַד גּוֹיִים, מְנַדִּין אוֹתוֹ עַד שֶׁיַּחֲזִיר הַדָּבָר לִכְמוֹת שֶׁהָיָה, וִיסַלֵּק יַד אַנָּס מִבֵּינֵיהֶם \u0010g22\u0011 וְיַעֲשׂוּ דִּין בְּיִשְׂרָאֵל. \u0005הַגָּה: \u0010c25\u0011 \u0010r33\u0011 מִכָּל מָקוֹם אֵין לוֹ דִּין מוֹסֵר, אַף עַל פִּי שֶׁהִפְסִיד חֲבֵרוֹ עַל יְדֵי זֶה הַרְבֵּה, דְּלָא מִקְרֵי מוֹסֵר אֶלָּא בְּמִתְכַּוֵּן לְהַזִּיק, \u0010g23\u0011 אֲבָל לֹא בְּמִתְכַּוֵּן לְהוֹצִיא אֶת שֶׁלּוֹ (תְּשׁוּבַת מיי' דִּנְזִיקִין סִימָן כ\"א וּמָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא בְּשֵׁם ר\"א)\u0006. וְיֵשׁ \u0010t21\u0011 חוֹלְקִין \u0010y16\u0011 \u0010g24\u0011 וּסְבִירָא לְהוּ דְּמִקְּרֵי מוֹסֵר וְחַיָּב לְשַׁלֵּם לוֹ כָּל הֶזֵּקוֹ, אִם לֹא הָיָה חֲבֵרוֹ סַרְבָן; וְכָל שֶׁכֵּן אִם הִתְרוּ בּוֹ תְּחִלָּה שֶׁלֹּא יִדּוֹנוּ בִּפְנֵי גּוֹיִם, וְעָבַר, שֶׁיֵּשׁ לוֹ דִין מוֹסֵר \u0005(מָרְדְּכַי פֶּרֶק הַגּוֹזֵל קַמָּא בְּשֵׁם מַהֲרַ\"ם וּפֶרֶק הַמַּנִיחַ וּתְשׁוּבַת הָרֹא\"שׁ כְּלָל י\"ז סִימָן ד' וּמַהֲרִי\"ק שֹׁרֶשׁ קנ\"ד וקס\"א)\u0006. \u0010c26\u0011 \u0010g25\u0011\nמִי \u0010t22\u0011 שֶׁנִּתְפַּס עַל חֲבֵרוֹ, וְלָקְחוּ גוֹיִים מָמוֹן מִמֶּנּוּ בִּגְלַל \u0010y17\u0011 חֲבֵרוֹ, אֵין חֲבֵרוֹ חַיָּב לְשַׁלֵּם. אֵין לְךָ מִי שֶׁנִּתְפַּס עַל חֲבֵרוֹ וְיִהְיֶה חֲבֵרוֹ חַיָּב לְשַׁלֵּם לוֹ, חוּץ מֵהַנִּתְפַּס \u0010y18\u0011 מִפְּנֵי הַמַּס הַקָּצוּב עַל כָּל אִישׁ וְאִישׁ \u0010g26\u0011 בְּכָל שָׁנָה, אוֹ הַנִּתְפַּס עַל הַתְּשׁוּרָה שֶׁנּוֹתֵן כָּל אִישׁ לַמֶּלֶךְ בְּעָבְרוֹ עֲלֵיהֶם אוֹ חַיָּלוֹתָיו, הֲרֵי זֶה חַיָּב לְשַׁלֵּם לוֹ; וְהוּא שֶׁיִּקְּחוּ מִמֶּנּוּ בְּפֵרוּשׁ בִּגְלַל פְּלוֹנִי, בִּפְנֵי עֵדִים; וְנִתְבָּאֵר עוֹד בְּסִימָן קכ\"ח. \u0010y19\u0011 \u0010c27\u0011 \u0010g27\u0011\nמִי שֶׁיֵּשׁ עָלָיו \u0010t23\u0011 עֵדִים שֶׁמָּסַר מָמוֹן חֲבֵרוֹ, כְּגוֹן שֶׁהֶרְאָה מֵעַצְמוֹ \u0010c28\u0011 אוֹ \u0010t24\u0011 שֶׁנֶּאֱנַס \u0010c29\u0011 וְנָשָׂא וְנָתַן, וְלֹא יָדְעוּ הָעֵדִים כַּמָּה הִפְסִידוֹ בִּמְסִירָתוֹ, וְהַנִּמְסָר אוֹמֵר: כָּךְ וְכָךְ הִפְסִידָנִי, \u0010c30\u0011 וְהַמּוֹסֵר \u0010t25\u0011 כּוֹפֵר בַּמֶּה שֶׁטָּעֲנוֹ, \u0010y20\u0011 \u0010c31\u0011 אִם \u0010t26\u0011 \u0010r34\u0011 תָּפַס הַנִּמְסַר אֵין מוֹצִיאִין מִיָּדוֹ, אֶלָּא נִשְׁבָּע בִּנְקִיטַת חֵפֶץ וְזוֹכֶה בַּמֶּה שֶׁתָּפַס. \u0010c32\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּבִסְפֵיקָא דְדִינָא לָא מְהַנֵּי תְּפִיסָה (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006 \u0005(וע\"ל ס\"ק ל\"ב)\u0006. וְאִם לֹא תָּפַס, אֵין מוֹצִיאִין מִן הַמּוֹסֵר אֶלָּא \u0010c33\u0011 \u0010t27\u0011 בִּרְאָיָה בְּרוּרָה. \u0010r35\u0011 \u0005וְאִם [לֹא] יָדְעוּ בֵּרוּר הַדְּבָרִים, \u0010y21\u0011 \u0010c34\u0011 רַק שֶׁהֻצְרַךְ לְהִתְפַּשֵּׁר עִם הַשַּׂר \u0010g28\u0011 \u0010t28\u0011 בְּכָךְ וְכָךְ, הַנִּמְסַר נִשְׁבָּע וְנוֹטֵל. (מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006 \u0010c35\u0011 \u0010g29\u0011 \u0010r36\u0011 וְיֵשׁ \u0010c36\u0011 מִי שֶׁאוֹמֵר, שֶׁאִם הַמּוֹסֵר אוֹמֵר: \u0010c37\u0011 אֵינִי יוֹדֵעַ כַּמָּה הִפְסַדְתָּ עַל יָדִי, יִשָּׁבַע הַנִּמְסַר \u0010t29\u0011 וְיִטֹּל. \u0005הַגָּה: (וע\"ל ס\"ק \u0010c38\u0011 \u0010r37\u0011 ל\"ז)\u0006 וְכָל זֶה בְּמוֹסֵר מָמוֹן; אֲבָל מָסַר \u0010t30\u0011 גּוּפוֹ שֶׁל חֲבֵרוֹ \u0005(לַאֲנָסִים)\u0006, הַנִּמְסַר נִשְׁבָּע וְנוֹטֵל. וְכֵן אִם גָּרַם לוֹ תְּפִיסָה, \u0010y22\u0011 דְּהָוֵי כְּמַזִּיק בְּיָדַיִם \u0010r38\u0011 וְצָרִיךְ לְשַׁלֵּם לוֹ כָּל הֶזֵּקוֹ \u0005(מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006. \u0010y23\u0011 \u0010c39\u0011 \u0010r39\u0011 הָאוֹמֵר \u0010t31\u0011 לַחֲבֵרוֹ: מְסַרְתַּנִי, וְהוּא כּוֹפֵר, יִשָּׁבַע לוֹ הֶסֵּת \u0005(הַגָּהוֹת אֲשֵׁירִי)\u0006. \u0010r40\u0011 וְיֵשׁ אוֹמְרִים דְּצָרִיךְ לִשָּׁבַע לוֹ לִפְנֵי הַשַּׂר שֶׁלֹּא מְסָרוֹ לוֹ \u0005(מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006. \u0010c40\u0011 \u0010r41\u0011 וְאֵין צָרִיךְ לַעֲשׂוֹת נְקִיּוּת זוֹ, אֶלָּא \u0010t32\u0011 עַל פִּי אֶחָד הַמֵּעִיד שֶׁמְּסָרוֹ, אֲבָל אֵין הַגּוֹיִים נֶאֱמָנִים בְּכָךְ \u0005(מָרְדְּכַי פֶּרֶק הַחוֹבֵל וּפֶרֶק הַפָּרָה וּפִסְקֵי מהרא\"י סִימָן פ\"ג וּתְשׁוּבַת רַשְׁבָּ\"א סִימָן אֶלֶף \u0010c41\u0011 \u0010r42\u0011 צ\"ח)\u0006. שְׁנַיִם שֶׁמָּסְרוּ בְּיַחַד, כָּל אֶחָד מְשַׁלֵּם \u0010t33\u0011 הַחֵצִי, \u0010g30\u0011 \u0010r43\u0011 וְאִם בְּזֶה אַחַר זֶה, הָאַחֲרוֹן \u0010g31\u0011 פָּטוּר, \u0010c42\u0011 דְּכָל זְמַן שֶׁלֹּא \u0010t34\u0011 נִפְטַר מִמְּסִירָה הָרִאשׁוֹנָה הַנֶּזֶק בָּא מִגְּרַם הָרִאשׁוֹן \u0005(מָרְדְּכַי פֶּרֶק הַפָּרָה)\u0006. \u0010y24\u0011 \u0010c43\u0011 \u0010g32\u0011 \u0010r44\u0011 וַאֲפִלּוּ לֹא מְסָרוֹ, רַק רָאָה אַנָּס אוֹ גוֹיִים שֶׁיַּגִּידוּ לַשַּׂר \u0010c44\u0011 \u0010r45\u0011 \u0005(מַהֲרַ\"ם מֵרִיזְבּוּרְק)\u0006. יֵשׁ אוֹמְרִים דְּאָדָם הַמֻּכֶּה מֵחֲבֵרוֹ יָכוֹל לֵילֵךְ לִקְבֹּל לִפְנֵי גוֹיִים, אַף עַל פִּי דְגוֹרֵם לַמַּכֶּה הֶזֵּק גָּדוֹל \u0005(מָרְדְּכַי הַנַּ\"ל ומהרי\"ו סִימָן כ\"ח וּתְשׁוּבַת מַיְמוֹנִי דִנְזִיקִין סִימָן ס\"ו וּמַהֲרַ\"ם \u0010g33\u0011 \u0010r46\u0011 מֵרִיזְבּוּרְק)\u0006.\nאֵין מַשְׁבִּיעִין אֶת הַמּוֹסֵר שֶׁהֶרְאָה מֵעַצְמוֹ, \u0010r47\u0011 לֹא שְׁבוּעָה חֲמוּרָה וְלֹא שְׁבוּעַת הֶסֵת, מִפְּנֵי שֶׁהוּא רָשָׁע וְאֵין לְךָ פָּסוּל יוֹתֵר מִזֶּה. \u0010c45\u0011 \u0010r48\u0011 \u0005וַאֲפִלּוּ לֹא מְסָרוֹ \u0010c46\u0011 עֲדַיִן, רַק שֶׁאוֹמֵר: אֵלֵךְ וְאֶמְסֹר, אִם אוֹמֵר כָּךְ בְּפַרְהֶסְיָא \u0010c47\u0011 נִפְסָל \u0010t35\u0011 לְעֵדוּת, \u0010r49\u0011 וְלֹא אַמְרִינָן בִּכְהַאי גַוְנָא עָבִיד אִינַשׁ דְּגָזִים וְלֹא עָבִיד (מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006. וְיֵשׁ חוֹלְקִין אֶלָּא אִם כֵּן מֻחְזָק בְּכָךְ \u0005(מָרְדְּכַי שָׁם בְּפ' הַנִּשְׁבָּעִין)\u0006. \u0010r50\u0011 וַאֲפִלּוּ לֹא יוֹדְעִין \u0010c48\u0011 אִם רָגִיל בְּכָךְ אוֹ לֹא, מִכָּל מָקוֹם יוּכַל זֶה שֶׁכְּנֶגְדּוֹ לַעֲמֹד וּלְהַצִיל עַצְמוֹ עַל יְדֵי גוֹיִים, אַף עַל פִּי שֶׁיַּגִּיעַ נֶזֶק לָזֶה \u0005(מַהֲרַ\"ם מֵרִיזְבּוּרְק וּתְשׁוּבַת רַשְׁבָּ\"א סִימָן קפ\"א וְהָרֹא\"שׁ כְּלָל ט\"ז)\u0006. \u0010r51\u0011 אֲבָל הַמּוֹסֵר \u0010y25\u0011 \u0010c49\u0011 שֶׁאֲנָסוּהוּ לְהַרְאוֹת אוֹ לְהָבִיא, \u0010r52\u0011 וְנָתַן \u0010t36\u0011 וְנָשָׂא בְיַד, אַף עַל פִּי שֶׁהוּא חַיָּב לְשַׁלֵּם, אֵינוֹ רָשָׁע, וּבֶן תַּשְׁלוּמִין הוּא בִּלְבַד, \u0010g34\u0011 \u0005(וּמַשְׁבִּיעִין אוֹתוֹ)\u0006 כִּשְׁאָר הַכְּשֵׁרִים. \u0005הַגָּה: וְכֵן אִם \u0010t37\u0011 הוֹדָה שֶׁמָּסַר, וְאֵין עֵדִים בַּדָּבָר, \u0010r53\u0011 אַף עַל פִּי שֶׁאֵינוֹ נִפְסָל בְּהוֹדָאַת עַצְמוֹ, \u0010c50\u0011 \u0010r54\u0011 \u0010r55\u0011 מִכָּל מָקוֹם חַיָּב לְשַׁלֵּם (מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006. \u0010g35\u0011 \u0010r56\u0011\nאָסוּר לִמְסֹר לְיִשְׂרָאֵל בְּיַד גּוֹיִים, בֵּין בְּגוּפוֹ \u0010r57\u0011 בֵין בְּמָמוֹנוֹ; וַאֲפִלּוּ הָיָה רָשָׁע וּבַעַל \u0010y26\u0011 \u0010g36\u0011 עֲבֵרוֹת; וַאֲפִלּוּ הָיָה מֵצֵר לוֹ וּמְצַעֲרוֹ. \u0005הַגָּה: \u0010r58\u0011 וְדַוְקָא בִּדְבָרִים בְּעָלְמָא; אֲבָל אִם מְסָרוֹ, מֻתָּר לְמָסְרוֹ, דְּהֲרֵי יוּכַל לְהָרְגוֹ בַדִּין \u0010c51\u0011 בְּמָקוֹם שֶׁיֵּשׁ חֲשָׁשׁ שֶׁיַּחֲזֹר וְיִמְסְרֶנּוּ (הָרֹא\"שׁ כְּלָל י\"ו סִימָן א' וב' וּתְשׁוּבַת רַשְׁבָּ\"א סִימָן קפ\"א)\u0006 \u0010r59\u0011 ; אוֹ אִם אִי אֶפְשָׁר לְהַצִּיל עַצְמוֹ בְּדֶרֶךְ אַחֵר; \u0010r60\u0011 אֲבָל אִם אֶפְשָׁר לְהַצִּיל עַצְמוֹ בְּדֶרֶךְ אַחֵר, הָוֵי כִּשְׁנַיִם שֶׁמָּסְרוּ זֶה אֶת זֶה וְכָל מִי שֶׁהִפְסִיד חֲבֵרוֹ יוֹתֵר חַיָּב לְשַׁלֵּם הַמּוֹתָר בְּנֶזֶק שָׁלֵם \u0005(מָרְדְּכַי פֶּרֶק הַנַּ\"ל וּתְשׁוּבַת מַיְמוֹנִי הנ\"ל)\u0006. \u0010c52\u0011 \u0010r61\u0011 וְכָל הַמּוֹסֵר יִשְׂרָאֵל בְּיַד גּוֹיִים, בֵּין בְּגוּפוֹ בֵּין בְּמָמוֹנוֹ, אֵין לוֹ חֵלֶק לָעוֹלָם \u0010t38\u0011 הַבָּא. \u0010y27\u0011 \u0010g37\u0011\nמֻתָּר לַהֲרֹג הַמּוֹסֵר אֲפִלּוּ בַּזְּמַן הַזֶּה. \u0010c53\u0011 וּמֻתָּר לְהָרְגוֹ קֹדֶם שֶׁיִּמְסֹר, אֶלָּא כְּשֶׁאָמַר: \u0010t39\u0011 הֲרֵינִי מוֹסֵר פְּלוֹנִי \u0010y28\u0011 בְּגוּפוֹ \u0010r62\u0011 אוֹ בְּמָמוֹנוֹ, אֲפִלּוּ מָמוֹן קַל, \u0010r63\u0011 הִתִּיר עַצְמוֹ לַמִּיתָה, \u0010r64\u0011 וּמַתְרִין בּוֹ וְאוֹמְרִים לוֹ: אַל תִּמְסֹר, אִם הֵעִיז פָּנָיו וְאָמַר: לֹא כִּי אֶלָּא אֶמְסְרֶנּוּ, מִצְוָה לְהָרְגוֹ, וְכָל הַקֹּדֶם לְהָרְגוֹ, זָכָה. \u0005הַגָּה: \u0010r65\u0011 וְאִם אֵין פְּנַאי לְהַתְרוֹת בּוֹ, אֵין צָרִיךְ הַתְרָאָה (הַמַּגִּיד פ\"ח \u0010g38\u0011 דְּחוֹבֵל)\u0006. \u0010r66\u0011 וְיֵשׁ אוֹמְרִים דְּאֵין לַהֲרֹג הַמּוֹסֵר אֶלָּא אִם כֵּן אִי אֶפְשָׁר לְהִנָּצֵל מִמֶּנּוּ בְּאֶחָד מֵאֵבָרָיו, אֲבָל אִם אֶפְשָׁר לְהַצִּיל בְּאֶחָד מֵאֵבָרָיו, כְּגוֹן לַחְתֹּךְ לְשׁוֹנוֹ אוֹ לְסַמּוֹת עֵינָיו, \u0010r67\u0011 אָסוּר לְהָרְגוֹ, דַּהֲרֵי לֹא גָּרַע מִשְּׁאָר רוֹדֵף \u0005(תְּשׁוּבַת מַיְמוֹנִי הַנַּ\"ל וּמָרְדְּכַי הַנַּ\"ל בְּשֵׁם מהר\"מ)\u0006. \u0010c54\u0011 \u0010g39\u0011 \u0010r68\u0011\nעָשָׂה הַמּוֹסֵר אֲשֶׁר זָמַם, וּמָסַר, אָסוּר \u0010c55\u0011 \u0010r69\u0011 לְהָרְגוֹ, אֶלָּא \u0010c56\u0011 \u0010c57\u0011 \u0010g40\u0011 \u0010t40\u0011 אִם כֵּן הֻחְזַק לִמְסֹר, שֶׁהֲרֵי זֶה יֵהָרֵג שֶׁמָּא יִמְסֹר אֲחֵרִים. \u0010c58\u0011 \u0010g41\u0011 \u0010r70\u0011\nכָּל \u0010t41\u0011 הַמּוֹסֵר הַצִּבּוּר וּמְצַעֲרָן, \u0010r71\u0011 מֻתָּר לְמָסְרוֹ בְּיַד גּוֹיִים לְהַכּוֹתוֹ וּלְאָסְרוֹ וּלְקָנְסוֹ; \u0010r72\u0011 אֲבָל \u0010y29\u0011 \u0010c59\u0011 מִפְּנֵי \u0010t42\u0011 צַעַר יָחִיד אָסוּר לְמָסְרוֹ. \u0005הַגָּה: (וְע\"ל סִימָן תכ\"ה ס\"א)\u0006. \u0010r73\u0011 מִי שֶׁעוֹסֵק בְּזִיּוּפִים וְכַדּוֹמֶה, וְיֵשׁ לָחוּשׁ שֶׁיַּזִּיק רַבִּים, \u0010r74\u0011 מַתְרִין בּוֹ שֶׁלֹּא יַעֲשֶׂה, וְאִם אֵינוֹ מַשְׁגִּיחַ, יְכוֹלִין לְמָסְרוֹ וְלוֹמַר שֶׁאֵין אַחֵר מִתְעַסֵּק בּוֹ אֶלָּא זֶה לְבַד. \u0010r75\u0011 מִי שֶׁרוֹצֶה לִבְרֹחַ וְלֹא לְשַׁלֵּם לַגּוֹי מַה שֶּׁחַיָּב, וְאַחֵר גִּלָּה הַדָּבָר, אֵין לוֹ דִּין מוֹסֵר, שֶׁהֲרֵי לֹא הִפְסִידוֹ רַק שֶׁהֻצְרַךְ לְשַׁלֵּם מַה \u0010g42\u0011 \u0010r76\u0011 שֶּׁחַיָּב, מִכָּל מָקוֹם בְּרָעָה עָשָׂה \u0010g43\u0011 דְּהָוֵי כְּמֵשִׁיב \u0010y30\u0011 \u0010c60\u0011 \u0010r77\u0011 אֲבֵדָה לְגוֹי; וְאִם גָּרַם לוֹ \u0010g44\u0011 הֶזֵּק, חַיָּב לְשַׁלֵּם לוֹ מַה שֶּׁגָּרַם לוֹ \u0005(מַהֲרַ\"ם \u0010c61\u0011 \u0010g45\u0011 \u0010r78\u0011 מֵרִיזְבּוּרְק)\u0006.\nאָסוּר לְאַבֵּד \u0010t43\u0011 מָמוֹנוֹ שֶׁל מוֹסֵר אַף עַל פִּי שֶׁמֻּתָּר לְאַבֵּד גּוּפוֹ, \u0010y31\u0011 שֶׁהֲרֵי מָמוֹנוֹ רָאוּי לְיוֹרְשָׁיו. \u0005(וע\"ל סי' ק\"ח ס\"ב)\u0006 \u0010y32\u0011 \u0010c62\u0011 \u0010t44\u0011 \u0010r79\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּמֻתָּר לִטֹּל מָמוֹנוֹ לְעַצְמוֹ, דְּאֵינוֹ אָסוּר אֶלָּא לְאַבְּדוֹ\u0006 \u0005(מָרְדְּכַי פֶּרֶק הַגּוֹזֵל בַּתְרָא)\u0006. \u0010g46\u0011 \u0010r80\u0011\nמוֹסֵר, \u0010y33\u0011 מְקַבְּלִים עֵדוּת שֶׁלֹּא בְפָנָיו. \u0005הַגָּה: \u0010c63\u0011 וְאֵין צְרִיכִין \u0010t45\u0011 לְכַוֵּן הָעֵדוּת כָּל כָּךְ \u0010g47\u0011 (טוּר)\u0006. \u0010g48\u0011 \u0010r81\u0011\nמִי \u0010r82\u0011 שֶׁמֻחְזָק שֶׁשְּׁלֹשָׁה פְעָמִים מָסַר יִשְׂרָאֵל אוֹ מָמוֹנָם בְּיַד גּוֹיִים, הָיוּ מְבַקְּשִׁים עֵצָה וְתַחְבּוּלָה \u0010y34\u0011 לְבַעֲרוֹ מֵהָעוֹלָם, \u0005הַגָּה: \u0010c64\u0011 \u0010r83\u0011 עַל יְדֵי גְרָמָא, \u0010c65\u0011 אַף עַל פִּי שֶׁאָסוּר \u0010g49\u0011 \u0010t46\u0011 לְהָרְגוֹ (בְּיָדַיִם)\u0006. \u0010r84\u0011 מִי שֶׁמְּדַבֵּר בִּפְנֵי קָהָל וְעֵדָה דִבְרֵי מְסִירוּת, וְעַל יְדֵי זֶה נִשְׁמַע לַשַּׂר וְגָרַם הֶזֵּק, אַף עַל פִּי שֶׁאֵין לוֹ דִּין מָסוֹר מִכָּל מָקוֹם מַעֲנִישִׁין אוֹתוֹ לְפִי רְאוֹת עֵינֵי הַדַּיָּנִים \u0005(רִיבָ\"שׁ סִימָן רל\"ט וּתְשׁוּבַת רַמְבַּ\"ן סִימָן ר\"מ)\u0006. \u0010r85\u0011 מִי שֶׁשָּׁלַח שָׁלִיחַ \u0010c66\u0011 לִמְסֹר, אִם הַשָּׁלִיחַ הֻחְזַק לַעֲשׂוֹת, חַיָּב הַמְשַׁלְּחוֹ, וְאֵין לוֹמַר אֵין שָׁלִיחַ לִדְבַר עֲבֵרָה, הוֹאִיל \u0010t47\u0011 וְהֻחְזַק בְּכָךְ. \u0010y35\u0011 \u0010c67\u0011 \u0010c68\u0011 \u0010c69\u0011 \u0010c70\u0011 \u0010c71\u0011 \u0010c72\u0011 \u0010c73\u0011 \u0010c74\u0011 \u0010r86\u0011 וְכֵן אִם מָסַר שְׁטָר פָּרוּעַ לְגוֹי, וְיוֹדֵעַ שֶׁיִּתְּנוֹ לַשַּׂר וְיָכֹף הַיִּשְׂרָאֵל \u0010g50\u0011 לִפְרֹעַ שֵׁנִית, \u0010t48\u0011 חַיָּב לְשַׁלֵּם \u0005(בֵּית יוֹסֵף בְּשֵׁם רשב\"ץ וּמַהֲרַ\"ם מֵרִיזְבּוּרְק)\u0006. \u0010g51\u0011 \u0010r87\u0011\nהוֹצָאוֹת שֶׁעָשׂוּ לְבַעֵר מוֹסֵר, כָּל הַדָּרִים בָּעִיר חַיָּבִים לִפְרֹעַ בָּהֶם, אֲפִלּוּ אוֹתָם שֶׁפּוֹרְעִים מַס בְּמָקוֹם אַחֵר: \u0010g52\u0011",{"g":["א) ל' רמב\"ם בפ\"ז מה' חובל די\"ז וכ' ה\"ה מפורש בסוף הכונס (מימרא דשמואל דף ס\"ב ע\"א)","\u0003ב) שם די\"ח זה מעשה שם ההיא גברא דבטש בכספתא וכו'\u0004 (שם)","ג) שם משתבע ושקיל","ד) פשוט שם בגמרא ממתני' ומודים חכמים לר' יהודה במדליק את הבירה","כתב ה\"ה נ' שרבינו ז\"ל סובר דבעי' בגמ' בעובדא דלעיל דסלקא בתיקו הוא בדבר הידוע שאין דרכו להניחו שם וזה טוען שהניחו שם והלה הזיקו ומשום דסלקא בתיקו פסק הרב שאם תפס אין מוציאין מידו כדרכו בכל תיקו","\u0003ה) וכתב שלשון דגמרא נראה כדברי האחרים דקאמרינן מי מנח אינשי וכו'\u0004 (וכמ\"ש התו' שם) ומ\"מ אם יש עדים שאותו דבר שהוא טוען היה שם אע\"פ שאין דרך להניח שם גובין מן המזיק וכו' נותנים לניזק בלא שבועה אך העלה הרשב\"א ז\"ל בזה שלא כדברי התוספות ע\"כ","ו) שם די\"ט וכתב ה\"ה דין זה יתבאר בפ\"ה מה' שאלה ופקדון בארוכה טעם המחבר והר\"ב המשיג ע\"כ ע\"ש כי קצר הגליון מהכיל","ז) ל' הרמב\"ם רפ\"ח מהלכות חובל ומזיק מבואר בפ\"ק דב\"ק דף ה' ע\"א ובפ\"י דף קיז ע\"א","\u0003ח) כ\"כ ה\"ה פירוש בקרקע אבל במטלטלי כל מידי מקרי מיטב כמ\"ש וכו'\u0004 (וכמ\"ש לעיל בסימן שמ\"ח ולקמן סימן תיט) דאי מוסר לא הוה משלם ממיטב לא הוה מקשינן (שם בפ\"ק לתנינהו בהדי הני דמשלמי ממיטב דכ\"ש היא ממטמא דמדמע דהיזק שאינו ניכר נינהו ומשלמי' ממיטב) כמ\"ש שם","ט) מבואר בגמרא שם בפ\"י מימרא דרבה","פי' שדבר לאנס והראה לו ממון חבירו דבמקום פלוני הם","י) כתב הרב המגיד פי' שאין זה היזק שאינו ניכר שפטרו חכמים את היורש וכמו שכתבתי וכו' (ולעיל סי' שפ\"ה סעיף א') ובגמרא פ' הגוזל בתרא (שם) משמע דדינא הוא במוכס דלא קנסא וכ\"כ רבינו האי והרמב\"ן והרשב\"א ז\"ל","\u0003כ) שם דין ב' מעובדא דרב הונא בר יהודה וכו'\u0004 וכדא\"ל רבא וברייתא שם בפרק י' דף קיז ע\"א","ל) אוקימתא דגמרא בלישנא אחרינא אמתני' שם דף קיז ע\"ב","\u0003מ) שם דף ג' וג' ה\"ה כל אלו הבבו' עד בעלי דינין וכו'\u0004 הם בביאור בהלכות הרב שם בפ' הגוזל בתרא ונחלקו בקצתן המפרשים ז\"ל וראיות ההלכות נכונות ביותר וכן העלה הרשב\"א ז\"ל","וע\"ל סימן ק\"ח ס\"ב","\u0003נ) כן משמע התם בעובדא דההוא גברא דאפקידו גביה כסא דכספא סליקו גנבי עליה וכו'\u0004 שם דף קי\"ז ע\"ב","ס) שם ברמב\"ם דין ג' מעובדא דרב הונא בר יהודה כדאמר ליה רבא וברייתא שם ע\"א","ע) שם ד\"ד ושם בברייתא וכתב ה\"ה בשם הרשב\"א שאם אותו ממון במקום שיד האנס שולטת בו אפילו אינו רואהו כל שיכול לחפש ולמצוא פטור וכו' ועיקר","\u0003פ) מעובדא דההוא דאנסו ואחוי אחמרא דרב מרי וכו'\u0004 וא\"ל דרי ואמטי בהדן כו' לקמיה דרב אשי וכו' שם","ע\"ש שכתב דין זה אאנסוהו להביא והביא כמ\"ש לעיל ולא זכיתי פה לספרו ד\"מ","\u0003צ) שם בפ\"ח מה' חובל ומזיק ד\"ה עובדא דההוא שותא וכו'\u0004 וכדא\"ל רבא לאביי וכו' שם","ק) כ' הריב\"ש בסימן פ' בא' שביזה החכם ונתן החכם העונש לשר העיר דהוי קרוב למסירה הביאו הסמ\"ע בשם ד\"מ וביאר שם כיון שעדיין לא נתברר זכותו מדיני ישראל אם הוא חייב או לא","ר) ע\"ש ששם היה מעשה שתקף בידי עכו\"ם לעצמו מדמהו לנסכא דרבי אבא אין חטפי ודידי חטפי (מבואר בסי' שס\"ד ס\"ד) וביאר שם שאם יש עדים שתקפו ע\"י עכו\"ם לאו כל כמיניה ☜אבל אם אין עדים נאמן במיגו בס' אבי העזרי וכתב עוד שם בפ' המניח ☜אדם שכפר בו חבירו בפקדונו והלך המפקיד ולקח את שלו ע\"י עכו\"ם ומתוך כך העלילו את הנפקד והפסיד הרבה אם אפשר למפקיד להציל את שלו בע\"א חייב כמו היה לו לשמטו ולא שמטו מבואר בסימן שפ\"ג ס\"ב","ש) וכ\"כ מהרי\"ו סי' קי\"א וכ' בשם המרדכי שלהי ב\"ק וכן בתשובת מיימוני ☜על אחד שרצה להכריח חבירו בדין עכו\"ם שיעשה לו דין ישראל וכאשר רצה לתפשו ולא הניח עצמו הכהו עד שהרגו ודן מהר\"מ על התובע כל דין רוצח אע\"פ שלא רצה להכריחו אלא לדין ישראל והביאו הסמ\"ע בשם ד\"מ","ת) שם ד\"ו וכתב ה\"ה פסק כרבי יהושע ב\"ל בירושלמי פ' הגוזל בתרא ופ' בתרא דכתובות דאמר אין אדם נתפס על חבירו אלא בארנון ובגלגולת ופירו' ארנון ארנונא האמור בגמ' בבבלי ופירשו סעוד' וארוחא ומשאת וכו' ואפשר לומר שכיון שהם חוקי המלך וזה פרעם חייב לשלם לו אפילו לקחם המלך מזה שלא כדין ואצ\"ל אם לקחם המלך מזה כדין מחמת חבירו שחבירו חייב לשלם לו כאותן שבפ' הגוזל בתרא (בבא קמא דף קי\"ג ע\"ב) גלגולת אחת מהן כמו שפי' שם רש\"י והראב\"ד ז\"ל דהיינו כרג' דשתא","א) כתב הכ\"מ שנ\"ל שנראה שרמז למ\"ש בהגוזל (שם) וה\"מ באבילא וכרגא דההיא שתא אבל שתא דחליף כיון דאיפייס מלכא חליף","ב) שם ד\"ז בעיא דאמימר שם פ\"ו דף ס\"ב ע\"א ולא אפשיטא וכתב ה\"ה ופירשה הרי\"ף בשיש עדים שמסר והפסידו אלא שלא ידוע כמה ופסק רבי' ז\"ל כדרכו בכל תיקו האמורים בגמ'","פי' דהמוסר אומר שלא בשביל המסירה לבדה פשרת את השר ולא דמי לדלעיל דהכא יש לו עדים שהוצרך לפשר בהך וכך אע\"פ שאינם יודעים אם כולו היה בשביל המסירה","ג) וכ\"כ ה\"ה שם דעת הרמב\"ם ושכן דעת ר\"ת יש חולקין ע\"כ ופ\"כ הטור בשם הסכים הרא\"ש","וביאר שם שאם האחד עני מ\"מ לא יפרע העשיר כי אם החצי","ד) וביאר שם פטור מממון אבל יענש בתעניות ומלקות","פי' שלא מסרו קוסד לזה שום יהודי אחר אלא הוא לבדו אם ראה השר מעצמו המעשה שעשה הנמסר או עכו\"ם אחרים דודאי עכו\"ם אחרים יגידו לשר או להשופט כי שמחים לאיד ישראל פטור המוסר","ה) שם ד\"ח וכ' ה\"ה דבר פשוט כתבו הרב","ו) כן הוא בהרמב\"ם וכן העתיק הטור","ז) שם ד\"ט","ח) וכן כתב הרי\"ף בסוף ב\"ח מהא דשבח מר עוקבא לר\"א בני אדם העומדים עלי ובידי למוסרן וכו' שלח ליה דום לה' והתחולל השכם והערב עליהם לבית המדרש והם כלים מאליהם פ\"ק דגיטין ד\"ז ע\"א","ט) שם ד\"י וכתב ה\"ה למד הרב ז\"ל מההוא מעשה דהגוזל בתרא (דף קי\"ו ע\"א) דבעי אחווי אתיבנא דחבריה וא\"ל רב לא תחוי וכו' קם רב כהנא שמטיה לקיעא וכו'","י) שם מאותו מעשה דרבי שילא בסוף ברכות דף נח ע\"א וכתב ה\"ה ההיא נמי בעי שיתרוהו כדאיתא פ\"א מה' רוצח והוא שיש פנאי ורבי שילא אפשר שהזהירו או שלא היה פנאי:","כ) שם די\"א שכן נ\"ל וכתב כ\"ה ונכון הוא שהרי לא מצינו היתר בגמ' אחר מעשה ועוד נ\"ל כעין ראיה מרודף אחר חבירו להרגו שניתן להצילו בנפשו וכן הרודף אחר הזכר ואחר נערה המאורס' כולן קודם מעשה נהרגים ואחר מעשה אין נהרגים (ומבואר לקמן סימן תכ\"ה)","\u0003ל) מברייתא האפיקורסים והמוסרים מורידין ולא מעלי' פ\"ב דע\"א דף כו\u0004 ע\"ג","מ) שם נלע\"ד שגם זה למד מברייתא הנזכר","נ) כן הוא שם בנמוקים","ס) לפענ\"ד דבריו תמוהין בזה שהרי הוא בעצמו כתב שם אם הפקיד העכו\"ם או הלוה לישראל ומת העכו\"ם והוא מעכב הפקדון או הפרעון ואינו מחזיר ליורשיו כשתובעים ממנו הוא קאי בעון וכמ\"ש בריש סי' שכ\"ט וכמ\"ש שם וא\"כ אינו ענין לאבידת העכו\"ם שהתירה התורה ואפי' באבידה במקום שיש קידוש השם כמחזירה הרי זה משובח כמבואר בסי' רסו וכבר פשט התיקון והמנהג שמנהיגי הקהלה יצ\"ו עומדים על המשמר שלא לעשות שקר ועולה לאומות ומכריזים ונותנים רשות לפרסם ולגלות להם על האנשים אשר לוקחים בהקפה או לוים בהלואה ואין דעתם לשלם והכל מדעת המנהיגים וע' במ\"ש ביור' דעה בסוף סימן של\"ד","\u0003ע) מבואר שם אם הוכרח ליתן יותר ממה שהיה חייב לו:\u0004 ","פ) פלוגתא דרב הונא ורב יהודה שם בהגוזל בתרא דף קי\"ט ע\"א ופסק הרי\"ף וש\"פ כמאן דאסר","צ) תשו' הריב\"ש בסימן רל\"ה בשם ת' הרא\"ש והביא ראיה מעובדא דשמעון בן שטח דתלה פ' נשים באשקלון משנה בפ\"ו דסנהדרין דף מ\"ה מחס\"ד","ק) טור סי\"ב בשם תשובת אביו הרא\"ש כלל יז סי\"א","ר) הריב\"ש בת' בסימן רל\"ט מחס\"ב","ש) כן הוא שם בת' הרא\"ש ושכן כתוב ר\"ח הביאו הטו' והב\"י שם וז\"ל שם סי' ג' כך שמעתי מר\"מ ז\"ל אחר שעשה המוסר מסירה אין להורגו בידים אלא ע\"י מושל כיון שהוא מוחזק במסורות וכ\"כ בסי' א' בשם ר\"ח שאין הורגים אותן בידים אלא מורידים אותן לבור שלא יוכל לעלות משם וימותו מעצמן ומה שאומרי' למושל להרגו היינו כמו הורדה לבור ואינו עושה מעשה ושכן באה בתשובה וכו'","☜ואפי' מסרו בין שאר השטרות ואמר דלא ידע מזה חייב לפי שהטוען לא הייתי יודע פושע והוי תחלתו בפשיעה וסופו באונס וחייב והביאו גם כן הסמ\"ע","ת) הרא\"ש בתשו' כלל ו' סי' כ\"א מחודשים סימן ו'","דיני מסירות בת' להרמב\"ן סי' ר\"מ ותשובת הריב\"ס סי' רל\"ה ומבואר עוד שם שאין רשות לבית דין להוציא המוסר מבית הארותין בערבות בטוחים בסך נורא ובקנסות אם ראו הב\"ד שיש ממש בדברי התובע ושאם יתברר הדבר יהיה העובר חייב מיתה או עונש אחר בגופו וע' עוד בת' הנ\"ל סי' תע\"ג ובתשו' הרא\"ש כלל י\"ז שאם רצו לתפסו שלא בדין והציל עצמו בנפשו של רודף שיפה עשה עוד הביא הב\"י בארוכה כתב הרשב\"א ששלח לחכמי צרפת על מוסר א' שהורו ה\"ר יונה בן אחי אביו של ה\"ר יונה החסיד ז\"ל והרשב\"א למלך שהוא חייב מיתה וצוה המלך להרגו והאריך שם עיין עליו עוד שם תשובה שהשיב לו ר\"מ מרוטנברג שמסרו ממון של ישראל ואחד מהן עני אם חייב העשיר לשלם כל הנזק ע' בהגהות מיימוני פי\"ב מהלכות נזקי ממון ועוד במרדכי פ' הפרה ופ' החובל כמה דיני מוסר ודין אשת איש שמסרה:"],"t":["\u0003יודע. \u0004 משמע דאם המזיק יודע מההיזק ומכחישו אין הניזק נשבע ונוטל ועמ\"ש לקמן סי' תי\"ח סי\"ג ועיין בתשובת רש\"ך ס\"ג סי' פ\"א. ש\"ך:","\u0003והשליכו. \u0004 כת' מהרש\"ל בפרק הכונס סי' ל\"ב וז\"ל וראבי\"ה כת' מי שמפסיד ממון לחבירו בפשיעתו ויש לו עדים שע\"י אבד ממונו כו' שישבע כמה הפסידו ויטול כו' ולא נ\"ל דלא עשו תקנת נגזל אלא כעין נגזל במזיק בידים אבל בפשיעה דאינו מזיק בידים לא ולא עוד אלא אפילו במזיק בידים נ\"ל דלא עשו תקנת נגזל אלא דומיא דנגזל במזיד ובכונה אבל המזיק בידים בשוגג לא עשו תקנה גביה וכן יראה לי מדברי הרמב\"ם שכת' המזיק ממון כו' כיצד לקח כיס חבירו והשליכו כו' עכ\"ל ולי נראה כדברי הראבי\"ה ומזיק בפשיעתו דקאמר היינו מזיק במזיד בפשיעתו ור\"ל דל\"ת דוקא השליכו בידים למים אלא אפילו זרקו לארץ ומכח זריקתו נתגלגל ונפל למים או שדחפו מיד חבירו וממילא נפל למים כה\"ג חייב והיינו דאמרינן בש\"ס דבטש בכספתא כו' משמע דהמעשה היה שלא השליכו בידים לנהרא רק דבטש ביה ומכח דחיפתו שדייה בנהרא ומ\"ש הרמב\"ם והשליכו נמי יש לפרש דבריו כן מיהו בהזיק בשוגג נראה כדברי מהרש\"ל ונראה דאף ראבי\"ה מודה בזה. שם:","\u0003אצלו. \u0004 וכת' מהרש\"ל שם דצריך לברר טענתו מי הפקידו אצלו. שם:","\u0003פשע. \u0004 מלשון זה משמע לכאורה דהטעם הוא משום דלא ה\"ל למזיק לאסוקי אדעתיה שיש שם דברים אלו וכ\"כ בע\"ש להדיא וא\"כ קשה מ\"ש אחר כך אינו נאמן וגם בספר לח\"מ הניח בצ\"ע ונ\"ל דה\"ק אינו נאמן וגם אינו מועיל שבועתו וכן משמע ברמב\"ם שסיים ואין משביעין אותו על כך שאין דרך בני אדם כו' ומ\"ש אחר כך ואם תפס כו' היינו משום דגם זה בכלל האיבעיא דדלמא לא מקרי פשיעה ומהני שבועתו אך מדברי הה\"מ נראה שהבין דהרמב\"ם מודה כשיש עדים דחייב וכן כת' מהרש\"ל להדיא לדעת הרמב\"ם וכ\"נ מדברי הרמ\"א ממ\"ש וי\"א כו' וצ\"ל לדבריהם דה\"ק פשע בעצמו שהרי העולם לא יאמינו לו שעשה כן. שם:","\u0003חמת. \u0004 ומהרש\"ל שם כת' דבכה\"ג פשיטא דאינו נאמן ולא מיבעיא אלא בארגז שמניחים בו כספים וטען שהיה בו מרגליות כמו שפרש\"י ע\"ש. שם:","\u0003תפס. \u0004 אפילו בעדים וי\"ח דתפיסה בעדים לא מהני בספיקא דדינא אבל בלא עדים פשיטא דנאמן וכבר הארכתי בזה בספרי תקפו כהן ע\"ש. שם:","\u0003ידע. \u0004 עמ\"ש בזה בסי' צ' ס\"י ועיין בספר א\"א דף ק\"ד ובתשו' רשד\"ם סי' קמ\"ג. שם:","\u0003ונוטל. \u0004 דבדבר דלא ה\"ל לידע לא אמרינן משאיל\"מ וכבר הארכתי בזה בסי' ע\"ב סי\"ב והעליתי דבכל גוונא הוי משואיל\"מ וא\"כ כאן העיקר כדברי הרמב\"ם והמחבר וכ\"כ רבינו ירוחם נל\"א ח\"ב וכן הסמ\"ג עשין. שם:","\u0003המוסר. \u0004 וה\"ה בקרקע שייך דין מוסר וכדלעיל ס\"ס שע\"א. שם:","\u0003בדין. \u0004 דסביר' ליה דמוסר דמיחייב משום דינא דגרמי דרבנן הוא וכמ\"ש בר\"ס שפ\"ז ולפ\"ז במוסר נשא ונתן ביד גם להי\"א גובין מהיורשים אף שלא עמד בדין פשוט הוא ועמ\"ש בסי' שפ\"ה ס\"ק ג' ע\"ש ועיין בתשובת ר\"מ אלשיך סימן קל\"ד:","\u0003חייה. \u0004 צ\"ע מ\"ש מחבלה באחרים דכת' הטור גם הרמ\"א בס\"ס תכ\"ד גם המחבר כתבו בחבלה בבעלה דצריכה למוכרן בטובת הנאה ולשלם ממנו דמי החבלה ואפשר דבמסירה דלא הזיקה בידים הקילו דשם קנס עליו כו' עכ\"ל הסמ\"ע וכת' הש\"ך ז\"ל ולא ידענא מאי קשיא ליה דודאי גם הכא אם הוא רוצה שתמכור נ\"מ שלה בטובת הנאה מחויבת לעשות כן וכמ\"ש הוא עצמו בסי' תכ\"ד ס\"ט בהג\"ה דגם בהלואה ובשאלה ובכל דבר הדין כן אע\"פ שלא הוזכר שם כן וא\"כ ה\"ה הכא ואדרב' הכא אשמעינן גדולה מזו דהנכסים מיד בחזקת הנמסר רק שהבעל אוכל פירות כו' וחייב לשלם אחר מיתתה כו' ע\"ש וכת' עוד דמהרש\"ל פרק החובל סי' ל' העלה דבין חבלה ובין מסירה בעל לוקח הוי ולא יורש ואינו חייב לשלם לאחר מיתה רק שכייפינן למכור כתובתה בטובת הנאה אם יש מי שיקנה ע\"ש עכ\"ל:","\u0003כיצד. \u0004 אדלעיל קאי במוסר בלא אונס דחייב כיצד הרי כו'. עיין בתשובת מבי\"ט ח\"א בשאלות השניות סי' נ\"ז דף קכ\"ו ובתשו' ן' לב ס\"ב סי' נ\"ד ובתשובת מהר\"מ אלשיך סי' ס\"ו ובתשובת רשד\"ם סי' שמ\"ד ושנ\"ח. ש\"ך:","\u0003להביא. \u0004 היינו בענין שאין בו דינא דמלכותא כמו שכתבתי בסי' שס\"ט ס\"ח וע\"ש. שם:","\u0003חייב. \u0004 באמת כן כת' הטור אבל לא ידעתי מנ\"ל הא ומן הסברא נראה דפטור דיש לומר הייתי סבור שמייסרין אותי להראות להם ממון ואולי האמת כך היה ולא יהא אלא ספק אמאי יתחייב וכן בש\"ס איתא ישראל שאנסוהו עובדי כוכבים והראה ממון חבירו פטור ולא הזכר שאנסוהו להראות ממון ומ\"ש הב\"י שהטור הוציא כן מעובדא דכסא דכספא לא נהיר' דהתם נטל ונתן ביד הוי וכן השיג עליו הב\"ח גם מ\"ש הב\"ח דמהא דאמר בש\"ס אחוי אחוויי כו' הוציא כן אין ראי' משם דמאן לימא לן דהתם אנסוהו ונראה דהטור מיירי כשניכרין הדברים שלא יסרוהו מתחלה בשביל ממון ודו\"ק. שם:","\u0003ממון. \u0004 ובתשובת הרשב\"א סי' תתק\"פ לא משמע כן אלא דבהראה פטור אף באונס ממון וכן מצאתי בספר החינוך להרא\"ה ז\"ל וידוע דמורו של הרא\"ה הי' הרמב\"ן ואם כן הרשב\"א והרמב\"ן והרא\"ה סוברים דאף באונס ממון פטור כשהראה נ\"ל די\"ל קים לי כוותייהו. שם:","\u0003לאחר. \u0004 כת' הסמ\"ע דבנ\"י שם סיים דאם כבר בא הנזק עליו אסור לסלקו ממנו כשגורם בזה היזק לחבירו \u0005(כת' בתשו' רש\"ל סי' י\"ט בראובן שקנה טבעת אחד מן העובד כוכבים בחזקת גנוב ומשכנו באופן זה לשמעון והלך שמעון ומכרו לאדון אחר ואחר כך העלילו עליו באמרם שגנוב הוא ומיד הציל עצמו בנפש חבירו ואמר שקנאו מראובן והוכרח ראובן להמלט על נפשו ונגרש מביתו והונו ופסק דשמעון חייב לשלם לו כל ההיזק שגרם כפי ראות עיני הב\"ד דאף אם יכפור ויאמר שלא הזהירו ראובן בזה שקנאו בחזקת גנוב מכל מקום לא הי' לו למכור משכון של חבירו בלא רשותו ובלא רשות ב\"ד ואפילו אם יטעון שמעון שקנאו מראובן בחזקת גנוב ולא בא לידו בתורת משכון מ\"מ אין להציל עצמו בדמי חבירו מאחר שהעלילה בא עליו ומזליה גרם וגדול' מזו כת' המרדכי שאם העליל האנס על יהודי אחד בעבור חבירו שאין לו לגלותו ואם גלהו יש לו דין מסור אמנם אם באמת מכרו לו ראובן ולא הודיעו שהוא גנוב משמע שם דפטור שמעון דיכול לומר אלו הודעתני שהוא גנוב לא הראיתו אותו בפני העובד כוכבים ע\"ש)\u0006:","\u0003חבירו. \u0004 אבל אם אין לאותו האיש ממון ואנס לזה שיראהו האיש ורצונו לתופסו עד שיפדנו הקהל או קרוביו וזה הנאנס יכול לפטור נפשו ג\"כ מהאנס מיסורים אם יתן להאנס ממון כזה נרא' דאסור לגרום היזק לקהל או ליחידים קרוביו כ\"כ הסמ\"ע ועיין בתשובת רשד\"ם סי' נ\"ה וקל\"ה ור\"ז:","\u0003פטור. \u0004 מדכת' המחבר לשון פטור ולא כת' דמותר להראותו יש לדקדק דלכתחל' לא יראהו אלא שאם הראהו פטור מתשלומין. שם:","\u0003חייב. \u0004 עיין בסמ\"ע שהבי' דברי הראב\"ד שהשיג על דין זה וגם הש\"ך הביאו והסכים לזה והעלה דדוק' אם אנסוהו על ממון סתם או אף שאנסוהו להבי' חייב כשנשא ונתן ביד דזה מקרי מציל עצמו בממון חבירו ודמי לנרדף ששבר הכלים כמ\"ש בסי' ש\"פ ס\"ג משא\"כ אם אנסוהו להבי' ממון פלוני א\"כ האונס הוא מתחל' על אותו פלוני ואין זה נקר' מציל עצמו כו' אלא שמוכרח לעשות כמו שא\"ל האנס ואם לא יעשה כן נמצ' מציל הוא ממון חבירו בנפשו ואין לך דבר שעומד בפני פקוח נפש וע\"ש שמבי' כמה פוסקים גדולי הראשונים שס\"ל כן וסיים וכת' ז\"ל וגם בתשובת רשד\"ם סי' נ\"ה כת' כיון דדבר זה פלוגת' דרבוות' הוא קמאי ובתראי לא מפקינן ממונ' וע\"ש וגם בש\"ג פרק הגוזל בתרא משמע דספיק' דרבוות' היא ע\"ש ולדידי לאו ספיק' היא אלא העיקר כהפוטרין עיין בתשובת הרמ\"א סי' י\"א עכ\"ל:","\u0003ביד. \u0004 ונרא' דאם הי' להם משכון בשותפות על החוב ונתנו להאנס מקרי נתן ביד וכן מוכח בתשובת מהר\"מ שבמרדכי שכת' ואי עביד הכי מדעתיה בלא אונס חייב כמו שורף שטרות כו' אבל באונס פטור ואע\"ג דאמרינן פרק אד\"מ \u0005(דף ל\"ג)\u0006 כיון דא\"ל פטור אתה כמי שנשא כו' הא איתותב עכ\"ל ושם ע\"כ בתר דאיתותב קמתרץ רבינא דהא דזיכה את החייב מיירי כגון שהי' לו בידו משכון ונטלו ממנו דה\"ל נשא ונתן ביד ע\"ש. ש\"ך:","\u0003בצד. \u0004 ראובן לקח חפץ אחד משמעון למכרו לשר ואח\"כ החזירו לשמעון בפני עבד השר ואח\"ז לקח השר החפץ משמעון בחזקה בלא דמים ראובן חייב לשלם לשמעון דה\"ל לחזור בינו לבין עצמו ולא מהני מה שאמר לא כונתי להזיקך עכ\"ל מהר\"ם מירזיבורג הביאו הד\"מ סו\"ס זה. סמ\"ע:","\u0003חולקין. \u0004 ובתשובת מהר\"ם מלובלין סי' כ\"ו הכריע להלכה כדעה ראשונ' ולא נהירא להכריע נגד מהר\"מ ב\"ב דלא הי' בדורו כמותו כדאית' בפסקי מהרא\"י סי' קמ\"ב ועוד דסבר' הראשונ' הוא רק סברת יחיד ר\"א מטולא במרדכי והרי במרדכי פרק המניח משמע דרבוות' פליגי עליה וכ\"כ באגודה שם שכן פסקו הגדולים וכן בד\"מ מסיק כן וגם מהרש\"ל פרק הגוזל בתר' סי' מ\"ט כת' שאין נראה דברי ר\"א מטולא לענין פטור ממון וחליל' להורות כן שיבא כמה חלול השם מזה ע\"ש ועיין בתשו' מהר\"מ מלובלין סי' ק\"כ ובתשובת הרמ\"א סי' פ\"ו ובתשו' מהרי\"ט סוף סי' מ\"ה. ש\"ך:","\u0003שנתפס. \u0004 עיין בתשו' רשד\"ם סי' רי\"ד:","\u0003עדים. \u0004 אבל אם אין עליו עדים ישבע לו היסת שלא מסרו כ\"כ הג\"א ד\"מ סי' צ' סי\"ד ועיין בתשו' רש\"ך ס\"ג סי' פ\"ז ופ\"ח באריכות מדיני מוסר:","\u0003שנאנס. \u0004 באמת כ\"כ הרמב\"ם וכן הוא בע\"ש דאיבעי' דלא איפשט' היא אבל ק\"ל בנאנס ונשא ונתן ביד היכי נימ' דהוא בעיא דלא איפשט' הא לא מיבעי' בש\"ס אלא במוסר למאן דדאין דינ' דגרמי אבל בנאנס ונשא ונתן ביד מזיק בידים ולאו גרמי הוא ופשיט' דלא שייך תקנת נגזל דהא אניס הוא וא\"כ כיון שמכחישו בברי נשבע זה שנאנס ופטור דהא אינו נפסל כיון שנאנס ויכול הוא לישבע כן נ\"ל ברור ודברי הרמב\"ם והמחבר והע\"ש צלע\"ג. ש\"ך:","\u0003כופר. \u0004 כת' הה\"מ ומביאו ב\"י שמדברי הרמב\"ם אלו משמע שסובר כר\"ת הוא היש מי שאומר שיביא המחבר לקמן ואחריו נמשך מהרש\"ל פרק הכונס סי' צ' ואין נ\"ל כן אלא דהרמב\"ם לטעמיה אזיל דס\"ל דכל מ\"מ ועל השאר אומר איני יודע ה\"ל מחויב שבועה ואיל\"מ אף בדבר דלא ה\"ל לידע וכמ\"ש בסי' ע\"ב סי\"ב באריכות לכך הוכרח לכתוב כאן שהמוסר כופר דאילו אומר איני יודע כמה ה\"ל מח\"ש ואיל\"מ וכשנגדו נוטל בלא שבועה כן נ\"ל ברור לדעת הרמב\"ם. שם:","\u0003תפס. \u0004 אפילו בעדים לשון מהרש\"ל פרק הכונס סי' ל' ואם העמיד האנס על ממון חבירו דהוי כמוסר בידים וכל כה\"ג או שמסר לאדם בגופו נשבע שנמסר ונוטל עכ\"ל ולא ירדתי לסוף דעתו אמאי בהעמיד כו' הוי כמוסר בידים ס\"ס לא הוי אלא גרמי כיון שלא נשא ונתן ביד כדמוכח בסוף הגוזל בתרא ע\"ש. שם:","\u0003ברורה. \u0004 ולא באומדנא ועי' ב\"ח. שם:","\u0003בכך וכך. \u0004 ואולי הערים או היה אפשר להתפשר בפחות ועיין בתשו' מהר\"מ מינץ סי' מ\"ד. שם:","\u0003ויטול. \u0004 עיין בש\"ך שהאריך בביאור מחלוקת זה ע\"ש וכת' עוד דבתשובת הרשב\"א סי' תקע\"א כת' גבי אחד שמסר את חבירו לאנסים ואינו יודע כמה הפסידו דאם תפס מטלטלים שלא בעדים אין לו עליו כי אם חרם סתם כל מי שנטל ממונו שלא כדין ע\"כ ונראה דדין זה אמת אפילו למאן דאמר בספיקא דדינא לא מהני תפיסה דאע\"ג דלדידיה אפילו תפס שלא בעדים לא מהני וכמ\"ש בספר תקפו כהן היינו בשאר ספיקי דדינא אבל הכא דמטעם נאמנות אתינן עלה דמספקינן אם יהא נאמן בשבועה ליטול והלכך כיון שתפס שלא בעדים ודאי נאמן מכח מיגו והא דאינו נשבע דהרי אפילו בשכנגדו טוען שמא צריך לישבע כדי ליטול כמ\"ש בסי' ע\"ב סי\"ז ע\"ש צ\"ל דמיירי שרוצה הנמסר להחזיק במטלטלים ואינו חפץ שיפדם המוסר ושיגבה ממנו חובו ובכה\"ג כתבתי שם דא\"צ לישבע ולכן אין עליו רק חרם סתם כן נראה לי עכ\"ל:","\u0003גופו. \u0004 והש\"ך האריך להשיג על דין זה ע\"ש ומסיק וכת' ז\"ל הלכך נראה ברור דבין מסר ממונו או גופו אם לא עשה מעשה בידיו כגון שהוליכו בעצמו לתפיסה ולא עביד אלא דיבורו לא מיחייב אלא משום דינא דגרמי והוא בכלל מה דאיבעיא בש\"ס אי עשו תקנת נגזל במסור למאן דדאין דינא דגרמי ולא הוצרכתי להאריך רק מפני שגדול הדור מהרי\"ל לא פסק כן ונמשכו אחריו מהרש\"ל והרמ\"א ומהר\"מ מלובלין ושאר אחרונים ולע\"ד הוא כשגגה היוצא מלפני השליטים האלו עכ\"ל:","\u0003מסרתני. \u0004 וכ' הרשב\"א בתשובה סי' תקע\"א מוסר שהודה במקצת משלם מה שהודה ואינו משלם השאר ואפילו או' נ' ידענא ונ' לא ידענא לא אמרינן מתוך שאיל\"מ מאחר שלא ה\"ל לידע כמה הזיקו ע\"כ והביאו בד\"מ עכ\"ל הסמ\"ע ובתשובה שם כ' ע\"ז וה\"ל כאותו של שק צרור דירושלמי ע\"כ וס\"ל בההיא דירושלמי כהרא\"ש וסייעתו שהביא הטור בסי' רצ\"ח וכ\"כ הה\"מ ספ\"ה דשאלה בשם הרשב\"א ולפ\"ז למ\"ש המחבר בסי' צ' ס\"י וסי' רצ\"ח ס\"א בשק צרו' הנ\"ל דה\"ל משאיל\"מ אע\"ג דלא ה\"ל לידע א\"כ ה\"ה הכא וגם בב\"ח סי' צ' ס\"ס י\"ד כ' דלא כתשובת רשב\"א הנ\"ל וכן העליתי בסי' ע\"ב סי\"ב דבכל ענין ה\"ל משואיל\"מ אם לא שהתובע מודה שהנתבע אינו יודע ע\"ש ודו\"ק. ש\"ך:","\u0003א'. \u0004 כ\"כ בד\"מ דכן משמע בתשובת מהר\"מ כו' ובאמת המעיין שם יראה דלא משמע מידי ובהג\"א ס\"פ הכונס משמע להדיא דאף שלא היה עד אחד צריך לישבע לפני האנס ונראה דאף הרמ\"א לא קאמר אלא לאפוקי שאין העובדי כוכבים נאמנים בכך לענין שיעש' נקיות זו בפניהן אבל אה\"נ אם הנמסר טוען ברי שמסרו צריך לעשות נקיות זו בפני האנס אף שאין שם עד כלל והך עובדא דר\"ת היה הנמסר טוען ברי ומ\"ש הרמ\"א ע\"פ עד אחד כו' היינו כשאין הנמסר טוען ברי שוב ראיתי בתשובת מהרי\"ל סי' צ' משמע כדברי דאפילו בלא עד יש להשביעו בפני השר וכמ\"ש וע\"ש שם:","\u0003החצי. \u0004 וסיים בתשובת מהר\"מ שם אמנם אם אתם רגילין לפטור המוסר לפי שהיה מוכה ואין אדם נתפס על צערו אז יראה לי ששמעון המוסר השני חייב כל ההיזק אם יש עדים שמסרו שניה' ביחד כר' נתן דכל היכא דליכא לאשתלומי מהאי כו'. שם:","\u0003נפטר. \u0004 ואם יש ספק בדבר אם נפטר ממסיר' הראשונה מספיקא לא מפקינן ממונא והאחרון פטור כן הוא שם בתשו' מהר\"מ. שם:","\u0003לעדות. \u0004 ע\"ל סי' ל\"ד ס\"כ ועיין בספר א\"א דף ע\"ד ע\"א ובתשובת הרמ\"א סי' י\"ב ובתשובת ן' לב ס\"א כלל י\"ד סי' צ\"ז וריש כלל כ' סי' ק\"ו ובתשובת מבי\"ט ח\"א סי' ל\"ח:","\u0003ונשא. \u0004 קאי גם אלהראות וק\"ל. שם:","\u0003הודה. \u0004 ואע\"ג דדינא דגרמי הוי קנסא מ\"מ לא אמרינן מודה בקנס פטור רק גבי קנס דאורייתא דכתיב אשר ירשיעון פרט למרשיע עצמו אבל קנסא דרבנן מיחייב בהודאת עצמו כן הוא בתשובת מהרי\"ל ס\"ס צ' וכן משמע בפוסקים ולא כדמשמע מדברי מהרש\"ל פרק הגוזל בתרא ס\"ס נ' ע\"ש. שם:","\u0003הבא. \u0004 ואמרינן נמי בפ\"ק דר\"ה דהמסורות יורדין לגיהנם ונידונין לדורי דורות וגופן ונשמתן כלה כו' וביו\"ד סי' ב' ס\"ט בהג\"ה נתבאר דיש פוסלין שחיטת מוסר ושם סי' רפ\"א ס\"ג נתבאר דס\"ת שכתבו מוסר פסולה. שם:","\u0003הריני. \u0004 היינו כשניכר שיעשה כן ועיין בתשוב' רשב\"א סי' קפ\"א:","\u0003הוחזק. \u0004 כתב בתשובת רשב\"א שהביא ב\"י מחודש ח' שהשיב לחכמי צרפת שאיזה מוחזק כל שנודע לרבים שהוא כן לא שהוחזק בב\"ד של כ\"ג ושקבלו עדיו בפניו שאם כן אין לך מוחזק בזמן שאין לנו מומחין והרי החכמים מחברי הספרים העידו וכתבו שהמוחזק היו הורגים אותו גם בזמן שלא היו מומחין וכל הנעשה ענוותן ומרחם על אלו נעשה אכזר על דורו ע\"כ. שם:","\u0003המוסר. \u0004 כן הוא בכל ספרי המחבר ובע\"ש וטעות הוא וצ\"ל המיצר וכן הוא בטור ורמב\"ם. שם:","\u0003צער. \u0004 אבל במוסר ליחיד דינו כמוסר לצבור מיהו אפשר דלהרמב\"ם דס\"ל דאם כבר מסר אין הורגין אותו אא\"כ הוחזק במוסר סבירא ליה דאם מוסר לצבור אפילו לא הוחזק מותר למסרו ביד אנסים. שם:","\u0003ממונו. \u0004 ביד אבל ע\"י גרמא או גרמי מותר טור בשם העיטור ומהרי\"ו סי' ק\"ס ולמסור ממונו לאנסים אסור כן כת' מהרש\"ל פרק הגוזל בתרא ס\"ס נ' וע\"ש ונראה דמי שמוחזק למסור ונראה שאין דבריו נשמעין רק מחמת עשרו וכשיעני לא יהיו דבריו נשמעין מותר לאבד ממונו או למוסרו לאנס שהרי במה שמאבדין ממונו מצילין אחרים ובתוס' דמסכתא ע\"א דף כ\"ו ע\"ב נסתפקו אי משיבין אבידתו וכתבו דמסור גרוע ממומר לעבודת כוכבים ובכל מקום שונה מוסר אצל מין ולא אתרבי אצל אבידה ושמא מאן דאית ליה ממון מוסר אסור לאבדו ביד אית ליה נמי דמשיבין אבידתו ומטעמא דיכין רשע וצדיק ילבש עכ\"ל ובהג\"א ס\"פ אלו מציאות כת' דמוסר הוי כמו מומר לעבודת כוכבים להכעיס דאסור להחזיר אבידתו ועיין שם:","\u0003דמותר. \u0004 והרי\"ף וסייעתו בע\"כ לא סבירא להו הכי וגם מהרש\"ל שם פסק דאסור ליטול ממונו לעצמו וכן עיקר וכן משמע להדיא מתשובת רש\"י שבמרדכי פ\"ק דקדושין והביאה ב\"י בסי' רפ\"ג מחודש ב' ע\"ש:","\u0003לכוין. \u0004 כלומר דאע\"ג דדיני נפשות צריכין דרישה וחקירה במוסר לא היו מדקדקין כ\"כ וכן הוא בטור סי\"ג בשם תשובת הרא\"ש וז\"ל ואילו רצו לקבל העדות בפניו ולדרוש ולחקור בדינו לעולם לא יעשה לו דין כי ינצל ע\"י אנסים ויסכן כל ישראל כו'. שם:","\u0003להרגו. \u0004 באמת כ\"כ הטור תשובת הרא\"ש בשם ר\"ח אבל תימא על הרמ\"א שכ\"כ בפשיטות שהרי מדברי המחבר בסי' י\"א מבואר שיש להורגו והוא דעת הרמב\"ם והרשב\"א ושאר פוסקים כמו שכתבתי שם והבאתי ראיות לדבריהם ע\"ש ובסמ\"ע כת' שדעת בעל העיטור מוכח דסבירא ליה כר\"ח ולעד\"נ דהעיטור לא קאי רק אממון ע\"ש. שם:","\u0003והוחזק. \u0004 והש\"ך השיג ע\"ז וכת' דהכי מוכח מדברי כל הפוסקים בכמה דוכתי שסתמו וכתבו אין שליח לד\"ע ולא חלקו בין שהשליח מוחזק בכך או לא וע\"ש:","\u0003חייב. \u0004 ובד\"מ כת' ע\"ז וע\"ל סי' שפ\"ו דין י\"ח בזה ונראה דר\"ל תשובת הרשב\"א שהביא שם וא\"כ יש לתמוה על הרא\"ה שכת' כאן בסתם וגם לענין דינא נ\"ל דברי הרשב\"א עיקר כמ\"ש \u0005(ועמ\"ש בסי' שפ\"ו ס\"ק י\"ד ע\"ש)\u0006. ש\"ך:"],"r":["\u0003המזיק כו'. \u0004 כיצד כו' עבה\"ג ס\"ק ב':","\u0003או לאש. \u0004 עתוס' שם ד\"ה לר\"י כו':","\u0003או שמסרו כו'. \u0004 עמ\"ש בס\"ז:","\u0003שמא עפר כו' והוא כו'. \u0004 ואם ידע המזיק כו' וי\"א כו'. עמ\"ש בסי' צ' ס\"י:","\u0003בנק\"ח. \u0004 עמ\"ש בסימן פט ס\"ב:","\u0003ודרכן כו' אבל כו'. \u0004 שם אי דקא כו' כמש\"ו:","\u0003 (ליקוט) אבל אם אין דרכם כו'. \u0004 הרמב\"ם ל\"ג מי מנחי כו' אלא דקא טעין מרגניתא מאי ובלא עדים ולא משום דאין מחזיקין שהיה שם מרגניתא אלא אפי' היה שם משום דע\"פ הדין אין נשבע ונוטל אלא דעשו תקנת נגזל ומיבעיא להו אם עשו תקנה בכה\"ג ומרגניתא ודאי אין דרך להניח לפי גירסתו כנ\"ל דהתקנה משום תיקון העולם אבל כאן אין דרך העולם והוא פשע וז\"ש הוא פשע כו' (ע\"כ):","\u0003הוא פשע בעצמו. \u0004 נראה שט\"ס הוא וצ\"ל הרי זה ספק וכמ\"ש המ\"מ שדעת הרמב\"ם דוקא בדליכא עדים וכמ\"ש למטה אינו נאמן וז\"ש בהג\"ה וי\"א כו' והוא דעת תוס' שם ד\"ה מי כו' ואין לפרש כו' אבל הרשב\"א פי' כדברי הרמב\"ם וכ' דאם כדברי תוס' מאי קאמר אתא כו' הכי והכי כו' הל\"ל וקא תבע מיניה מאי דהוה בגווה ומספקא ליה הואיל שזה אינו יודע אם שקיל בשבועה ופשיט ממתני' דשקיל בשבועה וא\"ל אי כו':","\u0003ופטור המזיק. \u0004 היינו לשיטת תוס' והכניס בדברי רמב\"ם כדרכו:","\u0003ואם תפס כו' וי\"ח. \u0004 עמ\"ש בליק' א':","\u0003והוא כו'. \u0004 כנ\"ל:","\u0003בין כו'. \u0004 ר\"ל אע\"ג דבגמ' וירושלמי תני עכו\"ם ל\"ד אלא בהוה דהא תנינן שם א\"ל אנס כו' סתמא ובתוספתא ספ\"י גנבים שנכנסו במחתרת ועשו תשובה כולן חייבין להחזיר עשה א' מהן תשובה אין חייב לשלם אלא על חלקו בלבד אם היה מוציא ונותן לפניהם חייב לשלם על הכל:","\u0003מהיפה כו'. \u0004 דפריך שם ה' א' וליתנינהו ושם כולן כאבות כו' ועתוס' קט\"ז ב' ד\"ה ל\"צ כו' וכן אמרינן שם ס\"ב א' ובב\"מ ע\"ז ב' אפ\"ת מעידית דנכסיו כו' וענ\"י שם:","\u0003אע\"פ כו'. \u0004 קט\"ז ב' קי\"ז א' ושם ב':","\u0003אלא הרגיל כו'. \u0004 ר\"ל אפי' בדיבור וכמש\"ש ה' א' בדיבורא כו' וכן מוכר שט\"ח לחבירו ומחלו דיבורא הוא. מרדכי:\n\u0003 (ליקוט) אלא הרגיל כו'. \u0004 כמו בדן את הדין ועסי' כ\"ה ס\"ד ומראה דינר לשולחני ועתוס' דב\"ק ק' א' ד\"ה טיהר כו' (ע\"כ):","\u0003ואם מת כו'. \u0004 כמ\"ש דינא כו' וכ\"כ הרשב\"א דפשיט ליה דדינא הוא:","\u0003וי\"א כו'. \u0004 כדעת ריצב\"א שכ' בסי' שפ\"ו ס\"ג דקנסא הוא ולא קנסינן לבניו כמ\"ש בפ\"ב דמ\"ק ובפ\"ד דגטין ובבכורות ועסי' ס\"ו סל\"ב שסתם כס' ראשונה:","\u0003שעמד בדין. \u0004 דאז ממונא הוא ונתחייב בכך בב\"ד וכמ\"ש בכתובות מ\"ב ועתוס' שם:","\u0003ואשה כו'. \u0004 כמש\"ש אלא א\"ר משמתינן כו':","\u0003ואם יש כו'. \u0004 כ\"מ שם פ\"ט א':","\u0003ואם יש כו' ואם מתה כו' ואין הבעל כו'. \u0004 ר\"ל לא מיבעיא דיכולה למכור בטובת הנאה כמ\"ש בס\"ס תכ\"ד אלא אפי' הנכסים עצמה גובה ואע\"ג דאמרינן שם תנינא לתקנת אושא כו' עתוס' בב\"ב קל\"ט ב' סד\"ה התם עוד מקשינן כו'. וי\"ל כו' וז\"ש ואין הבעל כו' ודלא כתי' השני שם ולרשב\"א כו' אבל הרמב\"ן כ' כתי' הרשב\"א וכ\"כ בס\"ס תכ\"ד וכ\"ד הפוסקים ועש\"ך.","\u0003הבעל אוכל כו'. \u0004 דמ\"ש בב\"ק שם תזבין לנכסי מלוג ל\"ד דהא אמרינן שם ובב\"ב קל\"ו א' והבן א\"י למכור כו' מכר הבן כו' ובב\"ק שם מדמנינן זה לבעל אלא משום תקנת אושא אלא דר\"ל תזבין כה\"ג לאחר מותה וה\"ה בנמסר עצמו כמש\"ש וכ\"ת זבינה ניהליה לההוא דחבלה כו':","\u0003ואם אנסו להראות כו'. \u0004 עתוס' שם ד\"ה ל\"צ וי\"ם דגרס כו' וע\"ל ס\"ס שע\"א:","\u0003אע\"פ שהוא כו'. \u0004 שם ישראל שאנסוהו כו' ואם נטל כו' מ' דאפי' אנסוהו דומיא דרישא דאל\"כ אפי' בהראה חייב כמש\"ש אמר רבא כו' וכן העובדא לקמיה דר\"א באנוס הוה מדקא' ה\"מ היכא דלא כו' וע\"ש ברי\"ף שהאריך והוצרך לזה לאפוקי דעת ר\"ה גאון שפוטר ופי' ואם נטל כו' שהוסיף מעצמו ונטל ונתן שלא אנסוה אלא להראות ולכאורה לפ\"ז אין ראיותיו מכריעות ופי' הרמב\"ן בזה דה\"ק הרי\"ף דליתני ישראל שאנסוהו ונטל ונתן פטור וכ\"ש הראה וע' במלחמות וז\"ש הרי\"ף ל\"ש אנסוה והלך הוא והביא ל\"ש אנסוה להביא והביא ודעת ר\"ח כדעת הגאון והביא ראיה ממ\"ש ב' חזינן אי כו' ואי לא כו' ואע\"ג דנשא ונתן ביד ובירושלמי פ' החובל תני ישראל שאנסוהו עכו\"ם ונטלו ממנו ממון חבירו בפניו פטור נטל הוא ונתן להם חייב א\"ר יוסי הדא דתימא באותן שא\"ל תן לנו ממון סתם אבל אמרו של פלוני אע\"פ שהוציא ונתן להם פטור אלמא באנסוה להביא פטור ודעת ר' אפרים לחלק בין שאנסוה להביא ממון סתם לאמרו ממון של פלוני וכמ\"ש בירושלמי וכן הביא מעשה דכסא דכספא דקאמרינן חזינן כו' ומה שם משום דלא אמיד אמרינן אדעתא כו' כ\"ש היכא דידיעא דעל ממון חבירו אתי וכמש\"ש דלאו מציל עצמו בממון חבירו הוא היכא דאדעתא דכספא אתי דחיוביה דאונס משום דמציל עצמו כו' וכ' הרז\"ה והרשב\"א דראית הרי\"ף מכרחת ממש\"ש א\"ל אנס הושיט כו' וע\"כ באנסוהו דאל\"כ מאי פריך מינה לרב אשי דהא עובדא דר\"א ע\"כ באנסוהו וקא' הושיט דעל ממון חבירו קאתי ועוד הקשה הרז\"ה דא\"כ מאי פריך שם בההוא חמרא והא מציל כו' הא שם מחמת ממון חבירו הוא ומיהו דוקא במקום שא\"י ליטול האנס בעצמו כמש\"ש איתביה ר\"א כו' הב\"ע כו' וכן אם יכול לחפש וליטלו דדוקא בתרי עברי דנהרא חייב ובזה ניחא העובדא דכסא כספא משא\"כ באתו אדעתא דידיה אז לא היו נוטלין מעצמן וכן הירושלמי הנ\"ל ג\"כ כה\"ג כ\"כ הרז\"ה והרשב\"א שם וערא\"ש. ותוס' שם תי' בדרך אחר וע\"ש בד\"ה ואי לא כו' וכ\"כ הרא\"ש וכ\"כ הרמב\"ן במלחמות וכ' שכה\"ג איירי הירושלמי הנ\"ל וכמש\"ש ממון חבירו בפניו כו' ושם אע\"פ שהוציא כו' ר\"ל מביתו של עצמו וכמ\"ש בספ\"ק דגטין א\"ה שפיר עבד. וכ\"ד הרמב\"ם וש\"ע בדעת הרי\"ף וכמ\"ש בס\"ד אע\"פ שהמלך כו':","\u0003שהמציל כו'. \u0004 ר\"ל לא כדעת הראב\"ד שכ' דוקא באונס ממון אבל אונס הגוף פטור והיינו עובדא דכספא דרבה אף שהרשב\"א בתשובה הסכים עמו בחידושיו חלק עליו וכן הקשה הרמב\"ן שם עליו דהא אמרינן שם סי' ב' אפי' במקום סכנת נפשות אסור להציל כו' ואע\"ג שא\"ל דבר שעומד בפני פ\"נ מ\"מ צריך לשלם וכ\"כ תוס' ורא\"ש שם וש\"פ וכמ\"ש בסימן שנ\"ט ס\"ד וכן עובדא דחמרא כו' ואמרינן שם ונרדף ששבר כו' דאסיר כו' וז\"ש בעובדא דכסא דכספא הנ\"ל והא מציל כו' וז\"ש שהמציל כו' וכמ\"ש בס\"ג או ימיתהו ואפ\"ה כ' בנשא ממון כו' בס\"ד דמ\"מ חייב וע' במלחמות שם שהאריך:","\u0003כיצד כו'. \u0004 עכשיו מפרש והולך. הרי כו'. שם קט\"ז ב' קי\"ז ב':","\u0003ואפי' יסרוהו כו' \u0004 שם אמר רבה אם הראה כו' ופי' הרשב\"א דבכה\"ג קאמר דאי במראה מעצמו בלא אונס מאי קמ\"ל מתני' היא כמש\"ש קט\"ז ב' קי\"ז ב' כנ\"ל:","\u0003ולא מקרי כו'. \u0004 דהטעם דבמקום אונס פטור כיון דאינו אלא גרמא בעלמא וחיובו משום קנס כמ\"ש ריצב\"א כה\"ג לא קנסוה אבל באונס ממון אמרינן בפ\"ב דכתובות דהוי רשיעי ועבהג\"מ סימן ך' ובמרדכי שם ואף שהראב\"ד אוקמי לסוגיא שם הכל באונס ממון כבר חלקו עליו כנ\"ל וכ' הרשב\"א דאנסוהו להראות בשלו והראהו בשל חבירו דנתכוין להציל את שלו חייב שלא כהר' אפרים ע\"ש וכ\"כ תוס' וכמש\"ל בהג\"ה ואם אנסו להראות כו' אבל הרא\"ה חולק ע\"ז מדקא' הראהו מעצמו כו' ועש\"ך וי\"ל לדעתו אע\"ג דהוי רשיעי כמ\"ש בכתובות שם אע\"ג דלא הוי רק גרמא מ\"מ פטירי כמ\"ש בגרמא ועתוס' ס' א' ד\"ה ר\"א כו' ובב\"ב שם:","\u0003היה רואה כו'. \u0004 ירושלמי בפ\"ג ראה אמת המים שוטפת ובאה לתוך שדהו עד שלא נכנסו המים לתוך שדהו רשאי לפנותו למקום אחר משנכנסו אין רשאי לפנותו למקום אחר אהן כריסו ארגירא עד דלא ייתי אהן כריסו ארגירא שרי למימר פלן עביד עבידתי פלן עביד עבידתי ר\"ל הגובה דורן למלך קודם שנכנס שרי לאחד לומר פלוני ופלוני עניים הן ועושין מלאכתי ואע\"פ שמתוך כך מכביד על אחרים מן דייתי אהן כריסו ארגירא אסור הדין אכסניא פרכא עד דלא ייתון רומאי שרי משחדוניה ומן דייתון רומאי אסור ועסמ\"ע ועהג\"א דפ\"ק דב\"ב סכ\"ו ד\"ה מכאן. ושוב מצאתי כו' וענ\"י שם:","\u0003שאם לא כו'. \u0004 מ' כמ\"ש בהג\"ה בס\"ב ולא כו':","\u0003לא נשא כו' אע\"פ כו'. \u0004 כנ\"ל ובעה\"ע חולק ודעתו כדעת הר' אפרים ודחה ראיות הרי\"ף וענ\"י:","\u0003ב' שותפין כו'. \u0004 כמ\"ש במוחל שט\"ח כו' דאינו חייב רק משום דינא דגר מי כמ\"ש בפ' הכותב ואע\"ג דבסנה' לג אמרי' כיון דאמר פטור כו' הא נשאר שם בקושיא ואמר רבינא כגון שה\"ל משכון כו' ודוקא באונס כנ\"ל ועסמ\"ע ובלא משכון כנ\"ל:","\u0003דהיינו כו'. \u0004 כ\"כ הרשב\"א מההוא כסא כנ\"ל:","\u0003מ\"מ אין כו'. \u0004 וכ\"כ הר' אפרים דמ\"ש אנסוהו עכו\"ם כו' היינו להראות בשלו והראה בשל חבירו דפטור כיון שלא נתכוין להזיק אלא להציל שלו פטור מדיני דגרמי אבל הרשב\"א חולק עליו וכ' דהא המראה דינר לשלחני אינו מתכוון להזיק ועסי' סו סך\"ג ואין לי לשלם מדינא כו' אבל תוס' חולקים ע\"ז וע\"ש פ\"ו א' ד\"ה זיל כו' ועסי' כ\"ה ס\"א אע\"פ שגרם כו' ושם ס\"ס ד' כדין כל כו' שזה מתכוון כו' ועמ\"ש שם:","\u0003אם תפס כו' וי\"א דבספיקא כו'. \u0004 כשיטתו כמ\"ש בי\"ד סי' שטו וכנ\"ל:","\u0003ואם ידעו כו'. \u0004 דכה\"ג א\"צ לתקנת נגזל והוא דינא דמתני' דפ' הנשבעין שכנגדו נשבע ונוטל ועסמ\"ע:","\u0003ויש מי כו'. \u0004 אבל הרמב\"ם שהוא ס' ראשונה חולק ע\"ז וכמ\"ש בס\"א או שמסרו ליד אנס כו' ואין לחלק בנשא ביד בין אונס או לא כנ\"ל וכ' שם ואם ידע המזיק כו' וכן בהראה וכשיטתו דגרמי מזיק הוא ולכן כ' כאן שהמוסר כופר אבל באומר א\"י א\"צ לישבע כלל וכמ\"ש הר\"י מיג\"ש בשק צרור וכמ\"ש בסי' צ' ס\"י אבל תוס' אזלי לשיטתייהו דבכל מידי דלא ה\"ל לידע א\"א משוילו\"מ וכמ\"ש הראב\"ד וכמ\"ש תוס' ברפ\"ה דב\"ק וש\"מ ועמ\"ש בסי' צ' ס\"י ובסי' פז ס\"ה ועתוס' שם ד\"ה עשו. שר\"י פי' דאף בכה\"ג קמיבעיא לגמ' אם נשבע המוסר דומיא דתקנת נגזל באשו והנה לדעת ריצב\"א דדינא דגרמי מדרבנן א\"כ לא הוי משוילו\"מ אלא בנשא ונתן אלא שהרי\"ף והרמב\"ם לא ס\"ל ס' דריצב\"א כמ\"ש בר\"ס שפח:\n\u0003 (ליקוט) ויש מי כו' \u0004 אבל ר\"י חולק וכ' דגם כה\"ג מיבעיא להו וכ\"כ הרשב\"א בשם הראב\"ד ונ\"י ממש\"ש צ\"ח ב' ואי דליכא סהדי כו' וכ\"ת בשבועה ותי' משום דלא איפשיטא לן כנ\"ל וערשב\"א שם ונ\"י שם (ע\"כ):","\u0003וכ\"ז במוסר כו' וכן אם גרם כו'. \u0004 דרבנן ל\"פ אר\"מ בדיני דגרמי אלא בממון אבל לא בגוף שהרי חובל בחבירו חייבה תורה ליתן שבת וריפוי וכן הדקיה באנדרונא כמ\"ש בפ' החובל ובבהמה פטור משום דגרמא הוא וצריך לחלק בין נזקי גופו לממונו דבגופו הוי כמזיק בידום ולא איבעיא לן במסור אלא בדיני דגרמי כמש\"ש אבל במזיק ממש לא כמ\"ש בההו דבטש בכספתא כו' וכמ\"ש בס\"א וז\"ש דהוי כמזיק בידים:","\u0003וצריך לשלם כו'. \u0004 ר\"ל אף שלא מסר לו כלל את ממונו אלא שהוצרך להוציא לפדות עצמו וכמו ריפוי בחובל כנ\"ל:","\u0003האומר לחבירו כו'. \u0004 דאף בגזל ממש הוא כן וכמ\"ש בסי' ע\"ה ס\"ח וזה שכ' בס\"ז שיש עדים שמסרו כו' וכמ\"ש בפ' הנשבעין בנגזל ועסמ\"ע ס\"ק כ\"ד בשם הרשב\"א והוא תליא בפלוגתא הנ\"ל בש\"ע:","\u0003וי\"א דצריך כו'. \u0004 וכמ\"ש בפ' הנשבעין נשבעין לבע\"ה במעמד כו' ואמרי' בירושלמי שם מפני הבושה ועסי' פז סכ\"ג:","\u0003וא\"צ לעשות כו'. \u0004 ר\"ל אם אין הנמסר יודע בזה ועסי' קעו סל\"ו אבל אף ע\"י התובע בעצמו צריך ג\"כ לישבע בפני השר כנ\"ל ועש\"ך:","\u0003שנים כו'. \u0004 כמו בחמשה שישבו על ספסל כאחד וכמ\"ש בסי' שפא וסי' שפג ס\"ג. והשמיט מ\"ש שם במרדכי אפי' אין לחבירו לשלם אין משלם רק החצי משום דהוא בפלוגתא בסי' ת\"י סל\"ז וסמך אשם:","\u0003ואם בזא\"ז כו'. \u0004 כמ\"ש בפ\"ק בחבילה וספסל אלא דבלאו כו' מאי קא עביד ופטור וכמש\"ש ושם וכן כאן במסירת הראשון ברי היזקא כמש\"ש כתוא מכמר כו' ואמרי' שם ה\"מ היכא דלא אוקמי כו' מיקלי קלייה:","\u0003ואפי' לא מסרו כו'. \u0004 עבה\"ג וכנ\"ל:","\u0003י\"א כו'. \u0004 דהא ר\"ה קץ ידא. מהרמ\"מ ואין זה ראיה דוקא בדיני ישראל אלא דוקא בא\"א להציל בע\"א כמ\"ש שם וכמ\"ש בס\"ט בהג\"ה ועש\"ך:","\u0003אין כו'. \u0004 כמ\"ש בסי' צב ס\"ג וכן הפסול כו' ועסי' לד סכ\"ב ולכן מיבעיא להו אם עשו תקנת נגזל אע\"פ שהמוסר כופר ויכול לישבע לפי' הרי\"ף ורמב\"ם:","\u0003לא כו'. \u0004 עסי' צב ס\"א:","\u0003ואפי' לא כו'. \u0004 דהא רב כהנא הרגו ע\"י שאמר כה\"ג שם:","\u0003ולא אמרי' כו'. \u0004 ר\"ל אף דאמרי' בפ\"ג דב\"ב ובפ' הנשבעין עביד כו' מ\"מ בכה\"ג שהעיז בפרהסיא לא אמרי' ועמ\"ש בס\"י אם העיז פניו כו' ועמש\"ש. וס' האחרונה ס\"ל דודאי אמרי' ועובדא דר\"כ שהיה מוחזק ועסי\"א:","\u0003ואפי' לא יודעין כו'. \u0004 כמ\"ש הבא להורגך השכם להורגו וכעובדא דר' שילא בפ' בתרא דברכות אע\"פ שלא מסרו עדיין ולא הוחזק בכך וכמ\"ש ברודף דניתן להצילו בנפשו אע\"ג דשמא לא יעשה אשר זמם ועמ\"ש בס\"י:","\u0003אבל המוסר כו'. \u0004 דאף לכתחלה מותר ע\"מ לשלם כמ\"ש בסי' שנט ס\"ד ואמרי' בפ' בתרא דיומא קפחיה לרועה:","\u0003ונשא ונתן כו'. \u0004 אבל בהראה ע\"י אונס אצ\"ל דכשר וכמ\"ש בפ\"ב דכתובות לא שנו כו' ועסי' א' ס\"ד בהג\"ה ועס\"ב בהג\"ה:","\u0003אע\"פ שאין כו'. \u0004 כמ\"ש בסי' צב ס\"ה:","\u0003מ\"מ כו'. \u0004 דאף לדעת האומרים דקנסא הוא מ\"מ לא אמרי' מודה בקנס פטור אלא בקנס דאורייתא דכתיב אשר ירשיעון אלקים פרט כו' ואמר ואין עדים דאלו באו עדים אפי' אח\"כ לא הוי מודה בקנס כמ\"ש הרא\"ש בספ\"ק והטור בסי' שמח משום דהאידנא ליכא ב\"ד לקנס וחוץ לב\"ד לאו הודאה הוא כמ\"ש בפ\"ז שאני ר\"ג דלאו כו':","\u0003חייב כו'. \u0004 עסי' א' ס\"ב וסי' כט ס\"ב:","\u0003אסור כו' ואפי' כו'. \u0004 גטין ז' א' אע\"פ שרשע כו':","\u0003בין כו'. \u0004 כמ\"ש כתוא מכמר כו':","\u0003ודוקא כו' דהרי כו'. \u0004 כמ\"ש בס\"י וסי\"א ואע\"ג דקי\"ל ממון מסור אסור לאבדו כמ\"ש בסי\"ג ולא אמרי' שלא יהא ממונו כו' התם בשאין מציל הנמסר עצמו בזה אבל להציל עצמו ודאי מותר דהא מטעם רודף הוא ואמרי' קיז ב' ונרדף כו' שלא יהא ממונו כו' ועתוס' סנה' ע\"ד א' ד\"ה שלא כו':","\u0003או אם כו'. \u0004 או ט\"ס הוא ש\"ך וכ\"ה במרדכי שם דהא הטעם שלא יהא ממונו כו' ואסור להרוג אותו בכה\"ג כמ\"ש בס\"י בהג\"ה ואמרי' ברפ\"ג וקצותה את כפה כו' וילפינן בספרי מזה לרוצח וערמב\"ם פ\"א מה' רוצח:","\u0003אבל אם כו'. \u0004 כמ\"ש בפ\"ג שנים שחבלו זה בזה כו' וכ\"ש במקום שאין חשש שימסרנו שא\"צ להציל ועסי' תכ\"א סי\"ג:","\u0003וכל המוסר כו'. \u0004 פ\"ק דר\"ה:","\u0003או כו'. \u0004 כנ\"ל:","\u0003התיר כו'. \u0004 עסי' ש\"פ ס\"ג:","\u0003ומתרין כו'. \u0004 כמש\"ש א\"ל לא תחוי כו' וכמ\"ש ברודף בסנה' ע\"ב ב' ראה ישראל כו':","\u0003ואם אין כו'. \u0004 כמו בעובדא דר' שילא בפ' בתרא דברכות:","\u0003י\"א כו'. \u0004 דאין הורגין אותו אלא מטעם רודף וכמ\"ש בסי\"א:","\u0003אסור כו'. \u0004 סנה' עד א':","\u0003עשה כו'. \u0004 שהרי אין הריגתו אלא משום להציל חבירו כמו ברודף אבל לא משום רוצח שהרי בגרמא פטור כמש\"ש עו ב' שיסה בו כו' וכן בעדים זוממין הרגו אין נהרגין וכ\"ש בזה\"ז ועריב\"ש סי' רלח:\n\u0003 (ליקוט) עשה המוסר כו'. \u0004 כ' המרדכי מדברי הרי\"ף ל\"נ כן שהוכיח דממון מסור אסור מדאיבעיא להו בס\"פ הכונס אם עשו תקנת כו' ואם איתא הא לאחר מעשה גם גופו אסור ול\"ל שלא יהא ממונו כו' ובלא\"ה אין ראייתו מוכרח די\"ל דמיירי שם שעשה תשובה. שם במרדכי:","\u0003אח\"כ הוחזק כו'. \u0004 כמ\"ש בפ\"ב דע\"ז המינין והמסורות כו' ועס\"ס תכ\"ה:","\u0003כל המוסר כו'. \u0004 ט\"ס הוא וצ\"ל כל המיצר כו' וזה שסיים אבל מפני כו' אבל במוסר אפי' בשביל יחיד מותר כמ\"ש בס\"ט בהג\"ה:","\u0003מותר כו'. \u0004 שהוא כמו מסור כמ\"ש בפ\"ק דר\"ה אבל המינין והמסורות כו' ושנתנו חתיתם כו':","\u0003אבל מפני כו'. \u0004 כמ\"ש בס\"ט:","\u0003מי שעוסק כו'. \u0004 דג\"כ רודף הוא ואף שאין מתכוין כמ\"ש בההיא חמרא בב\"ק שם ובסנה' ע\"ב ב' איתביה כו' יצא ראשו כו' ואף שאינו רק גרמא כמו במסור שאף ע\"י ממון קל כמו תיבנא ואף שאינו רק חששא כמו במסור וכן מחתרת וכיוצא ועסי' תכ\"ה ס\"א בהג\"ה וס\"ב:","\u0003מתרין כו'. \u0004 כמ\"ש בס\"י:","\u0003מי שרוצה כו'. \u0004 עסי' כח ס\"ג בהג\"ה אבל אינו כו' ואם בע\"ד כו':","\u0003מ\"מ ברעה כו'. \u0004 כמ\"ש בב\"ק קיג ב' דהפקעת הלואתו מותר והוי כאבידה כמש\"ש ואמרי' בסנה' עו ב' אר\"י כו' והמחזיר כו' והיינו במקום דליכא חלול השם כמ\"ש בב\"ק שם וכמ\"ש בסי' שמח ס\"ב בהג\"ה:","\u0003ואם כו'. \u0004 עבה\"ג וכמ\"ש בסי' כח שם בהג\"ה אבל אם יש לברר כו':","\u0003אסור כו'. \u0004 עבה\"ג וראיה מדאיבעיא להו ספ\"ו עשו תקנת כו' ואם איתא השתא לאבדו מותר כ\"ש דנשבע ונוטל רי\"ף שם:","\u0003וי\"א כו'. \u0004 ומדברי הרי\"ף לא מ' כן מראיה הנ\"ל עשו תקנת כו' אבל במרדכי שם כ' דשם עשה אשר זמם ואין מוחזק עוד דאסור להורגו לכ\"ע דל\"ל שלא יהא כו' וכן י\"ל בעשה תשובה. וראייתו מדקא' לאבדו כמש\"ו ובזה מתורץ קושית תוס' בע\"ז כו ב' ד\"ה אני. תימא כו'. וע\"ש בתוס' ושמא מאן כו' ועספ\"ג דפסחים ות\"ק כו' והוא כס' ראשונה וכ\"ש לפי' הרי\"ף שם כגון שהיה רץ אחר הזכור או אחר כו' שמותר להצילו כו' ועהג\"א ספ\"ב דב\"מ:","\u0003מוסר כו' וא\"צ כו'. \u0004 עסמ\"ע ועבה\"ג ועסי' ב':","\u0003מי כו'. \u0004 כנ\"ל בפ\"ב דע\"ז:","\u0003ששלשה כו'. \u0004 דאז הוחזק ועבסנהדרין פ\"א ב' במלקיות של כריתות כו' ושם קסבר כו':","\u0003ע\"י גרמא כו'. \u0004 כפי' ר\"ח דוקא מורידין שהיא גרמא אבל אין דעת הרמב\"ם כן כמ\"ש ס\"ס תכ\"ה אם יש בידו כח כו' וכ\"כ הרמב\"ם כאן להדיא ומעשים בכל יום כו' וכ\"כ הרשב\"א ועש\"ך ס\"ק נו:","\u0003מי שמדבר כו'. \u0004 כנ\"ל סי\"ב כל המיצר הצבור כו' וכן משום מיגדר מילתא כמ\"ש בסי' ב':","\u0003מי ששלח כו'. \u0004 ערש\"י דב\"ק נא א' ד\"ה אין שליח כו' משא\"כ כה\"ג שמפורסם שאינו שומע דברי הרב ובב\"מ יו\"ד ב' חמר רבינא היכא כו' וכן לתי' דרב סמא אי בעי עביד כו' ושמא לא יעשה משא\"כ כאן ועתוס' דב\"ק עט א' ד\"ה נתנו וי\"ל כו' ובין כו' אבל כאן יודע הוא כו':","\u0003וכן אם מסר כו'. \u0004 כמ\"ש בסי' כחס\"ג בהג\"ה והרשב\"א חולק ע\"ז והביאו ב\"י בסי' שפו וכשיטת ר\"י משום שאין מתחייב מיד ואינו אלא גרמא כמ\"ש בסי' שפו ול\"נ דהא מראה ממון חבירו הוא ומסור ממש הוא וגם במעיד אינו מתחייב מיד עד שיפסוק הדין וכ\"ש לס' ריצב\"א משום קנס כמו בכל מסור:","\u0003הוצאות כו'. \u0004 עסי' קסג ס\"א בהג\"ה וכמ\"ש בב\"ק קטז ב' בשיירא שעמד עליה גייס כו':"]}],["\u0003הלכות נזקי ממון\u0004\n\u0010y0\u0011 כָּל נֶפֶשׁ חַיָּה שֶׁהִיא בִּרְשׁוּתוֹ שֶׁל אָדָם שֶׁהִזִּיקָה, חַיָּבִים הַבְּעָלִים לְשַׁלֵּם, שֶׁנֶּאֱמַר: וְכִי יִגֹּף שׁוֹר אִישׁ אֶת שׁוֹר רֵעֵהוּ, \u0010y1\u0011 אֶחָד הַשּׁוֹר וְאֶחָד שְׁאָר בְּהֵמָה חַיָּה וָעוֹף, לֹא דִבֵּר הַכָּתוּב בְּשׁוֹר אֶלָּא בַּהֹוֶה.\nוְכַמָּה מְשַׁלֵּם, אִם הִזִּיקָה בַּדְּבָרִים שֶׁדַּרְכָּהּ לַעֲשׂוֹת תָּמִיד כְּמִנְהַג בְּרִיָּתָהּ, כְּגוֹן בְּהֵמָה שֶׁאָכְלָה תֶּבֶן אוֹ עָמִיר, אוֹ שֶׁהִזִּיקָה בְּרַגְלָהּ \u0005(אוֹ)\u0006 בְּדֶרֶךְ הִלּוּכָהּ, חַיָּב לְשַׁלֵּם נֶזֶק שָׁלֵם \u0010y2\u0011 מֵהַיָּפֶה שֶׁבִּנְכָסָיו, שֶׁנֶּאֱמַר: מֵיטַב שָׂדֵהוּ וּמֵיטַב כַּרְמוֹ יְשַׁלֵּם. וְאִם שִׁנְּתָה וְעָשְׂתָה מַעֲשִׂים שֶׁאֵין דַּרְכָּהּ לַעֲשׂוֹת תָּמִיד, וְהִזִּיקָה בָּהֶם, כְּגוֹן שׁוֹר שֶׁנָּגַח אוֹ נָשַׁךְ, חַיָּב לְשַׁלֵּם חֲצִי נֶזֶק מִגּוּף הַמַּזִּיק עַצְמוֹ, שֶׁנֶּאֱמַר: וּמָכְרוּ אֶת הַשּׁוֹר הַחַי \u0010y3\u0011 וְחָצוּ אֶת כַּסְפּוֹ וְגוֹ'.\nכֵּיצַד, שׁוֹר שְׁוֶה מָנֶה שֶׁנָּגַח לְשׁוֹר שְׁוֶה עֶשְׂרִים וְהֵמִיתוֹ, וַהֲרֵי הַנְּבֵלָה שָׁוָה אַרְבָּעָה, בַּעַל הַשּׁוֹר הַמַּזִּיק חַיָּב לְשַׁלֵּם שְׁמֹנָה. וְאֵינוֹ חַיָּב לְשַׁלֵּם אֶלָּא מִגּוּף הַשּׁוֹר שֶׁהִזִּיק, שֶׁנֶּאֱמַר: וּמָכְרוּ אֶת הַשּׁוֹר הַחַי. \u0010y4\u0011\nלְפִיכָךְ, אִם הֵמִית שׁוֹר שְׁוֶה עֶשְׂרִים לְשׁוֹר שְׁוֶה מָאתַיִם, וְהַנְּבֵלָה שָׁוָה מָנֶה, אֵין בַּעַל הַנְּבֵלָה יָכוֹל לוֹמַר לְבַעַל הַחַי: תֵּן לִי חֲמִשִּׁים, אֶלָּא אוֹמֵר לוֹ: הֲרֵי שּׁוֹר שֶׁהִזִּיק לְפָנֶיךָ, קָחֵהוּ וָלֵךְ, אֲפִלּוּ אֵינוֹ שָׁוֶה אֶלָּא דִּינָר; וְכֵן כָּל כַּיּוֹצֵא בָּזֶה.\nהָעוֹשֶׂה מַעֲשֶׂה שֶׁדַּרְכּוֹ לַעֲשׂוֹת תָּמִיד כְּמִנְהַג בְּרִיָּתוֹ, הוּא הַנִּקְרָא מוּעָד. וְהַמְשַׁנֶּה וְעָשָׂה מַעֲשֶׂה שֶׁאֵין דֶּרֶךְ כָּל מִינוֹ לַעֲשׂוֹתוֹ כֵּן תָּמִיד, כְּגוֹן שֶׁנָּגַח אוֹ נָשַׁךְ, הוּא נִקְרָא תָּם. וְזֶה הַמְשַׁנֶּה, אִם הִרְגִּיל בְּשִׁנּוּיוֹ פְּעָמִים רַבּוֹת, נַעֲשָׂה מוּעָד לְאוֹתוֹ דָּבָר שֶׁהִרְגִּיל בּוֹ, שֶׁנֶּאֱמַר: אוֹ נוֹדַע כִּי שׁוֹר נַגָּח הוּא.\nחֲמִשָּׁה מַעֲשִׂים תַּמִּים יֵשׁ בַּבְּהֵמָה, וְאִם הוּעֲדָה לְאֶחָד מֵהֶם, נַעֲשֵׂית מוּעֶדֶת לְאוֹתוֹ מַעֲשֶׂה. וְאֵלוּ הֵם: הַבְּהֵמָה אֵינָהּ מוּעֶדֶת מִתְּחִלָּתָהּ לֹא לִגַּח, וְלֹא לִגֹּף, וְלֹא לִנְשֹׁךְ, וְלֹא לִרְבֹּץ עַל הַכֵּלִים גְּדוֹלִים, וְלֹא \u0010y5\u0011 לִבְעֹט; וְאִם הוּעֲדָה לְאֶחָד מֵהֶם הֲרֵי זוֹ מוּעֶדֶת לוֹ. אֲבָל הַשֵּׁן מוּעֶדֶת מִתְּחִלָּתָהּ לֶאֱכֹל אֶת הָרָאוּי לָהּ, וְהָרֶגֶל מוּעֶדֶת מִתְּחִלָּתָהּ לְשַׁבֵּר בְּדֶרֶךְ הִלּוּכָהּ.\nהַבְּהֵמָה, יֵשׁ מִי שֶׁאוֹמֵר שֶׁהִיא מוּעֶדֶת מִתְּחִלָּתָהּ לִרְבֹּץ עַל פַּכִּים קְטַנִּים וּלְמַעֵךְ אוֹתָם, וְיֵשׁ חוֹלְקִין עָלָיו.\nחֲמִשָּׁה מִינֵי חַיָּה מוּעָדִים מִתְּחִלַת בְּרִיָּתָן לְהַזִּיק, אֲפִלּוּ אִם הֵם בְּנֵי תַרְבּוּת, לְפִיכָךְ, אִם הִזִּיקוּ אוֹ הֵמִיתוּ בִּנְגִיחָה אוֹ בִּנְשִׁיכָה וּדְרִיסָה וְכַיּוֹצֵא בָּהֶם, חַיָּב נֶזֶק שָׁלֵם. וְאֵלוּ הֵם: הַזְּאֵב, וְהָאֲרִי, וְהַדֹּב, וְהַנָּמֵר, וְהַבַּרְדְּלָס; וְכֵן הַנָּחָשׁ שֶׁנָּשַׁךְ, הֲרֵי זֶה מוּעָד וַאֲפִלּוּ הָיָה בֶּן תַּרְבּוּת. \u0005וְיֵשׁ אוֹמְרִים דַּוְקָא נָחָשׁ מוּעָד לְכָל מִינֵי הֶזֵּק, אֲבָל הָאֲחֵרִים אֵינָן מוּעָדִין אֶלָּא מַה שֶּׁדַּרְכָּן בְּכָךְ, \u0010y6\u0011 כְּגוֹן אֲרִי לִדְרֹס וּזְאֵב לִטְרֹף, אֲבָל לֹא אִפְּכָא (טוּר ס\"ג בְּשֵׁם ר\"י וְהָרֹא\"שׁ)\u0006.\nכָּל מוּעָד מְשַׁלֵּם נֶזֶק שָׁלֵם מֵהַיָּפֶה שֶׁבִּנְכָסָיו; וְכָל תָּם מְשַׁלֵּם חֲצִי נֶזֶק מִגּוּפוֹ.\nבַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁנִּכְנְסָה הַבְּהֵמָה לִרְשׁוּת הַנִּזָּק וְהִזִּיקַתְהוּ. אֲבָל אִם נִכְנַס הַנִּזָּק לִרְשׁוּת הַמַּזִּיק וְהִזִּיקַתְהוּ בְּהֶמְתּוֹ שֶׁל בַּעַל הַבַּיִת, הֲרֵי זֶה פָּטוּר עַל הַכֹּל, שֶׁהֲרֵי הוּא אוֹמֵר לוֹ: אִלּוּ לֹא נִכְנַסְתָּ לִרְשׁוּתִי לֹא הִגִּיעַ לְךָ \u0010y7\u0011 הֶזֵּק. וַהֲרֵי מְפֹרָשׁ בַּתּוֹרָה, וְשִׁלַּח אֶת בְּעִירוֹ וּבִעֵר בִּשְׂדֵה אַחֵר. \u0005הַגָּה: כָּל זֶה לְשׁוֹן הָרַמְבַּ\"ם וְצָרִיךְ עִיּוּן, דְּמִקְרָא זֶה בְּשֵׁן וְרֶגֶל הוּא דִכְתִיב \u0010y8\u0011 לְפָטְרָן בִּרְשׁוּת שְׁנֵיהֶם, אֲבָל בִּרְשׁוּת הַמַּזִּיק דְּפָטוּר אֲפִלּוּ בְקֶרֶן אֵין עִנְיָן מִקְרָא זֶה טַעַם אֵלָיו, אֶלָּא דְּפָטוּר מִכֹּחַ דְּאָמַר לֵהּ: אִלּוּ לֹא נִכְנַסְתָּ כו'; \u0010y9\u0011 וְהָא דְּפָטוּר בִּרְשׁוּת הַמַּזִּיק, דַּוְקָא שֶׁנִּכְנָס שֶׁלֹּא בִּרְשׁוּת, אֲבָל נִכְנַס בִּרְשׁוּת, כְּגוֹן פּוֹעֲלִים הַנִּכְנָסִין לִתְבֹּעַ שְׂכָרָן, וּנְגָחָן שׁוֹרוֹ שֶׁל בַּעַל הַבַּיִת, חַיָּב (טוּר ס\"ה בְשֵׁם הָרֹא\"שׁ)\u0006. \u0010y10\u0011\nהִזִּיקָה בִּרְשׁוּת הָרַבִּים אוֹ בְּחָצֵר שֶׁאֵינָה שֶׁל שְׁנֵיהֶם, לֹא לְמַזִּיק וְלֹא לַנִּזָּק, אוֹ בְּחָצֵר שֶׁהִיא שֶׁל שְׁנֵיהֶם וַהֲרֵי הִיא מְיֻחֶדֶת לְהַנִּיחַ בָּהּ פֵּרוֹת וּלְהַכְנִיס לָהּ בְּהֵמָה, כְּגוֹן הַבִּקְעָה וְכַיּוֹצֵא בָּהּ, אוֹ שֶׁהִיא שֶׁל שְׁנֵיהֶם לְהַכְנִיס בָּהּ בְּהֵמָה וְאֵין שׁוּם אֶחָד מֵהֶם רַשַּׁאי לְהַכְנִיס בָּהּ פֵּרוֹת, אִם בְּשֵׁן וְרֶגֶל הִזִּיקָה כְּדַרְכָּהּ, הֲרֵי זֶה פָּטוּר, מִפְּנֵי שֶׁיֵּשׁ לָהּ רְשׁוּת לְהַלֵּךְ בְּכָאן, וְדֶרֶךְ הַבְּהֵמָה לְהַלֵּךְ וְלֶאֱכֹל כְּדַרְכָּהּ וּלְשַׁבֵּר בְּדֶרֶךְ הִלּוּכָהּ. וְאִם נָגְחָה אוֹ נָגְפָה אוֹ רָבְצָה אוֹ בָּעֲטָה אוֹ נָשְׁכָה, אִם תַּמָּה הִיא מְשַׁלֵּם חֲצִי נֶזֶק; וְאִם מוּעֶדֶת, נֶזֶק שָׁלֵם.\nהָיָה הֶחָצֵר שֶׁל שְׁנֵיהֶם מְיֻחֶדֶת לְפֵרוֹת וְלֹא לְהַכְנִיס בָּהּ בְּהֵמָה, וְהִכְנִיס שָׁם אֶחָד מֵהַשֻּׁתָּפִים בְּהֵמָה, וְהִזִּיקָה, חַיָּב אֲפִלּוּ עַל הַשֵּׁן וְעַל הָרֶגֶל.\nוְכֵן אִם הָיְתָה מְיֻחֶדֶת לִבְהֵמָה לִשְׁנֵיהֶם, וְהָיָה רְשׁוּת לְאֶחָד מֵהֶם בִּלְבַד לְהַכְנִיס לָהּ \u0010y11\u0011 פֵּרוֹת, וְהִזִּיקָה פֵרוֹתָיו, חַיָּב אַף עַל הַשֵּׁן וְעַל הָרֶגֶל.\nאִם הוּא שֶׁל אֶחָד מֵהֶם לְפֵרוֹת וְלֹא לִשְׁוָרִים, וְלַשֵּׁנִי לִשְׁוָרִים וְלֹא לְפֵרוֹת, וְהִזִּיקָה בְּהֶמְתּוֹ שֶׁל אוֹתוֹ שֶׁמְּיֻחֶדֶת לוֹ לִשְׁוָרִים וְלֹא \u0010y12\u0011 לְפֵרוֹת לְאוֹתוֹ שֶׁמְּיֻחֶדֶת לוֹ לְפֵרוֹת; בְּשֵׁן וְרֶגֶל \u0010y13\u0011 חַיָּב, דִּלְגַבַּיְהוּ הֲוָה לֵהּ חָצֵר הַנִּזָּק; בְּקֶרֶן פָּטוּר, דִּלְגַבֵּי דִידֵהּ הֲוָה לֵהּ חֲצַר הַמַּזִּיק. וְאִם הִזִּיקָה בְּהֶמְתּוֹ שֶׁל אוֹתוֹ שֶׁמְּיֻחֶדֶת לוֹ לְפֵרוֹת לְאוֹתוֹ שֶׁמְּיֻחֶדֶת לוֹ לִשְׁוָרִים; בְּקֶרֶן חַיָּב, דִּלְגַבֵּי דִידֵהּ הֲוָה לֵהּ חֲצַר הַנִּזָּק; בְּשֵׁן וְרֶגֶל פָּטוּר, דִּלְגַבַּיְהוּ הָוֵי חֲצַר הַמַּזִּיק:\nשֵׁן וְרֶגֶל, אֵין חַיָּבִין אֶלָּא אִם כֵּן הִזִּיקוּ בִּרְשׁוּת הַנִּזָּק; אֲבָל בִּרְשׁוּת הָרַבִּים פְּטוּרִים. וְאֵין צָרִיךְ לוֹמַר בִּרְשׁוּת הַמַּזִּיק. וּמִיהוּ, אִם הִתִּיז אֲבָנִים בִּרְשׁוּת הָרַבִּים וְהָלְכוּ וְהִזִּיקוּ בִּרְשׁוּת \u0010y14\u0011 הַנִּזָּק, אוֹ עֵץ אָרֹךְ, מִקְצָתוֹ בִּרְשׁוּת הָרַבִּים וּמִקְצָתוֹ בִּרְשׁוּת הַנִּזָּק, וְדָרְסָה עָלָיו \u0010y15\u0011 בִּרְשׁוּת הָרַבִּים וְשִׁבְּרָה כֵּלִים בִּרְשׁוּת הַנִּזָּק, חַיָּב.\nרְאוּבֵן שֶׁהִכְנִיס פֵּרוֹתָיו לַחֲצַר שִׁמְעוֹן שֶׁלֹּא בִּרְשׁוּתוֹ, וְנִכְנַס שׁוֹרוֹ שֶׁל לֵוִי שָׁם וַאֲכַלְתָּם, פָּטוּר. \u0005הַגָּה: אֲבָל אִם הִכְנִיס רְאוּבֵן פֵּרוֹתָיו בִּרְשׁוּת, וְנִכְנַס שׁוֹרוֹ שֶׁל לֵוִי שֶׁלֹּא בִרְשׁוּת, \u0010y16\u0011 חַיָּב, דְּהָוֵי כְּחָצֵר שֶׁל שֻׁתָּפִים וְנִכְנַס שָׁם שׁוֹר שֶׁל אֲחֵרִים לְהַזִּיק, דְּחַיָּב (הַגָּהוֹת מַיְמוֹנִי שם)\u0006.\nחָצֵר שֶׁהִיא שֶׁל שְׁנֵיהֶם לִשְׁוָרִים, וְלָאֶחָד מֵהֶם לִשְׁאָר דְּבָרִים, וְהִכְנִיס בָּהּ טַלִּיתוֹ, וַחֲבֵירוֹ שֶׁמְּיֻחֶדֶת לוֹ לִשְׁוָרִים הִכְנִיס בָּהּ שׁוֹרוֹ, וְהִזִּיק הַשּׁוֹר לַטַּלִית וְגַם הַטַּלִּית לַשּׁוֹר, \u0010y17\u0011 אֵין אוֹמְרִים יֵצְאוּ זֶה בְּזֶה, אֶלָּא שָׁמִין הַנִּזָּקִין בְּבֵית דִּין, וְכָל מִי שֶׁהִזִּיק יוֹתֵר, יְשַׁלֵּם:\nג' אָבוֹת נְזִיקִין בְּשׁוֹר: הַקֶּרֶן וְהַשֵּׁן וְהָרֶגֶל. וְנִקְרְאוּ אָבוֹת מִפְּנֵי שֶׁהֵם כְּתוּבִים בַּפָּסוּק; וְלָהֶם תּוֹלָדוֹת, שֶׁכָּל דָּבָר הַדּוֹמֶה לְאֶחָד מִכָּל אֵלּוּ נִקְרָא תּוֹלָדָה וְדִינוֹ כָּמוֹהוּ, חוּץ מִנֶּזֶק צְרוֹרוֹת \u0010y18\u0011 כְּמוֹ שֶׁיִּתְבָּאֵר\nכֵּיצַד, שׁוֹר הָאָמוּר בַּתּוֹרָה הוּא שֶׁנָּגַח בְּקֶרֶן, וְאֵין דַּרְכּוֹ בְּכָךְ אֶלָּא דֶרֶךְ מִקְרֶה, וְאֵין לוֹ הֲנָאָה בְּהֶזֵּקוֹ; וְכָל הַדּוֹמֶה לוֹ דִּינוֹ כְּמוֹתוֹ, כְּגוֹן שֶׁנָּגְפָה בְּגוּפָהּ אוֹ נָשְׁכָה אוֹ בָעֲטָה אוֹ רָבְצָה עַל כֵּלִים וְשִׁבַּרְתָּם; \u0010y19\u0011 וְכֵן אִם אָכְלָה כְּסוּת אוֹ כֵּלִים, דִּינָהּ כְּקֶרֶן וְאֵינוֹ מְשַׁלֵּם אֶלָּא חֲצִי נֶזֶק, בֵּין בִּרְשׁוּת הַנִּזָּק בֵּין בִּרְשׁוּת הָרַבִּים. וְעוֹד יֵשׁ דְּבָרִים שֶׁמָזִּיקָה בְּרַגְלָהּ אוֹ בְפִיהָ וְדִינָם כְּקֶרֶן, וְיִתְבָּאֲרוּ בְּסִימָן ש\"צ.\nפָּרָה שֶׁרָבְצָה בִּרְשׁוּת הָרַבִּים, וְהָלְכָה פָרָה אַחֶרֶת דֶּרֶךְ עָלֶיהָ וּבָעֲטָה בָּהּ, \u0010y20\u0011 אַף עַל פִּי שֶׁזֹּאת שִׁנְּתָה וְרָבְצָה, אֵין לַמְּהַלֶּכֶת לִבְעֹט בָּהּ. אֲבָל אִם הִזִּיקָה דֶרֶךְ הִלּוּכָהּ, פְּטוּרָה:",["\u0003כל נפש חיה שהיא ברשותו של אדם. ודוקא כגון בהמ' שאינ' בר דעת אבל עבד שיש לו דעת אין רבו חייב על נזקיו שאם הי' חייב על נזקו אם יקניטנו רבו ילך ויזיק את רבו בכל יום ב\"כ הטור בסי' שמ\"ט וגם בסי' זה כתבו בקיצור.\u0004","\u0003אחד השור וא' בהמה. \u0004 דילפי' שור שור משבת ועד\"ר שכתבתי בשם ב\"י לימוד אחר אבל זה נ\"ל עיקר:","\u0003מהיפה שבנכסיו. \u0004 כבר נתבאר דאם משלם לו במטלטלין משלם לו המזיק במה שירצה שהרי כתיב ביה כסף ישיב ללמד שנפרע אפי' בסובין וכמ\"ש לקמן בסי' ת\"ג ובסי' תי\"ט בדברי הטור והמחבר אלא שבאם משלם לו קרקעות צריך לשלם בו מהיפה מנכסיו וגם בא לו' שבדברים כאלו שהוא בהן מועד אינו משתלם מגופו של שור המזיק לחוד ושבאם נגנב או נאבד לא יצטרך לשלם לו המזיק מביתו או לא ימלא לו דמי נזקו על דמי השור המזיק וכדין תם אלא צריך לשלם מכיסו וכמו שמבאר והולך ומ\"ה כ' הטור שמשלם מהעלייה וזהו ג\"כ דעת הרי\"ף שכ' שמשלם לו מהעידית ועפ\"ר:","\u0003וחצו את כספו: \u0004 וכתיב בתריה וגם את המת יחצון והתור' איירי בשווין שור שוה עשרים שהזיק שור שוה עשרים והמיתו והנבילה שוה עשרה שכשיחצו ויטלו כל א' חצי החי וחצי המת נמצא שנשתלם זה חצי נזקו דמעיקרא דאף שלא נחסר לו מעיקרא אלא עשרה והוא נוטל מהחי שוה עשרה מ\"מ הרי המזיק נוטל מהנבלה חמשה ואותן חמש' שהוא כדי חצי נזקו דמעיקרא הוא אשר יחסר לו והתשלומין דחצי נזקו יהא בענין זה דחמש' גובה מגוף המזיק וה' השניים המזיק ישלם לו אותו במה שירצה או משורו החי או מהנבילה שזיכה לו התורה מהניזק וזהו בשוים דאיירי בו התורה ומהשווי' נלמד לשאינו שוים וכמ\"ש ואזיל בסעיף שאחר זה (והוא ג\"כ מדברי הרמב\"ם) שכשנגח שור שוה מנה לשור שוה עשרים והנבילה שוה ארבע' כשיחצה הניזק הנבילה עם המזיק וקיבל ממנו שתים והמזיק צריך לחצות עמו שור השוה כ\"כ כמו שהי' שוה שור הניזק דהיינו עשרים ויתן ממנו עשרה לניזק ועל אותן עשר' משלם לו המזיק בדמי חצי נבילתו דהיינו שתי' שהרי על הניזק לטפל בנבילתו כדלקמן ונמצא דלא נשאר על המזיק ליתן לו אלא שמנה וק\"ל:","\u0003לפיכך אם המית כו'. \u0004 פי' לפיכך כיון דאינו משלם המזיק מביתו אלא מדמי שור המזיק לפיכך לפעמים אומר לו קחהו ולך:","\u0003ואם הועד' לאחד מהן \u0004 פי' שהותרו בבעליו לשומרו אחר שעשתה כן ג' פעמים:","\u0003כגון ארי לדרוס כו'. \u0004 לשון הטור בשם ר\"י כגון ארי לדרוס ולאכול או לטרוף ולהניח לפיכך באחד מאלו הוא מועד וחייב עליו ברשות הניזק נ\"ש ופטור בר\"ה כדין רגל אבל אם טרף ואכלו לאו אורחיה הוא וה\"ל כקרן תמה וחייב ח\"נ אפילו ברשות הניזק וזאב ושאר חיות דרכם בטריפה ולזה הן מועדין וכו'. אבל בדריסה לאו אורחייהו וה\"ל כקרן תמה ונחש נמי מועד מתחילתו ודרכו בכל מיני היזקות כו' עכ\"ל וכוונתו מפני שהארי הוא מלך בחיות ולא ישוב מפני כל אין ממתין להבהמה שדורס עד שתמות אלא דורס עליה ברגלו ואוכלה או טרפה ברוגזו לשני חתיכות ומניחה ואינה אוכלה אבל זאב ושאר חיות מפני מורך לבבם אינם אוכלים בעוד טורפם חי ומנענע וזהו זאב טורף ואוכל כ\"כ הרא\"ש ונחש שהמית אע\"פ שאינה נהנית כיון שדרכה בכך ולא בזה רוגזה ה\"ל מועד לכל דבר ועד\"ר:","\u0003והרי מפורש בתורה ושילח את בעירה וביער ובגמ' דרשו \"דושלח היינו היזק רגל ע\"י הליכתו וביער היינו היזק דשן דביערו על ידי אכילתו:\u0004","\u0003לפטרן ברשות שניהן \u0004 דבשדה אחר משמע שדה של אחר והיינו כשהיא מיוחדת להניזק ולא כשהיא של שניהן וכ\"ש כשהזיק בר\"ה שהוא מקום שכל הבהמות הולכין שם ברשות דפטור בעל המזיק מתשלומי שן ורגל דכיון דאורחתא דהבהמה היא לאכול בשן הראוי לאכול ולדרוס ברגל את כל המונח בדרך והניזק היה לו לשמור את הדבר שהיזק מלהניחו בדרך שהכל דשין בו משא\"כ כשהזיק בקרן והדומה לו דלאו אורחיה היא דלא ה\"ל לניזק לשמור מדבר דלאו אורח הבהמות להזיק בו מ\"מ חייב ח\"נ אפי' בר\"ה כמ\"ש המחבר בסעיף שאח\"ז. ונראה לישב תמיהת מור\"ם ז\"ל והוא דגם דעת הרמב\"ם והמחבר שכתבו והרי מפורש בתורה כו' לא אדסמיך ליה קאי אלא באו ליתן טעם אמ\"ש ברישא בד\"א כשנכנס' לרשות הניזק דממעט גם כשנכנס לרשות שניהן דהיינו מהאי קרא וכדי שלא תאמר מנ\"ל דהאי קרא אתא למעט גם כשנכנס לרשות שניהן דלמא לא אתא למעט אלא כשנכנס לרשות המזיק מ\"ה הקדים וכ' דלזה ודאי לא אתא דלרשות המזיק לא צריך קרא דסברא הוא דפטו' שהרי מצי א\"ל אילו לא נכנסת כו' וק\"ל:","\u0003והא דפטו' ברשות המזיק כו' \u0004 ענין בפני עצמו הוא וגם הטו' כתבו אמ\"ש לפני זה דאם הניזק נכנס לרשות המזיק והוזק דפטו' המזיק אם הפועלים נכנסים לרשותו ופעמים חייב ופעמים פטור ע\"ש ומסיק וכתב עליה בשם הרא\"ש דבזמן הזה דאין בעל הבית רגיל להמחות פועליו לחנוני אלא לפורעם במזומנים ואין רגיל לשלם להם בשוק כי אם בביתו ששם יש לו מעות מ\"ה לעולם נקראו נכנסים ברשות וחייב בניזקן ע\"ש:","\u0003הזיקה בר\"ה כו'. \u0004 סעיף זה וסעיף שלאחריו נתבא' ממ\"ש בסעיף שלפני זה ע\"ש:","\u0003והזיקה פירותיו חייב כו'. \u0004 דאף דיש להמזיק רשות להכניס שם שורו מכל מקום כיון שניתן להניזק רשות לבד להכניס שם פירותיו חצר הניזק קרינן ליה לענין היזק פירות ועפ\"ר מ\"ש עוד מזה ומדכתב חייב אף על השן והרגל ר\"ל וכל שכן אם הזיקה בקרן דהא אקרן חייב בכל מקום ועיין מ\"ש בסמוך:","\u0003לאותו שמיוחדת לו לפירות בשן ורגל כו' \u0004 בפריש' ודריש' הוכחתי דכל שהזיק הבהמה להפירות קרי לה שן ורגל על שם המקרא שנא' ושלח את בעירה וביער כו' דמיירי הבהמה הזיק' בשן ורגל וכל שהזיק' בהמה לבהמה קרי לה קרן ע\"ש המקרא שנא' כי יגח שור איש את שור רעהו והשתא אתי שפיר דסתם המחבר וכתב והזיקה בשן ורגל ר\"ל לפירות. בקרן פטור ר\"ל שהזיק בהמה דבעל השוורים לבהמה דבעל הפירות שהכניס' שלא ברשות ומ\"ש אח\"כ שאם הזיק' בהמתו דבעל הפירות לבעל השוורים בקרן ר\"ל לבהמתו דבעל השוורים גם מ\"ש בסוף בשן ורגל פטור ר\"ל ששניהן שינו דבעל הפירות הכניס הבהמה ובעל השוורים הכניס פירות והזיקה הבהמה להפירות פטור ואבהמתו הנזכר לפני זה קאי וקאמ' דאם אותה הבהמה הנזכרת הזיקה לבעל השוורים בשן ורגל פטור. אבל אין לפרש דמ\"ש ברישא בקרן פטור דר\"ל אם הזיק שורו של זה שניתן לו רשות לשוורים לפירותיו של השני בבעיט' או ברביצה דמקרי ג\"כ קרן דפטו' דאם כן קשה מ\"ש מהי' מיוחד לשניהן לשוורים ולא' מהן לשאר דברים והכניס בו טליתו והזיק השור להטלית בדריסתו עליו שכ' הטור והמחב' בסמוך בסי' ז' דחייב בעל השור על היזק הטלית וכתבתי שם דמוכח דל\"ד במיוחד לשניהם לשוורים איירי אלא ה\"ה במיוחד לזה לשוורים ולזה לטלית ע\"ש. וגם בסי\"ג כתב בסופו ז\"ל חייב אף על השן והרגל ור\"ל וכ\"ש על הקרן ש\"מ דאם הזיקה הבהמה לפירות בקרן דחייב מיהו לפי מ\"ש פי' דשן ורגל וקרן גם שם בס\"ס י\"ג יש לפרש דמ\"ש דחייב אף על השן והרגל דר\"ל וכ\"ש אם הזיק' בהמה דקה בקרן דחייב ומשלם דאקרן חייב בכל מקום אפי' ברה\"ר ודוק ועפ\"ר מ\"ש עוד בהוכחות פירוש זה שכתבתי ודו\"ק:","\u0003דלגבייהו ה\"ל חצר הניזק. \u0004 ר\"ל לגבי שן ורגל וטעמו כיון שיש לו רשות להכניס פירותיו ומ\"ש בסיפא דלגבייהו ה\"ל חצר המזיק כ\"כ ג\"כ הטו' ול\"ד קאמ' אלא ר\"ל דל\"ה חצר הניזק כיון שלא הי' מיוחד לו לפירות אלא להמזיק גם מ\"ש הטו' והמחב' לפני זה בחיובו דקרן משום דהוי לגבי דידי' חצר הניזק ל\"ד קאמ' דהא קרן חייב גם בר\"ה ובחצר של שניהן או שאינן של שום א' מהן אם לא בחצ' המזיק וכנ\"ל אלא משום דהאי חצר אינו מיוחד אלא לאחד מהן או למזיק או לניזק מ\"ה כתב האמת וק\"ל ועפ\"ר מ\"ש לכל זה עוד הוכחות וראיות:","\u0003או עץ ארוך כו'. \u0004 כל' זה כתב ג\"כ הטו' ובפרישה כתבתי דאין חיובן שוה דבדרכו על עץ ארוך כו' חייב עליו נזק שלם ובהתיז אבנים בר\"ה אינו חייב אלא ח\"נ דהיינו נזק צרורות וכמ\"ש הטו' והמחב' בסי' שאחר זה:","\u0003ושיברה כלים ברשות הניזק חייב. \u0004 ול\"ד לדרס' ע\"ג כלים ונתגלגל למקום אחר ושבר דקי\"ל דבתר מעיקרא אזלינן דשאני הכא דהנזק נעשה ברשות הניזק והניזק מעולם הי' שם:","\u0003דהוי כחצר של שותפין \u0004 פי' דבעל החצר וזה שנתן לו רשות להכניס הן שותפין בהחצ' ונקרא חצר הניזק לגבי זה שנכנס שם שלא ברשות:","\u0003אין אומרים יצאו זה בזה \u0004 פי' שלא תימא כיון דשניהם שוים בהכנסתם ה\"ל לכל אחד לשמור את שלו שלא יהא ניזק ולא יזקקו ב\"ד להן:","\u0003כמו שיתבאר. \u0004 בסימן שאחר זה:","\u0003וכן אם אכלה כסות כו' דאע\"ג דבשן הוה מועד מעיקרא ה\"מ בדבר שדרכו לאכול ולא כסות וכה\"ג:\u0004","\u0003אע\"פ דזאת שינתה \u0004 פי' וקי\"ל כל המשנה ובא אחר ושינה בו פטור וכמ\"ש בסי' שצ\"ה מ\"מ אין להאחרת רשות לבעוט בה:"],[],"\u0003הלכות נזקי ממון\u0004\n\u0010y0\u0011 \u0010g0\u0011 \u0010r0\u0011 כָּל נֶפֶשׁ חַיָּה \u0010r1\u0011 שֶׁהִיא בִּרְשׁוּתוֹ שֶׁל אָדָם שֶׁהִזִּיקָה, חַיָּבִים הַבְּעָלִים לְשַׁלֵּם, שֶׁנֶּאֱמַר: וְכִי יִגֹּף שׁוֹר אִישׁ אֶת שׁוֹר רֵעֵהוּ, \u0010y1\u0011 \u0010r2\u0011 אֶחָד הַשּׁוֹר וְאֶחָד שְׁאָר בְּהֵמָה חַיָּה וָעוֹף, לֹא דִבֵּר הַכָּתוּב בְּשׁוֹר אֶלָּא \u0010g1\u0011 בַּהֹוֶה.\nוְכַמָּה מְשַׁלֵּם, \u0010r3\u0011 אִם הִזִּיקָה בַּדְּבָרִים שֶׁדַּרְכָּהּ לַעֲשׂוֹת תָּמִיד כְּמִנְהַג \u0010g2\u0011 בְּרִיָּתָהּ, כְּגוֹן בְּהֵמָה שֶׁאָכְלָה תֶּבֶן אוֹ עָמִיר, \u0010g3\u0011 \u0010r4\u0011 אוֹ שֶׁהִזִּיקָה \u0010r5\u0011 בְּרַגְלָהּ \u0005(אוֹ)\u0006 בְּדֶרֶךְ הִלּוּכָהּ, חַיָּב לְשַׁלֵּם נֶזֶק שָׁלֵם \u0010y2\u0011 \u0010g4\u0011 מֵהַיָּפֶה שֶׁבִּנְכָסָיו, שֶׁנֶּאֱמַר: מֵיטַב שָׂדֵהוּ וּמֵיטַב כַּרְמוֹ יְשַׁלֵּם. וְאִם שִׁנְּתָה וְעָשְׂתָה מַעֲשִׂים שֶׁאֵין דַּרְכָּהּ לַעֲשׂוֹת תָּמִיד, וְהִזִּיקָה בָּהֶם, \u0010g5\u0011 כְּגוֹן שׁוֹר שֶׁנָּגַח אוֹ נָשַׁךְ, חַיָּב לְשַׁלֵּם חֲצִי נֶזֶק מִגּוּף הַמַּזִּיק עַצְמוֹ, שֶׁנֶּאֱמַר: וּמָכְרוּ אֶת הַשּׁוֹר הַחַי \u0010y3\u0011 וְחָצוּ אֶת כַּסְפּוֹ וְגוֹ'. \u0010g6\u0011 \u0010r6\u0011\nכֵּיצַד, שׁוֹר שְׁוֶה מָנֶה שֶׁנָּגַח לְשׁוֹר שְׁוֶה עֶשְׂרִים וְהֵמִיתוֹ, וַהֲרֵי הַנְּבֵלָה שָׁוָה אַרְבָּעָה, בַּעַל הַשּׁוֹר הַמַּזִּיק חַיָּב לְשַׁלֵּם שְׁמֹנָה. וְאֵינוֹ חַיָּב לְשַׁלֵּם אֶלָּא מִגּוּף הַשּׁוֹר שֶׁהִזִּיק, שֶׁנֶּאֱמַר: וּמָכְרוּ אֶת הַשּׁוֹר הַחַי. \u0010y4\u0011 \u0010g7\u0011 \u0010r7\u0011\nלְפִיכָךְ, אִם הֵמִית שׁוֹר שְׁוֶה עֶשְׂרִים לְשׁוֹר שְׁוֶה מָאתַיִם, וְהַנְּבֵלָה שָׁוָה מָנֶה, אֵין בַּעַל הַנְּבֵלָה יָכוֹל לוֹמַר לְבַעַל הַחַי: תֵּן לִי חֲמִשִּׁים, אֶלָּא אוֹמֵר לוֹ: \u0010r8\u0011 הֲרֵי שּׁוֹר שֶׁהִזִּיק לְפָנֶיךָ, קָחֵהוּ וָלֵךְ, אֲפִלּוּ אֵינוֹ שָׁוֶה אֶלָּא דִּינָר; וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0010g8\u0011 \u0010r9\u0011\nהָעוֹשֶׂה מַעֲשֶׂה שֶׁדַּרְכּוֹ לַעֲשׂוֹת תָּמִיד כְּמִנְהַג בְּרִיָּתוֹ, הוּא הַנִּקְרָא מוּעָד. וְהַמְשַׁנֶּה וְעָשָׂה מַעֲשֶׂה שֶׁאֵין דֶּרֶךְ כָּל מִינוֹ לַעֲשׂוֹתוֹ כֵּן תָּמִיד, כְּגוֹן שֶׁנָּגַח אוֹ נָשַׁךְ, הוּא נִקְרָא תָּם. וְזֶה הַמְשַׁנֶּה, \u0010r10\u0011 אִם הִרְגִּיל בְּשִׁנּוּיוֹ פְּעָמִים רַבּוֹת, נַעֲשָׂה מוּעָד לְאוֹתוֹ דָּבָר שֶׁהִרְגִּיל בּוֹ, שֶׁנֶּאֱמַר: אוֹ נוֹדַע כִּי שׁוֹר נַגָּח הוּא. \u0010g9\u0011\nחֲמִשָּׁה מַעֲשִׂים תַּמִּים יֵשׁ בַּבְּהֵמָה, וְאִם הוּעֲדָה לְאֶחָד מֵהֶם, נַעֲשֵׂית \u0010g10\u0011 \u0010r11\u0011 מוּעֶדֶת לְאוֹתוֹ מַעֲשֶׂה. \u0010g11\u0011 וְאֵלוּ הֵם: הַבְּהֵמָה אֵינָהּ מוּעֶדֶת מִתְּחִלָּתָהּ לֹא לִגַּח, וְלֹא לִגֹּף, וְלֹא לִנְשֹׁךְ, וְלֹא לִרְבֹּץ עַל הַכֵּלִים \u0010g12\u0011 גְּדוֹלִים, וְלֹא \u0010y5\u0011 לִבְעֹט; וְאִם הוּעֲדָה לְאֶחָד מֵהֶם הֲרֵי זוֹ מוּעֶדֶת לוֹ. \u0010g13\u0011 אֲבָל הַשֵּׁן מוּעֶדֶת מִתְּחִלָּתָהּ לֶאֱכֹל אֶת הָרָאוּי לָהּ, \u0010g14\u0011 וְהָרֶגֶל מוּעֶדֶת מִתְּחִלָּתָהּ לְשַׁבֵּר בְּדֶרֶךְ \u0010r12\u0011 הִלּוּכָהּ.\nהַבְּהֵמָה, \u0010g15\u0011 יֵשׁ מִי שֶׁאוֹמֵר שֶׁהִיא מוּעֶדֶת מִתְּחִלָּתָהּ לִרְבֹּץ עַל פַּכִּים קְטַנִּים וּלְמַעֵךְ אוֹתָם, \u0010g16\u0011 \u0010r13\u0011 וְיֵשׁ חוֹלְקִין עָלָיו. \u0010g17\u0011\nחֲמִשָּׁה מִינֵי חַיָּה מוּעָדִים מִתְּחִלַת בְּרִיָּתָן לְהַזִּיק, \u0010r14\u0011 אֲפִלּוּ אִם הֵם בְּנֵי תַרְבּוּת, לְפִיכָךְ, אִם הִזִּיקוּ אוֹ הֵמִיתוּ \u0010r15\u0011 בִּנְגִיחָה אוֹ בִּנְשִׁיכָה וּדְרִיסָה וְכַיּוֹצֵא בָּהֶם, חַיָּב נֶזֶק שָׁלֵם. וְאֵלוּ הֵם: הַזְּאֵב, וְהָאֲרִי, וְהַדֹּב, וְהַנָּמֵר, \u0010g18\u0011 וְהַבַּרְדְּלָס; וְכֵן הַנָּחָשׁ שֶׁנָּשַׁךְ, הֲרֵי זֶה מוּעָד \u0010r16\u0011 וַאֲפִלּוּ הָיָה בֶּן תַּרְבּוּת. \u0010r17\u0011 \u0005וְיֵשׁ אוֹמְרִים דַּוְקָא נָחָשׁ מוּעָד לְכָל מִינֵי הֶזֵּק, אֲבָל הָאֲחֵרִים אֵינָן מוּעָדִין אֶלָּא מַה שֶּׁדַּרְכָּן בְּכָךְ, \u0010y6\u0011 כְּגוֹן אֲרִי \u0010r18\u0011 \u0010r19\u0011 לִדְרֹס וּזְאֵב לִטְרֹף, אֲבָל לֹא אִפְּכָא (טוּר ס\"ג בְּשֵׁם ר\"י וְהָרֹא\"שׁ)\u0006. \u0010g19\u0011 \u0010r20\u0011\nכָּל מוּעָד מְשַׁלֵּם נֶזֶק שָׁלֵם מֵהַיָּפֶה שֶׁבִּנְכָסָיו; וְכָל תָּם מְשַׁלֵּם חֲצִי נֶזֶק מִגּוּפוֹ.\nבַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁנִּכְנְסָה הַבְּהֵמָה לִרְשׁוּת הַנִּזָּק וְהִזִּיקַתְהוּ. \u0010g20\u0011 אֲבָל אִם נִכְנַס הַנִּזָּק לִרְשׁוּת הַמַּזִּיק וְהִזִּיקַתְהוּ בְּהֶמְתּוֹ שֶׁל \u0010r21\u0011 בַּעַל הַבַּיִת, הֲרֵי זֶה פָּטוּר עַל הַכֹּל, שֶׁהֲרֵי הוּא אוֹמֵר לוֹ: אִלּוּ לֹא נִכְנַסְתָּ לִרְשׁוּתִי לֹא הִגִּיעַ לְךָ \u0010y7\u0011 הֶזֵּק. וַהֲרֵי מְפֹרָשׁ בַּתּוֹרָה, וְשִׁלַּח אֶת בְּעִירוֹ וּבִעֵר בִּשְׂדֵה אַחֵר. \u0005הַגָּה: כָּל זֶה לְשׁוֹן הָרַמְבַּ\"ם \u0010r22\u0011 וְצָרִיךְ עִיּוּן, דְּמִקְרָא זֶה בְּשֵׁן וְרֶגֶל הוּא דִכְתִיב \u0010y8\u0011 לְפָטְרָן בִּרְשׁוּת \u0010g21\u0011 שְׁנֵיהֶם, אֲבָל בִּרְשׁוּת הַמַּזִּיק דְּפָטוּר אֲפִלּוּ בְקֶרֶן אֵין עִנְיָן מִקְרָא זֶה טַעַם אֵלָיו, אֶלָּא דְּפָטוּר מִכֹּחַ דְּאָמַר לֵהּ: אִלּוּ לֹא נִכְנַסְתָּ כו'; \u0010y9\u0011 \u0010r23\u0011 וְהָא דְּפָטוּר בִּרְשׁוּת הַמַּזִּיק, דַּוְקָא שֶׁנִּכְנָס שֶׁלֹּא בִּרְשׁוּת, אֲבָל נִכְנַס בִּרְשׁוּת, כְּגוֹן פּוֹעֲלִים הַנִּכְנָסִין לִתְבֹּעַ שְׂכָרָן, וּנְגָחָן שׁוֹרוֹ שֶׁל בַּעַל הַבַּיִת, חַיָּב (טוּר ס\"ה בְשֵׁם \u0010g22\u0011 הָרֹא\"שׁ)\u0006. \u0010y10\u0011 \u0010g23\u0011\nהִזִּיקָה בִּרְשׁוּת הָרַבִּים \u0010g24\u0011 אוֹ בְּחָצֵר שֶׁאֵינָה שֶׁל שְׁנֵיהֶם, לֹא לְמַזִּיק וְלֹא לַנִּזָּק, אוֹ בְּחָצֵר שֶׁהִיא שֶׁל שְׁנֵיהֶם \u0010g25\u0011 \u0010r24\u0011 וַהֲרֵי הִיא מְיֻחֶדֶת לְהַנִּיחַ בָּהּ פֵּרוֹת וּלְהַכְנִיס לָהּ בְּהֵמָה, כְּגוֹן הַבִּקְעָה וְכַיּוֹצֵא בָּהּ, \u0010g26\u0011 \u0010r25\u0011 אוֹ שֶׁהִיא שֶׁל שְׁנֵיהֶם לְהַכְנִיס בָּהּ בְּהֵמָה וְאֵין שׁוּם אֶחָד מֵהֶם רַשַּׁאי לְהַכְנִיס בָּהּ \u0010g27\u0011 פֵּרוֹת, אִם בְּשֵׁן וְרֶגֶל הִזִּיקָה כְּדַרְכָּהּ, הֲרֵי זֶה פָּטוּר, \u0010r26\u0011 מִפְּנֵי שֶׁיֵּשׁ לָהּ רְשׁוּת \u0010g28\u0011 לְהַלֵּךְ בְּכָאן, וְדֶרֶךְ הַבְּהֵמָה לְהַלֵּךְ וְלֶאֱכֹל כְּדַרְכָּהּ וּלְשַׁבֵּר בְּדֶרֶךְ הִלּוּכָהּ. \u0010g29\u0011 וְאִם נָגְחָה אוֹ נָגְפָה אוֹ רָבְצָה אוֹ בָּעֲטָה אוֹ נָשְׁכָה, אִם תַּמָּה הִיא מְשַׁלֵּם חֲצִי נֶזֶק; וְאִם מוּעֶדֶת, נֶזֶק שָׁלֵם. \u0010g30\u0011 \u0010r27\u0011\nהָיָה הֶחָצֵר שֶׁל שְׁנֵיהֶם מְיֻחֶדֶת לְפֵרוֹת וְלֹא לְהַכְנִיס בָּהּ בְּהֵמָה, וְהִכְנִיס שָׁם אֶחָד מֵהַשֻּׁתָּפִים בְּהֵמָה, וְהִזִּיקָה, חַיָּב אֲפִלּוּ עַל הַשֵּׁן וְעַל הָרֶגֶל. \u0010g31\u0011 \u0010r28\u0011\nוְכֵן אִם הָיְתָה מְיֻחֶדֶת לִבְהֵמָה לִשְׁנֵיהֶם, וְהָיָה רְשׁוּת לְאֶחָד מֵהֶם בִּלְבַד לְהַכְנִיס לָהּ \u0010y11\u0011 פֵּרוֹת, וְהִזִּיקָה פֵרוֹתָיו, חַיָּב אַף עַל הַשֵּׁן וְעַל הָרֶגֶל. \u0010g32\u0011 \u0010r29\u0011\nאִם הוּא שֶׁל אֶחָד מֵהֶם לְפֵרוֹת וְלֹא לִשְׁוָרִים, וְלַשֵּׁנִי לִשְׁוָרִים וְלֹא לְפֵרוֹת, וְהִזִּיקָה בְּהֶמְתּוֹ שֶׁל אוֹתוֹ שֶׁמְּיֻחֶדֶת לוֹ לִשְׁוָרִים וְלֹא \u0010y12\u0011 לְפֵרוֹת לְאוֹתוֹ שֶׁמְּיֻחֶדֶת לוֹ לְפֵרוֹת; בְּשֵׁן \u0010t0\u0011 וְרֶגֶל \u0010y13\u0011 \u0010g33\u0011 \u0010r30\u0011 חַיָּב, דִּלְגַבַּיְהוּ הֲוָה לֵהּ חָצֵר הַנִּזָּק; בְּקֶרֶן פָּטוּר, דִּלְגַבֵּי דִידֵהּ הֲוָה לֵהּ חֲצַר הַמַּזִּיק. וְאִם הִזִּיקָה בְּהֶמְתּוֹ שֶׁל אוֹתוֹ שֶׁמְּיֻחֶדֶת לוֹ \u0010g34\u0011 לְפֵרוֹת לְאוֹתוֹ שֶׁמְּיֻחֶדֶת לוֹ \u0010g35\u0011 \u0010r31\u0011 לִשְׁוָרִים; בְּקֶרֶן חַיָּב, דִּלְגַבֵּי דִידֵהּ הֲוָה לֵהּ חֲצַר הַנִּזָּק; בְּשֵׁן וְרֶגֶל פָּטוּר, דִּלְגַבַּיְהוּ הָוֵי חֲצַר הַמַּזִּיק: \u0010g36\u0011\nשֵׁן וְרֶגֶל, אֵין חַיָּבִין אֶלָּא אִם כֵּן הִזִּיקוּ בִּרְשׁוּת הַנִּזָּק; אֲבָל בִּרְשׁוּת הָרַבִּים פְּטוּרִים. \u0010g37\u0011 \u0010r32\u0011 וְאֵין צָרִיךְ לוֹמַר בִּרְשׁוּת הַמַּזִּיק. \u0010g38\u0011 וּמִיהוּ, אִם הִתִּיז אֲבָנִים בִּרְשׁוּת הָרַבִּים וְהָלְכוּ וְהִזִּיקוּ בִּרְשׁוּת \u0010y14\u0011 \u0010g39\u0011 \u0010r33\u0011 הַנִּזָּק, אוֹ \u0010t1\u0011 עֵץ אָרֹךְ, מִקְצָתוֹ בִּרְשׁוּת הָרַבִּים וּמִקְצָתוֹ בִּרְשׁוּת הַנִּזָּק, וְדָרְסָה עָלָיו \u0010y15\u0011 בִּרְשׁוּת הָרַבִּים וְשִׁבְּרָה כֵּלִים בִּרְשׁוּת \u0010g40\u0011 \u0010t2\u0011 הַנִּזָּק, חַיָּב.\nרְאוּבֵן שֶׁהִכְנִיס פֵּרוֹתָיו לַחֲצַר שִׁמְעוֹן שֶׁלֹּא בִּרְשׁוּתוֹ, וְנִכְנַס שׁוֹרוֹ שֶׁל לֵוִי שָׁם וַאֲכַלְתָּם, פָּטוּר. \u0005הַגָּה: \u0010g41\u0011 אֲבָל אִם הִכְנִיס רְאוּבֵן פֵּרוֹתָיו בִּרְשׁוּת, וְנִכְנַס שׁוֹרוֹ שֶׁל לֵוִי שֶׁלֹּא בִרְשׁוּת, \u0010y16\u0011 \u0010r34\u0011 חַיָּב, דְּהָוֵי \u0010g42\u0011 כְּחָצֵר שֶׁל \u0010t3\u0011 שֻׁתָּפִים וְנִכְנַס שָׁם שׁוֹר שֶׁל אֲחֵרִים לְהַזִּיק, דְּחַיָּב (הַגָּהוֹת מַיְמוֹנִי שם)\u0006. \u0010g43\u0011 \u0010r35\u0011\nחָצֵר שֶׁהִיא שֶׁל שְׁנֵיהֶם לִשְׁוָרִים, וְלָאֶחָד מֵהֶם לִשְׁאָר דְּבָרִים, וְהִכְנִיס בָּהּ טַלִּיתוֹ, וַחֲבֵירוֹ שֶׁמְּיֻחֶדֶת לוֹ לִשְׁוָרִים הִכְנִיס בָּהּ שׁוֹרוֹ, וְהִזִּיק הַשּׁוֹר לַטַּלִית וְגַם הַטַּלִּית לַשּׁוֹר, \u0010y17\u0011 אֵין אוֹמְרִים \u0010t4\u0011 יֵצְאוּ זֶה בְּזֶה, אֶלָּא שָׁמִין הַנִּזָּקִין בְּבֵית דִּין, וְכָל מִי שֶׁהִזִּיק יוֹתֵר, יְשַׁלֵּם: \u0010g44\u0011\nג' אָבוֹת נְזִיקִין בְּשׁוֹר: הַקֶּרֶן וְהַשֵּׁן וְהָרֶגֶל. \u0010g45\u0011 \u0010r36\u0011 וְנִקְרְאוּ אָבוֹת מִפְּנֵי שֶׁהֵם כְּתוּבִים בַּפָּסוּק; \u0010g46\u0011 וְלָהֶם תּוֹלָדוֹת, שֶׁכָּל דָּבָר הַדּוֹמֶה לְאֶחָד מִכָּל אֵלּוּ נִקְרָא תּוֹלָדָה וְדִינוֹ כָּמוֹהוּ, חוּץ מִנֶּזֶק צְרוֹרוֹת \u0010y18\u0011 \u0010g47\u0011 כְּמוֹ שֶׁיִּתְבָּאֵר \u0010g48\u0011\nכֵּיצַד, שׁוֹר הָאָמוּר בַּתּוֹרָה הוּא שֶׁנָּגַח בְּקֶרֶן, \u0010r37\u0011 וְאֵין דַּרְכּוֹ בְּכָךְ אֶלָּא דֶרֶךְ מִקְרֶה, וְאֵין לוֹ הֲנָאָה בְּהֶזֵּקוֹ; וְכָל הַדּוֹמֶה לוֹ דִּינוֹ כְּמוֹתוֹ, כְּגוֹן שֶׁנָּגְפָה בְּגוּפָהּ אוֹ נָשְׁכָה אוֹ בָעֲטָה \u0010g49\u0011 אוֹ רָבְצָה עַל כֵּלִים וְשִׁבַּרְתָּם; \u0010y19\u0011 \u0010g50\u0011 וְכֵן אִם אָכְלָה כְּסוּת אוֹ כֵּלִים, דִּינָהּ כְּקֶרֶן וְאֵינוֹ מְשַׁלֵּם אֶלָּא \u0010t5\u0011 חֲצִי נֶזֶק, \u0010r38\u0011 בֵּין בִּרְשׁוּת הַנִּזָּק בֵּין בִּרְשׁוּת הָרַבִּים. וְעוֹד יֵשׁ דְּבָרִים שֶׁמָזִּיקָה בְּרַגְלָהּ אוֹ בְפִיהָ וְדִינָם כְּקֶרֶן, וְיִתְבָּאֲרוּ בְּסִימָן ש\"צ. \u0010g51\u0011\nפָּרָה שֶׁרָבְצָה בִּרְשׁוּת הָרַבִּים, וְהָלְכָה פָרָה אַחֶרֶת דֶּרֶךְ עָלֶיהָ וּבָעֲטָה בָּהּ, \u0010y20\u0011 אַף עַל פִּי שֶׁזֹּאת \u0010t6\u0011 שִׁנְּתָה וְרָבְצָה, אֵין לַמְּהַלֶּכֶת לִבְעֹט בָּהּ. אֲבָל אִם הִזִּיקָה דֶרֶךְ הִלּוּכָהּ, פְּטוּרָה:",{"g":["א) ל' הרמב\"ם ריש פ\"א מה' נזקי ממון וכתב ה\"ה זה מבואר במשנה פ\"ק דב\"ק (דף ט\"ו ע\"ב) שמונה זאב וארי ובפ\"ב דף כ\"א ע\"ב) משנה גמרא","ב) שם דין ב' משנה שם בפ\"ק (דף טז ע\"ב) מה בין תם למועד","ג) ומבואר בגמ' (רפ\"ב דף י\"ט ע\"א) באורחי' ולאו אורחיה","ד) שם ב\"ק דף ג' ע\"א ומשנה שם דפ\"ב דף יז ע\"א","ה) שם דף ה ע\"א מימרא דרב אבהו וכולן כאבו' לשלם ממיטב וכ' ה\"ה פי' בעידית כמ\"ש הנזקין מן העידית ור\"ל מן הקרקע כמ\"ש בפ\"ח ולקמן סימן תי\"ט","ו) שם דף ב' ע\"ב ומשנה שם דף ט\"ו ע\"ב","ז) שם דף ג' ממשנה וגמ' שם בפ\"ג דף ל\"ד ע\"ב","ח) שם ושם בגמרא ע\"ב","ט) שם ד\"ד משנה שם דף ט\"ו ע\"ב","י) שם דף ה' ושם במשנה ונתבאר בגמ' שם דף ט' ע\"ב","ר\"ל אבל לא לאחר שאם הועד' ליגח לא הועדה לישך וכן הוא בגמ' אם הועדו חמשתן (שם דף טז ע\"ב)","כ) שם במשנה","ל) שם בפ\"א מנזקי ממון ד\"ה חילוק דין כלים גדולים מבואר במ\"ש בסעיף ז' ע\"ש","מ) משנה שם דף יט ע\"ב","נ) משנה שם דף י\"ז ע\"א","ס) רמב\"ם שם וכתב ה\"ה מימרא דר\"א בפ\"ק דף ט\"ז ע\"א ויש שם לשונות חלוקים פסק הר\"ב ז\"ל כלשון אחרון ועיקר ותמה שאינה בהלכות וכתב הכ\"מ רבינו וה\"ה היו גורסין לשון ראשון דספרים דידן ללשון אחרון ומ\"ש ה\"ה ותימה שאינה בהלכות אפשר שהיו גורסים בספרים דידן דבלשון אחרון לא מפליג בין קטנים לגדולים ע\"כ בספרים שלפנינו הוא לישנא דסתמא דגמרא כלישנא בתרא שם:","ע) טור ס\"ז בשם הרי\"ף ואביו הרא\"ש ומבואר במ\"ש","פ) ל הרמב\"ם ד\"ו וכתב ה\"ה משנה שם (דף טו ע\"ב) כת\"ק והנחש גם כן מפורש במשנה וכל אלו אם עשו מעשה שן ורגל דינן כדין שן ורגל ואם עשו מעשה קרן והן ה' מעשים הנזכרים למעלה דינן כדין קרן לענין חילוק הרשיות כמבואר בסמוך (ולקמן סימן ש\"ץ ושצ\"א) אלא שהן מועדין מתחלתן","פי' אילטיס בל\"א","צ) שם ד\"ז ומבואר במ\"ש לעיל ס\"ב","ק) שם משנה וגמרא דף י\"ג ע\"ב","פי' כגון בחצר של שניהם או בר\"ה וה\"ה בחצר שאינה של שניהם כמ\"ש בסעיף הסמוך ולפענ\"ד לא עלה על דעת הרמב\"ם להביא ראיה לפטור כשנכנס לרשות המזיק אלא הוא ענין בפ\"ע והקדמה לדין הסמוך לו היזיקא בר\"ה וכו' שהוא פטור משום שמפורש בתורה וביער בשדה אחר וגומר","ר) מסוגיא דגמ' שם פ\"ג דף ל\"ג ע\"א כיון דבזמן זה פשוט שנכנסין הפועלים לבית בע\"ה וגם אין מצוי לאדם מעות בכיסו בשוק ועל כן השמיט הרי\"ף הברייתא:","ש) שם ד\"ח משנה שם בפ\"ב דף י\"ט ע\"ב","ת) כתב ה\"ה מבואר כדאמרינן בסוגיא (שם) דף י\"ד ע\"א מאי לא לזה ולא לזה אלא לאחד הא בעי' ובער בשדה אחר וליכא וזה פשוט:","א) מחלוקת אמוראים שם (דף יג ע\"ב) ופסק כפסק ההלכות","ב) טור ס\"ח וכ' הב\"י פשוט שאם אחד מהן הכניס בה פירות ה\"נ חצר המזיק ופטור","ג) לשון הרמב\"ם שם","ד) כ' ה\"ה נתכוון הרב שאם באה בהמת אחרים שאינה מאחד מהשותפין והזיקה שם בשן ורגל הרי הן כאלו הזיקה בחצר הניזק לגמרי דלגבי אחרים ברשות הניזק הוא וזה מבואר ר\"פ הפרה (סוף דף מו ע\"א) וכתבו רמ\"א בסעיף ט\"ז","ה) כברייתא דר\"ש בן אלעזר שם דף יד ע\"א","ו) שם דף ט' היינו כאוקימתא דרב יוסף דאמר בחצר השותפין חייב שם","ז) שם היינו מאי דאמר רבינא משמיה דרבא שם","ח) טור ס\"ו","ט) נלמד מההיא דרבינא שכתב עליה הרא\"ש אע\"פ ששור המזיק נכנס שם ברשות קרינן ביה חצר הניזק כיון דמיוחדת רק לאחד לפירות","י) פשוט הוא כיון דמיוחדת לשוורים לו ולא לחבירו","כ) מבואר במ\"ש","\u0003ל) שם משנה שם בפ' ב' דף י\"ט ע\"ב:\u0004 ","מ) שהרי קרן שחייב ברה\"ר פטור ברשות המזיק (ומבואר בסעיף א') שן ורגל שפטורין ברשות הרבים כל שכן שפטורין ברשות המזיק","נ) מסקנת הגמרא שם בפרק ב' דף י\"ט ע\"ב","\u0003ס) כן כתב הרא\"ש שם בפסקיו בשם התוספת:\u0004 ","\u0003ע) טור שם בסעיף הנזכר היינו דתני ר' יהודה בר סימון בנזקין דבי קרנא וכו'\u0004 כדמפ' שם טעמא ריש דף מ\"ח דה\"ל שן בר\"ה","\u0003פ) שם בהא דתני רב יהודה וכו'\u0004 משום דהוי כחצר הניזק:","צ) מבואר במ\"ש לעיל סי\"א בשם הרב המגיד","ק) גם זה טור שם כפירוש הרא\"ש שם בפסקיו אברייתא פרה שהזיקה טלית וטלית שהזיקה פרה וכו' שם דף יד ע\"ב","\u0003ר) ל' הרמב\"ם שם דין י' ברייתא שם דף ב' ע\"ב:\u0004 ","ש) לשון הטור סעיף ז' ושם בברייתא","\u0003ת) מבואר שם בד' ג' ע\"א וע\"ב:\u0004 ","א) בסימן ש\"ץ","ב) שם ומבואר שם דף ב' ע\"ב","ג) ומבואר שם במשנה דף טו ע\"ב וגמרא דף טז ע\"א וכדעת אביו הרא\"ש שאינו מחלק בין כלים קטנים לגדולים דמשמע ליה משנה וברייתא כצורתן וכפשטן וכלישנא בתרא דר\"א ושלכן השמיטו הרי\"ף ועיין בסעיף ז' ובמה שכתבתי שם","ד) שם משנה שם בפ' ב' דף יט ע\"ב","\u0003ה) שם ס\"ח מסקנת הגמרא בפרק ג' דף ל\"ד ע\"א.\u0004 "],"t":["\u0003ורגל. \u0004 ר\"ל דכל שהזיקה הבהמה להפירות קרי לה שן ורגל על שם המקרא ושלח את בעירה וגו'. וכל שהזיקה בהמה לבהמה קרי לה קרן ע\"ש הכתוב כי יגח שור איש את שור רעהו והשתא א\"ש דסתם המחבר וכתב והזיקה בשן ורגל ר\"ל לפירות ובקרן פטור ר\"ל שהזיקה בהמה דבעל השוורים לבהמת בעל הפירות שהכניסם שלא ברשות ומ\"ש בסוף בשן ורגל פטור ר\"ל ששניהן שינו דבעל הפירות הכניס בהמה ובעל השוורים הכניס פירות והזיקה הבהמה להפירות כו'. סמ\"ע:","\u0003ארוך. \u0004 ומש\"ה אין חיובן שוה דבדרכה על עץ ארוך כו' חייב עליו נ\"ש ובהתיז אבנים בר\"ה אינו חייב אלא ח\"נ דהיינו נזק צרורות וכמ\"ש הטור והמחבר בסי' שאח\"ז. שם:","\u0003חייב. \u0004 ול\"ד לדרסה ע\"ג כלים ונתגלגל למקום אחר ושבר דקי\"ל דבתר מעיקרא אזלינן שאני הכא דהנזק נעשה ברשות הניזק והניזק מעולם שם היה. שם:","\u0003שותפין. \u0004 פירוש דבעל החצר וזה שנתן לו רשות להכניס הן שותפין בהחצר ונקרא חצר הניזק לגבי זה שנכנס שם שלא ברשות. שם:","\u0003יצאו. \u0004 פירוש דל\"ת כיון דשניהם שוין בהכנסתן ה\"ל לכל אחד לשמור את שלו שלא יהא ניזוק ולא יזדקקו ב\"ד להן. שם:","\u0003חצי. \u0004 ואע\"ג דבשן הוי מועד מתחלתו ה\"מ בדבר שדרכו לאכול ולא כסות וכה\"ג. שם:","\u0003שינתה. \u0004 פירוש וקיי\"ל כל המשנה ובא אחר ושינה בו פטור וכמ\"ש בסי' שצ\"ה מ\"מ אין רשות להאחרת לבעוט בה. שם:"],"r":["\u0003כל כו'. \u0004 רפ\"ב במתני' וגמ' ועתוס' שם יז ב' ד\"ה קמ\"ל כו' ועבה\"ג וכן שם יט ב' וש\"מ:","\u0003 (ליקוט) שהיא ברשותו כו'. \u0004 מתני' ריש ב\"ק ושמירתו עליך ושם ט' ב' כל שחבתי כו' (ע\"כ):","\u0003 (ליקוט) א' השור כו'. \u0004 תוספתא פ\"ו א' שור וחמור וא' שאר בהמה חיה ועוף לנזקין מועד משלם נ\"ש ותם משלם ח\"נ א' שור כו' להרבעה כו' (ע\"כ):","\u0003אם הזיקה כו'. \u0004 שם:","\u0003או שהזיקה כו'. \u0004 מתני' בפ\"א וברפ\"ב:","\u0003ברגלה דרך כו'. \u0004 כצ\"ל כמ\"ש ברפ\"ב וכאן לא נחית לפרושי התולדות:","\u0003כיצד כו'. \u0004 ל\"ד ב' א\"ל רב אחא בר תחליפא כו':","\u0003לפיכך כו'. \u0004 מתני' ל\"ה ב' א' גדול כו':","\u0003 (ליקוט) הרי השור כו'. \u0004 כולו כמש\"ש ל\"ג א' שור שוה כו' (ע\"כ):","\u0003 (ליקוט) העושה כו'. \u0004 ספ\"א ורפ\"ב יז יח יט כ כא (ע\"כ):","\u0003אם הרגיל כו'. \u0004 גמ' שם טז א' ואם הועדו כו' וכמ\"ש בס\"ו ושם ב' דאייעד כו':","\u0003 (ליקוט) לאותו מעשה. \u0004 עבה\"ג ופשוט הוא דהא אמרינן מ\"ה ב' א\"ר מועד לקרן כו' וערש\"י שם ד\"ה אליבא דמאן כלומר כו' וכ\"ש כה\"ג (ע\"כ):","\u0003הבהמה יש כו'. \u0004 כלישנא בתרא שם ועוד דלי' קמא נמי ס\"ל כן ומסייעא מברייתא ולא דחיא ליה אלא בדלמא. רשב\"א ומ\"מ ודברי כ\"מ תמוהים וכבר השיגו בלח\"מ וכ\"פ הג\"א בשם א\"ז:","\u0003ויש כו'. \u0004 כיון דלישנא לא חידש אלא בלשון הוי חד עם לי' קמא ולישנא מציעא הוי לישנא בתרא ועוד דמתני' וברייתא סתמא קתני ולא חילקו. הרא\"ש וכ\"ז דחוק מאד:\n\u0003 (ליקוט) וי\"ח עליו. \u0004 ממש\"ש כ\"ד ב' כל המשנה כו' איתמר משמיה דר\"ל כוותך אלמא נקרא רבוצה בר\"ה על הארץ משנה וכ\"ש על כלים אפי' קטנים. נ\"י בשם הרמ\"ה שם (ע\"כ):","\u0003אפי' אם כו'. \u0004 דלא כר\"א:","\u0003 (ליקוט) בנגיחה או כו'. \u0004 ז\"ש הזאב כו' הרי כו' וערש\"י שם ד\"ה הרי כו' (ע\"כ):","\u0003ואפי' כו'. \u0004 בזה אפי' ר\"א מודה כמש\"ש:","\u0003וי\"א דוקא כו'. \u0004 ט\"ז ב':\n\u0003 (ליקוט) וי\"א כו'. \u0004 עתוס' ט\"ז א' ד\"ה והנחש כו' (ע\"כ):","\u0003לדרוס. \u0004 ולאכול ולטרוף להניח. שם וברא\"ש:","\u0003וזאב כו'. \u0004 כמ\"ש בב\"מ צג ב' בא זאב וטרף ארי ודרס ועתוס' ד\"ה והנחש כו' וכ\"פ הרשב\"א וכ' הרא\"ש דכל חיה דינה כזאב דדוקא ארי שהוא מלך כו'. והרמב\"ם פ' דלא כשמואל משום דאקשינן עליה טובא וכולהו שינויי דחיקי נינהו וכן הרי\"ף השמיט וז\"ש חמשה כו' בנגיחה כו' וכיוצא כו':","\u0003 (ליקוט) כל כו' וכל כו'. \u0004 כמש\"ש י\"ח א' דלא אשכחן כו' דלא אשכחן כו' (ע\"כ):","\u0003פטור על הכל. \u0004 ברייתא יד א':","\u0003וצ\"ע כו'. \u0004 וכה\"ג פריך בגמ' כ\"א ב' ועבה\"ג:","\u0003והא כו'. \u0004 עבה\"ג והוי כשכיח בבית:","\u0003וה\"ה מיוחדת כו'. \u0004 כאוקימתא דגמ' להני ברייתות:","\u0003או שהיא כו'. \u0004 מדאיצטריך לדחוקי לא לזה כו' אלא דחד לפירות להוציאו ממשמעות ול\"ק לא לזה ולא לזה כלל לפירות:","\u0003מפני כו'. \u0004 קאי אדסמיך לה ברמב\"ם שהיא של שניהם ולא כמו שדחק המ\"מ:","\u0003היה כו'. \u0004 ברייתא דרב יוסף וכאביי ורב חסדא:","\u0003 (ליקוט) וכן אם כו'. \u0004 הרא\"ש ורמב\"ם וטור וכגי' שלנו דלא כתוס' שם ד\"ה לא כו' והרשב\"א ועסי\"ז ועתוס' ד\"ה כולה כו' תימא כו' וכן דחק הרשב\"א בזה ותוס' שם לא רצו לפרש כפי שיטתו אבל מה שהקשו שם ולספרים כו' ק\"ו פריכא הוא (ע\"כ):","\u0003אם היא כו'. \u0004 שם אלא פשיטא לא לזה ולזה אלא דחד. והיינו כה\"ג דכפשטיה א\"א לומר כמו שהקשה הרשב\"א דא\"כ מאי לא לזה ולא לזה:\n\u0003 (ליקוט) אם היא כו'. \u0004 דז\"ש אלא דחד דא\"א לומר כפשטה מאי לא לזה כו' ועוד היינו רישא רשות לניזק ומאי ד' כללות (ע\"כ):","\u0003 (ליקוט) בקרן פטור דה\"ל כו'. \u0004 מדפריך שם אתאן לרבנן ואם איתא לוקמה בכה\"ג וכ\"ש בשן ורגל וז\"ש בשן ורגל כו' (ע\"כ):","\u0003בקרן כו' חצר הניזק. \u0004 ל\"ד אלא דלא הוי חצר המזיק ולישנא דגמ' שם נקט אלא פשיטא כו' וקתני סיפא כו':","\u0003ואצ\"ל כו'. \u0004 שם י\"ד א' כא ב':","\u0003או עץ כו'. \u0004 כ\"כ הרא\"ש בשם התוס' תי' שני על קושייתם ו' א' בד\"ה תאמר כו' וא\"ת כו' וערא\"ש ס\"א:","\u0003דהוי כחצר כו'. \u0004 רש\"י שם:","\u0003חצר כו'. \u0004 כמ\"ש בסי\"ג וכן י\"ל בכה\"ג דסי\"ד:\n\u0003 (ליקוט) חצר כו'. \u0004 הרא\"ש וכנ\"ל סי\"ג ותוס' שם נדחקו לשיטתן דלא ס\"ל כמ\"ש בסי\"ג (ע\"כ):","\u0003 (ליקוט) ונקראו אבות כו'. \u0004 רש\"י בריש מכילתין (ע\"כ):","\u0003ואין דרכו כו' ואין כו'. \u0004 ב' ב' (ע\"כ):","\u0003 (ליקוט) בין כו'. \u0004 י\"ד א' וכר\"י (ע\"כ)"]}],["רֶגֶל הִיא אָב, שֶׁוְשִׁלַּח אֶת בְּעִירֹה הַכָּתוּב בַּתּוֹרָה, הוּא \u0010y0\u0011 שֶׁהַבְּהֵמָה הוֹלֶכֶת בְּרַגְלֶיהָ וּמַזֶּקֶת בְּדֶרֶךְ הִלּוּכָהּ, וְהוּא דָּבָר שֶׁדַּרְכָּהּ בְּכָךְ וְאֵין לָהּ בּוֹ הֲנָאָה. וְכָל הַדּוֹמֶה לִדְבָרִים אֵלּוּ הוּא תּוֹלְדוֹתָיו, וְדִינוֹ כְּמוֹתוֹ. כֵּיצַד, כְּגוֹן שֶׁהִזִּיקָה בְּגוּפָהּ דֶּרֶךְ \u0010y1\u0011 הִלּוּכָהּ, אוֹ בִּשְׂעָרָה, אוֹ \u0010y2\u0011 בְשָׁלִיף \u0005(פֵּרַשׁ הַבַּרְטְנוּרָא בָּרִאשׁוֹן מִקַמָּא שָׁלִיף, מַשּׂאוֹי בְּאַמְתָּחוֹת וּמַרְצוּפִין)\u0006 שֶׁעָלֶיהָ, אוֹ בִּפְרוֹמְבִּיָּא \u0005(פֵּרוּשׁ, רֶסֶן)\u0006 שֶׁבְּפִיהָ, אוֹ בַּזּוּג שֶׁבְּצַוָּארָהּ, אוֹ בְּמַשּׂוֹי שֶׁעָלֶיהָ; וְתַרְנְגוֹלִים שֶׁהָיוּ פּוֹרְחִים מִמָּקוֹם לְמָקוֹם וְשָׁבְרוּ כֵּלִים בְּכַנְפֵיהֶם, אוֹ שֶׁהָיוּ \u0010y3\u0011 מְהַדְּסִין \u0005(פֵּרוּשׁ מְהַדְּסִין, עִנְיָן דְּרִיסָה וּרְקִידָה)\u0006 עַל גַּבֵּי עִסָה אוֹ פֵרוֹת וְטִנְּפוּם \u0010y4\u0011 אוֹ נִקְּרוּ בָּהֶם, וְכֵן כָּל דָּבָר הַמְחֻבָּר בְּגוּפָהּ, כְּגוֹן עֶגְלָה הַמּוֹשֶׁכֶת בְּקָרוֹן וְהוֹלִיכָתָהּ עַל גַּבֵּי הַכֵּלִים וְשִׁבַּרְתָּם, כָּל אֵלּוּ תוֹלָדוֹת הָרֶגֶל וְדִינָם כָּמוֹהוּ. \u0010y5\u0011\nכִּשְׁכְּשָׁה בִּזְנָבָהּ כִּשְׁכּוּשׁ רַב שֶׁאֵין דַּרְכָּהּ לַעֲשׂוֹת תָּמִיד, וְהִזִּיקָה בִּרְשׁוּת הָרַבִּים; אוֹ שֶׁכִּשְׁכְּשָׁה בַּגִּיד שֶׁלָּהּ בִּרְשׁוּת הָרַבִּים וְהִזִּיקָה, פָּטוּר. וְאִם תָּפַס הַנִּזָּק, גּוֹבֶה חֲצִי נֶזֶק מִמַּה שֶׁתָּפַס, שֶׁזֶּה הַדָּבָר סָפֵק הוּא אִם אֵלּוּ תּוֹלְדוֹת הַקֶּרֶן שֶׁחַיָּב עָלֶיהָ בִּרְשׁוּת הָרַבִּים, אוֹ תוֹלְדוֹת הָרֶגֶל שֶׁפָּטוּר עָלֶיהָ בִּרְשׁוּת הָרַבִּים. \u0005הַגָּה: \u0010y6\u0011 \u0010c0\u0011 וְיֵשׁ אוֹמְרִים דִּבְכָל סְפֵקָא דְדִינָא לָא מְהַנֵּי תְּפִיסָה, וְלָכֵן אֲפִלּוּ אִם תָּפַס מַפְקִינָן מִנֵּהּ (טוּר ס\"א בְּשֵׁם ר\"י)\u0006 \u0005(וע\"ל סִימָן שכ\"א)\u0006. וּלְדַעַת הָרֹא\"שׁ דְּכִשְׁכְּשָׁה בִּזְנָבָהּ לָא הֲוֵי סָפֵק, וַדַּאי פָטוּר \u0005(טוּר שָׁם הֵבִיאוֹ)\u0006.\nכָּל תּוֹלָדָה כְּאָב שֶׁלָּהּ, חוּץ מִצְּרוֹרוֹת הַמִּנַּתְּזִין מִתַּחַת רַגְלֵי הַבְּהֵמָה בִּשְׁעַת הִלּוּכָהּ, שֶׁאַף עַל פִּי שֶׁתּוֹלְדוֹת רֶגֶל הֵם וּפָטוּר עֲלֵיהֶם בִּרְשׁוּת הָרַבִּים כְּרֶגֶל, וְאִם הִזִּיקוּ בִּרְשׁוּת הַנִּזָּק מְשַׁלֵּם מֵהַיָּפֶה שֶׁבִּנְכָסָיו כְּרֶגֶל שֶׁהוּא אָב, אַף עַל פִּי כֵּן אֵינוֹ מְשַׁלֵּם אֶלָּא חֲצִי נֶזֶק. כֵּיצַד, בְּהֵמָה שֶׁנִּכְנְסָה לַחֲצַר הַנִּזָּק וְהָיוּ צְרוֹרוֹת מִנַּתְּזִין מִתַּחַת רַגְלֶיהָ וְשָׁבְרוּ אֶת הַכֵּלִים, מְשַׁלֵּם חֲצִי נֵזֶק \u0010y7\u0011 מֵהַיָּפֶה שֶׁבִּנְכָסָיו; \u0010y8\u0011 וְדָבָר זֶה הֲלָכָה לְמֹשֶׁה מִסִינַי. \u0010y9\u0011\nוְכֵן אִם הָיְתָה מְהַלֶּכֶת בִּרְשׁוּת הָרַבִּים וְנִתְּזוּ צְרוֹרוֹת מִתַּחַת רַגְלֶיהָ לִרְשׁוּת הַנִּזָּק וְשָׁבְרוּ אֶת הַכֵּלִים, מְשַׁלֵּם חֲצִי \u0010y10\u0011 נֶזֶק. וְהוּא הַדִּין לְתַרְנְגוֹלִים \u0010y11\u0011 שֶׁהִדְּסוּ וְהֶעֱלוּ עָפָר אוֹ צְרוֹרוֹת וְשָׁבְרוּ, וְכֵן חֲזִיר שֶׁהָיָה נוֹבֵר בְּאַשְׁפָּה וְהִתִּיז צְרוֹרוֹת וְהִזִּיק, מְשַׁלֵּם חֲצִי נֵזֶק.\nדָּרְסָה עַל הַכְּלִי בִּרְשׁוּת הַנִּזָּק וְשִׁבַּרְתּוֹ, וְנָפַל עַל כְּלִי אַחֵר וְשִׁבְּרוֹ, \u0010y12\u0011 עַל הָרִאשׁוֹן מְשַׁלֵּם נֶזֶק שָׁלֵם, וְעַל הָאַחֲרוֹן מְשַׁלֵּם חֲצִי נֶזֶק. וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁהוּא הַדִּין לְכֹחַ כֹּחוֹ. \u0005הַגָּה: דָּרְסָה עַל הַכְּלִי וְלֹא נִשְׁבַּר, וְנִתְגַּלְגֵּל לְמָקוֹם אַחֵר וְנִשְׁבַּר שָׁם, \u0010y13\u0011 מְשַׁלֵּם נֶזֶק שָׁלֵם (טוּר ס\"ב)\u0006. \u0010y14\u0011\nהָיְתָה מְהַלֶּכֶת בִּרְשׁוּת הָרַבִּים, וּבָעֲטָה וְהִתִּיזָה צְרוֹרוֹת, וְהִזִּיקוּ בִּרְשׁוּת הָרַבִּים, פָּטוּר. וְאִם תָּפַס הַנִּזָּק רְבִיעַ נֶזֶק, אֵין מוֹצִיאִין מִיָּדוֹ; שֶׁהַדָּבָר סָפֵק הוּא שֶׁמָּא שִׁנּוּי הוּא וְאֵינוֹ תּוֹלָדַת רֶגֶל, שֶׁהֲרֵי בָּעֲטָה.\nבָּעֲטָה בָאָרֶץ בִּרְשׁוּת הַנִּזָּק וְהִתִּיזָה צְרוֹרוֹת מֵחֲמַת הַבְּעִיטָה וְהִזִּיקָה שָׁם, חַיָּב לְשַׁלֵּם רְבִיעַ נֶזֶק, שֶׁזֶּה שִׁנּוּי הוּא בְּהַתָּזַת צְרוֹרוֹת. וְאִם תָּפַס הַנִּזָּק חֲצִי נֶזֶק, אֵין מוֹצִיאִין מִיָּדוֹ. וַאֲפִלּוּ הָיְתָה מְהַלֶּכֶת \u0010y15\u0011 בְּמָקוֹם שֶׁאִי אֶפְשָׁר לָהּ שֶׁלֹּא תַּתִּיז. וּבָעֲטָה וְהִתִּיזָה, מְשַׁלֵּם רְבִיעַ נֶזֶק. וְאִם תָּפַס הַנִּזָּק חֲצִי נֶזֶק, אֵין מוֹצִיאִין מִיָּדוֹ. \u0005הַגָּה: (ר\"י וְהָרֹא\"שׁ)\u0006 וּכְבָר נִתְבָּאֵר דְּיֵשׁ חוֹלְקִין וּסְבִירָא לְהוּ דְּלָא \u0010y16\u0011 מְהַנֵּי תְּפִיסָה בִּסְפֵק דִּינָא:\nבְּהֵמָה שֶׁהֵטִילָה גְלָלִים לְעִסָה, הַיְנוּ צְרוֹרוֹת. וּכְגוֹן דְּדָחִיק לָהּ עָלְמָא שֶׁאֵין לָהּ מָקוֹם לִנְטוֹת אָנֶה וָאָנָה, דְּאִי לָאו הָכִי \u0010y17\u0011 הָוֵי שִׁנּוּי וְתוֹלָדָה דְקֶרֶן הוּא.\nכְּשֵׁם שֶׁחַיָּב עַל כֹּחַ שֶׁיֵּשׁ בּוֹ מַמָּשׁ שֶׁהִתִּיז צְרוֹרוֹת, כָּךְ חַיָּב עַל כֹּחַ שֶׁאֵין בּוֹ מַמָּשׁ, כְּגוֹן סוּס שֶׁצָּנַף \u0005(פֵּרוּשׁ, צְנִיפָה בְּסוּס כְּמוֹ נְעִירָה בַּחֲמוֹר וּנְבִיחָה בְכֶלֶב וּשְׁאָגָה בְּאַרְיֵה)\u0006 וַחֲמוֹר שֶׁנּוֹעֵר וְשָׁבְרוּ כֵּלִים בְּכֹחַ קוֹלָם, וְתַרְנְגוֹל שֶׁשָּׁבַר כֵּלִים בְּרוּחַ כְּנָפָיו אוֹ שֶׁהוֹשִׁיט רֹאשׁוֹ לַאֲוִיר כְּלִי, וְתָקַע בּוֹ, וּשְׁבָרוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁיֵּשׁ בּוֹ זֵרְעוֹנִים, \u0010y18\u0011 דְּהַשְׁתָּא הָוֵי אוֹרְחֵהּ; אֲבָל אִם אֵין בּוֹ זֵרְעוֹנִים הָוֵי שִׁנּוּי, וְלֹא דַּיָּנִין לֵהּ הַשְׁתָּא. \u0010y19\u0011\nהַתַּרְנְגוֹלִים מוּעָדִים לְהַלֵּךְ כְּדַרְכָּן וּלְשַׁבֵּר. \u0005(אוֹ)\u0006 הָיָה חוּט אוֹ רְצוּעָה קָשׁוּר בְּרַגְלֵיהֶם, וְנִסְתַּבֵּךְ כְּלִי בְּאוֹתוֹ הַחוּט וְנִתְגַּלְגֵּל וְנִשְׁבַּר, מְשַׁלֵּם חֲצִי נֶזֶק. \u0005הַגָּה: זֶהוּ לָשׁוֹן הָרַמְבַּ\"ם, וְהוּא סָתוּם; אֲבָל אֲחֵרִים כָּתְבוּ: הָיָה חוּט אוֹ מְשִׁיחָה קְשׁוּרָה בְּרַגְלֶיהָ, אִם גָּרְרָה וְשִׁבְּרָה בּוֹ כְּלִי דֶרֶךְ הִלּוּכָהּ, \u0010y20\u0011 מְשַׁלֵּם נֶזֶק שָׁלֵם; \u0010y21\u0011 זְרָקוֹ וְשָׁבַר בּוֹ, מְשַׁלֵּם חֲצִי נֶזֶק. (וְאִם הִזִּיק אַחַר שֶׁנָּח, פָּטוּר)\u0006 בַּמֶּה דְּבָרִים אֲמוּרִים, בְּחוּט שֶׁל הֶפְקֵר אוֹ שֶׁיֵּשׁ לוֹ בְּעָלִים וְהִצְנִיעוֹ וְנִקְשַׁר מֵאֵלָיו; אֲבָל אִם הַחוּט שֶׁל בַּעַל הַתַּרְנְגוֹל וְלֹא הִצְנִיעוֹ, אֲפִלּוּ נִקְשַׁר מֵאֵלָיו וְשָׁבַר עַל יְדֵי זְרִיקָה, חַיָּב נֶזֶק שָׁלֵם \u0005(טוּר ס\"ג)\u0006, דַּחֲצִי נֵזֶק דִּצְרוֹרוֹת אֵינוֹ \u0010y22\u0011 אֶלָּא בְּהִתִּיזָה דְּבַר הֶפְקֵר, אֲבָל אִם הִתִּיזָה דָבָר \u0005(שֶׁיֵּשׁ לוֹ בְּעָלִים)\u0006 וְלֹא הִצְנִיעוֹ, חַיָּב נֶזֶק שָׁלֵם. וְאִם הַחוּט שֶׁל אֲחֵרִים, \u0010y23\u0011 בַּעַל הַחוּט חַיָּב, בֵּין הִזִּיק הַתַּרְנְגוֹל דֶּרֶךְ גְּרִירָה אוֹ דֶרֶךְ זְרִיקָה, הוֹאִיל וְלֹא הִצְנִיעַ חוּט שֶׁלּוֹ. וְאִם הִזִּיק הַחוּט לְאַחַר שֶׁנָּח, חַיָּב מִשּׁוּם \u0010y24\u0011 בּוֹר הַמִּתְגַּלְגֵּל. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּתַרְנְגוֹל שֶׁל הֶפְקֵר; אֲבָל אִם יֵשׁ לַתַּרְנְגוֹל בְּעָלִים, אִם הִזִּיק דֶּרֶךְ גְּרִירָה \u0010y25\u0011 שְׁנֵיהֶם מְשַׁלְּמִין בְּיַחַד. וְאִם הִזִּיק דֶּרֶךְ זְרִיקָה, \u0010y26\u0011 בַּעַל הַתַּרְנְגוֹל נוֹתֵן רְבִיעַ וּבַעַל הַחוּט שְׁלֹשָׁה חֲלָקִים. \u0010y27\u0011 וְאִם הִזִּיק לְאַחַר שֶׁנָּח, בַּעַל הַתַּרְנְגוֹל פָּטוּר וּבַעַל הַחוּט חַיָּב הַכֹּל. \u0005(וְעַיֵּן לְקַמָּן סִימָן תי\"א יִתְבָּאֵר בְּדִינֵי בוֹר)\u0006. וְכָל זֶה בְּנִקְשַׁר מֵאֵלָיו, אֲבָל אִם קְשָׁרוֹ אָדָם בְּרֶגֶל הַתַּרְנְגוֹל אָז הַקּוֹשֵׁר חַיָּב בְּכָל עִנְיָן, \u0010y28\u0011 אֲפִלּוּ יֵשׁ לַחוּט בְּעָלִים \u0005(טוּר)\u0006. וְהוּא הַדִּין אִם הָיָה הַחוּט מֻנָּח בְּמָקוֹם מֻצְנָע, וְהִנִּיחַ אָדָם בִּמְקוֹם תֻּרְפָּה וְעַל יְדֵי זֶה נִקְשַׁר בַּתַּרְנְגוֹל, הָוֵי כְּאִלּוּ קְשָׁרוֹ בְּיָדַיִם \u0005(בֵּית יוֹסֵף בְּשֵׁם הַתּוֹסָפוֹת שָׁם וּבְשֵׁם הָרֹא\"שׁ)\u0006.\nתַּרְנְגוֹל שֶׁהָיָה מְחַטֵּט בְּחֶבֶל דְּלִי וְנִפְסַק הַחֶבֶל וְנִשְׁבַּר הַדְּלִי, אִם עִסָה דְבוּקָה בַּחֶבֶל דְּהַשְׁתָּא \u0010y29\u0011 אוֹרְחֵהּ הוּא, אוֹ אֲפִלּוּ אֵין בּוֹ עִסָה וְהוּא בָלוּי שֶׁדַּרְכּוֹ לִפָּסֵק עַל יְדֵי חַטִּיטַת הַתַּרְנְגוֹל, חַיָּב בֵּין עַל הַחֶבֶל בֵּין עַל הַדְּלִי נֶזֶק שָׁלֵם. וְאִם הַחֶבֶל חָדָשׁ וְאֵין עִסָה דְּבוּקָה בּוֹ, מְשֻׁנֶּה הוּא וְאֵינוֹ חַיָּב אֶלָּא חֲצִי נֶזֶק בֵּין עַל הַחֶבֶל בֵּין עַל הַדְּלִי, \u0010y30\u0011 וְאִם הוּא הוֹלֵךְ אַחַר הַדְּלִי וּמְגַלְגְּלוֹ עַד הַמָּקוֹם שֶׁנִּשְׁבַּר שָׁם, מְשַׁלֵּם נֶזֶק שָׁלֵם.\nהַכֶּלֶב וְהַגְּדִי שֶׁקָּפְצוּ מֵרֹאשׁ הַגַּג מִלְמַעְלָה לְמַטָּה וְשָׁבְרוּ אֶת הַכֵּלִים, מְשַׁלְּמִים נֶזֶק שָׁלֵם \u0010y31\u0011 מִפְּנֵי שֶׁמּוּעָדִים הֵם לְדָבָר זֶה. וְכֵן אִם נָפְלוּ וְהִזִּיקוּ, שֶׁעֲלִיָּתָן לְרֹאשׁ הַגַּג פְּשִׁיעָה; וְאַף עַל פִּי שֶׁנְּפִילָתָן \u0010y32\u0011 אֹנֶס, כָּל שֶׁתְּחִלָּתוֹ בִּפְשִׁיעָה וְסוֹפוֹ בְּאֹנֶס, חַיָּב. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאִם הָיוּ הַכֵּלִים סְמוּכִים לַכֹּתֶל, שֶׁאֵין רְאוּיִין לִשָּׁבֵר עַל יְדֵי קְפִיצָה, וְנָפְלוּ, פָּטוּר, דְּאֹנֶס הוּא. וְאִם הַכְּלִי אָרֹךְ וְרֹאשׁוֹ אֶחָד קָרוֹב לַכֹּתֶל וְרֹאשׁ הַשֵּׁנִי רָחוֹק בְּעִנְיָן שֶׁרָאוּי לִשָּׁבֵר עַל יְדֵי קְפִיצָה, וְנָפְלוּ קָרוֹב לַכֹּתֶל וְשָׁבְרוּ, חַיָּב, דִּתְחִלָּתוֹ בִּפְשִׁיעָה עַל יְדֵי קְפִיצָה. וְאִם הַכֹּתֶל צַר, אֲפִלּוּ קְרוֹבִים לַכֹּתֶל וְנָפְלוּ, \u0010y33\u0011 חַיָּב, וְהוּא שֶׁקָּפְצוּ כְּדַרְכָּם; אֲבָל אִם קָפַץ הַכֶּלֶב בִּרְקִידָה וְהַגְּדִי נִסְרַךְ, דְּהָוֵי \u0010y34\u0011 שִׁנּוּי גַבַּיְהוּ, אֵין מְשַׁלְּמִין אֶלָּא חֲצִי נֶזֶק (טוּר ס\"א)\u0006. קָפְצוּ מִלְּמַטָּה לְמַעְלָה, מְשַׁלְּמִים חֲצִי נֶזֶק. \u0010y35\u0011 \u0005וְהוּא\u0006 שֶׁנִּתְלָה הַגְּדִי וְנִסְרַךְ, וְקָפַץ הַכֶּלֶב. אֲבָל נִסְרַךְ הַכֶּלֶב, וְדִלֵּג הַגְּדִי, בֵּין מִלְמַעְלָה לְמַטָּה בֵּין מִלְּמַטָּה לְמַעְלָה, חַיָּבִים נֶזֶק שָׁלֵם. וְכֵן תַּרְנְגוֹל שֶׁדִּלֵג בֵּין מִלְמַעְלָה לְמַטָּה בֵּין מִלְּמַטָּה לְמַעְלָה, מְשַׁלֵּם נֶזֶק שָׁלֵם. וְהוּא הַדִּין מִי שֶׁמָּסַר בֵּיתוֹ \u0010y36\u0011 לְשָׁמְרוֹ וְהָיוּ בּוֹ חֵרֵשׁ שׁוֹטֶה וְקָטָן, צָרִיךְ לְשָׁמְרָם שֶׁלֹּא יְדַלְּגוּ מִלְמַעְלָה לְמַטָּה וְלֹא מִלְּמַטָּה לְמַעְלָה:",["\u0003ה\"ג שהבהמה הולכת ברגלי' ומזקת בדרך הילוכה \u0004 וכ\"כ הטור ר\"ס זה ע\"ש:","\u0003או בשער' \u0004 פי' שנסתבך כלים בשער' וגרר' ושברן:","\u0003בשליף שעלי' \u0004 הוא משאוי שנטען עליה המונח באמתחת במרצופין רש\"י. ומ\"ש המחבר אחר זה או במשוי שעלי' ר\"ל משוי שהוא בעין הנטען עליה:","\u0003מהדסין \u0004 פי' שמרקדין:","\u0003או נקרו בהן \u0004 ומאסוהו בנקירתן אף שלא אכלוהו דאל\"כ ה\"ל תולד' דשן דהא יש לו הנאה באכילתו:","\u0003כשכשה בזנבה כו' \u0004 ז\"ל הטור אם כשכשה בדרך כל הבהמות (פי' ושיבר' כלי דרך כשכושה) ודאי אורחיה הוא פי' והוי דינו ברגל שפטור על מה שהזיק בר\"ה ועל הזיקו ברשו' הניזק חייב נ\"ש אבל בכשכש רב (פי' אם הזיק מכח כשכש רב ואי לא הוי מכשכש אלא כדרך שאר הבהמות לא הוי משתבר הכלי) מיבעיא אי הוי כאורח' וכ' הרמב\"ם דלא איפשט' לי' אבל הרא\"ש כ' דאיפשט' דהוה אורח' והוי תולד' דרגל ואם כשכשה בגיד שלה (ועי\"ז שברה הכלי לכ\"ע) הוא איבעיא דלא אפשטא כו' ע\"ש ועל פי זה נתבאר לך דברי המחב' ומה שכ' מ\"ו ר' משה אסרלש ז\"ל עליו בהג\"ה דהמחב' כ' כדברי הרמב\"ם דס\"ל דכשכש רב דזנבו וסתם כשכש דגיד שלה שוין הן ושניהן הן איבעיות דלא איפשט' בגמ' אי תולדה דקרן הוא או תולד' דרגל והמע\"ה ומ\"ה אי לא תפסו הניזק והזיקה בר\"ה אין לו כלו' דיכול המזיק לומ' תולדה דרגל הוא ואם הזיקה ברשות הניזק אינו משלם אלא ח\"נ ממ\"נ אבל אם תפס ונעשה הנזק ברשות הניזק צריך לשלם נ\"ש דיד התופס על העליונ' ויאמר תולד' דרגל הוא ואם בר\"ה נעשה הנזק יאמר התופס תולדה דקרן הוא וצריך לשלם חצי נזק והיינו דוקא לדעת הרמב\"ם דס\"ל דמהני תפיסה אף במקום שהוא ספק לנו אי הוה קרן או רגל ועל זה כ' מור\"ם די\"א (והוא ר\"י והרא\"ש) דלא מהני תפיס' בספיק' דדינ' ועוד כ' דלדעת הרא\"ש אם כשכש בזנבו כשכש (שאינו) רב אפשט' האיבעיא דהוה אורחא ותולדה דרגל היא ואם הזיקה ברשות הרבים פטור לגמרי אפי' למ\"ד דמהני תפיסה לספיק' דדינא דכאן אין ספק אלא ודאי אורחא הוא ומינה דאם הזיקה ברשות הניזק דמשלם נזק שלם אפי' לדעת ר\"י והרא\"ש כיון דודאי אורחא הוא וה\"ל למור\"ם לכתוב ג\"כ צד חיובו דכשכש בזנבו כשכוש שאינו רב ברשות הניזק אלא דחדא באידך תליא וצד החיוב נלמד מצד הפטור כנ\"ל:","\u0003דבכל ספיקא דדינא לא מהני תפיסה כו'. \u0004 והיינו בדבר שהוא איבעיא וכנ\"ל אבל ג\"כ מודים דאם הזיקה ברשו' הניזק דאינו משלם אפי' חצי נזק בלא תפיסה דכיון דלא איפשטא יש לומ' דלא הוה אורחא ותולדה דקרן הוא וקרן אינו משלם חצי נזק אלא מגופו וכמ\"ש הטור והמחב' בסימן א' וגם בסימן זה כתבו הטור ע\"ש ומ\"ה בעינן שיתפוס גופו דהמזיק דוקא וישלם ממנו ח\"נ ועד\"ר והטור מסיק וכ' בזה ז\"ל ואפי' אם היזק לאדם אחד בר\"ה וברשות הניזק דינא הכי ואינו יכול לומ' ממ\"נ אם תאמר שהוא קרן תתחייב לי גם כן ברה\"ר וא\"ת שהוא רגל (ומ\"ה תפטר על הזיקו בר\"ה אם כן) תן לי נזק שלם הזיקו דרשות הניזק אלא בשניהן להקל עד כאן לשון הטור ואע\"ג דכתב הטור והמחב' בסי' א' בספיקא דדינא אי כליו של לוקח ברשות מוכר או איפכא קונים וקנה אחד מחבירו בשניהן דקנה בא' מהן ממ\"נ שאני הכא דהוא ענין דקנסא דהא גופו לא הזיק אלא שורו שהוא ממונו מ\"ה הולכין בשניהן להקל ועד\"ר:","\u0003מהיפה שבנכסיו. \u0004 כבר כתבתי פירושו דמשלם המזיק ג\"כ מכיסו ולאו דוקא מהשור כדין קרן:","\u0003ודבר זה הלכה למשה מסיני \u0004 פי' אע\"פ שהדברים נראין כסותרין זא\"ז שיש לו דין רגל לענין פטור בר\"ה ולענין חיוב תשלומין מנכסיו יש לו דין קרן שאינו משלם אלא חצי נזק אף ברשות הניזק מ\"ה כ' דהלכה למשה מסיני. כן הוא ואין להרהר אחריה:","\u0003וכן אם היתה מהלכת בר\"ה כו'. \u0004 קמ\"ל בזה דאע\"ג דצרורות דין רגל יש לו ופטור על הזיקו בר\"ה מ\"מ כיון דהצרורות נתזו משם ברשות הניזק בתר הניזק אזלינן וחייב:","\u0003וה\"ה לתרנגולים כו'. \u0004 שכל שאורחא הוא והיזק בא מכחו דין צרורות יש לו:","\u0003שהדסו והעלו עפר. \u0004 פי' ברשות הניזק או ברשות הרבים ונתזו לרשות הניזק והזיקו וכנ\"ל:","\u0003על הראשון משלם נ\"ש כו'. \u0004 דהראשון נשבר ברגלו והשני נשבר בצרורות:","\u0003משלם נ\"ש. \u0004 כיון דהשבירה בא מכח הדריסה על הכלי עצמו הולכין אחר התחלתו והוי מרגל עצמו ולא מצרורות. משא\"כ בהיתה מהלכת בר\"ה והתיזה צרורות לרשות הניזק דאזלינן בתר מקום שנשבר שם וכנ\"ל:","\u0003היתה מהלכת בר\"ה ובעט' כו'. \u0004 כ\"מ שנזכ' התזת צרורות היינו צרורות באורחי' דהוא תולדה דרגל ומשלם ח\"נ וברשות הניזק דוקא ובר\"ה פטו' לגמרי כדין רגל וכנ\"ל וכל היכא דנזכ' צרורו' בבעיט' ה\"ל צרורות בשינוי דדרך הבהמות לילך ולהתיזו להשליך צרורות דרך הילוכה אבל לא בבעיטה דהיינו שמכה ברגליה בכח דרך אחוריה ומכח זה נתזין הצרורות למקום אחר וכבר נתבא' בטו' ובדברי המחב' בס\"ס שפ\"ט דהבעיטה בבהמה שינוי הוא וקמבעיא בגמ' אם יש שינוי בצרורות כיון שבאין מכח הבעיטה או אין שינוי ופירשו הרמב\"ם דבכלל איבעיא זו אי יש שינוי לצרורות הוא קולא וחומרא קולא דאפי' ברשות הניזק רביע הוא דמשלם ותו לא והיינו שינוי דכמו שתם כיון שנשתנה ממועד אינו משלם אלא ח\"נ דמועד ה\"נ שינוי דצרורות אין משלמין אלא ח\"נ מצרורות דעלמא והיינו רביע וחומרא נמי דאפי' בר\"ה הוא משלם כדין קרן כיון דהוא משונה ואינו אורח' משא\"כ כשאמרי' דאין שינוי לצרורות דאז יש לו דין צרורות דהוי אורחי' ופטו' בר\"ה דומה לרגל וגם כן חייב עליהן ח\"נ ברשות הניזק כדין צרורות ואיבעיא זו עלתה בתיקו וסבירא ליה להרמב\"ם והמחב' דאזל בשיטתי' דמהני תפיסה לספיקא דדינא וכנ\"ל ועל פי זה יתבארו דברי המחב' מ\"ש דאם בעטה והזיק' ברשות הרבים פטו' היינו דאמרי' המע\"ה ושמא אין שנוי לצרורות דבעיטה ויש לו דין רגל דפטו' בר\"ה ואם תפס ידו על העליונה לו' יש שינוי לצרורות ויש לו דין קרן לחייב ברשות הרבים מיהו כיון דהתופס בא לתפוס ולילך לחומרא לו' יש שינוי א\"כ עליו ג\"כ לקבל צד הקולא דהיא ביש שינוי דהיינו דאינו משלם ברשות הרבים אלא רביע נזק חצי דין קרן ואפי' אותו רביע אינו משלם אלא כשתפס גוף השור המזיק דהא קרן דתם אינו משלם אלא מגופו וכנזכ' לעיל וזה שסיים המחב' בטעמו וכתב שהדב' ספק כו' שהוא טעם לכולן וכמו שכתבתי ומסיק וכתב דאם בעטה והזיקה ברשות הניזק חייב לשלם רביע על כל פנים דאף אם הוא קרן ויש שינוי לצרירות עכ\"פ חצי צרורות חייב לשלם והיינו רביעית מיהו גם רביע זה אינו משתלם אלא מגופו דהמזיק וכנ\"ל ואם תפס החצי ואפילו תפס דבר אחר אין מוציאין מידו דיכול לו' אין שינוי לצרורות והוה תולדה דרגל ומשתלם ברשות הניזק חציו אפילו מכיסו דהמזיק:","\u0003במקום שא\"א לה שלא תתיז. \u0004 ג\"ז איבעיא בגמ' ומשום דבזה יש סברא לו' דה\"ל דין רגל טפי אף שבא מחמת בעיטה כיון דאפילו בלא בעיטה ג\"כ היתה מתזת צרורות כיון שהוא מקום שא\"א לה שלא תתיזה ואפ\"ה כיון דאיבעיא דלא איפשטא הוא דינא כאיבעיא שלפני זה בבעטה והתיזה והיה אפש' לה שלא תתיז:","\u0003מהני תפיסה כו' \u0004 ולדעתם כתב הטור דאם היזק בר\"ה מפקינן מיניה וברשות הניזק אי תפס גוף המזיק גובין לו ממנו רביע הנזק עד כאן לשונו וטעמו הוא פשוט על פי מה שאמר דהמע\"ה וכיון דלא מהני ביה תפיסה לעולם הניזק ידו על התחתונה:","\u0003הוי שינוי \u0004 דאין דרך הבהמה להטיל גללים לעיסה:","\u0003דהשתא הוי אורחא. \u0004 פי' אורחא להושיט שם ראשו כדי לאכול וכל שאורחא להושיט שם ראשו רגיל גם כן לצעוק ולתקוע:","\u0003התרנגולים מועדים כו'. \u0004 עד ונתגלגל ונשבר משלם ח\"נ זהו ל' הרמב\"ם והוא סתום כו' ע\"ש ברמב\"ם דכת' עוד פרטי דינים בתרנגול וחוט קשר ברגליו ומחלת במי קשרו ובשל מי הי' החוט ועל רוב דבריו השיג שם הראב\"ד ואפש' דמשום הכי לא העתיקם המחב' אלא שקשה דא\"כ גם בבא זו דנתגלגל ונשב' משלם ח\"נ לא הי' לו להעתיק דגם עליה השיג הראב\"ד שם גם מור\"ם לא היה לו לכתוב עליה ל' והוא סתם שהרי הרמב\"ם ביאר דבריו שם וכ' עליה בד\"א כו' אלא שהפוסקים חולקים על דבריו ונראה דהמחב' העתיק מדברי הרמב\"ם ריש דבריו משום דנוכל לקיימן אליבא דהלכתא ולפרש' דמיירי בחוט של הפק' וכששוב' דרך זריקה דאז גם שאר הפוסקים ס\"ל דמשלם בעל התרנגול ח\"כ וכדמסיק מור\"ם ג\"כ ואף שהרמב\"ם כ' שם ע\"ז בד\"א וגילה דלא איירי בהכי מ\"מ ניחא לי' להמחב' להעתיק לשונו מאי דאפשר לקיימו ומור\"ם כ' עלו והוא סתום ור\"ל דהמחב' העתיק סתימת דבריו אבל פירושו זה הוא דחוק וצ\"ע:","\u0003משלם נזק שלם \u0004 דהוי רגל:","\u0003זרקו ושבר \u0004 דה\"ל צרורות:","\u0003אלא בהתיזה דבר הפקר \u0004 דומיא דצרורות דהם הפקר:","\u0003בעל החוט חייב \u0004 פירוש כל הנזק אם התרנגול הוא של הפקר וכדמסיק ומטעם דבעל החוט הוה ליה לשמור חוטו שלא יסתבך בו התרנגול של הפקר:","\u0003בור המתגלגל \u0004 פי' אף שלא הניחו בעל החוט במקום שהזיק מ\"מ יש לו דין בור שחוטו יש לו דין בור שנתגלגל ממקום שהניחו למקום שנח עתה ע\"י התרנגול והיזק שם וכ' שם הטו' דאם היזק אחר שנח פטור על הזיק כלי' שנזקו בו כמו שכ' הטו' בסי' ת\"י כדין בור דדרשינן חמור ולא כלים (אבל מה דדרשינן שור ולא אדם היינו דוקא אם ימית האדם בנפילתו לבור ומכח החוט לא ימות משא\"כ כלי הנשבר דשבירתו זו היא מיתתו) משא\"כ בהיזק דרך גרירא או זריקה דאז חיובו מכח רגל או אשו וחייב על הכל:","\u0003שניהם משלמין ביחד. \u0004 דגם בעל התרנגול פשע דהוה ליה לשמור התרנגול:","\u0003בעל התרנגול נותן רביע. \u0004 דזריקה דתרנגול ה\"ל כצרורות דשור דאינו משלם אלא ח\"נ והשתא דאיכא לבעל החוט לשלם בהדיה אין עליו אלא חצי חיובו דהיינו רביע הנזק וג' חלקים על בעל החוט דהא בעל החוט אי הוה הוא לבדו כגון שהתרנגול היה הפקר היה מחויב לשלם כולו:","\u0003ואם הזיק לאחר שנח \u0004 דדרשינן כי יכרה איש בור ולא שור בור מ\"ה אין צד חיוב בזה על בעל התרנגול אף אם החוט היה הפקר והזיק אחר שנח:","\u0003אפי' יש לחוט בעלים \u0004 כן הוא ג\"כ לשון הטו' והו\"מ למימר רבותא טפי אפילו אם יש גם לתרנגול בעלים וצ\"ל דס\"ל דאין בזה צד רבותא טפי דכל נזק שבא מצד התרנגול ודאי זה הקושר הוא חייב בו ולא בעל התרנגול כיון דהדר הוא ולקחו וקשרו בתרנגול נעשה בו בעל ולא אתא לאשמועינן אלא דחייב גם בחיובו דבעל חוט דהוא בעל התקלה דחוט אף שאינו תולה הזיקה בתרנגול וק\"ל:","\u0003או אפי' אין בו עיסה כו'. \u0004 פי' אף שאין בו עיסה דרך התרנגול לחטט בחבל דלי שהוא רטוב למצות מים לשתות וזהו שייך בין שהחבל הוא ישן או חדש אלא שאין דרך החדש להפסיק מכח מציצ' מים כזו אבל אם יש בו עיסה חוטט בו טובא ואף כשהוא חדש פוסק לפעמים.","\u0003ואם הוא הולך אחר הדלי כו'. \u0004 אבל אם אינו הולך אחר הדלי אינו משלם אלא ח\"נ ול\"ד לדורס הכלי ונתגלגל הכלי למקום אחר דנתבאר בסי' זה דאזלינן בתר התחלת הדריס' וה\"ל רגל וחייב נ\"ש דשאני דריס' דאורחיה הוא משא\"כ פסיקת חבל חדש בזה דשינוי הוא ועד\"ר:","\u0003מפני שמועדין הן כו'. \u0004 פי' וה\"ל לבעליהן לשומרן שלא יקפצו ויזיקו:","\u0003כל שתחלתו בפשיע' וכו'. \u0004 וזה אונס הבא מחמת הפשיעה דאילו שמרם מהפשיעה לא הוי בא לידי נפילה מהגג ומיהו אין דרכם לקפוץ אלא רחוק קצת מהכותל ומ\"ה אם היו כלים סמוכים לכותל דאז לא פשע מתחל' במה שלא שמרם כיון שאין דרכן ליפול ובקפיצתן אינן יכולין להשתבר ומ\"ה כתב הטור וכתבו מור\"ם בהג\"ה דאם נפלו והזיקו דבעליהן פטורין:","\u0003ומ\"ש והוא שקפצו כדרכן. \u0004 פי' שדרך הגדי לקפוץ בזקירה אחת מלמעלה למטה משא\"כ הכלב שרגיל לסרוך ולנעץ צפרנו בצידי הכותל ומאחז בה ויורד ולבסוף קופץ:","\u0003אין משלמין בזה אלא ח\"נ \u0004 ואין אומרים בזה כיון שפשע מתחלה לענין שאם יקפצו כדרכן שיחייב נ\"ש דהא מ\"מ התורה לא חייבה על היזק הבא ע\"י שינוי אלא ח\"נ דומיא דתם שהזיק בקרן ומשום דלאו אורחיה הוא ה\"ל שינוי לגבייהו:","\u0003והוא שנתלה הגדי כו'. \u0004 כן הוא דעת הרי\"ף והרמב\"ם דס\"ל דלמעלה למטה בכל ענין חייב נ\"ש ודוקא בקפצו מלמטה למעלה בו חילקו בגמרא בין קפצו כדרכן או דרך שינוי ועד\"ר שהארכתי בגרסתם בגמ' ושל הרא\"ש והטור הי' ולהן גירסא אחרת בדברי הרי\"ף והרמב\"ם ממה שהי' בפני הב\"י:","\u0003והי' בו חש\"ו. \u0004 דאלו עבדו כבר נתבאר בסי' שמ\"ט ושפ\"ט דאין אדם חייב על נזקי עבדו ואילו הזיקו הוא עצמו כבר נתבאר דאדם מועד לעולם בין ער בין ישן על כל מה שיזיק ודוק:"],["\u0003 וי\"א דבכל ספיקא דדינא כו'. \u0004 וכ\"פ מהרש\"ל פ' כיצד הרגל סי' ה' וז' ועמ\"ש לעיל סי' שפ\"ח סעיף א' ועיין בסמ\"ע ס\"ק ז' עד דהוא ענין דקנסא דהא גופו לא הזיק וכו' אין לזה טעם כלל וכבר השיג עליו הב\"ח גם מ\"ש הב\"ח דמיירי בב' בהמות שהזיקו לא נהירא אלא נראה אף בבהמה אחת כיון דמבעיא אי אורחא היא ואין כוונתה להזיק או כוונתה להזיק והוי קרן א\"כ יכול לו' דלמא טבע הבהמה לפעמי' הוא כך ולפעמים כך ודלמא בר\"ה הזיקה דרך הלוכה כי אורחא ולא הי' כוונתה להזיק וברשות הניזק היתה כוונת' להזיק וקרן הוא ודוק כן נ\"ל ברור:"],"\u0010g0\u0011 רֶגֶל הִיא אָב, שֶׁוְשִׁלַּח אֶת בְּעִירֹה הַכָּתוּב בַּתּוֹרָה, הוּא \u0010y0\u0011 שֶׁהַבְּהֵמָה הוֹלֶכֶת בְּרַגְלֶיהָ וּמַזֶּקֶת \u0010r0\u0011 בְּדֶרֶךְ \u0010r1\u0011 הִלּוּכָהּ, וְהוּא דָּבָר שֶׁדַּרְכָּהּ בְּכָךְ \u0010r2\u0011 וְאֵין לָהּ בּוֹ הֲנָאָה. \u0010r3\u0011 וְכָל הַדּוֹמֶה לִדְבָרִים אֵלּוּ הוּא תּוֹלְדוֹתָיו, וְדִינוֹ כְּמוֹתוֹ. כֵּיצַד, \u0010g1\u0011 \u0010r4\u0011 כְּגוֹן שֶׁהִזִּיקָה בְּגוּפָהּ דֶּרֶךְ \u0010y1\u0011 הִלּוּכָהּ, אוֹ \u0010t0\u0011 בִּשְׂעָרָה, אוֹ \u0010y2\u0011 בְשָׁלִיף \u0005(פֵּרַשׁ הַבַּרְטְנוּרָא בָּרִאשׁוֹן מִקַמָּא שָׁלִיף, מַשּׂאוֹי בְּאַמְתָּחוֹת וּמַרְצוּפִין)\u0006 שֶׁעָלֶיהָ, אוֹ בִּפְרוֹמְבִּיָּא \u0005(פֵּרוּשׁ, רֶסֶן)\u0006 שֶׁבְּפִיהָ, אוֹ בַּזּוּג שֶׁבְּצַוָּארָהּ, \u0010r5\u0011 אוֹ בְּמַשּׂוֹי שֶׁעָלֶיהָ; וְתַרְנְגוֹלִים שֶׁהָיוּ פּוֹרְחִים מִמָּקוֹם לְמָקוֹם וְשָׁבְרוּ כֵּלִים בְּכַנְפֵיהֶם, אוֹ שֶׁהָיוּ \u0010y3\u0011 מְהַדְּסִין \u0005(פֵּרוּשׁ מְהַדְּסִין, עִנְיָן דְּרִיסָה וּרְקִידָה)\u0006 עַל גַּבֵּי עִסָה אוֹ פֵרוֹת וְטִנְּפוּם \u0010y4\u0011 אוֹ \u0010t1\u0011 נִקְּרוּ בָּהֶם, וְכֵן כָּל דָּבָר הַמְחֻבָּר בְּגוּפָהּ, כְּגוֹן עֶגְלָה הַמּוֹשֶׁכֶת בְּקָרוֹן וְהוֹלִיכָתָהּ עַל גַּבֵּי הַכֵּלִים וְשִׁבַּרְתָּם, כָּל אֵלּוּ תוֹלָדוֹת הָרֶגֶל \u0010r6\u0011 וְדִינָם כָּמוֹהוּ. \u0010y5\u0011 \u0010g2\u0011\nכִּשְׁכְּשָׁה בִּזְנָבָהּ כִּשְׁכּוּשׁ רַב שֶׁאֵין דַּרְכָּהּ לַעֲשׂוֹת תָּמִיד, וְהִזִּיקָה בִּרְשׁוּת הָרַבִּים; \u0010g3\u0011 אוֹ שֶׁכִּשְׁכְּשָׁה בַּגִּיד שֶׁלָּהּ בִּרְשׁוּת הָרַבִּים וְהִזִּיקָה, פָּטוּר. \u0010r7\u0011 וְאִם תָּפַס \u0010g4\u0011 הַנִּזָּק, גּוֹבֶה חֲצִי נֶזֶק מִמַּה שֶׁתָּפַס, שֶׁזֶּה הַדָּבָר סָפֵק הוּא אִם אֵלּוּ תּוֹלְדוֹת הַקֶּרֶן שֶׁחַיָּב עָלֶיהָ בִּרְשׁוּת הָרַבִּים, אוֹ תוֹלְדוֹת הָרֶגֶל שֶׁפָּטוּר עָלֶיהָ בִּרְשׁוּת הָרַבִּים. \u0005הַגָּה: \u0010y6\u0011 \u0010c0\u0011 וְיֵשׁ אוֹמְרִים דִּבְכָל סְפֵקָא \u0010t2\u0011 דְדִינָא לָא מְהַנֵּי תְּפִיסָה, וְלָכֵן אֲפִלּוּ אִם תָּפַס מַפְקִינָן מִנֵּהּ (טוּר ס\"א בְּשֵׁם ר\"י)\u0006 \u0010g5\u0011 \u0005(וע\"ל סִימָן שכ\"א)\u0006. \u0010r8\u0011 וּלְדַעַת הָרֹא\"שׁ דְּכִשְׁכְּשָׁה בִּזְנָבָהּ \u0010g6\u0011 לָא הֲוֵי סָפֵק, וַדַּאי פָטוּר \u0005(טוּר שָׁם הֵבִיאוֹ)\u0006. \u0010g7\u0011\nכָּל תּוֹלָדָה כְּאָב שֶׁלָּהּ, חוּץ מִצְּרוֹרוֹת הַמִּנַּתְּזִין מִתַּחַת רַגְלֵי הַבְּהֵמָה בִּשְׁעַת הִלּוּכָהּ, שֶׁאַף עַל פִּי שֶׁתּוֹלְדוֹת רֶגֶל הֵם \u0010r9\u0011 וּפָטוּר עֲלֵיהֶם בִּרְשׁוּת הָרַבִּים כְּרֶגֶל, \u0010r10\u0011 וְאִם הִזִּיקוּ בִּרְשׁוּת הַנִּזָּק מְשַׁלֵּם מֵהַיָּפֶה שֶׁבִּנְכָסָיו כְּרֶגֶל שֶׁהוּא אָב, אַף עַל פִּי כֵּן אֵינוֹ מְשַׁלֵּם אֶלָּא חֲצִי נֶזֶק. כֵּיצַד, \u0010g8\u0011 בְּהֵמָה שֶׁנִּכְנְסָה לַחֲצַר הַנִּזָּק וְהָיוּ צְרוֹרוֹת מִנַּתְּזִין מִתַּחַת רַגְלֶיהָ וְשָׁבְרוּ אֶת הַכֵּלִים, מְשַׁלֵּם חֲצִי נֵזֶק \u0010y7\u0011 מֵהַיָּפֶה שֶׁבִּנְכָסָיו; \u0010y8\u0011 \u0010r11\u0011 וְדָבָר זֶה הֲלָכָה לְמֹשֶׁה \u0010t3\u0011 מִסִינַי. \u0010y9\u0011 \u0010g9\u0011\nוְכֵן אִם הָיְתָה מְהַלֶּכֶת בִּרְשׁוּת הָרַבִּים וְנִתְּזוּ צְרוֹרוֹת מִתַּחַת רַגְלֶיהָ לִרְשׁוּת הַנִּזָּק וְשָׁבְרוּ אֶת הַכֵּלִים, \u0010t4\u0011 מְשַׁלֵּם חֲצִי \u0010y10\u0011 \u0010g10\u0011 נֶזֶק. וְהוּא הַדִּין \u0010g11\u0011 לְתַרְנְגוֹלִים \u0010y11\u0011 \u0010t5\u0011 שֶׁהִדְּסוּ \u0010t6\u0011 וְהֶעֱלוּ עָפָר אוֹ צְרוֹרוֹת וְשָׁבְרוּ, וְכֵן \u0010g12\u0011 חֲזִיר שֶׁהָיָה \u0010g13\u0011 נוֹבֵר בְּאַשְׁפָּה וְהִתִּיז צְרוֹרוֹת וְהִזִּיק, מְשַׁלֵּם חֲצִי נֵזֶק. \u0010g14\u0011\nדָּרְסָה עַל הַכְּלִי \u0010g15\u0011 בִּרְשׁוּת הַנִּזָּק וְשִׁבַּרְתּוֹ, וְנָפַל עַל כְּלִי אַחֵר וְשִׁבְּרוֹ, \u0010y12\u0011 עַל הָרִאשׁוֹן מְשַׁלֵּם נֶזֶק \u0010t7\u0011 שָׁלֵם, וְעַל \u0010g16\u0011 הָאַחֲרוֹן מְשַׁלֵּם חֲצִי נֶזֶק. \u0010g17\u0011 \u0010r12\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁהוּא הַדִּין לְכֹחַ כֹּחוֹ. \u0005הַגָּה: \u0010r13\u0011 דָּרְסָה עַל הַכְּלִי וְלֹא נִשְׁבַּר, וְנִתְגַּלְגֵּל לְמָקוֹם אַחֵר וְנִשְׁבַּר שָׁם, \u0010y13\u0011 מְשַׁלֵּם נֶזֶק שָׁלֵם \u0010g18\u0011 (טוּר ס\"ב)\u0006. \u0010y14\u0011 \u0010g19\u0011\nהָיְתָה מְהַלֶּכֶת בִּרְשׁוּת הָרַבִּים, וּבָעֲטָה וְהִתִּיזָה צְרוֹרוֹת, וְהִזִּיקוּ בִּרְשׁוּת הָרַבִּים, פָּטוּר. וְאִם תָּפַס \u0010t8\u0011 הַנִּזָּק רְבִיעַ נֶזֶק, אֵין מוֹצִיאִין מִיָּדוֹ; שֶׁהַדָּבָר סָפֵק הוּא שֶׁמָּא שִׁנּוּי הוּא וְאֵינוֹ תּוֹלָדַת רֶגֶל, שֶׁהֲרֵי בָּעֲטָה. \u0010g20\u0011\nבָּעֲטָה בָאָרֶץ בִּרְשׁוּת הַנִּזָּק וְהִתִּיזָה צְרוֹרוֹת מֵחֲמַת הַבְּעִיטָה וְהִזִּיקָה שָׁם, \u0010t9\u0011 \u0010r14\u0011 חַיָּב לְשַׁלֵּם רְבִיעַ נֶזֶק, שֶׁזֶּה שִׁנּוּי הוּא בְּהַתָּזַת צְרוֹרוֹת. וְאִם תָּפַס הַנִּזָּק חֲצִי נֶזֶק, אֵין מוֹצִיאִין מִיָּדוֹ. וַאֲפִלּוּ הָיְתָה מְהַלֶּכֶת \u0010y15\u0011 בְּמָקוֹם שֶׁאִי אֶפְשָׁר לָהּ שֶׁלֹּא תַּתִּיז. וּבָעֲטָה וְהִתִּיזָה, מְשַׁלֵּם רְבִיעַ נֶזֶק. וְאִם תָּפַס הַנִּזָּק חֲצִי נֶזֶק, אֵין מוֹצִיאִין מִיָּדוֹ. \u0005הַגָּה: (ר\"י וְהָרֹא\"שׁ)\u0006 וּכְבָר נִתְבָּאֵר \u0010g21\u0011 דְּיֵשׁ חוֹלְקִין וּסְבִירָא לְהוּ דְּלָא \u0010y16\u0011 מְהַנֵּי תְּפִיסָה בִּסְפֵק דִּינָא: \u0010g22\u0011\nבְּהֵמָה שֶׁהֵטִילָה גְלָלִים לְעִסָה, הַיְנוּ צְרוֹרוֹת. \u0010g23\u0011 וּכְגוֹן דְּדָחִיק לָהּ עָלְמָא שֶׁאֵין לָהּ מָקוֹם לִנְטוֹת אָנֶה וָאָנָה, דְּאִי לָאו הָכִי \u0010y17\u0011 הָוֵי \u0010t10\u0011 שִׁנּוּי וְתוֹלָדָה דְקֶרֶן הוּא. \u0010g24\u0011\nכְּשֵׁם שֶׁחַיָּב עַל כֹּחַ שֶׁיֵּשׁ בּוֹ מַמָּשׁ שֶׁהִתִּיז צְרוֹרוֹת, כָּךְ חַיָּב עַל כֹּחַ שֶׁאֵין בּוֹ מַמָּשׁ, כְּגוֹן סוּס שֶׁצָּנַף \u0005(פֵּרוּשׁ, צְנִיפָה בְּסוּס כְּמוֹ נְעִירָה בַּחֲמוֹר וּנְבִיחָה בְכֶלֶב וּשְׁאָגָה בְּאַרְיֵה)\u0006 וַחֲמוֹר שֶׁנּוֹעֵר וְשָׁבְרוּ כֵּלִים בְּכֹחַ קוֹלָם, וְתַרְנְגוֹל שֶׁשָּׁבַר כֵּלִים בְּרוּחַ כְּנָפָיו אוֹ שֶׁהוֹשִׁיט רֹאשׁוֹ לַאֲוִיר כְּלִי, וְתָקַע בּוֹ, וּשְׁבָרוֹ. \u0010g25\u0011 בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁיֵּשׁ בּוֹ זֵרְעוֹנִים, \u0010y18\u0011 דְּהַשְׁתָּא הָוֵי \u0010g26\u0011 \u0010t11\u0011 \u0010r15\u0011 אוֹרְחֵהּ; אֲבָל אִם אֵין בּוֹ זֵרְעוֹנִים הָוֵי שִׁנּוּי, וְלֹא דַּיָּנִין לֵהּ הַשְׁתָּא. \u0010y19\u0011 \u0010g27\u0011\nהַתַּרְנְגוֹלִים מוּעָדִים לְהַלֵּךְ כְּדַרְכָּן וּלְשַׁבֵּר. \u0005(אוֹ)\u0006 הָיָה חוּט אוֹ רְצוּעָה קָשׁוּר בְּרַגְלֵיהֶם, וְנִסְתַּבֵּךְ כְּלִי בְּאוֹתוֹ הַחוּט וְנִתְגַּלְגֵּל וְנִשְׁבַּר, מְשַׁלֵּם חֲצִי נֶזֶק. \u0005הַגָּה: \u0010g28\u0011 זֶהוּ לָשׁוֹן הָרַמְבַּ\"ם, וְהוּא סָתוּם; \u0010r16\u0011 אֲבָל אֲחֵרִים כָּתְבוּ: \u0010g29\u0011 הָיָה חוּט אוֹ מְשִׁיחָה קְשׁוּרָה בְּרַגְלֶיהָ, \u0010r17\u0011 אִם גָּרְרָה וְשִׁבְּרָה בּוֹ כְּלִי דֶרֶךְ הִלּוּכָהּ, \u0010y20\u0011 מְשַׁלֵּם נֶזֶק \u0010t12\u0011 שָׁלֵם; \u0010y21\u0011 זְרָקוֹ וְשָׁבַר בּוֹ, מְשַׁלֵּם חֲצִי נֶזֶק. \u0010r18\u0011 (וְאִם הִזִּיק אַחַר שֶׁנָּח, \u0010g30\u0011 פָּטוּר)\u0006 \u0010g31\u0011 \u0010r19\u0011 בַּמֶּה דְּבָרִים אֲמוּרִים, בְּחוּט שֶׁל הֶפְקֵר אוֹ שֶׁיֵּשׁ לוֹ בְּעָלִים וְהִצְנִיעוֹ וְנִקְשַׁר מֵאֵלָיו; \u0010g32\u0011 אֲבָל אִם הַחוּט שֶׁל בַּעַל הַתַּרְנְגוֹל וְלֹא הִצְנִיעוֹ, אֲפִלּוּ נִקְשַׁר מֵאֵלָיו וְשָׁבַר עַל יְדֵי זְרִיקָה, חַיָּב נֶזֶק שָׁלֵם \u0005(טוּר ס\"ג)\u0006, דַּחֲצִי נֵזֶק דִּצְרוֹרוֹת אֵינוֹ \u0010y22\u0011 אֶלָּא בְּהִתִּיזָה דְּבַר הֶפְקֵר, אֲבָל אִם הִתִּיזָה דָבָר \u0010g33\u0011 \u0005(שֶׁיֵּשׁ לוֹ בְּעָלִים)\u0006 וְלֹא הִצְנִיעוֹ, חַיָּב נֶזֶק שָׁלֵם. \u0010g34\u0011 \u0010r20\u0011 וְאִם הַחוּט שֶׁל אֲחֵרִים, \u0010y23\u0011 בַּעַל הַחוּט \u0010t13\u0011 חַיָּב, בֵּין הִזִּיק הַתַּרְנְגוֹל דֶּרֶךְ גְּרִירָה אוֹ דֶרֶךְ זְרִיקָה, הוֹאִיל וְלֹא הִצְנִיעַ חוּט שֶׁלּוֹ. וְאִם הִזִּיק הַחוּט לְאַחַר שֶׁנָּח, \u0010g35\u0011 חַיָּב מִשּׁוּם \u0010y24\u0011 בּוֹר \u0010t14\u0011 הַמִּתְגַּלְגֵּל. \u0010g36\u0011 בַּמֶּה דְּבָרִים אֲמוּרִים, בְּתַרְנְגוֹל שֶׁל הֶפְקֵר; אֲבָל אִם יֵשׁ לַתַּרְנְגוֹל בְּעָלִים, אִם הִזִּיק דֶּרֶךְ גְּרִירָה \u0010y25\u0011 שְׁנֵיהֶם מְשַׁלְּמִין \u0010t15\u0011 בְּיַחַד. וְאִם הִזִּיק דֶּרֶךְ זְרִיקָה, \u0010y26\u0011 בַּעַל הַתַּרְנְגוֹל נוֹתֵן \u0010t16\u0011 רְבִיעַ וּבַעַל הַחוּט שְׁלֹשָׁה חֲלָקִים. \u0010y27\u0011 \u0010r21\u0011 וְאִם הִזִּיק לְאַחַר שֶׁנָּח, בַּעַל הַתַּרְנְגוֹל פָּטוּר וּבַעַל הַחוּט חַיָּב הַכֹּל. \u0010r22\u0011 \u0005(וְעַיֵּן לְקַמָּן סִימָן תי\"א יִתְבָּאֵר בְּדִינֵי בוֹר)\u0006. \u0010r23\u0011 וְכָל זֶה בְּנִקְשַׁר \u0010g37\u0011 מֵאֵלָיו, אֲבָל אִם קְשָׁרוֹ אָדָם בְּרֶגֶל הַתַּרְנְגוֹל אָז הַקּוֹשֵׁר \u0010r24\u0011 חַיָּב בְּכָל עִנְיָן, \u0010y28\u0011 \u0010g38\u0011 \u0010r25\u0011 אֲפִלּוּ יֵשׁ לַחוּט בְּעָלִים \u0005(טוּר)\u0006. \u0010r26\u0011 וְהוּא הַדִּין אִם הָיָה הַחוּט מֻנָּח בְּמָקוֹם מֻצְנָע, וְהִנִּיחַ אָדָם בִּמְקוֹם תֻּרְפָּה וְעַל יְדֵי זֶה נִקְשַׁר בַּתַּרְנְגוֹל, הָוֵי כְּאִלּוּ קְשָׁרוֹ בְּיָדַיִם \u0005(בֵּית יוֹסֵף בְּשֵׁם הַתּוֹסָפוֹת שָׁם וּבְשֵׁם הָרֹא\"שׁ)\u0006. \u0010g39\u0011\nתַּרְנְגוֹל שֶׁהָיָה מְחַטֵּט בְּחֶבֶל דְּלִי וְנִפְסַק הַחֶבֶל וְנִשְׁבַּר הַדְּלִי, אִם \u0010g40\u0011 עִסָה דְבוּקָה בַּחֶבֶל דְּהַשְׁתָּא \u0010y29\u0011 \u0010r27\u0011 אוֹרְחֵהּ הוּא, אוֹ אֲפִלּוּ אֵין בּוֹ \u0010g41\u0011 עִסָה וְהוּא בָלוּי שֶׁדַּרְכּוֹ לִפָּסֵק עַל יְדֵי חַטִּיטַת הַתַּרְנְגוֹל, \u0010r28\u0011 חַיָּב בֵּין עַל הַחֶבֶל בֵּין עַל הַדְּלִי נֶזֶק שָׁלֵם. \u0010g42\u0011 \u0010r29\u0011 וְאִם הַחֶבֶל חָדָשׁ וְאֵין עִסָה דְּבוּקָה בּוֹ, מְשֻׁנֶּה הוּא וְאֵינוֹ חַיָּב אֶלָּא חֲצִי נֶזֶק בֵּין עַל הַחֶבֶל בֵּין עַל הַדְּלִי, \u0010y30\u0011 \u0010g43\u0011 \u0010r30\u0011 וְאִם הוּא \u0010t17\u0011 הוֹלֵךְ אַחַר הַדְּלִי וּמְגַלְגְּלוֹ עַד הַמָּקוֹם שֶׁנִּשְׁבַּר שָׁם, \u0010r31\u0011 מְשַׁלֵּם נֶזֶק שָׁלֵם. \u0010g44\u0011\nהַכֶּלֶב וְהַגְּדִי שֶׁקָּפְצוּ מֵרֹאשׁ הַגַּג מִלְמַעְלָה לְמַטָּה וְשָׁבְרוּ אֶת הַכֵּלִים, מְשַׁלְּמִים נֶזֶק שָׁלֵם \u0010y31\u0011 מִפְּנֵי שֶׁמּוּעָדִים הֵם לְדָבָר זֶה. \u0010g45\u0011 וְכֵן אִם נָפְלוּ וְהִזִּיקוּ, שֶׁעֲלִיָּתָן לְרֹאשׁ הַגַּג פְּשִׁיעָה; וְאַף עַל פִּי שֶׁנְּפִילָתָן \u0010y32\u0011 \u0010r32\u0011 אֹנֶס, כָּל שֶׁתְּחִלָּתוֹ בִּפְשִׁיעָה וְסוֹפוֹ \u0010t18\u0011 בְּאֹנֶס, חַיָּב. \u0005הַגָּה: \u0010g46\u0011 \u0010r33\u0011 וְיֵשׁ אוֹמְרִים דְּאִם הָיוּ הַכֵּלִים סְמוּכִים לַכֹּתֶל, שֶׁאֵין רְאוּיִין לִשָּׁבֵר עַל יְדֵי קְפִיצָה, וְנָפְלוּ, פָּטוּר, דְּאֹנֶס הוּא. \u0010r34\u0011 וְאִם הַכְּלִי אָרֹךְ וְרֹאשׁוֹ אֶחָד קָרוֹב לַכֹּתֶל וְרֹאשׁ הַשֵּׁנִי רָחוֹק בְּעִנְיָן שֶׁרָאוּי לִשָּׁבֵר עַל יְדֵי קְפִיצָה, וְנָפְלוּ קָרוֹב לַכֹּתֶל וְשָׁבְרוּ, חַיָּב, דִּתְחִלָּתוֹ בִּפְשִׁיעָה עַל יְדֵי קְפִיצָה. \u0010g47\u0011 \u0010r35\u0011 וְאִם הַכֹּתֶל צַר, אֲפִלּוּ קְרוֹבִים לַכֹּתֶל וְנָפְלוּ, \u0010y33\u0011 חַיָּב, וְהוּא שֶׁקָּפְצוּ כְּדַרְכָּם; \u0010g48\u0011 \u0010r36\u0011 אֲבָל אִם קָפַץ הַכֶּלֶב בִּרְקִידָה וְהַגְּדִי נִסְרַךְ, דְּהָוֵי \u0010y34\u0011 שִׁנּוּי גַבַּיְהוּ, אֵין מְשַׁלְּמִין אֶלָּא \u0010t19\u0011 חֲצִי נֶזֶק (טוּר ס\"א)\u0006. \u0010g49\u0011 \u0010r37\u0011 קָפְצוּ מִלְּמַטָּה לְמַעְלָה, מְשַׁלְּמִים חֲצִי נֶזֶק. \u0010y35\u0011 \u0005וְהוּא\u0006 שֶׁנִּתְלָה הַגְּדִי \u0010g50\u0011 וְנִסְרַךְ, וְקָפַץ הַכֶּלֶב. אֲבָל נִסְרַךְ הַכֶּלֶב, וְדִלֵּג הַגְּדִי, בֵּין מִלְמַעְלָה לְמַטָּה בֵּין מִלְּמַטָּה לְמַעְלָה, חַיָּבִים נֶזֶק שָׁלֵם. \u0010g51\u0011 וְכֵן תַּרְנְגוֹל שֶׁדִּלֵג בֵּין מִלְמַעְלָה לְמַטָּה בֵּין מִלְּמַטָּה לְמַעְלָה, מְשַׁלֵּם נֶזֶק שָׁלֵם. \u0010g52\u0011 \u0010r38\u0011 וְהוּא הַדִּין מִי שֶׁמָּסַר בֵּיתוֹ \u0010y36\u0011 לְשָׁמְרוֹ וְהָיוּ בּוֹ \u0010t20\u0011 חֵרֵשׁ שׁוֹטֶה וְקָטָן, צָרִיךְ לְשָׁמְרָם שֶׁלֹּא יְדַלְּגוּ מִלְמַעְלָה לְמַטָּה וְלֹא מִלְּמַטָּה לְמַעְלָה:",{"g":["א) לשון הטור וכ\"כ הרמב\"ם שם בפרק א' ד\"י ברייתא בריש ב\"ק סוף ד' ב'","ב) שם דף ג' ע\"א","ג) לשון הרמב\"ם ספ\"ק מה' נזקי ממון בעיא ולא אפשיטא שם (דף יט ע\"א) וכ' ה\"ה ויש מי שסובר שנפשטא וכו' דהא כי הדר וכי יאחזנה בזנבו וילך אפילו אכשכוש יתר קאי (וכן כתב הטור בשם אביו הרא\"ש והביאו הרמ\"ה בהג\"ה) ואין כן דעת הר\"ב ז\"ל אלא שהמשיב היה סבור שעל כשכוש כדרכו הוא שואל","ד) בעיא דרב עינא שם ולא איפשיטא","ה) כתב ה\"ה פסק כדרכו ז\"ל בכל תיקו דממונא מלבד קצת מקומות שיש טעם למה לא כתב כן","ו) כ\"כ ה\"ה שם בשם הרמב\"ן שכל תיקו שנסתפק לנו בגמרא מחמת הדין בעצמו לא מחמת הכחשה כיון בדינו לקולא לנתבע בין תפס בעדים בין שלא בעדים מוציאין מידו זהו דעתו","ז) דס\"ל דאיפשט' אבעיא ומבואר במ\"ש לעיל","ח) שם פ\"ב דין ב' ושם בגמרא דף ג' ע\"ב וכי קאמר רב פפא אתולדה דרגל וכו' לרב פפא פשיטא ליה וכו'","ט) מבואר שם משנה דף י\"ז ע\"א ושם בגמ' דף י\"ט ע\"א","י) שם ד\"ד וכתב ה\"ה מבואר שם בפ\"ב (שם) בבעיא דרבי ירמיה ומהכרח ברייתות","כ) ל' הטור ס\"ב","\u0003ל) ברייתא שם דף י\"ז ע\"ב וכתנא קמא:\u0004 ","מ) ברייתא שם וכת\"ק","פי' מעלה עפר וצרורות בחוטמו יכרסמנה חזיר מיער תרגומו ינוברינה","נ) ל' הרמב\"ם שם משנה שם ע\"א","ס) למעט רה\"ר וכן הוא בברייתא שם דף י\"ט ע\"א","ע) דהשני מקרי ח\"נ צרורות","פ) כן כתב הרא\"ש שם בפסקיו מבעיא דרב אשי כח כחו","\u0003צ) בעיא שם ונפשטא בדף י\"ח ע\"א לסומכוס וכו'\u0004 ","\u0003ק) שם ד\"ד ושם ד' י\"ט ע\"א רב אשי כרבנן מוקי לה ובעי לה הכי וכו'\u0004 ועלתה בתיקו ופסק בה כדרכו בכל תיקו דממונא כמ\"ש בס\"ב","ר) שם ד\"ו כתב ה\"ה שלמדן מבעיא דלעיל וסובר הרב ז\"ל דאי אמר יש שינוי משמע קולא וחומרא קולא דאפי' ברשות הניזק רביע ותו לא חומרא דאפי' בר\"ה משלם רביע הנזק דהויא לה כתולדה דקרן דכי אמרינן צרורות תולדה דרגל ופטורין בר\"ה דוקא כדרכן אבל ע\"י שינוי אי אמרינן יש שינוי לצרורות אפי' בר\"ה חייב ואינו משלם אלא רביע הנזק וכו' ואי אמרי' אין שינוי בר\"ה פטורין לגמרי ואפילו כשלא כדרכן כגון מחמת ביעוט וברשות הניזק ס\"ב ועלתה שאלה זו בתיקו","ש) לעיל ס\"ב","\u0003ת) טור ס\"ב פלוגתא דר\"י ור\"א דף י\"ח ע\"ב ומוקי בגמ' דר\"א דאמר חצי נזק כרבנן:\u0004 ","א) אוקימתא דגמרא שם","\u0003ב) שם מימרא דרב יוסף אמרי בי רב כו'\u0004 וכדמוקילה ריש דף י\"ט דסברי כרבנן","ג) אוקימתא דגמרא שם","פירוש דהושיט ראשו כדי לאכלו","ד) ל' הרמב\"ם ד\"י משנה שם דף י\"ז ע\"א","ה) המחבר ב\"י השמיט לחילוקי דינים כאלו שכתב הרמב\"ם בדין לעיל כי הושג באלו הדינין מהראב\"ד ז\"ל וגם ה\"ה לא מצא לו עזר בזה וכתב זה כתב על הסוגיא האמורה על משנה זה (שם דף י\"ט ע\"ב) ואינו יודע למה לפי גירסת ספרינו וכבר הושג מזה ע\"כ אבל בבבא דלעיל שהעתיק המחבר לא הושג שם ונלע\"ד שזו היא מ\"ש שם אלא מתני' בדאדיה אדויי ופירש בה הרמב\"ם שנסתבך בחוט ונתגלגל ונשבר במקום אחר ושזהו צרורות וחייב בחצי נזק ולא הושג אלא במ\"ש בד\"א שקשרו אדם וכו' מה שלא ביאר המחבר לנו פרטי הדינים לפי שיטת הגמרא שלפנינו וכשיטת התוס' והרא\"ש וכמו שכתבם הטור הביאם הרב רמ\"א נלע\"ד שסמך בדעתו שדינים אלו אינם שכיחים וכמ\"ש בב\"י שהרי\"ף השמיט מימרא דרב הונא נפי שאינו מצוי כל כך ע\"כ ואפשר שכן היה בספריו אבל בספרי הרי\"ף שלפנינו איתא להא דרב הונא","ו) ממשנה שם וכמ\"ש שם בגמ' אלא מתני' דאדיי אדיי","ז) וכן הוא שם בפסקיו וטור וביאר שם דכתיב כי יכרה איש בור ולא שור בור","ח) כ\"כ שם בפסקיו וכן פי' התוס' שם","\u0003ט) כן כתוב ברא\"ש שם:\u0004 ","י) כצ\"ל וכן הוא בפסקיו ממון הבעלים וכ\"צ להגיה בכל הטורים","כ) כ\"כ התוס' והרא\"ש שם","ל) וכתב הטור בשם הרמ\"ה ונפקא מיניה לפטור בו את הכלים","מ) כן כתב הרא\"ש שם בפסקיו","נ) מימרא דרב הונא שם","ס) וכתבו התוספת ואפי' לא נתכוין לזכות בו וכ\"כ הרא\"ש שם מידי דהוי אהיפך את הגלל (שם דף ל' ע\"א) דאפי' לא נתכוין לזכות בו ואפשר שזה הוא כוונת הרב רמ\"א שכתב בכל ענין","ע) ל' הטור ס\"ד מברייתא שם ריש דף יח","פ) אוקימתא דגמ' שם","צ) כן פי' התוס' והרא\"ש שם וכ\"כ ה\"ה שם בשם חידושי הרשב\"א","\u0003ק) מסוגיא דגמרא ופי' התוספת והרא\"ש שם:\u0004 ","\u0003ר) אוקימתא דרב ביבי בר אביי שם והרמב\"ם שם דין י\"ד כ' לדין זה המחטט וכו'\u0004 בל' אחר וכתב ה\"ה שכך היא שיטת הרשב\"א ז\"ל","\u0003ש) ל' הרמב\"ם שם דף ט\"ו משנה שם דף כ\"א ע\"ב:\u0004 ","\u0003ת) מבואר בגמ' שם:\u0004 ","א) כ\"כ התוס' שם והרא\"ש מברייתא ואוקימת' דגמ' שם עוד כתבו התוס' שם שאם היה לא מקורבות ולא מרוחקות מחברי בין בנפילה בין בקפיצה ולענ\"ד י\"ל דבהכי מיירי הרמב\"ם והרי\"ף שלא חילקו בזה בין שהיו סמוכין לכותל או רחוקים או שהיה להם גירסא אחרת כמ\"ש ה\"ה:","ב) אוקימתא דגמ' שם","ג) מבואר במ\"ש בסמוך","ד) שם דף ט\"ז וכתב ה\"ה הוא כפי גי' ההלכות מברייתא שם וכדמתרגמא ר\"פ שם ריש דף כ\"ב","פירוש שנועץ צפרניו בכותל ואין דרכן בכך ומשונ' הם","ה) שם בבריי' סוף דף כ\"א","ו) טור ס\"ו כ\"כ התוספת שם בד\"ה אדם ותרנגול וכן כתב הרא\"ש שם וש\"פ"],"t":["\u0003בשערה. \u0004 פירוש שנסתבך כלי בשערה וגררתו ושברתו. סמ\"ע:","\u0003נקרו. \u0004 פירוש דמאסוהו בנקירתן ולא אכלוהו דאל\"כ ה\"ל תולדה דשן דהא יש לו הנאה באכילתו. שם:","\u0003דדינא. \u0004 היינו בבעיא דלא איפשטא ובזה מודים דאם הזיקה ברשות הניזק דאינו משלם כלל אא\"כ תפס גוף המזיק דוקא ואז ישלם ממנו ח\"נ דכיון דלא איפשטא י\"ל דלא הוי אורחה ותולדה דקרן הוא וקרן אינו משלם אלא ח\"נ מגופו והטור מסיק בזה וכת' וז\"ל ואפילו אם הזיק לאדם אחד בר\"ה וברשות הניזק דינא הכי וא\"י לו' ממ\"נ אם תאמר שהוא קרן תתחייב לי ג\"כ בר\"ה וא\"ת שהוא רגל תן לי נ\"ש היזקא דרשות הניזק אלא בשניהן להקל עכ\"ל ואע\"ג דבסי' ר' כת' הטור גבי כליו של לוקח ברשות מוכר כו' דאם קנה אחד מחבירו בשניהן דקנה אחד מהן בממ\"נ שאני הכא דהוא ענין דקנסא דהא גופו לא הזיק אלא שורו שהוא ממונו מש\"ה הולכין בשניהן להקל עכ\"ל הסמ\"ע ואין לזה טעם כלל וכבר השיג עליו הב\"ח אך מ\"ש הב\"ח דמיירי בב' בהמות שהזיקו לא נהירא אלא נראה דאף בבהמה אחת כיון דמיבעיא אי אורחא הוא ואין כוונתה להזיק או כוונתה להזיק והוי קרן א\"כ י\"ל דלמא טבע הבהמה פעמים כך ולפעמים כך. ודלמא בר\"ה הזיקה דרך הילוכה כי אורחה ולא היה כונתה להזיק וברשות הניזק היה כונתה להזיק וקרן הוא ודו\"ק כן נ\"ל ברור. ש\"ך:","\u0003מסיני. \u0004 פירוש אע\"פ שהדברים נראין כסותרין זא\"ז שיש לו דין רגל לענין פטור בר\"ה ולענין חיוב תשלומין מנכסיו יש לו דין קרן שאינו משלם אלא ח\"נ אף ברשות הניזק. מש\"ה כת' דהל\"מ כן הוא ואין להרהר אחריה. סמ\"ע:","\u0003משלם. \u0004 קמ\"ל בזה דאע\"ג דצרורות דין רגל יש לו ופטור על היזקו בר\"ה מ\"מ כיון דנתזו משם לרשות הניזק בתר הניזק אזלינן וחייב. שם:","\u0003שהדסו. \u0004 שכל דאורחא הוא והניזק בא מכחו דין צרורות יש לו. שם:","\u0003והעלו. \u0004 פירוש ברשות הניזק או בר\"ה ונתזו לרשות הניזק והזיקו. שם:","\u0003שלם. \u0004 כיון דהשבירה באה מכח הדריסה על הכלי עצמו הולכין אחר התחלתו דהוי רגל עצמו ולא מצרורות משא\"כ בס\"ב אם היתה מהלכת בר\"ה כו' דאזלינן בתר המקום שנשבר שם כנ\"ל. שם:","\u0003רביע. \u0004 היינו כשתפס גוף השור המזיק דרביע נזק זה הוא חצי דין קרן דתם ואינו משתלם אלא מגופו. שם:","\u0003לשלם. \u0004 בזה ג\"כ אינו משלם הרביע אלא מגוף המזיק רק אם תפס החצי אפילו תפס דבר אחר אין מוציאין מידו דיכול לו' אין שינוי לצרורות והוי תולדה דרגל ומשתלם ברשות הניזק חציו אפילו מכיסו דהמזיק. שם:","\u0003שינוי. \u0004 דאין דרך הבהמה להטיל גללים לעיסה. שם:","\u0003אורחיה. \u0004 פירוש כל שאורחיה להושיט שם ראשו רגיל ג\"כ לצעוק ולתקוע. שם:","\u0003שלם. \u0004 דהוי רגל ובזרק כתב דה\"ל צרורות ומשלם ח\"נ. שם:","\u0003חייב. \u0004 פירוש כל הנזק דה\"ל לשמור חוטו שלא יסתבך בו תרנגול של הפקר. שם:","\u0003המתגלגל. \u0004 פירוש אף שלא הניחו בעל החוט במקום שהזיק מ\"מ יש להחוט דין בור שנתגלגל ממקום שהניחו למקום שנח עתה ע\"י התרנגול והזיק. שם:","\u0003ביחד. \u0004 דגם בעל התרנגול פשע דה\"ל לשמור התרנגול. שם:","\u0003רביע. \u0004 דזריקה דתרנגול ה\"ל כצרורות דשור דאינו משלם אלא ח\"נ והשתא דאיכא בעל החוט בהדיה אין עליו רק חצי חיובו דהוא רביע הנזק וג' חלקים על בעל החוט דהא אי הוה הוא לבדו כגון בתרנגול הפקר היה צריך לשלם כולו. שם:","\u0003הולך. \u0004 אבל אם אינו הולך אחר הדלי אינו משלם אלא חצי נזק ול\"ד למ\"ש בס\"ה בהג\"ה בדרסה על הכלי ונתגלגל כו' דאזלינן בתר התחלת הדריסה וה\"ל רגל וחייב נ\"ש דשאני דריסה דאורחיה הוא משא\"כ פסיקת חבל חדש כזה דשינוי הוא שם:","\u0003באונס. \u0004 וזהו אונס הבא מחמת הפשיעה דאילו שמרם לא היו באין לידי נפילה ומיהו אין דרכן לקפוץ אלא רחוק קצת מהכותל ומש\"ה אם היו כלים סמוכים לכותל דתו לא פשע מתחלה כיון שאין דרכן ליפול ובקפיצתן א\"י להשתבר מש\"ה כת' הרמ\"א דאם נפלו והזיקו פטור. שם:","\u0003חצי. \u0004 ואין אומרים בזה שיחייב נזק שלם כיון שפשע מתחלה לענין קפיצה כדרכן דהא מ\"מ התורה לא חייבה בהוזק ע\"י שינוי אלא ח\"נ דומיא דקרן בתם ומשום דלאו אורחיה הוא ה\"ל שינוי לגבייהו. שם:","\u0003חש\"ו. \u0004 דאילו עבדו אינו חייב על נזקו כמ\"ש בסי' שמ\"ט ס\"ד ע\"ש ואם הוא עצמו הזיק כבר נתבאר דאדם מועד לעולם בין ער בין ישן על כל מה שיזיק. שם:"],"r":["\u0003בדרך הילוכה. \u0004 מתני' טו ב' יז א' ב':","\u0003והוא כו'. \u0004 ב' ב' ג' א' רגל הזיקה מנוי כו':","\u0003ואין כו'. \u0004 שם ושם שהנאה להזיקה הוא שן ותולד':","\u0003וכל כו'. \u0004 ב' א':","\u0003כגון כו'. \u0004 שם וי\"ז ב':","\u0003או במשוי כו' ותרנגולים כו'. \u0004 י\"ז ב':","\u0003ודינם כו'. \u0004 ג' א':","\u0003ואם תפס כו' וי\"א כו'. \u0004 כמ\"ש בסי' שפח:","\u0003ולדעת כו'. \u0004 וכ\"כ הרשב\"א ועבה\"ג. אבל הרמב\"ם סובר כיון דפריך וכי מאחר כו' אלמא כשכוש יתירא לאו אורחיה הוא והדק\"ל א\"ה קרן נמי כו' והרא\"ש כ' דפשיט ליה וכי כו' דאפילו כשכוש יתירא אורחא הוא אלא דגמ' פריך בכשכוש כדרכה האיך ס\"ד למיבעי כלל:","\u0003ופטור כו'. \u0004 ג' ב' י\"ט א':","\u0003ואם כו'. \u0004 ג' ב' וכר\"פ דבתרא הוא ועוד לא שבקינן פשוטותיה משום ספיקא דרבא:\n\u0003 (ליקוט) משלם מהיפה כו'. \u0004 מדקא' סתמא דגמ' שם ואמאי כו' לר\"פ פשיטא ליה ואע\"ג שי\"ל דגם ר\"פ ס\"ל כרבא ולפוטרו ברה\"ר (ע\"כ):","\u0003ודבר כו'. \u0004 שם:","\u0003יש כו'. \u0004 מדלא איבעיא לרב אשי י\"ט א' בכח כחו אלא לסומכוס מ' דלרבנן פשיטא ליה ולא מיבעיא לסומכוס אלא אי גמר הלכה כו' וא\"ל דפשיטא ליה דלאו ככחו הוא אלא משום הלכה דהא הלכתא לגרע אתי כמ\"ש בפ\"ק דסוכה לכל התי' רק לחד תי' אליבא דר\"ש וז\"ש שם יז ב' לעולם כגופו כו' ול\"ק לעולם לאו כגופו כו'. הרא\"ש. וכנ\"ל מדקא' שם יח א' אי סומכוס אימא סיפא כו' מ' דלרבנן ניחא ומסיפא לבד יכול לפשוט. אבל הרמב\"ם לא ס\"ל כן כמ\"ש בסי' שצב בש\"ע וכ\"כ כאן הרא\"ש בשם התוס' ועתוס' ך\"ב א' ד\"ה ור\"י כו':","\u0003דרסה כו'. \u0004 יז ב' תפשוט כו' וכמ\"ש בסי' שפו ס\"ד:","\u0003חייב לשלם כו'. \u0004 ובזה\"ז פטור לגמרי בלא תפס:","\u0003אבל כו'. \u0004 ותליא בפלוגתא הנ\"ל דס\"ז אם תפס אי משלם ח\"נ או רביע נזק. רא\"ש. והרמב\"ם ס\"ל דאין כאן ספק אלא תולדה דקרן ומשלם ח\"נ. והרשב\"א כ' שדעת הרי\"ף באית בזרוני שמשלם נזק שלם כמ\"ש בדברי הרי\"ף דלא כמו שדחק הרא\"ש בדבריו וכ' דכיון דאוקמוה באית כו' לאו משום צרורות וכ\"ה בירושלמי תרנגול כו' ברוח שבין כנפיו משלם ח\"נ סומכוס אומר נ\"ש נפח בכלי ושברה משלם נ\"ש מ' דכ\"ע היא. וצ\"ל דהרי\"ף גרס בגמ' אלא דאית כו':","\u0003אבל אחרים כו'. \u0004 כ\"ז דברי הרא\"ש והטור וכשיטת התוס' שם:","\u0003אם גררה כו' זרקה כו'. \u0004 שם בדאדיה אדויי מ' הא בגררה נ\"ש כיון דמחובר בגופה כמו עגלה המושכת בקרון:","\u0003ואם הזיק כו'. \u0004 שם אלא חייב בעל התרנגול כו' ושם אר\"ה נקשר כו' וכמ\"ש תוס' בד\"ה נקשר כו':","\u0003בד\"א כו' או כו'. \u0004 תוס' ד\"ה אלא כו'. ר\"ל דמ\"ש אלא מתני' קאי אאצנעיה וכן בהפקר כמ\"ש בדברי ר\"ה דאי בדלא אצנעיה חייב נ\"ש כמ\"ש ואי דלא כו' וערש\"י ד\"ה פושע כו' וה\"ה באדיה או גרריה משום בור המתגלגל שם ו' א' דפריך אי בהדי דאזלי כו' ועתוס' שם ד\"ה לאתויי כו' וז\"ש אבל אם החוט כו' וכ\"ש בתר דנייח כמש\"ש ואי דלא אצנעיה כו':","\u0003ואם החוט של אחרים כו'. \u0004 כמש\"ש ואי דלא אצנעיה כו'. וה\"ה בשעת הילוך משום אש כמש\"ש ג' ב' תולדה דאש כו' בהדי דאזלי כו' וה\"ה כאן שהתרנגול כרוח מצוייה הוא ועתוס' ד\"ה וכי. וקשה כו' ומה שפריך שם ו' א' אי בהדי דאזלי כו' כבר פי' תוס' שם דר\"ל ליחייב גם בעל הבהמה ולכן לא אוקמיה מילתיה דרב הונא אמתני' כמ\"ש תוס' בד\"ה וכי כו' וך\"ג א' סד\"ה וליחייב וז\"ש אבל אם יש כו' ואם הזיק כו'. דקי\"ל כר\"נ שם נג א':","\u0003ואם הזיק לאחר כו'. \u0004 שם ב' א\"ד אמר אביי כו' הא כרבנן כו':","\u0003וע\"ל כו'. \u0004 סל\"ב וסל\"ד:","\u0003וכ\"ז כו' אבל אם כו'. \u0004 שם:","\u0003אפי' יש כו'. \u0004 דל\"ק דליל הפקר אלא משום נקשר מאליו וכמש\"ש ך\"ט ב' בהופך את הגלל אע\"פ שהחזירה למקומו דאסתלקי כו':","\u0003בכל ענין. \u0004 ר\"ל במקום בעל דליל אבל בחלק של בעל תרנגול אינו חייב וכמ\"ש תוס' ד\"ה וכי כו' דלא מתוקמא כו' וז\"ש אפי' יש כו' ר\"ל לענין זה דוקא והסמ\"ע שגה בזה:","\u0003וה\"ה אם כו'. \u0004 תוס' ד\"ה קשרו כו':","\u0003או אפילו כו'. \u0004 כפי' הראשון בתוס' שם ד\"ה והא כו' וכ\"כ ש\"פ:","\u0003בין כו'. \u0004 כמ\"ש בס\"ה בהג\"ה:","\u0003ואם כו'. \u0004 גמ' שם:","\u0003ואם הוא הולך כו'. \u0004 שם א\"ר ביבי כו' והביאו הרי\"ף וכ' מדל\"ק לא דקאזיל כו' אלמא לאו לדחיה אמרה ופי' הרא\"ש דבחבל שאינו דבוק בו עיסה ואינו בלוי דכה\"ג לאו משונה היא וכמש\"ש י\"ט ב' כיון דאורחיה למיכל כו':","\u0003משלם נ\"ש. \u0004 גם על החבל כנ\"ל כיון דאורחיה כו'. הרא\"ש בלישנא בתרא:","\u0003כל שתחילתו כו'. \u0004 שם וכמ\"ש בסי' רצא ס\"ו:","\u0003וי\"א כו'. \u0004 גמ' שם כגון כו':","\u0003ואם הכלי כו'. \u0004 תוס' שם ד\"ה הא. א\"כ כו':","\u0003ואם כו'. \u0004 שם פעמים כו'. ונ\"מ לדידן במקרבי לכותל:","\u0003אבל כו'. \u0004 גמ' שם לגי' שלנו אבל גי' הרי\"ף והרמב\"ם והתניא הכלב והגדי שדלגו בין כו' חייבין תרגמא כו' ור\"ל דברייתא ראשונה בדאפיך כו' ובזה מתורץ קושית תוס' ד\"ה והתניא כו' וז\"ש בש\"ע קפצו כו' אבל כו'. אבל לשיטת התוס' והרא\"ש מלמטה למעלה בכ\"ע פטורין לגמרי אפי' מח\"נ ועתוס' שם ד\"ה אדם כו' ואית דגרסי כו' וכצ\"ל ג\"כ לגי' הרי\"ף ורמב\"ם:","\u0003 (ליקוט) קפצו כו'. \u0004 כשיטת הרי\"ף ולשיטתו מתי' קושית תוס' ד\"ה והתניא כו' ואתי שפיר נמי מ\"ש שם אי הכי כו' כמש\"ש תוס' בד\"ה אדם כו' דבל\"ז ה\"א מ\"ש פטורין משום דמלמטה למעלה אונס הוא ע\"ש בתוס' משא\"כ לפי' תוס' דוחק לומר דמלמעלה למטה ג\"כ אונס הוא (ע\"כ):","\u0003וה\"ה מי כו'. \u0004 גמ' שם וכפי' תוס' בד\"ה הנ\"ל:"]}],["שֵׁן הִיא אָב, \u0010y0\u0011 דִּוְשִׁלַּח אֶת בְּעִירֹה \u0005(וּבִעֵר)\u0006 דִּכְתִיב בַּקְּרָא, מוֹקְמֵינָן לָהּ \u0010y1\u0011 נַמֵּי בִּבְהֵמָה שֶׁאוֹכֶלֶת פֵּרוֹת חֲבֵרוֹ דְּבָרִים הָרְאוּיִים לָהּ וְנֶהֱנֵית בַּאֲכִילָתָן חַיָּב נֶזֶק שָׁלֵם, בֵּין שֶׁאֲכָלָתָן בֵּין שֶׁלֹּא אֲכָלָתָן אֶלָּא שֶׁהִפְסִידָתָן \u0010y2\u0011 וְלֹא כִּלְּתָה אוֹתָם לְגַמְרֵי. לְפִיכָךְ, כָּל הַדּוֹמֶה לְזֶה, שֶׁמַּזִּיק בְּדָבָר שֶׁהִיא נֶהֱנֵית, הוּא תּוֹלָדָה דְשֵׁן; כְּגוֹן \u0010y3\u0011 נִתְחַכְּכָה בַכֹּתֶל לַהֲנָאָתָהּ וְהִזִּיקָה, אוֹ שֶׁטִּנְּפָה פֵרוֹת וְכֵלִים לַהֲנָאָתָהּ, כְּגוֹן שֶׁנִּתְגַּלְגְּלָה עֲלֵיהֶם:\nבַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁאָכְלָה דָּבָר הָרָאוּי לָהּ. אֲבָל אָכְלָה דָּבָר שֶׁאֵין רָאוּי לָהּ, כְּגוֹן כְּסוּת וְכֵלִים, שִׁנּוּי הוּא וְאֵינוֹ מְשַׁלֵּם אֶלָּא חֲצִי נֶזֶק, \u0010y4\u0011 בֵּין שֶׁאָכְלָה אוֹתָם בַּחֲצַר הַנִּזָּק בֵּין שֶׁאָכְלָה אוֹתָם בִּרְשׁוּת הָרַבִּים.\nאָכְלָה דָּבָר שֶׁאֵין דַּרְכָּהּ לֶאֱכֹל אֶלָּא עַל יְדֵי הַדְּחַק, כְּגוֹן פָּרָה שֶׁאָכְלָה שְׂעוֹרִים, וַחֲמוֹר שֶׁאָכַל כַּרְשִׁינִין, וְכֶלֶב שֶׁלָּקַק אֶת הַשֶּׁמֶן, וַחֲזִיר שֶׁאָכַל חֲתִיכַת בָּשָׂר, וְחָתוּל שֶׁאָכַל תְּמָרִים, חָשִׁיב שַׁפִּיר אֲכִילָה. אֲבָל בְּהֵמָה שֶׁאָכְלָה בָּשָׂר אוֹ תַבְשִׁיל, לָאו אֹרְחָא הוּא, וּמְשַׁלֵּם חֲצִי נֶזֶק. אָכְלָה פַּת הָוֵי אֹרְחָא, אֲבָל חַיָּה לָאו אֹרְחָא לֹא בְּפַת וְלֹא בְּתַבְשִׁיל.\nבְּהֵמָה שֶׁרָאֲתָה לֶחֶם בְּסַל, וְשִׁבְּרָה הַסַל וְאָכְלָה הַלֶּחֶם, מְשַׁלֵּם נֶזֶק שָׁלֵם גַּם עַל הַסַל, שֶׁכָּךְ דַּרְכָּהּ לְשַׁבֵּר הַסַל כְּדֵי לֶאֱכֹל הַלֶּחֶם. אֲבָל אִם אָכְלָה הַלֶּחֶם תְּחִלָּה וְאַחַר כָּךְ שָׁבְרָה הַסַל, אֵינוֹ מְשַׁלֵּם עַל הַסַל אֶלָּא חֲצִי נֶזֶק, דְּהָוֵי קֶרֶן וְאֵינוֹ מִשְׁתַּלֵּם אֶלָּא מִגּוּפוֹ.\nרָאֲתָה אֳכָלִים עַל פִּי הֶחָבִית, וְנִסְתַּבְּכָה בֶּחָבִית לַעֲלוֹת כְּדֵי לֶאֱכֹל הָאֳכָלִים וְשִׁבַּרְתּוֹ, מְשַׁלֵּם גַּם עַל הֶחָבִית נֶזֶק שָׁלֵם, שֶׁכֵּן דַּרְכָּם לַעֲלוֹת עָלָיו כְּדֵי \u0010y5\u0011 לֶאֱכֹל הָאֳכָלִים.\nחַיָּה שֶׁטָּרְפָה בְּהֵמָה וַאֲכַלְתָהּ, אוֹ שֶׁאָכְלָה בָּשָׂר חַי, אֹרְחָא הִיא וּמְשַׁלֵּם נֶזֶק שָׁלֵם. אֲבָל כֶּלֶב שֶׁהֵמִית כֶּבֶשׂ, וְחָתוּל שֶׁהֵמִית תַּרְנְגוֹלִים גְּדוֹלִים וַאֲכָלָם, מְשֻׁנֶּה הוּא וְאֵינוֹ מְשַׁלֵּם אֶלָּא חֲצִי נֵזֶק. וְדַוְקָא בִּפְחָת שֶׁפִּחֲתָה מִיתָה, \u0010y6\u0011 אֲבָל דְּמֵי הַנְּבֵלָה מְשַׁלֵּם בִּרְשׁוּת הַנִּזָּק נֶזֶק שָׁלֵם, \u0010y7\u0011 וּבִרְשׁוּת הָרַבִּים מַה שֶּׁנֶּהֱנֵית, שֶׁאֲכִילָה אֵינוֹ שִׁנּוּי, שֶׁכֵּן דַּרְכָּן לֶאֱכֹל נְבֵלוֹת אֲפִלּוּ שֶׁל בְּהֵמוֹת גְּדוֹלוֹת.\nאֵין חַיָּב הַשֵּׁן לְשַׁלֵּם נֶזֶק שָׁלֵם אֶלָּא אִם כֵּן אוֹכֶלֶת \u0010y8\u0011 בִּרְשׁוּת הַנִּזָּק, אֲבָל אִם לָקְחָה בַּחֲצֵרוֹ וְהוֹצִיאָה מִשָּׁם וְאָכְלָה בִּרְשׁוּת הָרַבִּים אוֹ בֶחָצֵר שֶׁל אַחֵר, פָּטוּר מִלְּשַׁלֵּם יוֹתֵר מִמַּה שֶׁנֶּהֱנֵית. וְאִם לָקְחָה בִּרְשׁוּת הָרַבִּים וְהָלְכָה וְאָכְלָה בִּרְשׁוּת הַנִּזָּק, יֵשׁ מְחַיְּבִים לְשַׁלֵּם נֶזֶק שָׁלֵם, מִשּׁוּם \u0010y9\u0011 דְּפִי פָרָה כַּחֲצֵר הַנִּזָּק דָּמֵי; וְנָפְקָא מִנָּהּ אֲפִלּוּ בְּמָקוֹם שֶׁאֵין לְחַיֵּב עַל הַנְּטִילָה, כְּגוֹן שֶׁהָיוּ הַפֵּרוֹת מֻנָּחִים בְּמָקוֹם שֶׁאִי אֶפְשָׁר לִטְּלָם מִשָּׁם וּבָא רְאוּבֵן וְהוֹשִׁיט פֵּרוֹת שֶׁל שִׁמְעוֹן שֶׁבַּחֲצַר שִׁמְעוֹן לְפִי פָרַת לֵוִי, חַיָּב לֵוִי אִם הַמּוֹשִׁיט חֵרֶשׁ שׁוֹטֶה וְקָטָן אוֹ \u0010c0\u0011 שֶׁאֵין לוֹ לְשַׁלֵּם, שֶׁאִם הָיָה אֶפְשָׁר לְהִשְׁתַּלֵּם מִמֶּנּוּ הָיָה הוּא חַיָּב וּבַעַל הַפָּרָה פָטוּר:\nאָכְלָה \u0010y10\u0011 \u0010c1\u0011 בִּרְשׁוּת הָרַבִּים, מְשַׁלֵּם כָּל מַה שֶּׁנֶּהֱנֵית, דְּהַיְנוּ כָּל מַה שֶּׁאָכְלָה אֵינוֹ מְשַׁלֵּם אוֹתוֹ אֶלָּא \u0010y11\u0011 כְּאִלּוּ הָיָה תֶבֶן. \u0010y12\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּמֵי שְׂעוֹרִים בְּזוֹל (טוּר ס\"ג בְּשֵׁם הָרַאֲבַ\"ד וְהָרֹא\"שׁ וְהָרְאָ\"ה וְהָרִיטְבָ\"א וְנ\"י)\u0006. וְאִם אָכְלָה אֳכָלִים הָרָעִים לָהּ, כְּגוֹן שֶׁאָכְלָה חִטִּים, הוֹאִיל \u0010y13\u0011 וְלֹא נֶהֱנֵית, פָּטוּר.\nהָיוּ \u0010y14\u0011 הַפֵּרוֹת מֻנָּחִים בְּצִדֵּי רְחָבָה וְהִיא בְּתוֹךְ הָרְחָבָה, וְהֶחֱזִירָה רֹאשָׁהּ לְצִדֵּי רְחָבָה וְאָכְלָה מֵהֶן, אֵינוֹ מְשַׁלֵּם אֶלָּא מַה שֶּׁנֶּהֱנֵית; דְּכֵיוָן דְּגוּפָהּ בִּרְשׁוּת הָרַבִּים, הָוֵי לֵהּ שֵׁן בִּרְשׁוּת הָרַבִּים. אֲבָל אִם יָצְאָה מֵרְחָבָה לְצִדֵּי רְחָבָה וְאָכְלָה שָׁם, מְשַׁלֵּם מַה שֶּׁהִזִּיקָה. \u0010y15\u0011 אָכְלָה מִפֶּתַח הַחֲנוּת, אֵינוֹ מְשַׁלֵּם אֶלָּא מַה שֶּׁנֶּהֱנֵית. מִתּוֹךְ הַחֲנוּת, מְשַׁלֵּם מַה שֶּׁהִזִּיקָה.\nהִקְצָה מָקוֹם מֵרְשׁוּתוֹ לִרְשׁוּת הָרַבִּים וְהִנִּיחַ שָׁם פֵּרוֹתָיו וַאֲכָלָתָם שָׁם, חָשׁוּב כִּרְשׁוּת הָרַבִּים.\nהָיְתָה מְהַלֶּכֶת בִּרְשׁוּת הָרַבִּים וּפָשְׁטָה צַוָּארָהּ וְאָכְלָה מֵעַל גַּבֵּי חֲבֶרְתָּהּ, וַאֲפִלּוּ עָמְדָה, \u0010y16\u0011 אֵינוֹ מְשַׁלֵּם אֶלָּא מַה שֶּׁנֶּהֱנֵית, שֶׁכֵּן דֶּרֶךְ הַבְּהֵמוֹת לֶאֱכֹל זוֹ מֵעַל גַּבֵּי זוֹ. \u0010y17\u0011 וְאִם קָפְצָה וְאָכְלָה מֵעַל גַּבֵּי חֲבֶרְתָּהּ, מְשַׁלֵּם מַה שֶּׁהִזִּיקָה, שֶׁגַּבֵּי חֲבֶרְתָּהּ כַּחֲצַר הַנִּזָּק הוּא חָשׁוּב. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּדַוְקָא שֶׁהוּא בְּעִנְיָן שֶׁאִי אֶפְשָׁר לָהּ לֶאֱכֹל כִּי אִם בִּקְפִיצָה, \u0010y18\u0011 אֲבָל אִם תּוּכַל לְאָכְלָם בְּלֹא קְפִיצָה אָז חָשׁוּב כִּרְשׁוּת הָרַבִּים (טוּר שָׁם בְּשֵׁם הָרֹא\"שׁ)\u0006. \u0010y19\u0011 וְהוּא הַדִּין לְהָיְתָה קֻפָּתוֹ מֻפְשֶׁלֶת לַאֲחוֹרָיו וְאָכְלָה פֵּרוֹת שֶׁבַּקֻפָּה.\nבְּהֵמָה שֶׁהָיְתָה עוֹמֶדֶת בִּרְשׁוּת הַנִּזָּק, וְתָלְשָׁה פֵּרוֹת מֵרְשׁוּת הָרַבִּים וַאֲכָלָתָן בִּרְשׁוּת \u0010y20\u0011 הַנִּזָּק, הֲרֵי הַדָּבָר סָפֵק, \u0005הַגָּה: \u0010y21\u0011 וְהוּא הַדִּין אִם הַבְּהֵמָה עוֹמֶדֶת בִּרְשׁוּת הָרַבִּים וְנָטְלָה הָאֹכֶל מֵרְשׁוּת הַנִּזָּק וְאָכְלָה בִּרְשׁוּת הָרַבִּים, דְּהָוֵי הַדָּבָר סָפֵק. וְדַוְקָא בְּכִי הַאי גַוְנָא שֶׁהַמַּאֲכָל בִּרְשׁוּת אֶחָד וְהַבְּהֵמָה גִּלְגְּלָה הַמַּאֲכָל לִרְשׁוּת שֵׁנִי, \u0010y22\u0011 אֲבָל אִם הַמַּאֲכָל דָּבָר אָרֹךְ, מִקְצָתוֹ מֻנָּח בִּפְנִים וּמִקְצָתוֹ מֻנָּח בַּחוּץ, וּכְשֶׁמּוֹשֶׁכֶת רֹאשׁ הָאֶחָד רֹאשׁ הַשֵּׁנִי נִגְרָר אַחֲרֶיהָ, בְּכָל מָקוֹם שֶׁהִיא מַתְחֶלֶת לְמוֹשְׁכוֹ חָשְׁבֵינָן לֵהּ כְּאִלּוּ אֲכָלָן שָׁם, בֵּין בִּרְשׁוּת הַיָּחִיד בֵּין בִּרְשׁוּת הָרַבִּים (טוּר)\u0006 ; לְפִיכָךְ, אֵינָהּ מְשַׁלֶּמֶת אֶלָּא מַה שֶּׁנֶּהֱנֵית. וְאִם תָּפַס הַנִּזָּק כַּמָּה שֶׁהִזִּיקָה, אֵין מוֹצִיאִין מִיָּדוֹ. \u0005הַגָּה: (ר\"י וְהָרֹא\"שׁ)\u0006 וּכְבָר נִתְבָּאֵר סִימָן ש\"צ \u0010y23\u0011 \u0010c2\u0011 דְּיֵשׁ חוֹלְקִין וּסְבִירָא לְהוּ דְּלָא מְהַנֵּי תְפִיסָה בִּסְפֵיקָא דְדִינָא:",["\u0003דושלח את בעירה וביער. \u0004 כצ\"ל דמושלח ילפינן היזק הרגל ומוביער ילפינן היזק דשן:","\u0003ומ\"ש הטור והמחבר תיבת נמי בבהמה שאוכלת כו'. \u0004 היינו דל\"ת מ\"ש וביער אלקיחה משדה הניזק קאי ולא אאכילה קמ\"ל דפירושו של וביער הוא שאוכלת כו' מיהו לשון וביער לא קאי דווקא אאכילה אלא על כל דבר שמפסיד אם יש לו הנאה ממנו וכדמפרש ואזיל:","\u0003ולא כלתה אותן לגמרי. \u0004 זה ילפינן מדכתיב היזק דשן ורגל בחד קרא ובדריסה דרגל אינו מפסיד לגמרי:","\u0003נתחככה בכותל כו'. \u0004 אבל נתחככה בחבירת' והזיקה י\"ל דלהזיקה נתכוון וה\"ל תולד' דקרן לשלם ח\"נ אם לא שגם לאחר ששמטה ממנה הבהמה שנתחככה בה הולכת זו ונתחככה בכותל דאז אגלאי מילתא למפרע דגם כשנתחככ' בבהמה להנאת' נתכוון עמ\"ש בסי' א' בס\"ג [בטו' בס\"ד]:","\u0003בין שאכלה בחצר כו' \u0004 כדין קרן ובא לאשמועינן דל\"ת דזה בכלל מ\"ש כל המשנ' ובא אחר ושינה בו ה\"ז פטור דגם כאן זה שהניח בגדיו בר\"ה שינה קמ\"ל דאין זה מיקרי שינוי דלפעמים אדם מניח בגדים בר\"ה על שעה אחת למתפח:","\u0003חיה שטרפה בהמה ואכלתו כו' \u0004 ע\"ל בסי' שפ\"ט שכ' הטור ומור\"ם בהג\"ה בס\"ס ח' דדוקא זאב וכיוצא בו דרכו לאכול בטריפ' משא\"כ ארי שהטריפ' לאכילה הוא שינוי גביה לדעת ר\"י והרא\"ש כי דרכו לדרוס לאכול ועפ\"ר:","\u0003אבל דמי הנביל' \u0004 פי' שאכל הנבילה אחר שהמית':","\u0003מה שנהנית. \u0004 פי' דאינו כ\"כ כדמי שווי הנבילה כמ\"ש בס\"ד [בס\"ח]:","\u0003ברשות הניזק \u0004 דכתיב וביער בשד' אחר ור\"ל בשדה של אחר והוא ניזק ועמ\"ש בס\"ס שפ\"ט:","\u0003דפי פרה כחצר הניזק דמי \u0004 פי' אע\"ג דכתיב וביער בשד' אחר והבא הלקיח' שהוא תחל' הביעור לא הי' בשד' של ניזק גם הכיליון וההפסד הנעש' בפי של פרה אחר הלקיחה הרי היא כחצר המזיק דהרי השור של מזיק הוא קמ\"ל דלא אלא עשאה פי הפרה דהיינו השן והאכילה והכליון הנעשה בפיה כאלו נעשה בחצר הניזק מאחר דבשעת האכיל' היא עומדת בחצר הניזק וכ\"כ הטור בשם הרמ\"ה ובדריש' כתבתי דיש דיעות דלא ס\"ל הכי אלא בעינן דגם בשעת הלקיחה תהא עומדת בחצר הניזק ואז חייבת אף אם נתנה בפיה חש\"ו וכדמסיק המחבר אפ\"ה חייב בעל השור כיון דמ\"מ הבהמ' הית' בחצר הניזק וגם האכילה והכליון ואף שהי' בגופו של הבהמה שהוא של מזיק וקי\"ל דפי פרה דהיינו הכיליון ה\"ל כחצר הניזק כשעומדת ברשות הניזק מתחל' ועד סוף וע' בטור דלא כתב פי פרה כחצר הניזק דמי אלא אהאי דינא בתרא כשהבהמה ברשות הניזק והאוכלים היו במקום גבוה ולא היתה יכולה ליטלה משם ונתנ' בפיה חש\"ו כו' לחוד והמחבר כתבו לטעם גם אכשנטלה מר\"ה והלכה לחצר הניזק ואכלו ולפ\"ז לא ה\"ל לערבב הדברים ולכתוב נ\"מ אפילו כו' אלא הל\"ל ועוד נ\"מ ועד\"ר שם הארכתי:","\u0003משלם כלמה שנהנית \u0004 כלומר אף שפטרה התורה מלשלם נ\"ש מ\"מ מה שנהנית צריך לשלם:","\u0003כאילו היה תבן. \u0004 דיכול המזיק לומר לא הייתי מאכילה שעורים אלא תבן ומה שנהנית שאין צריך ליתן לה תבן כיון ששבעה מהבשר הוא דמשלם לניזק ולא יותר:","\u0003דמי שעורים בזול \u0004 דהיינו שליש פחות מכדי שיווי השעורים וכמ\"ש הטור והמחב' בסי' שפ\"ט [שמ\"א]:","\u0003ולא נהנית פטור. \u0004 דכיון דהיא בר\"ה ולא נהנית אין עליה שום חיוב:","\u0003בצידי הרחבה \u0004 פי' צדי הרחבה הוא לפני הבתי' דכ\"א והוא מיוחד לכ\"א להניח שם פירותיו מביתו ומ\"ה כשהלכ' הבהמ' מר\"ה לצדי הרחבה ואכלה שם חייב נ\"ש דמיקרי חצר הניזק משא\"כ כשעומדת בגופה בר\"ה:","\u0003אכל' מפתח החנו' כו'. \u0004 אף דפתח החנות ודאי לא גרע מצידי הרחב' שנתבא' לפני זה דאם עמדה שם ואכלה משלמת מה שהזיקה מ\"מ כיון דבצד פתח החניו' רבים באים שם לקנות והבהמה עומד' שם ה\"ל כעמד' בר\"ה ואכלה מתוך צידי הרחבה דנתבאר דאינו משלמת אלא מה שנהנית אבל באכל' מתוך החנות אף שהבהמה עומדת בצד פתח החנות (ודוחק לפ' דמיירי שנכנסה לתוך החנות) מ\"מ כיון שאין דרך הבהמה להושיט ראשה כלל לתוך החנות אפילו שמואל דפליג (בגמ' דכ\"א ע\"א) עם רב במחזר' ראשה מודה בזה דה\"ל כאלו עמד' בחנות ואכלה משם משא\"כ כשאכל' מפתח החנות דדרך הליכה דרכה להושיט ראשה שם:","\u0003אינו משלם אלא מה שנהנית. \u0004 נראה אפי' הי' ראשה בשעת אכילת' ע\"ג בהמה מ\"מ כיון שגופה ורגלי' עומדת בר\"ה בתר גופה אזלינן ויש לו דין שן בר\"ה דאינו משלם נ\"ש כ\"א מה שנהנית וכמ\"ש לעיל:","\u0003ואם קפצ' ואכל' כו'. \u0004 פי' ואכלה בשעה שהיא עדיין מגביה רגליה הראשונים ואפי' היתה יכולה לאכול מעל גבה בלי קפיצ' מ\"מ מדקפצה ואכלה על גבה של הבהמה דהניזק מיקרי חצר הניזק אבל הרא\"ש והטור חולקין וס\"ל דכל שיכולה לאכול בלי קפיצה אינו כר\"ה דדרך הבהמה לאכול בכל מקום שתוכל לאכול וזהו מ\"ש מור\"ם ז\"ל בשם י\"א:","\u0003אבל אם תוכל לאכול בלי קפיצה כו' \u0004 פי' ואף שקפצה ואכלה חשוב כר\"ה:","\u0003וה\"ה להית' קופתו כו' \u0004 פי' גם בזו יש חילוק בין אם קפצה ואכלה או אכלה בלי קפיצה ולדעת הרמב\"ם זו נראה דה\"ה אם היו מונחים הפירות בר\"ה במקום שאפשר ליטלם בלי קפיצה וקפצת ואכלה חשוב כחצר הניזק ועיין בטור שכתב בשם הרמ\"ה דעת שלישית שחולק דבאכלה מע\"ג חבירת' או מתוך קופתו חייב אפי' בלי קפיצה ובר\"ה אם קפצה משלם כל מה שהזיקה ובלא קפיצה כל מה שנהנית עד\"ר שהארכתי בזה:","\u0003הרי הדבר ספק כו' \u0004 ואע\"ג דפסק המחבר לפני זה בס\"ז דאם לקחה פירות בר\"ה והלכה ואכלה ברשות הניזק יש מחייבין לשלם נ\"ש י\"ל דזה שעומדת ברשות הניזק ועומדת ומושיטה ראשה לאכול ברשות אחר מחשב שינוי שאין דרך אכילתה בכך לכן ה\"ל ספק משא\"כ כשהלכה מרשות לרשות:","\u0003וה\"ה אם הבהמ' עומדת בר\"ה כו'. \u0004 זהו תימא דהא לכ\"ע אם נוטלת ברשות הניזק ואכלה בר\"ה אינו משלמת אלא כפי מה שנהני' וכ\"ש בזה שהיא שינוי ומסתבר בו טפי לפטור מתשלומי נ\"ש ולמה כ' מור\"ם דיש להסתפק בזה ואף שרש\"י כ' ג\"כ האי וה\"ה וכו' על האיבעיא דמתגלגל אי חשוב כחצר הניזק הא שם סתרי התו' מכח האי קושי' גופיה לפירש\"י ופי' האיבעיא דמתגלגל שהי' האוכל מתגלגל מרשות כו' וכמ\"ש הטור בשם ר\"י ע\"ש ואפש' דס\"ל לרש\"י לחלק בין גלגלה מרשות לרשות בעודו מונחת ע\"ג קרקע ובין עקרה והוציאתה בפיה מרשות וצ\"ע:","\u0003אבל אם המאכל דבר ארוך כו'. \u0004 עד בין ברה\"י כו' וקימתא זו היא בגמ' אליבא דכ\"ע ודוק:","\u0003דיש חולקין וס\"ל כו'. \u0004 עפ\"ר דכתבתי מדלא כ' הטור כאן דעת אביו הרא\"ש שחולק בזה משמע דס\"ל דל\"פ כאן דכיון דעכ\"פ תפיס ברשות נגד מה שנהנית מהני התפיסה גם לשאר:"],["\u0003 שאין לו לשלם כו'. \u0004 אין לפרש הטעם דכיון דאין לו לשלם חייב מטעם דראובן ה\"ל שלוחו של לוי דהא לוי לא צוה לראובן לעשות כן ועוד דאפי' אין לו לשלם אמרינן אין שליח לדבר עבירה וכמ\"ש לעיל ר\"ס קפ\"ב ורצ\"ב ובמע\"מ פ' כיצד הרגל כ' הטעם וז\"ל וטעמא אע\"ג דפקח בר תשלומין הוא מ\"מ כיון דליכא לאשתלומי מיניה חייב אידך לשלם כר' נתן דכל דין שותפים יש לשנים שהזיקו ביחד עכ\"ל וקשה דהרי הטו' לקמן ס\"ס ת\"י השיג על הרמ\"ה בעל סברא זו וכ' ואין נראה דלא מחייב ר' נתן היכא דליכ' לאשתלומי מאידך כו' והוא דעת הי\"ח שהביא המחב' שם א\"כ יהיו דברי הטו' סותרים זא\"ז גם סותרים לדברי הרא\"ש פ' כיצד הרגל שהוציאו הט\"ו דבריהם שבכאן ממנו אלא נ\"ל דשאני הכא כיון שהמושיט לא הזיק כלום רק שהושיט לפי פרה ואז היה עדיין בעין בשלימותו וא\"כ הפרה עשתה כל ההיזק והמושיט לא ה\"ל רק כגזלן דמעידנא דאגבי' ה\"ל שולח יד בדבר שאינו שלו דה\"ל גזלן א\"כ ה\"ל כגוזל ומאכיל דרצה מזה גובה רצה מזה גובה דלעיל סי' שס\"א ס\"ה אלא דאם יש לו לשלם כיון דעכ\"פ חייב המושיט מטעם מזיק ובעל הפרה לא הזיק בידים שהרי אלו לא הושיט לא אכל' לכך גוב' מהמושיט ודוק:","\u0003 משלם כל מה שנהנית. \u0004 בהרא\"ש פ' הגוזל קמא כתב גבי אוקימת' דרבינא בצבע הקוף צמר בסמנין וז\"ל דדוקא כשגופו נהנה ע\"י אחר או ממונו נהנה מחבירו ע\"י מעשה של ממונו כמו אכלה מצדי רחבה ונפלה לגנ' אז משלם מה שנהנית אבל כשממונו נהנה ע\"י אחר פטו' עכ\"ל והוא כתירוץ הראשון של התוס' שם ד\"ק ע\"א מוכח דאם תחב לה אחר אוכלין לתוך פיה פטו' לשלם מה שנהנית (ודל\"ד לעיל ס\"ז דהתם משלם מה שהזיקה דהוי פשיעה וכ\"כ בספר מע\"מ פ' הגוזל שם) וכ\"כ מהרש\"ל פ' הגוזל סי' כ\"ח דהתוחב אוכלין לתוך פיו של בהמתו אינו משלם כלום מה\"ט ומ\"מ נ\"ל דמיירי שתחב אוכלין של אחרים ופטור מן בעל האוכלין אבל אם תחב אוכלין שלו חייב לשלם לו דלא גרע מיורד שלא ברשות וטעמא ביורד שלא ברשות כיון שמתכוין להשביח חייב לשלם לו יציאותיו ודוק ומיהו כ\"ז לשנויא קמא דתוס' אבל תמיהני על הרא\"ש ומהרש\"ל דהא התוס' מסקי שם וז\"ל א\"נ הנאה דהכא לא חשיבה הנאה שאינו אלא נוי בעלמא יותר עכ\"ל כלו' משום דחזיתא לאו מילתא היא וכדקאמרינן בש\"ס התם ותירוץ זה נ\"ל לכאורה עיקר דמניין לנו לחלק בחלוקים שלא נזכרו בש\"ס (הג\"ה וגם הא דבעי בש\"ס התם למיפשט דחזיתא מילתא היא מערלה ושביעית לא יתיישב שפיר לתירוץ קמא דתוספות ודו\"ק ע\"ש) ועכ\"פ נ\"ל דדין זה כשממונו נהנה ממונו של אחר שלא ע\"י מעשה ממונו ה\"ל ספיקא דדינא אי פטור או לא ודו\"ק:","\u0003 דיש חולקין כו' \u0004 עיין בסמ\"ע ס\"ק כ\"ד עד דכיון דעכ\"פ תפס ברשות נגד מה שנהנית מהני תפיסה גם לשאר עכ\"ל וזהו דוחק ול\"נ דשאני הכא דהוי בעי' ולא איפשטא ולא סלקא בתיקו ובזה גם להרא\"ש וטור מהני תפיסה וכמש\"ל סי' שמ\"ו סי\"ד (הג\"ה וע\"ש שחזר בו אח\"כ וגם בספרו תקפו כהן וס\"ל דאין לחלק בין תיקו לבעיא דלא איפשטא):"],"\u0010g0\u0011 \u0010r0\u0011 שֵׁן הִיא אָב, \u0010y0\u0011 דִּוְשִׁלַּח אֶת בְּעִירֹה \u0010g1\u0011 \u0010r1\u0011 \u0005(וּבִעֵר)\u0006 דִּכְתִיב בַּקְּרָא, מוֹקְמֵינָן לָהּ \u0010y1\u0011 נַמֵּי בִּבְהֵמָה שֶׁאוֹכֶלֶת פֵּרוֹת חֲבֵרוֹ דְּבָרִים הָרְאוּיִים לָהּ וְנֶהֱנֵית בַּאֲכִילָתָן חַיָּב נֶזֶק שָׁלֵם, \u0010g2\u0011 בֵּין שֶׁאֲכָלָתָן \u0010r2\u0011 בֵּין שֶׁלֹּא אֲכָלָתָן אֶלָּא שֶׁהִפְסִידָתָן \u0010y2\u0011 וְלֹא כִּלְּתָה אוֹתָם לְגַמְרֵי. \u0010g3\u0011 לְפִיכָךְ, \u0010r3\u0011 כָּל הַדּוֹמֶה לְזֶה, שֶׁמַּזִּיק בְּדָבָר שֶׁהִיא נֶהֱנֵית, הוּא תּוֹלָדָה דְשֵׁן; כְּגוֹן \u0010y3\u0011 נִתְחַכְּכָה \u0010t0\u0011 בַכֹּתֶל לַהֲנָאָתָהּ וְהִזִּיקָה, אוֹ שֶׁטִּנְּפָה פֵרוֹת וְכֵלִים לַהֲנָאָתָהּ, כְּגוֹן שֶׁנִּתְגַּלְגְּלָה עֲלֵיהֶם: \u0010g4\u0011\nבַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁאָכְלָה דָּבָר הָרָאוּי לָהּ. אֲבָל אָכְלָה דָּבָר שֶׁאֵין רָאוּי לָהּ, כְּגוֹן כְּסוּת וְכֵלִים, שִׁנּוּי הוּא וְאֵינוֹ מְשַׁלֵּם אֶלָּא חֲצִי נֶזֶק, \u0010y4\u0011 \u0010g5\u0011 \u0010r4\u0011 בֵּין שֶׁאָכְלָה אוֹתָם בַּחֲצַר הַנִּזָּק בֵּין שֶׁאָכְלָה אוֹתָם בִּרְשׁוּת \u0010t1\u0011 הָרַבִּים. \u0010g6\u0011\nאָכְלָה דָּבָר שֶׁאֵין דַּרְכָּהּ לֶאֱכֹל אֶלָּא עַל יְדֵי הַדְּחַק, כְּגוֹן פָּרָה שֶׁאָכְלָה שְׂעוֹרִים, וַחֲמוֹר שֶׁאָכַל כַּרְשִׁינִין, וְכֶלֶב שֶׁלָּקַק אֶת הַשֶּׁמֶן, וַחֲזִיר שֶׁאָכַל חֲתִיכַת בָּשָׂר, \u0010g7\u0011 וְחָתוּל שֶׁאָכַל תְּמָרִים, חָשִׁיב שַׁפִּיר אֲכִילָה. \u0010g8\u0011 \u0010r5\u0011 אֲבָל בְּהֵמָה שֶׁאָכְלָה בָּשָׂר אוֹ תַבְשִׁיל, לָאו אֹרְחָא הוּא, וּמְשַׁלֵּם חֲצִי נֶזֶק. \u0010g9\u0011 אָכְלָה פַּת הָוֵי \u0010g10\u0011 אֹרְחָא, אֲבָל חַיָּה לָאו אֹרְחָא לֹא בְּפַת וְלֹא בְּתַבְשִׁיל. \u0010g11\u0011\nבְּהֵמָה שֶׁרָאֲתָה לֶחֶם בְּסַל, וְשִׁבְּרָה הַסַל וְאָכְלָה הַלֶּחֶם, מְשַׁלֵּם נֶזֶק שָׁלֵם גַּם עַל הַסַל, שֶׁכָּךְ דַּרְכָּהּ לְשַׁבֵּר הַסַל כְּדֵי לֶאֱכֹל הַלֶּחֶם. \u0010g12\u0011 אֲבָל אִם אָכְלָה הַלֶּחֶם תְּחִלָּה וְאַחַר כָּךְ שָׁבְרָה הַסַל, אֵינוֹ מְשַׁלֵּם עַל הַסַל אֶלָּא חֲצִי נֶזֶק, \u0010g13\u0011 דְּהָוֵי קֶרֶן וְאֵינוֹ מִשְׁתַּלֵּם אֶלָּא מִגּוּפוֹ. \u0010g14\u0011\nרָאֲתָה אֳכָלִים עַל פִּי הֶחָבִית, וְנִסְתַּבְּכָה בֶּחָבִית לַעֲלוֹת כְּדֵי לֶאֱכֹל הָאֳכָלִים וְשִׁבַּרְתּוֹ, מְשַׁלֵּם גַּם עַל הֶחָבִית נֶזֶק שָׁלֵם, שֶׁכֵּן דַּרְכָּם לַעֲלוֹת עָלָיו כְּדֵי \u0010y5\u0011 \u0010g15\u0011 \u0010r6\u0011 לֶאֱכֹל הָאֳכָלִים.\nחַיָּה \u0010t2\u0011 שֶׁטָּרְפָה בְּהֵמָה וַאֲכַלְתָהּ, \u0010g16\u0011 אוֹ שֶׁאָכְלָה בָּשָׂר \u0010r7\u0011 חַי, אֹרְחָא הִיא וּמְשַׁלֵּם נֶזֶק שָׁלֵם. \u0010g17\u0011 אֲבָל כֶּלֶב שֶׁהֵמִית \u0010r8\u0011 כֶּבֶשׂ, וְחָתוּל שֶׁהֵמִית תַּרְנְגוֹלִים גְּדוֹלִים וַאֲכָלָם, מְשֻׁנֶּה הוּא וְאֵינוֹ מְשַׁלֵּם אֶלָּא חֲצִי נֵזֶק. \u0010g18\u0011 \u0010r9\u0011 וְדַוְקָא בִּפְחָת \u0010g19\u0011 שֶׁפִּחֲתָה מִיתָה, \u0010y6\u0011 אֲבָל \u0010t3\u0011 דְּמֵי הַנְּבֵלָה מְשַׁלֵּם בִּרְשׁוּת הַנִּזָּק נֶזֶק שָׁלֵם, \u0010y7\u0011 וּבִרְשׁוּת הָרַבִּים מַה שֶּׁנֶּהֱנֵית, שֶׁאֲכִילָה אֵינוֹ שִׁנּוּי, שֶׁכֵּן דַּרְכָּן לֶאֱכֹל נְבֵלוֹת אֲפִלּוּ שֶׁל בְּהֵמוֹת גְּדוֹלוֹת. \u0010g20\u0011\nאֵין חַיָּב הַשֵּׁן לְשַׁלֵּם נֶזֶק שָׁלֵם אֶלָּא אִם כֵּן אוֹכֶלֶת \u0010y8\u0011 בִּרְשׁוּת הַנִּזָּק, אֲבָל אִם לָקְחָה בַּחֲצֵרוֹ וְהוֹצִיאָה מִשָּׁם וְאָכְלָה בִּרְשׁוּת הָרַבִּים אוֹ בֶחָצֵר שֶׁל אַחֵר, פָּטוּר מִלְּשַׁלֵּם \u0010g21\u0011 \u0010r10\u0011 יוֹתֵר מִמַּה שֶׁנֶּהֱנֵית. \u0010r11\u0011 וְאִם לָקְחָה בִּרְשׁוּת הָרַבִּים וְהָלְכָה וְאָכְלָה בִּרְשׁוּת \u0010g22\u0011 הַנִּזָּק, יֵשׁ מְחַיְּבִים לְשַׁלֵּם נֶזֶק שָׁלֵם, \u0010g23\u0011 \u0010r12\u0011 מִשּׁוּם \u0010y9\u0011 דְּפִי פָרָה כַּחֲצֵר הַנִּזָּק דָּמֵי; \u0010g24\u0011 וְנָפְקָא מִנָּהּ אֲפִלּוּ בְּמָקוֹם שֶׁאֵין לְחַיֵּב עַל הַנְּטִילָה, כְּגוֹן שֶׁהָיוּ הַפֵּרוֹת מֻנָּחִים בְּמָקוֹם שֶׁאִי אֶפְשָׁר לִטְּלָם מִשָּׁם וּבָא רְאוּבֵן וְהוֹשִׁיט פֵּרוֹת שֶׁל שִׁמְעוֹן שֶׁבַּחֲצַר שִׁמְעוֹן לְפִי פָרַת לֵוִי, חַיָּב לֵוִי \u0010r13\u0011 אִם הַמּוֹשִׁיט חֵרֶשׁ שׁוֹטֶה וְקָטָן \u0010r14\u0011 אוֹ \u0010c0\u0011 שֶׁאֵין לוֹ \u0010t4\u0011 לְשַׁלֵּם, שֶׁאִם הָיָה אֶפְשָׁר לְהִשְׁתַּלֵּם מִמֶּנּוּ הָיָה הוּא חַיָּב וּבַעַל הַפָּרָה פָטוּר: \u0010g25\u0011\nאָכְלָה \u0010y10\u0011 \u0010c1\u0011 בִּרְשׁוּת הָרַבִּים, מְשַׁלֵּם כָּל מַה \u0010t5\u0011 שֶּׁנֶּהֱנֵית, דְּהַיְנוּ כָּל מַה שֶּׁאָכְלָה אֵינוֹ מְשַׁלֵּם אוֹתוֹ \u0010g26\u0011 \u0010r15\u0011 אֶלָּא \u0010y11\u0011 כְּאִלּוּ הָיָה תֶבֶן. \u0010y12\u0011 \u0010r16\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּמֵי שְׂעוֹרִים \u0010t6\u0011 בְּזוֹל (טוּר ס\"ג בְּשֵׁם הָרַאֲבַ\"ד וְהָרֹא\"שׁ וְהָרְאָ\"ה \u0010g27\u0011 וְהָרִיטְבָ\"א וְנ\"י)\u0006. \u0010g28\u0011 וְאִם אָכְלָה אֳכָלִים הָרָעִים לָהּ, כְּגוֹן שֶׁאָכְלָה חִטִּים, הוֹאִיל \u0010y13\u0011 וְלֹא נֶהֱנֵית, \u0010t7\u0011 פָּטוּר. \u0010g29\u0011 \u0010r17\u0011\nהָיוּ \u0010y14\u0011 הַפֵּרוֹת מֻנָּחִים בְּצִדֵּי רְחָבָה וְהִיא בְּתוֹךְ הָרְחָבָה, וְהֶחֱזִירָה רֹאשָׁהּ לְצִדֵּי רְחָבָה וְאָכְלָה מֵהֶן, אֵינוֹ מְשַׁלֵּם אֶלָּא מַה שֶּׁנֶּהֱנֵית; דְּכֵיוָן דְּגוּפָהּ בִּרְשׁוּת הָרַבִּים, הָוֵי לֵהּ שֵׁן בִּרְשׁוּת הָרַבִּים. אֲבָל אִם יָצְאָה מֵרְחָבָה לְצִדֵּי רְחָבָה וְאָכְלָה שָׁם, מְשַׁלֵּם מַה שֶּׁהִזִּיקָה. \u0010y15\u0011 \u0010g30\u0011 אָכְלָה מִפֶּתַח \u0010t8\u0011 הַחֲנוּת, אֵינוֹ מְשַׁלֵּם אֶלָּא מַה שֶּׁנֶּהֱנֵית. מִתּוֹךְ הַחֲנוּת, מְשַׁלֵּם מַה שֶּׁהִזִּיקָה. \u0010g31\u0011 \u0010r18\u0011\nהִקְצָה מָקוֹם מֵרְשׁוּתוֹ לִרְשׁוּת הָרַבִּים וְהִנִּיחַ שָׁם פֵּרוֹתָיו וַאֲכָלָתָם שָׁם, חָשׁוּב כִּרְשׁוּת הָרַבִּים. \u0010g32\u0011 \u0010r19\u0011\nהָיְתָה מְהַלֶּכֶת בִּרְשׁוּת הָרַבִּים וּפָשְׁטָה צַוָּארָהּ וְאָכְלָה מֵעַל גַּבֵּי חֲבֶרְתָּהּ, וַאֲפִלּוּ עָמְדָה, \u0010y16\u0011 אֵינוֹ מְשַׁלֵּם אֶלָּא מַה שֶּׁנֶּהֱנֵית, \u0010g33\u0011 שֶׁכֵּן \u0010t9\u0011 דֶּרֶךְ הַבְּהֵמוֹת לֶאֱכֹל זוֹ מֵעַל גַּבֵּי זוֹ. \u0010y17\u0011 \u0010r20\u0011 וְאִם קָפְצָה וְאָכְלָה מֵעַל גַּבֵּי חֲבֶרְתָּהּ, מְשַׁלֵּם מַה שֶּׁהִזִּיקָה, שֶׁגַּבֵּי חֲבֶרְתָּהּ כַּחֲצַר הַנִּזָּק הוּא חָשׁוּב. \u0005הַגָּה: \u0010r21\u0011 וְיֵשׁ אוֹמְרִים דְּדַוְקָא שֶׁהוּא בְּעִנְיָן שֶׁאִי אֶפְשָׁר לָהּ לֶאֱכֹל כִּי אִם בִּקְפִיצָה, \u0010y18\u0011 אֲבָל אִם תּוּכַל לְאָכְלָם בְּלֹא קְפִיצָה אָז חָשׁוּב כִּרְשׁוּת הָרַבִּים (טוּר שָׁם בְּשֵׁם הָרֹא\"שׁ)\u0006. \u0010y19\u0011 \u0010g34\u0011 וְהוּא הַדִּין לְהָיְתָה קֻפָּתוֹ מֻפְשֶׁלֶת לַאֲחוֹרָיו וְאָכְלָה \u0010g35\u0011 \u0010r22\u0011 פֵּרוֹת שֶׁבַּקֻפָּה.\nבְּהֵמָה שֶׁהָיְתָה עוֹמֶדֶת בִּרְשׁוּת הַנִּזָּק, וְתָלְשָׁה פֵּרוֹת מֵרְשׁוּת הָרַבִּים וַאֲכָלָתָן בִּרְשׁוּת \u0010y20\u0011 הַנִּזָּק, הֲרֵי הַדָּבָר \u0010t10\u0011 סָפֵק, \u0005הַגָּה: \u0010y21\u0011 \u0010g36\u0011 \u0010r23\u0011 וְהוּא הַדִּין אִם הַבְּהֵמָה עוֹמֶדֶת בִּרְשׁוּת הָרַבִּים וְנָטְלָה הָאֹכֶל מֵרְשׁוּת הַנִּזָּק וְאָכְלָה בִּרְשׁוּת הָרַבִּים, דְּהָוֵי הַדָּבָר סָפֵק. וְדַוְקָא בְּכִי הַאי גַוְנָא שֶׁהַמַּאֲכָל בִּרְשׁוּת אֶחָד וְהַבְּהֵמָה גִּלְגְּלָה הַמַּאֲכָל לִרְשׁוּת שֵׁנִי, \u0010y22\u0011 \u0010g37\u0011 אֲבָל אִם הַמַּאֲכָל דָּבָר אָרֹךְ, מִקְצָתוֹ מֻנָּח בִּפְנִים וּמִקְצָתוֹ מֻנָּח בַּחוּץ, וּכְשֶׁמּוֹשֶׁכֶת רֹאשׁ הָאֶחָד רֹאשׁ הַשֵּׁנִי נִגְרָר אַחֲרֶיהָ, בְּכָל מָקוֹם שֶׁהִיא מַתְחֶלֶת לְמוֹשְׁכוֹ חָשְׁבֵינָן לֵהּ כְּאִלּוּ אֲכָלָן שָׁם, בֵּין בִּרְשׁוּת הַיָּחִיד בֵּין בִּרְשׁוּת הָרַבִּים (טוּר)\u0006 ; לְפִיכָךְ, אֵינָהּ מְשַׁלֶּמֶת אֶלָּא מַה שֶּׁנֶּהֱנֵית. וְאִם תָּפַס הַנִּזָּק כַּמָּה שֶׁהִזִּיקָה, אֵין מוֹצִיאִין מִיָּדוֹ. \u0005הַגָּה: (ר\"י וְהָרֹא\"שׁ)\u0006 וּכְבָר נִתְבָּאֵר סִימָן ש\"צ \u0010y23\u0011 \u0010c2\u0011 דְּיֵשׁ \u0010t11\u0011 חוֹלְקִין וּסְבִירָא לְהוּ דְּלָא מְהַנֵּי תְפִיסָה בִּסְפֵיקָא דְדִינָא:",{"g":["א) ל' הטור משנה בפר' ב דב\"ק דף י\"ט ע\"ב ויליף לה מקרא שם בפ\"ק סוף דף כ'","כן הגיה הסמ\"ע וכתב דמושלח ילפינן היזק הרגל ומובער ילפינן היזק דשן ולענ\"ד שזה הי' כוונת המחבר שהוסיף תיבת נמי שאינו בטורי' שלפנינו","\u0003ב) מסקנת הגמרא שם דף ג' ע\"א אף שן לא שנא מכליא קרנא וכו'\u0004 ","ג) כ\"כ התוס' שם בריש הדף","\u0003ד) שם ס\"ב משנה שם בפ\"ב דף י\"ט ע\"ב.\u0004 ","ה) כשמואל וכר' יוחנן שם דף כ' ע\"א דאמרי' דהא דתנן שם במשנה אבל ברה\"ר פטור קאי אאכלה פירות וירקות אבל אכלה כסות וכלים חייבת והטעם משום דמשונה ה\"ל תולדה דקרן","ו) שם בטור וברייתא שם","ז) מימרא דר\"פ שם","ח) ברייתא שם","ט) מעובדא דההוא חמרא שם","י) ברייתא ואוקימתא דגמרא שם ומבואר שם בגמרא דחיה בבשר צלי אש לאו אורחיה והצבי אין דרכו בפת ובשר והבהמה אין דרכה לאכול הפת על השולחן","\u0003כ) מבואר שם על עובדא דההוא חמרא וכו'\u0004 לקמיה דרב יהודה","\u0003ל) היינו עובדא הנזכר שם:\u0004 ","מ) דשינוי הוא","\u0003נ) שם ושם ריש דף כ' עובדא דההוא ברחא וכו'\u0004 לקמיה דרבא","ס) שם וברייתא שם בספ\"ק דף י\"ו ע\"ב","ע) פשוט בגמ' בפ\"ב סוף דף יט","פ) מבואר במסק' דגמ' בספ\"ק דף טו ע\"ב","צ) שם בשם אביו הרא\"ש כן דקדק בפ\"ב אמתני' דאכל' כסוס שם דף כ' ע\"ב","ק) דשינוי הוא שאין דרכו להמית טו'","\u0003ר) שם ס\"ג ממשמעות הגמרא דף כג ע\"א אלימא בגדיש דעלמא וכולי לא צריכ' דאכלה וכו'\u0004 וכ\"כ הרא\"ש ונ\"י שם","ש) כן ביאר הרמב\"ם בפ\"ג מה' נזקי ממון דין ה'","ת) שם בשם הרמב\"ם וכתב הב\"י שזה לא נזכר בדברי הרמב\"ם ובספ' מדויק מצא הרמ\"ה במקום הרמב\"ם והוא הנכון ע\"כ ואני בענ\"ד אומ' שהרמב\"ם חולק בזה וסובר שהוא בעיא ולא נפשטא ומבוא' בסעיף י\"ב וכמ\"ש שם:","א) הר\"ב סמ\"ע נדחק לפרש מאי נתינת טעם הוא ליש מחייבין וגם בזה שדא ביה נרגא ולענ\"ד ברור שהוא טעות ולמחוק תיבת משום וד' דפי וצריך להיות פי פרה והוא עניין דין בפני עצמו וכן היא בטור וכן הגיה הב\"י שם ומוצא דין זה שם בגמרא דף כג ע\"א ותפשוט דפי פרה כחצר הניזק דמי ומשמע מדברי התוס' דקושטא דמלתא הכי הוא כ\"כ הרשב\"א והרא\"ש שם.","\u0003ב) כן כתבו התוספות והרא\"ש שם:\u0004 ","ג) משנה שם די\"ט ע\"ב","ד) פלוגתא דרבה ורבא שם ד\"כ ע\"א כ' בב\"י כיון שהרי\"ף והרמב\"ם מסופקים הלכה נמי ראוי לומר דנקטינן לקולא כרבה וכדפרש\"י דעמיר היינו תבן","ה) פסקו כרבא שם","ו) ברייתא שם","ז) משנה שם דף י\"ט ע\"ב וכדמפ' לה שמואל שם דף כ\"א ע\"א","ח) שם במשנה","ט) טור שם בשם אביו הרא\"ש שם בפסקיו פסק כלישנא קמא דשמואל דפטור במחזרת וכ\"ש במקצה מקום מדקאמר סתמא תלמודא בתר הכי שם ע\"ב לא דכ\"ע מחזרת אי כרב אי כשמואל וכ\"נ מדברי הרי\"ף והרמב\"ם שלא הביאו דין זה דמקצה מקום","י) ל' הרמב\"ם שם בפ\"ג ד\"י וכתב הכ\"מ מימרא דאילפא ורבי אושעיא שם דף כ' ע\"א וכדמפרש רבא בקופצת וכמ\"ש הנ\"י וז\"ל פי' קופצת היינו שזקפה רגליה ועמדה על הבהמה ואכלה זקופה אבל אם עמדה מעט כדי לפשוט צוארה פטורה משום דבהמתו לאו כרשות הניזק גמור הוא","פי' וחשיב כר\"ה טור","כ) טור וכן כתב הרשב\"א וקופצ' דקאמר (רבא שם אמימר' דרבי אושעיא) שקפצה על האדם שהקופה מופשלת לאחוריו וכן ע\"ג אנטבא שבר\"ה כיון דאורחה למיכל שעורים או כרשינין שבקופה אף היא דרכה לקפוץ שם וטעם חיובן של אלו מפני שהם כחצר הניזק ואע\"פ שהם עומדים בר\"ה מפני שיש להם רשות לעבור שם עם משאן","ל) ל' הרמב\"ם שם דין ד' וכתב ה\"ה כ\"ז שרשות האכילה הוא להחמיר על המזיק סובר רבינו שהיא בעיא דלא איפשטא (שם) וגורס כך בעי רבי זירא מתגלגל מהו היכי דמי דקיימא ברה\"י וקא מגלגל ואתי מרשות הרבים לרה\"י ובהשגות והיא מיושרת מן הגרסחות שלנו","מ) גם את זה לא ידעתי מה שהכניס הרב גירס' שלפנינו ומה שפרש\"י בתוך דברי הרמב\"ם דלהרמב\"ם פטור בזה כמ\"ש שם דין ה' כלב שנכנס לחצר וכמ\"ש ה\"ה שם דהיכא דלקחת הדבר ברשות אחר ואכילתו ברשות אחרת הולכין אחר הרשות שהאכילה שם כ\"ז שהוא להקל על המזיק ויצא לו מסוגיא שעל משנת כלב שנטל את החררה (שם דף כ\"ג ע\"א) וכן הקשו התוס' שם על פירש\"י מסוגיא ההוא ופירשו בע\"א והביאו הטור ומה שלא כתבו הרמ\"ה אפשר דס\"ל דלא שכיחא שיהא האוכל מתגלגל מעצמו מרשות הניזק לר\"ה וראיתי שגם הרב סמ\"ע העיר בזה","נ) תני רבי חייא איקימתא בתרייתא שם"],"t":["\u0003בכותל. \u0004 אבל נתחככה בחבירתה י\"ל דלהזיקה נתכוונה וה\"ל תולדה דקרן לשלם ח\"נ אם לא שאם לאחר ששמטו ממנה הבהמה שנתחככה בה הלכה ונתחככה בכותל דאגלאי מלתא למפרע דגם כשנתחככה בבהמה להנאתה נתכוונה וע\"ל סי' א' ס\"ג. סמ\"ע:","\u0003הרבים. \u0004 פירוש דל\"ת דזה שהניח בגדיו בר\"ה שינה וה\"ל בכלל דמ\"ש כל המשנה ובא אחר ושינה בו פטור קא משמע לן דאין זה מקרי שינוי דלפעמים אדם מניח בגדים בר\"ה לפי שעה למתפח. שם:","\u0003שטרפה. \u0004 ע\"ל סי' שפ\"ט ס\"ח בהג\"ה ובסמ\"ע שם:","\u0003דמי. \u0004 פירוש שאכל הנבילה אחר שהמיתה. שם:","\u0003לשלם. \u0004 אין לפרש הטעם דראובן ה\"ל שלוחו של לוי דהא לוי לא צוה לראובן לעשות כן ועוד דאפילו אין לו לשלם אמרינן אין שליח לד\"ע וכמ\"ש בר\"ס קפ\"ב ובסי' רצ\"ב ס\"ד ע\"ש אלא נ\"ל דהכא כיון שהמושיט לא הזיק כלום רק שהושיט לפי פרה ואז היה עדיין בעין בשלימותו וא\"כ הפרה עשתה כל ההיזק והמושיט לא ה\"ל רק כגזלן דמעידנא דאגביה ה\"ל שולח יד בדבר שאינו שלו דהוי גזלן אם כן ה\"ל כגוזל ומאכיל דרצה מזה גובה כו' כמ\"ש בסי' שס\"א ס\"ה אלא דאם יש לו לשלם כיון דעכ\"פ חייב המושיט מטעם מזיק ובעל הפרה לא הזיק בידים שהרי אילו לא הושיט לא אכלה לכך גובה מהמושיט. ש\"ך:","\u0003שנהנית. \u0004 כלומר אף שפטרה התורה מלשלם נ\"ש מה שנהנית צריך לשלם כ\"כ הסמ\"ע ועמ\"ש הש\"ך בביאור דברי הרא\"ש בזה ע\"ש:","\u0003בזול. \u0004 היינו שליש פחות מכדי שיווי השעורים כ\"כ הטור וע\"ש. סמ\"ע:","\u0003פטור. \u0004 דכיון דהוא בר\"ה ולא נהנית אין עליה שום חיוב. שם:","\u0003החנות. \u0004 כיון דבצד פתח חנויות רבים באים שם לקנות והבהמה עומדת שם ה\"ל כעמדה בר\"ה ואכלה מצידי הרחבה דאינו משלם רק מה שנהנית אבל באכלה מתוך החנות אף שעומדת בצד פתח החנות מ\"מ כיון שאין דרך הבהמה כלל להושיט ראשה לתוך החנות כ\"ע מודו דה\"ל כאילו עמדה בחנות ואכלה משם משא\"כ כשאכלה מפתח החנות דדרך הלוכה דרכה להושיט שם ראשה. שם:","\u0003דרך. \u0004 נראה דאפילו היה ראשה בשעת אכילתה ע\"ג בהמה מ\"מ כיון שגופה ורגליה עומדות בר\"ה בתר גופה אזלינן ויש לו דין שן בר\"ה דאינו משלם נ\"ש כי אם מה שנהנית. שם:","\u0003ספק. \u0004 ואע\"ג דכת' המחבר בס\"ז דאם לקחה בר\"ה והלכה ואכלה ברשות הניזק יש מחייבין לשלם נ\"ש י\"ל דבזה שעומדת בר\"ה ומושיטה ראשה לאכול ברשות אחר מיחשב שינוי שאין דרך אכילתה בכך לכן הוי ספק משא\"כ כשהלכה מרשות לרשות. שם:","\u0003חולקין. \u0004 ומדלא כת' הטור כאן דעת אביו הרא\"ש שחולק בזה משמע דס\"ל דל\"פ הכא דכיון דעל כל פנים תפיס ברשות נגד מה שנהנית מהני התפיסה גם להשאר. שם \u0005(ועיין מ\"ש בזה בסי' ר\"ב ס\"ק ו' ובסי' שס\"ב ס\"ק ו' ע\"ש)\u0006:"],"r":["\u0003שן כו'. \u0004 ב' ב':","\u0003וביער. \u0004 ליתיה בטור ור\"ל דמושלח ילפינן נמי לשן כמ\"ש ג' א' וז\"ש מוקמינן לה נמי וכ\"ה בטור שגם ב\"ח והסמ\"ע הוסיף תיבת ובער. ומ\"מ הדין עמו דודאי יליף מובער וה\"ק אצטריך כו' דהתורה לא רצה ללמוד מושלח כו' ושם נ\"ה ב' שן דכתיב כו' ובזה א\"צ לדחוקי מ\"ש תוס' שם ד\"ה אצטריך כו' ושם נ\"ה ב' ד\"ה עד כו' וע\"ש ד' א' לא ראיה רגל כו':\n\u0003 (ליקוט) וביער כו'. \u0004 דמש\"ש איצטריך סד\"א אמינא כו' שינוייא בעלמא הוא דתנא אמר וכה\"א כאשר כו' וכ\"מ בר\"פ הכונס וכן שם ד' א' אא\"ר תנא שור כו' וה\"ק לא ראי הרגל כו' ולא ראי השן כו' (ע\"כ):","\u0003בין שלא כו' לפיכך כו'. \u0004 כפי' תוס' שם ד\"ה הא כו':","\u0003כל כו'. \u0004 גמ' שם:","\u0003בין כו'. \u0004 דקי\"ל כר\"י ועוד דגם באידך דר\"ל לא קי\"ל כוותיה כמש\"ש כ\"ד ב': (ליקוט) בין כו' דאין הלכה כר\"ל דאף בדין דשתי פרות לא קי\"ל כוותיה ואף שהרא\"ש שם סי\"ד דחק עצמו דבריו אינן מובנין (ע\"כ):","\u0003אבל כו' אבל כו'. \u0004 שם ורמינהו כו' לא כו':","\u0003חיה כו'. \u0004 עסי' שפט סח:","\u0003חי. \u0004 שם:","\u0003כבש כו'. \u0004 טור דמ\"ש וה\"מ ברברבי לא קאי אלא אדסמיך אתרנגולי וכגי' הרי\"ף תרנגולי רברבי וכ\"ה בספ\"ג דכתובות וכ\"כ הרמב\"ם להדיא כבשים קטנים וט\"ס ברא\"ש פ\"ב סג כגון כלב כו' וצ\"ל להיפך וכ\"ה ברא\"ש וברמזים בספ\"ק ס\"כ:","\u0003ודוקא כו'. \u0004 מדקתני ספ\"ק הבהמה אינה מועדת כו' ול\"ק ששה תמין וכה\"ג וכן בפ\"ב דקאמר אכלה כסות כו' ול\"ק כה\"ג והא דקאמר שם ך\"ג א' זאת אומרת כו' ר\"ל דבלא\"ה אנוס הוא ופטור לגמרי דלא כרש\"י ד\"ה דסתם כו'. אבל ביש\"ש חלק עליו ואמר כל הפוסקים לא פי' כן וראייתו עדיין ק' דאכתי ליתני מה שאין דרכה לאכול כגון בהמה שאכלה בשר וכיוצא וע\"ש שתי' קושיות הנ\"ל:","\u0003יותר כו'. \u0004 כמ\"ש בס\"ח:","\u0003ואם לקחה כו'. \u0004 כ\"כ הטור בשם הרמ\"ה ואין דעת. התוס' כן שכ' שם בד\"ה סתם. ש\"מ דבעי לקיחה ואכילה כו' ודעת הרמ\"ה דאובער דהיינו אכילה קפדינן ובזה א\"צ לדחוקי מ\"ש תוס' בד\"ה וליחייב. האי לישנא כו' אלא דהחררה מונחת על גחלת של אחרים ברשות אחרים וכן פי' הרשב\"א בשם הראב\"ד אף שלפ\"ז לא מוכח דין של התוס' דבלקיחה לא סגי דהא שפיר קאמר תפשוט מ\"מ מוכח מדקאמר שם אלא שן הריב כו' ועתוס' הנ\"ל ועמ\"ש בסי\"ב:","\u0003משום דפי. \u0004 ט\"ס וצ\"ל פי ועבה\"ג והוא גמ' הנ\"ל שנפשטה האיבעיא מסוגיא הנ\"ל אלא שרצה לפשוט ג\"כ ממקום אחר:","\u0003אם המושיט כו'. \u0004 דבלא\"ה אפי' במקום שאפשר ליטול חייב המושיט לבד כמש\"ו ועהג\"א שם ועתוס' נג ב' ד\"ה שור כו' ו' א' ד\"ה לאתויי כו':","\u0003או שאין כו'. \u0004 כס' ראשונה בסי' תי סל\"ז ודברי ש\"ך ורחוקים מאד:","\u0003אלא כו'. \u0004 די\"ל הלכה כרבה דהוא רביה דרבא וי\"ל הלכה כרבא דהוא בתרא וכ' הרי\"ף והרמב\"ם ב' הדעות ופ' המחבר לקולא:\n\u0003 (ליקוט) דהיינו כו'. \u0004 שי\"א דהלכה כרבה דרביה דרבא הוא. רי\"ף ורא\"ש שם ועבה\"ג וערא\"ש שם ה\"א ובריש סוכה ובפי\"ט דשבת ס\"ה ובפ\"ק דעירובין ס\"ד ושם פ\"ב ס\"ד ובפ\"ק דב\"מ סמ\"ט ובפ\"ז דכתובות סי\"ג וערא\"ש בפ\"ג דב\"ב ס\"ו וכן כייל הרשב\"א והריטב\"א והר\"ן וש\"פ דכל היכא דאשכחן א\"ל רבא כו' הלכה כרבותיו אבל כשנחלקו כשני החולקין הלכה כרבא (ע\"כ):","\u0003וי\"א כו'. \u0004 משום דת\"כ דרבים הוא:","\u0003היו כו'. \u0004 כלי' קמא דסוגיא שם ב' כלישנא קמא דקא' לא דכ\"ע מחזרת כו' וה' כשמואל בדיני:","\u0003הקצה כו'. \u0004 כיון דקי\"ל כלי' קמא כ\"ש כה\"ג:","\u0003היתה כו'. \u0004 כשיטת הרי\"ף דמש\"ש בדאמר רבא כו' לאו לדחויי דברי אילפא אלא לפרש דבריו דלא כפירש\"י ותוס' ורז\"ה דח\"נ משלם אלא נ\"ש ול\"פ אילפא ור' אושעיא וא\"צ לדחוקי מ\"ש תוס' כא ב' ד\"ה דאילפא כו' וכ\"כ הראב\"ד ורשב\"א ורא\"ש דאין זה שינוי דהא אמרינן שם כיון דאורחיה למיכל כו' ועוד משלמת מה שהזיקה מ' נזק שלם וקא' דאילפא ור\"א וכו' וכן מפורש בירושלמי שינתה ואכלה משלמת נ\"ש מהו שינתה ואכלה כשהיתה קופתו מופשלת לאחוריו היתה עומדת ברה\"ר ופשטה את פיה ואכלה ממנה משלמת נ\"ש ור\"ל שינתה ממה שפטרה התורה וכן בתוספתא משלמת מה שהזיקה וענ\"י רשב\"א וכ' הטעם שכל כה\"ג הוי כרשות הניזק שכן יש להם רשות לעבור כה\"ג וע\"ס שהאריך:","\u0003 (ליקוט) ואם קפצה כו' וה\"ה כו'. \u0004 כפי' הרי\"ף דנ\"ש משלם וכ\"ה בירושלמי שם שינתה ואכלה משלם נ\"ש מהו שינתה ואכלה משלם נ\"ש היתה קופתו מופשלת לאחוריו ברה\"ר ופשטה פרה את פיה ואכלה ממנה משלם נ\"ש (ע\"כ):","\u0003וי\"א כו'. \u0004 כן פי' הרא\"ש דברי הרי\"ף והגמרא וכמש\"ש כ\"א ב' דאילפא כו' ואמרו אין דרכה כו' ר\"ל כי א\"א לה אלא בקפיצה והטעם דכל כה\"ג שאין מגעת כדרכה יש לו רשות להניח פירותיו. שם:","\u0003בהמה כו'. \u0004 כגי' דל\"ג עמיר וס\"ל כתוס' דשניהם ברשות הניזק בעינן אלא כיון דקי\"ל דפי פרה כרשות הניזק דמי ר\"ל אם עומדת ברשות הניזק ה\"נ כיון דעומדת ברשות הניזק שדינן הפה בתר גופה או לא אבל לדעת הרמ\"ה דס\"ז א\"א לפרש אלא כפי' תוס' וכ\"כ הרשב\"א דהכל בתר אכילה ופי' כפי' תוס':","\u0003וה\"ה כו'. \u0004 כגי' שלנו וכפירש\"י וכבר הקשו תוס' ורשב\"א וש\"פ מהא דס\"ז ודברי רש\"י י\"ל דפי' שם ך\"ג א' כמ\"ש בס\"ז לדברי הרמ\"ה ואף שרש\"י שם ד\"ה: ה\"ג וליחייב כו' כ' וקס\"ד כי' האמת כן כמ\"ש רש\"י בברכות טו א' וש\"מ אבל דברי הרב צ\"ע וצ\"ל דה\"ק ואכלה בר\"ה ר\"ל שעמידתה בר\"ה ואכלה אבל פיה ברשות הניזק וקמיבעיא להו אם פיה בתר גופא גריר או לא וכן ברישא אף שרש\"י לא פי' כן ובזה ניחא אף לשיטת התוס':"]}],["כֶּלֶב שֶׁנָּטַל אֶת הַחֲרָרָה וְהָלַךְ לוֹ לְגָדִישׁ \u0005שֶׁל בַּעַל הַחֲרָרָה, (טוּר ס\"ה)\u0006, אִם הִנִּיחָהּ בַּגָּדִישׁ \u0010y0\u0011 וְאָכַל אֶת הַחַלָּה וְהִדְלִיק אֶת הַגָּדִישׁ, עַל הַחַלָּה \u0010y1\u0011 וְעַל מְקוֹם הַחֲרָרָה מְשַׁלֵּם נֶזֶק שָׁלֵם, וְעַל הַגָּדִישׁ חֲצִי נֶזֶק; \u0010y2\u0011 וְאִם הָיָה מְגָרֵר אֶת הַחַלָּה עַל הַגָּדִישׁ וְהוֹלֵךְ וְשׂוֹרֵף, מְשַׁלֵּם עַל הַחֲרָרָה נֶזֶק שָׁלֵם, וְעַל מְקוֹם הַגַּחֶלֶת חֲצִי נֶזֶק, וְעַל שְׁאָר הַגָּדִישׁ פָּטוּר. \u0005וְיֵשׁ אוֹמְרִים דִּמְשַׁלֵּם עַל כָּל הַגָּדִישׁ חֲצִי נֶזֶק (טוּר שָׁם וּבֵית יוֹסֵף בְּשֵׁם הָרַשְׁבָּ\"א)\u0006. בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁשָּׁמַר בַּעַל הַגַּחֶלֶת אֶת אִשּׁוֹ, וְסָגַר הַדֶּלֶת, \u0010y3\u0011 וּבָא הַכֶּלֶב וְחָתַר, וְנָטַל אֶת הַחֲרָרָה מֵעַל הָאֵשׁ; אֲבָל אִם לֹא שָׁמַר אִשּׁוֹ, \u0010y4\u0011 בַּעַל הָאֵשׁ חַיָּב עַל שְׂרֵפַת הַגָּדִישׁ, וּבַעַל הַכֶּלֶב חַיָּב עַל אֲכִילַת הַחֲרָרָה וְעַל מְקוֹמָהּ \u0005(וְכ\"כ הַטוּר בְּשֵׁם הרמ\"ה)\u0006. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּעַל מְקוֹם הַחֲרָרָה מְשַׁלֵּם \u0010y5\u0011 כָּל אֶחָד הַחֵצִי, וְעַל שְׁאָר הַגָּדִישׁ \u0010y6\u0011 בַּעַל הַכֶּלֶב נוֹתֵן רְבִיעַ, וּבַעַל הַגַּחֶלֶת ג' חֲלָקִים. וְאִם זְרָקָהּ עַל הַגָּדִישׁ, אָז מְשַׁלֵּם בַּעַל הַכֶּלֶב רְבִיעַ אֲפִלּוּ עַל מְקוֹם הַחֲרָרָה, וּבַעַל הַגַּחֶלֶת שְׁלֹשָׁה חֲלָקִים\u0006 \u0005(טוּר שָׁם)\u0006.",["\u0003ואכל את החלה. \u0004 הוא חררה הנ\"ל אלא מתחלה לשון המשנה נקט דקתני חררה ואח\"כ ל' הרמב\"ם דכתב ל' חלה ואח\"כ תפס לשניהן יחד וכתב על החלה ועל מקום החררה:","\u0003ועל מקום החרר'. \u0004 דכיון דהניח' שם ה\"ל היזק בידים וכי אורחי' הוא חייב עליהן בעל הכלב נזק שלם ועל שאר הגדיש דלא בא ההיזק אלא מגרמת הנח' ה\"ל כצרורות ומ\"ה בתשלומי ח\"נ סגי:","\u0003ואם הי' מגרר כו'. \u0004 אז מקום הגחלת מחשב לשינוי או צרורות מ\"ה בח\"נ סגי ועל הגדיש ס\"ל דפטו' דזה גרע מכח כחו דנתבא' בטור ובדברי המחב' בסי' ש\"ץ דחייב עליו ג\"כ ח\"נ ע\"ש:","\u0003ובא הכלב וחתר כו'. \u0004 דבזה בעל הגחל' פטו' כיון דשמר אשו כדנטרי אינשי ובעל הכלב חייב כיון דסתם דלתות חתורות הן אצל כלבים ה\"ל לשמו' כלבו שלא יחתור ויזיק:","\u0003בעל האש חייב על שריפת הגדיש כו'. \u0004 ל\"ד קאמר חייב דהא מסתמא בעל החררה הוא בעל האש שאפה חררתו בתנורו והגחלת היא שלו וגם הוא בעל הגדיש ולמה ישלם אלא בא לו' שגם בעל הגחלת הוא הגורם ההיזק ומ\"ה בעל הכלב אינו משלם אלא החצי היזק:","\u0003כ\"א החצי \u0004 דשניהן שותפין בהנזק:","\u0003בעל הכלב נותן רביע. \u0004 דמחשב לגביה שינוי ואם הוא עשה ההיזק לבדו לא הי' חייב אלא ק\"נ השתא דאיכא בעל הגחלת דהוא שותפו בהיזק פטרו מחצי חיובו ולא נשאר עליו אלא רביע ההיזק ובעל הגחלת עליו לשלם שלשה רביעיו' כיון דאם לא הי' בעל הכלב שותפו ובעל הגחלת הי' עושה ההיזק הי' עליו לשלם הכל כי אין שייך אצלו לפטור מהחצי מ\"ה נשאר עליו חוב שלשה רביעית היזק:"],[],"\u0010g0\u0011 כֶּלֶב שֶׁנָּטַל אֶת הַחֲרָרָה וְהָלַךְ לוֹ לְגָדִישׁ \u0005שֶׁל בַּעַל הַחֲרָרָה, (טוּר \u0010g1\u0011 ס\"ה)\u0006, אִם \u0010g2\u0011 הִנִּיחָהּ בַּגָּדִישׁ \u0010y0\u0011 וְאָכַל אֶת הַחַלָּה וְהִדְלִיק אֶת הַגָּדִישׁ, עַל הַחַלָּה \u0010y1\u0011 וְעַל מְקוֹם הַחֲרָרָה מְשַׁלֵּם נֶזֶק \u0010t0\u0011 שָׁלֵם, \u0010g3\u0011 וְעַל הַגָּדִישׁ חֲצִי נֶזֶק; \u0010y2\u0011 \u0010r0\u0011 וְאִם הָיָה \u0010t1\u0011 מְגָרֵר אֶת הַחַלָּה עַל הַגָּדִישׁ וְהוֹלֵךְ וְשׂוֹרֵף, מְשַׁלֵּם עַל הַחֲרָרָה נֶזֶק שָׁלֵם, וְעַל מְקוֹם הַגַּחֶלֶת חֲצִי נֶזֶק, \u0010g4\u0011 וְעַל שְׁאָר הַגָּדִישׁ פָּטוּר. \u0010r1\u0011 \u0005וְיֵשׁ אוֹמְרִים דִּמְשַׁלֵּם עַל כָּל הַגָּדִישׁ חֲצִי נֶזֶק (טוּר שָׁם וּבֵית יוֹסֵף בְּשֵׁם הָרַשְׁבָּ\"א)\u0006. \u0010g5\u0011 בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁשָּׁמַר בַּעַל הַגַּחֶלֶת אֶת אִשּׁוֹ, וְסָגַר הַדֶּלֶת, \u0010y3\u0011 וּבָא הַכֶּלֶב \u0010t2\u0011 וְחָתַר, וְנָטַל אֶת הַחֲרָרָה מֵעַל הָאֵשׁ; אֲבָל אִם לֹא שָׁמַר אִשּׁוֹ, \u0010y4\u0011 \u0010r2\u0011 בַּעַל הָאֵשׁ \u0010t3\u0011 חַיָּב עַל שְׂרֵפַת הַגָּדִישׁ, וּבַעַל הַכֶּלֶב חַיָּב עַל אֲכִילַת הַחֲרָרָה וְעַל מְקוֹמָהּ \u0005(וְכ\"כ הַטוּר בְּשֵׁם הרמ\"ה)\u0006. \u0005הַגָּה: \u0010r3\u0011 וְיֵשׁ אוֹמְרִים דְּעַל מְקוֹם הַחֲרָרָה מְשַׁלֵּם \u0010y5\u0011 כָּל אֶחָד \u0010t4\u0011 הַחֵצִי, וְעַל שְׁאָר הַגָּדִישׁ \u0010y6\u0011 בַּעַל הַכֶּלֶב נוֹתֵן רְבִיעַ, וּבַעַל הַגַּחֶלֶת ג' חֲלָקִים. \u0010r4\u0011 וְאִם זְרָקָהּ עַל הַגָּדִישׁ, אָז מְשַׁלֵּם בַּעַל הַכֶּלֶב רְבִיעַ אֲפִלּוּ עַל מְקוֹם הַחֲרָרָה, וּבַעַל הַגַּחֶלֶת שְׁלֹשָׁה חֲלָקִים\u0006 \u0010g6\u0011 \u0005(טוּר שָׁם)\u0006.",{"g":["א) לשון הרמב\"ם בפ\"ב מהלכות נזקי ממון די\"ז משנה שם דף כ\"א ע\"א והחררה הזו יש בה גחלים שכן דרך לאפותה עליהם","ב) אוקימתא דגמרא שם דף נ\"ג ע\"א","ג) אוקימתא אליבא דר' יוחנן דאמר אשו משום חציו שם דף כ\"ב ע\"א","ד) פי' רש\"י דחציו דכלב הוא והיינו צרורות","ה) הראב\"ד השיב בזה דצרורות ע\"י שינוי מרביע נזק מיהא לא מיפטר וכ' ה\"ה ואיני יודע לתרץ וכו' ואולי שהוא סובר כיון שהניח כלי חציו ושוב אינו מחויב על הגרירה כיון שלא נשרף הגדיש אלא מחמת הגרירה וצ\"ע והכ\"מ תירץ דהאי מגרר שכ' רבי' הוא אדיי אדויי וכמ\"ש התו' שם לכן פטור ולענ\"ד אין ל' רבינו סובל פירושו ועוד שהרי כ' בב\"י בשם הרשב\"א דכל שכן בדאדיי אדויי חייב לר' יוחנן ח\"נ וכן כ' הטור והביא הרמ\"ה בהג\"ה","ו) שם דין י\"ח וכתב ה\"ה בסוגיא (דף כ\"ג ע\"א וכגרסא שהיה לפני התוספת) ויש בה פי' אחר וגורסים ולחייב נמי בעל הגחלת (כגירס' שלפנינו וכן גורס רש\"י)","ז) וכ\"כ התוס' שם והטעם כיון דכי לית שותפא לא משלם אלא פלגא דהיינו רביע ובעל הגחלת משלם ג' חלקים משום דכל היכא דליכא לאשתלומי מהאי משתלם מהאי כדרב נתן שם דף ל\"ג ע\"א"],"t":["\u0003שלם. \u0004 דכיון דהניחה שם ה\"ל היזק בידים וכי אורחיה הוא. סמ\"ע:","\u0003מגרר. \u0004 דאז מקום הגחלת מחשב לשינוי או צרורות מש\"ה בח\"נ סגי. שם:","\u0003וחתר. \u0004 דבזה בעל הגחלת פטור כיון דשמר אשו כדנטרי אינשי ובעל הכלב חייב כיון דסתם דלתות חתורות הן אצל כלבים ה\"ל לשמור כלבו שלא יחתור ויזיק. שם:","\u0003חייב. \u0004 ל\"ד קאמר חייב דהא מסתמא בעל החררה הוא בעל האש שאפה חררתו בתנורו וגם הוא בעל הגדיש ולמה ישלם אלא בא לומר דגם בעל הגחלת הוא גורם ההיזק ומש\"ה בעל הכלב אינו משלם אלא ח\"נ. שם:","\u0003החצי. \u0004 דשניהן שותפין בהנזק. שם:"],"r":["\u0003ואם היה מגרר כו'. \u0004 עתוס' שם ד\"ה ור\"י כו' וכן הקשה הרשב\"א דהכין מיתוקמא שפיר טפי דא\"צ לחלק בין מקום הגחלת לשאר הגדיש אלא שכ' דה\"ק דאפשר לאוקמיה אליביה אף בדאנחיה משא\"כ לר\"ל וז\"ש וי\"א כו' ועמ\"ש בסי' ש\"ץ ס\"ה:","\u0003 (ליקוט) וי\"א דמשלם כו'. \u0004 הרא\"ש ע\"ש אלא שכ' שתוס' לא פי' כן והוא דברי תוס' שם ד\"ה ור' יוחנן כו' אבל יש\"ש כ' דתוס' כ' כן משום סומכוס דאוקמינן שם י\"ח דברי ר\"א כסומכוס ודבריו תמוהין דא\"כ הל\"ל דאי לאו ככחו דמי ח\"נ הוא דמשלם וקשה לר\"א אבל קושית התוס' אפשר לתרץ כדברי יש\"ש (ע\"כ): [","\u0003בעל האש כו'. \u0004 כפשטיה דגמ' וליחייב כו':","\u0003וי\"א כו'. \u0004 תוס' ד\"ה וליחייב כו' פי' כו' וכמ\"ש בסי' ש\"צ ס\"י:","\u0003ואם זרקה כו'. \u0004 כשיטתו בהג\"ה ראשונה וי\"א דמשלם כו'. וכ\"ז לפי' הראב\"ד והרמ\"ה שכ' בסי' שצא ס\"ה אבל לשיטת התוס' ר\"ל שיפטר בעל הכלב מחלקו וע\"ש ד\"ה וליחייב השני:"]}],["הִכְנִיס \u0010y0\u0011 פֵּרוֹתָיו לַחֲצַר בַּעַל הַבַּיִת \u0005(שֶׁלֹּא בִּרְשׁוּת)\u0006 וַאֲכָלָתָן בְּהֶמְתּוֹ שֶׁל בַּעַל הַבַּיִת, פָּטוּר. \u0005וַאֲפִלּוּ הָיָה בַּעַל הֶחָצֵר טוֹחֵן, וְהֵבִיא זֶה חִטִּים \u0010y1\u0011 לִטְחֹן שֶׁיִּשְׂתַּכֵּר בָּהֶן בַּעַל הֶחָצֵר, אֲפִלּוּ הָכִי מִקְרֵי שֶׁלֹּא בִרְשׁוּת (טוּר ס\"א)\u0006. וְאִם הֻחְלְקָה בָּהֶם וְהֻזְּקָה, בַּעַל \u0010y2\u0011 הַפֵּרוֹת חַיָּב. וְאִם הִכְנִיס בִּרְשׁוּת, פָּטוּר. \u0005וְיֵשׁ חוֹלְקִין (טוּר בְּסִימָן צ\"א וְסִימָן שצ\"ח בְּשֵׁם ר\"י וְהָרֹא\"שׁ)\u0006. כְּמוֹ שֶׁיִּתְבָּאֵר לְקַמָּן סוֹף סִימָן שצ\"ח. וְאִם קִבֵּל עָלָיו \u0010c0\u0011 בַּעַל הַבַּיִת לִשְׁמֹר אֶת הַפֵּרוֹת, בַּעַל הַבַּיִת חַיָּב.\nהִכְנִיסָן שֶׁלֹּא בִּרְשׁוּת, וַאֲכָלָתָן בְּהֶמְתּוֹ שֶׁל בַּעַל הַבַּיִת וְהֻזְּקָה בַּאֲכִילָתָן, בַּעַל הַפֵּרוֹת פָּטוּר, מִפְּנֵי \u0010y3\u0011 שֶׁהָיָה לָהּ שֶׁלֹּא תֹּאכַל.\nהִכְנִיסָן בִּרְשׁוּת וְהִנִּיחוּ בַּעֲלֵי הֶחָצֵר אֶת זֶה שֶׁהִרְשׁוּהוּ בֶּחָצֵר לְשָׁמְרוֹ, וַאֲכַלְתָּן בְּהֶמְתּוֹ שֶׁל בַּעַל הַבַּיִת וְהֻזְּקָה בַּאֲכִילָתָן, בַּעַל הַפֵּרוֹת חַיָּב, שֶׁכֵּיוָן שֶׁרָאָה הַבְּהֵמָה אוֹכֶלֶת דְּבָרִים הַמַּזִּיקִים לָהּ וְהִנִּיחָהּ, חַיָּב, שֶׁהֲרֵי אֵין בַּעֲלֵי הֶחָצֵר מְצוּיִים שָׁם לְהַעֲבִיר הַבְּהֵמָה מֵהֶם. \u0010y4\u0011 וּמַעֲשֶׂה בְּאִשָּׁה אַחַת שֶׁנִּכְנְסָה בְּבֵית שְׁכֶנְתָּהּ לָלוּשׁ וְלֶאֱפוֹת, וְהִנִּיחוּהָ וְנִתְעַלְּמוּ \u0010y5\u0011 כְּדֵי שֶׁלֹּא יַבִּיטוּ בָּהּ בְּעֵת לִישָׁתָהּ וַאֲפִיָּתָהּ, וּבָא עֵז שֶׁל בַּעַל הַבַּיִת וְאָכַל הַבָּצֵק וָמֵת, וְחִיְּבוּהָ חֲכָמִים לְשַׁלֵּם דָּמָיו; וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0010y6\u0011\nהַמַּגְדִּישׁ בְּתוֹךְ שְׂדֵה חֲבֵרוֹ שֶׁלֹּא בִּרְשׁוּת, וַאֲכָלָתָם בְּהֶמְתּוֹ שֶׁל בַּעַל הַשָּׂדֶה, פָּטוּר. וְאִם הֻחְלְקָה בָּהֶם וְהֻזְּקָה, בַּעַל הַפֵּרוֹת חַיָּב. אֲכַלְתָּן וְהֻזְּקָה בַּאֲכִילָתָן, פָּטוּר. וְאִם הִגְדִּישׁ בִּרְשׁוּת בַּעַל הַשָּׂדֶה, חַיָּב אַף עַל פִּי שֶׁלֹּא קִבֵּל עָלָיו לִשְׁמֹר, שֶׁהַשּׁוֹמֵר בַּגְּרָנוֹת כֵּיוָן שֶׁאָמַר לוֹ: הַגְדֵּשׁ בְּכָאן, כְּמִי שֶׁאָמַר לוֹ: הַגְדֵּשׁ וַאֲנִי אֶשְׁמֹר לְךָ, הוּא חָשׁוּב:",["\u0003הכניס פירותיו לחצר בעל הבית שלא ברשות ואכלתן כו'. \u0004 כצ\"ל וכן הוא במיימוני פ\"ג דניזקין וכלל דבריו הן דבעל החצר פטור בהיזק פירותיו כיון דשלא ברשות הכניסן ומה\"ט אם הוזקה בהן פרה של בעל הבית אז בעל הפירות חייב לשלם לו הזיקו מיהו ה\"מ שהוזק' בהן מוכח שהוחלק' בהפירו' אבל אם הוזקה מכח רוב האכילה פטור בעל הפירות מהיזקה דעל ב\"ה הוא מוטל לשומרה מאכילה יתירא כדמסיק המחבר בסעי' שאחר זה:","\u0003שישתכר בהן בעל החצר \u0004 שיתן לו שכירות מהטחינה:","\u0003ואם הכניס ברשות פטור. \u0004 ע\"ל סי' שצ\"ח שכ' הטור פלוגתת הגאונים בזה דר\"י והרא\"ש פסקו כרבנן דאמרו כל שנתן לחבירו רשות להכניס פירות קיבל עליו שמירת הפירות והרי\"ף והרמב\"ם פסקו כר' דאמ' אף אם נתן לו רשות להכניס לא הוה כאילו קיבל עליו נטירותא מיהו ה\"מ שלא נתחייב בעל החצר בתשלומי היזק בעל הפירות אם הזיקו שורו לפירות שהכניס אבל כ' שם דלכ\"ע אין בעל הפירות חייב בנזקי דבעל החצר אם הוזק שורו דבעל חצר בפירותיו ע\"ש וז\"ש המחבר כאן דאם הכניס ברשות פטור דאף דפסק המחבר כהרי\"ף והרמב\"ם דסתם נתינת רשות לא הוי כקיבל עליו שמירת הפירות מ\"מ בעל הפירות אינו חייב באשר הוזק בהן שורו דבעל החצר וא\"כ תימא על מור\"ם שמסיק וכתב כאן על דברי המחבר דיש חולקין כמ\"ש בסי' שצ\"ח דהא שם לא פליגי אלא אם נתחייב בעל החצר בהיזק דבעל הפירות ומזה לא איירי המחב' כאן אלא בפטו' דבעל הפירות בהיזק דבעל החצר (דהא ואם הכניס ברשות פטור דכתב האי פטור קאי אמ\"ש לפני זה דחייב בו בהכניסה שלא ברשות) ובזה כ\"ע מודו וצריכין לדחוק ולו' דס\"ל למור\"ם דמדסיים המחב' וכתב ז\"ל ואם קיבל עליו בעל הבית לשמו' את הפירו' ב\"ה חייב ולפני זה לא נזכר שום פטר בהב\"ה והוצרך לכתוב דבקבל עליו השמירה דחייב צ\"ל דמ\"ש המחב' אם הכניס ברשות פטו' שכל א' פטו' משילום הזיקו דחבירו ונשמע מיניה דס\"ל להמחב' דגם ב\"ה פטו' משילום הזיקו דהנכנס אם הזיק שורו לשורו דהנכנס ועל זה כ' מור\"ם דיש חולקין אבל פי' זה דוחק כיון דלא נזכר לפני זה מחיובו דב\"ה:","\u0003שהי' לה שלא תאכל \u0004 פי' הי' לו לשמור פרתו שלא תאכל יותר משיעור' וזה דוקא מסתמא כשבעל החצר בחצירו אבל אם נסתלק משם בעל החצר בידיעת בעל הפירות על בעל הפירות מוטל השמירה שלא תאכל יותר מדאי אפי' אם הכניס ברשות וכמ\"ש בסעיף שאחר זה:","\u0003ומעשה באשה א' כו'. \u0004 מתחל' כתב המחבר דברי הרמב\"ם בנסתלק בעל החצר בידיעת בעל הפירו' והניח עליו השמירה דבעל הפירות הי' לו לשומרו ובמעשה זה בא להוסיף דאף דנסתלק בעל החצר שלא בידיעת בעל הפירות אפ\"ה אם בעל הפירות עושה דבר צניעות דמסתמא יסתלק עבורו בעל החצר ויצא באותה שעה שעוש' דבר הצניעות ה\"ל כאילו הודיעו שיצא ובעל הפירות חייב בשמירת בהמה דבעל החצר אפילו לענין שלא תאכל יותר מדאי ותוזק:","\u0003כדי שלא יביטו בה כו' \u0004 פי' שלא יביטו זרועותי' המגולות בעת לישתה העיסה:","\u0003המגדיש בתוך שדה חבירו כו' כל' המחבר כן הוא ל' הרמב\"ם בספ\"ג דנ\"מ ויש לדקדק בדבריהן שסיים וכ' שהשומר בגרנו כיון שא\"ל הגדש כו' ולפני זה לא הזכירו בדבריהן דמיירי שיש בהשד' שומר לשמור השד' ושהוא נתן לבעל הפירות רשות ליכנס ואדרבא כ' אם הגדיש ברשות בעל השדה דמשמע דאיירי דבעל השדה נתן לו רשות להגדיש ולא השומר וליישב זה צ\"ל דהן איירי בבעל השדה שהוא עצמו שומר השדה ואפשר דדרכן הי' בכך מ\"ה סתמו ולא הוצרכו לכותבו וא\"ש כיון דבעל השדה הוא עצמו השומר והוא הנותן לו רשות להגדיש מ\"ה הרי\"ף והרמב\"ם מודים בזה דאף בעלמא לא אמרינן עול ואנטר לך קאמר בזה דבל\"ה משמר השדה ויושב בצדו דה\"ל סתמא כאילו קיבל עליו שמירתו ונראה שגם הרא\"ש שכ' בפסקיו דיש נ\"מ גם לרבנן בשומר דהעלוהו מעלה א' ויהי' שלא ברשות דידיה כסתמא דעלמא דלא כתב כך אלא כשהבעל השדה עצמו הוא השומר דאל\"כ הוא נגד הסברא דיכניס זה גדישו לשדה חבירו שלא ברשות כלל ויחייב לבעל השדה בשמירתו אבל הטור מפרש בדבריו דלא מוקי להגמרא כן אלא פי' דהגמרא איירי כשבעל השדה יש לו שומר בפני עצמו המשמר בשדה שהרי כתב ואם א\"ל שומר השדה כנוס ותגדיש אף ע\"פ שלא א\"ל בעל השדה כנוס ע\"ש ובזה נתיישב התמיה הגדולה שיש להקשות על דברי הטור במ\"ש נגד דברי אביו דהרא\"ש כתב דאפי' בלא רשות ה\"ל לרבנן כאלו נתן רשות והטור כתב דבעינן עכ\"פ שיתן השומר רשות להגדיש ובמ\"ש ניחא אלא שעדיין ק' למה השמיט הטור דינו דהרא\"ש אביו ולפי מה שישבתי בפרישה עוד בע\"א א\"ש וק\"ל:\u0004"],["\u0003 בעל הבית חייב כו'. \u0004 נ\"ל דכאן שייך הי\"ח וק\"ל:"],"הִכְנִיס \u0010y0\u0011 \u0010g0\u0011 פֵּרוֹתָיו לַחֲצַר בַּעַל הַבַּיִת \u0005(שֶׁלֹּא בִּרְשׁוּת)\u0006 וַאֲכָלָתָן בְּהֶמְתּוֹ שֶׁל בַּעַל הַבַּיִת, פָּטוּר. \u0010r0\u0011 \u0005וַאֲפִלּוּ הָיָה בַּעַל הֶחָצֵר טוֹחֵן, וְהֵבִיא זֶה חִטִּים \u0010y1\u0011 לִטְחֹן שֶׁיִּשְׂתַּכֵּר בָּהֶן בַּעַל הֶחָצֵר, אֲפִלּוּ הָכִי מִקְרֵי שֶׁלֹּא בִרְשׁוּת \u0010g1\u0011 (טוּר ס\"א)\u0006. וְאִם הֻחְלְקָה בָּהֶם וְהֻזְּקָה, בַּעַל \u0010y2\u0011 הַפֵּרוֹת חַיָּב. וְאִם הִכְנִיס בִּרְשׁוּת, פָּטוּר. \u0010g2\u0011 \u0010r1\u0011 \u0005וְיֵשׁ חוֹלְקִין (טוּר בְּסִימָן צ\"א וְסִימָן שצ\"ח בְּשֵׁם ר\"י וְהָרֹא\"שׁ)\u0006. כְּמוֹ שֶׁיִּתְבָּאֵר לְקַמָּן סוֹף סִימָן שצ\"ח. \u0010g3\u0011 וְאִם קִבֵּל עָלָיו \u0010c0\u0011 בַּעַל הַבַּיִת \u0010g4\u0011 לִשְׁמֹר אֶת הַפֵּרוֹת, בַּעַל הַבַּיִת חַיָּב.\nהִכְנִיסָן שֶׁלֹּא בִּרְשׁוּת, וַאֲכָלָתָן בְּהֶמְתּוֹ שֶׁל בַּעַל הַבַּיִת וְהֻזְּקָה בַּאֲכִילָתָן, בַּעַל הַפֵּרוֹת פָּטוּר, מִפְּנֵי \u0010y3\u0011 \u0010t0\u0011 שֶׁהָיָה לָהּ שֶׁלֹּא תֹּאכַל. \u0010g5\u0011\nהִכְנִיסָן בִּרְשׁוּת וְהִנִּיחוּ בַּעֲלֵי הֶחָצֵר אֶת זֶה שֶׁהִרְשׁוּהוּ בֶּחָצֵר לְשָׁמְרוֹ, וַאֲכַלְתָּן בְּהֶמְתּוֹ שֶׁל בַּעַל הַבַּיִת וְהֻזְּקָה בַּאֲכִילָתָן, בַּעַל הַפֵּרוֹת חַיָּב, שֶׁכֵּיוָן שֶׁרָאָה הַבְּהֵמָה אוֹכֶלֶת דְּבָרִים הַמַּזִּיקִים לָהּ וְהִנִּיחָהּ, חַיָּב, שֶׁהֲרֵי אֵין בַּעֲלֵי הֶחָצֵר מְצוּיִים שָׁם לְהַעֲבִיר הַבְּהֵמָה מֵהֶם. \u0010y4\u0011 \u0010g6\u0011 וּמַעֲשֶׂה בְּאִשָּׁה אַחַת שֶׁנִּכְנְסָה בְּבֵית שְׁכֶנְתָּהּ לָלוּשׁ וְלֶאֱפוֹת, וְהִנִּיחוּהָ וְנִתְעַלְּמוּ \u0010y5\u0011 כְּדֵי שֶׁלֹּא \u0010t1\u0011 יַבִּיטוּ בָּהּ בְּעֵת לִישָׁתָהּ וַאֲפִיָּתָהּ, וּבָא עֵז שֶׁל בַּעַל הַבַּיִת וְאָכַל הַבָּצֵק וָמֵת, וְחִיְּבוּהָ חֲכָמִים לְשַׁלֵּם דָּמָיו; וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0010y6\u0011 \u0010g7\u0011 \u0010t2\u0011\nהַמַּגְדִּישׁ בְּתוֹךְ שְׂדֵה חֲבֵרוֹ שֶׁלֹּא בִּרְשׁוּת, וַאֲכָלָתָם בְּהֶמְתּוֹ שֶׁל בַּעַל הַשָּׂדֶה, פָּטוּר. וְאִם הֻחְלְקָה בָּהֶם וְהֻזְּקָה, בַּעַל הַפֵּרוֹת חַיָּב. אֲכַלְתָּן וְהֻזְּקָה בַּאֲכִילָתָן, פָּטוּר. וְאִם הִגְדִּישׁ בִּרְשׁוּת בַּעַל \u0010g8\u0011 הַשָּׂדֶה, חַיָּב אַף עַל פִּי שֶׁלֹּא קִבֵּל עָלָיו לִשְׁמֹר, שֶׁהַשּׁוֹמֵר בַּגְּרָנוֹת \u0010g9\u0011 \u0010r2\u0011 כֵּיוָן שֶׁאָמַר לוֹ: הַגְדֵּשׁ בְּכָאן, כְּמִי שֶׁאָמַר לוֹ: הַגְדֵּשׁ וַאֲנִי אֶשְׁמֹר לְךָ, הוּא חָשׁוּב: \u0010g10\u0011",{"g":["א) ל' הרמב\"ם בפ\"ג מה' נזקי ממון די\"ד משנה פ\"ה דב\"ק דף מז ע\"א","\u0003ב) מבריי' האשה שנכנסה לטחון וכו'\u0004 שם ע\"ב וכן כ' הרשב\"א אם הוחלקה והוזקה בהמתו של בעל הבית וה\"ה אם אכלתן בהמתו של ב\"ה נמי פטור","\u0003ונלפע\"ד שהגה זו קאי אחלוקה שניה מ\"ש ואם קיבל עליו וכו'\u0004 ומקומה בסוף הסעיף ומחלוקתה מבואר בס\"ס שנ\"ח","ג) כרבי שם במשנה וכשמואל דפכק כוותיה בגמ' שם דף מ\"מ ע\"ב וכתב ה\"ה ואף רבי לא אמרה דבעי קבלה בפי' אלא להתחייב בעל הבית בנזקי בעל הפירות אבל להפטר בעל הפירות מנזקי בעל החצר כיון שהרשהו להכנס פטור ונכון הוא וכן דעת התו' וגם הרא\"ה הודה לו בהשגות","ד) אוקימתא דרב אמתניתין שם","\u0003ה) שם מעובדא דההיא איתתא וכו'\u0004 וחייבה רבא דף מ\"ח ע\"א","\u0003ו) היינו עובדא דההיא איתתא וכו'\u0004 ","ז) שם ד\"ט משנה שם פ\"י דף נ\"ט ע\"ב","ח) אוקימתא דרב פפא שם הכא בנטר בי דרי עסקינן וכ\"כ הראב\"ד שם דוקא בשומר בית הגרנות","ולפענ\"ד צ\"ע שלא העתיק הרב רמ\"א לדעת הרא\"ש שס\"ל כדעת ר\"י ופסק כחכמים ולא צריך לאוקמי בנטר בי דרי שכתב הרא\"ש דנ\"מ בהך דרב פפא שבשומר הגרנות אפילו לא א\"ל כלום חייב וכמו שתמה הב\"י על הטור","☜דין ראובן שהעמיד בהמתו בבית שמעון במאמרו ולא קשרה ולעסה כר ומפה של שמעון בכלל ק\"א סי\"ד"],"t":["\u0003שהיה. \u0004 פירוש דה\"ל לשמור פרתו שלא תאכל יותר משיעורה וזה דוקא מסתמא כשבעל החצר בחצירו אבל לא בנסתלק משם כמ\"ש בסעיף שאח\"ז. סמ\"ע:","\u0003יביטו. \u0004 פירוש שלא יביטו זרועותיה המגולות בעת לישתה ובמעשה זה בא המחבר להוסיף דאף שנסתלק בעל החצר שלא בידיעת בעל הפירות אפ\"ה אם מסתמא יסתלק בעל החצר ויצא עבור דבר צניעות שעושה בעל הפירות ה\"ל כאילו הודיעו שיצא וחייב בעל הפירות בשמירת בהמת בעל החצר אפילו לענין שלא תאכל יותר מדאי ותוזק. שם:","\u0003המגדיש. \u0004 עמ\"ש הסמ\"ע שיש לחלק בזה בין אם בעל השדה עצמו שומר השדה או שיש לו שומר אחר ומבאר בזה פלוגתת הפוסקים בדין זה עיין שם:"],"r":["\u0003ואפי' היה כו'. \u0004 עתוס' שם ד\"ה שנכנסה כו':","\u0003וי\"ח כו'. \u0004 עס\"ס שצח:","\u0003כיון שא\"ל כו'. \u0004 עבה\"ג והרא\"ש שם:"]}],["בְּהֵמָה שֶׁהֻחְלְקָה בְּאֶבֶן אוֹ בְּמֵימֵי רַגְלַיִם, וְנָפְלָה לְגִנָּה, וְנֶחְבְּטָה עַל גַּבֵּי פֵּרוֹת וִירָקוֹת, אוֹ \u0010y0\u0011 שֶׁאָכְלָה, מְשַׁלֵּם מַה שֶּׁנֶּהֱנֵית. \u0010y1\u0011 אֲפִלּוּ הָלְכָה מֵעֲרוּגָה לַעֲרוּגָה, וַאֲפִלּוּ נִשְׁאֲרָה שָׁם כָּל הַיּוֹם כֻּלּוֹ, אֵינוֹ מְשַׁלֵּם אֶלָּא מַה שֶּׁנֶּהֱנֵית. וּמַה הֲנָאָה יֵשׁ לָהּ בַּחֲבָטָה, שֶׁהֲרֵי מָצְאָה מָקוֹם רַךְ \u0010c0\u0011 וְלֹא נִתְרַסְקוּ אֵיבָרֶיהָ. אֲבָל אִם יָרְדָה כְּדַרְכָּהּ וְאָכְלָה, מְשַׁלֵּם מַה \u0010y2\u0011 שֶּׁהִזִּיקָה. וַאֲפִלּוּ טִנְּפָה פֵּרוֹת בְּמֵי לֵדָה, מְשַׁלֵּם מַה שֶּׁהִזִּיקָה, מִפְּנֵי שֶׁתְּחִלָּתוֹ בִּפְשִׁיעָה. וְכֵן אִם דְּחָפָהּ חֲבֶרְתָּהּ וְנָפְלָה, מְשַׁלֵּם מַה שֶּׁהִזִּיקָה, מִפְּנֵי שֶׁהָיָה לוֹ לְהַעֲבִירָם אַחַת אַחַת כְּדֵי שֶׁלֹּא יִדְחֲפוּ זוֹ אֶת זוֹ \u0005(וְכֵן דַּעַת הָרִי\"ף)\u0006. \u0005הַגָּה: \u0010y3\u0011 וְיֵשׁ אוֹמְרִים דְּאִם דְּחָפָהּ חֲבֶרְתָּהּ לֹא מִקְרֵי פְשִׁיעָה, אֶלָּא הָוֵי אֹנֶס וּפָטוּר\u0006 \u0005(טוּר ס\"ג בְּשֵׁם ר\"י והרמ\"ה וְהָרֹא\"שׁ)\u0006. \u0010y4\u0011 \u0005אִם הֶעֱבִירָהּ אֵצֶל גִּנַּת חֲבֵרוֹ וְהָיָה אֶפְשָׁר לָהּ לֵירֵד וְלִכָּנֵס לַגִּנָּה, אֲפִלּוּ נָפְלָה בְּאֹנֶס חַיָּב, דְּהָוֵי תְּחִלָּתוֹ בִּפְשִׁיעָה וְסוֹפוֹ בְּאֹנֶס\u0006 \u0005(טוּר ס\"א וְתוֹסָפוֹת וְהָרֹא\"שׁ)\u0006. \u0005וְיֵשׁ מִי שֶׁחוֹלֵק בְּזֶה\u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם הָרַשְׁבָּ\"א בְּשֵׁם הָרַאֲבַ\"ד)\u0006.\nהֻחְלְקָה וְנָפְלָה וְיָצְאָה \u0005וְהוּא יָדַע (טוּר ס\"ב)\u0006, וְחָזְרָה לַגִּנָּה, אַף עַל פִּי שֶׁחָזְרָה שֶׁלֹּא לְדַעַת הַבְּעָלִים, מְשַׁלֵּם מַה שֶּׁהִזִּיקָה, מִפְּנֵי \u0010y5\u0011 \u0010c1\u0011 שֶׁהָיָה לוֹ לְשָׁמְרָהּ שֶׁלֹּא תַּחֲזֹר, שֶׁהַדָּבָר יָדוּעַ שֶׁכֵּיוָן שֶׁיָּדְעָה דֶרֶךְ הַגִּנָּה הֲרֵי הִיא חוֹזֶרֶת מֵאֵלֶיהָ. \u0005הַגָּה: \u0010c2\u0011 מִיהוּ, אִם שְׁמָרָהּ בִּשְׁמִירָה מְעֻלָּה וְיָצְאָה וְהִזִּיקָה, פָּטוּר (טוּר)\u0006. \u0010y6\u0011\nהַמַּעֲמִיד בֶּהֱמַת חֲבֵרוֹ עַל גַּבֵּי קָמַת חֲבֵרוֹ, הַמַּעֲמִיד חַיָּב לְשַׁלֵּם מַה שֶּׁהִזִּיקָה. וְכֵן אִם הִכִּישָׁהּ \u0005(פֵּרוּשׁ, הִכָּה אוֹתָהּ)\u0006 עַד שֶׁהָלְכָה לְקָמַת חֲבֵרוֹ וְהִזִּיקָה, זֶה שֶׁהִכִּישָׁהּ חַיָּב. \u0005הַגָּה: \u0010y7\u0011 וַאֲפִלּוּ הַפֵּרוֹת בִּרְשׁוּת הָרַבִּים, דְּהָוֵי כְּמַזִּיק בְּיָדַיִם (המ\"מ פ\"ד מִנִּזְקֵי מָמוֹן וּבֵית יוֹסֵף בְּשֵׁם רַשְׁבָּ\"א)\u0006. וְדַוְקָא הִכִּישָׁהּ וְכַיּוֹצֵא בָּזֶה, אֲבָל קָם לָהּ בְּאַפָּהּ עַד שֶׁהָלְכָה שָׁם, פָּטוּר, דְּהָוֵי גְרָמָא בִנְזָקִין \u0005(הַמַּגִּיד שָׁם, וּדְלָא כְּדַעַת הָרַאֲבַ\"ד)\u0006.\nכָּל \u0010y8\u0011 בְּהֵמָה שֶׁהִזִּיקָה פֵּרוֹת מְחֻבָּרִים, מְשַׁעֲרִים מַה שֶּׁהִזִּיקָה בְּשִׁשִּׁים וּמְשַׁלֵּם מִי שֶׁנִּתְחַיֵּב לְשַׁלֵּם. כֵּיצַד, הֲרֵי שֶׁאָכְלָה בֵּית סְאָה, שָׁמִין שִׁשִּׁים בֵּית סְאָה בְּאוֹתָהּ הַשָּׂדֶה כַּמָּה הָיָה שָׁוֶה, וְכַמָּה הוּא שָׁוֶה עַתָּה אַחַר שֶׁנִּפְסַד בּוֹ הַבֵּית סְאָה, וּמְשַׁלֵּם הַשְּׁאָר. \u0010y9\u0011 וְכֵן אִם אָכְלָה קַב אוֹ רֹבַע, אֲפִלּוּ קֶלַח אֶחָד, שָׁמִין אוֹתוֹ בְּשִׁשִּׁים.\nאָכְלָה פֵּרוֹת גְּמוּרִים שֶׁאֵינָם צְרִיכִים לַקַּרְקַע, מְשַׁלֵּם דְּמֵי פֵרוֹת גְּמוּרִים בְּשִׁוּוּיֵיהֶן, אִם סְאָה דְּמֵי סְאָה, וְאִם סְאָתַיִם דְּמֵי סְאָתַיִם.\nהֲרֵי שֶׁאָכְלָה פֵּרוֹת דֶּקֶל אֶחָד, \u0010y10\u0011 וְכֵן הַקּוֹצֵץ פֵּרוֹת דֶּקֶל חֲבֵרוֹ וְאָכַל, אִם הָיָה דֶקֶל רוֹמִי וְכַיּוֹצֵא בּוֹ שֶׁאֵין הַתְּמָרִים שֶׁלּוֹ יָפוֹת, מְשַׁעֲרִים אוֹתוֹ בְּשִׁשִּׁים עַל גַּבֵּי הַקַּרְקַע; וְאִם דֶּקֶל פַּרְסִי וְכַיּוֹצֵא בּוֹ הוּא, שֶׁהַתְּמָרִים שֶׁלּוֹ יָפוֹת בְּיוֹתֵר, מְשַׁעֲרִים הַדֶּקֶל בִּפְנֵי עַצְמוֹ, כַּמָּה הָיָה שָׁוֶה וְכַמָּה הוּא שָׁוֶה עַתָּה. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאִם לֹא נִגְמַר גִּדּוּלוֹ מְשַׁעֲרִין בְּשִׁשִּׁים, \u0010y11\u0011 וְאִם נִגְמַר גִּדּוּלוֹ מְשַׁעֲרִין כְּמוֹ שֶׁהוּא (טוּר ס\"ו)\u0006.",["\u0003משלם מה שנהנית כו'. \u0004 פי' ולא כל מה שהזיק' החילוק שבין דא לדא כ' הטור והמחבר בסי' שצ\"א ס\"ח ע\"ש:","\u0003ואפי' הלכה מערוג' לערוג' כו'. \u0004 פי' ואפי' בעל הבהמה ידע מזה דמזל רע דבעל השדה הוא דגרם ליה ההיזק:","\u0003ואפי' טנפה פירות כו'. \u0004 פי' אף שלא אכלם וזה שילדה וטנפ' הי' אונס דלא ה\"ל למיסק אדעתיה שתלד ותטנף אפי' הכי משלם אפי' כל ההוזק כיון דתחלתי' הוה בפשיעה דה\"ל לשומר' שלא תלך שם ותרד ותאכל הפירות וברישא מיירי שנפל' ממקו' שלא הי' לה לירד שם דרך הטבע אם לא שהוחלק' ונפלה שם באונס מ\"ה אינו משלם אלא מה שנהני' כ\"כ בטור ועמ\"ש מור\"ם בהג\"ה ובסמוך דיש חולק ע\"ז דתחלתו בפשיעה וסופו באונס:","\u0003וי\"א דאם דחפוה חבירת' כו'. \u0004 דאע\"ג דנתבאר בטור ובדברי המחבר לעיל בסי' ש\"ג סי\"א בש\"ש דבכה\"ג חייב לאו משום דהו' כפשיעה אלא דה\"ל כגניב' ואביד' דש\"ש חייב בו משא\"כ בשן ורגל דאין אדם מחויב לשמור בהמתו אלא שמירה פחות' כמ\"ש בר\"ס שצ\"ו ומחשב בהן זה לאונס ועד\"ר:","\u0003אם העביר' כו'. \u0004 והי' אפשר לה לירד כו' ומ\"ש המחבר בר\"ס זה יש לפרשו דלא הי' אפשר לה לירד וכמ\"ש לפני זה ובטו' כתב עוד ז\"ל או אפילו שאי אפשר שתרד ונפלה שם שלא באונס ג\"כ משלמת כל מה שהזיק' ור\"ל כגון שהיא הולכת במקו' גבוה והשדה בגיא ושינת' זו את טבע שאר הבהמות וקפצה לאכול הפירות שראת' שם","\u0003שהיה לו לשומר'. \u0004 פי' שמיר' מעול'. ופי' שמירה מעולה או פחות' תמצא בר\"ס שצ\"ו ובטור ובדברי המחבר:","\u0003המעמיד בהמת חבירו כו' \u0004 וכ\"ש בהמה שלו:","\u0003ואפי' הפירות בר\"ה ואע\"ג דבהיזק שן ורגל נתבאר בסימן שצ\"א דאם הזיק בהן בר\"ה אין בעל הבהמה משלם אלא (ח\"נ) מה שנהנית שאני הכא כיון דהעמידו שם ה\"ל כמזיק הפירות בידים וכדמסיק ומ\"ה משלם נ\"ש:\u0004","\u0003משמרין מה שהזיקה בס' כו' \u0004 ילפינן לה מדכתיב וביער בשד' אחר בבי\"ת דהול\"ל וביער שדה אחר ודרשינן דההיזק והביער ישער אגב שדה אחר והיינו דלא ישומו כמה היה שוה בית סאה זו הנאכל לחוד דהי' שוה טובא והי' מפסיד המזיק הרבה אלא משערינן אם אדם בא ליקח ס' כמו שיעור זה דהוזק כמה היה נותן בעדו דרך משל ס' זהו' וכמה הי' פוחת בשביל בית סאה זו שנאכל דדרך העולם הוא דלא הי' פוחת עבור זה כל שווי' בית סאה וגם אין שמין בית סאה זו הנאכל אגב שדה שלימה דלא הי' פוחת הקונה עבור זה כ\"א דבר מועט והיה נפסד הניזק טובא לכך נתנו שיעור ממוצע לשער בס' כשיעור הנאכל ואע\"ג דדרשינן זה מדכתיב וביער ובשדה אחר ילפינן נמי מינ' דדוקא כשהזיק' ברשות הניזק הוא דחייב לאפוקי הזיק' בר\"ה והיינו מדכתב' התורה גבי וביער ולא כתב' גבי דין תשלומין מיטב שדהו ישלם בשדה אחר ועד\"ר:","\u0003וכן אם אכלה קב כו'. \u0004 שמין אותו בששים כמו זה הנאכל ולאפוקי ממ\"ד דמשערינן לעולם אפי' קלח א' אגב סאה בס' סאין ועפ\"ר:","\u0003וכן הקוצץ כו'. \u0004 פי' בין שאכלה הבהמה בין שקוצץ האדם עצמו יש חילוק בין אם היו הפירות מדקל משובח או מדקל שאינו משובח כ\"כ:","\u0003ואם נגמר גדולו כו' \u0004 הטור כ\"כ אקוצץ אילן עצמו וחילק בין אם היה נגמר כ\"כ עד שהי' ראוי לשתלו במקום אחר או לא ומור\"ם ז\"ל אף שסדרו אמ\"ש המחבר לפני זה דמדבר בקוצץ פירות מ\"מ מוכרח דכוונתו אאילן הנזכר בכלל דברי המחבר שלפני זה מדכתב ב\"פ נגמרה גדולו ואי אפירות קאי הל\"ל אי נגמר גידולן וק\"ל:"],["\u0003 ולא נתרסק וכו'. \u0004 מלשון זה משמע דאם לא נתרסקו אבריה אלא הי' לה צער בעלמא לא הי' צריך לשלם כלל אבל אי יש לספק בזה צריך לשלם לו מה שהי' נותן שיצילו בהמתו מספק אמנם משמעות לשון התוספות והרא\"ש אינם מורין כן ע' ביש\"ש פ\"ו דב\"ק סי' י\"ג:","\u0003 שהי' לו לשומר'. \u0004 פי' שמירה מעולה ופי' שמירה מעולה או פחותה תמצא בר\"ס שצ\"ו וכו' עכ\"ל סמ\"ע ודלא כהבנת מהרש\"ל דלהרמב\"ם סגי בשמיר' פחותה ואינו כן אלא עכ\"פ צריך שמירה מעולה ולאפוקי הרא\"ש דס\"ל דלא סגי בשמירה מעולה ג\"כ ודוק:","\u0003 מיהו אם שמרה כו'. \u0004 וכ\"פ מהרש\"ל סי' י\"ז:"],"בְּהֵמָה \u0010g0\u0011 שֶׁהֻחְלְקָה בְּאֶבֶן אוֹ \u0010g1\u0011 בְּמֵימֵי רַגְלַיִם, וְנָפְלָה לְגִנָּה, \u0010g2\u0011 וְנֶחְבְּטָה עַל גַּבֵּי פֵּרוֹת וִירָקוֹת, אוֹ \u0010y0\u0011 שֶׁאָכְלָה, מְשַׁלֵּם מַה \u0010t0\u0011 שֶּׁנֶּהֱנֵית. \u0010y1\u0011 \u0010g3\u0011 \u0010t1\u0011 אֲפִלּוּ הָלְכָה מֵעֲרוּגָה לַעֲרוּגָה, וַאֲפִלּוּ נִשְׁאֲרָה שָׁם כָּל הַיּוֹם כֻּלּוֹ, אֵינוֹ מְשַׁלֵּם אֶלָּא מַה שֶּׁנֶּהֱנֵית. וּמַה הֲנָאָה יֵשׁ לָהּ בַּחֲבָטָה, שֶׁהֲרֵי מָצְאָה מָקוֹם רַךְ \u0010c0\u0011 וְלֹא נִתְרַסְקוּ \u0010t2\u0011 אֵיבָרֶיהָ. \u0010g4\u0011 אֲבָל אִם יָרְדָה כְּדַרְכָּהּ וְאָכְלָה, מְשַׁלֵּם מַה \u0010y2\u0011 \u0010g5\u0011 שֶּׁהִזִּיקָה. וַאֲפִלּוּ טִנְּפָה פֵּרוֹת בְּמֵי לֵדָה, מְשַׁלֵּם מַה שֶּׁהִזִּיקָה, מִפְּנֵי \u0010g6\u0011 שֶׁתְּחִלָּתוֹ \u0010g7\u0011 \u0010r0\u0011 בִּפְשִׁיעָה. וְכֵן אִם דְּחָפָהּ חֲבֶרְתָּהּ וְנָפְלָה, מְשַׁלֵּם מַה שֶּׁהִזִּיקָה, מִפְּנֵי שֶׁהָיָה לוֹ לְהַעֲבִירָם אַחַת אַחַת כְּדֵי שֶׁלֹּא יִדְחֲפוּ זוֹ אֶת זוֹ \u0005(וְכֵן דַּעַת הָרִי\"ף)\u0006. \u0005הַגָּה: \u0010y3\u0011 \u0010r1\u0011 וְיֵשׁ אוֹמְרִים דְּאִם דְּחָפָהּ חֲבֶרְתָּהּ לֹא מִקְרֵי פְשִׁיעָה, אֶלָּא הָוֵי אֹנֶס וּפָטוּר\u0006 \u0010g8\u0011 \u0005(טוּר ס\"ג בְּשֵׁם ר\"י והרמ\"ה וְהָרֹא\"שׁ)\u0006. \u0010y4\u0011 \u0010r2\u0011 \u0005אִם הֶעֱבִירָהּ אֵצֶל גִּנַּת חֲבֵרוֹ וְהָיָה אֶפְשָׁר לָהּ לֵירֵד וְלִכָּנֵס לַגִּנָּה, אֲפִלּוּ נָפְלָה בְּאֹנֶס חַיָּב, דְּהָוֵי תְּחִלָּתוֹ בִּפְשִׁיעָה וְסוֹפוֹ בְּאֹנֶס\u0006 \u0005(טוּר ס\"א וְתוֹסָפוֹת וְהָרֹא\"שׁ)\u0006. \u0010r3\u0011 \u0005וְיֵשׁ מִי שֶׁחוֹלֵק בְּזֶה\u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם הָרַשְׁבָּ\"א בְּשֵׁם הָרַאֲבַ\"ד)\u0006. \u0010g9\u0011 \u0010r4\u0011\nהֻחְלְקָה וְנָפְלָה וְיָצְאָה \u0005וְהוּא יָדַע \u0010g10\u0011 (טוּר ס\"ב)\u0006, וְחָזְרָה לַגִּנָּה, אַף עַל פִּי שֶׁחָזְרָה שֶׁלֹּא לְדַעַת הַבְּעָלִים, מְשַׁלֵּם מַה שֶּׁהִזִּיקָה, מִפְּנֵי \u0010y5\u0011 \u0010c1\u0011 שֶׁהָיָה לוֹ לְשָׁמְרָהּ שֶׁלֹּא תַּחֲזֹר, שֶׁהַדָּבָר יָדוּעַ שֶׁכֵּיוָן שֶׁיָּדְעָה דֶרֶךְ הַגִּנָּה הֲרֵי הִיא חוֹזֶרֶת מֵאֵלֶיהָ. \u0005הַגָּה: \u0010c2\u0011 \u0010r5\u0011 מִיהוּ, אִם שְׁמָרָהּ בִּשְׁמִירָה \u0010t3\u0011 מְעֻלָּה וְיָצְאָה וְהִזִּיקָה, פָּטוּר \u0010g11\u0011 (טוּר)\u0006. \u0010y6\u0011 \u0010g12\u0011\nהַמַּעֲמִיד בֶּהֱמַת חֲבֵרוֹ עַל גַּבֵּי קָמַת חֲבֵרוֹ, הַמַּעֲמִיד חַיָּב לְשַׁלֵּם מַה \u0010g13\u0011 שֶּׁהִזִּיקָה. וְכֵן אִם הִכִּישָׁהּ \u0005(פֵּרוּשׁ, הִכָּה אוֹתָהּ)\u0006 עַד שֶׁהָלְכָה לְקָמַת חֲבֵרוֹ וְהִזִּיקָה, זֶה שֶׁהִכִּישָׁהּ חַיָּב. \u0005הַגָּה: \u0010y7\u0011 \u0010r6\u0011 וַאֲפִלּוּ הַפֵּרוֹת בִּרְשׁוּת הָרַבִּים, דְּהָוֵי כְּמַזִּיק בְּיָדַיִם (המ\"מ פ\"ד מִנִּזְקֵי מָמוֹן וּבֵית יוֹסֵף בְּשֵׁם רַשְׁבָּ\"א)\u0006. \u0010g14\u0011 \u0010r7\u0011 וְדַוְקָא הִכִּישָׁהּ וְכַיּוֹצֵא בָּזֶה, אֲבָל קָם לָהּ בְּאַפָּהּ עַד שֶׁהָלְכָה שָׁם, פָּטוּר, דְּהָוֵי גְרָמָא בִנְזָקִין \u0005(הַמַּגִּיד שָׁם, וּדְלָא כְּדַעַת הָרַאֲבַ\"ד)\u0006. \u0010g15\u0011 \u0010r8\u0011\nכָּל \u0010y8\u0011 בְּהֵמָה שֶׁהִזִּיקָה פֵּרוֹת מְחֻבָּרִים, מְשַׁעֲרִים מַה שֶּׁהִזִּיקָה בְּשִׁשִּׁים וּמְשַׁלֵּם מִי שֶׁנִּתְחַיֵּב לְשַׁלֵּם. כֵּיצַד, הֲרֵי שֶׁאָכְלָה בֵּית סְאָה, שָׁמִין שִׁשִּׁים בֵּית סְאָה בְּאוֹתָהּ הַשָּׂדֶה כַּמָּה הָיָה שָׁוֶה, וְכַמָּה הוּא שָׁוֶה עַתָּה אַחַר שֶׁנִּפְסַד בּוֹ הַבֵּית סְאָה, \u0010g16\u0011 וּמְשַׁלֵּם הַשְּׁאָר. \u0010y9\u0011 וְכֵן אִם אָכְלָה קַב אוֹ \u0010g17\u0011 רֹבַע, אֲפִלּוּ קֶלַח אֶחָד, שָׁמִין אוֹתוֹ בְּשִׁשִּׁים. \u0010g18\u0011\nאָכְלָה פֵּרוֹת גְּמוּרִים שֶׁאֵינָם צְרִיכִים לַקַּרְקַע, מְשַׁלֵּם דְּמֵי פֵרוֹת גְּמוּרִים בְּשִׁוּוּיֵיהֶן, אִם סְאָה דְּמֵי סְאָה, וְאִם סְאָתַיִם דְּמֵי סְאָתַיִם. \u0010g19\u0011 \u0010r9\u0011\nהֲרֵי שֶׁאָכְלָה פֵּרוֹת דֶּקֶל אֶחָד, \u0010y10\u0011 וְכֵן הַקּוֹצֵץ פֵּרוֹת דֶּקֶל חֲבֵרוֹ וְאָכַל, \u0010r10\u0011 אִם הָיָה דֶקֶל רוֹמִי וְכַיּוֹצֵא בּוֹ שֶׁאֵין הַתְּמָרִים שֶׁלּוֹ יָפוֹת, \u0010g20\u0011 מְשַׁעֲרִים אוֹתוֹ בְּשִׁשִּׁים עַל גַּבֵּי הַקַּרְקַע; וְאִם \u0010g21\u0011 דֶּקֶל פַּרְסִי וְכַיּוֹצֵא בּוֹ הוּא, שֶׁהַתְּמָרִים שֶׁלּוֹ יָפוֹת בְּיוֹתֵר, מְשַׁעֲרִים הַדֶּקֶל בִּפְנֵי עַצְמוֹ, כַּמָּה הָיָה שָׁוֶה וְכַמָּה הוּא שָׁוֶה עַתָּה. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאִם לֹא נִגְמַר גִּדּוּלוֹ מְשַׁעֲרִין בְּשִׁשִּׁים, \u0010y11\u0011 וְאִם נִגְמַר גִּדּוּלוֹ מְשַׁעֲרִין כְּמוֹ שֶׁהוּא \u0010g22\u0011 (טוּר ס\"ו)\u0006.",{"g":["א) ל' הרמב\"ם בפ\"ג מהנ\"מ די\"א משנה רפ\"ו דב\"ק דף נ\"ה ע\"א","ב) כדמפרש רב כהנא שם דף נ\"ח ע\"א","\u0003ג) כדמפ' שם דרב לא מבעיא קאמר וכו'\u0004 ","ד) כדאמר רבי יוחנן שם","ה) שם במשנה","ו) בעיא דרכ ירמיה שם דף נ\"ח ע\"א למ\"ד תחלתו בפשיעה וסופו באונס פטור אבל למ\"ד תחלתו בפשיעה וסופו באונס חייב פשיט דחייב ואנן קיימא לן כוותיה","פרש\"י דהיה לו לשמרה שלא תרד","ז) פסק כרב כהנא וכתב ה\"ה שפסק בפסק ההלכות וכתב הב\"י דפשטא דגמ' כוותיהו","\u0003ח) פסקו כרבא דמפרש מתניתין נפלה לגינה וכו'\u0004 בשדחפוה חברותיה ופי' ☜פטור לשלם מה שהזוקה אבל חייב לשלם מה שנהנית פשוט ומבואר שם בגמ' וכ\"כ הרא\"ש בשם התוספת ולא דמי לעובדא דאדא סבולאה בפ\"ז דב\"מ דף צ\"ג ע\"ג ואיתא לעיל סימן ש\"ג סי\"א דחייבוה לשלם לאו משום פשיעה חייביה אלא משום שהיה ש\"ש וזה חשוב כגניבה ואבידה כדמשמע התם וכשם שהבעלים פטורים אם דחפה חבירתה כך שומר שכר שלו פטור דהא תנן מסר לש\"ח וכו' כלן נכנסו תחת הבעלים בפ\"ד דב\"ק סוף דף מ\"ד ע\"ב","ט) שם די\"ב ממימרא דרבי יוחנן כדמפרש לה רב פפא שם דף נ\"ח ע\"א","י) וכ\"כ ה\"ה שם וז\"ל וסובר רבינו ז\"ל שכל שנעל בפניה כראוי והוא לא ידע בצאתה פטור ואינו משלם אלא מה שנהנית ומן הדעת מוכרעים כן ושכ\"כ הראב\"ד בפירושיו וכן כתב הרשב\"א בשמו ונרא' שחזר בו מן ההשגה ובודאי אם החזיר דרך שם צריך לאוחזה כדי שלא תפיל עצמה שם וכ\"כ הרב ז\"ל","כ) כן פרש\"י שם וכן כתב הרא\"ש שם","ל) לשון הרמב\"ם שם בפ\"ד ד\"ג מימרא דרב מתנה אמר רב שם דף נ\"ו ע\"ב ומכ\"ש בהמתו","מ) שם אמר רבה לרב יוסף הכישה אמרת לן","נ) וכתב הב\"י אע\"פ שהתוס' כתבו דפטור כיון דלא משתמט בשום דוכתא דלחייב שן בר\"ה כדברי ה\"ה והרשב\"א נקטינן דטענת לא משתמיט לאו טענה הוא","ס) שם דין י\"ג ממשנה שם רפ\"ו וכדמפ' ר' חנינא שם דף נ\"ח ע\"ב","ע) דאינו מפסיד המזיק כל כך דמי שלוקח ס' סאין כשהיא בתבואתה אינו מזלזל בה בשביל הפסד בית סאה אחת כי אם דבר מועט","פ) כחזקי' שם","צ) שם די\"ד והם דברי ר\"ש במשנה ומסיק בגמ' שם דף נ\"ט ע\"ב משמיה דרב דפסק הלכתא כוותיה","\u0003ק) שם וכתב ה\"ה הכל מבואר שם בגמרא (בעובדא דההוא גברא דקץ קשבא וכו'\u0004 לקמיה דריש גלותא דף נ\"ח ע\"ב) בסוגיא לפי המסקנא","ר) בעובדא דר\"פ ורב הונא בריה דרב יהושע ואיפסקא הלכתא כוותייהו שם דף נט ע\"א","ש) דהכי איפסקא הלכתא שם בעובדא דר\"ג","\u0003ת) הוא כפי' הרא\"ש שם בפסקיו שפי' דקלא ארמאה שלא נגמר גידולו וכו'\u0004 ודקלא פרסאה שנגמר גידולו וראוי לעקרו ולשתלו במקום אחר וכן כתב ר\"י נל\"א ח\"א"],"t":["\u0003שנהנית. \u0004 באופן שנתבאר בסי' שצ\"א ס\"ח ע\"ש:","\u0003הלכה. \u0004 פירוש ואפי' בעל הבהמה ידע מזה דמזל רע דבעל השדה הוא דגרם ליה ההיזק. סמ\"ע:","\u0003איבריה. \u0004 מלשון זה משמע דאם לא נתרסקו איבריה אלא היה לה צער בעלמא א\"צ לשלם כלל ואם יש להסתפק בזה צריך לשלם לו מה שהיה נותן להציל בהמתו מספק אמנם משמעות ל' התוספות והרא\"ש אינן מורין כן עיין במהרש\"ל פ\"ו דב\"ק סי' י\"ג. ש\"ך:","\u0003מעולה. \u0004 וכ\"פ מהרש\"ל שם סי' י\"ז וע\"ל ר\"ס שצ\"ו:"],"r":["\u0003וכן אם דחפה כו'. \u0004 כשיטתם בכ\"מ שאמרו מ\"ד כו' ומ\"ד כו':","\u0003וי\"א כו'. \u0004 כרבא דהוא בתרא וכן ס\"ל לר\"פ בב\"מ צג ב' כוותיה וע\"ש תוס' בד\"ה איבעי כו' אבל הרשב\"א כ' דאתי אף לר\"כ דגבי בע\"ה פשיעותא הוא אבל לגבי ש\"ח פטור דלא קביל עליה למטרח כ\"כ:","\u0003אם כו'. \u0004 תוס' ד\"ה נפלה כו':","\u0003ויש כו'. \u0004 דלאו פשיעותא היא כמ\"ש י\"ט ב' וכי יאחזנה כו' וז\"ש ירדה כו' וז\"ש שם כיון דמשתמטא כו' ולדברי תוס' הא א\"א לירד לשם אף שיש לדחוק בזה:","\u0003והוא ידע. \u0004 גמ':","\u0003מיהו כו'. \u0004 רש\"י וז\"ש כל אימת דמשתמטא ול\"ק כיון דילפא. יש\"ש דלא כראב\"ד:","\u0003ואפילו כו'. \u0004 כפי' הרשב\"א דהטעם דהוי מזיק בידים ועתוס' ד\"ה המעמיד כו':","\u0003ודוקא כו'. \u0004 גמ' שם:","\u0003כל כו'. \u0004 כחזקיה וכל הסוגיא שם כוותיה ת\"ר אין כו' אלא כו' ושם אתא לקמיה דר\"נ כו' א\"ל רבא כו' והלכתא כו' אליעזר זעירא כו':\n\u0003 (ליקוט) כיצד כו' וכן כו' אפי' כו'. \u0004 ר\"ל כפי' ר\"ח שם וכן פי' הראב\"ד הביאו הרשב\"א שם אריב\"ח סאה כו' ר\"ל דוקא סאה שיימינן בששים מפני שהוא דבר גדול שלא להכחיש את המזיק והיינו דתנן במתני' סאה אבל פחות מסאה שמין בפ\"ע ר' ינאי כו' עד תרקב וחזקיה אמר אפי' קלח ע\"ש (ע\"כ):\n\u0003 (ליקוט) כיצד כו'. \u0004 עמ\"ש בפי' ר\"ח והראב\"ד ובזה ניחא מה שפריך שם מתבי אכלה כו' דהקושיא דוקא לחזקיה אבל לפירש\"י ה\"ל להקשות אמתני' וכן אף לפי' תוס' שפי' שם דמ\"ש בית סאה קאי אמה שאכלה ע\"ש ופ' כחזקיה דכל הסוגיא שם כוותיה ת\"ר אין כו' ההוא גברא כו' אתא כו' וכן אביי ורבא שם וכן ר\"פ ור\"ה כו' ושם והלכתא כו' אליעזר כו' שלחוה כו' והשמיט מש\"ש נטיעה כו' דס\"ל דחכמים שם פליגי אכולהו אבל הרא\"ש פ' דס\"ל דל\"פ אהא ממה שחזר ואמר וחכ\"א כו' על סמדר. וכן בכחש גופנא לא כ' דס\"ל כהרמ\"ה דלא מנכינן אבל הרא\"ש פ' שם דמנכינן דרבנן ס\"ל כוותיה ועתוס' שם ד\"ה מאן כו' וד\"ה אונס כו' וברא\"ש שם (ע\"כ):","\u0003הרי כו' וכן כו'. \u0004 שם:","\u0003אם כו'. \u0004 וכן פירש\"י:"]}],["הַמְשַׁסֶה \u0005(פֵּרוּשׁ, מְשַׁלֵּחַ וּמַקְנִיט)\u0006 כַּלְבּוֹ שֶׁל \u0010y0\u0011 חֲבֵרוֹ בַּחֲבֵרוֹ, פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם; וּבַעַל הַכֶּלֶב \u0010y1\u0011 חַיָּב חֲצִי נֶזֶק, שֶׁכֵּיוָן שֶׁהוּא יוֹדֵעַ שֶׁאִם שִׁסָה אֶת כַּלְבּוֹ לְהַזִּיק נוֹשֵׁךְ, לֹא הָיָה לוֹ לְהַנִּיחוֹ. \u0010y2\u0011 וְאִם שִׁסָהוּ בְּעַצְמוֹ, בַּעַל הַכֶּלֶב פָּטוּר, שֶׁכָּל הַמְשַׁנֶּה וּבָא אַחֵר וְשִׁנָּה בּוֹ, פָּטוּר:",["\u0003פטור מדיני אדם \u0004 הטעם דלא הוה אלא גרמא בניזקין:","\u0003חייב ח\"נ \u0004 במ\"מ מבואר דאפילו היה מועד אינו משלם אלא ח\"נ כיון דלא נשך מעצמו אלא ע\"י שיסוי ה\"ל שינוי:","\u0003ואם שיסהו בעצמו. \u0004 פי' ששיסה ראובן כלב של שמעון עד שהלך ונשך לראובן המשסה פטור שמעון דראובן שינה מתחלה בהשסתו וכל המשנה ובא אחר ושינה בו כגון זה שבא שמעון עם כלבו ושינה בו פטור שמעון:"],[],"הַמְשַׁסֶה \u0010g0\u0011 \u0010r0\u0011 \u0005(פֵּרוּשׁ, מְשַׁלֵּחַ וּמַקְנִיט)\u0006 כַּלְבּוֹ שֶׁל \u0010y0\u0011 \u0010g1\u0011 חֲבֵרוֹ בַּחֲבֵרוֹ, פָּטוּר מִדִּינֵי אָדָם \u0010r1\u0011 וְחַיָּב בְּדִינֵי שָׁמַיִם; וּבַעַל הַכֶּלֶב \u0010y1\u0011 \u0010g2\u0011 \u0010g3\u0011 \u0010r2\u0011 חַיָּב חֲצִי נֶזֶק, שֶׁכֵּיוָן שֶׁהוּא יוֹדֵעַ שֶׁאִם שִׁסָה אֶת כַּלְבּוֹ לְהַזִּיק נוֹשֵׁךְ, לֹא הָיָה לוֹ לְהַנִּיחוֹ. \u0010y2\u0011 \u0010g4\u0011 וְאִם שִׁסָהוּ \u0010g5\u0011 בְּעַצְמוֹ, בַּעַל הַכֶּלֶב \u0010t0\u0011 פָּטוּר, שֶׁכָּל הַמְשַׁנֶּה וּבָא אַחֵר וְשִׁנָּה בּוֹ, פָּטוּר:",{"g":["א) ל' הרמב\"ם בפ\"ב מהל' נזקי ממון דין י\"ט","ב) פשוט בפ\"ב דב\"ק דף כ\"ד ע\"ב ופרש\"י דגרמא בנזקין הוא וכ' הב\"י ומשמע לרבינו דמ\"מ חייב בדיני שמים (ומבואר לעיל סי' שע\"ח וסי' שפ\"ו)","\u0003ג) נלע\"ד שלמדו מהא דאמר רבא שם את\"ל המשסה כלבו של חבירו בחבירו חייב וכו'\u0004 משמע ליה דנפשטא הבעיא אי מחייב בעל הכלב או לא וכמו שדרכו ודרך הגאונים לפסוק ככל את\"ל","ד) כתב ה\"ה שנ\"ל ☜ואפילו הוא מועד כיון שלא עשה מעצמו אלא ע\"י שיסוי כדאמרי' גם גבי שור האצטיידין כי יגח ולא שיגיחוהו ופטור ממיתה אף כאן דינו כתם","ה) שם במימרא דרבא","פי' שנשך הכלב את המשסה"],"t":["\u0003פטור. \u0004 דהמשסה שינה בתחלה בהשסתו וכל המשנה כו'. סמ\"ע:"],"r":["\u0003המשסה כו'. \u0004 מתני' דסנה' עו ב' וגמ' דב\"ק כג ב':","\u0003וחייב כו'. \u0004 כמ\"ש בקדושין מג א' וכ\"ש בכה\"ג ולא גרע מכל הני דב\"ק נו ה':","\u0003 (ליקוט) חצי נזק. \u0004 דשינוי הוא כמ\"ש למטה דכל המשנה כו' וכמש\"ש בגמ' (ע\"כ):"]}],["שׁוֹר הַמּוּעָד, וְכֵן שֵׁן וָרֶגֶל \u0010y0\u0011 שֶׁהֵן מוּעָדִים \u0010y1\u0011 מִתְּחִלָּתָן, דַּי לָהֶם בִּשְׁמִירָה פְחוּתָה; לְפִיכָךְ, אִם קְשָׁרָם בְּעָלָיו בְּמוֹסֵרָה אוֹ שְׁמָרָם שְׁמִירָה פְּחוּתָה, וְיָצְאוּ וְהִזִּיקוּ, פָּטוּר. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּמוּעָד; אֲבָל תָּם לֹא סָגֵי לֵהּ לֹא בְּמוֹסֵרָה וְלֹא בִּשְׁמִירָה פְּחוּתָה, עַד שֶׁיִּשְׁמְרֶנּוּ שְׁמִירָה מְעֻלָּה. אֵי זוֹ הִיא שְׁמִירָה מְעֻלָּה, דֶּלֶת שֶׁיְּכוֹלָה לַעֲמֹד אֲפִלּוּ בְּרוּחַ שֶׁאֵינָהּ מְצוּיָה; וּשְׁמִירָה פְּחוּתָה, שֶׁיְּכוֹלָה לַעֲמֹד בְּרוּחַ מְצוּיָה וְלֹא בְּשֶׁאֵינָה מְצוּיָה. אֲבָל אִם אֵינָהּ יְכוֹלָה לַעֲמֹד אֲפִלּוּ בְּרוּחַ מְצוּיָה, כְּאִלּוּ לֹא שְׁמָרוֹ כְּלָל, וְחַיָּב, אֲפִלּוּ לֹא נָפְלָה הַדֶּלֶת עַל יְדֵי הָרוּחַ אֶלָּא לִסְטִים הוֹצִיאוּהָ, אוֹ חָפְרָה אוֹ חָתְרָה הַדֶּלֶת וְהִפִּילָתוֹ, דִּתְחִלָּתוֹ בִּפְשִׁיעָה לְגַבֵּי נְפִילַת הַדֶּלֶת, וְסוֹפוֹ בְּאֹנֶס לְגַבֵּי חֲתִירָה, וְקַיְמָא לָן כָּל שֶׁתְּחִלָּתוֹ בִּפְשִׁיעָה וְסוֹפוֹ \u0010y2\u0011 בְּאֹנֶס הַבָּא מֵחֲמַת הַפְּשִׁיעָה, חַיָּב. אֲבָל אִם חָתְרָה פִּרְצָה וְיָצְאָה מִשָּׁם, פָּטוּר, שֶׁאֵין הָאֹנֶס בָּא מֵחֲמַת הַפְּשִׁיעָה.\nשְׁמָרָהּ כָּרָאוּי \u0010y3\u0011 וְנִפְרְצָה בַלַּיְלָה, אוֹ שֶׁחָתְרָה הַדֶּלֶת וְיָצְאָה וְהִזִּיקָה, פָּטוּר, אֲפִלּוּ יָדַע שֶׁנִּפְרְצָה, שֶׁאֵינוֹ חַיָּב לָצֵאת לִטְרֹחַ אַחֲרֶיהָ. וְדַוְקָא נִפְרְצָה בַּלַּיְלָה, אֲבָל נִפְרְצָה בַּיּוֹם, חַיָּב, דְּקָלָא אִית לְמִלְּתָא וּמִסְתָמָא יָדַע.\nהוֹצִיאוּהָ לִסְטִים, \u0010y4\u0011 הֵם חַיָּבִים מִשְּׁעַת מְשִׁיכָה אוֹ שֶׁהִכִּישׁוּהָ בְּמַקֵּל לְהוֹצִיאָהּ. וְדַוְקָא שֶׁהוֹצִיאוּהָ כְּדֵי לְגָזְלָהּ, אֲבָל הוֹצִיאוּהָ \u0010y5\u0011 \u0010c0\u0011 כְּדֵי לְאַבְּדָהּ, פְּטוּרִים. \u0010c1\u0011\nהַפּוֹרֵץ גָּדֵר לִפְנֵי בֶּהֱמַת \u0010y6\u0011 חֲבֵרוֹ וְיָצְאָה וְהִזִּיקָה, אִם הָיָה גָּדֵר בָּרִיא וְחָזָק, חַיָּב. \u0005וְיֵשׁ אוֹמְרִים דְּאֵינוֹ חַיָּב בְּנִזְקֵי הַבְּהֵמָה אֶלָּא אִם הִכִּישָׁהּ וְהִזְמִינָהּ לְנֶזֶק, וְכֵן עִקָּר (טוּר בְּשֵׁם הָרַאֲבַ\"ד וְהַמַּגִּיד פ\"ד דְנ\"מ)\u0006. \u0010y7\u0011 וְיֵשׁ אוֹמְרִים דַּאֲפִלּוּ עַל הַבְּהֵמָה עַצְמָהּ אֵינוֹ חַיָּב, אִם נֶאֶבְדָה \u0005(טוּר)\u0006. וְאִם הָיָה כֹּתֶל רָעוּעַ, פָּטוּר מִדִּינֵי אָדָם \u0010y8\u0011 וְחַיָּב בְּדִינֵי שָׁמַיִם:\nהִנִּיחָהּ בַּחַמָּה, אֲפִלּוּ חָתְרָה וְיָצְאָה וְהִזִּיקָה, חַיָּב זֶה שֶׁהִנִּיחָהּ שָׁם, שֶׁכֵּיוָן שֶׁהִנִּיחָהּ בַּחַמָּה הֲרֵי הִיא מִצְטַעֶרֶת וְעוֹשָׂה כָּל שְׁאֶפְשָׁר לָהּ לַעֲשׂוֹת לִבְרֹחַ. \u0005הַגָּה: וְלָכֵן אֲפִלּוּ הָיְתָה קְשׁוּרָה בְּקֶשֶׁר חָזָק, חַיָּב (טוּר)\u0006.\nמָסַר הַשּׁוֹר לְחֵרֵשׁ, שׁוֹטֶה וְקָטָן, אַף עַל פִּי שֶׁהָיָה הַשּׁוֹר קָשׁוּר, הַבְּעָלִים \u0010y9\u0011 חַיָּבִין, שֶׁדֶּרֶךְ הַשּׁוֹר לְהַתִּיר הַקֶּשֶׁר וְלָצֵאת וּלְהַזִּיק. \u0010y10\u0011 אֲפִלּוּ שְׁמָרוּהוּ שְׁמִירָה מְעֻלָּה, וְחָתְרָה וְיָצְאָה וְהִזִּיקָה, הַבְּעָלִים חַיָּבִים.\nמָסַר שׁוֹרוֹ לַחֲמִשָּׁה בְּנֵי אָדָם, וּפָשַׁע בּוֹ אֶחָד מֵהֶם וְיָצָא וְהִזִּיק, אִם אֵינוֹ מִשְׁתַּמֵּר אֶלָּא בַּחֲמֶשְׁתָּן, זֶה שֶׁפָּשַׁע בִּשְׁמִירָתוֹ חַיָּב; וְאִם מִשְׁתַּמֵּר בַּשְּׁאָר, \u0010y11\u0011 אַף אֵלּוּ הַנִּשְׁאָרִים חַיָּבִים. וְיֵשׁ מִי שֶׁאוֹמֵר, דְּהָנֵי מִלֵּי, כְּשֶׁאָמְרוּ לוֹ: כֵּיוָן שֶׁאֵינְךָ רוֹצֶה לְשָׁמְרוֹ גַם אָנוּ מְסֻלָּקִים מִשְּׁמִירָתוֹ, אֲבָל אִם לֹא נִסְתַּלְּקוּ מִשְּׁמִירָתוֹ, \u0010y12\u0011 הוּא פָּטוּר וְהֵם חַיָּבִים.\nמְסָרוֹ לְאֶחָד מֵאַרְבָּעָה שׁוֹמְרִים, \u0010y13\u0011 מִסְתָמָא קִבֵּל עָלָיו שֶׁלֹּא יַזִּיק, וְשֶׁלֹּא יֻזָּק. וְהָנֵי מִלֵּי בְּשׁוֹר סְתָם, אֲבָל אִם מַכִּיר בּוֹ שֶׁהוּא נַגְחָן, אֵינוֹ מְקַבֵּל עָלָיו אֶלָּא שֶׁלֹּא יַזִּיק, \u0010y14\u0011 אֲבָל לֹא שֶׁלֹּא יֻזָּק. וְאִם לֹא שְׁמָרוּהוּ כְּלָל, וְיָצָא וְהִזִּיק, נִכְנְסוּ תַּחַת הַבְּעָלִים וְחַיָּבִים לְשַׁלֵּם תָּם חֲצִי נֶזֶק וּמוּעָד נֶזֶק שָׁלֵם, \u0010y15\u0011 וְהַבְּעָלִים פְּטוּרִים. \u0010y16\u0011 וְאִם אַחַר שֶׁהִזִּיק הַתָּם בִּרְשׁוּתוֹ אוֹמְרִים לַבְּעָלִים: הֲרֵי שֶׁלְּךָ לְפָנֶיךָ, לֹא אָמַר כְּלוּם, שֶׁהֲרֵי בֵּית דִּין לוֹקְחִים אוֹתוֹ לְהִשְׁתַּלֵּם מִגּוּפוֹ. \u0010y17\u0011 וְאִם שְׁמָרוּהוּ כָּרָאוּי \u0010y18\u0011 שְׁמִירָה מְעֻלָּה, הַשּׁוֹמְרִים פְּטוּרִים, וְהַבְּעָלִים חַיָּבִים בְּנֶזֶק קֶרֶן בִּלְבַד שֶׁהִיא תַמָּה, אֲבָל בְּנֶזֶק שֵׁן וָרֶגֶל גַּם הַבְּעָלִים פְּטוּרִים. וְאִם שְׁמָרוּהוּ שְׁמִירָה פְּחוּתָה, אִם שׁוֹמֵר חִנָּם הוּא פָטוּר, וְאִם שׁוֹמֵר שָׂכָר אוֹ שׂוֹכֵר אוֹ שׁוֹאֵל הוּא, חַיָּבִים:\nמְסָרוֹ הַשּׁוֹמֵר לְשׁוֹמֵר אַחֵר וְהֻזָּק, חַיָּב, שֶׁשּׁוֹמֵר שֶׁמָּסַר לְשׁוֹמֵר \u0010y19\u0011 חַיָּב, אֲפִלּוּ שׁוֹמֵר חִנָּם שֶׁמָּסַר לְשׁוֹמֵר שָׂכָר. וְאִם הִזִּיק, \u0010y20\u0011 חַיָּב הַשּׁוֹמֵר הָרִאשׁוֹן לְשַׁלֵּם לַנִּזָּק, וְיֵלֶךְ לַעֲשׂוֹת דִּין עִם הַשּׁוֹמֵר הַשֵּׁנִי. וְאִם מְסָרָהּ שׁוֹמֵר רִאשׁוֹן לִבְנוֹ אוֹ לְבֶן בֵּיתוֹ אוֹ לַמְסַעֲדוֹ, נִכְנְסוּ תַּחַת הַשּׁוֹמֵר, וְחַיָּבִים.\nאִם הִזִּיק שׁוֹרוֹ שֶׁל שׁוֹאֵל לְשׁוֹרוֹ שֶׁל מַשְׁאִיל אוֹ אִפְּכָא, נִתְבָּאֵר בְּסִימָן שמ\"ז.",["\u0003שהן מועדין מתחלתן. \u0004 נתבאר לעיל בסי' שפ\"ט בדברי הטור והמחבר ע\"ש:","\u0003די להן בשמירה פחותה כו'. עד שמרה שמיר' פחות' פטור \u0004 עפ\"ר שם כתבתי דלהרמב\"ם הן פטורין לגמרי אפי' מח\"נ ולתו' והרא\"ש אינן פטורין אלא מנ\"ש כדין שור המועד אבל ח\"נ חייב דלא עדיף לענין ח\"נ לאחר שנעשה מועד מבעוד היותו תם והטעם דבמועד סגי בשמירה פחות' משא\"כ בתם כן הוא בגמ' וכתבתיו ג\"כ בפרישה והוא דסתם שוורים בחזקת שימור קיים דאין לך אדם שאין משמר את שורו לפחות שמירה פחותה ואפ\"ה חייבו התורה אשור תם אלמא שמירה מעול' בעי והדר כתב רחמנא ולא ישמרנו גבי מועד דנעביד ליה שמירה וה\"ל ריבוי אחר ריבוי ואינו אלא למעט ומיעט דאין צריך בו שמירה מעולה וגבי שן ורגל (שהן מועדין מתחלתן) ובער ושלח כתיב דמשמע דאינו חייב עליהן עד דה\"ל דומה כאלו ביער ושלח בידים דהיינו שלא שמרו כלל הא עבד שמירה כל דהו אינו חייב בהו:","\u0003הבא מחמת פשיעה כו'. \u0004 וה\"נ מיקרי מחמת פשיעה דאלו העמיד לפני' דלת חזקה לא היתה נופלת הדלת מחמת שחתר' בקרקע או נגחה בהדלת עצמה:","\u0003ונפרצה בלילה או שחתרה. \u0004 האי שחתרה ג\"כ אבלילה שלפניו קאי ומ\"ש אח\"כ ודוקא שנפרצה בלילה כו' חדא מנייהו נקט וק\"ל:","\u0003הם חייבים משעת משיכה. \u0004 פי' הגזלן חייב על מה שהזיקה הבהמה אע\"ג דהגזלן לא קני ליה במשיכה דמאן א\"ל למשוך מ\"מ כיון דעשה בה דבר הקונה במקח ובממכר והיא עתה ברשותו חייב בשמירתו כ\"כ התוס' והרא\"ש ועפ\"ר ולא כע\"ש שכתב שחייבים משום דקנאה במשיכה:","\u0003כדי לאבדה פטורי'. \u0004 כ\"כ הרא\"ש והטור הטעם כיון דלא עשה מעשה בהבהמה שיקנה בה וגם לא עלתה על דעתו לקחנה לנפשו מעולם לא באתה לרשותו לחייב על נזקי' אבל אם נאבדה הבהמה חייב לשלמה לבעלים אם הוציאו' בידים ודוקא בפרץ גדר לפני בהמת חבירו ונאבדה כתב הטור והמחב' בסמוך די\"א דפטור אם נאבדה משום דלא עשה בה מעשה בידים בהוצאתה כלל:","\u0003ויצאה והזיקה כו'. \u0004 עד\"ר שם כתבתי מה שהקשו חכמי לוני\"ל להרמב\"ם בזה ומה שהשיב להן:","\u0003דאפי' על הבהמה עצמה אינו חייב. \u0004 הטעם דה\"ל גרמא בניזקין דהא לא עביד מעשה בגוף הבהמה וע\"ל בסי' קנ\"ז בטור ס\"ו ובדברי המחבר ונראה דאינו פטור מבהמה אלא בדיני אדם אבל בדיני שמים ודאי חייב ק\"ו מכותל רעוע:","\u0003וחייב בדיני שמים. \u0004 ועפ\"ר שם כתבתי דהתוס' כתבו דדוקא אבהמה שהזיקה חייב ולא אהכותל כיון שהיתה רעוע ושהרא\"ש כ' שאפשר דגם על הכותל חייב דהא ראוי' לעמוד יום או יומים עד שימצאו פועלים ויתקננה כו' וכן נראה שהוא דעת הטור והמחבר שסתמו וכתב חייב ולהרמב\"ם חייב אפי' אכותל רעוע בדיני אדם עד\"ר:","\u0003שדרך השור להתיר הקשר. \u0004 כל' זה כתב ג\"כ הרמב\"ם ובפרישה כתבתי דאין נראה לפרשו כמשמעו דהשור מתיר הקשר מעצמו וכדפירש\"י שם בפ\"ק דב\"ק דא\"כ לא ה\"ל לכתבו בפשיעת הבעלים במה שמסרו ליד חש\"ו דהא אף בלי חש\"ו היה מתיר הקשר ויוצא ועוד דל' להתיר דקאמר לא שייך בבהמה ולכאור' היה נראה לומר דטעות נפלה בדפוס בספרי הרמב\"ם וש\"ע דמ\"ש דדרך השור להתיר צ\"ל דררך חש\"ו והוא ?ר\"ח חרש שוטה וקטן אלא שקשה להגי' הספרים ועוד דא\"כ לא ה\"ל להרמב\"ם לכתוב שדרך השור וכיוצא בו אלא כיוצא בהן לכן היותר נראה דל' הגמ' דפ\"ק דב\"ק נקט ובגמ' שם אמרינן שור דרכו לנתק ופי' התו' שם דר\"ל דרכו ע\"י החש\"ו וכן משמע מל' המ\"מ שכ' אדברי הרמב\"ם הנ\"ל ז\"ל פי' רבי' דהשור קשור כראוי ואפ\"ה הוא חייב שדרכן של אלו לשחק בהן ולהתירן וכיון שכן ה\"ל תחלתו בפשיעה ואפי' סופו באונס כגון שחתרה חייב עכ\"ל:","\u0003ומ\"ש אפי' שמרוהו שמירה מעולה וחתרה כו'. \u0004 נ\"ל דה\"פ בשעה שמסר' הבהמ' ליד חש\"ו קשרו הבעלים לבהמה בקשר חזק והניחוה בידם בלי סגירת הדלת בפני הבהמ' כי סמכו הבעלים על החש\"ו ועל קשירת הבהמ' ולאחר זמן מצאו הבהמ' ניתקה והזיק' וקאמר דחייבי' הבעלי' אפי' עשו החש\"ו עוד שמירה מעולה להבהמ' והיינו שנעלו בפניה הדלת שיכול' לעמוד דהוא הנקרא שמיר' מעול' כנ\"ל אלא שהבהמ' יצא' בחתירה והזיק' אע\"פ שזהו אונס כנ\"ל אפ\"ה כיון שפשעו הבעלי' מתחל' במה שסמכו על הקשר כיון שדרך החש\"ו לנתק הקשר אמרי' דודאי גם קשר זה התירוהו וה\"ל כאלו לא עשו להבהמ' שום שמירה ויצא' מתחת ידה והזיק' ואע\"ג דבעלמ' בעינן שיבא האונס מחמת הפשיעה וכמ\"ש לעיל בסימן רצ\"א שאני הכא דאותו הפשיע' הראוי לבא בשעה שמסרו הבהמ' ליד החש\"ו דהיינו שתצא ותזיק היא הנעשית לבסוף מ\"ה אע\"פ שנעשה באונס מחויבים הבעלי' עליה ועמ\"ש לקמן בסי' ת\"י ס\"ט [סכ\"ד] במכסה הבור בכיסוי שאינו ראוי לעמוד בפני גמלים כו':","\u0003אף אלו הנשארים חייבים. \u0004 דהשמיר' מוטלת על כל א' ולא הי' לזה להסתלק בלי רשותם:","\u0003הוא פטור כו' \u0004 דיכול לומר סמכתי עליכם דהא לכלנו מסרו לכל מי שיכול לשמרו:","\u0003מסתמא קבל עליו כו' \u0004 פי' כיון דקיבל לשומרו כל שמיר' סתם היא שלא יזיק ושלא יוזק:","\u0003אבל לא שלא יוזק. \u0004 דסתמא לא קיבל עליו נטירותא אלא למה שהי' מוחזק ולא סלקא אדעתיה לשומרו שלא יוזק דהא עד היום לא הי' השור מתיצב לנגדו:","\u0003והבעלים פטורים. \u0004 דמאי הוה ליה למעבד דהא העמיד השומר במקומו לשומרו:","\u0003ואם אחר שהזיק התם.\u0004 כצ\"ל ודוקא תם דאינו משלם אלא מגופו דינא הכי משא\"כ במועד אחר שהזיק יכול השומר לומר לבעלי' הרי שלך לפניך ואני אשוה את נפשי עם הניזק דהרי אינו משתלם מגופו:","\u0003ואם שמרוהו כראוי כו'. עד והבעלים חייבים כו' \u0004 כלשון זה תמצא ברמב\"ם בפ\"ז דנ\"מ ובהמ\"מ דכ? עליו דהיינו בנזק קרן כו' ע\"ש והטור כ' על דברי הרמב\"ם ז\"ל ואיני מבין דבריו כיון ששמרוהו כראוי למה יהיו הבעלי' חייבים וכן השיג עליו הראב\"ד עכ\"ל ומ\"ש המ\"מ והמחבר דמיירי בנזקי קרן כ' הב\"י דבזה מיושב התמיה וז\"א דגם בהיזק קרן אינם חייבי' הבעלי' אלא בשמירה פחות' ולא בשמירה מעולה וכמש\"ר בר\"ס זה גם הרמב\"ם כ\"כ בפ\"ז דנ\"מ ועפ\"ר שם כתבתי בשם הכ\"מ שחכמי לוני\"ל הקשו ג\"כ קושי' זו להרמב\"ם והשיב בעצמו שט\"ס היא בספרים וכצ\"ל אבל אם שמרו בו שמיר' מעולה ויצתה והזיקה השומרים פטורים שמרוהו שמירה פחותה אם ש\"ח הוא פטור והבעלי' חייבים ואם ש\"ש או שוכר או שואל חייבים עכ\"ל. ובפרישה הוכחתי שטעות זה נראה וניכר מתוך נוסח ספרי הרמב\"ם שבידינו שכ' שם ז\"ל. אבל אם שמרו שמירה מעולה השומרי' פטורים והבעלים חייבים אפי' המיתה את האדם שמרוהו שמירה פחות' ש\"ח פטור ואם ש\"ש כו' וקשה חדא דהאי אפי' המיתה ע\"כ אשומרי' פטורים קאי וקשה למה הפסיק בתיבת בעלים חייבי' ועוד בסיפא כשאמר ש\"ח פטור הל\"ל והבעלי' חייבים א\"ו ט\"ס הוא הני שני תיבות והבעלים חייבי' שכתבם ברישא וצריכים להעמיד' בסיפא אצל שמירה פחותה וכנ\"ל וכתבתי עוד בדרישה שנראה פשוט שכן הי' נוסחת הרמב\"ם ג\"כ לפני המ\"מ ושבדברי המ\"מ נפל הטעות (מהמדפיס שסבר שנוסחא המוטעת שבידינו עיקר והגיה כן בדברי המ\"מ) וכצ\"ל שם ומ\"ש והבעלי' חייבים כששמרוה שמירה פחותה הוא כגון קרן וע\"ז שפיר מסיק וכ' ז\"ל כמ\"ש בפ\"ז דשם בפ\"ז אשמיר' פחותה קאי ע\"ש אבל על דברי המחבר כאן יש לתמוה שתפס ל' המ\"מ כאשר הוא נדפס בטעות והוא סותר למ\"ש בר\"ס זה ודוק.","\u0003ומ\"ש השומרים פטורי'. \u0004 ר\"ל אפי' השואל דאע\"ג דהשואל חייב באונסין היינו דוקא אם הוזקה הבהמ' שהוא שומר עלי' ולא לענין אם יצאת' והזיקה ועפ\"ר:","\u0003ואפי' ש\"ח שמסר לש\"ש. \u0004 פי' אע\"ג דש\"ש צריך לשומרו טפי מש\"ח מגניבה ואביד' וכבר נתבאר זה בסי' רצ\"א ע\"ש:","\u0003חייב השומר הראשון כו'. \u0004 מ\"מ אם ירצה הניזק יעשה דין עם השני אלא שקאמר שגם דינו עם הראשון דהוי ליה פשיעה גביה שמסרו לשני דיכולין הבעלי' לומר אתה נאמן עלי בשבועה ולא האחר ול\"ד לבעל השור שמוסר בהמתו להשומר דהשומר חייב כמ\"ש בסעיף שלפני זה דשם ברשות נתנו להשומר וכן אם נתנו השומר לבנו כו' דכ' המחבר אחר זה דהוא ברשות דכל המפקיד לאדם על דעת אשתו ובניו הוא מפקיד וכמ\"ש הטור והמחבר ג\"כ בסי' רצ\"א ע\"ש:"],["\u0003 כדי לאבדה. \u0004 פטורים על הנזק אבל [לא] על הבהמה עצמה אע\"פ שלא הי' דעתם אלא לאבדה וכדלעיל סי' שפ\"ו גבי זורק מטבע לים הגדול ואפשר דבהכיש' אפילו לאבדה ונאבד' פטור וצ\"ע:","\u0003 הפורץ גדר לפני בהמתו כו' \u0004 ע' בתשובת רשד\"ם סי' שס\"ה:"],"\u0010g0\u0011 \u0010r0\u0011 שׁוֹר הַמּוּעָד, \u0010r1\u0011 וְכֵן שֵׁן וָרֶגֶל \u0010y0\u0011 שֶׁהֵן מוּעָדִים \u0010y1\u0011 מִתְּחִלָּתָן, דַּי לָהֶם בִּשְׁמִירָה פְחוּתָה; \u0010r2\u0011 לְפִיכָךְ, אִם קְשָׁרָם בְּעָלָיו בְּמוֹסֵרָה אוֹ שְׁמָרָם שְׁמִירָה פְּחוּתָה, וְיָצְאוּ וְהִזִּיקוּ, \u0010t0\u0011 פָּטוּר. \u0010r3\u0011 בַּמֶּה דְּבָרִים אֲמוּרִים, בְּמוּעָד; אֲבָל תָּם לֹא סָגֵי לֵהּ לֹא בְּמוֹסֵרָה וְלֹא בִּשְׁמִירָה פְּחוּתָה, עַד שֶׁיִּשְׁמְרֶנּוּ שְׁמִירָה \u0010g1\u0011 מְעֻלָּה. אֵי זוֹ הִיא שְׁמִירָה מְעֻלָּה, דֶּלֶת שֶׁיְּכוֹלָה לַעֲמֹד אֲפִלּוּ בְּרוּחַ שֶׁאֵינָהּ מְצוּיָה; וּשְׁמִירָה פְּחוּתָה, שֶׁיְּכוֹלָה לַעֲמֹד בְּרוּחַ מְצוּיָה וְלֹא בְּשֶׁאֵינָה מְצוּיָה. אֲבָל אִם אֵינָהּ יְכוֹלָה לַעֲמֹד אֲפִלּוּ בְּרוּחַ מְצוּיָה, כְּאִלּוּ לֹא שְׁמָרוֹ כְּלָל, \u0010g2\u0011 \u0010r4\u0011 וְחַיָּב, אֲפִלּוּ לֹא נָפְלָה הַדֶּלֶת עַל יְדֵי הָרוּחַ אֶלָּא לִסְטִים הוֹצִיאוּהָ, אוֹ חָפְרָה אוֹ חָתְרָה הַדֶּלֶת וְהִפִּילָתוֹ, דִּתְחִלָּתוֹ בִּפְשִׁיעָה לְגַבֵּי נְפִילַת הַדֶּלֶת, וְסוֹפוֹ בְּאֹנֶס לְגַבֵּי חֲתִירָה, \u0010g3\u0011 וְקַיְמָא לָן כָּל שֶׁתְּחִלָּתוֹ בִּפְשִׁיעָה וְסוֹפוֹ \u0010y2\u0011 \u0010r5\u0011 בְּאֹנֶס הַבָּא \u0010t1\u0011 מֵחֲמַת הַפְּשִׁיעָה, \u0010g4\u0011 חַיָּב. אֲבָל אִם חָתְרָה פִּרְצָה וְיָצְאָה מִשָּׁם, פָּטוּר, שֶׁאֵין הָאֹנֶס בָּא מֵחֲמַת הַפְּשִׁיעָה.\nשְׁמָרָהּ כָּרָאוּי \u0010y3\u0011 \u0010g5\u0011 וְנִפְרְצָה \u0010g6\u0011 בַלַּיְלָה, אוֹ \u0010t2\u0011 שֶׁחָתְרָה הַדֶּלֶת וְיָצְאָה וְהִזִּיקָה, פָּטוּר, \u0010g7\u0011 \u0010r6\u0011 אֲפִלּוּ יָדַע שֶׁנִּפְרְצָה, שֶׁאֵינוֹ חַיָּב לָצֵאת \u0010g8\u0011 לִטְרֹחַ אַחֲרֶיהָ. וְדַוְקָא נִפְרְצָה \u0010g9\u0011 בַּלַּיְלָה, אֲבָל נִפְרְצָה בַּיּוֹם, חַיָּב, דְּקָלָא אִית לְמִלְּתָא וּמִסְתָמָא יָדַע. \u0010g10\u0011\nהוֹצִיאוּהָ לִסְטִים, \u0010y4\u0011 \u0010g11\u0011 \u0010t3\u0011 \u0010t4\u0011 הֵם חַיָּבִים מִשְּׁעַת מְשִׁיכָה \u0010g12\u0011 אוֹ שֶׁהִכִּישׁוּהָ בְּמַקֵּל לְהוֹצִיאָהּ. וְדַוְקָא שֶׁהוֹצִיאוּהָ כְּדֵי לְגָזְלָהּ, אֲבָל \u0010g13\u0011 הוֹצִיאוּהָ \u0010y5\u0011 \u0010c0\u0011 כְּדֵי לְאַבְּדָהּ, \u0010g14\u0011 פְּטוּרִים. \u0010c1\u0011 \u0010g15\u0011 \u0010r7\u0011\nהַפּוֹרֵץ גָּדֵר לִפְנֵי בֶּהֱמַת \u0010y6\u0011 חֲבֵרוֹ וְיָצְאָה וְהִזִּיקָה, אִם הָיָה גָּדֵר בָּרִיא וְחָזָק, \u0010g16\u0011 \u0010r8\u0011 חַיָּב. \u0005וְיֵשׁ אוֹמְרִים דְּאֵינוֹ חַיָּב בְּנִזְקֵי הַבְּהֵמָה אֶלָּא אִם הִכִּישָׁהּ וְהִזְמִינָהּ לְנֶזֶק, וְכֵן עִקָּר (טוּר בְּשֵׁם הָרַאֲבַ\"ד וְהַמַּגִּיד פ\"ד \u0010g17\u0011 דְנ\"מ)\u0006. \u0010y7\u0011 \u0010r9\u0011 וְיֵשׁ אוֹמְרִים דַּאֲפִלּוּ עַל הַבְּהֵמָה \u0010t5\u0011 עַצְמָהּ אֵינוֹ חַיָּב, אִם נֶאֶבְדָה \u0010g18\u0011 \u0005(טוּר)\u0006. וְאִם הָיָה כֹּתֶל רָעוּעַ, פָּטוּר מִדִּינֵי אָדָם \u0010y8\u0011 \u0010t6\u0011 וְחַיָּב בְּדִינֵי שָׁמַיִם: \u0010g19\u0011\nהִנִּיחָהּ בַּחַמָּה, אֲפִלּוּ חָתְרָה וְיָצְאָה וְהִזִּיקָה, חַיָּב זֶה שֶׁהִנִּיחָהּ שָׁם, שֶׁכֵּיוָן שֶׁהִנִּיחָהּ בַּחַמָּה הֲרֵי הִיא מִצְטַעֶרֶת וְעוֹשָׂה כָּל שְׁאֶפְשָׁר לָהּ לַעֲשׂוֹת לִבְרֹחַ. \u0005הַגָּה: \u0010r10\u0011 וְלָכֵן אֲפִלּוּ הָיְתָה קְשׁוּרָה בְּקֶשֶׁר חָזָק, חַיָּב (טוּר)\u0006. \u0010g20\u0011 \u0010r11\u0011\nמָסַר הַשּׁוֹר לְחֵרֵשׁ, שׁוֹטֶה וְקָטָן, אַף עַל פִּי שֶׁהָיָה הַשּׁוֹר קָשׁוּר, הַבְּעָלִים \u0010y9\u0011 \u0010r12\u0011 חַיָּבִין, שֶׁדֶּרֶךְ \u0010g21\u0011 הַשּׁוֹר לְהַתִּיר הַקֶּשֶׁר וְלָצֵאת וּלְהַזִּיק. \u0010y10\u0011 \u0010r13\u0011 אֲפִלּוּ שְׁמָרוּהוּ \u0010t7\u0011 שְׁמִירָה מְעֻלָּה, וְחָתְרָה וְיָצְאָה וְהִזִּיקָה, הַבְּעָלִים \u0010g22\u0011 חַיָּבִים.\nמָסַר שׁוֹרוֹ לַחֲמִשָּׁה בְּנֵי אָדָם, וּפָשַׁע בּוֹ אֶחָד מֵהֶם וְיָצָא וְהִזִּיק, אִם אֵינוֹ מִשְׁתַּמֵּר אֶלָּא בַּחֲמֶשְׁתָּן, זֶה שֶׁפָּשַׁע בִּשְׁמִירָתוֹ חַיָּב; וְאִם מִשְׁתַּמֵּר בַּשְּׁאָר, \u0010y11\u0011 \u0010g23\u0011 \u0010r14\u0011 אַף אֵלּוּ הַנִּשְׁאָרִים \u0010g24\u0011 \u0010t8\u0011 חַיָּבִים. וְיֵשׁ מִי שֶׁאוֹמֵר, דְּהָנֵי מִלֵּי, כְּשֶׁאָמְרוּ לוֹ: כֵּיוָן שֶׁאֵינְךָ רוֹצֶה לְשָׁמְרוֹ גַם אָנוּ מְסֻלָּקִים מִשְּׁמִירָתוֹ, אֲבָל אִם לֹא נִסְתַּלְּקוּ מִשְּׁמִירָתוֹ, \u0010y12\u0011 \u0010g25\u0011 הוּא פָּטוּר וְהֵם \u0010g26\u0011 \u0010r15\u0011 חַיָּבִים.\nמְסָרוֹ לְאֶחָד מֵאַרְבָּעָה שׁוֹמְרִים, \u0010y13\u0011 מִסְתָמָא קִבֵּל עָלָיו שֶׁלֹּא יַזִּיק, וְשֶׁלֹּא יֻזָּק. וְהָנֵי מִלֵּי בְּשׁוֹר סְתָם, \u0010g27\u0011 אֲבָל אִם מַכִּיר בּוֹ שֶׁהוּא נַגְחָן, אֵינוֹ מְקַבֵּל עָלָיו \u0010g28\u0011 אֶלָּא שֶׁלֹּא יַזִּיק, \u0010y14\u0011 אֲבָל לֹא שֶׁלֹּא יֻזָּק. וְאִם לֹא שְׁמָרוּהוּ כְּלָל, וְיָצָא וְהִזִּיק, \u0010g29\u0011 \u0010r16\u0011 נִכְנְסוּ תַּחַת הַבְּעָלִים וְחַיָּבִים לְשַׁלֵּם תָּם חֲצִי נֶזֶק וּמוּעָד נֶזֶק שָׁלֵם, \u0010y15\u0011 וְהַבְּעָלִים פְּטוּרִים. \u0010y16\u0011 וְאִם אַחַר שֶׁהִזִּיק הַתָּם בִּרְשׁוּתוֹ אוֹמְרִים לַבְּעָלִים: הֲרֵי שֶׁלְּךָ לְפָנֶיךָ, \u0010g30\u0011 לֹא אָמַר כְּלוּם, שֶׁהֲרֵי בֵּית דִּין לוֹקְחִים אוֹתוֹ לְהִשְׁתַּלֵּם מִגּוּפוֹ. \u0010y17\u0011 \u0010r17\u0011 וְאִם שְׁמָרוּהוּ כָּרָאוּי \u0010y18\u0011 \u0010g31\u0011 \u0010t9\u0011 שְׁמִירָה מְעֻלָּה, הַשּׁוֹמְרִים פְּטוּרִים, וְהַבְּעָלִים \u0010g32\u0011 חַיָּבִים בְּנֶזֶק קֶרֶן בִּלְבַד שֶׁהִיא תַמָּה, אֲבָל בְּנֶזֶק שֵׁן וָרֶגֶל גַּם הַבְּעָלִים פְּטוּרִים. \u0010g33\u0011 וְאִם שְׁמָרוּהוּ \u0010g34\u0011 שְׁמִירָה פְּחוּתָה, אִם שׁוֹמֵר חִנָּם הוּא פָטוּר, \u0010r18\u0011 וְאִם \u0010r19\u0011 שׁוֹמֵר שָׂכָר אוֹ שׂוֹכֵר אוֹ שׁוֹאֵל הוּא, \u0010g35\u0011 חַיָּבִים:\nמְסָרוֹ הַשּׁוֹמֵר לְשׁוֹמֵר אַחֵר וְהֻזָּק, חַיָּב, שֶׁשּׁוֹמֵר שֶׁמָּסַר לְשׁוֹמֵר \u0010y19\u0011 חַיָּב, אֲפִלּוּ שׁוֹמֵר חִנָּם שֶׁמָּסַר לְשׁוֹמֵר שָׂכָר. וְאִם הִזִּיק, \u0010y20\u0011 חַיָּב הַשּׁוֹמֵר הָרִאשׁוֹן לְשַׁלֵּם לַנִּזָּק, וְיֵלֶךְ לַעֲשׂוֹת דִּין עִם הַשּׁוֹמֵר הַשֵּׁנִי. \u0010g36\u0011 וְאִם מְסָרָהּ שׁוֹמֵר רִאשׁוֹן לִבְנוֹ אוֹ לְבֶן בֵּיתוֹ אוֹ לַמְסַעֲדוֹ, \u0010g37\u0011 נִכְנְסוּ תַּחַת הַשּׁוֹמֵר, וְחַיָּבִים.\nאִם הִזִּיק שׁוֹרוֹ שֶׁל שׁוֹאֵל לְשׁוֹרוֹ שֶׁל מַשְׁאִיל אוֹ אִפְּכָא, נִתְבָּאֵר בְּסִימָן שמ\"ז.",{"g":["א) ל' הטור פלוגתא דתלאי בספ\"ד דב\"ק דף מ\"ה ע\"ב ופסקו הפוסקים כרבי יהודה ובגמ' שם מפ' טעמיה מקרא","ב) מבואר בבריי' שם בפ\"ז דף צ\"ה ע\"ב ובגמ' שם","\u0003ג) כן משמע בגמ' שם דף צ\"ו ע\"א גבי הא דאמר רבא והוא שחתרה וכו'\u0004 ","ד) מבואר במ\"ש בסימן רצ\"א ס\"ו","ה) כן כתב הטור כיון שאין האונס בא מחמת הפשיעה וכן משמע שם בגמ' גבי הא דאמר רבא וכו' אבל הרמב\"ם רפ\"ד מנזקי ממון כתב סתם אפילו חתרה ויצאה","ו) שם ס\"ב שם במשנה","ז) שם בגמ'","ח) כן כתבי התוספת שם במשנה","ט) באפילה תוספת שם","י) שם בתוס' מדיוקא דמתני'","כ) שם ס\"ג שם במשנה","פי' כשהזיקה דברשותייהו קיימא","ל) שם בגמ' דף כ\"ו ע\"ב","מ) כ\"כ התוספת שם בשם הירושלמי וכ\"כ הרא\"ש שם","נ) אם הזיקה דלא נכנסו תחת הבעלים להתחייב בשמירתן כיון שלא נתכוונו לזכות בהן אבל אם נאבדה הבהמה חייבים","ס) ל' הרמב\"ם בפ\"ד מה' נזקי ממון ד\"ב ברייתא וסוגיא דגמ' שם סוף דף כ\"ה","ע) כתב ה\"ה פי' רבינו ז\"ל פטור וחייב בנזק שהזיקה הבהמה שהקשה עליו מהמשנה דלמעלה דקתני הוציאוה לסטים דוקא הוציאוה וכו' והשיב ז\"ל שחלוק בין לסטי' המתכונין לגניבה ולא לפרוץ גדר ובין זה המתכוון לפרוץ גדר ולא לגנוב והראה פנים לדבריו","פ) בשם פי' אחרים ושכן דעת האחרונים וחייב על הבהמה שנאבדה ושכן דעת הראב\"ד ע\"כ וכ\"כ הטור בשם הרמ\"ה וכתב הב\"י לפי שהוא סובר דהא דפריך נתחייב אבהמה נמי קאי דכיון דפרצו הגדר בפנים הוי כאילו אבדוה בידים","צ) כפי' רש\"י ותוס' שם","ק) ד\"ה שם במשנה רפ\"ו כדאמר רבה שם דף נ\"ו ע\"ב","ר) שם ד\"ו ברייתא שם בפ\"ק ד\"ט ע\"ב וסוגיא דגמ' אליבא דחזקיה שם","ש) כתב ה\"ה ופי' רבינו בשור קשור כראוי ואעפ\"כ (חייב) שדרכן של אלו לשחוק בהן ולהתירן וה\"ל תחלה בפשיעה ואפילו סופו באונס כגון שחתרה חייב כו' וכפי' זה הכריע הרשב\"א ע\"כ וכ\"פ התוס' שם אהא דאמרי' שם שור דרכו לנתוקי וכו'","ת) שם ד\"ז מבואר שם דף י' ע\"א","א) כ' ה\"ה כן פירשו כל המפרשים","ב) טור ס\"ו וכ\"פ הרא\"ש שם","ג) וביאר שם שהרי מסר לכולן שורו לכל מי שיכול לשמרו ונתרצה לשמרו אפילו בלא חבירו","ד) שם ס\"ז וכ\"כ ה\"ה שם ד\"י שכ\"נ מלשון הרמב\"ם וכן דעת הרשב\"א ז\"ל","ה) ממימרא דר' אלעזר וכדמפ' לה רבא שם ספ\"י דף מה ע\"ב","ו) למה שהוא מוחזק","ז) משנה שם","ח) וכ\"כ הרמב\"ם שם די\"ב וכתב ה\"ה מהא דאמרי' שם ד' מ' ע\"א סוף סוף לאו תורא בעית שלומי לדידיה","ט) כ\"כ הרמב\"ם שם ד\"ד","י) כ\"כ ה\"ה שם לפי שבהן הבעלים חייבים אף בשמירה מעולה ובזה נתיישב מה שתמה הטור בס\"ז ע\"ז והכ\"מ כ' שחכמי לוניל שאלו לרבי' על מה זה הבעלים חייבים כיון ששמרוה השומרים שמירה מעולה והשיב להם שטעות סופ' וכך היא נוסחא האמיתית ויצתה והזיקה השומרים פטורים שמרוה שמירה פחותה אם ש\"ח הוא פטור והבעלים חייבים ואם ש\"ש או שוכר או שואל חייבים","כ) שם ברמב\"ם","ל) מבואר לעיל ס\"א","\u0003מ) שם די\"א מבואר במ\"ש בסי' רצא ס' כו\u0004 ושם במשנה רפו שם בגמ' דף נז ע\"ב","נ) מבואר שם בגמ' ובסי' רצא שם","ס) כתב ה\"ה פירושו ☜שאפילו אין להם לשלם לאלו הוא פטור ואין כאן מקום להשגה כלל וכו' שהרי הדברים מבוארים שם בגמ'"],"t":["\u0003פטור. \u0004 כת' הסמ\"ע דלהרמב\"ם פטור לגמרי אפילו מח\"נ ולהתוספות והרא\"ש אינן פטורין אלא מנ\"ש אבל ח\"נ חייב כו' ע\"ש:","\u0003מחמת. \u0004 וה\"נ מקרי מחמת פשיעה דאילו העמיד לפניה דלת חזקה לא היתה נופלת מחתירתה בקרקע או מנגיחתה בהדלת עצמה. שם:","\u0003שחתרה. \u0004 קאי ג\"כ אבלילה שלפניו. שם:","\u0003הם. \u0004 פירוש הגזלן חייב על מה שהזיקה הבהמה אע\"ג דהגזלן לא קנה לה במשיכה דמאן א\"ל למשוך מ\"מ כיון דעשה בה דבר הקונה במקח וממכר והיא עתה ברשותו חייב בשמירתה כ\"כ התוספות והרא\"ש. שם:","\u0003עצמה. \u0004 ונראה דאינו פטור מהבהמה אלא בדיני אדם אבל בדיני שמים ודאי חייב ק\"ו מכותל רעוע וע\"ל סי' שפ\"ו בטור ס\"ג ועיין בתשו' רשד\"ם סי' שס\"ה. שם:","\u0003וחייב. \u0004 והתוספות כתבו דדוקא אהבהמה שהזיקה חייב ולא אהכותל כיון שהיתה רעוע והרא\"ש כת' שאפשר דגם על הכותל חייב דהא ראויה לעמוד יום או יומים עד שימצאו פועלים לתקנה כו' וכן נראה שהוא דעת הט\"ו שסתמו וכתבו חייב ולהרמב\"ם חייב אפילו אכותל רעוע בדיני אדם. שם:","\u0003מעולה. \u0004 הטעם כיון שפשעו הבעלים מתחלה במה שסמכו על הקשר כיון שדרך השור לנתק הקשר אמרינן דודאי גם קשר זה התירוהו וה\"ל כאילו לא עשו להבהמה שום שמירה ויצאה מתחת ידם והזיקה ואע\"ג דבעלמא בעינן שיבא האונס מחמת הפשיעה כמ\"ש בסי' רצ\"א \u0005(ע\"ש ס\"ק י\"ד)\u0006 שאני הכא דאותה פשיעה הראויה לבא בשעה שמסרו הבהמה ליד חש\"ו דהיינו שתצא ותזיק היא הנעשית לבסוף מש\"ה אף שנעשה באונס חייבים הבעלים עליהם וע\"ל סי' ת\"י סכ\"ג. שם:","\u0003חייבים. \u0004 דהשמירה מוטלת על כל אחד ולא היה לזה להסתלק בלי רשותם. שם:","\u0003השומרים. \u0004 ר\"ל אפילו השואל אע\"ג דחייב באונסין היינו דוקא אם הוזקה הבהמה שהוא שומר עליה ולא לענין אם יצאה והזיקה. שם:","\u0003הראשון. \u0004 ומ\"מ אם ירצה הניזק יעשה דין עם השני אלא דקאמר שגם דינו עם הראשון דה\"ל פשיעה גביה שמסרו לשני והבעלים י\"ל אתה נאמן עלי בשבועה ולא האחר ול\"ד לדין שלפני זה דהתם בעל השור ברשות נתנו להשומר גם בדין שאח\"ז בנתנו השומר לבנו כו' הוא ברשות דכל המפקיד ע\"ד אשתו ובניו הוא מפקיד וע\"ל סי' רצ\"א. שם:"],"r":["\u0003שור המועד. \u0004 כרב שם וכ\"פ הרמב\"ם. והרא\"ש פ' כר\"א בר אהבה:","\u0003וכן כו'. \u0004 נ\"ה ב' ולד\"ה:","\u0003לפיכך כו'. \u0004 שם ושם:","\u0003בד\"א כו'. \u0004 כר\"י:","\u0003אפי' כו'. \u0004 נו א' אלא בכותל כו':","\u0003הבא כו'. \u0004 כמ\"ש בסי' רצא ס\"ט וז\"ש אבל כו' וערש\"י שם ד\"ה תחלתו כו' כל תחבולות כו' ופי' דחוק דהא אכתי לא ידעינן טעמא דכל טצדקי כו' וכן מ\"ש בתחלה לא מיבעיא היכא כו' וק' והאיך יצאה אלא דבכותל רעוע עסקינן וכה\"ג ואף למ\"ד תחלתו כו' חייב דמודה כה\"ג כנ\"ל אלא דלמסקנא דקאי כל טצדקי כו' אפי' בכותל בריא אלא דרבה לרבותא קאמר דלס\"ד ה\"א אף בכותל רעוע פטור ובזה מתורץ קושית תוס' ד\"ה מ\"ד כו':\n\u0003 (ליקוט) וקי\"ל כל כו' אבל כו'. \u0004 עתוס' כב ב' ד\"ה ושכיחי. וא\"ת בהכונס כו' (ע\"כ):","\u0003אפי' ידע. \u0004 כלשון ב' של תוס' שם ד\"ה נפרצה:","\u0003הפורץ כו'. \u0004 מפ' אנזקיה מדהביא הגמ' אמתני' ש\"מ דומיא דמתני' ואע\"ג דבמתני' תנן דפטור ודוקא הוציאוה חייב כמ\"ש במתני' ועתוס' שם ד\"ה או כו' תי' הרמב\"ם והביאו מ\"ע והמ\"מ דכאן שאני שנתכוין שתזיק משא\"כ במתני' ועבה\"ג וס\"ל דגרמי הוא רק שאינו חייב אלא במתכוין להזיק וכשיטתו דס\"ל דכל גרמא חייב כמ\"ש בסי' שפו ואינו מחלק אלא בין מתכוין או לא כמ\"ש בסי' כה ס\"ג ע\"ש ועמ\"ש בסי' כה ובסי' שפח:","\u0003וי\"א כו'. \u0004 כנ\"ל וכמ\"ש בס\"ג:","\u0003וי\"א כו'. \u0004 רש\"י ותוס' ד\"ה אילימא כו' אבל דעת הרמ\"ה דחייב אבהמה ועתוס' דסנהדרין ע\"ז א' ד\"ה בנזקין כו' ומיהו יש כו' ובזה אתי שפיר מ\"ש בפני בהמה אף לס\"ד דמקשה דלתוס' אינו ניחא אלא למסקנא כמ\"ש שם וכן מתורץ קושיתם וא\"ת כו'. וס\"ל דגרמי הוא ודוקא אנזקיה אמר במתני' דפטורים דזה גרמא הוא אבל באבידתה כמזיק בידים הוא וכן פ' הרב:","\u0003ולכן כו'. \u0004 ערש\"י שם ד\"ה הניחה כו' ותוס' ד\"ה מ\"ד כו'. והראב\"ד חולק ולדידיה אתי הסוגיא שפיר כמ\"ש בס\"א:","\u0003מסר כו'. \u0004 שם במתני' וגמ' ט' ב':","\u0003שדרך כו'. \u0004 שם ועתוס' שם:","\u0003אפי' כו'. \u0004 נ\"ו א' וכפרש\"י כנ\"ל וכן בחש\"ו דאשניהם קאי דמתני' בחדא כללינהו:","\u0003אף אלו כו'. \u0004 רמב\"ם ועתוס' שם ד\"ה מאי. בכולה שמעתין כו' וכ\"כ הרשב\"א ומה שהקשו תוס' מיהו כו' תי' הרשב\"א דבאמת כה\"ג פטור אבל לא אמרו אלא במרבה חבילה שיש בה כדי לילך ולהזיק אבל הרא\"ש ס\"ל כפי' הנ\"י דפטור לגמרי וכמש\"ל סי' שפא וסי' שפג ופי' דהסוגיא איירי שלא נסתלקו משמירתו וז\"ש וי\"א כו' וצ\"ע שבסי' הנ\"ל סתם כס' האחרונה וכן בסי' שפח ס\"ז בהג\"ה:\n\u0003 (ליקוט) אף אלו חייבים \u0004 לשון הרמב\"ם וכ' המ\"מ כן פי' כל המפרשים והוא כדברי תוס' שם ד\"ה מאי כו' וכ\"כ בהג\"א וכ\"פ הרשב\"א וקושית תוס' והג\"א מיהו כו' תי' הרשב\"א דלא אמרו מרבה בחבילה אלא שיש בה לילך ולהזיק כמו בחופר עשר ועשרים הלא\"ה דומה להשלים לי\"א אבל הרא\"ש פי' דכולה סוגיין מאי קעביד ופטור מכח קושית תוס' הנ\"ל וכ\"כ טוש\"ע בסי' תיח ס\"י ובסי' שפא בהג\"ה וז\"ש כאן וי\"א כו' וערא\"ש שם וכ\"כ הרמב\"ם וש\"ע בסי' שפג ס\"ד וכ\"כ המ\"מ שם ע\"ש וצ\"ע (ע\"כ):","\u0003מסרו כו' מסתמא כו'. \u0004 ערא\"ש פ\"ה ס\"ד האי דקאמר כו' וכ\"כ רשב\"א בספ\"ד ממש\"ש כשהכיר שהוא נגחן כו' מ' דבסתמא מקבל הכל וכ\"כ בירוש':\n\u0003 (ליקוט) מסרו כו'. \u0004 ממש\"ש מ\"ה והב\"ע כגון שהכיר כו' הלא\"ה מסתמא קיבל שמירת כ\"ד ושם מ\"ח ב' ת\"ר כנוס כו' אלמא מסתמא קבל כ\"ד ובירוש' אר\"א מסר שור תם לש\"ח יצא והזיק פטור יצא ונטרף חייב אלמא בסתמא מקבל. רשב\"א ספ\"ד (ע\"כ):","\u0003נכנסו כו'. \u0004 מתני' מ\"ד ב' וגמ' נו ב' י\"ג ב':","\u0003ואם שמרוהו כראוי כו'. \u0004 בסוגיא מ\"ה א\"ב וט\"ס כאן כמ\"ש הרמב\"ם בתשובה וכ\"ה בשמירה מעולה כולם פטורין השומרים והבעלים בכ\"ע. וכן בשמירה פחותה במועד וכן שן ורגל ובתם בש\"ח הבעלים חייבים ושאר שומרים הם חייבים:","\u0003ואם כו'. \u0004 עסי' רצא סכ\"ד ובהג\"ה:","\u0003או כו'. \u0004 נו ב':"]}],["מִי שֶׁבְּהֶמְתּוֹ רְגִילָה לִכָּנֵס לִשְׂדֵה חֲבֵרוֹ וּמַזִּיקָתוֹ, \u0010y0\u0011 יָכוֹל בַּעַל הַשָּׂדֶה לְהַתְרוֹת בְּבַעַל הַבְּהֵמָה שֶׁיִּשְׁמֹר בְּהֶמְתּוֹ, וְצָרִיךְ לְשָׁמְרָהּ. \u0005וְאִם לֹא שְׁמָרָהּ וְהִזִּיקָה, \u0010c0\u0011 חַיָּב לְשַׁלֵּם הֶזֵּקוֹ (כֵּן מוּכָח מִדִּבְרֵי הַתוס' וְהָרֹא\"שׁ)\u0006. \u0010y1\u0011 וְאֵינוֹ יָכוֹל לוֹמַר לוֹ: גְּדֹר שָׂדְךָ כְּדֵי שֶׁלֹּא תִּכָּנֵס בּוֹ:\nהַקַּצָּבִים שֶׁיֵּשׁ לָהֶם בְּהֵמוֹת לִשְׁחֹט בְּיוֹם הַשּׁוּק, אִם הֵם מַזִּיקוֹת \u0010y2\u0011 \u0010y3\u0011 אֲפִלּוּ בִרְשׁוּת הָרַבִּים, מַתְרִים בַּבְּעָלִים שָׁלֹשׁ פְּעָמִים שֶׁיִּשְׁמְרוּם, וְאִם לֹא שְׁמָרוּם, רַשַּׁאי הַנִּזָּק לְשָׁחֲטָם שְׁחִיטָה כְּשֵׁרָה, וְאוֹמְרִים לַבְּעָלִים: בּוֹאוֹ וּמִכְרוּ הַבָּשָׂר שֶׁלָּכֶם:",["\u0003יכול הבעל השדה להתרו' כו'. \u0004 אבל לא לשחטם כמ\"ש בסעיף שאחר זה ששם מיירי מבהמות של קצבים שעומדי' לשחיטה אלא שהקצבים רוצים להשהות עד יום השוק שיכולין למכור אז הבשר ביוקר וקאמר דמשום הזיקתן מקדימין שחיטתן אם לא ישגיחו הקצבים בההתרא' משא\"כ כאן דאיירי בסתם בהמות דאינן עומדין לשחיטה:","\u0003ואינו יכול לומר לו גדור כו'. \u0004 דעל הבעלי' לשמור בהמת' שלא יזיקו ודומה זה לבהמה האוכלת מתוך החנות דחייבי' בעלי' לשלם לבעל החנות היזקתו כמ\"ש הטור והמחבר בסי' שצ\"א ואינו יכול לומר לו ה\"ל לסגור חנותך ע' בטור שם כ' שר\"ת והרא\"ש חולקין ע\"ז וס\"ל דאינו דומה לאכל' מתוך החנות ע\"ש ובפרישה:","\u0003אפי' בר\"ה. \u0004 ר\"ל אף דשם רשות המזיק והניזק שוה וה\"ל להניזק לשמור עניינו משור המזיק:","\u0003מתרין בבעלי' ג\"פ. \u0004 לא קאמר שצריכין שיזיקו ג\"פ אלא אף שלא הזיקו אלא פעם א' ואחר ההיזק התרו בבעלי' ג\"פ הרשות ביד הניזק לשחטם אם לא שמרם ואף אם ישיב בעל הבהמ' אם יהי' למי היזק מבהמתי אשלמנה לא משגיחין ביה דאין אדם רוצה להיות ניזק ולהטפל נפשו בתשלומין וגם ניחא לאדם בשלו והיינו דוקא בבהמת הקצבים דבלה\"נ עומדי' לשחיטה ביום השוק וכנ\"ל:"],["\u0003 חייב לשלם הזיקו ואינו יכול כו'. \u0004 ב\"י כתב שכך הם דברי הרמב\"ם פ\"ה מהל' נזקי ממון ועיינתי שם בכל דברי הרמב\"ם בהלכות נזקי ממון חפשתי ולא מצאתי דבר מזה ואי משום שכ' הרמב\"ם שם שחייב לשלם כשהזיקה הבהמה בשדות אחרות אין ראיה דהא בקרא נמי כתיב ובער בשדה אחר ומוקמינן לה בש\"ס כשגדר וחתרה או נפל בלילה וגם מ\"ש ב\"י שאין בדברי הרא\"ש הכרע דבריו תמוהין שהרי הרא\"ש מביא במסקנתו דברי רבינו חננאל ודוחה דברי התוס' ע\"ש ושפיר כ' הטור שמסקנת הרא\"ש כר\"ח: ומהרש\"ל כתב בפ\"ק דב\"ק סי' כ\"ה דלא נהירא כלל דברי ר\"ח דא\"כ למה סתם רועים גזלנים ופסולי' לעדות לפי שאינם נזהרים משדות אחרות ואי היה צריך לגדור כל אדם שדהו מסתמא כל השדות גדורים הם וא\"כ איך נכנס' בשדות אחרים כי מה שהבהמה חתר' הגדר לא שכיח כו' לכן נ\"ל כרב יוסף דהוא רבו של אביי ואין הלכה כתלמיד במקום הרב כו' עכ\"ל ודבריו לא נהירין לי דנהי דפטו' כשהזיק מ\"מ מסתמא כל השדות אינם גדורים ופוק חזי דאין דרך בני אדם לגדור שדותיהם דא\"כ צריך לגדור כל העולם אלא אין חוששין להיזק בהמות דלא שכיח שיזיקו בהמות בשדות אחרות והגע עצמך אף לדברי מהרש\"ל דחייב וכי בכל פעם יהיו לו עדות שהזיק' או פעמים שהוא עצמו לא ידע מהיזק הבהמות אלא ודאי אין חוששין לכך וכמ\"ש וסתם רועה פסול לעדות משום שרועה במזיד בשדות אחרות. גם בלאו הכי תימה על מהרש\"ל איך רוצה להכריע נגד אביי והלא אין בידינו להכריע מה שנחלקו בו חכמי הש\"ס והלא בע\"כ גם אביי מודה להא דסתם רועים פסולי' אלא ודאי כמ\"ש וגם על התוס' קשה כן שכתבו דאין הלכה כאביי משום דתניא אכלה מתוך החנות כו' ומ\"ש התוס' דאביי אשתמוטי קמשתמיט דוחק גדול הוא. גם מ\"ש מהרש\"ל דאין הלכ' כתלמיד במקו' הרב לא נ\"ל ואדרבא הא קי\"ל דהלכ' כבתראי מאביי ורבא ואילך ואולי כוון למ\"ש הנ\"י דאביי נגד רב יוסף תלמיד היושב לפני רבו היה באותו מעש' אבל גם זה לא נ\"ל ואדרבא משמע מדשתיק ליה רב יוסף אודי ליה ועוד דמשמע דהא דגרסי' בש\"ס ואי גדר שן דחייב רחמנא היכא משכחת לה כו' משמע דסתמא דש\"ס הוא דקפריך הכי דאי רב יוסף קא' לה הל\"ל אמ\"ר לי\"ה ואי שן כו' וא\"כ כיון דסתמא דש\"ס קאמר משמע דסתמא דש\"ס ס\"ל כאביי מדמשני אליבא דאביי כשחתר' או דנפל בלילה ואפי' תימא דרב יוסף קאמר לה מ\"מ משמע דקבל שינוי דאביי שחתר' כו' וכן מצאתי בהלכות גדולות דף פ\"ז סוף ע\"ג שכ' כדברי אביי וכ\"כ ראב\"ן בב\"ק דף פ\"ו ריש ע\"ב וז\"ל מהכא שמעינן דשן דחייב רחמנא בשד' אחר לא מיחייב אלא כשחתר' או דנפל גודא בלילה אבל אי לא גדר ארעי' ונכנסה בהמה ואכל' פטור עכ\"ל כיון דהלכות גדולות ורבינו חננאל וראב\"ן והרא\"ש וטור סוברים דפטור הכי נקטינן דכבר נודע שדברי ה\"ג ור\"ח דברי קבלה הם מהש\"ס ובפרט שהוכחתי שדבריהם עיקר:"],"מִי שֶׁבְּהֶמְתּוֹ רְגִילָה \u0010g0\u0011 \u0010r0\u0011 לִכָּנֵס לִשְׂדֵה חֲבֵרוֹ וּמַזִּיקָתוֹ, \u0010y0\u0011 יָכוֹל בַּעַל הַשָּׂדֶה \u0010t0\u0011 לְהַתְרוֹת בְּבַעַל הַבְּהֵמָה שֶׁיִּשְׁמֹר בְּהֶמְתּוֹ, וְצָרִיךְ לְשָׁמְרָהּ. \u0005וְאִם לֹא \u0010g1\u0011 שְׁמָרָהּ וְהִזִּיקָה, \u0010c0\u0011 חַיָּב לְשַׁלֵּם הֶזֵּקוֹ (כֵּן מוּכָח מִדִּבְרֵי הַתוס' וְהָרֹא\"שׁ)\u0006. \u0010y1\u0011 \u0010g2\u0011 וְאֵינוֹ יָכוֹל לוֹמַר לוֹ: \u0010t1\u0011 גְּדֹר שָׂדְךָ כְּדֵי שֶׁלֹּא תִּכָּנֵס בּוֹ: \u0010g3\u0011\nהַקַּצָּבִים שֶׁיֵּשׁ לָהֶם בְּהֵמוֹת לִשְׁחֹט בְּיוֹם הַשּׁוּק, אִם הֵם מַזִּיקוֹת \u0010y2\u0011 \u0010y3\u0011 \u0010g4\u0011 \u0010g5\u0011 \u0010t2\u0011 \u0010r1\u0011 אֲפִלּוּ בִרְשׁוּת הָרַבִּים, מַתְרִים \u0010t3\u0011 בַּבְּעָלִים שָׁלֹשׁ פְּעָמִים שֶׁיִּשְׁמְרוּם, וְאִם לֹא שְׁמָרוּם, \u0010g6\u0011 רַשַּׁאי הַנִּזָּק לְשָׁחֲטָם שְׁחִיטָה כְּשֵׁרָה, וְאוֹמְרִים לַבְּעָלִים: בּוֹאוֹ וּמִכְרוּ הַבָּשָׂר שֶׁלָּכֶם:",{"g":["\u0003א) ל' הטור בשם ר\"י מעובדא דהנהו עיזי דבי תרבא וכדאמר ר' יוסף לאביי.\u0004 ז\"ל כו' בפ\"ב דב\"מ דף נג ע\"ב","☜ולענ\"ד צריך עיון דלדעת הרא\"ש יכול לומר לו גדור שדך כדעת ר\"ח כמ\"ש הטור בסמוך לדעת התוס' שהביאו ראיה מאכלה תוך חניות וכו' נראה דחייב לשלם ואפילו לא התרה בו וכ\"כ הראב\"ד וכ\"כ ה\"ה בפ\"ה מהנ\"מ בשם רוב המפרשים לענ\"ד נ' שתשלומין הוא אפי' בלא התראה אבל התראה היא שיסלק הזיקו דאע\"פ שמשלם הזיקו לא בעי למוקם עלייהו בדינא ולפעמים אין האדם כמ\"ש התו' גבי הנהו עיזי דשוקא וכו' וכדעת הריטב\"א והרמ\"ה שהביא הנ\"י דמשמתי' למרייהו עד דמסלקי היזקא","ב) דליתיה לאביי דאמר הכי לרב יוסף כמ\"ש הרי\"ף דדיחוי בעלמא הוא וכ\"כ התוס' שם היה נשמט אביי שלא היה חפץ לילך לשם","\u0003ג) שם ס\"ב ושם בגמ' מכריז רב יוסי ואתימא רבה וכו'\u0004 ","ד) כן כתב רש\"י והרא\"ש שם","ה) ל' הרמב\"ם ריש פ\"ה וכ\"כ הרי\"ף וכן הוא בגמ' שם אכן במ\"ש הרמב\"ם שם שהדין כן בכל הבהמות לא קי\"ל כוותיה","פי' אפילו ביומא דלאו שוקא רש\"י"],"t":["\u0003להתרות. \u0004 אבל לא לשחיטה ול\"ד לסעיף שאח\"ז בבהמות קצבים שעומדין לשחיטה אלא שהקצבים רוצין לשהותן עד יום השוק כדי למכור הבשר ביוקר וקאמר דמשום הזיקתן מקדימין שחיטתן אם לא ישגיחו בההתראה משא\"כ כאן בסתם בהמות דאינן עומדות לשחיטה. סמ\"ע:","\u0003גדור. \u0004 דעל הבעלים לשמור בהמתן שלא יזיקו ודומה זה לבהמה האוכלת מתוך החנות כו' כמ\"ש בסי' שצ\"א ס\"ט וא\"י לו' לו ה\"ל לסגור חנותך ועיין בטור שכת' שר\"ת והרא\"ש חולקין ע\"ז וס\"ל דאינו דומה לאכלה מתוך החנות ע\"ש עכ\"ל הסמ\"ע וכן הוא דעת הש\"ך דאם לא גדר ארעיה ונכנסה בהמה ואכלה פטור דשן דחייב רחמנא בשדה אחר לא מיחייב אלא כשחתרה או דנפל גודא בלילה ע\"ש שהאריך בזה ומסיק וכת' ז\"ל וכיון דהלכות גדולות ור\"ח וראב\"ן והרא\"ש וטור סוברים דפטור הכי נקטינן דכבר נודע שדברי ה\"ג ור\"ח דברי קבלה הן מהש\"ס ובפרט שהוכחתי שדבריהן עיקר עכ\"ל:","\u0003בר\"ה. \u0004 ר\"ל אף דשם רשות המזיק והניזק שוה וה\"ל להניזק לשמור ענינו משור המזיק. סמ\"ע:","\u0003פעמים. \u0004 ואף שלא הזיקו אלא פעם אחד ואחר ההיזק התרו בבעלים ג\"פ הרשות ביד הניזק לשחטן אם לא שמרן ואפי' אם יאמר הקצב שישלם מה שיזיקו בהמותיו לא משגחינן ביה דאין אדם רוצה ליטפל נפשו בתשלומי נזקו וגם ניחא לאדם בשלו. שם:"],"r":["\u0003מי כו'. \u0004 עתוס' שם ד\"ה וכלי כו' וז\"ש ואם כו' אפי' בלא התראה. ודלא כר\"ח וכ\"פ הרי\"ף:","\u0003מתרין כו'. \u0004 עבה\"ג ועתוס' ד\"ה הנהו כו' וכ\"פ הפוסקים:"]}],["הִכְנִיס שׁוֹרוֹ לַחֲצַר חֲבֵרוֹ שֶׁלֹּא בִּרְשׁוּת, וּנְגָחוֹ שׁוֹרוֹ שֶׁל בַּעַל הֶחָצֵר, פָּטוּר. וְכֵן אִם הִזִּיקוֹ בַּעַל הֶחָצֵר, פָּטוּר, שֶׁיָּכוֹל לוֹמַר: כֵּיוָן שֶׁהִכְנִיסוֹ שֶׁלֹּא לְדַעַת לֹא יָדַעְתִּי בּוֹ עַד שֶׁשָּׁגִיתִי בּוֹ. וּמִיהוּ, אִם הִזִּיקוֹ לְדַעַת, חַיָּב לְשַׁלֵּם נֶזֶק שָׁלֵם, שֶׁאַף עַל פִּי שֶׁיֵּשׁ לוֹ רְשׁוּת לְהוֹצִיאוֹ מֵרְשׁוּתוֹ, אֵין לוֹ רְשׁוּת לְהַזִיקוֹ.\nהִזִּיק שׁוֹר הַנִּכְנָס לְבַעַל הֶחָצֵר אוֹ לְשׁוֹרוֹ, \u0010y0\u0011 דִּינוֹ כְּאִלּוּ הִזִּיקוֹ בִּרְשׁוּת הָרַבִּים, וּמְשַׁלֵּם תָּם חֲצִי נֶזֶק וּמוּעָד נֶזֶק שָׁלֵם.\nקִלְקֵל אֶת הֶחָצֵר, כְּגוֹן שֶׁחָפַר בּוֹ בּוֹרוֹת שִׁיחִין וּמְעָרוֹת, בַּעַל הַשּׁוֹר חַיָּב בְּנִזְקֵי הֶחָצֵר, \u0010y1\u0011 וּבַעַל הֶחָצֵר חַיָּב בְּנִזְקֵי הַבּוֹר, מִפְּנֵי שֶׁהָיָה לוֹ לְסָתְמוֹ.\nנָפַל לְבוֹר שֶׁבֶּחָצֵר וְהִבְאִישׁ אֶת מֵימָיו; אִם הִבְאִישָׁם \u0010y2\u0011 בִּשְׁעַת נְפִילָה, חַיָּב בְּנִזְקֵי הַמַּיִם; וְאִם הִבְאִישָׁם אַחַר נְפִילָה, פָּטוּר, \u0010y3\u0011 שֶׁהֲרֵי נַעֲשָׂה כִּשְׁאָר תַּקָּלָה שֶׁחָשׁוּב כְּבוֹר, וְהַמַּיִם חֲשׁוּבִים כְּכֵלִים, \u0010y4\u0011 וּבוֹר פָּטוּר בְּנִזְקֵי כֵלִים. \u0010c0\u0011\nאִם הִכְנִיסוֹ \u0010y5\u0011 בִּרְשׁוּת בַּעַל הֶחָצֵר, פָּטוּר בַּעַל הַשּׁוֹר. \u0010y6\u0011 \u0010c1\u0011 וְאִם הִזִּיק שׁוֹר בַּעַל \u0005הֶחָצֵר\u0006 לַשּׁוֹר הַנִּכְנָס בִּרְשׁוּת, פָּטוּר, אֶלָּא אִם כֵּן קִבֵּל עָלָיו בַּעַל הֶחָצֵר שְׁמִירָתוֹ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּכֵיוָן דְּנָתַן לוֹ רְשׁוּת לִכָּנֵס הָוֵי כְּאִלּוּ קִבֵּל עָלָיו שְׁמִירָתוֹ. וְדַוְקָא בִּנְזִיקִין דְּאָתוּ לֵהּ מִבַּעַל הֶחָצֵר, אֲבָל \u0010c2\u0011 בִּנְזִיקִין דְּאָתוּ לֵהּ מֵעָלְמָא, אֵינוֹ חַיָּב עַד שֶׁיְּקַבֵּל עָלָיו שְׁמִירָתוֹ (טוּר בְּשֵׁם ר\"י וְהָרֹא\"שׁ)\u0006.",["\u0003דינו כאלו הזיקו בר\"ה כו' ול\"ת דאפי' תם ישלם נ\"ש בהיזק דקרן מק\"ו דשן ורגל שאין משלמין עליהן בר\"ה אפ\"ה משלמין עליהן ברשו' הניזק נ\"ש קמ\"ל דלא אלא אמרינן דיו הואיל דבר\"ה אינו משלם אקרן כ\"א ח\"נ גם ברשות הניזק ישלם כן ועמ\"ש בסימן שפ\"ט:\u0004","\u0003ובעל החצר חייב בנזקי הבור. \u0004 והיינו דוקא בדהפקיר אח\"כ רשותו שסביב הבור ולא הפקיר הבור דאל\"כ ה\"ל בור בחצר המזיק ויכול לומר לניזק אנת ברשותי מאי בעית וכדמוכח בדברי הטור והמחבר בסי' ת\"י ס\"ב [ס\"ו] או שהבור הוא ברשותו סמוך לר\"ה וכמ\"ש הטור והמחבר שם:","\u0003בשעת נפילה חייב. \u0004 פי' שור תם ח\"נ ומועד נ\"ש כדין קרן:","\u0003שהרי נעשה כשאר תקלה שחשוב כבור. \u0004 פי' כבור דבעל השור:","\u0003ובור פטור בנזקי כלים. \u0004 לקמן סימן ת\"י ילפינן מדכתיב שור ולא אדם חמור ולא כלים ולא אמרינן דבל\"ה פטור כיון דלא סלקן בעל החצר וכמ\"ש הטור והמחבר שם בסימן ת\"ג ובסימן ת\"י דעל הניזק לסלק דבר המזיק והמזיק ישלם לו הוצאתו וטירחתו דשאני בסימן ת\"י דמאחר שמשלם לו בעל השור היזקו דחצירו שוב נקרא הוא בעל הבור כיון דהחצר הוא שלו גם בסי' ת\"ג ס\"ג דשם הדין נותן שמשלם המזיק להניזק נזקו בהנביל' אלא שצריך המזיק למסור הנביל' ליד הניזק וכמ\"ש שם בזה אמרו דלאחר שנודע להניזק מההיזק עליו להשתדל למכור הנביל' כדי שלא יפחו' דמיה והמזיק משלם לו טירחתו משא\"כ כאן דאין לבעל המים חלק בהשור שנפל למימיו ועפ\"ר:","\u0003ברשות בעל החצר \u0004 פי' שבעל החצר נתן רשות לראובן להכניס שורו לחצרו והזיק שור ראובן לשור בעל החצר בזה כ\"ע מודים דפטו' ראובן מההיזק ואם הוא איפכא דשור בעל החצר הזיק לשור ראובן הנכנס בזה פליגי דהמחב' פסק כר' דס\"ל דאף שנתן לו רשות לראובן להכניס שורו מ\"מ לא קיבל עליו שמירת שורו ומור\"ם הביא דעת הפוסקים כרבנן דס\"ל דמסתמא קיבל עליו שמירת שורו כיון דבעל החצר הוא מסתמא הוא ובני ביתו הן בחצירו משא\"כ זה שהכניס שורו דלא נשאר עומד שם לשמור שורו שלא יזיק לבעל החצר ועפ\"ר וע\"ל בסי' רצ\"א דשם נתבאר פלוגתייהו ועיין ג\"כ בסימן שצ\"ג מ\"ש שיש לתמוה על מור\"ם על מ\"ש שם בהג\"ה ס\"א ע\"ש:","\u0003ואם הזיק שור של בעל החצר כו' פטור. \u0004 דקדק וכ' שור כו' דאילו הזיקו בעל החצר בעצמו לשור הנכנס הי' חייב וכמ\"ש המחבר בס\"א דאם הזיקו לדעת חייב ור\"ל לדעת שידע בו שנכנס אף שנכנס שלא ברשות אפי' בשוגג ומשום דאדם מועד לעולם וכמ\"ש בסימן שע\"ח וכ\"ש כאן שנכנס ברשות:"],["\u0003 אם הכניסו כו'. \u0004 ע' בתשובת ר\"ש כהן ס\"ג סי' ו':","\u0003 ואם הזיק שור כו' \u0004 צ\"ל שיש ט\"ס בדברי הראב\"ד וכמ\"ש הרב המגיד ודלא כדאיתא בטור וב\"ח וכדמוכח בהשגות הראב\"ד ספ\"ג מה' נזקי ממון וע' בש\"ס ובתו' ובלח\"מ פ' ז' מהל' נזקי ממון ודו\"ק וצ\"ע:","\u0003 דאתי ליה מעלמא אינו חייב כו'. \u0004 פי' מהרש\"ל כגון שנכנסו שוורים לחצרו והזיקו לזה אבל אם יצא לחוץ והוזק חייב בעל החצר וה\"ה אם חנק עצמו בחצר דחייב ואף אם יצא והזיק לאחרים חייב בעל החצר ע\"ש באריכות ואין משמעו' לשון מוהר\"ם כן ומכ\"מ דברי מהרש\"ל עיקר ודוק בהרא\"ש:"],"הִכְנִיס שׁוֹרוֹ לַחֲצַר \u0010g0\u0011 חֲבֵרוֹ שֶׁלֹּא בִּרְשׁוּת, וּנְגָחוֹ שׁוֹרוֹ שֶׁל בַּעַל הֶחָצֵר, פָּטוּר. \u0010r0\u0011 וְכֵן אִם הִזִּיקוֹ בַּעַל הֶחָצֵר, פָּטוּר, שֶׁיָּכוֹל לוֹמַר: כֵּיוָן שֶׁהִכְנִיסוֹ שֶׁלֹּא לְדַעַת לֹא יָדַעְתִּי בּוֹ עַד שֶׁשָּׁגִיתִי בּוֹ. \u0010g1\u0011 וּמִיהוּ, אִם הִזִּיקוֹ לְדַעַת, חַיָּב לְשַׁלֵּם נֶזֶק שָׁלֵם, שֶׁאַף עַל פִּי שֶׁיֵּשׁ לוֹ רְשׁוּת לְהוֹצִיאוֹ מֵרְשׁוּתוֹ, אֵין לוֹ רְשׁוּת לְהַזִיקוֹ. \u0010g2\u0011 \u0010r1\u0011\nהִזִּיק שׁוֹר הַנִּכְנָס לְבַעַל הֶחָצֵר \u0010r2\u0011 אוֹ לְשׁוֹרוֹ, \u0010y0\u0011 \u0010r3\u0011 דִּינוֹ כְּאִלּוּ הִזִּיקוֹ בִּרְשׁוּת הָרַבִּים, וּמְשַׁלֵּם \u0010r4\u0011 תָּם חֲצִי נֶזֶק וּמוּעָד נֶזֶק שָׁלֵם. \u0010g3\u0011\nקִלְקֵל אֶת הֶחָצֵר, כְּגוֹן שֶׁחָפַר בּוֹ בּוֹרוֹת שִׁיחִין וּמְעָרוֹת, בַּעַל הַשּׁוֹר \u0010g4\u0011 חַיָּב בְּנִזְקֵי הֶחָצֵר, \u0010y1\u0011 וּבַעַל הֶחָצֵר חַיָּב בְּנִזְקֵי הַבּוֹר, \u0010g5\u0011 מִפְּנֵי שֶׁהָיָה לוֹ לְסָתְמוֹ. \u0010g6\u0011\nנָפַל לְבוֹר שֶׁבֶּחָצֵר וְהִבְאִישׁ אֶת מֵימָיו; אִם הִבְאִישָׁם \u0010y2\u0011 בִּשְׁעַת נְפִילָה, חַיָּב בְּנִזְקֵי הַמַּיִם; וְאִם הִבְאִישָׁם אַחַר נְפִילָה, פָּטוּר, \u0010y3\u0011 שֶׁהֲרֵי נַעֲשָׂה כִּשְׁאָר תַּקָּלָה שֶׁחָשׁוּב כְּבוֹר, וְהַמַּיִם חֲשׁוּבִים כְּכֵלִים, \u0010y4\u0011 וּבוֹר פָּטוּר בְּנִזְקֵי כֵלִים. \u0010c0\u0011 \u0010g7\u0011 \u0010r5\u0011\nאִם הִכְנִיסוֹ \u0010y5\u0011 בִּרְשׁוּת בַּעַל הֶחָצֵר, פָּטוּר בַּעַל הַשּׁוֹר. \u0010y6\u0011 \u0010c1\u0011 \u0010r6\u0011 וְאִם הִזִּיק שׁוֹר בַּעַל \u0005הֶחָצֵר\u0006 לַשּׁוֹר הַנִּכְנָס בִּרְשׁוּת, \u0010g8\u0011 פָּטוּר, \u0010g9\u0011 אֶלָּא אִם כֵּן קִבֵּל עָלָיו בַּעַל הֶחָצֵר שְׁמִירָתוֹ. \u0005הַגָּה: \u0010r7\u0011 וְיֵשׁ אוֹמְרִים דְּכֵיוָן דְּנָתַן לוֹ רְשׁוּת לִכָּנֵס הָוֵי כְּאִלּוּ קִבֵּל עָלָיו שְׁמִירָתוֹ. \u0010r8\u0011 וְדַוְקָא בִּנְזִיקִין דְּאָתוּ לֵהּ מִבַּעַל הֶחָצֵר, אֲבָל \u0010c2\u0011 בִּנְזִיקִין דְּאָתוּ \u0010t0\u0011 לֵהּ מֵעָלְמָא, אֵינוֹ חַיָּב עַד שֶׁיְּקַבֵּל עָלָיו שְׁמִירָתוֹ \u0010g10\u0011 (טוּר בְּשֵׁם ר\"י וְהָרֹא\"שׁ)\u0006.",{"g":["א) ל' הטור משנה פ\"ה דב\"ק דף מז ע\"א וכ\"כ הרמב\"ם בפ\"ז מה' נזקי ממון מימרא דרבא שם דף מח ע\"א","ב) מימרא דרב פפא שם","ג) שם סב דלגבי קרן לא שאני לן בין ר\"ה לרשות הניזק ומבואר בסי' שפט","ד) שם סג ממימרא דרבא שם וברמב\"ם שם ד\"ו","ה) וכתב ה\"ה כשהפקיר (בורו) לאחר מכאן כדין בור האמור בכל מקום וזה פשוט ולזה סתם רבינו (מבואר בסי' תי ס\"ו)","ו) שם בגמ' ולקמן סי' תי ס\"ד","ז) שם פ\"ד שם במשנ' כדמפ' לה רבא שם דף מח ע\"ב","ח) שם ס\"ה וכ\"כ הרמב\"ם שם ד\"ה","ט) שם ברמב\"ם וכ\"כ בשמו ובשם הרי\"ף וכתב ס\"ה שם נראין דברי התוס' והם כדברי רבי' שכתבו (שם דף מז ריש ע\"ב) שכך סובר רבי' שכשמכניס שורו ברשות הרי היא כאלו הם מתנה בפי' שיפטר כ\"א בנגיחת שורו ובשאר נזקין וכן עיקר","י) פסק כדברי רבינו שם במשנה וכשמואל שפסק כן (שם דף מח ע\"ב)","כ) שפסקו כחכמים שם במשנה וכרב שפסק כן שם בגמ' וכמ\"ש בסוף שצג"],"t":["\u0003מעלמא. \u0004 כת' הש\"ך דמהרש\"ל פירש כגון שנכנסו שוורים לחצירו והזיקו לזה אבל אם יצא לחוץ והוזק חייב בעל החצר וה\"ה אם חנק עצמו בחצר דחייב ואף אם יצא והזיק לאחרים חייב בעל החצר ע\"ש באריכות ואין משמעות ל' הרמ\"א כן ומ\"מ דברי מהרש\"ל עיקר ודוק בהרא\"ש עכ\"ל וע\"ל סי' רצ\"א ור\"ס שצ\"ג ע\"ש:"],"r":["\u0003וכן כו' ומיהו כו'. \u0004 כמ\"ש בסי' שעח ס\"ו:","\u0003הזיק כו'. \u0004 מח א':","\u0003או לשורו. \u0004 מתני' מז ב':","\u0003דינו כו'. \u0004 פלוגתא דר\"ט ורבנן בספ\"ב וקי\"ל כחכמים:","\u0003תם כו'. \u0004 כמ\"ש בסי' תה ס\"א:","\u0003אם כו'. \u0004 גמ' שם טעמא כו' ואף תוס' מודי בזה שהם פ' כתי' דרבא כמ\"ש בהג\"ה:","\u0003ואם כו'. \u0004 דקי\"ל כשמואל בדיני:","\u0003וי\"א כו'. \u0004 כרבנן דסוגיא כוותייהו ועתוס' מח ב' ד\"ה ושמואל כו' וד\"ה טעמא כו' כולה כו' ר\"ל אבל לרבא לרבי אפי' ברשות חייב דלא כהס\"ד לעיל ולכן אוקמה רבא למתני' כרבנן וז\"ש תוס' בד\"ה הנ\"ל ואי כר' אפי' כו' אבל רב אלפס הביא הא דרבא וס\"ל דאפי' לר' אלא שרוצה לאוקמי מתני' אף כרבנן וכחד תנא ומ\"מ ק' א\"כ לוקמיה ברייתא רישא וסיפא כר'. הרא\"ש וז\"ש בש\"ע אם הכניסו כו'. לרי\"ף לכ\"ע ולתוס' לרבא אליבא דרבנן:","\u0003ודוקא כו'. \u0004 מ\"ז ב' בעיא דלא איפשיטא ולקולא ועתוס' שם ד\"ה אז כו' ומדברי הרא\"ש והטור והרב מ' כתי' הראשון של תוס' אבל הא\"ז והג\"א פ' כתי' הב' וכ\"פ יש\"ש:"]}],["פָּרָה מְעֻבֶּרֶת שֶׁהִזִּיקָה, גוֹבֶה חֲצִי נֶזֶק \u0010y0\u0011 מִמֶּנָּה וּמִוְּלָדָהּ, מִפְּנֵי שֶׁהוּא כְּגוּפָהּ. \u0010y1\u0011 אֲפִלּוּ לֵיתָא לַפָּרָה, מִשְׁתַּלֵּם כָּל חֲצִי נֶזֶק מֵהַוָּלָד, מִפְּנֵי שֶׁהוּא כְּגוּפָהּ. אֲבָל תַּרְנְגוֹלֶת שֶׁהִזִּיקָה אֵינוֹ גוֹבֶה מִבֵּיצָתָהּ, מִפְּנֵי שֶׁהַבֵּיצָה אֵינָהּ מִגּוּפָהּ, אֶלָּא מֻבְדֶּלֶת וּמֻפְרֶשֶׁת. \u0005הַגָּה: מִיהוּ, אִם הַבֵּיצָה אֲגֻדָּה עֲדַיִן בְּגוּפָהּ, יֵשׁ אוֹמְרִים דְּגוֹבִין מִמֶּנָּה (הַמַּגִּיד פ\"ט דְנ\"מ)\u0006.\nפָּרָה מְעֻבֶּרֶת שֶׁנָּגְחָה, וְנִמְצָא עֻבָּרָה בְּצִדָּהּ, וְאֵין יָדוּעַ אִם קֹדֶם נְגִיחָה יָלְדָה, וְאָז אֵין לְהִשְׁתַּלֵּם מֵהַוָּלָד, אוֹ לְאַחַר נְגִיחָה יָלְדָה וְיֵשׁ לְהִשְׁתַּלֵּם מֵהַוָּלָד, \u0010y2\u0011 וְאֵין הַפָּרָה לְפָנֵינוּ, הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה וְלֹא יִטֹּל מֵהַוָּלָד.\nוְכֵן שׁוֹר שֶׁנָּגַח אֶת הַפָּרָה וְנִמְצָא עֻבָּרָה מֵת בְּצִדָּהּ, וְאֵין יָדוּעַ אִם מֵחֲמַת נְגִיחָה הִפִּילָה אוֹ אִם הִפִּילָה קֹדֶם, הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. וַאֲפִלּוּ שֶׁהַנִּזָּק טוֹעֵן בָּרִי, וְהַמַּזִּיק טוֹעֵן שֶׁמָּא, וַאֲפִלּוּ שֶׁאֵין הַמַּזִּיק \u0010y3\u0011 מֻחְזָק, כְּגוֹן שֶׁעוֹמֶדֶת בָּאֲגַם, \u0010c0\u0011 פָּטוּר \u0010y4\u0011 \u0010c1\u0011 וַאֲפִלּוּ מִשְּׁבוּעָה. \u0005הַגָּה: \u0010y5\u0011 \u0010c2\u0011 מִיהוּ, אִם תָּפַס הַנִּזָּק, נֶאֱמָן, אִם יֵשׁ לוֹ מִגּוֹ דְּלָא הָיוּ דְּבָרִים מֵעוֹלָם (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006.\nנָגַח פָּרָה מְעֻבֶּרֶת וְהִפִּילָה, אֵין שָׁמִין פְּחַת פָּרָה בִּפְנֵי עַצְמָהּ וּפְחַת הַוָּלָד בִּפְנֵי עַצְמוֹ, אֶלָּא שָׁמִין כַּמָּה הָיְתָה הַפָּרָה שָׁוָה כְּשֶׁהָיְתָה מְעֻבֶּרֶת וּבְרִיאָה, וְכַמָּה הִיא שָׁוָה עַכְשָׁיו הִיא וְהַנֶּפֶל שֶׁלָּהּ, וּמְשַׁלֵּם הַפְּחָת, אוֹ חֶצְיוֹ אִם הָיָה תָּם.\nהָיְתָה הַפָּרָה לְאֶחָד וְהַוָּלָד לְאַחֵר, הֲרֵי פְּחַת הַשּׁוּמָן שֶׁפָּחַת גּוּף הַפָּרָה לְבַעַל הַפָּרָה, וּפְחַת הַנֶּפַח \u0010y6\u0011 \u0005דְּהַיְנוּ מַה שֶּׁהָיְתָה נִרְאֵית תְּחִלָּה יוֹתֵר גְּדוֹלָה (טוּר)\u0006 חוֹלְקִין אוֹתוֹ בַּעַל הַפָּרָה עִם בַּעַל הַוָּלָד, וְהַנֶּפֶל שֶׁל בַּעַל הַוָּלָד:",["\u0003ממנה ומולד'. \u0004 פי' אע\"פ שהי' תם ותם אינו משלם אלא מגופו טור:","\u0003אפי' ליתא לפרה \u0004 פי' וה\"א דאין כאן צד חיוב אולד' אבל אי איתא לפרה מה לו למזיק לשלם מהפרה לחוד או גם מהולד דהא א\"צ לשלם אלא חצי נזק דהניזק גם קמ\"ל דמשתלם כל ח\"נ מהולד אפי' ליתא לפרה ול\"ת דלא משתלם מהולד אלא רביע מיהו גם בדאיתא לפרה איכא חידוש בדין זה כגון אם הפרה אינה שוה כשיעור ח\"נ דהניזק:","\u0003ואין הפרה לפנינו. \u0004 וה\"ה אם והיא לפנינו ואינה שוה דמי חצי נזק דהניזק וכמ\"ש אלא משום דמסתמ' שויא כדי דמי חצי נזק מש\"ה כ\"כ וכ\"כ הטור:","\u0003כגון שעומדת באגם כו' שמ\"ה אוקמי' ממונא אחזקת מרא קמא והמע\"ה:\u0004","\u0003ואפי' משבועה. \u0004 פי' היכא דהמזיק טוען ג\"כ ברי או שהניזק אומר ברי לי שאתה יודע השבע לי שאין אתה יודע דבכהאי גוונא בשור המועד צריך לישבע וכמ\"ש הטור והמחבר בסמוך בר\"ס ת' כאן דמיירי בשור תם אינו צריך לישבע והטעם מבואר בטור שכ' ז\"ל דלא רמינן שבועה אנתבע אלא כי היכי דלודי אבל הכא דקנסא הוא ואי מודה מפטר אכפירה נמי לא מחייב שבועה עכ\"ל וכן מבואר לעיל בטור ובדברי המחבר בסי' פ\"ז סכ\"ה ע\"ש גם המחבר רמזו בסמוך ר\"ס ת' ע\"ש:","\u0003מיהו אם תפס כו'. \u0004 כ\"כ הטור בשם הרא\"ש ולא כדעת הרמ\"ה דכתב דלא מהני תפיסה אפי' בלא עדים דכיון דקנסא הוא לא שייך ביה חיוב אלא בעדים:","\u0003דהיינו מה שהיתה נראה כו'. \u0004 כ\"כ בטור ע\"ש:"],["\u0003 פטור כו'. \u0004 כיון דהוי קנס כ\"כ הטור והיינו כשאומר לו הניזק אתה יודע דאל\"כ אפי' במועד פטור מטעם דלא ה\"ל לידע וכדלקמן רס\"ח וכ\"כ הסמ\"ע ס\"ק ה':","\u0003 ואפי' משבוע'. \u0004 ואף שידוע ונתחייב במקצת ע\"פ עדים שראו הנגיח' לא הוי על השאר מחויב שבועה ואינו יכול לישבע משלם בקנס כ\"כ התוס' ר\"פ שור שנגח הפרה ועוד כתבו שם ובנ\"י ובהגה' אשר\"י תירוץ אחר דלא ה\"ל לידע ע\"ש ומטעם הילך לא מיפטר דאף ע\"ג דכתבתי לעיל סי' פ\"ז ס\"א וסי' פ\"ח סעיף כ\"ד דהילך הוי בדבר שהוא בעין אפי' הוא בביתו של נפקד וכ\"כ הנ\"י גופי' בפ\"ק דמציעא היינו דוקא בדבר שהוא של התובע מיד לגמרי והלכך כל היכא דאיתי' ברשותא דמארי' איתי' משא\"כ בשור תם דצריך שומא א\"כ לאו הילך הוא וע' מ\"ש לקמן סי' ת' ס\"ג:","\u0003 מיהו אם תפס כו'. \u0004 כ\"כ הטור בשם הרא\"ש ולא כדעת הרמ\"ה דכתב דלא מהני תפיס' אפי' בלא עדים בקנס וכ\"כ הנ\"י ס\"פ המניח כהרמ\"ה ומשמע שם שהם דברי הרמ\"ה. והב\"ח הקשה דמדברי הרמ\"ה שהביא הרא\"ש ספ\"ק דב\"ק והטור לעיל ס\"ס שמ\"ט מבואר דבפלגא נזקא קנסא מהני תפיסה וצ\"ע עכ\"ל ולא דק דהתם מיירי כשיש לו עדים על הנזק דלא הי' פטור משום מודה בקנס וק\"ל: לשון הטור ולא נהירא לא\"א הרא\"ש ז\"ל כו' ולא מצאתי בהרא\"ש מבואר שחולק על הרמ\"ה בזה. מיהו בס\"פ המניח משמע שם מדבריו דלא כהרמ\"ה שכתב שם גבי שני תמין אם תפס משתלם כדקאמר מזיק אבל כדקאמר ניזק לא כיון שתפס בפני עדים עכ\"ל משמע אי תפס שלא בעדים משתלם כדקאמר ניזק משום מגו והרי הרא\"ש ס\"ל התם להדיא דסוגיא אזלא למ\"ד פלגא נזקא קנסא ע\"ש ואע\"ג דמודה בקנס פטור נרא' דכיון דהיכא דאית ליה מגו נאמן בכל דוכתי אלמ' דתפיסתו בלא עדים חשיב ליה כאלו הביא עדים שכדבריו כן הוא דאל\"כ איך יהא נאמן וא\"כ זה שמוד' ה\"ל כמוד' אחר שבאו עדים ולפ\"ז גם להרא\"ש וטור לא מהני כשתפס ויש לו מגו אלא כשתפס קודם שהוד' וה\"ה בזמן הזה דליכא מומחין ולא חשוב' הודאה וכמ\"ש הרמב\"ן והרא\"ש ספ\"ק דב\"ק והטור לעיל ס\"ס א' א\"כ בכל ענין מהני תפיסה בקנס אם יש מגו כן נ\"ל ודו\"ק:"],"פָּרָה מְעֻבֶּרֶת שֶׁהִזִּיקָה, \u0010g0\u0011 גוֹבֶה חֲצִי נֶזֶק \u0010y0\u0011 מִמֶּנָּה וּמִוְּלָדָהּ, מִפְּנֵי שֶׁהוּא כְּגוּפָהּ. \u0010y1\u0011 \u0010g1\u0011 \u0010t0\u0011 אֲפִלּוּ לֵיתָא לַפָּרָה, מִשְׁתַּלֵּם כָּל חֲצִי נֶזֶק מֵהַוָּלָד, מִפְּנֵי \u0010g2\u0011 שֶׁהוּא כְּגוּפָהּ. אֲבָל תַּרְנְגוֹלֶת שֶׁהִזִּיקָה אֵינוֹ גוֹבֶה מִבֵּיצָתָהּ, מִפְּנֵי שֶׁהַבֵּיצָה אֵינָהּ מִגּוּפָהּ, \u0010g3\u0011 אֶלָּא מֻבְדֶּלֶת וּמֻפְרֶשֶׁת. \u0005הַגָּה: \u0010r0\u0011 מִיהוּ, אִם הַבֵּיצָה אֲגֻדָּה עֲדַיִן בְּגוּפָהּ, יֵשׁ אוֹמְרִים דְּגוֹבִין מִמֶּנָּה (הַמַּגִּיד פ\"ט \u0010g4\u0011 דְנ\"מ)\u0006. \u0010g5\u0011\nפָּרָה מְעֻבֶּרֶת שֶׁנָּגְחָה, וְנִמְצָא עֻבָּרָה בְּצִדָּהּ, וְאֵין יָדוּעַ אִם קֹדֶם נְגִיחָה יָלְדָה, וְאָז אֵין לְהִשְׁתַּלֵּם מֵהַוָּלָד, אוֹ לְאַחַר נְגִיחָה יָלְדָה וְיֵשׁ לְהִשְׁתַּלֵּם מֵהַוָּלָד, \u0010y2\u0011 וְאֵין הַפָּרָה \u0010t1\u0011 לְפָנֵינוּ, הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה וְלֹא יִטֹּל מֵהַוָּלָד. \u0010g6\u0011\nוְכֵן שׁוֹר שֶׁנָּגַח אֶת הַפָּרָה וְנִמְצָא עֻבָּרָה מֵת בְּצִדָּהּ, וְאֵין יָדוּעַ אִם מֵחֲמַת נְגִיחָה הִפִּילָה אוֹ אִם הִפִּילָה קֹדֶם, הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו \u0010r1\u0011 הָרְאָיָה. וַאֲפִלּוּ שֶׁהַנִּזָּק טוֹעֵן בָּרִי, וְהַמַּזִּיק טוֹעֵן שֶׁמָּא, \u0010g7\u0011 \u0010r2\u0011 וַאֲפִלּוּ שֶׁאֵין הַמַּזִּיק \u0010y3\u0011 \u0010t2\u0011 מֻחְזָק, כְּגוֹן שֶׁעוֹמֶדֶת בָּאֲגַם, \u0010c0\u0011 פָּטוּר \u0010y4\u0011 \u0010c1\u0011 \u0010t3\u0011 \u0010r3\u0011 וַאֲפִלּוּ מִשְּׁבוּעָה. \u0005הַגָּה: \u0010y5\u0011 \u0010c2\u0011 \u0010r4\u0011 מִיהוּ, אִם \u0010t4\u0011 תָּפַס הַנִּזָּק, נֶאֱמָן, אִם יֵשׁ לוֹ מִגּוֹ דְּלָא הָיוּ דְּבָרִים מֵעוֹלָם (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. \u0010g8\u0011\nנָגַח פָּרָה מְעֻבֶּרֶת וְהִפִּילָה, אֵין שָׁמִין פְּחַת פָּרָה בִּפְנֵי עַצְמָהּ וּפְחַת הַוָּלָד בִּפְנֵי עַצְמוֹ, אֶלָּא שָׁמִין כַּמָּה הָיְתָה הַפָּרָה שָׁוָה \u0010g9\u0011 כְּשֶׁהָיְתָה מְעֻבֶּרֶת וּבְרִיאָה, וְכַמָּה הִיא שָׁוָה עַכְשָׁיו הִיא וְהַנֶּפֶל שֶׁלָּהּ, וּמְשַׁלֵּם הַפְּחָת, אוֹ חֶצְיוֹ אִם הָיָה תָּם. \u0010g10\u0011\nהָיְתָה הַפָּרָה לְאֶחָד וְהַוָּלָד לְאַחֵר, \u0010g11\u0011 הֲרֵי פְּחַת הַשּׁוּמָן שֶׁפָּחַת גּוּף הַפָּרָה לְבַעַל \u0010g12\u0011 הַפָּרָה, וּפְחַת הַנֶּפַח \u0010y6\u0011 \u0010r5\u0011 \u0005דְּהַיְנוּ מַה שֶּׁהָיְתָה נִרְאֵית תְּחִלָּה יוֹתֵר גְּדוֹלָה (טוּר)\u0006 חוֹלְקִין אוֹתוֹ בַּעַל הַפָּרָה עִם בַּעַל הַוָּלָד, וְהַנֶּפֶל שֶׁל בַּעַל הַוָּלָד:",{"g":["א) ל' הטור וכ\"כ הרמב\"ם רפ\"ח מה' נזקי ממון מימרא דרבא בפ\"ה דב\"ק דף מז ע\"א","\u0003ב) שם בגמ' אבל אי פשיטא לן וכו'\u0004 ","ג) שם במימרא דרבא","ד) ל' הרמב\"ם שם","ה) בשם קצת מפרשים ואולי זה שכתב רבינו מובדלת ומפורשת (וכ\"כ התו' שם בד\"ה מ\"ט פירשא בעלמא וכו')","ו) שם סג ושם דף מו ע\"א אמתני' ממימרא דרב יהודה אמר שמואל זו דברי סומכוס וכו' אבל חכמים אומרים וכו' ופסקו הפוסקים כחכמים","\u0003ז) שם סד שם במשנה וכמימרא דר\"י וכו'\u0004 דחכמים פליגי וכחכמים ודלא כמתני' דסומכוס היא","ח) מבואר בפ\"ח דב\"מ דף ק ע\"א","ט) ל' הרמב\"ם שם דף ד מימרא דרבא שם בב\"ק דף מז ע\"א","י) כתב ה\"ה לימד שמה שפחתה היא אף בשומנה ופחתה בנפח מלבד נזק הולד כדין האמור בסמוך","כ) שם ד\"ה","ל) פשוט שם בגמ'","מ) כרב אחא בריה דרב איקא דאיפסקא הלכתא כותיה שם"],"t":["\u0003ליתא. \u0004 קמ\"ל בזה דל\"ת דלא משתלם מהולד אלא רביע מיהו גם בדאיתא לפרה איכא חידוש בדין זה כגון אם אין הפרה שוה כשיעור ח\"נ דהניזק. סמ\"ע:","\u0003לפנינו. \u0004 וה\"ה אם היא לפנינו ואינה שוה כדי חצי הנזק. שם:","\u0003מוחזק. \u0004 דמ\"מ מוקמינן ממונא אחזקת קמא והמע\"ה. שם:","\u0003משבועה. \u0004 כיון דהוי קנס כ\"כ הטור ע\"ש והיינו כשא\"ל הניזק אתה יודע דאל\"כ אפי' במועד פטור מטעם דלא ה\"ל לידע וכדלקמן ר\"ס ת' וע\"ל סי' פ\"ז סכ\"ה ואף שידוע ונתחייב במקצת ע\"פ עדים שראו הנגיחה לא הוי על השאר משואיל\"מ בקנס כמ\"ש התו' ר\"פ הפרה ועוד כתבו שם תירוץ אחר דלא ה\"ל לידע וכ\"כ בנ\"י ובהג\"א ע\"ש ומטעם הילך לא מיפטר דאע\"ג דכתבו בסי' פ\"ז ס\"א וסי' פ\"ח סכ\"ד דהילך הוי בדבר שהוא בעין אפילו הוא בבית הנפקד וכ\"כ הנ\"י בפ\"ק דב\"מ היינו דוקא בדבר שהוא של התובע מיד לגמרי והלכך כל היכא דאיתיה ברשותא דמריה איתיה משא\"כ בשור תם דצריך שומא א\"כ לאו הילך הוא וע\"ל סי' ק' ס\"ג. ש\"ך:","\u0003תפס. \u0004 כ\"כ הטור בשם הרא\"ש ולא כדעת הרמ\"ה דכתב דלא מהני תפיסה אפילו בלא עדים בקנס וכ\"כ הנ\"י ס\"פ המניח כהרמ\"ה והב\"ח הקשה דמדברי הרמ\"ה שהביא הרא\"ש ספ\"ק דב\"ק והטור ס\"ס ש\"ט מבואר דבפלגא נזקא קנסא מהני תפיסה וצ\"ע עכ\"ל ולא דק דהתם מיירי שיש לו עדים על הניזק דלא היה פטור משום מודה בקנס כ\"כ הש\"ך וכת' עוד דגם להרא\"ש והטור לא מהני כשתפס ויש לו מיגו אלא כשתפס קודם שהודה וה\"ה בזה\"ז דליכא מומחין ולא חשיבא הודאה וכמ\"ש הרמב\"ן והרא\"ש שם והטור בס\"ס א' א\"כ בכל ענין מהני תפיסה בקנס אם יש מיגו כן נ\"ל עכ\"ל:"],"r":["\u0003מיהו כו'. \u0004 ממ\"ש בחולין נח א' מ\"ט כיון דאגידה כו' ועתוס' בב\"ק שם ד\"ה מ\"ט כו' וערשב\"א וכ\"ה בר ירוחם להדיא ע\"ש:","\u0003ואפי' כו'. \u0004 גמ' שם:","\u0003ואפילו שאין כו'. \u0004 עתוס' ד\"ה שור שנגח כו' ועבה\"ג:","\u0003ואפילו משבועה. \u0004 עתוס' שם ד\"ה דאפילו. ועי\"ל דלמ\"ד כו' ועסי' פז סכ\"ו:","\u0003מיהו כו'. \u0004 עש\"ך ועס\"ס ת' ובש\"ך שם ס\"ק יד:","\u0003דהיינו כו'. \u0004 רש\"י:"]}],["שׁוֹר שֶׁהָיָה רוֹדֵף אַחַר שׁוֹר אַחֵר, וְהֻזַּק, זֶה אוֹמֵר: שׁוֹרְךָ הִזִּיק, וְזֶה אוֹמֵר: לֹא כִּי \u0010y0\u0011 אֶלָּא בַּסֶלַע לָקָה, הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו \u0010c0\u0011 הָרְאָיָה, אֲפִלּוּ נִזָּק טוֹעֵן בָּרִי וּמַזִּיק טוֹעֵן שֶׁמָּא. \u0010c1\u0011 וְאִם טָעַן הַנִּזָּק: אַתָּה יוֹדֵעַ שֶׁשּׁוֹרְךָ הִזִּיק, \u0010c2\u0011 נִשְׁבָּע הֶסֵת שֶׁאֵינוֹ יוֹדֵעַ. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּמוּעָד; אֲבָל בְּתָם, פָּטוּר אַף מֵהֶסֵת, שֶׁהֲרֵי אִם הוֹדָה הָיָה פָטוּר, \u0010y1\u0011 הוֹאִיל וְהוּא קְנָס.\nהָיוּ שְׁנַיִם רוֹדְפִים אַחַר אֶחָד, \u0010y2\u0011 וַהֲרֵי עֵדִים שֶׁאֶחָד מֵהֶם הִזִּיק, וְאֵינָם יוֹדְעִים אֵיזֶה מִשְּׁנֵיהֶם, זֶה אָמַר: שׁוֹרְךָ הִזִּיק, וְזֶה אָמַר: שׁוֹרְךָ הִזִּיק, שְׁנֵיהֶם פְּטוּרִים. וְאִם הָיוּ שֶׁל אִישׁ אֶחָד, חַיָּב לְשַׁלֵּם \u0010y3\u0011 מִגּוּף הַפָּחוּת שֶׁבִּשְׁנֵיהֶם. וְאִם הָיוּ מוּעָדִים, מְשַׁלֵּם נֶזֶק שָׁלֵם מִנְּכָסָיו. בַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁשְּׁנֵי הַשְּׁוָרִים עוֹמְדִים. אֲבָל אִם מֵת אֶחָד מֵהֶם אוֹ אָבַד, וְהָיָה אֶחָד מֵהֶם תָּם, אַף עַל פִּי שֶׁהֵם שֶׁל אִישׁ אֶחָד, פָּטוּר, שֶׁהֲרֵי אוֹמֵר לוֹ: \u0010y4\u0011 הָבֵא רְאָיָה שֶׁזֶּה הָעוֹמֵד הוּא שֶׁהִזִּיק וַאֲשַׁלֵּם לְךָ.\nהָיוּ שְׁנֵי הַשְּׁוָרִים הָרוֹדְפִים אֶחָד גָּדוֹל וְאֶחָד קָטָן, הַנִּזָּק אוֹמֵר: הַגָּדוֹל הִזִּיק, וְהַמַּזִּיק אוֹמֵר: קָטָן הִזִּיק; הָיָה אֶחָד תָּם וְאֶחָד מוּעָד, הַנִּזָּק אוֹמֵר: מוּעָד הִזִּיק, וְהַמַּזִּיק אוֹמֵר: תָּם הִזִּיק; \u0010y5\u0011 הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. \u0005(לֹא הָיָה שָׁם רְאָיָה בְּרוּרָה שֶׁזֶּה הִזִּיק, אֶלָּא עֵדִים מְעִידִים שֶׁאֶחָד מִשְּׁנֵי אֵלּוּ הִזִּיק, מְשַׁלֵּם הַמַּזִּיק כְּמוֹ שֶׁאוֹמֵר)\u0006. \u0010c3\u0011 וְאִם טָעַן הַנִּזָּק: אַתָּה יוֹדֵעַ וַדַּאי שֶׁזֶּה הִזִּיק בְּפָנֶיךָ, הֲרֵי הַמַּזִּיק \u0010c4\u0011 מְשַׁלֵּם מַה שֶּׁהוֹדָה, \u0010y6\u0011 \u0010c5\u0011 וְנִשְׁבַּע \u0010c6\u0011 שְׁבוּעַת הַתּוֹרָה עַל הַשְּׁאָר. \u0005הַגָּה: \u0010c7\u0011 \u0010c8\u0011 וְיֵשׁ אוֹמְרִים דְּאֵין כָּאן שְׁבוּעָה כְלָל, דְּהָוֵי לֵהּ כִּטְעָנוֹ חִטִּין וְהוֹדָה לוֹ בִּשְׂעוֹרִים דְּפָטוּר אַף בַּמֶּה שֶׁהוֹדָה, וַאֲפִלּוּ תָפַס מַפְקִינָן מִנֵּהּ (טוּר ס\"ב בְּשֵׁם הָרֹא\"שׁ)\u0006. וְדַוְקָא טָעַן הַנִּזָּק בָּרִי, אֲבָל אִם טוֹעֵן שֶׁמָּא, מְשַׁלֵּם הַמַּזִּיק כְּמוֹ שֶׁהוּא טוֹעֵן \u0005(שָׁם)\u0006.\nהָיוּ הַנִּזָּקִים שְׁנַיִם, אֶחָד גָּדוֹל וְאֶחָד קָטָן, וְהַמַּזִיקִים \u0005(ב')\u0006 אֶחָד גָּדוֹל וְאֶחָד קָטָן, הַנִּזָּק אוֹמֵר: גָּדוֹל הִזִּיק אֶת הַגָּדוֹל וְקָטָן אֶת הַקָּטָן, וְהַמַּזִּיק אוֹמֵר: לֹא כִּי אֶלָּא הַקָּטָן הִזִּיק אֶת הַגָּדוֹל וְגָדוֹל הִזִּיק אֶת הַקָּטָן, אוֹ שֶׁהָיָה אֶחָד תָּם וְאֶחָד מוּעָד, הַנִּזָּק אוֹמֵר: מוּעָד הִזִּיק אֶת הַגָּדוֹל וְתָם אֶת הַקָּטָן, וְהַמַּזִּיק אוֹמֵר: תָּם הִזִּיק אֶת הַגָּדוֹל וּמוּעָד אֶת הַקָּטָן, הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה, וְאִם לֹא הֵבִיא רְאָיָה \u0010c9\u0011 בְּרוּרָה פָּטוּר הַמַּזִּיק, \u0010c10\u0011 שֶׁהֲרֵי \u0005(זֶה)\u0006 כִּטְעָנוֹ לוֹ חִטִּים וְהוֹדָה לוֹ בִּשְׂעוֹרִים, שֶׁהוּא נִשְׁבָּע הֶסֵת וּפָטוּר אַף מִדְּמֵי שְׂעוֹרִים. \u0010c11\u0011 \u0005זוֹ הִיא סְבָרַת יֵשׁ אוֹמְרִים שֶׁכָּתַבְתִּי בְּסָמוּךְ. אֲבָל יֵשׁ מְחַלְּקִים דְּאִם הָיוּ כָּאן עֵדִים שֶׁאוֹמְרִים אֶחָד מֵהֶן הִזִּיק אֶלָּא שֶׁאֵינָם יוֹדְעִין אֵיזֶה הוּא, מְשַׁלֵּם כְּמוֹ שֶׁאָמַר מַזִּיק, וְלֹא מִקְרֵי כְּהַאי גַּוְנָא טְעָנוֹ חִטִּין וְהוֹדָה לוֹ בִּשְׂעוֹרִים (הַמַּגִּיד פ\"ט דב\"מ)\u0006. וְכִסְבָרָא הָרִאשׁוֹנָה שֶׁכָּתַב הַמְחַבֵּר שֶׁמִּקְּרֵי הוֹדָאָה וּכְמוֹ שֶׁנִּתְבָּאֵר. \u0010y7\u0011 \u0010c12\u0011 וְאִם תָּפַס \u0010y8\u0011 הַנִּזָּק, הֲרֵי זֶה מְשַׁלֵּם לַקָּטָן מֵהַגָּדוֹל וְלַגָּדוֹל מֵהַקָּטָן כְּמוֹ שֶׁהוֹדָה הַמַּזִּיק. וַאֲפִלּוּ תָּפַס בְּעֵדִים, נוֹטֵל כְּמוֹ שֶׁאָמַר הַמַּזִּיק \u0010c13\u0011 \u0010c14\u0011 \u0010c15\u0011 \u0010c16\u0011 \u0010c17\u0011 אֲבָל אֵינוֹ נוֹטֵל כְּפִי דְבָרָיו. וְדַוְקָא תָּפַס קֹדֶם שֶׁבָּא לְבֵית דִּין, אֲבָל לְאַחַר שֶׁבָּא לְבֵית דִּין לֹא מְהַנְּיָא לֵהּ תְּפִיסָה, אֲפִלּוּ לִטֹּל כְּדִבְרֵי הַמַּזִּיק:",["\u0003אלא בסלע לקה. \u0004 ואע\"פ שנלקה ע\"י רדיפת שורו אחריו לא הוי אלא גרמא בניזקין:","\u0003הואיל והוא קנס. \u0004 כבר נתבאר טעמו בס\"ס שצ\"ט ס\"ג:","\u0003והרי עדים שא' מהן הזיק. \u0004 רצה לומר ואינן יכולין לטעון שבסלע נלקה מ\"ה אם היו שניהן של אחד מהן חייב וכדמסיק ובאם היו של שנים פטורים שניהן אף שיש עדים שא' מהן ודאי נגחו וק\"ל:","\u0003מגוף הפחות שבשניהן. \u0004 אם אינו שוה כדי דמי ח\"נ מפסיד הניזק:","\u0003הבא ראי' שזה העומד כו' \u0004 נראה דאם זה העומד הוא תם והמועד מת או נאבד דגובה ח\"נ מזה התם העומד ממ\"נ דאם הוא נגחו הרי בדין גובה מגוף המזיק ח\"נ ואם זה שמת נגחו הרי הי' מועד וחייבים בעליו לשלם מנכסיו. וזה שור תם העומד בכלל נכסיו דבעל השור המועד שמת הוא אלא איירי המחבר שזה העומד הוא מועד א\"נ אינם ניכרים איזה מועד ואיזה תם וק\"ל:","\u0003המע\"ה. \u0004 הרמב\"ם סיים שם וכתב ז\"ל לא הי' שם ראי' ברור' שזה הזיק אלא עדים מעידים שא' משנים אלו היזק משלם המזיק כמו שאומר וכ\"כ הטור בשמו (וכן צריכים להגיה בדברי המחבר) וכתב הטור עליו וז\"ל ובודאי הוא כדבריו אם אין הניזק מברר דבריו לומר ודאי זה שהזיקני אבל אם טוען ברי לי שזה הזיקני אז הוא מודה שהאחר לא הזיקו לפיכך אם אין לו עדים אינו נוטל כלום דמזה שאומר שהזיקו אינו נוטל שהרי המזיק מכחישו גם מהשני נמי אינו נוטל שהרי הודה לו שאינו הזיקו ודומה לטועני חטין והודה לו בשעורים שפטור אף מדמי שעורים אבל יראה לי מדברי הרמב\"ם שס\"ל שנוטל כדברי המזיק אף שבירר הניזק דבריו וזהו תימה דה\"ל כטוענו חטים והודה לו בשעורים ואפילו תפס כתב א\"א הרא\"ש ז\"ל דל\"מ תפיסה עכ\"ל ובזה מבוארין דברי המחבר ודברי מור\"ם ז\"ל שהמחבר כ' כדעת הרמב\"ם ומור\"ם כ' לדברי הרא\"ש והטור לי\"א. ומ\"ש ודוקא טען הניזק ברי כו' הוא מ\"ש הטור ובודאי הוא כדבריו אם לא בירר הניזק דבריו כו' כנ\"ל. אלא שצ\"ע למה כתב מור\"ם די\"א דאין כאן שבוע' כלל כו' דהל\"ל דאין כאן תשלומין כלל כל' הטור הנ\"ל. גם קשה דלא הל\"ל דאין כאן שבוע' כלל דהא אפילו בטוענו בחטין והודה לו בשעורים נהי דאין עליו חיוב תשלומין ולא ש\"ד דמודה מקצת מ\"מ שבועת היסת צריך לישבע וכמ\"ש סי' פ\"ח ומטעם דהרי טענו חוטין והודה לו שעורים ה\"ל כאלו אמר איני חייב לך חיטים ובטענה וכפירה לא נפטר משבועת היסת כמ\"ש הרמב\"ם והמחב' עצמו כאן בסס\"ד וצ\"ל בכלל דכתב מור\"ם ר\"ל לא חיוב תשלומין ולא ש\"ד דמחייב הרמב\"ם להנתבע בתרווייהו ע\"ז כ' די\"א דאפי' ש\"ד אין עליו וכ\"ש תשלומין מה שהודה אלא פטור מתרווייהו כלל ומשבועת היסת לא איירי כאן ועפ\"ר שם כתבתי ל' המ\"מ שמיישב לדברי הרמב\"ם מהשגת הטור וכתב דס\"ל להרמב\"ם דלא הוה כטוענו חיטים והודה לו בשעורין כיון שיש עכ\"פ עדים שאחד משוריו נגחו ויש לניזק ממ\"נ ממון אצל בעל השורים המזיק משא\"כ בטוענו חטים כו' דמיירי דאין שם עדים כלל ומה\"נ כתב דנשבע שבועה דאורייתא על השאר דהא ה\"ל מודה מקצת על הממון שח\"ל ע\"פ העדים עכ\"פ (ואפשר דהרא\"ש והטור לא סבירא להו האי חילוק דעדים בענין זה כיון דהעדים אינן מבררים דבריהם איזה נגח לזה ואיזה לזה) ושם הוכיח המ\"מ חילוק זה דאיירי הרמב\"ם כאן דוקא ביש בה עדים שא' מהן הזיק דאל\"כ קשיין דברי הרמב\"ם אהדדי דכאן כתב דצריך לשלם מה שהוד' ובבבא שאחריו כתב שם הרמב\"ם בעצמו בדין ט' י' באם לא הי' שם ראיה דפטור לגמרי מטעם דה\"ל כטוענו חטים כו' וכמ\"ש המחבר אותן דברים עצמן אחר זה מיד בס\"ד אלא ודאי מ\"ש הרמב\"ם ברישא דמשלם מה שהודה מיירי ביש עדים ובסיפא מיירי דאין כאן עדים כלל ואף שכתב הרמב\"ם בסיפא ז\"ל ואם לא הביא ראיה ברורה כו' ומשמע דאיירי דליכא ראי' ברורה שהגדול הזיק אבל יש ראיה שא' מהן הזיק ואפ\"ה פטור הא כתב המ\"מ שם שצ\"ל שאין כוונת הרמב\"ם לזה במ\"ש ראיה ברורה דא\"כ יסתרו סוף דבריו לראשיתן וכמ\"ש ע\"ש. וכ' עוד שם המ\"מ דהא דמיירי הרמב\"ם בסיפא בלא עדים וברישא בעדים ה\"ט דבכל א' כ' רבותא דברישא קמ\"ל דאע\"ג דלא ניזק אלא שור א' וטענתו רק על שור אחד אפ\"ה חייב לשלם כשיש עדים ובסיפא קמ\"ל דאע\"פ שטענתו על שניהן ששניהן נגחו לשני שוורים אפ\"ה פטור כשאין עדים וכ\"ש ברישא שאין תביעה אלא על א' מהן עכ\"ל המ\"מ בשינוי ל' קצת לתוס' ביאור. וזהו כוונת המחבר שהעתיק רישא וסיפא דדברי הרמב\"ם כצורתן זא\"ז בס\"ג ובס\"ד ומהתימא על מור\"ם שכ' על מ\"ש המחבר בס\"ד ז\"ל זהו סברת י\"א כו' וז\"א דהא מ\"ש המחבר שם בס\"ד הן דברי הרמב\"ם עצמן בעל הסברא החולק עם הי\"א וכנ\"ל בס\"ג וצריכין לדחוק וליישב דהי' קשה למור\"ם על דברי המחבר שהעתיק דברי הרמב\"ם ג\"כ מ\"ש ואם לא הביא ראיה ברורה כו' דמשמע דמיירי דאף אם יש קצת ראי' והיינו דיש עדים שהזיק א' מהן אלא שאינן יודעין איזהו. ע\"ז מתמה וכ' הלא זו היא דעת י\"א הנ\"ל ולא ה\"ל להמחב' לסתום דבריו ומסיק אבל יש מחלקים ור\"ל דס\"ל לאותן י\"א דהו' המ\"מ הנ\"ל דאין שום דקדוק במ\"ש ראי' ברורה אלא מיירי באין עדים כלל דאם היו כאן עדים כו' ושכן הוא דעת המחב' מ\"ה העתיקו סתם ודוק:","\u0003ונשבע שבוע' התורה על השאר. \u0004 גם הטור כתב זה בשם הרמב\"ם אחר דבריו ודברי הרא\"ש הנ\"ל וכתב עליו בשם הראב\"ד דלא כ\"כ הרמב\"ם אלא כשאחד מהן תם ואחד מהן מועד דכיון דאחד מהן מועד תביעת הניזק הוא על נכסי המזיק נמצא דגם שור תם בכלל תביעת נכסיו הן מ\"ה מחשב כמודה מקצת אבל בא' גדול ואחד קטן ושניהן תמין שהחיוב היא על גוף השוורים כל אחד מחשב תביעה בפני עצמו ואין כאן מודה מקצת ולדעת א\"א הרא\"ש ז\"לאין כאן שבועה כלל (פי' אפי' כשאחד הוא תם ואחד מועד) דה\"ל כטוענו חטין כו' עכ\"ל הטור ע\"ש:","\u0003ואם תפס הניזק כו'. \u0004 דכיון דטען על שניהן ששניהן נגחוהו וגם המזיק מודה בזה אף שאין לו עדים בזה איזהו נגח לזה ואיזהו לזה מהני תפיסתו לכ\"ע וכן הוא בגמ' ועד\"ר:","\u0003הרי זה משלם לקטן מהגדול כו'. \u0004 והיינו דוקא כשתפס בעדים וכדמסיק דאין מיגו להניזק אבל אם תפס בלא עדים גובה להגדול מהגדול כמו שאומר הניזק וכמ\"ש מור\"ם בסי' שצ\"ט בס\"ג והוא כדעת הרא\"ש והטור שכ\"כ הטור שם בשמו וגם כאן כתבו ז\"ל אבל אינו נוטל כדי דבריו כיון שתפס בעדים עכ\"ל דמוכח מזה הא תפס בלא עדים נוטל כדבריו והכי הוא הצעת דברי הטור ודברי המחבר ואם תפס הניזק כו' מהני תפיסתו לשלם כו' ואין בו דין טענו בחיטין כו' ול\"ת דזהו דוקא בתפס בלא עדים אלא אף אם תפס בעדים הדין כן ואח\"כ מסיק וכתב מיהו בהא דתפס בעדים אינו נוטל כפי דבריו וק\"ל:"],["\u0003 אפי' ניזק טוען ברי ומזיק שמא \u0004 משמע מדברי הרמב\"ם והט\"ו דאפי' במועד דינ' הכי ומהרש\"ל פרק המניח סי' ל\"ג כתב דבמועד שרדף חייב כשניזק טוען ברי ומזיק שמא מאחר דרב הונא ורב יודא מחייבים בברי ושמא ואין דבריו נכונים אלא כיון דקי\"ל דלא כרב הונא ורב יודא אלא מוקמינן ממונא בחזקת מאריה א\"כ בכל ענין המע\"ה:","\u0003 ואם טען הניזק אתה יודע כו'. \u0004 אבל כשאינו טוען כן א\"צ לישבע היסת שהרי הניזק עצמו מודה שלא היה שם וא\"כ ודאי אין הניזק [המזיק] יודע ועיין מ\"ש לעיל סי' ע\"ב סי\"ב ס\"ק נ\"א יסי' צ\"ג סעיף י\"ג:","\u0003 נשבע היסת שאינו כו'. \u0004 כתב מהרש\"ל שם והא דאינו פטור מהיסת במגו דיכול לטעון להד\"ם דמאחר שטען זה ברי כנגדו הוי כמגו במקו' עדים דהא רב הונא ורב יהודא מחייבי' בברי ושמא כמו בעדים אף דלית הלכתא כותייהו מ\"מ לענין מגו הוי כעדים עכ\"ל ודבריו תמוהים ולחנם דחק דמאי מגו איכא הא אי טען להד\"מ נמי היה צריך לישבע היסת:","\u0003 ואם טען הניזק אתה יודע ודאי כו'. \u0004 ואע\"ג דבעלמא ס\"ל להרמב\"ם והמחבר דאע\"ג שאינו טוען אתה יודע הוי מחויב שבוע' וכמ\"ש לעיל סי' ע\"ב סעיף י\"ב ס\"ק נ\"א שאני התם דיכול להיות שיודע אבל הכא אם אינו טוען אתה יודע ודאי אינו יודע שהרי המזיק לא היה שם וכיון שהניזק בעצמו מודה שהמזיק לא היה שם לא שייך שבוע' כלל וכמ\"ש בסי' ע\"ב ס\"ק נ\"א שם ע\"ש ודו\"ק:","\u0003 משלם מהשהודה ונשבע שבועת התורה על השאר \u0004 כ\"כ הרמב\"ם וצ\"ע דהא טוענו מועד ונתחייב בתם ומין אחר הוא ובמ\"ש ה\"ה והטור דכשתובעו על המועד גם שור תם בכלל נכסיו עדיין לא נתקררה דעתי דאטו מי שיתבע את אחד שהלוה לו מנה ויודה לו בכלי שוה נ' או יתחייב לו כלי שוה נ' ע\"פ עדים יתחייב ש\"ד על השאר הא ודאי פטור כיון דמין אחר הוא וכן מוכח להדיא מדברי הנ\"י ס\"פ המניח והמחבר גופיה לעיל סי' פ\"ח סעיף י\"ג וא\"כ הוא הדין הכא וכן מוכח בש\"ס ס\"פ המניח מדפריך מיניה לרבה בר נתן אלמא דמין אחר הוא כמו חטים ושעורים ונראה דאין ה\"נ בתובעו ממון ק' ומודה לו בכלי שוה נ' דהוי מודה מקצת דומי' דתובעו דינר זהו' דשוה קאמר ובכל מה שיודה לו חשיב ממין הטענ' וכדלעיל סי' פ\"ח סעיף ט' והא דפריך בש\"ס לרבה בר נתן היינו כיון דלא הודה לו ממש מה שתבעו מצי למימר משטה ודחויי הוי קמדחינא לך תדע דהא בהיו הנזקין שנים והמזיקין שנים תמין דודאי חשיב הודאה ממין הטענ' דהא תובע שניהם ואפ\"ה פריך מיניה לרבה בר נתן אלא ודאי כמ\"ש. ולפי זה מה שכ' הנ\"י ס\"פ המניח והמחבר לעיל סי' פ\"ח סי\"ג מיירי כשטוען משטה הייתי דאלו עומד בהודאתו הוי מודה מקצת ממש וחייב שבועה דאורייתא. ומ\"מ מה דאיתא בש\"ס ופוסקים והט\"ו לעיל סי' פ\"ח סעיף ט' בתובעו בדינר זהו' בכל מה שיודה לו חשיב ממין הטענ' ומשמע דהוי הודא' גמור' ואינו יכול לחזור בו לא דמי לכאן דהתם כיון שזה שוה קאמר וזה כל מה שיודה לו בכלל הוא ובכל ענין חייב לשלם לו כל מה שיודה אפי' נאבד זה שמוד' א\"כ הוי ממש ממין הטענ' ולאו דחויי הוא ואינו יכול לחזור אבל כאן שמוד' לו בתם נהי דהתם הוא בכלל נכסיו מ\"מ כיון שמוד' לו דבר שאינו משתלם אלא מגופו ואילו נאבד אינו חייב לו ש\"מ דמשטה הוא בו ויכול לחזור בו והיינו הך שכתב הנ\"י והמחבר לעיל סי' פ\"ח סי\"ג דהיכא דהוד' לו כלי שאינו משתלם אלא מגופו פטור אלא דהיכא דהוא עומד בהודאתו או איכא עדים חייב ש\"ד וכדכתבו הרמב\"ם והראב\"ד וה\"ה והט\"ו כאן כן נ\"ל ודוק: שוב ראיתי בספר לחם משנה ספ\"ט מה' נזקי ממון כ' וז\"ל ואיכא לאתמוהי על הראב\"ד אם כן כיון דחשיב ממין הטענ' מה שמודה בתם א\"כ מה הקשו בסוף המניח תנן היה אחד תם ואחד מועד הניזק אומ' מועד הזיק את הגדול כו' הא לא מייתי ראיה שקיל כדקאמר מזיק הא חטים ושעורים נינהו והא לא דמי לחטים ושעורים דהודא' בתם הוי ממין הטענ' לדעת הראב\"ד ז\"ל ובשלמא לדברי רבינו ז\"ל איכא למימר דלא קאמר רבינו ז\"ל דהוי מחויב שבועת התורה אלא משום דאיכא עדים שנגח א' מהם ומתניתין איירי דליכא עדים ומשום הכי דמי לחטין ושעורים ואע\"ג דגם עליו קשה אמאי לא מוקי הש\"ס מתניתין בדאיכא עדים דומיא דרישא כדכתיבנא לעיל מ\"מ להראב\"ד ז\"ל קשה יותר שהוא מפרש דבמתני' אע\"ג דליכא עדים חשיב תם ממין הטענ' דמועד ואלו היה טוען מזיק ברי היה נשבע א\"כ לדידי' לא פריך הש\"ס כלל כדכתיבנא וצ\"ע עכ\"ל ואין דבריו נכונים בעיני דאם איתא דמוכח בש\"ס דתם לא חשיב ממין הטענה דמועד אם כן גם על הרמב\"ם תקשי אמאי חייב שבועת התורה אטו מי שיתבע את חברו במאה חביות חטין וחברו כופר ומביא התובע עדים שחייב לו נ' חביות שעורים היתחייב שבועת התורה על השאר הא פשיטא כיון דאין החיוב ממין הטענה מה לי שנתחייב במקצת על פי הודאתו או על פי עדים (וגם על דברי הרב המגיד הקשתי לקמן בזה ע\"ש) ועוד דאף אם תאמר דתם לא חשיב ממין הטענה דמועד מ\"מ תיקשי מאי פריך בתר הכי מהיו הניקין שנים והמזיקין ב' לרבה בר נתן דהא התם ודאי מין הטענה ממש הוא שהתובע רוצה כל השני תמים שהזיקו והנתבע מודה לו הקטן שהזיק ובמקצת גדול שהזיק אלא ודאי כמ\"ש דאף דהוי הודאה ממין הטענה פריך שפיר כיון דטעמא דרבה בר נתן הוא משום דכיון דלא הודה לו ממש כמו שתבעו יכול לטעון משטה הייתי בך א\"כ ה\"ה במתניתין כיון דלא הודה לו ממש אמאי שקיל כדקאמ' מזיק הא יכול לומר משטה הייתי בך ויש ראיה לזה ממ\"ש התוס' ס\"פ המניח ד\"ה לימא תיהוי תיובתא כו' והגהת מיי' פ\"ג מה' טוען דרבה בר נתן קאמ' מילתיה אפי' לרבן גמליאל דחייב שבועה בטענו חטים והודה לו בשעורים מ\"מ פטור לשלם השעורים ע\"ש. ודוק ותראה שכל זה ברור וע' מ\"ש לעיל סי' פ\"ח סי\"ב עוד מזה באריכות:","\u0003 ונשבע שבועת התורה כו' \u0004 כ' הטו' בשם הראב\"ד דלא כ' הרמב\"ם כן אלא כשא' מהן תם וא' מהן מועד דכיון דא' מהן מועד תביעת הניזק הוא על נכסי המזיק נמצא דגם שור תם בכלל נכסיו הן מ\"ה מחשב כמודה מקצת אבל בא' גדול וא' קטן ושניהן תמין שהחיוב הוא על גוף השוורים כל א' מחשב תביעה בפ\"ע ואין כאן מודה מקצת עכ\"ל סמ\"ע ס\"ק ז' ובאמת כן פי' הטור דברי הראב\"ד וכ\"כ ה\"ה בדעת הראב\"ד (וכ\"כ מהרש\"ל ס\"פ המניח בפי' דברי הראב\"ד דר\"ל דאי בשניהם תמים כיון דשני מינים הם ה\"ל כטענו חטים והודה לו בשעורים וא\"צ לישבע רק היסת וכ\"כ הב\"ח) אבל לפע\"ד דברי הטור והרב המגיד והנמשכים אחריהם תמוהים דנ\"ל שלא נתכוין הראב\"ד לזה אלא מ\"ש הראב\"ד אתם ומועד קאי ר\"ל דאי בשני תמין לא שייכא שבועה כלל משום מודה בקנס פטור ויותר תמיה לי על מה שמסיים הרב המגיד וז\"ל ויש לחלק שאפי' כששניהם תמים כיון שיש שם עדים חייב שבועת התורה וצ\"ע עכ\"ל ומביאו ב\"י דהאיך אפשר לחייב שום שבועה כלל דהא קנס הוא וכמ\"ש הרמב\"ם והט\"ו לעיל ר\"ס זה וליכא למימר דשאני הכא כיון דאיכא עדים דהא העדים אין מעידים רק על א' מהן והשאר אינם יודעים והכי מוכח נמי להדיא בתוס' ר\"פ שור שנגח הפרה דאפי' איכא עדים כיון שאין יודעים מהשאר ליכא שבועה כיון דאם היה מודה בקנס הי' פטור והוא פשוט וא\"כ דברי הרב המגיד וכן דברי הטור והנמשכים אחריו צ\"ע:","ועוד קשה לי על הרב המגיד כיון דבשני תמין לא חשיב ממין הטענה א\"כ מה בכך שיש עדים לענין שבועה דאוריית' וכי מי שתובע את חברו בק' חביות חטים וחבירו כופר והתובע מביא עדים שחייב לו נ' שעורים וכי יוכלו עדים לחייב ש\"ד בזה על השאר אלא ודאי מ\"ש הרמב\"ם עדים היינו משום דאל\"כ הי' יכול לחזור מהודאתו כמו בטענו חטים והודה לו בשעורים דפטור אף משעורים דהודאתו לאו הודאה היא וכמ\"ש לעיל ואפשר שלכך כתב הרב המגיד בסוף דבריו וצ\"ע כלומר דצ\"ע אם יש לחלק בין הודה לעדים בזה אבל לפע\"ד אין כאן צ\"ע והדבר ברור כמ\"ש ודוק:","\u0003 שבועת התורה על השאר. \u0004 ואע\"ג דהתם הוא בעין והעליתי לעיל סי' פ\"ז ס\"א וסי' פ\"ח סכ\"ד דדבר שהוא בעין ה\"ל הילך אפי' הוא בביתו של הנתבע היינו היכא שהוא של התובע מיד כגון בפקדון וכה\"ג דכל היכא דאיתא ברשותי' דמארי איתי' משא\"כ הכא כיון דצריך שומא לא ה\"ל הילך והכי מוכח בתוס' ונ\"י ר\"פ שור שנגח הפרה וכמ\"ש לעיל סימן שצ\"ט ס\"ג וע\"ש:","\u0003 וי\"א כו'. \u0004 ולעיל סי' פ\"ח סעיף י\"ב הוכחתי דלא כהי\"א בזה אלא דהיכא דאיכא עדים משלם הפחות שבשניהם וכן תפיסה מהני ליטול כדקאמר מזיק אפי' ליכא עדים וע\"ש:","\u0003 דאין כאן שבועה כלל כו'. \u0004 כלומר אין כאן תשלומין ושבועה כלל דהוה ליה כו' וכ' הסמ\"ע ס\"ק ז' דלדעת הרא\"ש אין כאן שבועה כלל אפי' כשא' הוא תם ואחד הוא מועד והב\"ח השיג עליו וכתב דדוקא בשני תמין ס\"ל להרא\"ש דאפי' היסת א\"צ אבל בתם ומועד מודה דנשבע ש\"ד עד כאן ולא דק דהא כיון דס\"ל להרא\"ש דאפי' יש לו עדים על הנגיחה פטור כיון דהוי כהודה והודאת בע\"ד כק' עדים א\"כ אפי' בתם ומועד פטור מש\"ד ומתשלומין וגם מה שכ' הב\"ח דלהרא\"ש אפי' היסת אין צריך הוא תמוה דלמה לא ישבע היסת לפטור עצמו מתביעת הניזק שאומר גדול הזיק לסברתם שלא הרגישו במודה בקנס פטור ודו\"ק:","\u0003 פטור המזיק שהרי כו' \u0004 ומשמע מדברי הרמב\"ם והמחבר דאפי' בבבא דמועד הזיק את הקטן אם אין עדים על הנגיח' פטור לגמרי (וכן משמע בטור) אבל הנ\"י ס\"פ המניח כ' וז\"ל ובבא דאמר מועד היזק את הקטן אפי' בדליכא סהדי משלם דמועד משלם נזק שלם מן העליה וממונא הוא הילכך משלם ע\"פ עצמו ואי תימא ואפי' כי מודה הודאה גמור' אמאי חייב והלא טענו חטים והוד' לו בשעורים היא שהניזק טוען נזקי גדול ומזיק מודה לו בנזקי קטן וי\"ל דליתא דכיון דניזק טוענו נזקי גדול מן העלי' ומזיק מודה לו בנזקי קטן מן העלי' ה\"ל כטוענו כסות (נ\"ל שצ\"ל דמי) דעבד גדול והלה מודה לו בכסות (בדמי) עבד קטן כדאיתא פרק השואל וכ\"כ הרמ\"ה עכ\"ל ובאמת משמע כן בש\"ס פ' השואל (דף ק' ע\"א) ועמ\"ש לעיל סימן ה' [צ\"ה] סעיף ג' ודוחק לומר דהתם מיירי כשאינו טוען משטה רק עומד בהודאתו דהא כי היכא דפריך הש\"ס בסוף פרק המניח ממתני' אמאי שקיל כדקאמר מזיק הא יכול לחזור בו ה\"ל לאקשויי התם אמאי חייב הא יכול לחזור בו ועוד דהא מוכח התם בפרק השואל דבכה\"ג הוי הודא' ממין הטענ' אבל נראה לי דגם הרמב\"ם והמחבר מודים בטוענו דמי עבד גדול ומודה לו בדמי עבד קטן דחייב ואינו יכול לטעון משטה אלא דס\"ל להרמב\"ם והמחבר דפריך דכיון דטעמא דרבה בר נתן משום דדחויי קמדחי ליה א\"כ הכא במועד נמי כיון דמסתמא לא הי' המזיק שם ואינו יודע מההיזק כלל והי' לו לטעון איני יודע כלל משום הזיק א\"כ נימא דמאי דקאמר מועד היזק את הקטן דחוי קמדחי לי' ויטעון משטה הייתי בך כי היכא דלרבה בר נתן כל מה דלא הי' מחויב לטעון כגון בשעורים שלא תבעו בשעורים כי מודי ליה בשעורים יכול לטעון משטה הייתי בך א\"כ הכא נמי נימא כיון שלא הי' מחויב להודות כלל שהזיק את הקטן ושפיר הי' יכול לו' איני יודע כלל משום היזק א\"כ נימא דדחוי קמדחי ליה ויוכל לטעון אח\"כ משטה הייתי בך והכי משמע פשטא דש\"ס דממועד הזיק את הקטן נמי פריך אלא ודאי כמ\"ש. כן נ\"ל):","\u0003 שהרי זה כטוענו לו חטים כו' \u0004 הוצרך לזה במועד אבל בתמין בלאו הכי פטור משום מודה בקנס וכ\"כ הרב המגיד שם:","\u0003 זו היא סברת יש אומרים כו' \u0004 באמת זה אינו אלא כל סעיף זה וכל סעיף ג' דלעיל הכל הוא לשון הרמב\"ם ומיירי כאן כשאין עדים כלל על הנגיחה וכן פי' ה' המגיד ומביאו ב\"י: וראיתי בספר גידולי תרומה שער ז' חלק ב' דף כ\"ו ע\"ד האריך להקשות דהאיך אפשר דהרמב\"ם מחייב בעדים דאם כן תיקשי קושיית הבעה\"ת שם והרא\"ש ס\"פ המניח הא מתני' בעדים מיירי דאל\"כ פטור משום מודה בקנס ועוד דהא מדברי הרמב\"ם פ\"ג מה' טוען משמע דס\"ל דטעמא דרבה בר נתן הוא משום דהוה כאלו הודה התובע שאין בידו שעורים וכיון דמדין הודא' אתינן עלה פשיטא דאפי' יביא מאה עדים לסתור הודאתו לא משגיחינן בהו אלא ודאי מ\"ש הרמב\"ם לעיל בס\"ג משלם המזיק כמו שאומר היינו כשהניזק טוען שמא דאם הניזק טוען ברי פטור לגמרי אפי' יש עדים דה\"ל כטוענו בחטים והודה לו בשעורים ע\"כ דבריו ואין דבריו נכונים כלל מכמה טעמים חדא דפשט דברי הרמב\"ם דלעיל משמע דהניזק טוען ברי ועוד דהא כ' שם מיד אח\"כ ואם טען הניזק אתה יודע שזה היזק בפניך הרי המזיק משלם מה שהוד' ונשבע שבועת התורה על השאר. והרי כשטען הניזק אתה יודע ודאי כו' אין לך ברי גדול מזה דהאיך יודע הניזק שהוא יודע ודאי שזה היזק בפניך אלא ודאי אומר אני ואתה היינו שם באותו מעמד ואני ואתה ראינו שזה היזק הרי שטוען ברי ואפ\"ה קאמר משלם מה שהודה ונשבע כו' ועוד דאי הוי טעין הניזק שמא לא הוה שייך לומר ונשבע שבועת התורה דהא אין נשבעין על טענת שמא אלא ודאי ברי קטעין שאומר ברי לי שאתה יודע שזה הזיק בפניך ואפ\"ה משלם מה שהודה ונשבע כו'. ול\"ד לחטים ושעורים כיון שיש כאן עדים וכמו שכתב הרב המגיד וכמו שהבין הטור בדעת הרמב\"ם וכ\"כ הסמ\"ע והב\"ח לדעת הרמב\"ם והוא ברור ודלא כבעל ספר גי' תרומה:","\u0003ולענין מה שהקשה הסי' גי' תרומה דתקש' קושיית הבעה\"ת והרא\"ש סוף פ' המניח כו'\u0004 נראה דאישתמיטתי' או לא עיין שפיר בהרב המ' שהרי הרב המ' כ' דמתני' מיירי בלא עדים וסוגין כמ\"ד פלגא נזקא ממונא כו' וכבר הארכתי לעיל סי' פ\"ח סעיף י\"ב הוכיח כן ע\"ש:","\u0003גם מה שהקשה דהא מדברי הרמב\"ם פ\"ג מהל' טוען משמע דמדין הודאה אתינן עלה כו'\u0004 לק\"מ דאפי' תימא דטעמא הוא משום הודא' מ\"מ כשיש לו עדים לא חשבינן ליה כאלו הודה די\"ל הא דלא תבעתי השעורים משום שיש לי עדים כי על מה שיש לי עדים ואינו יכול לכפור למה לי לתובעו רק רציתי לתובעו במה שאין לי עדים וכמ\"ש לעיל סי' פ\"ח סי\"ב ועוד די\"ל דטעמא דהרמב\"ם פ\"ג מה' טוען נמי דמשום דכיון שזה לא תבע ממנו מה שהודה הרי הודה שאינו תובע זה ויכול הנתבע לטעון משטה הייתי בך ואין הב\"ד מחייבין את הנתבע ליתן מפני הודאתו הראשונה וכמ\"ש לעיל סי' פ\"ח סי\"ב ועכ\"פ דעת הרמב\"ם ברור דהיכא דאיכא עדים חייב ול\"ד לטענו חטים והודה לו בשעורים דהתם מיירי בלא עדים וכן עיקר וכמו שהארכתי לעיל ספ\"ח סי\"ב והוכחתי כן בראיות מן הש\"ס והרבה פוסקים ע\"ש:","\u0003 ואם תפס הניזק ה\"ז משלם לקטן כו'. \u0004 ואע\"פ שהמוד' בקנס פטור כבר תירץ הר\"א ז\"ל בפירושיו דפלגא נזקא שאני משאר קנסות שאם תפס אין מוציאין מידו והוא דעת רבינו ז\"ל עכ\"ל הר' המ' ס\"פ ט' מהל' נזקי ממון אבל הנ\"י ס\"פ המניח כתב דלמ\"ד פלגא נזקא קנסא דקי\"ל כותי' לא מהני עד דאיכא סהדי אבל אי ליכא סהדי אפי' כדקאמר ניזק [מזיק] לא שקיל דלא מהניא תפיס' אלא בממונא דאי הוה מוד' ביה נתבע הוי מחוייב אבל בקנסא דרחמנא פטריה אפי' תפסי' בלא עדים ליכא מגו עכ\"ל (ומשמע שם שהן דברי הרמ\"ה ועמ\"ש לעיל סי' שצ\"ט ס\"ג דבתפס בלא עדים נ\"ל עיקר דמהני) ובאמת כיון דמוכח בש\"ס בכמה דוכתי וכן בפ' מרובה (ריש בבא קמא דף ע\"ה) גבי ר\"ג שסימא את עין טבי עבדו דתפיס' לא מהני במודה בקנס דאין לך תפיסה גדולה מעבד וכדאיתא בהראב\"ד עצמו ובהרא\"ש ספ\"ק דבב\"ק ובכסף משנה ס\"פ ה' מהל' עבדים ושאר פוסקים וכן מוכח מדברי הרב המגיד גופיה דתפיסה לא מהני במודה בקנס א\"כ מנלן לחלק בין פלגא נזקא לשאר קנסות וכ\"כ מהרש\"ל פ' המניח סי' ל\"ה דלא מסתבר לחלק בכך ע\"ש:","שוב ראיתי בתוס' י\"ט ס\"פ המניח שכ' על דברי הברטנורא דברי הר\"ב המגיד בשם הר\"מ דלעיל ועל הראשונים אני מצטער והוא בא להוסיף וכל המוסיף גורע ובחנם דחק די\"ל דהברטנורא מיירי כשיש עדים על הנגיחה וק\"ל:","\u0003 אבל אינו נוטל כפי דבריו. \u0004 כיון שתפס בעדים ואם תפס שלא בעדים נוטל כפי דבריו כ\"כ הטור ומשמע דהיינו משום דמהימן במגו אף בקנס וכן משמע בהרא\"ש ס\"פ המניח וכמ\"ש לעיל סי' שצ\"ט ס\"ג ועמ\"ש שם:"],"\u0010g0\u0011 שׁוֹר שֶׁהָיָה רוֹדֵף אַחַר שׁוֹר אַחֵר, וְהֻזַּק, זֶה אוֹמֵר: שׁוֹרְךָ הִזִּיק, וְזֶה אוֹמֵר: לֹא כִּי \u0010y0\u0011 אֶלָּא \u0010t0\u0011 בַּסֶלַע לָקָה, הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו \u0010c0\u0011 \u0010g1\u0011 הָרְאָיָה, אֲפִלּוּ נִזָּק טוֹעֵן \u0010t1\u0011 בָּרִי וּמַזִּיק טוֹעֵן שֶׁמָּא. \u0010c1\u0011 \u0010g2\u0011 \u0010r0\u0011 וְאִם טָעַן הַנִּזָּק: אַתָּה \u0010t2\u0011 יוֹדֵעַ שֶׁשּׁוֹרְךָ הִזִּיק, \u0010c2\u0011 נִשְׁבָּע הֶסֵת שֶׁאֵינוֹ יוֹדֵעַ. \u0010r1\u0011 בַּמֶּה דְּבָרִים אֲמוּרִים, בְּמוּעָד; אֲבָל בְּתָם, פָּטוּר אַף מֵהֶסֵת, שֶׁהֲרֵי אִם הוֹדָה הָיָה פָטוּר, \u0010y1\u0011 הוֹאִיל וְהוּא קְנָס. \u0010g3\u0011\nהָיוּ שְׁנַיִם רוֹדְפִים אַחַר אֶחָד, \u0010y2\u0011 \u0010g4\u0011 \u0010r2\u0011 וַהֲרֵי עֵדִים שֶׁאֶחָד מֵהֶם הִזִּיק, וְאֵינָם יוֹדְעִים אֵיזֶה מִשְּׁנֵיהֶם, זֶה אָמַר: שׁוֹרְךָ הִזִּיק, וְזֶה אָמַר: שׁוֹרְךָ הִזִּיק, שְׁנֵיהֶם פְּטוּרִים. וְאִם הָיוּ שֶׁל אִישׁ אֶחָד, חַיָּב לְשַׁלֵּם \u0010y3\u0011 \u0010g5\u0011 \u0010r3\u0011 מִגּוּף הַפָּחוּת שֶׁבִּשְׁנֵיהֶם. \u0010r4\u0011 וְאִם הָיוּ מוּעָדִים, מְשַׁלֵּם נֶזֶק שָׁלֵם מִנְּכָסָיו. \u0010g6\u0011 \u0010r5\u0011 בַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁשְּׁנֵי הַשְּׁוָרִים עוֹמְדִים. אֲבָל אִם מֵת אֶחָד מֵהֶם אוֹ אָבַד, וְהָיָה אֶחָד מֵהֶם תָּם, אַף עַל פִּי שֶׁהֵם שֶׁל אִישׁ אֶחָד, פָּטוּר, שֶׁהֲרֵי אוֹמֵר לוֹ: \u0010y4\u0011 הָבֵא רְאָיָה שֶׁזֶּה \u0010t3\u0011 הָעוֹמֵד הוּא שֶׁהִזִּיק וַאֲשַׁלֵּם לְךָ. \u0010g7\u0011\nהָיוּ שְׁנֵי הַשְּׁוָרִים הָרוֹדְפִים אֶחָד גָּדוֹל וְאֶחָד קָטָן, הַנִּזָּק אוֹמֵר: הַגָּדוֹל הִזִּיק, וְהַמַּזִּיק אוֹמֵר: קָטָן הִזִּיק; הָיָה אֶחָד תָּם וְאֶחָד מוּעָד, הַנִּזָּק אוֹמֵר: מוּעָד הִזִּיק, וְהַמַּזִּיק אוֹמֵר: תָּם הִזִּיק; \u0010y5\u0011 \u0010g8\u0011 הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו \u0010g9\u0011 הָרְאָיָה. \u0005(לֹא הָיָה שָׁם רְאָיָה בְּרוּרָה שֶׁזֶּה הִזִּיק, \u0010r6\u0011 אֶלָּא עֵדִים מְעִידִים שֶׁאֶחָד מִשְּׁנֵי אֵלּוּ הִזִּיק, \u0010t4\u0011 מְשַׁלֵּם הַמַּזִּיק כְּמוֹ \u0010g10\u0011 שֶׁאוֹמֵר)\u0006. \u0010c3\u0011 \u0010r7\u0011 וְאִם טָעַן הַנִּזָּק: אַתָּה יוֹדֵעַ וַדַּאי שֶׁזֶּה הִזִּיק בְּפָנֶיךָ, הֲרֵי הַמַּזִּיק \u0010c4\u0011 מְשַׁלֵּם מַה שֶּׁהוֹדָה, \u0010y6\u0011 \u0010c5\u0011 וְנִשְׁבַּע \u0010c6\u0011 שְׁבוּעַת הַתּוֹרָה עַל הַשְּׁאָר. \u0005הַגָּה: \u0010c7\u0011 \u0010c8\u0011 \u0010t5\u0011 \u0010r8\u0011 וְיֵשׁ אוֹמְרִים דְּאֵין כָּאן שְׁבוּעָה כְלָל, דְּהָוֵי לֵהּ כִּטְעָנוֹ חִטִּין וְהוֹדָה לוֹ בִּשְׂעוֹרִים דְּפָטוּר אַף בַּמֶּה שֶׁהוֹדָה, \u0010r9\u0011 וַאֲפִלּוּ תָפַס מַפְקִינָן \u0010g11\u0011 מִנֵּהּ (טוּר ס\"ב בְּשֵׁם הָרֹא\"שׁ)\u0006. וְדַוְקָא טָעַן הַנִּזָּק בָּרִי, אֲבָל אִם טוֹעֵן שֶׁמָּא, מְשַׁלֵּם הַמַּזִּיק כְּמוֹ שֶׁהוּא טוֹעֵן \u0005(שָׁם)\u0006. \u0010g12\u0011 \u0010r10\u0011\nהָיוּ הַנִּזָּקִים שְׁנַיִם, אֶחָד גָּדוֹל וְאֶחָד קָטָן, וְהַמַּזִיקִים \u0005(ב')\u0006 אֶחָד גָּדוֹל וְאֶחָד קָטָן, הַנִּזָּק אוֹמֵר: גָּדוֹל הִזִּיק אֶת הַגָּדוֹל וְקָטָן אֶת הַקָּטָן, וְהַמַּזִּיק אוֹמֵר: לֹא כִּי אֶלָּא הַקָּטָן הִזִּיק אֶת הַגָּדוֹל וְגָדוֹל הִזִּיק אֶת הַקָּטָן, אוֹ שֶׁהָיָה אֶחָד תָּם וְאֶחָד מוּעָד, הַנִּזָּק אוֹמֵר: מוּעָד הִזִּיק אֶת הַגָּדוֹל וְתָם אֶת הַקָּטָן, וְהַמַּזִּיק אוֹמֵר: תָּם הִזִּיק אֶת הַגָּדוֹל וּמוּעָד אֶת הַקָּטָן, הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו \u0010g13\u0011 הָרְאָיָה, וְאִם לֹא הֵבִיא רְאָיָה \u0010c9\u0011 \u0010g14\u0011 בְּרוּרָה פָּטוּר הַמַּזִּיק, \u0010c10\u0011 שֶׁהֲרֵי \u0005(זֶה)\u0006 כִּטְעָנוֹ לוֹ חִטִּים וְהוֹדָה לוֹ בִּשְׂעוֹרִים, שֶׁהוּא נִשְׁבָּע הֶסֵת וּפָטוּר אַף מִדְּמֵי שְׂעוֹרִים. \u0010c11\u0011 \u0010g15\u0011 \u0010r11\u0011 \u0005זוֹ הִיא סְבָרַת יֵשׁ אוֹמְרִים שֶׁכָּתַבְתִּי בְּסָמוּךְ. אֲבָל יֵשׁ מְחַלְּקִים דְּאִם הָיוּ כָּאן עֵדִים שֶׁאוֹמְרִים אֶחָד מֵהֶן הִזִּיק אֶלָּא שֶׁאֵינָם יוֹדְעִין אֵיזֶה הוּא, מְשַׁלֵּם כְּמוֹ שֶׁאָמַר מַזִּיק, וְלֹא מִקְרֵי כְּהַאי גַּוְנָא טְעָנוֹ חִטִּין וְהוֹדָה לוֹ בִּשְׂעוֹרִים (הַמַּגִּיד פ\"ט דב\"מ)\u0006. וְכִסְבָרָא הָרִאשׁוֹנָה שֶׁכָּתַב הַמְחַבֵּר שֶׁמִּקְּרֵי הוֹדָאָה וּכְמוֹ שֶׁנִּתְבָּאֵר. \u0010y7\u0011 \u0010c12\u0011 \u0010g16\u0011 \u0010r12\u0011 וְאִם \u0010t6\u0011 תָּפַס \u0010y8\u0011 הַנִּזָּק, הֲרֵי זֶה מְשַׁלֵּם לַקָּטָן מֵהַגָּדוֹל וְלַגָּדוֹל מֵהַקָּטָן כְּמוֹ שֶׁהוֹדָה הַמַּזִּיק. \u0010g17\u0011 \u0010r13\u0011 וַאֲפִלּוּ תָּפַס בְּעֵדִים, נוֹטֵל כְּמוֹ שֶׁאָמַר הַמַּזִּיק \u0010c13\u0011 \u0010c14\u0011 \u0010c15\u0011 \u0010c16\u0011 \u0010c17\u0011 \u0010r14\u0011 אֲבָל אֵינוֹ נוֹטֵל כְּפִי \u0010t7\u0011 דְבָרָיו. וְדַוְקָא תָּפַס קֹדֶם שֶׁבָּא לְבֵית דִּין, אֲבָל לְאַחַר שֶׁבָּא לְבֵית דִּין לֹא מְהַנְּיָא לֵהּ תְּפִיסָה, אֲפִלּוּ לִטֹּל כְּדִבְרֵי הַמַּזִּיק:",{"g":["א) משנה ספ\"ג דב\"ק דף ל\"ה ע\"א","ב) כן משמע שם בגמ' ע\"ב ובהדיא אמרינן הכי ברפ\"ה דף מ\"ו ע\"א לרבנן דקי\"ל כוותייהו","ג) רמב\"ם פ\"ט מה' נזקי ממון ד\"ז והביאו הטור וכתב הב\"י ודברים פשוטים הם על פי מה שנתבאר שאין נשבעין היסת אלא על טענת ודאי ועל דבר שאם היה מודה היה מתחייב ממון","ד) שם ד\"ז ושם במשנה","ה) הוא מוכרח דאל\"כ לא הוי מצי למתני אם היו של איש אחד חייב","ו) כ' ה\"ה מפני שהוא ספק דהמע\"ה","ז) ד\"ח כ' ה\"ה הוא מפורש בגמ' שם (דף ל\"ו ע\"א) ע\"ד פירושו ז\"ל והוא הנכון שאם אבד האחד אבד לגמרי ודברי רבינו עיקר ע\"כ וכ\"כ הטור בשם הרא\"ש","ח) שם דין ט' ושם במשנה","ט) וכ' ה\"ה וביאור דבריו שאם לא הביאו (הניזק) ראיה כלל הרי המזיק פטור לגמרי כמ\"ש לפנינו בדין היו הניזוקים ב' (בסעיף הסמוך) שהרי הוא דומה לחטין ושעורין ולא עוד אלא כיון שאינו מודה אלא בתם אם אין שם עדים הרי הוא מודה בקנס ופטור וכו' ואנן קי\"ל פלגא ניזקא קנסא","י) שם ד\"י וכתב ה\"ה הוא דין נכון שאינו דומה לדין חיטין ושעורים שלפנינו שהרי יש כאן עדים","כ) כתב ה\"ה הר\"א הודה לו בהשגות בא' תם וא' מועט מטעמו שהרי התם בכלל תביעה המוע' שכל הנכסים משועבדים לו אבל כששניהם תמים הרי הם כחטים ושעורים ואע\"פ שיש שם עדים שאחד מהם הזיק פטור ומן השבועה ויש לחלק שאפילו בב' תמין כיון שיש שם עדים חייב שבועת התורה וצ\"ע","ל) בריש ס\"ג אמה שכ' הרמב\"ם משלם המזיק כמו שאומר כתב שנראה כדבריו אם הניזק טוען שמא אפילו אין לו עדים","מ) שם די\"א משנה שם ע\"ב","נ) שם בגמ'","ס) כ' ה\"ה א\"א לבאר מאמר רבינו ז\"ל לומר שאין שם ראיה ברורה איזה מהם הזיק אבל יש שם עדים שהזיקו שא\"כ (היאך) יאמר פטור שהרי למעלה אמר בכיוצא בזה משלם המזיק כמו שאמר דכל שיש שם עדים אינו דומה לחטים ושעורים כמ\"ש למעלה אלא ודאי כוונת רבינו ז\"ל שאין שם עדים כלל והמזיק פטור בתמין מדינים דמודה בקנם פטור ובאחד תם ובא' מועד כדין טענו חטים והודה לו בשעורים ע\"כ","ע) לא הבנתי כוונת הרב רמ\"א הלא המה דברי הרמב\"ם מועתקי' אות באו' ומ\"ש אבל יש מחלקים וכו' הוא מה שכתב ה' המגיד בפי' דברי הרמב\"ם כמ\"ש וכבר העיר ג\"כ הרב סמ\"ע בזה ואכמ\"ל","פ) שם בגמ' וכתב ה\"ה היא ודאי בששניהם תמין כך היא בגמ' מפורש ואע\"פ שהמודה בקנס פטור כבר תירץ הר\"א ז\"ל בפירושיו דפלג' נזקא שאני משאר קנסות שאם תפס אין מוציאין מידו והוא דעת רבינו ז\"ל ודע שדיני בבא זו ושל מעלה ממנה שוין וכו' ורבי' ז\"ל כ' למעלה דין עדים שמעידים שהוא חייב אע\"פ שאין התביעה אלא על אחד מהם וכ\"ש כאן שהתביעה על שניהם וכאן כתב כשאין שם עדים כלל שהוא פטור מדין חטין ושעורים אף על פי שהתביעה על שניהם וכ\"ש למעלה שאין התביעה אלא לאחד ולזה יש דעה אחרת למפרשים","\u0003צ) טור ס\"ה בשם אביו הרא\"ש ומבואר שם בפסקיו:\u0004 "],"t":["\u0003בסלע. \u0004 ואע\"פ שניזקה ע\"י רדיפת שורו אחריו לא הוי אלא גרמא בנזקין. סמ\"ע:","\u0003ברי. \u0004 משמע דאפילו במועד דינא הכי ומהרש\"ל פרק המניח סי' ל\"ג כת' דבמועד שרדף חייב כשניזק טוען ברי ומזיק שמא מאחר דרב הונא ורב יהודה מחייבין בברי ושמא ואין דבריו נכונים אלא כיון דקי\"ל כרבנן דמוקמינן ממונא בחזקת מריה א\"כ בכל ענין המע\"ה. ש\"ך:","\u0003יודע. \u0004 אבל כשאינו טוען כן א\"צ לישבע היסת שהרי הניזק עצמו מודה שלא היה שם וא\"כ ודאי אין הניזק יודע ועמ\"ש בסי' ע\"ב סי\"ב וסי' צ\"ג סי\"ג. שם","\u0003העומד. \u0004 ואם זה העומד הוא תם והמועד מת או נאבד דגובה ח\"נ מזה התם העומד ממ\"נ אם הוא נגחו הרי בדין גובה ח\"נ מגוף המזיק ואם זה שמת נגחו הרי היה מועד וחייבים בעליו לשלם מנכסיו וזה שור המועד בכלל נכסיו הוא אלא דהמחבר איירי שזה העומד הוא מועד א\"נ אינם ניכרין איזה מועד ואיזה תם. סמ\"ע:","\u0003משלם. \u0004 הסמ\"ע והש\"ך האריכו די באר בדין זה כל הצורך ע\"ש:","\u0003וי\"א. \u0004 ולעיל סי' פ\"ח סי\"ב הוכחתי דלא כהי\"א בזה אלא דהיכא דאיכא עדים משלם הפחות שבשניהם וכן תפיסה מהני ליטול כדקאמר מזיק אפילו ליכא עדים וע\"ש. ש\"ך:","\u0003תפס. \u0004 דכיון דטען על שניהן שנגחוהו וגם המזיק מודה בזה אף שאין לו עדים איזה נגח לזה ואיזה לזה מהני תפיסתו לכ\"ע וכן הוא בש\"ס. סמ\"ע:","\u0003דבריו. \u0004 כיון שתפס בעדים. ואם תפס שלא בעדים נוטל כפי דבריו כ\"כ הטור ומשמע דהיינו משום דמהימן במיגו אף בקנס וכן משמע בהרא\"ש ס\"פ המניח וכמ\"ש בסי' שצ\"ט ס\"ג וע\"ש. שם:"],"r":["\u0003ואם טען כו'. \u0004 עתוס' מו א' ד\"ה דאפילו כו' ועוד אמר ר\"י דל\"ד כו' וע\"כ צריך ליתן טעם כו' אבל הרמב\"ם ס\"ל אף בדבר דלא ה\"ל לידע כמ\"ש בסי' צ' ס\"י אלא דוקא אם התובע טוען שיודע הנתבע משא\"כ ביורשים וכאן. וכעין זה כ' ש\"ך בסי' עב סי\"ב:","\u0003בד\"א כו'. \u0004 כמ\"ש בסי' שצט ס\"ג:","\u0003והרי עדים כו'. \u0004 דאל\"כ הרי מודה בקנס כנ\"ל ועבה\"ג:","\u0003מגוף הפחות כו'. \u0004 כמ\"ש בס\"ג ואמרינן שם בגמ' ואפי' בברי ושמא וכמ\"ש בס\"א:\n\u0003 (ליקוט) מגוף הפחות כו'. \u0004 תוספתא פ\"ג ואם בידוע שהן המיתוהו הרי אלו משלמין בקטן ולא בגדול בתם ולא במועד וכ\"ה במתני' שם (ע\"כ):","\u0003ואם היו כו'. \u0004 שם לו א':","\u0003בד\"א כו'. \u0004 שם וכפרש\"י דלא כברצלוני בשם גאון וערא\"ש:","\u0003אלא עדים כו'. \u0004 דאל\"כ פטור מכלום כמ\"ש בס\"ב ועמ\"ש למטה דהרמב\"ם ס\"ל דכל הסוגיא מיירי בעדים:","\u0003ואם טען כו'. \u0004 ולא היה הודאה שלא ממין הטענה כמ\"ש בב\"מ ק' א' בטוענו דמי כו' ה\"נ טוענו שנתחייב לו דמים בשביל היזק של שורו זה אומר בכך וזה אומר בכך ודוקא לענין זה שיפטר אף מהקטן מדמי גמ' נחטין ושעורים דחד טעמא להו משום מחילה או משטה וכיוצא. ודוקא שטוען אתה יודע כנ\"ל אבל בלא\"ה א\"צ לישבע וגם אם אומר המזיק שמא לא הוי משוילו\"מ ומזה למד הרמב\"ם דין זה מדקאמר כאן המע\"ה ולא הוי משוילו\"מ לאוקימתא דגמ' באומר שמא וכן באומר ברי ישבע דממתני' דרפ\"ה י\"ל כתי' שני של תוס' משום דהוי קנס וכמ\"ש בס\"א בד\"א כו' אבל כאן דניזק אומר מועד וע\"ז קאמר כאן ונשבע וכ\"כ הראב\"ד א\"א אתם ואמועד קאי ומתני' דקתני המע\"ה כגון דקאמר שמא תם הזיק דליכא שבועה גביה ואיתימא להוי כמחוייב שוילו\"מ דוקא בתובע בבריא וא\"ל באמת אתה יודע ועבה\"ג בשם המ\"מ ושגה בזה דטעמו משום מודה בקנס כמ\"ש בס\"א בד\"א במועד כו' אח\"כ מצאתי בש\"ך שהשיג עליו:","\u0003וי\"א כו'. \u0004 פליג בתרתי חדא דאף אם נתחייב מ\"מ ליכא כאן שבועה וכמ\"ש נ\"י שם ועסי' ע\"ה סי\"ג והשניה שפטור אף במה שהודה דהא מדמי לרבה ב\"נ אלא דהרמב\"ם ס\"ל כיון שיש עדים על א' מהן לא שייכא בדרבה ב\"נ והי\"א ס\"ל אפי' בעדים דהא כאן ע\"כ בעדים מיירי דאל\"כ הוי מודה בקנס ואפ\"ה פריך מדרבה ב\"נ ועמ\"ש בסי' פח סי\"ב. וגם מה שדימה הרמב\"ם דמי לעבד ס\"ל כפרש\"י ותוס' שם ועמ\"ש בסי' פח סי\"ט:","\u0003ואפילו תפס כו'. \u0004 אפי' בסיפא תם ומועד ועתוס' שם ד\"ה ראוי כו' אבל הרי\"ף ורמב\"ם חולקים ע\"ז וכמ\"ש בסי' פ\"ח סי\"ב וכן סתם בהג\"ה שם:","\u0003ודוקא טען כו'. \u0004 גמ' שם:","\u0003זו היא כו' \u0004 דברי הרב אינן מכוונין דהאכ\"ז הוא לשון הרמב\"ם וגם דברי המ\"מ תמוהים מאד ועמ\"ש בליקו' ג' א' בסי' ת' שדעת הרמב\"ם דבעדים משלם מה שהודה כמ\"ש בס\"ג ע\"ש ועסי' פח סי\"ב מש\"ש ושם סתם המחבר להיפך דפטור ע\"ש.","\u0003ואם תפס כו' \u0004 גמ' שם וכל מ\"ש המ\"מ כאן תמוהים מאד וגם האחרונים נתקשו וכבר יישבתי כנ\"ל אבל בזה צדקו דבריו מ\"ש אע\"ג דמודה בקנס פטור מ\"מ מהני תפיסה אף ברישא א' גדול וא' קטן וכמש\"ש בגמ' ודלא כנ\"י שכ' דסוגיא דגמ' למ\"ד פלגא נזקא ממונא אבל הרמב\"ם לא ס\"ל כן וכמש\"ל שהרמב\"ם אוקים הסוגיא כמ\"ד פלגא נזקא קנסא וכמ\"ש בליקו' שם אבל נ\"י מפ' כהיש מחלקין דבלא עדים מיירי וע\"כ כמ\"ד ממונא כנ\"ל ועש\"ך שהסכים לדברי נ\"י והקשה על המ\"מ מהא דר\"ג שם ע\"ד ע\"ש ודבריו נכונים אבל טעם הרמב\"ם דס\"ל דמודה בקנס דוקא אם הודה בעיקר הדבר אבל כל שעל עיקר הדבר יש עדים לאו מודה בקנס הוא וחייב ע\"פ עצמו וז\"ש בס\"ג ואם טען כו' ונשבע כו' ומ' מדבריו שאפי' ברישא בשניהן תמין לא הראב\"ד שפי' אסיפא שאין דבריו מ' כן וזה דפריך בגמ' אסיפא מדרבה ב\"נ הא לא מייתי כו' ואם איתא בלא\"ה הא מודה בקנס הוא כיון דליכא ראיה ברורה ששניהם הזיקו כנ\"ל. וקושית התוס' דרפ\"ה מתרץ כנ\"ל כיון שלא א\"ל אתה יודע בודאי:","\u0003ואפי' תפס כו' ודוקא כו'. \u0004 עסי' פח סי\"ב:","\u0003אבל כו'. \u0004 עסי' שצט ס\"ג בהג\"ה ועש\"ך כאן ושם אב להרמב\"ם דין ממון כאן כנ\"ל:"]}],["שׁוֹר שֶׁנָּגַח וְחָזַר וְנָגַח שׁוֹר אַחֵר, \u0010c0\u0011 הֲרֵי הַנִּזָּק הָרִאשׁוֹן וְהַבְּעָלִים \u0010c1\u0011 כְּשֻׁתָּפִים בּוֹ. כֵּיצַד, שׁוֹר שְׁוֵה מָאתַיִם שֶׁנָּגַח שׁוֹר שְׁוֵה מָאתַיִם, וְאֵין הַנְּבֵלָה יָפָה כְּלוּם, הַנִּזָּק נוֹטֵל ק' וּבַעַל הַשּׁוֹר ק'. חָזַר וְנָגַח שׁוֹר אַחֵר שְׁוֵה מָאתַיִם, וְאֵין הַנְּבֵלָה יָפֶה כְּלוּם, הָאַחֲרוֹן נוֹטֵל מֵאָה וְהַנִּזָּק שֶׁלְּפָנָיו עִם הַבְּעָלִים נוֹטְלִים חֲמִשִּׁים, חֲמִשִּׁים זוּז. חָזַר וְנָגַח שׁוֹר שְׁוֵה מָאתַיִם וְאֵין הַנְּבֵלָה יָפָה כְּלוּם, הָאַחֲרוֹן נוֹטֵל מֵאָה, וְהַנִּזָּק שֶׁלְּפָנָיו חֲמִשִּׁים, וְהַנִּזָּק הָרִאשׁוֹן עִם הַבְּעָלִים כ\"ה כ\"ה; \u0010y0\u0011 וְכֵן עַל דֶּרֶךְ זֶה חוֹלְקִים וְהוֹלְכִים.\nנִזָּק שֶׁתָּפַס בְּהֵמָה שֶׁהִזִּיקָה, לִגְבּוֹת חֲצִי נִזְקוֹ מִגּוּפָהּ, נַעֲשָׂה עָלֶיהָ שׁוֹמֵר שָׂכָר לִנְזָקִים, וְאִם יָצָאת וְהִזִּיקָה, \u0010c2\u0011 הַנִּזָּק הָרִאשׁוֹן חַיָּב בִּנְזָקֶיהָ וְהַבְּעָלִים פְּטוּרִים. כֵּיצַד, שׁוֹר שְׁוֵה מָאתַיִם שֶׁנָּגַח וְהִפְסִיד מָאתַיִם, וּתְפָסוֹ הַנִּזָּק לִגְבּוֹת מִמֶּנּוּ ק', \u0010y1\u0011 וְחָזַר וְנָגַח וְהִפְסִיד ק\"מ, הֲרֵי הַנִּזָּק הָאַחֲרוֹן מִשְׁתַּלֵּם ע', וְהַנִּזָּק הָרִאשׁוֹן שֶׁתָּפְסוֹ מִשְׁתַּלֵּם מוֹתַר נִזְקוֹ וְהוּא ל', וְהַבְּעָלִים ק'; וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0005הַגָּה: \u0010y2\u0011 \u0010c3\u0011 \u0010c4\u0011 \u0010c5\u0011 וְיֵשׁ אוֹמְרִים דְּאֵין חִלּוּק בֵּין אִם תְּפָסוֹ אוֹ לֹא תְפָסוֹ, בְּכָל עִנְיָן הַנִּזָּק אֵינוֹ מַפְסִיד אֶלָּא חֲצִי וְהַבְּעָלִים חֲצִי (טוּר בְּשֵׁם ר\"י וְהָרֹא\"שׁ)\u0006.",["\u0003וכן על דרך זה הולכים וחולקים. \u0004 לפי מה שהקדים המחבר וכתב כיצד כו' לפרש בו שחזר ונגח וחזר ונגח הרי מיירי שנגח ג' פעמים ובג\"פ נעשה שור המועד וגבהו הניזק האחרון כולו ולא הל\"ל שכן עד\"ז חולקים והולכים ואפשר של\"ד קאמר או מיירי כשלא התרה בו דלא נעשה מועד:","\u0003וחזר ונגח והפסיד ק\"מ כו'. \u0004 כן הוא גם כן לשון הרמב\"ם וק\"ק למה שינה בלשונו ונקט הפסיד ק\"מ ולא כתב כמו לעיל שהפסיד שור שוה ק\"ק שמפסיד התופס כל חלקו כי הניזק האחרון יטול משור המזיק ק' והבעלים ק' וכ\"כ הטור בקיצור ע\"ש:","\u0003וי\"א דאין חילוק בין אם תפסו כו'. \u0004 הטעם כיון דקי\"ל דניזק ובעלים נעשים שותפים בו ואם כיחש או נשבח הוא ברשות שניהן לא נעשה שומר אלא מחלקו דעל כל א' מוטל לשמור חלקו ועד\"ר וע\"ל סי' קע\"ו שכתב הטור בסי\"א ז\"ל השותפין שומרי שכר הן שאם נגנב או נאבד מהשותפין ברשות א' מהן חייב באחריות בד\"א בזמן שכל אחד ואחד מתעסק בהשותפות זמן ידוע ונגנב לו בזמן שמתעסק בו אבל כו' ויש לחלק ביניהן ולומר דלא נעשה שומר עליו אלא שלא יתאבד חלק הבעלים שהן שותפין ולא לענין שמיר' דניזקין דעלמא ועד\"ר:"],["\u0003 הרי הניזק הראשון. \u0004 כתבו התוס' ר\"פ שור שנגח ארבעה וחמשה דהיינו כשיש בידו להביא עדים לאלתר ולזכות בו אבל כשאין בידו להביא עדים לאלתר לא הוי שותף וראשון ראשון נשכר ע\"ש. ע' בתשו' הר\"ב סי' כ\"ז ומ\"ש לעיל ר\"ס ע\"ז:","\u0003 כשותפין כו'. \u0004 ולפ\"ז אם הקדישו ניזק עד שלא עמד בדין מוקדש הכי אמרי' בש\"ס פ' המניח (בבא קמא דף ל\"ג ע\"א) וכ\"כ הנ\"י ר\"פ שור שנגח ד' וה' בשם הרמ\"ה וכן אם מכרו הניזק וכדלקמן ריש סי' ת\"ז ועמ\"ש שם. וכן אין המזיק יכול לסלק את הניזק במעות אלא נוטל את השור עצמו כדאיתא בש\"ס שם בפ' המניח ובתוס' שם ד\"ה והקדישו ניזק כו' ע\"ש עוד בתוס' [דבור בפ\"ע] וכן על דרך זה הולכים וחולקים לפי מה שהקדים המחבר וכתב כיצד כו' לפרש בו שחזר ונגח וחזר ונגח הרי מיירי שנגח ג' פעמים ובג\"פ נעשה שור המועד וגבהו הניזק האחרון כו' ולא הל\"ל וכן עד\"ז חולקים והולכים ואפשר של\"ד קאמר או מיירי כשלא התרה בו דלא נעשה מועד עכ\"ל סמ\"ע ס\"ק א' ומה שכ' ולא הל\"ל וכן עד\"ז חולקין כו' לא קשה מידי דהרמב\"ם והמחבר כתבו כל' המשנה שור שנגח ארבע וחמשה ומ\"ש או מיירי כשלא התר' בו דלא נעשה מועד כ\"כ ג\"כ ר' ירוחם נ\"א ח\"ג. ועי\"ל כמו שפירש\"י ר\"פ שור שנגח ד' וה' ז\"ל ובכלן הי' תם דמשתלם מגופו והיכי דמי כגון ראה שור ונגח שור ולא נגח וראה שור ונגח ואחר נגיחה הב' ראה ב' פעמים ולא נגח דאפילו מועד לסירוגין ליכא דשור אינו נעשה מועד אלא א\"כ נגח השלשה נגיחות בשלשה שראה כסדרן או שלא כסדרן ונעשה מועד לסירוגין עכ\"ל וכ\"כ הנימוקי יוסף שם:","\u0003 הניזק הראשון חייב כו'. \u0004 וכן אם תפסו ניזק שני נעשה ש\"ש לראשון ולבעלים וכן ג' וד' כדמוכח בש\"ס וכתבו התוס' דפעמים שהרביעי אין לו כלום ושלישי יש לו כגון שנזקי ד' וה' שוים ונזקי ג' יתרים ואפי' חמישי נמי פעמים שאין לו כל נזקו אם נזקיו יתרים על של ד' שאינו נוטל אלא חלקו של ד'. ומהר\"ש אידלש תמה על דבריהם דלמה לא יטול החמישי מגוף המזיק מהבעלים ומהג' ומהב' וכדפריך לקמן ולימא ליה אי תם הוה משתלם מגופו משום דא\"ל ס\"ס תורי בעי שלומי וגם בשלטי גבורים הניח דבריהם בצ\"ע עכ\"ד מהרש\"א ול\"ק מידי דהתם נתנו לשומר משא\"כ הכא שתפסו בע\"כ יכול המזיק לומר אנוס הייתי ולא הייתי יכול לשומרו וה\"ל כהוציאו' לסטים דהבעלים פטורים וגם מה שהקש' הש\"ג דלמה לא ישלם הב' והג' מה שהזיק יותר מחלקו פשיטא נמי דל\"ק מידי דכיון דתם אינו משלם רק מגופו היאך יעלה על הדעת שישלם יותר ממה שיש לו בו ואפילו הי' החלק שיש לו בו שלו לגמרי לא הי' משלם יותר. ונראה דאף למ\"ש לקמן דהעיקר כהי\"א דאף בתופסו לא הוי רק ש\"ש על חלקו מ\"מ נ\"מ לענין מועד שהזיק דבכה\"ג לכ\"ע נעשה שומר שכר לנזקיו כשתפסו וכמ\"ש לקמן וא\"כ לפי מה שכתבתי אינו נוטל יותר ממה שמגיע למי שלפניו ודוק:","\u0003 וי\"א כו' \u0004 טור בשם ר\"י והרא\"ש. וכן דעת ה\"ר אפרים תלמיד הרי\"ף ובעל המאור והרמ\"ה והתוס' ר\"פ ד' וה' וכן נראה דעת הברטנורא שם וכ\"כ האגוד' בשם ר\"י וכן נראה עיקר בש\"ס שם וכ\"פ מהרש\"ל שם ודלא כעיר שושן שהשמיט דעת הי\"א ועשה מן הטפל עיקר (גם תמיהא לי על ר' ירוחם שכתב בנל\"א ח\"א בסתם כדברי הרמב\"ם ולא הזכיר דעת הרא\"ש רבו וכל הני רבוותא כלל) מיהו במועד לכ\"ע נעשה שומר דהא מוכח בש\"ס דע\"כ לא פליג ר\"ע עליה דר' ישמעאל אלא משום דס\"ל כיון דמשתלם מגופו שותפי נינהו וכן כתב הבעל המאור והנ\"י ומהרש\"ל שם וגדולה מזו נ\"ל דבמועד שתפסו חייב אפי' באונסין וכמ\"ש לעיל סי' ע\"ב ס\"ב ס\"ק ט' ואע\"ג דבש\"ס אמרי' נעשה כש\"ש לנזקיו היינו בתם דמשתלם מגופו ואע\"ג דלר' ישמעאל אין לו בו חלק מבורר מ\"מ דכיון דמשתלם מגופו לא הוי רק ש\"ש אבל במועד שמשלם מן העלי' א\"כ ה\"ל התפיס' ממש כתופס משכון שלא ברשות ב\"ד דכתבתי לעיל סי' ע\"ב ס\"ב ס\"ק ט' דחייב לכ\"ע אף באונסים וע\"כ קשה לי על בעל המאור והנמ\"י שכתבו דבמועד נעשה שומר שכר ומהא שמעינן דמאן דתפיס מחבריה מידי למגבי מיני' חובו נעשה עליו שומר שכר כו' דעדיפא מיניה ה\"ל לאשמועינן דחייב עלי' באונסים ומכ\"ש לפי מש\"ל סי' ע\"ב ס\"ב ס\"ק ט' דדעת בעל המאור דר' יצחק דאמר ב\"ח קונה משכון במשכנו שלא בשעת הלואתו היינו אפי' לאונסים וגם קשה דמאי אצטריך בעל המאור לאתויי ראי' מהכא הא היינו מימרא דרבי יצחק ודוחק לומר דס\"ל לבעל המאור דמשכנו שלא ברשות ב\"ד עדיף טפי דאדרבא איפכא מסתברא וכמש\"ל סי' ע\"ב ס\"ק ט' וגם בש\"ס ורמב\"ם והרב המגיד מוכח דברשות בית דין עדיף טפי כמ\"ש שם וצ\"ע:","שוב נרא' דלפי מה שהעליתי לעיל סי' ע\"ב ס\"ב ס\"ק ט' באריכות דטעמא דשלא בשעת הלואתו קני ליה אף לאונסים דכיון דאין לו לשלם אם כן שעבודי' רמיא עליה דההוא משכון ונקנ' לו גוף המשכון א\"כ לא קשה מידי דשאני הכא דמיירי דיש לו לשלם ממקום אחר א\"כ שעבודי' לא רמי' על שור זה ולא דמי לדר' יצחק ומשום תופס שלא ברשות נמי ליכא דכיון דשור זה הזיקו יש לו רשות לתפסו דמי שתופס דבר המזיק לא חשיב גזלן בהכי (ועיין בספרי תקפו בהן סי' ק\"ח וק\"י) ובעל המאור ונ\"י שלמדו מכאן דמאן דתפיס מחברי' מידי למגבי מיני' חובו נעשה עליו ש\"ש כו' כוונתם אפילו תפס ברשות דומיא דשור המועד כגון שנתן לו חבירו רשות שאם לא ישלם לו לזמן פלוני יהא לו רשות לתפוס ממנו מטלטלים בעצמו שלא ע\"פ ב\"ד וכה\"ג הוי ש\"ש ומיהו לאונסים לא קני כיון יש לו לשלם ממקום אחר ועוד נ\"ל די\"ל דאה\"נ דס\"ל לבעל המאור ונ\"י דחייב באונסים מטעם דר' יצחק אלא מדר' יצחק לא נשמע אלא בב\"ח קונ' משכון כלומר מה שכנגד הלואתו הוי כאלו מכור לו אבל לא שמעינן מיני' דהוי עליה ש\"ש כלל להמותר שעל חובו והלכך למדו מהך דשור דאפילו ש\"ש הוי להמותר בההיא הנאה דתפיס ליה אחובי' מיהו לענין דינא האמת דלא קנה לאונסים אלא כשאין לו לשלם ממקום אחר וכמו שהארכתי בזה לעיל סי' ע\"ב ס\"ב ס\"ק ט' ע\"ש:","\u0003 דאין חילוק כו' \u0004 וע\"ל סי' קע\"ו שכתב הטור בסי\"א ז\"ל השותפין שומרי שכר הן שאם נגנב או נאבד מהשותפין ברשות א' מהן חייב באחריות בד\"א בזמן שכל א' וא' מתעסק בשותפות בזמן ידוע ונגנב לו בזמן שמתעסק בו אבל כו' ויש לחלק ביניהן ולומר דלא נעש' שומר עליו אלא שלא יתאבד חלק הבעלים שהן שותפין ולא לענין שמיר' דניזקין דעלמא עכ\"ל סמ\"ע ס\"ק ג' ודבריו אינם נכונים ונ\"מ טובי לדינא דלדבריו כי היכי בשור של שותפים שהי' ברשות א' מהן והזיק אין השותף חייב על חלק חבירו וגם בזה שתפסו אם נאבד אצלו חייב לשלם חלק הבעלים לפי סברתו דמחלק בין ניזקין לאביד' ואין טעם כלל לחלק בכך וגם בש\"ס ופוסקים לא משמע כן גם מל' הרא\"ש שכתב דהוי כמו חפץ ששו' ר' שלפעמים זה שומרו ולפעמים זה שומרו ולעולם הוי אחריותו על שניהם עכ\"ל לא משמע כן אבל האמת יורה דרכו דשאני הכא כיון שאינו מחויב לשמור א\"כ אינו נעש' שומר רק על חלקו אבל על חלק חבירו אפי' ש\"ח לא הוי וכ\"כ בעל המאור ר\"פ שור שנגח ד' וה' להדיא לחלק בכך וכ\"כ המרדכי פ' ח\"ה ובלי ספק דאשתמיטתי' להסמ\"ע דברי בעל המאור והמרדכי. ולפ\"ז ה\"ה אם נאבד אצלו פטור על חלק חבירו אבל בשור של ב' שותפין שחל א' מחויב לשמור אפי' הזיק חייב גם על חלק חבירו. ועיין מ\"ש לעיל סי' קע\"ז ס\"ח:"],"\u0010g0\u0011 שׁוֹר שֶׁנָּגַח וְחָזַר וְנָגַח שׁוֹר אַחֵר, \u0010c0\u0011 הֲרֵי הַנִּזָּק הָרִאשׁוֹן וְהַבְּעָלִים \u0010c1\u0011 \u0010t0\u0011 כְּשֻׁתָּפִים בּוֹ. כֵּיצַד, שׁוֹר שְׁוֵה מָאתַיִם שֶׁנָּגַח שׁוֹר שְׁוֵה מָאתַיִם, וְאֵין הַנְּבֵלָה יָפָה כְּלוּם, הַנִּזָּק נוֹטֵל ק' וּבַעַל הַשּׁוֹר ק'. חָזַר וְנָגַח שׁוֹר אַחֵר שְׁוֵה מָאתַיִם, וְאֵין הַנְּבֵלָה יָפֶה כְּלוּם, הָאַחֲרוֹן נוֹטֵל מֵאָה וְהַנִּזָּק שֶׁלְּפָנָיו עִם הַבְּעָלִים נוֹטְלִים חֲמִשִּׁים, חֲמִשִּׁים זוּז. חָזַר וְנָגַח שׁוֹר שְׁוֵה מָאתַיִם וְאֵין הַנְּבֵלָה יָפָה כְּלוּם, הָאַחֲרוֹן נוֹטֵל מֵאָה, וְהַנִּזָּק שֶׁלְּפָנָיו חֲמִשִּׁים, וְהַנִּזָּק הָרִאשׁוֹן עִם הַבְּעָלִים כ\"ה כ\"ה; \u0010y0\u0011 וְכֵן עַל דֶּרֶךְ זֶה חוֹלְקִים \u0010t1\u0011 וְהוֹלְכִים. \u0010g1\u0011\nנִזָּק שֶׁתָּפַס בְּהֵמָה שֶׁהִזִּיקָה, לִגְבּוֹת חֲצִי נִזְקוֹ מִגּוּפָהּ, נַעֲשָׂה עָלֶיהָ שׁוֹמֵר שָׂכָר לִנְזָקִים, וְאִם יָצָאת וְהִזִּיקָה, \u0010c2\u0011 \u0010t2\u0011 הַנִּזָּק הָרִאשׁוֹן חַיָּב בִּנְזָקֶיהָ וְהַבְּעָלִים פְּטוּרִים. כֵּיצַד, שׁוֹר שְׁוֵה מָאתַיִם שֶׁנָּגַח וְהִפְסִיד מָאתַיִם, וּתְפָסוֹ הַנִּזָּק לִגְבּוֹת מִמֶּנּוּ ק', \u0010y1\u0011 וְחָזַר וְנָגַח וְהִפְסִיד ק\"מ, הֲרֵי הַנִּזָּק הָאַחֲרוֹן מִשְׁתַּלֵּם ע', וְהַנִּזָּק הָרִאשׁוֹן שֶׁתָּפְסוֹ מִשְׁתַּלֵּם מוֹתַר נִזְקוֹ וְהוּא ל', וְהַבְּעָלִים ק'; וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0005הַגָּה: \u0010y2\u0011 \u0010c3\u0011 \u0010c4\u0011 \u0010c5\u0011 \u0010r0\u0011 וְיֵשׁ אוֹמְרִים דְּאֵין חִלּוּק בֵּין אִם תְּפָסוֹ אוֹ לֹא תְפָסוֹ, בְּכָל עִנְיָן הַנִּזָּק אֵינוֹ מַפְסִיד אֶלָּא \u0010t3\u0011 חֲצִי וְהַבְּעָלִים חֲצִי (טוּר בְּשֵׁם ר\"י \u0010g2\u0011 וְהָרֹא\"שׁ)\u0006.",{"g":["א) ל' הרמב\"ם פ\"ט מהלכות נזקי ממון די\"א משנה ריש פ\"ד דב\"ק דף ל\"ו ע\"א וכתב ה\"ה פסק רבינו כר\"ש דמתניתין דאתיא כר\"ע בגמרא (שם ע\"ב):","ב) שם דף י\"ב וכ' ה\"ה זה נלמד מהסוגיא אשר שם (ריש ע\"ב וכמו שפי' רש\"י שם) וברור הוא וכן כתב בהלכות","\u0003ג) שם בתוספת.\u0004 "],"t":["\u0003כשותפים. \u0004 כתבו התוס' ר\"פ ד' וה' דהיינו כשיש בידו להביא עדים לאלתר ולזכות בו אבל כשאין בידו להביא עדים לאלתר לא הוי שותף וראשון ראשון נשכר ע\"ש ועמ\"ש לעיל ר\"ס ע\"ד ועיין בתשובת הרמ\"א סי' כ\"ד ואם הקדישו ניזק עד שלא עמד בדין מוקדש הכי אמרינן בש\"ס פרק המניח וכ\"כ הנ\"י ריש פרק ד' וה' בשם הרמ\"ה וכן אם מכרו הניזק וכדלקמן ר\"ס ת\"ז ועמ\"ש שם וכן אין המזיק יכול לסלק את הניזק במעות אלא נוטל את השור עצמו כדאיתא בש\"ס ובתוס' שם ד\"ה והקדישו ניזק ע\"ש. ש\"ך:","\u0003והולכים. \u0004 לפי מה שמפרש המחבר כיצד כו' שנגח ג\"פ צ\"ל דמיירי כשלא התרו בו דלא נעשה מועד א\"נ כדפרש\"י ר\"פ ד' וה' כגון שראה שור ונגח שור ולא נגח כו' דאפילו מועד לסירוגין ליכא ע\"ש. שם:","\u0003הראשון. \u0004 וכן אם תפסו ניזק שני נעשה ש\"ש לראשון ולבעלים וכן ג' וד' כדמוכח בש\"ס. שם:","\u0003חצי. \u0004 הטעם כתב הסמ\"ע כיון דקי\"ל דניזק ובעלים נעשין שותפין בו ואם כוחש או נשבח הוא ברשות שניהן לא נעשה שומר אלא מחלקו דעל כל אחד מוטל לשמור חלקו ועיין בש\"ך שהביא הרבה גדולי הפוסקים דס\"ל כדעת הי\"א וכת' דכן נראה עיקר בש\"ס וע\"ש עוד שהשיג על הסמ\"ע במה שרוצה לחלק בין ההיא דהכא ובין מ\"ש הטור בסי' קע\"ז סי\"א דהשותפין ש\"ש הן כו' ויש בזה נ\"מ טובא לדינא ע\"ש באריכות:"],"r":["\u0003וי\"א כו'. \u0004 תוס' ד\"ה כגון כו' מדדחיק לאוקמי בב' תנאי. ורמב\"ם ס\"ל כפירש\"י שם:"]}],["שְׁנֵי שְׁוָרִים תַּמִּים שֶׁחָבְלוּ זֶה בָזֶה, מְשַׁלְּמִים בַּמּוֹתָר חֲצִי נֶזֶק. כְּגוֹן אִם אֶחָד הִזִּיק בַּחֲבֵרוֹ שָׁוֶה ק', וְהַשֵּׁנִי הִזִּיק שָׁוֶה נ', \u0010y0\u0011 יָצְאוּ חֲמִשִּׁים בַּחֲמִשִּׁים, וְהַנ' הַנּוֹתָרִים יְשַׁלֵּם לוֹ חֶצְיָם. \u0005וַאֲפִלּוּ נֶאֱבַד הָאֶחָד. \u0010y1\u0011 וְדַוְקָא שֶׁשָּׁוֶה כָּל אֶחָד דְּמֵי נִזְקוֹ; אֲבָל אִם אֵינוֹ שָׁוֶה כָּל כָּךְ, אֵינוֹ מְנַכֶּה לוֹ רַק מַה שֶּׁיּוּכַל לִגְבּוֹת מִגּוּפוֹ (נִמּוּקֵי יוֹסֵף שם)\u0006. וְאִם שְׁנֵיהֶם מוּעָדִים, מְשַׁלְּמִים בַּמּוֹתָר נֶזֶק שָׁלֵם. וְאִם הָיָה אֶחָד תָּם וְאֶחָד מוּעָד, מוּעָד בְּתָם, שֶׁהִזִּיק הַמּוּעָד לַתָּם יוֹתֵר מִמַּה שֶׁהִזִּיקוֹ, יְשַׁלֵּם בַּמּוֹתָר נֶזֶק שָׁלֵם. \u0010y2\u0011 כְּגוֹן אִם הִזִּיק מוּעָד בְּתָם מֵאָה, וְהַתָּם לֹא הִזִּיקוֹ אֶלָּא נ', מְשַׁלֵּם לוֹ ע\"ה. תָּם בְּמוּעָד יְשַׁלֵּם לוֹ חֲצִי נֶזֶק, כְּגוֹן שֶׁהִזִּיק תָּם בְּמוּעָד ק', וְהַמּוּעָד לֹא הִזִּיקוּ אֶלָּא כ\"ה, מְשַׁלֵּם לוֹ כ\"ה. \u0005הַגָּה: \u0010y3\u0011 יֵשׁ אוֹמְרִים דְּכָל זֶה מַיְרֵי דַּוְקָא שֶׁהִתְחִילוּ בְּבַת אַחַת, \u0010y4\u0011 אוֹ לְאַחַר שֶׁנִּפְרְדוּ זֶה מִזֶּה חָזַר הַשֵּׁנִי וְחָבַל בָּרִאשׁוֹן; אֲבָל אִם אֶחָד הִתְחִיל, הַמַּתְחִיל מְשַׁלֵּם וְהַשֵּׁנִי פָּטוּר, דְּכָל הַמְשַׁנֶּה וּבָא אַחֵר וְשִׁנָּה (בּוֹ)\u0006 פָּטוּר \u0005(טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. וְכֵן הוּא לְקַמָּן סִימָן תכ\"א סָעִיף י\"ג לְעִנְיַן שְׁנֵי אֲנָשִׁים שֶׁחָבְלוּ זֶה בָזֶה. \u0010c0\u0011 וְהַמְחַבֵּר שֶׁפָּסַק כָּאן כְּמִי שֶׁחוֹלֵק, וּסְבִירָא לֵהּ שֶׁאֵין לְחַלֵּק, וּלְקַמָּן פָּסַק כְּמוֹ שֶׁכָּתַבְתִּי, לֹא כִּוֵּן יָפֶה:",["\u0003יצאו חמשים בחמשים כו'. \u0004 ונ\"מ אם נאבד האח' וכמ\"ש מור\"ם על זה דה\"א כיון דהשור תם אינו משלם אלא מגופו נמצא שור של ראובן שנגח שור של שמעון והפסידו מנה ואח\"כ חזר שור של שמעון ונגח לשור של ראובן שוה מנה והפסידו חמשים ונאבד שור של שמעון אח\"כ ה\"א דראובן יפסיד הזיקו שאין לו מקום לגבות ושמעון יגבה חמשים זוז משורו של ראובן קמ\"ל דלא אלא מיד שהזיקו זא\"ז מנכין זא\"ז בכדי שווים דמי ההזיק והמותר משלם ח\"נ א\"נ קמ\"ל אע\"ג דשור אח' יפה למכור מהשני וה\"א כיון דקי\"ל דגובין וחוזרין וגובין לשני בעלי חובות שחייבין זה לזה היכא שיש להן נ\"מ כגון שיש לאח' עידית ובינונית ולהשני זיבורית וכמ\"ש הטור והמחבר לעיל סימן פ\"ה ס\"ג ה\"נ יגבה כ\"א דמי נזקו מהמזיק קמ\"ל כיון דהניזק משלם ממיטב זהו מיטב שלו שיעמוד כל אחד בשלו כ\"כ הנ\"י ועפ\"ר והאי טעמא בתרא שייך בשני מועדים דהן גובין מעידית שיש למזיק ולא בתמין וטעם הראשון שייך דוקא בשני תמין דהן משלמין דוקא מגופן וכן בשני' שחבלו זה בזה דנשנה שם במשנ' עמהן דמשלמין במותר נ\"ש וכתבו הטור והמחבר לקמן בסי' תכ\"א ס\"ג שייך בו ג\"כ טעם בתרא וק\"ל ולא כע\"ש שכ' דה\"ט דמנכין זה כנגד זה משום דאפוכי מטרת' ל\"ל דז\"א אלא אף אם יש בו נ\"מ לא' בגביות כל אחד מחבירו לא שמעינן ליה ומטעם שכתבתי:","\u0003ודוקא ששוה כל א' כו'. \u0004 כ\"כ הנ\"י פ' המניח (בדפוס גדול דף י\"ז ע\"א) ז\"ל וראוי שתדע דכי אמרינן דמשלמין במותר ח\"נ דוקא במאי דיכלו לאשתלומי מיניה אהדדי אבל שור שוה ר' שנגח לשור שוה מנה והכחישו פ' זוז וחזר האחרון ונגח להראשון והכחישו מנה אם נאמר נוציא מ' שהוא ח\"נ שחייב הראשון כנגד מ' מחמשים שחייב האחרון וגובה הראשון מהאחרון י' דינרים במותר ח\"נ לקתה מדין שהרי האחרון שהכחיש להראשון מנה אינו שוה אלא ך' ואין להראשון להשתלם אלא מגופו והראשון שחייב להאחרון נ' זוז עדיין שוה מנה ויכול להשתלם ממנו לפיכך דין הוא בזה שנוציא ך' כנגד ך' שהוא שיעור מה דאית להו לאשתלומי מהדדי ויגבה האחרון מהראשון ך' זוז שהוא מותר מ' מחצי נזק שלו ונמצא דפעמים הניזק מועד גובה יותר מחביריו שנזקו מרוב' עכ\"ל:","\u0003כגון אם הזיק מועד בתם ק' כו' \u0004 כ\"כ ג\"כ בטור ושם בפריש' כתבתי דהי' יכול לומר כגון דגם המועד לא הזיקו אלא נ' אפ\"ה משלם המועד במותר כ\"ה אח' שניכה כ\"ה דח\"נ דתם נגד כ\"ה מנ' דמועד ולא נקט שהזיק ק' אלא אגב שהוצרך לכתוב כן לשטת פירש\"י דכתב הרא\"ש והטור משמו דהיכי דהתחילו התם והמועד יחד דגם התם משלם נ\"ש ע\"ש ועפ\"ר:","\u0003י\"א דכל זה כו' עד והמחבר שפסק כאן כמי שחולק כו' \u0004 עד\"ר שם כתבתי דלעד\"נ דלית פלוגתא בזה דכ\"ע ס\"ל דאם לא התחילו יחד אלא שחזר ונגח קודם שנח רוגזו דהשני פטור וכמ\"ש הטור בשם הרא\"ש כן בלי חולק עליו בב' מקומות בשור ובאדם ול\"פ ר\"י אפירש\"י אלא במ\"ש רש\"י דאם התחילו כא' והי' א' תם וא' מועד דמשלם תם כמועד נ\"ש דבזה ס\"ל לר\"י דאפילו התחילו יחד אינו משלם התם אלא ח\"נ והמחבר לא הזכיר דעת רש\"י כלל לא כאן בשוורים ולא בסימן תכ\"א באדם אלא ס\"ל פשוט כר\"י והחילוק שכתב הרא\"ש בין החחילו יחד או לא כתבו המחבר בסימן תכ\"א וה\"ה כאן בשוורים דמ\"ש זה או זה ומ\"ש מור\"ם כאן החילוק דבין התחילו יחד בשם י\"א לא דק גם בזה כי אין פלוגתא בזה וכמ\"ש וחדא באידך תליא דמשום דעלה בדעת מור\"ם דפליגי וכתבו בשם י\"א הוא הגורם לכתוב אהמחבר דלא כוון יפה ודו\"ק:","\u0003או לאחר שנפרדו כו'. \u0004 יחזר השני וחבל כו' דאז הוי השני ג\"כ כהתחל' חדשה משא\"כ אם חבל השני בראשון קודם שנפרדו וז\"ש מור\"ם אבל אם א' התחיל כו':"],["\u0003 והמחבר שפסק כאן כמי שחולק כו'. \u0004 ונוסחת הטור שלפנינו גרם למור\"ם לכתוב כן והנוסחא הנכונה עיין ביש\"ש פ\"ג סי' כ\"ו והב\"ח לא הרגיש בזה ולכן הגיה נוסחא המוטעת וגם הסמ\"ע לא הזכירה ומ\"מ כוון כהלכה בדעת הרא\"ש וכן הוא ברמזים והוא ע\"פ נוסחת מהרש\"ל וק\"ל:"],"\u0010g0\u0011 שְׁנֵי שְׁוָרִים תַּמִּים שֶׁחָבְלוּ זֶה בָזֶה, מְשַׁלְּמִים בַּמּוֹתָר חֲצִי נֶזֶק. כְּגוֹן אִם אֶחָד הִזִּיק בַּחֲבֵרוֹ שָׁוֶה ק', וְהַשֵּׁנִי הִזִּיק שָׁוֶה נ', \u0010y0\u0011 יָצְאוּ חֲמִשִּׁים בַּחֲמִשִּׁים, וְהַנ' הַנּוֹתָרִים יְשַׁלֵּם לוֹ חֶצְיָם. \u0010t0\u0011 \u0010r0\u0011 \u0005וַאֲפִלּוּ נֶאֱבַד הָאֶחָד. \u0010y1\u0011 \u0010r1\u0011 וְדַוְקָא שֶׁשָּׁוֶה כָּל אֶחָד דְּמֵי נִזְקוֹ; אֲבָל אִם אֵינוֹ שָׁוֶה כָּל כָּךְ, אֵינוֹ מְנַכֶּה לוֹ רַק מַה שֶּׁיּוּכַל לִגְבּוֹת \u0010t1\u0011 מִגּוּפוֹ (נִמּוּקֵי יוֹסֵף שם)\u0006. \u0010g1\u0011 וְאִם שְׁנֵיהֶם מוּעָדִים, מְשַׁלְּמִים בַּמּוֹתָר נֶזֶק שָׁלֵם. וְאִם הָיָה אֶחָד תָּם וְאֶחָד מוּעָד, מוּעָד בְּתָם, שֶׁהִזִּיק הַמּוּעָד לַתָּם יוֹתֵר מִמַּה שֶׁהִזִּיקוֹ, יְשַׁלֵּם בַּמּוֹתָר נֶזֶק שָׁלֵם. \u0010y2\u0011 \u0010g2\u0011 \u0010r2\u0011 כְּגוֹן אִם הִזִּיק מוּעָד בְּתָם מֵאָה, וְהַתָּם לֹא הִזִּיקוֹ אֶלָּא נ', מְשַׁלֵּם לוֹ ע\"ה. תָּם בְּמוּעָד יְשַׁלֵּם לוֹ חֲצִי נֶזֶק, כְּגוֹן שֶׁהִזִּיק תָּם בְּמוּעָד ק', וְהַמּוּעָד לֹא הִזִּיקוּ אֶלָּא כ\"ה, מְשַׁלֵּם לוֹ כ\"ה. \u0005הַגָּה: \u0010y3\u0011 \u0010r3\u0011 יֵשׁ אוֹמְרִים דְּכָל זֶה מַיְרֵי דַּוְקָא שֶׁהִתְחִילוּ בְּבַת אַחַת, \u0010y4\u0011 אוֹ לְאַחַר שֶׁנִּפְרְדוּ זֶה מִזֶּה חָזַר הַשֵּׁנִי וְחָבַל בָּרִאשׁוֹן; אֲבָל אִם אֶחָד הִתְחִיל, הַמַּתְחִיל מְשַׁלֵּם וְהַשֵּׁנִי פָּטוּר, דְּכָל הַמְשַׁנֶּה וּבָא אַחֵר וְשִׁנָּה (בּוֹ)\u0006 פָּטוּר \u0005(טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. וְכֵן הוּא לְקַמָּן סִימָן תכ\"א סָעִיף י\"ג לְעִנְיַן שְׁנֵי אֲנָשִׁים שֶׁחָבְלוּ זֶה בָזֶה. \u0010c0\u0011 \u0010r4\u0011 וְהַמְחַבֵּר שֶׁפָּסַק כָּאן כְּמִי שֶׁחוֹלֵק, וּסְבִירָא לֵהּ שֶׁאֵין לְחַלֵּק, וּלְקַמָּן פָּסַק כְּמוֹ שֶׁכָּתַבְתִּי, \u0010g3\u0011 לֹא \u0010t2\u0011 כִּוֵּן יָפֶה:",{"g":["א) ל' הטור וכ\"כ הרמב\"ם בספ\"ט מהלכות נזקי ממון משנה פ\"ג דב\"ק דף ל\"ג ע\"א","ב) שם במשנה","ג) טור בשם ר\"י וכתב הב\"י שכ\"נ מדברי הרמב\"ם שם בפ\"ט והכי נקטינן","\u0003ד) ולענ\"ד יש לחלק בזה דהכא חייבו הרא\"ש מטעם כל המשנה ובא וכו'\u0004 ובזה לא סבירא ליה כוותיה אבל התם בסימן תכ\"א גבי ב' אנשים ביאר הרא\"ש הטעם משום שיש לשני רשות לחבול בו כדי להציל עצמו ואפי' בזה צריך אומד אם היה יכול להציל עצמו בחבל' מועטת משלם המותר וענין הצלה זו אינו שייך בשוורים והסמ\"ע כ' בענין אחר והמעיין יבחר ואכמ\"ל:"],"t":["\u0003נאבד. \u0004 פי' דל\"ת כיון דתם אינו משלם אלא מגופו נמצא שור של ראובן שנגח שור של שמעון והפסידו ק' ואח\"כ חזר שור של שמעון ונגח שור של ראובן והפסידו נ' ונאבד שור של שמעון וה\"א דראובן יפסיד הזיקו שאין לו מקום לגבות ושמעון יגבה נ' משורו דראובן קמ\"ל דלא אלא מיד שהזיקו זא\"ז מנכין זא\"ז בכדי שיווי דמי ההיזק והמותר משלם ח\"נ. סמ\"ע:","\u0003מגופו. \u0004 ז\"ל הנ\"י פרק המניח וראוי שתדע דכי אמרינן דמשלמין במותר ח\"נ דוקא במאי דיוכלו לאשתלומי מיניה אהדדי אבל שור שוה ר' שנגח לשור שוה ק' והכחישו פ' וחזר האחרון ונגח להראשון והכחישו ק' אם נאמר נוציא מ' שהוא ח\"נ שחייב הראשון כנגד מ' מנה שחייב האחרון וגובה הראשון מהאחרון י' במותר ח\"נ לקתה מדת הדין שהרי האחרון שהכחיש להראשון ק' אינו שוה אלא כ' ואין להראשון להשתלם אלא מגופו והראשון שחייב להאחרון נ' עדיין שוה ק' ויכול להשתלם ממנו לפיכך דין הוא בזה שנוציא כ' כנגד כ' שהוא שיעור מאי דאית להו לאשתלומי מהדדי ויגבה האחרון מהראשון כ' שהוא מותר מח\"נ שלו ונמצא דפעמי' הניזק מועט גובה יותר מחבירו שנזקו מרובה עכ\"ל. שם:","\u0003יפה. \u0004 עמ\"ש הסמ\"ע והש\"ך ליישב דברי המחבר בזה ע\"ש:"],"r":["\u0003ואפי' כו'. \u0004 תוס' ד\"ה שנו כו' ואפי' לר\"י נ\"מ כו' וכ\"כ נ\"י ואף לר\"ע:","\u0003ודוקא כו'. \u0004 עסמ\"ע וכמ\"ש בכתובות קי א' רמי ב\"ח אמר הכא כו' ואף לרבא שם דקאמר ליגבינהו כו' כאן ל\"ל דאין גובה אלא מגופו:","\u0003כגון אם הזיק כו'. \u0004 טור לאפוקי ממ\"ש הרא\"ש בשם רש\"י:","\u0003י\"א כו' דכל כו'. \u0004 כמ\"ש כ\"ד ב' וכמו בעטה מהלכת ברבוצה שר\"ל ואף רבא ל\"פ אלא משום דא\"ל כי אית לך כו' ואפי' באדם יש לו רשות בכה\"ג דהא אפילו על עסקי ממון אמרינן ברפ\"ג מאה פנדי כו' ואע\"ג דלא שייך באדם כל המשנה כו' ועתוס' ד\"ז ב' ד\"ה ה\"ג כו' והג\"א שם ד\"ה והא כו' כ\"ש בשור וז\"ש וכ\"ה לקמן כו' ועמש\"ש:","\u0003והמחבר כו'. \u0004 דברי הרב תמוהין כי אין חולק ע\"ז והמחבר לא הזכיר כלום מזה וסמך אמ\"ש בסי' תנא וגרם לו דברי הטור שכ' וכ' א\"א הרא\"ש ז\"ל דמיירי דוקא שהתחילו בבת אחת כו' וכ' עוד היכא שהתחילו כאחד גם התם משלם נ\"ש כמו המועד כך דקדק מדברי רש\"י ואין דעת ר\"י כן אלא בין שהתחילו בב\"א בין שהתחילו זא\"ז נפרעין כמו שפי' תחלה מ' דר\"י חולק גם ארישא וס\"ל להרב דהא בהא תליא דהא לא מצינו לר\"י שחולק ע\"ז וז\"ש והמחבר כו' ר\"ל כיון שפי' כפי' ר\"י במתני' כנ\"ל שכ' כגון אם הזיק כו' ה\"ה באידך ס\"ל כר\"י. אבל ליתא דר\"י אין חולק ע\"ז וגם אינו מדברי רש\"י וט\"ס הוא בטור כמ\"ש יש\"ש שמ\"ש בין שהתחילו כו' עד בזא\"ז ט\"ס:"]}],["שָׁמִין הַשְּׁבָרִים בִּנְזִיקִים. אִם שָׁבַר כְּלִי הוּא אוֹ בְּהֶמְתּוֹ אֵין אוֹמְרִים: יִתֵּן לוֹ כְּלִי שָׁלֵם וְיִקַּח הַשְּׁבָרִים, \u0010y0\u0011 אֶלָּא שָׁמִין כַּמָּה נִפְחֲתוּ דָּמָיו בִּשְׁבִיל הַשְּׁבִירָה, וְיִקַּח הַנִּזָּק הַשְּׁבָרִים, וְהַמַּזִּיק יַשְׁלִים עֲלֵיהֶם.\nפְּחַת הַנְּבֵלָה לַנִּזָּק, וּשְׁבַח הַנְּבֵלָה חוֹלְקִים אוֹתוֹ הַמַּזִּיק וְהַנִּזָּק. כֵּיצַד, שׁוֹר שָׁוֶה מָאתַיִם שֶׁנְּגָחוּהוּ וּמֵת, וַהֲרֵי הַנְּבֵלָה שָׁוָה בִּשְׁעַת מִיתָה מֵאָה, וּבִשְׁעַת הַעֲמָדָה בַּדִּין פָּחֲתָה וַהֲרֵי שָׁוָה פ', אֵין הַמַּזִּיק מְשַׁלֵּם אֶלָּא ק'. וְאִם הָיָה תָּם, מְשַׁלֵּם לוֹ נ' מִגּוּפוֹ. \u0010y1\u0011 \u0005(נ\"י)\u0006 \u0005וְדַוְקָא שֶׁנּוֹדַע לַנִּזָּק בִּשְׁעַת מִיתָה, אֲבָל אִם לֹא נוֹדַע לוֹ, הַפְּחָת עַל הַמַּזִּיק עַד \u0010y2\u0011 שֶׁיִּוָּדַע לַנִּזָּק. וְיֵשׁ אוֹמְרִים דְּהוּא הַדִּין אִם הוּזְלָה\u0006 \u0005(טוּר ס\"ח)\u0006. \u0005וְיֵשׁ חוֹלְקִין דִּבְזוֹלָא \u0010y3\u0011 אַף עַל גַּב דְּלָא נוֹדַע לֵהּ הָוֵי שֶׁל נִזָּק\u0006 \u0005(נִמּוּקֵי יוֹסֵף פֶּרֶק הנ\"ל)\u0006. הִשְׁבִּיחָה הַנְּבֵלָה וַהֲרֵי הִיא שָׁוָה בִּשְׁעַת הַעֲמָדָה בַדִּין ק\"כ, הֲרֵי הַמַּזִּיק מְשַׁלֵּם תִּשְׁעִים. \u0010y4\u0011 וְאִם הָיָה תָּם, מְשַׁלֵּם מ\"ה מִגּוּפוֹ, \u0010y5\u0011 וְזֶהוּ וְגַם אֶת הַמֵּת יֶחֱצוּן. \u0005הַגָּה: מִיהוּ, אִם הִשְׁבִּיחָה כָּל כָּךְ עַד שֶׁחֲצִי שֶׁבַח הוּא יוֹתֵר מִדְּמֵי \u0010y6\u0011 הַהֶזֵּק, לָא אָמְרִינָן דְּהַמַּזִּיק יִטּוֹל חֲצִי הַשֶּׁבַח וְיַרְוִיחַ (טוּר)\u0006. \u0010y7\u0011\nעַל הַמַּזִּיק לִטְרֹחַ בַּנְּבֵלָה עַד שֶׁמַּמְצִיא אוֹתוֹ לַנִּזָּק. כֵּיצַד, כְּגוֹן שֶׁנָּפַל הַשּׁוֹר לְבוֹר וָמֵת, מַעֲלֶה הַנְּבֵלָה מֵהַבּוֹר וְנוֹתְנָהּ לַנִּזָּק, וְאַחַר כָּךְ שָׁמִין לוֹ פְּחַת נְבֵלָה. שֶׁנֶּאֱמַר: כֶּסֶף יָשִׁיב לִבְעָלָיו וְהַמֵּת יִהְיֶה לוֹ, מְלַמֵּד, שֶׁהוּא חַיָּב לְהָשִׁיב אֶת הַנְּבֵלָה וְאֶת הַפְּחָת שֶׁפָּחֲתָה מִן הַחַי לַנִּזָּק; וְאִם הָיָה תָם, חֲצִי הַפְּחָת:",["\u0003אלא שמין כמה נפחתו כו'. \u0004 וכ\"כ הטור והמחבר הדין בשואל בסי' שמ\"ד וסי' שפ\"ז כתבו הטור בדין ניזק משא\"כ בגנב וגזלן וכמ\"ש בטור והמחבר בסי' שנ\"ד ושס\"ב והטעה כתבתי שה דכתיב והשיב את הגזלה אשר גזל ודרשינן כאשר גזל וגם בגניבה דרשינן אחיי' לגניבתו אבל בניזק כתבה התורה ישיב ודרשינן מיניה דכשבא לשלם במטלטלין דיכול לשלם בכל מה דיכול להשיב אפילו סובין וכמ\"ש בסי' תי\"ט ע\"ש:","\u0003ודוקא שנודע לניזק כו'. \u0004 פי' דאז ה\"ל לניזק לטפל במכירת הנבילה קודם שנסרח' ונפחתה מדמי' ואפילו נפלה לבור דעל המזיק מוטל להעלותה ולמסרה להניזק בדמי שווי' וכמ\"ש הטור והמחבר בסמוך בס\"ג היינו שהמזיק מחויב ליתן הוצאת שצריכין ליתן להמעלין מהבור אבל הטפול להשתדל להעלותה מוטל על הניזק וחוזר ולוקח ההוצאה מהמזיק וכ\"כ בטור ובב\"י שהוא הסכמת הפוסקים:","\u0003אם הוזלה \u0004 פי' שלא נפחתה הנבילה מצד עצמה ממה שהיתה בשעת מיתה אלא שהוזל הבשר:","\u0003אע\"ג דלא נודע לו. \u0004 דבזול אין נ\"מ בידיעתו דדוקא בנפחתה מחמת סרחון דרגיל להיות מחמת שהיי' אמרינן אלו ידע ודאי היה מטפל בה למכרה משא\"כ בזולא דלא עלתה על דעתו שיזול:","\u0003ואם הי' תם משלם מ\"ה. \u0004 דלעולם שמין הריוח לפי השומא שהיה שוה מתחלה ומתחלה היה שוה ר' ובאותן ר' משותף המזיק בשור הניזק ברביעית דהיינו נ' כיון שהוא תם לכך אינו נוטל אלא הרביעית בהריוח:","\u0003וזהו וגם את המת יחצון. \u0004 ר\"ל שבח המת יחצון (וכ\"ה בהדיא שם ברמב\"ם) וילפינן מיתורא דוגם דהמ\"ל ואת המת יחצון ואף על גב דאין להמזיק אלא בפחת כנ\"ל יש לו חלק בהריוח דהתורה חס על המזיק כיון שהוא עצמו לא הזיק אלא שורו:","\u0003לא אמרינן דהמזיק יטול חצי השבח וירויח. \u0004 עפ\"ר ודרישה שם כתבתי והוכחתי דאף דאז אין נוטל חלק בהשבח מ\"מ פטור הוא ג\"כ מלשלם להניזק מה שהזיק שורו דהיינו שור ששוה ה' סלעים שנגח לשור ששוה חמשה סלעים ובשעה שנודע לו לא היתה שוה אלא ג' סלעים ואח\"כ השביחה עד ששוה ל' זוז דהיינו ו' סלעים כיון דהשתא אחר שהשביח אין לו הפסד ול\"ד למ\"ש הטור והמחבר בר\"ס שאחר זה דאם נגח השור והפחיתו ועדיין הוא חי והשביח עד ששוה כפל ממה שהי' מתחל' דאפ\"ה משלם לו היזק כמו שהי' בשעת הנגיחה דשאני התם דמצי הניזק למימר לולי שנגחוהו שורך היה ריוח זה דנעשית שומן גדולה כפל ממה שהוא עתה שכן דרך הטבע שבהמה חיה נשבחת בשומן וגידול וכשהיא אינה נגוח' נשבחת יותר מנגוח' וחולה משא\"כ כאן בנבילה דאף דנתיקר הבשר הוא דבר שאינו מצוי ותלוי במזל ואין לו' אלו לא המיתו היה נתיקר בכפלים דיכול להיות דבמזלו נתיקר:","\u0003על המזיק לטרוח כו'. \u0004 כבר כתבתי דעל הניזק להעלותו מהבור עד שנודע לו שנפלה שם ונוטל דמי הוצאותיו של העלי' מהמזיק ואם לא עשה כן ונפסד השור בהבור דהוא פסידא דהניזק. וכ\"כ הטור בהדיא וכתב הב\"י שהוא הסכמת הפוסקי' וכאן למדונו דאם לא ירצה המזיק להעלותו ולא ליתן לו הוצאה להעלותו דצריך ליתן דמים שכל חציו דהפחת אם הוא תם ואם הוא מועד צריך לשלם דמי כל הפחת מאשר היה שוה כשהי' חי וכן משמעות הקרא כסף ישיב לבעליו והמת שגם המת ישיב המזיק ויתנהו לידו דניזק ואז יהי' לו המת בתשלומי דמי נזקו והמותר עד כדי נזקו ישלם לו בכסף אם נפל לבורו דפסוק זה בנפל לבורו כתיב וה\"ה לשור מועד שנגח וק\"ל:"],[],"שָׁמִין \u0010g0\u0011 \u0010t0\u0011 \u0010r0\u0011 הַשְּׁבָרִים בִּנְזִיקִים. אִם שָׁבַר כְּלִי הוּא אוֹ בְּהֶמְתּוֹ אֵין אוֹמְרִים: יִתֵּן לוֹ כְּלִי שָׁלֵם וְיִקַּח הַשְּׁבָרִים, \u0010y0\u0011 אֶלָּא שָׁמִין כַּמָּה נִפְחֲתוּ דָּמָיו בִּשְׁבִיל הַשְּׁבִירָה, וְיִקַּח הַנִּזָּק הַשְּׁבָרִים, וְהַמַּזִּיק יַשְׁלִים עֲלֵיהֶם. \u0010g1\u0011\nפְּחַת \u0010g2\u0011 הַנְּבֵלָה לַנִּזָּק, וּשְׁבַח הַנְּבֵלָה חוֹלְקִים אוֹתוֹ הַמַּזִּיק וְהַנִּזָּק. כֵּיצַד, שׁוֹר שָׁוֶה מָאתַיִם שֶׁנְּגָחוּהוּ וּמֵת, וַהֲרֵי הַנְּבֵלָה שָׁוָה בִּשְׁעַת מִיתָה מֵאָה, וּבִשְׁעַת הַעֲמָדָה בַּדִּין פָּחֲתָה וַהֲרֵי שָׁוָה פ', אֵין הַמַּזִּיק מְשַׁלֵּם אֶלָּא ק'. וְאִם הָיָה תָּם, מְשַׁלֵּם לוֹ נ' מִגּוּפוֹ. \u0010y1\u0011 \u0005(נ\"י)\u0006 \u0010r1\u0011 \u0005וְדַוְקָא שֶׁנּוֹדַע לַנִּזָּק בִּשְׁעַת מִיתָה, \u0010g3\u0011 אֲבָל אִם לֹא נוֹדַע לוֹ, הַפְּחָת עַל הַמַּזִּיק עַד \u0010y2\u0011 \u0010r2\u0011 שֶׁיִּוָּדַע לַנִּזָּק. וְיֵשׁ אוֹמְרִים דְּהוּא הַדִּין אִם \u0010t1\u0011 הוּזְלָה\u0006 \u0005(טוּר ס\"ח)\u0006. \u0010r3\u0011 \u0005וְיֵשׁ חוֹלְקִין דִּבְזוֹלָא \u0010y3\u0011 אַף עַל גַּב דְּלָא \u0010t2\u0011 נוֹדַע לֵהּ הָוֵי שֶׁל \u0010g4\u0011 נִזָּק\u0006 \u0005(נִמּוּקֵי יוֹסֵף פֶּרֶק הנ\"ל)\u0006. הִשְׁבִּיחָה הַנְּבֵלָה וַהֲרֵי הִיא שָׁוָה בִּשְׁעַת הַעֲמָדָה בַדִּין ק\"כ, הֲרֵי הַמַּזִּיק מְשַׁלֵּם תִּשְׁעִים. \u0010y4\u0011 וְאִם הָיָה תָּם, מְשַׁלֵּם \u0010t3\u0011 מ\"ה מִגּוּפוֹ, \u0010y5\u0011 וְזֶהוּ וְגַם אֶת הַמֵּת יֶחֱצוּן. \u0005הַגָּה: \u0010r4\u0011 מִיהוּ, אִם הִשְׁבִּיחָה כָּל כָּךְ עַד שֶׁחֲצִי שֶׁבַח הוּא יוֹתֵר \u0010r5\u0011 מִדְּמֵי \u0010y6\u0011 הַהֶזֵּק, לָא אָמְרִינָן דְּהַמַּזִּיק יִטּוֹל חֲצִי הַשֶּׁבַח \u0010t4\u0011 וְיַרְוִיחַ \u0010g5\u0011 (טוּר)\u0006. \u0010y7\u0011 \u0010g6\u0011 \u0010r6\u0011\nעַל הַמַּזִּיק לִטְרֹחַ בַּנְּבֵלָה עַד שֶׁמַּמְצִיא אוֹתוֹ לַנִּזָּק. כֵּיצַד, כְּגוֹן שֶׁנָּפַל הַשּׁוֹר לְבוֹר וָמֵת, מַעֲלֶה הַנְּבֵלָה מֵהַבּוֹר וְנוֹתְנָהּ לַנִּזָּק, וְאַחַר כָּךְ שָׁמִין לוֹ פְּחַת \u0010g7\u0011 נְבֵלָה. שֶׁנֶּאֱמַר: כֶּסֶף יָשִׁיב לִבְעָלָיו וְהַמֵּת יִהְיֶה לוֹ, מְלַמֵּד, שֶׁהוּא חַיָּב לְהָשִׁיב אֶת \u0010r7\u0011 הַנְּבֵלָה וְאֶת הַפְּחָת \u0010r8\u0011 שֶׁפָּחֲתָה מִן הַחַי לַנִּזָּק; וְאִם הָיָה תָם, חֲצִי הַפְּחָת:",{"g":["א) לשון הטור וכן כ' הרמב\"ם בפ\"ז מה' נזקי ממון ד\"ח מימרא דשמואל פ\"ק דב\"ק דף י\"א ע\"א","ב) ל' הרמב\"ם שם דין ח' וט' שם סוף דף י' דריש לה מקרא והסכמות הגמרא ריש דף י\"א לא דכ\"ע וכו'","ג) פלוגתא דר' מאיר ור' יהודה שם בפ\"ג דל\"ד ע\"א וכאוקימתא דר' יוחנן שם ע\"ב ופסקו הפוסקים הלכה כרבי יהודה","ד) אף ע\"פ שעל המזיק מוטל טורח הנבילה להעלותה וליתנה לניזק כדלקמן מ\"מ משנודע לו לניזק היה לו להשתדל בו ולהעלותו ולא להשהות' שהרי ידע שכלה ונפסדת אלא היה לו למכור לאלתר ועל המזיק ליתן לו ההוצא'","ה) שם דין י' מבואר במ\"ש","ו) שם כאוקימת' דר\"י","ז) שהדין י\"ג ושם בגמרא ריש דף י\"א פלוגתא דתנאי ופסקו הפוסקים כאבא שאול דטורח נבילה על המזיק","\u0003ח) שם ברייתא משמיה דאחרים:\u0004 "],"t":["\u0003השברים. \u0004 דבניזק כתבה התורה ישיב ודרשינן מיניה דכשבא לשלם במטלטלים דיכול לשלם אפילו סובין וכמ\"ש בסי' תי\"ט וע\"ל סי' שמ\"ד ס\"ב וסי' שפ\"ז. סמ\"ע:","\u0003הוזלה. \u0004 פי' שלא נפחתה הנבלה מצד עצמה ממה שהיתה בשעת מיתה אלא שהוזל הבשר. שם:","\u0003נודע. \u0004 דבזול אין נ\"מ בידיעתו דלא עלתה על דעתו שיוזל. שם:","\u0003מ\"ה. \u0004 דלעולם שמין הריוח לפי השומא שהיה שוה מתחלה וזה היה שוה ר' מתחלה ובאותן ר' משותף המזיק בשור הניזק ברביעית דהיינו נ' כיון שהוא תם לכך אינו נוטל אלא הרביעית בהריוח. שם:","\u0003וירויח. \u0004 ומ\"מ פטור הוא מלשלם מה שהזיק שורו ול\"ד למ\"ש הט\"ו בר\"ס שאח\"ז ע\"ש דהתם מצי הניזק לו' אלמלי הנגיחה כו' שכן דרך הבהמה דנשבחת בשומן וגידול כשהיא חיה ובריאה בלא נגיחה יותר ממה שהיא נגוחה וחולה משא\"כ כאן בנבלה דנתייקר הבשר שהוא דבר שאינו מצוי ותלוי במזל ואין יכול לומר אילו לא המיתו היה נתייקר בכפלים די\"ל דבמזלו נתייקר. שם:"],"r":["\u0003אם כו' או כו'. \u0004 שם:","\u0003ודוקא כו'. \u0004 הרא\"ש שם דהטעם ע\"כ משום פשיעותא דניזק דהא בשבחא חולקים שם ואינו מוכרח דפלגא שנוטל המזיק משום דחס רחמנא עליה כמש\"ש והיינו דהא קשיא כו' וכ\"ת כו' אבל ל\"ל חלק בנבילה כלום וכן כאן חס רחמנא וכ\"ש שגוף שלו מדינא ועיש\"ש שחולק ע\"ז:","\u0003וי\"א כו'. \u0004 כנ\"ל:","\u0003וי\"ח כו'. \u0004 עסמ\"ע וכ' שם דלא גרע מגזלן דהגזילה חוזרות בעיניה ע\"ש:\n\u0003 (ליקוט) ודוקא כו'. \u0004 ל\"ד א' דא\"ל קרנא כו' וכ' הרשב\"א וא\"ת מ\"ש מפחת נבילה לא היא דשאני התם דה\"ל לזבונה מיד דאין דרך להמתין על הנבילה אבל דרך הניזקין להמתין עד שיתרפאו וישביחו ר\"ל בלא מתה וז\"ש וי\"א דה\"ה כו' ג\"כ מזה הטעם אבל הרמ\"ה כ' דהטעם דה\"ל לאסוקי אדעתיה שתסרחה משא\"כ שם וה\"ה בהוזלה וז\"ש וי\"ח כו' ועסמ\"ע (ע\"כ):\n\u0003 (ליקוט) ודוקא כו'. \u0004 עתוס' שם ד\"ה לא נצרכא כו' משא\"כ אם לא נודע דאמרינן קרנא דתורא כו' וז\"ש וי\"ח כו' דלא שייך קרנא כו' (ע\"כ):","\u0003מיהו כו'. \u0004 שם וכ\"ת ה\"מ כו':","\u0003מדמי. \u0004 ר\"ל ח\"נ:","\u0003על כו'. \u0004 פ' כאבא שאול משום דאחרים ס\"ל כוותיה. הרא\"ש וש\"פ:","\u0003ואת כו' ואם כו'. \u0004 ר\"ל בין בתם בין במועד כמש\"ש ט\"ו א':","\u0003מן החי. \u0004 ר\"ל משעת מיתה דלא כמ\"ש בהג\"ה בס\"ב ולשון הגמ' ל\"ד א' פחת שפחתה כו' פחת נבילה א\"ב:"]}],["שׁוֹר שְׁוֵה מָאתַיִם שֶׁנָּגַח שׁוֹר שְׁוֵה מָאתַיִם \u0010y0\u0011 וְהִפְחִיתוֹ חֲמִשִּׁים, וּבִשְׁעַת הַעֲמָדָה בַדִּין הִשְׁבִּיחַ הַנִּזָּק וַהֲרֵי הוּא שָׁוֶה ת', \u0010y1\u0011 וְאִלְמָלֵא הַנְּגִיחָה שֶׁהִפְחִיתוֹ הָיָה שָׁוֶה ת\"ת, בֵּין שֶׁפִּטְּמוֹ בֵּין שֶׁשָּׁבַח מֵאֵלָיו, אֵינוֹ נוֹתֵן אֶלָּא כִּשְׁעַת הַנֶּזֶק.\nכָּחַשׁ מֵחֲמַת הַמַּכָּה בִּשְׁעַת הַעֲמָדָה בַּדִּין, וַהֲרֵי הַפְּחָת שָׁוֶה מֵאָה, \u0010y2\u0011 נוֹתֵן לוֹ כִּשְׁעַת הַעֲמָדָה בַּדִּין. \u0010y3\u0011 הִשְׁבִּיחַ הַמַּזִּיק בִּשְׁעַת הַעֲמָדָה בַּדִּין, אִם מֵחֲמַת שֶׁפִּטְּמוֹ שָׁבַח, אֵינוֹ מִשְׁתַּלֵּם מִמֶּנּוּ אֶלָּא מַה שֶּׁהָיָה שָׁוֶה בְּשָׁעָה שֶׁהִזִּיק. \u0010y4\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּאִם הַשֶּׁבַח יֶתֶר עַל הַהוֹצָאָה נוֹטֵל הַמַּזִּיק דְּמֵי הַהוֹצָאָה וּשְׂכַר טָרְחוֹ וַעֲמָלוֹ, וּבִשְׁאָר הַשֶּׁבַח נוֹטֵל הַנִּזָּק חֶלְקוֹ (טוּר ס\"ג)\u0006. \u0010y5\u0011 וְאִם מֵחֲמַת עַצְמוֹ הִשְׁבִּיחַ, מִשְׁתַּלֵּם מִמֶּנּוּ כִּשְׁעַת הַעֲמָדָה בַדִּין:",["\u0003והפחיתו חמשים כו' \u0004 פי' ועדיין הוא חי והשביח בין הנגיח' להעמדה בדין במה שנתגדל' או השמינ':","\u0003ואלמלא הנגיחה שהפחית' כו'. \u0004 פי' ולא יכול הניזק לתובעו בעד אותו נזק כיון שאינו אלא גרמא ולא פסידא בידים מיהו צריך לשלם כשעת הנזק אע\"ג דנשבח הרבה יותר ממה שהיה שוה בשעת הנגיח' משא\"כ במת מחמת הנגיחה ונתייקר הבשר וכמ\"ש בסי' שלפני זה מילתא בטעמא ע\"ש:","\u0003נותן לו כשעת העמדה בדין. \u0004 לשון הגמ' דאמר לי' מקרנ' דתורך דקבירא בשורי המנוגח כיחש כ\"כ פי' כיון שהוא עדיין חי כאב הנגיחה הוא בו עדיין ומכח זה מכחיש ואזיל משא\"כ בסי' שלפני זה דשם מיירי דמת מיד מהנגיחה והפסידה דאח\"כ אינו מחמת כאב הנגיח':","\u0003השביח המזיק. \u0004 פי' שור המזיק:","\u0003וי\"א דאם השבח יתר על ההוצאה כו'. \u0004 בטור כתב עוד ז\"ל דאם ההוצא' יתירה על השבח אין לו לניזק בשבח כלום אלא נוטל כפי מה שמגיעו בשעת הנזק ע\"כ וכתבתי בפריש' דדוקא קאמר דאין לו בשבח כלום אבל ג\"כ א\"צ ליתן הוצאה כלום ומפסיד המזיק מה שהיתה ההוצא' יתירה על השבח וה\"ט דאף דהם שותפין בשור המזיק והשותף היורד ברשות צריך לשלם לו חצי ההוצא' מכיסו היתירה על השבח וכמ\"ש בסי' שע\"ה היינו דוקא בשותף היורד ברשות אבל זה אף דהוא כשותף מ\"מ ה\"ל כשותף היורד שלא ברשות וכמ\"ש בסי' קע\"ה ושע\"ה ע\"ש ודו\"ק:","\u0003ואם מחמת עצמו כו'. \u0004 הטעם דמיד בשעת נגיחה נעשו המזיק והניזק שותפין בהשור והוא ברשות שניהן לענין אם נפחת או נשבח ממילא משעת הנגיחה והלאה וכ\"כ בטור:"],[],"\u0010g0\u0011 שׁוֹר שְׁוֵה מָאתַיִם שֶׁנָּגַח שׁוֹר שְׁוֵה מָאתַיִם \u0010y0\u0011 וְהִפְחִיתוֹ חֲמִשִּׁים, וּבִשְׁעַת הַעֲמָדָה בַדִּין הִשְׁבִּיחַ הַנִּזָּק וַהֲרֵי הוּא שָׁוֶה ת', \u0010y1\u0011 \u0010t0\u0011 וְאִלְמָלֵא הַנְּגִיחָה שֶׁהִפְחִיתוֹ הָיָה שָׁוֶה ת\"ת, \u0010r0\u0011 בֵּין שֶׁפִּטְּמוֹ בֵּין שֶׁשָּׁבַח מֵאֵלָיו, \u0010r1\u0011 אֵינוֹ נוֹתֵן אֶלָּא כִּשְׁעַת הַנֶּזֶק. \u0010g1\u0011\nכָּחַשׁ מֵחֲמַת הַמַּכָּה בִּשְׁעַת הַעֲמָדָה בַּדִּין, וַהֲרֵי הַפְּחָת שָׁוֶה מֵאָה, \u0010y2\u0011 נוֹתֵן לוֹ כִּשְׁעַת הַעֲמָדָה בַּדִּין. \u0010y3\u0011 \u0010g2\u0011 הִשְׁבִּיחַ \u0010g3\u0011 הַמַּזִּיק בִּשְׁעַת \u0010t1\u0011 הַעֲמָדָה בַּדִּין, אִם מֵחֲמַת שֶׁפִּטְּמוֹ שָׁבַח, אֵינוֹ מִשְׁתַּלֵּם מִמֶּנּוּ אֶלָּא מַה שֶּׁהָיָה שָׁוֶה בְּשָׁעָה שֶׁהִזִּיק. \u0010y4\u0011 \u0010r2\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּאִם הַשֶּׁבַח יֶתֶר עַל הַהוֹצָאָה נוֹטֵל הַמַּזִּיק דְּמֵי הַהוֹצָאָה וּשְׂכַר טָרְחוֹ וַעֲמָלוֹ, וּבִשְׁאָר הַשֶּׁבַח נוֹטֵל הַנִּזָּק חֶלְקוֹ \u0010g4\u0011 (טוּר ס\"ג)\u0006. \u0010y5\u0011 וְאִם מֵחֲמַת \u0010t2\u0011 עַצְמוֹ הִשְׁבִּיחַ, מִשְׁתַּלֵּם מִמֶּנּוּ כִּשְׁעַת הַעֲמָדָה בַדִּין:",{"g":["\u0003א) בברייתא בפ\"ג דב\"ק דף ל\"ד ע\"א:\u0004 ","\u0003ב) שם בבריית' וכדמפרש לה רב אשי:\u0004 ","ג) שם בברייתא וכדמפ' לה ר\"פ","פי' שור המזיק","\u0003ד) כן כתבו התוספת שם.\u0004 "],"t":["\u0003ואלמלא. \u0004 פירוש ואין יכול לתובעו בעד אותו הנזק כיון שאינו אלא גרמא ולא הפסידו בידים. סמ\"ע:","\u0003בדין. \u0004 כיון שעדיין חי הוא עוד כאב הנגיחה בו ומכח זה מכחיש ואזיל. שם:","\u0003עצמו. \u0004 הטעם דמיד בשעת נגיחה נעשו המזיק והניזק שותפין בהשור והוא ברשות שניהן לענין אם נפחת או נשבח ממילא משעת הנגיחה והלאה כ\"כ הטור. שם:"],"r":["\u0003בין כו'. \u0004 שם רישא כו':","\u0003אינו כו'. \u0004 פי' כלשון אחרון של רש\"י אבל רש\"י ותוס' הסכימו ללשון ראשון ע\"ש ד\"ה שאלמלא כו':","\u0003וי\"א כו'. \u0004 תוס' ד\"ה הב\"ע כו'. והראב\"ד חולק וכ' דל\"ד לשותף דשם אדעתא דשותפותא מפטם משא\"כ כאן והרשב\"א נסתפק שם:"]}],["שׁוֹר שֶׁחָבַל בָּאָדָם, \u0010y0\u0011 אֲפִלּוּ נִתְכַּוֵּן לַבְּהֵמָה וְחָבַל בָּאָדָם, דִּינוֹ כְּדִין שׁוֹר שֶׁהִזִּיק לְשׁוֹר; תָּם מְשַׁלֵּם חֲצִי נֵזֶק, וּמוּעָד נֶזֶק שָׁלֵם, \u0010y1\u0011 וּפָטוּר מִצַּעַר וְרִפּוּי וְשֶׁבֶת וּבֹשֶׁת, שֶׁלֹּא חִיְּבָה תּוֹרָה בְּאַרְבָּעָה דְּבָרִים אֵלּוּ, אֶלָּא בְּאָדָם. \u0010y2\u0011\nשׁוֹרוֹ שֶׁחָבַל בְּאָבִיו וְאִמּוֹ, אוֹ שֶׁהִדְלִיק גָּדִישׁ בְּשַׁבָּת, חַיָּב בִּנְזָקָיו; אַף עַל פִּי שֶׁאִם עָשָׂה הוּא כֵּן \u0010y3\u0011 הָיָה פָטוּר:\nנָגַח אִשָּׁה וְיָצְאוּ יְלָדֶיהָ, \u0010y4\u0011 פָּטוּר מִדְּמֵי וְלָדוֹת, אַף עַל פִּי שֶׁהוּא מוּעָד לִנְגֹחַ. אֲבָל אִם נָגַח שִׁפְחָה מְעֻבֶּרֶת וְיָצְאוּ יְלָדֶיהָ, חַיָּב כְּאִילוּ נָגַח בְּהֵמָה מְעֻבֶּרֶת, וְשָׁמִין אוֹתָהּ כַּמָּה הָיְתָה שָׁוָה תְּחִלָּה, וְכַמָּה נִפְחֲתוּ דָּמֶיהָ, וּמְשַׁלֵּם תָּם חֲצִי נֶזֶק, וּמוּעָד נֶזֶק שָׁלֵם:",["\u0003אפילו נתכוון לבהמה וחבל באדם \u0004 עפ\"ר דכתבתי דיש צד רבותא בזה יותר משור שכוון לנגח בהמה זו ונגח בהמ' אחרת דהתם מין בהמה אחת היא משא\"כ אדם שיש לו מזל (וכמ\"ש בסי' א') ואין דרכו של שור לכוין אליו לנגחו וה\"א דמחשב אונס טפי:","\u0003ופטור מצער כו'. \u0004 דכי יתן איש בעמיתו כתיב ולא שור בעמיתו:","\u0003שור שחבל באביו כו'. \u0004 פי' שור שחבל באביו ואמו של בעל השור חייב בעל השור בנזקי אביו:","\u0003היה פטור. \u0004 וה\"ט דמה שהוא הי' פטור היינו משום דקים לי' בדרבא מיני' דהי' חייב מית' משא\"כ בשורו שחבלו שבעליו אינו חייב מיתה אזה:","\u0003פטור מדמי ולדות דכתיב כי ינצו אנשים ולא שורים:\u0004"],[],"שׁוֹר שֶׁחָבַל בָּאָדָם, \u0010y0\u0011 \u0010g0\u0011 \u0010t0\u0011 אֲפִלּוּ נִתְכַּוֵּן לַבְּהֵמָה וְחָבַל בָּאָדָם, דִּינוֹ כְּדִין שׁוֹר שֶׁהִזִּיק לְשׁוֹר; \u0010g1\u0011 תָּם מְשַׁלֵּם חֲצִי נֵזֶק, וּמוּעָד נֶזֶק שָׁלֵם, \u0010y1\u0011 וּפָטוּר \u0010g2\u0011 מִצַּעַר וְרִפּוּי וְשֶׁבֶת \u0010r0\u0011 וּבֹשֶׁת, שֶׁלֹּא חִיְּבָה תּוֹרָה בְּאַרְבָּעָה דְּבָרִים אֵלּוּ, אֶלָּא בְּאָדָם. \u0010y2\u0011 \u0010g3\u0011\nשׁוֹרוֹ שֶׁחָבַל בְּאָבִיו וְאִמּוֹ, אוֹ שֶׁהִדְלִיק גָּדִישׁ בְּשַׁבָּת, חַיָּב בִּנְזָקָיו; אַף עַל פִּי שֶׁאִם עָשָׂה הוּא כֵּן \u0010y3\u0011 הָיָה \u0010t1\u0011 פָטוּר: \u0010g4\u0011\nנָגַח אִשָּׁה וְיָצְאוּ יְלָדֶיהָ, \u0010y4\u0011 פָּטוּר מִדְּמֵי \u0010t2\u0011 וְלָדוֹת, \u0010r1\u0011 אַף עַל פִּי שֶׁהוּא מוּעָד \u0010g5\u0011 לִנְגֹחַ. אֲבָל אִם נָגַח שִׁפְחָה מְעֻבֶּרֶת וְיָצְאוּ יְלָדֶיהָ, חַיָּב כְּאִילוּ נָגַח בְּהֵמָה מְעֻבֶּרֶת, וְשָׁמִין אוֹתָהּ כַּמָּה הָיְתָה שָׁוָה תְּחִלָּה, וְכַמָּה נִפְחֲתוּ דָּמֶיהָ, וּמְשַׁלֵּם תָּם חֲצִי נֶזֶק, וּמוּעָד נֶזֶק שָׁלֵם:",{"g":["א) ל' הטור סעיף ב' וכ\"כ הרמב\"ם בפי\"א מהנ\"מ ד\"ו וכתב ה\"ה נזקי שלא בכוונה מחלוקת ר' יהודה ור\"ש פרק ד' דב\"ק דף מד ע\"א פסק כרבי יהודה בידוע דר\"ש ור' יהודה הלכה כרבי יהודה","ב) משנה וברייתא שם בפרק ג' דף לג ע\"א וכחכמים","ג) משנה שם פ\"ו דף פ\"ו ע\"א","ד) שם ס\"ד משנה שש בפ\"ג דף לד ע\"ב","ה) שם ס\"ה משנה שם בפ\"ד דף מ\"ח ע\"ב","\u0003ו) מימרא דר\"פ שם ד' מ\"ט ע\"א ויליף לה מקרא.\u0004 "],"t":["\u0003לבהמה. \u0004 ויש צד רבותא בזה יותר מאם כוון לנגח בהמה זו ונגח בהמה אחרת דהתם מין בהמה אחת היא משא\"כ אדם שיש לו מזל ואין דרך השור לכוין אליו לנגחו וה\"א דמחשב אונס טפי סמ\"ע:","\u0003פטור. \u0004 משום דקלב\"מ דחייב מיתה משא\"כ בשורו שבעליו אינו חייב מיתה בזה. שם:","\u0003ולדות. \u0004 דכתיב כי ינצו אנשים ולא שוורים. שם:"],"r":["\u0003שלא כו'. \u0004 ה' ב' נג ב':","\u0003אע\"פ שהוא כו'. \u0004 ר\"נ דלא כמש\"ש מ\"ב ח' לרבא אליבא דריה\"ג ועתוס' ד\"ה כתב כו' והא דתניא כו' ולמסקנא אף ר\"י הגלילי לא ס\"ל כן:"]}],["שׁוֹר שֶׁל יִשְׂרָאֵל \u0010y0\u0011 שֶׁנָּגַח שׁוֹר שֶׁל גּוֹי, פָּטוּר. וְשֶׁל גּוֹי שֶׁנָּגַח לְשֶׁל יִשְׂרָאֵל, בֵּין תָּם בֵּין מוּעָד, מְשַׁלֵּם נֶזֶק שָׁלֵם.\nשׁוֹר שֶׁל הֶפְקֵר שֶׁנָּגַח, וְקֹדֶם שֶׁיִּתְפֹּס אוֹתוֹ הַנִּזָּק קָדַם אַחֵר \u0010y1\u0011 וְזָכָה בּוֹ, פָּטוּר.\nנָגַח שׁוֹרוֹ וְהִפְקִירוֹ קֹדֶם שֶׁעָמַד בַּדִּין, וְזָכָה בּוֹ אַחֵר, פָּטוּר. אֲבָל אִם זָכָה בּוֹ הוּא עַצְמוֹ, חַיָּב.\nנָגַח \u0010y2\u0011 וְאַחַר כָּךְ מָכַר אוֹ הוֹרִישׁ, חַיָּב.\nשׁוֹר שֶׁל פִּקֵּחַ שֶׁנָּגַח לְשׁוֹר חֵרֵשׁ שׁוֹטֶה וְקָטָן, חַיָּב. וְשֶׁל חֵרֵשׁ שׁוֹטֶה וְקָטָן שֶׁנָּגַח לְשֶׁל פִּקֵּחַ, וְכֵן שׁוֹר שֶׁהָלְכוּ בְּעָלָיו לִמְדִינַת הַיָּם \u0010y3\u0011 וְנָגַח, פְּטוּרִים:",["\u0003שנגח שור של עכו\"ם פטור. \u0004 דשור רעהו כתיב ולא שור של עכו\"ם ומה\"ט היה מן הראוי לפטור ג\"כ איפכא בשל עכו\"ם שנגח לשל ישראל אלא דלמדו מקר' לחייב מדכתי' (בחבקוק) אלוה מתימן יבא וקדוש מהר פארן כו' עד עמד וימודד ארץ ראה ויתר גוים ודרשו רז\"ל בפרק שור שנגח ד' וה' (ריש בבא קמא דף ל\"ח) ראה ז' מצות בני נח שקבלו עליהן ולא קיימו עמד והתיר וכו' ור' יוחנן דרשו מדכתיב בפ' וזאת הברכה הופיע מהר פארן. מפארן שרצה ליתן להן התורה ולא רצו לקבל' הופיע וכו' כן הוא בגמ' שם ומהתימ' על המחבר \"עיר שושן שערבב וכתב ראה והופיע יחד וגם כתב אחריו ז\"ל כיון שראה שלא קיימו אפילו ז' מצות בני נח הופיע וכו' ומשמע מל' שם דס\"ל דחד לימוד ומקרא א' הוא וז\"א:","\u0003וזכה בו פטור. \u0004 פי' זה הזוכה פטור מהניזק ובגמ' ילפינן מקראי דבעינן שיהא לו בעלים בשעת נגיחה ובשעת גמר דין ועפ\"ר:","\u0003ואח\"כ מכר כו'. \u0004 קמשמע לן כיון דיש לו בעלים גם בשעת גמר דין אף ע\"ג דאינן בעלים הראשונים חייב.","\u0003ונגח פטורים. \u0004 עד\"ר שכתבתי לשון התוס' שדרז\"ל שלא לחייב באלו דכאלו אין להם בעלים דמי וגם לא תקנו להעמיד אפוטרופוס על השמירה ולגבות מהן לאחר שיגחו אם לא שכבר נגחו ג\"פ אז תקנו חכמי משנ' שיעמדו להן אפטרופוס ואח\"כ כשיחזרו ויגחו ג\"פ לפני אפוטרופוס לאחר התראה מגבינן נזקיהו מעליית היתומים וכתבו הטור ע\"ש והמחבר השמיטו ולא כתבו ג\"כ מור\"ם ז\"ל נראה דהיינו טעמא משום דאינו נוהג בזמן הזה דהא אין מועד בבבל (כמ\"ש בסי\"א) והטור לא כתבו אלא ללמדינו פי' הגמ' וגם משום דאם הועד בא\"י בכה\"ג ובא לח\"ל והזיק וקדם ותפסו הניזק שאין מוציאין מידו והוא דבר שאינו שכיח לכך לא כתבוהו ולא הזכיר אפטרופוס כלל ובעיר שושן נתן מכשול לפני המעייני' בספרו במ\"ש בזה ז\"ל חשו לממונא שלא לכלייא קרנא אמרו שלא להעמיד להן אפטרופוס לחובתן לשלם לניזק כו' וז\"א דהא אחר שנגחו ג\"פ מעמידין אפטרופוס וכנ\"ל ואי משום דכ' לכליא קרנא דהיינו כ\"ז שהן תמים שאז גובה מגופו ושייך כילוי קרן משא\"כ כשהועד הא זה הטעם דחו התו' ועד\"ר:"],[],"\u0010g0\u0011 שׁוֹר שֶׁל יִשְׂרָאֵל \u0010y0\u0011 שֶׁנָּגַח שׁוֹר שֶׁל \u0010g1\u0011 \u0010t0\u0011 גּוֹי, פָּטוּר. וְשֶׁל גּוֹי שֶׁנָּגַח לְשֶׁל יִשְׂרָאֵל, בֵּין תָּם בֵּין מוּעָד, \u0010g2\u0011 מְשַׁלֵּם נֶזֶק שָׁלֵם. \u0010g3\u0011\nשׁוֹר שֶׁל הֶפְקֵר שֶׁנָּגַח, וְקֹדֶם שֶׁיִּתְפֹּס אוֹתוֹ הַנִּזָּק קָדַם אַחֵר \u0010y1\u0011 וְזָכָה בּוֹ, פָּטוּר. \u0010g4\u0011\nנָגַח שׁוֹרוֹ וְהִפְקִירוֹ קֹדֶם שֶׁעָמַד בַּדִּין, \u0010t1\u0011 וְזָכָה בּוֹ אַחֵר, פָּטוּר. \u0010r0\u0011 אֲבָל אִם זָכָה בּוֹ הוּא עַצְמוֹ, \u0010g5\u0011 \u0010r1\u0011 חַיָּב.\nנָגַח \u0010y2\u0011 וְאַחַר כָּךְ מָכַר אוֹ הוֹרִישׁ, \u0010g6\u0011 \u0010t2\u0011 חַיָּב.\nשׁוֹר שֶׁל פִּקֵּחַ שֶׁנָּגַח לְשׁוֹר חֵרֵשׁ שׁוֹטֶה וְקָטָן, חַיָּב. וְשֶׁל חֵרֵשׁ שׁוֹטֶה וְקָטָן שֶׁנָּגַח לְשֶׁל פִּקֵּחַ, \u0010g7\u0011 וְכֵן שׁוֹר שֶׁהָלְכוּ בְּעָלָיו לִמְדִינַת הַיָּם \u0010y3\u0011 וְנָגַח, \u0010t3\u0011 פְּטוּרִים:",{"g":["\u0003א) משנה פ\"ד דב\"ק דף נ\"ו ע\"ב.\u0004 ","ב) כ' הרמב\"ם בפ\"ח ד\"ה הטעם לפי שאין העכו\"ם מחייבים את האדם על בהמתו שהזיקה והרי אנו דנין להם בדיניהם וכתב ה\"ה שהוא נתינת טעם מדעתו ועל מה שהשיגו הראב\"ד כתב ואפשר שבזמן הגמרא לא היו העכו\"ם נפרעים כלל","ג) כ' הרמב\"ם קנס זה הוא לעכו\"ם לפי שאין זהירים במצות ואינם דסלקין הנזק ואם לא תחייבם על נזקי בהמתן אין משמרין אותן ומפסידין ממון הבריות","ד) ברייתא שם בפ\"ק דף י\"ג ע\"ב וכדמפרש לה התם","ה) טור ס\"ב אוקימתא דרבינא וברייתא משמיה דר' יהודה שם ולע\"ד צ\"ע דהתם לענין מועד אתמר כמו שפירש\"י והתוספת שם אבל תם כשם שהניזק גובה מן הלוקח כמ\"ש לקמן בריש הסימן הסמוך וע\"ש וכן גובה מן הזוכה בו כשהפקירו","\u0003ו) ס\"ג ומבואר בריש הסימן הסמוך:\u0004 ","ז) שם ע\"ד משנה שם פרק ד' דף ל\"ט ע\"א","\u0003ח) ברייתא שם ע\"ב כחכמים:\u0004 "],"t":["\u0003פטור. \u0004 דשור רעהו כתיב ולא שור של עובדי כוכבים ומה\"ט היה מן הראוי לפטור גם כן איפכא אלא דלמדו מקרא לחייב מדכתיב עמד וימודד ארץ כו' כדאיתא בב\"ק ריש ד' ל\"ח ע\"ש. סמ\"ע:","\u0003וזכה. \u0004 פטור זוכה זה מהניזק ובש\"ס ילפי מקראי דבעינן שיהא לו בעלים בשעת נגיח' ובשעת גמר דין. שם:","\u0003חייב. \u0004 קא משמע לן כיון דיש לו בעלים גם בשעת גמר דין אע\"ג דאינן בעלים הראשונים חייב. שם:","\u0003פטורים. \u0004 עיין בטור שכתב דאם הוחזקו נגחנים ב\"ד מעמידין להן אפוטרופוס כו' והמחבר השמיטו וגם הרמ\"א לא כתבו ונראה דה\"ט משום דאינו נוהג בזה הזמן דהא אין מועד בבבל ואף אם בכה\"ג הועד בא\"י ובא לח\"ל והזיק ותפשו הניזק שאין מוציאין מידו מ\"מ הוא דבר שאינו שכיח לכך לא כתבוהו ולא הזכירו בזה דין אפטרופוס כלל. ש\"ך:"],"r":["\u0003אבל אם כו'. \u0004 דייק ממש\"ש עד שתהא כו' ול\"ק עד שתהא מיתה וגמר דין שוה כאחד אלא דביני ביני א\"צ להיות באדם א' ולכן קמ\"ל דאף העמדה בדין ג\"כ צריך ורש\"י שם לא פי' כן וע\"ש בד\"ה למעיטי כו' וד\"ה והועד כו':","\u0003נגח ואח\"כ כו'. \u0004 וכ\"כ הרשב\"א דל\"ד באיש אחד דא\"כ הל\"ל מכר או הוריש אלא דר\"ל באיש מתחלתו ועד סופו לאפוקי הפקר שאינו שור איש וכמ\"ש ל\"ג ב' וכמ\"ש בר\"ס תז:"]}],["שׁוֹר תָּם שֶׁהִזִּיק, אִם מְכָרוֹ הַמַּזִּיק עַד שֶׁלֹּא עָמַד בַּדִּין, \u0010y0\u0011 \u0010c0\u0011 אַף עַל פִּי שֶׁהוּא מָכוּר, הֲרֵי הַנִּזָּק גּוֹבֶה הֵימֶנּוּ, וְחוֹזֵר הַלּוֹקֵחַ וְגוֹבֶה מֵהַמַּזִּיק שֶׁמָּכַר לוֹ; שֶׁכֵּיוָן שֶׁנָּגַח, קוֹל יֵשׁ לוֹ וְלֹא הָיָה לוֹ לַלּוֹקֵחַ לִקַּח אוֹתוֹ עַד שֶׁיִּגְבֶּה הַנִּזָּק. \u0005הַגָּה: מְכָרוֹ נִזָּק, מָכוּר; \u0010y1\u0011 וּכְשֶׁיִּתְפְּסֶנּוּ, יִקָּחֶנּוּ הַלּוֹקֵחַ (טוּר ס\"א)\u0006.\nשְׁחָטוֹ מַזִּיק, גּוֹבֶה מִבְּשָׂרוֹ. \u0010c1\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּצָרִיךְ לְשַׁלֵּם פְּחַת הַשְּׁחִיטָה (טוּר שָׁם מהג\"מ פֶּרֶק הַמֵּנִיחַ)\u0006. \u0010c2\u0011 וְכֵן אִם \u0010c3\u0011 נִשְׁתַּמֵּשׁ בּוֹ חַיָּב לִתֵּן לַנִּזָּק שְׂכִירוּת. \u0005(טוּר וּבֵית יוֹסֵף בְּשֵׁם רַשִׁ\"י וְהָרַאֲבַ\"ד)\u0006. נְתָנָהּ בְּמַתָּנָה, מַה שֶּׁעָשָׂה עָשׂוּי, וְיִגְבֶּה הַנִּזָּק מִמֶּנּוּ:\nבַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁמָּכַר אוֹ נָתַן קֹדֶם שֶׁעָמַד בַּדִּין. אֲבָל אִם עָמַד בַּדִּין וְאַחַר כָּךְ מְכָרוֹ אוֹ נְתָנוֹ בְמַתָּנָה, לֹא עָשָׂה כְּלוּם.\nקָדְמוּ בַּעַל חוֹב שֶׁל מַזִּיק וּתְפָסוּהוּ, בֵּין שֶׁחָב עַד שֶׁלֹּא הִזִּיק, בֵּין הִזִּיק עַד שֶׁלֹּא חָב, לָא זָכָה, אֶלָּא הַנִּזָּק גּוֹבֶה מִמֶּנּוּ, \u0010y2\u0011 שֶׁאֲפִלּוּ הָיָה אֵצֶל בַּעַל חוֹב מִתְּחִלָּה וְהִזִּיק, הָיָה גוֹבֶה מִגּוּפוֹ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דַּוְקָא דְּיוּכַל הַבַּעַל חוֹב לִגְבּוֹת חוֹבוֹ מִמָּקוֹם אַחֵר, אֲבָל אִם הָיָה הַשּׁוֹר \u0010y3\u0011 אִפּוֹתִיקִי מְפֹרָשׁ לְבַעַל חוֹב, וְקָדַם בַּעַל חוֹב לַנְּזִיקִין, \u0010y4\u0011 בַּעַל חוֹב קוֹדֵם (טוּר ל' הָרַמְבַּ\"ם שָׁם וְהָרֹא\"שׁ)\u0006.",["\u0003אע\"פ שהוא מכור. \u0004 פי' לענין זה דיכול הלוקח לחרוש ולעבוד בו וגם אין שום א' מהן יכול לחזור בו כ\"ז שלא גבה ממנו הניזק וכן לענין זה קאמר בסמוך בס\"ב דמתנתו מתנה:","\u0003וכשיתפסנו יקחנו כו'. \u0004 כ' שיתפסנו משום זמן הזה דאין מגבין דיני קנסות בב\"ד ולרבותא כ\"כ דאע\"ג דאין לו בו דבר עד שיתפסנו אפ\"ה מכירתו מכיר' ועפ\"ר:","\u0003שאפי' היה אצל ב\"ח כו'. \u0004 היה גובה מגופו ר\"ל כיון שאפי' היה של עצמו גובה מידו אם הזיק כ\"ש זה שאין עליו אלא שיעבוד ועד\"ר שם כתבתי דכן הוא בגמר' ושהתו' כתבו ע\"ז דאין זה כ\"ש דבשלמא אם היה שלו מעולם או שכבר גבהו בחובו ויצא והזיק מ\"ה חייב דהוא פשע בשמירתו משא\"כ זה שנגח בעוד שלא היה ברשותו ולא בא הגמרא אלא לומר קצת טעם דמ\"ה גובה מיד ב\"ח כיון דאין גוף השור משועבד לב\"ח כמו שהוא משועבד לניזק:","\u0003אפותיקי מפורש לב\"ח. \u0004 פי' שכתב לו לא יהא לך פרעון אלא מזה דאז אינו גובה ממקום אחר אף אם נגנב או נשתדף זה האפותיקי א\"ל ברצון שניהן או שמשלם לו במזומנים וכמ\"ש הטור והמחבר בסי' קי\"ז ע\"ש:","\u0003ב\"ח קודם. \u0004 פי' כשתפסו עפ\"ר ודריש' שם כתבתי דנרא' דאפ\"ה אם קדם הניזק ותפס השור דאין מוציאין מידו דלא עדיף לגבי ב\"ח משאר מטלטלים שעשאו אפותיקי מפורש דאם קדם ומכרו או שקידם ב\"ח מאוחר וגבהו גבייתו גביי' ומכירתו מכיר' וכמ\"ש הטור בסי' קי\"ז ס\"ד ואפי' אם לא קדם הניזק ותפס ובאו הניזק וב\"ח יחד לגבות משור זה שעשאו אפותיקי לב\"ח הב\"ד מגבין אותו לשניהן בשוה כמ\"ש הטור והמחבר בסימן ק\"ד דאין קדימ' למטלטלין מיהו אם הוא איפכא דניזק קודם שלוה מזה הב\"ח אפי' קדם הב\"ח ותפס זה השור הניזק שעשאו אפותיקי מפורש ל\"מ תפיסתו דשור זה שנגח שם תורא דנגחנא לפלוני יש עליו ויש לו קול ודינו כקרקע לענין הניזק ובקרקע קיימא לן דבעל חוב מאוחר שקדם וגבה גבייתו לאו גביי' הוא וכמ\"ש בסי' ק\"ד ועפ\"ר מ\"ש עוד מזה:"],["\u0003 אע\"פ שהוא מכור לרדיא \u0004 ומהרש\"ל פ\"ג דב\"ק סימן כ\"ח תמה ע\"ז וכתב דלרבי עקיבא אפילו לרדיא אינו מכור וע\"ש וכן דעת הטור וכ\"כ התוספות דף ל\"ג ע\"א ד\"ה והקדישו וכן נרא' עיקר בש\"ס למאי דקי\"ל כר' עקיבא דשותפין נינהו ודו\"ק היינו שכתב הרב שס\"ב וכן אם נשתמש בו חייב ליתן לו שכירות ועיין מ\"ש שם:","\u0003 וי\"א כו' \u0004 וכן עיקר לפי מאי דקי\"ל כרשב\"ג דמזיק שעבודו של חבירו חייב וכמו שכ' הרמב\"ם פ\"ז מה' חובל ופ\"ח מה' מלוה וכ\"כ המחבר לעיל סימן קי\"ז (סעיף ו') וכ\"פ בהגהות אשרי פ' המניח וכ\"פ מהרש\"ל שם סי' כ\"ח ומ\"ש הרמב\"ם והמחבר אח\"כ נתנו במתנה מה שעש' עשוי אין לדקדק מזה דפטור מפח' שחיט' וכדדייקינן בש\"ס מהאי לישנא דבש\"ס מדייק שפיר דקתני שחטו ונותנו במתנה מה שעש' עשוי אבל הרמב\"ם והמחבר שכתבו מתחלה שחטו גובה מבשרו אם כן מה שכתב אחר כך נתנו במתנ' מה שעשה עשוי ומתנתו מתנה לרדיא ודו\"ק וכ\"כ בע\"ש נתנו במתנה מה שעש' עשוי לענין לחרוש בו ועיין מ\"ש לעיל סי' שפ\"ו:","\u0003 וכן אם כו' \u0004 סדר הר\"ב אינו נכון בעיני דהא זה חולק אדברי הרמב\"ם והמחבר לעיל סעיף א' שכתבו אע\"פ שמכר והל\"ל זה בלשון י\"א בסעיף א' ודו\"ק:","\u0003 נשתמש בו כו'. \u0004 כתב ב\"י שהרשב\"א חולק על זה ומפרש לרדיא היינו לענין לחרוש בו לכתחל' אבל אם כבר נשתמש בו פטור ליתן שכירות דהא כשמכרו גזלן הוא וגזלן אינו מעלה שכר לבעלים ע\"כ ויש לו ראיה מש\"ס פרק הגוזל קמא גבי תוקף עבדו וספינתו של חברו ועש' בהם מלאכה ונתבאר לעיל סי' שי\"ג [שס\"ג] ס\"ד וה' ועמ\"ש שם ס\"ד:"],"\u0010g0\u0011 שׁוֹר תָּם שֶׁהִזִּיק, אִם מְכָרוֹ הַמַּזִּיק עַד שֶׁלֹּא עָמַד בַּדִּין, \u0010y0\u0011 \u0010c0\u0011 \u0010g1\u0011 \u0010r0\u0011 אַף עַל פִּי שֶׁהוּא \u0010t0\u0011 מָכוּר, \u0010r1\u0011 הֲרֵי הַנִּזָּק גּוֹבֶה הֵימֶנּוּ, וְחוֹזֵר הַלּוֹקֵחַ וְגוֹבֶה מֵהַמַּזִּיק שֶׁמָּכַר לוֹ; \u0010g2\u0011 שֶׁכֵּיוָן שֶׁנָּגַח, קוֹל יֵשׁ לוֹ וְלֹא הָיָה לוֹ לַלּוֹקֵחַ לִקַּח אוֹתוֹ עַד שֶׁיִּגְבֶּה הַנִּזָּק. \u0005הַגָּה: \u0010r2\u0011 מְכָרוֹ נִזָּק, מָכוּר; \u0010y1\u0011 \u0010g3\u0011 \u0010r3\u0011 וּכְשֶׁיִּתְפְּסֶנּוּ, יִקָּחֶנּוּ הַלּוֹקֵחַ \u0010g4\u0011 (טוּר ס\"א)\u0006. \u0010g5\u0011\nשְׁחָטוֹ מַזִּיק, גּוֹבֶה מִבְּשָׂרוֹ. \u0010c1\u0011 \u0010t1\u0011 \u0010r4\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּצָרִיךְ לְשַׁלֵּם פְּחַת הַשְּׁחִיטָה \u0010g6\u0011 (טוּר שָׁם מהג\"מ פֶּרֶק הַמֵּנִיחַ)\u0006. \u0010c2\u0011 \u0010r5\u0011 וְכֵן אִם \u0010c3\u0011 נִשְׁתַּמֵּשׁ בּוֹ חַיָּב לִתֵּן לַנִּזָּק שְׂכִירוּת. \u0010g7\u0011 \u0005(טוּר וּבֵית יוֹסֵף בְּשֵׁם רַשִׁ\"י וְהָרַאֲבַ\"ד)\u0006. \u0010g8\u0011 נְתָנָהּ בְּמַתָּנָה, מַה שֶּׁעָשָׂה עָשׂוּי, וְיִגְבֶּה הַנִּזָּק מִמֶּנּוּ: \u0010g9\u0011\nבַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁמָּכַר אוֹ נָתַן קֹדֶם שֶׁעָמַד בַּדִּין. אֲבָל אִם עָמַד בַּדִּין וְאַחַר כָּךְ מְכָרוֹ אוֹ נְתָנוֹ בְמַתָּנָה, לֹא עָשָׂה כְּלוּם. \u0010g10\u0011\nקָדְמוּ בַּעַל חוֹב שֶׁל מַזִּיק וּתְפָסוּהוּ, בֵּין שֶׁחָב עַד שֶׁלֹּא הִזִּיק, בֵּין הִזִּיק עַד שֶׁלֹּא חָב, לָא זָכָה, אֶלָּא הַנִּזָּק גּוֹבֶה מִמֶּנּוּ, \u0010y2\u0011 \u0010r6\u0011 שֶׁאֲפִלּוּ הָיָה אֵצֶל בַּעַל חוֹב \u0010t2\u0011 מִתְּחִלָּה וְהִזִּיק, הָיָה גוֹבֶה מִגּוּפוֹ. \u0005הַגָּה: \u0010r7\u0011 וְיֵשׁ אוֹמְרִים דַּוְקָא דְּיוּכַל הַבַּעַל חוֹב לִגְבּוֹת חוֹבוֹ מִמָּקוֹם אַחֵר, אֲבָל אִם הָיָה הַשּׁוֹר \u0010y3\u0011 אִפּוֹתִיקִי \u0010g11\u0011 מְפֹרָשׁ לְבַעַל חוֹב, וְקָדַם בַּעַל חוֹב לַנְּזִיקִין, \u0010y4\u0011 בַּעַל חוֹב קוֹדֵם \u0010g12\u0011 (טוּר ל' הָרַמְבַּ\"ם שָׁם וְהָרֹא\"שׁ)\u0006.",{"g":["\u0003א) ל' הרמב\"ם בפ\"ח מהנ\"מ דין וברייתא בפ\"ג דב\"ק דף לג ע\"ב:\u0004 ","ב) שם בגמ' מכור לרדיא ופ' ה' המגיד הכונה לומרי שהלוקח חורש בו לכתחלה וכן שהמכר קיים ואין א' יכול לחזור בו נראה שהוא סובר שהברייתא אתיא מפי' לר\"ע דאמר התם שותפי נינהו ויליף לה מדאמר הקדישו מוקדש מדרב אבהו וכו' דאי לרבי ישמעאל דאמר ב\"ח לא צריכין לרבי אבהו","ג) שם בגמ'","פי' לדידן דלא מגבינן ליה אי תפס לא מפקינן מיני'","ד) מבואר בסוגי' שם אליבא דר\"ע דהלכה כוותיה מחבירו","\u0003ה) שם ד\"ו ברייתא שם חי אין לי וכו'\u0004 וכתב הרמב\"ם שם ☜הקדישו המזיק הרי זה מוקדש כדי שלא יאמרו הקדש יוצא בלא פדיון וכתב ה\"ה זו היא דר' אבהו דלעיל (שם) והכוונ' שפודה אותו בדבר מועט הנזוק וכו' וגובה ממנו וכן פי' המפרשי' ולא ידעתי למה השמיטו המחבר:","\u0003ו) מהא דכ' הרא\"ש שם אבא דא\"ר הונא וכו'\u0004 שם זאת אומרת המזיק שעבודו של חבירו פטור כתב הרא\"ש ולקמן פסקינן הלכה כמאן דדאין דינא דגרמי הלכך המזיק שעבודו של חבירו חייב וכדברי הטור כתבו גם הגהת אשר\"י ונלענ\"ד לא מחייבינן ליה לשלם לניזק אלא כשתפס כמ\"ש לעיל","ז) דס\"ל דאוקימתא דמכור לרדיא הוא אבריית' דאתיא כר' ישמעאל ואם כן לר\"ע דקי\"ל כוותיה מכרו אינו מכור אפי' לרדיא ודלא כמ\"ש בסימן דלעיל בשם ה\"ה לדעת הרמב\"ם במ\"ש אע\"פ שהוא מכור ולענ\"ד היה לו לרב רמ\"א לכתוב הגה זו לעיל וגם בזה צ\"ל לפי עניות דעתי דאיירי בשתפס הניזק אבל הרשב\"א כ' כשמכרו מזיק גזלן הוא לר\"ע וגזלן אינו מעלה שכר לבעלים (כמ\"ש בסימן שס\"ג ס\"ג)","ח) שם ברמב\"ם ברייתא שם וכפי' רש\"י מה שעשה עשוי לרדיא וכמ\"ש בסי' דלעיל בשם ה\"ה ואין דעת הטור כן וגם בזה לפענ\"ד היה לו לרב רמ\"א להגיה עליו דעת הטור","ט) שם ד\"ח בברייתא שם ומבואר במ\"ש בשם ה\"ה אבל לדעת הטור אין חילוק בזה כמ\"ש","י) שם ובברייתא","פירוש שלא יהא לו פרעון אלא מזה","כ) שם ס\"ג ממ\"ש התוספת שם ריש דף ל\"ד ומטעם שהב\"ח לא פשע בשמירתו וכ' הסמ\"ע ומיהו ☜אם קדם הניזק ותפס אין מוציאין מידו כדין אפותיקי מפו' במטלטל שקדם ב\"ח מחוסר וגבה מה שגבה גבה כמ\"ש לעיל בסימן קי\"ז ס\"ד:"],"t":["\u0003מכור. \u0004 ומהרש\"ל תמה ע\"ז וכתב דלר\"ע אפי' לרדיא אינו מכור וכן דעת הטור וכ\"כ התוספות דף ל\"ג ע\"א ד\"ה והקדישו וכן נראה עיקר בש\"ס למאי דקי\"ל כר\"ע דשותפי נינהו והיינו שכ' הרמ\"א בס\"ב וכן אם נשתמש בו כו' אלא שלא סדרו על נכון לע\"ד דה\"ל לכתבו כאן בל' י\"א ודו\"ק. ש\"ך:","\u0003וי\"א. \u0004 וכן עיקר לפי מאי דקי\"ל כרשב\"ג דמזיק שעבודו של חבירו חייב וכמ\"ש הרמב\"ם פ\"ז דחובל ופ\"ח דמלוה וכ\"כ המחבר בסי' קי\"ז וכ\"פ בהג\"א פרק המניח ומהרש\"ל שם סי' כ\"ב ומ\"ש המחבר אח\"כ נתנו במתנה כו' אין לדקדק דפטור מפחת שחיטה כדדייקינן בש\"ס דהתם מדייק שפיר דקתני שחטו ונתנו במתנה מה שעשה עשוי אבל הרמב\"ם והמחבר שכתבו מתחלה שחטו גובה מבשרו א\"כ מ\"ש אח\"כ נתנו במתנה כו' ר\"ל דהוי מתנה לרדיא וכ\"כ בע\"ש ועיין מה שכתבתי לעיל סי' שפ\"ו. שם:","\u0003מתחלה. \u0004 ר\"ל שאפילו אם היה של עצמו גובה מידו אם הזיק כ\"ש זה שאין לו עליו אלא שעבוד כן הוא בש\"ס והתוספת כתבו דאין זה כ\"ש דבשלמא אם היה שלו מעולם או שכבר גבאו בחובו ויצא והזיק דפשע בשמירתו מש\"ה חייב משא\"כ זה שנגח בעוד שלא הי' ברשותו ולא בא הש\"ס אלא ליתן קצת טעם דמש\"ה גובה מיד בע\"ח כיון דאין גוף השור משועבד לבע\"ח כמו שהוא משועבד לניזק. סמ\"ע:"],"r":["\u0003אע\"פ כו'. \u0004 עתוס' שם ד\"ה הקדישו כו' דלר\"ע דקי\"ל כוותיה אינו מכור אפי' לרדיא וכ\"ד רש\"י וע\"ש בד\"ה מכרו אינו מכור קס\"ד כו' אבל דעת הרמב\"ם דלרדיא אפי' לר\"ע מכור כמש\"ש ת\"ר שור תם כו' אמר מר מכרו כו' ומ' דאתי ככ\"ע ועוד דאמר הקדישו מוקדש משום דר\"א וזה א\"צ אלא לר\"ע כמ\"ש הקדישו מוקדש אפי' לר\"ע משום דר\"א כו' ומש\"ש מכרו אינו מכור מני ר\"ע קס\"ד דאינו מכור לגמרי דוקא לר\"ע ומשני דזה אפי' לר\"י. והרשב\"א מסכים ג\"כ דלר\"ע אינו מכור לרדיא אלא שחולק על רש\"י מ\"ש בד\"ה לרדיא שאם כו' והוא כ' דזה לד\"ה כמש\"ש צ\"ו ב' בההוא דגזל פדנא כו' וכן שם צ\"ז א' בספינה כו' וה\"נ לא נחית אדעתא דאגרא אלא דלרדיא פי' לכתחלה לחרוש בו ונראה שכן פי' הרמב\"ם וז\"ש אע\"פ כו' ר\"ל דאף לכתחלה מותר להשתמש כדין מכירה:","\u0003הרי כו' שכיון כו'. \u0004 שם:","\u0003מכרו כו'. \u0004 שם אלא ניזק מכרו כו' וקי\"ל כר\"ע דהלכה כמותו מחבירו וסתם מתני' שם כוותיה:","\u0003וכשיתפסנו כו'. \u0004 ר\"ל אפי' האידנא דלא זכי עד תפיסה דהא גם בימיהם לא זכה עד העמדה בדין ואפ\"ה אינו מכור ועתוס' שם ד\"ה א\"ב. ונראה דאע\"ג דלר\"ע כו' וא\"ת כו':","\u0003וי\"א דצריך כו'. \u0004 שם זאת אומרת כו' הא נמי רבה כו' מ\"ד כו' וכיון דלא קי\"ל כרבה שם כמש\"ש צח ב' מאן דדאין כו' וקי\"ל כד\"מ כמ\"ש בר\"ס שפו כ\"ש דקי\"ל במזיק כו' דחייב וכ\"פ בגטין מא כל הפוסקים כרשב\"ג דמזיק שיעבודו חייב וכ\"פ הרמב\"ם בעצמו וכמש\"ל סי' קיז ס\"ו ובי\"ד סי' רסז סס\"ח:","\u0003וכן אם כו'. \u0004 בזה חולק על הרמב\"ם כנ\"ל וכפרש\"י ומפרשים הברייתא ת\"ר כו' הכל אליבא דר\"י ומ\"ש הקדישו מוקדש משום דר\"א אף לר\"י משום דקדושת דמים אינו מפקיע מידי שיעבוד ועתוס' ד\"ה משום כו'. יש\"ש. וצ\"ע דא\"כ מאי קאמר שם הקדישו מוקדש אתאן לר\"י כו' ועוד מאי דוחקיה לאוקמיה בקדושת דמים:\n\u0003 (ליקוט) וכן אם כו'. \u0004 ומש\"ש אמר מר מכרו מכור לרדיא היינו לר' ישמעאל ומש\"ש הקדישו מוקדש משום דר\"א אפי' לר\"י כמש\"ש בתוס' ד\"ה משום כו' וציונו של תוס' על משום דר\"א דהכא אבל מש\"ש למעלה הקדישו מוקדש אפי' לר\"ע משום דר\"א מיירי בקדושת הגוף ואפ\"ה לא קדוש משום דהוחלט לגמרי לר\"ע ולכן ס\"ד דהקדישו קדוש ממש קאמר וכר\"י משום דמיירי בקדושת הגוף וז\"ש תוס' בד\"ה ומיירי הכא כו' הכא דוקא והא דל\"ק גמ' כאן בקדושת הגוף ולגמרי משום דמכרו ונתנו במתנה קתני דלאו לגמרי אלא לרדיא (ע\"כ):","\u0003שאפילו כו'. \u0004 שם וכפרש\"י:","\u0003וי\"א כו'. \u0004 כפי' תוס' שם ד\"ה אילו כו' ועסי' קיז ס\"א:\n\u0003 (ליקוט) וי\"א דוקא כו'. \u0004 ערש\"י לו א' ד\"ה ראשון כו' והא ל\"ד לחב כו' אבל הרשב\"א שם הקשה הניחא אם י\"ל נכסים אחרים כו' וכמו שפריך בגמ' שם מ' ב' הניחא כו' וכ' ע\"כ נראה כפי' הראב\"ד דהתם ה\"ל לגבי ניזק כאפותיקי של קרקע ומגופו בלבד משתלם וכאלו מכרו לו לנזקיו משא\"כ לבע\"ח ואפילו עשאו לו אפותיקי מפורש ה\"ל כמו שעשאו אפותיקי מפורש ומכרו שאין בע\"ח גובה הימנו ולכן קא' ראשון ראשון גובה כמו באפותיקי של קרקע כו' וזהו ס' ראשונה שכ' ש\"ע וסתם אבל הטור והרב ס\"ל כפירש\"י הנ\"ל ותוס' לג א' ועבטור כיון שהבע\"ח כו' לפיכך כו' ועב\"ח ודו\"פ (ע\"כ):"]}],["אֵין הַנְּזִיקִים מִשְׁתַּלְּמִים \u0010y0\u0011 אֶלָּא בִּרְאָיָה בְּרוּרָה וּבְעֵדִים כְּשֵׁרִים. \u0005וְאֵין מְקַבְּלִין הָעֵדוּת אֶלָּא בִּפְנֵי בַּעַל דִּין, אֲפִלּוּ הָיָה הוּא וְעֵדָיו חוֹלִים (נִמּוּקֵי יוֹסֵף פֶּרֶק כֵּיצַד)\u0006.\nשׁוֹר שֶׁהָיָה רוֹעֶה, וְנִמְצָא שׁוֹר הָרוּג בְּצִדּוֹ, אַף עַל פִּי שֶׁזֶּה מְנֻגָּח וְזֶה מוּעָד לִגַּח, זֶה מְנֻשָּׁךְ וְזֶה מוּעָד לִנְשֹׁךְ, אֵין אוֹמְרִים בְּיָדוּעַ שֶׁזֶּה נְגָחוֹ אוֹ נְשָׁכוֹ. וַאֲפִלּוּ גָמָל הָאוֹחֵר בֵּין הַגְּמַלִּים וְנִמְצָא הָרוּג בְּצִדּוֹ, אֵין אוֹמְרִים בְּיָדוּעַ שֶׁזֶּה הֲרָגוֹ, עַד שֶׁיִּרְאוּהוּ עֵדִים כְּשֵׁרִים:",["\u0003אלא בראי' ברורה. \u0004 כן הוא במשנ' והרמב\"ם בפ\"ח מהל' נ\"מ מסיק וכתב בזה והביאו הטור כאן ז\"ל של\"ת הואיל ואין מצוי בארוות הסוסים ובגדרות הצאן אלא הרועים והעבדים וכיוצא בהם אם העידו ששור זה נגח או היזק לאדם שומעין להן קמ\"ל דאין הדבר כן אלא לעולם אין מחייבין ממון אלא ע\"פ עדים כשרים ויעידו בב\"ד ויחייבו ב\"ד המזיק לשלם ועד\"ר מ\"ש בשם ת\"ה ע\"ז וכתבו מור\"ם ז\"ל לעיל בהג\"ה ש\"ע בס\"ס ל\"ה דמכח תקנה יכולין להעיד ועוד כתב הטור כאן בשם ר\"י דקמ\"ל המשנ' הנ\"ל בזה דאפי' שור עכו\"ם שנגח לשור של ישראל אין דנין אותו אלא בעדים כשרים עכ\"ל:"],[],"\u0010g0\u0011 \u0010r0\u0011 אֵין הַנְּזִיקִים מִשְׁתַּלְּמִים \u0010y0\u0011 אֶלָּא בִּרְאָיָה \u0010t0\u0011 בְּרוּרָה וּבְעֵדִים כְּשֵׁרִים. \u0010r1\u0011 \u0005וְאֵין מְקַבְּלִין הָעֵדוּת אֶלָּא בִּפְנֵי בַּעַל דִּין, אֲפִלּוּ הָיָה הוּא וְעֵדָיו חוֹלִים (נִמּוּקֵי יוֹסֵף פֶּרֶק כֵּיצַד)\u0006. \u0010g1\u0011\nשׁוֹר שֶׁהָיָה רוֹעֶה, וְנִמְצָא שׁוֹר הָרוּג בְּצִדּוֹ, אַף עַל פִּי שֶׁזֶּה מְנֻגָּח וְזֶה מוּעָד לִגַּח, זֶה מְנֻשָּׁךְ וְזֶה מוּעָד לִנְשֹׁךְ, אֵין אוֹמְרִים בְּיָדוּעַ שֶׁזֶּה נְגָחוֹ אוֹ נְשָׁכוֹ. וַאֲפִלּוּ גָמָל \u0010g2\u0011 הָאוֹחֵר בֵּין הַגְּמַלִּים וְנִמְצָא הָרוּג בְּצִדּוֹ, אֵין אוֹמְרִים בְּיָדוּעַ שֶׁזֶּה הֲרָגוֹ, עַד שֶׁיִּרְאוּהוּ עֵדִים כְּשֵׁרִים:",{"g":["א) ל' הרמב\"ם בפ\"ח מה' נזקי ממון משנה בפ\"ח דב\"ח וכדמפרש לה בגמ' שם ריש דף י\"ג:","ב) שם די\"ד ברייתא ספ\"ו דב\"ב דף צ\"ג ע\"א וכת\"ק","ג) כ' ה\"ה פי' שמשמש אחור כנגד אחור ודרכו להרוג כל מסתכל בו בשעת תשמישו ל\"א אוחר נוחר ופי' מ\"ש רבינו ואפי' גמל האוחר פירוש ואפי' הוא מועד ועוד שאוחר:"],"t":["\u0003ברורה. \u0004 בטור הביא לשון הרמב\"ם בזה שכתב וז\"ל של\"ת הואיל ואין מצוי בארוות הסוסים ובגדרות הצאן אלא הרועים והעבדים וכיוצא בהם אם העידו ששור זה נגח או הזיק לאדם שומעין להן קמ\"ל דאין הדבר כן אלא לעולם אין מחייבין ממון אלא ע\"פ עדים כשרים ויעידו בב\"ד ויחייבו ב\"ד המזיק לשלם וע\"ל ס\"ס ל\"ה בהג\"ה דמכח תקנה יכולין להעיד ע\"ש ועוד כת' הטור בשם ר\"י דקמ\"ל בזה דאפילו שור עובד כוכבים שנגח לשור של ישראל אין דנין אותו אלא בעדים כשרים עד כאן לשונו. סמ\"ע:"],"r":["\u0003אין כו'. \u0004 עבה\"ג ועמ\"ש בס\"ס ל\"ה:","\u0003ואין מקבלין כו'. \u0004 ממש\"ש כ\"ד א' אין השור כו' העידו בו בפני כו' אינו נעשה כו' מדכפל ושנה ש\"מ דר\"ל אפי' במקום דלא אפשר כגון זה וכמש\"ש קיב בהא אינו כלום. וכ\"ש לס' האחרונה דסי' כח סט\"ו ודייקי ממה שמקבלין בעדיו חולים וכיוצא ש\"מ דבדיעבד ש\"ד וכאן אמרי' דאפי' בדיעבד אינו כלום. ולכאורה וכאן ראיה לס' הנ\"ל מדהוצרך לומר כאן וי\"ל דסד\"א דבפני השור סגי כיון דמקשינן מיתת השור כו' כמש\"ש מ\"ה א' קמ\"ל כמ\"ש בסנה' יט:"]}],["\u0010y0\u0011 אֵין מְגַדְּלִים בְּהֵמָה דַקָּה \u0010y1\u0011 בְּאֶרֶץ יִשְׂרָאֵל, מִפְּנֵי שֶׁדַּרְכָּם לִרְעוֹת בְּשָׂדוֹת שֶׁל אֲחֵרִים וְהֶזֵּקָם מָצוּי; אֲבָל מְגַדְּלִים בְּסוּרְיָא וּבַמִּדְבָּרוֹת שֶׁבְּאֶרֶץ יִשְׂרָאֵל. וְהָאִדָּנָא, שֶׁאֵין מָצוּי שֶׁיִּהְיוּ לְיִשְׂרָאֵל בְּאֶרֶץ יִשְׂרָאֵל שָׂדוֹת, נִרְאֶה דְּשָׁרִי. \u0010y2\u0011\nלֹא יְגַדֵּל יִשְׂרָאֵל חֲזִירִים בְּכָל מָקוֹם, אֲפִלּוּ לִמְשֹׁחַ בָּהֶם עוֹרוֹת; \u0010y3\u0011 וְאֵין צָרִיךְ לוֹמַר לִסְחוֹרָה.\nאָסוּר לְגַדֵּל כֶּלֶב רָע, \u0010y4\u0011 אֶלָּא אִם כֵּן הוּא אָסוּר בְּשַׁלְשְׁלָאוֹת שֶׁל בַּרְזֶל וְקָשׁוּר בָּהֶם. וּבְעִיר הַסְמוּכָה לַסְפָר, מֻתָּר לְגַדְּלוֹ; וְקוֹשְׁרוֹ בַּיּוֹם וּמַתִּירוֹ בַּלַּיְלָה. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּהַשְׁתָּא שֶׁאָנוּ שְׁרוּיִן בֵּין הַגּוֹיִים וְאוּמוֹת בְּכָל עִנְיָן שָׁרִי, וּפוּק חַזֵּי מַאי עַמָּא דָּבַר (הַגָּהַת אַלְפָסִי הַחֲדָשִׁים)\u0006. מִיהוּ, נִרְאֶה, אִם הוּא כֶּלֶב רָע, שֶׁיֵּשׁ לָחוּשׁ שֶׁיַּזִּיק בְּנֵי אָדָם, דְּאָסוּר לְגַדְּלוֹ אֶלָּא אִם כֵּן קָשׁוּר בְּשַׁלְשְׁלָאוֹת שֶׁל בַּרְזֶל:\nמִי שֶׁנָּפְלוּ לוֹ כְּלָבִים וַחֲזִירִים בִּירֻשָּׁה, אֵין מְחַיְּבִים אוֹתוֹ לְמָכְרָם בְּיַחַד, אֶלָּא מוֹכֵר מְעַט מְעַט:",["\u0003אין מגדלין בהמה דקה כו' \u0004 בטור כתב דאפי' בבית אסור ואפי' אין הבהמה שלו דאין אדם חוטא ולא לו מ\"מ כיון שדרך בהמה דקה לצאת ולהזיק גזרו מחששא שתצא בלי ידיעת הרוע' ותזיק:","\u0003בא\"י \u0004 בגמ' והטור כ' דגם בבבל היו אוסרין כשהיו שכיחין רוב ישראל והי' להן שדות וכרמים וה\"ה לשאר ארצות אם היו בהן כן אלא שאין זה בזמנינו עיין בטור שכת' כן:","\u0003לא יגדל ישראל חזירים כו'. \u0004 משום מעשה שהי' בימי הורקנוס ואריסתובלוס גזרו כן וכתבתיהו בפריש' ע\"ש:","\u0003ואצ\"ל לסחור'. \u0004 דלסחור' אסר מדאורייתא כמ\"ש בי\"ד סי' קי\"ג דאסור לסחור בכל הדברים האסורים מן התור' לאכול אע\"פ שמותרין בהנא':","\u0003אא\"כ קשור בשלשלאות של ברזל. \u0004 דאז טעם שישוך וגם טעם שמנבח ומפילות הנשים מיראתו אין כאן כיון דיודעין שהוא קשור לא מתיראין ממנו ואינן מפילות:"],[],"\u0010y0\u0011 \u0010g0\u0011 אֵין מְגַדְּלִים בְּהֵמָה דַקָּה \u0010y1\u0011 בְּאֶרֶץ \u0010t0\u0011 יִשְׂרָאֵל, מִפְּנֵי שֶׁדַּרְכָּם לִרְעוֹת בְּשָׂדוֹת שֶׁל אֲחֵרִים וְהֶזֵּקָם מָצוּי; \u0010g1\u0011 אֲבָל מְגַדְּלִים בְּסוּרְיָא וּבַמִּדְבָּרוֹת שֶׁבְּאֶרֶץ יִשְׂרָאֵל. \u0010g2\u0011 \u0010r0\u0011 וְהָאִדָּנָא, שֶׁאֵין מָצוּי שֶׁיִּהְיוּ לְיִשְׂרָאֵל בְּאֶרֶץ יִשְׂרָאֵל שָׂדוֹת, נִרְאֶה דְּשָׁרִי. \u0010y2\u0011 \u0010g3\u0011\nלֹא יְגַדֵּל יִשְׂרָאֵל חֲזִירִים \u0010g4\u0011 בְּכָל מָקוֹם, אֲפִלּוּ לִמְשֹׁחַ בָּהֶם עוֹרוֹת; \u0010y3\u0011 וְאֵין צָרִיךְ לוֹמַר לִסְחוֹרָה. \u0010g5\u0011\nאָסוּר לְגַדֵּל כֶּלֶב רָע, \u0010y4\u0011 אֶלָּא אִם כֵּן הוּא אָסוּר בְּשַׁלְשְׁלָאוֹת שֶׁל בַּרְזֶל וְקָשׁוּר בָּהֶם. \u0010g6\u0011 וּבְעִיר הַסְמוּכָה לַסְפָר, מֻתָּר לְגַדְּלוֹ; וְקוֹשְׁרוֹ בַּיּוֹם וּמַתִּירוֹ בַּלַּיְלָה. \u0005הַגָּה: \u0010r1\u0011 וְיֵשׁ אוֹמְרִים דְּהַשְׁתָּא שֶׁאָנוּ שְׁרוּיִן בֵּין הַגּוֹיִים וְאוּמוֹת בְּכָל עִנְיָן שָׁרִי, וּפוּק חַזֵּי מַאי עַמָּא דָּבַר (הַגָּהַת אַלְפָסִי הַחֲדָשִׁים)\u0006. \u0010r2\u0011 מִיהוּ, נִרְאֶה, אִם הוּא כֶּלֶב רָע, שֶׁיֵּשׁ לָחוּשׁ שֶׁיַּזִּיק בְּנֵי אָדָם, דְּאָסוּר לְגַדְּלוֹ אֶלָּא אִם כֵּן קָשׁוּר בְּשַׁלְשְׁלָאוֹת שֶׁל בַּרְזֶל: \u0010g7\u0011\nמִי שֶׁנָּפְלוּ לוֹ כְּלָבִים וַחֲזִירִים בִּירֻשָּׁה, אֵין מְחַיְּבִים אוֹתוֹ לְמָכְרָם בְּיַחַד, אֶלָּא מוֹכֵר מְעַט מְעַט:",{"g":["א) לשון הטור וכ\"כ הרמב\"ם בפ\"ה מה' נזקי ממון ד\"ב משנה וברייתא פ\"ז דב\"ק דף ע\"ט ע\"א","ב) ם ברמב\"ם ושם במשנה","\u0003ג) וכיוצא בזה כ' הטור לענין ח\"ל:\u0004 ","ד) שם במשנה והטעם מפורש בברייתא שם סוף דף פ\"ב","\u0003ה) כ\"כ התוספת שם בשם ר\"ת בד\"ה לא יגדל אדם חזירים כו'\u0004 ליישב מה שהקשו תיפוק לי' דאסור לעשות סחורות בכל דברי' טמאים כמ\"ש וכו' (ונתבאר בי\"ד סימן קי\"ז) וכן כ' הרא\"ש שם","ו) שם ס\"ו ושם ברמב\"ם ושם במשנה","ז) ברייתא שם דף פ\"ג ע\"א","\u0003ח) ברייתא שם דף פ' ע\"א:\u0004 "],"t":["\u0003ישראל. \u0004 וכת' הטור דגם בבבל היו אוסרין כשהיו שכיחין רוב ישראל והיה להן שדות וכרמים והוא הדין לשאר ארצות אם היו בהן כו' ע\"ש וכת' עוד דאפילו בבית אסור ואפילו אם אין הבהמה שלו דאין אדם חוטא ולא לו מ\"מ כיון שדרך בהמה דקה לצאת ולהזיק גזרו מחששא שתצא בלי ידיעת הרועה ותזיק. סמ\"ע:"],"r":["\u0003והאידנא כו'. \u0004 דברי המחבר שזה לא תליא בא\"י רק ביישוב ישראל וערש\"י ותוס' פ\"א ד\"ה מכי אתא כו' ועבא\"ע סי' קמב ס\"א:","\u0003וי\"א כו'. \u0004 דדמי לספר:","\u0003מיהו כו'. \u0004 שם דרש כו' ההיא איתתא כו' ושם ספ\"ק טו ב' וספ\"ד מו א':"]}],["בּוֹר הוּא מֵאֲבוֹת נְזִיקִין, דִּכְתִיב: כִּי יִכְרֶה אִישׁ בֹּר; שֶׁמֵּאַחַר שֶׁחָפְרוּ נִתְחַיֵּב בִּנְזָקָיו, כֵּיוָן שֶׁעָשָׂה דָּבָר הַמַּזִּיק. וְזֶהוּ מָמוֹנוֹ שֶׁמַּזִּיק בְּמָקוֹם שֶׁעֲשָׂאוֹ, שֶׁאֵינוֹ זָז מִמְּקוֹמוֹ אֶלָּא עוֹמֵד בִּמְקוֹמוֹ וְהָעוֹבֵר עָלָיו נִזָּק. לְפִיכָךְ, כָּל הַדּוֹמֶה לוֹ, שֶׁהוּא מָמוֹנוֹ \u0010y0\u0011 וּמֻנָּח בִּמְקוֹמוֹ וּמַזִּיק, אֲפִלּוּ שָׁפַךְ מַיִם בִּרְשׁוּת הָרַבִּים וְהֻחְלַק בָּהֶם אַחֵר, חַיָּב:\nאֶחָד הַכּוֹרֶה בּוֹר, \u0010y1\u0011 וְאֶחָד הַפּוֹתֵחַ בּוֹר שֶׁכָּרָהוּ אַחֵר וְכִסָהוּ כָרָאוּי וּבָא זֶה וְגִלָּהוּ, חַיָּב.\nהַמּוֹצֵא בּוֹר וְכִסָהוּ וְחָזַר \u0010y2\u0011 וְגִלָּהוּ, בַּעַל הַבּוֹר חַיָּב, וְזֶה הָאַחֲרוֹן פָּטוּר. סְתָמוֹ בֶּעָפָר וְחָזַר וְהוֹצִיא אֶת כָּל הֶעָפָר, זֶה הָאַחֲרוֹן חַיָּב, שֶׁכֵּיוָן שֶׁסְתָמוֹ בֶּעָפָר \u0010y3\u0011 נִסְתַּלֵּק מַעֲשֵׂה רִאשׁוֹן.\nאֶחָד הַחוֹפֵר אוֹ הַלּוֹקֵחַ אוֹ שֶׁנִּתַּן לוֹ בְּמַתָּנָה, שֶׁנֶּאֱמַר: בַּעַל הַבּוֹר יְשַׁלֵּם, מִי שֶׁיֵּשׁ לוֹ בְּעָלִים מִכָּל מָקוֹם. וְכֵן אִם נֶחְפַּר \u0010y4\u0011 מֵאֵלָיו, אוֹ שֶׁחָפְרוּ בְּהֵמָה וְחַיָּה בִּרְשׁוּתוֹ, הוֹאִיל וְהוּא חַיָּב לְמַלּאוֹתוֹ אוֹ לְכַסוֹתוֹ וְלֹא עָשָׂה, \u0010y5\u0011 הֲרֵי זֶה חַיָּב בִּנְזִיקִין. \u0005הַגָּה: וְכֵן אִם כָּרָה אַחֵר בִּרְשׁוּתוֹ וְנוֹדַע לְבַעַל הֶחָצֵר, חַיָּב בַּעַל הֶחָצֵר לְכַסּוֹתוֹ, וְאִם לֹא כִּסָּה הָוֵי כְּאִלּוּ חֲפָרָה בְּעַצְמוֹ; וְהַכּוֹרֶה חַיָּב לְשַׁלֵּם לוֹ נִזְקֵי חֲצֵרוֹ (טוּר)\u0006.\nשׁוֹרוֹ שֶׁחָפַר בִּרְשׁוּת הָרַבִּים אוֹ בִּרְשׁוּת אַחֵר, פָּטוּר בַּעַל הַשּׁוֹר, שֶׁנֶּאֱמַר: כִּי יִכְרֶה אִישׁ בֹּר, וְלֹא שׁוֹר בּוֹר.\nאֶחָד הַחוֹפֵר בּוֹר בִּרְשׁוּת הָרַבִּים, אוֹ הַחוֹפֵר בּוֹר בִּרְשׁוּתוֹ \u0010y6\u0011 וּפְתָחוֹ \u0010y7\u0011 לִרְשׁוּת הָרַבִּים אוֹ פָּתַח לִרְשׁוּת חֲבֵרוֹ, אוֹ שֶׁחָפַר וּפָתַח לִרְשׁוּתוֹ וְהִפְקִיר רְשׁוּתוֹ וְלֹא הִפְקִיר בּוֹרוֹ, הֲרֵי זֶה חַיָּב בִּנְזָקָיו. אֲבָל אִם הִפְקִיר רְשׁוּתוֹ וּבוֹרוֹ, \u0010y8\u0011 אוֹ שֶׁהִפְקִיר בּוֹרוֹ שֶׁבִּרְשׁוּתוֹ, הֲרֵי זֶה פָטוּר. שֶׁנֶּאֱמַר: בַּעַל הַבּוֹר יְשַׁלֵּם, מִי שֶׁיֵּשׁ לוֹ בְּעָלִים, וְזֶה הֶפְקֵר, וּבַתְּחִלָּה בִּרְשׁוּת חָפַר, מִפְּנֵי שֶׁחָפַר בִּרְשׁוּתוֹ.\nהַחוֹפֵר בּוֹר \u0010y9\u0011 בִּרְשׁוּת הָרַבִּים לְצֹרֶךְ רַבִּים, וּמָסַר לָהֶם כִּסוּיוֹ, אוֹ הוֹדִיעַ לְבֵית דִּין שֶׁרוֹצֶה לְהִסְתַּלֵּק מִמֶּנּוּ, שֶׁהֵם יִתְעַסְקוּ בּוֹ לְכַסוֹתוֹ, פָּטוּר. \u0010y10\u0011 וְהוּא שֶׁחָפַר בְּמָקוֹם שֶׁיֵּשׁ רְשׁוּת לַחְפֹּר.\nהָאוֹמֵר לַחֲבֵרוֹ לַחְפֹּר בּוֹר בִּרְשׁוּת הָרַבִּים, וַחֲפָרוֹ; הַחוֹפֵר \u0010y11\u0011 חַיָּב וְהַמְשַׁלֵּחַ פָּטוּר.\nהַבּוֹנֶה סָמוּךְ לִרְשׁוּת הָרַבִּים, רַשַּׁאי לַחְפֹּר לְצֹרֶךְ הַיְסוֹד, \u0010y12\u0011 אֲפִלּוּ לְהַרְחִיבוֹ, לְצַד \u0010y13\u0011 \u0010c0\u0011 רְשׁוּת הָרַבִּים; וְאִם הֻזְּקוּ בּוֹ פָטוּר, כֵּיוָן שֶׁעָשָׂה בִּרְשׁוּת.\nאֶחָד הַחוֹפֵר \u0010y14\u0011 בּוֹר אוֹ שִׁיחַ אוֹ מְעָרָה אוֹ חָרִיץ. \u0010y15\u0011 וְלָמָּה נֶאֱמַר: בּוֹר, שֶׁיְּהֵא בּוֹ כְּדֵי לְהָמִית, דְּהַיְנוּ עֹמֶק י' טְפָחִים; אֲבָל אִם הָיָה פָּחוֹת מִי' טְפָחִים, וְנָפַל לְתוֹכוֹ שׁוֹר אוֹ שְׁאָר בְּהֵמָה חַיָּה וָעוֹף, וּמֵת, פָּטוּר. וְאִם הִזִּיק, בַּעַל הַתַּקָּלָה חַיָּב נֶזֶק שָׁלֵם.\nהָיָה עֹמֶק הַבּוֹר ט' טְפָחִים, וּמֵהֶם טֶפַח אֶחָד מַיִם, \u0010y16\u0011 חַיָּב, שֶׁהַטֶּפַח שֶׁל מַיִם חָשׁוּב כְּעֹמֶק ב' טְפָחִים בַּיַּבָּשָׁה.\nהָיָה עָמֹק שְׁמֹנָה, \u0010y17\u0011 וּמֵהֶם שְׁנֵי טְפָחִים מַיִם, אוֹ שֶׁהָיָה עָמְקוֹ ז' טְפָחִים וּמֵהֶם ג' טְפָחִים מַיִם, וְנָפַל לְתוֹכוֹ שׁוֹר וְכַיּוֹצֵא בּוֹ וָמֵת, אֵין מְחַיְּבִין אוֹתוֹ לְשַׁלֵּם, וְאִם תָּפַס אֵין מוֹצִיאִין מִיָּדוֹ. \u0005הַגָּה: וְעַיֵּן לְעֵיל סִימָן שפ\"ח סָעִיף א' וְז' \u0010y18\u0011 דְּיֵשׁ חוֹלְקִין:\u0006\nחָפַר אֶחָד שְׁמֹנָה, וּבָא חֲבֵרוֹ וְחָפַר עוֹד טֶפַח, \u0010y19\u0011 שְׁנֵיהֶם חַיָּבִים בִּנְזָקִין, כָּל אֶחָד לְפִי מַה שֶּׁחָפַר.\nהַחוֹפֵר בּוֹר עֲשָׂרָה, וּבָא אַחֵר וְהִשְׁלִימוֹ לְכ', וּבָא אַחֵר וְהִשְׁלִימוֹ לְל', \u0010y20\u0011 כֻּלָּם חַיָּבִים.\nחָפַר הָרִאשׁוֹן פָּחוֹת מִי', אֲפִלּוּ טֶפַח, וּבָא אַחֲרוֹן וְהִשְׁלִימוֹ לַעֲשָׂרָה, בֵּין שֶׁחָפַר בּוֹ טֶפַח אוֹ שֶׁהִגְבִּיהַּ בִּנְיָן עַל שְׂפָתוֹ, זֶה \u0010y21\u0011 הָאַחֲרוֹן חַיָּב \u0005אֲפִלּוּ בִּנְזִיקִין (טוּר ס\"ח)\u0006. סָתַם טֶפַח שֶׁהוֹסִיף, אוֹ שֶׁסָתַר טֶפַח שֶׁבָּנָה, \u0010y22\u0011 הֲרֵי זֶה סָפֵק אִם כְּבָר נִסְתַּלֵּק מַעֲשֵׂה רִאשׁוֹן אוֹ אִם עֲדַיִן לֹא נִסְתַּלֵּק.\nחָפַר הָרִאשׁוֹן בּוֹר עָמֹק, וּבָא הָאַחֲרוֹן וְהִרְחִיבוֹ, וְנָפַל לְתוֹכוֹ שׁוֹר וָמֵת, \u0010y23\u0011 אִם מֵחֲמַת הַבְלוֹ מֵת, הָאַחֲרוֹן פָּטוּר, שֶׁהֲרֵי מִעֵט הַבְלוֹ; וְאִם מֵחֲמַת חֲבָטוֹ מֵת, הָאַחֲרוֹן חַיָּב, שֶׁהֲרֵי הִקְרִיב הֶזֵּק בּוֹר זֶה. \u0010y24\u0011 וְכֵן אִם נָפַל הַשּׁוֹר מֵאוֹתוֹ הַצַּד שֶׁהִרְחִיב הָאַחֲרוֹן, חַיָּב, שֶׁהֲרֵי הִקְרִיב הֶזֵּק בּוֹר זֶה אַף עַל פִּי שֶׁמֵּת מִן הַהֶבֶל. \u0010y25\u0011 וְאִם מֵהַצַּד שֶׁחָפַר הָרִאשׁוֹן נָפַל, הָרִאשׁוֹן חַיָּב, שֶׁזֶּה הָאַחֲרוֹן מִעֵט הַבְלוֹ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאֵין חִלּוּק בֵּין מֵת בְּהַבְלָא אוֹ בַחֲבָטָהּ, רַק, אִם נָפַל מִצַּד שֶׁהִרְחִיב חַיָּב בְּכָל עִנְיָן, וְאִם נָפַל מִצַּד הַשֵּׁנִי, הָאַחֲרוֹן פָּטוּר בְּכָל עִנְיָן (טוּר ס\"ח בְּשֵׁם הָרֹא\"שׁ)\u0006.\nבּוֹר שֶׁחִיְּבָה עָלָיו תּוֹרָה, \u0010y26\u0011 אֲפִלּוּ לֹא מֵתָה הַבְּהֵמָה אֶלָּא מֵהַבְלוֹ, וְאֵין צָרִיךְ לוֹמַר אִם מֵתָה מֵחֲבָטוֹ. \u0010y27\u0011 לְפִיכָךְ, אִם הָיָה עֹמֶק הַבּוֹר כְּרָחְבּוֹ, אֵין לוֹ הֶבֶל; \u0010y28\u0011 וְאִם לֹא נֶחְבְּטָה בּוֹ הַבְּהֵמָה וָמֵתָה, פָּטוּר. הָיָה עָמְקוֹ יוֹתֵר עַל רָחְבּוֹ, יֵשׁ לוֹ הֶבֶל, וְאִם מֵתָה בּוֹ הַבְּהֵמָה חַיָּב, אַף עַל פִּי שֶׁלֹּא נֶחְבְּטָה בְּקַרְקָעִיתָהּ. \u0010y29\u0011\nעָשָׂה תֵּל גָּבוֹהַּ בִּרְשׁוּת הָרַבִּים, וְנֶחְבְּטָה בּוֹ הַבְּהֵמָה וָמֵתָה, אִם הָיָה גָבוֹהַּ י' טְפָחִים חַיָּב לְשַׁלֵּם. וְאִם הָיָה פָּחוֹת מִי', פָּטוּר עַל מִיתַת הַבְּהֵמָה, אֲבָל אִם הֻזְּקָה בִּלְבַד חַיָּב לְשַׁלֵּם נֶזֶק שָׁלֵם. \u0010c1\u0011 וַאֲפִלּוּ בְתֵל גָּבוֹהַּ כָּל שֶׁהוּא אוֹ בַּחֲפִירָה כָּל שֶׁהִיא, שֶׁהַנֶּזֶק בְּכָל שֶׁהוּא דָּבָר מָצוּי וְיָדוּעַ, וְאֵין הַמִּיתָה בְּכָל שֶׁהוּא מְצוּיָה, וַהֲרֵי הוּא כְּמוֹ \u0010y30\u0011 אֹנֶס.\nוְכֵן אֵינוֹ חַיָּב עַל מִיתַת הַבְּהֵמָה בַּבּוֹר אוֹ עַל חֲבָטָתָהּ בַּתֵּל, אֶלָּא אִם הָיְתָה הַבְּהֵמָה קְטַנָּה אוֹ חֵרֶשֶׁת, אוֹ שׁוֹטָה אוֹ סוּמָא, אוֹ שֶׁנָּפְלָה בַּלַּיְלָה, אֲבָל אִם הָיְתָה פִּקַּחַת וְנָפְלָה בַּיּוֹם וָמֵתָה, פָּטוּר, שֶׁזֶּה כְּמוֹ אֹנֶס, מִפְּנֵי שֶׁדֶּרֶךְ הַבְּהֵמָה לִרְאוֹת וְלָסוּר מֵהַמִּכְשׁוֹלוֹת. \u0010y31\u0011\nוְכֵן אִם נָפַל לְתוֹכוֹ אָדָם וָמֵת, אֲפִלּוּ הָיָה סוּמָא אוֹ שֶׁנָּפַל בַּלַּיְלָה, בֵּין שֶׁהָיָה בֶּן חוֹרִין אוֹ עֶבֶד, הֲרֵי זֶה פָּטוּר; וְאִם הֻזָּק בּוֹ הָאָדָם אוֹ הַבְּהֵמָה הַפִּקַּחַת, חַיָּב נֶזֶק שָׁלֵם. \u0005הַגָּה: \u0010y32\u0011 וְיֵשׁ אוֹמְרִים דְּבִּבְהֵמָה פִקַּחַת פָּטוּר אֲפִלּוּ מִנִּזָּקִין אִם נָפַל שָׁם בַּיּוֹם (טוּר סכ\"ב וְהַמַּגִּיד פֶּרֶק י\"ב דְּנִזְקֵי מָמוֹן)\u0006. \u0010y33\u0011\nנָפְלוּ כֵּלִים בַּבּוֹר וְהֻזְּקוּ אוֹ נִשְׁתַּבְּרוּ, פָּטוּר, שֶׁנֶּאֱמַר: וְנָפַל שָׁמָּה שׁוֹר אוֹ חֲמוֹר \u0005(שְׁמוֹת כא, לג)\u0006, שׁוֹר וְלֹא אָדָם, חֲמוֹר וְלֹא כֵּלִים; וְלֹא נִתְמַעֵט אָדָם אֶלָּא מִמִּיתָה, אֲבָל אִם הֻזָּק בּוֹ חַיָּב; אֲבָל עַל הַכֵּלִים פָּטוּר, בֵּין אִם נִשְׁבְּרוּ לְגַמְרֵי בֵּין אִם הֻזְּקוּ.\nכִּסָהוּ כָּרָאוּי, אַף עַל פִּי שֶׁהִתְלִיעַ מִתּוֹכוֹ, וְנָפַל לְתוֹכוֹ שׁוֹר וָמֵת, פָּטוּר, שֶׁנֶּאֱמַר: וְלֹא יְכַסֶנּוּ \u0010y34\u0011 \u0005(שְׁמוֹת כא, לג)\u0006, הָא אִם כִּסָהוּ, פָּטוּר.\nכִּסָהוּ בְּדָבָר שֶׁיָּכוֹל לַעֲמֹד בִּפְנֵי שְׁוָרִים, וְאֵינוֹ יָכוֹל לַעֲמֹד בִּפְנֵי גְּמַלִּים, וְהָלְכוּ עָלָיו גְּמַלִּים וְנִתְרוֹעֵעַ, וְהָלְכוּ עָלָיו שְׁוָרִים וְנָפְלוּ בּוֹ, אִם אֵין הַגְּמַלִּים מְצוּיִים בְּאוֹתוֹ מָקוֹם הֲרֵי זֶה פָּטוּר, מִפְּנֵי שֶׁזֶּה \u0010y35\u0011 אֹנֶס. \u0005מִיהוּ, אִם נָפַל בְּתוֹכוֹ גָמָל, אֲפִלּוּ פִּקֵּחַ, חַיָּב, דְּהוֹאִיל וְרָאָהוּ מְכֻסֶּה עָבַר עָלָיו (טוּר ס\"ט)\u0006. וְאִם יָבֹאוּ שָׁם גְּמַלִּים אֲפִלּוּ לִפְרָקִים, חַיָּב.\nהִתְלִיעַ מִתּוֹכוֹ וְנָפְלוּ בּוֹ שְׁוָרִים, אַף עַל פִּי שֶׁהַגְּמַלִּים מְצוּיִים שָׁם תָּמִיד \u0010y36\u0011 וַהֲרֵי הוּא פּוֹשֵׁעַ לַגְּמַלִּים, הוֹאִיל וּמֵחֲמַת שֶׁהִתְלִיעַ נָפְלוּ בּוֹ הַשְּׁוָרִים, פָּטוּר, וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0005הַגָּה: וְיֵשׁ מְחַלְּקִין: דְפָטוּר בִּכְהַאי גַוְנָא, דַּוְקָא שֶׁאִם הָיוּ עוֹבְרִים הַגְּמַלִּים הָיוּ נוֹפְלִים עִם הַכִּסּוּי, דְּאָז לֹא פָשַׁע כְּלָל לְגַבֵּי שְׁוָרִים, דְּאִם יַעַבְרוּ גְמַלִּים יִפֹּל הַכִּיסוּי, וְלֹא יַעַבְרוּ שְׁוָרִים פִּקְחִין כִּי יִרְאוּ שֶׁאֵינוֹ מְכֻסֶּה; אֲבָל אִם הוּא שֶׁאִם יַעַבְרוּ הַגְּמַלִּים לֹא יִפֹּל הַכִּסּוּי רַק יִתְרוֹעֵעַ, וְאִם יַעַבְרוּ אַחַר כָּךְ שְׁוָרִים יִפְּלוּ, \u0010y37\u0011 חַיָּב אַף בְּהִתְלִיעַ מִתּוֹכוֹ, דְּהוֹאִיל וּפָשַׁע לְגַבֵּי שְׁוָרִים חַיָּב אַף בְּהַתְלָעָה (טוּר ס\"ט)\u0006.\nבּוֹר שֶׁל שְׁנֵי שֻׁתָּפִין, וְעָבַר עָלָיו הָרִאשׁוֹן וְלֹא כִּסָהוּ, הַשֵּׁנִי וְלֹא כִּסָהוּ. הָרִאשׁוֹן חַיָּב, עַד שֶׁיִּמְסֹר דָּלְיוֹ לַשֵׁנִי. \u0010y38\u0011 \u0005וְיֵשׁ אוֹמְרִים דִּשְׁנֵיהֶן חַיָּבִין, עַד שֶׁיִּמְסֹר דָּלְיוֹ לַשֵּׁנִי (טוּר ס\"י)\u0006. \u0010y39\u0011 וּמִשֶּׁמָּסַר דָּלְיוֹ לַשֵּׁנִי לִדְלוֹת מִמֶּנּוּ, נִפְטָר הָרִאשׁוֹן, וְנִתְחַיֵּב הַשֵּׁנִי לְכַסוֹתוֹ:\nכִּסָהוּ הָרִאשׁוֹן, וּבָא הַשֵּׁנִי וּמְצָאוֹ מְגֻלֶּה וְלֹא כִּסָהוּ, הַשֵּׁנִי חַיָּב. וְעַד אֵימָתַי יִהְיֶה הַשֵּׁנִי חַיָּב לְבַדּוֹ, \u0010y40\u0011 עַד שֶׁיֵּדַע הָרִאשׁוֹן שֶׁהַבּוֹר מְגֻלֶּה, וּכְדֵי שֶׁיִּשְׂכֹּר פּוֹעֲלִים וְיִכְרֹת אֲרָזִים וִיכַסֶנּוּ; וְכָל שֶׁיָּמוּת בּוֹ תּוֹךְ זְמַן זֶה, הֲרֵי הַשֵּׁנִי לְבַדּוֹ חַיָּב בּוֹ, וְכָל שֶׁיָּמוּת בּוֹ אַחַר זְמַן כַּזֶּה, שְׁנֵיהֶם חַיָּבִים לְשַׁלֵּם, שֶׁהֲרֵי שְׁנֵיהֶם פָּשְׁעוּ בוֹ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּגַם לַשֵּׁנִי נוֹתְנִין זְמַן עַד שֶׁיִּשְׂכֹּר פּוֹעֲלִים וְיִכְרֹת אֲרָזִים, \u0010y41\u0011 אֶלָּא שֶׁאֵינוֹ צָרִיךְ הוֹדָעָה (טוּר סי\"ב בְּשֵׁם ר\"י וְהָרֹא\"שׁ)\u0006.\nיֵשׁ מִי שֶׁאוֹמֵר, שֶׁאִם אֵינוֹ מוֹצֵא לִקְנוֹת אֲרָזִים אֶלָּא \u0010y42\u0011 בְּיֹקֶר, צָרִיךְ לְהַמְתִּין לוֹ עַד שֶׁיִּמְצָא לִקְנוֹת בְּשָׁוְיָם.\nכָּל הַנְּזָקִים, אִם הוּא דָּבָר שֶׁאֵין דַּרְכּוֹ בְּעַצְמוֹ לְסַלְּקוֹ, אֵין מְחַיְּבִין אוֹתוֹ לְסַלְּקוֹ עַד שֶׁיִּשְׂכֹּר פּוֹעֲלִים. וְהָנֵי מִלֵּי דְאָנוּס, כְּגוֹן בּוֹר שֶׁכִּסָהוּ כָּרָאוּי וְהִתְלִיעַ, אֲבָל בּוֹר שֶׁהִנִּיחוֹ מְגֻלֶּה, פּוֹשֵׁעַ הוּא וּלְאַלְתַּר חַיָּב בִּנְזָקָיו.\nהַמְכַסֶה בּוֹרוֹ בְּדָלְיוֹ שֶׁל חֲבֵרוֹ, וּבָא בַּעַל הַדְּלִי וְנָטַל דָּלְיוֹ, \u0010y43\u0011 בַּעַל הַבּוֹר חַיָּב.\nהַמּוֹסֵר בּוֹרוֹ לְשׁוֹמֵר, חַיָּב בִּנְזָקָיו. וְאִם מְסָרוֹ לְחֵרֵשׁ שׁוֹטֶה וְקָטָן, אַף עַל פִּי שֶׁהָיָה מְכֻסֶה, הֲרֵי הַבְּעָלִים \u0010y44\u0011 חַיָּבִים, שֶׁהַבּוֹר עָשׂוּי לְהִתְגַּלּוֹת וְאֵלּוּ אֵין בָּהֶם דַּעַת:\nבּוֹר שֶׁכָּרוּי וְעוֹמֵד, וְנִכְנַס בּוֹ אָדָם לְהַרְחִיבוֹ אוֹ לְהַעֲמִיקוֹ, וְעָמַד שׁוֹר עַל שְׂפָתוֹ וְנִבְעַת מִקּוֹל הַכּוֹרֶה, וְנָפַל לְתוֹכוֹ, \u0010y45\u0011 בֵּין לְפָנָיו בֵּין לְאַחֲרָיו, חַיָּב בַּעַל הַבּוֹר, אֲפִלּוּ הַשּׁוֹר פִּקֵחַ וּבַיּוֹם; שֶׁהַכּוֹרֶה פָּטוּר שֶׁאֵינוֹ אֶלָּא גְרָמָא, וְכֵיוָן שֶׁאִי אֶפְשָׁר לְהִשְׁתַּלֵּם מִמֶּנּוּ, יִשְׁתַּלֵּם מִבַּעַל הַבּוֹר. \u0010y46\u0011 אֲבָל אִם נִבְעַת הַשּׁוֹר מִקּוֹל הַכּוֹרֶה וְנָפַל לַאֲחוֹרֵי הַבּוֹר, פָּטוּר.\nשׁוֹר שֶׁדָּחַף בְּהֵמָה לְתוֹךְ הַבּוֹר וָמֵת, אִם מוּעָד הוּא, בַּעַל הַבּוֹר מְשַׁלֵּם מֶחֱצָה וּבַעַל הַשּׁוֹר מֶחֱצָה; וְאִם תָּם הוּא, בַּעַל הַשּׁוֹר מְשַׁלֵּם רְבִיעַ מִגּוּפוֹ וּבַעַל הַבּוֹר מְשַׁלֵּם ג' חֲלָקִים מֵהַיָּפֶה שֶׁבִּנְכָסָיו; שֶׁבַּעַל הַנְּבֵלָה אוֹמֵר לְבַעַל הַבּוֹר: \u0010y47\u0011 פְּחַת נְבֵלָה זוֹ יֵשׁ לִי אֶצְלְךָ, \u0010y48\u0011 אַף עַל פִּי שֶׁהִיא גְּדוֹלָה וּפִקַּחַת, \u0010y49\u0011 כֵּיוָן שֶׁנִּדְחֲפָה, הֲרֵי זוֹ כְּמִי שֶׁנָּפְלָה בַלַּיְלָה, כָּל שֶׁאֲנִי יָכוֹל לְהוֹצִיא מִבַּעַל הַשּׁוֹר אֲנִי מוֹצִיא \u0010y50\u0011 וְהַשְּׁאָר אַתָּה חַיָּב לְשַׁלְּמוֹ.\nוְכֵן הַמַּנִּיחַ אֶבֶן עַל פִּי הַבּוֹר וּבָא הַשּׁוֹר וְנִתְקַל בָּהּ וְנָפַל לַבּוֹר וָמֵת, הַמַּנִּיחַ אֶת הָאֶבֶן מְשַׁלֵּם מֶחֱצָה, וּבַעַל הַבּוֹר מֶחֱצָה.\nאִם אָדָם וְשׁוֹר דָּחֲפוּ שׁוֹר אַחֵר לְבוֹר; וְהָיָה אָדָם שֶׁלֹּא \u0010y51\u0011 בְּכַוָּנָה, שֶׁאִם הָיָה בְּכַוָּנָה הָיָה בַּעַל הַבּוֹר פָּטוּר; שְׁלָשְׁתָּן חַיָּבִים; אִם הַשּׁוֹר מוּעָד, מְשַׁלְּשִׁים בֵּינֵיהֶם. וְאִם הוּא תָּם, \u0010y52\u0011 מְשַׁלֵּם הַשְּׁתוּת, וְהַמּוֹתָר יְשַׁלְּמוּ בֵּינֵיהֶם הָאָדָם וּבַעַל הַבּוֹר.\nאִם דָּחֲפוּ אִשָּׁה וְיָצְאוּ יְלָדֶיהָ, הָאָדָם לְבַדּוֹ חַיָּב הַכֹּל, \u0010y53\u0011 וְשׁוֹר וּבוֹר פְּטוּרִים.\nאִם דָּחֲפוּ בּוֹ אָדָם וְהֻזָּק, שְׁלָשְׁתָּם חַיָּבִים בְּנֶזֶק. וְאָדָם לְבַדּוֹ \u0010y54\u0011 \u0010c2\u0011 חַיָּב בִּשְׁאָר \u0005(ד')\u0006 דְּבָרִים. וְאִם דָּחֲפוּ בּוֹ כֵּלִים וְנִשְׁבְּרוּ, אָדָם וּבַעַל הַשּׁוֹר \u0010y55\u0011 חַיָּבִים, וּבַעַל הַבּוֹר פָּטוּר.\nיֵשׁ מִי שֶׁאוֹמֵר, הוּא הַדִּין לִשְׁנַיִם שֶׁהִזִּיקוּ וּשְׁנֵיהֶם בְּנֵי חִיּוּבָא, אֶלָּא שֶׁהָאֶחָד בָּרַח אוֹ שֶׁאֵין לוֹ בַּמֶּה לְשַׁלֵּם, מִשְׁתַּלֵּם \u0010y56\u0011 מֵהָאַחֵר עַד שִׁעוּר מַה שֶּׁהָיָה הוּא חַיָּב עַל נֶזֶק זֶה אִלּוּ עֲשָׂאוֹ לְבַדּוֹ. \u0010c3\u0011 וְיֵשׁ חוֹלְקִין דְּכֵיוָן דַּחֲבֵירוֹ מִדִּינָא בַּר תַּשְׁלוּמִין אֶלָּא שֶׁאֵין לוֹ מַה לְּשַׁלֵּם, לָמָּה יִפְרַע זֶה בִּשְׁבִילוֹ. וּלְפִי זֶה, שׁוֹר שֶׁדָּחַף בְּהֵמָה לְבוֹר, הָאִדָּנָא אֵינוֹ מְשַׁלֵּם אֶלָּא ג' חֲלָקִים; אַף עַל פִּי שֶׁהַשּׁוֹר פָּטוּר אַף מֵהָרְבִיעַ, שֶׁהֲרֵי אֵין דָּנִין דִּינֵי קְנָסוֹת, אֵין בַּעַל הַבּוֹר מְשַׁלֵּם אוֹתוֹ בִּשְׁבִילוֹ.\nהַחוֹפֵר בּוֹר בִּרְשׁוּת הָרַבִּים וְנָפַל עָלָיו שׁוֹר וַהֲרָגוֹ, \u0010y57\u0011 בַּעַל הַשּׁוֹר פָּטוּר. וְאִם מֵת הַשּׁוֹר, נוֹטֵל בַּעַל הַשּׁוֹר דְּמֵי שׁוֹרוֹ \u0010y58\u0011 מִיּוֹרְשֵׁי בַּעַל הַבּוֹר:",["\u0003ומונח במקומו ומזיק כו'. \u0004 ל' הטור אם הוא בעומק או בגובה או אפילו לא זה ולא זה אלא שפך מים כו' ועפ\"ר:","\u0003ואחד הפותח בור \u0004 דכתיב בפרשת משפטים גבי אהדדי כי יפתח איש בור או כי יכרה איש בור ולא יכסנו ונפל שמה שור או חמור בעל הבור ישלם כו' ומדכתיב ולא יכסנו ש\"מ דבהכיסוי הוא פטור ומינה נלמד דמ\"ש כי יפתח איש בור בעל הבור ישלם דהפותח הכיסוי נקרא בעל הבור ומחייב בתשלומי הניזקין שיפלו בה:","\u0003בעל הבור חייב. \u0004 עפ\"ר שכתבתי בשם המ\"מ דאפי' ראה הראשון דכיסהו שני ולא ראה שחזר וגילהו אפ\"ה הראשון חייב דלא ה\"ל לסמוך אהכיסוי של זה שאין לו חלק בבור משא\"כ בבור של שני שותפין כדלקמן בסימן זה:","\u0003נסתלק מעשה הראשון. \u0004 פי' כאלו לא חפרו מעולם והשני חפרו מחדש:","\u0003או שחפרו בהמה וחיה כו'. \u0004 פי' אע\"ג דכתיב כי יכרה איש בור וכמ\"ש המחבר בסעיף שאחר זה ה\"מ בחופר בר\"ה דהקרקע אינו שלו וכיון דהוא לא חפר אין עליו למלאות קרקע שאינו שלו משא\"כ בחפר' בהמתו בחצירו דלא גרע מנחפר בור שם מאליו דמוזהר עכ\"פ שלא יוזק אדם ממונו דהיינו חצירו שהוא קרקע שלו שיש בו בור והיינו דוקא אם הפקיר חצירו שסביב הבור ולא הפקיר באותו פעם גם מקום הבור דאל\"כ אלא דלא הפקיר כלל יכול לומר מה לאחרים לילך בחצרי דאתחייב בשמירתן וה\"ל דומיא דהיזק רגל בחצר הניזק דפטור כמ\"ש בסי' ש\"ץ ושצ\"א ואם הפקיר אח\"כ הבור וחצירו שסביבו בפעם אחת ג\"כ לא נתחייב על היזק הבור כיון דבשעת הכריה הי' הכל שלו ושוב לא עשה מעשה בחפיר' דיתחייב עליו משא\"כ כשחפר תחילה בחצירו ואחר כך הפקיר מקום שסביב לבור ונותן רשות לכל לקרב נפשם סמוך לבור דהוה ליה כפותח בור לר\"ה דמחויב לשמור בורו מהזיקתן וכמ\"ש הטור והמחבר בסמוך בסעיף ו' ומשם נלמד ג\"כ זה שכתבתי דמיירי שהפקיר רשותו לחוד ולא שניהן יחד ואחר שהפקיר רשותו לחוד אף שאח\"כ ג\"כ הפקיר בורו חייב על נזקי' דלאו כל כמיניה להפקיר נזקיו שכבר עליו החיוב לסלק התקל' וע\"ל בטור ובדברי המחבר ר\"ס שצ\"ח ובפרישה מ\"ש עוד מזה:","\u0003ה\"ז חייב בניזקין \u0004 מדלא כתבו בדין זה ג\"כ השיעור בכדי שידע וישכור פועלים ויכרתו ארזים כמ\"ש לקמן בסכ\"ו נראה דזה דומה לחופר בור והניחו מגולה דכתב הטור והמחבר לקמן בסכ\"ח דמחשב פשיעה ולאלתר חייב בניזקין והוא הדין בור שחפרו השור בחצירו כיון דעליו מוטל לטרוח ולכסותו:","\u0003ופתחו לר\"ה. ל' הטור שפתחו ברשותו בתוך ד\"ט סמוך לר\"ה עכ\"ל וה\"ט דכל ד\"ט סמוך לר\"ה דחקי ביה רבים אבל בפתחו לרשות חבירו בעינן שיסמכו לרשות חבירו ומ\"ה לא כתב הטור ד\"ט כ\"א בסמוך לר\"ה ועפ\"ר:\u0004","\u0003או פתחו לרשות חבירו כו'. \u0004 ז\"ל הטור ומיהו דוקא קודם שנודע לבעל החצר אבל אחר שנודע לו פטור הכורה כיון דהוא חייב בניזקי הבעל החצר הי' לו לבעל החצר למלאותו מיד וזה יפרע לו וכיון דלא מלאוהו כמאן דכרייה איהו דמי עכ\"ל ואף ע\"פ שהבור אינו ברשות בעל החצר הניזק אלא ברשות החצר המזיק רק שפתוח לרשות הניזק מ\"מ כיון שעומדת סמוך לחצר הניזק ממש וכמ\"ש ה\"ל כאלו עומדת בחצר הניזק ועליו לסתמו להרחיק ממנו נזקו ויקבל שכר טרחתו מהכורה:","\u0003או שהפקיר בורו שברשותו כו'. \u0004 הוא מטעם שכתבתי כיון דלא הי' להניזק רשות ליכנס ולהקריב להבור אין בעל הבור חייב בשמירתו:","\u0003לצורך רבים כו'. \u0004 בטור בשם הרמ\"ה כתב דאי חפר מעיקרא לצורך עצמו והדר מימלך למימסרי' לרבים דלא נפטר החופר עד דטמים ליה וכתב עליו הטור ז\"ל ואינו נראה כיון דמסרו עתה לרבים והן צריכים לו מאי נ\"מ שחפרו מתחלה לצרכו עכ\"ל:","\u0003והוא שחפר במקום שיש לו רשות לחפור \u0004 כן כתב ג\"כ הטור בשם הרמ\"ה ז\"ל והני מילי שחפר לצורך רבים במקום שיש לו רשות לחפור כו' ור\"ל דאפילו בר\"ה אינו מותר לחפור לצורך רבים אלא כשכורה במקום שאינו מעבר לרבים וכדומה לו שמזיק לרבים וק\"ל:","\u0003והמשלח פטור. \u0004 משום דאין שליח לדבר עבירה וע\"ל בר\"ס קפ\"ב:","\u0003אפי' להרחיבו לצד ר\"ה \u0004 נראה דר\"ל ל\"מ דמותר לעשות ברשותו בתוך ד\"ט סמוך לר\"ה אף דבלא לצורך בנין הוה אסור וכמ\"ש בסמוך בס\"ו אלא אפי' לחפור עד סוף גבול והיינו שהרחיב קצה הבור עד שהיה עומדת פתוח' בצד ר\"ה ממש מותר:","\u0003ואם הוזקו בו פטור כו'. \u0004 ול\"ד למש\"ר לקמן בסי' תי\"ד בהוצאת זבלים בר\"ה או בהנחת קוריו ועציו לצורך בנין בס\"ס תי\"ז דג\"כ עשאו ברשות ואפ\"ה אם מקלקלין ומזיקין שם דחייב דשאני התם דעושה בר\"ה עצמו משא\"כ כאן דהבור עומד ברשותו וגם הוא לשעה ומיד אחר החפירה יחזור לסותמו באבני הבנין שיניח ביסוד חומתו ומה\"ט אינו דומה לעושה תנור בביתו והרחיקו כשיעור מהעלי' ואפ\"ה אם הודלק העליה דחייב על העלייה כמ\"ש הטור והמחבר בר\"ס קנ\"ה דשם הוא עושה כן תדיר משא\"כ זה שעושה לפי שעה וכ\"כ הרי\"ף כתבתיהו בדרישה ע\"ש מ\"ש עוד מזה:","\u0003בור או שיח כו'. \u0004 במתני' קתני ג\"כ ונעיצין ול\"מ בכולן קאמר ל\"מ בור דהוא קטן ועגול ובהפשיטא דחייב דיש בה הבל אלא אפילו שיח שהוא ארוך ואפי' מערה שהיא מרובעת ואפילו חריצין שאין מקורין ואפי' נעיצין שהן רויחי מעילאי טפי מתתאי דלית בה הבל אלא דבר מועט קמ\"ל דאפ\"ה חייב ושם במשנה סיים וקתני ז\"ל אף כל הדומה לבור ומפרשו שמואל דבא לרבות בהאי כל כגון שעשה תל גבוה י' טפחים וכתבתי בפרי' דאליבי' (דאלו לרב מיושב בע\"א וכתבתי בדרישה ע\"ש) ה\"ק המשנה ל\"מ הני דאית בהו הבלא וחבטה אלא אפי' דבר דלית בהו הבל כלל כגון עשה תל ונכשל בה או נפל מעליו ג\"כ חייב:","\u0003ולמה נאמר בור. \u0004 פי' למה כתבה התורה כי יכרה איש בור לחייב עליו כיון דאפי' אהני ג\"כ חייב ומשני דנקט בור דהוא ידוע בשיעור עמיקתו וכאלו אמר דנקט בור לרבותא לענין פטור דאפי' בור אם אינו עמוק י\"ט ונפל שמה שור או חמור ומת פטור דה\"ל מיתה אונס דאין דרך הבהמה למות בנפיל' בפחות מי\"ט ק\"ו לשיח ומערה כשאינן גבוהין י\"ט:","\u0003שהטפח של מים חשוב כו'. \u0004 פי' נחשב לענין הבל שיש הבל במים יותר מבאויר:","\u0003ומהם שני טפחים מים כו'. \u0004 איבעיא הוא בגמרא דלא איפשטא אי גם בכה\"ג יחשב כל טפח מים לשני טפחים אויר ומ\"ה אם אינן אלא ז' עם המים דהיינו ג' טפחים עמקות המים וע\"ג המים עוד ד' טפחים אויר אי ג\"כ הוה לענין הבל כעומק עשרה טפחים דג\"ט של מים יחשבו כששה של אויר והרי עשרה טפחים ביחד או לא ובכזה אמרי' המע\"ה ועפ\"ר שם כתבתי שיש גירסאות בזה ושהטור כתב הגירסא שבעומק ח' ומהן ב\"ט של מים פשיטא להגמ' דנחשב כשתים שהן ארבע וחייב והאיבעיא היא דוקא בבור של ז' ומהן ג\"ט של מים או בשל ט' ומהן טפח א' של מים (דקמבעיא ליה אי נחשב טפח א' של מים להבל) ע\"ש:","\u0003די\"ח. \u0004 פי' חולקין וס\"ל דלא מהני תפיסה בספיקא דדינא:","\u0003שניהן חייבין בניזקין. \u0004 דקדק וכתב בניזקין לאפוקי נפלה שם בהמה ומתה דפטור כל שאינו עמוק עשרה וכנ\"ל:","\u0003כולם חייבים \u0004 פי' אפילו לענין אם נפלה שם בהמה ומתה כיון דיש במעשה דכל אחד כדי להמית וכח דכולם מעורבים בו.","\u0003האחרון חייב אפילו בניזקין \u0004 דכיון דבור זה נקרא ע\"ש האחרון לחוד לענין תשלומין כשנפל שם ומת נקרא ג\"כבורולחוד לענין ניזקין:","\u0003הרי זה טפח כו' איבעיא דלא איפשיטא הוא שם בגמרא אם מחויב תו האחרון בתשלומי ניזקין שיזיק בהבור שאינו עמוק עשרה מי אמרינן כיון דבשע' שהוסיף טפח היה הוא בעל הבור לחוד לחייב עליה וכמ\"ש מאותה שעה נסתלק מעשה הראשון גם לענין זה דאף שלאחר שחזר והסיר התוספות נקרא הבור על שמו או נימא דחזר הדבר לקדמותו מיד שהסיר מה שהוסיף וחייב הראשון ולא השני וכיון דלא איפשטא דינא הוי דהמע\"ה להמחבר ולהחולקין לא מהני ת\"ה וכמ\"ש בס\"ב.\u0004","\u0003אם מחמת הבלו מת האחרון פטור. \u0004 נראה דר\"ל שנפל לבור דרך פיה למטה ומתה וניכר הדבר להרואים שמתה מחמת הבל ולא מחמת חבטה ואם מחמת חבטה היינו שנפלה לבור על גבה וניכר להרואים שלא מתה אלא מחמת החבט' ומיירי בבבא זו כשנפל מצד שלא הרחיב וכדמסיק ואפ\"ה מסיק דחייב כשמת בחבטה שהרי הקריב היזק בור זה כו' ור\"ל דכיון דהיא גרם היזק לענין חבט' אם נפל מצד שהרחיב מקרי בעל הבור לענין חבט' אף כשיפול מיד השניי' ועפ\"ר:","\u0003וכן אם נפל השור כו'. \u0004 אפילו מתה מחמת הבלו חייב וה\"ט דכיון שהוא פושע לענין שור זה עצמו דהי' ראוי למות מחמת חבטה שקירב מיתתו לענין חבטה תלינן נמי בו מיתה מהבל אף ע\"פ שמיעט הוא מהבל וכמ\"ש הרא\"ש והטור והמחבר דומה לזה סמוך לענין אם פשע בשור לענין גמלים אלא שאינו דומה ממש כיון דכאן נראה לעינים דמיעט ההבל ומ\"ה השיג הטור אדברי הרמב\"ם בזה:","\u0003ואם מהצד שחפר הא' כו'. \u0004 פי' אף כשמת מההבל וכבר כתב המחבר בריש סעיף זה דבכה\"ג האחרון פטור וכאן קמ\"ל דהראשון חייב ולא אמרי' דנסתלק מעשה הראשון כשהרחיב זה הבור:","\u0003אפילו לא מתה הבהמה אלא מהבלו \u0004 ואצ\"ל אם מתה מחבטה כ\"כ ג\"כ הרמב\"ם והל' אינו מדוקדק ע\"פ פלוגתת רב ושמואל דרב ס\"ל דלא מחייב משום בור אא\"כ מתה מהבל הבור ולא מהחבט' כיון דהוא קרקע עולם (אם לא שהבור ברשותו וסמך לר\"ה דאז קרקעית הבור דידי' הוא) ולשמואל חייב נמי אם מתה בחבט' וקי\"ל כוותי' והנה לרב לא א\"ש דהא ס\"ל דפטור אם מתה בחבט' ולשמואל הל\"ל איפכא אפי' מתה בחבט' ואצ\"ל בהבלא וצ\"ל דלסברת שמואל מאחר דחייבי התור' אחבט' אף שהיא קרקע עולם תו יש סברא לחייבו יותר ע\"י חבט' דיש בו מעש' טפי ממת' ע\"י הבל הבור דאין בו אלא כעין גרמא:","\u0003לפיכך אם היה עומק הבור כרחבו כו'. \u0004 פטור הטעם דמתה באונס שלא כדרך מיתת הבהמות והרי לא היה כאן לא חבט' ולא הבל והאי לפיכך דכתב נמשך למ\"ש בבבא שניי' וה\"ק כיון דחייב על הבלא בלא חבט' לפיכך אם היה עומקו יותר כו' חייב.","\u0003ואם לא נחבט' בו הבהמה כו'. \u0004 בטור מפורש כגון שהי' בתוכו ספוגין שהן רכים ואינ' ניזקה מחבטת' עליהן:","\u0003עשה תל גבוה בר\"ה ונחבטה בו הבהמה כו' \u0004 קמ\"ל בזה דאע\"ג דאין כאן הבל אפ\"ה חייב כיון דמתה מחמת חבט' וק\"ק דלענין אם נחבט' בתל עצמו א\"צ גבוהי' דהא אפי' נתקל הבהמ' בקרקע עולם והוזק' באבן ומת' חייב כמ\"ש הטור והמחבר בסי' שאחר זה גם ה\"ל לכתוב רבותא כאן דאפי' לא נחבט בתל אלא בקרקע עולם וכן בסעיף שאחר זה דכתב ז\"ל וכן אינו חייב כו' עד או על חבטת' בתל ובטור כתב ז\"ל דאם עשה תל בר\"ה גבוה י' ועלה עליו שור ונפלה לארץ ומתה חייב וזה א\"ש דתל דומה לבור דאם נפל מלמעל' למט' בעינן גבוה י' כיון דהוזק' לבסוף בקרקע עולם:","\u0003וכן אינו חייב על מיתת הבהמה בבור או כו'. \u0004 כצ\"ל וכתב בבור ל' מיתה ור\"ל בין שמת' בחבט' בין בהבל משא\"כ בתל שאין שם הבל כ' בו ל' חבט':","\u0003וכן אם נפל לתוכה אדם ומת כו'. \u0004 דכתיב ונפל שמה שור או חמור. ושור וחמור ל\"ד הוא דהא ילפי' שור שור משבת דעל כל בהמה חייב וא\"כ למה נכתב שור וחמור ודרשינן שור ולא אדם חמור ולא כלים ומיעוט דשור ולא אדם היינו דוקא אם נפל שם האדם ומת דקרא זה במית' איירי כדכתיב בו והמת יהי' לו אבל אם נפל שם אדם והוזק לא נתמעט מתשלומי הזיקו אבל כלים דאיתמעטו אתמעטו ואפי' בשבירתן דהא שבירתן זהו מיתתן וכ\"כ המחבר בסעיף שאחר זה:","\u0003וי\"א דבבהמה פקחת פטור כו' \u0004 דבהמ' עיני' למט' ודרכ' להתבונן בדרכי' ולהשמר מנזקי' משא\"כ אדם שהולך ועינו משוטטו' למעל' ולהלן מדרך הלוכו וכמ\"ש בסימן תי\"ב ס\"ג בדברי המחבר גם בטו' ע\"ש:","\u0003נפלו כלים לבור כו'. \u0004 ל' הטור ואפי' נפל שם השור עם הכלים ומת השור ונשתברו הכלים חייב על השור ופטור על הכלים:","\u0003הא אם כסהו פטור. \u0004 קמ\"ל דל\"ת דעליו לסתמו בעפר באופן שלא יוכל להגיע ממנ' היזק:","\u0003מיהו אם נפל בתוכו גמל כו'. \u0004 פי' אע\"ג דגמלים אינם שכיחי' כלל מ\"מ ה\"ל לאסוקי אדעתי' שמא יבא אבל אם נפל שמה שור כולי האי לא ה\"ל לאסוקי אדעתי' כשאין גמלים שכיחים שיבא גמל ויארעוהו ואח\"כ יבא שור ויפול בו:","\u0003והרי הוא פושע לגמלי'. \u0004 פי' דאם עברו שם גמלים היו נופלים שם השוורי' והגמלי' שכיחי' וה\"ל פושע מתחלתו שמא יעברו שם גמלים מ\"מ הואיל ולא עברו גמלים ולא נפלו לבור אלא מכח שהתליע הכיסוי ה\"ל אונס שלא בא מחמת הפשיע' ופטו' וע\"ז כ' מור\"ם דיש מחלקין וס\"ל דחיי' בזה:","\u0003חייב אף בהתליע מתוכו הטור כתב מילתא בטעמא יותר והוא כיון דפשע לענין השור זה עצמו דהרי זה השור שנפל כאן מחמת התלעה ג\"כ הי' נופל שם אם הי' שעברו שם גמלים וקלקלו הכיסוי (משא\"כ כשנפל בבור שור פקח דאף שפשע לענין נפיל' שור חרש או סומא מ\"מ לענין שור פקח שנפל שם לא הי' בו צד פשיע') כיון דפשע מתחל' בשור זה עצמו אף שבסופו הי' האונס מחמת התלעה ונראה דאינו מחמת הפשיע' מ\"מ כל שפשע מתחלה באותו דבר עצמו כל מאי דאפשר לתלות בו תלינן אף בחשש רחוק (ובפרט התלעה שהוא ג\"כ דבר שאינו שכיח וכ\"ד שא\"ש הוא על המיעוט) ותלינן לומר שאם הי' מכסהו בכיסוי חזק שראוי לעמוד לפני הגמלים לא הי' נתלע ועפ\"ר מ\"ש עוד מזה יותר כאן וגם לעיל ר\"ס שצ\"ו:\u0004","\u0003וי\"א דשניהן חייבין הא דכתב מור\"ם בל' י\"א משום שנ\"ל מוכח דהראשון חייב דכ' הרמב\"ם והמחבר ר\"ל דחייב הראשון לבדו דאם לא כן אלא תאמר מ\"ש חייב הראשון ר\"ל אף הראשון וכמו שפי' הרא\"ש לדברי הרי\"ף א\"כ מ\"ש אחר זה עד שימסר דליו לשני ע\"כ ר\"ל דכוונתו דאז נתחייב השני לבדו ותו לא הוה צ\"ל ז\"ל ומי שמסר דליו להשני כו' נתחייב השני לכסותו וק\"ל ומה\"ט כתב הטור ג\"כ אל' הרמב\"ם שהוא כל' המחבר ול\"נ כו' ע\"ש וכמ\"ש בדרישה ולא כב\"י שתמה על הטור עבור זה:\u0004","\u0003ומשמסר דליו להשני לדלות. משמע דמפרש דליו מלשון דלי וכן פי' ר\"ח אבל רש\"י והטור פירשו דליו כיסוי הבור ע\"ש:\u0004","\u0003עד שידע הראשון דקדק וכ' עד שידע דהיינו שהודיעו ממש ולא די בכדי זמן שיכול להוודע דדילמא לא נודע לו ואח\"כ כ' וכדי שישכור פועלים כו' דאחר שנודע לו והי' לו שהות זמן לשכור פועלים ולא שכרם מאז גם הוא יש לו חלק בתשלומי נזקין ועפ\"ר:\u0004","\u0003אלא שאינו צריך הודעה דהא מיירי שכבר ידע דהא מתחל' כ' ובא השני ומצאוהו מגול':\u0004","\u0003צריך להמתין לו כו'. ע\"ש בטור ובפריש' שם כתבתי הוכחתם:\u0004","\u0003בעל הבור חייב. בטור מסיים בזה וכתב ז\"ל ואין בעל הכיסוי צריך להודיעו שנטלו ע' ד\"מ שכתבתי ליישב דל\"ת מזה למ\"ש הרא\"ש דחייב הנוטל (והביאו מור\"ם בהג\"ה לעיל סימן שפ\"ג ס\"ד) דשאני התם בתשובה דהסומך חביתו בר\"ה באבן של חבירו ובא חבירו ונטל אבנו דנשבר החביו' מיד וה\"ל כהזיקו בידים משא\"כ כאן בגיל' הבור דאין ההיזק בא מיד אלא לאחר זמן כשיפול שם בהמת חבירו וגם לא ברי כ\"כ היזקו:\u0004","\u0003שהבור עשוי להתגלות. ע\"ל בסי' שצ\"ו ס\"ו בדין המוסר שורו ביד חש\"ו דכתב דאפי' היה קשור בהחבל מחשב פשיעת בעלים משום שדרך השור להתיר הקשר ופירש התו' דר\"ל דחש\"ו בעצמן יתירוהו נראה דה\"ה כאן י\"ל כיון דלאו בני דעה נינהו חיישינן שיגלו להבור העשויה להתגלות בקל כי בגמ' אתאמרו הני שני דינים יחד ע\"ש שכתבתי שם לשון הגמרא:\u0004","\u0003בין לפניו בין לאחריו. \u0004 פירוש דאם נפל השור דרך פניו מסתמא מת בהבל ואם מת בבור דרך אחוריו אז מסתמא לא מת מכח הבל אלא מחמת חבטה וכנ\"ל וכבר נתבאר דקי\"ל דחייב בעל הבור בין מת בחבט' בין בהבל ועיין ברמב\"ם שכתב דאם נפלה מאחריה לבור פטור אבל הראב\"ד וגם המ\"מ תמהו שם על דבריו ע\"ש:","\u0003אבל אם נבעת השור מקול הכורה ונפל לאחורי הבור. \u0004 כן הוא ג\"כ ל' הרמב\"ם ובטור כתב אבל נבעת מקול הכור' ונתקל בבור ונפל כו' והטעם דפטור כיון דקרקע עולם הזיקתו והוא דומה לנתקל באבן וניזק בקרקע דפטור כמ\"ש הטור והמחבר בסי' תי\"א ס\"א:","\u0003פחת נביל' זו יש לי אצלך. שהרי בבורך מצאתי הזיקי:\u0004","\u0003אע\"פ שהיא גדולה ופקחת כו' \u0004 בטור כתב האי אע\"פ ברישא וז\"ל שור שדחף בהמה לבור אע\"פ שהוא ביום ופקחת כו' וא\"ש טפי ונוסחת המחבר והרמב\"ם צ\"ל דהניזק מדבר כן עם בעל השור דפחת נבילתו היא אצלו לחוד אע\"פ כו' ומ\"ה כל שאני יכול להוציא כו':","\u0003כיון שנדחפה כו'. \u0004 דהיה לבעל הבור לאסוקי אדעתי' שמא ידחפנו אותו שור שם ויגרם בורו היזק לבעל השור:","\u0003והשאר אתה חייב לשלמו. \u0004 היינו דין דאמר רבי נתן בגמ' כל היכא דליכא לאשתלומי מהאי משתלם מהאי:","\u0003שאם היה בכונה כו' \u0004 הוא מטע' שכתבו התו' ז\"ל דאטו אם ישים אדם טליתו של חבירו באש מי מחייב בעל האש:","\u0003משלם השתות. \u0004 דכיון שיש שנים עמו אין מגיע אלא שליש לנזק שלם והשתא דהוא תם אם עשה היזק לחוד לא היה משלם אלא חצי נזק חצי' מחלק שלו הוא שתות:","\u0003ושור ובור פטורים. \u0004 פי' בעל השור ובעל הבור פטורים השור מדכתיב וכי ינצו אנשים ולא שוורים ובור דרשינן שור ולא אדם וכנ\"ל וכיון דליכא לאשתלומי מהני משתלם מאדם כולה:","\u0003חייב בשאר ד' דברי'. \u0004 דאיש בעמיתו כתיב:","\u0003ובעל הבור פטור \u0004 דחמור כתיב ולא כלים וכנ\"ל","\u0003עד שיעור מה שהי' הוא חייב כו'. \u0004 בטור מבואר זה יותר ז\"ל ודוקא עד שיעור מה שהי' חייב ביה אהאי נזקא היכא דהו' עביד ליה איהו לבדו אבל טפי לא עכ\"ל ולכאורה הי' נראה לפרש דר\"ל משום דלפעמים נחבל וניזק יותר מדחיפת שנים מבדחיפת א' ובא לומר דבכה\"ג אין האחד צריך לשלם כל הנזק הנעשה ע\"י שניהן כיון דאין הא' יכול להזיקו כ\"כ אבל ק' דה\"ט שייך גם בדחפו כלים לבור ונשברו דאי לאו בור לא היו נשברים הכלים מדחיפת האדם ואפ\"ה קאמר לפני זה דצריך האדם לשלם כל נזק. הכלים ☜לכן נר' דלא אתי לאפוקי אלא כגון אדם ושור שדחפו אדם והזיקוהו שנתבא' לפני זה שבדמי היזקו המה משותפי' ובשאר ד' דברי' האדם צריך לשלמן לבדו ולמדונו כאן דאם ברח האדם אזי על בעל השור חיוב לשלם כל דמי נזקו כאלו הזיקו לבדו אבל שאר ד' דברים א\"צ לשלם עבור האדם שברח ואע\"ג דבעל השור עומד בחיוב התשלומין בעד האדם לא אמרינן דעומד במקומו בכולו משום דאף אם הי' מזיקו השור לבדו לא הי' חייב לשלם ודוק:","\u0003בעל השור פטור. \u0004 דאיהו גרם ההפסד לנפשו בחפירתו:","\u0003מיורשי בעל הבור. \u0004 רצה לומר ל\"מ דאם הוא חי דצריך לשלם השור אלא אפילו מת הכורה צריכי' בניו היורשים לשלם לבעל השור הזיקו ואע\"פ דמלוה על פה של ראובן אינן נפרעין מיורשיו אחרי מותו שאני הכא כיון דאביהן עכשיו מת בשעה שנפל שם השור בודאי לא פרע להן עדיין דמי השור ועפ\"ר:"],["\u0003 ואם הוזקו בו פטור. \u0004 וביש\"ש כתב שהוא טעות וחייב לשלם והש\"ס איירי כשכנס החומה לתוך שלו והחפירה הוא בחלק הכניסה ע\"ש שהוכיח כן ודלא כמ\"ש בסמ\"ע ס\"ק י\"ד וכ\"כ הב\"ח:","\u0003 ואפילו בתל גבוה \u0004 מלשון זה נראה אפילו התל והחפירה הוא פחות מג' טפחים ומהרש\"ל סימן כ\"ד כתב דכל פחות מג' טפחים הוא כארעא סמיכתא ופטור דלא מיקרי בור ולדבריו צ\"ל דל\"ד קאמר המחבר והרמב\"ם כל שהוא וכה\"ג אשכחן פ' ראשית הגז ומסכת נדה ופרק העור והרוטב וכמה כל שהוא כו' אמנם מדברי המרדכי סוף הבית והעלי' ומדברי הרב לקמן סימן תי\"ד ס\"ב בהג\"ה מוכח לכאורה דאף פחות מג\"ט אף דאינם יכולים לעכב מ\"מ אם הזיק חייב לשלם ודמי למוציא זבלים שלא בשע' הוצאת זבלים כדי לפנותו לאלתר ודו\"ק במרדכי ואם כן צ\"ע לדינא:","\u0003 חייב בשאר ד' דברים \u0004 והא דחייב בבושת אף דע\"כ איירי שדחפו שלא בכוונה כמ\"ש סל\"ד צ\"ל כמ\"ש התוספת כגון שידע אדם בשעת נפילת חבירו והשיב בכונה ומהרש\"ל סימן מ\"ב פסק דפטור מבשת אא\"כ שבתחלה דחפו השור ואח\"כ בא האדם להוסיף עליו וע\"ש שהאריך ודבריו דחוקים ע\"ש:","\u0003 וי\"ח \u0004 וכ\"כ הג\"ה מיי' ומרדכי בשם מהר\"ם וכ\"פ מהרש\"ל פ\"ה דב\"ק סי' מ' ע\"ש במהרש\"ל ובתוספת פ' כיצד הרגל ועיין בהגהות מיי' דיש ליישב דגם דברי מהר\"ם הראשונים אינם סותרים זה (והב\"י וב\"ח ומהרש\"ל לא הבינו כן) ועיין בסוף ספר שארית יוסף שכתב בכאן דברים שאינם מוכרחים:"],"\u0010g0\u0011 בּוֹר הוּא מֵאֲבוֹת נְזִיקִין, דִּכְתִיב: כִּי יִכְרֶה אִישׁ בֹּר; שֶׁמֵּאַחַר שֶׁחָפְרוּ נִתְחַיֵּב בִּנְזָקָיו, כֵּיוָן שֶׁעָשָׂה דָּבָר הַמַּזִּיק. \u0010r0\u0011 וְזֶהוּ מָמוֹנוֹ \u0010r1\u0011 שֶׁמַּזִּיק בְּמָקוֹם שֶׁעֲשָׂאוֹ, \u0010r2\u0011 שֶׁאֵינוֹ זָז מִמְּקוֹמוֹ אֶלָּא עוֹמֵד בִּמְקוֹמוֹ וְהָעוֹבֵר עָלָיו \u0010g1\u0011 \u0010r3\u0011 נִזָּק. לְפִיכָךְ, כָּל הַדּוֹמֶה לוֹ, שֶׁהוּא מָמוֹנוֹ \u0010y0\u0011 וּמֻנָּח בִּמְקוֹמוֹ וּמַזִּיק, \u0010g2\u0011 אֲפִלּוּ שָׁפַךְ מַיִם בִּרְשׁוּת הָרַבִּים וְהֻחְלַק בָּהֶם אַחֵר, \u0010g3\u0011 חַיָּב:\nאֶחָד הַכּוֹרֶה בּוֹר, \u0010y1\u0011 וְאֶחָד הַפּוֹתֵחַ בּוֹר שֶׁכָּרָהוּ אַחֵר וְכִסָהוּ כָרָאוּי וּבָא זֶה \u0010g4\u0011 וְגִלָּהוּ, חַיָּב.\nהַמּוֹצֵא בּוֹר וְכִסָהוּ וְחָזַר \u0010y2\u0011 וְגִלָּהוּ, בַּעַל הַבּוֹר \u0010t0\u0011 חַיָּב, וְזֶה הָאַחֲרוֹן פָּטוּר. סְתָמוֹ בֶּעָפָר וְחָזַר וְהוֹצִיא אֶת כָּל הֶעָפָר, זֶה הָאַחֲרוֹן חַיָּב, שֶׁכֵּיוָן שֶׁסְתָמוֹ בֶּעָפָר \u0010y3\u0011 נִסְתַּלֵּק מַעֲשֵׂה רִאשׁוֹן. \u0010g5\u0011 \u0010r4\u0011\nאֶחָד הַחוֹפֵר אוֹ הַלּוֹקֵחַ אוֹ שֶׁנִּתַּן לוֹ בְּמַתָּנָה, שֶׁנֶּאֱמַר: בַּעַל הַבּוֹר יְשַׁלֵּם, מִי שֶׁיֵּשׁ לוֹ בְּעָלִים \u0010r5\u0011 מִכָּל מָקוֹם. וְכֵן \u0010g6\u0011 אִם נֶחְפַּר \u0010y4\u0011 \u0010r6\u0011 מֵאֵלָיו, אוֹ שֶׁחָפְרוּ \u0010t1\u0011 בְּהֵמָה וְחַיָּה בִּרְשׁוּתוֹ, הוֹאִיל וְהוּא חַיָּב לְמַלּאוֹתוֹ אוֹ \u0010t2\u0011 לְכַסוֹתוֹ וְלֹא עָשָׂה, \u0010y5\u0011 הֲרֵי זֶה חַיָּב בִּנְזִיקִין. \u0005הַגָּה: \u0010r7\u0011 וְכֵן אִם כָּרָה אַחֵר בִּרְשׁוּתוֹ וְנוֹדַע לְבַעַל הֶחָצֵר, חַיָּב בַּעַל הֶחָצֵר לְכַסּוֹתוֹ, וְאִם לֹא כִּסָּה הָוֵי כְּאִלּוּ חֲפָרָה בְּעַצְמוֹ; וְהַכּוֹרֶה חַיָּב לְשַׁלֵּם לוֹ נִזְקֵי \u0010g7\u0011 חֲצֵרוֹ (טוּר)\u0006. \u0010g8\u0011\nשׁוֹרוֹ שֶׁחָפַר בִּרְשׁוּת הָרַבִּים אוֹ בִּרְשׁוּת אַחֵר, פָּטוּר בַּעַל הַשּׁוֹר, שֶׁנֶּאֱמַר: כִּי יִכְרֶה אִישׁ בֹּר, וְלֹא שׁוֹר בּוֹר. \u0010g9\u0011 \u0010r8\u0011\nאֶחָד \u0010r9\u0011 הַחוֹפֵר בּוֹר בִּרְשׁוּת הָרַבִּים, \u0010r10\u0011 אוֹ הַחוֹפֵר בּוֹר בִּרְשׁוּתוֹ \u0010y6\u0011 וּפְתָחוֹ \u0010y7\u0011 \u0010t3\u0011 לִרְשׁוּת הָרַבִּים אוֹ \u0010r11\u0011 פָּתַח לִרְשׁוּת \u0010t4\u0011 חֲבֵרוֹ, אוֹ שֶׁחָפַר וּפָתַח לִרְשׁוּתוֹ \u0010r12\u0011 וְהִפְקִיר רְשׁוּתוֹ וְלֹא הִפְקִיר בּוֹרוֹ, הֲרֵי זֶה חַיָּב בִּנְזָקָיו. \u0010g10\u0011 \u0010r13\u0011 אֲבָל אִם הִפְקִיר רְשׁוּתוֹ וּבוֹרוֹ, \u0010y8\u0011 \u0010r14\u0011 אוֹ שֶׁהִפְקִיר בּוֹרוֹ שֶׁבִּרְשׁוּתוֹ, הֲרֵי זֶה פָטוּר. שֶׁנֶּאֱמַר: בַּעַל הַבּוֹר יְשַׁלֵּם, מִי שֶׁיֵּשׁ לוֹ בְּעָלִים, וְזֶה הֶפְקֵר, וּבַתְּחִלָּה בִּרְשׁוּת חָפַר, מִפְּנֵי שֶׁחָפַר בִּרְשׁוּתוֹ. \u0010g11\u0011\nהַחוֹפֵר בּוֹר \u0010y9\u0011 \u0010t5\u0011 בִּרְשׁוּת הָרַבִּים לְצֹרֶךְ רַבִּים, \u0010g12\u0011 \u0010r15\u0011 וּמָסַר לָהֶם \u0010g13\u0011 \u0010r16\u0011 כִּסוּיוֹ, אוֹ הוֹדִיעַ לְבֵית דִּין שֶׁרוֹצֶה לְהִסְתַּלֵּק מִמֶּנּוּ, שֶׁהֵם יִתְעַסְקוּ בּוֹ לְכַסוֹתוֹ, פָּטוּר. \u0010y10\u0011 וְהוּא שֶׁחָפַר בְּמָקוֹם שֶׁיֵּשׁ \u0010t6\u0011 רְשׁוּת \u0010g14\u0011 לַחְפֹּר.\nהָאוֹמֵר לַחֲבֵרוֹ לַחְפֹּר בּוֹר בִּרְשׁוּת הָרַבִּים, וַחֲפָרוֹ; הַחוֹפֵר \u0010y11\u0011 חַיָּב וְהַמְשַׁלֵּחַ פָּטוּר. \u0010g15\u0011\nהַבּוֹנֶה סָמוּךְ לִרְשׁוּת הָרַבִּים, רַשַּׁאי לַחְפֹּר לְצֹרֶךְ הַיְסוֹד, \u0010y12\u0011 \u0010r17\u0011 אֲפִלּוּ לְהַרְחִיבוֹ, לְצַד \u0010y13\u0011 \u0010c0\u0011 רְשׁוּת הָרַבִּים; וְאִם הֻזְּקוּ בּוֹ \u0010t7\u0011 פָטוּר, כֵּיוָן שֶׁעָשָׂה בִּרְשׁוּת. \u0010g16\u0011\nאֶחָד הַחוֹפֵר \u0010y14\u0011 בּוֹר אוֹ שִׁיחַ אוֹ מְעָרָה אוֹ חָרִיץ. \u0010y15\u0011 וְלָמָּה נֶאֱמַר: בּוֹר, שֶׁיְּהֵא בּוֹ כְּדֵי לְהָמִית, דְּהַיְנוּ עֹמֶק י' טְפָחִים; אֲבָל אִם הָיָה פָּחוֹת מִי' טְפָחִים, וְנָפַל לְתוֹכוֹ שׁוֹר אוֹ שְׁאָר בְּהֵמָה חַיָּה וָעוֹף, וּמֵת, פָּטוּר. \u0010g17\u0011 וְאִם הִזִּיק, בַּעַל הַתַּקָּלָה חַיָּב נֶזֶק שָׁלֵם. \u0010g18\u0011\nהָיָה עֹמֶק הַבּוֹר ט' טְפָחִים, וּמֵהֶם טֶפַח אֶחָד מַיִם, \u0010y16\u0011 חַיָּב, שֶׁהַטֶּפַח שֶׁל מַיִם חָשׁוּב כְּעֹמֶק ב' טְפָחִים בַּיַּבָּשָׁה. \u0010g19\u0011 \u0010r18\u0011\nהָיָה עָמֹק שְׁמֹנָה, \u0010y17\u0011 וּמֵהֶם שְׁנֵי טְפָחִים מַיִם, אוֹ שֶׁהָיָה עָמְקוֹ ז' טְפָחִים וּמֵהֶם ג' טְפָחִים מַיִם, וְנָפַל לְתוֹכוֹ שׁוֹר וְכַיּוֹצֵא בּוֹ וָמֵת, אֵין מְחַיְּבִין אוֹתוֹ לְשַׁלֵּם, וְאִם תָּפַס אֵין מוֹצִיאִין מִיָּדוֹ. \u0005הַגָּה: וְעַיֵּן לְעֵיל סִימָן שפ\"ח סָעִיף א' וְז' \u0010y18\u0011 דְּיֵשׁ \u0010t8\u0011 חוֹלְקִין:\u0006 \u0010g20\u0011 \u0010r19\u0011\nחָפַר אֶחָד שְׁמֹנָה, וּבָא חֲבֵרוֹ וְחָפַר עוֹד טֶפַח, \u0010y19\u0011 שְׁנֵיהֶם חַיָּבִים בִּנְזָקִין, כָּל אֶחָד לְפִי מַה שֶּׁחָפַר. \u0010g21\u0011 \u0010r20\u0011\nהַחוֹפֵר בּוֹר עֲשָׂרָה, וּבָא אַחֵר וְהִשְׁלִימוֹ לְכ', וּבָא אַחֵר וְהִשְׁלִימוֹ לְל', \u0010y20\u0011 \u0010t9\u0011 כֻּלָּם \u0010g22\u0011 חַיָּבִים.\nחָפַר הָרִאשׁוֹן פָּחוֹת מִי', אֲפִלּוּ טֶפַח, וּבָא אַחֲרוֹן וְהִשְׁלִימוֹ לַעֲשָׂרָה, בֵּין שֶׁחָפַר בּוֹ טֶפַח אוֹ שֶׁהִגְבִּיהַּ בִּנְיָן עַל שְׂפָתוֹ, זֶה \u0010y21\u0011 הָאַחֲרוֹן \u0010g23\u0011 חַיָּב \u0005אֲפִלּוּ בִּנְזִיקִין (טוּר ס\"ח)\u0006. \u0010g24\u0011 סָתַם טֶפַח שֶׁהוֹסִיף, אוֹ שֶׁסָתַר טֶפַח שֶׁבָּנָה, \u0010y22\u0011 הֲרֵי זֶה סָפֵק אִם כְּבָר נִסְתַּלֵּק מַעֲשֵׂה רִאשׁוֹן אוֹ אִם עֲדַיִן לֹא נִסְתַּלֵּק. \u0010g25\u0011\nחָפַר הָרִאשׁוֹן בּוֹר עָמֹק, וּבָא הָאַחֲרוֹן וְהִרְחִיבוֹ, וְנָפַל לְתוֹכוֹ שׁוֹר וָמֵת, \u0010y23\u0011 אִם מֵחֲמַת \u0010t10\u0011 הַבְלוֹ מֵת, הָאַחֲרוֹן פָּטוּר, שֶׁהֲרֵי מִעֵט הַבְלוֹ; וְאִם מֵחֲמַת \u0010t11\u0011 חֲבָטוֹ מֵת, הָאַחֲרוֹן חַיָּב, שֶׁהֲרֵי הִקְרִיב הֶזֵּק בּוֹר זֶה. \u0010y24\u0011 וְכֵן אִם נָפַל הַשּׁוֹר מֵאוֹתוֹ הַצַּד שֶׁהִרְחִיב הָאַחֲרוֹן, חַיָּב, שֶׁהֲרֵי הִקְרִיב הֶזֵּק בּוֹר זֶה אַף עַל פִּי שֶׁמֵּת מִן הַהֶבֶל. \u0010y25\u0011 וְאִם מֵהַצַּד שֶׁחָפַר הָרִאשׁוֹן נָפַל, הָרִאשׁוֹן חַיָּב, שֶׁזֶּה הָאַחֲרוֹן מִעֵט הַבְלוֹ. \u0005הַגָּה: \u0010r21\u0011 וְיֵשׁ אוֹמְרִים דְּאֵין חִלּוּק בֵּין מֵת בְּהַבְלָא אוֹ בַחֲבָטָהּ, רַק, אִם נָפַל מִצַּד שֶׁהִרְחִיב חַיָּב בְּכָל עִנְיָן, וְאִם נָפַל מִצַּד הַשֵּׁנִי, הָאַחֲרוֹן פָּטוּר בְּכָל עִנְיָן (טוּר ס\"ח בְּשֵׁם \u0010g26\u0011 הָרֹא\"שׁ)\u0006. \u0010g27\u0011 \u0010r22\u0011\nבּוֹר שֶׁחִיְּבָה עָלָיו תּוֹרָה, \u0010y26\u0011 אֲפִלּוּ לֹא מֵתָה הַבְּהֵמָה אֶלָּא מֵהַבְלוֹ, וְאֵין צָרִיךְ לוֹמַר אִם מֵתָה מֵחֲבָטוֹ. \u0010y27\u0011 \u0010g28\u0011 \u0010r23\u0011 לְפִיכָךְ, אִם הָיָה עֹמֶק הַבּוֹר כְּרָחְבּוֹ, אֵין לוֹ הֶבֶל; \u0010y28\u0011 וְאִם לֹא נֶחְבְּטָה בּוֹ הַבְּהֵמָה וָמֵתָה, \u0010t12\u0011 פָּטוּר. הָיָה עָמְקוֹ יוֹתֵר עַל רָחְבּוֹ, יֵשׁ לוֹ הֶבֶל, וְאִם מֵתָה בּוֹ הַבְּהֵמָה חַיָּב, אַף עַל פִּי שֶׁלֹּא נֶחְבְּטָה בְּקַרְקָעִיתָהּ. \u0010y29\u0011 \u0010g29\u0011\nעָשָׂה תֵּל גָּבוֹהַּ בִּרְשׁוּת הָרַבִּים, וְנֶחְבְּטָה \u0010t13\u0011 בּוֹ הַבְּהֵמָה וָמֵתָה, אִם הָיָה גָבוֹהַּ י' טְפָחִים חַיָּב לְשַׁלֵּם. וְאִם הָיָה פָּחוֹת מִי', פָּטוּר עַל מִיתַת הַבְּהֵמָה, אֲבָל אִם הֻזְּקָה בִּלְבַד חַיָּב לְשַׁלֵּם נֶזֶק שָׁלֵם. \u0010c1\u0011 \u0010r24\u0011 וַאֲפִלּוּ בְתֵל גָּבוֹהַּ כָּל \u0010t14\u0011 שֶׁהוּא אוֹ בַּחֲפִירָה כָּל שֶׁהִיא, שֶׁהַנֶּזֶק בְּכָל שֶׁהוּא דָּבָר מָצוּי וְיָדוּעַ, וְאֵין הַמִּיתָה בְּכָל שֶׁהוּא מְצוּיָה, וַהֲרֵי הוּא כְּמוֹ \u0010y30\u0011 \u0010g30\u0011 אֹנֶס.\nוְכֵן אֵינוֹ חַיָּב עַל מִיתַת הַבְּהֵמָה בַּבּוֹר אוֹ עַל חֲבָטָתָהּ בַּתֵּל, אֶלָּא אִם הָיְתָה הַבְּהֵמָה קְטַנָּה אוֹ חֵרֶשֶׁת, אוֹ שׁוֹטָה אוֹ סוּמָא, אוֹ שֶׁנָּפְלָה בַּלַּיְלָה, אֲבָל אִם הָיְתָה פִּקַּחַת וְנָפְלָה בַּיּוֹם וָמֵתָה, פָּטוּר, שֶׁזֶּה כְּמוֹ אֹנֶס, מִפְּנֵי שֶׁדֶּרֶךְ הַבְּהֵמָה לִרְאוֹת וְלָסוּר מֵהַמִּכְשׁוֹלוֹת. \u0010y31\u0011 \u0010g31\u0011\nוְכֵן אִם נָפַל לְתוֹכוֹ אָדָם וָמֵת, אֲפִלּוּ הָיָה סוּמָא אוֹ שֶׁנָּפַל בַּלַּיְלָה, בֵּין שֶׁהָיָה בֶּן חוֹרִין אוֹ עֶבֶד, הֲרֵי זֶה פָּטוּר; \u0010g32\u0011 \u0010r25\u0011 וְאִם הֻזָּק בּוֹ הָאָדָם \u0010r26\u0011 אוֹ הַבְּהֵמָה \u0010g33\u0011 הַפִּקַּחַת, חַיָּב נֶזֶק שָׁלֵם. \u0005הַגָּה: \u0010y32\u0011 וְיֵשׁ אוֹמְרִים דְּבִּבְהֵמָה פִקַּחַת פָּטוּר \u0010t15\u0011 אֲפִלּוּ מִנִּזָּקִין אִם נָפַל שָׁם בַּיּוֹם (טוּר סכ\"ב וְהַמַּגִּיד פֶּרֶק י\"ב \u0010g34\u0011 דְּנִזְקֵי מָמוֹן)\u0006. \u0010y33\u0011 \u0010g35\u0011\nנָפְלוּ \u0010t16\u0011 כֵּלִים בַּבּוֹר וְהֻזְּקוּ אוֹ נִשְׁתַּבְּרוּ, פָּטוּר, \u0010g36\u0011 שֶׁנֶּאֱמַר: וְנָפַל שָׁמָּה שׁוֹר אוֹ חֲמוֹר \u0005(שְׁמוֹת כא, לג)\u0006, שׁוֹר וְלֹא אָדָם, חֲמוֹר וְלֹא כֵּלִים; \u0010g37\u0011 וְלֹא נִתְמַעֵט אָדָם אֶלָּא מִמִּיתָה, אֲבָל אִם הֻזָּק בּוֹ חַיָּב; אֲבָל עַל הַכֵּלִים פָּטוּר, \u0010r27\u0011 בֵּין אִם נִשְׁבְּרוּ לְגַמְרֵי בֵּין אִם \u0010g38\u0011 הֻזְּקוּ.\nכִּסָהוּ כָּרָאוּי, \u0010r28\u0011 אַף עַל פִּי שֶׁהִתְלִיעַ מִתּוֹכוֹ, וְנָפַל לְתוֹכוֹ שׁוֹר וָמֵת, פָּטוּר, שֶׁנֶּאֱמַר: וְלֹא יְכַסֶנּוּ \u0010y34\u0011 \u0005(שְׁמוֹת כא, לג)\u0006, הָא אִם כִּסָהוּ, פָּטוּר. \u0010g39\u0011\nכִּסָהוּ בְּדָבָר שֶׁיָּכוֹל לַעֲמֹד בִּפְנֵי שְׁוָרִים, וְאֵינוֹ יָכוֹל לַעֲמֹד בִּפְנֵי גְּמַלִּים, וְהָלְכוּ עָלָיו גְּמַלִּים וְנִתְרוֹעֵעַ, וְהָלְכוּ עָלָיו שְׁוָרִים וְנָפְלוּ בּוֹ, \u0010r29\u0011 אִם אֵין הַגְּמַלִּים מְצוּיִים בְּאוֹתוֹ מָקוֹם הֲרֵי זֶה פָּטוּר, מִפְּנֵי שֶׁזֶּה \u0010y35\u0011 \u0010r30\u0011 אֹנֶס. \u0005מִיהוּ, אִם נָפַל בְּתוֹכוֹ גָמָל, \u0010r31\u0011 אֲפִלּוּ פִּקֵּחַ, חַיָּב, דְּהוֹאִיל וְרָאָהוּ מְכֻסֶּה עָבַר עָלָיו \u0010g40\u0011 (טוּר ס\"ט)\u0006. \u0010r32\u0011 וְאִם יָבֹאוּ שָׁם גְּמַלִּים אֲפִלּוּ לִפְרָקִים, \u0010g41\u0011 חַיָּב.\nהִתְלִיעַ מִתּוֹכוֹ וְנָפְלוּ בּוֹ שְׁוָרִים, אַף עַל פִּי שֶׁהַגְּמַלִּים מְצוּיִים שָׁם תָּמִיד \u0010y36\u0011 וַהֲרֵי הוּא פּוֹשֵׁעַ לַגְּמַלִּים, הוֹאִיל וּמֵחֲמַת שֶׁהִתְלִיעַ נָפְלוּ בּוֹ הַשְּׁוָרִים, פָּטוּר, וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0005הַגָּה: \u0010r33\u0011 וְיֵשׁ מְחַלְּקִין: דְפָטוּר בִּכְהַאי גַוְנָא, דַּוְקָא שֶׁאִם הָיוּ עוֹבְרִים הַגְּמַלִּים הָיוּ נוֹפְלִים עִם הַכִּסּוּי, דְּאָז לֹא פָשַׁע כְּלָל לְגַבֵּי שְׁוָרִים, דְּאִם יַעַבְרוּ גְמַלִּים יִפֹּל הַכִּיסוּי, וְלֹא יַעַבְרוּ שְׁוָרִים פִּקְחִין כִּי יִרְאוּ שֶׁאֵינוֹ מְכֻסֶּה; אֲבָל אִם הוּא שֶׁאִם יַעַבְרוּ הַגְּמַלִּים לֹא יִפֹּל הַכִּסּוּי רַק יִתְרוֹעֵעַ, וְאִם יַעַבְרוּ אַחַר כָּךְ שְׁוָרִים יִפְּלוּ, \u0010y37\u0011 חַיָּב אַף בְּהִתְלִיעַ מִתּוֹכוֹ, דְּהוֹאִיל \u0010g42\u0011 וּפָשַׁע לְגַבֵּי שְׁוָרִים חַיָּב אַף בְּהַתְלָעָה \u0010g43\u0011 (טוּר ס\"ט)\u0006. \u0010g44\u0011 \u0010r34\u0011\nבּוֹר שֶׁל שְׁנֵי שֻׁתָּפִין, וְעָבַר עָלָיו הָרִאשׁוֹן וְלֹא כִּסָהוּ, הַשֵּׁנִי וְלֹא כִּסָהוּ. הָרִאשׁוֹן חַיָּב, עַד שֶׁיִּמְסֹר דָּלְיוֹ לַשֵׁנִי. \u0010y38\u0011 \u0010r35\u0011 \u0005וְיֵשׁ אוֹמְרִים דִּשְׁנֵיהֶן חַיָּבִין, עַד שֶׁיִּמְסֹר דָּלְיוֹ לַשֵּׁנִי (טוּר ס\"י)\u0006. \u0010y39\u0011 וּמִשֶּׁמָּסַר דָּלְיוֹ לַשֵּׁנִי \u0010t17\u0011 לִדְלוֹת מִמֶּנּוּ, נִפְטָר הָרִאשׁוֹן, וְנִתְחַיֵּב הַשֵּׁנִי לְכַסוֹתוֹ: \u0010g45\u0011\nכִּסָהוּ הָרִאשׁוֹן, וּבָא הַשֵּׁנִי וּמְצָאוֹ מְגֻלֶּה וְלֹא כִּסָהוּ, הַשֵּׁנִי חַיָּב. וְעַד אֵימָתַי יִהְיֶה הַשֵּׁנִי חַיָּב לְבַדּוֹ, \u0010y40\u0011 \u0010r36\u0011 עַד שֶׁיֵּדַע הָרִאשׁוֹן שֶׁהַבּוֹר מְגֻלֶּה, וּכְדֵי שֶׁיִּשְׂכֹּר פּוֹעֲלִים וְיִכְרֹת אֲרָזִים וִיכַסֶנּוּ; וְכָל שֶׁיָּמוּת בּוֹ תּוֹךְ זְמַן זֶה, הֲרֵי הַשֵּׁנִי לְבַדּוֹ חַיָּב בּוֹ, וְכָל שֶׁיָּמוּת בּוֹ אַחַר זְמַן כַּזֶּה, שְׁנֵיהֶם חַיָּבִים לְשַׁלֵּם, שֶׁהֲרֵי שְׁנֵיהֶם פָּשְׁעוּ בוֹ. \u0005הַגָּה: \u0010r37\u0011 וְיֵשׁ אוֹמְרִים דְּגַם לַשֵּׁנִי נוֹתְנִין זְמַן עַד שֶׁיִּשְׂכֹּר פּוֹעֲלִים וְיִכְרֹת אֲרָזִים, \u0010y41\u0011 אֶלָּא שֶׁאֵינוֹ צָרִיךְ הוֹדָעָה (טוּר סי\"ב בְּשֵׁם \u0010g46\u0011 ר\"י וְהָרֹא\"שׁ)\u0006. \u0010g47\u0011 \u0010r38\u0011\nיֵשׁ מִי שֶׁאוֹמֵר, שֶׁאִם אֵינוֹ מוֹצֵא לִקְנוֹת אֲרָזִים אֶלָּא \u0010y42\u0011 בְּיֹקֶר, צָרִיךְ לְהַמְתִּין לוֹ עַד שֶׁיִּמְצָא לִקְנוֹת \u0010g48\u0011 בְּשָׁוְיָם.\nכָּל הַנְּזָקִים, אִם הוּא דָּבָר שֶׁאֵין דַּרְכּוֹ בְּעַצְמוֹ לְסַלְּקוֹ, אֵין מְחַיְּבִין אוֹתוֹ לְסַלְּקוֹ עַד שֶׁיִּשְׂכֹּר פּוֹעֲלִים. \u0010r39\u0011 וְהָנֵי מִלֵּי דְאָנוּס, כְּגוֹן בּוֹר שֶׁכִּסָהוּ כָּרָאוּי וְהִתְלִיעַ, אֲבָל בּוֹר שֶׁהִנִּיחוֹ מְגֻלֶּה, פּוֹשֵׁעַ הוּא וּלְאַלְתַּר חַיָּב בִּנְזָקָיו. \u0010g49\u0011\nהַמְכַסֶה בּוֹרוֹ בְּדָלְיוֹ שֶׁל חֲבֵרוֹ, וּבָא בַּעַל הַדְּלִי \u0010t18\u0011 וְנָטַל דָּלְיוֹ, \u0010y43\u0011 בַּעַל הַבּוֹר \u0010g50\u0011 \u0010r40\u0011 חַיָּב.\nהַמּוֹסֵר בּוֹרוֹ לְשׁוֹמֵר, \u0010g51\u0011 חַיָּב בִּנְזָקָיו. \u0010g52\u0011 וְאִם מְסָרוֹ לְחֵרֵשׁ שׁוֹטֶה וְקָטָן, \u0010g53\u0011 \u0010r41\u0011 אַף עַל פִּי שֶׁהָיָה מְכֻסֶה, הֲרֵי הַבְּעָלִים \u0010y44\u0011 חַיָּבִים, שֶׁהַבּוֹר עָשׂוּי \u0010t19\u0011 לְהִתְגַּלּוֹת וְאֵלּוּ אֵין בָּהֶם דַּעַת: \u0010g54\u0011\nבּוֹר שֶׁכָּרוּי וְעוֹמֵד, וְנִכְנַס בּוֹ אָדָם לְהַרְחִיבוֹ אוֹ לְהַעֲמִיקוֹ, וְעָמַד שׁוֹר עַל שְׂפָתוֹ וְנִבְעַת מִקּוֹל הַכּוֹרֶה, וְנָפַל לְתוֹכוֹ, \u0010y45\u0011 \u0010g55\u0011 \u0010r42\u0011 בֵּין לְפָנָיו בֵּין לְאַחֲרָיו, חַיָּב בַּעַל הַבּוֹר, \u0010g56\u0011 אֲפִלּוּ הַשּׁוֹר פִּקֵחַ וּבַיּוֹם; \u0010g57\u0011 שֶׁהַכּוֹרֶה פָּטוּר שֶׁאֵינוֹ אֶלָּא גְרָמָא, \u0010g58\u0011 וְכֵיוָן שֶׁאִי אֶפְשָׁר לְהִשְׁתַּלֵּם מִמֶּנּוּ, יִשְׁתַּלֵּם מִבַּעַל הַבּוֹר. \u0010y46\u0011 \u0010g59\u0011 אֲבָל אִם נִבְעַת הַשּׁוֹר מִקּוֹל הַכּוֹרֶה וְנָפַל לַאֲחוֹרֵי הַבּוֹר, \u0010t20\u0011 פָּטוּר. \u0010g60\u0011 \u0010r43\u0011\nשׁוֹר שֶׁדָּחַף בְּהֵמָה לְתוֹךְ הַבּוֹר וָמֵת, אִם מוּעָד הוּא, בַּעַל הַבּוֹר מְשַׁלֵּם מֶחֱצָה וּבַעַל הַשּׁוֹר מֶחֱצָה; וְאִם תָּם הוּא, בַּעַל הַשּׁוֹר מְשַׁלֵּם רְבִיעַ מִגּוּפוֹ וּבַעַל הַבּוֹר מְשַׁלֵּם ג' חֲלָקִים מֵהַיָּפֶה שֶׁבִּנְכָסָיו; \u0010r44\u0011 שֶׁבַּעַל הַנְּבֵלָה אוֹמֵר לְבַעַל הַבּוֹר: \u0010y47\u0011 פְּחַת נְבֵלָה זוֹ יֵשׁ לִי \u0010t21\u0011 אֶצְלְךָ, \u0010y48\u0011 \u0010r45\u0011 אַף עַל פִּי שֶׁהִיא גְּדוֹלָה וּפִקַּחַת, \u0010y49\u0011 כֵּיוָן \u0010t22\u0011 שֶׁנִּדְחֲפָה, הֲרֵי זוֹ כְּמִי שֶׁנָּפְלָה בַלַּיְלָה, כָּל שֶׁאֲנִי יָכוֹל לְהוֹצִיא מִבַּעַל הַשּׁוֹר אֲנִי מוֹצִיא \u0010y50\u0011 וְהַשְּׁאָר אַתָּה חַיָּב לְשַׁלְּמוֹ. \u0010g61\u0011\nוְכֵן הַמַּנִּיחַ אֶבֶן עַל פִּי הַבּוֹר וּבָא הַשּׁוֹר וְנִתְקַל בָּהּ וְנָפַל לַבּוֹר וָמֵת, הַמַּנִּיחַ אֶת הָאֶבֶן מְשַׁלֵּם מֶחֱצָה, וּבַעַל הַבּוֹר מֶחֱצָה. \u0010g62\u0011 \u0010r46\u0011\nאִם אָדָם וְשׁוֹר דָּחֲפוּ שׁוֹר אַחֵר לְבוֹר; \u0010g63\u0011 וְהָיָה אָדָם שֶׁלֹּא \u0010y51\u0011 בְּכַוָּנָה, שֶׁאִם הָיָה \u0010t23\u0011 בְּכַוָּנָה הָיָה בַּעַל הַבּוֹר פָּטוּר; שְׁלָשְׁתָּן חַיָּבִים; אִם הַשּׁוֹר מוּעָד, מְשַׁלְּשִׁים בֵּינֵיהֶם. וְאִם הוּא תָּם, \u0010y52\u0011 \u0010g64\u0011 מְשַׁלֵּם הַשְּׁתוּת, וְהַמּוֹתָר יְשַׁלְּמוּ בֵּינֵיהֶם הָאָדָם וּבַעַל הַבּוֹר. \u0010g65\u0011\nאִם דָּחֲפוּ אִשָּׁה וְיָצְאוּ יְלָדֶיהָ, הָאָדָם לְבַדּוֹ חַיָּב הַכֹּל, \u0010y53\u0011 \u0010g66\u0011 וְשׁוֹר וּבוֹר \u0010g67\u0011 פְּטוּרִים. \u0010g68\u0011\nאִם דָּחֲפוּ בּוֹ אָדָם וְהֻזָּק, שְׁלָשְׁתָּם \u0010g69\u0011 חַיָּבִים בְּנֶזֶק. וְאָדָם לְבַדּוֹ \u0010y54\u0011 \u0010c2\u0011 חַיָּב בִּשְׁאָר \u0005(ד')\u0006 \u0010t24\u0011 דְּבָרִים. וְאִם דָּחֲפוּ בּוֹ כֵּלִים וְנִשְׁבְּרוּ, אָדָם וּבַעַל הַשּׁוֹר \u0010y55\u0011 \u0010g70\u0011 חַיָּבִים, וּבַעַל הַבּוֹר פָּטוּר. \u0010g71\u0011 \u0010r47\u0011\nיֵשׁ מִי שֶׁאוֹמֵר, הוּא הַדִּין לִשְׁנַיִם שֶׁהִזִּיקוּ וּשְׁנֵיהֶם בְּנֵי חִיּוּבָא, אֶלָּא שֶׁהָאֶחָד בָּרַח אוֹ שֶׁאֵין לוֹ בַּמֶּה לְשַׁלֵּם, מִשְׁתַּלֵּם \u0010y56\u0011 מֵהָאַחֵר עַד שִׁעוּר מַה שֶּׁהָיָה הוּא חַיָּב עַל נֶזֶק זֶה אִלּוּ עֲשָׂאוֹ \u0010t25\u0011 לְבַדּוֹ. \u0010c3\u0011 \u0010g72\u0011 \u0010r48\u0011 וְיֵשׁ \u0010t26\u0011 חוֹלְקִין דְּכֵיוָן דַּחֲבֵירוֹ מִדִּינָא בַּר תַּשְׁלוּמִין אֶלָּא שֶׁאֵין לוֹ מַה לְּשַׁלֵּם, לָמָּה יִפְרַע זֶה בִּשְׁבִילוֹ. \u0010g73\u0011 \u0010r49\u0011 וּלְפִי זֶה, שׁוֹר שֶׁדָּחַף בְּהֵמָה לְבוֹר, הָאִדָּנָא אֵינוֹ מְשַׁלֵּם אֶלָּא ג' חֲלָקִים; אַף עַל פִּי שֶׁהַשּׁוֹר פָּטוּר אַף מֵהָרְבִיעַ, שֶׁהֲרֵי אֵין דָּנִין דִּינֵי קְנָסוֹת, אֵין בַּעַל הַבּוֹר מְשַׁלֵּם אוֹתוֹ בִּשְׁבִילוֹ. \u0010g74\u0011\nהַחוֹפֵר בּוֹר בִּרְשׁוּת הָרַבִּים וְנָפַל עָלָיו שׁוֹר וַהֲרָגוֹ, \u0010y57\u0011 בַּעַל הַשּׁוֹר \u0010t27\u0011 פָּטוּר. וְאִם מֵת הַשּׁוֹר, נוֹטֵל בַּעַל הַשּׁוֹר דְּמֵי שׁוֹרוֹ \u0010y58\u0011 \u0010t28\u0011 מִיּוֹרְשֵׁי בַּעַל הַבּוֹר:",{"g":["א) ל' הטור וכ' בין הפקירו או לא הפקירו חייב ובר\"ה איירי כיון שעשאו שלא ברשות ומבואר בסעיף ו' וז':","ב) שם בפ\"ק ד' וג' ע\"ב ובפ\"ג דף כח ע\"ב","\u0003ג) משנה שם בפ\"ג דף ל' ע\"א:\u0004 ","ד) שם ס\"ב ושם בגמ' פ\"ה דף מט ע\"ב ויליף לה מדכתיב וכי יפתח וכי יכר' וכו'","ה) ל' הרמב\"ם שם דף ו' מבואר בסוגיא דפ\"ג דף כט ע\"ב וכדא\"ל מר זוטרא בריה דרבא לרבינא","\u0003ו) שם דף ד':\u0004 ","\u0003ז) מימרא דרבא הכניס שורו לחצר בעל הבית וכו'\u0004 שם בפ\"ה דף מ\"ח ע\"א","ח) היינו מימרא דרבא הנזכר לעיל וכדלעיל סימן שצח ס\"ג","ט) שם בגמ'","י) ל' הרמב\"ם שם דין ב' וכת' ה' המגיד מחלוקת שם (דף מט ע\"ב) ופסק כר\"ע ואליבא דרבה או כר' ישמעאל ואליבא דרב יוסף שם (דף נ' ע\"א)","כ) כ' ה' המגיד דבר פשוט ומוסכם מרוב המפרשים ז\"ל שהרי על הכרייה אינו חייב שברשות כרה וכשהפקירו הרי סלק עצמו מן הכל:","\u0003ל) טור ס\"ג מברייתא החופר בר\"ה לצורך רבים כו'\u0004 שם דף כ' ע\"א","מ) כ\"כ הרא\"ש שם וטעמו מדאמרינן גבי של ב' שותפים ראשון מאימת מיפטר משימסו' לו דליו שם ד' ב\"א ע\"ב","נ) שם בשם הרמ\"ה","\u0003ס) שם ס\"ד מסוגיא דגמ' שם אי דשוי שליח כו'\u0004 אין שלד\"ע שם דף נ\"א ע\"א","ע) שם דף סה בריית' שם ד' נ' ע\"א כגון אלו החופרי' לאושין וכפרש\"י שם אצל ר\"ה אבל אם חפר בר\"ה לצורך היסוד אם הוזקו בו חייב מברייתא פרק י' דב\"מ דף קיח ע\"ב כל אותם המקלקלי' בר\"ה וכו' כ\"כ בשם מהרש\"ל בפ' הפרה סי' כ\"א","פ) ל' הרמב\"ם שם דף י' משנה שם ע\"ב","צ) כ' ה\"ה פי' בחפירה כל שהוא שאין שיעור נזקין ובתוספתא מחלוקת ופסק כת\"ק דאמר כל שהוא וכסתם משנה שם שלא נתנה בו שיעור","\u0003ק) ל' הרמב\"ם שם בפ' י\"ב די\"א מימרא דרבה ב\"ב חנה וכו'\u0004 שם פ\"ה דף נ\"א ע\"ב וכת' ה' המגיד שם נראה שהי' גירסתו בור ט ומהם טפח מים חייב קסבר כל טפח מים כטפחים ביבשה דמי אבעי' להו בור ח' ומהם ב' טפחים מים מהו מי אמרינן כיון דלא עמוק לית להו הבלא או דלמא כיון דנפישא מיא אית ביה הבלא ואם תמצא לומר דנפישא מיא אית ביה הבלא בור ז' ומהם ג\"ט מים מהו וכו' תיקו והב\"י והב\"ח כתבו שהטור נמשך אחר דברי הרמב\"ם ואינו כן בדין זה בנוסח הטור שלפנינו ואכמ\"ל","ר) שם ושם ומבואר במ\"ש ולדידי צ\"ע שלא פסק הבעיא הראשונה לחיוב כדרכו לפסוק בכל את\"ל שנפשטא הבעיא","ש) ל' הטור שם וכ\"כ הרא\"ש שם וכ\"ה התו' שם ע\"א וכ\"כ ה\"ה שם דין י\"ב לדעת הרמב\"ם שהרי הי' במעשה הראשון שיעור (לנזקין) ושכ\"כ המפרשים ז\"ל","ת) שם ושם ברמב\"ם ברייתא שם וכ' ה\"ה וכאוקימת' קמיית' דרב זביד דטפי עדיף לאוקמי' כהלכתא","א) שם דין י\"ג ברייתא שם וכרבנן","ב) וכן כ' ה\"ה שם בפי' דברי הרמב\"ם מפני שהאחרון העתיקו ממדת נזקין למדת מיתה ומתוך כך חייב בכל","ג) בעיא דרבה שם ע\"ב ולא איפשט'","ד) שם די\"ג וכתב ה\"ה בעיא שם והרכיב רבי' ב' הלשונות (דרב אשי) האמורין שם (דף נא ע\"א) וביאר דבריו בשחפר הוא בור עמוק לשיעור המיתה ובא אחר והרחיבו ברחבו מצד אחר אם נפל השור מאותו צד שהרחיב האחרון חייב ואפי' מת מחמת הבלא שאם לא הרחיב לא היה נופל נפל השור מצד אחר שלא הרחיב זה בו אם מת מחמת הבל האחרון פטור שהרי מיעט הבלו ואם מחמת החבטה מת האחרון חיי' והוא תימה איך ערב הלשונו' וכו' ואולי דעת הרבינו ז\"ל שאינן חולקין לענין הדין וצ\"ע ע\"כ והכ\"מ כ' על מה שתמה ה\"ה על דברי רבינו שכדי לתרץ קושית התוספת שהקשו שם אלישנא קמא אמאי פטור כי מיית מחמת הבלא אפי' נפל מצד שהרחיב הא אם לא הי' מרחיבו לא היה נופל וכן קשה לל\"ב כי נפל מאידך גיסא אמאי פטור אי מיית מחמת חבטא הרי כיון שעשה מעשה בבור אין ראוי ליפטר לכן מפרש רבינו דהני לישני כל חד סמוך אחבריה ול\"פ ודבריו נכוני' עכ\"ל ולפענ\"ד היא רחוק לחייב השני כשנפל השור בצד אחד שלא הרחיב הוא שהרי לא בגרמא הרחיבו הבור נפל ולא נפל לתוך בורו שחפר כלל ואין כאן שום קושיא אלישנא בתרא אף מה שהקשו התוספת אלישנא קמא נלע\"ד שהרמב\"ם מפרש דל\"ק דאיירי בשאינם יודעים מאיזה צד נפל לכן אם מת מחמת הבלא אין השני שהרחיב חייב מספקא שמא מצד שהרחיב נפלה כיון שהספק הוא בגרמי דנזקין שהרי מיתתה מחמת ההבל לא היה בגרמתו פטור אבל אם מת בחבטה כיון שהוא ספק מאיזה צד נפל ומת גם הוא חייב בתשלומין ושניהם משלמין הנזק ומ\"ש הרמב\"ם ברישא האחרון חייב היינו אף האחרון וכיוצא בזה מבואר לקמן סעיף כ\"ה ע\"ש ומ\"ש בסיפא ואם מן הצד שחפר הראשון נפל הראשון חייב שזה האחרון מיעט הבלו ואצ\"ל אם מת מחמת חבטו שהשני פטור הרי לא נפל ולא נחבט במקום שחפר האחרון","ה) פסק כלישנא בתרא","ו) שם די\"ד פסק כשמואל שם ד' נ' ע\"ב דקי\"ל דהלכתא כוותיה בדינא","\u0003ז) מימרא דרבה ורב יוסף שם דף נא ע\"ב וכחד אמר וכו'\u0004 בלישנא בתרא","ח) שם דט\"ו ג\"ז כשמואל שם ד\"נ ע\"ב וכ' ה\"ה דשיעור העשרה טפחים דומיא דבור","ט) שם דף כ\"ב ע\"א וכדמפרש לה רבה שם דף נד ע\"ב ותניא כוותיה","י) שם ושם במשנה ויליף לה מקרא שם דף נד ע\"ב","\u0003כ) מפורש שם בפ' ג' דף כח ע\"ב הני מילי לענין קטלא וכו'\u0004 ","ל) כ' ה\"ה חיוב נזקי הבהמה הפקחית לא נתבאר בגמ' והראב\"ד השיג בזה שם ולי נ' שיצא דין זה לרבינו ממ\"ש שם בפ\"ג (דף כז ע\"ב) לפי שאין דרכן של בני אדם להתבונן בדרכים וסובר רבי' דכ\"ש בהמה שאין בה דעת וכשמיעטו בהמה פקחת ביום לא מעטוה אלא מן המיתה דדוקא שהפקחות מעיינות ונשמרות ממכשול גדול שיש בו סכנות נפשות אבל אינם שומרות עצמן כ\"כ מן הנזיקין ולפיכך חייב בעל הבור וכו' ואפשר שהר\"א סובר שאדם שהוא בעל מחשבה הוא שאינו מתבונן בדרכי' אבל בהמה דרכה להתבונן הלכך ה\"ל כאונס ופטור וכן פי' הרשב\"א","\u0003מ) בשם הראב\"ד והרשב\"א ומבואר במ\"ש וכן דקדק הב\"ח מדברי הרמ\"ה סכ\"ג ושהכי נקטינין:\u0004 ","נ) רמב\"ם רפ\"ג וטור ס\"כ משנה שם בפ\"ה דף נב ע\"א","ס) שם בגמרא דף נג ע\"ב ודלא כר' יהודה שם בגמרא","ע) שם בפ\"ג דף כח ע\"ב","פ) לשון רמב\"ם שם בפי\"ב ד\"ד ושם בפ\"ה במשנה","\u0003צ) שם כ' ה\"ה מבואר שם בסוגי' בלישנא בתר' וכו'\u0004 (שם ע\"ב)","ק) שם בתוספת וכ\"כ הרא\"ש שם בפסקיו וז\"ל ואע\"ג דלא שכיחי גמלים דאבעי ליה למיחש דלמא אתו גמלי' ולענ\"ד דבמקום שאינם מצויי' כלל פטור","ר) שם בעיא שם בלישנא בתרא ואיפשיט' שם","פירוש דהוי תחילתו בפשיעה וסופו באונס דחייב כמ\"ש לעיל בבהמה דעכו\"ם","ש) כ\"כ הרא\"ש שם בפסקיו מדברי התוס' שם בשם ר\"י","ת) שם דין ז' וכ' ה\"ה משנה מפורשת פרק הפרה (שם דף נא ע\"א) ומסירת הדלי מבואר בגמ' (שם ע\"ב) ופסק כר\"א בן יעקב דאיפסק הלכתא כוותיה בנדרים פ\"ה (דף מו ע\"ב) ע\"כ וכ' הרא\"ש שם בפרק הפרה הביאו הב\"י וז\"ל גי' רש\"י השני חייב והרי\"ף גורס הראשון חייב ואין חילוק בין ב' גרסאות כלל דלפי' רש\"י השני חייב בשהניחו משתמש הא לאו הכי שניהם חייבים ולגירסת הרי\"ף ז\"ל ה\"פ אף הראשון חייב דלא תימא השני שעבר עליו באחרונה חייב וכו' ע\"כ ולענ\"ד אין ספק שגי' הרי\"ף היה גירסת רבינו הרמב\"ם וה\"ה ושגם דעת הרמב\"ם הי' כך שגם הראשון חייב כי כן מבורר שם בגמ' למאי דמוקמי לה אליבא דרב\"י וכמ\"ש הרא\"ש לדברי הרי\"ף וכבר תמה הב\"י על רבינו הטור שכ' על דברי הרמב\"ם ולא נהירא וכו' ולא פי' דבריו כמו שפי' הרא\"ש דברי הרי\"ף","א) שם ושם במשנה דף נב פסק כר' יוחנן ועל מה שהשיגו הראב\"ד אין בגמרא עד שידע הראשון וכו' כ' ה\"ה ומדברי שאר המפרשי' נראה דבעינן שידע ממש וכדברי רבינו וכן עיקר ע\"כ וכן הוא בגירסת הגמרא שלפנינו וכן כ' התוס' שם","ב) שם בתוספות","ג) שם סי\"ב בשם הרמ\"ה ודייק לי' מדקאמר לכרות ארזי'","ד) גם זה סי\"ג בשמו ודייק לה מדקאמר לשכור פועלים","ה) מימרא דרבינא שם פ\"ג דף ל' ע\"א וכ' הטור סי\"ד ואין בעל הכיסוי צריך להודיע","ו) ל' הרמב\"ם שם פי\"ב מהר\"מ ד\"ח","פי' השומר חייב וכ\"כ הטור סט\"ז","ז) בריית' בפ\"ק (דף י ע\"א)","ח) והראב\"ד השיגו שם וכ' ה\"ה וכבר הכריע הרשב\"א ז\"ל כדברי רבינו ז\"ל שאפי' מכוסה כראוי חייב אליבא דחזקיה דהלכתא כוותיה וכמוכרח בסוגיא שם דף ט' ע\"ב","ט) ל' הטור סכ\"ה משנה שם דף נב ע\"א","י) פסקי כשמואל שם ריש דף נג וכ\"פ הרמב\"ם שם כשמואל ועל מ\"ש הרמב\"ם בדין זה שם דין י\"ח וכתב ה\"ה דלשון הנמצא בדברי רבינו משובש משובש המעתיקין","כ) כן פרש\"י מפני שקול הכרייה בעתתו וכ' ה\"ה שם שכן עיקר אע\"פ שהבעלי תוס' חולקים בדבר","ל) פשוט בגמרא שם דף נב ע\"א","\u0003מ) כדאמר רב שימי בר אשי הא מני ר' נתן הוא וכו'\u0004 ","נ) שם במשנה וכשמואל","ס) שם ברמב\"ם די\"ט ברייתא שם משמיה דר' נתן וכדמפרש רבא שם ר' נתן דיינא הוא ונחית לעומקא דדינא וכו' ותו דקיימא מתניתין כוותיה","ע) שם דין כ' מימרא דרבא שם אליב' דר' נתן","פ) טור סכ\"ח מימרא דרבא שם ע\"ב","צ) כן כתבו התוספות שם","\u0003ק) כ' הב\"י ופשוט הוא שזהו ח\"נ הנוגע לחלקו:\u0004 ","ר) שם ושם במימרא דרבא","ש) פי' רש\"י אנשים כתיב גבי ולדות ולא שוורים","\u0003ת) מבואר בס\"ס ת\"ה:\u0004 ","א) שם ושם במימרא דרבא","ב) דהא דקי\"ל שור ולא אדם בקטל' קי\"ל כגון שנפל לתוכו עבד ומת ומבואר לעיל סעיף כ'","ג) מבואר במ\"ש לעיל סעי' כ\"א","ד) שם סכ\"ט בשם הרמ\"ה כר' נתן ומבואר לעיל סימן לב וכמ\"ש שם","ה) טור לדעתו ושכ\"כ ה\"ר חזקי'","ו) שם סעיף ל","ז) ל' הרמב\"ם שם ספי\"ב וכתב ה\"ה ברייתא הובאה בפ' קמא דערכין (דף ז' ע\"א) ופסק כפשט הברייתא ואיתא ס\"פ גט פשוט והאוקימתו' שנא' עליה (שם דף קעה ע\"ב) הם אליבא דמ\"ד מלוה ע\"פ אינו גובה מן היורשין ואין הלכה כן כמו שיתבאר וכו' (ומבואר לעיל סימן ק\"ז וק\"ח]:"],"t":["\u0003חייב. \u0004 וכתב המ\"מ דאפילו ראה הראשון דכסהו שני ולא ראה שחזר וגלהו אפילו הכי הראשון חייב דלא ה\"ל לסמוך אכיסוי של זה שאין לו חלק בבור [משא\"כ בבור] של ב' שותפין כדלקמן בסי' זה. סמ\"ע:","\u0003בהמה. \u0004 ואע\"ג דכתי' כי יכרה איש בור כמ\"ש בסעיף שאח\"ז ה\"מ בחופר בר\"ה דהקרקע אינו שלו וכיון דהוא לא חפר אין עליו למלאותו משא\"כ בחפרה בהמתו בחצירו דלא גרע מנחפר שם מאליו דמוזהר עכ\"פ שלא יוזק אדם בקרקע שלו שיש בו בור והיינו דוקא אם הפקיר חצירו שסביב הבור ולא הפקיר באותו פעם גם מקום הבור דאם לא הפקיר כלל י\"ל מה לאחרים לילך בחצרו ופטור דומיא דהיזק רגל בחצר הניזק כמה שכתו' בסי' ש\"צ ושצ\"א ואם הפקיר החצר והבור בפעם אחת ג\"כ לא נתחייב על נזקי הבור כיון דבשעת הכרייה היה הכל שלו משא\"כ כשחפר תחלה בחצירו ואח\"כ הפקיר מקום שסביב לבור ונתן רשות לכל לקרב נפשם להבור דה\"ל כפותח בור בר\"ה שבס\"ו ואם הפקיר רשותו לחוד אף שאח\"כ הפקיר גם בורו חייב על נזקיו דלאו כל כמיניה להפקיר נזקיו שכבר חל עליו לסלק התקלה וע\"ל ר\"ס שצ\"ח. שם:","\u0003לכסותו. \u0004 מדלא כתבו בדין זה כ\"כ השיעור בכדי שידע ויסגור כו' כמ\"ש בסכ\"ו נראה דזה דומה לחופר בור והניחו מגולה שבסכ\"ח דמיחשב פשיעה ולאלתר חייב בנזקין וה\"ה בבור שחפרו השור בחצירו כיון דעליו מוטל לטרוח ולכסותו. שם:","\u0003לר\"ה. \u0004 לשון הטור שפתחו ברשותו בתוך ד\"ט סמוך לר\"ה עכ\"ל וה\"ט דכל ד\"ט סמוך לר\"ה דחקי ביה רבים אבל בפתחו לרשות חבירו בעינן סמוך ממש ומש\"ה לא כת' הטור ד\"ט כי אם בסמוך לר\"ה. שם:","\u0003חבירו. \u0004 גם כאן כת' הטור דאחר שנודע לבעל החצר פטור הכורה כיון דהוא חייב בנזקי בעל החצר כו' כמ\"ש הרמ\"א בס\"ד בהג\"ה ואע\"ג דכאן הבור הוא ברשות המזיק רק שפתוח לרשות הניזק מ\"מ כיון שעומד סמוך לחצירו ממש כנ\"ל ה\"ל כאילו עומד שם ועליו לסתמו להרחיק ממנו נזקו ויקבל שכר טרחתו מהכורה. שם:","\u0003רבים. \u0004 הרמ\"ה כת' דאי חפר מעיקרא לצורך עצמו והדר מימלך למימסריה לרבים לא נפטר החופר עד דטמים ליה וכת' עליו הטור ז\"ל ואינו נראה כיון דמסרה עתה לרבים והן צריכין לו מאי נ\"מ שחפרו מתחלה לצרכו עכ\"ל. שם:","\u0003רשות. \u0004 דגם לצורך רבים אינו רשאי לחפור בר\"ה במקום שהוא מכביד לרבים וכדומה לו שמזיק להן. שם:","\u0003פטור. \u0004 ול\"ד למ\"ש הטור והמחבר בסי' תי\"ד ס\"ב בהוצאת זבלים לר\"ה ובס\"ס תי\"ז בהנחת אבנים לצורך בנין דגם כן עשאו ברשות ואפילו הכי אם קלקלו והזיקו חייבים שאני התם דעושה בר\"ה עצמו משא\"כ כאן דהבור עומד ברשותו וגם הוא לשעה ומיד אחד החפירה יחזור לסותמו באבני הבנין שיניח ביסוד חומתו ומה\"ט ל\"ד נמי לעושה תנור בביתו והרחיקו כשיעור מהעלייה ואפי' הכי אם יצא אש והזיקה חייב כמה שכתו' בר\"ס קנ\"ה דשם הוא עושה כן תדיר משא\"כ זה שעושה לפי שעה וכן כת' הרי\"ף עכ\"ל הסמ\"ע אבל הש\"ך כת' ז\"ל וביש\"ש כת' שהוא טעות וחייב לשלם והש\"ס איירי כשנכנס החומה לתוך שלו והחפירה הוא בחלק הכניסה ע\"ש שהוכיח כן ודלא כמ\"ש בסמ\"ע וכן כת' הב\"ח עכ\"ל \u0005(* א\"ה עיין בדרישה שם הביא דברי מהרש\"ל אלו והשיג עליו ע\"ש באריכות)\u0006:","\u0003חולקין. \u0004 וסבירא ליה דלא מהני תפיסה בספיקא דדינא וע\"ש. סמ\"ע:","\u0003כולם. \u0004 פירוש אפילו לענין אם נפלה שם בהמה ומתה כיון דיש במעשה דכל אחד כדי להמית וכח דכולם מעורב בו. שם:","\u0003הבלו. \u0004 נראה דר\"ל שנפל לבור דרך פיו למטה ומת וניכר הדבר להרואים שמת מחמת הבל ולא מחמת חבטה. שם:","\u0003חבטו. \u0004 היינו שנפל לבור על גבו וניכר להרואים שלא מת אלא מחמת החבטה. שם:","\u0003פטור. \u0004 הטעם דמתה באונס שלא כדרך מיתת הבהמות והרי לא היה כאן חבטה ולא הבל. שם:","\u0003בו. \u0004 קצת קשה דלענין אם נחבטה בתל עצמו אין צריך גבוה י' דהא אפילו נתקל בקרקע עולם והוזק באבן ומת חייב כמ\"ש הטור והמחבר בר\"ס תי\"א ובטור כת' ז\"ל דאם עשה תל גבוה י' בר\"ה ועלה עליו שור ונפל לארץ ומת חייב וזה מ\"ש דתל דומה לבור דאם נפל מלמעלה למטה בעינן גובה י\"ט כיון דהוזק לבסוף בקרקע עולם:","\u0003שהוא. \u0004 מלשון זה נראה אפילו התל והחפירה הוא פחות מג\"ט ומהרש\"ל סי' כ\"ד כת' דכל פחות מג\"ט כארעא סמיכתא הוא ופטור דלא מקרי בור ולדבריו צ\"ל דל\"ד קאמר כל שהוא וכה\"ג אשכחן פרק ראשית הגז ופרק העור והרוטב ומס' נדה וכמה כל שהוא כו' אמנם מדברי המרדכי סוף ב\"מ ומדברי הרמ\"א לקמן סי' תי\"ד ס\"ב מוכח לכאורה דאף פחות מג\"ט אף דא\"י לעכב מ\"מ אם הזיק חייב לשלם ודמי למוציא זבלו שלא בשעת הוצאת זבלים כדי לפנותו לאלתר ודו\"ק במרדכי ואם כן צ\"ע לדינא. ש\"ך:","\u0003מנזיקין. \u0004 דבהמה עיניה למטה ודרכה להתבונן בדרכים ולהשמר מנזקיה משא\"כ אדם שהולך ועיניו משוטטות למעלה ולהלן מדרך הלוכו וכמה שכתבתי בסי' תי\"ב ס\"ג. סמ\"ע:","\u0003כלים. \u0004 לשון הטור ואפי' נפל שמה שור עם הכלים ומת השור ונשתברו הכלים חייב על השור ופטור על הכלים. שם:","\u0003לדלות. \u0004 משמע דמפרש דליו מלשון דלי וכן פירש ר\"ח אבל רש\"י והטור פירשו דליו כיסוי הבור ע\"ש. שם:","\u0003ונטל. \u0004 ול\"ד למ\"ש הרמ\"א בסי' שפ\"ג ס\"ב בהג\"ה וכן ראובן שלקח כלי של שמעון כו' דשאני התם דנשבר החבית מיד והוי ליה כאילו הזיקו בידים משא\"כ כאן דאין ההיזק בא מיד אלא לאחר זמן כשתפול שם בהמת חבירו וגם לא ברי כל כך היזקו. שם:","\u0003להתגלות. \u0004 ע\"ל סי' שצ\"ו ס\"ו במוסר שורו ביד חש\"ו דאפילו היה קשור בחבל מיחשב פשיעת הבעלים משום דדרך השור להתיר הקשר ופירש התוספות דר\"ל דחש\"ו בעצמן יתירוהו ונראה דה\"ה כאן יש לומר כיון דלאו בני דעת נינהו חיישינן שיגלו הבור דעשוי להתגלות בקל כי בש\"ס אתאמרו הני ב' דינים יחד. שם:","\u0003פטור. \u0004 מטעם דקרקע עולם הזיקתו ודומה לנתקל באבן וניזק בקרקע דפטור כמ\"ש הטור והמחבר בסי' תי\"א ס\"א. שם:","\u0003אצלך. \u0004 שהרי בבורך מצאתי הזיקי. שם:","\u0003שנדחפה. \u0004 דה\"ל לבעל הבור לאסוקי אדעתיה שמא ידחפנו שור שם ויגרום בורו היזק לבעל השור. שם:","\u0003בכוונה. \u0004 הוא מטעם שכתבו התוספות ז\"ל דאטו אם ישים אדם טליתו של חבירו באש מי מיחייב בעל האש. שם:","\u0003דברים. \u0004 והא דחייב בבושת אף דע\"כ איירי שדחפו שלא בכונה כמו שכתוב בסל\"ד צ\"ל כמ\"ש התוספות כגון שידע האדם בשעת נפילת חבירו וחשוב בכונה ומהרש\"ל סי' מ\"ב פסק דפטור מבושת אא\"כ שמתחלה דחפו השור ואחר כך בא האדם להוסיף עליו וע\"ש שהאריך ודבריו דחוקים. ש\"ך:","\u0003לבדו. \u0004 נראה דאתי לאפוקי כגון אדם ושור שדחפו אדם והוזק שנתבאר לפני זה שבדמי היזקו המה משותפים ובשאר דברים צריך האדם לבד לשלם ולמדנו כאן דאם ברח האדם צריך בעל השור לשלם כל דמי הנזק כאילו הזיקו לבדו אבל שאר דברים א\"צ לשלם עבור האדם שברח ואע\"ג דבעל השור עומד בחיוב התשלומין בעד האדם לא אמרינן דעומד במקומו בכולו משום דאף אם היה השור מזיקו לבדו לא היה חייב לשלם. סמ\"ע:","\u0003חולקין. \u0004 וכן כתב הגהת מיימון ומרדכי בשם מהר\"מ וכ\"פ מהרש\"ל פ\"ה דב\"ק סי' מ' ע\"ש ובתוספות פרק כיצד הרגל ועיין בהגמי\"י דיש ליישב דגם דברי מהר\"מ הראשונים אינם סותרין זה. ש\"ך:","\u0003פטור. \u0004 דאיהו גרם ההפסד לנפשו בחפירתו:","\u0003מיורשי. \u0004 ר\"ל ל\"מ אם הוא חי דצריך לשלם לבעל השור אלא אפילו מת הכורה צריכין בניו היורשים לשלם לבעל השור היזקו ואע\"ג דמלוה ע\"פ של אביהן אינן נפרעין מיורשיו אחרי מותו שאני הכא כיון דאביהן עכשיו מת בשעה שנפל שם השור בודאי לא פרע עדיין דמי השור. סמ\"ע:"],"r":["\u0003וזהו ממונו. \u0004 מכילתא וכי יפתח איש בור למה נאמר עד שלא יאמר יש לי בדין הואיל והבור ממונו והשור ממונו כו' ובגמ' ג' מ\"ש בור כו' ועתוס' שם ד\"ה וממונך כו' ושם כב א' ד\"ה אשו משום ממונו כו':","\u0003שמזיק כו' דהעובר כו'. \u0004 ג' ב' וש\"מ שתחלת עשייתו לנזק וערש\"י שם:","\u0003שאינו זז כו'. \u0004 מתני' דריש ב\"ק לא זה וזה כו' ובברייתא ת\"י וש\"מ:","\u0003לפיכך כו'. \u0004 ג' ב' וכבר כ' דממונו ל\"ד ומ\"מ נ\"מ לפעמים כמ\"ש י\"ט ב' בדליל ובנזקין לאחר נפילת אונס שם ך\"ט ושם בגלל ל\"ש אלא כו' וערש\"י שם ד\"ה בשהפכה כו' וכיו\"ב:","\u0003א' החופר כו'. \u0004 מכילתא שם בעל הבור ישלם מ\"מ:\n\u0003 (ליקוט) א' החופר כו'. \u0004 ירושלמי פ\"ה אין לי אלא כשחפר לקח ירש נתן לו במתנה מנין ת\"ל או כי יכרה כו' (ע\"כ):","\u0003וכן אם כו'. \u0004 י\"ט ב' נקשר מאליו מאן כו' ואי לא כו':","\u0003או שחפרו כו'. \u0004 מ\"ח א':","\u0003וכן אם כו'. \u0004 תוס' שם סד\"ה אע\"ג. ונראה כו' ועמ\"ש בסי' תיג שהרמב\"ן חולק ועתוס' מט ב' ד\"ה ברה\"י כו' ולפי' ר\"י קשה כו' והרא\"ש פי' כפיר\"י ותי' הטור דשם מיירי כשלא נודע לבעל החצר וז\"ש ונודע כו':\n\u0003 (ליקוט) וכן כו' ונודע כו'. \u0004 וכ\"כ בנ\"י שם כפי' תוס' מט ב' ד\"ה ברה\"י ור\"י מפ' כו' ומ\"ש תוס' ולפיר\"י כו' כ' דמיירי שלא נודע כו' (ע\"כ):\n\u0003 (ליקוט) וכן כו' ונודע כו'. \u0004 ערי\"ו נל\"א ח\"א בשם רשב\"ם ע\"ש (ע\"כ):","\u0003אחד כו'. \u0004 כרבה דהלכתא כרבה בר כו' וכר\"ע דהלכה כר\"ע מחבירו. רי\"ף ורא\"ש וש\"פ ועוד כ' דסתם מתני' כוותיה:","\u0003החופר כו'. \u0004 מתני' נ' ב':","\u0003או החופר בור כו'. \u0004 מתני' מט ב':","\u0003לרשות חבירו. \u0004 כפיר\"י והרא\"ש וכשלא נודע לו. טור וכנ\"ל:","\u0003והפקיר כו'. \u0004 רש\"י וכמ\"ש בגמ' שם ר\"ע הפקיר כו':","\u0003אבל אם כו'. \u0004 וכ\"כ תוס' כח ב' סד\"ה אבל ושם נ\"א א' ד\"ה בור כו' ורא\"ש וש\"פ דלא כרש\"י נ' א' ד\"ה בעל התקלה כו':","\u0003או כו'. \u0004 ר\"ל במקום שיש רשות לילך דלא כפי' הסמ\"ע כמש\"ו שנא' בעל כו':","\u0003ומסר כו'. \u0004 כן פ' הרא\"ש ועבה\"ג:","\u0003או כו'. \u0004 כן פי' בטור בשם הרמ\"ה וכן פירש\"י:","\u0003אפי' כו' ואם כו'. \u0004 שם כגון דארוח כו' וערש\"י שם אבל רש\"ל וב\"ח כ' דט\"ס ברש\"י דמ\"ש בד\"ה ברה\"י הסמוכה כגון מקצה כו'. צ\"ל בד\"ה דארוח ארוחי לר\"ה. כגון מקצה מקום כו' והלכך טעמא דלאושין כו' אבל בר\"ה עצמו חייב אע\"פ שהוא ברשות כמש\"ש ל' א' כל אלו כו' וכיוצא וקושייתם על הטור אבל דברי ש\"ע אפשר לפרש בדבריהם ועבה\"ג:","\u0003היה כו'. \u0004 כגי' בור שמנה כו' בור שבעה כו' מהו:","\u0003חפר א' כו'. \u0004 תוס' שם ד\"ה האחרון כו':","\u0003החופר כו'. \u0004 עבה\"ג וכן הסוגיא שם כוותי' בבעיא דרב שיזבי וללישנא בתרא היא דלא כהלכתא:","\u0003וי\"א כו'. \u0004 כלישנא בתרא כשיטת הגאונים. והרמב\"ם סובר דל\"פ והכריחו קושית תוס' שם ד\"ה אי כו':","\u0003בור כו'. \u0004 עבה\"ג ואע\"ג דשם נב א' תני רב חנניא כוותיה מ\"מ ר\"נ ס\"ל כוותיה דשמואל שם נא א' וכן רב אשי שם ב' וכמ\"ש בס' שקדם:","\u0003לפיכך כו'. \u0004 עתוס' נ' ב' ד\"ה א\"ב כו':","\u0003ואפי' בתל כו'. \u0004 תוספתא פ\"ו כמה שיעורו להזיק כ\"ש ולמיתה י\"ט:","\u0003ואם הוזק כו' \u0004 ס\"ל דלא אמרו אלא למיתה וראיה מהזיק דאדם בכל פרק המניח ואין מחלק בין פיקח כו' ואמרי' כ\"ז ב' לפי כו'. ועתוס' שם ד\"ה לפי כו' וז\"ש וי\"א כו':","\u0003 (ליקוט) או הבהמה הפקחת כו'. \u0004 עבה\"ג וע\"ל סי' תיב ס\"ג וי\"ל שיצא לו ג\"כ ממש\"ש כד ב' א\"ל אנא כו' ועתוס' ך\"ז ב' סד\"ה אמאי וקצת קשה כו' (ע\"כ):","\u0003בין כו'. \u0004 ר\"ל דז\"ש שם ה\"מ כו' דשבירתן זהו מיתתן אבל לענין כו' ר\"ל שלא נשברו אלא הוזקו:","\u0003אע\"פ כו'. \u0004 גמ' שם:","\u0003אם אין כו'. \u0004 שם ואי דלא כו':","\u0003מיהו כו'. \u0004 הרא\"ש ותוס' שם ד\"ה ואתו כו':","\u0003אפי' כו'. \u0004 הרא\"ש:","\u0003ואם יבאו כו'. \u0004 שם א\"ד הא כו':","\u0003ויש מחלקין כו'. \u0004 כפי' תוס' בד\"ה הנ\"ל ונראה לר\"י כו'. וס' הראשונה סובר כפי' ריב\"ם שם וכ\"כ הרשב\"א:\n\u0003 (ליקוט) ויש מחלקין כו'. \u0004 כפי' ר\"י בתוס' שם דלא כריב\"א אע\"ג דלעיל סי' רצא ס\"ט קי\"ל כדברי ריב\"א כ' ביש\"ש פ\"ה סל\"ח לחלק בין מיגו דהוי פשיעה כו' לתחלתו בפשיעה כו' כי הכא אמר מיגו כו' משום דהפשיעה והאונס בענין אחד הוא בנפילה בבור אבל התם הפשיעה לענין זאבים וגנבים והאונס הוא במיתה ע\"ש (ע\"כ):","\u0003בור כו'. \u0004 כגי' הרי\"ף:","\u0003וי\"א כו'. \u0004 כגי' שלנו והרא\"ש כ' דאף גי' הרי\"ף י\"ל כפרש\"י. וע\"כ נ\"ל כן כמש\"ש כתנאי המדלה כו' במאי קמפלגי כו':","\u0003עד שידע כו'. \u0004 כ\"ה גי' הרמב\"ם והרא\"ש כר' יוחנן:\n\u0003 (ליקוט) עד שידע. \u0004 כ\"ה גי' בגמ' וכ\"ה גי' הרא\"ש וכ\"כ הטור (ע\"כ):","\u0003וי\"א כו'. \u0004 תוס' ד\"ה בכדי כו'. והרמב\"ם ס\"ל כפירש\"י:","\u0003יש כו'. כל כו'. \u0004 עבה\"ג:","\u0003וה\"מ דאניס כו'. \u0004 מדל\"ק אמתני' דשם נ\"א א':","\u0003המוסר כו' \u0004 נלמד ממ\"ש למטה ואם כו':","\u0003אע\"פ כו'. \u0004 שם ועתוס' שם ד\"ה בשור כו':","\u0003בין לפניו כו' אבל כו'. \u0004 כשמואל ועמ\"ש בסי\"ז:","\u0003שור כו'. \u0004 כר\"נ דכולה סוגיא שם כוותיה ועבה\"ג:","\u0003 (ליקוט) שבעל הנבילה כו'. \u0004 הוא כאב\"א שם ולפ\"ז צ\"ע מ\"ש בסל\"ה וסל\"ו ועתוס' שם ב' ד\"ה הא כו' ונראה לר\"י כו' (ע\"כ):\n\u0003 (ליקוט) שבעל כו'. \u0004 כלישנא בתרא שם דקי\"ל כלישנא בתרא בכ\"מ וכן הסוגיא שם למעלה הא מני ר\"נ היא כו' וכל היכא כו' וכן שם י\"ג א' אב\"א ר\"נ התם כו' ודלא כתוס' שפ' כלי' קמא וכ' דסוגיא דשם בפלוגתא דשור ושור פסולי המוקדשין כלישנא קמא וכבר תי' בהג\"מ דאתי אף כלישנא בתרא וכ\"כ יש\"ש אבל הא דסל\"ד לה לו צ\"ע וכ\"כ ביש\"ש שם סמ\"ב דבכל זה אינן משלמין אלא חלקן בלבד (ע\"כ):","\u0003אע\"פ שהיא גדולה כו'. \u0004 רש\"י שם ד\"ה ר\"ן כו':","\u0003 (ליקוט) אם כו'. \u0004 צ\"ע וגם הג\"מ לא תי' אלא בשני שוורים ובזה מתרץ קו' תוס' שם שהקשו אמאי לא משני הא והא כר\"ן והא כלישנא קמא והא כלי' בתרא אבל בכה\"ג לכאורה צ\"ע ונראה מ\"ש אנא תוראי בבירך כו' לאו משום דהוא הגומר את ההיזק דוקא אלא משום שהוא עושה בשעתו ההיזק לבד בלא השור וכ\"ש בשור שממנו התחיל הנזק והוא עיקר הגורם וכמש\"ש והא כורה קגרים כו' ותוס' שכ' ונראה לר\"י כו' לא כ' אלא בשני שוורים דוקא שמתחלה ועד סוף עמו ביחד וכן דברי הג\"מ (ע\"כ):\n\u0003 (ליקוט) אם כו'. \u0004 עמש\"ש דאף ללישנא בתרא דמש\"ש אנא תוראי כו' ל\"ד כה\"ג דה\"ה כה\"ג דסעי' זה וכיוצא ושלא כדברי תוס' וכ\"כ במלחמות שם ע\"ש שהאריך (ע\"כ):\n\u0003 (ליקוט) סל\"ה אם אדם כו'. \u0004 אע\"ג דבסל\"ב הוצרך לטעם שבעל כו' שם דוקא שבור פלגא היזקא עבד משא\"כ בשני שורים דאף לישנא בתרא מודה דכ\"א כולה היזקא עבד דלא כתוס' שם ב' ד\"ה הא כו' הג\"מ ספי\"ב מהנ\"מ ס\"ק ג' ובס\"ס נזיקין סי' יב אבל כאן צ\"ע ועהג\"מ ונראה שאף לדברי תוס' מ\"מ קי\"ל כלישנ' קמא כיון דרבא ורבינא ס\"ל כן ע\"ש בתוס' אלא שהרי\"ף ורמב\"ם ס\"ל כרברי מהר\"ם שאף ללישנא בתרא כאן חייב ולכן כ' לישנא בתרא (ע\"כ):","\u0003יש כו'. \u0004 וכ\"נ דעת תוס' כג א' בד\"ה תפשוט:\n\u0003 (ליקוט) יש כו'. \u0004 ע\"ל סי' שצא ס\"ז (ע\"כ):\n\u0003 (ליקוט) י\"א כו'. \u0004 וכ\"כ נ\"י ספ\"ג על מש\"ש ש\"מ שוורים תמין שהזיקו כו' ועתוס' שם ד\"ה ש\"מ כו' ונר' לפרש כו' וכ' ולא איפשיטא הבעיא ואינו גובה אלא רביע מזה ורביע מזה ואי ליכא לאשתלומי כוליה רביע מזה משתלם שארא מהאיך כר\"נ כו' (ע\"כ):","\u0003 (ליקוט) וי\"ח כו'. \u0004 וכ\"ד המרדכי ספ\"ה ועמ\"ש בסי' שפח ס\"ז (ע\"כ):\n\u0003 (ליקוט) וי\"ח כו'. \u0004 עתוס' מו ב' ד\"ה גלית כו' ואפי' לר\"נ כו' ר\"ל דבשלמא שם דבעל השור אן חייב כו' משא\"כ דחייב רק שא\"י לגבות מספיקא כמ\"ש כאן ומשם למדו הפוסקים דין זה (ע\"כ):\n\u0003 (ליקוט) וי\"ח כו'. \u0004 מרדכי ס\"פ הפרה סי' ע' ע\"ש והג\"מ ספי\"ב מה' נ\"מ ס\"ק ג' ובתשובה אחרת כו' אבל בס\"ס משפטים סי' סג כ' כס' ראשונה וכ' שם דמטעם זה אמרי' שנים שלוו כ\"א נעשו כו' ואם אין לא' לשלם גובה מחבירו הכל כמש\"ל ר\"ס ע\"ז (ע\"כ):","\u0003 (ליקוט) ולפ\"ז כו'. \u0004 דבור גובה האידנא ממש\"ש ך\"ז ב' בפומבדיתא וחייב רבא. נ\"י שם וכ' שכ\"כ הרמ\"ה. דדוחק לומר דמיירי בתפס ושם בפ\"ב ההוא חמרא כו' ההוא ברחא כו' כ' הרשב\"א ג\"כ דמיירי בלא תפס דכיון דשכיחא מגבי' בבבל ע\"ש (ע\"כ):"]}],["תּוֹלְדוֹת הַבּוֹר, אַבְנוֹ, סַכִּינוֹ וּמַשָּׂאוֹ וְכַיּוֹצֵא בָּהֶן, \u0010y0\u0011 שֶׁהִנִּיחָם בִּרְשׁוּת הָרַבִּים וְהִזִּיקוּ בִּמְקוֹמָם, בֵּין הִפְקִירָן אוֹ לֹא הִפְקִירָן, אוֹ שֶׁהִנִּיחָם בְּרֹאשׁ גַּגּוֹ וְנָפְלוּ בְּרוּחַ מְצוּיָה וְהִזִּיקוּ בִּמְקוֹמָם אַחַר שֶׁנָּחוּ, שֶׁדּוֹמֶה לְבוֹר מָמוֹנוֹ שֶׁמַּזִּיק בְּמָקוֹם שֶׁמֻּנָּח שָׁם, לְפִיכָךְ, יֵשׁ לוֹ כָּל דִּינֵי בּוֹר \u0010y1\u0011 לְחַיֵּב נֶזֶק שָׁלֵם מִתְּחִלָּתוֹ עַל מִיתַת בְּהֵמָה אוֹ הֶזֵּקָהּ וְעַל נִזְקֵי אָדָם, בֵּין נִתְקַל בְּאֶבֶן וְהֻזַּק בְּאֶבֶן בֵּין נִתְקַל בְּקַרְקַע וְהֻזַּק בְּאֶבֶן. אֲבָל אִם נִתְקַל בְּאֶבֶן \u0010y2\u0011 וְהֻזַּק בַּקַּרְקַע, פָּטוּר. \u0010y3\u0011 \u0005וּפָטוּר\u0006 בּוֹ מִמִּיתַת אָדָם וְנִזְקֵי כֵּלִים. וְכֵן אִם הִנִּיחָם בִּרְשׁוּתוֹ וְהִפְקִיר רְשׁוּתוֹ וְלֹא הִפְקִירָם, וְנִתְקַל בְּקַרְקַע וְנִזַּק בְּתַקָּלָה זוֹ וְהֻזַּק, חַיָּב בַּעַל הַתַּקָּלָה.\nוְאִם נָפְלוּ בְּרוּחַ שֶׁאֵינָהּ מְצוּיָה וְהִזִּיקוּ בִּשְׁעַת נְפִילָה, אוֹ אֲפִלּוּ אַחַר נְפִילָה כָּל זְמַן שֶׁלֹּא הָיָה לוֹ פְּנַאי לְסַלְּקָם, פָּטוּר; אֲבָל לְאַחַר מִכָּאן \u0010y4\u0011 חַיָּב. וְאִי אַפְקְרִינְהוּ, פָּטוּר אֲפִלּוּ לְאַחַר מִכָּאן.\nאִם הִנִּיחָם בִּרְשׁוּת הָרַבִּים, וְלֹא הִזִּיקוּ בִּמְקוֹמָם, אֶלָּא נִתְגַלְגְּלוּ לְמָקוֹם אַחֵר \u0010y5\u0011 עַל יְדֵי רַגְלֵי אָדָם אוֹ רַגְלֵי בְּהֵמָה, אִם הִזִּיקוּ דֶרֶךְ הִלּוּכָן עַל יְדֵי רַגְלֵי אָדָם חַיָּב הַמְגַּלְגֵּל הַכֹּל, שֶׁהוּא פּוֹשֵׁעַ בְּהֶזֵּק זֶה, וּבַעַל הַתְּקָלָה פָטוּר. \u0010c0\u0011\nאִם גִּלְגְּלָם רַגְלֵי בְהֵמָה וְהִזִּיקוּ בְּהִלּוּכָם, חַיָּב בַּעַל הַבְּהֵמָה הַחֵצִי, וּבַעַל הַתַּקָּלָה הַחֵצִי.\nאִם הִתִּיזָה הַבְּהֵמָה וְהִזִּיקָה דֶרֶךְ הִלּוּכָהּ, \u0010y6\u0011 מְשַׁלֵּם בַּעַל הַבְּהֵמָה רְבִיעַ, וּבַעַל הַתַּקָּלָה שְׁלֹשָׁה חֲלָקִים.\nאִם לְאַחַר שֶׁנָּחוּ מֵגִּלְגוּלָם הִזִיקוּ, הָוָה לֵהּ בּוֹר וְחַיָּב בַּעַל הַתַּקָּלָה הַכֹּל.\nהִכְנִיס שׁוֹרוֹ לַחֲצַר חֲבֵרוֹ שֶׁלֹּא בִּרְשׁוּת \u0010y7\u0011 וְהֵטִיל בּוֹ גְּלָלִים וְטִנְּפוּ כֵּלָיו שֶׁל בַּעַל הֶחָצֵר, פָּטוּר בַּעַל הַשּׁוֹר, דְּהָוָה לֵהּ הָנַךְ גְּלָלִים בּוֹר, \u0010y8\u0011 וּבוֹר פָּטוּר בְּכֵלִים, כְּמוֹ שֶׁנִּתְבָּאֵר בְּסִימָן שֶׁקֹּדֶם זֶה:",["\u0003והזיקו במקומם. \u0004 דאז הוה דומיא דבור דהוא מונח במקומו והניזק עובר עליו משא\"כ אם הזיקו דרך הליכתן או נפילתן מן הגג דהוי תולד' דאש דמזיק דרך הלוכו לניזק העומד במקומו וכמ\"ש הטור והמחבר בסי' תי\"ח:","\u0003נזק שלם מתחלתו. \u0004 לאפוקי שור דאינו משלם נ\"ש מתחלתו עד שיגח ג\"פ:","\u0003והוזק בקרקע פטור. \u0004 דקרקע עולם הזיקתו דומה למ\"ש הטור בסי' ת\"י סכ\"ה בנתקל בבור ונפל אחורי הבור והוזק:","\u0003ופטור בו ממיתת אדם כו'. \u0004 כדין בור וכנ\"ל בסי' ת\"י ולא הפקירם דאלו הפקירם גם כן היה פטור כמ\"ש בסי' תי\"ו ס\"ו בחופר בור ברשותו ואח\"כ הפקיר בור ורשותו דסביבו ומטעם שכתבתי שם:","\u0003ואי אפקרינהו פטור. דה\"ל מפקיר נזקיו קודם שמזיקין אחר נפילת אונס דפטור:\u0004","\u0003ע\"י רגלי אדם חייב המגלגל כו' דאע\"ג דאין דרך בני אדם להתבונן בדרכים כמ\"ש בסימן ת\"י היינו לענין זה שאם שבר כלי שהוא מונח לפניו דפטור אבל כולי האי אין לו להשתגע בהליכתו שיתיז כלי ממקומו ויזיק דרך הליכתו ופושע הוא ומחייב בכולו ואם גלגל' רגלי בהמה והזיקה משלם כל אחד מחצה (כמ\"ש בסעיף שאחר זה) דומה לדליל הנקשר בתרנגול וכלב שנטל חררה ובה גחלת דחייב בעל הדליל ובעל הגחלת כל אחד מחצה וכמ\"ש בסי' ש\"ץ וטעם א' להן דהכלב והתרנגול דלשם ובהמה שבכאן לאו בני דעת נינהו אבל האדם בן דעת הוא מ\"ה הוא לבדו חייב בכולו:\u0004","\u0003משלם בעל הבהמה רביעית. דהתיז צרורות לבדו אינו משלם אלא חצי נזק וכאן דיש שותף עמו בחיוב היזקו אין עליו חוב אלא חצי דמי חיובו דהיינו רביעית והמותר על בעל התקלה מדרבי נתן:\u0004","\u0003והטיל בו גללי'. \u0004 ע\"ל סי' ש\"ץ ס\"ח דכתב אם הטילה גללים לעיסה חייב ח\"נ דה\"ל צרורות ונראה דה\"ה אם טנפה כלים דרך נפילתה (אלא שבהטילה לעיסה בעינן דדחיק' לה עלמא וכמבואר שם) משא\"כ כאן דאיירי בהזיקו אחר נפילתו:","\u0003ובור פטור בכלים. \u0004 אבל אם הוזק בו בעל החצר חייב בעל הבהמ' דה\"נ בורו ואע\"ג דכתיב כי יכרה איש בור ולא שור בור מ\"מ כיון דדידיה הוה בשעת נפילה ועליה דידיה רמיא לסלוקי ה\"ל כאלו איהו כרייה ואע\"ג דבסי' שי\"ג נתבאר בטור ובדברי המחבר דאם בהמת ראובן הטיל' גללים בחצר שמעון דזכה שמעון בהגללים שאני הכא דלא ניחא לי' לבעל החצר שיזכה חצירו דבר שיוזק על ידו אבל אם נראה דכבר ידע בעל החצר בהגללים וניחא לו בהו זוכ' לו חצירו ואח\"כ הוזק בו בעל החצר פטור בעל הבהמ' מניזקיו:"],["\u0003 אם גלגלם רגלי בהמה כו'. \u0004 וצ\"ל דגילגלו ברשות הניזק דאי בר\"ה פטורה דהא הוי תולד' דרגל וכן מצאתי ביש\"ש פ\"ק סי' ח' ודוק וא\"ל דהוי משונה והוי תולדה דקרן א\"כ לא ישלם אלא רביע כמו בהתיז' בסעיף ה' ודוחק לומר דבמועד איירי כאן וק\"ל:"],"\u0010g0\u0011 תּוֹלְדוֹת הַבּוֹר, אַבְנוֹ, סַכִּינוֹ וּמַשָּׂאוֹ וְכַיּוֹצֵא בָּהֶן, \u0010y0\u0011 שֶׁהִנִּיחָם בִּרְשׁוּת הָרַבִּים וְהִזִּיקוּ בִּמְקוֹמָם, בֵּין הִפְקִירָן \u0010g1\u0011 \u0010r0\u0011 אוֹ לֹא הִפְקִירָן, \u0010g2\u0011 \u0010r1\u0011 אוֹ שֶׁהִנִּיחָם בְּרֹאשׁ גַּגּוֹ וְנָפְלוּ בְּרוּחַ מְצוּיָה וְהִזִּיקוּ בִּמְקוֹמָם אַחַר שֶׁנָּחוּ, שֶׁדּוֹמֶה לְבוֹר מָמוֹנוֹ שֶׁמַּזִּיק בְּמָקוֹם שֶׁמֻּנָּח שָׁם, \u0010r2\u0011 לְפִיכָךְ, \u0010g3\u0011 יֵשׁ לוֹ כָּל דִּינֵי בּוֹר \u0010y1\u0011 לְחַיֵּב נֶזֶק שָׁלֵם מִתְּחִלָּתוֹ \u0010g4\u0011 \u0010r3\u0011 עַל מִיתַת בְּהֵמָה אוֹ הֶזֵּקָהּ וְעַל נִזְקֵי אָדָם, \u0010g5\u0011 בֵּין נִתְקַל בְּאֶבֶן וְהֻזַּק בְּאֶבֶן בֵּין נִתְקַל בְּקַרְקַע וְהֻזַּק בְּאֶבֶן. \u0010g6\u0011 \u0010r4\u0011 אֲבָל אִם נִתְקַל בְּאֶבֶן \u0010y2\u0011 וְהֻזַּק בַּקַּרְקַע, פָּטוּר. \u0010y3\u0011 \u0010g7\u0011 \u0005וּפָטוּר\u0006 בּוֹ מִמִּיתַת אָדָם וְנִזְקֵי כֵּלִים. \u0010g8\u0011 \u0010r5\u0011 וְכֵן אִם הִנִּיחָם בִּרְשׁוּתוֹ וְהִפְקִיר רְשׁוּתוֹ וְלֹא הִפְקִירָם, וְנִתְקַל בְּקַרְקַע וְנִזַּק בְּתַקָּלָה זוֹ וְהֻזַּק, חַיָּב בַּעַל הַתַּקָּלָה. \u0010g9\u0011 \u0010r6\u0011\nוְאִם נָפְלוּ בְּרוּחַ שֶׁאֵינָהּ מְצוּיָה וְהִזִּיקוּ בִּשְׁעַת \u0010r7\u0011 נְפִילָה, אוֹ אֲפִלּוּ אַחַר נְפִילָה כָּל זְמַן שֶׁלֹּא הָיָה לוֹ פְּנַאי לְסַלְּקָם, פָּטוּר; \u0010g10\u0011 אֲבָל לְאַחַר מִכָּאן \u0010y4\u0011 \u0010g11\u0011 \u0010r8\u0011 חַיָּב. וְאִי אַפְקְרִינְהוּ, פָּטוּר אֲפִלּוּ לְאַחַר מִכָּאן. \u0010g12\u0011 \u0010r9\u0011\nאִם הִנִּיחָם בִּרְשׁוּת הָרַבִּים, וְלֹא הִזִּיקוּ בִּמְקוֹמָם, אֶלָּא נִתְגַלְגְּלוּ לְמָקוֹם אַחֵר \u0010y5\u0011 עַל יְדֵי רַגְלֵי אָדָם אוֹ רַגְלֵי בְּהֵמָה, אִם הִזִּיקוּ דֶרֶךְ הִלּוּכָן עַל יְדֵי רַגְלֵי אָדָם \u0010g13\u0011 חַיָּב הַמְגַּלְגֵּל הַכֹּל, שֶׁהוּא פּוֹשֵׁעַ בְּהֶזֵּק זֶה, וּבַעַל הַתְּקָלָה פָטוּר. \u0010c0\u0011 \u0010g14\u0011\nאִם \u0010t0\u0011 גִּלְגְּלָם רַגְלֵי בְהֵמָה וְהִזִּיקוּ בְּהִלּוּכָם, חַיָּב בַּעַל הַבְּהֵמָה הַחֵצִי, וּבַעַל \u0010t1\u0011 הַתַּקָּלָה הַחֵצִי. \u0010g15\u0011 \u0010r10\u0011\nאִם הִתִּיזָה הַבְּהֵמָה וְהִזִּיקָה דֶרֶךְ הִלּוּכָהּ, \u0010y6\u0011 מְשַׁלֵּם בַּעַל הַבְּהֵמָה \u0010t2\u0011 רְבִיעַ, וּבַעַל הַתַּקָּלָה שְׁלֹשָׁה חֲלָקִים. \u0010g16\u0011\nאִם לְאַחַר שֶׁנָּחוּ מֵגִּלְגוּלָם הִזִיקוּ, הָוָה לֵהּ בּוֹר וְחַיָּב בַּעַל הַתַּקָּלָה הַכֹּל. \u0010g17\u0011\nהִכְנִיס שׁוֹרוֹ לַחֲצַר חֲבֵרוֹ שֶׁלֹּא בִּרְשׁוּת \u0010y7\u0011 וְהֵטִיל בּוֹ גְּלָלִים וְטִנְּפוּ \u0010t3\u0011 כֵּלָיו שֶׁל בַּעַל הֶחָצֵר, פָּטוּר בַּעַל הַשּׁוֹר, דְּהָוָה לֵהּ הָנַךְ גְּלָלִים בּוֹר, \u0010y8\u0011 וּבוֹר פָּטוּר \u0010t4\u0011 בְּכֵלִים, כְּמוֹ שֶׁנִּתְבָּאֵר בְּסִימָן שֶׁקֹּדֶם זֶה:",{"g":["א) לשון הטור והרמב\"ם בפי\"ג ד\"ג מבואר בפ' קמא דב\"ק דף ג' ע\"א ודף י' ובפ\"ג דכ\"ח ע\"ב","ב) פסק כשמואל שם דבלא אפקרינהו נמי הוי בור כידוע דהלכה כשמואל בדיני","ג) מבואר בפ\"ק שם דף ג' ע\"ב דמסיק אי בהדי דאזלי מזקי היינו אש מבואר בס\"ס תי\"ח ואי בתר דנייחי היינו בור וכו'","ד) כדעת הרא\"ש שם בר\"פ קמא","\u0003ה) מבואר במ\"ש בסי' דלעיל סעיף י:\u0004 ","\u0003ו) כלישנא בתרא דר' אלעזר שם בפ\"ג:\u0004 ","\u0003ז) כן כתבו התוספ' שם דקרקע עולם מזיקתו:\u0004 ","ח) כמו בבור עצמו ומבואר במ\"ש לעיל סי' ת\"י סעיף כ' וכ\"א","\u0003ט) גם זה מבואר במה שכתבתי בסימן דלעיל סעיף ו:\u0004 ","\u0003י) שם הכי משמע בפ\"ג דב\"ק דף כט ע\"א וטעמא משום דאנוס הוא:\u0004 ","\u0003כ) משום דהשתא אינו אנוס וכן כתבו התוספת שם:\u0004 ","ל) מבואר שם בגמרא ע\"א במפקיר נזקיו לאחר נפילת אונס פטור לרבנן דקיימא לן כותיהו","מ) שם כן כ' הרא\"ש בריש ב\"ק","נ) וביאר הרא\"ש שם אף ע\"ג דאמרינן שם בר\"פ המניח אין דרכן של בני אדם להתבונן בדרכים היינו לענין כלי שהיה מונח לפניו ושברו דרך הליכתו בלא התבונות אבל כולי האי אין לו להשתגע בהליכתו שיתיז הכלי ממקומו ופושע הוא בהיזק זה:","ס) שם דשם בפסקי הרא\"ש ברי' ב\"ק","\u0003ע) שם ושם וכר' נתן מבואר בסי' ת\"י סל\"ב:\u0004 ","פ) שם ושם מבואר במ\"ש בסעיף א' סעי' קטן ג'","צ) שם ס\"ב וברמב\"ם שם דין ד' מימרא דרבא שם בפ' ה' ד' מ\"ח ע\"א ופירשה רב פפא שם"],"t":["\u0003גלגלם. \u0004 וצ\"ל דגילגלן ברשות הניזק דאי ברשות הרבים פטורה דהא הוי תולדה דרגל וכן מצאתי במהרש\"ל פ\"ק סי' ה'. וא\"ל דהוי משונה וה\"ל תולדה דקרן א\"כ לא ישלם אלא רביע כמו בהתיזה בס\"ה ודוחק לו' דכאן איירי במועד. ש\"ך:","\u0003החצי. \u0004 דזה דומה לדליל הנקשר בתרנגול שבסי' ש\"צ ס\"י ע\"ש בהג\"ה וכלב שנטל חררה ובה גחלת דבר\"ס שצ\"ב דחייב בעל הדליל ובעל הגחלת כל אחד מחצה וטעם א' להן שם וכאן דכולהו לאו בני דעת נינהו אבל האדם בן דעת הוא מש\"ה כשנתגלגלו ע\"י אדם הוא לבדו חייב בכולו. סמ\"ע:","\u0003רביע. \u0004 דבהתיז צרורות לבדו אינו משלם אלא ח\"נ וכאן דיש שותף עמו בחיוב היזקו אין עליו חוב אלא חצי דמי חיובו דהיינו רביע. שם:","\u0003כליו. \u0004 ע\"ל סי' ש\"צ ס\"ח דכתב אם הטילה גללים לעיסה חייב ח\"נ דה\"ל צרורות ונראה דה\"ה אם טנפה כלים דרך נפילתן משא\"כ כאן דאיירי בהזיקו אחר נפילתן. שם:","\u0003בכלים. \u0004 אבל אם הוזק בהן בעל החצר חייב בעל הבהמה ואע\"ג דכתיב כי יכרה איש בור ולא שור בור מ\"מ כיון דדידיה הוי בשעת נפילה ועליה רמיא לסלוקי ה\"ל כאילו איהו כרייה ואע\"ג דנתבאר בסי' שי\"ג דאם בהמת ראובן הטילה גללים בחצר שמעון דזכה שמעון בהגללים שאני הכא דלא ניחא ליה לבעל החצר שיזכה חצירו דבר שיוזק על ידו אבל אם נראה דכבר ידע בעל החצר בהגללים וניחא ליה בהו וזכה לו חצירו ואח\"כ הוזק בו בעל החצר פטור בעל הבהמה מנזקין. שם:"],"r":["\u0003 (ליקוט) או לא הפקירן. \u0004 עבה\"ג וכן ס\"ל לרבא עס\"י תי\"ג (ע\"כ):","\u0003או שהניחם כו'. \u0004 ו' א':","\u0003לפיכך כו'. \u0004 הרא\"ש שם וכ' דכל האוקימתות שם אע\"ג דגמר במה הצד מ\"מ תולדות דבור הם ע\"ש:\n\u0003 (ליקוט) לפיכך כו'. \u0004 דג' אוקימתות האחרונות דיליף משור ע\"כ היאך חייב בהם ברה\"ר ועתוס' שם ד\"ה. תאמר כו'. הרא\"ש שם (ע\"כ): \u0003 (ליקוט') לפיכך יש לו כו'. \u0004 דעיקר דינו הוא כבור ואע\"ג דיליף לה ג\"כ מאש לא אמרינן דיו ועתוס' דקדושין יו\"ד ב' ד\"ה זו. ור\"ש כו'. יש\"ש ועיש\"ש שם שחולק וכ' דוקא באפקרינהו אבל בלא\"ה דין שניהן להן ואינו מוכרח (ע\"כ):","\u0003על כו'. בין כו'. \u0004 כ\"ח ב':","\u0003אבל כו'. \u0004 תוס' ד\"ה ונישוף כו':\n\u0003 (ליקוט) אבל אם נתקל כו'. \u0004 אבל נ\"י כ' דכ\"ש כה\"ג דחייב וכ\"כ הרשב\"א ועתוס' כ' ב' ד\"ה לשמואל כו' שדחקו בזה וערשב\"א שם (ע\"כ):","\u0003וכן כו'. \u0004 כמ\"ש בסי' ת\"י ס\"ו:","\u0003ואם נפלו כו'. \u0004 כ\"ט א' ומודה ר\"מ כו':","\u0003או כו' אבל כו'. \u0004 כמש\"ש ל\"א א' אר\"י ל\"ת כו' שה\"ל כו':","\u0003ואי כו'. \u0004 עבה\"ג. וכל סעי' זה הוא פי' תוס' שם ד\"ה פליגי ומודים דקתני בברייתא כו':","\u0003אם הניחם כו'. \u0004 ו' א' וכמ\"ש תוס' שם ד\"ה לאתויי כו':","\u0003אם התיזה כו'. \u0004 כ\"ז כ' הרא\"ש ומבואר בסי' ש\"צ ס\"י בהג\"ה דהתיזה היינו שור תם ובור לר\"נ נ\"ג א\"ב. ולאחר שנחו כמ\"ש בדליל י\"ט ב' וג\"כ כר\"נ:"]}],["הַמַּנִיחַ אֶת הַכַּד בִּרְשׁוּת הָרַבִּים, וּבָא אַחֵר וְנִתְקַל בּוֹ וּשְׁבָרוֹ, פָּטוּר, שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לְהִתְבּוֹנֵן בַּדְּרָכִים. וְאִם הֻזַּק בּוֹ, בַּעַל הַכַּד חַיָּב וַאֲפִלּוּ הִפְקִיר הַכַּד, שֶׁכָּל הַמַּפְקִיר נְזָקָיו בְּדָבָר שֶׁאֵין לוֹ רְשׁוּת לַעֲשׂוֹת מִתְּחִלָּה, חַיָּב.\nהִנִּיחַ הַכַּד בְּמָקוֹם שֶׁיֵּשׁ לוֹ רְשׁוּת לְהַנִּיחוֹ, כְּמוֹ \u0010y0\u0011 בְּמָקוֹם פָּנוּי שֶׁלִּפְנֵי בֵּית הַבַּד, וּבָא אַחֵר וְנִתְקַל בּוֹ \u0010y1\u0011 וְשָׁבְרוֹ, חַיָּב. וְאִם הֻזַּק בּוֹ הַמְהַלֵּךְ, בַּעַל הַכַּד פָּטוּר, מִפְּנֵי שֶׁהָיָה לוֹ לְהִסְתַּכֵּל. \u0010y2\u0011 וְאִם הָיְתָה אֲפֵלָה, אוֹ שֶׁמִּלֵּא כָּל הַדֶּרֶךְ כַּדִּים, פָּטוּר עַל שְׁבִירָתָן. וְאִם נִתְקַל בָּהּ וְהֻזַּק, בַּעַל הַכַּד חַיָּב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְאִם מִלֵּא כָּל הַדֶּרֶךְ כַּדִּים שֶׁאִי אֶפְשָׁר לַעֲבֹר, אֲפִלּוּ שְׁבָרוֹ בְּיָדַיִם פָּטוּר. וּמִיהוּ, אִם בְּשָׁעָה שֶׁשִּׁבְּרָם הֻזַּק בַּחֲרָסֶיהָ, פָּטוּר, אַף עַל פִּי שֶׁזֶּה מִלֵּא כָּל הַדֶּרֶךְ, דְּאִיהוּ דְאַזִּיק אַנַּפְשֵׁהּ.\nוְדַוְקָא אָדָם אֵין דַּרְכּוֹ לְהִסְתַּכֵּל בַּדְּרָכִים; אֲבָל בְּהֵמָה שֶׁעֵינֶיהָ לְמַטָּה, דַּרְכָּהּ לְעַיֵּן אָנָה תֵּלֵךְ. לְפִיכָךְ אִם נִתְקְלָה וְהֻזְּקָה בַּכַּד הַמֻּנָּח בִּרְשׁוּת הָרַבִּים, פָּטוּר בַּעַל הַכַּד. וְאִם שִׁבַּרְתּוֹ דֶּרֶךְ \u0010y3\u0011 הִלּוּכָהּ, הָוָה לֵהּ רֶגֶל וּפָטוּר. דֶּרֶךְ \u0010y4\u0011 בִּעוּט, הָוָה לֵהּ קֶרֶן וְחַיָּב.\nמִי שֶׁהָיָה טָעוּן כַּד, וְנִתְקַל וְנִשְׁבַּר הַכַּד וְהִזִּיק לַאֲחֵרִים בִּשְׁעַת נְפִילָה, פָּטוּר, \u0010y5\u0011 דְּנִתְקָל לָאו פּוֹשֵׁעַ הוּא. \u0005(ע\"ל טוּר סִימָן ש\"ד)\u0006. לְפִיכָךְ, אִם לְאַחַר שֶׁנָּחוּ שִׁבְרֵי הַכַּד בָּאָרֶץ הֻזָּק בָּהֶם אָדָם, אוֹ שֶׁהֻחְלַק בְּמַיִם שֶׁנִּשְׁפְּכוּ מֵהַכַּד, פָּטוּר מִדִּינֵי אָדָם, \u0010y6\u0011 דְּהָוֵי לֵהּ מַפְקִיר נְזָקָיו לְאַחַר נְפִילַת אֹנֶס, וְחַיָּב בְּדִינֵי שָׁמַיִם אִם הָיָה לוֹ פְּנַאי לְסַלְּקָם. וְאִם נִתְכַּוֵּן לִזְכּוֹת בְּשִׁבְרֵי הַחֶרֶס, חַיָּב בְּנִזָּקִין שֶׁיַּזִּיקוּ אַחַר כָּךְ, דְּהַשְׁתָּא הָוָה לֵהּ בּוֹר וּפָטוּר בָּהֶם עַל הַכֵּלִים. וְאִם פָּשַׁע בִּנְפִילָתָן וְנִשְׁבַּר הַכַּד, חַיָּב עַל מַה שֶּׁיַּזִּיק, בֵּין בִּשְׁעַת נְפִילָה בֵּין עַל אַחַר שֶׁנָּחוּ הַשְּׁבָרִים, \u0010y7\u0011 אֲפִלּוּ דְאַפְקְרִינְהוּ.\nהַשּׁוֹפֵךְ מַיִם בִּרְשׁוּת הָרַבִּים וְנִטַּנְפוּ בָּהֶם כֵּלָיו שֶׁל חֲבֵרוֹ, פָּטוּר, דְּהָוָה לֵהּ בּוֹר וּפָטַר בּוֹ אֶת הַכֵּלִים, בֵּין הִפְקִירָם בֵּין לֹא הִפְקִירָם. אֲבָל אִם הֻחְלַק בָּהֶם אָדָם \u0010y8\u0011 וְנָפַל לָאָרֶץ וְהֻזַּק, חַיָּב. וְכָל שֶׁכֵּן אִם \u0010y9\u0011 נִבְלְעוּ הַמַּיִם בָּאָרֶץ וְנַעֲשׂוּ רֶפֶשׁ וְטִיט \u0010y10\u0011 וְהִזִּיקוּ, דְּהַשְׁתָּא הָוֵי לֵהּ בּוֹר מַמָּשׁ, אֲפִלּוּ אִם הוּא בִּימוֹת הַגְּשָׁמִים שֶׁיֵּשׁ רְשׁוּת לְכָל אָדָם לִפְתֹּחַ בִּיב שֶׁלּוֹ לִהְיוֹת מְקַלֵּחַ בִּרְשׁוּת הָרַבִּים, אֲפִלּוּ הָכִי אִם הִזִּיק חַיָּב לְשַׁלֵּם. וְכָל שֶׁכֵּן בִּימוֹת הַחַמָּה, דְּחַיָּב, כֵּיוָן שֶׁהוּא שֶׁלֹּא בִּרְשׁוּת, שֶׁאֵין לָאָדָם רְשׁוּת לִפְתֹּחַ לִרְשׁוּת הָרַבִּים בִּימוֹת הַחַמָּה:",["\u0003במקום הפנוי שלפני בית הבד שפעמים מניחין שם כדין כשבית הבד מלא או כיוצא בו. טור:\u0004","\u0003ושברו חייב \u0004 דאף דאין דרך בני אדם להתבונן בדרכים שאני הכא דיודע דלפעמים מניחים שם כלים וה\"ל להתבונן ולראות אם יש שם ואם היתה אפילה שלא היה יכול להתבונן ה\"ל כנתקל בכלי דשאר מקומות ופטור:","\u0003ואם היתה אפילה או שמילא כל הדרך כדים פטור כו' \u0004 כן הוא ל' הרמב\"ם בפי\"ג דנ\"מ ד\"ו. ונרא' דאף דקאמר דממלא כל הדרך כדים מ\"מ מיירי דהי' אפשר לו לסבב ולילך מן הצד או להגבי' רגליו לעבור דרך עליהן מ\"ה דוקא בנתקל בה ושברו קאמר דפטור אבל כשמילא כ\"כ עד שא\"א לעבור בזה כ' המחבר אחר זה מיד דאפי' שברה בידים וברשות פטור וכן הוא משמעות הגמרא דר\"פ המניח ורש\"י והתוס' שם ע\"ש וגם ע\"ל ס\"ס שע\"ט:","\u0003ה\"ל רגל ופטור דרגל אינו חייב אלא בחצר הניזק \u0004 כמ\"ש בסימן ש\"ץ ושצ\"א:","\u0003ה\"ל קרן וחייב. \u0004 פי' חייב ח\"נ כדין קרן:","\u0003דנתקל לאו פושע היא. כ\"כ הרי\"ף והרמב\"ם וגם הטור סתם וכתב בסי' זה כן בס\"ו ולא חילק בין נתקל במקום מדרון לבמקום שאינו מדרון אכן בר\"ס ש\"ד חילק בינייהו וכ' דנתקל במקום שאינו מדרון פושע הוא מדינא וכ\"כ בקיצור פסקי הרא\"ש בס\"פ האומנין אבל הרא\"ש ג\"כ לא הזכיר שם חילוק בין מקום מדרון לאינו מקום מדרון ועד\"ר בר\"ס ש\"ד שם הארכתי:\u0004","\u0003דה\"ל מפקיר נזקיו כו'. \u0004 דמסתמא אדם מפקיר החרסים מן הכלי שנשבר לו בדרך והמים שנשפכו ממנו להארץ:","\u0003אפילו דאפקרינהו. \u0004 דה\"ל מפקיר נזקיו אחר שהונחו במקום שלא היה להן רשות להניח כגון זה שפשע בנפילתו:","\u0003ונפל לארץ והוזק בפר שם כתבתי ל' התוס' דמוקי לה בנפל לארץ שבו המים נשפכו דה\"ל כקרקעית הבור דא\"כ קשה מ\"ש מנתקל בבור ונפל אחורי הבור דפטור כמ\"ש בסי' ת\"י ע\"ש:\u0004","\u0003נבלעו המים בארץ. \u0004 ונמחה מהן הארץ עד שנעשה רפש וטיט:","\u0003והזיקו דהשתא כו' \u0004 דוקא הזיקו הא אם מת מזה השור פטור כיון דאין כאן הבל וגם ליתא כאן חבטה דעומק עשרה טפחים וכמ\"ש בסי' ת\"י בטור ובדברי המחבר דחבטה גובה י' טפחים דוקא בעינן לתשלומי מית' ע\"ש:"],[],"\u0010g0\u0011 הַמַּנִיחַ אֶת הַכַּד בִּרְשׁוּת הָרַבִּים, וּבָא אַחֵר וְנִתְקַל בּוֹ וּשְׁבָרוֹ, פָּטוּר, \u0010g1\u0011 שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לְהִתְבּוֹנֵן בַּדְּרָכִים. וְאִם הֻזַּק בּוֹ, בַּעַל הַכַּד חַיָּב וַאֲפִלּוּ הִפְקִיר הַכַּד, \u0010g2\u0011 שֶׁכָּל הַמַּפְקִיר נְזָקָיו בְּדָבָר שֶׁאֵין לוֹ רְשׁוּת לַעֲשׂוֹת מִתְּחִלָּה, \u0010g3\u0011 חַיָּב.\nהִנִּיחַ הַכַּד בְּמָקוֹם שֶׁיֵּשׁ לוֹ רְשׁוּת לְהַנִּיחוֹ, כְּמוֹ \u0010y0\u0011 בְּמָקוֹם פָּנוּי שֶׁלִּפְנֵי בֵּית הַבַּד, וּבָא אַחֵר וְנִתְקַל בּוֹ \u0010y1\u0011 וְשָׁבְרוֹ, \u0010g4\u0011 \u0010r0\u0011 חַיָּב. וְאִם הֻזַּק בּוֹ הַמְהַלֵּךְ, בַּעַל הַכַּד פָּטוּר, \u0010g5\u0011 מִפְּנֵי שֶׁהָיָה לוֹ לְהִסְתַּכֵּל. \u0010y2\u0011 \u0010g6\u0011 \u0010r1\u0011 וְאִם הָיְתָה \u0010g7\u0011 אֲפֵלָה, אוֹ שֶׁמִּלֵּא כָּל \u0010t0\u0011 הַדֶּרֶךְ כַּדִּים, פָּטוּר עַל שְׁבִירָתָן. וְאִם נִתְקַל בָּהּ וְהֻזַּק, בַּעַל הַכַּד חַיָּב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0010g8\u0011 וְאִם מִלֵּא כָּל הַדֶּרֶךְ כַּדִּים שֶׁאִי אֶפְשָׁר לַעֲבֹר, אֲפִלּוּ שְׁבָרוֹ בְּיָדַיִם פָּטוּר. \u0010g9\u0011 וּמִיהוּ, אִם בְּשָׁעָה שֶׁשִּׁבְּרָם הֻזַּק בַּחֲרָסֶיהָ, פָּטוּר, אַף עַל פִּי שֶׁזֶּה מִלֵּא כָּל הַדֶּרֶךְ, דְּאִיהוּ דְאַזִּיק \u0010g10\u0011 \u0010r2\u0011 אַנַּפְשֵׁהּ.\nוְדַוְקָא אָדָם אֵין דַּרְכּוֹ לְהִסְתַּכֵּל בַּדְּרָכִים; אֲבָל בְּהֵמָה שֶׁעֵינֶיהָ לְמַטָּה, דַּרְכָּהּ לְעַיֵּן אָנָה תֵּלֵךְ. לְפִיכָךְ אִם נִתְקְלָה וְהֻזְּקָה בַּכַּד הַמֻּנָּח בִּרְשׁוּת הָרַבִּים, פָּטוּר בַּעַל הַכַּד. וְאִם שִׁבַּרְתּוֹ דֶּרֶךְ \u0010y3\u0011 הִלּוּכָהּ, הָוָה לֵהּ רֶגֶל \u0010g11\u0011 וּפָטוּר. דֶּרֶךְ \u0010y4\u0011 \u0010g12\u0011 בִּעוּט, הָוָה לֵהּ קֶרֶן \u0010g13\u0011 וְחַיָּב.\nמִי שֶׁהָיָה טָעוּן כַּד, וְנִתְקַל וְנִשְׁבַּר הַכַּד וְהִזִּיק לַאֲחֵרִים בִּשְׁעַת נְפִילָה, פָּטוּר, \u0010y5\u0011 \u0010t1\u0011 דְּנִתְקָל לָאו פּוֹשֵׁעַ הוּא. \u0005(ע\"ל טוּר סִימָן ש\"ד)\u0006. לְפִיכָךְ, אִם לְאַחַר שֶׁנָּחוּ שִׁבְרֵי הַכַּד בָּאָרֶץ הֻזָּק בָּהֶם אָדָם, אוֹ שֶׁהֻחְלַק בְּמַיִם שֶׁנִּשְׁפְּכוּ מֵהַכַּד, \u0010g14\u0011 פָּטוּר מִדִּינֵי אָדָם, \u0010y6\u0011 \u0010t2\u0011 דְּהָוֵי לֵהּ מַפְקִיר נְזָקָיו \u0010r3\u0011 לְאַחַר נְפִילַת אֹנֶס, וְחַיָּב בְּדִינֵי שָׁמַיִם \u0010r4\u0011 אִם הָיָה לוֹ פְּנַאי לְסַלְּקָם. \u0010g15\u0011 \u0010r5\u0011 וְאִם נִתְכַּוֵּן לִזְכּוֹת בְּשִׁבְרֵי הַחֶרֶס, חַיָּב בְּנִזָּקִין שֶׁיַּזִּיקוּ אַחַר כָּךְ, דְּהַשְׁתָּא הָוָה לֵהּ בּוֹר \u0010g16\u0011 וּפָטוּר בָּהֶם עַל הַכֵּלִים. \u0010g17\u0011 \u0010r6\u0011 וְאִם פָּשַׁע בִּנְפִילָתָן וְנִשְׁבַּר הַכַּד, חַיָּב עַל מַה שֶּׁיַּזִּיק, בֵּין בִּשְׁעַת נְפִילָה \u0010g18\u0011 \u0010r7\u0011 בֵּין עַל אַחַר שֶׁנָּחוּ הַשְּׁבָרִים, \u0010y7\u0011 \u0010t3\u0011 אֲפִלּוּ דְאַפְקְרִינְהוּ. \u0010g19\u0011 \u0010r8\u0011\nהַשּׁוֹפֵךְ מַיִם בִּרְשׁוּת הָרַבִּים וְנִטַּנְפוּ בָּהֶם כֵּלָיו שֶׁל חֲבֵרוֹ, פָּטוּר, דְּהָוָה לֵהּ בּוֹר וּפָטַר בּוֹ אֶת הַכֵּלִים, \u0010g20\u0011 בֵּין הִפְקִירָם בֵּין לֹא הִפְקִירָם. אֲבָל אִם הֻחְלַק בָּהֶם אָדָם \u0010y8\u0011 וְנָפַל \u0010t4\u0011 לָאָרֶץ \u0010g21\u0011 וְהֻזַּק, חַיָּב. וְכָל שֶׁכֵּן אִם \u0010y9\u0011 נִבְלְעוּ הַמַּיִם בָּאָרֶץ \u0010g22\u0011 וְנַעֲשׂוּ רֶפֶשׁ וְטִיט \u0010y10\u0011 \u0010t5\u0011 וְהִזִּיקוּ, דְּהַשְׁתָּא הָוֵי לֵהּ בּוֹר מַמָּשׁ, \u0010g23\u0011 אֲפִלּוּ אִם הוּא בִּימוֹת הַגְּשָׁמִים שֶׁיֵּשׁ רְשׁוּת לְכָל אָדָם \u0010g24\u0011 לִפְתֹּחַ בִּיב שֶׁלּוֹ לִהְיוֹת מְקַלֵּחַ בִּרְשׁוּת הָרַבִּים, אֲפִלּוּ הָכִי אִם הִזִּיק חַיָּב לְשַׁלֵּם. וְכָל שֶׁכֵּן בִּימוֹת הַחַמָּה, דְּחַיָּב, כֵּיוָן שֶׁהוּא שֶׁלֹּא בִּרְשׁוּת, שֶׁאֵין לָאָדָם רְשׁוּת לִפְתֹּחַ לִרְשׁוּת הָרַבִּים בִּימוֹת הַחַמָּה:",{"g":["א) משנה רפ\"ג דבב\"ק דף כ\"ז ע\"א","\u0003ב) שם ע\"ב במסקנא הכי אמרי במערבא אין וכו':\u0004 ","ג) כן כתב הרמב\"ם בפי\"ג מהל' נזקי ממון דין פלוגתא דאמוראי שם דף כט ע\"ב ופסקו הפוסקים כרבי יוחנן דמחייב","\u0003ד) לשון הטור מעובדא שם דף כ\"ז ע\"ב בפומבדית' חייביה רבא וכדמפרש ר\"פ שם:\u0004 ","ה) לשון הרמב\"ם שם דין ו'","אע\"ג דאין דרך בני אדם להתבונן בדרכים במקום דשכיח להיות כדים יש להם","ו) כתב ה\"ה שם פי\"ג ד\"ו והדין עמו שהרי כך נראה מהסוגיא שם (מהא דאמר שמואל באפילה שנו):","\u0003ז) גם זה מהסוגיא שם אמרי דבי רב וכו':\u0004 ","\u0003ח) טור ס\"ג מימרא דרב זביד משמיה דרבא שם:\u0004 ","ט) שם ס\"ד ושם במימרא הנזכר מדיוק' דמתני'","י) שם ה\"ד כ\"כ הרא\"ש שם בפסקיו וכ\"כ התו' שם ממשנ' שור פקח ביום פטור","כ) מבואר בסימן ש\"ץ וכמ\"ש שם","ל) מבואר בסי' שפ\"ט ס\"ו","מ) שם ס\"ו ושם ברמב\"ם ד\"ז משנה שם דף כ\"ח ע\"א ופסקו הפוסקים כרבי יהודה דהיינו חכמים דברייתא וריש דף כ\"ט וכדאמר אביי שם דפליגי בתרתי וכולי","נ) שם בברייתא","\u0003ס) היינו דקאמר ר\"י במתני' אם במתכוין חייב וכו'\u0004 ","ע) נתבאר בסי' ת\"י סעיף כ\"א","פ) זה פשוט דהיכא דפושע ליכא מאן דפטר ביה","צ) ג\"ז נתבאר בתי' ת\"י ס\"ד","ק) שם ס\"ח וברמב\"ם שם די\"ב וכתב ה\"ה הוא כשמואל דבגמרא ולא כרב והטעם מפני שכל אלו הנזקין תולדות בור ולא מצינו בור שחייב בו את הכלים","ר) כשמואל שם דף כ\"ח ע\"ב דקי\"ל כוותיה","ש) גם זה כשמואל דאמר בור שחייב' עליו התורה להבלו וכל שכן לחבטי שם דף נ ע\"ב ודלא כאוקימתא דרב שם דף צ ע\"א","\u0003ת) דבכה\"ג לרב נמי חייב מבואר שם בסוגיא:\u0004 ","א) ברייתא שם","\u0003פי' רש\"י צינור המקלח מי שופכין של תשמיש הבית לר\"ה:\u0004 "],"t":["\u0003הדרך. \u0004 נראה דמ\"מ מיירי דהיה אפשר לו לסבב ולילך מן הצד או להגביה רגליו לעבור דרך עליהן מש\"ה דוקא בנתקל ושברו פטור אבל כשמילא כל כך עד שא\"א לעבור בזה אפילו שמרו בידים פטור כמ\"ש המחבר אח\"ז וכן הוא משמעות הש\"ס דר\"פ המניח ורש\"י ותוספות שם ועיין לעיל סוף סי' שע\"ט. סמ\"ע:","\u0003דנתקל. \u0004 עמ\"ש בזה בר\"ס ד\"ש ע\"ש:","\u0003מפקיר. \u0004 דמסתמא אדם מפקיר החרסים מן הכלי שנשבר לו בדרך והמים שנשפכו ממנו להארץ. שם:","\u0003דאפקרינהו. \u0004 דה\"ל מפקיר נזקיו אחר שהונחו במקום שלא היה לו רשות להניחן כגון זה שפשע בנפילתו. שם:","\u0003לארץ. \u0004 וכתבו התוס' דאיירי שנחבט בקרקע שהמים נשפכים עליה דדמיא לקרקעית הבור דאל\"כ מ\"ש הנתקל באבן והוזק בקרקע דפטור כמ\"ש בר\"ס תי\"א. שם:","\u0003והזיקו. \u0004 אבל אם מת השור מזה פטור כיון דאין כאן הבל ולא חבטא דעומק עשרה טפחים כמ\"ש בסי' ת\"י. שם:"],"r":["\u0003ואם הוזק כו'. \u0004 כיון דאיבעיא ליה לעיוני וכמש\"ש נ\"ד ב' בשור פקח:","\u0003ואם כו' או כו'. \u0004 דבזה ל\"פ במערבא ארב ושמואל.","\u0003ודוקא כו'. \u0004 עסי' ת\"י ס\"כ:","\u0003לאחר נפילת אונס. \u0004 שם ב' אלא הקמ\"ל דמפקיר כו':","\u0003ואם נתכוון כו'. \u0004 גמ' שם. ופליגי הרי\"ף ור\"י דרי\"ף כ' דמ\"ש דפליגי בתרתי חדא תליא בחבירתה כמ\"ש ר' יוחנן שם אלא הקמ\"ל כו' כנ\"ל ולפ\"ז באחר פשיעה לד\"ה חייב ור\"י כ' דר\"י פליג אף באחר נפילת פשיעה ומ\"מ לדינא אין נ\"מ דמ\"מ אין הלכה כר\"י בזה וכמ\"ש ר' יוחנן וכן מבור בר\"ה כמש\"ש ב' וקי\"ל דחייב כמ\"ש בסי' ת\"י ס\"ו וז\"ש ואם פשע כו'. ופי' כר' יהודה משום דבכולה פירקין קרו ליה רבנן ועמ\"ש בסי\" תי\"ג ס\"ב:","\u0003אם ה\"ל כו'. \u0004 עתוס' שם ד\"ה מדמתני'. ועוד דאי ל\"פ כו':","\u0003ואם פשע כו' בין כו'. \u0004 זהו מש\"ש ומודים חכמים לר\"מ כו':","\u0003בין על כו'. \u0004 זהו אידך ומודים כו' דוקא ברוח שאין מצויה וכפי' תוס' שם סד\"ה ופליגי:","\u0003השופך כו'. \u0004 עבה\"ג וכמש\"ש ותרתי ל\"ל כו':"]}],["שְׁנֵי קַדָּרִים שֶׁהָיוּ מְהַלְּכִים בַּדֶּרֶךְ, זֶה אַחַר זֶה, וְנִתְקַל הָרִאשׁוֹן וְנָפַל, וְנִתְקַל הַשֵּׁנִי בָּרִאשׁוֹן, אִם הָיָה לָרִאשׁוֹן לַעֲמֹד וְלֹא עָמַד, חַיָּב הָרִאשׁוֹן בְּנִזְקֵי שֵׁנִי, שֶׁאַף עַל פִּי שֶׁהוּא אָנוּס בִּשְׁעַת נְפִילָה, אֵינוֹ אָנוּס בִּהְיוֹתוֹ מֻטָּל לַדֶּרֶךְ, וַהֲרֵי הוּא יָכוֹל לַעֲמֹד; וְאִם לֹא הָיָה לוֹ לַעֲמֹד, פָּטוּר, וְאַף עַל פִּי שֶׁלֹּא הִזְהִיר לְזֶה שֶׁנִּתְקַל בּוֹ, מִפְּנֵי שֶׁהוּא טָרוּד בְּנַפְשׁוֹ. \u0010y0\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּחַיָב אִם הָיָה לוֹ פְּנַאי לְהַזְהִירוֹ וְלֹא הִזְהִיר (טוּר ס\"א בְשֵׁם הָרֹא\"שׁ)\u0006. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁהוּא חַיָּב בִּנְזָקָיו שֶׁל שֵׁנִי, כְּשֶׁהֻזַּק גּוּפוֹ שֶׁל שֵׁנִי. אֲבָל אִם הֻזְּקוּ כֵלָיו, פָּטוּר, שֶׁאֵינוֹ חַיָּב עַל הַכֵּלִים בַּבּוֹר, וְכָל תַּקָּלָה תּוֹלְדוֹת בּוֹר הוּא, \u0010y1\u0011 כְּמוֹ שֶׁנִּתְבָּאֵר.\nהַקַּדָּרִים וְהַזַּגָּגִים \u0005(פֵּרוּשׁ, מוֹכְרִים כְּלֵי זְכוּכִית)\u0006 וְכַיּוֹצֵא בָּהֶם שֶׁהָיוּ מְהַלְּכִים זֶה אַחַר זֶה, וְנִתְקַל הָרִאשׁוֹן וְנָפַל, וְנִתְקַל הַשֵּׁנִי בָּרִאשׁוֹן, וְהַשְּׁלִישִׁי בַּשֵּׁנִי, וְכָל אֶחָד מֵהֶם \u0010y2\u0011 יֵשׁ לוֹ לַעֲמֹד וְלֹא עָמַד, הָרִאשׁוֹן חַיָּב בְּנִזְקֵי גוּפוֹ שֶׁל שֵׁנִי, בֵּין שֶׁהֻזַּק בְּגוּפוֹ שֶׁל רִאשׁוֹן הַמֻּטָּל לָאָרֶץ \u0010y3\u0011 בֵּין שֶׁהֻזַּק בְּמַשָּׂאוֹ. \u0010y4\u0011 \u0005וְיֵשׁ חוֹלְקִין וּסְבִירָא לְהוּ דְּאִם הֻזַּק בְּמַשָּׂאוֹ אֲפִלּוּ גוּפוֹ שֶׁל שֵׁנִי, פָּטוּר (טוּר שָׁם בְּשֵׁם הָרֹא\"שׁ)\u0006. וְהַשֵּׁנִי חַיָּב בְּנִזְקֵי גוּפוֹ שֶׁל שְׁלִישִׁי, אִם הֻזַּק בְּגוּפוֹ שֶׁל שֵׁנִי; אֲבָל אִם הֻזַּק בְּמַשָּׂאוֹ שֶׁל שֵׁנִי שֶׁנָּפַל, פָּטוּר, שֶׁהֲרֵי אוֹמֵר לוֹ הַשֵּׁנִי: בּוֹר זֶה שֶׁהוּא מַשָּׂאִוֹ \u0010y5\u0011 אֵין אֲנִי הַכּוֹרֶה אוֹתוֹ, שֶׁהֲרֵי הָרִאשׁוֹן הִפִּיל הַשֵּׁנִי עִם מַשָּׂאוֹ. וְאִם הִזְהִירוּ זֶה אֶת זֶה, כֻּלָּם פְּטוּרִין.\nנָפַל הָרִאשׁוֹן וְהָיָה מֻטָּל לְרֹחַב הַדֶּרֶךְ, וְנִתְקַל אֶחָד בְּרֹאשׁוֹ וְאֶחָד בְּרַגְלָיו וְאֶחָד בְּבִטְנוֹ, הֲרֵי הוּא חַיָּב בְּנִזְקֵי כֻלָּם הוֹאִיל וְהָיָה לוֹ לַעֲמֹד וְלֹא עָמַד. \u0005הַגָּה: \u0010y6\u0011 וְיֵשׁ אוֹמְרִים דְּדַוְקָא אִם מֻנָּח הָרִאשׁוֹן בַּאֲלַכְסוֹן (טוּר שָׁם בְּשֵׁם הָרֹא\"שׁ)\u0006.",["\u0003וי\"א דחייב אם היה לו פנאי להזהירו ולא הזהיר. \u0004 הוא דעת הטור שכ\"כ בשם הרא\"ש בר\"ס זה ובדריש' כתבתי כאן בסי' שע\"ט דהרא\"ש משו' דין זה לדין אחד הולך בקורה ורשני בא אחריו בחביתו ונשבר החביות בהקור' דתנן בפ' המניח דאם עמד בעל הקור' בדרך עם קורתו דחייב בעל הקורה בשבירת חביתו ומפרש' דמיירי אפילו בעומד לתקן משאו ולא אמרי' דה\"ה טרוד במשאו מלהזהירו לבעל החביות ע\"ש ולא כהרי\"ף דמפרש להמשנה דמיירי דוקא בעומד לנוח וא\"כ ק' על הטור וגם על מור\"ם שבסימן שע\"ט סתמו כדברי הרי\"ף דבעמד כדי לתקן משאו פטור על שבירת החביות וכאן כתב הדברים בפלוגתא וכתבתי דצ\"ל הטור וגם מור\"ם ס\"ל דטרדת דבעל הקורה לתקן משאו היא גדולה יותר מאשר הוא טרוד הקדר והדומה לו שנפלו ושס\"ל שגם הרא\"ש אפשר דמודה לפי המסקנא לחלק בינייהו ושהמשנ' מיירי דוקא בעומד לנוח ועד\"ר בסי' שע\"ט שכתבתי מילתא בטעמא:","\u0003כמו שנתבאר \u0004 ר\"ל בסי' תי\"א ותי\"ב וזהו דעת הרמב\"ם והרא\"ש אבל הטו' כתב שדעת הרי\"ף הוא דגופו של ראשון שהיה יכול לעמוד ולא עמד מחשב כאדם המזיק בפשיעה ופושע חייב אפילו על כלים ויש בו נ\"מ לדינא גם למ\"ש בסעיף שאחד זה ועד\"ר שם הארכתי בפירושים ע\"פ סוגית הגמרא וע\"ש:","\u0003יש לו לעמוד ולא עמד \u0004 ולהי\"א הנ\"ל אף אם לא היה יכול לעמוד רק שהיה יכול להזהיר להבא אחריו ולא הזהיר וכ\"כ בטור ע\"ש:","\u0003בין שהוזק במשאו. \u0004 היינו הקדרי' והזגגים שנשאו ונפלו בדרך:","\u0003ויש חולקין כו' \u0004 לפי מה שנדפס ההג\"ה זו ומסודרת לפנינו היה נ\"ל להגיה וצ\"ל ויש חולקין וס\"ל דאפילו אם הוזק במשאו של ראשון גופו כו' וקאי האפילו אמ\"ש אם הוזק במשאו של שני פטור והי\"א ס\"ל דאף בשל ראשון פטור אבל שוב מצאתי בהגהות דמור\"ם הנכתבי' בכתיבת ידו שמסודרת החי הג\"ה לפני זה אמ\"ש דהראשון חייב בנזקי גופו של שני בין שהוזק בגופו של ראשון בין שהוזק במשאו אזה קאי הג\"ה דיש חולקין וס\"ל דדוקא אם הוזק גופו של שני בגופו של ראשון הוא דחייב הראשון ולא כשהזיק במשאו והוא דעת הרא\"ש וטעמו כיון דקי\"ל דנתקל לאו פושע הוא דיינו אם ניתן על גופו תורת בור ולא על משאו:","\u0003אין אני הכורה כו'. \u0004 אבל מה שהוזק מגופו חייב כיון דמ\"מ היה יכול לעמוד עם משאו ועד\"ר:","\u0003וי\"א דדוקא אם מונח הראשון באלכסון \u0004 הטעם דהיה לו להראשון ליזהר כשבא וראה שהשני נתקל בהראשון אבל כשמונח באלכסון כשנתקל השני בראשו של הראשון אותו שבא אח\"כ ונתקל ברגל דהראשון י\"ל דלא ראה השני מוטל לפניו ועד\"ז נמי כשנתקל עוד א' בהראשון בבואו לבטנו י\"ל דלא ראה לפניו לא זה שנתקל בראש דהראשון ולא זה שנתקל ברגלי דהראשון וק\"ל:"],[],"\u0010g0\u0011 שְׁנֵי קַדָּרִים שֶׁהָיוּ מְהַלְּכִים בַּדֶּרֶךְ, זֶה אַחַר זֶה, וְנִתְקַל הָרִאשׁוֹן וְנָפַל, וְנִתְקַל הַשֵּׁנִי בָּרִאשׁוֹן, \u0010g1\u0011 \u0010r0\u0011 אִם הָיָה לָרִאשׁוֹן לַעֲמֹד וְלֹא עָמַד, חַיָּב הָרִאשׁוֹן בְּנִזְקֵי שֵׁנִי, שֶׁאַף עַל פִּי שֶׁהוּא אָנוּס בִּשְׁעַת נְפִילָה, אֵינוֹ אָנוּס בִּהְיוֹתוֹ מֻטָּל לַדֶּרֶךְ, וַהֲרֵי הוּא יָכוֹל לַעֲמֹד; וְאִם לֹא הָיָה לוֹ לַעֲמֹד, פָּטוּר, וְאַף עַל פִּי שֶׁלֹּא הִזְהִיר לְזֶה שֶׁנִּתְקַל בּוֹ, מִפְּנֵי שֶׁהוּא טָרוּד בְּנַפְשׁוֹ. \u0010y0\u0011 \u0010r1\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּחַיָב אִם הָיָה לוֹ פְּנַאי לְהַזְהִירוֹ וְלֹא הִזְהִיר (טוּר ס\"א בְשֵׁם \u0010g2\u0011 הָרֹא\"שׁ)\u0006. \u0010g3\u0011 \u0010r2\u0011 בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁהוּא חַיָּב בִּנְזָקָיו שֶׁל שֵׁנִי, כְּשֶׁהֻזַּק גּוּפוֹ שֶׁל שֵׁנִי. אֲבָל אִם הֻזְּקוּ כֵלָיו, פָּטוּר, שֶׁאֵינוֹ חַיָּב עַל הַכֵּלִים בַּבּוֹר, וְכָל תַּקָּלָה תּוֹלְדוֹת בּוֹר הוּא, \u0010y1\u0011 כְּמוֹ \u0010t0\u0011 שֶׁנִּתְבָּאֵר. \u0010g4\u0011 \u0010r3\u0011\nהַקַּדָּרִים וְהַזַּגָּגִים \u0005(פֵּרוּשׁ, מוֹכְרִים כְּלֵי זְכוּכִית)\u0006 וְכַיּוֹצֵא בָּהֶם שֶׁהָיוּ מְהַלְּכִים זֶה אַחַר זֶה, וְנִתְקַל הָרִאשׁוֹן וְנָפַל, וְנִתְקַל הַשֵּׁנִי בָּרִאשׁוֹן, וְהַשְּׁלִישִׁי בַּשֵּׁנִי, \u0010g5\u0011 וְכָל אֶחָד מֵהֶם \u0010y2\u0011 יֵשׁ לוֹ \u0010t1\u0011 לַעֲמֹד וְלֹא עָמַד, \u0010g6\u0011 הָרִאשׁוֹן חַיָּב בְּנִזְקֵי גוּפוֹ שֶׁל שֵׁנִי, בֵּין שֶׁהֻזַּק בְּגוּפוֹ שֶׁל רִאשׁוֹן הַמֻּטָּל לָאָרֶץ \u0010y3\u0011 בֵּין \u0010g7\u0011 שֶׁהֻזַּק בְּמַשָּׂאוֹ. \u0010y4\u0011 \u0010r4\u0011 \u0005וְיֵשׁ חוֹלְקִין וּסְבִירָא לְהוּ דְּאִם הֻזַּק בְּמַשָּׂאוֹ אֲפִלּוּ גוּפוֹ שֶׁל שֵׁנִי, \u0010t2\u0011 פָּטוּר (טוּר שָׁם בְּשֵׁם הָרֹא\"שׁ)\u0006. וְהַשֵּׁנִי חַיָּב בְּנִזְקֵי גוּפוֹ שֶׁל שְׁלִישִׁי, אִם הֻזַּק בְּגוּפוֹ שֶׁל שֵׁנִי; אֲבָל אִם הֻזַּק בְּמַשָּׂאוֹ שֶׁל שֵׁנִי שֶׁנָּפַל, \u0010g8\u0011 פָּטוּר, שֶׁהֲרֵי אוֹמֵר לוֹ הַשֵּׁנִי: בּוֹר זֶה שֶׁהוּא מַשָּׂאִוֹ \u0010y5\u0011 אֵין אֲנִי הַכּוֹרֶה אוֹתוֹ, שֶׁהֲרֵי הָרִאשׁוֹן הִפִּיל הַשֵּׁנִי עִם מַשָּׂאוֹ. \u0010g9\u0011 וְאִם הִזְהִירוּ זֶה אֶת זֶה, כֻּלָּם פְּטוּרִין. \u0010g10\u0011 \u0010r5\u0011\nנָפַל הָרִאשׁוֹן וְהָיָה מֻטָּל לְרֹחַב הַדֶּרֶךְ, וְנִתְקַל אֶחָד בְּרֹאשׁוֹ וְאֶחָד בְּרַגְלָיו וְאֶחָד בְּבִטְנוֹ, הֲרֵי הוּא חַיָּב בְּנִזְקֵי כֻלָּם הוֹאִיל וְהָיָה לוֹ לַעֲמֹד וְלֹא עָמַד. \u0005הַגָּה: \u0010y6\u0011 וְיֵשׁ אוֹמְרִים דְּדַוְקָא אִם מֻנָּח הָרִאשׁוֹן \u0010t3\u0011 בַּאֲלַכְסוֹן (טוּר שָׁם בְּשֵׁם \u0010g11\u0011 הָרֹא\"שׁ)\u0006.",{"g":["א) לשון הרמב\"ם בפ' י\"ג מנזקי ממון ד\"ח משנה בפ\"ג דב\"ק דף ל\"א ע\"א","ב) פסק כר' יוחנן שם וכן פסק הרי\"ף וכן ראיתי בהג\"ה שם בשם א\"ז ושכן פסק מהרי\"ח:","ג) כר\"נ ב\"י שם וכתב הב\"י תמיהותיו של הרא\"ש על הרי\"ף שפסק כר' יוחנן אינם מכריעות דבקל יש לישבם ע\"כ ולענ\"ד לא החליט הרא\"ש לפסוק כר\"נ בר יצחק וז\"ל שם דלכאורה משמע והלכה כרב נחמן ואף על פי שאין אני כדאי להכריע מכל מקום אומר אני כיון שגם הא\"ז ומהרי\"ח מסכימים לדעת הרי\"ף והרמב\"ם וגם הרא\"ש לא החליט לפסוק כרב נחמן בן יצחק כדבריהם נקטינן וכן ראיתי אחר כך בב\"ח שכ\"כ","ד) שם ד\"ו ומבואר במ\"ש בסימן דלעיל ס\"ה","\u0003ה) שם ד\"י ברייתא שם וכתב ה\"ה גירסת רבינו ז\"ל כגיר' ההלכות ורש\"י ז\"ל והיא הנכונה:\u0004 ","ו) אוקימתא דגמרא שם אליבא דרבי יוחנן","ז) מימרא דרבא שם כגי' ההלכות ור\"י ז\"ל","ח) כתב ה\"ה ודברים פשוטים שכשחייב רבינו במשא הראשון לא חייב אלא בשלא הפקירו שאם כשהפקיר משאו וכבר נתבאר כו' ומבואר בסי' דלעיל ס\"ד במ\"ש שם וכ\"כ הראב\"ד שם בהשגות ראיתי להרב הרי\"ף שכ\"כ אמרתי אי אפשר שהוא טועה אלא הענין כולו כשלא הפקירו וכו' ע\"כ מעתה אין מקום למ\"ש הטור שאביו הרא\"ש חולק על דברי הרי\"ף והרמב\"ם ולא למ\"ש הרב רמ\"א שכתב ויש חולקין וכו'","ט) פירש הראב\"ד שם אף ע\"ג דלא הפקיר משאו ההוא שעתא מיה' בורו של ראשון הוא וראשון פטור דהא לאו בורו הוא ומפקיר נזקי אונסין פטור","י) שם בברייתא","\u0003כ) שם דין י\"א ברייתא שם ואם מחמת הראשון נפלו וכו'\u0004 וכדמפרש לה רב פפא שם ע\"ב וכן פסק הרי\"ף","ל) כמו שהגיה הב\"י שם וכדמפרש רב זביד כחוטר' דסמיותא וכפי' התוספת שם דפליגי ומסתפק הרא\"ש הלכתא כמאן ונקטינן לקולא ואין מחייבינן ליה אלא כשהוא באלכסון:"],"t":["\u0003שנתבאר. \u0004 בריש תי\"א ותי\"ב וע\"ל סי' שע\"ט וזהו דעת הרמב\"ם והרא\"ש אבל הטור כ' שדעת הרי\"ף דגופו של ראשון שהיה יכול לעמוד ולא עמד מיחשב כאדם המזיק בפשיעה ופושע חייב אף על הכלים ויש בזה נ\"מ לדינא גם למ\"ש בסעיף שאח\"ז. סמ\"ע:","\u0003לעמוד. \u0004 ולהי\"א שבס\"א אם היה לו פנאי להזהיר כו' וכ\"כ הטור ע\"ש. שם:","\u0003פטור. \u0004 טעמו כיון דקי\"ל נתקל לאו פושע הוא דיינו אם ניתן על גופו תורת בור ולא על משאו. שם:","\u0003באלכסון. \u0004 הטעם דאם מונח בשוה ה\"ל להשלישי ליזהר \u0005(א\"ה נ\"ל דכצ\"ל ובספרי סמ\"ע הנדפסים נראה שיש שם ט\"ס ע\"ש וק\"ל)\u0006 כשבא וראה שהשני נתקל בהראשון אבל כשמונח באלכסון כשנתקל השני בראשו של הראשון אותו שבא אח\"כ ונתקל ברגל דהראשון י\"ל דלא ראה השני מוטל לפניו ועד\"ז נמי כשעוד אחד נתקל בהראשון בבאו לבטנו י\"ל דלא ראה לפניו לא זה שנתקל בראש דהראשון ולא זה שנתקל ברגלי הראשון. שם:"],"r":["\u0003אם היה כו'. \u0004 כר\"י דגמ' שקיל וטרי לתרץ כל המתני' אליביה וכן במילתיה דרבא קא' שני אגופו מיחייב משום דה\"ל לעמוד כו':","\u0003וי\"א כו'. \u0004 כרנב\"י דבתרא הוא ועוד דכל תי' דשנינהו אליבא דר\"י שינויי דחיקי נינהו והא דקח' במילתיה דרבא משום דה\"ל כו' חדא מינייהו נקט כו' ועבה\"ג:","\u0003בד\"ח כו'. \u0004 ית' למטה:","\u0003הקדרים כו' הראשון כו' והשני כו'. \u0004 ז\"ל הרי\"ף אמר רבא ראשון חייב בנזקי שני בין דאיתזק בגופו בין דאיתזק בממונו ושני חייב בנזקי שלישי בדאיתזק בגופו אבל לא בדאיתזק בממונו מ\"ט דא\"ל האי בירא לאו אנא כריתיה והנה בגמ' נאמרו בה ב' פי' הא' פירש\"י כמ\"ש לפנינו והסכימו עמו תוס' והרא\"ש דלי' קמא דרבא מ\"ש ראשון חייב בין כו' שני כו' קאי הכל אגוף וממון דמזיקין ובנזקין אין חילוק בין גוף לממון מה שהוזק חייב אלא ממון דשני בראשון לבד פטור והדר קאמר אלא כו' דהכל קאי אניזוקים והכל בגוף המזיק אבל בממון המזיק פטור לעולם והדר פריך לרב כו' וחוזר לאוקימתא קמייתא וגי' רש\"י ותוס' ורא\"ש דל\"ג בגמ' לעולם כדקאמר מעיקרא כו' עד תרגמא וכ' הרא\"ש ואליבא דרב הוצרך לזה אבל אליבא דשמואל י\"ל כמ\"ש באוקימתא שניה מיהו אין לפרש מילתיה דרבא בתרי גווני אלא גם אליבא דשמואל מתרץ ר\"א בר אהבה ועוד דשינוייא קמא אלא אמר רבא כו' דחוק הוא כמ\"ש בתוס' ורא\"ש שם ואח\"כ כ' ורב אלפס ז\"ל כ' אמר רבא ראשון כו' ופי' דברי הרי\"ף כאוקימתא שניה וכמ\"ש הרא\"ש בתחלה דאוקימתא דר\"א ב\"א אינה אלא לרב אבל לשמואל קיימא אוקימתא שניה דאניזקין קאי וכ' ומ\"ש הרי\"ף מ\"ט דא\"ל האי כו' לא קאי אדברי רבא דזה הטעם לא שייך אלא אממונן דמזיקין אלא אברייתא קאי וכולן חייבין כו' שהביא הרי\"ף קודם לזה והביא דברי רבא ארישא דברייתא אנזקי גופן דמזיקין וחילק בניזקין כנ\"ל ואח\"כ כ' הרי\"ף על מ\"ש בברייתא ופטורין כו' דבממונן של המזיקין לעולם פטורין אף הראשון אף על גופו של שני מ\"ט דא\"ל האי כו' ולפ\"ז דברי הרמב\"ם אינו כדברי הרי\"ף דלא כמ\"ש הטור ודבריו תמוהין אבל הראב\"ד ומ\"מ וב\"י כ' שדברי הרמב\"ם כדברי הרי\"ף וכפירש\"י כנ\"ל ושלא כפי' הרא\"ש דדברי הרי\"ף אניזקין קאי אלא אמזיקין וכדברי הרמב\"ם וכמו שחזרו בגמ' לאוקימתא קמייתא והשתא דברי רי\"ף כפשטן דמ\"ש מ\"ט דא\"ל האי כו' קאי אדברי רבא וכמ\"ש הרמב\"ם והעתיקו בש\"ע דברי הרמב\"ם כלשונו. ועדיין צ\"ע דהא לאוקימתא קמייתא אף כלים דלכל הניזקין חייבין לפירש\"י והרמב\"ם וש\"ע בס\"א כ' בד\"א כו' אבל בעל המאור והמלחמות פי' דברי הרי\"ף והגמרא כפי' ר\"ח ולשון ראשון שברש\"י הביאו תוס' ד\"ה אמר כו'. וז\"ל הגמ' לגי' ר\"ח אמר רבא ראשון חייב בנזקי שני בין בנזקי גופו בין בנזקי ממונו דשני שני חייב בנזקי שלישי בנזקי גופו דשלישי אבל לא בנזקי ממונו מ\"נ אי נתקל פושע כו' שני אגופו מיחייב משום דה\"ל לעמוד ולא עמד אממונו פטור דה\"ל בור ולא מצינו בור שחייב בו את הכלים מתבי וכולם חייבים כו' אלא אמר רבא ראשון חייב בנזקי שני בין דאיתזק מגופו בין דאיתזק מממונו שני חייב בנזקי שלישי בדאיתזק מגופו אבל לא בדאיתזק מממונו מ\"ט דא\"ל האי בירא לאו אנא כריתיה וכולן חייבין על נזקי גופן ופטורין על נזקי ממונם הניחא לשמואל כו' מאי איכא למימר תרגמא רב אדא כו' והיא הפוכה מגי' רש\"י דלפ\"ז באוקימתא קמייתא קאי דברי רבא אניזקין ובאוקימתא שניה קאי אמזיקין אלא דלפ\"ז לא הדר מאוקימתא שניה דקושית גמ' הניחא לא קאי אדברי רבא אלא אברייתא דוכולן כו' בין לאוקימתא ראשונה בין לאוקימתא שניה וכמ\"ש תוס' דהאי וכולן כו' כמו אמר מר הוא ואף שהרז\"ה ל\"ג כלל וכולן חייבין כו' אלא גרס במ\"ש בגי' שלנו אחר מילתיה דרבא הניחא מ\"מ מפרש כפי' תוס' דאברייתא קאי דלגי' רש\"י מפרשינן וכולן כו' קאי אמזיקין ולכן פריך מזה ארבא ואוקימתא שניה דרבא אניזוקין וקאי הניחא ארבא וצריך לחזור מאוקימתא זו אבל לפיר\"ח קאי וכולן כו' אניזקין ולא קאי הקושיא אלא אברייתא לאוקימתא שניה והשתא דברי הרי\"ף כדברי הרמב\"ם וכפיר\"ח דמ\"ש הרמב\"ם וש\"ע בס\"ר בד\"א כו' הוא הברייתא וכולן כו' אלא דלדברי רב כלים בכלים דוקא ולשמואל אפילו כלים באדם וקי\"ל כשמואל ומ\"ש בס\"ב הראשון כו' הוא מילתיה דרבא באוקימתא שניה והכי קיימא וכ\"כ לח\"מ וע\"ש שמתרץ כל קושיות תוס' על פיר\"ח:","\u0003וי\"ח כו'. \u0004 הרואה סובר שהוא בא להקל ואינו אלא להחמיר והוא דברי הרא\"ש שהסכים ללשון שני של רש\"י הנ\"ל וכדעת התוס' וכמש\"ש דאף לשמואל הדרינן לאוקימתא קמייתא והוא ג\"כ כשיטת ר\"ח לפי' תוס' שכ' דמ\"ש תרגמא ר\"א כו' קאי אף לשיטת ר\"ח אף לשמואל מטעם אדם המזיק דחייב אף על הכלים אבל הרמב\"ם לא ס\"ל כן אלא דהתי' אינה אלא לרב אבל לשמואל הברייתא כפשטא דכל ממון הניזקין פטורין אף מאדם וכמ\"ש בעל המאור דלשמואל כל תקלה בור אף גוף הראשון אבל לתוס' ורש\"י דגם שמואל ס\"ל כרב ס\"ל דגוף מזיק הוא אף גוף השני. ופי' רש\"י ותוס' ורא\"ש והרז\"ה דממון המזיק הראשון בין לאוקימתא קמייתא דרבא לפירש\"י דהכי קיימא במסקנא בין לאוקימתא שניה לפיר\"ח דהכי קיימא במסקנא לפירושו שלדינא הכל אחד משום מפקיר נזקיו לאחר נפילת פשיעה משא\"כ בשני דאנוס הוא אלא גופו משום דה\"ל לעמוד ה\"ל מזיק ולרמב\"ם ורז\"ה אליבא דשמואל בור דכל תקלה בור כנ\"ל והקשו תוס' ורא\"ש דל\"ל לרבא לומר אליבא דר\"מ ה\"ל לפרש ברייתא אליבא דרבנן ואין חילוק בין ראשון לשני ותי' דלרבנן ממונן של הניזקין אף בגופו של ראשון פטור משום דכיון דלאו פושע הוא לא הוי אלא מטעם תקלה דה\"ל בור ופטור אכלים ול\"ד לגוף השני אליבא דר\"מ דהתם אע\"ג דנתקל בראשון דלאו פושע גמור הוא שיהיה מפקיר נזקיו לאחר נפילת פשיעה מ\"מ קצת פשיעה איכא ומצטרף עם הטעם דה\"ל לעמוד לעשות גופו כמזיק משא\"כ לרבנן דשניהן אנוסין גמורין הן ואנן קי\"ל כרבנן דהא ר' יוחנן ס\"ל כוותיהו שם צ\"ט ב' כמש\"ש אמר שמואל כו'. ומי אר\"י הכי כו' ובב\"מ פ\"ג א' ההוא גברא דקא מעבר חביתא כו' א\"ל רסתקא דמחוזא שכיחי בה אינשי אייתי ראיה דלא פשעת בה ואיפטר כו' כ\"ה גי' הרי\"ף שם וכ\"כ במלחמות שכן הגי' בספרים וכ' הרי\"ף שם מהא שמעינן דהיכא דליכא סהדי דלא פשע לא משבעינן ליה דשלא בכוונה תברה והך דקאמר רבא שם שבועה שלא בכוונה כו' לפרושיה לדר\"מ קאתי וליה לא ס\"ל וכמ\"ש בסי' ש\"ד ס\"א וסי' תי\"ב ס\"ד וא\"כ בין ראשון בין שני אינו חייב אלא גוף בגוף וז\"ש וי\"ח כו' וכ\"ה לרז\"ה אליבא דרבנן אלא שהוא פוסק כר\"מ כמ\"ש למטה אבל לר\"ה והרמב\"ם שפי' שממונם של נזקין פטורין לעולם הדרא קושית תוס' ורא\"ש לדוכתיה ומכח זה פי' הרז\"ה כר\"מ ובב\"מ שם ל\"ג דלא פשעת כגי' שלנו ובב\"ק שם ר' יוחנן לא ס\"ל כשמואל דמדמי לנתקל. והרמב\"ן במלחמות סתר דבריו ופי' דרבא אף לרבנן קאמר ואפ\"ה ראשון בדאיתזק מממונו משום שאינו מפקיר וסתמא דמילתא הכי הוא שאין מפקירין משום דנפלו אבל שני פטור אע\"ג דלא אפקריה משום דא\"ל האי כו' ודומה לאבנו סכינו ומשאו שהצניען בביתו ובא אחר והניחן ברה\"ר והזיקו שהבעלים פטורים ואע\"ג שה\"ל לסלקו ולא אפקריה שאינו מן הדין שזה חופר וזה יתחייב וכאן אף הראשון פטור מה שהזיק ממונו של שני אף שכרהו דה\"ל כמפקיר נזקיו לאחר נפילת אונס שהרי אינו שלו וכן פי' הראב\"ד בהשגות דברי רי\"ף והרמב\"ם וז\"ש הרמב\"ם במשאו ועבה\"ג ס\"ק ח' ט' ובכה\"ג להי\"ח שהוא הרא\"ש אף ממונו של שני שהזיק גוף השלישי חייב אפי' לרבנן ומ\"ש הרמב\"ן מידי דהוי כו' שאינו מן הדין כו' כ\"כ ג\"כ הרא\"ש והטור והב\"י בסי' ש\"צ ס\"י בהג\"ה אבל אם קשרו אדם כו' אפילו יש כו' מיהו לדברי תוס' והרב בסי' ת\"י ס\"ד בהגה דוקא בשלא נודע אבל נודע ה\"ל לסלקו וא\"כ אף כאן אף השני חייב אף על ממונו שמזיק בדלא אפקריה ועתוס' כ\"ט א' ד\"ה פליגי ואפי' נתנו אחר כו' וכ\"כ בהג\"א שם ד\"ה אבל אי כו' וזהו דעת הרא\"ש והי\"ח כאן והתוס' מ\"ח א' סד\"ה אע\"ג הניחו בצ\"ע והרא\"ש שם ס\"ז לפי דברי ש\"ע בסי' ת\"י ס\"ו שכ' או פתח לרשות חבירו מ' כדברי הרמב\"ן הנ\"ל אלא שבדברי הרא\"ש אין הכרע שהוא כ' אם נפל לתוכו בהמת בעל החצר וכ\"כ יש\"ש והטור פי' שלא נודע לבעל החצר וכמש\"ש בס\"ד בהגה וגם מדברי התוס' שם מ\"ט ב' סד\"ה ברה\"י אין הכרע שהם כ' כיון שהחופר משלם בנזקי כו' מ' דוקא כה\"ג ולכאורה הוא כדברי הרמב\"ן וכן י\"ל ג\"כ תוס' הנ\"ל מ\"ח א' ושלכן סתם הרא\"ש והרב בדליל כנ\"ל:","\u0003נפל כו'. \u0004 כפירש\"י והרי\"ף דל\"פ ר\"פ ור\"ז וערא\"ש:"]}],["לֹא יוֹצִיא אָדָם תִּבְנוּ וְקַשּׁוֹ לִרְשׁוּת הָרַבִּים כְּדֵי שֶׁיִּדֹּשׁוּ וְיַעֲשׂוּ זֶבֶל; וְאִם הוֹצִיאָם, קְנָסוּהוּ חֲכָמִים שֶׁיִּהְיוּ כְּהֶפְקֵר וְכָל הַקּוֹדֵם בָּהֶם זָכָה \u0010y0\u0011 מֵעֵת שֶׁנִּדּוֹשׁוּ וְהִשְׁבִּיחוּ. \u0005מִיהוּ יֵשׁ אוֹמְרִים, דְּאֵין מוֹרִין לוֹ לְכַתְּחִלָּה לְהַחֲזִיק רַק בַּשֶּׁבַח, אֲבָל לֹא בְּגוּפוֹ; וְאִם הִתְרוּ בַּבְּעָלִים וְלֹא סִלְּקוּ, מַפְקִירִין אוֹתוֹ לַכֹּל (טוּר ס\"ד)\u0006. וְאִם קָדַם אָדָם וְזָכָה בָּהֶם מִשְּׁעַת הוֹצָאָה לִרְשׁוּת הָרַבִּים, אֵין מוֹצִיאִין מִיָּדוֹ. \u0005וְיֵשׁ אוֹמְרִים דְּלָא מְהַנֵּי תְּפִיסָה (ר\"י וְרֹא\"שׁ וְטוּר שָׁם)\u0006 וְע\"ל סִימָן שפ\"ח. וְאַף עַל פִּי שֶׁהֵם כְּהֶפְקֵר, אִם הֻזַּק בָּהֶם אָדָם אוֹ בְּהֵמָה, \u0010y1\u0011 הֲרֵי זֶה הַמּוֹצִיא חַיָּב לְשַׁלֵּם. \u0010y2\u0011\nיֵשׁ לְכָל אָדָם לְהוֹצִיא אֶת הַזֶּבֶל וְהַגְּלָלִים לִרְשׁוּת הָרַבִּים בִּשְׁעַת הוֹצָאַת זְבָלִים, \u0005אֲבָל שֶׁלֹּא בִּשְׁעַת הוֹצָאַת זְבָלִים אָסוּר לְהוֹצִיאוֹ כְּדֵי לְהַנִּיחוֹ שָׁם, אֲבָל מוֹצִיאוֹ כְּדֵי לְפַנּוֹתוֹ לְאַלְתַּר (טוּר ס\"א)\u0006, וְכָל שֶׁכֵּן מַיִם נְקִיִּים וְשׁוֹפְכִין שֶׁלּוֹ \u0010y3\u0011 שֶׁאֵין שׁוֹהִין וּמִתְעַכְּבִים בִּרְשׁוּת הָרַבִּים, שֶׁמֻּתָּר לְשָׁפְכָן אֲפִלּוּ בִּימוֹת הַחַמָּה; וַאֲפִלּוּ מַיִם סְרוּחִין, כָּל שֶׁדַּעְתּוֹ לְפַנּוֹתוֹ לְאַלְתַּר. וַאֲפִלּוּ מְתַקֵּן בּוֹר פָּחוֹת מִשְּׁלֹשָׁה טְפָחִים אֵין בְּנֵי רְשׁוּת הָרַבִּים יְכוֹלִים לְעַכֵּב \u0005(מָרְדְּכַי סוֹף ב\"מ בְּשֵׁם מַהֲרַ\"מ)\u0006, וְלִצְבֹּר אוֹתָם שָׁם שְׁלֹשִׁים יוֹם, \u0010y4\u0011 כְּדֵי שֶׁיִּהְיֶה נִשֹּׁף בְּרַגְלֵי אָדָם; \u0010y5\u0011 וְאַף עַל פִּי כֵן אִם הִזִּיק חַיָּב לְשַׁלֵּם. וְחַיָּבִים עַל זֶה הַגָּלָל מִשּׁוּם גָּזֵל, כֵּיוָן שֶׁאֵין בּוֹ שֶׁבַח אִם נִדֹּשׁ, לֹא קָנְסוּ בּוֹ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דִּלְאַחַר שֶׁהֻזַּק, כָּל הַקּוֹדֵם בָּהֶם זָכָה (טוּר ס\"ב)\u0006.",["\u0003מעת שנידושו והשביחו. \u0004 בגמרא קאמר דקנסו גופו של תבן לעשותו כהפקר משום שבחו כדי שלא יעברו ויוציאו לר\"ה להשביחו לעשות ממנו זבל וקמבעיא בגמרא אם לא גזרו על גופו להפקירו עד שעה שכבר השביח דאז שייך טפי לומר שגזרו גופו משום שבחו או דילמא גם קודם שהשביח ונעשה זבל קנסו להיות גופו של הזוכה כדי שלא יוציאו ולא איפשיטא והמחבר סתם וכתב כדעת הרמב\"ם שנתבאר לעיל כמה פעמים בטור וגם בסי' זה בשמו דס\"ל דמהני תפיס' לספיקא דדינא ומש\"ה כ' אחר זה ז\"ל ואם קדם אדם כו' אין מוציאין מידו ומור\"ם כ' עליו די\"א (והוא דעת ר\"י והרא\"ש) דלא מהני כו':","\u0003הרי זה המוציא חייב לשלם \u0004 דכיון דממונו היא ס\"ל כמפקיר נזקיו אחר הנחתו במקום שלא היה לו רשות להניחו דחייב כמ\"ש בסימנים שלפני זה:","\u0003יש לכל אדם להוציא את הזבל כו'. \u0004 דזבל אינו מזיק כ\"כ כמו קש שהוא מחליק וגם הוא ארוך ונופלים ע\"י בקל:","\u0003שאין שוהין ומתעכבין \u0004 פי' אלא נוזלין ויוצאין מעצמם מיד לאחר שפיכתן מאותו מקום ויתפזרו ואין מזיקין:","\u0003כדי שיהא נישוף. \u0004 בגמרא קאמר הטעם דע\"מ כן הנחיל יהושע את הארץ לישראל שלא יקפדו בזה זה על זה וע\"ל סי' רע\"ד דשם כ' הטור שהרי\"ף חולק ע\"ז:","\u0003ואעפ\"כ אם הזיק חייב. \u0004 דיהושע לא התנ' שיהא פטור מתשלומי היזיקו ואעפ\"כ צריכין לתנאי דיהושע דאל\"כ היו מוחין דלא ניחא ליה לאדם שיהא ניזק בשלו ואח\"כ ישתלם הזיקו וגם יצטרך לירד עמו בדינא ודיינא ולא כע\"ש שכ' שיהושע לא התנה אלא ע\"מ שיהא כ\"א משמר את זבלו ע\"ש וזה ודאי אינו אלא אף אם אינו משמרו כו' רק שיהא צריך לשלם הזיקו:"],[],"\u0010g0\u0011 \u0010r0\u0011 לֹא יוֹצִיא אָדָם תִּבְנוּ וְקַשּׁוֹ לִרְשׁוּת הָרַבִּים כְּדֵי שֶׁיִּדֹּשׁוּ וְיַעֲשׂוּ \u0010g1\u0011 זֶבֶל; \u0010r1\u0011 וְאִם הוֹצִיאָם, קְנָסוּהוּ חֲכָמִים שֶׁיִּהְיוּ כְּהֶפְקֵר \u0010g2\u0011 וְכָל הַקּוֹדֵם בָּהֶם זָכָה \u0010y0\u0011 \u0010g3\u0011 \u0010r2\u0011 מֵעֵת שֶׁנִּדּוֹשׁוּ וְהִשְׁבִּיחוּ. \u0010r3\u0011 \u0005מִיהוּ יֵשׁ אוֹמְרִים, \u0010g4\u0011 דְּאֵין מוֹרִין לוֹ לְכַתְּחִלָּה לְהַחֲזִיק \u0010r4\u0011 רַק בַּשֶּׁבַח, אֲבָל לֹא בְּגוּפוֹ; \u0010g5\u0011 וְאִם הִתְרוּ בַּבְּעָלִים וְלֹא סִלְּקוּ, מַפְקִירִין אוֹתוֹ לַכֹּל (טוּר ס\"ד)\u0006. \u0010g6\u0011 וְאִם קָדַם אָדָם וְזָכָה בָּהֶם מִשְּׁעַת הוֹצָאָה לִרְשׁוּת הָרַבִּים, אֵין מוֹצִיאִין מִיָּדוֹ. \u0005וְיֵשׁ אוֹמְרִים דְּלָא מְהַנֵּי תְּפִיסָה (ר\"י וְרֹא\"שׁ וְטוּר שָׁם)\u0006 וְע\"ל סִימָן שפ\"ח. \u0010g7\u0011 וְאַף עַל פִּי שֶׁהֵם כְּהֶפְקֵר, אִם הֻזַּק בָּהֶם אָדָם אוֹ בְּהֵמָה, \u0010y1\u0011 הֲרֵי זֶה הַמּוֹצִיא \u0010t0\u0011 חַיָּב לְשַׁלֵּם. \u0010y2\u0011 \u0010g8\u0011 \u0010r5\u0011\nיֵשׁ לְכָל אָדָם לְהוֹצִיא אֶת \u0010t1\u0011 הַזֶּבֶל וְהַגְּלָלִים לִרְשׁוּת הָרַבִּים בִּשְׁעַת הוֹצָאַת זְבָלִים, \u0010r6\u0011 \u0005אֲבָל שֶׁלֹּא בִּשְׁעַת הוֹצָאַת זְבָלִים אָסוּר לְהוֹצִיאוֹ כְּדֵי לְהַנִּיחוֹ שָׁם, \u0010r7\u0011 אֲבָל מוֹצִיאוֹ כְּדֵי לְפַנּוֹתוֹ לְאַלְתַּר (טוּר ס\"א)\u0006, \u0010r8\u0011 וְכָל שֶׁכֵּן מַיִם נְקִיִּים וְשׁוֹפְכִין שֶׁלּוֹ \u0010y3\u0011 שֶׁאֵין שׁוֹהִין \u0010t2\u0011 וּמִתְעַכְּבִים בִּרְשׁוּת הָרַבִּים, שֶׁמֻּתָּר לְשָׁפְכָן \u0010r9\u0011 אֲפִלּוּ בִּימוֹת הַחַמָּה; וַאֲפִלּוּ מַיִם סְרוּחִין, כָּל שֶׁדַּעְתּוֹ לְפַנּוֹתוֹ לְאַלְתַּר. \u0010r10\u0011 וַאֲפִלּוּ מְתַקֵּן בּוֹר פָּחוֹת מִשְּׁלֹשָׁה טְפָחִים אֵין בְּנֵי רְשׁוּת הָרַבִּים יְכוֹלִים לְעַכֵּב \u0010g9\u0011 \u0005(מָרְדְּכַי סוֹף ב\"מ בְּשֵׁם מַהֲרַ\"מ)\u0006, וְלִצְבֹּר אוֹתָם שָׁם שְׁלֹשִׁים יוֹם, \u0010y4\u0011 כְּדֵי שֶׁיִּהְיֶה \u0010t3\u0011 נִשֹּׁף בְּרַגְלֵי אָדָם; \u0010y5\u0011 \u0010r11\u0011 וְאַף עַל פִּי כֵן אִם הִזִּיק \u0010t4\u0011 חַיָּב לְשַׁלֵּם. וְחַיָּבִים עַל זֶה הַגָּלָל \u0010g10\u0011 מִשּׁוּם גָּזֵל, כֵּיוָן שֶׁאֵין בּוֹ שֶׁבַח אִם נִדֹּשׁ, לֹא קָנְסוּ בּוֹ. \u0005הַגָּה: \u0010r12\u0011 וְיֵשׁ אוֹמְרִים דִּלְאַחַר שֶׁהֻזַּק, כָּל הַקּוֹדֵם בָּהֶם זָכָה (טוּר ס\"ב)\u0006.",{"g":["א) ל' הרמב\"ם בפי\"ג מהנ\"מ די\"ד משנה פ\"ג דב\"ק דף ל' ע\"א ואוקימתא דרב אשי שם","פי' כדי לזבל שדות וכרמים","ב) שם במשנה וכרב דאמר בין בגופן בין בשבחן שם ע\"ב","ג) פשוט שם בגמרא ע\"ב אליבא תירוצא דרב נחמן","ד) כן כתב הרא\"ש בפסקיו מאוקימתא דגמרא שם וכ' הב\"י וכן בכ\"מ דהרמב\"ם ס\"ל דהאי אוקימתא דיחויא בעלמא הוא ונלע\"ד הא דאיתא מימרא מפורשת דרב הונא משמיה דרב שם ס\"ל לרבינו הרמב\"ם דהדר ביה שם בסוגיא ריש ד' נ\"א","ה) אוקימתא דגמרא שם","ו) בעיא שם ולא נפשטא ולטעמיה אזיל דבכל ספיקא דדינא ס\"ל אם תפס אין מוציאין מידו וכ\"כ הטור בשם הרמ\"ה","ז) שם במשנה","ח) שם דט\"ו וכתב ה\"ה פסק כר' יהודה (ברייתא שם דף ל' ע\"א) במה שאמר שבשעת הוצאות הזבלים מותר להוציא לר\"ה ופסק דלא כותיה בניזקין ואנו קי\"ל דחייב וכן כתב בהלכות","ט) הביאו הב\"י ס\"ס תי\"ד","\u0003י) מבואר שם בגמרא ע\"ב:\u0004 "],"t":["\u0003לשלם. \u0004 דכיון דממוניה הוא ה\"ל כמפקיר נזקיו אחר הנחתו במקום שלא היה לו רשות להניחו דחייב כמ\"ש בסימנים שלפני זה. סמ\"ע:","\u0003הזבל. \u0004 דאינו מזיק כל כך כמו קש שהוא מחליק וגם הוא ארוך ונופלים ע\"י בקל. שם:","\u0003ומתעכבין. \u0004 פירוש אלא נוזלין ויוצאין מעצמן מיד לאחר שפיכתן מאותו מקום ויתפזרו ואינן מזיקין. שם:","\u0003נשוף. \u0004 בש\"ס קאמר הטעם דע\"מ כן הנחיל יהושע את הארץ לישראל שלא יקפידו בזה זה על זה ועיין לעיל סימן רע\"ד בטור שכתב דהרי\"ף חולק ע\"ז. שם:","\u0003חייב. \u0004 דיהושע לא התנה שיהי' פטור מתשלומי היזקו ומ\"מ צריכין לתנאי דיהושע דאל\"כ היו מוחין דלא ניחא ליה לאדם להיות ניזוק בשלו וגם יצטרך אח\"כ לירד בדינא ודיינא להשתלם היזקו. שם:"],"r":["\u0003לא יוציא כו'. \u0004 אפילו לר' יהודה כמש\"ש רב אשי אמר כו':","\u0003ואם כו'. \u0004 מתני' שם וכרב דרבו של זעירי הוה ועוד דזעירי אתי כתנאי ודרב ככ\"ע וגם פשטא דמתני' כרב דבהן מ' בגופן. הרא\"ש:","\u0003מעת כו' ואם קדם כו'. \u0004 בעיא שם דלא איפשטא וכשיטתו:","\u0003מיהו י\"א כו'. \u0004 כרב הונא דקאי כת\"ק דרשב\"ג:","\u0003רק בשבח. \u0004 הג\"א. ברייתא שם אלא לאו ה\"ק וכל כו' ועתוס' ד\"ה לזעירי כו' אבל הרמב\"ם פ' כרב אדא משום דאתמר באחרונה כשיטתו אין הולכין בזה אחר פלוגתא דתנאי במקום דפליגי אמוראי בזה כמ\"ש בכמה מקומות ולח\"מ כ' דס\"ל כפי' ראשון של רש\"י במתני' ד\"ה כל המקלקלין כו' והלכה כרשב\"ג במתני' ע\"ש:","\u0003יש לכ\"א כו'. \u0004 כר\"י ועסי' רס\"ד ס\"ה בהג\"ה:","\u0003אבל שלא כו'. \u0004 שם אר\"נ מתני' שלא כו':","\u0003אבל מוציאו כו'. \u0004 עתוס' דב\"מ קיח ב' וי\"ל כו' ולהכי ל\"ק ליה כו':","\u0003וכ\"ש כו'. \u0004 למד מהנ\"ל:","\u0003אפילו בימות החמה. \u0004 דאסור בלא\"ה כמ\"ש בב\"ק שם חדא בימות כו' דתניא כו' בכה\"ג מותר כנ\"ל:","\u0003ואפילו מתקן כו'. \u0004 ממ\"ש בב\"ב נז א' ועשה מקום כו' הא פחות מכאן לא אלמא דא\"י למחות אע\"ג דשם נ\"ט א' אמרינן למעלה מד\"א כו' התם כדמפ' זמנין דמותבת כו' הלא\"ה אמרינן דכופין על כו'. שם:","\u0003ואעפ\"כ כו'. \u0004 ואף דגם בזה פליג ר\"י אין הלכה בזה כר\"י דבב\"מ שם אוקמיה בשיטה ואמרינן בב\"ק שם חדא כו' דתניא כו' וכן שם ו' א' אוקמוה מתני' שם כהאי ברייתא. הרא\"ש וש\"פ:","\u0003וי\"א כו'. \u0004 הג\"א שם:\n\u0003 (ליקוט) וי\"א דלאחר כו'. \u0004 ממש\"ש כ\"א א' לימא בבור כו' וערש\"י שם ד\"ה לימא כו' ואע\"ג דמסתמא ליכא שבחא בפירות אלא דמיירי בכה\"ג וז\"ש בבור כו' ובזה מתו' קושית תוס' שם בד\"ה דרב. והא דתנן כו' וק' לר\"י כו' (ע\"כ):\n\u0003 (ליקוט) וי\"א דלאחר כו'. \u0004 ממש\"ש וזעירי א\"ל אנא דאמרי כו' מ' דלאחר שהזיק ודאי דזכה לזעירי אף בדבר שאין בו שבח דהא לזעירי טעמא לאו משום שבחא דהא ס\"ל דלא קנסו גופן משום שבחן וכ\"ש לרב דהא רב פליג לחומרא ואף דגמ' קא' לזעירי דוקא אליבא דר\"מ הא קא' שם בגמ' דלרב ל\"פ רבנן עליה דר\"מ אלא קרן דבהתירא אבל הכא כו' (ע\"כ):"]}],["הַמַּצְנִיעַ אֶת הַקּוֹץ וְאֶת הַזְּכוּכִית, וְהַגּוֹדֵר גִּדְרוֹ בְּקוֹצִים \u0010y0\u0011 וְהִפְרִיחוּ לִרְשׁוּת הָרַבִּים וְהֻזַּק בָּהֶם אַחֵר, חַיָּב נֶזֶק שָׁלֵם. וְאִם גָּדַר בְּקוֹצִים \u0010y1\u0011 בְּצִמְצוּם בְּתוֹךְ רְשׁוּתוֹ, פָּטוּר, לְפִי \u0010y2\u0011 שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לְהִתְחַכֵּךְ בַּכְּתָלִים.\nהַמַּצְנִיעַ קוֹצָיו וּזְכוּכִיּוֹתָיו בְּתוֹךְ כָּתְלוֹ שֶׁל חֲבֵרוֹ, וּבָא בַּעַל הַכֹּתֶל וְסָתַר כָּתְלוֹ וְנָפַל לִרְשׁוּת הָרַבִּים וְהִזִּיק, אִם כֹּתֶל רָעוּעַ הוּא, הַמַּצְנִיעַ חַיָּב; וְאִם כֹּתֶל בָּרִיא הוּא, בַּעַל הַכֹּתֶל חַיָּב. \u0005הַגָּה: וְאִם הִזִּיקוּ בִּשְׁעַת נְפִילָה, \u0010y3\u0011 יֵשׁ אוֹמְרִים דְּבַעַל כֹּתֶל חַיָּב בְּכָל עִנְיָן (טוּר ס\"ב)\u0006. וְאִם נָפַל הַכֹּתֶל מֵאֵלָיו, אִם הָיָה בָרִיא פְּטוּרִים; וְאִם הָיָה רָעוּעַ, הַמַּצְנִיעַ חַיָּב. וְאִם סְתָרוֹ אִינַשׁ דְּעָלְמָא, הַסּוֹתֵר חַיָּב וְהַמַּצְנִיעַ פָּטוּר \u0005(נִמּוּקֵי יוֹסֵף פֶּרֶק הַמַּנִּיחַ)\u0006. וְעַיֵּן לְעֵיל סִימָן שצ\"ו. \u0010y4\u0011\nמִדַּת חֲסִידוּת הוּא שֶׁיַּצְנִיעַ אָדָם קוֹצָיו וּשְׁאָר כָּל דָּבָר הַמַּזִּיק בְּמָקוֹם שֶׁלֹּא יָבֹא מֵהֶם תַּקָּלָה, כְּגוֹן שֶׁיַּשְׁלִיכֵם לַנָּהָר אוֹ יִשְׂרְפֵם:",["\u0003והפריחו לר\"ה. \u0004 ל' הטור והוציאן לר\"ה אפי' מעט:","\u0003בצמצום בתוך רשותו \u0004 פי' שלא הוציאם כלל לר\"ה אפי' יצאו ובולטין מן הכותל כל שהן ברשותו:","\u0003שאין דרך בני אדם. \u0004 פי' ההולכים לר\"ה:","\u0003דבעל הכותל חייב בכל ענין. \u0004 פי' אפי' הכותל רעוע דכיון דסתרו \"בידים ה\"ל כאדם הנוטל זכוכיתו של חבירו ומזיק בו לאחר דמזיק חייב (מה\"ט נמי מסיק וכ' דאם סתרה אינש דעלמא הסותר חייב) ומה\"ט דוקא אם סתר הכותל בידים הא נפלה מאליו והיית' רעוע המצניע חייב וכדמסיק:","\u0003מדת חסידות כו'. \u0004 ועל כיוצא בזה אמרו בפרק המניח האי מאן דבעי למהוי חסידא לקיים מילי דניזקין וע\"ל ר\"ס שע\"ח כתבתי ל' הנ\"י בזה ועפ\"ר:"],[],"\u0010g0\u0011 הַמַּצְנִיעַ אֶת הַקּוֹץ וְאֶת הַזְּכוּכִית, וְהַגּוֹדֵר גִּדְרוֹ בְּקוֹצִים \u0010y0\u0011 \u0010g1\u0011 \u0010r0\u0011 וְהִפְרִיחוּ לִרְשׁוּת הָרַבִּים וְהֻזַּק בָּהֶם אַחֵר, חַיָּב נֶזֶק שָׁלֵם. וְאִם גָּדַר בְּקוֹצִים \u0010y1\u0011 בְּצִמְצוּם בְּתוֹךְ רְשׁוּתוֹ, פָּטוּר, \u0010g2\u0011 לְפִי \u0010y2\u0011 שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לְהִתְחַכֵּךְ \u0010g3\u0011 בַּכְּתָלִים.\nהַמַּצְנִיעַ קוֹצָיו וּזְכוּכִיּוֹתָיו בְּתוֹךְ כָּתְלוֹ שֶׁל חֲבֵרוֹ, וּבָא בַּעַל הַכֹּתֶל וְסָתַר כָּתְלוֹ וְנָפַל לִרְשׁוּת הָרַבִּים וְהִזִּיק, \u0010g4\u0011 אִם כֹּתֶל רָעוּעַ הוּא, הַמַּצְנִיעַ חַיָּב; וְאִם כֹּתֶל בָּרִיא הוּא, בַּעַל \u0010g5\u0011 הַכֹּתֶל חַיָּב. \u0005הַגָּה: \u0010r1\u0011 וְאִם הִזִּיקוּ בִּשְׁעַת נְפִילָה, \u0010y3\u0011 יֵשׁ אוֹמְרִים דְּבַעַל \u0010t0\u0011 כֹּתֶל חַיָּב בְּכָל \u0010g6\u0011 עִנְיָן (טוּר ס\"ב)\u0006. \u0010r2\u0011 וְאִם נָפַל הַכֹּתֶל מֵאֵלָיו, אִם הָיָה בָרִיא פְּטוּרִים; וְאִם הָיָה רָעוּעַ, הַמַּצְנִיעַ \u0010r3\u0011 חַיָּב. וְאִם סְתָרוֹ אִינַשׁ דְּעָלְמָא, הַסּוֹתֵר חַיָּב וְהַמַּצְנִיעַ פָּטוּר \u0005(נִמּוּקֵי יוֹסֵף פֶּרֶק הַמַּנִּיחַ)\u0006. וְעַיֵּן לְעֵיל סִימָן שצ\"ו. \u0010y4\u0011 \u0010g7\u0011\nמִדַּת \u0010t1\u0011 חֲסִידוּת הוּא שֶׁיַּצְנִיעַ אָדָם קוֹצָיו וּשְׁאָר כָּל דָּבָר הַמַּזִּיק בְּמָקוֹם שֶׁלֹּא יָבֹא מֵהֶם תַּקָּלָה, כְּגוֹן \u0010g8\u0011 שֶׁיַּשְׁלִיכֵם לַנָּהָר אוֹ \u0010g9\u0011 יִשְׂרְפֵם:",{"g":["א) לשון הרמב\"ם בפר' י\"ג מה' נזקי ממון דין כ' משנה בפ\"ג דב\"ק דף ל' ע\"א במימרא דרבי יוחנן שם","\u0003ב) פי' הפריח שהוציא חוץ מרשותו ה\"ה:\u0004 ","\u0003ג) מימרא דרב אחא בר איקא שם:\u0004 ","ד) שם דף כ\"א ברייתא שם","ה) מימרא דר' יוחנן שם","ו) פירש\"י דה\"ל לאצנועינהו","ז) בב\"י לא ביאר מוצא דין זה והרב ב\"ח כ' שלמדו מדברי הרא\"ש שם ולפי עניות דעתי המעיין בדברי הרא\"ש יראה בבירו' שהוא בהיפך שהוא מחייב המצניע בכותל רעוע ולא בעל הכותל שסתרו אבל ראיתי בנ\"י שכ' ג\"כ דבכותל רעוע חייב בעל הכותל שסתרו והביא ראיה דלא גרע מהיתה אבן בחיקו אף ע\"ג דלא הכיר בה מעולם ומבואר בסימן תכ\"א ס\"י ומה שהשמיטו המחבר נלענ\"ד משום דלא דמיא להדדי דהתם ליכא למשתלם מאינש אחרינא אבל הכא דאיכא המצניע משתלם מהמצניע ור' נתן מבואר בסי' ת\"י סי' נ\"ב וכפשטא דגמרא שם","ח) ל' הטור ס\"ג וכ\"כ הרמב\"ם שם דף כ\"ב ברייתא שם","ט) כדעבד רבא שם","\u0003י) כדעבד רב ששת שם:\u0004 "],"t":["\u0003בכל ענין. \u0004 פי' אפילו הכותל רעוע דכיון דסתרו בידים ה\"ל כאדם הנוטל זכוכיתו של חבירו ומזיק בו לאחר דחייב המזיק וה\"ט דמסיק הרמ\"א בנפל הכותל מאליו ובסתרו אינש דעלמא כו'. סמ\"ע:","\u0003חסידות. \u0004 ועל כיוצא בזה אמרו בפרק המניח האי מאן דבעי למהוי חסידא ליקיים מילי דנזיקין וע\"ל ר\"ס שע\"ח. שם:"],"r":["\u0003והפריחו כו'. \u0004 עתוס' כ\"ט ב' ד\"ה אלא ר\"י כו' ועסי' ת\"י ס\"ו:","\u0003ואם הזיקו בשעת כו'. \u0004 טור וכ\"כ נ\"י דלא גרע ממש\"ש כ\"ו ב' היתה אבן מונחת כו' ולא הכיר בה דחייב בנזקין ור\"ל דבשעת נפילה ה\"ל מזיק בידים וחייב על השוגג ואונס כמש\"ש אבל לאחר נפילה הוי מטעם בור כמו אבנו סכינו ומשאו כו' דאינו חייב אלא ברוח מצויה אם אפקרינהו וכמ\"ש בסי' תי\"א ס\"ב ע\"ש וה\"נ במצניע בכותל בריא ובבעל הכותל בכותל רעוע דפטורים ועבנ\"י וברא\"ש שם:\n\u0003 (ליקוט) ואם הזיקו כו'. \u0004 טור ודייק מדברי הרא\"ש שם שכ' ול\"ד למוצא כו' כמו אבנו כו' לאחר נפילה דייק דוקא לאחר נפילה (ע\"כ):","\u0003ואם נפלה כו'. \u0004 דכאן א\"א לחיוביה לבעל הכותל וכמו בכותל ואילן שנפלו לרה\"ר בר\"ס תי\"ו:","\u0003ואם סתרה כו'. \u0004 ר\"ל אפילו ברעוע דכיון שלא ברשות עבד הוי מפקיר נזקיו לאחר פשיעה ואין המכניע חייב אלא הוא דהוי כורה אחר כורה ועסי' ת\"י סט\"ו:"]}],["הַכֹּתֶל וְהָאִילָן שֶׁנָּפְלוּ לִרְשׁוּת הָרַבִּים וְהִזִּיקוּ, פָּטוּר מִלְּשַׁלֵּם, \u0010y0\u0011 וְאַף עַל פִּי שֶׁהִפְקִירָם; לְפִי שֶׁאֵינָם דּוֹמִים לְבוֹר, שֶׁהֲרֵי אֵין תְּחִלָּתָן לְהַזִּיק. \u0005וְיֵשׁ אוֹמְרִים דְּאִם הָיָה לוֹ פְּנַאי לְסַלְּקָן וְלֹא הִפְקִירָן, חַיָּב (טוּר ס\"א)\u0006. וְאִם הָיוּ רְעוּעִין, בֵּית דִּין קוֹבְעִים לוֹ זְמַן \u0005וְדַוְקָא שֶׁהִתְרוּ בוֹ בֵּית דִּין, אֲבָל בְּלֹא בֵּית דִּין אַף עַל פִּי שֶׁהִתְרוּ בּוֹ חֲבֵרָיו אֵינוֹ כְּלוּם; מִיהוּ, אִם חָפַר בַּכֹּתֶל וְגָרַם לְהַפִּילוֹ, חַיָּב בְּנִזָּקִין דְּהָוָה לֵהּ חִצָּיו מַמָּשׁ (בֵּית יוֹסֵף בְּשֵׁם רַשְׁבָּ\"א)\u0006, לָקֹץ אֶת הָאִילָן וְלִסְתֹּר אֶת הַכֹּתֶל. וְכַמָּה הַזְּמָן, ל' יוֹם. \u0005וְאִם הַדָּבָר נָחוּץ וְיֵשׁ לָחוּשׁ שֶׁיַּזִּיק לַאֲחֵרִים, אֵין נוֹתְנִין לוֹ זְמַן רַק כּוֹפִין אוֹתוֹ לְסַלֵּק הֶזֵּיקוֹ מִיָּד (בֵּית יוֹסֵף בְּשֵׁם רִיטְבָ\"א)\u0006. נָפְלוּ בְּתוֹךְ הַזְּמַן, פָּטוּר; \u0010y1\u0011 לְאַחַר הַזְּמַן חַיָּב, מִפְּנֵי שֶׁהִשְׁהָה אוֹתָם. \u0005הַגָּה: וְכָל זֶה כְּשֶׁבְּנָאָהּ מִתְּחִלָּתוֹ כָּרָאוּי, אֲבָל אִם לֹא בְנָאָהּ כָּרָאוּי וּמֵחֲמַת זֶה נָפַל הַכֹּתֶל, חַיָּב בְּנִזְקָה (תוס' הַמַּגִּיד פי\"ג דְּנִזְקֵי מָמוֹן וּבֵית יוֹסֵף בְּשֵׁם רַבֵּנוּ יְרוּחָם נל\"א ח\"א)\u0006.",["\u0003ואע\"פ שהפקירם. \u0004 לכאורה היה נראה להגיה שלא הפקירם דכיון שאין מונחין בר\"ה והן שלו עדיין שלא הפקירן והזיקו יש סברא להשתלם ממנו טפימשהפקירן והזיקו וכמ\"ש מור\"ם ג\"כ בהג\"ה ע\"ז ז\"ל ולא הפקירן חייב ולפי הגירסא שלפנינו צריך לומר דה\"ק אע\"פ שהפקירן ויש רשות לכל אדם לעבור דרך עליו ויזוקו בו אפ\"ה פטור מטעם שהרי כו':","\u0003לאחר הזמן חייב. \u0004 לשון הטור לאחר הזמן והזיקו בין בשעת נפילה בין לאחר נפילה יש להן דין בור כו' וכ\"כ הרא\"ש וכתב עוד הרא\"ש ז\"ל ול\"ד לאבנו סכינו ומשאו שהניחו בראש גגו ונפלו ברוח מצויה והזיקו בשעת נפילה דיש להן דין אש דהנך נעשו אש ע\"י כח אחרים (דהיינו ברוח שהפילם) אבל כותל ואילן מחמת עצמן מריעותא נפלו כי ראו שלא היו יכולין לעמוד יותר והזהירו ב\"ד עליהן להפילן ואי משום דהולכים ומזיקין ואינו דומה לבור לא גריע מחמת זה וכ\"ש דיש לחייבו יותר מידי דהוי אקושר אבן ברגל בהמתו והלכה לר\"ה והזיקו ואי משום דאין תחלת עשייתן להזיק שור יוכיח עכ\"ל הרא\"ש שם:"],[],"\u0010g0\u0011 הַכֹּתֶל וְהָאִילָן שֶׁנָּפְלוּ לִרְשׁוּת הָרַבִּים וְהִזִּיקוּ, פָּטוּר מִלְּשַׁלֵּם, \u0010y0\u0011 וְאַף עַל פִּי שֶׁהִפְקִירָם; לְפִי שֶׁאֵינָם דּוֹמִים לְבוֹר, שֶׁהֲרֵי אֵין תְּחִלָּתָן לְהַזִּיק. \u0010r0\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּאִם הָיָה לוֹ פְּנַאי לְסַלְּקָן וְלֹא הִפְקִירָן, \u0010g1\u0011 חַיָּב (טוּר ס\"א)\u0006. וְאִם הָיוּ רְעוּעִין, בֵּית דִּין קוֹבְעִים לוֹ זְמַן \u0010r1\u0011 \u0005וְדַוְקָא שֶׁהִתְרוּ בוֹ בֵּית דִּין, אֲבָל בְּלֹא בֵּית דִּין אַף עַל פִּי שֶׁהִתְרוּ בּוֹ חֲבֵרָיו אֵינוֹ כְּלוּם; \u0010r2\u0011 מִיהוּ, אִם חָפַר בַּכֹּתֶל וְגָרַם לְהַפִּילוֹ, חַיָּב בְּנִזָּקִין דְּהָוָה לֵהּ חִצָּיו מַמָּשׁ (בֵּית יוֹסֵף בְּשֵׁם רַשְׁבָּ\"א)\u0006, לָקֹץ אֶת הָאִילָן וְלִסְתֹּר אֶת \u0010g2\u0011 הַכֹּתֶל. וְכַמָּה הַזְּמָן, ל' יוֹם. \u0010r3\u0011 \u0005וְאִם הַדָּבָר נָחוּץ וְיֵשׁ לָחוּשׁ שֶׁיַּזִּיק לַאֲחֵרִים, אֵין נוֹתְנִין לוֹ זְמַן רַק כּוֹפִין אוֹתוֹ לְסַלֵּק הֶזֵּיקוֹ מִיָּד (בֵּית יוֹסֵף בְּשֵׁם רִיטְבָ\"א)\u0006. \u0010g3\u0011 נָפְלוּ בְּתוֹךְ הַזְּמַן, פָּטוּר; \u0010y1\u0011 לְאַחַר \u0010t0\u0011 הַזְּמַן חַיָּב, מִפְּנֵי שֶׁהִשְׁהָה אוֹתָם. \u0005הַגָּה: \u0010r4\u0011 וְכָל זֶה כְּשֶׁבְּנָאָהּ מִתְּחִלָּתוֹ כָּרָאוּי, אֲבָל אִם לֹא בְנָאָהּ כָּרָאוּי וּמֵחֲמַת זֶה נָפַל הַכֹּתֶל, חַיָּב בְּנִזְקָה (תוס' \u0010g4\u0011 הַמַּגִּיד פי\"ג דְּנִזְקֵי מָמוֹן וּבֵית יוֹסֵף בְּשֵׁם רַבֵּנוּ יְרוּחָם נל\"א ח\"א)\u0006.",{"g":["א) לשון הרמב\"ם בפר' י\"ג מהכ\"מ דף י\"ט משנה פ\"ו דב\"מ דף קיז ע\"ב והובא' בפ\"ק דב\"ק דף ו' ע\"ב וכתב ה\"ה ודברי רבינו הם כשהזיקו בשעת נפילה ולפיכך פטור אע\"פ שהפקירן וכו' וכן מוכח שם (בפ\"ק דב\"ק) מפני הטענה שכתב רבינו ז\"ל ול' אף ע\"פ שהפקירם הוא קשה להולמו (פי' ליישבו) שהרי יותר יש לחייבו כשלא הפקירם ע\"כ ומ\"ש הסמ\"ע שהיה נראה להגיה ואף על פי שלא הפקירם לא יתכן ג\"כ שהרי פי' ה\"ה דהרמב\"ם איירי כשהזיק בשעת נפילה ואז לא שייך לומר הפקירם או לא הפקירם גם הפי' שכתב לפי הנוסח שלפנינו ואע\"פ שהפקירם הוא דוחק ואומר אני לענ\"ד שטעות נפל בהעתק' ואלו ב' תיבות מתחנה הושמטו ואח\"כ הועמדו מן הצד והמעתיק העמידם שלא במקומם וצריך להסירם מפה ולהעמידם בסוף הסעיף וצ\"ל מפני שהשהה אותם אע\"פ שהפקירם ע\"כ ואת' לאשמועינן אע\"ג דקיימא לן המפקיר נזקיו לאחר נטילת אונס פטור הכא חייב כיון שעבר על זמן ב\"ד וזה נלע\"ד הוא ברור ואמת לאמתו מ\"מ לא שלחתי ידי להגיה כן כיון שהוא כן בכל הספרים אבל בטוח אני בכל מעיין שיאמר שהג\"ה זו היא כפתור ופרח","ב) וכ\"כ ה\"ה שם לדעת הרמב\"ם ומבואר במ\"ש לעיל תי\"ב","ג) מימרא דר' יוחנן שם דף קי\"ח ע\"א וכתבו התוס' שם ☜ולשאר נזיקים שבשעה קלה יכול להסיר משם אין נותנים לו זמן ב\"ד כדאמרינן גבי נשברה כדו (ומבואר לעיל סי' תי\"ב)","ד) שם במשנה","ה) בשם הרשב\"א ושהכי איתא בתוספתא מבואר שם ☜שנפלה מחמת רוחות וזיעות וגשמים וכן הוא בתו' הנזכר לעיל:"],"t":["\u0003הזמן. \u0004 לשון הטור לאחר הזמן והזיקו בין בשעת נפילה בין לאחר נפילה יש להן דין בור כו' וכן כתב הרא\"ש וכת' עוד ז\"ל ול\"ד לאבנו וסכינו ומשאו שהניחן בראש גגו ונפלו ברוח מצויה והזיקו בשעת נפילה דיש להן דין אש דהנך נעשו אש על ידי כח אחרים \u0005(דהיינו ברוח שהפילן)\u0006 אבל כותל ואילן מחמת עצמן מריעותן נפלו כי ראו שלא היו יכולין לעמוד יותר והזהירו ב\"ד עליהן להפילן ולא משום דהולכין ומזיקין ואינו דומה לבור לא גריע מחמת זה וכ\"ש דיש לחייבו יותר מידי דהוי אקושר אבן ברגל בהמתו והלכה לר\"ה והזיקה ואי משום דאין תחלת עשייתן להזיק שור יוכיח עד כאן לשון הרא\"ש. סמ\"ע:"],"r":["\u0003וי\"א כו'. \u0004 עתוס' שם ד\"ה' היינו כו' ורא\"ש שם וכמ\"ש בסי' תי\"א ס\"ב וסי' תי\"ב ס\"ד:\n\u0003 (ליקוט) וי\"א דאם כו'. \u0004 עתוס' שם ד\"ה היינו כו' ונראה כו' וכגון שלא כו' והרשב\"א והרא\"ש כ' דאפילו אם י\"ל פנאי אלא שהפקירן וגם תוס' ס\"ל כן ועתוס' שם ד\"ה אי כו' משא\"כ בתוך הזמן אלא משום דגמ' סבור לאוקמי בלא הפקירן כמש\"ש ואי דלא אפקרינהו ול\"ק להו אלא לשמואל כו' והכלל דבד' אופנים פטור בשעת נפילה או לאחר נפילה וכשלא נודע או לא ה\"ל פנאי או שהפקירן ולאחר זמן חייב בכולם שלא נודע או לא ה\"ל פנאי דהן כשעת נפילה ואפילו בשעת נפילה חייב ובשהפקירן חייב כמש\"ש בתוס' ד\"ה אי כו' ובשעת נפילה חייב כמ\"ש בתוס' ד\"ה היינו. ועתוס' ך\"ג א' ד\"ה פליגי כו' (ע\"כ):","\u0003ודוקא כו'. \u0004 מדקא' בב\"מ שם וכמה זמן ב\"ד כו' אלמא דבב\"ד תליא:","\u0003מיהו כו'. \u0004 כמ\"ש מודה ר\"י בגירי דיליה:","\u0003ואם הדבר כו'. \u0004 עתוס' בב\"מ שם ד\"ה זמן כו' וכ\"כ הריטב\"א:","\u0003וכ\"ז כשבנאה כו'. \u0004 ירושלמי דב\"ק ר\"פ הכונס ותוספתא דב\"מ שם נפל הכותל מחמת הזועות ומחמת הרוח ומחמת הגשמים אם בנאו כדרכו פטור א\"ל חייב נתנו לו זמן נפל בתוך זמן פטור לאחר זמן חייב וקאי ארישא:"]}],["לֹא יְסַקֵּל אָדָם מֵרְשׁוּתוֹ לִרְשׁוּת הָרַבִּים. וְאֵין עוֹשִׂין חָלָל \u0010y0\u0011 תַּחַת רְשׁוּת הָרַבִּים, וְלֹא בּוֹרוֹת וְלֹא שִׁיחִין וְלֹא מְעָרוֹת, וְאַף עַל פִּי שֶׁהָעֲגָלָה יְכוֹלָה לְהַלֵּךְ עַל גַּבֵּיהֶן וְהִיא טְעוּנָה אֲבָנִים, \u0010y1\u0011 שֶׁמָּא תִפָּתַח מִלְּמַטָּה שֶׁלֹּא מִדַּעְתּוֹ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאַף עַל גַּב דְּהָכִי דִינָא הוּא, מִכָּל מָקוֹם כְּבָר נָהֲגוּ לַעֲשׂוֹת בִּיבִין וּמַרְתְּפוֹת תַּחַת חֲלַל רְשׁוּת הָרַבִּים, וְכֵן זִיזִין, \u0010y2\u0011 וְכֻלָּן מוֹחֲלִין עַל כָּךְ מֵאַחַר שֶׁכֵּן נָהֲגוּ. וְעוֹד, שֶׁרְשׁוּיוֹת הָרַבִּים הֵם \u0010y3\u0011 שֶׁל מוֹשְׁלֵי הָעִיר, וּלְכָל מַה שֶּׁנּוֹתְנִין רְשׁוּת אָזְלֵינָן בַּתְרֵהּ וּלְפִי עִנְיָן הַמִּנְהָג (בֵּית יוֹסֵף בְּשֵׁם רַשְׁבָּ\"א)\u0006. וְהַחוֹפֵר בּוֹר לְצָרְכֵי רַבִּים, \u0010y4\u0011 \u0010c0\u0011 מֻתָּר:\nאֵין מוֹצִיאִין זִיזִין וּגְזֻזְטְרָאוֹת לִרְשׁוּת הָרַבִּים, אֶלָּא אִם כֵּן הָיוּ לְמַעְלָה מִגָּמָל וְרוֹכְבוֹ, וְהוּא שֶׁלֹּא יַאֲפִיל הַדֶּרֶךְ עַל גַּבֵּי רְשׁוּת הָרַבִּים. וְאִם רָצָה, כּוֹנֵס לְתוֹךְ שֶׁלּוֹ וּמוֹצִיאוֹ. כָּנַס וְלֹא הוֹצִיא, הֲרֵי זֶה מוֹצִיא כָּל זְמַן שֶׁיִּרְצֶה, אֲבָל אֵינוֹ יָכוֹל לְהַחֲזִיר הַכְּתָלִים לִמְקוֹמָם לְעוֹלָם, שֶׁכָּל מֶצֶר שֶׁהֶחֱזִיקוּ בּוֹ רַבִּים אָסוּר לְקַלְקְלוֹ. \u0005הַגָּה: וְדַוְקָא בְּמָקוֹם שֶׁרַבִּים דּוֹרְסִים בּוֹ, אֲבָל אִם אֵין דּוֹרְסִים שָׁם, כְּגוֹן שֶׁבָּנָה שָׁם אִצְטַבָּא, אַף עַל גַּב דְּרַבִּים מַעֲבִירִים שָׁם מַשָּׂאָם, יָכוֹל לְהַחֲזִיר הַכֹּתֶל לִמְקוֹמוֹ (בֵּית יוֹסֵף בְּשֵׁם רַבֵּנוּ יְרוּחָם)\u0006.\nלָקַח חָצֵר וּבָהּ זִיזִין וּגְזֻזְטְרָאוֹת יוֹצְאוֹת \u0010y5\u0011 לִרְשׁוּת הָרַבִּים, הֲרֵי זוֹ בְּחֶזְקָתָהּ, וְאִם נָפְלָה, חוֹזֵר וּבוֹנֶה אוֹתָהּ כְּשֶׁהָיְתָה.\nאִילָן שֶׁהוּא נוֹטֶה לִרְשׁוּת הָרַבִּים, קוֹצֵץ, כְּדֵי שֶׁיְּהֵא הַגָּמָל עוֹבֵר בְּרוֹכְבוֹ. וּמַנִּיחִים מָקוֹם פָּנוּי מִשְׁתֵּי שִׂפְתוֹת הַנָּהָר כְּרֹחַב כִּתְפֵי הַמַּלָחִים שֶׁיּוֹרְדִים שָׁם וּמוֹשְׁכִים הַסְפִינָה, וְכָל אִילָן הַנִּמְצָא בְּרֹחַב זֶה קוֹצְצִין אוֹתוֹ מִיָּד וְאֵין מַתְרִין בַּבְּעָלִים, שֶׁהֲרֵי מְעַכֵּב מוֹשְׁכֵי הַסְפִינָה.\nאֵין שׁוֹרִין טִיט בִּרְשׁוּת הָרַבִּים לְהַשְׁהוֹתוֹ זְמַן רַב, וְאֵין לוֹבְנִים בּוֹ לְבֵנִים; אֲבָל גּוֹבְלִים שָׁם טִיט לְצֹרֶךְ בִּנְיָן, אֲבָל לֹא לַעֲשׂוֹת לְבֵנִים.\nהַבּוֹנֶה בִּרְשׁוּת הָרַבִּים, כְּשֶׁמֵּכִין הָאֲבָנִים צָרִיךְ שֶׁלֹּא יַשְׁהֵם שָׁם, אֶלָּא מֵבִיא וּבוֹנֶה מִיָּד.\nוְכֻלָּם שֶׁהִזִּיקוּ, חַיָּבִים לְשַׁלֵּם נֶזֶק שָׁלֵם.",["\u0003תחת רשות הרבים ולא בורות שיחין כו' \u0004 וכן הוא ל' הרמב\"ם והטור דכתבו \"ולא בורות כו' בוי\"ו ומשמע דתרתי דברים נינהו חלל ובורות ואפשר משום דבורות מיירי שהן מגולין ועומדין וכן אינך שיכולין בני ר\"ה ליזהר מהן ואפ\"ה אסור אבל במשנה קתני לא בורות בלא וי\"ו ופי' רשב\"ם שם דחדא הוא דקתני חלל והדר מפרש דהיינו בורות שיחין כו' וכן משמע מדמסיק ותני עלייהו אף ע\"פ שהעגלה יכולה לילך ע\"ג כו' מוכח דמבוסות הן ועפ\"ר:","\u0003שמא תפחת מלמט' שלא מדעתו \u0004 ולא סגי במה שמקבל עליו אחריות היזקן דהעוברים עליו דניחא לבני אדם בשלהן ולא שיזיקו בשלהן ולקבל עליו תשלומין וחילופיהן וגם לא ניחא להו לירד בדינא ודיינא וכמ\"ש לעיל:","\u0003וכולן מוחלין על כך \u0004 שהיום או מחר יצטרך גם הוא או בניו לעשות כן:","\u0003של מושלי העיר \u0004 פי' של שר העיר ז\"ל הרשב\"א שהדבר ידוע שהדרכים עם היותם מסורים לרבים של אדוני הארץ הם והם רשאים לסתום דרכים ולפתחן במקום אחר לפי שהדרכי' שלהם הן והרי זה ככונס לתוך שלו על דעת שיוציא זיזין ומחילות לכשירצה עכ\"ל ועד\"מ:","\u0003אין מוציאין זיזין כו' לר\"ה \u0004 ל' הטור אבל במבוי יכול להוציאן מדע' בני המבוי משא\"כ בר\"ה שאין לו בעלים וכתב ר\"י דהאי מבוי ר\"ל שאיני מפולש דאם הוא מפולש שרבים עוברים שם דינו כר\"ה הביאו הב\"י ומהתימה למה השמיטו המחבר:","\u0003ה\"ז בחזקתו דטוענין ללוקח ואמרינן דשמא המוכר לו או אבותיו כונס לתוך שלו היה וכנ\"ל:\u0004"],["\u0003 אין מוציאין זיזין כו'. \u0004 עיין בתשובות מהרי\"ט סימן ק\"ח:"],"\u0010g0\u0011 לֹא \u0010g1\u0011 יְסַקֵּל אָדָם מֵרְשׁוּתוֹ \u0010g2\u0011 לִרְשׁוּת הָרַבִּים. וְאֵין עוֹשִׂין חָלָל \u0010y0\u0011 תַּחַת רְשׁוּת הָרַבִּים, וְלֹא בּוֹרוֹת וְלֹא שִׁיחִין וְלֹא מְעָרוֹת, \u0010g3\u0011 וְאַף עַל פִּי שֶׁהָעֲגָלָה יְכוֹלָה לְהַלֵּךְ עַל גַּבֵּיהֶן וְהִיא טְעוּנָה אֲבָנִים, \u0010y1\u0011 \u0010g4\u0011 שֶׁמָּא \u0010t0\u0011 תִפָּתַח מִלְּמַטָּה שֶׁלֹּא מִדַּעְתּוֹ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאַף עַל גַּב דְּהָכִי דִינָא הוּא, מִכָּל מָקוֹם כְּבָר נָהֲגוּ לַעֲשׂוֹת בִּיבִין וּמַרְתְּפוֹת תַּחַת חֲלַל רְשׁוּת הָרַבִּים, וְכֵן זִיזִין, \u0010y2\u0011 \u0010r0\u0011 וְכֻלָּן מוֹחֲלִין עַל כָּךְ מֵאַחַר שֶׁכֵּן נָהֲגוּ. \u0010r1\u0011 וְעוֹד, שֶׁרְשׁוּיוֹת הָרַבִּים הֵם \u0010y3\u0011 שֶׁל מוֹשְׁלֵי הָעִיר, וּלְכָל מַה שֶּׁנּוֹתְנִין רְשׁוּת אָזְלֵינָן בַּתְרֵהּ וּלְפִי עִנְיָן הַמִּנְהָג (בֵּית יוֹסֵף בְּשֵׁם רַשְׁבָּ\"א)\u0006. \u0010r2\u0011 וְהַחוֹפֵר בּוֹר לְצָרְכֵי רַבִּים, \u0010y4\u0011 \u0010c0\u0011 \u0010g5\u0011 מֻתָּר:\nאֵין מוֹצִיאִין זִיזִין \u0010g6\u0011 \u0010t1\u0011 וּגְזֻזְטְרָאוֹת לִרְשׁוּת הָרַבִּים, אֶלָּא אִם כֵּן הָיוּ לְמַעְלָה מִגָּמָל וְרוֹכְבוֹ, \u0010g7\u0011 וְהוּא שֶׁלֹּא יַאֲפִיל הַדֶּרֶךְ עַל גַּבֵּי \u0010g8\u0011 רְשׁוּת הָרַבִּים. וְאִם רָצָה, כּוֹנֵס לְתוֹךְ שֶׁלּוֹ וּמוֹצִיאוֹ. \u0010g9\u0011 כָּנַס וְלֹא הוֹצִיא, הֲרֵי זֶה מוֹצִיא כָּל זְמַן שֶׁיִּרְצֶה, \u0010g10\u0011 אֲבָל אֵינוֹ יָכוֹל לְהַחֲזִיר הַכְּתָלִים לִמְקוֹמָם לְעוֹלָם, שֶׁכָּל מֶצֶר שֶׁהֶחֱזִיקוּ בּוֹ רַבִּים אָסוּר לְקַלְקְלוֹ. \u0005הַגָּה: וְדַוְקָא בְּמָקוֹם שֶׁרַבִּים דּוֹרְסִים בּוֹ, אֲבָל אִם אֵין דּוֹרְסִים שָׁם, כְּגוֹן שֶׁבָּנָה שָׁם אִצְטַבָּא, אַף עַל גַּב דְּרַבִּים מַעֲבִירִים שָׁם מַשָּׂאָם, יָכוֹל לְהַחֲזִיר הַכֹּתֶל לִמְקוֹמוֹ (בֵּית יוֹסֵף בְּשֵׁם רַבֵּנוּ יְרוּחָם)\u0006. \u0010g11\u0011\nלָקַח חָצֵר וּבָהּ זִיזִין וּגְזֻזְטְרָאוֹת יוֹצְאוֹת \u0010y5\u0011 \u0010t2\u0011 לִרְשׁוּת הָרַבִּים, הֲרֵי זוֹ בְּחֶזְקָתָהּ, \u0010g12\u0011 וְאִם נָפְלָה, חוֹזֵר וּבוֹנֶה אוֹתָהּ כְּשֶׁהָיְתָה. \u0010g13\u0011\nאִילָן שֶׁהוּא נוֹטֶה לִרְשׁוּת הָרַבִּים, קוֹצֵץ, כְּדֵי שֶׁיְּהֵא הַגָּמָל עוֹבֵר בְּרוֹכְבוֹ. \u0010g14\u0011 וּמַנִּיחִים מָקוֹם פָּנוּי מִשְׁתֵּי שִׂפְתוֹת הַנָּהָר כְּרֹחַב כִּתְפֵי הַמַּלָחִים שֶׁיּוֹרְדִים שָׁם וּמוֹשְׁכִים הַסְפִינָה, וְכָל אִילָן הַנִּמְצָא בְּרֹחַב זֶה \u0010g15\u0011 קוֹצְצִין אוֹתוֹ מִיָּד וְאֵין מַתְרִין בַּבְּעָלִים, שֶׁהֲרֵי מְעַכֵּב מוֹשְׁכֵי הַסְפִינָה. \u0010g16\u0011\nאֵין שׁוֹרִין טִיט בִּרְשׁוּת הָרַבִּים לְהַשְׁהוֹתוֹ זְמַן רַב, וְאֵין לוֹבְנִים בּוֹ לְבֵנִים; אֲבָל גּוֹבְלִים שָׁם טִיט לְצֹרֶךְ בִּנְיָן, אֲבָל לֹא לַעֲשׂוֹת לְבֵנִים. \u0010g17\u0011\nהַבּוֹנֶה בִּרְשׁוּת הָרַבִּים, כְּשֶׁמֵּכִין הָאֲבָנִים צָרִיךְ שֶׁלֹּא יַשְׁהֵם שָׁם, אֶלָּא מֵבִיא וּבוֹנֶה מִיָּד. \u0010g18\u0011\nוְכֻלָּם שֶׁהִזִּיקוּ, חַיָּבִים לְשַׁלֵּם נֶזֶק שָׁלֵם.",{"g":["א) לשון הרמב\"ם בפי\"ג מהל' נזקי ממון דכ\"ג וכתב ה\"ה ברייתא פ\"ה דב\"ק (דף נ' ע\"ב) ☜","פירוש לא יזרוק אבנים","ב) משנה פ\"ג דב\"ב דף כ' ע\"א ופסק כחכמים שם","ג) וכתב ה\"ה ודע שאע\"פ שאינו רשאי לעשות כן לכתחלה אם עשה וכסה כראוי פטור דהיינו במקום שהשוורים מצויים לעמוד בפני השוורים ובמקום שהגמלים מצוים כראוי לגמלים ובירוש' איתא במקום שהעגלות מצוים כראוי לעגלה מהלכת טעינה אבנים והכל כלל רבי' בפי\"ב במלת כראוי:","ד) שם בגמרא","ה) שם דף כ\"ד שם במשכ'","ו) כתב ה\"ה היא סברא כתובה בהלכות (וכ\"כ הרא\"ש ולמדוהו מדין אילן שהוא נוטה כמו שנתבאר (בסמוך ס\"ד):","ז) שם ברמב\"ם וכ\"כ הרשב\"א בתשוב' ועיין בהג\"ה דסעיף דלעיל","ח) שם במשנ'","ט) שם בגמרא ע\"ב אליבא דר' יעקב כ\"ע לא פליגי דמוציא","י) פסק כר' יוחנן שם","כ) שם דכ\"ה ושם במשנה","ל) מימרא דרב הונא שם ע\"ב","מ) שם דכ\"ו משנה פ\"ג דבבא בתרא דף כ\"ז ע\"ב","\u0003נ) מהא דמכריז רבי אמי מלא כתפי נגדא וכו'\u0004 בפרק ט' דבבא מציעא דף ק\"ז ע\"ב:","\u0003ס) מעובדא דרבה בר רב נחמן וכו'\u0004 א\"ל קוצו קוצו שם ריש דף ק\"ח","ע) ל' הטור סי\"א וכ\"כ הרמב\"ם שם דין י\"ו משנה שם פ\"י דף קי\"ח ע\"ב","פ) שם ושם במשנה","\u0003צ) שם ושם במשנה:\u0004 "],"t":["\u0003תפחת. \u0004 ולא סגי במה שמקבל עליו אחריות היזקן דהעוברים עליו דניחא לבני אדם בשלהן וגם לא ניחא להו לירד בדינא ודיינא וכמ\"ש לעיל. סמ\"ע:","\u0003לר\"ה. \u0004 לשון הטור אבל במבוי יכול להוציאן מדעת בני המבוי משא\"כ בר\"ה שאין לו בעלים וכת' ר' ירוחם והאי מבוי ר\"ל שאינו מפולש דאם הוא מפולש שרבים עוברים שם דינו כר\"ה והביאו הב\"י ומהתימא שהשמיטו המחבר עכ\"ל הסמ\"ע ועיין בתשו' מהרי\"ט סי' ק\"ח:","\u0003בחזקתה. \u0004 דטוענין ללוקח ואומרים דשמא המוכר לו או אבותיו כונס לתוך שלו היה כמ\"ש בס\"ב. שם:"],"r":["\u0003וכולן מוחלין כו'. \u0004 אע\"ג דשתיקת רבים לא הוי מחילה וכמש\"ש לרה\"ר מפיק מאן מחיל גבך מ\"מ מחילה בפירוש מזט\"ה במא\"ה מועיל כמש\"ש כג א'. א\"נ אחולי אחיל כו' ועתוס' שם ד\"ה אחולי כו' ואמר ואי אשמעינן הכא כו' אימא לא. ר\"ל דא\"א להם למחול צריכא דאפשר למחול והא דר' אמי הנ\"ל משום דבשתיקה אין מחילה ברה\"ר אלא שכ' הרשב\"א שאפשר לפרש שם אבל רבים כו' דא\"א להם למחול ומ\"ש צריכא דאימר כונס בתוך שלו היה וכ\"פ רשב\"ם בספ\"ג שם וכ' ומיהו כיון שהורגלו הכל ואין נמנעין והכל מוחלין מותר כמש\"ש בב\"מ יב ב' עשו שאינו זוכה כזוכה מ\"ט עניים כו' וה\"נ ניחא לכולהו שהכל צריכין לכך:","\u0003ועוד כו'. \u0004 עסמ\"ע ועסי' שסט בסמ\"ע ס\"ק יב:","\u0003והחופר בור כו'. \u0004 ב\"ק כ' א' וכמ\"ש בסי' תי ס\"ז וכמ\"ש בתוספתא דב\"ק פ\"ו חפר בור ברשות ופתח לרה\"ר אפי' היא של רבים חייב עד שימסור לרבים ואמרו שם ובגמ' וכן היה נחוניא כו' ועמש\"ש:"]}],["אֵשׁ הוּא אָב, \u0010y0\u0011 דִּכְתִיב: כִּי תֵצֵא אֵשׁ וּמָצְאָה קוֹצִים \u0005(שְׁמוֹת כב, ה)\u0006 ; וְהוּא מָמוֹנוֹ שֶׁהוֹלֵךְ לְמֵרָחוֹק וּמַזִּיק עַל יְדֵי הָרוּחַ שֶׁמּוֹלִיכוֹ. לְפִיכָךְ, כָּל הַדּוֹמֶה לוֹ, שֶׁהוּא מָמוֹנוֹ וְהוֹלֵךְ וּמַזִּיק, הוּא תוֹלַדְתּוֹ וְיֵשׁ לוֹ דִּין לִפְטֹר בּוֹ טָמוּן.\nכְּתִיב: כִּי תֵצֵא אֵשׁ \u0005(שְׁמוֹת כב, ה)\u0006 ; אֲפִלּוּ מֵעַצְמָהּ, שֶׁהִדְלִיק בְּתוֹךְ שֶׁלּוֹ וְהָלַךְ וְדָלַק בְּתוֹךְ שֶׁל \u0010y1\u0011 חֲבֵרוֹ. אֲפִלּוּ לֹא שָׂרְפָה אֶלָּא עֵצָיו וַאֲבָנָיו, אוֹ שֶׁלִּחֲכָה נִירוֹ, חַיָּב לְשַׁלֵּם הַכֹּל, אֶלָּא אִם כֵּן הִרְחִיק כְּשִׁעוּר; אֲבָל אִם הִרְחִיק \u0010c0\u0011 כְּשִׁעוּר וְיָצָא וְהִזִּיק, פָּטוּר. \u0005הַגָּה: וְכָל זֶה בְּמַדְלִיק בְּתוֹךְ שֶׁלּוֹ; \u0010y2\u0011 אֲבָל בְּמַדְלִיק בְּתוֹךְ חֲבֵרוֹ, אֲפִלּוּ עָבְרָה כַּמָּה מִילִין, חַיָּב (טוּר ס\"א)\u0006.\nוְכַמָּה שִׁעוּר הַהַרְחָקָה, הַכֹּל לְפִי \u0010c1\u0011 גֹבַהּ הַדְּלֵקָה. וְאִם לֹא הִרְחִיק כָּרָאוּי, וְעָבְרָה הָאֵשׁ וְהִזִּיקָה, חַיָּב לְשַׁלֵּם נֶזֶק שָׁלֵם:\nהִרְחִיק כָּרָאוּי, וְעָבְרָה וְהִזִּיקָה, פָּטוּר, \u0010y3\u0011 שֶׁזּוֹ מַכָּה בִּידֵי שָׁמַיִם הִיא. וְכֵן אִם עָבְרָה נָהָר אוֹ שְׁלוּלִית שֶׁיֵּשׁ בָּהֶם מַיִם, \u0010y4\u0011 וְרָחְבָּם שְׁמֹנֶה אַמּוֹת, פָּטוּר. \u0005וְיֵשׁ אוֹמְרִים דְּאִם הַנָּהָר \u0010c2\u0011 רָחָב שְׁמֹנֶה אַמּוֹת, אֲפִלּוּ אֵין בּוֹ מַיִם; וְהַיְאוֹר, אֲפִלּוּ כָּל שֶׁהוּא וְיֵשׁ בּוֹ מַיִם פָּטוּר (טוּר ס\"א)\u0006. עָבְרָה גָדֵר, אוֹמְדִים גֹּבַהּ הַגָּדֵר וְגֹבַהּ הַדְּלֵקָה וְהָעֵצִים וְהַקּוֹצִים הַמְּצוּיִים שָׁם, אִם אֵינָהּ רְאוּיָה לַעֲבֹר, פָּטוּר; וְאִם רְאוּיָה \u0010y5\u0011 לַעֲבֹר, חַיָּב.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בָּאֵשׁ הַקּוֹדַחַת. אֲבָל אִם הָיָה לַהַב גָּדוֹל הָעוֹלֶה וְנִכְפָּף מִגֹּבַהּ עֲלִיַּת הַלַּהַב, וְהָיוּ עֵצִים מְצוּיִים שָׁם, אֵין לָהּ אֹמֶד, אֶלָּא אֲפִלּוּ עָבְרָה אֶלֶף אַמָּה, חַיָּב.\nנָפְלָה דְלֵקָה בַּחֲצֵרוֹ, וְנָפַל גָּדֵר שֶׁלֹּא מֵחֲמַת הַדְּלֵקָה, וְעָבְרָה הַדְּלֵקָה בְּחָצֵר אַחֶרֶת, אִם הָיָה יָכוֹל לִגְדֹּר הַגָּדֵר שֶׁנָּפַל וְלֹא גְּדָרוֹ, חַיָּב; לְמָה הַדָּבָר דּוֹמֶה, לְשׁוֹרוֹ שֶׁיָּצָא וְהִזִּיק, שֶׁהָיָה לוֹ לְשָׁמְרוֹ וְלֹא שְׁמָרוֹ.\nהַשּׁוֹלֵחַ אֶת הַבְּעֵרָה בְּיַד חֵרֵשׁ שׁוֹטֶה וְקָטָן, פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם. בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁמָּסַר לָהֶם גַּחֶלֶת וְלִבּוּהָ \u0005(פֵּרוּשׁ, מֵעִנְּיַן לַבַּת אֵשׁ)\u0006 \u0005(שְׁמוֹת ג, ב)\u0006, שֶׁדֶּרֶךְ הַגַּחֶלֶת לְהִכָּבוֹת מֵאֵלֶיהָ קֹדֶם שֶׁתַּעֲבֹר וְתַדְלִיק, אֲבָל אִם מָסַר לָהֶם שַׁלְהֶבֶת, חַיָּב, שֶׁהֲרֵי מַעֲשָׂיו גָּרְמוּ.\nשָׁלַח הַבְּעֵרָה בְּיַד הַפִּקֵּחַ, זֶה שֶׁהִבְעִיר חַיָּב לְשַׁלֵּם; וְהַשּׁוֹלֵחַ פָּטוּר. \u0010y6\u0011 וְכֵן אִם הִנִּיחַ שׁוֹמֵר לִשְׁמֹר הַבְּעֵרָה, הַשּׁוֹמֵר חַיָּב:\nאֶחָד הֵבִיא אֶת הָאוּר, וְאֶחָד הֵבִיא אֶת \u0010y7\u0011 הָעֵצִים, הַמֵּבִיא אֶת הָעֵצִים חַיָּב. אֶחָד הֵבִיא אֶת הָעֵצִים וְאֶחָד הֵבִיא אֶת הָאוּר, הַמֵּבִיא אֶת הָאוּר חַיָּב. בָּא אַחֵר וְלִבָּה, הַמְלַבֶּה \u0010y8\u0011 חַיָּב. לִבָּתוֹ רוּחַ שֶׁאֵינָהּ מְצוּיָה תָמִיד, הֲרֵי כֻּלָּם פְּטוּרִים. \u0005וְאִם הָרוּחַ מְצוּיָה, הָאַחֲרוֹן חַיָּב (טוּר ס\"ד)\u0006. וְכֵן אִם הָיָה הָרוּחַ שֶׁאֵינָהּ מְצוּיָה, מְנַשֵּׁב בְּשָׁעָה שֶׁבָּא הָאַחֲרוֹן לְשָׁם, הָאַחֲרוֹן חַיָּב \u0005(הַמַּגִּיד פי\"ד \u0010c3\u0011 דְנ\"מ)\u0006. לִבָּה וְלִבָּתוֹ הָרוּחַ, חַיָּב. \u0005הַגָּה: \u0010y9\u0011 וְיֵשׁ אוֹמְרִים דְּאֵין הַמְלַבֶּה חַיָּב אֶלָּא כְּשֶׁיֵּשׁ בַּלִּבּוּי שֶׁלּוֹ כְּדֵי לְלַבּוֹת, וְאֵין בָּרוּחַ לְבַד כְּדֵי לְלַבּוֹת. אֲבָל אֵין בְּכָל אֶחָד כְּדֵי לְלַבּוֹת, אוֹ שֶׁיֵּשׁ בְּכָל אֶחָד כְּדֵי לְלַבּוֹת, פָּטוּר (טוּר שָׁם ובֵית יוֹסֵף בְּשֵׁם הָרַאֲבַ\"ד וְהָרֹא\"שׁ)\u0006. וְיֵשׁ אוֹמְרִים דְּהוּא הַדִּין אִם שְׁנַיִם לִבּוּ וְאֵין בְּכָל אֶחָד כְּדֵי לְלַבּוֹת, פְּטוּרִין \u0005(מָרְדְּכַי פֶּרֶק הַכּוֹנֵס)\u0006.\nעָשָׂה הָאֶחָד הָאֵשׁ, וּבָא אַחֵר וְהוֹסִיף, אִם יֵשׁ בַּמֶּה שֶׁעָשָׂה הָרִאשׁוֹן כְּדֵי שֶׁתַּגִּיעַ לַמָּקוֹם שֶׁהָלְכָה, הָרִאשׁוֹן חַיָּב; וְאִם לָאו, הָרִאשׁוֹן פָּטוּר וְהָאַחֲרוֹן חַיָּב.\nהַכּוֹפֵף קָמָתוֹ שֶׁל חֲבֵרוֹ לִפְנֵי הַדְּלֵקָה, כְּדֵי שֶׁתַּגִּיעַ בָּהּ הַדְּלֵקָה, אִם כְּפָפָהּ בְּמָקוֹם שֶׁתּוּכַל הַדְּלֵקָה לְהַגִּיעַ בְּרוּחַ מְצוּיָה, חַיָּב לְשַׁלֵּם; וְאִם אֵינָהּ יְכוֹלָה לְהַגִּיעַ בְּרוּחַ מְצוּיָה, פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם. \u0005וְאִם הָרוּחַ שֶׁאֵינָהּ מְצוּיָה כְּבָר מְנַשֵּׁב, וְאַחַר כָּךְ כְּפָפָהּ, חַיָּב בְּכָל עִנְיָן (הַמַּגִּיד הַנַּ\"ל)\u0006.\nגָּמָל שֶׁהוּא טָעוּן פִּשְׁתָּן, וְעָבַר בִּרְשׁוּת הָרַבִּים וְנִכְנַס פִּשְׁתָּנוֹ לְתוֹךְ הַחֲנוּת וְדָלְקָה בְּנֵרוֹ שֶׁל חֶנְוָנִי וְהִדְלִיק אֶת כָּל הַבִּירָה, בַּעַל הַגָּמָל חַיָּב, מִפְּנֵי שֶׁהִרְבָּה בַּמַּשּׂאוֹי, בֵּין שֶׁעָמְדָה הַבְּהֵמָה בֵּין שֶׁלֹּא עָמְדָה. וְאִם הִנִּיחַ הַחֶנְוָנִי נֵרוֹ מִבַּחוּץ, הוּא חַיָּב לְשַׁלֵּם אַף דְּמֵי הַפִּשְׁתָּן לְבַעַל הַגָּמָל, \u0010y10\u0011 \u0010c4\u0011 וַאֲפִלּוּ הוּא נֵר חֲנֻכָּה, שֶׁהָיָה לוֹ לֵישֵׁב וְלִשְׁמֹר שֶׁלֹּא יַזִּיק. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאִם הַדְּלֵקָה בְּמָקוֹם אֶחָד וְנִתְפַּשֵּׁט הָאֵשׁ לְמָקוֹם אַחֵר, חַיָּב עַל מְקוֹם הָאֵשׁ נֶזֶק שָׁלֵם וְעַל הַשְּׁאָר חֲצִי נֶזֶק. וְאִם הַגָּמָל סִכְסֵךְ הָאֵשׁ בְּכָל הַבִּירָה, חַיָּב עַל כֻּלּוֹ נֶזֶק שָׁלֵם (טוּר ס\"ז)\u0006, וְעַיֵּן לְעֵיל סִימָן שצ\"ב חִלּוּקִין אֵלּוּ: \u0010y11\u0011\nטָמוּן בְּאֵשׁ, פָּטוּר. שֶׁאִם הִדְלִיק גְּדִישׁ חֲבֵרוֹ וְהָיוּ טְמוּנִים בּוֹ אֲפִלּוּ מוֹרִגִּים \u0005(פֵּרוּשׁ, קְרָשִׁים נְקוּבִים וּבָהֶם יְתֵדוֹת שֶׁל עֵץ אוֹ שֶׁל בַּרְזֶל שֶׁדָּשִׁין בָּהֶם הַתְּבוּאָה)\u0006 וּכְלֵי בָּקָר \u0010y12\u0011 שֶׁדֶּרֶךְ לְהַטְמִינָם בַּגָּדִישׁ, פָּטוּר, וְרוֹאִים מְקוֹם הַכֵּלִים הַטְּמוּנִים \u0010y13\u0011 כְּאִלּוּ הָיוּ שָׁם שְׂעוֹרִים אוֹ חִטִּים כְּפִי מַה שֶּׁהוּא הַגָּדִישׁ, וְכָךְ יְשַׁלֵּם לוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּמַדְלִיק בְּתוֹךְ שֶׁלּוֹ וְהָלְכָה וְדָלְקָה בְּשֶּׁל חֲבֵרוֹ וְכָלוּ חִצָּיו, כְּגוֹן שֶׁנָּפַל הַגָּדֵר שֶׁבֵּינֵיהֶם שֶׁלֹּא מֵחֲמַת \u0010y14\u0011 הַדְּלֵקָה, וְהָיָה אֶפְשָׁר לוֹ לִגְדֹּר וְלֹא גָדַר. אֲבָל אִם הִדְלִיק בְּתוֹךְ שֶׁל חֲבֵרוֹ, אוֹ אֲפִלּוּ בְּתוֹךְ שֶׁלּוֹ וְלֹא כָּלוּ חִצָּיו, כְּגוֹן שֶׁנָּפַל הַגָּדֵר מֵחֲמַת הַדְּלֵקָה, חַיָּב בְּדָבָר שֶׁדַּרְכּוֹ לְהַטְמִין בַּגָּדִישׁ כְּגוֹן מוֹרִגִּים וּכְלֵי בָּקָר, כְּמוֹ שֶׁנִּתְבָּאֵר בְּסִימָן צ'. וּבְבַיִת \u0010c5\u0011 חַיָּב עַל כָּל דָּבָר, שֶׁדֶּרֶךְ בְּנֵי אָדָם לְהַנִּיחַ בַּבַּיִת כָּל כְּלֵיהֶם וְכָל חֲפָצֵיהֶם, וְכָל מַה שֶּׁיִּטְעֹן בַּעַל הַבַּיִת שֶׁהָיָה בַבַּיִת, \u0010y15\u0011 \u0010c6\u0011 הֲרֵי זֶה נִשְׁבָּע בִּנְקִיטַת חֵפֶץ וְנוֹטֵל, וּבִלְבַד שֶׁיִּטְעֹן דְּבָרִים שֶׁהוּא אָמוּד בָּהֶם שֶׁהֵם שֶׁלּוֹ \u0010c7\u0011 אוֹ שֶׁרְגִילִים לְהַפְקִיד בְּיָדוֹ. \u0005וְע\"ל סִימָן צ'.\u0006\nהַמַּשְׁאִיל מָקוֹם לַחֲבֵרוֹ לְהַגְדִּישׁ בּוֹ, וְהִגְדִּישׁ וְהִטְמִין בּוֹ כֵּלִים, וְהִדְלִיק הַמַּשְׁאִיל \u0010y16\u0011 \u0005דְּהַיְנוּ שֶׁעָשָׂה הַמַּשְׁאִיל אֵשׁ וְיָצְאָה וְהִדְלִיקָה (טוּר)\u0006 וְשָׂרַף הַגָּדִישׁ וְהַכֵּלִים שֶׁבְּתוֹכָהּ, אֵינוֹ מְשַׁלֵּם אֶלָּא דְּמֵי גָדִישׁ בִּלְבַד.\nהִשְׁאִילוֹ מָקוֹם \u0010y17\u0011 לְהַגְדִּישׁ חִטִּים, וְהִגְדִּישׁ שְׂעוֹרִים, אוֹ לְהַגְדִּישׁ שְׂעוֹרִים \u0010y18\u0011 וְהִגְדִּישׁ חִטִּים, אוֹ שֶׁהִגְדִּישׁ חִטִּים \u0010y19\u0011 וְחִפָּם בִּשְׂעוֹרִים, \u0010y20\u0011 אוֹ שֶׁהִגְדִּישׁ שְׂעוֹרִים וְחִפָּם בְּחִטִּים, אֵינוֹ מְשַׁלֵּם לוֹ אֶלָּא דְּמֵי שְׂעוֹרִים בִּלְבַד.\nמִי שֶׁרָאָה דְּלֵקָה שֶׁמִּתְקָרֶבֶת לְקָמַת חֲבֵרוֹ, וְהָלַךְ וְכִסָה הַקָּמָה, אַף עַל פִּי שֶׁגָּרַם לוֹ הֶפְסֵד שֶׁהֲרֵי עֲשָׂאוֹ טָמוּן, הֲרֵי זֶה פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם.\nאֵשׁ שֶׁעָבְרָה וְהִזִּיקָה אֶת הָאָדָם \u0010y21\u0011 וְחָבְלָה בּוֹ, הֲרֵי הַמַּבְעִיר חַיָּב בְּנִזְקוֹ וּבְשִׁבְתּוֹ \u0010y22\u0011 וּבְרִפּוּיוֹ וּבְצַעֲרוֹ וּבְבָשְׁתּוֹ \u0010y23\u0011 כְּאִלּוּ הִזִּיקוֹ בְּיָדוֹ, \u0005(שֶׁאַף עַל פִּי)\u0006 שֶׁאִשּׁוֹ מָמוֹנוֹ הוּא, \u0010y24\u0011 הֲרֵי הוּא כְּמוֹ שֶׁהִזִּיק בְּחִצָּיו; וְהוּא שֶׁהָיָה הָאֵשׁ רָאוּי לְהַגִּיעַ שָׁם לַמָּקוֹם שֶׁהִזִּיק בְּשָׁעָה שֶׁהִדְלִיק, אֲבָל אִם לֹא הָיָה רָאוּי לְהַגִּיעַ שָׁם, כְּגוֹן שֶׁהָיָה גָּדֵר בֵּינֵיהֶם וְנָפַל שֶׁלֹּא מֵחֲמַת הָאֵשׁ, אֲפִלּוּ אִם הָיָה אֶפְשָׁר לוֹ לְגָדְרָהּ, כְּבַר כָּלוּ חִצָּיו וְיֵשׁ לוֹ דִּין מָמוֹנוֹ שֶׁהִזִּיק אָדָם שֶׁאֵינוֹ חַיָּב אֶלָּא בְּנֶזֶק בִּלְבַד, \u0010y25\u0011 וּפָטוּר מֵאַרְבָּעָה דְבָרִים.\nהִנִּיחַ לַחֲבֵרוֹ גַּחֶלֶת עַל לִבּוֹ, וְנִשְׂרַף, פָּטוּר, אֲפִלּוּ הִתְרוּ בּוֹ; שֶׁלֹּא הָיָה סָבוּר שֶׁלֹּא יְסַלְּקֶנָּה, שֶׁאֵין דֶּרֶךְ שֶׁיַּנִּיחַ אָדָם עַצְמוֹ לִשְׂרֹף כְּדֵי שֶׁיֵּהָרֵג חֲבֵרוֹ. אֲבָל אִם הִנִּיחַ גַּחֶלֶת עַל בִּגְדוֹ שֶׁל חֲבֵרוֹ וְנִשְׂרָף, \u0010y26\u0011 \u0010c8\u0011 חַיָּב, שֶׁאֵינוֹ חוֹשֵׁשׁ לְסַלְּקוֹ כֵּיוָן שֶׁזֶּה חַיָּב לְשַׁלֵּם לוֹ. וְעַבְדּוֹ כְּגוּפוֹ, וְשׁוֹרוֹ כְּבִגְדוֹ. \u0005הַגָּה: \u0010y27\u0011 וְיֵשׁ אוֹמְרִים דְּעֶבֶד קָטָן דִּינוֹ כְּשׁוֹר (נִמּוּקֵי יוֹסֵף ס\"פ כֵּיצַד)\u0006. וְיֵשׁ אוֹמְרִים דַּוְקָא בְּשׁוֹר כָּפוּת, אֲבָל בְּשׁוֹר שֶׁאֵינוֹ כָפוּת, פָּטוּר \u0005(טוּר סי\"ד בְּשֵׁם רַשְׁבָּ\"א וְהָרֹא\"שׁ)\u0006.",["\u0003דכתיב כי תצא וגו' \u0004 בפרשת משפטים כי תצא אש ומצאה קוצים ונאכל גדיש או הקמה או השדה שלם ישלם המבעיר את הבעירה ודרשינן שהדבר הנשרף בעינן שיהא דומיא דקמה וגדיש שהן דברים שבגלוי לאפוקי אם נטמן בהן דבר וכמ\"ש הטור והמחבר בסמוך בסי\"ג ע\"ש:","\u0003אפי' לא שרפו אלא עציו ואבניו כו' \u0004 ל' הטור או שליחכ' נירו שהוא דבר \"שאינו \"ראוי לו ובפרישה כתבתי שהאי \"שאינו \"ראוי לו קאי גם אאבניו וגם אעציו אם הם בענין שאינם ראויים לו וקמ\"ל דאף דכתיב ביה כי תאכל לשון אכילה ובהיזק שן נתבאר בסי' ש\"ץ דאם אכל דבר הראוי לו ודרכן בכך נתחייב עליו בעליו נ\"ש ואי לא (ח\"נ) אבל בכאן אפי' אינו ראוי לשרוף מתחייב עליו נ\"ש וילפינן מיתורא דאו השדה דאפי' ליחכה נירו וה\"ה נשרפו אבניו:","\u0003אבל במדליק בתוך חבירו כו' \u0004 דכיון דהדליק מתחלה שלא ברשות חייבוהו על הכל:","\u0003שזו מכה בידי שמים הוא. \u0004 כצ\"ל וכן הוא לשון הרמב\"ם ורצה לו' ומה\"ט פטור אע\"ג דבעלמא אמרינן דכל המקלקלין אע\"פ שהניח ברשות אפי' הכי הוא חייב וכמו שכתבו הטור והמחבר בסוף סי' שלפני זה ועמ\"ש בשם הרי\"ף בסי' ת\"י ס\"ה בדרישה בטעם חילוקי חיוב פטור הללו:","\u0003ה\"ג ורחבם שמנ' \u0004 וכן הוא ברמב\"ם דפוס גדול וקטן:","\u0003בד\"א באש הקודחת כו' \u0004 לשון הטור וכל זה לא איירי אלא כשמתמרה ועולה למעלה אבל אם נסרכ' לצידה ועצים מצויי' לה אין לה שיעורכו':","\u0003וכן אם הניח שומר לשמור כו'. \u0004 וכן הדין במי שמסר שור ביד שומר ויצא והזיק כמ\"ש הטור והמחבר בסי' שצ\"ו ושם נתבאר חילוק דאם הוא ש\"ח או ש\"ש או שואל ודין שומר שמסר לשומר ע\"ש:","\u0003המביא עצים חייב כו'. \u0004 ל' הטור לעולם האחרון חייב:","\u0003רוח שאינו מצויה תמיד \u0004 ז\"ל מ\"מ בפ\"ד מנ\"מ רוח שאינו מצויה ר\"ל שאין העולם מתנהג בה תמיד אלא לפעמים אף ע\"פ שהוא בא בעתים הרבה ואצ\"ל רוח סערה שאינו נשבה אלא לעתים רחוקות:","\u0003דאין המלבה חייב אלא כו'. \u0004 ואע\"ג דלענין הזורה בשבת והרוח מסייעו חייב שאני התם דמלאכת מחשבת אסרה התורה והרי מלאכת הזרייה דרכה בכך ע\"י הרוח שסייעו משא\"כ כאן דה\"ל הוא רק גורם להיזק ופטור והרמב\"ם סבר דחייב כיון דהוא עצמו ליבה ויש לו חלק בנזק זה ואינו דומה לגרמא בנזקין דפטור עד\"ר:","\u0003ואפי' הוא נר חנוכה \u0004 פירוש אע\"פ שהניחו שם ברשות כי המצוה הוא בכך:","\u0003טמון באש פטור. \u0004 בר\"ס זה כתבתי דילפינן ליה מיתור' דאו הקמה דבעינן דיהא דומה לקמה דהוא דבר שבגלוי והאי או קמה גבי תצא אש כתיב דמיירי שיצאה מרשותו בזה דוקא מצינו בו דפטור בו טמון משא\"כ בהדליק בשל חבירו וכדמסיק:","\u0003שדרך להטמינ' בגדיש. \u0004 פי' וה\"ל לאסוקי אדעתיה שישנו שם ולהיות חייב בשריפתן:","\u0003כאלו היה שם חטים או שעורים כו'. \u0004 בפרישה כתבתי שאם הגדיש הוא חיטין או שעורין עם תבן שלהן וכדרך הגדיש דשמין גם המוריגי' בחיטין ושעורין בתבן שלהן וגם זהו בכלל מ\"ש הטור והמחבר כפי מה שהוא הגדיש:","\u0003והיה אפשר לו לגדור \u0004 דאל\"כ לא היה חייב על היזק השריפה כיון שכלו חציו וכמ\"ש לפני זה בס\"ו:","\u0003נשבע בנק\"ח ונוטל. \u0004 פי' אע\"פ שאין עדים בדבר שכך וכך הי' לו בבית ע' בד\"מ שכ' בשם המ\"מ אם היו מחולקין בדבר הנשרף לו בגלוי שהניזק אמר כך וכך הי' והמזיק אמר ברי לי שלא הי' אלא כך אפ\"ה הניזק נשבע ונוטל דעשו תקנ' נגזל ג\"כ בנשרף ע\"ש וע\"ל בסי' צ' מקור דין נשבע ונוטל בענייני' אלו:","\u0003דהיינו שעשה המשאיל אש כו' \u0004 פי' עשה האש בשלו וכלו חציו וכנ\"ל קמל\"ן דל\"ת כיון דנתן ראובן רשות לשמעון להגדיש בחצירו וה\"ל כאלו קיבל ראובן שמירתו דגדיש עליוואפי' להרי\"ף והרמב\"ם החולקים בסימן שצ\"ח עם ר\"י והרא\"ש ופטרי לב\"ה שהזיק שורו לשור הנכנס ברשות ה\"א דמודו בהא כיון דמ\"מ הדליק האש בידים קמל\"ן:","\u0003להגדיש חטין והגדיש שעורים \u0004 וא\"ת פשיטא איך ישלם טפי ממה שהזיק י\"ל דקמ\"ל דל\"ת דליחייב אמוריגין שהטמין בתוכו כאלו הי' חטים וכדין מוריגין שטמון בגדיש של חטין והרי נתן לו רשות לחיטין ועפ\"ר:","\u0003והגדיש חטים וכו' \u0004 דיכול לומר לא קבלתי עלי אלא שמירת שעורים:","\u0003וחיפן בשעורים. \u0004 אף ע\"ג דנתן רשות לחיטין יכול לומר לא ראיתי לפני אלא שעורין:","\u0003ומ\"ש הטור והמחבר או שהגדיש שעורים וחיפן בחיטין. \u0004 בפריש' כתבתי ל' רש\"י שפי' דמיירי בנתן לו רשות להגדיש שעורים וכתבתי דלפ\"ז ל\"ל דקמ\"ל בזה דל\"ת דוקא ברישא ששינ' מדעת המשאילו לגמרי שנתן לו רשות לשעורים והוא הגדיש חטים הוא דפטור מחטים מה שא\"כ זה שהגדיש שעורים לחייב לפחות גם אחיפוי חטין קמ\"ל:","\u0003וחבלה בו. \u0004 ואם מת מכח הבערה חייב בעליו מיתה כאלו ירה בו חץ וכ\"כ הטור:","\u0003ובצערו ובבשתו. \u0004 ואע\"ג דיתבאר בסי' תכ\"א דאין חייב על הבשת עד שיכוון לבייש ה\"נ כיון דעבר הדליק' ברוח מצויה ה\"ל כאלו ידע וכוון לכך וצריכין לומר דחילקו הרמב\"ם והמחבר בין זה לנפל מן הגג ברוח מצוי' והזיק שכתב הרמב\"ם בפ\"א דחובל והמחבר לקמן בסי' תכ\"א סי\"א דאינו משלם בבשת משום דלא כוון דשאני התם דנפילתו מהגג ויזיק מחשב לאונס טפי אף שהי' ברוח מצוי' מהדליק אש ויצא והזיק לאדם אבל רש\"י ור\"ן כתבו בפ' כיצד הרגל בהדיא גם בזה דפטור מבושת והביאו ראיה מההיא דנפל מהגג והרא\"ש והטור סתמו וכתבו בדין זה דחייב בד' דברים ועפ\"ר שכתבתי שנ\"ל דס\"ל ג\"כ כהרמב\"ם דחייב גם בבשת וד' דברים חוץ מנזק קאמרי דנזק חייב בפשיע' לכ\"ע אף אם לא היה בו משום חציו אלא משום ממונא ע\"ש ודו\"ק:","\u0003כאלו הזיק בידים \u0004 שאע\"פ שאשו כו' כצ\"ל וילפינן לה מדכתי' כי תצא אש ומצאה קוצים דמשמע דיצאה מעצמו וסיים וכתב ישלם המבעיר משמע דנחשב כאילו הבעירו בידים:","\u0003הרי הוא כמי שהזיק בחציו. \u0004 פי' לענין להתחייב עליו בה' דברים וגם מיתה אם מת מחמת האש וכנ\"ל אבל ג\"כ לא גרע משור ובור שהן ממונו וחייב עליהן לפחות נזק ונ\"מ דאפי' היכא דלא חייב על האש משום חציו כגון שלא היה לו לעבור עדיין חייב משום ממונו וכדמסיק המחבר:","\u0003ופטור מד' דברים. \u0004 דכי יתן איש בעמיתו כתיב וכנ\"ל:","\u0003שאינו חושש לסלק כו' \u0004 ונראה דה\"ה אם ראובן אמר לשליח שאינו בר חיובא כגון חש\"ו קרע בגד שמעון והחש\"ו קרעו לפני שמעון ושותק דחייב ראובן המשלח מה\"ט שלא חשש שמעון למחות בידו:","\u0003דעבד קטן דינו כשור. \u0004 עד\"ר שם כתבתי דלא כתב הנ\"י כן אלא לשטת פירש\"י דס\"ל דבהניח על השור אף שאינו כפות חייב דלא אמרינן גבי בהמה דאין לה דעת דה\"ל לברוח ע\"ז כתב הנ\"י בס\"פ כיצד הרגל דה\"ה עבד קטן דאין בו דעת אבל לדעת התוס' והרא\"ש דכתבו דדוקא בשור כפות הוא דחייב אבל באינו כפות פטור משום דדרכו לברוח מהאש אף שאינו בר דעת ובהניח על לב עבד פטור אם רבו הוא שם אפי' בכפות משום דסבר המניח שרבו יסירנ' מעליו כיון שעבד הוא בן חורין (חיוב) וחייב במצות מה\"ט גם בעבד קטן שאינו כפות פטור דהוי לו לברוח דומיא דשור. ובכפות ורבו עומד בצדו (אינו) דומה לעבד גדול ואין יכול המניח גחלת על לבו להתנצל ולומר סברתי שרבו יסירנה מלבו כדין עבד: וע\"פ מ\"ש יתבאר לך דמור\"ם דסתם וכ' די\"א עבד קטן הוא כשור הוא ע\"פ מה שסתם המחבר וכ' דין שור ועבד ולא הזכיר בדבריו כפות כ\"כ אבל לפי מה שמסיק מור\"ם וכ' די\"א דוקא שור כפות ע\"פ אותו דעה אין דין עבד קטן כשור וכמ\"ש וזה ברור אלא שק' הא צ\"ל דהמחבר אף שלא הזכיר כפות ע\"כ צריכין לפ' דמיירי בכפות שהרי כ' בר\"ס שפ\"ג אעבד ושור דין זה כשהיו כפותין וצ\"ל שקיצר כאן יסמך אמ\"ש שם וכמ\"ש בסמ\"ע שם בסי' שפ\"ג וצריכין לדחוק ולומר דאעפ\"כ מ\"מ כיון דלא הזכיר המחבר כאן כפות כ' מור\"ם עליו כן:"],["\u0003 ויצא והזיק כו'. \u0004 ע\"ל סימן קנ\"א [קנ\"ה] ס\"א:","\u0003 ואם לא הרחיק כו'. \u0004 עיין ביש\"ש סי' צ\"ח [כ\"ח] מה שהקשה ע\"ז מ\"ש בס\"ד ויש ליישבו ודוק וע\"ש:","\u0003 רחב ח' אמות כו' \u0004 וכ\"פ מהרש\"ל סי' כ\"ח ועיין שם טעמו ואין כדאי בטעמו לדחות דברי הרא\"ש וטור:","\u0003 ליבה וליבתו הרוח חייב. \u0004 הוא לשון הרמב\"ם והראב\"ד השיג עליו וז\"ל איך לא חלק כמו שחלק בברייתא אם יש בלבויו כדי ללבות חייב ואם לאו פטור והרב המגיד כתב שאפשר לתרץ שפסק דלא כרב אשי אלא כאידך שנויי דאמוראי אלא שקשה שבפי\"א מה' שכנים פסק כרב אשי (כדלעיל סימן קנ\"ה סל\"ד ע\"ש) והב\"י כתב שדברי הרב המגיד נכונים ול\"ק מפי\"א מה' שכני' דשאני התם שאין נזק זה בא מכח מזיק עצמו משא\"כ הכא שבא מכח מזיק עצמו נקטינן כאינך אמוראי דחייב עכ\"ל ואחריו נמשך הסמ\"ע ושאר אחרונים וכה\"ג כתב מהרש\"ל פ' הכונס סימן כ\"ד. ואני אומר אם כדבריהם ודאי פה השיגו הראב\"ד דהאיך יתכן שיפסוק כאינך אמוראי והא קיימא לן בכל דוכתא הלכתא כרב אשי נגד הנך אמוראי ועוד דמ\"מ תיקשי דהל\"ל כדברי הברייתא ואם לאו פטור ולפרושי בהנך גווני דמפרשי לה אינך אמוראי לאביי כגון שלבתו הרוח מצד אחר ולרבא ברוח שאינו מצויה ולר' זירא כגון דצמרא צמורי אכן לפע\"ד נ' שלא ירדו כולם לסוף דעת הרמב\"ם וטעמו ונמוקו עמו מה שלא חלק כמו שחילק בבריית' והוא בשום לב עוד שהרמב\"ם כתב וז\"ל לבה ולבתו הרוח חייב שהרי הוא גרם וכל הגורם להזיק משלם נזק שלם מן היפה שבנכסיו כשאר כל המזיקין עכ\"ל דלאיזה צורך האריך הרמב\"ם בטעם זה וגם היאך כתב טעם שלא נזכר בש\"ס כלל אלא ודאי כוונת הרמב\"ם לפסוק כרב אשי דבתראי הוא וס\"ל דפירושא דברייתא ודאי כרב אשי הוא ולא כאידך אמוראי ואין חילוק בין לבתו מצד אחר או בין רוח שאינה מצויה או בין צמרה צמורי אלא ברייתא כפשטא היא כדאוקמה רב אשי דטעמא הוא משום גרמא בנזקין פטור אלא דס\"ל להרמב\"ם דנהי דאוקימתא דברייתא הכי היא מ\"מ לא קי\"ל כוותה משום דאתיא כמ\"ד דלא דיינינן דינא דגרמי ואנן דיינינן דינא דגרמי וכדאיתא להדיא בש\"ס פרק הגוזל קמא (בבא קמא דף צ\"ח ע\"ב) ונתבאר לעיל סי' שפ\"ו (וס\"ל להרמב\"ם דגרמי וגרמא הכל א' הוא וכדעת רש\"י שהביא הרמב\"ן בדיני דגרמי שלו וכן הוכחתי מדברי רש\"י ר\"פ הכונס ופ' הגוזל שם ע\"א ופרק לא יחפור סוף (בבא בתרא דף כ\"ב) ודלא כמהרש\"ל פרק כיצד הרגל סי' ל\"ו ופרק הגוזל קמא סי' י\"ט לדעתו עיין שם) וזה לשון הש\"ס פרק הגוזל גבי שורף שטר של חברו אמר אמימר מאן דדאין דינא דגרמי מגבי דמי שטרא מעליא ומאן דלא דאין דינא דגרמי מגבי דמי ניירא בעלמא הוה עובד' וכפייה רפרם לרב אשי ואגביה כי כשורא לצלמא עכ\"ל ופירש רש\"י כי כשורא לצלמא פרעון גמור מן העידית וכן כ' הרמב\"ם פ\"ז מה' חובל וז\"ל כל הגורם להזיק ממון חברו חייב לשלם נ\"ש מן היפה שבנכסיו כו' וכן השורף שטר של חברו וכן אם מחלה משלם המוחל מן היפה שבנכסיו עכ\"ל הרי שזה ה\"ל [הל'] ממש שכתב הרמב\"ם בפי\"ד מה' נזקי ממון הוא שאול מדבריו פ\"ז מהלכו' חובל והוא ע\"פ מאי דקי\"ל דדיינינן דינא דגרמי. כן נראה לי ברור בדעת הרמב\"ם ז\"ל אך יש לדקדק אמאי פסק בפי\"א מהלכות שכנים דפטור ומה שתירץ הב\"י בזה שאין הנזק בא מכחו הוא דוחק דהא כיון שבהכאתו הולך העפר דומה לליבה שבלבתו הולך האש ויש לתרץ בזה כמו שחילקו הרמב\"ם בדיני דגרמי שלו ומהרש\"ל שם דל\"ד לעפר שבפי\"א שהולך הפך מכחו שכונתו להפיל העפר לארץ ולא שילך למרחוק משא\"כ אש שהרוח מסייע למה שכוונתו שילך האש ע\"ש ואולי גם הב\"י כוון לזה ואין להקשות מנ\"ל להרמב\"ם לחלק בכך י\"ל דמשמע לי' דמסתמא לא פליגי [מר בר] רב אשי ואמימר בס\"פ לא יחפור ארבינ' פלוגתא רחוק' דרבינא שרי אפי' לכתחלה כדמוכח התם אלא ודאי אינהו לא קאמרו אלא לכתחל' אבל בדיעבד אם הזיק פטור לכ\"ע והיינו משום דהתם ליכא גרמא כלל משום דלא ניחא ליה במה שהעפר הולך למרחוק והיינו בכלל מה דמשני התם בגמרא הכא לא ניחא ליה דליזל אבל בליבה ולבתו הרוח ניחא ליה דליזל. כל זה נ\"ל לדעת הרמב\"ם והיה לבי נוקפי קצת על מה שפרשתי בדעת הרמב\"ם שטה אחרת בש\"ס ס\"פ הכונס עד שמצאתי ת\"ל ראיה ברור' לדברי בראב\"ן פרק הגוזל קמא בספרו ד' צ' ע\"א וז\"ל הוה עובדא דאדם אחד שרף שטר של חבירו ובאו לדין לפני רב אשי והי' פוטרו כדברי רבה ולפי שמועתו שאמר בפרק הכונס גבי לבה וליבתו הרוח דאמר רב אשי גרמא בעלמא הוא וגרמא בנזיקין פטור ואכפייה רפרם לרב אשי בדברים ובדין ואגביה ביה כשורא מן המובחר וכיון דרב אשי ורפרם עבדו עובדא ודנו דיני דגרמי כותייהו קי\"ל דאינון בתראי עכ\"ל הרי להדיא כדברי. ובריש הספר הסוגיא דס\"פ לא יחפור כתב ראב\"ן וז\"ל ולרבינא מאי שנא מגץ היוצא כו' כלומר מאי שנא מזור' וגץ דבתרוייהו הרוח מסייעו ומשני התם ניחא ליה דליזל כלומר בין זורה בין גץ ניחא ליה דליזלו מרחוק ולא יפלו תחתם אבל רקתא לא ניחא ליה דליזל אלא שיפול תחתיו וכי אזיל לאו גירי' הוא דמדעתו ורצונו לא אזיל עכ\"ל והלכך הרמב\"ם אע\"ג דפסק כמר בר רב אשי ואמימר דפליגי אדרבינא היינו לענין להרחיק לכתחלה אבל אם הזיק משמע ליה דל\"ד לזורה ורוח מסייעתו מהאי טעמא וכמ\"ש ודו\"ק:","\u0003 ואפי' הוא נר חנוכה \u0004 (הגה\"ה ועיין ברי\"ף פרק במה מדליקין דאיתא שם שפטור ועיין בש\"ג שם שכתב שהוא הג\"ה ואינו מלשון הרי\"ף ע\"ש טעמו וק\"ל וכן משמעות הלשון שם שהוא אינו מדברי הרי\"ף):","\u0003 על כל דבר שדרך בני אדם להניח כו' \u0004 משמע אם אין דרך להניחו אפי' ידוע שהי' שם פטור ויש להקשות דהא לעיל ר\"ס שפ\"ח משמע להדיא מדברי הרמב\"ם והמחבר דבידוע שהי' שם אפי' אין דרכו להניח שם חייב וצ\"ל דהתם מיירי המזיק בידים אבל הכא אע\"פ דמיירי שהדליק בתוך של חבירו היינו בפשיעה ולא בידים וכן נ\"ל מתוך דברי מהרש\"ל פרק הכונס סי' ל\"ב שכתב שם וז\"ל אבל אי הוי עדים פשיטא דמשלם מאחר דמזיק בידים הוא אבל מזיק בפשיעה לא משלם אפי' בעדים דבר שאין דרך להניח בו ומדליק בתוך של חבירו נמי דפטרי רבנן כל מה שאין דרכו להניח היינו דמדליק בידים פשיטא שחייב על הכל עכ\"ל ונ\"ל שיש חסרון בדבריו וכך צ\"ל היינו מדליק בפשיע' דאלו מדליק בידים פשיטא שחייב על הכל ודו\"ק:","\u0003 הרי זה נשבע בנקיטת חפץ. \u0004 ועיין בד\"מ ובב\"י שכתבו בשם המ\"מ אם היה מחולקין בדבר הנשרף לו בגלוי שהניזק אומר כך וכך היה והמזיק אומר ברי לי שלא היה אלא כך אפ\"ה הניזק נשבע ונוטל דעשו תקנת נגזל ג\"כ בנשרף ע\"ש ומביאו ג\"כ בסמ\"ע ומיירי שיש עדים על הדליק' וכן הוא במ\"מ להדיא ובזה ניחא דלא תקשי ממ\"ש הרמב\"ם והמחבר לעיל ר\"ס שפ\"ח המזיק ממון חבירו ואינו יודע מה הזיק כו' או לאש כו' והמזיק אומר אינו יודע כו' הניזק נשבע בנק\"ח ונוטל כו' דמשמע הא אם טוען המזיק ברי אין הניזק נשבע ונוטל דהתם מיירי שאין עדים שהזיקו אם כן נאמן במגו ודו\"ק כל זה צ\"ל לדעת הרב והמגיד והסמ\"ע אבל באמת נ\"ל עיקר דהרמב\"ם והמחבר ס\"ל כהי\"א שהביא הרב המגיד דבאש אם טוען המבעיר ברי נשבע ונפטר והדעת נותנת כן וכן משמע להדיא מדברי מהרש\"ל פרקי הכונס ס\"ס ל\"ג שכתב שם וז\"ל דוקא שטען המזיק שמא אבל אי טען ברי לא א\"ל גבי גזלן כו' וכ\"כ עוד מהרש\"ל להדיא שם סי' ל' דמסור מיירי כשטוען המוסר ברי ואף דהא דאמרי' עשו תקנת נגזל באשו לא איירי בכופר המבעיר מכל מקום לא הוי רשע כגזלן ודוק' מוסר ראוי לדמותו לגזלן אבל לא מזיק אפי' להכעיס כו' עכ\"ל וכן מוכח להדיא בהרא\"ש פרק הכונס וז\"ל ואין נראה לר\"י דמשמע בבעיא דומיא דטמון באש שאין המבעיר יודע כמה הפסיד הניזק והכי מסתבר טפי לדמות בעיא זו לטמון באש מלדמותו לנגזל דהא טמון לא מדמינן לנגזל אף ע\"ג דקאמר עשו תקנת נגזל באשו עכ\"ל ובספר מע\"מ שם כתב על דברי הרא\"ש אלו וז\"ל דהא טמון לא מדמינן לנגזל כו' לא ידענא מאי קאמר לענין מה דלא מדמינן שלא מצינו בתלמוד שום דבר עכ\"ל ולא דק דה\"ק דהא טמון לא אשכחן דמדמינן לנגזל היכא דהמבעיר טוען ברי וק\"ל וכן כתב עוד הרא\"ש בס\"פ הכונס וז\"ל ותימא למה יעשו תקנת נגזל במפקיד בשלמא בנגזל עשו תקנה שלא ישבע הגזלן וכן באש שפשע בשמירת אשו וגם אין המבעיר יכול לידע מה היה לניזק בבית וכן במוסר שבועה על הנמסר שישבע ויטול שעשה המוסר עבירה אבל במפקיד למה הטילו כו' עכ\"ל וכן עיקר:","\u0003 או שרגילים כו' \u0004 עמ\"ש לעיל סימן צ' סעיף ז':","\u0003 שאינו חושש לסלקו כו'. \u0004 עיין בסמ\"ע ס\"ק כ\"ז וה\"ה דאמר לשליח שאינו בר חיובא כגון חש\"ו כו' דבריו תמוהין דהא תנן השולח את הבערה ביד חש\"ו פטור ועיין בפ\"ק דמציעא (דף י') ובתוס' שם (הג\"ה ר\"ל שהרגישו בקושיא זו דהא לאו בר חיובא הוא ותירצו ע\"ש) ובנ\"י שם ועמש\"ל ר\"ס קפ\"ב ורצ\"ב (הג\"ה ושמ\"ח):"],"\u0010g0\u0011 \u0010r0\u0011 אֵשׁ הוּא אָב, \u0010y0\u0011 דִּכְתִיב: כִּי תֵצֵא אֵשׁ וּמָצְאָה קוֹצִים \u0010g1\u0011 \u0010r1\u0011 \u0005(שְׁמוֹת כב, ה)\u0006 ; וְהוּא מָמוֹנוֹ שֶׁהוֹלֵךְ לְמֵרָחוֹק וּמַזִּיק עַל יְדֵי הָרוּחַ שֶׁמּוֹלִיכוֹ. לְפִיכָךְ, כָּל הַדּוֹמֶה לוֹ, שֶׁהוּא מָמוֹנוֹ וְהוֹלֵךְ וּמַזִּיק, הוּא תוֹלַדְתּוֹ וְיֵשׁ לוֹ \u0010r2\u0011 דִּין לִפְטֹר בּוֹ \u0010g2\u0011 טָמוּן. \u0010r3\u0011\nכְּתִיב: כִּי תֵצֵא אֵשׁ \u0005(שְׁמוֹת כב, ה)\u0006 ; אֲפִלּוּ מֵעַצְמָהּ, \u0010g3\u0011 \u0010r4\u0011 שֶׁהִדְלִיק בְּתוֹךְ שֶׁלּוֹ \u0010g4\u0011 וְהָלַךְ וְדָלַק בְּתוֹךְ שֶׁל \u0010y1\u0011 \u0010g5\u0011 \u0010r5\u0011 חֲבֵרוֹ. אֲפִלּוּ לֹא שָׂרְפָה אֶלָּא עֵצָיו וַאֲבָנָיו, אוֹ שֶׁלִּחֲכָה נִירוֹ, חַיָּב לְשַׁלֵּם הַכֹּל, \u0010g6\u0011 אֶלָּא אִם כֵּן הִרְחִיק כְּשִׁעוּר; אֲבָל אִם הִרְחִיק \u0010c0\u0011 כְּשִׁעוּר וְיָצָא וְהִזִּיק, פָּטוּר. \u0005הַגָּה: \u0010r6\u0011 וְכָל זֶה בְּמַדְלִיק בְּתוֹךְ שֶׁלּוֹ; \u0010y2\u0011 אֲבָל בְּמַדְלִיק בְּתוֹךְ \u0010t0\u0011 חֲבֵרוֹ, אֲפִלּוּ עָבְרָה כַּמָּה מִילִין, חַיָּב (טוּר ס\"א)\u0006. \u0010g7\u0011\nוְכַמָּה שִׁעוּר הַהַרְחָקָה, הַכֹּל לְפִי \u0010c1\u0011 \u0010g8\u0011 גֹבַהּ הַדְּלֵקָה. וְאִם לֹא הִרְחִיק \u0010t1\u0011 כָּרָאוּי, וְעָבְרָה הָאֵשׁ וְהִזִּיקָה, חַיָּב לְשַׁלֵּם נֶזֶק שָׁלֵם: \u0010g9\u0011\nהִרְחִיק כָּרָאוּי, וְעָבְרָה וְהִזִּיקָה, פָּטוּר, \u0010y3\u0011 \u0010r7\u0011 שֶׁזּוֹ מַכָּה בִּידֵי שָׁמַיִם הִיא. וְכֵן אִם \u0010g10\u0011 \u0010r8\u0011 עָבְרָה נָהָר אוֹ \u0010g11\u0011 שְׁלוּלִית שֶׁיֵּשׁ בָּהֶם מַיִם, \u0010y4\u0011 \u0010t2\u0011 וְרָחְבָּם \u0010g12\u0011 שְׁמֹנֶה אַמּוֹת, \u0010g13\u0011 פָּטוּר. \u0010r9\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּאִם הַנָּהָר \u0010c2\u0011 רָחָב שְׁמֹנֶה אַמּוֹת, אֲפִלּוּ אֵין בּוֹ מַיִם; וְהַיְאוֹר, \u0010r10\u0011 אֲפִלּוּ כָּל שֶׁהוּא וְיֵשׁ בּוֹ מַיִם פָּטוּר \u0010g14\u0011 (טוּר ס\"א)\u0006. \u0010g15\u0011 \u0010r11\u0011 עָבְרָה גָדֵר, אוֹמְדִים גֹּבַהּ הַגָּדֵר וְגֹבַהּ הַדְּלֵקָה וְהָעֵצִים וְהַקּוֹצִים הַמְּצוּיִים שָׁם, אִם אֵינָהּ רְאוּיָה לַעֲבֹר, פָּטוּר; וְאִם רְאוּיָה \u0010y5\u0011 \u0010g16\u0011 \u0010r12\u0011 \u0010r13\u0011 לַעֲבֹר, חַיָּב.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בָּאֵשׁ הַקּוֹדַחַת. אֲבָל אִם הָיָה לַהַב גָּדוֹל הָעוֹלֶה וְנִכְפָּף מִגֹּבַהּ עֲלִיַּת הַלַּהַב, וְהָיוּ עֵצִים מְצוּיִים שָׁם, אֵין לָהּ אֹמֶד, אֶלָּא אֲפִלּוּ עָבְרָה אֶלֶף אַמָּה, \u0010g17\u0011 חַיָּב.\nנָפְלָה דְלֵקָה בַּחֲצֵרוֹ, וְנָפַל \u0010g18\u0011 גָּדֵר שֶׁלֹּא מֵחֲמַת הַדְּלֵקָה, וְעָבְרָה הַדְּלֵקָה בְּחָצֵר אַחֶרֶת, אִם הָיָה יָכוֹל לִגְדֹּר הַגָּדֵר שֶׁנָּפַל וְלֹא גְּדָרוֹ, חַיָּב; לְמָה הַדָּבָר דּוֹמֶה, לְשׁוֹרוֹ שֶׁיָּצָא וְהִזִּיק, שֶׁהָיָה לוֹ לְשָׁמְרוֹ וְלֹא שְׁמָרוֹ. \u0010g19\u0011\nהַשּׁוֹלֵחַ אֶת הַבְּעֵרָה בְּיַד חֵרֵשׁ שׁוֹטֶה וְקָטָן, פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם. \u0010g20\u0011 \u0010r14\u0011 בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁמָּסַר לָהֶם גַּחֶלֶת וְלִבּוּהָ \u0005(פֵּרוּשׁ, מֵעִנְּיַן לַבַּת אֵשׁ)\u0006 \u0005(שְׁמוֹת ג, ב)\u0006, שֶׁדֶּרֶךְ הַגַּחֶלֶת לְהִכָּבוֹת מֵאֵלֶיהָ קֹדֶם שֶׁתַּעֲבֹר וְתַדְלִיק, אֲבָל אִם מָסַר לָהֶם שַׁלְהֶבֶת, חַיָּב, שֶׁהֲרֵי מַעֲשָׂיו גָּרְמוּ. \u0010g21\u0011\nשָׁלַח הַבְּעֵרָה בְּיַד הַפִּקֵּחַ, זֶה שֶׁהִבְעִיר חַיָּב לְשַׁלֵּם; וְהַשּׁוֹלֵחַ פָּטוּר. \u0010y6\u0011 \u0010g22\u0011 \u0010r15\u0011 וְכֵן אִם הִנִּיחַ שׁוֹמֵר לִשְׁמֹר הַבְּעֵרָה, הַשּׁוֹמֵר \u0010g23\u0011 חַיָּב:\nאֶחָד הֵבִיא אֶת הָאוּר, וְאֶחָד הֵבִיא אֶת \u0010y7\u0011 הָעֵצִים, הַמֵּבִיא אֶת הָעֵצִים חַיָּב. אֶחָד הֵבִיא אֶת הָעֵצִים וְאֶחָד הֵבִיא אֶת הָאוּר, הַמֵּבִיא אֶת הָאוּר חַיָּב. בָּא אַחֵר \u0010g24\u0011 וְלִבָּה, הַמְלַבֶּה \u0010y8\u0011 \u0010g25\u0011 חַיָּב. לִבָּתוֹ רוּחַ \u0010r16\u0011 שֶׁאֵינָהּ מְצוּיָה \u0010g26\u0011 תָמִיד, הֲרֵי כֻּלָּם פְּטוּרִים. \u0005וְאִם הָרוּחַ מְצוּיָה, הָאַחֲרוֹן חַיָּב (טוּר ס\"ד)\u0006. \u0010r17\u0011 וְכֵן אִם הָיָה הָרוּחַ שֶׁאֵינָהּ מְצוּיָה, מְנַשֵּׁב בְּשָׁעָה שֶׁבָּא הָאַחֲרוֹן לְשָׁם, הָאַחֲרוֹן חַיָּב \u0005(הַמַּגִּיד פי\"ד \u0010c3\u0011 \u0010g27\u0011 \u0010t3\u0011 \u0010r18\u0011 דְנ\"מ)\u0006. לִבָּה וְלִבָּתוֹ הָרוּחַ, חַיָּב. \u0005הַגָּה: \u0010y9\u0011 וְיֵשׁ אוֹמְרִים דְּאֵין הַמְלַבֶּה \u0010r19\u0011 חַיָּב אֶלָּא כְּשֶׁיֵּשׁ בַּלִּבּוּי שֶׁלּוֹ כְּדֵי לְלַבּוֹת, \u0010r20\u0011 וְאֵין בָּרוּחַ לְבַד כְּדֵי לְלַבּוֹת. \u0010r21\u0011 אֲבָל אֵין בְּכָל אֶחָד כְּדֵי לְלַבּוֹת, \u0010r22\u0011 אוֹ שֶׁיֵּשׁ בְּכָל אֶחָד כְּדֵי לְלַבּוֹת, פָּטוּר (טוּר שָׁם ובֵית יוֹסֵף בְּשֵׁם הָרַאֲבַ\"ד וְהָרֹא\"שׁ)\u0006. \u0010r23\u0011 וְיֵשׁ אוֹמְרִים דְּהוּא הַדִּין אִם שְׁנַיִם לִבּוּ וְאֵין בְּכָל אֶחָד כְּדֵי לְלַבּוֹת, פְּטוּרִין \u0005(מָרְדְּכַי פֶּרֶק הַכּוֹנֵס)\u0006. \u0010g28\u0011\nעָשָׂה הָאֶחָד הָאֵשׁ, וּבָא אַחֵר וְהוֹסִיף, אִם יֵשׁ בַּמֶּה שֶׁעָשָׂה הָרִאשׁוֹן כְּדֵי שֶׁתַּגִּיעַ לַמָּקוֹם שֶׁהָלְכָה, הָרִאשׁוֹן חַיָּב; וְאִם לָאו, \u0010r24\u0011 הָרִאשׁוֹן פָּטוּר וְהָאַחֲרוֹן \u0010g29\u0011 חַיָּב.\nהַכּוֹפֵף קָמָתוֹ שֶׁל חֲבֵרוֹ לִפְנֵי הַדְּלֵקָה, כְּדֵי שֶׁתַּגִּיעַ בָּהּ הַדְּלֵקָה, אִם כְּפָפָהּ בְּמָקוֹם שֶׁתּוּכַל הַדְּלֵקָה לְהַגִּיעַ בְּרוּחַ מְצוּיָה, חַיָּב לְשַׁלֵּם; וְאִם אֵינָהּ יְכוֹלָה לְהַגִּיעַ בְּרוּחַ מְצוּיָה, פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם. \u0010r25\u0011 \u0005וְאִם הָרוּחַ שֶׁאֵינָהּ מְצוּיָה כְּבָר מְנַשֵּׁב, וְאַחַר כָּךְ כְּפָפָהּ, חַיָּב בְּכָל עִנְיָן (הַמַּגִּיד הַנַּ\"ל)\u0006. \u0010g30\u0011\nגָּמָל שֶׁהוּא טָעוּן פִּשְׁתָּן, וְעָבַר בִּרְשׁוּת הָרַבִּים וְנִכְנַס פִּשְׁתָּנוֹ לְתוֹךְ הַחֲנוּת וְדָלְקָה בְּנֵרוֹ שֶׁל חֶנְוָנִי וְהִדְלִיק אֶת כָּל הַבִּירָה, בַּעַל הַגָּמָל חַיָּב, מִפְּנֵי שֶׁהִרְבָּה בַּמַּשּׂאוֹי, \u0010g31\u0011 \u0010r26\u0011 בֵּין שֶׁעָמְדָה הַבְּהֵמָה בֵּין שֶׁלֹּא עָמְדָה. וְאִם הִנִּיחַ הַחֶנְוָנִי נֵרוֹ מִבַּחוּץ, הוּא חַיָּב לְשַׁלֵּם אַף דְּמֵי הַפִּשְׁתָּן לְבַעַל הַגָּמָל, \u0010y10\u0011 \u0010c4\u0011 \u0010g32\u0011 \u0010r27\u0011 וַאֲפִלּוּ הוּא נֵר חֲנֻכָּה, שֶׁהָיָה לוֹ לֵישֵׁב וְלִשְׁמֹר שֶׁלֹּא יַזִּיק. \u0005הַגָּה: \u0010r28\u0011 וְיֵשׁ אוֹמְרִים דְּאִם הַדְּלֵקָה בְּמָקוֹם אֶחָד וְנִתְפַּשֵּׁט הָאֵשׁ לְמָקוֹם אַחֵר, חַיָּב עַל מְקוֹם הָאֵשׁ נֶזֶק שָׁלֵם וְעַל הַשְּׁאָר חֲצִי נֶזֶק. וְאִם הַגָּמָל סִכְסֵךְ הָאֵשׁ בְּכָל הַבִּירָה, חַיָּב עַל כֻּלּוֹ נֶזֶק שָׁלֵם \u0010g33\u0011 (טוּר ס\"ז)\u0006, וְעַיֵּן לְעֵיל סִימָן שצ\"ב חִלּוּקִין אֵלּוּ: \u0010y11\u0011 \u0010g34\u0011 \u0010r29\u0011\nטָמוּן בְּאֵשׁ, פָּטוּר. \u0010r30\u0011 שֶׁאִם הִדְלִיק גְּדִישׁ חֲבֵרוֹ וְהָיוּ טְמוּנִים בּוֹ אֲפִלּוּ מוֹרִגִּים \u0005(פֵּרוּשׁ, קְרָשִׁים נְקוּבִים וּבָהֶם יְתֵדוֹת שֶׁל עֵץ אוֹ שֶׁל בַּרְזֶל שֶׁדָּשִׁין בָּהֶם הַתְּבוּאָה)\u0006 וּכְלֵי בָּקָר \u0010y12\u0011 שֶׁדֶּרֶךְ לְהַטְמִינָם בַּגָּדִישׁ, פָּטוּר, \u0010r31\u0011 וְרוֹאִים מְקוֹם הַכֵּלִים הַטְּמוּנִים \u0010y13\u0011 כְּאִלּוּ הָיוּ שָׁם שְׂעוֹרִים אוֹ חִטִּים כְּפִי מַה שֶּׁהוּא הַגָּדִישׁ, וְכָךְ יְשַׁלֵּם לוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּמַדְלִיק בְּתוֹךְ שֶׁלּוֹ וְהָלְכָה וְדָלְקָה בְּשֶּׁל \u0010g35\u0011 \u0010r32\u0011 חֲבֵרוֹ וְכָלוּ חִצָּיו, כְּגוֹן שֶׁנָּפַל \u0010g36\u0011 הַגָּדֵר שֶׁבֵּינֵיהֶם שֶׁלֹּא מֵחֲמַת \u0010y14\u0011 הַדְּלֵקָה, וְהָיָה אֶפְשָׁר לוֹ לִגְדֹּר וְלֹא גָדַר. אֲבָל אִם הִדְלִיק בְּתוֹךְ שֶׁל חֲבֵרוֹ, אוֹ אֲפִלּוּ בְּתוֹךְ שֶׁלּוֹ וְלֹא כָּלוּ חִצָּיו, כְּגוֹן שֶׁנָּפַל הַגָּדֵר מֵחֲמַת הַדְּלֵקָה, חַיָּב בְּדָבָר שֶׁדַּרְכּוֹ לְהַטְמִין בַּגָּדִישׁ כְּגוֹן מוֹרִגִּים וּכְלֵי בָּקָר, כְּמוֹ שֶׁנִּתְבָּאֵר בְּסִימָן צ'. וּבְבַיִת \u0010c5\u0011 חַיָּב עַל כָּל דָּבָר, \u0010g37\u0011 \u0010r33\u0011 שֶׁדֶּרֶךְ בְּנֵי אָדָם \u0010t4\u0011 לְהַנִּיחַ בַּבַּיִת כָּל כְּלֵיהֶם וְכָל חֲפָצֵיהֶם, \u0010r34\u0011 וְכָל מַה שֶּׁיִּטְעֹן בַּעַל הַבַּיִת שֶׁהָיָה בַבַּיִת, \u0010y15\u0011 \u0010c6\u0011 \u0010g38\u0011 הֲרֵי זֶה נִשְׁבָּע בִּנְקִיטַת חֵפֶץ \u0010t5\u0011 וְנוֹטֵל, \u0010g39\u0011 וּבִלְבַד שֶׁיִּטְעֹן דְּבָרִים שֶׁהוּא אָמוּד בָּהֶם שֶׁהֵם שֶׁלּוֹ \u0010c7\u0011 אוֹ שֶׁרְגִילִים לְהַפְקִיד בְּיָדוֹ. \u0005וְע\"ל סִימָן צ'.\u0006 \u0010g40\u0011\nהַמַּשְׁאִיל מָקוֹם לַחֲבֵרוֹ לְהַגְדִּישׁ בּוֹ, וְהִגְדִּישׁ וְהִטְמִין בּוֹ כֵּלִים, וְהִדְלִיק הַמַּשְׁאִיל \u0010y16\u0011 \u0010r35\u0011 \u0005דְּהַיְנוּ שֶׁעָשָׂה הַמַּשְׁאִיל אֵשׁ וְיָצְאָה וְהִדְלִיקָה (טוּר)\u0006 וְשָׂרַף הַגָּדִישׁ וְהַכֵּלִים שֶׁבְּתוֹכָהּ, אֵינוֹ מְשַׁלֵּם אֶלָּא דְּמֵי גָדִישׁ בִּלְבַד. \u0010g41\u0011\nהִשְׁאִילוֹ מָקוֹם \u0010y17\u0011 לְהַגְדִּישׁ חִטִּים, וְהִגְדִּישׁ \u0010t6\u0011 שְׂעוֹרִים, אוֹ לְהַגְדִּישׁ שְׂעוֹרִים \u0010y18\u0011 וְהִגְדִּישׁ \u0010t7\u0011 חִטִּים, אוֹ שֶׁהִגְדִּישׁ חִטִּים \u0010y19\u0011 \u0010t8\u0011 וְחִפָּם בִּשְׂעוֹרִים, \u0010y20\u0011 אוֹ שֶׁהִגְדִּישׁ שְׂעוֹרִים \u0010t9\u0011 וְחִפָּם בְּחִטִּים, אֵינוֹ מְשַׁלֵּם לוֹ אֶלָּא דְּמֵי שְׂעוֹרִים בִּלְבַד. \u0010g42\u0011\nמִי שֶׁרָאָה דְּלֵקָה שֶׁמִּתְקָרֶבֶת לְקָמַת חֲבֵרוֹ, וְהָלַךְ וְכִסָה הַקָּמָה, אַף עַל פִּי שֶׁגָּרַם לוֹ הֶפְסֵד שֶׁהֲרֵי \u0010g43\u0011 עֲשָׂאוֹ טָמוּן, הֲרֵי זֶה פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם. \u0010g44\u0011\nאֵשׁ שֶׁעָבְרָה \u0010t10\u0011 וְהִזִּיקָה אֶת הָאָדָם \u0010y21\u0011 וְחָבְלָה בּוֹ, הֲרֵי הַמַּבְעִיר חַיָּב בְּנִזְקוֹ \u0010r36\u0011 וּבְשִׁבְתּוֹ \u0010y22\u0011 וּבְרִפּוּיוֹ וּבְצַעֲרוֹ \u0010t11\u0011 וּבְבָשְׁתּוֹ \u0010y23\u0011 כְּאִלּוּ הִזִּיקוֹ בְּיָדוֹ, \u0010g45\u0011 \u0005(שֶׁאַף עַל פִּי)\u0006 שֶׁאִשּׁוֹ מָמוֹנוֹ הוּא, \u0010y24\u0011 הֲרֵי הוּא כְּמוֹ שֶׁהִזִּיק \u0010t12\u0011 בְּחִצָּיו; \u0010g46\u0011 וְהוּא שֶׁהָיָה הָאֵשׁ רָאוּי לְהַגִּיעַ שָׁם לַמָּקוֹם שֶׁהִזִּיק בְּשָׁעָה שֶׁהִדְלִיק, אֲבָל אִם לֹא הָיָה רָאוּי לְהַגִּיעַ שָׁם, כְּגוֹן שֶׁהָיָה גָּדֵר בֵּינֵיהֶם וְנָפַל שֶׁלֹּא מֵחֲמַת הָאֵשׁ, אֲפִלּוּ אִם הָיָה אֶפְשָׁר לוֹ לְגָדְרָהּ, כְּבַר כָּלוּ חִצָּיו וְיֵשׁ לוֹ דִּין מָמוֹנוֹ שֶׁהִזִּיק אָדָם שֶׁאֵינוֹ חַיָּב אֶלָּא בְּנֶזֶק בִּלְבַד, \u0010y25\u0011 וּפָטוּר מֵאַרְבָּעָה דְבָרִים. \u0010g47\u0011\nהִנִּיחַ לַחֲבֵרוֹ גַּחֶלֶת עַל לִבּוֹ, וְנִשְׂרַף, פָּטוּר, \u0010g48\u0011 \u0010r37\u0011 אֲפִלּוּ הִתְרוּ בּוֹ; שֶׁלֹּא הָיָה סָבוּר שֶׁלֹּא יְסַלְּקֶנָּה, שֶׁאֵין דֶּרֶךְ שֶׁיַּנִּיחַ אָדָם עַצְמוֹ לִשְׂרֹף כְּדֵי \u0010g49\u0011 שֶׁיֵּהָרֵג חֲבֵרוֹ. אֲבָל אִם הִנִּיחַ גַּחֶלֶת עַל בִּגְדוֹ שֶׁל חֲבֵרוֹ וְנִשְׂרָף, \u0010y26\u0011 \u0010c8\u0011 חַיָּב, שֶׁאֵינוֹ \u0010t13\u0011 חוֹשֵׁשׁ לְסַלְּקוֹ כֵּיוָן שֶׁזֶּה חַיָּב לְשַׁלֵּם לוֹ. \u0010g50\u0011 וְעַבְדּוֹ כְּגוּפוֹ, וְשׁוֹרוֹ כְּבִגְדוֹ. \u0005הַגָּה: \u0010y27\u0011 \u0010r38\u0011 וְיֵשׁ אוֹמְרִים דְּעֶבֶד קָטָן דִּינוֹ כְּשׁוֹר (נִמּוּקֵי יוֹסֵף ס\"פ כֵּיצַד)\u0006. \u0010r39\u0011 וְיֵשׁ אוֹמְרִים דַּוְקָא בְּשׁוֹר \u0010t14\u0011 כָּפוּת, אֲבָל בְּשׁוֹר שֶׁאֵינוֹ כָפוּת, פָּטוּר \u0005(טוּר סי\"ד בְּשֵׁם רַשְׁבָּ\"א וְהָרֹא\"שׁ)\u0006.",{"g":["א) ל' הטור משנה ב' בריש ב\"ק","\u0003ב) שם בגמ' ה\"ד אי בהדי דאזלי מזקי היינו אש וכו'\u0004 שם דף ג' ע\"ב","ג) יתבאר בסי' י\"ג","ד) משנה שם בפ\"ו דף ס\"א ע\"ב","פירוש האש מעצמו","ה) משנה שם דף ס' ע\"א ושם בגמרא יליף לה מקרא","ו) שם במשנה דף ס\"א ע\"ב","ז) ל' הרמב\"ם בפי\"ד מהל' נזקי ממון דין ב' ושם במשנה פלוגתא דתנאי ואיפסקא הלכתא בגמ' כר\"ש דאמר הכי","\u0003ח) כדמפרש רב נחמן וכו'\u0004 שם","ט) שם ושם במשנה","י) משנה שם ע\"א וכתב הכ\"מ מדלא הזכיר אריתא דדלאי כדאמר שמואל שם משמע דס\"ל דרב ושמואל בנהר הרחב פליגי דלרב אפי' לית ביה מיא מפסיק ולשמואל לא מפסיק אלא בדאית ביה מיא ולא קרי ליה חריתא דדלאי אלא למימר דאית ביה מיא","כ) כ' ה' המגיד ברייתא שם ופירש רבי יוחנן שלולית אמת המים שמחלקת שלל לאגפיה ע\"כ והכ\"מ כ' שהוא פוסק כשמואל שם ומקום שמי גשמים שוללים ופירש רש\"י והערוך שמתקבצים שם","ל) כן הוא ברמב\"ם שלפנינו","מ) כ' הכ\"מ נראה שדעת רבינו שכל כיוצא בזה אפי' בדליקה גדולה פטור","נ) מפורש שם בגמ' וכפי' רש\"י והתוס' שם","ס) שם דין ג' וה\"ה והכ\"מ לא כתבו מאין יצא לו לחלק בגדר חילוק זה ולפענ\"ד למדו מברייתא שם עברה גדר גבוה ד\"א חייב ואע\"ג דשנינהו בגמ' תנא דידן קא חשיב מלמעלה למטה וכו' הוא אליבא דת\"ק אבל אנן דקי\"ל כר\"ש דאמר הכל לפי גובה הדליקה הברייתא כפשטה כשהדליקה גבוה","ע) שם ושם בגמרא וכתב ה\"ה ופירש קודחת שאין שלהבת גדולה ופסק כרב דאמר הכין ודלא כשמואל דתניא כוותיה דרב שם","פ) מבואר בפ' ט' דף כ\"ג ע\"א","פי' שהיה בינו לבין חבירו ולא היה ראויה להגיע שם מחמת הגדר","צ) שם דין ה' משנה שם בפרק ו' דף נט ע\"א","ק) פסק כריש לקיש משמיה דחזקיה שם משום דהוא רביה דרבי יוחנן וכן פסק הרי\"ף","ר) שם דין ו' ושם במשנה","ש) כתב ה\"ה יצא לו ז\"ל מדין שאר המזיקין דהשומרים נכנסים תחת הבעלים (ומבואר בסימן שצ\"ו וסי' ת\"י):","ת) שם דין ז' שם במשנ' וכתב הרב המגיד וכגון שהובערה ברוח מצויה תמיד והראשון פטור לפי שלא עשה כלום:","א) שכיון שלא היתה מתלבה מאלי' הראשוני' פטורים","\u0003ב) שם במשנה ליבתו רוח וכו'\u0004 ופירש בירושלמי ברוח שאינה מצויה","פירוש אע\"פ שהיא באה בעתים הרבה ואין צריך לומר רוח סערה שאינה נושבת אלא לעתים רחוקות וכן הוא בירושלמי וכן עיקר וה\"ה","ג) ברייתא שם דף ס' ע\"ב והראב\"ד השיגו שלא הפליג במ\"ש בברייתא אם יש בלבויו כדי ללבותו חייב ואם לאו פטור וכתב ה\"ה הייתי סבו' לתרץ דרבינו פסק כאחת מן האוקימתות דלכולהו דברי רבינו ז\"ל קיימין וכו' (ע\"ש בגמרא) ויפסוק רבינו דלא כרב אשי דאמר גרמא בנזקין פטור אלא שק' לי שרבינו ז\"ל עצמו פסק בפי\"א מה' שכנים (ומבואר בסי' קנ\"ה סעי ל\"ד) כאוקימת' דרב אשי וכו' וצל\"ע ע\"כ והכ\"מ כתב ליישב שטעם הפטור שם שאין הנזק בא מכח המזיק עצמו אבל בנדון דידן שהנזק בא מחמת עצמו שהוא מלבב נקטינן כאינך אמוראי כלהו דאמרי חייב ע\"כ ולפענ\"ד מ\"מ הוא דוחק לאוקמי דלא כרב אשי דהוא בתראה והרי\"ף הביאו לבדו נלע\"ד שהרמב\"ם מפ' מ\"ש בברייתא אם יש בליבויו כדי ללבותו היינו ברוח מצוייה ואם לאו פי' שאין בליבויו ללבותו אלא ברוח שאינו מצויה פטור וכמ\"ש התוס' בד\"ה רבא אמר וכו' ומקש' ואמאי הוי כזורה ורוח מסייעתו דחייב פי' אפי' ברוח שאינה מצויה כיון שכוונתו ללבות ומתרץ רבא כיון דסגי לה בזורה ורוח מסייעתו אפי' ברוח מצוי' כמו שפירש רש\"י לכן חייב שם אפי' ברוח שאינה מצויה משא\"כ בנזקין בשלא נתכוין אלא לרוח מצויה וכו' עוד יש אוקימתות אחריני דאמוראי שם ע\"ש ורב אשי תירץ דשאני לענין שבת דחייב אפי' ברוח שאינה מצויה ואפי' אם לא היתה מלאכתו נעשית ברוח מצויה מטעמא דמלאכת מחשבת אסרה תורה אבל לגבי ניזקין שאינו חייב אלא בשליב' ברוח מצויה ומעתה לא היה צריך לרבינו הרמב\"ם לפרש שפטור ברוח שאינה מצויה כי כבר כתב זה לעיל ס\"ק ב' מבואר במ\"ש שם ובפי' זה מצאתי בפי' נ\"י ברי\"ף שם במשנה שפי' כן בהג\"א שם בפ\"ב דב\"ב שפירשו בשם ר\"ת וריב\"ם דהא דחייב בשבת אפילו ברוח שאינה מצויה אלא שמחייבו שם דעושה גורן ברוח מצויה ורבינו פוטר שם מטעם שכתב הכ\"מ זה נלע\"ד לדעת הרמב\"ם ברור ואמת","ד) טור ס\"ה מבואר בפ\"ק דב\"ק דף י' ע\"א והאיכא מרבה בחבילות וכפרש\"י ויש לרמב\"ם פי' אחר בזה מבואר לעיל סי' שפ\"ג ס\"ד","\u0003ה) שם סעיף ו' וברמב\"ם שם דין י\"ד ברייתא וגמרא שם בפ\"י ריש דף נ\"ו:\u0004 ","ו) לשון הרמב\"ם שם דין י\"ג משנה שם דף ס\"ב ע\"ב","ז) כתב ה\"ה מתבאר שם בפ\"ב (דף ב\"ב פ\"א)","ח) שם במשנה דף ס\"ב וכת\"ק אע\"פ שהוא מצו' להניחם בחוץ","ט) וכ\"כ ה\"ה שם בפרק י\"ד מה' נזקי ממון בשם המפרשים ונתלו בסוגיא שם דף ב\"ב ע\"א והרמב\"ם כתב המשנה כפשטה","י) ל' הטור ס\"ח משנה שם בפ' ו' דף ס\"א ע\"ב וכחכמים באוקימת' דרבא שם","כ) החילוק בין כלו חציו ללא כלו חציו מבואר בפ\"ב דף נ\"ג ע\"א והרמב\"ם שם דט\"ו ולא חילק בזה וה\"ה שם תמה בזה וכתב אולי שרבינו מפרשה בפנים אחרות ואפשר שדעתו ז\"ל שאין להניח פשט השניות והברייתות והמימרות שלא חלקו בטמון מפני הסוגיא ההיא:","ל) מבואר במ\"ש לעיל ס\"ז","מ) ל' הרמב\"ם שם דין י\"ב","נ) ומפורש בגמרא דף ס\"ב ע\"א","ס) כדא\"ל רב אשי לרב יימר שם","ע) שם די\"א ברייתא שם ומודה ר' יהודה לחכמים","פ) שם ושם בברייתא","צ) טור ס\"ו וברמב\"ם שם די\"ד מברייתא ומימרא דרב אשי טמון איתמר שם דף נ\"ו ע\"א","פי' וגרם לו שנפטר המבעיר טור","ק) לשון הרמב\"ם שם דט\"ו וכתב ה\"ה מפורש בפ\"ב (דף כג ע\"א) בפלוגתא דרבי יוחנן ופסק כרבי יוחנן","ר) כן הוא ברמב\"ם שם","ש) טור סי\"א ומונא הדין זה ומ\"ש ה\"ה על הרמב\"ם שלא חילק בזה כתבתי לעיל ס\"ג","\u0003ת) שם סי\"ב מימר' דרבה בפ\"ב דף כז ע\"א:\u0004 ","א) כן כתב הרא\"ש שם בפסקיו","ב) שם במימרא הנזכר וכתב הסמ\"ע שנ\"ל שה\"ה אם אמר לחש\"ו קרע בגד שמעון והחש\"ו קרעו לפני שמעון והוא שותק דחייב משלח מה\"ט","ג) בעי' דאיפשטא וכפרש\"י שם שהי' לי לעבד לסלק והשור אין בו דעת לסלקו ועיין מ\"ש לעיל בזה סימן שפג"],"t":["\u0003חבירו. \u0004 דכיון שהדליק מתחלה שלא ברשות חייבוהו על הכל. סמ\"ע:","\u0003כראוי. \u0004 עיין ביש\"ש סי' כ\"ח מה שהקשה ע\"ז ממ\"ש בס\"ד ויש ליישבו ודו\"ק וע\"ש. ש\"ך:","\u0003ורחבם. \u0004 וכ\"פ מהרש\"ל שם ועיין שם טעמו ואין כדאי בטעמו לדחות דברי הרא\"ש והטור. שם:","\u0003הרוח. \u0004 עיין בש\"ך שהאריך ליישב דעת הרמב\"ם בזה ע\"ש:","\u0003להניח. \u0004 משמע אם אין דרך להניחו אפילו ידוע שהיה שם פטור ויש להקשות דהא בר\"ס שפ\"ח משמע להדיא דבידוע שהיה שם אפילו אין דרכו להניח שם חייב וצ\"ל דהתם מיירי במזיק בידים אבל הכא אע\"ג דמיירי שהדליק בתוך של חבירו היינו בפשיעה ולא בידים וכן נ\"ל מתוך דברי מהרש\"ל פרק הכונס סי' ל\"ב ע\"ש דנראה שיש חסרון בדבריו שם וכצ\"ל ומדליק בתוך של חבירו נמי דפטרי רבנן כל מה שאין דרכו להניח היינו מדליק בפשיעה דאילו מדליק בידים פשיטא שחייב על הכל ודוק. ש\"ך:","\u0003ונוטל. \u0004 פירוש אע\"פ שאין עדים בדבר שכך וכך היה לו בבית עיין בד\"מ שכת' בשם המ\"מ אם היו מחולקים בדבר הנשרף לו בגלוי שהניזק אומר כך וכך היה והמזיק אמר ברי לי שלא היה אלא כך אפילו הכי הניזק נשבע ונוטל דעשו תקנת נגזל גם בנשרף עיין שם וע\"ל סי' צ' מקור דין נשבע ונוטל בענינים אלו עכ\"ל הסמ\"ע וז\"ל הש\"ך ומיירי שיש עדים על הדליקה וכן הוא במ\"מ להדיא ובזה ניחא דלא תקשי ממ\"ש לעיל ר\"ס שפ\"ח המזיק ממון חבירו כו' או לאש כו' והמזיק אומר איני יודע כו' הרי הניזק נשבע בנק\"ח ונוטל כו' דמשמע הא אם טוען המזיק ברי אין הניזק נשבע ונוטל דהתם מיירי שאין עדים שהזיקו אם כן נאמן במיגו כל זה צ\"ל לדעת המ\"מ והסמ\"ע אבל באמת נראה לי עיקר דהרמב\"ם והמחבר סבירא להו כהי\"א שהביא הה\"מ דבאש אם טוען המבעיר ברי נשבע ונפטר והדעת נותנת כן וכן משמע להדיא מדברי מהרש\"ל שם ס\"ס ל\"ג ע\"ש וכ\"כ עוד שם סי' ל' וז\"ל דהא דאמרינן דעשו תקנת נגזל באשו לא איירי בכופר המבעיר דמ\"מ לא הוי רשע כגזלן ודוקא מוסר ראוי לדמותו לגזלן אבל לא מזיק אפי' להכעיס כו' עכ\"ל וכן מוכח להדיא בהרא\"ה פרק הכונס כו' ע\"ש:","\u0003שעורים. \u0004 וא\"ת פשיטא איך ישלם טפי ממה שהזיק יש לו' דקמ\"ל דל\"ת דליחייב אמוריגין שהטמין בתוכו כאילו היה חטים וכדין מוריגין שטמון בגדיש של חטים והרי נתן לו רשות לחטים. סמ\"ע:","\u0003חטים. \u0004 די\"ל לא קבלתי עלי אלא שמירת שעורים. שם:","\u0003וחיפם. \u0004 אע\"ג דנתן רשות לחטים י\"ל לא ראיתי לפני אלא שעורים. שם:","\u0003בחטים. \u0004 רש\"י פירש בזה דנתן לו רשות להגדיש שעורים ולא חטים וצ\"ל דאשמועינן בזה דל\"ת דוקא ברישא שהשאילו להגדיש שעורים והגדיש חטים ששינה מדעת המשאיל לגמרי הוא דפטור מחטים משא\"כ זה שהגדיש שעורים ליחייב לפחות גם אחיפוי חטים קא משמע לן. שם:","\u0003והזיקה. \u0004 ואם מת מכח הבעירה חייב עליו מיתה כאילו ירה בו חץ וכן כת' הטור. שם:","\u0003ובבשתו. \u0004 אע\"ג דיתבאר בר\"ס תכ\"א דאינו חייב על הבושת עד שיכוון לביוש הכא נמי כיון דעברה הדליקה ברוח מצויה ה\"ל כאילו ידע וכוון לכך אבל רש\"י והר\"ן כתבו בפרק כיצד הרגל דפטור בזה מבושת והביא ראיה מההיא דנפל מהגג שבסי' תכ\"א סי\"א ולדעת המחבר צ\"ל דשאני התם דנפילתו מהגג מחשב לאונס טפי מהדליק אש ויצא והזיק לאדם והרא\"ש והטור סתמו בדין זה וכתבו דחייב בד' דברים ונ\"ל דס\"ל גם כן דחייב בבושת וד' דברים חוץ מנזק קאמרי דנזק חייב בפשיעה לכ\"ע אף אם לא היה בו משום חציו אלא משום ממונא. שם:","\u0003בחציו. \u0004 פירוש לענין להתחייב עליו בד' דברים וגם מיתה אם מת מחמת האש אבל ג\"כ לא גרע משור ובור שהן ממונו וחייב עליהן לפחות נזק ונ\"מ דאפילו היכא דאינו חייב משום חציו כגון שלא היה לו לעבור מ\"מ חייב משום ממונא וכדמסיק. שם:","\u0003חושש. \u0004 ונראה דה\"ה אם ראובן אמר לשליח שאינו בר חיובא כגון חש\"ו קרע בגד שמעון והחש\"ו קרעו לפני שמעון ושתק דחייב ראובן המשלח מה\"ט שלא חשש שמעון למחות בידו עכ\"ל הסמ\"ע ודבריו תמוהין דהא תנן השולח את הבעירה ביד חש\"ו פטור ועיין בפ\"ק דב\"מ דף י' בתוספות שם ועיין מה שכתבתי בר\"ס קפ\"ב ורצ\"ב ושמ\"ח. ש\"ך:","\u0003כפות. \u0004 עמ\"ש בזה הסמ\"ע כאן ובר\"ס שפ\"ג ע\"ש:"],"r":["\u0003אש כו' דכתיב כו'. \u0004 ערש\"י ריש ב\"ק ד\"ה ארבעה כו'.","\u0003והוא כו' שהולך כו' לפיכך כו'. \u0004 ג' ב' וערש\"י שם ד\"ה ברוח מצוייה כו':","\u0003דין. \u0004 ה' ב':","\u0003כתיב כו'. \u0004 ס' ב':","\u0003שהדליק כו'. \u0004 רש\"י שם ד\"ה פתח כו' וכמש\"ש ס\"א ב' ועתוס' שם סד\"ה אלא. ורבין במדליק בתוך כו':","\u0003אפי' לא כו'. \u0004 מתני' ס' א' וגמ' שם ואי כתב כו' שדה ל\"ל כו':","\u0003וכ\"ז כו'. \u0004 ממ\"ש במתני' שם המדליק בתוך שלו. הרא\"ש וכן ית' מדברי הרי\"ף שכ' בגמ' שם ואי קשיא לך מ\"ש התם גבי תנור דקא יהבי רבנן שיעורא ואפ\"ה אם הזיק משלם מה שהזיק ומ\"ש הכא כו' ותי' דהכא כיון דלפי שעה קמדליק וקעברה יתיר משיעורא אנוס הוא ומאי ה\"ל למיעבד כו' ע\"ש משא\"כ כה\"ג דפושע הוא:","\u0003שזו מכה כו'. \u0004 כ\"ה דברי הרי\"ף הנ\"ל לתרץ מ\"ש הכא דקי\"ל כר\"ש ומ\"ש התם בב\"ב דלא קי\"ל כר\"ש וכנ\"ל וכ' וראיה דהא רבנן פליגי על ר\"ש שם והכא אינהו גופייהו יהבי שיעורא:","\u0003עברה נהר כו'. \u0004 מפ' דרב ושמואל פליגי וה' כשמואל:","\u0003וי\"א כו'. \u0004 כפי' דל\"פ:","\u0003אפי' כ\"ש. \u0004 כ\"כ הטור וצ\"ע דהא בברייתא תני ח\"א והרא\"ש ל\"ק אלא דביש בו מים א\"צ נהר אלא ה\"ה אריתא:","\u0003עברה גדר כו'. \u0004 מפרש דמש\"ש ב' רש\"א הכל כו' קאי גם אמתני' ראשונה אבל לא אנהר דזה לאו משום שיעורא הוא דהא בח\"א סגי וראיה מדשקלא וטריא רב ושמואל לפרושי נהר אע\"ג דשמואל פ' כר\"ש:","\u0003 (ליקוט) בד\"א כו' אין לה אומד כו'. \u0004 מ' דקאי אדסמיך אגובה וכן מ' ממ\"ש למעלה דאם הרחיק כשיעור פטור ולא חילק אבל תוס' ורא\"ש וש\"פ כ' ג\"כ ארוחב דברייתא דקא' אפי' מאה מיל ע\"כ קאי ארוחב ע\"ש ושם ושיטת הרי\"ף דאין חילוק כלל בין קולחת לנכפפת דקי\"ל כר\"ש (ע\"כ):","\u0003 (ליקוט) באש הקודחת. \u0004 כ' הסמ\"ג והג\"מ שכ\"ה הגי' בספרים ישנים. וכ\"ה בירוש' שם (ע\"כ):","\u0003בד\"א בשמסר כו'. \u0004 עבה\"ג ולא מני ליה בהדי הנך ג' דהלכה כר\"ל משום דקא' משמיה דרביה כמו שלא חשיב הא דחולין ך\"ט ב' ועתוס' שם ד\"ה אר\"ל כו'. וכן סוגיא דפ\"ק ט' ב' כר\"ל דקא' והאר\"ל כו' ול\"ק הניחא לר\"י אלא כו':\n\u0003 (ליקוט) בד\"א כו'. \u0004 כר\"ל וערש\"י ך\"ב ב' ד\"ה ור' יוחנן כו' ולקמן מסקינן דר\"י מודה לר\"ל וע\"כ צ\"ל דר\"י חזר בו. אבל תוס' שם בד\"ה חציו כ' והא דפוטר כו' (ע\"כ):","\u0003וכן אם כו'. \u0004 ממש\"ש כיצד מסר כו' ומ' לשומרן ומ' דבפקח בכולן פטור:","\u0003שאינה מצויה כו' ואם כו'. \u0004 דרוח מצויה כהזיק בידים כמ\"ש באבני סכינו ומשאו וכן בכופף קמת חבירו בפני הדליקה וכמ\"ש בירושלמי הביאו תוס' שם סד\"ה לבתה דגרסי' התם כו' שפעמים כו' ר\"ל רוח שאינה מצויה:","\u0003וכן אם כו'. \u0004 תוס' בא\"ד הנ\"ל וז\"ש רבא בגמ' כגון שליבה ברוח מצויה כו' ר\"ל דמעיקרא ס\"ד שכבר היה הרוח שא\"מ ולא תי' שבא אח\"כ רוח מצויה משום דחייב בכה\"ג כנ\"ל:\n\u0003 (ליקוט) ואם הרוח מצויה כו' וכן אם כו'. \u0004 קאי אשני בבות הראשונות ולא מיירי בליבה הוא ג\"כ שאח\"כ כ' ליבה וליבתה כו' ודינו מפורש בהגה דלמטה וי\"א דאין כו' ושם אין חילוק בין מנשב בתחלה או אח\"כ דברישא שיש בליבויו ולא ברוח חייב אפי' בא אח\"כ רשא\"מ כמש\"ש רבא אמר כו' ואפ\"ה חייב וכן הפטור בכ\"ע הוא (ע\"כ):","\u0003ליבה כו'. \u0004 שם רב אשי אמר כו' והרמב\"ם לשיטתו דס\"ל דלא קי\"ל כר\"א דגרמא פטור כמ\"ש בסי' שפו וז\"ש בכתובות פ\"ו ח' כפייה כו'. אבל תוס' והרב חלקו שם עליו וז\"ש כאן וי\"א כו' ומה שהקשו על הרמב\"ם ממ\"ש בסי' קנה סל\"ד עש\"ך:\n\u0003 (ליקוט) ליבה כו'. \u0004 ול\"ד למ\"ש בסי' קנה סל\"ד כמ\"ש בב\"ב כו א' ולרבינא כו' התם ניחא כו' וה\"נ דמיא לגץ דניחא ליה דליזל אלא שרב אשי מחלק בינה לגץ כמ\"ש תוס' בב\"ק שם בד\"ה רב כו' וגץ כו' אבל אנן לא קי\"ל כרב אשי בזה וכן הוא שיטתו של הרמב\"ם דגרמי אינו חייב אלא במתכוין משא\"כ שם (ע\"כ):","\u0003אלא כשיש כו'. \u0004 גמ' הנ\"ל:","\u0003ואין כו'. \u0004 תוס' שם ד\"ה ליבה כו':","\u0003אבל אין כו'. \u0004 גמ' הנ\"ל:","\u0003אי כו'. \u0004 תוס' הנ\"ל:\n\u0003 (ליקוט) או שיש בכ\"א כו'. \u0004 תוס' שם ד\"ה ליבה כו' והרא\"ש וטור אבל הרשב\"א חולק ע\"ש (ע\"כ):","\u0003וי\"א כו'. \u0004 עתוס' שם ד\"ה והכא כו':","\u0003הראשון פטור. \u0004 עמ\"ש בסי' שצו ס\"ז:","\u0003ואם הרוח כו' \u0004 כנ\"ל ס\"ט:","\u0003בין כו'. \u0004 דלא מפליג שם אלא לר\"ל:","\u0003ואפי' כו'. \u0004 עמ\"ש בסי' תיד:","\u0003וי\"א כו. \u0004 כמש\"ש בשלמא לר\"י כו' הב\"ע כו' וא\"כ גם לר\"י נ\"מ לענין ח\"נ דהא צרורות הוא וכמש\"ש ועל הגדיש כו':","\u0003טמון כו'. \u0004 דסוגיא ה' ב' נו א' וש\"מ כת\"ק:","\u0003שאם הדליק כו' בד\"א כו'. \u0004 שם בתרת פליגי כו':","\u0003ורואים כו'. \u0004 ברייתא שם:","\u0003 (ליקוט) וכלו חיציו כו'. \u0004 אבל הרמב\"ם וסמ\"ג לא כ' כ\"ז ודבריהם נכונים דודאי כל הסוגיות מוכיחין דטמון פטור בכ\"ע וכן באותו קרא שמחייב משום חציו פוטר טמון וכן הקושיא שם דפריך וכי מאחר כו' מאי בינייהו הוא תמוה מאד דהא עכשיו קאמר דאינו פטור לר\"י בטמון אלא בנפלה כו' ומאי פריך אף שתוס' כ' דהמ\"ל כו' מ\"מ בטמון שמדבר בזה עתה א\"א להקשות וכי מאחר כו' אלא דהשתא דקאמר אלא למאן דאית כו' חוזר ממ\"ש בתחלה כגון שנפלה כו' ולכן קאמר אלא ור\"ל דמה שחייבה תורה על חציו דאש מה שלא גדר אח\"כ דהא י\"ל מאי קאמר טמון כו' היכא משכחת לה ול\"ק טמון אמאי פטרה תורה אלא דה\"ק משום דאמרינן בסוף הכונס דלא פטרה תורה אלא במדליק בתוך שלו כו' ואי הוי כזורק חץ על של חבירו א\"כ לעולם הוא מדליק בתוך של חבירו ומשני אלא כו' שה\"ל לגודרה כו' ור\"ל מש\"ה פטרה תורה בשלו דעדיין היה יכול לגודרה אחר שיצא האש ולכן פריך מאי בינייהו ומשני בד' דברים דבד' דברים וכיוצא אינו פטור מחמת שהיה יכול אח\"כ לגודרה כמו בזרק חץ על האדם או ש\"ד אע\"ג שיכול להגן אח\"כ משום זה אינו פטור רק בטמון שגילתה תורה וכ\"ה בדברי רי\"ף א\"ה טמון כו' אלא כו' ונראה דהאי כגון ל\"ד דלעולם יכול לגודרה ולכן ל\"ק דא\"ב כה\"ג בטמון שא\"י לגודרה ולכן השמיטו הרמב\"ם ג\"כ ונראה דל\"ג כגון אלא שה\"ל כו' ועבה\"ג אבל מ\"מ בההוא דס\"ו מודה הרמב\"ם אלא דלעולם אפשר הוא (ע\"כ):","\u0003שדרך ב\"א להניח בבתים. \u0004 כמ\"ש במתני' שכן דרך ב\"א כו' מ' דוקא דבר שדרכו בכך וכמ\"ש בגדיש דוקא מוריגים כו':","\u0003וכל מה כו'. \u0004 שם עשו תקנת כו' ופי' אע\"ג דאין ה' כר\"י מ\"מ נ\"מ לרבנן בכה\"ג ועתוס' שם ד\"ה לר\"י כו':","\u0003דהיינו כו'. \u0004 תוס' ד\"ה שאינו כו'. ונראה דגם בסט\"ו הדין כ\"ה וכ\"מ בתוס' הנ\"ל:","\u0003ובבשתו. \u0004 ורש\"י כ' דפטור מבשת ועסמ\"ע:\n\u0003 (ליקוט) חייב בנזקו כו'. \u0004 רש\"י וש\"פ פי' דפטור על הבשת אבל בירושלמי פ\"ק אתמר בהדיא מקבל עליו נזק צער ריפוי שבת ובשת (ע\"כ):","\u0003אפי' התרו כו'. \u0004 דבלא התראה בלא\"ה פטור:","\u0003וי\"א דעבד כו'. \u0004 שאין בו דעת לסלקו והיינו כפירש\"י באינו כפות:","\u0003וי\"א כו'. \u0004 תוס' כב ב' ד\"ה והיה. וההיא כו' וכ\"פ שם כז א' ד\"ה הניח כו' אבל הרשב\"א ונ\"י כ' דאף לפי שיטתם דוקא לברוח ה\"ל. אבל לא ה\"ל ליטלה וכפרש\"י ס\"א ב' וע\"ל ר\"ס שפג:"]}],["\u0010c0\u0011 כְּשֶׁבֵּית דִּין נִזְקָקִין לִגְבּוֹת לַנִּזָּק מִנִּכְסֵי הַמַּזִּיק, \u0010y0\u0011 \u0010c1\u0011 גּוֹבִין מֵהַמִּטַּלְטְלִין תְּחִלָּה, וְאִם לֹא הָיוּ מִטַּלְטְלִין כְּלָל, אוֹ שֶׁלֹּא הָיוּ לוֹ מִטַּלְטְלִין כְּנֶגֶד כָּל הַנֶּזֶק, גּוֹבִין הַשְּׁאָר מֵהַקַּרְקַע הַמְעֻלֶּה שֶׁבְּנִכְסֵי הַמַּזִּיק; וְכָל זְמַן שֶׁיִּמְצָא מִטַּלְטְלִין, וַאֲפִלּוּ סֻבִּין, אֵין נִזְקָקִין לַקַּרְקַע. \u0010c2\u0011 וַאֲפִלּוּ שֶׁיֵּשׁ לוֹ כֶּסֶף, יָכוֹל לְפוֹרְעוֹ בְּסֻבִּין, דְּכָל מִטַּלְטְלִים מֵיטַב נִינְהוּ. וְשָׁמִין אוֹתָהּ \u0010y1\u0011 כְּמוֹ שֶׁיָּכוֹל לְמוֹכְרָהּ מִיָּד וּבִמְקוֹמוֹ. וּכְשֶׁמְּשַׁלֵּם מֵהַקַּרְקַע, אֲפִלּוּ הָיְתָה זִבּוּרִית שֶׁל מַזִּיק טוֹבָה מֵעִדִּית שֶׁל נִזָּק, אֵינוֹ מְקַבֵּל מִמֶּנּוּ, אֶלָּא מַגְבִּין לוֹ \u0010y2\u0011 מֵעִדִּית שֶׁבְּנִכְסֵי הַמַּזִּיק.\nאִם יֵשׁ לַמַּזִּיק שְׁנֵי עִדִּית, אֵין הַנִּזָּק יָכוֹל לוֹמַר לוֹ: תֵּן לִי מֵעִדִּית פְּלוֹנִי, אֶלָּא תָּלוּי בִּרְצוֹן הַמַּזִּיק לָתֵת לוֹ אֵיזֶה שֶׁיִּרְצֶה. אֲבָל אִם הַמַּזִּיק חָפֵץ לָתֵת לוֹ הָעִדִּית שֶׁבִּקֵּשׁ, אֶלָּא שֶׁהִיא עַתָּה בְּזוֹל וּמַמְתִּין עַד שֶׁתִּתְיַקֵּר, וְאוֹמֵר: אִם תִּרְצֶה אוֹתָהּ קַח אוֹתָהּ כְּפִי מַה שֶּׁהִיא עֲתִידָה לְהִתְיַקֵּר, אֵין שׁוֹמְעִין לוֹ, אֶלָּא \u0010c3\u0011 צָרִיךְ לִתְּנָהּ לוֹ \u0010y3\u0011 כְּפִי מַה שֶּׁשָּׁוָה עַתָּה.\nמֵת הַמַּזִּיק קֹדֶם שֶׁיִּפְרַע, \u0010c4\u0011 מַגְבִּין \u0010y4\u0011 \u0010c5\u0011 לַנִּזָּק מֵהַמִּטַּלְטְלִין שֶׁל יְתוֹמִים; וְאִם לֹא הִנִּיחַ מִטַּלְטְלִין, מַגְבִּין לוֹ מִזִּבּוּרִית שֶׁבְּקַרְקְעוֹתָיו, \u0010c6\u0011 \u0010c7\u0011 \u0010c8\u0011 \u0010c9\u0011 שֶׁכָּל הַבָּא לִפָּרַע מִנִּכְסֵי יְתוֹמִים, לֹא יִפָּרַע אֶלָּא מֵהַזִּבּוּרִית:",["\u0003גובין מהמטלטלין תחלה. \u0004 עד\"ר שם כתבתי ל' הגמרא והוכחתי ממנה דאף בהלוא' [דבהלוא'] יד המלוה על העליונה דאם יש ללוה כסף או מטלטלין צריך לשלם ממנו ולאו כל כמיניה לשלם לו מקרקע אפי' מעידית ה\"ט דהמלוה הלוה לו מעות מ\"ה דינו ג\"כ במעות או במטלטלין שקרובים למעות שיכולין לטלטלן ולמכרם אפי' במקום אחר אי לא מזדבני בהאי מתא אבל בניזק יד המזיק על העליונה שאף אם יש לו כסף או מטלטלי אם ירצה לשלם בקרקע צריך הניזק לקבלן אך שיתן לו מעידית שבנכסיו וזהו כוונת רב פפא שאמר בגמ' בישוב הקושיא שהקשו שם בפי' מיטב שדהו ומיטב כרמו ישלם מיטב אין מידי אחריני לא והתניא ישיב לרבות שוה כסף ואפי' סובין ומשני רב פפא דביש לו מטלטלין ובא לפרוע מהם אינהו מקרי מיטב דאי לא מזדבני בהאי מתא מזדבני במתא אחריתי ואם בא לשלם מקרקעותיו צריך לשלם ממיטב שדותיו ועד\"ז פירשתי ג\"כ דעת הטור וכן יש לפרש ג\"כ דעת המחבר ומ\"ש גובין מהמטלטלין תחל' היינו משום דמסתמא ניחא למזיק לשלם במטלטלין מבקרקעות שהוא בר קיימא ומ\"ה קאמר כשב\"ד נזקקין משלמין מהמטלטלין ולמדונו דאף אם אין המזיק לפנינו לגלות דעתו לשלם במטלטלים אמרינן דמסתמא ניחא למזיק לשלם ממטלטלים ואף אם הניזק צועק לשלם לו מקרקעות כמשמעות הקרא ממיטב שדהו אין ב\"ד שומעין לו אבל ודאי אם המזיק גיל' דעתו דניחא ליה טפי במטלטלים ורוצה לשלם לו בקרקעות והניזק רוצה דוקא במטלטלין יד המזיק על העליונה ול\"ד למלוה ולוה ומטעם שכתבתי וק\"ל ולא כב\"י והע\"ש נמשך אחריו שכ' ז\"ל דאי בעי הניזק מטלטלים צריך המזיק ליתן לו כו' ע\"ש אבל אני הוכחתי דלע\"ד לא עלתה על דעתו דהטור כן עיין שם בדרישה:","\u0003כמו שיכול למוכרם מיד כו' \u0004 ע\"ל סי' ק\"א וק\"ג מ\"ש בביאור זה:","\u0003מעידית שבנכסי המזיק. \u0004 דכתי' מיטב שדהו ישלם ודרשינן דהיאך דמשלם דהיינו המזיק","\u0003כפי ששוה עתה \u0004 וכ\"כ הטור ועפ\"ר שם כתבתי דל\"ד למלוה שדינו להשתלם מהלוה בבינונית וכשהוא אומר להלוה פרע לי מעידי' שלך בציר פורתא וגם הלוה נתרצה לשלם לו מהעידית רק שא\"ל קח אות' כיוקרא דלקמי' דפסק הטור כהרא\"ש בסי' ק\"כ [ק\"ב] דהדין עם הלוה דצריך לקבל כיוקרא דלקמיה ולא כמו שהוא שוה עתה שאני התם דאין דין המלוה להשתל' מהעידי' כלל אבל ניזק דדינו להשתלם מהעידית אלא שיפו חז\"ל כח המזיק ליתן לו מאיזה עידית שהוא רוצה ולשייר החביב לפניו וכיון שהוא גילה דעתו שאינו מבקש לקיים זו לפניו אלא שרוצה להעלות להניזק בדמים כיוקרא דלקמיה העמידהו על דינו לשלם ממיטב ממש וכזולא דהשתא ולא כע\"ש דכ' דברי המחבר וכ' עליהן ז\"ל ונ\"ל דלא נאמרו דברים הללו אלא כשיש למזיק עידית ובינונית ואומר הניזק תן לי בינונית טפי פורת' כו' עד אבל בשניהן עידי' אפי' אם המזיק גילה דעתו שאינו רוצה להעמיד בידו אותו עידית שמבקש הניזק א\"צ ליתן לו כזולא דהשתא דמ\"ש זה מכשיש בידו כסף וסובין דאמרי' בסעיף א' דיכול ליתן לו סובין משום דמטלטלי כל מילי מיטב הוא ויכול ליתן איזה שירצ' ה\"נ הא שניהם מיטב הוא ויכול ליתן לו איזה שירצה ומהתימא שהטור גם מהרי\"ק ז\"ל בש\"ע לא דקדקו בזה וצ\"ע עכ\"ל עיר שושן ומהתימא דלפי סברתו הו\"ל להקשות דברי הטור והמחבר אהדדי מכאן למ\"ש בסי' ק\"ב הנ\"ל. ועוד מאי מייתי ראי' מכסף וסובין הלא י\"ל דכמו שהן מחולקין ביש לו שני מיני עדות כתבו דהרשות בידו ליתן איזה שירצה ואפ\"ה כתבו דכשגיל' דעתו שאינו מבקש להעמיד הטוב' יות' לפניו צריך ליתנו לו כזולא דהשתא. א\"כ גם בכסף וסובין נאמר כן. גם י\"ל דמ\"ה לא אמרו בהדיא בכסף וסובין דאם גיל' דעתו כו' דנותן לו מהכסף כזול' דהשתא משום דלא שייך בכסף כיוקרא דלקמיה וזולא דהשתא דכל הזמנים שוים בדמי שוויה דהכסף משא\"כ בקרקע שבימי הקיץ שהן עומדין לזרוע ולאכול מהן פירות הן יקרים טפי מכשהן בימי הגשמים וכמבואר בי\"ד סי' רנ\"ג ע\"ש:","\u0003מהמטלטלים של יתומים. \u0004 בטור מפורש דמיירי לאחר תקנת הגאונים דתקנו דמלוה גובה ממטלטלים דיתמי וה\"ה מזיק וגם לענין זה מזיק שוה למלוה דבא לגבות מנכסי יתמי לוה דאינו גובה אלא מהזיבורית אף דהלוה הי' צריך לשלם מבינונית ה\"נ בניזק שבא לגבות מיתמי המזיק. וצ\"ע דכאן סתם המחבר ומשמע דס\"ל דאפי' אם בא לגבות מיתומים גדולים אינו גובה אלא מהזיבורית והמ\"מ בפ\"ה דנ\"מ כתב שכן הוא דעת הרמב\"ם ושהרשב\"א חילק בין קטנים לגדולים ולעיל ס\"ס ק\"ח פסק המחבר גופו כן לחלק בין קטנים לגדולים ומטעם שכתבתי שם בסמ\"ע והוא כדעת הרא\"ש וה\"ר יונה וכמו שכתב הטור שם והא דבסי' זה סתם הטור ג\"כ וכתב דאין מגבין לניזק ממטלטלי דיתמי דאינן משועבדין לב\"ח אלא מקרקעותיו ומהזיבורית שבהן י\"ל שאגב שכ' החילוק שבין אם בא לגבות מהמזיק עצמו לבא לגבות מיתומים לענין מטלטלין כ' ג\"כ החילוק שביניהן לענין זיבורית ומיירי דוקא בקטנים ולולי דעת המ\"מ הנ\"ל הייתי אומר שגם דעת הרמב\"ם כן ששם בפ\"ח דנ\"מ כתב כל' הטור שבכאן אבל ל' המחבר שבכאן דגובין ממטלטלין א\"א לפרש כן וצ\"ע:"],["\u0003 כשב\"ד נזקקין כו'. \u0004 עיין ביש\"ש פ\"ק דב\"ק סימן ט\"ז פסק דניזקין גובין ממשועבדים אף שלא עמד בדין דיש קול לניזקין וכן משמע בתוס' פ\"ק דב\"ק דף י\"ד ע\"ב לפי' ר\"ת כפי מאי דס\"ל שעבודא דאורייתא וכ\"כ ר' ירוחם נתיב ל\"א ח\"א בסופו וכ\"כ הרב המגיד פי\"ט מה' מלוה בשם יש מפרשים וכ\"כ הסמ\"ע לעיל סי' קי\"ט ס\"ק י\"ד מיהו יש חולקין ועיין מה שכתבתי לעיל סי' ס\"ו סעיף ל\"ה [ע\"ד הסמ\"ע] ס\"ק פ\"ג:","\u0003 גובין מהמטלטלים תחלה כו'. \u0004 כ' הסמ\"ע דהיינו משום דמסתמא ניחא למזיק לשלם במטלטלין מבקרקעות ולמדונו דאף אם אין המזיק לפנינו גובין לו ממטלטלין אבל ודאי אם המזיק גילה דעתו דניחא ליה טפי במטלטלין ורוצה לשלם לו בקרקעות והניזק רוצה דוקא מטלטלין יד המזיק על העליונה ולא דמי למלוה ולוה ולא כב\"י והעיר שושן נמשך אחריו שכתב ז\"ל דאי בעי הניזק מטלטלין צריך המזיק ליתן לו כו' ע\"ש עכ\"ל ואין דבריו נכונים דפשיטא דדעת הרמב\"ם והמחבר כהעיר שושן וכן דעת הטור ושאר הרבה פוסקים וכן עיקר וכמו שאבאר וכן מצאתי בנ\"י ריש פרק המוכר פירות שכ' להדיא שמדברי הרמב\"ם נראה בניזקין אי אית לי' קרקע ומטלטלים כפינן ליה ליתן לו מטלטלים וע\"ש והכי משמע ודאי פשט דברי הרמב\"ם שכתב כשב\"ד נזקקין כו' גובין מהמטלטלים תחלה כו' משמע דעליה דבי דינא רמיא לגבות תחלה מהמטלטלים והדין כך הוא ואינו תלוי ברצון המזיק או הניזק ועוד שכתב שם הרמב\"ם מיד אח\"כ דמדין הש\"ס אם מת והניח מטלטלים וקרקעות גובין מהיתומים מקרקעות וכן הוא בטור ואם איתא דמסתמא ניחא ליה למזיק טפי ליתן מטלטלים נטעון להו ליתמי לטעון מטלטלים והיאך יגרע כח היתומים מן המזיק עצמו ואמת שבהרא\"ש פ\"ק דב\"ק ומרדכי ושאר פוסקים משמע שדעת ר\"ת דאין צריך ליתן לו מטלטלים אלא נותן לו מה שירצה או מקרקעי או מטלטלי וכ\"כ הנ\"י ריש פרק המוכר פירות בשם המפרשים וכן כתבו התוספות ר\"פ המוכר פירות וריש ב\"ק ופ' הפר' דף מ\"ו ריש ע\"ב בשם ר\"ת ומשמע שם שר\"ת מפרש דהא דקאמרינן בש\"ס בב\"ק (דף ט' ע\"א) רב הונא אמר או כסף או מיטב דהיינו שהרשות בידו ליתן לו איזו שירצה אבל לדעת הרמב\"ם נ\"ל לפרש או כסף או מיטב או דינו על כסף היכא דאית לי' מטלטלים או דינו במיטב גבי קרקע היכא דלית לי' מטלטלי ובהא דכסף לא קי\"ל כרב הונא אלא אפי' סובין מיטב נינהו וכן מוכח להדיא מדברי בעל התרומות ריש שער ד' ומבואר שם להדיא ג\"כ דעת רבינו חננאל שהביא שם הך דרב הונא ומאי דשקיל וטרי התם בש\"ס עלי' וכתב ע\"ז וז\"ל וכ' על זה ר\"ח ז\"ל מהכא שמעינן דלא מסלקינן לב\"ח בארעא אלא היכא דקים לן דלית ליה זוזי למפרע מיניה כו' עכ\"ל ודלא כס' גידולי תרומה שם דף כ\"ז ע\"א שתמה הרבה על דברי ר\"ח והניחם בצ\"ע והדבר ברור דר\"ח מפרש כדפי' וכן נראה להדיא מדברי ראב\"ן ריש ב\"ק ע\"ש בדף פ\"ה ע\"א וכן מוכח מדברי הרמ\"ה שהביא הנ\"י ריש ב\"ק גבי מ\"ש שכל הפוסקים פסקו הלכה כרב פפא ורב הונא ברי' דרב יושיע וכ' הרמ\"ה כו' ע\"ש דמוכח דס\"ל לרמ\"ה גם כן דהיכא דאית ליה למזיק מטלטלים וקרקעות כפינן ליה למיתב מטלטלים כמו גבי ב\"ח:","וכן משמע פשט דברי הטור דדין הוא לגבות מהמטלטלים אפי' בע\"כ של מזיק ובמ\"ש ב\"י והיינו שכתב גם כן מיד אח\"כ דאם מת המזיק מגבינן מן הקרקעות של היתומים ולא מן המטלטלים מדינא דש\"ס ואי הברירה ביד המזיק אמאי כשמת יגרע כח היתומים וכמ\"ש לעיל. והב\"ח כ' דע\"כ לא קאמר הרא\"ש הכי אלא בבעל חוב אבל בניזקין אין הניזק יכול לכופו לגבות מהמטלטלים אם רוצה ליתן לו קרקע וכן דעת הטור ודלא כב\"י אלא יד המזיק על העליונה וכן מפורש בדברי הרב המגיד רפ\"א דחובל ובפ\"ח דהלכות נזקי ממון עכ\"ל ולפעד\"נ כמ\"ש הב\"י ואף שלכאורה משמע בהרא\"ש דכתב כן דוקא בב\"ח מ\"מ נראה דהא דכתב כן בב\"ח היינו אפי' לר\"ת אבל למה שכתב הרא\"ש שם דדברי רב אלפס עיקר הרי אלפס לא כתב שהבריר' ביד המזיק וגם נראה כיון דלרב אלפס אפי' יש לו מעות יכול לסלקו בסובין א\"כ הא דכתב קרא ישיב לרבות שוה כסף היינו דגלי לן קרא דעיקר גביה על המטלטלים הוא א\"כ לא מסתברא שיהא הברירה ביד המזיק כיון דגלי לן קרא דעיקר גביה במטלטלים היא אפי' אית ליה כסף גם מ\"ש הב\"ח בדעת הרב המגיד ליתא וכמ\"ש לקמן:","ועוד נ\"ל כן עיקר ממאי דגרסינן בש\"ס פ\"ב דב\"ק (דף י\"ד ע\"ב) על פסקא דשוה כסף רמי ליה רב יודא בר חנניא לרב הונא בריה דרב יושיע תנא שוה כסף ככסף מלמד שאין ב\"ד נזקקין אלא לנכסי' שיש להן אחריות והתניא ישיב לרבות שוה כסף ואפי' סובין הכא במאי עסקינן ביתמי ע\"כ ומייתי לה הרי\"ף אלמא דמעיקרא ס\"ד דב\"ד נזקקין לקרקע ומסיק דנזקקין לגבות ממטלטלי ואין ספק שמכאן הוציא הרמב\"ם את דבריו והיינו שכ' כשב\"ד נזקקין כו' כ' לשון נזקקין כל' הש\"ס שהוציא משם דבריו וכן כ' הרב המגיד להדיא בפ\"ח מה' נזקי ממון וז\"ל כשב\"ד נזקקין כו' מבואר פ\"ק בסוגיא על פיסקא דשוה כסף וכן למעל' באותו פרק מחלוקת אמוראין ופסק רבינו כר\"פ ורב הונא בריה דרב יושיע וכ\"ד ההלכות עכ\"ל ודבריו ברורים וליכא למימר דמעיקרא ס\"ד דנזקקין לקרקע ואין נזקקין למטלטלין כלל אפי' אין לו קרקע וכ\"מ לכאורה מפרש\"י שכ' אין ב\"ד נזקקין ליפרע מן המזיק אא\"כ יש לו קרקע כו' וא\"כ כי משני הכא ביתמי י\"ל דבדידי' כשיש לו מטלטלי לבד חייב ליתן לו אבל אה\"נ אם יש לו מטלטלי וקרקע הבריר' ביד המזיק דהיאך נא' דקס\"ד מעיקרא אפי' יהיה לו מטלטלים לא יצטרך לשלם לו כלום אם אין לו קרקע וכי בשביל שלא יהיה לו קרקע יפטר מלשלם ועוד דא\"כ לא שבקת חיי לכל בריה דכל מי שלא יהיה לו קרקע יזיק לבריות מה שירצה ויפטר מלשלם ועוד דהא לעיל (בדף ט' ע\"א) אהא דקאמר רב הונא ישיב אפי' סובין מיירי בדלית ליה אלא סובין פריך אי דלית ליה פשיטא ומשני מהו דתימא אמרינן ליה זיל טרח וזבן קמ\"ל אלמא דאינו עולה על הדעת כלל דכשאין לו רק סובין שלא יצטרך לשלם לו סובין אלא ודאי דמעיקרא סבר דב\"ד נזקקין לגבות מן הקרקע בע\"כ של מזיק דשוה כסף היינו קרקע ומסיק דב\"ד נזקקין לגבות מהמטלטלים בע\"כ של מזיק דשוה כסף היינו מטלטלים. ודקדקתי היטב בסוגיא זו לפרשה בדרכים אחרים והתבוננתי שא\"א לפרשה כי אם כמו שכתבתי אם לא ע\"פ דוחק גדול לכן העיקר כמ\"ש ודוק היטב. ומעתה גם מ\"ש הב\"ח שכך מפורש בדברי הרב המגיד רפ\"א מה' חובל ופ\"ח מה' נזקי ממון שיד המזיק על העליונה ליתא דהמעיין שם בדברי הרב המגיד יראה דאדרבא יותר נראה מדברי הרב המגיד כמ\"ש וגם בר\"פ א' מהל' מלוה נראה מהרב המגיד כמ\"ש ע\"ש: ועוד נראה כיון דבבעל חוב קי\"ל לעיל סי' ק\"א דמחויב ליתן לו מטלטלים כשיש לו ואין צריך המלוה ליקח קרקע א\"כ למה נימא דניזקין שאני דהא אדרבא ניזקין עדיפי דגובה מהעידית ואף שיש לחלק כמו היכי דיש לו מעות דאין צריך המזיק ליתן לו מעות ונמצא המזיק עדיף בזה מלוה היינו משום דגלי לן קרא גבי מזיק ישיב אפי' סובין ולא גלי לן הכי גבי ב\"ח א\"כ מסתבר דב\"ח דיהיב ליה זוזי צריך למפרע ליה בזוזי אבל בהא שיגבה תחלה מן מטלטלים בע\"כ של החייב אין סברא לחלק בין ב\"ח למזיק ודוק:","\u0003 ואפי' שיש לו כסף יכול לסלקו בסובין. \u0004 כלומר אפי' יש לו מעות א\"צ ליתן לו מעות ונותן לו מהפחות שבמטלטלים משא\"כ בב\"ח לעיל סימן ק\"א והיינו כהרי\"ף והרא\"ש והרמב\"ם שפסקו כרב פפא ורב הונא בריה דר' יושיע ולא כר\"ת (וכ\"כ בעל הטור ברמזי הרא\"ש שם דלית הלכתא כר\"ת וקאי אניזקין ודלא כב\"י לעיל ר\"ס ק\"א שכ' שמ\"ש ברמזי הרא\"ש הוא כשגגה דליתא דהמעיין שם יראה להדיא דקאי אניזקין רק שיש שם קצת ט\"ס ברמזים שלפנינו כנראה לכל מעיין בנקל והדבר ברור כמו שהוא בנוסחות הרמזים הישנים וכמו שהביא בספר מעד\"מ ברמזים שם ע\"ש): אך מ\"ש הרא\"ש שם ונראה דברי רב אלפס עקר דרב כהנא תלמידו דרבא דבתרא' הוא סבר כרב פפא ור' הונא בריה דרב יהושע דאמר לקמן א\"ל רב כהנא לרבא טעמא דכתב רחמנא והמת יהיה לו הא לאו הכי ה\"א נבלה דמזיק הוי השתא אי אית ליה לדידיה יהיב לי' דאמר מר ישיב לרבות שוה כסף אפי' סובין נבלה דידיה מבעיא ואם איתא לדרב הונא לימא ליה דאצטריך קרא היכא דאית ליה כסף או מיטב עכ\"ל לא ירדתי לסוף דעתו דלא מצינו בשום מקום דרב כהנא היה תלמידו דרבא אלא משמע בכמה דוכתי דרב כהנא היה תלמידו דרב וכדאיתא נמי בפרק אחד דיני ממונות (סנהדרין דף ל\"ו ריש ע\"ב) כי קאמר רב כגון [רב] כהנא ורב אסי דלגמריה דרב הוי צריכי כו' וכן בכמה דוכתי וכן הוא לקמן בכל ספרי הש\"ס (סוף ד\"י) א\"ל רב כהנא לרב טעמא דכתב רחמנא והמת יהיה לו כו' ואין ספק שנוסחא מוטעת מזדמנא להרא\"ש בכאן בש\"ס ועוד קשה לי על הרא\"ש הא רב פפא ורב הונא בריה דרב יהושע הוו בתראי טפי מרבא. וזהו עיקר הטעם שפסק הרי\"ף כרב פפא ורב הונא ברי' דרב יושיע דבתראי נינהו ואין צריך טעם יותר דמ\"ש הרא\"ש מתחל' בדעת ר\"ת דרב פפא ורב הונא בריה דרב יהושע לא פליגי ארב הונא ודאי נדח' מהא דקאמר רב כהנא לרב טעמא דכתב רחמנא והמת יהיה לו כו' דא\"כ לא הוי פריך מידי דקרא מיירי היכ' דאית ליה כסף וגם בתוספות פרק הפרה דף מ\"ו ריש ע\"ב ושאר פוסקים מבואר דאף ר\"ת ס\"ל דפליגי. וגם מ\"ש הרא\"ש דהטעם ר\"ת היא כיון דהש\"ס קאי לדרב הונא באחרונה חשיב ליה עיקר אף שיכול להיות שדעת ר\"ת כן מ\"מ אין ראיה כ\"כ מזה וק\"ל וכבר האריך מהרש\"ל פ\"ק דב\"ק סי' כ\"א בזה להוכיח דקי\"ל כרב פפא ורב הונא בריה דרב יושיע וכ\"כ בנ\"י שכ\"פ כל המפרשים ז\"ל וכן עיקר. אך כתב הנ\"י שם שכתב הרמ\"ה ז\"ל דהא דמצי יהיב ליה אפי' סובין ה\"מ היכא דלית ליה למזיק זוזי כו' וע\"ש בגליון האלפסי של מהר\"ם מטיקאטין שתמה על זה דהא לרב פפא ורב הונא בריה דר\"י אפי' אית ליה כסף יכול לסלקו בסובין ול\"נ שדעת הרמ\"ה דכסף שאני וכן מדוקדק בלשונו שם ע\"ש אך דעת כל הפוסקי' מבואר דכסף היינו זוזי ואפי' אית ליה זוזי יכול לסלקו בסובין והכי מוכח נמי מהך דא\"ל רב כהנא לרב טעמא דכתב רחמנא והמת יהיה לו כו' ואי איתא דהיכא דאית ליה זוזי צריך לסלקו בזוזי לא הוה פריך מידי דדלמא קרא איירי בדאית לי' זוזי א\"ו כסף היינו זוזי כמו אם כסף תלוה וכן עיקר:","מיהו היכא דהמזיק רוצה לסלקו במעות ודאי אין צריך ליתן לו מטלטלי או קרקעות שלו ופשוט הוא:","\u0003 צריך ליתנה לו כפי מה כו'. \u0004 והעיר שושן חולק על זה ועיין בספר מגדל דוד ובסמ\"ע ס\"ק ד' מה שהשיגו עליו ואין דבריהם מוכרחים ודברי הע\"ש יותר נכונים. ומהרש\"ל פ\"ק דב\"ק סי' י\"א חולק בכל הסעיף וכתב דהניזק לעולם גובה מעידית המזיק אפי' עידי עידית שהוא רוצה מאחר שדינו ממיטב ומ\"מ לפי ראות עיני הדייני' שאם יראו שזאת טובה לניזק וזאת טובה למזיק זהו בכלל ועשית הישר והטוב כו' וע\"ש:","\u0003 מגבין לניזק מהמטלטלים של יתומים \u0004 רבינו אפרים השיב על הרי\"ף בזה דניזקין מלתא דלא שכיחא היא וכי תקנו הגאונים לב\"ח משום נעילת דלת בפני לווין אי נמי לאשה משום פריה ורביה אבל לניזקין לא תקון והרא\"ש כ' וז\"ל ונ\"ל דבדורות הללו מטלטלי כמקרקעי לכל מילי שעבוד מדינ' דש\"ס אף בלא תקנה דהוי כגמלי דערביא ואשלי דקמחוניא דקאמר בכתובות אשה גובה פורנא מהם עכ\"ל וכן מסקנת הטור ולפי עניות דעתי אין דברי הרא\"ש מוכרחים בזה דהא דאמרי' בכתובות בפרק מציאת אשה (כתובות דף ס\"ז ע\"א) אשה גובה פורנא מהם היינו דוקא בכתובה דאש' סמכ' דעתה עלייהו ומתחלה כשנשאת לזה אדעתא דהכי נשאת שתגבה ממטלטלי כיון שעיקר משא ומתן שלהם היה במטלטלים וזה לא שייך בניזקין. ומ\"מ דעת רוב הפוסקים כהרי\"ף והרמב\"ם והמחב' דהאידנא אף נזקין גובין ממטלטלי' דיתמי וכ\"כ מהרש\"ל פ\"ק דב\"ק סי' ל\"ט וע\"ש:","\u0003 מהמטלטלי' של יתומים. \u0004 משמע דהיינו אפילו יש להן קרקע מיהו היינו מן הסת' אבל אם היתומי' רוצים לסלקו בקרקע הרשות בידם דבכה\"ג לא תקנו הגאונים וכדלעיל סי' ק\"ז סעיף א' גבי ב\"ח וכ\"ש הכא ועמ\"ש שם וכן כ' בשלטי גבורים פ' חזקת הבתים דף קפ\"ד ע\"א ע\"ש:","\u0003 שכל הבא ליפרע מיתומים כו'. \u0004 משמע אפילו גדולים וכן נראה דעת הרמב\"ם ודלא כהסמ\"ע לדעתו ועמש\"ל סוף סי' ק\"ח מזה:"],"\u0010c0\u0011 \u0010g0\u0011 \u0010t0\u0011 \u0010r0\u0011 כְּשֶׁבֵּית דִּין נִזְקָקִין לִגְבּוֹת לַנִּזָּק מִנִּכְסֵי הַמַּזִּיק, \u0010y0\u0011 \u0010c1\u0011 גּוֹבִין מֵהַמִּטַּלְטְלִין \u0010t1\u0011 תְּחִלָּה, \u0010r1\u0011 וְאִם לֹא הָיוּ מִטַּלְטְלִין כְּלָל, אוֹ שֶׁלֹּא הָיוּ לוֹ מִטַּלְטְלִין כְּנֶגֶד כָּל הַנֶּזֶק, גּוֹבִין הַשְּׁאָר מֵהַקַּרְקַע הַמְעֻלֶּה שֶׁבְּנִכְסֵי הַמַּזִּיק; וְכָל זְמַן שֶׁיִּמְצָא מִטַּלְטְלִין, וַאֲפִלּוּ סֻבִּין, אֵין נִזְקָקִין לַקַּרְקַע. \u0010c2\u0011 \u0010g1\u0011 \u0010r2\u0011 וַאֲפִלּוּ שֶׁיֵּשׁ לוֹ \u0010t2\u0011 כֶּסֶף, יָכוֹל לְפוֹרְעוֹ בְּסֻבִּין, דְּכָל מִטַּלְטְלִים מֵיטַב נִינְהוּ. \u0010g2\u0011 \u0010r3\u0011 וְשָׁמִין אוֹתָהּ \u0010y1\u0011 כְּמוֹ שֶׁיָּכוֹל לְמוֹכְרָהּ מִיָּד וּבִמְקוֹמוֹ. וּכְשֶׁמְּשַׁלֵּם מֵהַקַּרְקַע, אֲפִלּוּ הָיְתָה \u0010g3\u0011 זִבּוּרִית שֶׁל מַזִּיק טוֹבָה מֵעִדִּית שֶׁל נִזָּק, אֵינוֹ מְקַבֵּל מִמֶּנּוּ, אֶלָּא מַגְבִּין לוֹ \u0010y2\u0011 מֵעִדִּית שֶׁבְּנִכְסֵי הַמַּזִּיק. \u0010g4\u0011 \u0010r4\u0011\nאִם יֵשׁ לַמַּזִּיק שְׁנֵי עִדִּית, אֵין הַנִּזָּק יָכוֹל לוֹמַר לוֹ: תֵּן לִי מֵעִדִּית פְּלוֹנִי, אֶלָּא תָּלוּי בִּרְצוֹן הַמַּזִּיק לָתֵת לוֹ אֵיזֶה שֶׁיִּרְצֶה. \u0010r5\u0011 אֲבָל אִם הַמַּזִּיק חָפֵץ לָתֵת לוֹ הָעִדִּית שֶׁבִּקֵּשׁ, אֶלָּא שֶׁהִיא עַתָּה בְּזוֹל וּמַמְתִּין עַד שֶׁתִּתְיַקֵּר, וְאוֹמֵר: אִם תִּרְצֶה אוֹתָהּ קַח אוֹתָהּ כְּפִי מַה שֶּׁהִיא עֲתִידָה \u0010g5\u0011 לְהִתְיַקֵּר, אֵין שׁוֹמְעִין לוֹ, אֶלָּא \u0010c3\u0011 צָרִיךְ לִתְּנָהּ לוֹ \u0010y3\u0011 כְּפִי מַה שֶּׁשָּׁוָה \u0010t3\u0011 עַתָּה. \u0010g6\u0011\nמֵת הַמַּזִּיק קֹדֶם שֶׁיִּפְרַע, \u0010c4\u0011 מַגְבִּין \u0010y4\u0011 \u0010c5\u0011 \u0010t4\u0011 לַנִּזָּק מֵהַמִּטַּלְטְלִין שֶׁל \u0010t5\u0011 יְתוֹמִים; \u0010r6\u0011 וְאִם לֹא הִנִּיחַ מִטַּלְטְלִין, \u0010r7\u0011 מַגְבִּין לוֹ \u0010g7\u0011 מִזִּבּוּרִית שֶׁבְּקַרְקְעוֹתָיו, \u0010c6\u0011 \u0010c7\u0011 \u0010c8\u0011 \u0010c9\u0011 \u0010r8\u0011 שֶׁכָּל הַבָּא לִפָּרַע מִנִּכְסֵי יְתוֹמִים, לֹא יִפָּרַע אֶלָּא \u0010t6\u0011 מֵהַזִּבּוּרִית:",{"g":["א) לשון הרמב\"ם פ\"ח מה' נזקי ממון וכתב ה\"ה מבואר בפ\"ק ובסוגיא דעל פיסקא דשוה כסף (דף יד ע\"ב) וכן למעלה מחלוקת אמוראים ופסק רבינו כרב פפא ורב הונא ברי' דרבי יהושע שם דף יז ע\"ב וכן דעת ההלכות ע\"כ וכ\"כ הטור והרא\"ש שם בפסקיו","ב) לשון הטור ס\"א מימרא דר\"פ ורב הונא הנזכר לעיל","ג) שם כ\"כ הרא\"ש שם בפסקיו לענין ב\"ח דלא תנעל דלת בפני לוין ואע\"ג דליכא האי טעמא בניזקין סבירא ליה לרבינו דלא פליג רבנן בינייהו לענין זה","ד) ברייתא שם ד\"ו ע\"ב וכאוקימתא דרב אחא בר יעקב ופסקו הפוסק כר\"ע דהלכה כר\"ע מחבירו","ה) שם ס\"ג כ\"כ הרא\"ש שם בפסקיו","ו) שם ושם בפסקיו מהא דפריך ליה רב אחא בר יעקב אם כן הורע כחן של נזקין שם דף ז' ע\"ב","ז) שם ס\"ג בשם הרי\"ף מתקנת הגאונים ואילך וכ\"כ הרמב\"ם שם בפ\"ח דין י\"ב","ח) כתב ה\"ה מחלוקת האמוראי' פ\"ה דגיטין דף נ' ע\"א ופסק כרב נחמן דהלכתא כוותיה בדיני וכאביי דאמר הכי דלא כרבא וכ\"פ ז\"ל דיתומים אלו בין קטנים בין גדולי' אבל הרשב\"א ז\"ל כ' בשם ה\"ר יונה דוקא קטנים אבל גדולים מן העידית:"],"t":["\u0003נזקקין. \u0004 מהרש\"ל פ\"ק דב\"ק סי' ט\"ז פסק דנזיקין גובין ממשועבדים אף שלא עמד בדין דיש קול לנזקין וכן משמע בתוספות שם דף י\"ד ע\"ב לפר\"ת למאי דס\"ל שעבודא דאורייתא וכן כת' ר' ירוחם גם הה\"מ פי\"ט דמלוה בשם י\"מ וכן כת' הסמ\"ע בסי' קי\"ח ס\"ג ע\"ש מיהו יש חולקין ועמ\"ש בסי' ס\"ו סל\"ה. ש\"ך:","\u0003תחלה. \u0004 כת' הסמ\"ע דהיינו משום דמסתמא ניחא למזיק לשלם במטלטלין מבקרקעות ולמדונו דאף אם אין המזיק לפנינו גובין לו ממטלטלים אבל ודאי אם המזיק גילה דעתו דניחא ליה טפי במטלטלים ורוצה לשלם לו בקרקעות והניזק רוצה דוקא מטלטלין יד המזיק על העליונה ולא דמי למלוה ולוה כו' והש\"ך השיג עליו דאין סברא לחלק בענין זה בין בע\"ח למזיק וכת' דכן דעת הרבה פוסקים וכן עיקר ע\"ש באריכות:","\u0003כסף. \u0004 פירש הש\"ך דר\"ל אפילו יש לו מעות א\"צ ליתן לו מעות ונותן לו מהפחות שבמטלטלים משא\"כ בבע\"ח לעיל סי' ק\"ח כו' וכן עיקר מיהו היכא דהמזיק רוצה לסלקו במעות ודאי אין צריך ליתן לו מטלטלים או קרקעות שלו ופשוט הוא עכ\"ל:","\u0003עתה. \u0004 והע\"ש חולק ע\"ז ועיין בספר מגדול דוד ובסמ\"ע מה שהשיגו עליו ואין דבריהם מוכרחים ודברי הע\"ש יותר נכונים ומהרש\"ל פ\"ק דב\"ק סי' י\"א חולק בכל הסעיף וכת' דהניזק לעולם גובה מעידית המזיק אפילו עידי עידית שהוא רוצה מאחר שדינו ממיטב ומ\"מ לפי ראות עיני הדיינים שאם יראו שזאת טובה לניזק וזאת טובה למזיק זהו בכלל ועשית הישר והטוב כו' וע\"ש. ש\"ך:","\u0003מהמטלטלין. \u0004 רבינו אפרים השיג על הרי\"ף בזה דנזיקין מלתא דלא שכיחא היא וכי תקנו הגאונים לבע\"ח משום נעילת דלת ולאשה משום פריה ורביה אבל לניזקין לא תקון והרא\"ש כת' עליו ז\"ל ונ\"ל דבדורות הללו מטלטלי כמקרקעי לכל מילי שעבוד מדינא דש\"ס אף בלא תקנה דהוי כגמלי דערביא כו' דאמרינן בכתובות \u0005(דף ס\"ז ע\"א)\u0006 אשה גובה פורנא מהן עכ\"ל וכן מסקנת הטור ולע\"ד אין דברי הרא\"ש מוכרחים בזה דלא אמרו בש\"ס שם אלא דוקא בכתובה דאשה סמכא דעתה עלייהו ומתחלה כשנשאת לזה אדעתא דהכי נשאת שתגבה ממטלטלי כיון שעיקר מו\"מ שלהם היה במטלטלים וזה לא שייך בניזקין ומ\"מ דעת רוב הפוסקים כהרי\"ף והרמב\"ם והמחבר דהאידנא אף ניזקין גובין ממטלטלי דיתמי וכ\"כ מהרש\"ל פ\"ק דב\"ק סי' ל\"ט וע\"ש. ש\"ך:","\u0003יתומים. \u0004 משמע דהיינו אפילו יש להן קרקע מיהו היינו מן הסתם אבל אם היתומים רוצים לסלקו בקרקע הרשות בידם דבכה\"ג לא תקנו הגאונים וכמ\"ש בר\"ס ק\"ז גבי בע\"ח וכ\"ש הכא וממ\"ש שם וכן כת' בש\"ג פרק חז\"ה ע\"ש. שם:","\u0003מהזיבורית. \u0004 משמע אפילו מיתומים גדולים דינא הכי וכ\"נ דעת הרמב\"ם ודלא כהסמ\"ע לדעתו ועמ\"ש לעיל ס\"ס ק\"ח מזה. שם:"],"r":["\u0003כשב\"ד כו' וכ\"ז שימצא כו'. \u0004 י\"ד ב' דת\"ר שוה כסף כו' והתניא ישיב כו' וא\"כ דינו כבע\"ח וכמ\"ש בסי' קא ס\"ב:\n\u0003 (ליקוט) כשב\"ד כו'. \u0004 רמב\"ם ולמד מבע\"ח דכשיש מטלטלין אין נזקקין לקרקעות וצ\"ע דל\"ד דשם כשיש לו כסף אין נזקקין לש\"ד ומטלטלין דמי לכסף משא\"כ כאן והרי ר\"ה דמחמיר אמר או כסף או מיטב אלמא יכול לגבות קרקעות אע\"ג שיש לו כסף ועתוס' שם ד\"ה רב הונא כ\"ש לדידן דקי\"ל כר\"פ ור\"ה בדר\"י וכ\"כ הרמב\"ם וש\"ע לעיל סי' שמח ס\"ה וג\"כ תמוה וכ\"מ ברא\"ש דב\"ק שם סוף ס\"ה ולענין פריעת ב\"ח כו' אי כו' כיון דזוזי יהיב כו' מדקא' ולענין פריעת כו' מ' דוקא בבע\"ח ועוד דקאמר כיון דזוזי יהיב והוא דוקא בבע\"ח דדינו בכסף וצע\"ג (ע\"כ):\n\u0003 (ליקוט) כשב\"ד כו'. \u0004 הוא לשון הרמב\"ם אבל לשון הטור יתן לו מטלטלין כו' ע\"ש ור\"ל ברצונו של מזיק תלוי ואמר שלוקח מטלטלין לאפוקי מרב הונא דאמר כ\"ז שיש לו מיטב א\"י ליתן לו מטלטלין וכן פי' ב\"ח ודו\"פ דלא כב\"י וז\"ש ואפי' שיש לו כסף כו' אבל לשון הרמב\"ם אינו מורה כן דאינו תולה ברצון המזיק ונראה דס\"ל כדעת הרמ\"ה דכ\"ז שי\"ל כסף א\"י ליתן לו לא מטלטלין ולא קרקע וה\"ה כשיש לו מטלטלין דאי\"ל קרקע ועסי' שנד ס\"ה אלא שצ\"ע למה לא כ' הרמב\"ם דביש לו כסף שאי\"ל מטלטלין ונר' שהרמב\"ם ס\"ל דמטלטלין ה\"ה כנסף כמש\"ש י\"ד ב' והני כולהו כסף כו' ומפ' מ\"ש שם ט' א' ר\"ה אמר או כסף או מיטב ר\"ל אם יש לו כסף יתן כסף ואם אין לו יתן מיטב כפי' הרמ\"ה איתביה כו' הב\"ע בדל\"ל ר\"ל שאין לו מטלטלין אז אר\"ה שיתן מיטב פשיטא מ\"ד כו' שיזבין מיטב שדותיו אמרה תורה ודלא כפירש\"י דמ\"ש בדל\"ל שאין לו מיטב אז יתן סובין והוא ס' הפוכה דסובין טוב ממיטב כמ\"ש ז' ב' כל מילי כו' וס\"ל להרמב\"ם דמטלטלין בכלל כסף הוא וז\"ש ר\"ה או כסף או מיטב ולא הזכיר מטלטלין שהוא בכלל כסף ולפ\"ז ל\"פ ר\"פ ור\"ה בריה דר\"י אר\"ה ול\"פ על ר\"ה מש\"ש י\"ד ב' השתא אי אית כו' דלפרש\"י ק' קושית הרא\"ש דלמא בשיש כסף אי מיטב אבל לפי' הרמב\"ם ניחא וזה הכריחו ג\"כ דמטלטלין הוא בכלל כסף דאל\"כ לוקמיה בי\"ל כסף (ע\"כ):\n\u0003 (ליקוט) כשב\"ד כו'. \u0004 וכ\"כ נ\"י שם בשם הרמ\"ה אלא שכ' דבכל הוא שוה לבע\"ח דכשיש לו כסף אין נזקקין למטלטלין ואינו כן דעת הרמב\"ם (ע\"כ):","\u0003ואם לא כו'. \u0004 כמש\"ש ז' ב' כל מילי כו' בר כו':","\u0003ואפי' שיש כו'. \u0004 עמ\"ש בסי' שנד ס\"ה:\n\u0003 (ליקוט) ואפי' שי\"ל כו'. \u0004 דלא כר\"ה דס\"ל דוקא אם א\"ל קרקעות ולא כסף ודלא כר\"ת שפ' כר\"ה. הרי\"ף דר\"פ ור\"ה בריה דר\"י בתרא. וכ\"פ הרא\"ש וכ' דרב כהנא שם יו\"ד ב' ג\"כ כוותייהו ס\"ל דאל\"כ מאי פריך די\"ל דקמ\"ל אפי' אית ליה כסף תו מיטב (ע\"כ)","\u0003ושמין כו'. \u0004 כמ\"ש בסי' קא ס\"ט:","\u0003אם יש כו' \u0004 כמ\"ש בסי' קב ס\"ב:","\u0003 (ליקוט) אבל אם כו'. \u0004 טור וכשיטת הרא\"ש דא\"י לכופו גם בבינונית וזיבורית ומה שפריך א\"כ הורעת כו' בכה\"ג וא\"כ ה\"ה לב' עידית וערא\"ש שם וע\"ל סי' קב ס\"ב (ע\"כ):","\u0003 (ליקוט) אם כו'. \u0004 ר\"ל בזה\"ז דבימי הגמ' לא היו גובין ממטלטלי דיתמי כמש\"ש י\"ד ב' אבל האידנא כמו שגובה בע\"ח כו' הרי\"ף שם וכ' הרא\"ש שם שהר' אפרים חולק דלא תקנו אלא לב\"ח וכתובה אבל נזקין מלתא דלא שכיחא והרא\"ש הסכים לדעת הרי\"ף ולא מטעמו אלא משום דבזה\"ז דינא הוא כמ\"ש תוס' בכתובות ס\"ז א' בד\"ה גמלים כו' ומכאן כו' אבל כ' ואין נראה לר\"ת וכ\"כ הרא\"ש שם (ע\"כ):","\u0003 (ליקוט) מגבין לו כו'. \u0004 גיטין נ' א' ועבה\"ג אבל הרשב\"א כו'. וכ\"כ הרא\"ש שם בשם הר' יונה והסכים עמו וכ\"כ לעיל ס\"ס קח (ע\"כ):","\u0003שכל כו', \u0004 עסי' קח סכ\"א שחולק ע\"ז ועמ\"ש בליקוטים ב' א' בשם הרשב\"א:\n\u0003 (ליקוט) שכל כו'. \u0004 מתני' ר\"פ הנזקין (ע\"כ):"]}],["\u0003הלכות חובל בחבירו\u0004\nאָסוּר לְאָדָם לְהַכּוֹת חֲבֵרוֹ; וְאִם הִכָּהוּ עוֹבֵר בְּלָאו, \u0010y0\u0011 שֶׁנֶּאֱמַר: פֶּן יֹסִיף \u0005(דְּבָרִים כה, ג)\u0006. וְאִם הִקְפִּידָה תּוֹרָה \u0010y1\u0011 בְּהַכָּאַת רָשָׁע שֶׁלֹּא לְהַכּוֹתוֹ יוֹתֵר עַל רִשְׁעוֹ, קַל וָחֹמֶר בְּהַכָּאַת צַדִּיק. וְהַמֵּרִים יַד עַל חֲבֵרוֹ לְהַכּוֹתוֹ, \u0010y2\u0011 אַף עַל פִּי שֶׁלֹּא הִכָּהוּ, נִקְרָא רָשָׁע. \u0005הַגָּה: וְעַיֵּן לְקַמָּן סִימָן תכ\"א סָעִיף י\"ג. וְדִין הַכָּאַת אִישׁ לְאִשְׁתּוֹ, עַיֵּן בְּאֶבֶן הָעֵזֶר סִימָן קנ\"ד. \u0010y3\u0011 דְּיֵשׁ אוֹמְרִים דְּיֵשׁ חֵרֶם קַדְמוֹנִים בְּאָדָם הַמַּכֶּה לַחֲבֵרוֹ, וּצְרִיכִין לְהַתִּיר לוֹ כְּדֵי לְצָרְפוֹ לְמִנְיָן עֲשָׂרָה, וּמִיָּד שֶׁמְּקַבֵּל עָלָיו לַעֲשׂוֹת דִּין, מַתִּירִין לוֹ אַף עַל פִּי שֶׁאֵין (הַמֻּכֶּה)\u0006 מִתְרַצֶּה \u0005(מַהֲרַ\"ם מֵרִיזְבּוּרְק והג\"מ פֶּרֶק הַחוֹבֵל)\u0006.\nהִכָּהוּ מַכָּה שֶׁאֵין בָּהּ שְׁוֵה פְרוּטָה, לוֹקֶה, \u0010y4\u0011 כֵּיוָן שֶׁאֵין בָּהּ חִיּוּב מָמוֹן. וַאֲפִלּוּ הִכָּה \u0010y5\u0011 \u0010c0\u0011 עֶבֶד כְּנַעֲנִי, לוֹקֶה הוּא, שֶׁהֲרֵי חַיָּב בְּמִצְוֹת.\nהַחוֹבֵל \u0010y6\u0011 \u0010c1\u0011 בַּחֲבֵרוֹ, חַיָּב בַּחֲמִשָּׁה דְבָרִים: נֶזֶק, צַעַר, רִפּוּי, שֶׁבֶת, בֹּשֶׁת; אִם הַחַבָּלָה בְּעִנְיָן שֶׁיֵּשׁ בָּהּ כָּל הֶחָמֵשׁ. \u0005הַגָּה: יֵשׁ אוֹמְרִים דְּצָרִיךְ לִתֵּן גַּם כֵּן תּוֹסָפוֹת מְזוֹנוֹת הַצְּרִיכִין בְּחָלְיוֹ מִמַּה שֶׁהָיָה אוֹכֵל כְּשֶׁהָיָה בָּרִיא (נִמּוּקֵי יוֹסֵף פֶּרֶק הַחוֹבֵל)\u0006, וְנִרְאֶה לִי, דְבִכְלָל רִפּוּי יֵחָשֵׁב. וְאִם אֵין בָּהּ אֶלָּא ד', מְשַׁלֵּם ד'; וְאִם ג', ג'; וְאִם ב', ב'; וְאִם א', א'.\nכֵּיצַד, קָטַע יָדוֹ אוֹ רַגְלוֹ אוֹ אֶצְבַּע אַחַת, אוֹ שֶׁחִסְרוֹ אֶחָד מִכָּל אֵבָרָיו, נוֹתֵן לוֹ כָּל ה' הַדְּבָרִים.\nהִכָּהוּ \u0010y7\u0011 עַל יָדוֹ וְצָבְתָה וְסוֹפָהּ לַחֲזֹר, אוֹ הִכָּהוּ עַל עֵינוֹ וּמָרְדָה וְסוֹפָהּ לַחֲזֹר, אֵין כָּאן נֶזֶק, וְנוֹתֵן לוֹ שְׁאָר אַרְבַּע דְּבָרִים.\nהִכָּהוּ עַל רֹאשׁוֹ וְצָבְתָה, אֵין כָּאן נֶזֶק וְשֶׁבֶת, וְנוֹתֵן לוֹ שְׁאָר הַשְּׁלֹשָׁה דְבָרִים. \u0010y8\u0011\nהִכָּהוּ בְּמָקוֹם שֶׁאֵינוֹ נִרְאָה, וְלֹא רָאָהוּ שׁוּם אָדָם, אֵינוֹ נוֹתֵן לוֹ אֶלָּא צַעַר וְרִיפּוּי.\nהִכָּהוּ בְּמִטְפַּחַת שֶׁבְּיָדוֹ אוֹ בִּשְׁטָר וְכַיּוֹצֵא בְּזֶה, אֵין כָּאן אֶלָּא בֹּשֶׁת. \u0005וְיֵשׁ אוֹמְרִים דַּוְקָא שֶׁהוּא בִּמְקוֹם רוֹאִין (הָרַאֲבַ\"ד)\u0006.\nכְּוָאוֹ בְּשַׁפּוּד עַל צִפָּרְנוֹ, בְּמָקוֹם שֶׁאֵינוֹ עוֹשֶׂה חַבּוּרָה וְאֵינוֹ מְעַכְּבוֹ מִמְּלָאכָה, אֵינוֹ נוֹתֵן אֶלָּא צַעַר. \u0005וְאִם הָיָה בִּמְקוֹם רוֹאִין, חַיָּב בְּבֹשֶׁת (המ\"מ שם)\u0006.\nהִשְׁקָהוּ סַם, אוֹ שֶׁסָכוֹ סַם, וְשִׁנָּהוּ מִמַּרְאֵה עוֹרוֹ, אֵינוֹ מְשַׁלֵּם לוֹ \u0010y9\u0011 אֶלָּא רִפּוּי בִּלְבַד.\nהִכְנִיסוֹ בְּחֶדֶר וְסָגַר הַדֶּלֶת עָלָיו וּבִטְּלוֹ מִמְּלַאכְתּוֹ, אֵינוֹ נוֹתֵן לוֹ אֶלָּא שֶׁבֶת בִּלְבַד. אֲבָל אִם הָיָה כְּבָר בְּחֶדֶר וְסָגַר עָלָיו מִלָּצֵאת, \u0010y10\u0011 הָוֵי גְרָמָא בְּנִזָּקִין וּפָטוּר מִדִּינֵי אָדָם.\nגִּלַּח שְׂעַר רֹאשׁוֹ, אֵינוֹ נוֹתֵן לוֹ \u0010y11\u0011 אֶלָּא בֹּשֶׁת. סָכוֹ בְּסַם עַד שֶׁאֵין סוֹף הַשֵּׂעָר לַחֲזֹר, חַיָּב בְּה' דְּבָרִים, \u0010y12\u0011 שֶׁהֲרֵי מִצְטַעֵר מִן הַסַם, וְשֶׁבֶת שֶׁהֲרֵי הוּא רָאוּי לְרַקֵּד \u0010y13\u0011 וּלְנַדְנֵד \u0005(שְׂעַר)\u0006 רֹאשׁוֹ בִּשְׁעַת רִקּוּד, וְנִמְצָא בָּטֵל מִמְּלָאכָה זוֹ.\nהַמְחַסֵר אֶת חֲבֵרוֹ אֵבֶר שֶׁאֵינוֹ חוֹזֵר, חַיָּב בְּכָל הַה' דְּבָרִים. אֲפִלּוּ הִפִּיל שִׁנּוֹ, חַיָּב בַּכֹּל, שֶׁאִי אֶפְשָׁר שֶׁלֹּא יֶחֱלֶה פִיו שָׁעָה אַחַת; אַף עַל פִּי שֶׁהַשֵּׁן אֵין לוֹ רְפוּאָה, בְּשַׂר הַשִּׁנַּיִם צָרִיךְ רְפוּאָה.\nאֲפִלּוּ חִסְרוֹ כִּשְׂעוֹרָה מֵעוֹר בְּשָׂרוֹ, חַיָּב בְּה' דְּבָרִים, שֶׁהָעוֹר אֵינוֹ חוֹזֵר \u0010y14\u0011 אֶלָּא צַלֶּקֶת \u0005(פֵּרוּשׁ, רֹשֶׁם מַכָּה שֶׁנִּתְרַפְּאָה)\u0006. לְפִיכָךְ, הַחוֹבֵל בַּחֲבֵרוֹ וְקָרַע הָעוֹר וְיָצָא מִמֶּנּוּ דָם, חַיָּב בְּה' דְּבָרִים.\nכֵּיצַד מְשַׁעֲרִים הַה' דְּבָרִים, נֵזֶק אִם חִסְרוֹ אֵבֶר אוֹ חָבַל חַבּוּרָה שֶׁאֵין סוֹפָהּ לַחֲזֹר שָׁמִין אוֹתוֹ \u0010y15\u0011 כְּאִלּוּ הוּא עֶבֶד נִמְכָּר בַּשּׁוּק, כַּמָּה הָיָה שָׁוֶה קֹדֶם שֶׁחָבַל בּוֹ וְכַמָּה נִפְחֲתוּ דָמָיו אַחַר הַחַבָּלָה, וְכָךְ יִתֵּן לוֹ. \u0005הַגָּה: \u0010c2\u0011 וְאִם הָיָה בַּעַל אֻמָּנוּת, כְּגוֹן נוֹקֵב מַרְגָלִיּוֹת, וְקָטַע לוֹ יָדוֹ, מְשַׁעֲרִינָן הֶזֵּיקוֹ כְּפִי מַה שֶּׁהוּא. אֲבָל אִם קָטַע רַגְלוֹ, \u0010y16\u0011 שֶׁאֵין מַזִּיק לוֹ כָּל כָּךְ, מְשַׁעֲרִינָן הֶזֵּקוֹ כְּאִלּוּ לֹא הָיָה בַּעַל אֻמָּנוּת (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006.\nצַעַר כֵּיצַד, הֲרֵי שֶׁקָּטַע אֶצְבָּעוֹ, אוֹמְדִים כַּמָּה אָדָם רוֹצֶה לִתֵּן בֵּין לִקְטֹע לוֹ אֵבֶר זֶה בְּסַיִף אוֹ לִקְטֹעַ אוֹתוֹ בְּסַם, \u0010y17\u0011 אִם גָּזַר הַמֶּלֶךְ לִקְטֹעַ אֵבֶר \u0005בְּסַיִף,\u0006 וּמַה שֶּׁיֵּשׁ בֵּין זֶה לְזֶה מְשַׁלֵּם לוֹ. \u0005הַגָּה: וּבְמָקוֹם דְּאִכָּא צַעַר לְחוּד, מְשַׁעֲרִין \u0010y18\u0011 אִם הָיָה גּוֹזֵר הַמֶּלֶךְ לִכְווֹת אוֹתוֹ בְּשַׁפּוּד עַל צִפָּרְנוֹ וְכַדּוֹמֶה, כַּמָּה הָיָה נוֹתֵן לְהִנָּצֵל מִצַּעַר זֶה (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006.\nכֵּיצַד מְשַׁעֲרִין הַשֶּׁבֶת, אִם לֹא חִסְרוֹ אֵבֶר אֶלָּא חָלָה וְנָפַל לְמִשְׁכָּב, אוֹ צָבְתָה יָדוֹ וְסוֹפָהּ לַחֲזֹר, נוֹתֵן לוֹ שִׁבְתּוֹ שֶׁל כָּל יוֹם וָיוֹם \u0010y19\u0011 כְּפוֹעֵל בָּטֵל שֶׁל אוֹתָהּ מְלָאכָה שֶׁבָּטַל מִמֶּנָּה. וְאִם חִסְרוֹ אֵבֶר, כְּגוֹן שֶׁקָּטַע יָדוֹ, נוֹתֵן לוֹ דְּמֵי יָדוֹ שֶׁהוּא הַנֶּזֶק, וְשֶׁבֶת רוֹאִין אוֹתוֹ כְּאִלּוּ הוּא שׁוֹמֵר קִשּׁוּאִין, וְרוֹאִין כַּמָּה הוּא שְׂכַר שׁוֹמֵר קִשּׁוּאִים בְּכָל יוֹם, וְעוֹשִׂין חֶשְׁבּוֹן כָּל יְמֵי חָלְיוֹ שֶׁל זֶה וְנוֹתֵן לוֹ. וְכֵן אִם קָטַע רַגְלוֹ, רוֹאִין אוֹתוֹ כְּאִלּוּ הוּא שׁוֹמֵר עַל הַפֶּתַח. סִמָּא אֶת עֵינוֹ, רוֹאִין אוֹתוֹ כְּאִלּוּ הוּא טוֹחֵן בְּרֵחַיִם; וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0005הַגָּה: וְדַוְקָא בִּסְתָם בְּנֵי אָדָם שֶׁאֵינָן בְּנֵי אֻמָּנוּת, אֲבָל אִם הוּא בֶּן אֻמָּנוּת וְיָכוֹל לַעֲסֹק בִּמְלַאכְתּוֹ אַחַר חָלְיוֹ, מְשַׁעֲרִין הַשֶּׁבֶת כְּפִי הַמְּלָאכָה דְבָטֵל מִנֵּהּ (טוּר סי\"ט בְּשֵׁם הָרֹא\"שׁ)\u0006.\nכֵּיצַד מְשַׁעֲרִין הָרִיפּוּי, אוֹמְדִים בְּכַמָּה יָמִים יִחְיֶה מֵחֹלִי זֶה, וְכַמָּה הוּא צָרִיךְ, וְנוֹתֵן לוֹ מִיָּד; וְאֵין מְחַיְּבִים אוֹתוֹ לָתֵת דְּבַר יוֹם בְּיוֹמוֹ, \u0010y20\u0011 וְדָבָר זֶה תַּקָּנָה הִיא לַמַּזִּיק. וְכֵן הַשֶּׁבֶת אוֹמְדִין אוֹתוֹ וְנוֹתֵן הַכֹּל מִיָּד; אִם הָיָה מִתְגַּלְגֵּל בְּחָלְיוֹ וְהוֹלֵךְ, וְאָרַךְ הַחֹלִי יוֹתֵר עַל מַה שֶּׁאֲמָדוּהוּ, אֵינוֹ מוֹסִיף לוֹ כְּלוּם; וְכֵן אִם הִבְרִיא מִיָּד, אֵין פּוֹחֲתִין מִמַּה שֶׁאֲמָדוּהוּ:\nאָמַר הַמַּזִּיק: אֵין רְצוֹנִי בְּתַקָּנָה זוֹ אֶלָּא אֶרְפָּאֶנּוּ דְּבַר יוֹם בְּיוֹמוֹ, שׁוֹמְעִין לוֹ. \u0010y21\u0011 הֲרֵי שֶׁלֹּא פָּסַק עִמּוֹ אֶלָּא הָיָה מְרַפֵּא יוֹם יוֹם, וְעָלוּ בּוֹ צְמָחִים מֵחֲמַת הַמַּכָּה, אוֹ נִסְתְּרָה הַמַּכָּה אַחֲרֵי שֶׁחָיְתָה, חַיָּב לְרַפּאוֹתוֹ וְלָתֵת לוֹ דְּמֵי שִׁבְתּוֹ; עָלוּ בּוֹ צְמָחִים \u0010y22\u0011 שֶׁלֹּא מַחֲמַת הַמַּכָּה, אֵינוֹ חַיָּב לְרַפּאוֹתוֹ וְלֹא לָתֵת לוֹ דְּמֵי שִׁבְתּוֹ.\nעָבַר עַל דִּבְרֵי הָרוֹפֵא וְהִכְבִּיד עָלָיו הַחֹלִי, אֵינוֹ חַיָּב לְרַפּאוֹתוֹ.\nאָמַר לוֹ הַמַּזִּיק: אֲנִי אֲרַפֵּא אוֹתְךָ, אוֹ: יֵשׁ לִי רוֹפֵא שֶׁמְּרַפֵּא בְּחִנָּם, \u0010y23\u0011 אֵין שׁוֹמְעִין לוֹ, אֶלָּא מֵבִיא רוֹפֵא אֻמָּן וּמְרַפְּאוֹ בְּשָׂכָר:\nאִם יֹאמַר הַמַּזִּיק: אָבִיא לְךָ רוֹפֵא מִמָּקוֹם רָחוֹק שֶׁיִּקַּח שָׂכָר מוּעָט, יָכוֹל הַנֶחְבָּל לוֹמַר לוֹ: הָרוֹפֵא שֶׁהוּא בִּמְקוֹמוֹ מְדַקְדֵּק יוֹתֵר, שֶׁלֹּא יַפְסִיד הַמְחָאָתוֹ.\nאָמַר הַנֶחְבָּל: תֵּן לִי שְׂכַר הָרוֹפֵא וַאֲנִי אֲרַפֵּא אֶת עַצְמִי, יָכוֹל הַחוֹבֵל לוֹמַר לוֹ: שֶׁמָּא לֹא תְּרַפֵּא עַצְמְךָ יָפֶה וְיִקְרְאוּ אוֹתִי מַזִּיק לְעוֹלָם.\nכֵּיצַד מְשַׁעֲרִין הַבֹּשֶׁת, הַכֹּל לְפִי הַמְבַיֵּשׁ וְהַמִּתְבַּיֵּשׁ; אֵינוֹ דוֹמֶה מִתְבַּיֵּשׁ מֵהַקָּטָן לַמִּתְבַּיֵּשׁ מֵאָדָם גָּדוֹל \u0010y24\u0011 וּמְכֻבָּד, שֶׁזֶּה שֶׁבִּיְּשׁוֹ הַקַּל בָּשְׁתּוֹ מְרֻבָּה. \u0005הַגָּה: וְכֵן הַמִּתְבַּיֵּשׁ, כְּפִי מַה שֶּׁכְּבוֹדוֹ גָדוֹל בָּשְׁתּוֹ מְרֻבָּה (טוּר)\u0006. וְהַמְבַזֶּה כֹּהֵן, בָּשְׁתּוֹ יוֹתֵר גְּדוֹלָה מִבְּאִישׁ אַחֵר \u0005(רִיבָ\"שׁ סִימָן נ\"ד)\u0006.\nצָעַק בְּאָזְנוֹ וְחֵרְשׁוֹ, \u0010y25\u0011 פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם. אָחֲזוֹ \u0010y26\u0011 וְתָקַע בְּאָזְנוֹ וְחֵרְשׁוֹ, אוֹ שֶׁהִכָּהוּ בְּאָזְנוֹ וְחֵרְשׁוֹ, נוֹתֵן לוֹ דְּמֵי כֻּלּוֹ אִם אֵינוֹ בַּעַל אֻמָּנוּת. וְאִם הוּא בַּעַל אֻמָּנוּת וְרָאוּי עֲדַיִן לְאוֹתוֹ אֻמָּנוּת, רוֹאִים כַּמָּה נִפְחֲתוּ דָמָיו וְנוֹתֵן לוֹ.\nסִמָּא עֵינוֹ וְלֹא אֲמָדוּהוּ, \u0005(קָטַע יָדוֹ וְלֹא אֲמָדוּהוּ)\u0006, וְקָטַע רַגְלוֹ וְלֹא אֲמָדוּהוּ, וְאַחַר כָּךְ חֵרְשׁוֹ, הוֹאִיל וְלֹא אֲמָדוּהוּ מִכָּל נֶזֶק וָנֶזֶק, \u0010y27\u0011 נוֹתֵן לוֹ דְּמֵי כֻּלּוֹ. \u0005הַגָּה: וּמְחֻיָּב לִתֵּן צַעַר וְרִפּוּי וּבֹשֶׁת שֶׁל כָּל מַכָּה וּמַכָּה, רַק שֶׁאוֹמְדִים הַכֹּל בְּיַחַד (טוּר סי\"ז בְּשֵׁם הָרֹא\"שׁ)\u0006. \u0010y28\u0011 אֲמָדוּהוּ לְכָל נֶזֶק וָנֶזֶק, וְאַחַר כָּךְ אֲמָדוּהוּ לְכֻלּוֹ, אֵין גּוֹבִין מִמֶּנּוּ אֶלָּא דְּמֵי כֻּלּוֹ בִּלְבַד. \u0010y29\u0011 וְאִם תָּפַס הַנִּזָּק נֶזֶק כָּל אֵבֶר וְאֵבֶר וּדְמֵי כֻלּוֹ, אֵין מוֹצִיאִין מִיָּדוֹ. \u0005הַגָּה: וּכְבָר נִתְבָּאֵר סִימָן שפ\"ח דְּיֵשׁ חוֹלְקִין וּסְבִירָא לְהוּ דְּלָא מְהַנֵּי תְפִיסָה (הָרֹא\"שׁ וְהַטּוּר)\u0006.\nכְּשֶׁבֵּית דִּין מַגְבִּין לַנֶּחְבָּל אַרְבָּעָה דְבָרִים, \u0010c3\u0011 אֵין נוֹתְנִים לַחוֹבֵל בָּהֶם שׁוּם זְמַן. אֲבָל אִם לֹא עָשָׂה בּוֹ דָּבָר \u0010y30\u0011 אֶלָּא שֶׁבִּיְּשׁוֹ, נוֹתְנִים לוֹ זְמַן כֵּיוָן שֶׁלֹּא חִסְרוֹ מָמוֹן. \u0010y31\u0011\nכְּשֵׁם שֶׁאוֹמְדִים לְמִיתָה, כָּךְ אוֹמְדִים לִנְזִיקִין. כֵּיצַד, הֲרֵי שֶׁהִכָּה \u0010y32\u0011 חֲבֵרוֹ בִּצְרוֹר קָטָן שֶׁאֵין בּוֹ כְּדֵי לְהַזִּיק, אוֹ בְּקֵיסָם שֶׁל עֵץ קָטָן, וְחָבַל בּוֹ חַבָּלָה שֶׁאֵין חֵפֶץ זֶה רָאוּי לַעֲשׂוֹתוֹ, \u0010y33\u0011 הֲרֵי זֶה פָטוּר, שֶׁנֶּאֱמַר: בְּאֶבֶן אוֹ בְאֶגְרֹף \u0005(שְׁמוֹת כא, יח)\u0006, דָּבָר הָרָאוּי לְהַזִּיק; \u0010y34\u0011 אֲבָל חַיָּב הוּא בְּבֹשֶׁת בִּלְבַד, שֶׁאֲפִלּוּ רָקַק בְּגוּפוֹ שֶׁל חֲבֵרוֹ חַיָּב בְּבֹשֶׁת; לְפִיכָךְ צְרִיכִים הָעֵדִים לֵידַע בַּמֶּה הִזִּיק, וּמְבִיאִים הַחֵפֶץ שֶׁהִזִּיק בּוֹ לְבֵית דִּין, עַד שֶׁאוֹמְדִין אוֹתוֹ וְדָנִין עָלָיו. וְאִם אָבַד הַחֵפֶץ, וְאָמַר הַחוֹבֵל: לֹא הָיָה בּוֹ כְּדֵי לְהַזִּיק, וְנֶחְבָּל אוֹמֵר: הָיָה בּוֹ כְּדֵי לְהַזִּיק, \u0010y35\u0011 יִשָּׁבַע הַנֶּחְבָּל \u0010y36\u0011 וְיִטֹּל.\nהַבַּרְזֶל, אֵין לוֹ אֹמֶד; אֲפִלּוּ מַחַט קְטַנָּה רְאוּיָה הִיא לְהָמִית, וְאֵין צָרִיךְ לוֹמַר לְהַזִּיק. וְדַוְקָא כְּעֵין מַחַט, שֶׁהִיא חַדָּה, אֲבָל אִם לֹא הִזִּיק אֶלָּא מֵחֲמַת מִשְׁקָלוֹ, \u0010y37\u0011 שֶׁאֵינוֹ מְחֻדָּד כְּלָל, אוֹמְדִים אוֹתוֹ כִּשְׁאָר דְּבָרִים.\nהַזּוֹרֵק אֶבֶן, וּלְאַחַר שֶׁיָּצְאָה מִתַּחַת יָדוֹ הוֹצִיא הֲלָה רֹאשׁוֹ מֵהַחַלּוֹן וְקִבְּלָהּ, פָּטוּר מִכֻּלָּם, שֶׁנֶּאֱמַר: וּמָצָא אֶת רֵעֵהוּ \u0005(דְּבָרִים יט, ה)\u0006, פְּרָט לְמַמְצִיא אֶת עַצְמוֹ.\nהַחוֹבֵל בְּעַצְמוֹ, אַף עַל פִּי שֶׁאֵינוֹ רַשַּׁאי, \u0005(פָּטוּר)\u0006 \u0010y38\u0011 ; אֲחֵרִים שֶׁחָבְלוּ בּוֹ, חַיָּבִים.\nהַמַּבְעִית אֶת חֲבֵרוֹ, אַף עַל פִּי שֶׁחָלָה מֵהַפַּחַד, פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם; וְהוּא שֶׁלֹּא נָגַע בּוֹ, כְּגוֹן שֶׁצָּעַק לוֹ מֵאֲחוֹרָיו, אוֹ שֶׁנִּרְאָה לוֹ בַּאֲפֵלָה וְכַיּוֹצֵא בּוֹ. וְכֵן אִם זָעַק לוֹ בְּאָזְנוֹ וְחֵרְשׁוֹ, פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם. \u0010y39\u0011 אָחֲזוֹ וְתָקַע לוֹ בְּאָזְנוֹ וְחֵרְשׁוֹ, אוֹ שֶׁנָּגַע בּוֹ וַהֲדָפוֹ בְּשָׁעָה שֶׁהִבְעִיתוֹ, אוֹ שֶׁאָחֲזוֹ בִּבְגָדָיו, חַיָּב בְּתַשְׁלוּמִין.\nאִם הַנֶחְבָּל אוֹמֵר: נֶחֱרַשְׁתִּי, נִסְמֵית עֵינִי, וְאֵינִי רוֹאֶה, אוֹ: אֵינִי שׁוֹמֵעַ, אֵינוֹ נֶאֱמָן, שֶׁאֵין אָנוּ מַכִּירִים הַדָּבָר וְשֶׁמָּא יַעֲרִים, וְאֵינוֹ נוֹטֵל הַנֶּזֶק עַד שֶׁיִּבָּדֵק זְמַן מְרֻבֶּה וְיִהְיֶה מֻחְזָק שֶׁאָבַד מְאוֹר עֵינָיו אוֹ נִתְחָרֵשׁ, וְאַחַר כָּךְ יְשַׁלֵּם זֶה. \u0010y40\u0011\nהַמְבַיֵּשׁ אֶת הֶעָרֹם אוֹ מִי שֶׁהוּא בְּבֵית הַמֶּרְחָץ, פָּטוּר. נָשְׁבָה בּוֹ הָרוּחַ וְהִגְבִּיהַּ בְּגָדָיו וְנִרְאָה כְּעָרֹם, וּבָא אַחֵר וְהוֹסִיף בְּהַפְשָׁטָתוֹ, חַיָּב בְּבֹשֶׁת; וּמִכָּל מָקוֹם, אֵין בָּשְׁתּוֹ שֶׁל זֶה מְרֻבָּה כְּמוֹ הַמְבַיֵּשׁ אֶת שֶׁאֵינוֹ עָרֹם כְּלָל. וְכֵן אִם הִגְבִּיהַ בְּגָדָיו לֵירֵד לַנָּהָר, אוֹ שֶׁעָלָה מִנָּהָר, וּבִיְּשׁוֹ, חַיָּב; וּמִכָּל מָקוֹם, אֵינוֹ כָּל כָּךְ בֹּשֶׁת כְּמוֹ שֶׁמְּבַיֵּישׁ הַמְלֻבָּשׁ.\nבִּיְּשׁוֹ כְּשֶׁהוּא יָשֵׁן, וּמֵת \u0005(בְּתוֹךְ שְׁנָתוֹ)\u0006, שֶׁלֹּא הִרְגִּישׁ בְּבֹשֶׁת, אֵין גּוֹבִין אוֹתוֹ \u0010y41\u0011 בֹּשֶׁת; וְאִם תָּפְסוּ יוֹרְשָׁיו, אֵין מוֹצִיאִין מִיָּדָם. \u0010y42\u0011 \u0005וְיֵשׁ אוֹמְרִים שֶׁהוּא פָּטוּר (טוּר סכ\"ו בְּשֵׁם הָרֹא\"שׁ)\u0006. \u0010y43\u0011\nיָשֵׁן שֶׁבִּיֵּשׁ, פָּטוּר.\nהַמְבַיֵּשׁ אֶת \u0010y44\u0011 הַשּׁוֹטֶה, פָּטוּר. אֶת הַחֵרֵשׁ, אוֹ אֶת הַגֵּר, אוֹ אֶת הָעֶבֶד, אוֹ \u0010y45\u0011 אֶת הַקָּטָן שֶׁכְּשֶׁמַּכְלִימִים אוֹתוֹ נִכְלָם, חַיָּב. וּמִכָּל מָקוֹם, אֵינוֹ דוֹמֶה הַמְבַיֵּשׁ אֶת הַקָּטָן לַמְּבַיֵּשׁ אֶת הַגָּדוֹל, וְלֹא הַמְבַיֵּשׁ אֶת הָעֶבֶד לַמְּבַיֵּשׁ בֶּן חוֹרִין, וְלֹא הַמְבַיֵּשׁ חֵרֵשׁ לַמְּבַיֵּשׁ פִּקֵּחַ. \u0010y46\u0011 \u0010c4\u0011\nרָקַק בַּחֲבֵרוֹ, חַיָּב. אֲבָל רָקַק בִּבְגָדָיו, אוֹ שֶׁבִּיְּשׁוֹ בִּדְבָרִים, פָּטוּר; וְיֵשׁ לְבֵית דִּין בְּכָל מָקוֹם וּבְכָל זְמַן לִגְדֹּר כְּפִי מַה שֶּׁיִּרְאוּ. וְיֵשׁ \u0010y47\u0011 אוֹמְרִים שֶׁמְּנַדִּין אוֹתוֹ עַד שֶׁיְּפַיֵּס הַמְבֻיָּשׁ. \u0005הַגָּה: \u0010y48\u0011 וְיֵשׁ אוֹמְרִים דְּמַכִּין אוֹתוֹ מַכַּת מַרְדוּת (בֵּית יוֹסֵף ס\"ס א' בְּשֵׁם מָרְדְּכַי פֶּרֶק הַזָּהָב)\u0006. וְהַמּוֹצִיא שֵׁם רָע עַל חֲבֵרוֹ, הָוֵי בִּכְלַל הַמְבַיֵּשׁ בִּדְבָרִים \u0005(פִּסְקֵי מהרא\"י סִימָן רי\"ב ות\"ה סִימָן ש\"ז)\u0006. הַמְקַנְטֵר חֲבֵרוֹ וְאָמַר \u0010y49\u0011 לֵהּ: אֵינִי מוּמָר וְאֵינִי עֲבַרְיָן, אַף עַל פִּי שֶׁלֹּא אָמַר: כָּמוֹךָ, הָוֵי כְּאִלּוּ פֵּרַשׁ כָּמוֹךָ \u0005(בֵּית יוֹסֵף מָצָא כָתוּב מהרי\"ו סִימָן קנ\"ז)\u0006. הָאוֹמֵר לַחֲבֵרוֹ: הֲרֵי אַתָּה עוֹשֶׂה כְּמוֹ מַמְזֵר, אוֹ: אַתָּה כְּמַמְזֵר, אֵינוֹ כְלוּם \u0005(מהרי\"ו סִימָן נ\"ט)\u0006. וְיֵשׁ חוֹלְקִין וּסְבִירָא לְהוּ שֶׁאִם אוֹמֵר: אַתָּה כְּמַמְזֵר, כְּאִלּוּ קְרָאוֹ מַמְזֵר \u0005(פִּסְקֵי מהרא\"י סִימָן רנ\"ז וְסִימָן קל\"ה וּמַהֲרִי\"ט סִימָן קכ\"ז וַאֲגֻדָּה פ\"ב דְּיוֹמָא)\u0006 ; אֲבָל אִם אוֹמֵר: אַתָּה מְכַזֵּב כְּמוֹ מַמְזֵר עַד שֶׁתִּתְבָּרֵר דָּבָר זֶה, אוֹ כַיּוֹצֵא בָּזֶה שֶׁהֵטִיל בַּדָּבָר תְּנַאי, אֵינוֹ כְלוּם \u0005(פִּסְקֵי מהרא\"י סִימָן קל\"ה)\u0006. הָאוֹמֵר לַחֲבֵרוֹ: פָּסוּל אַתָּה, \u0010y50\u0011 יֵשׁ אוֹמְרִים דְּיָכוֹל לְתָרֵץ דְּפָסוּל מִשּׁוּם קוּרְבָה קָאָמַר וְאֵין זֶה בִּיּוּשׁ \u0005(מהרי\"ו סִימָן נ\"ט)\u0006. \u0010y51\u0011 וְיֵשׁ חוֹלְקִין \u0005(מַהֲרַ\"ם מֵרִיזְבּוּרְק)\u0006. \u0010c5\u0011 הַמְדַבֵּר רָע עַל שׁוֹכְנֵי עָפָר, צָרִיךְ לְקַבֵּל עָלָיו תַּעֲנִיּוֹת וּתְשׁוּבָה וְעֹנֶשׁ מָמוֹן כְּפִי רְאוֹת בֵּית דִּין \u0005(מָרְדְּכַי פֶּרֶק הַחוֹבֵל)\u0006 ; וְאִם קְבוּרִים בְּסָמוּךְ לוֹ, יֵלֵךְ עַל קִבְרֵיהֶם וִיבַקֵּשׁ מֵהֶם מְחִילָה, וְאִם הֵם רְחוֹקִים \u0010y52\u0011 יִשְׁלַח שָׁם שְׁלוּחוֹ \u0005(מַהֲרַ\"ם מֵרִיזְבּוּרְק)\u0006. וְאִם כּוֹפֵר הַמְבַיֵּשׁ, אִם הוּא בִּיּוּשׁ שֶׁל שׁוֹכְנֵי עָפָר, יִתְּנוּ חֵרֶם בְּעֵדוּת, \u0010y53\u0011 \u0010c6\u0011 אֲבָל לֹא עַל בִּיּוּשִׁים אֲחֵרִים \u0005(מָרְדְּכַי הַנַּ\"ל מהרי\"ו סִימָן כ\"ח)\u0006. וְנִרְאֶה, דְהַכֹּל לְפִי רְאוֹת בֵּית דִּין. וְעַיִּןִ לְעֵיל סִימָן פ\"ז סָעִיף כ\"ה. הַקּוֹרֵא \u0010y54\u0011 לַחֲבֵרוֹ מַלְשִׁין בֶּן מַלְשִׁין, אִם הוּא לְבַד מַלְשִׁין, פָּטוּר. וְכֵן אִם קוֹרֵא לְרָשָׁע בֶּן צַדִּיק: רָשָׁע בֶּן רָשָׁע \u0005(הַגָּהוֹת מָרְדְּכַי)\u0006. \u0010y55\u0011 \u0010c7\u0011 הַקּוֹרֵא לַחֲבֵרוֹ עֶבֶד אוֹ מַמְזֵר, וְהוּא אֱמֶת, פָּטוּר; אֲבָל אִם לֹא יוּכַל לְבָרֵר, אַף עַל גַּב דְּשָׁמַע כֵּן שֶׁאֲחֵרִים דִּבְּרוּ כָךְ, לֹא נִפְטָר בְּכָךְ \u0005(נִמּוּקֵי מַהֲרַ\"ם)\u0006 \u0005(וע\"ל סי' תכ\"א ס\"ג)\u0006.\nאַף עַל פִּי שֶׁהַמְבַיֵּשׁ בִּדְבָרִים אֵינוֹ בַּר תַּשְׁלוּמִין, עָוֹן גָּדוֹל הוּא; וְאֵין הַמְחָרֵף וּמְגַדֵּף לָעָם וּמְבַיְּשָׁן אֶלָּא שׁוֹטֶה רָשָׁע וְגַס רוּחַ. וְכָל הַמַּלְבִּין פְּנֵי אָדָם כָּשֵׁר מִיִּשְׂרָאֵל בִּדְבָרִים, אֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא. \u0010c8\u0011\nדִּין הַמְבַיֵּשׁ תַּלְמִיד חָכָם בִּדְבָרִים, נִתְבָּאֵר בְּטוּר י\"ד \u0005סִימָן רמ\"ג סָעִיף ז'.\u0006\nיֵשׁ הַכָּאוֹת רַבּוֹת שֶׁיֵּשׁ בָּהֶם בִּזּוּי וְצַעַר מְעַט, וְאֵין בָּהֶם נֶזֶק; וּכְבָר פָּסְקוּ לָהֶם חֲכָמִים דָּמִים קְצוּבִים, וְכָל הַמַּכֶּה אֶת חֲבֵרוֹ הַכָּאָה מֵהֶן, מְשַׁלֵּם אוֹתוֹ הַמָּמוֹן הַקָּצוּב; וְכֻלָּם קְנָסוֹת הֵן. וְאוֹתוֹ הַמָּמוֹן הַקָּצוּב \u0010y56\u0011 הוּא דְּמֵי הַצַּעַר וְהַבֹּשֶׁת וְהָרִפּוּי וְהַשֶּׁבֶת, \u0010y57\u0011 בֵּין צָרִיךְ לִרְפוּאָה בֵּין לֹא צָרִיךְ, זֶהוּ מְשַׁלֵּם. וְכַמָּה הוּא מְשַׁלֵּם, הַבּוֹעֵט בַּחֲבֵרוֹ בְּרַגְלוֹ, מְשַׁלֵּם ה' סְלָעִים; הִכָּהוּ בְּאַרְכּוּבָתוֹ, מְשַׁלֵּם ג' סְלָעִים; קִבֵּץ אֶצְבְּעוֹתָיו כְּמוֹ אוֹגֵד אֲגֻדָּה וְהִכָּהוּ בְּיָדוֹ כְּשֶׁהִיא אֲגֻדָּה, מְשַׁלֵּם י\"ג סְלָעִים; תָּקַע אֶת חֲבֵרוֹ בְכַפּוֹ, מְשַׁלֵּם סֶלַע; סְטָרוֹ עַל פָּנָיו, מְשַׁלֵּם חֲמִשִּׁים סְלָעִים; סְטָרוֹ בַּאֲחוֹרֵי יָדוֹ, מְשַׁלֵּם ק' סְלָעִים; וְכֵן אִם צָרַם בְּאָזְנוֹ אוֹ תָלַשׁ בִּשְׂעָרוֹ אוֹ רָקַק וְהִגִּיעַ בּוֹ \u0010y58\u0011 הָרֹק, מְשַׁלֵּם מֵאָה סְלָעִים. וְכָזֶה הוּא מְשַׁלֵּם עַל כָּל מַעֲשֶׂה וּמַעֲשֶׂה; כֵּיצַד, כְּגוֹן שֶׁבָּעַט בַּחֲבֵרוֹ אַרְבַּע בְּעִיטוֹת, אֲפִלּוּ זוֹ אַחַר זוֹ, מְשַׁלֵּם עֶשְׂרִים סְלָעִים. סְטָרוֹ עַל פָּנָיו שְׁתֵּי סְטִירוֹת, מְשַׁלֵּם מֵאָה סֶלַע, וְכֵן בַּשְּׁאָר. \u0005הַגָּה: יֵשׁ אוֹמְרִים אַף עַל גַּב דְּאִיתָא בַגְּמָרָא הַקּוֹרֵא לַחֲבֵרוֹ מַמְזֵר סוֹפֵג אַרְבָּעִים, מִכָּל מָקוֹם יֵשׁ מְקוֹמוֹת שֶׁאֵין נוֹהֲגִין כֵּן, וְהוֹלְכִין אַחַר הַמִּנְהָג (הָרֹא\"שׁ כְּלָל ק\"א סִימָן א')\u0006. וְנִרְאֶה לִי, דְּהוּא הַדִּין בְּאֵלּוּ הַדְּבָרִים הַנִּזְכָּרִים:\nכָּל אֵלּוּ הַסְלָעִים, הֵם מִכֶּסֶף מְדִינָה שֶׁאֵין בּוֹ כֶּסֶף \u0010y59\u0011 אֶלָּא שְׁמִינִית, שֶׁהֵם שָׁלֹשׁ מָעִין, שֶׁכָּל מָעָה מִשְׁקָל ט\"ז שְׂעוֹרוֹת כֶּסֶף צָרוּף, שֶׁהוּא עוֹטָמָנִי אֶחָד.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בִּמְכֻבָּד. אֲבָל אָדָם שֶׁהוּא מְבֻזֶּה וְאֵינוֹ מַקְפִּיד בְּכָל אֵלּוּ הַדְּבָרִים וְכַיּוֹצֵא בָּהֶם, אֵינוֹ אֶלָּא כְּפִי מַה שֶּׁיִּרְאוּ הַדַּיָּנִים שֶׁרָאוּי לִטֹּל. \u0005הַגָּה: יֵשׁ אוֹמְרִים שֶׁאֵלּוּ הַדְּבָרִים אֵינָן רַק מִשּׁוּם בֹּשֶׁת וְצַעַר, אֲבָל רִפּוּי וָשֶׁבֶת הַכֹּל לְפִי הָעִנְיָן (טוּר סל\"ד בְּשֵׁם הָרִי\"ף וְכ\"כ הָרֹא\"שׁ בִּשְׁמוֹ)\u0006.\nכֵּיצַד מַגְבִּין הָאִדָּנָא חַבָּלוֹת וּקְנָסוֹת אֵלּוּ, נִתְבָּאֵר בְּסִימָן א'.",["\u0003שנאמר פן יוסיף כו' \u0004 בסוף פ' כי תצא כתיב והי' אם בן הכות הרשע וגו' ארבעים יכנו ולא יוסיף פן יוסיף להכותו כו' והנה הטור והמחבר למדו הלאו מדכתיב פן יוסיף לרמוז למ\"ש כל מקום שנ' השמר פן ואל אינו אלא ל\"ת אבל ברמב\"ם פ\"ה דחובל למדו מדכתיב בהדיא בקרא לא יוסיף וכן פירש\"י שם בפי' החומש ז\"ל לא יוסיף מכאן אזהר' למכה את חבירו וניחא ליה להרמב\"ם ללמדו מלא יוסיף שהוא לאו מפורש והטור והמחבר לא ניחא להו ללמדו מלא יוסיף משום דקאי אהכאת הרשע וי\"ל דדוקא נקיט שם דנלקה כבר ל\"ט מכות ויש סכנה בהוספ' לו עוד מכה א' משא\"כ בהכאה לחבירו מכה א' מ\"ה למדוה מיתורא דפן יוסיף ועמ\"ש בפרישה עוד מזה:","\u0003בהכאת הרשע. \u0004 דשם בקרא ארשע קאי כנ\"ל:","\u0003אף ע\"פ שלא הכהו. \u0004 דכתיב רשע למה תכה רעך הכית לא נאמר אלא תכה:","\u0003דיש חרם קדמונים אדם המכה לחבירו וצריכין להתיר לו כו'. \u0004 הל' משמע דא\"צ לנדותו עתה מחדש אלא מנודה ועומד זה המכה מהחרם שהחרימו ע\"ז הקדמונים וקאמר דצריך להתיר עתה אותו חרם למי שעברו ונ\"ל דה\"ה ☜ היכן שנזכרו בדברי האחרונים שהקהלות החרימו ע\"ז או שיש בו חרם ר\"ג נמי פי' הכי שא\"צ לנדותו עתה מחדש אלא שהוא מוחרם ועומד העובר על דברי תקנות ומדסתם מור\"ם וכ' ז\"ל וצריכין להתיר לו כו' משמע דר\"ל כסתם התרת נדרים שהוא בג' וכמ\"ש הטור והמחבר בי\"ד סי' של\"ד ולא כמו שעלה על דעת חכם א' לו' שכל מקום שנזכר בדברי האחרונים ז\"ל שהקהלות החרימו ע\"ז דאין לו התרה כ\"א בק' אנשים מג' קהילות מג' מדינות שלא מצינו שהחמירו בזה כ\"א בהרוצה לישא אשה על אשתו הראשונה משום צורך שהתירוהו עליו להנשא ודוקא אחר היתר גדול כזה אבל בשאר חרמות הקהלות או דר\"ג לא מצינו זה ודו\"ק:","\u0003כיון שאין בו חיוב ממון. \u0004 אבל אם יש בו חיוב ממון נותן ממון ואין לוקין אותו אע\"ג דאתרו ביה ולמדינן לה בגמ' מדכתיב כאשר עשה כן יעשה לו כן ינתן בו תו ל\"ל אלא דבר שיש בו נתינה ומאי נינהו ממון. וממון ומלקות כחדא פשיטא דלא מענשין אותו דכתיב כדי רשעתו כדי רשעה א' ולא ב' רשעות וע\"ל ר\"ס תכ\"ד מ\"ש עוד מזה:","\u0003עבד כנעני של חבירו. \u0004 והב\"י תמה שם עליהן וכ' דאפי' עבד כנעני שלו נמי דינא הכי כיון דחייב במצות ומ\"ה השמיטו ג\"כ כאן בש\"ע תיבת של חבירו ובדריש' כתבתי ליישב זה והוא דכיון דנתבאר דבמכ' שיש בה ש\"פ משלמין ואין לוקין וחיוב תשלומין לא שייך במכה עבד שלו דמה שקנה עבד קנה רבו ומ\"ה גם בהכא' דפחות מש\"פ לא מצינו גבי אדונו שום חיוב דאם באנו לחייבו עליה מלקות יבא להכותו מתחל' מכה רבה שיהיה בו ש\"פ כדי שיפטר בו מכל וכל ומ\"ה סתם הטור והמחבר לקמן בסי' תכ\"ד ס\"ג וכ' דהחובל בעבדו הכנעני פטור וכ\"כ הרמב\"ם בפ\"ב דהחובל דין י' ע\"ש ודוחק לומר דאיירי דוקא בחבל' שיש בו ש\"פ ומעלה ולא בפחות ממנו ועיין מ\"ש בדריש' שם וכאן:","\u0003חייב בחמש' דברים. \u0004 בגמרא ילפינן מקרא ועפ\"ר:","\u0003על ידו וצבתה. \u0004 מל' וצבתה בטנה דהיינו נפחה:","\u0003הכהו במקום שאינו נראה ולא ראוהו שום אדם \u0004 פי' תרתי בעינן שלא ראוהו בשעת הכאה וגם שתהא המכה עומדת במקום שלא תהיה נרא' לאחר זמן:","\u0003אלא ריפוי לבד. \u0004 כדי להחזירו למרא' עורו:","\u0003הוה גרמא בניזקין דומה לזה כ' הטור והמחבר [והרב] לעיל בסי' שס\"ג בסגירת בית חבירו ומעכבו מלדור בו ע\"ש:\u0004","\u0003אלא בשת. \u0004 דסופו לחזור השערות:","\u0003שהרי מצטער מן הסם. \u0004 שעושה בקעים בראשו מחמת חריפותו וצריך ריפוי לרפאותו ונזק אין לך נזק גדול מזה שלא יהיה לו שערות לעולם לחמם בהן ראשו גם בשת יש לו מזה הן בשעה שסכו כשאר מכה שיש לו בשת מה שרואין שהכהו וגם אח\"כ במה שרואין שאין לו שערות ונעשה קרח:","\u0003ולנדנד ראשו. \u0004 בטור כתב שער ראשו ועפ\"ר דהוכחתי דל\"ד קאמר שער ראשו דהנדנוד בראשו בשעת ריקודו נעשה גם בלא שערות (דאל\"כ גם בגילח לו שערות היה לו לחייבו ועוד דא\"כ בכלל נזק יחשב וכיון דכבר שילם לו נזקי דמי שערות שלו בכללו הוא השבת דשערות) אלא שכל זמן שראשו עליו יכאב אינו יכול להתעסק במלאכת ריקוד ונדנוד ראשו והוא שבתו והאי שבת לאו בכל ענין מתחייב בו אא\"כ מלאכתו הוא בכך וכן הוא לשון הטור ז\"ל ושבת אם הוא יודע לרקד בו ע\"ש:","\u0003אלא צלקת. \u0004 פי' שחיתה המכה ובעור נשאר רושם המכה לעולם. והמ\"מ כ' והב\"י הביאו דצ\"ע בחובל בבתו משמע דאינו חייב בזה כ\"א בחבל בפניה דשם יש הקפדה ברושם וכאן סתם המחב' ובפריש' כתבתי שי\"ל דדוקא בתו אינה מקפדת עם אביה בשאר מקומות משא\"כ איש זה עם איש אחר ע\"ש:","\u0003כאלו הוא עבד נמכר בשוק. \u0004 רש\"י ונ\"י ר\"פ החובל פירשו כאלו נמכר להיות עבד עברי אבל הרא\"ש כתב שם דשמינן ליה כמו עבד כנעני דנמכר לעבד לעולם כי גם חסרון אברו הוא לעולם משא\"כ עבד עברי שאינו נמכר אלא לו' שנים ואם באנו לשומו בכל ו' שנים פעם אחר פעם יעלה לערך יותר ממה שיעלה הערך כששמין אותו פעם אחת וגם כבר כתבתי מזה בסי' א' ואפי' הוא אדם חשוב שיימינן נזקו כעבד ואשר נגע בכבוד חשיבתו זה משלם לו בכלל בושת שהיא משתלמת לפי המתבייש כדלקמן אבל לענין נזק הכל שווין:","\u0003שאינו מזיק לו כ\"כ. \u0004 לשון הטור בשם הרא\"ש ויראה דשומא זו ששמין לאדם כפי מלאכתו היינו דוקא להוסיף בשומא כגון אם קיטע ידו של עבד נוקב מרגליות אבל אם קיטע רגלו והיתה שומתו פחותה משומת עבד העומד לשימוש לפי שהעבד הנוקב מרגליות אין רבו מקפיד כל כך על חסרון רגלו שעדיין הוא ראוי למלאכתו ראשונה ויותר יהיה עתה קבוע במלאכתו לא ישומו אותו כנוקב מרגליות דמסתברא (יעמוד) שלא יפסיד באומנתו לפי שאם ירצה לא יעשה דבר זה ויהי' כשאר כל אדם הנמסר לכל מיני תשמיש עכ\"ל ולזה כוון מור\"ם ז\"ל בקיצור לשונו:","\u0003אם גזר המלך לקטוע בסייף \u0004 שהרי גם כאן גזר המלך הש\"י שכאשר עשה וחתכו לחבירו בסייף כן יעשה לו אלא שלמדנו שעשייה זו היא נתינת ממון ומ\"ה אף שישלם לו דמי נזק ידו עדיין עליו לשלם מה שציערו בקטיעת היד ומן הדין עליו לשלם לו דמי צער קטיעת סייף כמו שעשה אלא שמשום דמה שקיטע ידו דחבירו כבר נעשה ולקטוע ידו לכתחלה אין אדם לוקח דמים הרבה מ\"ה אמרו חכמים לשער כמה היה כשהיה נותן לחתוך בסם למי שנגזר עליו חתיכת סייף דמדכתיב וביער בשדה אחר ואחז\"ל שלא ישום הערוגה שהזיקה לבד אלא ישומו אגב כל השדה וכמ\"ש לעיל סי' שצ\"ד למדונו שהתורה חסה על המזיק להקל לו בשומא אשר\"י:","\u0003אם היה גוזר המלך לכוות כו'. \u0004 אבל אין שמין כמה אדם רוצה ליקח להכוות אותו בשפוד דאין אדם לוקח הרבה כדי להצטער בתחלה בכזה וכנ\"ל","\u0003כפעל בטל כו' \u0004 לשון הטור הוא מבוא' בדין זה יותר והנה אעתיקו נותן לו כפועל בטל של אותה מלאכה דבטל ממנו ורואין כמה היה רוצה ליקח ויהיה בטל וזה תלוי כפי מה שהוא מלאכתו שיש מלאכה כבידה ושכרה מועט שהיה לוקח מעט שישב בטל ויש מלאכה קלה ששכרה הרבה וצריכין ליתן לו הרבה שישב בטל ממנה (ודומה לזה כתב הטו' בפועל בטל בי\"ד סי' שי\"ב בדין ראית בכור במומו ע\"ש והרמב\"ם הוסיף בזה וכתב דאם הוא אדם שהבטלה קשה לו כאוכלסי דמחוזאי צריך ליתן לו כל שכרו ודומה לזה כתב הטור לעיל ס\"ס של\"ד ושל\"ה ע\"ש) ואם חסרו אבר כבר נתן לו נזק שהוא דמי האבר כגון אם קטע ידו כבר נתן לו מה ששוה פחות לפי שאינו יכול לעשות מלאכה בידו אבל עדיין הוא ראוי לשמור קישואין לכשיתרפא לפיכך נותן לו כל ימי משך חליו בכל יום ויום כמו שנותנין לשומר קישואין (ובסעיף שאחר זה יתבאר דנותנין לו מיד הריפוי והשבת דכל ימי חליו והוא לטובת המכה וכמו שיתבא' שם ומה\"נ דקדק הרמב\"ם וכ' כאן ז\"ל ועושין חשבון כל ימי חליו של זה ונותן לו ר\"ל נותן לו מיד בפעם א') וכן אם שיבר רגל א' עדיין הוא ראוי לשמר קישואין (וכן אם נחתך ידו ורגלו א') שבר שני רגליו אינו ראוי לשמו' קישואין (דשומר קישואים צריך לסבב הגנים ולילך בכל צד לשומרם) אבל ראוי לישב במקום א' לשמור הפתח וכן יתן לו כל ימי משך חליו (והמותר עולה לו בדמי נזקו שהוא בזה יותר גדול מאילו לא חיסר אלא רגל א' וכן בסימא עינו בסמוך והכלל כל שהשבת יותר מעט נזקו יותר גדול) סימא לו עינו א' עדיין הוא ראוי לו למלאכה ראשונה (פי' ונותן לו השבת כל ימי חליו מכאיבת עינו הא' כפועל בטל ממלאכתו הראשונה וכנ\"ל) סימא ב' עיניו אז אינו ראוי אחר שיתרפא אלא לטחון ברחיים וכן יתן לו כל ימי חליו וכתב א\"א הרא\"ש ז\"ל דכל זה הוא בסתם בני אדם שאינם בני אומנות אבל אם הוא בעל מלאכה שמין השבת לאותה מלאכה שיכול לעשות אחר שיתרפא (וז\"ש מור\"ם ודוקא בסתם כו') כגון אם הוא מלמד תינוקות וקיטע את ידו או שיבר את רגלו לאחר שיתרפאו הוא ראוי למלאכתו וגם אם היה ניקב מרגליות ושיבר את רגלו לכשיתרפא ראוי הוא למלאכתו ולמה ישומו אותו בימי חליו כשומר קשואין עכ\"ל הטור ובזה דברי המחב' מבוארין דמ\"ש קיטע רגלו ר\"ל שני רגליו ומ\"ש סימא את עינו ר\"ל ב' עיניו ודוק:","\u0003ודבר זה תקנה הוא למזיק. \u0004 דאם היה צריך לתת לו שכר רפוי דבר יום ביומו שמא יתרשל המוכה ברפואתו באמרו דמי הרפואה הן על המכה אצערנו בזה כדי שיוציא הרבה דמים וזה שמסיק וכ' דאם היה מתגלגל וארך החולה אינו מוסיף לו כלום ואף דלפעמים יהיה להמכה בזה הפסד דאם הבריא מיד דאין פוחתין לו מהאומד כדמסיק זהו דבר שאינו שכיח שיבריא קודם זמן שאמדוהו לכך משא\"כ בהמשך חליותו דאיכא למיחש כנ\"ל ועוד כמה סבות וגרמות הן דימשך חליותו:","\u0003הרי שלא פסק עמו וכו' \u0004 משמע דאפי' סתמא נמי כל שלא פסק ונתן דבר יום ביומו ועלתה בו צמחים חייב בריפוי ושבת הצמחים מ\"ה דרך המכה לדרוש טובתו ולפסוק וכנ\"ל ולא כע\"ש דכ' ז\"ל אמר המזיק ליתן דבר יום ביומו ועלה בו צמחים כו' דבלא אמירה כן נמי דינא הכי וק\"ל.","\u0003שלא מחמת מכה. \u0004 בגמ' דף פ\"ה ע\"א פריך פשיטא ומשני קמ\"ל דאפי' א\"ל אל תאכל מיני מתיקה והוא אכלם ועלה בו צמחים כיון דעבר על דברי הרופא שלא מחמת מכה מיקרי והטו' והמחב' כתבו מתחלה שלא מחמת מכה ובכללא הוא זה דאכל מיני מתיקה ואח\"כ כ' ג\"כ עבר על דברי הרופא לרבות שאר כל דבר:","\u0003אין שומעין לו \u0004 בגמ' מפרש טעמא דאם אמר אני ארפאך יאמר לו דמית עלי כאריא ארבא ועל רופא אחר חנם יאמר רופא שאינו מקבל תשלומין אין מדקדק ברפואתו ובטו' כ' ה\"ט בתרא גם אאם א\"ל ואני ארפאך ע\"ש:","\u0003שזה שביישו הקל בשתו מרובה. \u0004 בפרישה כתבתי בשם רש\"י והר\"ן דבושת אדם בינוני מרובה משל אדם נכבד ומזולזל חוץ באונס ומפתה שבושת הקל מהמזולזל בושתו יותר:","\u0003פטור מדיני אדם כו'. \u0004 דכל שלא אחזו לעשות מעשה בגופו גרמא בעלמא מיקרי ומ\"מ חייב בדיני שמים כיון שנחרש בסיבתו:","\u0003ותקע באזנו כו' \u0004 וכתב המרדכי פ' החובל דאף דלא תקע באזנו אלא הכה על הכותל כנגד אזנו ונתחרש חייב אם אחזו עכ\"ל ד\"מ כ\"ד:","\u0003נותן לו דמי כלו \u0004 ל' הטור וכ' א\"א הרא\"ש ז\"ל לענין נזק ושבת אין חילוק בין חד אומדנא ובין כל אבר ואבר לבד דבכל שומא שמין כמה נחסרו דמיו בשביל אותו אבר עד שיצטרפו כל איבריו יחד וגם שבת שבין הכאה להכאה פשיטא שנותן לו כי עדיין הוא ראוי למלאכה כשיתרפא כל זמן שלא חרשו ואין חילוק אלא לענין צער וריפוי ובושת ודבר פשוט דצריך ליתן לו צער ריפוי ובושת של כל מכה ומכה בפני עצמה אלא יותר יעלו כשישומו כל מכה ומכה בפני עצמה ממה שיעלו כשישומו כאילו עשאן כולם כאחד ואין ביניהן אלא דבר מועט אבל בנזק ושבת אפי' מועט כזה אין ביניהן כי גם לבסוף שמין כמה נפחת דמיו בשביל כל אבר ואבר בפני עצמו עכ\"ל בקצת שינוי ל' לתוס' ביאור וז\"ש מור\"ם בהג\"ה דנותן לו צער ריפוי ובשת באומדן הכל יחד שבהן יש נ\"מ בין אומדנא יחד או כל א' וא' בפני עצמו משא\"כ בנזק ושבת דאין ביניהן חילוק כלל.","\u0003אמדוהו לכל נזק ונזק כו'. \u0004 איבעיא דלא איפשטא הוא בגמרא ופסק הרמב\"ם כפי שטתו בכל תיקו דממונא דאם לא תפס דהוה קולא לנתבע וחומרא לתובע ואינו משלם לו אלא דמי כולו ואם תפס דמי אומדן לכל אבר בפני עצמו מהני תפיסתו ע\"ז כ' מור\"ם דבסי' שפ\"ח נתבאר די\"ח וס\"ל דלא מהני תפיסה בספיקא דדינא ודע דהרא\"ש והטור הן בעלי סברא זו שם בסי' שפ\"ח ובשאר דינים המבוארים בטור סי' זה ואפ\"ה סברי בדין זה דנותן לו דמי אומדן של כל מכה בפני עצמה ומטעם כיון דאין נ\"מ כ\"א דבר מועט בריפוי ובשת ובנזק ושבת אין נ\"מ כלל לכן פסק דגובין נזק של כל אבר בפני עצמו כיון שכבר אמדוהו לכך:","\u0003ואם תפס הניזק נזק כל אבר ואבר ודמי כולו אין מוציאין כו' \u0004 כן הוא גם לשון הרמב\"ם בפ\"ב דחובל וכ' עליו המ\"מ שם ז\"ל אם דעת הרב במ\"ש דמי כל אבר ואבר כל נזק אין דמי כולו האמור ראשון (ר\"ל שכ' ברישא נותן לו דמי כולו) כדמי כולו השני שאלו הראשון דמי כולו כמו שהיה בריא טרם שחבל בו כלל והאחרון דמי כולו אחר שנגרעו דמיו מחסרון עינו וידו ורגלו דודאי אם תפס דמי האברים ודמי כולו כמו שהיה בריא מפקינן מיניה עכ\"ל ועד\"ר מ\"ש ביאור דבריו הללו והנלוה לו:","\u0003אלא שביישו נותנין כו'. \u0004 עפ\"ר שם הוכחתי דלבשת של חבלה אין נותנין זמן כיון שלשאר דברים שגובין בחבלה אין נותנין זמן כיון דיש בהן חסרון ממון אגבן גובין ג\"כ צער ובשת אע\"ג דלית בהו חסרון ממון ודוקא בדבר שאין גובין עליה אלא דמי בשת לחוד הוא דנותנין זמן ונראה דה\"ה צער כשהוא לחוד כגון בשפוד במקום שאין רואין כיון דלית ביה חסרון ממון נותנין לו זמן והא דכ' הטור והמחבר והרמב\"ם דין זה בבשת לחוד ולא בצער משום דבמשנה וגמרא מעשה כך היה לפני רבי עקיבא באשה שפרע ראשה ונתביישה ועיין שם ובפרישה:","\u0003כשם שאומדים למיתה כו' \u0004 דבמיתה כתי' בפרשת מסעי בהדיא אם באבן או באגרוף אשר ימות בו הכהו ופירשהו רז\"ל שיעור שימות בו:","\u0003בצרור קטן כו'. \u0004 בטור כ' עוד דאומדין ג\"כ המקום אשר הכהו עליו מ\"ש:","\u0003ה\"ז פטור \u0004 דאמרי' מזלו גרם:","\u0003אבל חייב בבשת. \u0004 עפ\"ר שם הוכחתי דאפילו אם האבן קטן עשה חבלה גדולה ונתבייש בה אף דאינו חייב בשאר הדברים מכל מקום אבשת שנתבייש בה חייב וראיה לזה שהרי אפילו רקק בחבירו שהוא ענין קל חייבוהו עליו בשת ה\"ה בבושת הבא לו מאבן קטן:","\u0003ישבע הנחבל ויטול. \u0004 כיון דאין דרך לעשות מכה כזה אא\"כ היהבה כדי להזיק אוקמינן אחזקתו וק\"ו הוא ממה שאמרו נחבל נשבע ונוטל אף אם אומר הנתבע לא אני חבלתי אלא חבל בעצמו כיון דאין דרך אדם לחבול בעצמו וכמ\"ש הטור והמחבר לעיל ס\"ס צ':","\u0003הברזל אין לו אומד דבברזל לא כתיב אשר ימות בו:\u0004","\u0003שאינו מחודד. \u0004 נראה דאפילו אם הוא מחודד אלא שלא המית בחידודו אלא במשקלו פטור דזיל בתר טעמו:","\u0003אחרים שחבלו בו חייבים. \u0004 פי' ול\"ת כיון דזה עובר על דעת המקום במה שחבל בעצמו אף שאינו רשאי וגם אנו רואים שאינו מקפיד בצערו וחבלתו שהרי חובל בעצמו גם אחרים שחבלו בו יהיו פטורים קמ\"ל ועפ\"ר וע\"ל סי' שפ\"ב שכתב הטור דומה לזה בקוצץ נטיעתו של חבירו:","\u0003אחזו ותקע לו באזנו חייב בתשלומין \u0004 בכאן לא כתב כמה חייב כי סמך אמה שכתוב לפני זה בסכ\"ח [בסכ\"ה] וחזר וכתבו כאן כדי לכללו בין שאר דינים שחילק בכולן בין אחז בו ועשה מעשה בגופו דחייב ובין לא אחז בו דפטור בדיני אדם:","\u0003המבייש את הערום \u0004 כן הוא ל' הרמב\"ם ובפרישה הוכחתי דמדכתב המבייש את הערום מוכח דס\"ל כרש\"י דאפי' ביישו בכל מיני ביוש שרקק בו או הכהו אפ\"ה פטור מהבשת כיון דלאו בר בשת הוא במרחץ כיון שהולך ערום וכ\"ש כשהולך ערום בלא מרחץ מה שא\"כ כשאינו הולך ערום כל כך דאז בר בושת מיקרי וחייב עליו אפי' כשבא אחר והגביה בגדיו קצת יותר וכ\"ש אם ביישו בענין אחר אבל ר\"י כתב דגם כשהוא ערום או בבית המרחץ דאינו פטור כשמביישו בשאר ענינים אלא דכשהוא רוחץ במרחץ דאז הוא כבר ערום לגמרי לא שייך בו בשת דהפשטת בגדים אבל כשהוא הולך לרחוץ בנהר והגביה בגדיו ובא אחר והגביהן יותר או שנשבה בו רוח והגביהן ובא אחר והגביהן יותר בזה קאמר הברייתא דביישו ערום בבית המרחץ או כשהוא ערום דחייב ומהתימא על מור\"ם שלא הביא דעת ר\"י זו שסתר פירש\"י שהוא כדברי הרמב\"ם שכ' המחבר:","\u0003ואם תפסו יורשיו כו' \u0004 איבעיא הוא בגמרא אם טעם דחייבתו התורה בשת הוא משום כיסופא דידיה והכא לא שייך כיון שמת ופטור או משום בשת דבני משפחתו חייבו התורה והרי הן בחיים וחייב ולא איפשטא וס\"ל להרמב\"ם דמהני תפיסה בספיקא דדינא:","\u0003וי\"א שהוא פטור. \u0004 עפ\"ר שכתבתי דאפילו הסוברים דמהני תפיסה לספיקא דדינא יש מהן דס\"ל כאן פטור משום דס\"ל דהא איבעיא נפשט' בגמ' דמשום כיסופ' דידיה הוא ע\"ש מ\"ש עוד בזה:","\u0003ישן שבייש פטור. \u0004 דמוהחזיקה במבושיו ילפינן דבבשת בעינן דוקא שיבייש בכונה:","\u0003השוטה פטור \u0004 דלאו בר בשת הוא משא\"כ בחרש ובגר ועבד דחייבים משום דבני מצות נינהו:","\u0003את הקטן שכשמכלימין אותו נכלם לשון הטור הוא זה וכאילו אמר אם כשמכלימין אותו הוא נכלם חייב ואם לאו הוא פטור וכ\"כ בהדיא בטור ע\"ש בסכ\"ט:\u0004","\u0003רקק בחבירו חייב \u0004 משום בשת ובבגדיו ובביישו בדברים פטור דבעינן דיעשה מעש' בגופו דומיא דוהחזיקה במבושיו:","\u0003שמנדין אותו שיש בוטה כמדקרות חרב ואין לך בשת גדולה יותר מהוצאת שם רע ודבה אשר\"י וע\"ל ס\"ס א' וגם המחבר סתם וכתב שם כן בס\"ו וכאן כתבו בשם י\"א וכבר כתבתי כמה פעמים דאין הוכחה מלשון י\"א דפלוגתא הוא אלא דבמקום שמצא שיחיד כ\"כ ואינו מפורסם בשאר פוסקים רגיל לכתבו המחבר ומור\"ם בלשון י\"א:\u0004","\u0003דמכין אותו מכת מרדות \u0004 דעבר על לאו דלא תונו אבל כיון דהוא לאו שאין בו מעשה אין לוקין עליו מלקות דאורייתא:","\u0003איני מומר כו'. \u0004 וכתב בהגמ\"ר (דף נ\"ג) אם קראו מומר אחר שעשה תשובה הרי עובר חרם ר\"ג ואי לא ידע מן החרם אינו מקרי עבריין עכ\"ל ודין איש שחרף אשה כ' בהגמ\"ר דקידושין דיתענה בה\"ב וישב יחף לפני ב\"ה ויבקש מחילה על המגדל וע\"ל סי' תכ\"א סי\"ג מדין אשה שביזה לאחר:","\u0003י\"א דיכול לתרץ כו' וכ' מהרי\"ו שם עוד וכן אם קראו מבייש הנשים יכול לתרץ דיבוריה דר\"ל דמביישן בדברים וכן אם קראו בן הזונה יכול לתרץ דיבוריה ור\"ל בן פונדקת עכ\"ל ד\"מ שם. הג\"ה וכ' עוד בשם נימוקי מהר\"ם דכ' באם עד ח' מעיד שקראו ממזר ועד א' מעיד שקראו בן הזונה דמצטרפין לענין בן הזונה דבכלל מאתים מנה מ\"מ אין לו דין ממזר דלמא קראו בן הזונה כשהיתה פנויה עכ\"ה.\u0004","\u0003ויש חולקין. \u0004 ר\"ל דלא יוכל לתרץ דיבוריה ושם כ' כן על א' שקראו כנען אבל כ' שם מהר\"ם על אשה אחת שיצא עליה קול שזינתה בטבריה וצוח לה אחד טברי' טבריה לא מיקרי ביוש בפרהסי' כו'. ע\"ש ד\"מ:","\u0003ישלח שם שלוחו \u0004 ומסיק שם דשלוחו יקח ב' מהעיר שנקבר שם וילך על קברו ויבקש מחילה בשם המחרף:","\u0003אבל לא על ביושים אחרים \u0004 ר\"ל דשם נותנין חרם אחר עדות אבל גם בביוש של שוכני עפר א\"צ לישבע ע\"ז כן הוא שם ע\"ש דמ\"ש.","\u0003מלשין בן מלשין פטור. \u0004 דאמרינן בפרק ד' מיתות כמאן קרינן לרשיע בר צדיקא רשיעא בר רשיעא שנא' ובת כהן כי תחל לזנות את אביה היא מחללת ע\"ש:","\u0003הקורא לחבירו עבד כו' \u0004 וכ' מוהר\"ם מריזבורק וז\"ל האומר לחבירו ממזר או עבד או רשע או נואף או פסול או נבל לוקה (ועמ\"ש בהג\"ה בסמ\"ע בשם הרא\"ש ואם קראו עובר על חרם מלשין או גנב הוי כקוראו רשע ויורד עמו לחייו ופי' ר\"י דמותר להכותו דעובר על לאו דלא תונו אבל אם קראו טמא או כלב או שאר חירופין און בהן דין אלא צריך לפייס חבירו עכ\"ל ד\"מ שם וע\"ל ר\"ס תכ\"א באחד הקובל על חבירו שהלשינו או גנב לו. (הג\"ה וכ' בד\"מ סל\"ד ומהרי\"ו סי' כ\"ח פסק בא' שחבל בחבירו להלקותו בב\"ה בין מנחה למעריב דהמגביה ידו על חבירו נקרא רשע וחייב מלקות וגם הוצרך לעשות מחילה וגם פסק ליתן לו זקוק כסף אם הוא עני ואם הוא עשיר יתנו לעומלי תורה כן פסק גדול א' על א' שתלש שערו של חבירו ופסק ליתן לו זקוק כסף אמנם אם יש מנהג בזו הכל לפי המנהג ונ\"ל דכל זה אינו אלא הוראת שעה לפי ראות עיני הב\"ד שחטא המחבל אבל מדינא אינו חייב מלקות וממון כמו שנתבאר כו' עכ\"ל ד\"מ עכ\"ה):","\u0003הוא דמי כו'. \u0004 ר\"ל הריפוי והשבת הוא בכללו שאף אם יש מחמת אותו הכא' הוצא' ממון דריפוי או שבת א\"צ לשלם לו יות' ובע\"ש כ' שינוי לשון ז\"ל ואמרו שיתן הצער והבושת והריפוי והשבת כו' דמשמע דתחלת תיקונו היה כ\"כ בשביל הריפוי והשבת כו' וללא צורך כ\"כ וגם אמירה זו לא מצינו שאמרו כן:","\u0003בין צריך לרפואה בס\"ס זה כ' מור\"ם דעת החולקים ע\"ז ואומרים דדמים הללו אינן בשביל רפוי ושבת כי לא קצבו דמים קצובים כ\"א הצער ובושת שהן בכל מכות שמכה אדם לחבירו ואם יש ריפוי ושבת משלם עוד נוסף על קצבה זו ולפי הענין ובהן לא יוכלו חז\"ל ליתן בהן קצבה:\u0004","\u0003משלם ק' סלעים כו'. \u0004 ובטור סל\"ד מסיים כאן ז\"ל או שפרע ראש האשה משלם ק' סלעים כו' וכתב בד\"מ סל\"ד בשם נימוקי מוהר\"ם וז\"ל המלעיג על דברי חכמים לוקה והקורא לאשת חבירו זונה או פרוצה לוקה ד' מלקיות דתנן פרע ראש האשה נותן ארבע מאות זוז ומדלא מגבינן קנסא בבבל לוקה ד' מלקיות וע\"ל סי' ב' מ\"ש בשם מהרי\"ו (ור\"ל דשם כתב דכל מלקיות הוא ארבעים זוז) עכ\"ל ד\"מ ח':","\u0003אלא שמינית כו' \u0004 ז\"ל הטור והרמב\"ם סלע מדינה יש בו חצי דינר כסף (שהוא שמינית שבסלע צורי שיש בו ד' דינרי כסף) וג' דינרים ומחצה נחושת לפיכך מי שנתחייב ק' סלעי' משלם י\"ב סלעי' ומחצה כסף נקי עכ\"ל ובפרישה כתבתי דאינו ר\"ל דיצא בשילום י\"ב סלעי' והחצי כסף נקי לחוד שהרי כיון דחייבוהו לשלם בסלעים שבכל סלע יש בו ז' חלקים נחשת והחלק השמיני של כסף נהי דנסתלק ממנו בזה ידי שלום הכסף שבו עדיין לא נסתלק ממנו תשלומין הנחשת שבו וצ\"ל דמ\"ש דמשלם י\"ב סלעי' ומחצה כו' צ\"ל כשיבא לשלם לו בסלעי' דמדינה ירא' שלא יהא בהן פחות מי\"ב סלעים ומחצה כסף והמותר יהיה נחשת ומשום דהמקומות והזמנים משתנים שפוחתין בסלע מדינה הכסף ומוסיפין במקומו נחשת מ\"ה כתב שיעור הכסף שלא יפחות מזה ומה\"נ נראה דסתם המחבר ולא כתב שיתן י\"ב סלעים ומחצה כסף כי לא בא אלא ללמדינו כמה כסף יהיה בו והרמב\"ם שכתבו בספ\"ג דחובל מ\"מ רמזו במה שהתחיל שם וכתב ז\"ל כל אלו הסלעים הן מכסף א\"י באותו זמן שהיה בכל סלע כו' חצי דינר כסף כו' הרי לשונו משמע שבא ללמדינו כמה היה הסלע באותו זמן דחכמי המשנ' שקבעו שיעורים הללו ומאותו שיעור נלמד לכל זמן וזמן ומקום ומקום לפי מה שהוא המטבע שם שלא יפחות הכסף ממנו וכנ\"ל ועמ\"ש בפריש' עוד מזה:"],["\u0003 עבד כנעני של חברו כו'. \u0004 עיין בסמ\"ע ס\"ק ו' עד ומ\"ה גם בהכא' כו' והב\"ח השיג ע\"ז ואין דבריו מוכרחים:","\u0003 חייב בחמש' דברים \u0004 וה' דברים אלו משתלמין מן היפה שבנכסיו כדין כל המזיקין עכ\"ל רמב\"ם ריש הל' חובל וכן כ' הסמ\"ג דף קמ\"ה ע\"ג וכ' הרב המגיד שם שהדין מבואר ריש ב\"ק דאמר כלם כאבות הן לשלם ממיטב ע\"כ וכן פסקו הרי\"ף והרא\"ש והנ\"י ריש ב\"ק וכ\"פ רש\"ל שם סי' ו' וכן הוא הדין לעיל סי' שפ\"ה ושפ\"ח ס\"ב:","\u0003 ואם הי' בעל אומנות כו'. \u0004 ומהרש\"ל פסק דלענין נזק אין חילוק בשום בני אדם בעולה אלא שמין אותו כעבד שא\"י שום מלאכה וע\"ש סי' י\"א ומכל מקום אין טעם לדבריו דהא מכל מקום היזקו הוא רב יותר מעבד שאינו יודע שום מלאכה ודו\"ק נ\"ל:","\u0003 אין נותנין לחובל שום זמן כו' \u0004 משמע אפילו זיל נכסי דנתבע ודוקא כשנתחייב בדין אבל אם מבקש זמן להביא עדים לפטור נותנים זמן אף לחבלות אם זיל נכסיה כדמוכח בתוספות והרא\"ש פרק הפרה וכ\"כ נ\"י שם ודלא כב\"ח סי' כ\"ד וכבר השגתי עליו שם ע\"ש:","\u0003 רקק בחבירו \u0004 עיין בתשו' ר\"י לבית לוי סי' כ\"ט מדינים אלו:","\u0003 המדבר רע על שוכני עפר כו' \u0004 עיין בתשו' ר\"א ן' חיים סי' נ' וסי' צ\"ג וסי' קי\"א:","\u0003 אבל לא על ביושים אחרים כו' \u0004 ע\"ל סי' פ\"ז (בסמ\"ע) ס\"ק ע\"ה וע\"ו כ' הסמ\"ע ר\"ל דשם נותנין חרם אחר עדות אבל גם בביוש של שוכני עפר א\"צ לישבע ע\"ז כן הוא שם עכ\"ל ובאגוד' פ' הזהב ז\"ל אם אדם טוען ביישתני בדברים או בשוכני עפר והלה כופר נרא' דא\"נ לישבע דלא נתקנ' שבועת היסת ע\"ז מיהו בס' מיימוני ובס' המצות לא משמע הכי עכ\"ל ולא ידעתי למה לא משמע הכי בס' מיימוני ובס' המצות ואי משום שכ' בריש הלכות טוען ונטען שהטוען לחבירו אתה ביישתני וזה אומר להד\"ם אם הוא במקום שגובין קנס נשבע היסת כו' וה\"נ אלו הוה אמת היו קונסין אותו י\"ל דשאני התם דאלו היה האמת קונסין אותו ממון הקצוב בתורה משא\"כ הכא תדע שהרי גם הטור ס\"ס פ\"ז כתב כהרמב\"ם וסמ\"ג ואפ\"ה כתב שם לעיל מיניה דאם טוען אתה קללת אותי או הוצאת עלי ש\"ר אין משביעים אותו רק מחרימים ע\"ז שהרי אם יתברר שהוא אמת קונסין אותו כו' (הג\"ה עיין במהרש\"ל פ' החובל באריכות מדינים אלו ועיין בתשובת ר\"י מטראני מי\"ד סי' ט\"ז שכ' שכל מה שמדבר לחבירו בלשון צחות כגון שקורא לרבים בני יונים או אמר על אחד שבא לדור ממקום אחר ונעשה דיין הגר אשר בקרבך יעלה עליך וגו' אע\"ג דקרא קאי אעכו\"ם לא מיקרי בושת וההיא איתתא דאמרה ורב כריסא וכו' אשה זו. פושעת היתה דה\"ל ליתן בו סי' אחר וע\"ש ראיה שלו:","\u0003 הקור' לחבירו עבד \u0004 עיין בתשו' ר\"מ אלשיך סי' ע\"ג ובתשובת מבי\"ט ח\"ח בשאלות השניות סי' ע\"ז דף ק\"ח אם קראו בן השפח' ונידהו ועיין עוד שם סי' קכ\"ה דף קע\"ד:","\u0003 דין המבייש ת\"ח כו'. \u0004 וראשים וממונים הקהל כת\"ח כ\"כ בתשובת מהר\"י לבית לוי סי' כ\"ט ועיין שם באריכות:"],"\u0003הלכות חובל בחבירו\u0004\n\u0010g0\u0011 \u0010r0\u0011 אָסוּר לְאָדָם \u0010r1\u0011 לְהַכּוֹת חֲבֵרוֹ; וְאִם הִכָּהוּ עוֹבֵר בְּלָאו, \u0010y0\u0011 \u0010g1\u0011 שֶׁנֶּאֱמַר: פֶּן \u0010r2\u0011 יֹסִיף \u0005(דְּבָרִים כה, ג)\u0006. וְאִם הִקְפִּידָה תּוֹרָה \u0010y1\u0011 בְּהַכָּאַת רָשָׁע שֶׁלֹּא לְהַכּוֹתוֹ יוֹתֵר עַל רִשְׁעוֹ, קַל וָחֹמֶר בְּהַכָּאַת צַדִּיק. \u0010g2\u0011 וְהַמֵּרִים יַד עַל חֲבֵרוֹ לְהַכּוֹתוֹ, \u0010y2\u0011 אַף עַל פִּי שֶׁלֹּא הִכָּהוּ, נִקְרָא רָשָׁע. \u0005הַגָּה: וְעַיֵּן לְקַמָּן סִימָן תכ\"א סָעִיף י\"ג. וְדִין הַכָּאַת אִישׁ לְאִשְׁתּוֹ, עַיֵּן בְּאֶבֶן הָעֵזֶר סִימָן קנ\"ד. \u0010y3\u0011 דְּיֵשׁ אוֹמְרִים דְּיֵשׁ חֵרֶם קַדְמוֹנִים בְּאָדָם הַמַּכֶּה \u0010g3\u0011 \u0010r3\u0011 לַחֲבֵרוֹ, וּצְרִיכִין לְהַתִּיר לוֹ כְּדֵי לְצָרְפוֹ לְמִנְיָן עֲשָׂרָה, וּמִיָּד שֶׁמְּקַבֵּל עָלָיו \u0010g4\u0011 לַעֲשׂוֹת דִּין, מַתִּירִין לוֹ אַף עַל פִּי שֶׁאֵין \u0010g5\u0011 (הַמֻּכֶּה)\u0006 מִתְרַצֶּה \u0005(מַהֲרַ\"ם מֵרִיזְבּוּרְק והג\"מ פֶּרֶק הַחוֹבֵל)\u0006. \u0010g6\u0011\nהִכָּהוּ מַכָּה שֶׁאֵין בָּהּ שְׁוֵה פְרוּטָה, לוֹקֶה, \u0010y4\u0011 \u0010g7\u0011 כֵּיוָן שֶׁאֵין בָּהּ חִיּוּב מָמוֹן. \u0010g8\u0011 \u0010r4\u0011 וַאֲפִלּוּ הִכָּה \u0010y5\u0011 \u0010c0\u0011 עֶבֶד כְּנַעֲנִי, לוֹקֶה הוּא, \u0010g9\u0011 \u0010r5\u0011 שֶׁהֲרֵי חַיָּב בְּמִצְוֹת. \u0010g10\u0011\nהַחוֹבֵל \u0010y6\u0011 \u0010c1\u0011 \u0010t0\u0011 בַּחֲבֵרוֹ, חַיָּב בַּחֲמִשָּׁה דְבָרִים: נֶזֶק, צַעַר, רִפּוּי, שֶׁבֶת, \u0010r6\u0011 בֹּשֶׁת; אִם הַחַבָּלָה בְּעִנְיָן שֶׁיֵּשׁ בָּהּ כָּל הֶחָמֵשׁ. \u0005הַגָּה: \u0010r7\u0011 יֵשׁ אוֹמְרִים דְּצָרִיךְ לִתֵּן גַּם כֵּן תּוֹסָפוֹת מְזוֹנוֹת הַצְּרִיכִין בְּחָלְיוֹ מִמַּה שֶׁהָיָה אוֹכֵל כְּשֶׁהָיָה בָּרִיא (נִמּוּקֵי יוֹסֵף פֶּרֶק הַחוֹבֵל)\u0006, וְנִרְאֶה לִי, דְבִכְלָל רִפּוּי יֵחָשֵׁב. \u0010g11\u0011 וְאִם אֵין בָּהּ אֶלָּא ד', מְשַׁלֵּם ד'; וְאִם ג', ג'; וְאִם ב', ב'; וְאִם א', א'. \u0010g12\u0011\nכֵּיצַד, קָטַע יָדוֹ אוֹ רַגְלוֹ \u0010r8\u0011 אוֹ אֶצְבַּע אַחַת, אוֹ שֶׁחִסְרוֹ אֶחָד מִכָּל אֵבָרָיו, נוֹתֵן לוֹ כָּל ה' הַדְּבָרִים. \u0010g13\u0011\nהִכָּהוּ \u0010y7\u0011 עַל יָדוֹ וְצָבְתָה וְסוֹפָהּ \u0010g14\u0011 לַחֲזֹר, אוֹ הִכָּהוּ עַל עֵינוֹ וּמָרְדָה וְסוֹפָהּ לַחֲזֹר, אֵין כָּאן נֶזֶק, וְנוֹתֵן לוֹ שְׁאָר אַרְבַּע דְּבָרִים. \u0010g15\u0011\nהִכָּהוּ עַל רֹאשׁוֹ וְצָבְתָה, אֵין כָּאן נֶזֶק וְשֶׁבֶת, וְנוֹתֵן לוֹ שְׁאָר הַשְּׁלֹשָׁה דְבָרִים. \u0010y8\u0011 \u0010g16\u0011 \u0010r9\u0011\nהִכָּהוּ בְּמָקוֹם שֶׁאֵינוֹ \u0010g17\u0011 \u0010r10\u0011 נִרְאָה, וְלֹא רָאָהוּ שׁוּם \u0010t1\u0011 אָדָם, אֵינוֹ נוֹתֵן לוֹ אֶלָּא צַעַר וְרִיפּוּי. \u0010g18\u0011\nהִכָּהוּ \u0010r11\u0011 בְּמִטְפַּחַת שֶׁבְּיָדוֹ \u0010g19\u0011 אוֹ בִּשְׁטָר וְכַיּוֹצֵא בְּזֶה, אֵין כָּאן אֶלָּא \u0010r12\u0011 בֹּשֶׁת. \u0005וְיֵשׁ אוֹמְרִים דַּוְקָא שֶׁהוּא בִּמְקוֹם רוֹאִין \u0010g20\u0011 (הָרַאֲבַ\"ד)\u0006. \u0010g21\u0011\nכְּוָאוֹ בְּשַׁפּוּד עַל צִפָּרְנוֹ, בְּמָקוֹם שֶׁאֵינוֹ עוֹשֶׂה חַבּוּרָה וְאֵינוֹ מְעַכְּבוֹ מִמְּלָאכָה, אֵינוֹ נוֹתֵן אֶלָּא צַעַר. \u0010r13\u0011 \u0005וְאִם הָיָה בִּמְקוֹם רוֹאִין, חַיָּב בְּבֹשֶׁת (המ\"מ שם)\u0006. \u0010g22\u0011 \u0010r14\u0011\nהִשְׁקָהוּ סַם, אוֹ שֶׁסָכוֹ סַם, וְשִׁנָּהוּ מִמַּרְאֵה עוֹרוֹ, אֵינוֹ מְשַׁלֵּם לוֹ \u0010y9\u0011 אֶלָּא רִפּוּי בִּלְבַד. \u0010g23\u0011\nהִכְנִיסוֹ בְּחֶדֶר וְסָגַר הַדֶּלֶת עָלָיו וּבִטְּלוֹ מִמְּלַאכְתּוֹ, אֵינוֹ נוֹתֵן לוֹ אֶלָּא שֶׁבֶת בִּלְבַד. \u0010g24\u0011 \u0010r15\u0011 אֲבָל אִם הָיָה כְּבָר בְּחֶדֶר וְסָגַר עָלָיו מִלָּצֵאת, \u0010y10\u0011 הָוֵי \u0010t2\u0011 גְרָמָא בְּנִזָּקִין וּפָטוּר מִדִּינֵי אָדָם. \u0010g25\u0011\nגִּלַּח שְׂעַר רֹאשׁוֹ, אֵינוֹ נוֹתֵן לוֹ \u0010y11\u0011 אֶלָּא \u0010g26\u0011 בֹּשֶׁת. סָכוֹ בְּסַם עַד שֶׁאֵין סוֹף הַשֵּׂעָר לַחֲזֹר, חַיָּב בְּה' דְּבָרִים, \u0010y12\u0011 שֶׁהֲרֵי מִצְטַעֵר מִן הַסַם, וְשֶׁבֶת שֶׁהֲרֵי הוּא רָאוּי לְרַקֵּד \u0010y13\u0011 וּלְנַדְנֵד \u0010g27\u0011 \u0010t3\u0011 \u0010r16\u0011 \u0005(שְׂעַר)\u0006 רֹאשׁוֹ בִּשְׁעַת רִקּוּד, וְנִמְצָא בָּטֵל מִמְּלָאכָה זוֹ. \u0010g28\u0011 \u0010r17\u0011\nהַמְחַסֵר אֶת חֲבֵרוֹ אֵבֶר שֶׁאֵינוֹ חוֹזֵר, חַיָּב בְּכָל הַה' דְּבָרִים. אֲפִלּוּ הִפִּיל שִׁנּוֹ, חַיָּב בַּכֹּל, שֶׁאִי אֶפְשָׁר שֶׁלֹּא יֶחֱלֶה פִיו שָׁעָה אַחַת; אַף עַל פִּי שֶׁהַשֵּׁן אֵין לוֹ רְפוּאָה, בְּשַׂר הַשִּׁנַּיִם צָרִיךְ רְפוּאָה. \u0010g29\u0011 \u0010r18\u0011\nאֲפִלּוּ חִסְרוֹ כִּשְׂעוֹרָה מֵעוֹר בְּשָׂרוֹ, חַיָּב בְּה' דְּבָרִים, שֶׁהָעוֹר אֵינוֹ חוֹזֵר \u0010y14\u0011 אֶלָּא צַלֶּקֶת \u0005(פֵּרוּשׁ, רֹשֶׁם מַכָּה שֶׁנִּתְרַפְּאָה)\u0006. לְפִיכָךְ, הַחוֹבֵל בַּחֲבֵרוֹ וְקָרַע הָעוֹר וְיָצָא מִמֶּנּוּ דָם, חַיָּב בְּה' דְּבָרִים. \u0010g30\u0011\nכֵּיצַד מְשַׁעֲרִים הַה' דְּבָרִים, נֵזֶק \u0010g31\u0011 אִם חִסְרוֹ אֵבֶר \u0010g32\u0011 אוֹ חָבַל חַבּוּרָה שֶׁאֵין סוֹפָהּ לַחֲזֹר שָׁמִין אוֹתוֹ \u0010y15\u0011 \u0010g33\u0011 \u0010r19\u0011 כְּאִלּוּ הוּא \u0010t4\u0011 עֶבֶד נִמְכָּר בַּשּׁוּק, כַּמָּה הָיָה שָׁוֶה קֹדֶם שֶׁחָבַל בּוֹ וְכַמָּה נִפְחֲתוּ דָמָיו אַחַר הַחַבָּלָה, וְכָךְ יִתֵּן לוֹ. \u0005הַגָּה: \u0010c2\u0011 \u0010r20\u0011 וְאִם הָיָה בַּעַל \u0010t5\u0011 אֻמָּנוּת, כְּגוֹן נוֹקֵב מַרְגָלִיּוֹת, וְקָטַע לוֹ יָדוֹ, מְשַׁעֲרִינָן הֶזֵּיקוֹ כְּפִי מַה שֶּׁהוּא. \u0010r21\u0011 אֲבָל אִם קָטַע רַגְלוֹ, \u0010y16\u0011 שֶׁאֵין מַזִּיק לוֹ כָּל כָּךְ, מְשַׁעֲרִינָן \u0010g34\u0011 הֶזֵּקוֹ כְּאִלּוּ לֹא הָיָה בַּעַל אֻמָּנוּת (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. \u0010g35\u0011 \u0010r22\u0011\nצַעַר כֵּיצַד, הֲרֵי שֶׁקָּטַע אֶצְבָּעוֹ, אוֹמְדִים כַּמָּה אָדָם רוֹצֶה לִתֵּן בֵּין לִקְטֹע לוֹ אֵבֶר זֶה בְּסַיִף אוֹ לִקְטֹעַ אוֹתוֹ בְּסַם, \u0010y17\u0011 אִם גָּזַר \u0010t6\u0011 הַמֶּלֶךְ לִקְטֹעַ אֵבֶר \u0010g36\u0011 \u0005בְּסַיִף,\u0006 וּמַה שֶּׁיֵּשׁ בֵּין זֶה לְזֶה מְשַׁלֵּם לוֹ. \u0005הַגָּה: \u0010r23\u0011 וּבְמָקוֹם דְּאִכָּא צַעַר לְחוּד, מְשַׁעֲרִין \u0010y18\u0011 אִם הָיָה גּוֹזֵר הַמֶּלֶךְ לִכְווֹת אוֹתוֹ בְּשַׁפּוּד עַל צִפָּרְנוֹ וְכַדּוֹמֶה, כַּמָּה הָיָה נוֹתֵן לְהִנָּצֵל מִצַּעַר זֶה (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. \u0010g37\u0011\nכֵּיצַד מְשַׁעֲרִין הַשֶּׁבֶת, אִם לֹא חִסְרוֹ אֵבֶר אֶלָּא חָלָה וְנָפַל לְמִשְׁכָּב, אוֹ צָבְתָה יָדוֹ וְסוֹפָהּ לַחֲזֹר, נוֹתֵן לוֹ שִׁבְתּוֹ שֶׁל כָּל יוֹם וָיוֹם \u0010y19\u0011 \u0010t7\u0011 \u0010r24\u0011 כְּפוֹעֵל בָּטֵל שֶׁל אוֹתָהּ מְלָאכָה שֶׁבָּטַל מִמֶּנָּה. וְאִם חִסְרוֹ אֵבֶר, כְּגוֹן שֶׁקָּטַע יָדוֹ, נוֹתֵן לוֹ דְּמֵי יָדוֹ שֶׁהוּא הַנֶּזֶק, וְשֶׁבֶת רוֹאִין אוֹתוֹ כְּאִלּוּ הוּא שׁוֹמֵר קִשּׁוּאִין, וְרוֹאִין כַּמָּה הוּא שְׂכַר שׁוֹמֵר קִשּׁוּאִים בְּכָל יוֹם, \u0010r25\u0011 וְעוֹשִׂין חֶשְׁבּוֹן כָּל יְמֵי חָלְיוֹ שֶׁל זֶה וְנוֹתֵן לוֹ. וְכֵן אִם קָטַע רַגְלוֹ, רוֹאִין אוֹתוֹ כְּאִלּוּ הוּא שׁוֹמֵר עַל הַפֶּתַח. סִמָּא אֶת עֵינוֹ, רוֹאִין אוֹתוֹ כְּאִלּוּ הוּא טוֹחֵן בְּרֵחַיִם; וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0005הַגָּה: \u0010r26\u0011 וְדַוְקָא בִּסְתָם בְּנֵי אָדָם שֶׁאֵינָן בְּנֵי אֻמָּנוּת, אֲבָל אִם הוּא בֶּן אֻמָּנוּת וְיָכוֹל לַעֲסֹק בִּמְלַאכְתּוֹ אַחַר חָלְיוֹ, מְשַׁעֲרִין הַשֶּׁבֶת כְּפִי הַמְּלָאכָה דְבָטֵל מִנֵּהּ (טוּר סי\"ט בְּשֵׁם הָרֹא\"שׁ)\u0006. \u0010g38\u0011\nכֵּיצַד מְשַׁעֲרִין הָרִיפּוּי, אוֹמְדִים בְּכַמָּה יָמִים יִחְיֶה מֵחֹלִי זֶה, וְכַמָּה הוּא צָרִיךְ, וְנוֹתֵן לוֹ מִיָּד; וְאֵין מְחַיְּבִים אוֹתוֹ לָתֵת דְּבַר יוֹם בְּיוֹמוֹ, \u0010y20\u0011 \u0010r27\u0011 וְדָבָר זֶה \u0010t8\u0011 תַּקָּנָה הִיא לַמַּזִּיק. וְכֵן הַשֶּׁבֶת אוֹמְדִין אוֹתוֹ וְנוֹתֵן הַכֹּל מִיָּד; אִם הָיָה מִתְגַּלְגֵּל בְּחָלְיוֹ וְהוֹלֵךְ, וְאָרַךְ הַחֹלִי יוֹתֵר עַל מַה שֶּׁאֲמָדוּהוּ, אֵינוֹ מוֹסִיף לוֹ כְּלוּם; \u0010g39\u0011 וְכֵן אִם הִבְרִיא מִיָּד, אֵין פּוֹחֲתִין מִמַּה שֶׁאֲמָדוּהוּ: \u0010g40\u0011\nאָמַר הַמַּזִּיק: אֵין רְצוֹנִי בְּתַקָּנָה זוֹ אֶלָּא אֶרְפָּאֶנּוּ דְּבַר יוֹם בְּיוֹמוֹ, שׁוֹמְעִין לוֹ. \u0010y21\u0011 \u0010g41\u0011 הֲרֵי שֶׁלֹּא פָּסַק עִמּוֹ אֶלָּא הָיָה מְרַפֵּא יוֹם \u0010g42\u0011 \u0010r28\u0011 יוֹם, וְעָלוּ בּוֹ צְמָחִים מֵחֲמַת הַמַּכָּה, אוֹ נִסְתְּרָה הַמַּכָּה אַחֲרֵי שֶׁחָיְתָה, חַיָּב לְרַפּאוֹתוֹ \u0010g43\u0011 וְלָתֵת לוֹ דְּמֵי שִׁבְתּוֹ; עָלוּ בּוֹ צְמָחִים \u0010y22\u0011 שֶׁלֹּא מַחֲמַת הַמַּכָּה, \u0010g44\u0011 אֵינוֹ חַיָּב לְרַפּאוֹתוֹ וְלֹא לָתֵת לוֹ דְּמֵי שִׁבְתּוֹ. \u0010g45\u0011\nעָבַר עַל דִּבְרֵי הָרוֹפֵא וְהִכְבִּיד עָלָיו הַחֹלִי, אֵינוֹ חַיָּב לְרַפּאוֹתוֹ. \u0010g46\u0011\nאָמַר לוֹ הַמַּזִּיק: אֲנִי אֲרַפֵּא אוֹתְךָ, אוֹ: יֵשׁ לִי רוֹפֵא שֶׁמְּרַפֵּא בְּחִנָּם, \u0010y23\u0011 אֵין שׁוֹמְעִין לוֹ, אֶלָּא מֵבִיא רוֹפֵא אֻמָּן וּמְרַפְּאוֹ \u0010g47\u0011 בְּשָׂכָר: \u0010g48\u0011\nאִם יֹאמַר הַמַּזִּיק: אָבִיא לְךָ רוֹפֵא מִמָּקוֹם רָחוֹק שֶׁיִּקַּח שָׂכָר מוּעָט, יָכוֹל הַנֶחְבָּל לוֹמַר לוֹ: הָרוֹפֵא שֶׁהוּא בִּמְקוֹמוֹ מְדַקְדֵּק יוֹתֵר, שֶׁלֹּא יַפְסִיד הַמְחָאָתוֹ. \u0010g49\u0011\nאָמַר הַנֶחְבָּל: תֵּן לִי שְׂכַר הָרוֹפֵא וַאֲנִי אֲרַפֵּא אֶת עַצְמִי, יָכוֹל הַחוֹבֵל לוֹמַר לוֹ: שֶׁמָּא לֹא תְּרַפֵּא עַצְמְךָ יָפֶה וְיִקְרְאוּ אוֹתִי מַזִּיק לְעוֹלָם. \u0010g50\u0011\nכֵּיצַד מְשַׁעֲרִין הַבֹּשֶׁת, הַכֹּל לְפִי \u0010r29\u0011 הַמְבַיֵּשׁ וְהַמִּתְבַּיֵּשׁ; אֵינוֹ דוֹמֶה מִתְבַּיֵּשׁ מֵהַקָּטָן לַמִּתְבַּיֵּשׁ מֵאָדָם גָּדוֹל \u0010y24\u0011 וּמְכֻבָּד, שֶׁזֶּה \u0010t9\u0011 שֶׁבִּיְּשׁוֹ הַקַּל בָּשְׁתּוֹ מְרֻבָּה. \u0005הַגָּה: \u0010r30\u0011 וְכֵן הַמִּתְבַּיֵּשׁ, כְּפִי מַה שֶּׁכְּבוֹדוֹ גָדוֹל בָּשְׁתּוֹ מְרֻבָּה (טוּר)\u0006. \u0010r31\u0011 וְהַמְבַזֶּה כֹּהֵן, בָּשְׁתּוֹ יוֹתֵר גְּדוֹלָה מִבְּאִישׁ אַחֵר \u0005(רִיבָ\"שׁ סִימָן נ\"ד)\u0006. \u0010g51\u0011\nצָעַק בְּאָזְנוֹ וְחֵרְשׁוֹ, \u0010y25\u0011 פָּטוּר מִדִּינֵי \u0010t10\u0011 אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם. אָחֲזוֹ \u0010y26\u0011 \u0010g52\u0011 וְתָקַע בְּאָזְנוֹ וְחֵרְשׁוֹ, \u0010r32\u0011 אוֹ \u0010g53\u0011 שֶׁהִכָּהוּ בְּאָזְנוֹ וְחֵרְשׁוֹ, \u0010g54\u0011 נוֹתֵן לוֹ דְּמֵי \u0010g55\u0011 \u0010r33\u0011 כֻּלּוֹ אִם אֵינוֹ בַּעַל אֻמָּנוּת. וְאִם הוּא בַּעַל אֻמָּנוּת וְרָאוּי עֲדַיִן לְאוֹתוֹ אֻמָּנוּת, רוֹאִים כַּמָּה נִפְחֲתוּ דָמָיו וְנוֹתֵן לוֹ. \u0010g56\u0011\nסִמָּא עֵינוֹ וְלֹא אֲמָדוּהוּ, \u0010g57\u0011 \u0005(קָטַע יָדוֹ וְלֹא אֲמָדוּהוּ)\u0006, וְקָטַע רַגְלוֹ וְלֹא אֲמָדוּהוּ, וְאַחַר כָּךְ חֵרְשׁוֹ, הוֹאִיל וְלֹא אֲמָדוּהוּ מִכָּל נֶזֶק וָנֶזֶק, \u0010y27\u0011 נוֹתֵן לוֹ דְּמֵי כֻּלּוֹ. \u0005הַגָּה: \u0010r34\u0011 וּמְחֻיָּב לִתֵּן צַעַר וְרִפּוּי וּבֹשֶׁת שֶׁל כָּל מַכָּה וּמַכָּה, רַק שֶׁאוֹמְדִים \u0010g58\u0011 הַכֹּל בְּיַחַד (טוּר סי\"ז בְּשֵׁם \u0010g59\u0011 הָרֹא\"שׁ)\u0006. \u0010y28\u0011 \u0010g60\u0011 אֲמָדוּהוּ לְכָל נֶזֶק וָנֶזֶק, וְאַחַר כָּךְ אֲמָדוּהוּ לְכֻלּוֹ, אֵין גּוֹבִין מִמֶּנּוּ אֶלָּא דְּמֵי כֻּלּוֹ בִּלְבַד. \u0010y29\u0011 וְאִם תָּפַס הַנִּזָּק נֶזֶק כָּל אֵבֶר וְאֵבֶר \u0010g61\u0011 וּדְמֵי כֻלּוֹ, אֵין מוֹצִיאִין מִיָּדוֹ. \u0005הַגָּה: וּכְבָר נִתְבָּאֵר סִימָן שפ\"ח דְּיֵשׁ חוֹלְקִין וּסְבִירָא לְהוּ דְּלָא מְהַנֵּי תְפִיסָה (הָרֹא\"שׁ וְהַטּוּר)\u0006. \u0010g62\u0011\nכְּשֶׁבֵּית דִּין מַגְבִּין לַנֶּחְבָּל אַרְבָּעָה דְבָרִים, \u0010c3\u0011 אֵין נוֹתְנִים לַחוֹבֵל בָּהֶם שׁוּם \u0010t11\u0011 זְמַן. \u0010g63\u0011 אֲבָל אִם לֹא עָשָׂה בּוֹ דָּבָר \u0010y30\u0011 אֶלָּא \u0010t12\u0011 שֶׁבִּיְּשׁוֹ, נוֹתְנִים לוֹ זְמַן כֵּיוָן שֶׁלֹּא חִסְרוֹ מָמוֹן. \u0010y31\u0011 \u0010g64\u0011\nכְּשֵׁם שֶׁאוֹמְדִים לְמִיתָה, כָּךְ אוֹמְדִים לִנְזִיקִין. כֵּיצַד, הֲרֵי שֶׁהִכָּה \u0010y32\u0011 חֲבֵרוֹ בִּצְרוֹר \u0010t13\u0011 קָטָן שֶׁאֵין בּוֹ כְּדֵי לְהַזִּיק, אוֹ בְּקֵיסָם שֶׁל עֵץ קָטָן, וְחָבַל בּוֹ חַבָּלָה שֶׁאֵין חֵפֶץ זֶה רָאוּי לַעֲשׂוֹתוֹ, \u0010y33\u0011 הֲרֵי זֶה \u0010t14\u0011 פָטוּר, שֶׁנֶּאֱמַר: בְּאֶבֶן אוֹ בְאֶגְרֹף \u0005(שְׁמוֹת כא, יח)\u0006, דָּבָר הָרָאוּי לְהַזִּיק; \u0010y34\u0011 \u0010g65\u0011 \u0010r35\u0011 אֲבָל חַיָּב הוּא בְּבֹשֶׁת בִּלְבַד, \u0010g66\u0011 שֶׁאֲפִלּוּ רָקַק בְּגוּפוֹ שֶׁל \u0010r36\u0011 חֲבֵרוֹ חַיָּב בְּבֹשֶׁת; לְפִיכָךְ צְרִיכִים הָעֵדִים לֵידַע בַּמֶּה הִזִּיק, וּמְבִיאִים הַחֵפֶץ שֶׁהִזִּיק בּוֹ לְבֵית דִּין, עַד שֶׁאוֹמְדִין אוֹתוֹ וְדָנִין עָלָיו. וְאִם אָבַד הַחֵפֶץ, וְאָמַר הַחוֹבֵל: לֹא הָיָה בּוֹ כְּדֵי לְהַזִּיק, וְנֶחְבָּל אוֹמֵר: הָיָה בּוֹ כְּדֵי לְהַזִּיק, \u0010y35\u0011 \u0010g67\u0011 יִשָּׁבַע הַנֶּחְבָּל \u0010y36\u0011 \u0010g68\u0011 וְיִטֹּל.\nהַבַּרְזֶל, אֵין לוֹ \u0010g69\u0011 אֹמֶד; אֲפִלּוּ מַחַט קְטַנָּה רְאוּיָה הִיא לְהָמִית, וְאֵין צָרִיךְ לוֹמַר לְהַזִּיק. \u0010g70\u0011 וְדַוְקָא כְּעֵין מַחַט, שֶׁהִיא חַדָּה, אֲבָל אִם לֹא הִזִּיק אֶלָּא מֵחֲמַת מִשְׁקָלוֹ, \u0010y37\u0011 שֶׁאֵינוֹ \u0010t15\u0011 מְחֻדָּד כְּלָל, אוֹמְדִים אוֹתוֹ כִּשְׁאָר דְּבָרִים. \u0010g71\u0011 \u0010r37\u0011\nהַזּוֹרֵק אֶבֶן, וּלְאַחַר שֶׁיָּצְאָה מִתַּחַת יָדוֹ הוֹצִיא הֲלָה רֹאשׁוֹ מֵהַחַלּוֹן וְקִבְּלָהּ, פָּטוּר \u0010r38\u0011 מִכֻּלָּם, שֶׁנֶּאֱמַר: וּמָצָא אֶת רֵעֵהוּ \u0005(דְּבָרִים יט, ה)\u0006, פְּרָט לְמַמְצִיא אֶת עַצְמוֹ. \u0010g72\u0011\nהַחוֹבֵל בְּעַצְמוֹ, אַף עַל פִּי שֶׁאֵינוֹ רַשַּׁאי, \u0010g73\u0011 \u0005(פָּטוּר)\u0006 \u0010y38\u0011 ; אֲחֵרִים שֶׁחָבְלוּ בּוֹ, \u0010g74\u0011 \u0010t16\u0011 חַיָּבִים.\nהַמַּבְעִית אֶת חֲבֵרוֹ, אַף עַל פִּי שֶׁחָלָה מֵהַפַּחַד, פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם; וְהוּא שֶׁלֹּא נָגַע בּוֹ, כְּגוֹן שֶׁצָּעַק לוֹ מֵאֲחוֹרָיו, אוֹ שֶׁנִּרְאָה לוֹ בַּאֲפֵלָה וְכַיּוֹצֵא בּוֹ. \u0010g75\u0011 וְכֵן אִם זָעַק לוֹ בְּאָזְנוֹ וְחֵרְשׁוֹ, פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם. \u0010y39\u0011 אָחֲזוֹ וְתָקַע לוֹ בְּאָזְנוֹ וְחֵרְשׁוֹ, אוֹ שֶׁנָּגַע בּוֹ וַהֲדָפוֹ בְּשָׁעָה שֶׁהִבְעִיתוֹ, אוֹ שֶׁאָחֲזוֹ בִּבְגָדָיו, חַיָּב בְּתַשְׁלוּמִין. \u0010g76\u0011 \u0010r39\u0011\nאִם הַנֶחְבָּל אוֹמֵר: נֶחֱרַשְׁתִּי, נִסְמֵית עֵינִי, וְאֵינִי רוֹאֶה, אוֹ: אֵינִי שׁוֹמֵעַ, אֵינוֹ נֶאֱמָן, שֶׁאֵין אָנוּ מַכִּירִים הַדָּבָר וְשֶׁמָּא יַעֲרִים, וְאֵינוֹ נוֹטֵל הַנֶּזֶק עַד שֶׁיִּבָּדֵק זְמַן מְרֻבֶּה וְיִהְיֶה מֻחְזָק שֶׁאָבַד מְאוֹר עֵינָיו אוֹ נִתְחָרֵשׁ, וְאַחַר כָּךְ יְשַׁלֵּם זֶה. \u0010y40\u0011 \u0010g77\u0011\nהַמְבַיֵּשׁ אֶת הֶעָרֹם אוֹ מִי שֶׁהוּא בְּבֵית הַמֶּרְחָץ, פָּטוּר. נָשְׁבָה בּוֹ הָרוּחַ וְהִגְבִּיהַּ בְּגָדָיו וְנִרְאָה כְּעָרֹם, וּבָא אַחֵר וְהוֹסִיף בְּהַפְשָׁטָתוֹ, חַיָּב בְּבֹשֶׁת; וּמִכָּל מָקוֹם, אֵין בָּשְׁתּוֹ שֶׁל זֶה מְרֻבָּה כְּמוֹ הַמְבַיֵּשׁ אֶת שֶׁאֵינוֹ עָרֹם כְּלָל. וְכֵן אִם הִגְבִּיהַ בְּגָדָיו לֵירֵד לַנָּהָר, אוֹ שֶׁעָלָה מִנָּהָר, וּבִיְּשׁוֹ, חַיָּב; וּמִכָּל מָקוֹם, אֵינוֹ כָּל כָּךְ בֹּשֶׁת כְּמוֹ שֶׁמְּבַיֵּישׁ \u0010g78\u0011 הַמְלֻבָּשׁ.\nבִּיְּשׁוֹ כְּשֶׁהוּא יָשֵׁן, וּמֵת \u0010g79\u0011 \u0005(בְּתוֹךְ שְׁנָתוֹ)\u0006, שֶׁלֹּא הִרְגִּישׁ בְּבֹשֶׁת, אֵין גּוֹבִין אוֹתוֹ \u0010y41\u0011 בֹּשֶׁת; וְאִם תָּפְסוּ יוֹרְשָׁיו, אֵין מוֹצִיאִין מִיָּדָם. \u0010y42\u0011 \u0010r40\u0011 \u0005וְיֵשׁ אוֹמְרִים שֶׁהוּא פָּטוּר (טוּר סכ\"ו בְּשֵׁם \u0010g80\u0011 הָרֹא\"שׁ)\u0006. \u0010y43\u0011 \u0010g81\u0011\nיָשֵׁן שֶׁבִּיֵּשׁ, פָּטוּר.\nהַמְבַיֵּשׁ אֶת \u0010y44\u0011 \u0010g82\u0011 הַשּׁוֹטֶה, פָּטוּר. \u0010r41\u0011 אֶת הַחֵרֵשׁ, \u0010g83\u0011 \u0010r42\u0011 אוֹ אֶת הַגֵּר, \u0010g84\u0011 אוֹ אֶת הָעֶבֶד, \u0010g85\u0011 \u0010r43\u0011 אוֹ \u0010y45\u0011 אֶת הַקָּטָן \u0010r44\u0011 שֶׁכְּשֶׁמַּכְלִימִים אוֹתוֹ נִכְלָם, \u0010r45\u0011 חַיָּב. וּמִכָּל מָקוֹם, אֵינוֹ דוֹמֶה הַמְבַיֵּשׁ אֶת הַקָּטָן לַמְּבַיֵּשׁ אֶת הַגָּדוֹל, וְלֹא הַמְבַיֵּשׁ אֶת הָעֶבֶד לַמְּבַיֵּשׁ בֶּן חוֹרִין, וְלֹא הַמְבַיֵּשׁ חֵרֵשׁ לַמְּבַיֵּשׁ פִּקֵּחַ. \u0010y46\u0011 \u0010c4\u0011 \u0010g86\u0011 \u0010t17\u0011\nרָקַק בַּחֲבֵרוֹ, חַיָּב. אֲבָל רָקַק בִּבְגָדָיו, אוֹ \u0010g87\u0011 שֶׁבִּיְּשׁוֹ בִּדְבָרִים, פָּטוּר; \u0010g88\u0011 \u0010r46\u0011 וְיֵשׁ לְבֵית דִּין בְּכָל מָקוֹם וּבְכָל זְמַן לִגְדֹּר כְּפִי מַה שֶּׁיִּרְאוּ. \u0010g89\u0011 \u0010r47\u0011 וְיֵשׁ \u0010y47\u0011 אוֹמְרִים שֶׁמְּנַדִּין אוֹתוֹ עַד שֶׁיְּפַיֵּס הַמְבֻיָּשׁ. \u0005הַגָּה: \u0010y48\u0011 \u0010r48\u0011 וְיֵשׁ אוֹמְרִים דְּמַכִּין אוֹתוֹ מַכַּת \u0010t18\u0011 מַרְדוּת (בֵּית יוֹסֵף ס\"ס א' בְּשֵׁם מָרְדְּכַי פֶּרֶק הַזָּהָב)\u0006. \u0010r49\u0011 וְהַמּוֹצִיא שֵׁם רָע עַל חֲבֵרוֹ, הָוֵי בִּכְלַל הַמְבַיֵּשׁ בִּדְבָרִים \u0005(פִּסְקֵי מהרא\"י סִימָן רי\"ב ות\"ה סִימָן ש\"ז)\u0006. \u0010g90\u0011 הַמְקַנְטֵר חֲבֵרוֹ וְאָמַר \u0010y49\u0011 לֵהּ: אֵינִי מוּמָר וְאֵינִי עֲבַרְיָן, אַף עַל פִּי שֶׁלֹּא אָמַר: כָּמוֹךָ, הָוֵי כְּאִלּוּ פֵּרַשׁ כָּמוֹךָ \u0005(בֵּית יוֹסֵף מָצָא כָתוּב מהרי\"ו סִימָן קנ\"ז)\u0006. \u0010g91\u0011 \u0010r50\u0011 הָאוֹמֵר לַחֲבֵרוֹ: הֲרֵי אַתָּה עוֹשֶׂה כְּמוֹ מַמְזֵר, אוֹ: אַתָּה כְּמַמְזֵר, אֵינוֹ כְלוּם \u0010g92\u0011 \u0005(מהרי\"ו סִימָן נ\"ט)\u0006. \u0010r51\u0011 וְיֵשׁ חוֹלְקִין וּסְבִירָא לְהוּ שֶׁאִם אוֹמֵר: אַתָּה כְּמַמְזֵר, כְּאִלּוּ קְרָאוֹ מַמְזֵר \u0005(פִּסְקֵי מהרא\"י סִימָן רנ\"ז וְסִימָן קל\"ה וּמַהֲרִי\"ט סִימָן קכ\"ז וַאֲגֻדָּה פ\"ב דְּיוֹמָא)\u0006 ; אֲבָל אִם אוֹמֵר: אַתָּה מְכַזֵּב כְּמוֹ מַמְזֵר עַד שֶׁתִּתְבָּרֵר דָּבָר זֶה, אוֹ כַיּוֹצֵא בָּזֶה שֶׁהֵטִיל בַּדָּבָר תְּנַאי, אֵינוֹ כְלוּם \u0005(פִּסְקֵי מהרא\"י סִימָן קל\"ה)\u0006. הָאוֹמֵר לַחֲבֵרוֹ: פָּסוּל אַתָּה, \u0010y50\u0011 יֵשׁ אוֹמְרִים דְּיָכוֹל \u0010t19\u0011 לְתָרֵץ \u0010g93\u0011 דְּפָסוּל מִשּׁוּם קוּרְבָה קָאָמַר וְאֵין זֶה בִּיּוּשׁ \u0005(מהרי\"ו סִימָן נ\"ט)\u0006. \u0010y51\u0011 וְיֵשׁ חוֹלְקִין \u0010g94\u0011 \u0005(מַהֲרַ\"ם מֵרִיזְבּוּרְק)\u0006. \u0010c5\u0011 \u0010r52\u0011 הַמְדַבֵּר רָע עַל שׁוֹכְנֵי \u0010t20\u0011 עָפָר, צָרִיךְ לְקַבֵּל עָלָיו תַּעֲנִיּוֹת וּתְשׁוּבָה וְעֹנֶשׁ מָמוֹן כְּפִי רְאוֹת בֵּית דִּין \u0005(מָרְדְּכַי פֶּרֶק הַחוֹבֵל)\u0006 \u0010r53\u0011 ; וְאִם קְבוּרִים בְּסָמוּךְ לוֹ, יֵלֵךְ עַל קִבְרֵיהֶם וִיבַקֵּשׁ מֵהֶם מְחִילָה, וְאִם הֵם רְחוֹקִים \u0010y52\u0011 \u0010g95\u0011 יִשְׁלַח שָׁם שְׁלוּחוֹ \u0005(מַהֲרַ\"ם מֵרִיזְבּוּרְק)\u0006. וְאִם כּוֹפֵר הַמְבַיֵּשׁ, אִם הוּא בִּיּוּשׁ שֶׁל שׁוֹכְנֵי עָפָר, יִתְּנוּ \u0010t21\u0011 חֵרֶם בְּעֵדוּת, \u0010y53\u0011 \u0010c6\u0011 אֲבָל לֹא עַל בִּיּוּשִׁים אֲחֵרִים \u0005(מָרְדְּכַי הַנַּ\"ל מהרי\"ו סִימָן כ\"ח)\u0006. וְנִרְאֶה, דְהַכֹּל לְפִי רְאוֹת בֵּית דִּין. וְעַיִּןִ לְעֵיל סִימָן פ\"ז סָעִיף כ\"ה. \u0010r54\u0011 הַקּוֹרֵא \u0010y54\u0011 לַחֲבֵרוֹ מַלְשִׁין בֶּן מַלְשִׁין, אִם הוּא לְבַד מַלְשִׁין, פָּטוּר. וְכֵן אִם קוֹרֵא לְרָשָׁע בֶּן צַדִּיק: רָשָׁע בֶּן רָשָׁע \u0005(הַגָּהוֹת מָרְדְּכַי)\u0006. \u0010y55\u0011 \u0010c7\u0011 הַקּוֹרֵא \u0010t22\u0011 לַחֲבֵרוֹ עֶבֶד אוֹ מַמְזֵר, וְהוּא אֱמֶת, פָּטוּר; \u0010r55\u0011 אֲבָל אִם לֹא יוּכַל לְבָרֵר, אַף עַל גַּב דְּשָׁמַע כֵּן שֶׁאֲחֵרִים דִּבְּרוּ כָךְ, לֹא נִפְטָר בְּכָךְ \u0005(נִמּוּקֵי מַהֲרַ\"ם)\u0006 \u0005(וע\"ל סי' תכ\"א ס\"ג)\u0006. \u0010g96\u0011\nאַף עַל פִּי שֶׁהַמְבַיֵּשׁ בִּדְבָרִים אֵינוֹ בַּר תַּשְׁלוּמִין, עָוֹן גָּדוֹל הוּא; וְאֵין הַמְחָרֵף וּמְגַדֵּף לָעָם וּמְבַיְּשָׁן אֶלָּא שׁוֹטֶה רָשָׁע וְגַס רוּחַ. \u0010g97\u0011 וְכָל הַמַּלְבִּין פְּנֵי אָדָם כָּשֵׁר מִיִּשְׂרָאֵל בִּדְבָרִים, אֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא. \u0010c8\u0011\nדִּין \u0010t23\u0011 הַמְבַיֵּשׁ תַּלְמִיד חָכָם בִּדְבָרִים, נִתְבָּאֵר בְּטוּר י\"ד \u0005סִימָן רמ\"ג סָעִיף ז'.\u0006 \u0010g98\u0011\nיֵשׁ הַכָּאוֹת רַבּוֹת שֶׁיֵּשׁ בָּהֶם בִּזּוּי וְצַעַר מְעַט, וְאֵין בָּהֶם נֶזֶק; וּכְבָר פָּסְקוּ לָהֶם חֲכָמִים דָּמִים קְצוּבִים, וְכָל הַמַּכֶּה אֶת חֲבֵרוֹ הַכָּאָה מֵהֶן, מְשַׁלֵּם אוֹתוֹ הַמָּמוֹן הַקָּצוּב; וְכֻלָּם קְנָסוֹת הֵן. וְאוֹתוֹ הַמָּמוֹן הַקָּצוּב \u0010y56\u0011 הוּא דְּמֵי \u0010g99\u0011 הַצַּעַר וְהַבֹּשֶׁת וְהָרִפּוּי וְהַשֶּׁבֶת, \u0010y57\u0011 בֵּין צָרִיךְ לִרְפוּאָה בֵּין לֹא צָרִיךְ, זֶהוּ מְשַׁלֵּם. וְכַמָּה הוּא מְשַׁלֵּם, הַבּוֹעֵט בַּחֲבֵרוֹ בְּרַגְלוֹ, מְשַׁלֵּם ה' סְלָעִים; הִכָּהוּ בְּאַרְכּוּבָתוֹ, מְשַׁלֵּם ג' סְלָעִים; \u0010g100\u0011 קִבֵּץ אֶצְבְּעוֹתָיו כְּמוֹ אוֹגֵד אֲגֻדָּה וְהִכָּהוּ בְּיָדוֹ כְּשֶׁהִיא אֲגֻדָּה, מְשַׁלֵּם י\"ג סְלָעִים; \u0010g101\u0011 \u0010r56\u0011 תָּקַע אֶת חֲבֵרוֹ בְכַפּוֹ, מְשַׁלֵּם סֶלַע; \u0010g102\u0011 סְטָרוֹ עַל פָּנָיו, מְשַׁלֵּם חֲמִשִּׁים סְלָעִים; סְטָרוֹ בַּאֲחוֹרֵי יָדוֹ, מְשַׁלֵּם ק' סְלָעִים; וְכֵן אִם צָרַם בְּאָזְנוֹ אוֹ תָלַשׁ בִּשְׂעָרוֹ אוֹ רָקַק וְהִגִּיעַ בּוֹ \u0010y58\u0011 הָרֹק, מְשַׁלֵּם מֵאָה סְלָעִים. \u0010r57\u0011 וְכָזֶה הוּא מְשַׁלֵּם עַל כָּל \u0010t24\u0011 מַעֲשֶׂה וּמַעֲשֶׂה; כֵּיצַד, כְּגוֹן שֶׁבָּעַט בַּחֲבֵרוֹ אַרְבַּע בְּעִיטוֹת, אֲפִלּוּ זוֹ אַחַר זוֹ, מְשַׁלֵּם עֶשְׂרִים סְלָעִים. סְטָרוֹ עַל פָּנָיו שְׁתֵּי סְטִירוֹת, מְשַׁלֵּם מֵאָה סֶלַע, וְכֵן בַּשְּׁאָר. \u0005הַגָּה: יֵשׁ אוֹמְרִים אַף עַל גַּב דְּאִיתָא \u0010g103\u0011 בַגְּמָרָא הַקּוֹרֵא לַחֲבֵרוֹ מַמְזֵר סוֹפֵג אַרְבָּעִים, \u0010r58\u0011 מִכָּל מָקוֹם יֵשׁ מְקוֹמוֹת שֶׁאֵין נוֹהֲגִין כֵּן, \u0010g104\u0011 וְהוֹלְכִין אַחַר הַמִּנְהָג (הָרֹא\"שׁ כְּלָל ק\"א סִימָן א')\u0006. וְנִרְאֶה לִי, דְּהוּא הַדִּין בְּאֵלּוּ הַדְּבָרִים \u0010g105\u0011 הַנִּזְכָּרִים: \u0010g106\u0011 \u0010r59\u0011\nכָּל אֵלּוּ הַסְלָעִים, הֵם מִכֶּסֶף מְדִינָה \u0010r60\u0011 שֶׁאֵין בּוֹ כֶּסֶף \u0010y59\u0011 אֶלָּא שְׁמִינִית, שֶׁהֵם שָׁלֹשׁ מָעִין, \u0010r61\u0011 שֶׁכָּל מָעָה מִשְׁקָל ט\"ז שְׂעוֹרוֹת כֶּסֶף צָרוּף, שֶׁהוּא עוֹטָמָנִי \u0010g107\u0011 \u0010r62\u0011 אֶחָד.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בִּמְכֻבָּד. אֲבָל אָדָם שֶׁהוּא מְבֻזֶּה וְאֵינוֹ מַקְפִּיד בְּכָל אֵלּוּ הַדְּבָרִים וְכַיּוֹצֵא בָּהֶם, אֵינוֹ אֶלָּא כְּפִי מַה שֶּׁיִּרְאוּ הַדַּיָּנִים שֶׁרָאוּי לִטֹּל. \u0005הַגָּה: \u0010r63\u0011 יֵשׁ אוֹמְרִים שֶׁאֵלּוּ הַדְּבָרִים אֵינָן רַק מִשּׁוּם בֹּשֶׁת וְצַעַר, אֲבָל רִפּוּי וָשֶׁבֶת הַכֹּל לְפִי הָעִנְיָן (טוּר סל\"ד בְּשֵׁם הָרִי\"ף וְכ\"כ \u0010g108\u0011 הָרֹא\"שׁ בִּשְׁמוֹ)\u0006. \u0010g109\u0011\nכֵּיצַד מַגְבִּין הָאִדָּנָא חַבָּלוֹת וּקְנָסוֹת אֵלּוּ, נִתְבָּאֵר בְּסִימָן א'.",{"g":["א) לשון הטור וכן כתב הרמב\"ם רפ\"ה מהלכות חובל","ב) כתב ה\"ה איתא בכמה מקומות ואיתא בפ\"ג דכתובות דף ל\"ב ע\"ב","ג) מימרא דריש לקיש בפרק ד' מיתות סנהדרי' דף נ\"ח ע\"ב","ד) וכתב הסע\"ע דה\"ה היכא שנזכ' בדברי האחרונים שהקהילות החרימו על זה ☜אין צריך לנדותו עתה מחדש חלא שהוא מוחרם ועומד העובר על דבר תקנתם וכתב עוד שנ\"ל מדסתם מהרמ\"א וכתב סתם וצריכים להתיר וכו' משמע דרצונו לומר כסתם התרת נדרים שהוא בג' שלא החמירו להתיר בק' אנשים מג' קהילות מג' מדינות כי אם ברוצה לישא אשה על אשתו וכו':","ה) נלע\"ד שצ\"ל לעשות לו דין וז\"ל שם ע\"מ שיקבל עליו כל מה שירצו בב\"ד","ו) כצ\"ל וכן הוא שם בנימוקים","ז) שם ס\"ד וברמב\"ם שם ד\"ב מימרא דרבי יוחנן שם בכתובות דף ל\"ה ע\"ה","כלומר אבל' אם יש בה שוה פרוטה כיון שהוא חיוב ממון אין אדם לוקה ומשלם","ח) שם ושם ברמב\"ם","כ' ה\"ה הכי אסקינן פ\"ח דב\"ק דף פ\"ח (ע\"א) דעבד אחיו הוא במצות והרי הוא כאשה והדין מבואר בפרק ג' דמכות (ריש דף ט') ובטור וברמב\"ם שם איתא עבד כנעני של חבירו ותמה בב\"י בזה למה הצריך שיהי' עבד של אחרים שאף עבדו אין ניתן לו רשות להכותו מטעם ששייך במצות ושכ\"כ הרמב\"ם בספט\"ו מה' סנהדרין (וע' בכ\"מ שם שכתב שם טעם אחר) ולכן השמיט המחבר של חבירו","ט) משנה רפ\"ק דב\"ק דף פ\"ג פ\"ב","\u0003שם בגמרא דף פ\"ה ע\"א וע\"ב ויותר מבואר הוא בירושלמי כתבוהו הרי\"ף והרא\"ש בר\"פ החובל:\u0004 ","י) לשון הטור ס\"ו וכ\"כ הרמב\"ם בפ\"ב מהלכות חובל ומזיק דין ב' שם במשנה","כ) שם ושם וכ' ה\"ה פסק כרבא שם (דף פ\"ז ע\"א) ובהל'","ל) בטור וברמב\"ם שם איתא לחיות","מ) שם ושם וכ' ה\"ה פשוטו כשאין כאן שבת דאינו בטל ממלאכתו ונזק לא חשבינן ליה לא בהא ולא בההיא כיון דסופו לחזור אין לו נזק אע\"ג דאי מיזדבן השתא היה נגרע מערכך","נ) שם ושם","ס) כן כתב הראב\"ד שם בהשגה וכתב ה\"ה שנ\"ל שגם זה דעת הרב ז\"ל וסתם הרב דפשיטא הוא והדין הוא בירו' הביאו בהל' וכ\"כ הטור ע\"ש","ע) שם ושם","פ) שם ברמב\"ם וכ' ה\"ה כתב זה במקום טימוס האמו' בירושלמי שהיא מכה קלה מאוד","צ) שם וכתב ה\"ה שם וגם זה נכון","ק) שם דין ג' וטור סעיף י' שם במשנה ובגמרא דף פ\"ד ע\"ב","ר) שם ושם סוגיא בגמרא שם דף פ\"ה ע\"ב וביארו שם עד שיחזיר מראהו כשהיה","ש) לשון הטור סי\"ב אוקימתא בגמרא שם","ת) כ\"כ הרא\"ש שם מסברא והביא ראיה מהתוספת פ' הנשרפין (סנהדרין ד' ע\"ח) בד\"ה סוף חמה לבא וכו':","א) שם ושם מבואר בסוגיא בב\"ק פ\"ו דפ\"ו ע\"א אליבא דרבא דלעיל","ב) גם זה מפורש באותה סוגיא שם אך בטור הוסיף ☜שאינו משלם השבת אלא אם הוא יורד לרקד בראשו וכן משמע לשון הגמ' מפירש\"י שם","\u0003ג) כן הוא בטור וברמב\"ם שם פ\"ב מה' חובל:\u0004 ","ד) שם ושם","ה) שם ד\"ו כתב ב\"ה שלעולם הרושם ניכר שאינו חוזר כמו שהיה וההיא סוגיא דהחובל בבתו צ\"ע דמשמע דלאו בכל מקום משלם נזק אלא במקום הנר' כמו פנים","\u0003ו) ל' הטור סי\"ז:\u0004 ","ז) משנה שם דף פ\"ג ע\"ב סימא עינו קטע את ידו","ח) שם במשנה שבר רגלו","ט) ואפי' הוא אדם חשוב ואשר נגע בכבוד חשיבותו זה משלם לו בכלל בושה שהיא משתלמת לפי המתבייש:","י) ועומד לשימוש ולעשות כל מה שירצה לפי שהעבד הנוקב מרגליות אין רבו מקפיד כ\"כ על חסרון רגלו שראוי הוא למלאכתו הראשונה ויותר יהיה קבוע במלאכתו וישומו כאלו לא היה נוקב מרגליות דמסתבר שלא יפסיד באומנות הרא\"ש שם","כ) לשון הרמב\"ם שם דף י\"א מבואר שם בגמרא דף פ\"ה ע\"א","ל) טור וכן פסק רש\"י שם","מ) לשון הרמב\"ם שם דין י\"ב שם במשנה ומימרא דרבא שם דף פ\"ה ע\"ב","נ) שם דין י\"ד אברייתא שם דף צ\"ח ע\"א ואיתא בהלכות שם","ס) באותה ברייתא שם","ע) שם די\"ו וכתב ה\"ה נראה שזה פשוט אצל הרב דע\"כ לא לא אמרינן דנותן לו מיד אלא כדי שלא יתחייב יותר מן האמוד אבל אם רצה המזיק ליתן דבר יום ביומו ואם יתרפא קל מהר' ירויח ואם יאמר יפסיד ודאי שומעין לו שהרי אינו חייב בו אלא ברפואתו ושבתו והרי הוא נותן ונכון הוא","פ) שם דין י\"ט וכתב ה\"ה יצא לרבינו ממ\"ש לבעלה שאם רצה המזיק אין שם אומד שאם בהכרח שיש שם אומד תכף יתן לו אומדו ויפטר וכן כתבו המפרשים","צ) משנה שם רפ\"ח דף פ\"ג ר\"ב","ק) ברייתא שם דף פ\"ה ע\"א וכת\"ק","ר) כן הגי' ה\"ה שם בספרי הרמב\"ם והוא עיקר הנוסחא","ש) ברייתא שם","ת) שם די\"ח שם בגמ'","א) שם בגמרא אסיא דמגן במגן ופירושו כשאין הרופא מצפה לקבל שכר אינו מעיין כל כך בענין החולי","ב) טור סי\"ז ושם בגמרא אסיא רחיקא","ג) שם ושם בגמרא","\u0003ד) ל' הרמב\"ם שם רפ\"ג משנה שם רפ\"ח.\u0004 ","ה) שם דין ז' ברייתא שם דף צא ע\"א","ו) וכתב המרדכי וה\"ה ☜אם אחזו והכה בכותל כנגד אזנו ונתחרש סמ\"ע בשם ד\"מ","\u0003ז) שם ס\"ג:\u0004 ","\u0003ח) מימרא דרבא שם דף פ\"ה ע\"ב:\u0004 ","\u0003ט) טור סי\"ו בשם הרא\"ש:\u0004 ","י) שם דין י\"ג כ' ה\"ה בעיא דרבא שם ואמר את\"ל כיון דלא אמדוהו יהיב ליה דמי כולו וכו' ופסק כאת\"ל וכן דרך רבינו בגמרא:","כ) כן היא שם בגמ' ברמב\"ם ובטור","פירו' כאלו עשה הכל בפע' אחת שאינו עולה כ\"כ כמו שאומדין כל אחת בפני עצמו תוס'","ל) וכן כ' ה\"ה שם בשם התו' ושלזה הסכים הרשב\"א ואפשר שזה דעת רבינו הרמב\"ם ז\"ל","מ) שם ושם בגמרא בעיא דלא איפשטא","נ) כ' ה\"ה פי' אחר שנגרעו דמיו מחסרון ידו ורגלו דודאי אם תפס דמי כולו כמו שהיה בריא מפקינן מיניה וא\"ת הכל עולה לחשבון א' לא היה דחילוק יש בין שומ' אחת לשומות הרבה כדאמרינן לעיל","ס) ל' הטור סי\"ח וכ\"כ הרמב\"ם שם ס\"פ הנזכר מימרא דרבי חנינא שם דף צ\"א ע\"א","\u0003ע) אמתניתין שם אמר ליה רבי תן לי זמן וכו'\u0004 בגמ' שם:","\u0003פ) ל' הרמב\"ם שם בפ\"א דין יח בעיא דאיפשטא שם:\u0004 ","\u0003צ) כ' ה\"ה פשוט הוא:\u0004 ","ק) מפורש במשנה שם דף צ ע\"א ובגמרא שם דף צ\"א ע\"א מימרא דר\"פ אבל בבגדו לא","ר) כ' ה\"ה אינו מבואר בגמרא אבל נכון הוא מן הטענה שכ' הראב\"ד ז\"ל א\"א יפה אמר ומה במקום שאין העדים יודעים שחבל בו ב\"ה או חבל הוא בעצמו אמרו נשבע ונוטל לפי שאין דרך שיחבול אדם בעצמו והולכין אחר החזקות כיון שראו עדים שחבל בו ואין דרך אבן קטנה לחבל' הזאת כ\"ש עכ\"ל","ש) שם ד' י\"ט וכ' ה\"ה מפורש באלו הן הנשרפין (דף ע\"ו ע\"ב) לענין מיתה וכל שכן לענין נזיקין (","ת) ☜דבברזל לא כתיב אשר ימות בו)","א) כ\"כ ה\"ה שם כמ\"ש שם בגמרא","ב) שם ברמב\"ם מחלוקת שונות בפ\"ג דב\"ק (דף ל\"ג ע\"א) ופסק בפסק ההל' ה\"ה","ג) משנה בפ\"ח דב\"ק דף צ ע\"א","ד) כן הוא בגמ' ובהלכות הרי\"ף ופסקי הרא\"ש","ה) לשון הרמב\"ם שם בפ\"ב דין ז' מפורש בברייתא וגמרא שם דף צ\"א ע\"א","ו) מבואר במ\"ש שם סי' כ\"ה","\u0003ז) שם ד\"ח כתב יראה לי וכו'\u0004 וכתב ה\"ה טענה נכונה היא זו","ח) ל' הטור סעיף כ\"ד וכ\"כ הרמב\"ם שם בפ\"ג ד\"ב פשוט בגמ' ערום בר בושת הוא וכו' בי' המרחץ בר בושת הוא דף פ\"ו ע\"ב וכ' ה\"ה דעת רבינו ז\"ל כפי' רש\"י שכיון שאינו מקפיד לילך ערום בפני בני אדם מי הוי בר בושת אפי' רוקקין אותו או מכין אותו לא יהיה מתבייש ובית המרחץ בנ\"א עומדי' ערומים שם ואין בושת אבל בתו כתבו דפשיטא שרק בפני ערום או סטרו חייב ובהכי איירי מתני' שם המבייש את הערום חייב וסוגיא דגמרא בשביישו דרך הפשטה והיינו דאקשי' ערום בר בשת הוא וכו' כיון דאינו לבוש מי יפשיטנו והלא ערום הוא ועד\"ז פי' בית המרחץ הרשב\"א בנימוקיו וכתב הב\"י וכיון דאפוקי ממונא היא נקטינן לקולא","ט) שם ד\"ג בעיא ולא איפשיטא שם בגמ' דפ\"ו ע\"א ופסק כדרכו לפסוק בכל ספיק' דדינא","י) כן הוא ברמב\"ם וכן העתיק הטור","כ) שהוא מפרש סוגיא דהתם דבעיא איפשטא לפטורא וכ\"נ מדברי התו' שם","\u0003ל) שם בפ\"ג דין ד' ושם במשנה דף פ\"ו ע\"ב:\u0004 ","מ) ברייתא שם","נ) שם בברייתא","ס) כ' ה\"ה מפורש בסוגיא לדברי הכל שם דף פח ע\"א וכ\"כ התו' שם בריש העמוד דף פ\"ו ע\"ב וכדמפרש ר\"פ שם","ע) ברייתא שם","פ) משנה שם וכדמפרש לה ר\"פ שם דצ\"א ע\"א","צ) שם ע\"א אמרי במערבא משמיה דר' יוסי בר אבין","ק) רמב\"ם שם ד\"ה","ר) טור סל\"ג בשם רב שרירא גאון ושכ\"כ אביו הרא\"ש שם בפ' החובל וז\"ל שם ומסתברא דיותר בושת בדברים מבושת של חבלה דאין דבר גדול כלשון הרע ודבה שאדם מוציא על חבירו ועוד כ' בתשו' בכלל ק\"א ס\"א נהגו בכל מקומות ישראל לעשות תקנה וסייג לבעלי הלשון ולקנוס המבייש לפי המבייש והמתבייש וכן יעשו ב\"ד בכל ענין ע\"כ","ש) כ' בהגה' מרדכי אם קראו מותר אחר שעשה תשו' ☜הרי עובר חרם ר\"ג ואם לא ידע מן החרם אינו מקרי' עבריין הביאו הסמ\"ע ומבואר במ\"ש בסי' של\"ד בסופו ובהג\"מר דקידושין כ' בדין ☜איש שחרף אשה דיתענה בה\"ב וישב יחף פני ב\"ה ויבקש מחילה על המגדל הביאו הסמ\"ע וע' בסי' תכ\"א סי\"ג:","ת) בשם גדולי אשכנז וראי' ספ\"ב דמציעא דף ל\"ג ע\"א בעי רב חסדא מרב הונא תלמיד וצריך לו רבו א\"ל ר' חסדא ל\"צ לך וכו'","א) וכתב שם שאינו צריך לפייס אלא לאותו איש שחירף ולא אמו","ב) בשם תשובת רבינו אביגדור כהן וכתב עוד בשמו וכן אם קראו בן הזונה יכול לתרץ דיבוריה ר\"ל בן הפונדקי'","ג) כ\"כ על א' שקראו כנען דליכא למימר כמו כנען בידו מאזני מרמה דאם כן עבד נמי ר\"ל עבד עברי או עבד לוה לאיש מלוה אבל כ' על אשה אחת שיצא עליה קול שזינתה בטברי' וצווח א' לא' מבני' בעת הקטטה טבריה טברי' לא מקרי ביוש בפרהסיא אך יקח י' אנשים ויבקש מטו ממנו בחצר ב\"ה דרך כבוד וכו' הביאו גם כן הסמ\"ע בקיצור","ד) ומסיק שם ☜שלוחו יקח ב' מהעיר שנקבר שם וילך על קברו לבקש מחילה בשם המחרף","ה) שם ס\"ג דין ז' ומפרש בכמה מקומות","\u0003ו) דרש רבא וכו'\u0004 פ\"ד דב\"מ דף נ\"ט ע\"א","\u0003ז) שם דין ח' מהא דשלח ליה רב חסדא לר\"נ וכו'\u0004 הרי אמרו לרכיבה שלש כו' שם בפ\"ג דף כ\"ז ע\"ב","ח) ע' במ\"ש בסוף הסי'","ט) כ' ה\"ה לשון הגמ' לסינוקרת י\"ג ופירוש הרב קבץ אצבעותיו ורש\"י ז\"ל פי' פי' אחר וזה הנכון והנ\"י כ' בשם הרא\"ה והערוך הבועט ברגלו ה' לפי שהכהו בחמשה אצבעות שברגלו לארכובה ג' לפי שיש בה שלשה פרקים לסינוקרת י\"ג שהוא הכהו מאחרי ידו לפי שיש בידו י\"ג פרקים לבד מפרק אגודל שלא הכה בו וזה עם פרק העליון","\u0003י) זה ב' בפי' מה ששנינו התוקע לקבירו נותן לו סלע וכו'\u0004 שם פ\"ח (דף צ ע\"א) אבל יתר המפרשים פירשו שתקע באזנו בקול גדול ופ\"א המכה כנגד אזנו (וכן פרש\"י שם) והדין כת\"ק דמתני' שם ה\"ה","כ) כל זאת הבבא הוא במשנה","ל) קידושין פ\"א דף כ\"ח ע\"א","מ) וכתב שם שיש רשות לקנוס אותו כפי התיקון שרשות לעשות גדר ותקנה לעבירה לפי ראות עיניהם וכו':","נ) ובנימוקי מהר\"מ כ' שם על איזה דברים חייב עליהם מלקות ועל פי מ\"ש הרמ\"א לא העתקתי אותם:","ס) איבעי' בגמרא שם ד' צ' ע\"ב ונפשטא מימרא דרב יהודה א\"ר כל כסף האמור בתורה כסף צורי ושל דבריהם כסף מדינה בפ\"ד דף ל\"ו ע\"ב וכ\"כ הרמב\"ם שם בפ\"ג ד\"י כל אנו הסלעים הם מכסף א\"י באותו הזמן שהיה בכל סלע חצי דינר כסף וג' דינרים ומחצה נחושת וכו'","ע) שם די\"א כ' ה\"ה חלוק זה מכל האמורין מתקע חבירו עד כאן מפיר' במשנה שם כתנא קמא דר\"ע (מפרש בגמ' דף צ\"א ע\"א) אבל אג' הראשונים אינם מפורשי' אם הם במכובד דוקא ודעת רבינו להשוותן ונכון הוא (וכ\"כ התוספת בשם ר\"י שם סוף דף כ\"ז)","פ) וכ\"כ ה\"ה שם ד\"ח בשם קצת המפרשים וכן פירש\"י ז\"ל שם","צ) כ' הב\"י אבל בנוסחת הרי\"ף שבידינו איתא שהסכים לדעת רבנן אחריני דהאי דמי הכל הוא הרי בהדיא שהסכים לדעת הרמב\"ם והכי נקטינן כ\"ש דאוקמי ממונא הוא ע\"כ (וה\"כ איתא בספרים שלפנינו) וכ' עוד הב\"י דאם הכהו בחוזק באותן מיני הכאות עד שהיה בהן כדי לעשות נזק גדול ביותר משמע לי דמוד' הרמב\"ם דמשלם ריפוי ושבת:"],"t":["\u0003בחמשה. \u0004 וה' דברים אלו משתלמין מן היפה שבנכסיו כדין כל המזיקין כן הוא בהרמב\"ם ריש הלכות חובל וכ\"כ הסמ\"ק וכת' הה\"מ שם שהדין מבואר ריש ב\"ק דאמר כולן כאבות לשלם ממיטב ע\"כ וכ\"פ הרי\"ף והרא\"ש והנ\"י ריש ב\"ק וכ\"פ רש\"ל שם סי' ו' וכן הדין לעיל סי' שפ\"ה ושפ\"ח ס\"ב. ש\"ך:","\u0003אדם. \u0004 פירוש תרתי בעינן שלא ראוהו בשעת הכאה וגם שתהא המכה עומדת במקום שלא תהי' נראית לאחר זמן. סמ\"ע:","\u0003גרמא. \u0004 ע\"ל סי' שס\"ג סס\"ו בהג\"ה דומה לזה בסגירות בית חבירו ומעכבו מלדור בו. שם:","\u0003שער. \u0004 כן הוא בטור ול\"ד קאמר דהנדנוד בראשו בשעת רקודו נעשה גם בלא שערות דאל\"כ גם בגילח שערו ה\"ל לחייבו ועוד דא\"כ בכלל נזק יחשב וכיון דכבר שילם לו נזק דמי השערות שלו בכללו הוא השבת דשערות אלא דכל זמן שראשו עליו יכאב א\"י להחעסק במלאכת ריקוד ונדנוד ראשו והוא שבתו. שם:","\u0003עבד. \u0004 רש\"י ונ\"י ר\"פ החובל פירשו כאילו נמכר להיות עבד עברי אבל הרא\"ש כתב שם דשמינן ליה כמו עבד כנעני דנמכר לעבד עולם דגם חסרון אברו הוא לעולם משא\"כ ע\"ע שאינו נמכר אלא לשש שנים ואם באנו לשומו בכל ו' שנים פעם אחר פעם יעלה לערך יותר ממה שיעלה הערך כששמין אותו פעם אחד. שם:","\u0003אומנות. \u0004 ומהרש\"ל פסק דלענין נזק אין חילוק בשום בן אדם בעולם אלא שמין אותו כעבד שאינו יודע שום מלאכה וע\"ש סי' י\"א ומ\"מ אין טעם לדבריו דהא עכ\"פ היזקו היא רב יותר מעבד שאינו יודע שום מלאכה ודו\"ק נ\"ל. ש\"ך:","\u0003המלך. \u0004 שהרי גם כאן גזר המלך הש\"י שכאשר עשה וחתכו לחבירו בסייף כן יעשה לו אלא שלמדנו דעשייה זו היא נתינת ממון ומש\"ה אף שישלם לו דמי נזק ידו עדיין עליו לשלם מה שציערו בקטיעת היד ומן הדין צריך לשלם דמי צער קטיעת סייף כמו שעשה אלא משום דקטיעת יד חבירו כבר נעשה ולקטוע ידו לכתחלה אין אדם לוקח דמים הרבה מש\"ה שיערו חכמים כמה היה נותן לחתוך בסם למי שנגזר עליו חתיכת סייף דמדכתי' ובער בשדה אחר ואחז\"ל שישומו הערוגה אגב כל השדה כמ\"ש בסי' שצ\"ד למדנו שהתורה חס' על המזיק להקל לו בשומא כן כת' הרא\"ש. סמ\"ע:","\u0003בטל. \u0004 עיין בסמ\"ע שהאריך בביאור דברי הטור בזה וע\"ל סי' רס\"ה וסי' של\"ד ושל\"ה:","\u0003תקנה. \u0004 דאם היה צריך לתת שכר ריפוי דבר יום ביומו שמא יתרשל המוכה ברפואתו באומרו דמי הרפואה הן על המכה אצערנו בזה שיוציא הרבה דמים זהו שמסיק דאם היה מתגלגל כו' ואף דלפעמים יהי' בזה הפסד להמכה באם הבריא מיד כו' זהו דבר שאינו שכיח דיבריא קודם זמן האומד משא\"כ בהמשך חליו דאיכא למיחש כמ\"ש ועוד דכמה סבות גורמות הן שיומשך החולי. סמ\"ע:","\u0003הקל. \u0004 ורש\"י בפרק אלו נערות פירש דבושת אדם בינוני מרובה משל אדם נכבד ומזולזל וכת' הר\"ן שם וז\"ל ובודאי דבמילי אחריני הכי הוא אבל באונס ומפתה נראין הדברים שכל שהוא זולזל יותר בשתו מרובה. שם:","\u0003אדם. \u0004 דכל שלא אחזו לעשות מעשה בגופו גרמא בעלמא מקרי ומכל מקום חייב בד\"ש כיון שנתחרש בסיבתו. שם:","\u0003זמן. \u0004 משמע אפילו זיל נכסי דנתבע ודוקא כשנתחייב בדין אבל אם מבקש זמן להביא עדים לפטור נותנין זמן אף לחבלות אם זיל נכסיה כדמוכח בתוספות והרא\"ש פרק הפרה וכ\"כ הנ\"י שם ודלא כב\"ח בסי' כ\"ד וכבר השגתי עליו שם ע\"ש. ש\"ך:","\u0003שביישו. \u0004 עפ\"ר שם הוכחתי דלבשת של חבלה אין נותנין זמן כיון דלשאר דברים שגובין בחבלה אין נותנין זמן משום דיש בהן חסרון ממון אגבן גובין ג\"כ צער ובשת אע\"ג דלית בהו חסרון ממון ודוקא בדבר שאין גובין עליה אלא דמי בשת לחוד הוא דנותנין זמן ונראה דה\"ה צער כשהוא לחוד כגון כואו בשפוד במקום שאין רואין כיון דלית ביה חסרון ממון נותנין לו זמן והא דכתבו הפוסקים דין זה בבשת לחוד ולא בצער משום דבש\"ס מעשה כך היה לפני ר\"ע באשה שפרע ראשה ונתביישה. סמ\"ע:","\u0003קטן. \u0004 בטור כתב עוד דאומדין ג\"כ המקום אשר הכהו עליו ע\"ש. שם:","\u0003פטור. \u0004 דאמרי' מזלו גרם. שם:","\u0003כלל. \u0004 נראה דאפילו אם הוא מחודד אלא שלא המית בחידודו רק במשקלו פטור דזיל בתר טעמא. שם:","\u0003חייבים. \u0004 ע\"ל סי' שס\"ב שכתב הטור דומה לזה בקוצץ נטיעותיו של חבירו. שם:","\u0003רקק. \u0004 עיין בתשובת ר\"י לבית לוי מדינים אלו וכ' הסמ\"ע דחייב משום בשת ובבגדיו ובביישו בדברים פטור דבעי' שיעשה מעשה בגופו דומיא דוהחזיקה במבושיו:","\u0003מרדות. \u0004 דעבר על לאו דלא תונו ומ\"מ כיון דהוא לאו שאין בו מעשה אין לוקין עליו מלקות דאורייתא. שם:","\u0003לתרץ. \u0004 וכתב עוד מהרי\"ו שם וכן אם קראו מבייש הנשים יכול לתרץ דיבוריה דר\"ל דמביישן בדברים עכ\"ל הד\"מ וכתב עוד בשם נימוקי מהר\"ם דאם ע\"א מעיד שקראו ממזר ועד א' מעיד שקראו בן הזונה דמצרפין לענין בן הזונה דבכלל מאתים מנה מ\"מ אין לו דין ממזר דלמא קראו בן הזונה כשהיתה פנויה. שם:","\u0003עפר. \u0004 עיין בתשובת ראנ\"ח סי' צ' וצ\"ג וקי\"א:","\u0003חרם. \u0004 אבל א\"צ לישבע גם בביוש של שוכני עפר כן הוא שם עכ\"ל הסמ\"ע עיין במהרש\"ל פ' החובל באריכות מדינים אלו ועיין בתשובת מהרי\"ט מיו\"ד סי' ט\"ז שכתב שכל מה שמדבר לחבירו בלשון צחות כגון שקורא לרבים בני יוונים או אמר על א' שבא לדור ממקום אחר ונעשה דיין הגר אשר בקרבך יעלה עליך וגומר אע\"ג דקרא קאי אעו\"ג לא מקרי בושת וההיא איתתא דאמרה רבה כריסיה כו' אשה זו פושעת היתה דה\"ל ליתן בו סימן אחר וע\"ש ראיה שלו. הגה בש\"ך:","\u0003עבד. \u0004 עיין בתשובת ר\"מ אלשיך סי' ע\"ג ובתשובת מבי\"ט ח\"א בשאלות השניות סי' ט\"ז דף ק\"ח אם קראו בן השפחה ונידהו וע\"ש עוד בסי' קצ\"ה דף קע\"ד. שם:","\u0003ת\"ח. \u0004 וראשים וממוני הקהל כת\"ח כן כתוב בתשובת מהר\"י לבית לוי סי' כ\"ט וע\"ש באריכות \u0005(א\"ה יען ראיתי בספר בני חייא שהעתיק בסי' זה ובסי' שאח\"ז הרבה פסקי דינים שהובאו בספר כנה\"ג מכמה תשובות גדולי ראשונים ואחרונים הם המדברים מעניני קנסות וביושים וכדומה לזה אמנם א\"א לפורטן הנה כי רבים הם מאד והרוצה לעמוד עליהן יעיין אחריהן במקומן)\u0006:","\u0003מעשה. \u0004 ובטור מסיים כאן ז\"ל או שפרע ראש האשה משלם מאה סלעים כו' וכתב בד\"מ בשם נמוקי מהר\"מ וז\"ל המלעיג על דברי חכמים לוקה והקורא לאשת חבירו זונה או פרוצה לוקה ד' מלקיות דתנן פרע ראש האשה נותן לה ת' זוז ומדלא מגבינן קנסא בבבל לוקה ד' מלקיות ועמ\"ש בסימן ב' בשם מהרי\"ו דכל מלקות הוא מ' זוז עכ\"ל. סמ\"ע:"],"r":["\u0003אסור כו'. \u0004 סנה' פ\"ה א' א\"ל ואחר כו' וע\"ש כל הסוגיא:","\u0003ואם כו' שנא' כו'. \u0004 כתובות לג א':","\u0003ואם הקפידה כו'. \u0004 סנה' שם וה\"ק ומה כו':","\u0003וצריכין כו'. \u0004 עבא\"ח סי' נה סי\"א וסי\"ב:","\u0003ואפי' הכה כו'. \u0004 מכות ח' ב':","\u0003שהרי כו'. \u0004 ב\"ק פ\"ח א' ועבה\"ג וב\"ח כ' שלכך כ' של חבירו משום דבשלו אף ביש בה ש\"פ לוקה כיון שאינו משלם דלא כסמ\"ע שכ' דברים זרים מאד:","\u0003אם החבלה כו'. \u0004 ואם אין כו' עד ס\"ט ירושלמי והביאו הרי\"ף ורא\"ש שם:","\u0003י\"א כו'. \u0004 רש\"י שם צא א' ד\"ה וריפוי כו' ובירושלמי ר\"פ תני בן עזאי אומר נותנין נכאי מזון מהו נכאי מזון בקדמיתא הוינא אכל טלופחין וירק וכדון לית בי מיכל אלא ביען ותרנגולין ומה דו אמר יהבין ליה:","\u0003או אצבע כו'. \u0004 עסי\"ד:","\u0003 (ליקוט) הכהו במקום שאינו נראה. \u0004 כגון שהכהו על ברכיו או בגבו. רמב\"ם (ע\"כ):","\u0003ולא ראהו כו'. \u0004 דלא גרע מהכהו במטפחת בס\"ח ורקק בחבירו בסל\"ח:\n\u0003 (ליקוט) ולא ראהו כו'. \u0004 זהו מהגהת הראב\"ד עליו וטעמו דלא ורע ממטפחת דס\"ח וכן הגיה שם במטפחת וכמ\"ש בס\"ח בהג\"ה וי\"א כו' (ע\"כ):","\u0003במטפחת שבידו או כו'. \u0004 לשון הרמב\"ם ובירושלמי טומוס והוא שטר וכמ\"ש בתוספתא ספ\"ט הכהו באחר ידו בנייר בפנקס בעורות שאינן עבודין בטומוס של שטרות שבידו נותן ארבע מאות זוז לא מפני שמכה של צער אלא מפני שמכה של בזיון שנ' קומה ה' הושיעני אלקי כי הכית את כל אויבי לחי כו' בשבט יכו על הלחי גוי נתתי למכים כו'. וה\"ה למטפחת ורא\"ש פי' בשם ערוך קלף:","\u0003וי\"א דוקא כו'. \u0004 כנ\"ל ס\"ז:","\u0003ואם כו'. \u0004 כנ\"ל:","\u0003השקהו כו'. \u0004 למד ממ\"ש פ\"ו א' וצ\"ע דשם פ\"ה ב' אמרינן ריפוי כגון כו' ול\"ק בכה\"ג וצ\"ל שגי' הרמב\"ם שם היתה בכה\"ג שהרי לא הזכירו מ\"ש בגמ' שם כלל:","\u0003אבל אם כו'. \u0004 כמ\"ש בסנהדרין ע\"ז א' סוף חמה כו' ועתוס' שם ד\"ה סוף כו' וכ\"ש לענין נזקין דהא פליגי במצמצם בנזקין שם:","\u0003שער ראשו. \u0004 ל\"ג שער דזה אין סופי לחזור ובכלל נזק הוא ועוד א\"כ גילח נמי וכ\"כ סמ\"ע וכ\"ה בגמ' שם:","\u0003המחסר כו'. \u0004 כמש\"ש פ\"ו א' וכנ\"ל ס\"ה וה\"ה לכל איברים שאינן חוזרין וכמ\"ש בפ\"ק דקדושין לענין עבד שיוצא בכל איברים שאינן חוזרין דיליף משן ועין וה\"ה כאן ועסי\"ד:","\u0003אפי' כו'. \u0004 דהא אחבורה חייב רחמנא וע\"ש פ\"ד ב' ולכן דוקא שאינה חוזרת כמ\"ש בשבת קז ב' מנין לחבורה כו' וז\"ש לפיכך כו' כמ\"ש בפ\"ג דחולין ושאר שקצים ורמשים כו' וה\"ה לאדם כמש\"ש קכב א' ועסט\"ו או חבל כו' וכנ\"ל וכמש\"ש חבורה נאמר תחלה כו'. ומ\"מ מ' שם פ\"ח א' דוקא במקום הנראה כגון בפנים וכן השיגו המ\"מ וע\"כ צ\"ל כן דהא שמין אותו כעבד ואמרינן בכתובות נ\"ח ובקדושין י\"א אי משום מומין שבסתר כו' וכה\"ג אמרינן לענין יציאתו לחירות מומין שבגלוי ואינן חוזרין:","\u0003 (ליקוט) כאלו כו'. \u0004 ר\"ל עבד כנעני שאין דמים לעברי וערש\"י בב\"ב י\"ג א' בד\"ה ה\"ג כו' אבל אינו כו' (ע\"כ):","\u0003ואם היה כו'. \u0004 כמו בשבת בסי\"ז בהג\"ה:","\u0003אבל אם כו'. \u0004 דאל\"כ דאף לפחות משערינן א\"כ למה אמרו דשמין אותו כעבד סתמא שאינו אלא באדם בטל:","\u0003צער כו' בסייף כו'. \u0004 שם:","\u0003ובמקום כו'. \u0004 מתני' וגמ' שם ליטול זה מזה כו':","\u0003 (ליקוט) כפועל בטל כו'. \u0004 וכ\"כ הרא\"ש שם וכמ\"ש בב\"מ ע\"ו ב' אינו דומה כו': (ע\"כ):","\u0003ועושין חשבון כו'. \u0004 כמש\"ש צ\"א א' וכמ\"ש בסי\"ח:","\u0003ודוקא כו'. \u0004 תוס' שם ד\"ה רואין כו' וכמש\"ש פ\"ז א' שבת דהוה מרקיד כו'. הרא\"ש וכן ראיה מפ\"ק דעירובין ועתוס' בב\"ק שם ד\"ה חרשו ולר\"י נראה כו':\n\u0003 (ליקוט) אם כו'. \u0004 כמש\"ש פ\"ו א' דהוה מרקיד כו' וערש\"י שם ד\"ה דבעי כו'. הרא\"ש (ע\"כ):","\u0003ודבר זה כו'. \u0004 כמ\"ש בסי\"ט אמר המזיק כו' שהרי אף אם א\"ל אסייך אנא היה שומע לו א\"ל משום דא\"ל דמית עלי כו' וכן אסיא דמגן כו' וזש\"ש עלו בו צמחים מחמת כו' ואיירי בבה\"ג וכמ\"ש בסי\"ט הרי שלא כו' ועסמ\"ע:","\u0003ועלו בו כו'. \u0004 בת\"ק בברייתא ולא כחכמים דמתני' דלא כוותייהו:","\u0003אינו דומה כו'. \u0004 רמב\"ם וטור ורש\"י במתני' כאן דלא כרש\"י בכתובות מ\"ם א':","\u0003וכן המתבייש כו'. \u0004 כ\"ה בגמ' פ\"ו א' ופ' כר' יהודה דהלכה כמותו נגד ר\"מ ור\"ש כמ\"ש בפ\"ד דעירובין ואע\"ג דמתני' אוקמוה כר\"ש היינו משום דרי\"א סומא כו' אבל לענין זה פשטא דמתני' יותר אתי כר\"י ולכן השמיט הרי\"ף פלוגתייהו וכפשטא דמתני' ודלא כרא\"ש שפ' כר\"ש ע\"ש:\n\u0003 (ליקוט) וכן כו'. \u0004 כר\"י אבל הרא\"ש פ' כר\"ש דאוקמי למתני' שם כוותיה וזה אינו מוכרח ועוד כ' דמתני' שם צ' א' כוותיה דאמר פרע ראש כו' אר\"ע כו' ומעשה כו' מכלל דת\"ק נמי כב\"ח שירדו כו' משער וזו ראיה גדולה (ע\"כ):","\u0003והמבזה כו'. \u0004 כמ\"ש בפ' הנזיקין וע' רמב\"ם פ\"ד מה' כלי המקדש:","\u0003או שהכהו כו'. \u0004 פ\"ה ב'.","\u0003אם אינו כו'. \u0004 כפר\"י שם ד\"ה חרשו כו':","\u0003ומחוייב כו'. \u0004 עתוס' שם ד\"ה נהי כו' וכ\"כ הרא\"ש והרשב\"א וכ' וז\"ש פ\"ו א' הב\"ע כגון שחרשו ואמר חייב בכולן והיינו בהני תלתא:\n\u0003 (ליקוט) ומחוייב כו'. \u0004 עתוס' שם ד\"ה נהי כו' ושם פ\"ו א' ד\"ה כגון כו' (ע\"כ):","\u0003אבל כו'. \u0004 כמש\"ו וכמ\"ש בס\"ח:","\u0003לפיכך כו'. \u0004 שם:","\u0003הזורק כו'. \u0004 ל\"ג א' ומאן דמתני לה אקמייתא כו' ופ' ברי\"ף כן וכשיטתו בכ\"מ:","\u0003שנא' כו'. \u0004 שם.","\u0003ואם הנחבל כו'. \u0004 שדין הנחבל כמו הנגזל כמ\"ש בפ' הנשבעין ואמרינן בנגזל שם ואימר לא משכנו כו':","\u0003וי\"א כו'. \u0004 ממש\"ש והתניא ר\"א כו' ועתוס' סד\"ה ביישו כו' ונראה דרי\"ף ורמב\"ם ל\"ג להו וכן נראה דהא בברייתא ראשונה תני ר\"א חרש וקטן כו' ועוד דלמה לא פשטוהו מזה הברייתא ובב\"ח דחק עצמו ואין דבריו נראין:\n\u0003 (ליקוט) בסנהדרין פ\"ה א' \u0004 ועתוס' שם ד\"ה והאמר כו' ובב\"ק שם ד\"ה ביישו כו' אך ק' דבמסקנא כו' וכ\"ד הרא\"ש שם (ע\"כ):\n\u0003 (ליקוט) ביישו כו'. \u0004 ורי\"ף השמיטו משום קושיא דרבא שם פ\"ד ח' ועתוס' שם ד\"ה זילו כו' (ע\"כ):","\u0003את החרש כו'. \u0004 שם:","\u0003או את הגר. \u0004 פ\"ח א' וליטעמיך כו':","\u0003או כו'. \u0004 מתני' שם וכת\"ק:","\u0003שכשמכלימין כו'. \u0004 טור וכנ\"ל סל\"ה:","\u0003ומ\"מ אינו כו'. \u0004 פ\"ו א' מאן תנא להא דת\"ר נתכוין כו' וכנ\"ל וכר\"י:","\u0003ויש לב\"ד כו'. \u0004 כנ\"ל סי' כז ס\"ב:","\u0003וי\"א כו'. \u0004 וכ\"כ בסי' א' ס\"ו עמש\"ש:","\u0003וי\"א דמכין כו'. \u0004 במרדכי שם כ' דמלקין אותו שהרי עבר על לאו גמור דלא תונו אותו וכמ\"ש בב\"מ ס\"פ הזהב וכ' ב\"י ותימהני דהא קי\"ל לאו שאין בו מעשה אין לוקין עליו חוץ מנשבע כו' ואפשר דמכות מרדות מדרבנן קאמר. ובלא\"ה אין מלקות עכשיו:","\u0003והמוציא ש\"ר כו' \u0004 כ\"ה ברא\"ש שם ועמ\"ש בסס\"א:","\u0003האומר לחבירו כו'. \u0004 כמ\"ש בפ\"ד דתענית כאלמנה לא כאלמנה כו' ובפד\"א כמעשה ער ואונן ולא כמעשה כו' ה\"נ י\"ל אתה מכחש כמו ממזר אבל לא ממזר ממש אף דאינו אומר בכף הדמיון מ\"מ ל\"ד קאמר דהא בספ\"ב דנדרים ויבואו בני לידי ממזרות ולאו ממזר גמור קאמר ע\"כ וכ\"ש בכה\"ג:","\u0003וי\"ח כו'. \u0004 ממ\"ש ברפ\"ב דיומא ודלמא כבן שנה כו' אחזי ליה סיוטא כו':","\u0003המדבר רע כו'. \u0004 עמ\"ש בא\"ח סי' תר\"ו ס\"ג:","\u0003ואם קרובים כו'. \u0004 גמ' סוף יומא וכמש\"ש ס\"ב:","\u0003הקורא לחבירו כו'. \u0004 כמ\"ש בפ\"ז דסנהדרין כמאן קרינן לרשיעא כו':","\u0003אבל אם לא כו'. \u0004 גדולה מזו אפילו אם אומר שהאמת אתו אם א\"י לברר חייב כמ\"ש בפ\"ק דקדושין באומר השבע כי שאין עבדי אתה:","\u0003 (ליקוט) תקע כו'. \u0004 כת\"ק ואע\"ג דר\"י נשיאה עבד כריה\"ג לא קי\"ל כוותיה אלא כהנך עובדי דרפ\"ד דבתראי נינהו (ע\"כ):\n\u0003 (ליקוט) תקע כו'. \u0004 כת\"ק ואע\"ג דרי\"נ עבד שם כריה\"ג סמכינן ארב יוסף ור\"ה ברפ\"ד דעבדו כת\"ק. הרא\"ש שם וש\"פ (ע\"כ):","\u0003וכזה הוא כו'. \u0004 ל\"ז א':","\u0003מ\"מ כו'. \u0004 כמ\"ש בסוף ב\"ק ולא ישנו מתנהג כו' וש\"מ:","\u0003כל אלו כו'. \u0004 ל\"ו ב':","\u0003 (ליקוט) שאין בו כסף כו'. \u0004 כמ\"ש ברפ\"ד שסלע הוא פלגא דזוזא (ע\"כ):","\u0003 (ליקוט) שכל מעה כו'. \u0004 כמ\"ש הרי\"ף ורא\"ש בריש קדושין ע\"ש ועי\"ד ר\"ס רצ\"ד וסי' ש\"ד (ע\"כ):","\u0003בד\"א כו'. \u0004 עתוס' כז ב' ד\"ה הרי כו':\n\u0003 (ליקוט) בד\"א כו'. \u0004 אף בג' הראשונים דבירושלמי והביאו הרא\"ש שם תני עלה דמתני תני רב לבעיטה כו' ומ' דאמכובד דומיא דמסני' ואף שחולק עם הגמ' שלנו בשיעור ואינו משער באצבעות הרגלים וביד משער בגודל ג' פרקים ראש הגודל שהוא שוה עם פרקים בשניים של האצבעות (ע\"כ):","\u0003י\"א שאלו כו'. \u0004 והגי' שלנו הוא ברי\"ף להיפך שהסכים לדברי החולקים וכדעת הרמב\"ם בסמ\"א והביא ראיה ממה שלא חייבוהו לחנן שם ל\"ז א' אלא פלגא דזוזא ואינו מוכרח דבסתמא אין בהכאה כזה ריפוי ושבת והרא\"ש הכריח בשם הרי\"ף משם להיפך כגי' הרי\"ף להיפך וג\"כ אינו מוכרח:\n\u0003 (ליקוט) י\"א כו'. \u0004 וכ\"כ רש\"י שם לו ב' ד\"ה נותן לו כו' (ע\"כ):\n\u0003 (ליקוט) י\"א כו'. \u0004 ערש\"י פ ד ב' ד\"ה ד' מאה כו' (ע\"כ):\n\u0003 (ליקוט) י\"א כו'. \u0004 גמ' שם צב א' וערש\"י שם ד\"ה כל אלו כו' (ע\"כ):"]}],["אֵינוֹ חַיָּב עַל הַבֹּשֶׁת עַד שֶׁיִּתְכַּוֵּן לְבַיְּשׁוֹ; וְהַמְבַיֵּשׁ אֶת חֲבֵרוֹ שֶׁלֹּא \u0010y0\u0011 בְּכַוָּנָה, פָּטוּר. \u0010y1\u0011 לְפִיכָךְ, יָשֵׁן שֶׁבִּיֵּשׁ, פָּטוּר. \u0005הַגָּה: וְכֵן מִי שֶׁקּוֹבֵל עַל חֲבֵרוֹ שֶׁמְּסָרוֹ אוֹ גָּנַב לוֹ וְכַיּוֹצֵא בָּזֶה, אַף עַל פִּי שֶׁלֹּא יָכוֹל לְבָרֵר עָלָיו, מִכָּל מָקוֹם פָּטוּר, \u0010y2\u0011 דַּהֲרֵי לֹא כִּוֵּן לְבַיְּשׁוֹ (מהרי\"ו סִימָן קס\"ח)\u0006.\nהַמִּתְכַּוֵּן לְבַיֵּשׁ אֶת הַקָּטָן וּבִיֵּשׁ אֶת הַגָּדוֹל, \u0010y3\u0011 נוֹתֵן לַגָּדוֹל דְּמֵי בָּשְׁתּוֹ שֶׁל קָטָן. נִתְכַּוֵּן לְבַיֵּשׁ אֶת הָעֶבֶד וּבִיֵּשׁ בֶּן חוֹרִין, נוֹתֵן לַבֶּן חוֹרִין דְּמֵי בָּשְׁתּוֹ שֶׁל עֶבֶד: \u0010y4\u0011\nיֵשׁ אוֹמְרִים דְּצַעַר רִפּוּי וְשֶׁבֶת \u0010y5\u0011 חַיָּב אֲפִלּוּ שֶׁלֹּא בְכַוָּנָה, וּבִלְבַד שֶׁלֹּא יְהֵא אָנוּס, אֶלָּא שׁוֹגֵג קָרוֹב לְמֵזִיד; אֲבָל בְּנֶזֶק \u0010y6\u0011 חַיָּב אֲפִלּוּ אָנוּס, \u0010y7\u0011 דְּאָדָם מוּעָד לְעוֹלָם, בֵּין שׁוֹגֵג בֵּין מֵזִיד, בֵּין עֵר בֵּין יָשֵׁן.\nבַּמֶּה דְּבָרִים אֲמוּרִים שֶׁיָּשֵׁן חַיָּב, בְּשֶׁיָּשְׁנוּ שְׁנֵיהֶם כְּאֶחָד וְנִתְהַפֵּךְ אֶחָד מֵהֶם עַל חֲבֵרוֹ וְהִזִּיקוֹ אוֹ קָרַע בְּגָדָיו. אֲבָל אִם הָיָה אֶחָד יָשֵׁן, וּבָא חֲבֵרוֹ וְשָׁכַב בְּצִדּוֹ, זֶה שֶׁבָּא בָּאַחֲרוֹנָה חַיָּב אִם הִזִּיק לָרִאשׁוֹן. וְאִם הָרִאשׁוֹן הִזִּיקוֹ, פָּטוּר. \u0005וְהוּא הַדִּין בְּכָל אֹנֶס גָּדוֹל כְּזֶה, פָּטוּר הַמַּזִּיק (ר\"י נל\"א ח\"ב)\u0006. וְכֵן אִם הִנִּיחַ כֵּלָיו בְּצַד הַיָּשֵׁן, וְנִתְהַפֵּךְ עֲלֵיהֶם וּשְׁבָרָם, פָּטוּר, שֶׁזֶּה שֶׁהִנִּיחָם בְּצִדּוֹ \u0010y8\u0011 פּוֹשֵׁעַ הוּא בַּמֶּה שֶׁהִנִּיחָם בְּצִדּוֹ.\nשְׁנַיִם שֶׁנִּתְאַבְּקוּ יַחַד, וְאֶחָד הִפִּיל חֲבֵרוֹ לָאָרֶץ, וְנָפַל \u0010y9\u0011 עָלָיו וְסִמָּא אֶת עֵינוֹ, פָּטוּר.\nבְּכָל מָקוֹם שֶׁחוֹבֵל בַּחֲבֵרוֹ בְּכַוָּנָה חַיָּב בְּה' דְּבָרִים, אֲפִלּוּ נִכְנַס חֲבֵרוֹ לִרְשׁוּתוֹ שֶׁלֹּא בִּרְשׁוּת, וְחִבֵּל בּוֹ וְהוֹצִיאוֹ, חַיָּב; דִּנְהִי שֶׁיֵּשׁ לוֹ רְשׁוּת לְהוֹצִיאוֹ, אֵין לוֹ רְשׁוּת לַחְבֹּל בּוֹ. אֲבָל אִם הוּא מְסָרֵב בּוֹ וְאֵינוֹ רוֹצֶה לָצֵאת, יֵשׁ אוֹמְרִים שֶׁיֵּשׁ לוֹ רְשׁוּת אֲפִלּוּ לַחְבֹּל בּוֹ כְּדֵי לְהוֹצִיאוֹ. \u0005הַגָּה: וְכֵן מִי שֶׁיֵּשׁ לוֹ מְשָׁרֵת, וְחוֹשֵׁשׁ שֶׁיִּגְנֹב לוֹ, יוּכַל לְהוֹצִיאוֹ קֹדֶם זְמַן הַשְּׂכִירוּת; \u0010y10\u0011 וְאִם מְסָרֵב, יוּכַל לְהַכּוֹתוֹ עַד שֶׁיֵּצֵא (מָרְדְּכַי פֶּרֶק הַמַּנִיחַ)\u0006.\nנִכְנַס לַחֲצַר חֲבֵרוֹ שֶׁלֹּא בִּרְשׁוּת, וְלֹא יָדַע בַּעַל הַבַּיִת שֶׁנִּכְנַס, \u0010y11\u0011 וְהִזִּיקוֹ בַּעַל הַבַּיִת שֶׁלֹּא בְּכַוָּנָה, פָּטוּר. וְאִם הֻזַּק בּוֹ בַּעַל הַבַּיִת, חַיָּב, כֵּיוָן שֶׁנִּכְנַס שֶׁלֹּא בִּרְשׁוּת. וְדַוְקָא בְּשֶׁלֹא יָדַע בּוֹ וְלֹא רָאָהוּ שֶׁנִּכְנָס, אֲבָל רָאָהוּ, פָּטוּר, דְּאִיהוּ דְּאַזִּיק \u0010y12\u0011 אַנַּפְשֵׁהּ.\nהָיוּ שְׁנֵיהֶם בִּרְשׁוּת אוֹ שְׁנֵיהֶם שֶׁלֹּא בִּרְשׁוּת, וְהֻזְּקוּ זֶה בְּזֶה, שְׁנֵיהֶם פְּטוּרִים. \u0005הִזִּיקוּ זֶה אֶת זֶה בְכַוָּנָה, שְׁנֵיהֶם חַיָּבִים (טוּר ס\"ט)\u0006. וְעַיֵּן לְעֵיל סִימָן שע\"ח \u0010y13\u0011\nהַמְבַקֵּעַ עֵצִים בִּרְשׁוּת הָרַבִּים, וּפָרַח עֵץ מֵהֶם וְהִזִּיק בִּרְשׁוּת הַיָּחִיד, אוֹ שֶׁבָּקַע בִּרְשׁוּת הַיָּחִיד וְהִזִּיק בִּרְשׁוּת הַיָּחִיד אַחֵר, \u0010y14\u0011 אוֹ שֶׁנִּכְנָס לַחֲנוּתוֹ שֶׁל נַגָּר, בֵּין בִּרְשׁוּת בֵּין שֶׁלֹּא בִּרְשׁוּת, וְנִתְּזָה בְּקַעַת וְטָפְחָה לוֹ עַל פָּנָיו, חַיָּב בְּד' דְּבָרִים וּפָטוּר מֵהַבֹּשֶׁת.\nהָיְתָה לוֹ אֶבֶן מֻנַּחַת בְּחֵיקוֹ, בֵּין שֶׁלֹּא הִכִּיר בָּהּ מֵעוֹלָם בֵּין \u0010y15\u0011 שֶׁהִכִּיר בָּהּ וּשְׁכָחָהּ, וְעָמַד וְנָפְלָה וְהִזִּיקָה, וְכֵן אִם נִתְכַּוֵּן לִזְרֹק שְׁנַיִם \u0010y16\u0011 וְזָרַק אַרְבָּעָה וְהִזִּיק, אוֹ שֶׁהִזִּיק כְּשֶׁהוּא יָשֵׁן, חַיָּב בְּנֶזֶק וּפָטוּר מִד' דְּבָרִים.\nמִי שֶׁנָּפַל מִן הַגַּג בְּרוּחַ מְצוּיָה וְהִזִּיק, \u0010y17\u0011 חַיָּב בְּד' דְּבָרִים וּפָטוּר מֵהַבֹּשֶׁת. נָפַל בְּרוּחַ שֶׁאֵינָהּ מְצוּיָה, חַיָּב בְּנֶזֶק בִּלְבַד וּפָטוּר מִד' דְּבָרִים \u0005(וְע\"ל סִימָן תי\"ח סי\"ג)\u0006. \u0010y18\u0011 וְאִם נִתְהַפֵּךְ, חַיָּב בַּכֹּל, אַף בְּבֹשֶׁת; שֶׁכָּל הַמִּתְכַּוֵּן לְהַזִּיק, אַף עַל פִּי שֶׁלֹּא נִתְכַּוֵּן לְבַיֵּשׁ, חַיָּב בְּבֹשֶׁת.\nהַמַּזִּיק לְאִשְׁתּוֹ בְתַשְׁמִישׁ הַמִּטָּה, \u0010y19\u0011 חַיָּב בִּנְזָקֶיהָ. הָאוֹמֵר \u0010y20\u0011 לַחֲבֵרוֹ: קְטַע אֶת יָדִי, אוֹ: סַמֵּא אֶת עֵינִי עַל מְנַת שֶׁאַתָּה פָטוּר, הֲרֵי זֶה חַיָּב בַּחֲמִשָּׁה דְבָרִים, שֶׁהַדָּבָר יָדוּעַ שֶׁאֵין אָדָם רוֹצֶה בְכָךְ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאִם אָמַר לוֹ בְּפֵרוּשׁ: עַל מְנַת לִפְטֹר, פָּטוּר; אֶלָּא שֶׁאִם לֹא אָמַר לוֹ בְּפֵרוּשׁ, רַק דְּבָרִים שֶׁמַּשְׁמָעָן כָּךְ, אָנוּ דָנִין דְּבָרָיו שֶׁלֹּא פְטָרוֹ, \u0010y21\u0011 כְּגוֹן שֶׁאָמַר לוֹ: קְטַע יָדִי, אוֹ: סַמֵּא עֵינִי, וְאָמַר לוֹ הַמַּזִּיק: עַל מְנַת לִפְטֹר, וְאָמַר לוֹ הַנִּזָּק: הֵן, אָנוּ דָנִין שֶׁבִּתְמִיהָה קָאָמַר הֵן, וְחַיָּב הַמַּזִּיק (טוּר סי\"א בְּשֵׁם הָרֹא\"שׁ)\u0006. \u0010c0\u0011\nשְׁנַיִם שֶׁחָבְלוּ זֶה בְּזֶה, אִם חָבַל הָאֶחָד בַּחֲבֵרוֹ יוֹתֵר מִמַּה שֶׁחָבַל בּוֹ הוּא, \u0010y22\u0011 מְשַׁלֵּם לוֹ בַּמּוֹתָר נֶזֶק שָׁלֵם. וְדַוְקָא שֶׁהִתְחִילוּ שְׁנֵיהֶם כְּאֶחָד, אוֹ לְאַחַר שֶׁחָבַל \u0010y23\u0011 בַּחֲבֵרוֹ חָזַר גַּם הוּא מִיָּד וְחָבַל בּוֹ; אֲבָל אִם הִתְחִיל הָאֶחָד, הַשֵּׁנִי פָטוּר, שֶׁיֵּשׁ לוֹ רְשׁוּת לַשֵּׁנִי לַחְבֹּל בּוֹ \u0010y24\u0011 כְּדֵי לְהַצִּיל עַצְמוֹ. \u0010y25\u0011 \u0010c1\u0011 \u0005וְכֵן הוּא לְעִנְיַן גִּדּוּפִים וּבִיּוּשִׁים, הַמַּתְחִיל פּוֹרֵעַ הַקְּנָס (הַגָּהוֹת מָרְדְּכַי דְקִדּוּשִׁין)\u0006. רְאוּבֵן שֶׁהִכָּה לְשִׁמְעוֹן, וְחָזַר שִׁמְעוֹן וּבָא לְהַכּוֹתוֹ לִרְאוּבֵן, \u0010y26\u0011 וּבָאתָה אִשְׁתּוֹ שֶׁל רְאוּבֵן וְהֶחֱזִיקָה בְּשִׁמְעוֹן, וְהוּא נִתֵּק יָדָיו וְהִכָּה אוֹתָהּ, פָּטוּר \u0005(מהרי\"ו סִימָן כ\"ח)\u0006. וְע\"ל סוֹף סִימָן תכ\"ד אִישׁ וְאִשָּׁה שֶׁחָבְלוּ זֶה בְּזֶה. וּמִיהוּ צָרִיךְ אֹמֶד, אִם הָיָה יָכוֹל לְהַצִּיל עַצְמוֹ בְּחַבָּלָה מוּעֶטֶת וְחָבַל בּוֹ הַרְבֵּה, חַיָּב. \u0005וְדַוְקָא לְעִנְיַן חַבָּלָה שֶׁמְּשַׁלֵם לוֹ ד' דְּבָרִים, דְּהָוֵי כְּאָדָם הַמַּזִּיק בְּשׁוֹגֵג; אֲבָל פָּטוּר עַל הַבֹּשֶׁת, דְּהָא לֹא כִּוֵּן לְבַיֵּשׁ. וְלָכֵן הַמַּכֶּה חֲבֵרוֹ, וַחֲבֵירוֹ קְרָאוֹ מַמְזֵר, פָּטוּר, שֶׁנֶּאֱמַר: וְהָיָה כִּי יֵחַם לְבָבוֹ וְגוֹ' (דְּבָרִים יט, ו)\u0006. וְכֵן אִם אֶחָד קָרָא לַחֲבֵרוֹ גַּנָּב, וְהוּא אוֹמֵר לוֹ: \u0010c2\u0011 אַתָּה מְכַזֵּב כְּמַמְזֵר, אוֹ קְרָאוֹ מַמְזֵר, פָּטוּר מֵהַאי טַעֲמָא \u0005(מהרי\"ו סִימָן כ\"ח וְסִימָן ס')\u0006. וְכֵן הַדִּין בְּאָדָם הָרוֹאֶה אֶחָד מִיִּשְׂרָאֵל מַכֶּה חֲבֵרוֹ, וְאֵינוֹ יָכוֹל לְהַצִּילוֹ אִם לֹא שֶׁיַּכֶּה הַמַּכֶּה, יָכוֹל לְהַכּוֹתוֹ, \u0010y27\u0011 כְּדֵי לְאַפְרוּשֵׁי מֵאִסוּרָא. \u0005הַגָּה: וְכֵן מִי שֶׁהוּא תַּחַת רְשׁוּתוֹ, וְרוֹאֶה בּוֹ שֶׁהוּא עוֹשֶׂה דְּבַר עֲבֵרָה, רַשַּׁאי לְהַכּוֹתוֹ וּלְיַסְּרוֹ כְּדֵי לְהַפְרִישׁוֹ מֵאִסּוּר, וְאֵין צָרִיךְ לַהֲבִיאוֹ לְבֵית דִּין (ת\"ה סִימָן רי\"ח)\u0006.\nשְׁנַיִם שֶׁחָבְלוּ בְּאֶחָד כְּאֶחָד, שְׁנֵיהֶם חַיָּבִים, וּמְשַׁלְּשִׁים בֵּינֵיהֶם. הָיָה אֶחָד מִתְכַּוֵּן וְהַשֵּׁנִי לֹא כִּוֵּן, הַשֵּׁנִי פָּטוּר מִבֹּשֶׁת:",["\u0003עד שיכוון לביישו כו'. \u0004 כבר נתבאר זה בסי' ת\"ך סל\"ו דין ישן שבייש פטור ודהוא מדכתיב והחזיקה במבושיו דמיניה למדין דין בשת ובעינן דומה לו שמתכוין לכך:","\u0003לפיכך ישן שבייש פטור \u0004 כ\"כ ג\"כ בטור והוא פשיטא ממ\"ש כבר דבעינן כוונה ובפרישה כתבתי דה\"ק ומה\"ט תנינא ישן שבייש פטור:","\u0003דהרי לא כוון לביישו. \u0004 אלא לגבות ממנו הזיקו:","\u0003נותן לגדול דמי בשתו של קטן. \u0004 בסי' ת\"ך סל\"ז נתבאר דבקטן אין חייבין על בושתו אלא בתנאי שכשמכלימין אותו הוא נכלם ושם ג\"כ כתב המחבר דמ\"מ אין דומה המבייש הקטן להמבייש הגדול וזה שכ' כאן שאינו נותן לו אלא דמי בשת של קטן שהרי לא נתכוון אלא לבשת כזה ולבושת היתרה לא כוון ובשת שלא בכוונה אין מחייבין עליו:","\u0003יש אומרי' דצער כו'. \u0004 דין זה כתבו הטור וגם שאר פוסקים בפשיטות בלי פלוגתא ומה שסיים וכתב ז\"ל אבל בנזק חייב אפי' אונס כו' בסמוך כ' הטור והמחבר בסעיף י\"א דאפי' נפל מהגג ברוח שאינה מצויה חייב בנזק וע\"ל ר\"ס שע\"ח מ\"ש המחבר בשני סעיפים תכופים זה לזה סא\"ב ושם כתבתי בספר מאירת עינים מוכח מדברי הטור והמחבר שמחלקים בין נפל על גבי אדם והזיקו דחייב בנזקו אפילו בנפל ברוח שאינו מצויה. ובין נפל על הכלים דאינו חייב בנזק כ\"א ברוח מצויה ובסי' זה מנפל ע\"ג אדם איירי מ\"ה סתמו הטור והמחבר בסעיף י\"א וכתבו דאפי' ברוח שאינו מצוי' חייב ע\"ש ודו\"ק:","\u0003חייב אפי' שלא בכוונה \u0004 נלמד מדכתיב כי יריבון כו' ושם קרוב למזיד הוא וריפוי ושבת כתובין שם וה\"ה לצער:","\u0003אפי' אנוס \u0004 ילפינן לה מיתורא דקרא דכתיב פצע תחת פצע והל\"ל פצע בפצע וכל מה דמצינן לפטור שוגג פטרינן לכן לא אוקמינן האי יתורא דקרא כ\"א אנזק:","\u0003דאדם מועד לעולם \u0004 מ\"מ לכ\"ע אאונס גדול אינו חייב וכמ\"ש הטו' והמחב' ומור\"ם בסמוך בס\"ד וגם זה מבוא' בסי' שע\"ח ובשאר מקומות.","\u0003פושע הוא. \u0004 בכלל פושע הוא דקאמ' הוא נמי דאם הישן הוזק בהכלים שהונחו בצדו שחייב בעל הכלים בנזקי דהישן וק\"ל:","\u0003וסימא את עינו פטור טעם הדבר כיון דהתאבקו שניהם ברצון וכל אחד דעתו היה להפיל חבירו וכל אחד ידע שא\"א לצמצם שיפילו דוקא באופן שלא יהיה בו היזק ה\"ל כאלו נתייאשו ומחלו אהדדי שאף אם יארע לא' היזק יהיה מה שיהיה כיון שלא נתכוון חבירו להזיקו אלא שקרה לו דרך נפילתו שיהיה פטור דומה למ\"ש בשנים שרצין בר\"ה והזיקו זא\"ז דרך ריצתן דפטו' המזיק משום דכל הרץ בר\"ה יודע שגם לאחרים יש רשות לרוץ בר\"ה וכאשר יפגשו שניהם הרצין זה נגד זה דרכן להזיק זא\"ז. ואע\"ג דאמרינן אדם מועד לעולם ע\"כ לאו בכל ענין אמרוהו דהרי בהזיקת אונס גמור פטור וכאשר כתבתי טעם זה כן הוא דברי הרא\"ש בתשובותיו הביאו הטו' בסי' זה וכמ\"ש בפרישה ועפ\"ר בסי' שע\"ח ס\"ח שם כתבתי דבשניהן רצין לאו משום מחילה לחוד הוא אלא משום דשניהן עבדו מעשה בהזיקתן ומה\"ט בלא ר\"ה נמי אלא כל שרצין שנים זה כנגד זה וכ\"כ הטור בשם הרמ\"ה שם בהדיא וע\"ש בדרישה דכתבתי שנראה דהטו' בשם רש\"י חולק על הרמ\"ה הנ\"ל ושי\"ל דאין חולקין ועמ\"ש כאן בפרישה מיד מזה:\u0004","\u0003ואם מסרב יכול להכותו \u0004 בגמרא אמרו כן בעבד עברי ולמדו כן מדכתיב לא תקחו כופר לשוב וגו' ודרשינן לא תקחו שופר לשב פי' מי שדינו להיות שב אל משפחתו:","\u0003והזיקו בעל הבית כו' \u0004 דלא מסיק בעל הבית אדעתיה שיכנס אדם לרשותו שלא מדעתו ועיין בטור שכתב שם עוד בבא א' ז\"ל ואם זה שנכנס ניזק מאליו בע\"ה פטור והב\"י כתב דט\"ס הוא וגם כאן השמיטו המחבר ובפרישה כתבתי דטעמא דב\"י הוא דס\"ל דנלמד במכ\"ש מהבבא הראשונה דאפי' הזיקו הב\"ה פטור וכ\"ש אם הוזק מאיליו בב\"ה מיירי ושם כתבתי דנ\"ל דא\"צ למוחקו דאלו ברישא אינו פטור הב\"ה אלא כשלא ידע מזה שנכנס ומציעתא זו דהוזק בו מאיליו מיירי אפי' ידע ממנו שנכנס אפ\"ה פטור כיון דהוזק מאיליו וק\"ל:","\u0003היו שניהם ברשות כו'. \u0004 כבר נתבא' טעמו דכל ששניהן שווין הן היה לזה לשמו' כמו זה וכיון שהזיקו שלא בכוונה זא\"ז היזק כזה מחלו מתחל' אהדדי:","\u0003המבקע עצים בר\"ה כו'. \u0004 לא זו אף זו קאמר ל\"מ אם הבקיעה היתה במקום דשכיחי רבים דהיה לו ליזהר טפי דחייב אלא אפי' הבקיעה היתה ברה\"י וגם ההיזק נעשה במקום דלא שכיחי בה רבים אפי' הכי חייב (ובטו' כ' עוד בבא דאם הבקיעה ברה\"י והזיק בר\"ה חייב והמחב' קיצר דנלמד במכ\"ש מהסיפא) ל\"מ בנזק אלא אפי' בשאר ג' דברים משום דקרוב לפשיעה הוא זה זולת הבושת דפטר כיון דלא כוון לזה:","\u0003או שנכנס בחנותו של נגר. \u0004 לשון הטור וריב\"א פי' אפי' לא ראוהו נכנס חייב דכל אומן שדרך בני אדם לכנס לביתו בשביל אומנתו יש ליזהר יותר עכ\"ל ור\"ל אף שזה לא נכנס כדי לקנות ממנו מ\"מ מוזהר ועומד הוא על כל הנכנסים כיון שדרך לכנוס וליקח ממנו:","\u0003שהכיר בה ושכחה \u0004 ג\"ז דומה לאונס הוא:","\u0003וזרק ארבע כו'. \u0004 בטור כ' עוד ז\"ל או שנתכוון לזרוק ד' וזרק שמונה כו' ועפ\"ר שכתבתי טעם למה כ' זה עיין בטור שכ' כאן עוד דין הזורק אבן ואח\"כ הוציא ראשו וקבלה פטור מד' דברים וחייב בנזק כו' והמחב' כתבו בסי' ת\"ך ס\"ל וכ' שם דפטור מכולם ולאפוקי מהטור שכ' שחייב בנזק ע\"ש:","\u0003חייב בד' דברים \u0004 ז\"ל הטור דשוגג קרוב למזיד הוא דלא היה לו לעלות לגג שאין לו מעקה כיון שיכול ליפול ברוח מצויה:","\u0003ואם נתהפך \u0004 ל' הטור ואם נתהפך דרך נפילתו כדי שיפול על האדם להנאתו כדי שלא יחבט בהקרקע:","\u0003חייב בנזקיה \u0004 ל' הטור חייב בד' דברים וגם המחב' דכ' בנזקיה ר\"ל כל נזקי' זולת הבושת דלאו בכלל נזקיה הוא דהא לא כוון לביישה אבל בשאר דברים אע\"ג דיש לו רשות לשמש עמה מ\"מ ה\"ל לעיוני דלא יזיק ודין המעות דנותן בהד' דברים יתבאר בסי' תכ\"ג מה עושה בהן ואיך דינן גם בא\"ע סימן פ\"ג:","\u0003קטע את ידי כו'. \u0004 עד\"ר שם כתבתי דלסברא זו דס\"ל דאפי' א\"ל מתחלה בפי' מ\"מ לפטור אפ\"ה חייב בהני דוקא קאמר דחייב כיון דהן ראשי איברים ידועים ואין אדם רוצה בחסרון איברים הללו וסבור שחבירו לא יקטעו ויסמאוהו אע\"ג דא\"ל ע\"מ לפטו' אבל אם א\"ל הכני פצעני ע\"מ לפטור והוא פצע בו בלא חסרון ראשי איברים הוא פטו' כמו בא\"ל שבור את כדי ושאר כלים לעיל וכמ\"ש הטור והמחב' ר\"ס ש\"פ ע\"ש:","\u0003כגון שא\"ל קטע את ידי כו' \u0004 עד שבתמיה קאמר ובהאי דלא א\"ל בפי' ע\"מ לפטור אלא נוכל לומר דבתמיה קאמר אפי' בלא ראשי איברים נמי אמרי' דבתמיה קאמר וחייב ולא נקט קטע ידי כו' אלא ללמדינו דאם אמר בפי' ע\"מ לפטור דפטור אפי' בהני ודוקא בהיזק ממון הוא דפטרינן ליה אף בל' המתפרש דבתמיה קאמר וכמ\"ש הטור והמחבר לעיל ר\"ס ש\"פ ע\"ש ולא בצער דגופו ודלא כע\"ש דכ' דגם י\"א הללו לא חייבוהו בסתם אלא בראשי איברים דז\"א ועיין בפרישה ודרישה כאן ולעיל בסי' ש\"פ:","\u0003משלם במות' נזק שלם \u0004 ע\"ל בסי' ת\"ב מ\"ש בהיזק שור בשור בתשלומי במותר נזק שלם ומינה יש ללמד לאדם באדם:","\u0003חזר גם הוא מיד גם בטור כ' כאן כהאי לישנא ז\"ל או לאחר שחבל זה בחבירו חזר גם הוא מיד וחבל בו אבל כו' ובפרישה כתבתי דלכאורה נראה דהאי מיד ט\"ס הוא דאם השני חזר וחבלו מיד בעודו בחימום הוא פטור וגם לעיל בס\"ס ת\"ב בשני שוורים לא כ' הטור ומור\"ם לתיבת מיד אלא ז\"ל או לאחר שנפרדו זה מזה חזר השני כו' ושניהן נשנו בפ' המניח (בבא קמא דף ל\"ג) במשנה אחת גם באשר\"י שם (דף קל\"ב פ\"א) ולא כ' תיבת מיד אלא ז\"ל או לאחר זמן זה שחבל זה כו' ור\"ל לאחר זמן שכבר נפרדו זה מזה ועבר חימומן ודוחק לו' שגרס' הטור היה באשר\"י כאשר כ' כאן ומחלק בין שוורים לאדם שאדם הוא מועד לעולם וס\"ל דבשני בני אדם אף דהתחיל הא' מ\"מ אם פסק אותו א' אף שעדיין השני המוכה בחמימותו אם חזר וחבלו גם הוא להראשון דחייב דה\"ל להעמידו בדין על הכאתו משא\"כ בשני שוורי' דאין שייך זה מ\"ה כתבו שם דתלה באחר שנפרדו וכאן בשני בני אדם כתבו או לאחר שחבל זה בחבירו פי' ופסק מלהכותו אם חזר גם הוא מיד פי' אפי' בעודו בחמימתו וחבל בו חייב גם הוא ומ\"ש אם התחיל הא' השני פטור ר\"ל הראשון התחיל במריבה וירא השני שיחבל בו וכדי להציל נפשו מההכא' חבל בהראשון או שכבר חבל בו הראשון וירא שיחבול בו עוד וקידם וחבל בהראשון כדי שלא יחבלוהו עוד פטור דאין הל' סובל פי' זה וגם ק' מנ\"ל להרא\"ש והטור לחלק בזה מאחר דהמשנה השוויהן יחד גם בקיצור פסקי הרא\"ש כ' שניהם בל' אחד לכן נראה דט\"ס הוא וה\"ג בדברי הטור והמחבר או לאחר זמן שחבל זה בחבירו חזר גם הוא וחבל בו אז החיוב על שניהן ומשלם במותר נזק שלם אבל אם התחיל הא' וחזר השני וחבל בו מיד השני פטור והיינו כלישנא דהרא\"ש דפ' המניח הנ\"ל ודו\"ק והשתא א\"ש הא דמסיק מור\"ם וכ' אדברי המחבר ז\"ל וכן הוא לענין גדופים כו' עד וכן אם קרא לחבירו גנב והשני קראו ממזר דפטור ולא מחייבינן להשני משום דהיה לו לתובעו בדין ודוק ועמ\"ש מור\"ם שם בסי' ת\"ב תמיה על המחבר ששם סתם ולא חילק כלל וכאן חילק וכתב דאם האחד התחיל השני פטור כתבתי שם ישוב נכון ולק\"מ ע\"ש:\u0004","\u0003כדי להציל עצמו \u0004 דאפי' אחרים חייבים לחבול בהחובל כדי להציל חביריהן כמ\"ש הטור והמחבר בסי' תכ\"ה כ\"ש הוא עצמו:","\u0003וכן הוא לענין גידופין כו'. \u0004 וכתב מהר\"מ מריזבור\"ק ראובן טען על שמעון שקראו ממזר ושמעון אומר שמתחלה לחש לו באזנו שהוא ממזר לכן נתרגז וא\"ל כן אומדנא דמוכח הוא כיון שקראו פתאום ממזר ודאי האמת אתו עכ\"ל וא\"צ לישבע ע\"ז כמ\"ש לעיל סי' ת\"ך סל\"ה עכ\"ל ד\"מ י\"ט:","\u0003ובאתה אשתו כו'. \u0004 וכתב בנימוקי מהר\"מ דדין אשה לענין בזיון כדין איש ואם אין האיש רוצה שתתבזה אשתו צריך לפדותה בממון כפי אשר ישיתו עליו הב\"ד וע\"ל סי' תכ\"ד ס\"י מזה:","\u0003כדי לאפרושי מאיסורא. \u0004 בטור כתב עוד בבא א' לפני בבא זו וכן הדין באדם הרואה את חבירו שמכה לאביו או בנו או אחיו והרואה הכה המכה כדי להציל את קרובו שפטור עכ\"ל ודקדקתי בפרישה מדלא כייל אחיו ובנו עם סיפא דרואה מכה לא' מישראל גם כתב בכל א' טעם בפני עצמו דבמציעתא כתב כדי להציל את קרובו ובסיפא כ' כדי לאפרושי מאיסורא וכתבתי דאיכא בינייהו נ\"מ לדינא והוא דאם זה הבא להציל ולהכות המכה אינו בר הכי דרגיל לאפרושי מאיסורא דכמה פעמים רואה שמכה א' לחבירו ואינו חושש לאפרושי המכה מאיסורא אז אמרינן דאסור להכות לזה המכה דודאי מכח שנאה בא להכותו ולא בא להפרישו מהאיסור מה שא\"כ ברואה מכה אביו ובנו ואחיו דמותר להציל קרובו בהכאה אף שאין מדרכו להפריש אחרים והמחבר דלא חילק בינייהו אפשר משום דלא הרגיש בזה דבאמת טעם הגון הוא לחלק בינייהו ודוק"],["\u0003 שנים שחבלו זה בזה כו'. \u0004 עיין בתשו' מבי\"ט ח\"ב סימן שי\"א:","\u0003 וכן הוא הדין לענין גדופים וביושים כו'. \u0004 עיין בתשובת ר\"א ן' חיים סי' נ' וסי' צ\"ג וסי' קי\"א:","\u0003 אתה מכזב כממזר כו'. \u0004 עיין בנימוקי מהר\"מ מריזבורק וביש\"ש פ\"ח דב\"ק סימן מ\"ב:"],"אֵינוֹ חַיָּב עַל הַבֹּשֶׁת עַד שֶׁיִּתְכַּוֵּן לְבַיְּשׁוֹ; וְהַמְבַיֵּשׁ אֶת חֲבֵרוֹ שֶׁלֹּא \u0010y0\u0011 \u0010g0\u0011 \u0010r0\u0011 בְּכַוָּנָה, פָּטוּר. \u0010y1\u0011 לְפִיכָךְ, \u0010g1\u0011 יָשֵׁן שֶׁבִּיֵּשׁ, פָּטוּר. \u0005הַגָּה: \u0010r1\u0011 וְכֵן מִי שֶׁקּוֹבֵל עַל חֲבֵרוֹ שֶׁמְּסָרוֹ אוֹ גָּנַב לוֹ וְכַיּוֹצֵא בָּזֶה, אַף עַל פִּי שֶׁלֹּא יָכוֹל \u0010g2\u0011 לְבָרֵר עָלָיו, מִכָּל מָקוֹם פָּטוּר, \u0010y2\u0011 דַּהֲרֵי לֹא כִּוֵּן לְבַיְּשׁוֹ (מהרי\"ו סִימָן קס\"ח)\u0006. \u0010g3\u0011\nהַמִּתְכַּוֵּן לְבַיֵּשׁ אֶת הַקָּטָן וּבִיֵּשׁ אֶת הַגָּדוֹל, \u0010y3\u0011 נוֹתֵן לַגָּדוֹל דְּמֵי בָּשְׁתּוֹ שֶׁל \u0010t0\u0011 קָטָן. \u0010g4\u0011 נִתְכַּוֵּן לְבַיֵּשׁ אֶת הָעֶבֶד וּבִיֵּשׁ בֶּן חוֹרִין, נוֹתֵן לַבֶּן חוֹרִין דְּמֵי בָּשְׁתּוֹ שֶׁל עֶבֶד: \u0010y4\u0011 \u0010g5\u0011 \u0010r2\u0011\nיֵשׁ אוֹמְרִים דְּצַעַר רִפּוּי וְשֶׁבֶת \u0010y5\u0011 חַיָּב אֲפִלּוּ שֶׁלֹּא \u0010r3\u0011 בְכַוָּנָה, וּבִלְבַד שֶׁלֹּא יְהֵא אָנוּס, אֶלָּא שׁוֹגֵג קָרוֹב לְמֵזִיד; \u0010r4\u0011 אֲבָל בְּנֶזֶק \u0010y6\u0011 חַיָּב אֲפִלּוּ אָנוּס, \u0010y7\u0011 \u0010r5\u0011 דְּאָדָם מוּעָד לְעוֹלָם, בֵּין שׁוֹגֵג בֵּין מֵזִיד, בֵּין עֵר בֵּין יָשֵׁן. \u0010g6\u0011 \u0010r6\u0011\nבַּמֶּה דְּבָרִים אֲמוּרִים שֶׁיָּשֵׁן חַיָּב, בְּשֶׁיָּשְׁנוּ שְׁנֵיהֶם כְּאֶחָד וְנִתְהַפֵּךְ אֶחָד מֵהֶם עַל חֲבֵרוֹ וְהִזִּיקוֹ אוֹ קָרַע בְּגָדָיו. אֲבָל אִם הָיָה אֶחָד יָשֵׁן, וּבָא חֲבֵרוֹ וְשָׁכַב בְּצִדּוֹ, זֶה שֶׁבָּא בָּאַחֲרוֹנָה חַיָּב אִם הִזִּיק לָרִאשׁוֹן. וְאִם הָרִאשׁוֹן הִזִּיקוֹ, פָּטוּר. \u0010r7\u0011 \u0005וְהוּא הַדִּין בְּכָל אֹנֶס גָּדוֹל כְּזֶה, פָּטוּר הַמַּזִּיק (ר\"י נל\"א ח\"ב)\u0006. \u0010g7\u0011 וְכֵן אִם הִנִּיחַ כֵּלָיו בְּצַד הַיָּשֵׁן, וְנִתְהַפֵּךְ עֲלֵיהֶם וּשְׁבָרָם, פָּטוּר, שֶׁזֶּה שֶׁהִנִּיחָם בְּצִדּוֹ \u0010y8\u0011 \u0010t1\u0011 פּוֹשֵׁעַ הוּא בַּמֶּה שֶׁהִנִּיחָם בְּצִדּוֹ. \u0010g8\u0011 \u0010r8\u0011\nשְׁנַיִם שֶׁנִּתְאַבְּקוּ יַחַד, וְאֶחָד הִפִּיל חֲבֵרוֹ לָאָרֶץ, וְנָפַל \u0010y9\u0011 עָלָיו וְסִמָּא אֶת עֵינוֹ, פָּטוּר.\nבְּכָל מָקוֹם שֶׁחוֹבֵל בַּחֲבֵרוֹ בְּכַוָּנָה חַיָּב בְּה' דְּבָרִים, \u0010g9\u0011 אֲפִלּוּ נִכְנַס חֲבֵרוֹ לִרְשׁוּתוֹ שֶׁלֹּא בִּרְשׁוּת, וְחִבֵּל בּוֹ וְהוֹצִיאוֹ, חַיָּב; דִּנְהִי שֶׁיֵּשׁ לוֹ רְשׁוּת לְהוֹצִיאוֹ, אֵין לוֹ רְשׁוּת לַחְבֹּל בּוֹ. \u0010r9\u0011 אֲבָל אִם הוּא מְסָרֵב בּוֹ וְאֵינוֹ רוֹצֶה לָצֵאת, \u0010g10\u0011 יֵשׁ אוֹמְרִים שֶׁיֵּשׁ לוֹ רְשׁוּת אֲפִלּוּ לַחְבֹּל בּוֹ כְּדֵי לְהוֹצִיאוֹ. \u0005הַגָּה: \u0010r10\u0011 וְכֵן מִי שֶׁיֵּשׁ לוֹ מְשָׁרֵת, \u0010t2\u0011 וְחוֹשֵׁשׁ שֶׁיִּגְנֹב לוֹ, יוּכַל לְהוֹצִיאוֹ קֹדֶם זְמַן הַשְּׂכִירוּת; \u0010y10\u0011 וְאִם מְסָרֵב, יוּכַל לְהַכּוֹתוֹ עַד שֶׁיֵּצֵא (מָרְדְּכַי \u0010g11\u0011 פֶּרֶק הַמַּנִיחַ)\u0006. \u0010g12\u0011 \u0010r11\u0011\nנִכְנַס לַחֲצַר חֲבֵרוֹ שֶׁלֹּא בִּרְשׁוּת, וְלֹא יָדַע בַּעַל הַבַּיִת שֶׁנִּכְנַס, \u0010y11\u0011 וְהִזִּיקוֹ בַּעַל הַבַּיִת שֶׁלֹּא בְּכַוָּנָה, פָּטוּר. וְאִם הֻזַּק בּוֹ בַּעַל הַבַּיִת, חַיָּב, כֵּיוָן שֶׁנִּכְנַס שֶׁלֹּא בִּרְשׁוּת. \u0010g13\u0011 וְדַוְקָא בְּשֶׁלֹא יָדַע בּוֹ וְלֹא רָאָהוּ שֶׁנִּכְנָס, אֲבָל רָאָהוּ, פָּטוּר, דְּאִיהוּ דְּאַזִּיק \u0010y12\u0011 \u0010g14\u0011 אַנַּפְשֵׁהּ.\nהָיוּ שְׁנֵיהֶם בִּרְשׁוּת אוֹ שְׁנֵיהֶם שֶׁלֹּא בִּרְשׁוּת, וְהֻזְּקוּ זֶה בְּזֶה, שְׁנֵיהֶם פְּטוּרִים. \u0005הִזִּיקוּ זֶה אֶת זֶה בְכַוָּנָה, שְׁנֵיהֶם חַיָּבִים (טוּר ס\"ט)\u0006. וְעַיֵּן לְעֵיל סִימָן שע\"ח \u0010y13\u0011 \u0010g15\u0011\nהַמְבַקֵּעַ עֵצִים \u0010t3\u0011 בִּרְשׁוּת הָרַבִּים, וּפָרַח עֵץ מֵהֶם וְהִזִּיק בִּרְשׁוּת הַיָּחִיד, אוֹ שֶׁבָּקַע בִּרְשׁוּת הַיָּחִיד וְהִזִּיק בִּרְשׁוּת הַיָּחִיד אַחֵר, \u0010y14\u0011 אוֹ \u0010g16\u0011 שֶׁנִּכְנָס לַחֲנוּתוֹ שֶׁל נַגָּר, \u0010r12\u0011 בֵּין בִּרְשׁוּת \u0010g17\u0011 בֵּין שֶׁלֹּא בִּרְשׁוּת, וְנִתְּזָה בְּקַעַת וְטָפְחָה לוֹ עַל פָּנָיו, חַיָּב בְּד' דְּבָרִים \u0010g18\u0011 וּפָטוּר \u0010g19\u0011 מֵהַבֹּשֶׁת.\nהָיְתָה לוֹ אֶבֶן מֻנַּחַת בְּחֵיקוֹ, בֵּין שֶׁלֹּא הִכִּיר בָּהּ מֵעוֹלָם בֵּין \u0010y15\u0011 שֶׁהִכִּיר בָּהּ וּשְׁכָחָהּ, וְעָמַד וְנָפְלָה וְהִזִּיקָה, \u0010g20\u0011 וְכֵן אִם נִתְכַּוֵּן לִזְרֹק שְׁנַיִם \u0010y16\u0011 וְזָרַק אַרְבָּעָה וְהִזִּיק, \u0010r13\u0011 אוֹ שֶׁהִזִּיק \u0010g21\u0011 כְּשֶׁהוּא יָשֵׁן, חַיָּב בְּנֶזֶק וּפָטוּר מִד' דְּבָרִים. \u0010g22\u0011\nמִי שֶׁנָּפַל מִן הַגַּג בְּרוּחַ מְצוּיָה וְהִזִּיק, \u0010y17\u0011 \u0010t4\u0011 חַיָּב בְּד' דְּבָרִים וּפָטוּר מֵהַבֹּשֶׁת. נָפַל בְּרוּחַ שֶׁאֵינָהּ מְצוּיָה, חַיָּב בְּנֶזֶק בִּלְבַד וּפָטוּר מִד' דְּבָרִים \u0005(וְע\"ל סִימָן תי\"ח סי\"ג)\u0006. \u0010y18\u0011 \u0010g23\u0011 וְאִם נִתְהַפֵּךְ, חַיָּב בַּכֹּל, אַף בְּבֹשֶׁת; שֶׁכָּל הַמִּתְכַּוֵּן לְהַזִּיק, אַף עַל פִּי שֶׁלֹּא \u0010g24\u0011 נִתְכַּוֵּן לְבַיֵּשׁ, חַיָּב בְּבֹשֶׁת.\nהַמַּזִּיק לְאִשְׁתּוֹ בְתַשְׁמִישׁ הַמִּטָּה, \u0010y19\u0011 \u0010t5\u0011 חַיָּב בִּנְזָקֶיהָ. \u0010g25\u0011 \u0010r14\u0011 הָאוֹמֵר \u0010y20\u0011 לַחֲבֵרוֹ: קְטַע אֶת יָדִי, אוֹ: סַמֵּא אֶת עֵינִי עַל מְנַת שֶׁאַתָּה פָטוּר, הֲרֵי זֶה \u0010t6\u0011 חַיָּב בַּחֲמִשָּׁה דְבָרִים, שֶׁהַדָּבָר יָדוּעַ שֶׁאֵין אָדָם רוֹצֶה בְכָךְ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאִם אָמַר לוֹ בְּפֵרוּשׁ: עַל מְנַת לִפְטֹר, פָּטוּר; אֶלָּא שֶׁאִם לֹא אָמַר לוֹ בְּפֵרוּשׁ, רַק דְּבָרִים שֶׁמַּשְׁמָעָן כָּךְ, אָנוּ דָנִין דְּבָרָיו שֶׁלֹּא פְטָרוֹ, \u0010y21\u0011 כְּגוֹן שֶׁאָמַר לוֹ: קְטַע יָדִי, אוֹ: סַמֵּא עֵינִי, וְאָמַר לוֹ הַמַּזִּיק: עַל מְנַת לִפְטֹר, וְאָמַר לוֹ הַנִּזָּק: הֵן, אָנוּ דָנִין \u0010t7\u0011 שֶׁבִּתְמִיהָה קָאָמַר הֵן, וְחַיָּב הַמַּזִּיק (טוּר סי\"א בְּשֵׁם \u0010g26\u0011 הָרֹא\"שׁ)\u0006. \u0010c0\u0011 \u0010g27\u0011\nשְׁנַיִם שֶׁחָבְלוּ זֶה בְּזֶה, אִם חָבַל הָאֶחָד בַּחֲבֵרוֹ יוֹתֵר מִמַּה שֶׁחָבַל בּוֹ הוּא, \u0010y22\u0011 מְשַׁלֵּם לוֹ \u0010t8\u0011 בַּמּוֹתָר נֶזֶק שָׁלֵם. \u0010g28\u0011 \u0010r15\u0011 וְדַוְקָא שֶׁהִתְחִילוּ שְׁנֵיהֶם כְּאֶחָד, אוֹ \u0010g29\u0011 לְאַחַר שֶׁחָבַל \u0010y23\u0011 בַּחֲבֵרוֹ חָזַר גַּם הוּא \u0010t9\u0011 \u0010r16\u0011 מִיָּד וְחָבַל בּוֹ; אֲבָל אִם הִתְחִיל הָאֶחָד, הַשֵּׁנִי פָטוּר, שֶׁיֵּשׁ לוֹ רְשׁוּת לַשֵּׁנִי לַחְבֹּל בּוֹ \u0010y24\u0011 כְּדֵי לְהַצִּיל \u0010t10\u0011 עַצְמוֹ. \u0010y25\u0011 \u0010c1\u0011 \u0005וְכֵן הוּא לְעִנְיַן \u0010t11\u0011 גִּדּוּפִים וּבִיּוּשִׁים, \u0010g30\u0011 הַמַּתְחִיל פּוֹרֵעַ הַקְּנָס (הַגָּהוֹת מָרְדְּכַי דְקִדּוּשִׁין)\u0006. רְאוּבֵן שֶׁהִכָּה לְשִׁמְעוֹן, \u0010r17\u0011 וְחָזַר שִׁמְעוֹן וּבָא לְהַכּוֹתוֹ לִרְאוּבֵן, \u0010y26\u0011 \u0010g31\u0011 וּבָאתָה אִשְׁתּוֹ שֶׁל רְאוּבֵן וְהֶחֱזִיקָה בְּשִׁמְעוֹן, וְהוּא נִתֵּק יָדָיו וְהִכָּה אוֹתָהּ, פָּטוּר \u0005(מהרי\"ו סִימָן כ\"ח)\u0006. וְע\"ל סוֹף סִימָן תכ\"ד אִישׁ וְאִשָּׁה שֶׁחָבְלוּ זֶה בְּזֶה. \u0010g32\u0011 \u0010r18\u0011 וּמִיהוּ צָרִיךְ אֹמֶד, אִם הָיָה יָכוֹל לְהַצִּיל עַצְמוֹ בְּחַבָּלָה מוּעֶטֶת וְחָבַל בּוֹ הַרְבֵּה, חַיָּב. \u0005וְדַוְקָא לְעִנְיַן חַבָּלָה שֶׁמְּשַׁלֵם לוֹ ד' דְּבָרִים, דְּהָוֵי כְּאָדָם הַמַּזִּיק בְּשׁוֹגֵג; אֲבָל פָּטוּר עַל הַבֹּשֶׁת, דְּהָא לֹא כִּוֵּן לְבַיֵּשׁ. וְלָכֵן הַמַּכֶּה חֲבֵרוֹ, וַחֲבֵירוֹ קְרָאוֹ מַמְזֵר, פָּטוּר, שֶׁנֶּאֱמַר: וְהָיָה כִּי יֵחַם לְבָבוֹ וְגוֹ' (דְּבָרִים יט, ו)\u0006. וְכֵן אִם אֶחָד קָרָא לַחֲבֵרוֹ גַּנָּב, וְהוּא אוֹמֵר לוֹ: \u0010c2\u0011 אַתָּה מְכַזֵּב כְּמַמְזֵר, אוֹ קְרָאוֹ מַמְזֵר, פָּטוּר מֵהַאי טַעֲמָא \u0005(מהרי\"ו סִימָן כ\"ח וְסִימָן ס')\u0006. \u0010g33\u0011 \u0010r19\u0011 וְכֵן הַדִּין בְּאָדָם הָרוֹאֶה אֶחָד מִיִּשְׂרָאֵל \u0010g34\u0011 מַכֶּה חֲבֵרוֹ, וְאֵינוֹ יָכוֹל לְהַצִּילוֹ אִם לֹא שֶׁיַּכֶּה הַמַּכֶּה, יָכוֹל לְהַכּוֹתוֹ, \u0010y27\u0011 כְּדֵי לְאַפְרוּשֵׁי \u0010t12\u0011 מֵאִסוּרָא. \u0005הַגָּה: וְכֵן מִי שֶׁהוּא תַּחַת רְשׁוּתוֹ, וְרוֹאֶה בּוֹ שֶׁהוּא עוֹשֶׂה דְּבַר עֲבֵרָה, רַשַּׁאי לְהַכּוֹתוֹ וּלְיַסְּרוֹ כְּדֵי לְהַפְרִישׁוֹ מֵאִסּוּר, וְאֵין צָרִיךְ לַהֲבִיאוֹ לְבֵית דִּין (ת\"ה \u0010g35\u0011 \u0010r20\u0011 סִימָן רי\"ח)\u0006.\nשְׁנַיִם שֶׁחָבְלוּ בְּאֶחָד כְּאֶחָד, שְׁנֵיהֶם חַיָּבִים, וּמְשַׁלְּשִׁים בֵּינֵיהֶם. הָיָה אֶחָד מִתְכַּוֵּן וְהַשֵּׁנִי לֹא כִּוֵּן, הַשֵּׁנִי פָּטוּר מִבֹּשֶׁת:",{"g":["א) משנה בפ\"ח דב\"ק דף פ\"ו ע\"א","ב) משנה שם ע\"ב","ג) וכ' שם ומ\"מ יקבל דכונתו לא היתה לביישו","ד) ל' הרמב\"ם בפ\"א מה' חובל ומזיק וכת' ה\"ה ברייתא בפ\"ח דב\"ק (דף פ\"ו ע\"א)","ה) שם באותה ברייתא","\u0003ו) טור ס\"ד וכן כ' הרא\"ש בספ\"ב דב\"ק על משנה אדם מועד לעולם וכו'\u0004 שם דף כ\"ו ע\"ח וכ\"כ התוספת בספ\"ו דב\"מ דף פ\"ב ע\"א","ז) שם בסימן ו' וכ\"כ הרמב\"ם שם דף יא וכ' ה\"ה מהירושלמי שם וגם הרא\"ש הביאו שם","ח) שם ושם","ט) שם סעיף ז' בשם תשובת הרא\"ש כלל ק\"א סי' ו' מטעם דהוי אנוס כי עיקר כוונתם הי' להפיל א' לחביריו וא\"א לצמצם ולכוין שיפלו בנחת ומחלו זה על זה ואדעתא דהכי אבקו יחד","י) שם סח מימרא דר\"פ בפ\"ה דב\"ק דף מח ע\"א","\u0003כ) טור שם מברייתא שם פ\"ג דף כח ע\"ב מניין לנרצע כו'\u0004 ואע\"ג דמוקי לה התם בעבדא גנבא היינו אליבא דמ\"ד דלא עביד אינש לנפשיה דינא במקום דליכא פסידא ואנן קיימ' לן כמ\"ד דעביד וכו' לעיל סי' ד'","\u0003ל) מברייתא הנזכרת וכ' עוד וכ\"ש ☜אדם מעלמא שיצא עליו שם שהוא גנב:\u0004 ","מ) שם סט מימרא דרבא שם בפ\"ה דף מא ע\"א","נ) שם בשם הרמ\"ה","ס) מבואר במ\"ש לעיל סי' רפ\"ח סעיף ז'","ע) ל' הרמב\"ם בפ\"ח מה' חובל ומזיק דין י\"ז משנה שם בפ\"ג דף לב ע\"ב","פ) ברייתא שם","צ) כ' ה\"ה פסק כלישנא בתרא דר' יוסי בר חנינא גבי הך ברייתא שם וי\"מ שלא ברשות אבל יודע בו הוא כההיא דלעיל וכן כ' הטור בשם רש\"י) ויש מי שפי' אע\"ג דלא ידע ליה שאני נגר שהכל רגילין ליכנס אצל האומנים וה\"ל שלא ברשות כברשות (וכ\"כ הטור בשם ריב\"א) ☜","מבואר בסעיף א'","\u0003ק) שם דף טו מימרא דרבה שם בפ\"ב דף כו\u0004 ע\"ב","ר) שם באותה מימרא","ש) משנה שם ע\"א סוגיא דגמרא שם","\u0003ת) שם דף יב מימרא דרבא שם דף כז ע\"א:\u0004 ","א) פירש\"י לאחר שהתחיל ליפול שנתכוין ליפול על האדם להזיקו להנאתו חייב על הבוש' ואע\"פ שלא נתכוין משום בשתו וכ' ה\"ה דע שג' חלוקים הם כל זמן שיש בדבר פשיעה גמורה וזהו רוח מצויה אבל היא שלא בכוונה חייב בד' דברי' ופטור מן הבושת לא היתה שם פשיעה גמורה וגם כן לא נעשה באונס גמור חייב על הנזק ופטור מן השאר וזהו רוח שאינה מצויי' ובאונס גמור כתבו המפרשים ז\"ל שהוא פטור ע\"כ וכתב רבינו ירוחם כל אונס שהוא כעין גניבה פטור וכ\"כ התוספות","ב) שם בפ\"ד דף יז בעיא דאפשיטא שם בפ\"ג דף לב ע\"א והטור סי\"ו כ' שחייב בד' דברים וכ' הב\"י שם משמע שם דעל הבושת פטור דאינו חייב על הבושת עד שיתכוין","ג) שם בפ\"ח די\"א משנה שם בפ\"ח דף צב ע\"א וכ' ה\"ה ודע דרבינו מפרש דר' יוחנן שם דף צג ע\"א דאמר יש הן וכו' לא קאי אראשי איברים דמתני' דלימא דטעמא דמתני' מפני שאמר לי' הן כמתמיה וכדפי' רש\"י ז\"ל אלא דר\"י דינא באנפי נפשה הוא ובהכני ופצעני בדוקא אבל בראשי איברי' אפי' אמר הן בניחותא חייב וז\"ש רבינו בראשי איברי' בדוקא אבל בהכני ופצעני ודאי הרי לו הן בנזקי ממון וכן עיקר ולא הביא הרב ז\"ל דין המדבר בתמיה לפי שהוא פשוט","ד) מימרא דר' יוחנן שם וכפרש\"י","ה) טור סי\"ט משנה בפ\"ג דל\"ג ע\"א","ו) שם בשם אביו הרא\"ש שם בפסקיו","פי' לאחר שנפרדו זה מזה וע\"ל בסי' ת\"כ","ז) וכ' מהר\"ם מרוזבורג ☜ראובן טען על שמעון שקראו ממזר ושמעון אומר שמתחל' לחש לו באזנו שהוא ממזר לכן נתרגז וא\"ל כן אומדנא דמוכח הוי כיון שקראו פתאום ממזר ודאי האמת אתו עכ\"ל וא\"צ לישבע ע\"ז כמ\"ש לעיל סימן ת\"כ סל\"ח סמ\"ע בשם ד\"מ","ח) וכ' בנימוקי מהר\"ם דדין אשה לענין בזיון כדין איש ואם אין האיש רוצ' שתתבזה אשתו צריך לפדותה בממון כפי אשר ישיתו עליו הב\"ד וע' לעיל סי' תכד ס\"ח מזה סמ\"ע בשם ד\"מ","\u0003ט) שם ושם:\u0004 ","\u0003י) שם ושם:\u0004 ","כ) כ' המרדכי פרק המניח אין לדחוף אדם את חבירו כשמכין זה את זה אלא יש לשומטו בנחת ואם דחף חייב לעשות לו דין ונלע\"ד שלמדו מדין שור שעלה ע\"ג שור מבואר בסי' שפ\"ג ס\"ב","ל) רמב\"ם בס\"א מה' חובל ומזיק די\"ב"],"t":["\u0003קטן. \u0004 ע\"ל סימן ת\"כ סל\"ז:","\u0003פושע. \u0004 ובכלל זה הוא דאם הישן הוזק בהכלים שהונחו בצדו דחייב בעל הכלים בנזקיו דהישן. סמ\"ע:","\u0003וחושש. \u0004 \u0005(* א\"ה בתשובה שבות יעקב ח\"א סי' קע\"ד נשאל בדין זה וכמדומה דאישתמיטתיה הג\"ה זו ע\"ש)\u0006:","\u0003בר\"ה. \u0004 לא זו אף זו קאמר ל\"מ אם הבקיעה היתה במקום דשכיחי רבים דחייב דה\"ל ליזהר טפי אלא אפי' היתה הבקיעה ברה\"י וגם ההיזק נעשה במקום דלא שכיחי רבים אפ\"ה חייב ל\"מ בנזק אלא אפי' בשאר ג' דברים משום דקרוב לפשיעה הוא זולת מבושת דפטור דהא לא כוון לזה. סמ\"ע:","\u0003חייב. \u0004 ז\"ל הטור דשוגג קרוב למזיד הוא דלא ה\"ל לעלות לגג שאין לו מעקה כיון שיכול ליפול משם ברוח מצויה \u0005(ועמ\"ש בזה בסי' שע\"ח ס\"ק ג' ע\"ש)\u0006:","\u0003בנזקיה. \u0004 ר\"ל כל נזקיה דאע\"ג דיש לו רשות לשמש עמה מ\"מ ה\"ל לעיוני דלא יזיק ודין המעות דנותן בהארבע דברים יתבאר בסי' תכ\"ג מה עושה בהן ואיך דינן גם בא\"ע סימן פ\"ג. סמ\"ע:","\u0003חייב. \u0004 ואף לסברא זו דוקא בראשי אברים ידועים הוא דחייב דאין אדם רוצה בחסרון אברים הללו וסבור שחבירו לא יקטעו ויסמאהו אע\"ג דא\"ל ע\"מ לפטור אבל אם אמר ליה הכני פצעני ע\"מ לפטור והוא פצע בו בלא חסרון ראשי אברים פטור כמו בא\"ל שבור את כדי כו' וכמ\"ש בר\"ס ש\"פ ע\"ש. שם:","\u0003קאמר. \u0004 ובזה אפילו בלא ראשי אברים נמי אמרי' דבתמיה קאמר וחייב ולא נקט קטע ידי כו' אלא ללמדנו דאם אמר בפירוש ע\"מ לפטור דפטור אפי' בהני ודוקא בהיזק ממון הוא דפטרי' ליה אף בלשון המתפרש דבתמיה קאמר וכמ\"ש בר\"ס ש\"פ שם ולא בצער דגופו. שם:","\u0003במותר. \u0004 ע\"ל סי ת\"ב מ\"ש בהזיק שור בשור בתשלומי במותר נ\"ש ומינה יש ללמוד לאדם באדם ועיין בתשוב' מבי\"ט ח\"ב סי' שי\"א:","\u0003מיד. \u0004 עיין בסמ\"ע שכתב דהאי מיד ט\"ס הוא ע\"ש באורך:","\u0003עצמו. \u0004 דאפילו אחרים חייבים לחבול בהחובל כדי להציל חבריהן כמ\"ש בסימן תכ\"ה כ\"ש הוא עצמו. סמ\"ע:","\u0003וביושים. \u0004 עיין בתשובת ראנ\"ח סי' נ' וצ\"ג וקי\"א ובמהרש\"ל פ\"ח דב\"ק סימן מ\"ב:","\u0003מאיסורא. \u0004 בטור כתב עוד בבא אחד לפני זה וז\"ל וכן הדין באדם הרואה את חבירו שמכה לאביו או בנו או אחיו והרואה הכה המכה כדי להציל את קרובו שפטור עכ\"ל ומדלא כייל אחיו ובנו עם סיפא דרואה מכה לאח' מישראל גם מדכתב בכל אחד טעם בפ\"ע דבמציעתא כתב כדי להציל קרובו ובסיפא כתב כדי לאפרושי מאיסורא דקדקתי בזה נ\"מ לדינא והוא דאם זה הבא להציל אינו בר הכי להיות רגיל לאפרושי מאיסורא דכמה פעמים רואה שמכה אחד לחבירו ואינו חושש לאפרושי המכה מאיסורא אז אמרינן דאסור להכות לזה המכה דודאי מכח שנאה בא להכותו משא\"כ ברואה מכה אביו ובנו ואחיו דמותר להציל קרובו בהכאה אף שאין דרכו להציל אחרים והמחבר דלא חילק בינייהו אפשר דלא הרגיש בזה ובאמת טעם נכון הוא לחלק כן. סמ\"ע:"],"r":["\u0003אינו כו' לפיכך כו'. \u0004 מתני' פ\"ו ב':","\u0003 (ליקוט) וכן מי כו'. \u0004 דמש\"ש כ\"ז א' ואם נתהפך כו' ר\"ל שנתכוין להזיקו דוקא כמש\"ש כיון שנתכוין להזיק דלא כרש\"י שם ד\"ה ואם נתהפך כו' שכ' להנאתו. יש\"ש שם. ול\"ד לפלוגתא דסי' שפח ס\"ה בהג\"ה מ\"מ כו' וי\"ח כו' דהא לענין ד' דברים ודאי חייב אפי' לא נתכוין כמש\"ש וכ\"ש בנזק גופו או ממונו (ע\"כ):","\u0003י\"א כו'. \u0004 אין חולק בדבר וגמ' ערוכה היא שם כ\"ז א' ברוח מצויה כו' וכמ\"ש בסי\"א:","\u0003ובלבד כו'. \u0004 שם ושם ברוח שא\"מ כו' ושם כו א' קתני סימא כו' ושם ב' היתה אבן כו' הכיר כו'.","\u0003אבל בנזק כו'. \u0004 שם ושם:","\u0003דאדם כו'. \u0004 מתני' כו א':","\u0003בד\"א כו'. \u0004 ירושלמי הביאו תוס' ד' א' ד\"ה כיון כו' וש\"פ:","\u0003וה\"ה כו'. \u0004 תוס' כז ב' ד\"ה ושמואל כו' צ\"ט ב' ד\"ה אימא כו' ב\"מ פ\"ב ב' ד\"ה וסבר כו' וש\"פ ועסי' שעח ס\"א:","\u0003שנים כו'. \u0004 כמו שניהם רצין ברה\"ר ועסמ\"ע:","\u0003אבל אם כו'. \u0004 עתוס' שם ד\"ה מנין כו':","\u0003וכן כו'. \u0004 כתי' דגמ' שם:","\u0003נכנס כו' ודוקא כו' היו כו'. \u0004 עסי' שעח:","\u0003בין כו'. \u0004 כר\"ע דמתני ארישא דהוא לישנא בתרא ואמרו שם ומאן דמתני לה ארישא כו' וכשיטתם ועסי' ת\"כ ס\"ל:","\u0003או שהזיק כו'. \u0004 מתני' וגמ' שם קתני סימא כו':","\u0003האומר כו' וי\"א כו'. \u0004 ער\"ס ש\"פ:","\u0003ודוקא כו'. \u0004 כמש\"ש כ\"ז ב' מאה פנדי כו' וכ\"ש כה\"ג ושם כח א' וקצותה כו' דוקא בשיכולה להציל כו':","\u0003מיד. \u0004 ט\"ס וז\"ש וכ\"ה לענין גידופי' כו' ועסמ\"ע:","\u0003וחזר שמעון כו'. \u0004 ר\"ל מיד וכנ\"ל דאז פטור:","\u0003ומיהו צריך כו'. \u0004 דלא גרע מרודף סנהדרין ע\"ד א' משא\"כ בשוורים. שם:","\u0003וכן הוין כו' וכן מי כו'. \u0004 כמש\"ש כ\"ח א' רנב\"י אמר כו':\n\u0003 (ליקוט) וכן הדין באדם כו' וכן כו'. \u0004 ערש\"י בערכין טז ב ד\"ה יכול כו' (ע\"כ):","\u0003שנים כו' היה כו'. \u0004 כמש\"ש נ\"ג ב' בשור דאדם ועתוס' ד\"ה שור כו':"]}],["הַחוֹבֵל בַּחֲבֵרוֹ, אַף עַל פִּי שֶׁנָּתַן לוֹ ה' דְּבָרִים, \u0010y0\u0011 אֵינוֹ מִתְכַּפֵּר לוֹ עַד שֶׁיְּבַקֵּשׁ מִמֶּנּוּ \u0010y1\u0011 וְיִמְחֹל לוֹ. \u0010y2\u0011 וְאָסוּר לַנֶּחְבָּל לִהְיוֹת אַכְזָרִי מִלִּמְחֹל, כִּי \u0010y3\u0011 אֵין זֶה דֶרֶךְ זֶרַע יִשְׂרָאֵל, אֶלָּא כֵּיוָן שֶׁבִּקֵשׁ מִמֶּנּוּ הַחוֹבֵל וְנִתְחַנֵּן לוֹ \u0010y4\u0011 פַעַם רִאשׁוֹנָה וּשְׁנִיָּה, וְיָדוּעַ שֶׁהוּא שָׁב מֵחֶטְאוֹ וְנִחַם מֵרָעָתוֹ, יִמְחֹל לוֹ. וְכָל הַמְמַהֵר לִמְחֹל הֲרֵי זֶה מְשֻׁבָּח, וְרוּחַ חֲכָמִים נוֹחָה הֵימֶנּוּ. \u0005הַגָּה: \u0010y5\u0011 וְעַיֵּן בְּאֹרַח חַיִּים סִימָן תר\"ו. אָסוּר לְבַקֵּשׁ דִּין מִן הַשָּׁמַיִם עַל חֲבֵרוֹ שֶׁעָשָׂה לוֹ רָעָה. וְדַוְקָא דְּאִית לֵהּ דַּיָּנָא בְאַרְעָא. וְכָל הַצּוֹעֵק עַל חֲבֵרוֹ, הוּא נֶעֱנָשׁ תְּחִלָּה (גְּמָרָא פֶּרֶק הַחוֹבֵל)\u0006. וְיֵשׁ אוֹמְרִים דַּאֲפִלּוּ לֵית לֵהּ דַּיָּנָא בְּאַרְעָא אָסוּר לִצְעֹק עָלָיו, אֶלָּא אִם כֵּן הוֹדִיעוֹ תְּחִלָּה \u0005(הָרַ\"ן פ\"ק דְּר\"ה)\u0006.\nדִּין נֶחְבָּל נִשְׁבָּע וְנוֹטֵל, נִתְבָּאֵר בְּסִימָן צ'.",["\u0003אינו מתכפר לו עד כו'. \u0004 כן הוא ל' המשנה והברייתא בפרק החובל (בבא קמא דף צ\"ב ע\"א) גם ברמב\"ם כ\"כ אבל רש\"י פי' שם דקאי אצער דבושת וכ\"כ בקיצור פסקי הרא\"ש גם בטורים המדויקים כ\"כ בהדיא אבל בדפוס ב\"י כתב צער והבושת:","\u0003וימחול לו. בגמרא למדו זה מדכתי' באבימלך ועתה השב את אשת האיש כו' ויתפל בעדך. ונראה דהלימוד משם הוא דאם רצה הש\"י למחול לו היה מוחל לו בלא תפילת אברהם אלא למדונו שצריך לפייסו עד שימחול לו במחילה גמורה ואז יתפלל בעדו:\u0004","\u0003ואסור לנחבל כו'. \u0004 גם זה נלמד מאותו מעשה דהרי אברהם נתפייס מאבימלך והתפלל בעדו כמ\"ש בכתוב:","\u0003ה\"ג אין זה דרך זרע ישראל כו'. \u0004 ור\"ל שג' סימנים יש לזרע אברהם ביישנים רחמנים גומלי חסדים ורחמנים הוא היפך אכזריות:","\u0003פעם הראשונה ושנייה. \u0004 ובא\"ח סי' תר\"ו כתב הטור והמחבר ראשונה ושנייה ושלישית שם קאי אהמפייס וקאמר שאם לא נתפייס בשני פעמים ילך אצלו גם פעם שלישית וכאן למדונו שזה שמפייסין אותו יהיה רחמן ולא ימתין עד שילך ויבא אצלו שלישית אלא ימחול לו בראשונה או בשנייה וק\"ל:","\u0003ועיין בא\"ח סי' תר\"ו \u0004 שם כתב מור\"ם בהג\"ה דאם הוציא עליו שם רע א\"צ למחול לו עכ\"ל והוא מדברי הג\"מ פ\"ב דהל' תשובה ומהרי\"ל והטעם דשם רע פגע בכבוד אבותיו או בניו לדורות ושמא היו אנשים דשמעו הש\"ר ולא ישמעו החרטה והמחילה ויסברו שהוא אמת:"],[],"הַחוֹבֵל \u0010g0\u0011 בַּחֲבֵרוֹ, אַף עַל פִּי שֶׁנָּתַן לוֹ ה' דְּבָרִים, \u0010y0\u0011 אֵינוֹ מִתְכַּפֵּר לוֹ עַד שֶׁיְּבַקֵּשׁ מִמֶּנּוּ \u0010y1\u0011 וְיִמְחֹל לוֹ. \u0010y2\u0011 \u0010r0\u0011 וְאָסוּר לַנֶּחְבָּל לִהְיוֹת אַכְזָרִי \u0010r1\u0011 מִלִּמְחֹל, כִּי \u0010y3\u0011 \u0010g1\u0011 אֵין זֶה דֶרֶךְ זֶרַע יִשְׂרָאֵל, אֶלָּא כֵּיוָן שֶׁבִּקֵשׁ מִמֶּנּוּ הַחוֹבֵל וְנִתְחַנֵּן לוֹ \u0010y4\u0011 פַעַם רִאשׁוֹנָה \u0010t0\u0011 וּשְׁנִיָּה, וְיָדוּעַ שֶׁהוּא שָׁב מֵחֶטְאוֹ וְנִחַם מֵרָעָתוֹ, יִמְחֹל לוֹ. \u0010r2\u0011 וְכָל הַמְמַהֵר לִמְחֹל הֲרֵי זֶה מְשֻׁבָּח, וְרוּחַ חֲכָמִים נוֹחָה הֵימֶנּוּ. \u0005הַגָּה: \u0010y5\u0011 וְעַיֵּן בְּאֹרַח חַיִּים סִימָן תר\"ו. \u0010r3\u0011 אָסוּר לְבַקֵּשׁ דִּין מִן הַשָּׁמַיִם עַל חֲבֵרוֹ שֶׁעָשָׂה לוֹ רָעָה. וְדַוְקָא דְּאִית לֵהּ דַּיָּנָא בְאַרְעָא. וְכָל הַצּוֹעֵק עַל חֲבֵרוֹ, הוּא נֶעֱנָשׁ תְּחִלָּה (גְּמָרָא \u0010g2\u0011 פֶּרֶק הַחוֹבֵל)\u0006. וְיֵשׁ אוֹמְרִים דַּאֲפִלּוּ לֵית לֵהּ דַּיָּנָא בְּאַרְעָא אָסוּר לִצְעֹק עָלָיו, אֶלָּא אִם כֵּן הוֹדִיעוֹ תְּחִלָּה \u0005(הָרַ\"ן פ\"ק דְּר\"ה)\u0006.\nדִּין נֶחְבָּל נִשְׁבָּע וְנוֹטֵל, נִתְבָּאֵר בְּסִימָן צ'.",{"g":["\u0003א) משנה בפ\"ח דב\"ק ד' צב ע\"א:\u0004 ","\u0003ב) לשון הרמב\"ם בפ\"ה מה' חובל ושם במשנה:\u0004 ","\u0003ג) שם דף צג ע\"א:\u0004 "],"t":["\u0003ושניה. \u0004 ובא\"ח סימן תר\"ו כ' ושלישית דשם קאי אהמפייס וקאמר שאם לא נתפייס בב' פעמים ילך אצלו גם פעם הג' וכאן למדונו דזה שמפייסין אותו יהיה רחמן ולא ימתין עד שילך ויבוא אצלו שלישית אלא ימחול לו בראשונה או בשניה עוד כתב בא\"ח שם הרמ\"א בהג\"ה דאם הוציא עליו שם רע א\"צ למחול לו והוא מדברי הג\"מ פ\"ב דתשובה ומהרי\"ל והטעם דבשם רע פגע בכבוד אבותיו או בניו לדורות ושמא היו אנשים ששמעו השם רע ולא ישמעו החרטה והמחילה ויסברו שהוא אמת. סמ\"ע:"],"r":["\u0003ואסור כו'. \u0004 שם:","\u0003כי אין כו'. \u0004 יבמות עט א':","\u0003וכל הממהר כו'. \u0004 רפ\"ב דיומא ופ\"ק דר\"ה:","\u0003אסור כו' ודוקא כו' וכל כו'. \u0004 ב\"ק צג א':"]}],["הַנּוֹגֵף אֶת הָאִשָּׁה וְיָצְאוּ יְלָדֶיהָ, \u0010y0\u0011 אַף עַל פִּי שֶׁלֹּא נִתְכַּוֵּן, חַיָּב לְשַׁלֵּם דְּמֵי וְלָדוֹת לְבַעְלָהּ, \u0010y1\u0011 וְנֵזֶק וְצַעַר לָאִשָּׁה. וְכֵיצַד מְשַׁעֲרִין דְּמֵי וְלָדוֹת, שָׁמִין אֶת הָאִשָּׁה כַּמָּה הָיְתָה יָפָה עַד שֶׁלֹּא יָלְדָה, \u0010y2\u0011 וְכַמָּה הִיא יָפָה מִשֶּׁיָּלְדָה, וְנוֹתְנִים לַבַּעַל. \u0005וְצַעַר וְנֶזֶק מְשַׁעֲרִין כַּמָּה תִּפְחַת הָאִשָּׁה וְנִכְחֶשֶׁת יוֹתֵר כְּשֶׁהִיא מַפֶּלֶת עַל יְדֵי הַכָּאָה מִשֶּׁיָּלְדָה כְּדַרְכָּהּ. \u0010y3\u0011 וְכֵן בְּשֶׁבֶת וְרִפּוּי, אִם צְרִיכָה לְכָךְ (טוּר ס\"א)\u0006. וְעַיֵּן בְּאֶבֶן הָעֵזֶר סִימָן פ\"ג. וְאִם מֵת הַבַּעַל, נוֹתְנִים לְיוֹרְשָׁיו. \u0005(שָׁם בְּשֵׁם הרמב\"ם ד\"ב)\u0006. וְאִם נְגָפָהּ אַחַר מִיתַת הַבַּעַל, נוֹתְנִים אַף \u0010y4\u0011 דְּמֵי וְלָדוֹת לָאִשָּׁה. \u0010y5\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּהוּא שֶׁל יוֹרְשָׁיו (טוּר בְּשֵׁם הָרַאֲבַ\"ד וְהָרֹא\"שׁ)\u0006.\nהָיְתָה נְשׂוּאָה לְגֵר, וְחִבֵּל בָּהּ בְּחַיֵּי הַגֵּר, נוֹתֵן דְּמֵי וְלָדוֹת לַבַּעַל. \u0010y6\u0011 מֵת הַגֵּר, פָּטוּר. וְאִם חָבַל בָּהּ אַחַר מִיתַת הַגֵּר, \u0010y7\u0011 זָכְתָה הִיא בִּדְמֵי וְלָדוֹת. \u0010y8\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּהוּא פָטוּר (טוּר ס\"ג בְּשֵׁם הָרֹא\"שׁ)\u0006.\nהָיְתָה שִׁפְחָה אוֹ גוֹיָה בִּשְׁעַת הֵרָיוֹן, וּבִשְׁעַת נְגִיפָה נִשְׁתַּחְרְרָה אוֹ \u0010y9\u0011 נִתְגַיְּרָה, הֲרֵי דְּמֵי וְלָדוֹת שֶׁלָּהּ. \u0010y10\u0011 \u0010c0\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּאִם בַּעְלָהּ קַיָּם הֲרֵי הֵן שֶׁל בַּעַל; \u0010y11\u0011 וְאִם לָאו, הוּא פָטוּר (טוּר ס\"ד בְּשֵׁם הָרֹא\"שׁ)\u0006.\nהַנּוֹגֵף אֶת הָאִשָּׁה וְיָצְאוּ יְלָדֶיהָ וָמֵתָה, אַף עַל פִּי שֶׁהָיָה שׁוֹגֵג, הֲרֵי זֶה פָטוּר מֵהַתַּשְׁלוּמִין וְאֵינוֹ מְשַׁלֵּם כְּלוּם, \u0010y12\u0011 שֶׁנֶּאֱמַר: וְלֹא יִהְיֶה אָסוֹן עָנֹשׁ יֵעָנֵשׁ \u0005(שְׁמוֹת כא, כב)\u0006 ; \u0005(לֹא חִלֵּק הַכָּתוּב בֵּין שׁוֹגֵג לְמֵזִיד בְּדָבָר שֶׁיֵּשׁ בּוֹ מִיתַת בֵּית דִּין לְפָטְרוֹ מִן הַתַּשְׁלוּמִין\u0006 \u0010y13\u0011 בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁנִּתְכַּוֵּן לָאִשָּׁה. אֲבָל אִם נִתְכַּוֵּן לַחֲבֵרוֹ, וְנָגַף אֶת הָאִשָּׁה, אַף עַל פִּי שֶׁמֵּתָה, הוֹאִיל וְהֵמִיתָהּ בְּלֹא \u0010y14\u0011 כַּוָּנָה הֲרֵי זֶה כְּדָבָר שֶׁאֵין בּוֹ מִיתַת בֵּית דִּין, וּמְשַׁלֵּם דְּמֵי וְלָדוֹת. \u0005וְיֵשׁ אוֹמְרִים דַּאֲפִלּוּ לֹא נִתְכַּוֵּן לָאִשָּׁה פָּטוּר מִתַּשְׁלוּמִין (טוּר ס\"ה בְשֵׁם הָרַאֲבַ\"ד)\u0006.",["\u0003אע\"פ שלא נתכוין כו'. \u0004 דכתיב בפרשת משפטים וכי ינצו אנשים ונגפו אשה הרה ויצאו ילדיה ולא יהיה אסון ענוש יענש כאשר ישית עליו בעל האשה דמדכתיב וכי ינצו אנשים למדונו דלא נתכוין להאשה ומדכתיב ולא יהיה אסון פי' בהאשה הנוגפת למדונו דבזה דוקא יהיה עליו חיוב תשלומין הוולדות הא אם יהיה בה אסון מיתה פטור מדמי וולדות דקם להו בדרבה מיניה וכמ\"ש הטור והמחבר בס\"ס זה ע\"ש ומדכתיב בעל האשה למדונו שזכתה התורה דמי הולדות לבעלה:","\u0003ונזק וצער של האשה. \u0004 עיין בא\"ה סי' פ\"ג שם כ' הטור והמחבר דהנזק והפגם הוא שלו ושלה ולק\"מ דשם קאי אנזק דקטיעת ידה או אבר שמחסרה ממלאכתה מ\"ה יש לו חלק בו דהא מכח זה נתבטלה ממלאכתו משא\"כ כאן דמיירי מכחישת גופה דאין לו חסרון ממלאכתו כ\"א שבת בעודה בחליות' ואותה משלם להבעל ועפ\"ר:","\u0003וכמה היא יפה משילדה. \u0004 פי' אם היא ילדה בלא הכאה אלא שהיא ריקנית בלא ולד ומשום דלפעמים אשה מפלת ג\"כ מעצמה בלי נגיפה והכאה מ\"ה אין עליו לשלם כל דמי הולד אלא בכמה אדם קונה אשה הרה ביוקר כדי שאם תלד יהיה הולד שלו דאין נותן בה כ\"כ דמים דשמא תפיל ולא תשארה בידו אלא ריקנית וק\"ל והיינו פחת דמי הולדות דזכתה לו התורה אבל מה שנכחש גופה מחמת כאב הכאתה זהו מקרי נזק ועליו כ' הטור והמחבר דהוא של האשה:","\u0003וכן בשבת וריפוי. \u0004 והריפוי נותן לרופא והשבת לבעל משום דמעשה ידיה הוא שלו וכ\"כ בטור עוד כ' שם דהבושת אם הוא בסתר לו חלק א' ולה שני חלקים ואם הוא בגלוי לה חלק א' ולו שני חלקים ולא ידעתי למה השמיטו המחבר. ופי' סתר ובגלוי בדבר זה נראה דר\"ל דההכאה היה בסתר שלא היו רואין בדבר או בגלוי במקום רואין ועפ\"ר מ\"ש עוד בזה וגם עיין בטור א\"ע סי' פ\"ג דכ' שם בדין ריפוי אם אמדוהו לרפאותו בה' ימים ועבדה לה סמא חריפא ונתרפאת בג' ימים דהוא בכלל צער והוא שלה:","\u0003דמי יולדות לאשה. \u0004 פי' ולא ליורשיו משום דאין אדם מוריש ליורשיו דבר שלא בא לעולם דבחייו עדיין לא נגפה והן שלה כיון דכתיב בתורה ויצאה ילדיה ולא כתיב הילדים ללמדינו ששמה נקרא על ילדיה היכא דאין לאב זכייה בהן:","\u0003דהוא של יורשיו \u0004 דכיון דזיכתה התורה להיות דמי הולדות שלו נחשבו הולדות כשהן במעי אמן של הבעל וכשמת שם יורשיו נקראין עליהן ועומדים במקומו גם בזה:","\u0003מת הגר פטור \u0004 פי' ואינם נותנים ליורשיו דאין יורשי הגר יורשים אותו וכמ\"ש הטור והמחבר לעיל בסי' רע\"ה:","\u0003זכתה היא בדמי כו'. \u0004 דומיא דאשה ישראלית שנגפה אחר מיתת הבעל דפסק המחבר לעיל דנותנין לאשה דמי הוולדות ולא ליורשיו:","\u0003דהוא פטור. \u0004 ג\"כ הוא מטעם דס\"ל לי\"א הנ\"ל באשה דעלמא דאין האשה זכה בהן כ\"א יורשיו ובגר דאין יורשיו יורשין אותו ממילא פטור הנוגף:","\u0003הרי דמי הולדות שלה \u0004 דכיון דאין הקדושין תופסין בשפחה ועכו\"ם משום ישראל לא קרינן ביה בעל האשה ואין לישראל זה שנתעברה ממנו זכייה בהולדות ואף שהוא חי בשעת נגיפה (ול\"ד לישראל שנתעברה מישראל בזנות דקי\"ל דדמי הולדות הוא של הבועל דשם בני קידושין נינהו וכ\"כ המ\"מ שם) ומ\"ה הדמים הן שלה משום דס\"ל דזכתה התורה לה היכא דאין להבעל בהן זכייה כנ\"ל:","\u0003וי\"א דאם בעלה קיים הרי הן של בעל. \u0004 פי' כשנתעברה מישראל וכנ\"ל וטעמם דמדמי זה לישראל המזנה עם ישראלית:","\u0003ואם לאו הוא פטור. \u0004 י\"א הללו ג\"כ לטעמם הנ\"ל אזלי דאין לאשה שום זכייה בדמי וולדותי':","\u0003שנאמר ולא יהיה אסון כו'. ה\"ג יענש לח חילק הכתוב בין שוגג למזיד בדבר שיש בו מיתת ב\"ד לפוטרו מהתשלומין בד\"א כו' וכן ברמב\"ם שם:\u0004","\u0003כשנתכוין לאשה כו' \u0004 אף ע\"ג דקרא איירי בשנים שמריבין ומכוין להכות לחברו ונגף האשה שלא בכוונה וכמ\"ש בר\"ס זה מ\"מ הדיוק דלמדנו מולא יהיה אסון הא אם יהיה אסון פטור מדמי ולדות משום דקם ליה בדרבה מיניה זה (לא) שייך כשלא נתכוין להאשה דס\"ל דאין צד מיתה בכה\"ג אבל כשנתכוין להאשה אע\"פ שהיה שוגג במיתתה למדנו מקרא כל שאם מזיד היה חייב מיתה אפילו אם היה שוגג באותה מיתה ג\"כ פטור מממון וכמו שכ' הטור והמחבר בריש סי' שאחר זה:","\u0003כדבר שאין בו מיתת בית דין. \u0004 כן הוא ג\"כ ל' הרמב\"ם שם בפ\"ד דהל' חובל ואע\"ג דסבירא ליה להרמב\"ם דאין מיתת בית דין בנתכוין להרוג את זה והרג את זה וכמו שכתוב שם מכל מקום כ' כדבר בכ\"ף הדמיון משום דבהרג שוגג ג\"כ אין מיתת בין דין ואפי' הכי אמרי' דפטור מדמי וולדות כיון דאיכא צד מיתת בית דין אם היה מזיד וה\"נ ג\"כ בלא נתכוון להקמ\"ל דבכזה אמרינן כאלו אין כאן צד מיתת בית דין כלל:"],["\u0003 דאם בעל הקיים כו' \u0004 ומהרש\"ל פ\"ה דב\"ק סי' י\"ז כתב דלהרא\"ש לעולם אין לו לבעל דהא לא מיקרי בעל כיון דלא תפס בה קידושין ע\"ש דהטור ומור\"ם לא דקדקו בהרא\"ש:"],"\u0010g0\u0011 הַנּוֹגֵף אֶת הָאִשָּׁה וְיָצְאוּ יְלָדֶיהָ, \u0010y0\u0011 אַף עַל פִּי שֶׁלֹּא נִתְכַּוֵּן, חַיָּב לְשַׁלֵּם דְּמֵי וְלָדוֹת לְבַעְלָהּ, \u0010y1\u0011 \u0010g1\u0011 \u0010r0\u0011 וְנֵזֶק \u0010r1\u0011 וְצַעַר \u0010t0\u0011 לָאִשָּׁה. \u0010r2\u0011 וְכֵיצַד מְשַׁעֲרִין דְּמֵי וְלָדוֹת, \u0010g2\u0011 שָׁמִין אֶת הָאִשָּׁה כַּמָּה הָיְתָה יָפָה עַד שֶׁלֹּא יָלְדָה, \u0010y2\u0011 וְכַמָּה הִיא יָפָה \u0010g3\u0011 \u0010t1\u0011 מִשֶּׁיָּלְדָה, וְנוֹתְנִים לַבַּעַל. \u0005וְצַעַר וְנֶזֶק מְשַׁעֲרִין כַּמָּה תִּפְחַת הָאִשָּׁה וְנִכְחֶשֶׁת יוֹתֵר כְּשֶׁהִיא מַפֶּלֶת עַל יְדֵי הַכָּאָה מִשֶּׁיָּלְדָה כְּדַרְכָּהּ. \u0010y3\u0011 וְכֵן בְּשֶׁבֶת \u0010t2\u0011 וְרִפּוּי, אִם צְרִיכָה לְכָךְ (טוּר ס\"א)\u0006. וְעַיֵּן בְּאֶבֶן הָעֵזֶר סִימָן פ\"ג. \u0010g4\u0011 וְאִם מֵת הַבַּעַל, נוֹתְנִים לְיוֹרְשָׁיו. \u0005(שָׁם בְּשֵׁם הרמב\"ם ד\"ב)\u0006. וְאִם נְגָפָהּ אַחַר מִיתַת הַבַּעַל, נוֹתְנִים אַף \u0010y4\u0011 דְּמֵי וְלָדוֹת לָאִשָּׁה. \u0010y5\u0011 \u0010r3\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּהוּא שֶׁל \u0010t3\u0011 יוֹרְשָׁיו (טוּר בְּשֵׁם \u0010g5\u0011 הָרַאֲבַ\"ד וְהָרֹא\"שׁ)\u0006. \u0010g6\u0011 \u0010r4\u0011\nהָיְתָה נְשׂוּאָה לְגֵר, וְחִבֵּל בָּהּ בְּחַיֵּי הַגֵּר, נוֹתֵן דְּמֵי וְלָדוֹת לַבַּעַל. \u0010y6\u0011 מֵת הַגֵּר, \u0010g7\u0011 פָּטוּר. וְאִם חָבַל בָּהּ אַחַר מִיתַת הַגֵּר, \u0010y7\u0011 \u0010g8\u0011 זָכְתָה הִיא בִּדְמֵי וְלָדוֹת. \u0010y8\u0011 \u0010r5\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּהוּא פָטוּר (טוּר ס\"ג בְּשֵׁם \u0010g9\u0011 הָרֹא\"שׁ)\u0006. \u0010g10\u0011 \u0010r6\u0011\nהָיְתָה שִׁפְחָה אוֹ גוֹיָה בִּשְׁעַת הֵרָיוֹן, וּבִשְׁעַת נְגִיפָה נִשְׁתַּחְרְרָה אוֹ \u0010y9\u0011 נִתְגַיְּרָה, הֲרֵי דְּמֵי וְלָדוֹת \u0010t4\u0011 \u0010r7\u0011 שֶׁלָּהּ. \u0010y10\u0011 \u0010c0\u0011 \u0010r8\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּאִם בַּעְלָהּ \u0010t5\u0011 קַיָּם הֲרֵי הֵן שֶׁל בַּעַל; \u0010y11\u0011 וְאִם לָאו, הוּא פָטוּר (טוּר ס\"ד בְּשֵׁם הָרֹא\"שׁ)\u0006. \u0010g11\u0011 \u0010r9\u0011\nהַנּוֹגֵף אֶת הָאִשָּׁה וְיָצְאוּ יְלָדֶיהָ וָמֵתָה, \u0010g12\u0011 אַף עַל פִּי שֶׁהָיָה שׁוֹגֵג, הֲרֵי זֶה פָטוּר מֵהַתַּשְׁלוּמִין וְאֵינוֹ מְשַׁלֵּם כְּלוּם, \u0010y12\u0011 שֶׁנֶּאֱמַר: וְלֹא יִהְיֶה אָסוֹן עָנֹשׁ יֵעָנֵשׁ \u0005(שְׁמוֹת כא, כב)\u0006 ; \u0005(לֹא חִלֵּק הַכָּתוּב בֵּין שׁוֹגֵג לְמֵזִיד בְּדָבָר שֶׁיֵּשׁ בּוֹ מִיתַת בֵּית דִּין לְפָטְרוֹ מִן הַתַּשְׁלוּמִין\u0006 \u0010y13\u0011 \u0010t6\u0011 בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁנִּתְכַּוֵּן לָאִשָּׁה. אֲבָל אִם נִתְכַּוֵּן לַחֲבֵרוֹ, וְנָגַף אֶת הָאִשָּׁה, אַף עַל פִּי שֶׁמֵּתָה, הוֹאִיל וְהֵמִיתָהּ בְּלֹא \u0010y14\u0011 כַּוָּנָה הֲרֵי זֶה כְּדָבָר שֶׁאֵין בּוֹ מִיתַת בֵּית דִּין, וּמְשַׁלֵּם דְּמֵי וְלָדוֹת. \u0010r10\u0011 \u0005וְיֵשׁ אוֹמְרִים דַּאֲפִלּוּ לֹא נִתְכַּוֵּן לָאִשָּׁה פָּטוּר מִתַּשְׁלוּמִין (טוּר ס\"ה בְשֵׁם הָרַאֲבַ\"ד)\u0006.",{"g":["א) לשון הרמב\"ם רפ\"ד מהלכות חובל משנה בפ\"ד דב\"ק סוף דף מח","\u0003ב) כתב ה\"ה מפורש שם (דף מט ע\"א) ברייתא הכה את האשה וכו'\u0004 ופי' נזק מה שנפחת גופה מחמת מכה ורש\"י ז\"ל פי' ונזקא דהכא כחבלה בעלמ' והדין קצוב בכתובו' וכו' (מבואר בא\"ה סימן פג) ורבינו ז\"ל פסק כפשט הברייתא","ג) כת\"ק דרשב\"ג שם במשנה","פי' בלא מכה שילד' מאליה שאלו פחת המכה זהו הנזק שהוא לאשה ה\"ה","ד) שם במשנה ושם בברייתן","ה) וביאר שם דשאני שם לרבא גבי אשת הגר הוא מפני שאין לו יורשין דקיימא וקדמ' איהו וזכיא בגווייהו וכו' וכתב ה\"ה לא מצאתי לו טענה ברורה לסמוך עליו וכו' ואפשר שהוא סובר כאשר ישית עלי' בעל האשה בזמן שהוא בעולם בשעת נגיפה אבל אם מת לאשה דומיא לאשת גר וצ\"ע","ו) שם ד\"ד מפורש שם בברייתא וגמרא","פירוש לפי שאין לו יורשים","ז) פסק כרבה שם","ח) פסק כרב חסדא שם","ט) שם ד\"ד וכתב ה\"ה דעת הרב בזה דשפחה ועכו\"ם לא קרינן בה בעל האשה שאין קידושין תופסים בהן וכו' והביא ראי' מהירושלמי ושזה עיקר","י) שם דין ה'","כ) כ' ה\"ה כדאסיקנא בהדי' בפ\"ג דכתובות דף לה ע\"א וכדתנא דבי חזקיה בזה לחלק שאין חילוק בין שוגג למזיד וסובר כרב אדא בר אהבה דאסיק בפ\"ק דב\"ק (דף מב ע\"א) אנשים שנתכוונו זה לזה אע\"ג דיש אסון לאשה יענשו וכרבי דאמר הכין בפרק הנשרפין (סנהדרין דף עט ע\"א) ודלא כתנא דבי חזקיה בזה החלק ואין הא' תלוי בחבירו וכו' ורבינו ז\"ל כבר פסק וכו' כר' שמעון נתכוין להרוג זה והרג זה דפטור (שם) ונ\"ל שיצא לו מדמקשי שם בב\"ק רב אדא בפשיטותא על אביי ורבא וכו' ותו דמסקנא הכי' הוא סתם כרב אדא (דאמר כי אתי רב חגי מדרומא אייתי מתניתא וכו' שם בב\"ק ומ\"מ שטות אחרות יש ע\"כ)"],"t":["\u0003לאשה. \u0004 ובא\"ע סימן פ\"ג כתב דהנזק ופגם הוא שלו ושלה ולק\"מ דשם קאי אנזק דקטיעת ידה או אבר שנתבטלה ממלאכתו ע\"י זה מש\"ה יש לו חלק בו משא\"כ כאן דמיירי מכחישת גופה דאין לו חסרון ממלאכתו כי אם שבת בעודה בחלייה ואותו משלם להבעל. סמ\"ע:","\u0003משילדה. \u0004 דלפעמים מפלת האשה ג\"כ מעצמה בלי נגיפה והכאה מש\"ה אין עליו לשלם כל דמי הולד אלא בכמה אדם קונה אשה הרה ביוקר כדי שאם תלד יהא הולד שלו דאינו נותן בה כל כך דמים דשמא תפיל ולא תשאר בידו אלא ריקנית והיינו פחת דמי הולדות דזכתה לו התורה. שם:","\u0003וריפוי. \u0004 הוא נותן להרופא והשבת לבעל משום דמעשה ידיה הוא שלו וכ\"כ בטור עוד כתב דבבשת יש לחלק בין בסתר או בגלוי ונתבאר בא\"ע סימן פ\"ג וע\"ש בטור שכתב דאם אמדוה לרפאותה בה' ימים ועבדו לה סמא חריפא ונתרפאת בג' ימים דהוי בכלל צער והוא שלה. שם:","\u0003יורשיו. \u0004 דכיון דזיכתה התורה להיות דמי הולדות שלו נחשבו הולדות כשהן במעי אמן של הבעל וכשמת שם יורשיו נקראין עליהן ועומדין במקומו גם בזה. שם:","\u0003שלה. \u0004 דסבירא ליה דזכתה התורה לה היכא דאין להבעל זכיה בהן ול\"ד לישראלית שנתעברה מישראל בזנות דקי\"ל דדמי הולדות הוא של הבועל דשם בני קידושין נינהו כן כתב הה\"מ שם:","\u0003קיים. \u0004 ומהרש\"ל פ\"ה דב\"ק סימן י\"ז כתב דלהרא\"ש לעולם אין לו לבעל דהא לא מקרי בעל כיון דלא תפסי בה קידושין ע\"ש דהטור והרמ\"א לא דקדקו בהרא\"ש. ש\"ך:","\u0003כשנתכוון. \u0004 אע\"ג דקרא איירי בשנים שמריבין ומכוין להכות לחבירו ונגף האשה שלא בכוונה וכמו שכתו' בר\"ס זה מכל מקום הדיוק דלמדנו מולא יהי' אסון הא אם יהי' אסון פטור מדמי ולדות משום דקלב\"מ זה שייך כשלא נתכוון לאשה דאין צד מיתה בכה\"ג אבל כשנתכוין לאשה אע\"פ שהיה שוגג במיתתה למדנו מקרא דגם חייבי מיתות שוגגין פטורין מתשלומין וכמ\"ש בר\"ס שאח\"ז. סמ\"ע:"],"r":["\u0003 (ליקוט) ונזק וצער כו' וכן בשבת וריפוי כו'. \u0004 תוספתא פ\"ט דב\"ק הכה את האשה ויצאו ילדיה משלם נזק צער ריפוי שבת ובשת לאשה וולדות לבעל כו' (ע\"כ):\n\u0003 (ליקוט) ונזק כו'. \u0004 צ\"ע דברייתא אתי לת\"ק אבל אנן קיי\"ל כריב\"ב וכמ\"ש בא\"ה סי' פג ס\"א ולדברי רש\"י בפ\"ו דכתובות שפי' רק בבשת ניחא וכ\"כ הרא\"ש בב\"ק שם אבל רש\"י שם בב\"ק ד\"ה שמין כ' אף בנזק כדברי הרמב\"ם אבל הרמב\"ם שם כ' דאף בנזק (ע\"כ):","\u0003וצער כו' וכן כו'. \u0004 הרא\"ש שם ותוס' מב ב' ד\"ה נותן כו' וע\"ש נ\"ט א' לפי שסופה כו' וערש\"י שם ד\"ה נכי כו':","\u0003 (ליקוט) וכיצד כו'. \u0004 דלא כרשב\"ג דאמוראי נינהו ואליבא דר\"י וכמ\"ש בס\"פ המדיר ובפ\"ג דב\"מ והסוגיא בגמ' כאידך ממ\"ש בס\"פ השואל יחלוקו חדש העיבור לרשב\"ג דס\"ל כסומכוס וקי\"ל בכ\"מ דלא כסומכוס וכן כל האמוראי דשם וערא\"ש פ\"ד דב\"ב ס\"ו. וערי\"ף ורא\"ש פג\"פ (ע\"כ):\n\u0003 (ליקוט) וכיצד כו'. \u0004 דלא כר\"י דפ' בכ\"מ כרשב\"ג במשנתי' כמ\"ש הרי\"ף בפ' ג\"פ וכמ\"ש במ\"א וכן רבא ל\"ל האי כללא בפ' בתרא דע\"ז ס\"ט ב' א\"ר הלכה כרשב\"ג דלר\"י ל\"צ ועוד דקא' הואיל ותנן סתמא כו' וכן שמואל בפי\"ד דשבת ורפ\"ג די\"ט דפ' כרשב\"ג וכן בפ\"ח דב\"ב קלג ב' וערשב\"ם שם ד\"ה ת\"ש ודבריו צ\"ע ואמוראי בתראי ס\"ל הא דשמואל כמ\"ש בספ\"ד דכתובות נג א' (ע\"כ):","\u0003וי\"א דהוא כו'. \u0004 אפי' לרבה שם תוס' שם ד\"ה אטו כו' והרא\"ש והראב\"ד אבל סוגיא דשם מ\"ג א' כהרמב\"ם וש\"ע ותוס' שם ד\"ה גרושה כו' נשארו בקושיא והרשב\"א שם יישבה בדוחק ע\"ש:","\u0003היתה כו'. \u0004 מתני' וגמ' שם:","\u0003וי\"א כו'. \u0004 כר\"ח דאתוקם שם ב' כד\"ה ודרבה כתנאי ועוד דגדול מרבה כמ\"ש בב\"מ ו' ב' וזה אינו מוכרח דאפי' ר\"ה רבו של ר\"ח מצינו דבעי מרבה שם כ' ב' וש\"מ. והרמב\"ם פ' כרבה דסוגיא הנ\"ל מ\"ג א' כוותיה כנ\"ל:","\u0003היתה כו'. \u0004 עבה\"ג ועתוס' מג א' ד\"ה אפי' כו':","\u0003שלה. \u0004 כשיטתו בס\"א וס\"ב וכקושיא דגמ' שם גרושה נמי כו' וכאן אין לבעל כלום:","\u0003וי\"א כו'. \u0004 כ\"כ הטור שלדעת הרא\"ש דהיא לא זכיא בוולדות כר\"ח כנ\"ל ודבריו תמוהים דאפי' בעל קיים פטור וכ\"ה לפי' ריב\"א במתני' היתה כו' ועתוס' מב ב' ד\"ה היתה כו' ואף תוס' לא דחו פי' אלא משום דסוגיא לא מ' כוותיה וכן מצאתי ביש\"ש שתמה עליו וכ' די\"ל פי' ריב\"א דרבה לשיטתו דבכה\"ג זכתה האשה לכן הוכרח לפרש כפירש\"י אבל לר\"ח אפשר לפרש מתני' כפי' ריב\"א ע\"ש:","\u0003הנוגף כו' בד\"א כו'. \u0004 עבה\"ג וכ\"כ לח\"מ שם:\n\u0003 (ליקוט) בד\"א בשנתכוין כו'. \u0004 כמש\"ש ך\"ו א' ויהא אדם כו' ועתוס' שם ד\"ה ויהא כו' והרשב\"א בשם י\"מ כ' דמיירי בלא מתכוין דקי\"ל כר' יוחנן דחייב כופר בלא מתכוין ודלא כחזקיה ועמש\"ש (ע\"כ):\n\u0003 (ליקוט) בד\"א כו'. \u0004 עבה\"ג בשם המ\"מ ומ\"ש כרב אדא ב\"א כו' ומ\"ש כרבי ולא כתנא ד\"ח ליתא שהרי הרמב\"ם עצמו פ' ברפ\"ד מה' רוצח דלא כרבי אלא כתנא ד\"ח וכ\"כ בה' נערה וכן א\"א לומר כמ\"ש דרמב\"ם מפ' מתכוין כפי' תוס' באותו ממון דרמב\"ם שם ושם כ' בהדיא בממון אחר כפירש\"י וצ\"ל דס\"ל דאע\"ג דהלכה כתנא ד\"ח מ\"מ בדמי ולדות לא קי\"ל כוותיה דר\"א בר אהבה פליג עליה וקי\"ל כוותיה (ע\"כ):","\u0003וי\"א כו'. \u0004 הראב\"ד שם דקי\"ל כתנא ד\"ח כמ\"ש בכתובות ל\"ה א' ועתוס' שם ד\"ה ומי כו' ואור\"י כו' והא דקא' מי איכא כו' וכ\"כ בסנהדרין עט א':"]}],["הַחוֹבֵל בְּאָבִיו וְאִמּוֹ \u0010y0\u0011 וְלֹא הוֹצִיא מֵהֶם דָּם, חַיָּב בַּחֲמִשָּׁה דְבָרִים. הוֹצִיא מֵהֶם דָּם, חַיָּב מִיתָה, לְפִיכָךְ פָּטוּר מִתַּשְׁלוּמִין אֲפִלּוּ הוּא שׁוֹגֵג. לְפִיכָךְ, לֹא יַקִּיז הַבֵּן לְאָבִיו, וְלֹא יוֹצִיא קוֹץ מִבְּשָׂרוֹ וְלֹא יִפְתַּח לוֹ מוּרְסָא, שֶׁמָּא יָבֹא לְהוֹצִיא מִמֶּנּוּ דָם. וְנִתְבָּאֵר זֶה בְּטּוּר יוֹרֶה דֵעָה סִימָן רמ\"א.\nהַחוֹבֵל בַּחֲבֵרוֹ בְּשַׁבָּת, פָּטוּר מִתַּשְׁלוּמִין אֲפִלּוּ הוּא שׁוֹגֵג, \u0010y1\u0011 כֵּיוָן שֶׁיֵּשׁ בּוֹ מִיתַת בֵּית דִּין. אֲבָל הַחוֹבֵל \u0010y2\u0011 בַּחֲבֵרוֹ בְּיוֹם הַכִּפּוּרִים, \u0005(אֲפִלּוּ)\u0006 בְּמֵזִיד, חַיָּב לְשַׁלֵּם לוֹ.\nהַחוֹבֵל \u0010y3\u0011 בְּעֶבֶד כְּנַעֲנִי שֶׁלּוֹ, פָּטוּר. חָבְלוּ בּוֹ אֲחֵרִים, רַבּוֹ נוֹטֵל \u0010y4\u0011 ה' דְּבָרִים. וַאֲפִלּוּ צִעֲרוֹ בְּסַם וְנִתְרַפֵּא מְהֵרָה, הֲרֵי כָּל רְפוּאָתוֹ לְרַבּוֹ.\nמִי שֶׁחֶצְיוֹ עֶבֶד וְחֶצְיוֹ בֶּן חוֹרִין, שֶׁהִכָּהוּ אָדָם אוֹ נְגָחוֹ שׁוֹר, נִתְבָּאֵר מִשְׁפָּטוֹ בְּטוּר יו\"ד סִימָן רס\"ז \u0005(סָעִיף ס\"ב)\u0006.\nמִי שֶׁיָּצָא לְחֵרוּת וַעֲדַיִן לֹא הִגִּיעַ גֵּט שִׁחְרוּר לְיָדוֹ, \u0010y5\u0011 וְחָבְלוּ בּוֹ אֲחֵרִים, פְּטוּרִים. \u0010y6\u0011\nהַחוֹבֵל בְּבַת קְטַנָּה שֶׁל אֲחֵרִים, אִם נֶזֶק \u0010y7\u0011 הַפּוֹחֵת אוֹתָהּ מִכַּסְפָּה הוּא, \u0010y8\u0011 הֲרֵי הוּא שֶׁל הָאָב. וְכֵן שִׁבְתָּהּ שֶׁל אָב, שֶׁהֲרֵי מַעֲשֵׂה יָדֶיהָ וְכֶסֶף מְכִירָתָהּ שֶׁל אָבִיהָ \u0010y9\u0011 הוּא. \u0005וְיֵשׁ אוֹמְרִים דַּוְקָא בִּסְמוּכָה עַל \u0010y10\u0011 שֻׁלְּחָנוֹ, אֲבָל אֵינָהּ סְמוּכָה עַל שֻׁלְּחָנוֹ, הוּא שֶׁלָּהּ (טוּר בְּשֵׁם הָרַמְבַּ\"ם)\u0006. וְיֵשׁ אוֹמְרִים אֲפִלּוּ בִּסְמוּכָה עַל שֻׁלְּחָנוֹ הוּא שֶׁלָּהּ, \u0010y11\u0011 אִם אֲחֵרִים חָבְלוּ בָהּ \u0005(שָׁם בְּשֵׁם הָרֹא\"שׁ)\u0006. אֲבָל צַעַר וְרִפּוּי וּבֹשֶׁת, שֶׁלָּהּ. וְכֵן נֶזֶק שֶׁאֵינוֹ פּוֹחֲתָהּ מִכַּסְפָּה הֲרֵי הוּא שֶׁלָּהּ. וְכֵן הַחוֹבֵל בְּבִתּוֹ, מְשַׁלֵּם צַעַר וְרִפּוּי וּבֹשֶׁת. \u0005הַגָּה: וְנִרְאֶה לִי, דַּוְקָא בְּאֵינָהּ סְמוּכָה עַל שֻׁלְּחָנוֹ (ע' בד\"מ)\u0006, אֲבָל סְמוּכָה עַל שֻׁלְּחָנוֹ \u0010y12\u0011 יֵשׁ אוֹמְרִים דְּפָטוּר \u0005(הַמ\"מ לְדַעַת הָרַמְבַּ\"ם)\u0006, כְּמוֹ שֶׁיִּתְבָּאֵר בְּסָמוּךְ:\nהַחוֹבֵל בְּבָנָיו הַגְּדוֹלִים, אִם אֵינָם סְמוּכִים עַל שֻׁלְחָנוֹ, נוֹתֵן לָהֶם מִיָּד; \u0010y13\u0011 וְהַקְּטַנִּים, יִלָּקַח קַרְקַע בְּנִזְקָן, \u0010y14\u0011 \u0005וְיֵשׁ אוֹמְרִים סֵפֶר תּוֹרָה (טוּר סי\"א בְּשֵׁם הָרֹא\"שׁ)\u0006 וְהֵם אוֹכְלִים פֵּרוֹתָיו. וְכֵן בַּאֲחֵרִים שֶׁחָבְלוּ בָּהֶם. וְאִם הָיוּ סְמוּכִים עַל שֻׁלְחָנוֹ, וְחָבַל בָּהֶם \u0005(הוּא)\u0006, פָּטוּר בֵּין שֶׁהָיוּ גְּדוֹלִים בֵּין שֶׁהָיוּ קְטַנִּים; וְאִם אֲחֵרִים חָבְלוּ בָהֶם, בִּגְדוֹלִים יִתֵּן לָהֶם מִיָּד; בִּקְטַנִים, יִלָּקַח בָּהֶם קַרְקַע וְהוּא אוֹכֵל פֵּרוֹתָיו עַד שֶׁיִּגְדְּלוּ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאֵינוֹ פָטוּר בִּסְמוּכִים עַל שֻׁלְּחָנוֹ אֶלָּא מִשֶּׁבֶת, אֲבָל חַיָּב בִּשְׁאָר ד' דְּבָרִים, וְדִינוֹ בָּהֶם כְּאִלּוּ חָבְלוּ בָהֶן אֲחֵרִים (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006.\nהַחוֹבֵל בְּחֵרֵשׁ שׁוֹטֶה וְקָטָן, חַיָּב; וְהֵם שֶׁחָבְלוּ בַּאֲחֵרִים, פְּטוּרִים; אַף עַל פִּי שֶׁנִּתְפַּקַּח הַחֵרֵשׁ וְנִשְׁתַּפֶּה הַשּׁוֹטֶה וְהִגְדִּיל הַקָּטָן, אֵינָם חַיָּבִים לְשַׁלֵּם, שֶׁבַּשָׁעָה שֶׁחָבְלוּ בָּהֶם לֹא הָיוּ בְּנֵי דַעַת:\nהָעֶבֶד וְהָאִשָּׁה, הַחוֹבֵל בָּהֶם חַיָּב; וְהֵם שֶׁחָבְלוּ בַּאֲחֵרִים, פְּטוּרִים, \u0010y15\u0011 אֲבָל מְשַׁלְּמִים לְאַחַר זְמַן, \u0010c0\u0011 אִם נִתְגָרְשָׁה הָאִשָּׁה אוֹ נִתְאַלְמְנָה אוֹ נִשְׁתַּחְרֵר הָעֶבֶד. \u0005הַגָּה: יֵשׁ לָהּ נִכְסֵי מְלוֹג אוֹ נִכְסֵי צֹאן בַּרְזֶל, מוֹכֶרֶת אוֹתָן לַאֲחֵרִים \u0010y16\u0011 בְּטוֹבַת הֲנָאָה, וּמְשַׁלֶּמֶת לַנֶּחְבָּל (טוּר סי\"ג)\u0006.\nהָאִשָּׁה שֶׁחָבְלָה בְּבַעְלָהּ, \u0010y17\u0011 אִם הָיָה תּוֹסֶפֶת בִּכְתֻבָּתָהּ אוֹ נִכְסֵי מְלוֹג אוֹ נִכְסֵי צֹאן בַּרְזֶל, מְחַיְּבִים אוֹתָהּ לְמָכְרָם לְבַעְלָהּ בְּטוֹבַת הֲנָאָה, וְגוֹבֶה מִמֶּנָּה אִם רָצָה הַבַּעַל. וְאִם רָצָה לְגָרְשָׁהּ וְלִגְבּוֹת מִמֶּנָּה הַכֹּל, גּוֹבֶה; וְאִם לֹא הָיָה לָהּ, אֵינָהּ יְכוֹלָה לִמְכֹּר לוֹ עִקַּר כְּתֻבָּתָהּ, שֶׁאָסוּר לָאָדָם לַשְׁהוֹת אֶת אִשְׁתּוֹ שָׁעָה אַחַת בְּלֹא כְּתֻבָּה, אֶלָּא אִם רָצָה הַבַּעַל כּוֹתֵב עָלֶיהָ שְׁטָר בִּדְמֵי הַחַבָּלָה, אוֹ מְגָרְשָׁהּ וְנוֹטֵל מִכְּתֻבָּתָהּ הָרָאוּי לוֹ. \u0005הַגָּה: וְכֵן אִם הַחַבָּלָה כְּפִי כְּתֻבָּתָהּ, מוֹכֶרֶת כְּתֻבָּתָהּ לְבַעְלָהּ וּמְשַׁלֶּמֶת לְבַעְלָהּ, וְלָא חַיְשִׁינָן שֶׁמָּא תְהֵא קַלָּה בְּעֵינָיו לְהוֹצִיאָהּ, \u0010y18\u0011 שֶׁהֲרֵי אִם יִרְצֶה יוּכַל לְגָרְשָׁהּ וְלִגְבּוֹת בַּחַבָּלָתוֹ (טוּר סי\"ג)\u0006.\nדִּין אֵשֶׁת אִישׁ שֶׁחָבְלוּ בָּהּ אֲחֵרִים אוֹ בַּעְלָהּ, נִתְבָּאֵר בַּטּוּר א\"ה סִימָן פ\"ג. \u0005הַגָּה: אִישׁ, וְאִשָּׁה שֶׁיֵּשׁ לָהּ בַּעַל, שֶׁחָבְלוּ זֶה בָזֶה, \u0010y19\u0011 לָא אַמְרִינָן שֶׁיְּשַׁלְּמוּ בַּמּוֹתָר נֶזֶק שָׁלֵם, דְּהָא קְצָת מֵחַבָּלָה שֶׁחָבַל בָּאִשָּׁה הוּא לְבַעְלָהּ, עַל כֵּן יְשַׁלֵּם הַחוֹבֵל בָּהּ הַשַּׁיָּךְ לְבַעְלָהּ, וּמַה שֶּׁשַׁיָּךְ לָאִשָּׁה מְנַכִּין לוֹ נֶגֶד חַבָּלָתוֹ (תְּשׁוּבַת רַשְׁבָּ\"א סִימָן תתקמ\"ח)\u0006.",["\u0003ולא הוציא מהם דם. \u0004 פי' דאז לא חייב מיתה על הכאתו דכתי' בסוף פ' אמור מכה בהמה ישלמנה ומכה אדם יומת והאי אדם ר\"ל לאביו ולאמו דזולתם לא היה חייב מיתה על הכאתם והוקש אהדדי הכאת אביו לענין מיתה להכאת בהמה לתשלומין מה מכה בהמה אינו חייב עליה בתשלומין אא\"כ עשה בה חבלה שמוציא ממנה דם דכתי' לפני זה מכה נפש בהמה ודם הוא הנפש אף מכה אביו כן ומה מכה בהמה בין שוגג בין מזיד דאדם מועד לעולם לחייב על נזקיו כן נמי מ\"ש מכה אדם יומת איירי אפי' במכה בשוגג לענין זה דשם מיתה עליו ואינו חייב אפי' בתשלומין על חבלתו דקם ליה בדרב' מיני' אם היה מזיד וה\"ה בשוגג לענין זה:","\u0003כיון שיש בו מיתת ב\"ד \u0004 פי' אם חבלו במזיד ומשום הכי אפי' בשוגג אינו חייב בתשלומין וכמ\"ש בסעיף שלפני זה וכ' הרמב\"ם אע\"ג דמקלקל הוא מ\"מ הואיל ועשה נחת רוח ליצרו בשעה שחבל בחבירו מ\"ה חייב מיתה אחבלה זו אם חבלו במזיד ומה\"ט חייב אע\"פ שאין עושה להנאתו ועפ\"ר:","\u0003ביום הכיפורים אפי' במזיד כו' \u0004 כצ\"ל וכ\"כ בטור ור\"ל בי\"כ דליכא מיתה אפי' בחובל או עשה מלאכה בו אפי' במזיד כי אם כרת ואף על גב דיש לאו עם הכרת שעושה מלאכה ביום הכפורים ולוקה עליה דלאו אם התרו בו וקי\"ל כל היכא דאיכא חיובי מלקות וחיוב ממון (על מעשה אחד ואין עושין שתיהן באדם אחד דרשעה אחת אנו מחייבין אותו) לוקין אותו ולא משלם שאני גבי חבלה דגלי לן קרא דיתן ממון ולא יהא לוקה דנתינה כתיב ביה וכמ\"ש לעיל בר\"ס ת\"ך ע\"ש:","\u0003בעבד כנעני שלו פטור \u0004 סתם וכ' דפטור ומשמע דאפי' הכהו מכה דאין בה שוה פרוטה ואין אומרים דחייב עליה מלקות ומטעם שכתבתי בפרישה ריש סימן ת\"ך ע\"ש ולא כמ\"ש ב\"י שם דבכה\"ג אפי' בשלו חייב מלקות ע\"ש. ולהב\"י צ\"ל דהכא דוקא במכה שיש בה ש\"פ ולמעלה איירי דאז משלם ומה שקנה עבד קנה רבו ועפ\"ר:","\u0003חמשה דברים \u0004 ואע\"פ דהריפוי צריך ליתן להרופא שירפאהו מ\"מ נ\"מ בזה אם אמדוהו שירפאהו בה' ימים ונתן לו החובל דמי הרפואה על ה' ימים ורפאו רבו בסם חריף בג' ימים המותר מדמי הרפוא' נשאר ביד רבו וזהו שסיים המחבר וכ' ואפי' צערו הרבה לעבד זה הנחבל בסם חריף ונתרפא כו' ונכון להגיה דלי\"ת דאפי' צערו במקום וי\"ו ואפי' ועד\"ז כ' בטור ע\"ש וק\"ל:","\u0003וחבלו בו אחרי' פטורי'. \u0004 ז\"ל הטו' אינו יכול להוצי' מהם לעצמו כיון שעדיין לא נגמר שחרורו ולא האדון יכול להוצי' מהן כו'. והראב\"ד השיג עליו וכ' ויש אומרים דכותבין הרשאה זה לזה וגובין אותו עכ\"ל הטור וכ' הב\"י שם בפנים דנ\"ל דהכל מודים בזה שאם כתבו הרשאות אדון להעבד או איפכא יכולין להוצי' מידו. ודומ' לזה כ' הטו' והמחב' בס\"ס מ\"ג ובסי' ר' בטו' ס\"ח ע\"ש ומהתימא על שהשמיטו המחבר כאן האי דין דהרשאה:","\u0003החובל בבת קטנה כו'. \u0004 המחבר השמיט כאן דין חובל בע\"ע וכתבו הרמב\"ם פ\"ד דחובל והטור בסי' זה ס\"ח דבעבדו העברי חייב בכולן ליתן להעבד חוץ משבת דישאר בידו אם העבד הוא שלו דבשבתו הוא מבטל ממלאכת רבו שחבלו. ובחבלו בו אחרים כתב הרמב\"ם ילקח בהן קרקע והרב אוכל מפירותיו כ\"ז שהוא אצלו וכשיצא לחירות יקח הקרקע לעצמו וכן דעת הרי\"ף וכן פסק ב\"י להלכה. ור\"ח פי' דשבת גדולה דהיינו דמי ידו ילקח בהן קרקע והרב יאכל פירות שהרי הוא מפסיד בקטיעת ידו מה שיש בין שאר מלאכות לשמירת קישואין לאחר שיתרפא (ר\"ל כשמשלם נזק דמי היד שקטע ממנו אינו משלם לו בעדו אלא מה שהיה עושה מלאכה בידו אבל עדיין הוא ראוי לשמור קישואין מיד שיתרפא מכאב קטיעת ידו וכמ\"ש לעיל סי' ת\"ך) ולכך יאכל פירות בעודו אצלו (כמו שהיה אוכל ממלאכת ידו שנקטעה) ולכשיצא לחרות יטלנה ושבת קטנה דהיינו שכר שומר קישואין כל ימי משך החולי כולו לרבו ולזה הסכים א\"א הרא\"ש ז\"ל ואם חבלו בדבר שאין בו הפסד לרבו כגון שקטע ראש אזנו או ראש חוטמו חבלתו לעבד ואין לרבו בו כלום עד כאן ל' הטור ועפ\"ר:","\u0003הפוחת אותה מכספה \u0004 פי' אם בא למכרה או להשיאה לאיש אין נותנין בעדה כל כך כמו שנותנין בעדה קודם חבלתו ובטור קאמר כגון שפצע' בפניה וכו' ור\"ל דאף אחר שנתרפאת מ\"מ עומד רושם המכה בפניה ונמאסת בה וכ\"ש אם קטע ממנה אבר אחד דמחוסרת אבר אחד שהוא נזק מבורר וידוע יותר ועפ\"ר:","\u0003הרי הוא של אב \u0004 דכתיב את בתי נתתי לאיש הרי שנתנה התורה ברשותו ליתן לאיזה איש שירצה והוא מקבל דמי קדושיה וגם כי ימכור איש את בתו כתיב וכיון דכסף קדושין ומכירתו שלו וזה פחתה מכספה לוקח האב דמי פחתה. ולא כע\"ש דכתב דמדכתיב בנעוריה בית אביה למדינן מיניה דכל שבנעוריה בית אביה היא דז\"א דבהדיא כתבו התוספות דההיא דוקא בהפרת נדרי' איירי וכתבו דאף דבגמ' נזכר לפעמי' האי קרא דבנעוריה בית אביה לא נקטו אלא לסימנא בעלמא ועפ\"ר:","\u0003וי\"א דווקא בסמוכה כו'. \u0004 נראה דאם אינה סמוכה על שלחנו אפי' אביה רוצה ליתן לה מזונות בימי חליה כדי ליקח לעצמו משבתה כדי להיות לו ממנו מותר דמי מזונותיה לאו כל כמיניה משא\"כ בחבל בה האב דכ' המ\"מ שם בדין י\"ט דבכה\"ג שבתה לאביה ע\"ש ודוק:","\u0003אבל אינה סמוכה היא שלה. \u0004 פי' אשבתה קאי דאז ניזונית בדמי שבתה אבל בדמי נזקה דמכירה וכסף קדושיה הנ\"ל אין חילוק:","\u0003אם אחרים חבלו בה \u0004 ל' הרא\"ש דבמידי דאתי לה מעלמא וע\"י צער לא קפיד:","\u0003יש אומרים דפטור \u0004 כמ\"ש בסמוך ר\"ל מיד בסעיף שאחר זה בדין אם חובל בבניו הגדולים וכמ\"ש המחבר שם והוא דעת הרמב\"ם ודין בן ובת שוה גם המ\"מ כתב אדברי הרמב\"ם כמ\"ש מור\"ם דמיירי דוק' באינה סמוכה ע\"ש סוף פ\"ד דחובל:","\u0003והקטני' ילקח בהן קרקע כו'. \u0004 בגמרא פליגי שני מ\"ד חד אמר דיקלא וחד אמר ס\"ת והרמב\"ם והמחבר כתבו קרקע במקום דיקלא דסביר' ליה דלא קאמר דיקל' אלא משום דדמים הללו השייכים לקטן בחבלתו אין בהן כדי לקנות בהן קרקע והיכא דאפשר לקנות בהן קרקע קרקע עדיפ' שקרנו קיים יותר וכן מצינו בגמ' בכמה מקומות שקונין קרקע והבעל אוכל פירותיו:","\u0003ויש אומרים ספר תורה. \u0004 פי' והקטנים ילמדו מתוכה והוא פירות דספר תורה והקרן קיימת להן עד שיגדלו ועיי' מה שכתבתי בדרישה ע\"ז מ\"ש זה מהא דאית' בגמרא פ\"ז דהמקבל פקדון מיד קטנים דהדין הוא דאין מחזירין הפקדון ליד הקטן ופליגי נמי בו הני שני מ\"ד חד אמר לא יחזירהו לקטן אלא יקנ' בו דיקל' וחד אמר ס\"ת ופסק שם בטור דיקנ' דקל וי\"ל דשאני הכא דהמעות הן ודאי שלקטן אלא שאין נותנין בידו מפני שיפסידו וס\"ל שטובתו הוא שיקנ' בהן ס\"ת וילמד מתוכה ואף אם יקלקלנ' לא איכפת לן בהך כיון שהוא שלו והוא טובתו משא\"כ התם דיש לחוש שיתברר של מי היה הממון לכך יקנה דקל דלא כליא קרנא אלא שצ\"ע מ\"ט דהרמב\"ם דפסק כאן כרבה דיקנה בהן דקל ובפ\"ו דפקדון פסק דיקנה בהן ס\"ת או דקל ויאכל פירותיו ואפש' דה\"ט דהכא שעדיין לא בא הממון ליד הקטן ס\"ל דאין קונים בעד הדמים ס\"ת ונותנין לו לפי שיכלה קרנם ואין לב\"ד לגרום שיצ' תקלה מתחת ידם אבל בפקדון דכבר היה מוחזק הממון ביד הקטן ומידו הפקיעו לזה הנפקד אלא שמחשש השבת אבידה נגעו בה דלמא יבואו הבעלים ויכירו את שלהם ס\"ל דאין לחוש כולי האי וקונים בעד הדמים אפי' ס\"ת ללמוד מתוכו וק\"ל:","\u0003אבל משלמין לאחר זמן. \u0004 ול\"ד לחש\"ו שחבלו מפני דהאשה והעבד הן בני דעת בשעה שחבלו דחייבין לשלם אלא שאין להם במה לשלם והטור כתב ע\"ז ז\"ל לפיכך שמין ב\"ד הה' דברים בשעה שחבלו באחרים וכותבין ונותנין אותו ביד הנחבל ולכשיהיה להן נכסים משלמין:","\u0003בטובת הנאה לשון הטור \u0004 פי' שאם תתאלמן או תתגרש יקחם הלוקח ואם תמות ישארו לבעל ואותה טובת הנאה שקבלו בהן תתנה לנחבל אבל אינה חייבת למכור כתובתה לשלם לנחבל עכ\"ל והטעם משום דקיימא לן המוכר שטר חוב לחברו וחזר ומחלו מחול וכמ\"ש הטור והמחבר לעיל סי' ס\"ו ואם תמכר שטר כתובתה שיש לה על בעלה לאחר והיא תמחול החוב שבשטר כתובתה לבעלה יפסידו הב\"ד להלוקח בידים וכי תימא תמכרה הכתובה לההוא דחבלה בו בטובת הנאה דאז אף אם תמחלה לבעלה לא קמפסיד דמה לי שיש לו עליה חוב של חבלתו או דמי הכתובה לאחר שתמחלה לבעלה מ\"מ כיון דודאי מחלה לגבי בעלה אטריחי רבנן בכדי למה לן כן הוא בגמ' דפרק החובל (דס\"ט) ושם ג\"כ הדין אם חבלה בבעלה דכתב המחבר אחר זה ושם ג\"כ הדין דאם יש לה נכסי מלוג ונצ\"ב שהן בעין ולא שייך בהו ה\"ט דמחלה לבעלה וע\"ל סי' שפ\"ח ס\"ב דכ' שם דאם אשה מסרה לאח' דמשמתינן לה וכ\"כ המרדכי בפ' החובל אהא שאמרו נשים ועבדים שפגיעתן רעה דמ\"מ משמתינן אותן ומלקין אותן שלא ירגילו לעשות כן ואפשר דדוקא במסירה וחבלה או בשאר בזיון דמבזין ס\"ל הכי ולא בחוב שעליה דאין עליה אלא חיוב ממון (וע\"ל סי' תכ\"א סי\"ג מ\"ש מדין בזיון אשה) וכתב בעל התרומות בשער ל\"ו דאם אין מי שירצה ליקח הנכסי מלוג או נכסי צאן ברזל בטובת הנאה יקחם הנחבל עצמו בטובת הנאה ואם יש מותר בטובת הנאה מדמי החבלה אין צריך ליתן הנחבל להאשה המותר עד שעה דקניא לנפשה ועיין לעיל בסי' שפ\"ח סעיף ב' דכתבתי דגם בהלואה דס\"ס צ\"ו ובשאלה (ונשאת) ונאנסה הבהמה דס\"ס שמ\"ו ובגניבה בסימן שמ\"ט דאם יש להנ\"מ ונצ\"ב ותוס' כתובה דג\"כ מחוייבת למכרה בטובת הנאה ולשלמ' וע\"ל ס\"ס שמ\"ו מ\"ש מזה ועפ\"ר מ\"ש עוד מזה:","\u0003אם היה תוספות בכתובתה או נ\"מ כו' \u0004 האי תוספות לא קאי אנכסי מלוג ואנצ\"ב דקאמר וגם בטור וברמב\"ם לא נזכר בדין זה נ\"מ וצ\"ב רק שהמחבר כללן יחד וכתב אשלשתן דהב\"ד כופין אותה למוכרו בטובת הנאה כל אחד כפי דינו דהיינו נצ\"ב ונ\"מ צריכה למכור לבעלה או לאחר כולן והמעות שתקבל צריכה ליתן לבעלה בדמי חבלתו ואם הבעל קנאה כבטובת הנאה אזי הבעל מנכה לה אותן דמים דדמי חבלתו ובתוס' כתובתה שאינה יכולה למכור לאחר מטעם הנ\"ל שתמחלה לבעלה כו' אזי אין לה קונה כ\"א הבעל עצמו והאי תוס' כתובתה ר\"ל שהוסיף לה בעלה זה כתובתה על דין כתובה דאורייתא דהיינו לבתולה מאתים דינרין צורי ולאלמנה מנה ומשום שהוצרך לכתוב אדין אם יש תוספות בכתובתה שימכרנה לבעלה בטובת הנאה ולא לאחר כתבו נמי כן אנצ\"ב ונ\"מ וסמך אהמחבר אפשיטיתו דבנצ\"ב ונ\"מ שהם בעין אין חילוק בין אם ימכרם לבעלה שחבל' בו או לאחרים וליכא למטעי בו. ומסיק וכ' ז\"ל ואם לא הי' לה ר\"ל דאין לה שום אחד משלשתן ואין לה אלא כתובה דאורייתא על בעלה אינה יכולה למכור כו' ור\"ל שאין יכולה למכור ממנה כלום בין בטובת הנאה בין שלא בטובת הנאה דהא חכמים שיערו הכתובה במנה ומאתים ושבפחות מזה אפי' פרוטה יש לחוש שתהא קלה בעיניו להוציאה מ\"ה אין תקנה לבעלה הנחבל לגבות ממנה דמי חבלתו אם לא שיגרשנה ויגבה מכתובתה דמי חבלתו או שיכתוב עליה שט\"ח וכדמסיק וק\"ל:","\u0003שהרי אם ירצה כו' \u0004 ל' הטור שאף אם לא תמכרנה לו בשביל חיוב כתובה לא ימנע מלהוציאה אם ירצה שהרי אינו צריך ליתן לה כתובה כיון שחייבת לו נגד החבל' אבל אם כתובתה מרובה מחבל' אין אומרים למכור לו (פי' בטובת הנאה דאז אף שהוא מרובה מדמי החבלה אין נותנין בהנאה דמי החבלה) כדי שלא תהא קלה בעיניו להוציא' ואלמלא המכר לא הי' מוציא' כיון שכתובת' מרובה מהחבלה עכ\"ל וכן הוא בטור והוא מגמרא שם בפ' החובל ע\"ש:","\u0003לא אמרינן שישלם במותר נזק שלם. \u0004 פי' שינכו דמי החבלים זה כנגד זה ודמי החבלה העולה יותר בא' מהשני ישלם לו השני החובלו נ\"ש וכמ\"ש הטור בס\"ס תכ\"א סי\"ט וגם המחבר כתבו שם סי\"ג ע\"ש קמ\"ל דבאיש שחבל באשה של איש אחר אין הדין כן והטעם שהאשה אין לה במה לשלם מה שחבלה באיש האחר ומה שחבל האיש האחר בה מגיע ממנו חלק לבעלה כמ\"ש הט\"ו מ\"ה קאמר דצריך האיש החובל באשה ליתן לבעלה כל חלקו מה שיגיע לו מדמי חבלתה והחלק השייך לה א\"צ ליתן לה פי' דה\"א דגם זה יתן וילקח בעלה באותן דמים שדה ויאכל פירות כל ימי חייה והאיש הנחבל לא יגבה דמי חבלתו עד שימות הבעל בחייה דאז יגבה האיש הנחבל לטרוף אותו שדה והמותר יגבה מדמי כתובתה קמ\"ל דלא ומשום דעשאוהו חז\"ל חלקה כנכסים שאין ידועים לבעלה שאין הבעל אוכל מהן פירות כל זה כתב שם בתשובת הרשב\"א ומ\"ה אותן דמים שמגיע בחלקה על שחבל בה הוא ינכה במה שהיא חייבת לו במה שחבלה בו ובהמותר יכתוב שטר עליהן וימתין עד שתתגרש או ימות בעלה:"],["\u0003 אם נתגרשה האשה כו' \u0004 ע' בתשו' רשד\"ם ס\"ס רי\"ז:"],"\u0010g0\u0011 הַחוֹבֵל בְּאָבִיו וְאִמּוֹ \u0010y0\u0011 \u0010r0\u0011 וְלֹא הוֹצִיא מֵהֶם דָּם, חַיָּב בַּחֲמִשָּׁה דְבָרִים. \u0010r1\u0011 הוֹצִיא מֵהֶם דָּם, חַיָּב מִיתָה, לְפִיכָךְ פָּטוּר מִתַּשְׁלוּמִין \u0010g1\u0011 \u0010r2\u0011 אֲפִלּוּ הוּא שׁוֹגֵג. \u0010g2\u0011 \u0010r3\u0011 לְפִיכָךְ, לֹא יַקִּיז הַבֵּן לְאָבִיו, וְלֹא יוֹצִיא קוֹץ מִבְּשָׂרוֹ וְלֹא יִפְתַּח לוֹ מוּרְסָא, שֶׁמָּא יָבֹא לְהוֹצִיא מִמֶּנּוּ דָם. וְנִתְבָּאֵר זֶה בְּטּוּר יוֹרֶה דֵעָה סִימָן רמ\"א. \u0010g3\u0011\nהַחוֹבֵל בַּחֲבֵרוֹ בְּשַׁבָּת, פָּטוּר מִתַּשְׁלוּמִין אֲפִלּוּ הוּא שׁוֹגֵג, \u0010y1\u0011 כֵּיוָן שֶׁיֵּשׁ בּוֹ \u0010t0\u0011 מִיתַת \u0010r4\u0011 בֵּית דִּין. אֲבָל הַחוֹבֵל \u0010y2\u0011 \u0010g4\u0011 \u0010r5\u0011 בַּחֲבֵרוֹ בְּיוֹם הַכִּפּוּרִים, \u0005(אֲפִלּוּ)\u0006 בְּמֵזִיד, \u0010g5\u0011 חַיָּב לְשַׁלֵּם לוֹ. \u0010g6\u0011\nהַחוֹבֵל \u0010y3\u0011 בְּעֶבֶד כְּנַעֲנִי שֶׁלּוֹ, \u0010t1\u0011 פָּטוּר. חָבְלוּ בּוֹ אֲחֵרִים, \u0010r6\u0011 רַבּוֹ נוֹטֵל \u0010y4\u0011 ה' דְּבָרִים. \u0010g7\u0011 \u0010t2\u0011 וַאֲפִלּוּ צִעֲרוֹ בְּסַם וְנִתְרַפֵּא מְהֵרָה, הֲרֵי כָּל רְפוּאָתוֹ לְרַבּוֹ.\nמִי שֶׁחֶצְיוֹ עֶבֶד וְחֶצְיוֹ בֶּן חוֹרִין, שֶׁהִכָּהוּ אָדָם אוֹ נְגָחוֹ שׁוֹר, נִתְבָּאֵר מִשְׁפָּטוֹ בְּטוּר יו\"ד סִימָן רס\"ז \u0005(סָעִיף ס\"ב)\u0006. \u0010g8\u0011 \u0010r7\u0011\nמִי שֶׁיָּצָא לְחֵרוּת וַעֲדַיִן לֹא הִגִּיעַ גֵּט שִׁחְרוּר לְיָדוֹ, \u0010y5\u0011 וְחָבְלוּ בּוֹ אֲחֵרִים, פְּטוּרִים. \u0010y6\u0011 \u0010g9\u0011\nהַחוֹבֵל בְּבַת קְטַנָּה שֶׁל אֲחֵרִים, אִם נֶזֶק \u0010y7\u0011 \u0010t3\u0011 הַפּוֹחֵת אוֹתָהּ מִכַּסְפָּה הוּא, \u0010y8\u0011 הֲרֵי הוּא שֶׁל הָאָב. וְכֵן שִׁבְתָּהּ שֶׁל אָב, \u0010r8\u0011 שֶׁהֲרֵי מַעֲשֵׂה יָדֶיהָ \u0010r9\u0011 וְכֶסֶף מְכִירָתָהּ שֶׁל אָבִיהָ \u0010y9\u0011 הוּא. \u0005וְיֵשׁ אוֹמְרִים דַּוְקָא \u0010t4\u0011 בִּסְמוּכָה עַל \u0010y10\u0011 שֻׁלְּחָנוֹ, אֲבָל אֵינָהּ סְמוּכָה עַל שֻׁלְּחָנוֹ, הוּא שֶׁלָּהּ (טוּר \u0010g10\u0011 בְּשֵׁם הָרַמְבַּ\"ם)\u0006. \u0010r10\u0011 וְיֵשׁ אוֹמְרִים אֲפִלּוּ בִּסְמוּכָה עַל שֻׁלְּחָנוֹ הוּא \u0010t5\u0011 שֶׁלָּהּ, \u0010y11\u0011 אִם \u0010t6\u0011 אֲחֵרִים חָבְלוּ בָהּ \u0005(שָׁם בְּשֵׁם \u0010g11\u0011 הָרֹא\"שׁ)\u0006. אֲבָל צַעַר וְרִפּוּי וּבֹשֶׁת, שֶׁלָּהּ. וְכֵן נֶזֶק שֶׁאֵינוֹ פּוֹחֲתָהּ מִכַּסְפָּה הֲרֵי הוּא שֶׁלָּהּ. וְכֵן הַחוֹבֵל בְּבִתּוֹ, מְשַׁלֵּם צַעַר וְרִפּוּי וּבֹשֶׁת. \u0005הַגָּה: וְנִרְאֶה לִי, \u0010g12\u0011 דַּוְקָא בְּאֵינָהּ סְמוּכָה עַל שֻׁלְּחָנוֹ (ע' בד\"מ)\u0006, אֲבָל סְמוּכָה עַל שֻׁלְּחָנוֹ \u0010y12\u0011 יֵשׁ אוֹמְרִים דְּפָטוּר \u0005(הַמ\"מ לְדַעַת הָרַמְבַּ\"ם)\u0006, כְּמוֹ שֶׁיִּתְבָּאֵר בְּסָמוּךְ: \u0010g13\u0011\nהַחוֹבֵל בְּבָנָיו הַגְּדוֹלִים, אִם אֵינָם סְמוּכִים עַל שֻׁלְחָנוֹ, נוֹתֵן לָהֶם מִיָּד; \u0010y13\u0011 וְהַקְּטַנִּים, \u0010r11\u0011 יִלָּקַח \u0010g14\u0011 קַרְקַע בְּנִזְקָן, \u0010y14\u0011 \u0010t7\u0011 \u0010r12\u0011 \u0005וְיֵשׁ אוֹמְרִים סֵפֶר תּוֹרָה \u0010g15\u0011 (טוּר סי\"א בְּשֵׁם הָרֹא\"שׁ)\u0006 \u0010g16\u0011 וְהֵם אוֹכְלִים פֵּרוֹתָיו. וְכֵן בַּאֲחֵרִים שֶׁחָבְלוּ בָּהֶם. וְאִם הָיוּ סְמוּכִים עַל שֻׁלְחָנוֹ, וְחָבַל בָּהֶם \u0005(הוּא)\u0006, פָּטוּר בֵּין שֶׁהָיוּ גְּדוֹלִים בֵּין שֶׁהָיוּ קְטַנִּים; וְאִם אֲחֵרִים חָבְלוּ בָהֶם, בִּגְדוֹלִים יִתֵּן לָהֶם מִיָּד; בִּקְטַנִים, יִלָּקַח בָּהֶם קַרְקַע וְהוּא אוֹכֵל פֵּרוֹתָיו עַד שֶׁיִּגְדְּלוּ. \u0005הַגָּה: \u0010r13\u0011 וְיֵשׁ אוֹמְרִים דְּאֵינוֹ פָטוּר בִּסְמוּכִים עַל שֻׁלְּחָנוֹ אֶלָּא מִשֶּׁבֶת, אֲבָל חַיָּב בִּשְׁאָר ד' דְּבָרִים, וְדִינוֹ בָּהֶם כְּאִלּוּ חָבְלוּ בָהֶן אֲחֵרִים (טוּר בְּשֵׁם \u0010g17\u0011 הָרֹא\"שׁ)\u0006. \u0010g18\u0011\nהַחוֹבֵל בְּחֵרֵשׁ שׁוֹטֶה וְקָטָן, חַיָּב; וְהֵם שֶׁחָבְלוּ בַּאֲחֵרִים, פְּטוּרִים; \u0010r14\u0011 אַף עַל פִּי שֶׁנִּתְפַּקַּח הַחֵרֵשׁ וְנִשְׁתַּפֶּה הַשּׁוֹטֶה וְהִגְדִּיל הַקָּטָן, אֵינָם חַיָּבִים לְשַׁלֵּם, שֶׁבַּשָׁעָה שֶׁחָבְלוּ בָּהֶם לֹא הָיוּ בְּנֵי דַעַת: \u0010g19\u0011\nהָעֶבֶד וְהָאִשָּׁה, הַחוֹבֵל בָּהֶם חַיָּב; וְהֵם שֶׁחָבְלוּ בַּאֲחֵרִים, פְּטוּרִים, \u0010y15\u0011 אֲבָל \u0010t8\u0011 מְשַׁלְּמִים לְאַחַר זְמַן, \u0010c0\u0011 \u0010g20\u0011 אִם נִתְגָרְשָׁה הָאִשָּׁה אוֹ נִתְאַלְמְנָה אוֹ נִשְׁתַּחְרֵר הָעֶבֶד. \u0005הַגָּה: יֵשׁ לָהּ נִכְסֵי מְלוֹג \u0010r15\u0011 אוֹ נִכְסֵי צֹאן בַּרְזֶל, \u0010r16\u0011 מוֹכֶרֶת אוֹתָן לַאֲחֵרִים \u0010y16\u0011 בְּטוֹבַת \u0010t9\u0011 הֲנָאָה, וּמְשַׁלֶּמֶת לַנֶּחְבָּל \u0010g21\u0011 (טוּר \u0010g22\u0011 סי\"ג)\u0006.\nהָאִשָּׁה שֶׁחָבְלָה בְּבַעְלָהּ, \u0010y17\u0011 \u0010r17\u0011 אִם הָיָה תּוֹסֶפֶת \u0010g23\u0011 בִּכְתֻבָּתָהּ אוֹ נִכְסֵי מְלוֹג אוֹ נִכְסֵי צֹאן בַּרְזֶל, \u0010g24\u0011 מְחַיְּבִים אוֹתָהּ לְמָכְרָם לְבַעְלָהּ בְּטוֹבַת הֲנָאָה, וְגוֹבֶה מִמֶּנָּה אִם רָצָה הַבַּעַל. וְאִם רָצָה לְגָרְשָׁהּ וְלִגְבּוֹת מִמֶּנָּה הַכֹּל, גּוֹבֶה; וְאִם לֹא הָיָה לָהּ, אֵינָהּ יְכוֹלָה לִמְכֹּר לוֹ \u0010g25\u0011 \u0010r18\u0011 עִקַּר כְּתֻבָּתָהּ, שֶׁאָסוּר לָאָדָם לַשְׁהוֹת אֶת אִשְׁתּוֹ שָׁעָה אַחַת בְּלֹא כְּתֻבָּה, אֶלָּא אִם רָצָה הַבַּעַל כּוֹתֵב עָלֶיהָ שְׁטָר בִּדְמֵי הַחַבָּלָה, אוֹ מְגָרְשָׁהּ וְנוֹטֵל מִכְּתֻבָּתָהּ הָרָאוּי לוֹ. \u0005הַגָּה: וְכֵן אִם הַחַבָּלָה כְּפִי כְּתֻבָּתָהּ, מוֹכֶרֶת כְּתֻבָּתָהּ לְבַעְלָהּ וּמְשַׁלֶּמֶת לְבַעְלָהּ, וְלָא חַיְשִׁינָן שֶׁמָּא תְהֵא קַלָּה בְּעֵינָיו לְהוֹצִיאָהּ, \u0010y18\u0011 שֶׁהֲרֵי אִם \u0010t10\u0011 יִרְצֶה יוּכַל לְגָרְשָׁהּ וְלִגְבּוֹת בַּחַבָּלָתוֹ (טוּר סי\"ג)\u0006.\nדִּין אֵשֶׁת אִישׁ שֶׁחָבְלוּ בָּהּ אֲחֵרִים אוֹ בַּעְלָהּ, נִתְבָּאֵר בַּטּוּר א\"ה סִימָן פ\"ג. \u0005הַגָּה: אִישׁ, וְאִשָּׁה שֶׁיֵּשׁ לָהּ בַּעַל, שֶׁחָבְלוּ זֶה בָזֶה, \u0010y19\u0011 לָא אַמְרִינָן שֶׁיְּשַׁלְּמוּ בַּמּוֹתָר נֶזֶק שָׁלֵם, \u0010r19\u0011 דְּהָא קְצָת מֵחַבָּלָה שֶׁחָבַל בָּאִשָּׁה הוּא לְבַעְלָהּ, עַל כֵּן יְשַׁלֵּם הַחוֹבֵל בָּהּ הַשַּׁיָּךְ לְבַעְלָהּ, \u0010r20\u0011 וּמַה שֶּׁשַׁיָּךְ לָאִשָּׁה מְנַכִּין לוֹ נֶגֶד חַבָּלָתוֹ (תְּשׁוּבַת רַשְׁבָּ\"א סִימָן תתקמ\"ח)\u0006.",{"g":["א) לשון הטור וכן כ' הרמב\"ם כ\"ד מה\"ח ד\"ו משנה פ\"ח דב\"ק דף פ\"ז ע\"א","ב) מבואר במ\"ש בסי' דלעיל ס\"ד","ג) ציינתיו בי\"ד סי' רמ\"א","ד) שם ס\"ג ושם במשנה","ה) כן הוא בטור","ו) אפילו אתרו ביה לא אמרינן דמלקי לקי ולא משלם שהרי בפירוש רבתה תורה לתשלומין מבואר בפ\"ג דכתובות דף לז ע\"א","ז) שם ס\"ד בפ' משנה ח' דבבא קמא דף פז ע\"א","ח) מבואר בספ\"ק דגיטין דף י\"ב ע\"ב","\u0003ט) רמב\"ם שם די\"א וכתב ה\"ה בעיא דלא איפשטא וכו'\u0004 בגיטין פ' השולח (גיטין דף מב) ע\"ב ובפי' משמע בסוגיא התם דאי אין לו קנס ה\"ה דאין לו דמי נזקו דמייתי התם הא דמפיל שן עבד וכו' והר\"א ז\"ל כ' שיש מי שסובר דבהרשאה גובין ע\"כ והביאו הטור","\u0003י) שם דין י\"ד פסק כרב יוחנן דאמר הכין בפ\"ח דב\"ק סוף דף פ\"ז:\u0004 ","כ) וכתב הב\"י ומשמע לרבינו מדסיים בה שהרי מעשה ידיה של אביה היינו בוודאי בסמוכה על שלחנו דאל\"כ אין מעשה ידי' שלו ע\"כ ולא ידעתי למה כ' הרמ\"א וי\"א אלא זה הוא פי' הטור לדעת הרמב\"ם שהעתיק המחבר","ל) שם בפסקיו כאוקימתא דגמ' שם","מ) וכ\"כ ה\"ה שם פי' דין זה מכח דין הסמוך וביאר שם והא דלא נקט רבינו שמשלם לה שבת כיון שאינה סמוכה על שולחנו איכא למימר שהוא זנה כל ימי חליה ומה שיהיה יתר השבת על מזונותיה הוא שנשאר לאב והכי פריק לה בגמרא:","נ) שם דין י\"ט כ' ה\"ה ברייתות שם העלו אותה בסוגיא ומזה יראה דבתו כשהיא סמוכה על שלחנו אם חבל בה פטור דמה לי בת מה לי בן ובפירוש שנינו דבניו ובנותיו פטור ואוקימנא לה בסמוכין","ס) פסק כרב' בר הונא שם","ע) פסק כרב חסדא שם","\u0003פ) וכן פי' רשב\"ם בפרק ג' דב\"ב דף נ\"ב ע\"א:\u0004 ","צ) וכן כ' הטור בקיצור פסקי הרא\"ש אבל בנוסחי פסקי הרא\"ש שלפנינו מצאתי כן אך ראיתי בתוס' שם בד\"ה וקתני ולא עוד כו' שכתבו לזה בלשון ועוד נוכל לפרש וכו' ומ\"מ בפסקי תוספות ראיתי שכתבו שבסמוכין על שלחנו האב פטור ומשמע דפטור מכולם כדעת הרמב\"ם","ק) שם בפ\"ג מהלכות חובל ד\"כ משנה שם דף פז ע\"א","ר) שם ושם במשנה","ש) וכ' ה\"ה ומפרש בגמרא והא דלא מזבני' כתובתה בטובת הנאה [מפורש בא\"ה סי' קה] לשלם לנזק. מפני שתחזור ותמחול אצל הבעל ואטרוח ביה דינא בכדי לא מטריחינן","ת) נכסי מלוג מפורש בגמ' שם דף פט ע\"א ומשמע דה\"ה לנכסי צאן וברזל וכן כתב הרא\"ש שם:","א) שם דין י\"ח וכ' ה\"ה זאת הבבא מפורשת בפרק הנזכר (דף סט ע\"ב)","ב) הן דברי המחבר ולמדו מדין האשה שחבלה באחרים ויש לה נכסי מלוג וכולי בהג\"ה דלעיל ומבואר במ\"ש שם","ג) שם ברמב\"ם","ד) שלא תהא קלה בעיניו להוציא' כי יגרשנו מיד וירויח הכל ואלמל' המכר לא היה מוציאה כיון שכתובתה מרובה מהחבלה כן כתבו התו' שם והטור"],"t":["\u0003מיתת. \u0004 וכת' הרמב\"ם אע\"ג דמקלקל הוא מ\"מ הואיל ועשה נחת רוח ליצרו בשעה שחבל בחבירו מש\"ה חייב מיתה אחבלה זו אם חבלו במזיד ומה\"ט חייב אע\"פ שאינו עושה להנאתו. סמ\"ע:","\u0003פטור. \u0004 משמע דאפילו הכהו מכה שאין בה ש\"פ ואין אומרים דליחייב עליה מלקות וע\"ל סי' ת\"כ ס\"ב. שם:","\u0003ואפילו. \u0004 זהו כמו נתינת טעם דמשכחת לה דנוטל רבו כל ה' דברים דהא הריפוי צריך ליתן להרופא וק\"ל. שם:","\u0003הפוחת. \u0004 בטור כת' כגון שפצעה בפניה כו' ור\"ל דאף אחר שנתרפאת מ\"מ עומד רושם המכה בפניה ונמאסת בה וכ\"ש אם קטע ממנה אבר אחד שהוא נזק מבורר וידוע יותר. שם:","\u0003בסמוכה. \u0004 נראה דאם אינה סמוכה על שלחנו אפילו אביה רוצה ליתן לה מזונות בימי חליה כדי ליקח לעצמו משבתה המותר מדמי מזונותיה לאו כל כמיניה משא\"כ בחבל בה האב כמו שכתב הה\"מ. שם:","\u0003שלה. \u0004 פירוש אשבתה קאי דאז ניזונית בדמי שבתה אבל בדמי נזקה דמכירה וכסף קידושיה אין חילוק. שם:","\u0003אחרים. \u0004 לשון הרא\"ש דבמידי דאתי לה מעלמא וע\"י צער לא קפיד. שם:","\u0003ספר תורה. \u0004 פי' הסמ\"ע דהקטנים ילמדו מתוכה והוא פירות דס\"ת והקרן קיימת להן עד שיגדלו ועמ\"ש עוד לחלק בין דין זה להא דאיתא בש\"ס במקבל פקדון מן הקטנים דדינא נמי הכי הוא כמו כאן כו' ע\"ש:","\u0003משלמין. \u0004 ול\"ד לחש\"ו שחבלו מפני דהאשה והעבד הן בני דעת בשעה שחבלו אלא שאין להן במה לשלם והטור כת' ע\"ז וז\"ל לפיכך שמין ב\"ד החמשה דברים בשעה שחבלו באחרים וכותבין ונותנין אותו ביד הנחבל ולכשיהי' להן נכסים משלמין. שם:","\u0003הנאה. \u0004 וכת' בעה\"ת בשער ל\"ו דאם אין מי שירצה ליקח הנ\"מ או נצ\"ב בטובת הנאה יקחם הנחבל עצמו בטובת הנאה ואם יש מותר בטובת הנאה מדמי החבלה א\"צ הנחבל ליתן להאשה המותר עד שעה דקניא לנפשה \u0005(ועמ\"ש בזה בסי' שמ\"ו ס\"ק י\"ט ובסי' שפ\"ח ס\"ק י\"א. ע\"ש)\u0006:","\u0003ירצה. \u0004 ל' הטור שאף אם לא תמכרנה לו בשביל חיוב כתובה לא ימנע מלהוציאה אם ירצה שהרי א\"צ ליתן לה כתובה כיון שחייבת לו נגד החבלה עכ\"ל ועיין בתשובת רשד\"ם ס\"ס רי\"ז:"],"r":["\u0003ולא הוציא כו'. \u0004 עסי' ת\"כ סי\"ד:","\u0003הוציא כו'. \u0004 שם במתני' ושם ל\"ד ב':\n\u0003 (ליקוט) הוציא מהם כו' \u0004 וס\"ב החובל כו\" ולפ\"ד א\"ז והג\"א בפ\"ז ס\"ז ד\"ה וכל כו' אין נ\"מ האידנא אלא לענין לנדות לתקנת הגאונים (ע\"כ):","\u0003אפי' כו'. \u0004 שם ל\"ה א':","\u0003לפיכך כו'. \u0004 סנה' פ\"ד ב':","\u0003אבל. \u0004 כסתם מתני' שם ודלא כרנב\"ה וכן ברפ\"ג דכתובות:","\u0003אפי' כו'. \u0004 ר\"ל אתרו ביה וכמ\"ש בכתובות ל\"ב ב' בפירוש כו':","\u0003רבו כו'. \u0004 גטין י\"ב ועתוס' שם ד\"ה שבתו כו' ובירושלמי הביאו הרי\"ף והרא\"ש בפ' החובל ס\"ס ו' א\"ר יוחנן הקוטע יד עבדו של חבירו רבו נוטל ה' דברים והלה מתפרנס מן הצדקה כו' ע\"ש:","\u0003מי שיצא כו'. \u0004 גטין מב ב' השתא חבול כו' ולא איפשיטא ועתוס' שם ד\"ה חבלי כו' ועבה\"ג בשם הראב\"ד וכ' הב\"י דהכל מודים בזה וכמ\"ש בס\"ס מג וש\"מ:","\u0003שהרי מעשה כו'. \u0004 זהו הטעם על שבתה וכמש\"ש מודה רב כו':","\u0003וכסף כו'. \u0004 זהו הטעם על נזקה וערש\"י ד\"ה דאפחתה כו' ותוס' פז א' ד\"ה כיון כו':","\u0003וי\"א כו' וי\"א כו'. \u0004 הכל מדברי הטור וז\"ל הטור ובשבת כ' הרמב\"ם שאם היתה סמוכה על שלחן האב הוא שלו כיון שמעשה ידיה שלו וא\"א ז\"ל כ' דאפי' היא סמוכה על שולחנו אם חבלו בה אחרים הוא לעצמה ואם חבל בה הוא פטור ואם אינה סמוכה על שלחן אביה אפי' חבל בה הוא חייב ליתן לה ומ\"ש בשם הרמב\"ם שאם היתה כו' הוא דברי הרמב\"ם שהעתיק כאן בש\"ע כלשונו ודייק מדבריו שאמר שהרי מעשה ידיה כו' אלמא בסמוכה מיירי דאל\"כ אין מעשה ידיה שלו כמ\"ש בגמ' שם ואפי' למ\"ד כו ומ\"ש הטור וא\"א ז\"ל כו' ואם חבל בה הוא כו' ערא\"ש שם סז ומודה רב בשבת כו' ומיהו לקמן בברייתא כו' וכן הלכה ואם אינה סמוכה כו' ואם יש בשבת מותר כו' ולכאורה דברי הרא\"ש צ\"ע דמתחלה כ' אפי' סמוכה ובסוף כ' ואם אינה סמוכה כו' ועוד ל\"ל לומר דהא בעי למיתזן מינה הא אפילו בסמוכה דידה הוא וע\"כ פי' הטור דמ\"ש ואם אינה סמוכה כו' קאי אחבל בה הוא דאז בסמוכה השבת שלו כמ\"ש בבנו במתני' שם ס\"ח ובאינן סמוכין על שלחנו ואם הן סמוכין כו' וכ\"פ בדרישה אבל דברי הטור תמוהין מאד בין בפי' הרמב\"ם בין בפי' הרא\"ש דהיאך פי' בדברי הרא\"ש דחבלו אחרים לעולם שבת דידה והא בבריית' תניא בהדיא ולא עוד אלא אפי' אחרים כו' וכן מ\"ש בדברי הרמב\"ם דבסמוכה מיירי הא תניא בברייתא להדיא החובל בבניו ובנותיו של אחרים כו' קטנים יעשה כו' ומוקמינן בסמוכין על שלחנו דלא קפיד ועוד האיך סיים וכן החובל בבתו כו' הא בסמוכים פוטר כמ\"ש בס\"ז ואם היו סמוכים כו' וז\"ל המ\"מ שם ומזה יראה דבתו סמוכה על שולחנו אם חבל בה פטור דמ\"ל בנו או בתו ובפי' שנו בברייתא בבניו ובנותיו שלו פטור ולפ\"ז מ\"ש הרב למעלה החובל בבתו בשאינה סמוכה ומשלם השבת להעדפה וכמ\"ש בגמ' וכמ\"ש בהג\"ה למטה ונ\"ל דוקא כו' והוא דברי המ\"מ וכ\"כ לח\"מ ודיוקו של הטור מ\"ש הרמב\"ם שהרי מעשה ידיה כו' הרמב\"ם ל' הגמ' נקט מודה רב כו' ור\"ל בהעדפה אלא שהרא\"ש לא ניחא לפרושי דברי רב כן דקא' סתמא בשבת דמעשה כו' ופי' דברי רב בסמוכין ולכן כ' ומיהו לקמן בברייתא כו' וכן הלכה ומפ' דברייתא פליגא ארב וזה דחקו לטור לפרש דברי הרמב\"ם בסמוכה אבל הרמב\"ם מפ' דברי רב באינה סמוכה ולהעדפה אבל לדינא אין מחלוקת בין הרמב\"ם להרא\"ש אלא דמ\"ש הרא\"ש אפילו סמוכה תיבת אפילו ט\"ס וצ\"ל אם סמוכה כו' וז\"ש ואם אינה סמוכה כו' וקאי הכל אחבלו בה אחר' וצ\"ל דקא בעי כו' משום דגברא קפדנא הוא כמ\"ש בגמ' ולכן המותר שלו ובחבל בה איהו לא קמיירי כאן ונלמד ממש\"ש בס\"ח בבנו וכ\"ה דברי הרמב\"ם כמ\"ש המ\"מ אלא דהמותר באינה סמוכה הוא שלו דלא גרע מאחר וכמ\"ש בגמ' החובל בבתו קטנה פטור ולפ\"ז מ\"ש כאן וי\"א כו' וי\"א כו' אין מחלוקת כלל אלא הדין להיפך דוקא באין סמוכה המותר של אב בין חבלו אחרים בין חבל איהו אבל בסמוכה וחבלו אחרים שלה הוא השבת הכל ואם חבל איהו כל השבת שלו וכמו בבניו בס\"ז ועכשיו אבאר דבריהם בפרטות מ\"ש החובל כו' אם נזק כו' הוא כר\"י וכמ\"ש בגמ' אריב\"ח כו'. ומ\"ש וכן שבתה כו'. בזה אפי' רב מודה כמש\"ש מודה רב כו' ובברייתא שם ולא עוד כו' ומוקמינן בשבת ובאינה סמוכה כמש\"ש. ומ\"ש אבל צער כו'. דל\"פ ר\"י ארב אלא בנזק וכמש\"ש פציעה ס\"ד כו' ר\"ל דפציעה אין שם אלא צער וריפוי ובשת. ומ\"ש וכן החובל כו'. דמ\"ש בברייתא החובל בבתו כו' ג\"כ בשבת כמש\"ש ה\"נ בשבת ומדקא' ולא עוד כו' ואם הרישא מיירי בכל ה' דברים מאי ולא עוד ובאינה סמוכה כמש\"ש בגמ' וכמ\"ש בהג\"ה ונ\"ל כו' וכמ\"ש המ\"מ דכנ\"ל דבאינה סמוכה אין חילוק בין חבל הוא לחבלו אחרים:\n\u0003 (ליקוט) וי\"א כו' וי\"א כו'. \u0004 כ\"כ הטור כפי' בדברי הרמב\"ם והטור אבל אינו כן כמש\"ש (ע\"כ):","\u0003ילקח קרקע. \u0004 כרבב\"ה דנא' באחרונה כשיטתו בכ\"מ:","\u0003וי\"א כו'. \u0004 דגדול היה מרבב\"ה כמ\"ש בספ\"ח דשבת א\"ל ר\"ה לרבה בריה וכשיטתו ועסי' תכג ס\"ב:","\u0003וי\"א דאינו כו'. \u0004 הרא\"ש שם במתני' סח וכ\"כ תוס' שם ד\"ה וקתני. ועוד נוכל לפרש כו' אבל הרמב\"ם ס\"ל כס' ראשונה של תוס':\n\u0003 (ליקוט) סו וסז החובל כו'. \u0004 הכלל דלתוס' ורא\"ש שני הברייתות מיירי הכל בשבת והכלל דבסע\"ש החובל בבניו ובנותיו פטור בין גדולים בין קטנים ואחרים שחבלו בהן נותן להם ובאסע\"ש לעולם הוא להן לבד מבתו הקטנה שהעדפה הוא של אב בין חבל הוא או אחרים וכ\"ז בשבת אבל שאר ד' דברים לעולם הוא שלהן לבד נזק בבתו הקטנה שהוא של אב בין חבל הוא או אחרים בין סע\"ש או אינן סמוכים ובתו קטנה היינו כ\"ז שלא בגרה ולהרמב\"ם בסע\"ש וחבל בהן האב פטור מכל ה' דברים בין גדולים או קטנים (ע\"כ):\n\u0003 (ליקוט) וי\"א כו'. \u0004 נראה מדבריו שלדעת הרמב\"ם חייב בכל ה' דברים וכ\"כ המ\"מ וצע\"ג דריפוי דידה הוי וכן צער ובשת וכן בעל לא זכה בהם אלא בחלקי בשת לדברי ריב\"ב (ע\"כ):","\u0003אע\"פ כו'. \u0004 מדקא' בסיפא אבל משלמין כו' מ' אבל ברישא לא דלא כהג\"א שם ד\"ה מיהו כו' ורש\"י שם צח ב' ד\"ה ואכפייה כו' וערש\"י בכתובות פו א':","\u0003או נצ\"ב. \u0004 הרא\"ש שם דל\"ק בגמ' כ\"מ אלא לס\"ד דתמכור לגמרי משא\"כ בנצ\"ב:","\u0003מוכרת כו'. \u0004 עסי' שפח ס\"ב בהג\"ה ואשה שמסרה כו' ועמש\"ש:","\u0003אם היה כו'. \u0004 שם:","\u0003שאסור כו' וכן אם החבלה כו'. \u0004 הכל גמ' שם:","\u0003דהא קצת כו'. \u0004 דקי\"ל כריב\"ב ברפ\"ו דכתובות וכמ\"ש בא\"ע סי' פג והויכחובל בגופו כמ\"ש בגמ' שם:","\u0003ומה ששייך כו'. \u0004 ואע\"ג שאוכל פירות והיא א\"י למחול כמו בנ\"מ מ\"מ בשעה שחבל היה נכסים שא\"י לבעל ולא זכה בהן הבעל וכמש\"ש ע\"ח ב' לר\"ש ואפילו במברחת אמרינן שם עט א' עשאוהו כו' כ\"ש כה\"ג. שם:"]}],["\u0005הַגָּה: \u0010y0\u0011 כָּל חַיְבֵי מִיתוֹת בֵּית דִּין בַּזְּמַן הַזֶּה, אֵין בְּיָדֵנוּ לְהַלְקוֹתָן אוֹ לְהַגְלוֹתָן אוֹ לְהָרְגָן אוֹ לְחָבְטָן, אֶלָּא מְנַדִּין אוֹתָן וּמַבְדִּילִים אוֹתָן מִן הַקָּהָל (טוּר ס\"א בְּשֵׁם רַב נַטְרוֹנַאי גָאוֹן)\u0006. כָל זֶה מִצַּד הַדִּין, אֲבָל אִם רוֹאִין בֵּית דִּין שֶׁהוּא צֹרֶךְ שָׁעָה \u0010y1\u0011 וּמִגְדַּר מִלְּתָא, יְכוֹלִין לַעֲנֹשׁ בַּמֶּה שֶׁיִּרְצוּ \u0005(שָׁם וּבְשֵׁם תְּשׁוּבַת הַגָּאוֹן)\u0006 כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן ב'. וְדַוְקָא בְּדִינֵי נְפָשׁוֹת הַצְּרִיכִין בֵּית דִּין, אֲבָל הַנֶּהֱרָגִין בְּלֹא בֵּית דִּין נִדּוֹנִין גַּם עַתָּה, כְּמוֹ שֶׁיִּתְבָּאֵר \u0005(טוּר שָׁם)\u0006 . הָרוֹדֵף אֶת חֲבֵרוֹ לְהָרְגוֹ, \u0010y2\u0011 וְהִזְהִירוּהוּ, וַהֲרֵי הוּא רוֹדֵף אַחֲרָיו, אֲפִלּוּ הָיָה הָרוֹדֵף קָטָן, \u0010y3\u0011 הֲרֵי כָּל יִשְׂרָאֵל מְצֻוִּים לְהַצִּילוֹ בְּאֵבֶר מֵאֶבְרֵי הָרוֹדֵף. וְאִם אֵינָם יְכוֹלִים לְכַוֵּן וְלֹא לְהַצִּילוֹ אֶלָּא אִם כֵּן יַהַרְגוּ לָרוֹדֵף, הֲרֵי אֵלּוּ הוֹרְגִים אוֹתוֹ \u0010y4\u0011 אַף עַל פִּי שֶׁעֲדַיִן לֹא הָרַג. \u0005הַגָּה: (טוּר ס\"ז)\u0006 \u0010y5\u0011 הַבָּא בַּמַּחְתֶּרֶת לִגְנֹב גַּם כֵּן דִּינוֹ כְּרוֹדֵף. וְאִם יָדוּעַ שֶׁלֹּא בָּא רַק עַל עֵסֶק מָמוֹן, וְאַף אִם יַעֲמֹד בַּעַל הַמָּמוֹן נֶגְדּוֹ לֹא יַהַרְגֵהוּ, אָסוּר לְהָרְגוֹ. וְעַיֵּן בְּדִבְרֵי הַטּוּר בְּסִימָן זֶה. מִי שֶׁמְּסַכֵּן רַבִּים, כְּגוֹן \u0010y6\u0011 שֶׁעוֹסֵק בְּזִיּוּפִים בְּמָקוֹם שֶׁהַמַּלְכֻיּוֹת מַקְפִּידוֹת, דִּינוֹ כְּרוֹדֵף וּמֻתָּר לְמָסְרוֹ לַמַּלְכוּת \u0005(נִמּוּקֵי מַהֲרַ\"ם מֵרִיזְבּוּרְק)\u0006, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן שפ\"ח סי\"ב:\nלְפִיכָךְ, הַמְעֻבֶּרֶת שֶׁהִיא מַקְשָׁה לֵילֵד, מֻתָּר לַחְתֹּךְ הָעֻבָּר בְּמֵעֶיהָ, בֵּין בְּסַם בֵּין בַּיָּד, מִפְּנֵי שֶׁהוּא כְּרוֹדֵף אַחֲרֶיהָ לְהָרְגָהּ. וְאִם הוֹצִיא רֹאשׁוֹ, אֵין נוֹגְעִין בּוֹ, שֶׁאֵין דּוֹחִין נֶפֶשׁ מִפְּנֵי נֶפֶשׁ \u0010y7\u0011 וְזֶהוּ טִבְעוֹ שֶׁל עוֹלָם.\nוְכֵן הָרוֹדֵף אַחַר הַזָּכָר אוֹ אַחַר אַחַת מִכָּל הָעֲרָיוֹת \u0005לְאָנְסָהּ,\u0006 \u0010y8\u0011 חוּץ מֵהַבְּהֵמָה, מַצִּילִין אוֹתוֹ אֲפִלּוּ בְּנֶפֶשׁ הָרוֹדֵף. וְאִם רָדַף אַחַר עֶרְוָה וְתָפַס וְשָׁכַב עִמָּהּ, \u0010y9\u0011 כֵּיוָן שֶׁהֶעֱרָה בָּהּ, אַף עַל פִּי שֶׁלֹּא גָמַר בִּיאָתוֹ, אֵין מְמִיתִין אוֹתוֹ עַד עָמְדוֹ בַּדִּין.\nרָדַף אַחַר עֶרְוָה, וַאֲחֵרִים הָיוּ רוֹדְפִים אַחֲרָיו לְהַצִּילָהּ, וְאָמְרָה לָהֶם: הַנִּיחוּהוּ \u0010y10\u0011 כְּדֵי שֶׁלֹּא יַהַרְגֵנִי, \u0010y11\u0011 אֵין שׁוֹמְעִין לָהּ, אֶלָּא מַבְהִילִין אוֹתוֹ וּמוֹנְעִין אוֹתוֹ עַל יְדֵי הַכָּאַת אֵבָרָיו, וְאִם אֵינָם יְכוֹלִים בְּאֵבָרָיו אֲפִלּוּ בְּנַפְשׁוֹ. \u0005הַגָּה: הַבָּא עַל הַגּוֹיָה בְּפַרְהֶסְיָא לְעֵינֵי עֲשָׂרָה יִשְׂרְאֵלִים, \u0010y12\u0011 קַנָּאִין פּוֹגְעִים בּוֹ וּמֻתָּרִין לְהָרְגוֹ. וְדַוְקָא בִּשְׁעַת מַעֲשֶׂה, אֲבָל אִם פֵּרַשׁ אָסוּר לְהָרְגוֹ. וְדַוְקָא שֶׁהִתְרוּ בּוֹ וְלֹא פֵרַשׁ. וְדַוְקָא שֶׁבָּא הַקַּנַּאי לְהָרְגוֹ מֵעַצְמוֹ, אֲבָל אִם שָׁאַל לְבֵית דִּין \u0010y13\u0011 אֵין מוֹרִין לוֹ כָּךְ:\u0006 \u0010y14\u0011\n\u0005(אֶפִּיקוֹרוֹס מִ)\u0006 [מִּינֵי] יִשְׂרָאֵל, וְהֵם עוֹבְדֵי עֲכּוּ\"ם; אוֹ עוֹשֶׂה עֲבֵרוֹת לְהַכְעִיס, אֲפִלּוּ אָכַל נְבֵלָה אוֹ לָבַשׁ שַׁעַטְנֵז לְהַכְעִיס, \u0005(הֲרֵי זֶה)\u0006 \u0005(אֶפִּיקוֹרוֹס)\u0006 ; [מִּין] וְהַכּוֹפְרִים בַּתּוֹרָה וּבַנְּבוּאָה; מִיִּשְׂרָאֵל מִצְוָה לְהָרְגָן. אִם יֵשׁ בְּיָדוֹ \u0010y15\u0011 כֹּחַ לְהָרְגָן בְּסַיִף בְּפַרְהֶסְיָא, הוֹרֵג; וְאִם לָאו, יָבֹא עֲלֵיהֶם בַּעֲלִילוֹת עַד שֶׁיְּסַבֵּב הֲרִיגָתָן. כֵּיצַד, רָאָה אֶחָד מֵהֶם שֶׁנָּפַל לִבְאֵר, וְהַסֻלָּם בַּבְּאֵר, \u0010y16\u0011 קוֹדֵם וּמְסַלְּקוֹ, וְאוֹמֵר: הֲרֵינִי טָרוּד לְהוֹרִיד בְּנִי מֵהַגַּג וְאַחֲזִירֶנּוּ לְךָ, וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ. אֲבָל \u0010y17\u0011 הַגּוֹיִים שֶׁאֵין בֵּינֵינוּ וּבֵינָם מִלְחָמָה, וְרוֹעֶה בְּהֵמָה דַקָּה מִיִּשְׂרָאֵל \u0010y18\u0011 בְּמָקוֹם שֶׁהַשָּׂדוֹת הֵם שֶׁל יִשְׂרָאֵל, וְכַיּוֹצֵא בָּהֶם, אֵין מְסוֹבְּבִין לָהֶם הַמִּיתָה, וְאָסוּר לַהֲצִילָן. \u0005(שָׁם [פ\"ד מֵרוֹצֵח] וי\"א ע\"ל סל\"ד סי\"ג וּבְסִימָן ת\"ט)\u0006. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּיִשְׂרָאֵל בַּעַל עֲבֵרוֹת וְהוּא עוֹמֵד בְּרִשְׁעוֹ וְשׁוֹנֶה בּוֹ תָּמִיד, כְּגוֹן רוֹעֶה בְּהֵמָה דַקָּה שֶׁפָּקְרוּ בְּגָזֵל וְהֵם הוֹלְכִים בְּאִוַּלְתָּם; אֲבָל יִשְׂרָאֵל בַּעַל עֲבֵרוֹת שֶׁאֵינוֹ עוֹמֵד בְּרִשְׁעוֹ תָּמִיד, אֶלָּא עוֹשֶׂה עֲבֵרוֹת לַהֲנָאַת עַצְמוֹ, \u0010y19\u0011 כְּגוֹן אוֹכֵל נְבֵלוֹת לְתֵיאָבוֹן, \u0010y20\u0011 \u0010c0\u0011 מִצְוָה לְהַצִּילוֹ, וְאָסוּר לַעֲמֹד עַל דָּמוֹ. \u0005(שָׁם ד\"ג)\u0006 \u0005עַיֵּן בְּיוֹרֶה דֵעָה סִימָן קנ\"ח.\u0006",["\u0003כל חייבי מיתות ב\"ד בזמן הזה אין בידינו להלקותו כו' \u0004 כל' זה כ' ג\"כ הטור בשם רב נטרונאי גאון והא דכ' בחייבי מיתות וכ' עליהן להלקותן ולחבטן כתבתי בפרישה דנראה דה\"ק ל\"מ דאין דנין הד' מיתות עצמן כל א' כפי מה שצותה התורה אלא אפי' לעשות במקומו עונש אחר לדונו אין בידינו מצד הדין כ\"א מצד מגדר מילתא ע\"ש:","\u0003ומגדר מילתא כו' \u0004 פי' לעשות דין לזה שכבר נרצח או מוכה אין לנו לעשותו אבל למגדר מילתא אם יש לחוש שיעשהו ג\"כ אחרים להבא יגדרוהו כדי שלא יעשוהו עוד ועפ\"ר:","\u0003והזהירוהו כו'. \u0004 פי' א\"צ לעשות בו התראה ממש ושיקבל ההתראה אלא אמרינן לו זה שאתה רודף אחריו ישראל הוא והתורה אמרה שופך דם האדם באדם דמו ישפך ובדיעבד אפי' לא אמרו לו אפי' זה אפ\"ה מצילין הנרדף בנפשו של רודף וראיה מקטן שרודף דאיני בר הבחנת האזהרה הוא וקאמר גם כן הורגין אתו להציל ממנו ועפ\"ר:","\u0003הרי כל ישראל מצווי' להצילו. \u0004 למדו זה מדכתיב [בפרשת כי תצא] ולנערה לא תעשה דבר צעקה (בשדה) ואין מושיע לה משמע הא אם יש לה מושיע להצילה מזה הבא לאונסה היינו מצווין להושיע אותה מידו במאי דאפשר וממנו למדנו דין רודף להרוג לחבירו כי בתר קרא הנ\"ל מיד כתיב כי כאשר יקום איש על רעהו כו' ודרשו ואמרו ה\"ז בא ללמד ונמצא למד רוצח מנערה המאורס' מה נער' המאורס' ניתן להציל' בנפש זה הבא לאונסה וכמ\"ש כן דינו של הרודף אחר חבירו להרגו וגם למדנו נערה המאורס' מרוצח ואין כאן מקומו לכתבו:","\u0003אע\"פ שעדיין לא הרג \u0004 לאו למימרא דמכ\"ש אם כבר הרגו דחוזרים והורגים להרוצח דז\"א בזמנינו דאין דנין מיתת ב\"ד אלא ל' הרמב\"ם תפס והוא כ\"כ אמ\"ש שם לפני זה דין רוצח שאין הורגין אותו עד שיגמור דינו למיתה אחר שהרג אזה כתב דברודף אין הדין כן אלא ממיתין אותו אע\"פ שלא הרג ולא נגמר דינו בשום דבר:","\u0003הבא במחתרת כו'. \u0004 דין למדו מדכתיב בפ' משפטים] אם במחתרת ימצא הגנב והכה ומת אין לו דמים [פי' כאלו אין לו דם לזה הנרצח והוא מת מעיקרא] אם זרחה השמש עליו דמים לו והטעם דאין לו דמים מפני שכל גנב יודע שאין אדם עומד ורואה שגונבים ממנו ממונו ושותק ומתחלה בא אדעתא דהכי שבאם יעמוד בע\"ה לנגדו למחות בידו אזי יעמוד עליו להרגו וה\"ז כרודף ומותר להציל עצמו בנפשו ומ\"ש אם זרחה עליו השמש פשוטו של מקרא הוא דאם נמצא הגנב במחתרת ביום בעת זריחת השמש אז אמרינן דודאי לא בא הגנב על עסקי מיתה כי יודע שביום יהיו עוזרים הרבה לזה הנגנב כשיעמוד עליו להרגו ובודאי לא בא אלא אם יראה שיהיה הב\"ה במקום שגונב שישמיט ויצא אלא דא\"כ לא הל\"ל אלא ואם זרחה השמש \"עליו למה לי מ\"ה דרשו דבא ללמדינו שאם הוא ברור לנו כשמש שלא בא להרוג לב\"ה שבא לגנוב ממנו כגון שידוע הוא שאוהב נאמן הוא לו או שחתר האב לבנו דאז אפי' אין ידוע לנו אלא מסתמא אמרי' דהאב לבנו אינו בא להרוג אלא לגנוב יש לו דמים לאביו או לאוהב הנאמן בהריגתן כשבאו במחתרת אבל בן הבא על אביו לא אמרי' מסתמא שלא בא להרוג כן הוא בגמ' ועיין בטור מ\"ש עוד מזה פלוגתות ודעות:","\u0003שעוסק בזיופי' \u0004 כתב שם כגון מגזמי' בדליק' או שעוסקי' בחתיכות המטבעות ומ\"ש שהמלכיות מקפידות דקדק לכתוב שהמלכיות מקפידות דאל\"כ אין דינו כרודף וכ\"כ בהדיא שם בנימוקי מהר\"ם מרוזב\"ורק.","\u0003וזה טבעו של עולם \u0004 הוצרך לכתוב זה של\"ת הולד הרי הוא רודף ויצילו את אמו בנפשו קמ\"ל כיון שטבע של עולם בכך אין דין רודף עליו ואעפ\"כ בעודו במיעיה מותר לחתכו אע\"פ שהוא חי שכל שלא יצא לאויר העולם אין שם נפש עליו והא ראייה דהנוגף אשה הרה ויצאו ילדיה ומתו משלם דמי הולדות ואין שם רוצח ומיתה עליו וכמ\"ש לעיל סי' תכ\"ג:","\u0003חוץ מהבהמה \u0004 בגמ' ס\"פ בן סורר ומורה ילפי' דאין ניתן להצילו בנפשו של רודף אלא ערוה שיש בו קלון ופגם לנרדף כגון נערה המאורסה שנפגמה וזכר שאינו עומד להשתמש בו ויש בו קלון טובא וילפינין להו מדכתיב ולנערה לא תעשה דבר כו' עד ואין מושיע לה וכנ\"ל וכתיב נער וקרינן נערה ודרשינן הקרי והכתיב דנער ר\"ל הזכר ומיתורא דהמקרא דרשי' אפי' שאר עריות ויש בו גם כן מיעוט וממעטינן מיניה הרודף אחר הבהמה או לחלל שבת כו' דלית בהו קלון ופגם כלל:","\u0003כיון שהערה בה \u0004 דאין הורגין אותו אלא קודם שנפגמה ועפ\"ר:","\u0003כדי שלא יהרגני \u0004 פי' קודם שתשיגהו ימית אותי כשיראה שאת' רוצים להמית אותו בשבילי:","\u0003אין שומעין לה \u0004 משמע דוקא בכה\"ג דנוכל לומר דמקפדת על פגמה אלא שחשה לנפשה שמא ימיתנה ולכן אין שומעין לה דהתורה הקפיד' אפגם כזה שלא יעשה אבל אם אומרת הניחוהו ואל תהרגהו דנראה מדבריה שאינה חוששת אפגמ' בזה שומעין לה וכן משמע לשון הברייתא והרמב\"ם שכתבו שלא יהרגיני כמ\"ש המחבר אבל בטור כתב דאפי' בכה\"ג אין שומעין לה וכתב הב\"י דס\"ל דאפי' בכה\"ג י\"ל דמקפד' שלא יפגמה אלא שאינה רוצה שיהרג הרודף על ידה:","\u0003קנאין פוגעין בו. \u0004 ל' הטורמי שמקנה לשם יכול להורגו עכ\"ל והוא נלמד ממעשה דפנחס עם זמרי והוא הלכה למשה מסיני:","\u0003אין מורין לו \u0004 בטור מסיים וכ' ז\"ל ואפי' אם לא פירש והרג הבועל להמקנא אינו נהרג עליו עכ\"ל והוא מימר' בגמ' והתימא שהשמיטו מור\"ם ז\"ל ואפשר דמשום דהטור סיים וכ' אחר זה עוד ז\"ל הרג אדם אחר להמקנא נהרג עליו עכ\"ל וכ' ב\"י עליו דהוא פשוט ולא ניתן להכתב מרוב פשיטות ואגב שיטפא שהשמיט מור\"ם לאותו דין מרוב פשיטתו השמיט עמו ג\"כ זה דבחדא בבא כתבינהו הטור ע\"ש והיותר נרא' דמ\"ה השמיטו משום דלא כ' המחבר אלא הני עניני מיתה דיש בהן מגדר מילת' משא\"כ בזה דהבועל יכול לפרוש ולהרוג להמקנא דאין בו מגדר מילתא ואדרבה הטור אגב שיטפא לרבותא כתבו וק\"ל:","\u0003אפיקורס מישראל והם כו' \u0004 המחבר נמשך אחר נוסחת הרמב\"ם שבדפוס כסף משנה דספ\"ד דהל' רוצח ושמירת נפש אלא ששם לא כתב אחר זה כמ\"ש המחבר ז\"ל והאפיקורסי' והם שכופרי' בתורה כו' דלפ\"ז היא לשון שאינו מדוקדק דהרי כבר כ' דהאפיקורס הוא עכו\"ם כו' אלא כ' שם ז\"ל האפיקורסי' הן שעובדי' עכו\"ם כו' עד שעטנז להכעיס ה\"ז אפיקורס ושכופרין בתורה כו' ע\"ש אבל נוסח זה אינו עולה יפה דלפ\"ז הא שכ' ושכופרין בתורה אמאי קאי לכך נראה יותר מדוקדק נוסח ל' הרמב\"ם דדפוס גדול דכתב בו ז\"ל המינים מישראל והן ע\"א כו' עד ה\"ז אפיקורס והן שכופרים כו' וכן מצאתי בדפוס ישן נושן של הרמב\"ם וכן הוא לשון הטור ע\"ש:","\u0003להעבירן \u0004 בע\"ש כתב דנראה לו הטעם דמצוה להעבירן לכתחלה דומי' דעיר הנידחת וזה אינו נרא' לי דדוק' ביושבי עיר כולה או רובה הנידחת מצות' בסייף אבל ביחידי' בעובדי כו\"ם דינם בסקילה אלא שאין אנו לע\"ע דנין דין ד' מיתות האמורים בתורה מ\"ה קאמר מעבירין ונראה דל\"ד קאמר אלא כאלו אמר אם יש בידינו כח להעבירן הרי מצוה עלינו להעבירן לעין כל והנשארי' ישמעו וייראו ואם לאו לפחות יסבבו להן וכדמסיק:","\u0003קודם ומסלקו \u0004 כל' זה כ\"כ במיימוני ולפי הנראה היה נ\"ל למחוק הוי\"ו ומסלקו וה\"ק אם הסולם בבור קודם בואו אזי מסלקו משם ואומר הריני טרוד כו' ולפי הנוסח שלפנינו צריכין לפרש קודם ל' מקדים דמקדים נפשו ומסלקו:","\u0003שאין בינם ובינינו מלחמה \u0004 דאלו יש מלחמה ע\"ז אמרו טוב שבעכו\"ם הרוג והיינו מצו' להורידן ולסבב עליהן המיתה וכ\"כ התו' ועיין בספר שבט יהודה כ' בזה תשובה למינים והוא שטוב שבמדות העכו\"ם הוא זה שדנין דין הריגה ומיתה לחוטאין ואין מחפשין זכות לעושי עולה ועיין בי\"ד סי' קנ\"ח מדינים אלו:","\u0003במקום שהשדות הן של ישראל \u0004 פי' ל\"ד ארץ ישראל אלא בכ\"מ שיש לישראל שדות וכ\"כ לעיל סי' ל\"ד סי\"ג ואע\"ג דהמחבר כ' לעיל סי' ת\"ט דמותר לגדל בסוריא ומדברות בהמה דקה ומשמע לכאורה דאפי' דיש להישראל הדרים שם שדות דאל\"כ אפי' בא\"י נמי שרי וכדמסיק שם הרי לפנינו דדוקא בא\"י אסור היינו לענין איסור גידול בהמה דקה ומשום גזירה שמא יבא לרעות בשדות ישראל דלא גזרו כולי האי אלא בא\"י ומשום פסידא דא\"י אבל ודאי דאסור לרעותן בשדות של ישראל אפילו בשאר ארצות ובבהמה דקה החמירו ארועה שלהן דמסתמא אפי' אין רואה אותו שמרעה אותן בשדות ישראל כיון דהן קופצין ואזלי מעצמן ה\"ל לסלק מרעייתן ואף דלעיל סימן ל\"ד סי\"ג כ' הטור והמחבר שם הרועים בהמה גסה נמי פסולים הא כ' שם בצדו דהיינו דוקא בהמות של עצמן ומשום דחשדינן ליה שיניחם לרעות בשדות ישראל להנאתו משא\"כ כאן דמיירי גם ברועה בהמות של אחרים א\"נ לענין דאסור להצילם לא אמרו כי אם בהמה דקה ועמ\"ש עוד שם בסי' ל\"ד:","\u0003כגון אוכל נבילות לתיאבון. \u0004 פי' כשאינו מוצא בשר כשר כזה אוכל נבילות למלאות תאותו ולהכעיס מקרי שיש בנמצא בשר כזה ואוכל נבילה להכעיס מצות בוראו ית':","\u0003מצוה להצילו. \u0004 הב\"י כתב החילוק שיש בין מומר אוכל נבילות לתיאבון ובין רועה בהמה דקה (דאף שגם רועה לתאבון ולהנאת עצמו מניחו לרעות בשדות ישראל) דהרועה עושה עבירה מידי יום ביום וכל היום משא\"כ אוכל נבילות לתאבון ובפריש' כתבתי עוד חילוק והוא דהאוכל נבילות לתאבון אינו חוטא אלא להש\"י משא\"כ רועה דגוזל וחוטא לחבירו ישראל ע\"ש:"],["\u0003 מצוה להצילו כו'. \u0004 ומ\"מ אין מחויב לפדותו אם נשבע אלא דאם רוצה לפדותו אין איסור בדבר ב\"י ומור\"ם בי\"ד סי' רנ\"א ס\"ב ובסי' רנ\"ב שם סעיף ו' וב\"ח שם:"],"\u0005הַגָּה: \u0010y0\u0011 כָּל חַיְבֵי מִיתוֹת בֵּית דִּין בַּזְּמַן הַזֶּה, אֵין \u0010r0\u0011 בְּיָדֵנוּ לְהַלְקוֹתָן \u0010r1\u0011 אוֹ לְהַגְלוֹתָן \u0010r2\u0011 אוֹ לְהָרְגָן \u0010r3\u0011 אוֹ לְחָבְטָן, \u0010r4\u0011 אֶלָּא מְנַדִּין אוֹתָן וּמַבְדִּילִים אוֹתָן מִן הַקָּהָל (טוּר ס\"א בְּשֵׁם רַב נַטְרוֹנַאי גָאוֹן)\u0006. \u0010r5\u0011 כָל זֶה מִצַּד הַדִּין, אֲבָל אִם רוֹאִין בֵּית דִּין שֶׁהוּא צֹרֶךְ שָׁעָה \u0010y1\u0011 וּמִגְדַּר מִלְּתָא, יְכוֹלִין לַעֲנֹשׁ בַּמֶּה שֶׁיִּרְצוּ \u0005(שָׁם \u0010g0\u0011 וּבְשֵׁם תְּשׁוּבַת הַגָּאוֹן)\u0006 כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן ב'. \u0010r6\u0011 וְדַוְקָא בְּדִינֵי נְפָשׁוֹת הַצְּרִיכִין בֵּית דִּין, אֲבָל הַנֶּהֱרָגִין בְּלֹא בֵּית דִּין נִדּוֹנִין גַּם עַתָּה, כְּמוֹ שֶׁיִּתְבָּאֵר \u0005(טוּר שָׁם)\u0006 \u0010g1\u0011 . הָרוֹדֵף אֶת חֲבֵרוֹ לְהָרְגוֹ, \u0010y2\u0011 \u0010t0\u0011 \u0010r7\u0011 וְהִזְהִירוּהוּ, וַהֲרֵי הוּא רוֹדֵף אַחֲרָיו, \u0010g2\u0011 אֲפִלּוּ הָיָה הָרוֹדֵף קָטָן, \u0010y3\u0011 הֲרֵי כָּל יִשְׂרָאֵל מְצֻוִּים לְהַצִּילוֹ \u0010g3\u0011 בְּאֵבֶר מֵאֶבְרֵי הָרוֹדֵף. וְאִם אֵינָם יְכוֹלִים לְכַוֵּן וְלֹא לְהַצִּילוֹ אֶלָּא אִם כֵּן יַהַרְגוּ לָרוֹדֵף, הֲרֵי אֵלּוּ הוֹרְגִים אוֹתוֹ \u0010y4\u0011 \u0010g4\u0011 \u0010r8\u0011 אַף עַל פִּי שֶׁעֲדַיִן לֹא הָרַג. \u0005הַגָּה: \u0010g5\u0011 (טוּר ס\"ז)\u0006 \u0010y5\u0011 הַבָּא בַּמַּחְתֶּרֶת לִגְנֹב גַּם כֵּן דִּינוֹ כְּרוֹדֵף. \u0010r9\u0011 וְאִם יָדוּעַ שֶׁלֹּא בָּא רַק עַל עֵסֶק מָמוֹן, וְאַף אִם יַעֲמֹד בַּעַל הַמָּמוֹן נֶגְדּוֹ לֹא יַהַרְגֵהוּ, אָסוּר לְהָרְגוֹ. וְעַיֵּן בְּדִבְרֵי הַטּוּר בְּסִימָן זֶה. \u0010r10\u0011 מִי שֶׁמְּסַכֵּן רַבִּים, כְּגוֹן \u0010y6\u0011 שֶׁעוֹסֵק \u0010t1\u0011 בְּזִיּוּפִים בְּמָקוֹם שֶׁהַמַּלְכֻיּוֹת מַקְפִּידוֹת, דִּינוֹ כְּרוֹדֵף וּמֻתָּר לְמָסְרוֹ לַמַּלְכוּת \u0005(נִמּוּקֵי מַהֲרַ\"ם מֵרִיזְבּוּרְק)\u0006, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן שפ\"ח סי\"ב: \u0010g6\u0011 \u0010r11\u0011\nלְפִיכָךְ, הַמְעֻבֶּרֶת שֶׁהִיא מַקְשָׁה לֵילֵד, מֻתָּר לַחְתֹּךְ הָעֻבָּר בְּמֵעֶיהָ, בֵּין בְּסַם בֵּין בַּיָּד, מִפְּנֵי שֶׁהוּא כְּרוֹדֵף אַחֲרֶיהָ לְהָרְגָהּ. וְאִם הוֹצִיא רֹאשׁוֹ, אֵין נוֹגְעִין בּוֹ, שֶׁאֵין דּוֹחִין נֶפֶשׁ מִפְּנֵי נֶפֶשׁ \u0010y7\u0011 \u0010g7\u0011 \u0010r12\u0011 וְזֶהוּ טִבְעוֹ שֶׁל \u0010t2\u0011 עוֹלָם. \u0010g8\u0011\nוְכֵן הָרוֹדֵף אַחַר הַזָּכָר \u0010r13\u0011 אוֹ אַחַר אַחַת מִכָּל הָעֲרָיוֹת \u0005לְאָנְסָהּ,\u0006 \u0010y8\u0011 חוּץ \u0010t3\u0011 מֵהַבְּהֵמָה, מַצִּילִין אוֹתוֹ אֲפִלּוּ בְּנֶפֶשׁ הָרוֹדֵף. \u0010g9\u0011 וְאִם רָדַף אַחַר עֶרְוָה וְתָפַס וְשָׁכַב עִמָּהּ, \u0010y9\u0011 \u0010r14\u0011 כֵּיוָן שֶׁהֶעֱרָה בָּהּ, אַף עַל פִּי שֶׁלֹּא גָמַר בִּיאָתוֹ, אֵין מְמִיתִין אוֹתוֹ עַד עָמְדוֹ בַּדִּין. \u0010g10\u0011\nרָדַף אַחַר עֶרְוָה, וַאֲחֵרִים הָיוּ רוֹדְפִים אַחֲרָיו לְהַצִּילָהּ, וְאָמְרָה לָהֶם: הַנִּיחוּהוּ \u0010y10\u0011 כְּדֵי שֶׁלֹּא \u0010t4\u0011 יַהַרְגֵנִי, \u0010y11\u0011 אֵין שׁוֹמְעִין לָהּ, אֶלָּא מַבְהִילִין אוֹתוֹ וּמוֹנְעִין אוֹתוֹ עַל יְדֵי הַכָּאַת אֵבָרָיו, וְאִם אֵינָם יְכוֹלִים בְּאֵבָרָיו אֲפִלּוּ בְּנַפְשׁוֹ. \u0005הַגָּה: \u0010g11\u0011 הַבָּא עַל \u0010g12\u0011 הַגּוֹיָה בְּפַרְהֶסְיָא \u0010r15\u0011 לְעֵינֵי עֲשָׂרָה יִשְׂרְאֵלִים, \u0010y12\u0011 קַנָּאִין פּוֹגְעִים בּוֹ וּמֻתָּרִין לְהָרְגוֹ. \u0010g13\u0011 וְדַוְקָא בִּשְׁעַת מַעֲשֶׂה, אֲבָל אִם פֵּרַשׁ אָסוּר לְהָרְגוֹ. \u0010g14\u0011 \u0010r16\u0011 וְדַוְקָא שֶׁהִתְרוּ בּוֹ וְלֹא \u0010g15\u0011 פֵרַשׁ. וְדַוְקָא שֶׁבָּא הַקַּנַּאי לְהָרְגוֹ מֵעַצְמוֹ, אֲבָל אִם שָׁאַל לְבֵית דִּין \u0010y13\u0011 אֵין מוֹרִין לוֹ \u0010t5\u0011 כָּךְ:\u0006 \u0010y14\u0011 \u0010g16\u0011 \u0010r17\u0011\n\u0005(אֶפִּיקוֹרוֹס מִ)\u0006 [מִּינֵי] יִשְׂרָאֵל, וְהֵם עוֹבְדֵי עֲכּוּ\"ם; אוֹ עוֹשֶׂה עֲבֵרוֹת לְהַכְעִיס, אֲפִלּוּ אָכַל נְבֵלָה אוֹ לָבַשׁ שַׁעַטְנֵז לְהַכְעִיס, \u0010g17\u0011 \u0005(הֲרֵי זֶה)\u0006 \u0005(אֶפִּיקוֹרוֹס)\u0006 ; [מִּין] וְהַכּוֹפְרִים בַּתּוֹרָה וּבַנְּבוּאָה; מִיִּשְׂרָאֵל מִצְוָה \u0010g18\u0011 \u0010r18\u0011 לְהָרְגָן. אִם יֵשׁ בְּיָדוֹ \u0010y15\u0011 כֹּחַ לְהָרְגָן בְּסַיִף בְּפַרְהֶסְיָא, הוֹרֵג; וְאִם לָאו, יָבֹא עֲלֵיהֶם בַּעֲלִילוֹת עַד שֶׁיְּסַבֵּב הֲרִיגָתָן. כֵּיצַד, רָאָה אֶחָד מֵהֶם שֶׁנָּפַל לִבְאֵר, וְהַסֻלָּם בַּבְּאֵר, \u0010y16\u0011 קוֹדֵם וּמְסַלְּקוֹ, וְאוֹמֵר: הֲרֵינִי טָרוּד לְהוֹרִיד בְּנִי מֵהַגַּג וְאַחֲזִירֶנּוּ לְךָ, וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ. \u0010g19\u0011 אֲבָל \u0010y17\u0011 \u0010r19\u0011 הַגּוֹיִים שֶׁאֵין בֵּינֵינוּ וּבֵינָם מִלְחָמָה, וְרוֹעֶה \u0010r20\u0011 בְּהֵמָה \u0010t6\u0011 דַקָּה מִיִּשְׂרָאֵל \u0010y18\u0011 בְּמָקוֹם שֶׁהַשָּׂדוֹת הֵם שֶׁל יִשְׂרָאֵל, וְכַיּוֹצֵא בָּהֶם, אֵין מְסוֹבְּבִין לָהֶם \u0010g20\u0011 הַמִּיתָה, וְאָסוּר לַהֲצִילָן. \u0005(שָׁם [פ\"ד מֵרוֹצֵח] וי\"א ע\"ל סל\"ד סי\"ג וּבְסִימָן ת\"ט)\u0006. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּיִשְׂרָאֵל בַּעַל עֲבֵרוֹת וְהוּא עוֹמֵד בְּרִשְׁעוֹ וְשׁוֹנֶה בּוֹ תָּמִיד, כְּגוֹן רוֹעֶה בְּהֵמָה דַקָּה שֶׁפָּקְרוּ בְּגָזֵל וְהֵם הוֹלְכִים בְּאִוַּלְתָּם; אֲבָל יִשְׂרָאֵל בַּעַל עֲבֵרוֹת שֶׁאֵינוֹ עוֹמֵד בְּרִשְׁעוֹ תָּמִיד, \u0010g21\u0011 אֶלָּא עוֹשֶׂה עֲבֵרוֹת לַהֲנָאַת עַצְמוֹ, \u0010y19\u0011 \u0010r21\u0011 כְּגוֹן אוֹכֵל \u0010g22\u0011 \u0010t7\u0011 נְבֵלוֹת לְתֵיאָבוֹן, \u0010y20\u0011 \u0010c0\u0011 מִצְוָה \u0010t8\u0011 לְהַצִּילוֹ, וְאָסוּר לַעֲמֹד עַל דָּמוֹ. \u0005(שָׁם ד\"ג)\u0006 \u0005עַיֵּן בְּיוֹרֶה דֵעָה סִימָן קנ\"ח.\u0006",{"g":["\u0003א) מהא דא\"ר אלעזר בן יעקב שמעתי מכין ועונשין וכו'\u0004 פרק נגמר הדין דמ\"ז ע\"א","ב) רמב\"ם פ\"א מהלכות רוצח דין ו' וטור ס\"ג משנה וגמרא בסנהדרין ס\"פ בן סורר ומורה דף פ\"ב וע\"ג:","ג) מימרא דרב הונא שם","\u0003ד) ברייתא משמיה דר' יונתן בן שאול שם ריש דף עד ובכמה דוכתי:\u0004 ","ה) כ' ה\"ה צ\"ל דהכי קאמר כיון שלא הרג לא היה ראוי להרגו ואעפ\"כ הורגין אותו כדי להציל את הנרדף דאלו כבר הרגו אינם רשאין להרגו","\u0003ו) משנה וגמרא בפרק בן סורר ומורה (סנהדרין דף ע\"א) וע\"ב:\u0004 ","\u0003ז) שם ד\"ט משנה ספ\"ז דאהלות:\u0004 ","ח) כ' ה\"ה שזהו מ\"ש שם בסנה' דף עב ע\"ב הא דמקשי אמימרא דרב הונא קטן וכו' ממשנה דאהלות הנזכר ומשני שאני התם דמשמיא קא רדפי לה","ט) שם משנה שם סוף דף ע\"ב","י) שם די\"ב בברייתא שם דף ע\"ג ע\"א וכ' ה\"ה זה הולך על השורש שקדם שמחוייבי מיתות שעברו ועשו אין ממיתים אותן עד שיגמור דינם בב\"ד וזה כיון שהערה כבר עשה העבירה","\u0003כ) שם דף י\"ג שם בברייתא פלוגתא דר' יהודה ורבנן ופסק כרבנן:\u0004 ","ל) טור ס\"ט ורמב\"ם פי\"ב מהלכות איסורי ביאה משנה פרק הנשרפין (סנהדרין דף פ\"א ע\"ב)","\u0003מ) ע\"א דף ל\"ו ע\"ב:\u0004 ","נ) מימרא דר' יוחנן סנהדרין דף פ\"ב ע\"א","ס) הראב\"ד בהשגות","ע) שם במימרא דר\"י","פ) ל' הרמב\"ם שם פרק ד' דין י' מברייתא פ\"ב דע\"א דף כ\"ו ע\"ב וסוגיא דגמרא שם ויש נוסחא אחרת בב\"י והעתיק' בי\"ד סי' קנ\"ח סי\"א וע\"ש","\u0003צ) הן הוא ברמב\"ם שם וכ' הכ\"מ בפלוגתא דרב אחא ורבינא וכו'\u0004 שם פסק כמ\"ד מותר להכעיס אפיקורס הוא ועוד דר' אבהו ור' יוחנן סברי הכי שם:","\u0003ק) שם בברייתא וכדמפרשי לה האמוראי שם:\u0004 ","ר) כלומר דהא דתני' בסוף קידושין ובמ\"ש טוב שבעכו\"ם הרוג היינו בשעת מלחמה וכמ\"ש התוספת בשם הירושלמי:","ש) לא אמרו חז\"ל דבר זה אלא על העכו\"ם שהיו בזמניהם שהיו עובדי כוכבים ומזלות ולא היו מאמינים ביציאת מצרים ובחדוש העולם אבל אלו הגוים אשר אנחנו אומה ישראלים חוסים בצל שלהם ומפוזרים ביניהם הם מאמינים בחדוש העולם וביציאת מצרים ובעיקרי הדת וכל כוונתם לעושה שמים וארץ כמ\"ש הפוסקים והביאו רמ\"א בא\"ח סי' קכ\"ו בהגה לא די שאין איסור להצילן אלא אפילו אנחנו מחוייבים להתפלל בשלומם וכאשר האריך בזה בעל מעשה ה' בסדר הגדה בפסוק שפוך חמתך על הגוים אשר לא ידעוך שדוד המע\"ה התפלל לשפוך על העכו\"ם אשר אינם מאמינים בחידוש העולם וענין האותות והנפלאות אשר עשה השי\"ת לנו במצרים ובמתן תורה אבל הגוים אלו אשר אנחנו בצילם חיים וחוסי' תחת כנפיהם הם מאמיני' בכל אלה כמ\"ש ועל משמרתינו אנחנו עומדי' להתפלל תמיד על שלום המלכות והשרים להצלחתם ועל כל מדינות ומקומות ממשלתיהם וכ' הרמב\"ם דהלכה כר' יהושע בפרק חלק (סנהדרין דף ק\"ה ע\"א) דאפילו חסידי עכו\"ם יש להם חלק לעוה\"ב","ת) כ' הכ\"מ פי' ואינו עומד ברשעו תמיד לאפוקי רועה בהמה דקה אף על פי שעושים להנאת עצמן בשביל חמדת ממון מ\"מ הוא עומד ברשעו תמיד","לאפוקי שאם אוכל נבילות להכעיס אע\"פ שאינו עומד ברשעו הרי הוא בכלל האפיקורסי' כמה שקדם בתחלת הסעיף"],"t":["\u0003והזהירוהו. \u0004 פירוש א\"צ לעשות בו התראה ממש ושיקבל ההתראה אלא אמרינן לו זה שאתה רודף אחריו ישראל הוא והתורה אמרה שופך דם האדם וגו' ובדיעבד אפילו אם גם זה לא אמרו לו אפילו הכי מצילין הנרדף בנפשו של רודף וראיה מקטן שרודף דאינו בר הבחנת אזהרה וקאמר גם כן דהורגין אותו להציל ממנו. סמ\"ע:","\u0003בזיופים. \u0004 כגון שמגזמין בדליקה או שעוסקים בחתיכת המטבעות ואם אין המלכיות מקפידות אין דינו כרודף כן כת' בנימוקי מהר\"ם שם להדיא. שם:","\u0003עולם. \u0004 הוצרך לכתוב זה של\"ת הולד הרי הוא רודף ויצילו את אמו בנפשו קמ\"ל כיון שטבע של עולם בכך אין דין רודף עליו ומכל מקום בעודו במעיה מותר לחתכו אע\"פ שהוא חי שכל שלא יצא לאויר העולם אין שם נפש עליו והראיה מנגף אשה ויצאו ילדיה ומתו משלם דמי הולדות ואין שם רוצח ומיתה עליו וכמו שכתוב בסי' תכ\"ג. שם:","\u0003מהבהמה. \u0004 דאין ניתן להצילו בנפשו של רודף אלא ערוה שיש בה קלון ופגם לנרדף כן הוא בש\"ס ס\"פ בן סורר. שם:","\u0003יהרגני. \u0004 פירוש קודם שתשיגוהו ימית אותי כשיראה שאתם רוצים להמית אותו בשבילי ומשמע דדוקא בכה\"ג דנוכל לומר דמקפדת על פגמה אלא שחוששת לנפשה שמא יהרגנה ולכך אין שומעין לה דהתורה הקפידה אפגם כזה שלא יעשה אבל אם אומרת הניחוהו ואל תהרגוהו דנראה מדבריה דאינה חוששת אפגמה בזה שומעין לה וכן משמע לשון הברייתא והרמב\"ם שכתבו שלא יהרגני כמ\"ש המחבר אבל בטור כת' דאפילו בכה\"ג אין שומעין לה וכת' הב\"י דסבירא ליה דאפי' בכה\"ג יש לו' דמקפדת שלא יפגמה אלא שאינה רוצה שיהרג הרודף על ידה. שם:","\u0003כך. \u0004 עיין בטור שביאר עוד דינים בזה ע\"ש:","\u0003דקה. \u0004 ע\"ל סי' ל\"ד סי\"ג ובסי' ת\"ט:","\u0003לתאבון. \u0004 דהוא אינו חוטא אלא להש\"י משא\"כ רועה דגוזל וחוטא לחבירו ישראל. סמ\"ע:","\u0003להצילו. \u0004 ומכל מקום אינו מחויב לפדותו אם נשבה אלא דאם רוצה לפדותו אין איסור בדבר. ב\"י והרמ\"א בי\"ד סי' רנ\"א ס\"ב ובסי' רנ\"ב ס\"ו וב\"ח שם. ש\"ך:"],"r":["\u0003להלקותן. \u0004 דבעינן מומחין כמ\"ש הרמב\"ם בפט\"ז מה' סנהדרין הלכה ב' ג' מלקין בזה\"ז בכ\"מ מן התורה בפני שלשה סמוכין אבל לא בפני הדיוטות וכל מלקות שמלקין דייני ח\"ל בכ\"מ אינה אלא מכות מרדות וכמ\"ש בפ\"ח דב\"ק דלא עבדינן שליחותייהו אלא בהודאות והלוואות דחסרון כיס כו':","\u0003או להגלותן. \u0004 שאין לנו ערי מקלט. טור. ובספרי והקריתם לכם ערים אחר ירושה וישיבה הכתוב מדבר או אינו מדבר אלא בכניסתן לארץ מיד ת\"ל כי יכרית ד' אלקיך את הגוים כו':","\u0003או להרגן. \u0004 סנהדרין נב ב' ואפילו מ' שנה קודם חורבן בטלו כמש\"ש מ\"א א':","\u0003או לחבטן. \u0004 הב\"ח הגיה לחבשן ר\"ל כמש\"ש פ\"א בי ההורג נפש שלא בעדים כו' והיינו מיתה אבל מכות מרדות מכין אותו כמ\"ש הטור שם אלא מנדין אותו ומכין אותו מ\"מ ומבדילין כו' וכמ\"ש הרמב\"ם הנ\"ל וכמו שמצינו בגמ' בכמה מקומות נגדוהו והרב השמיט מכות מרדות משום גי' בטור לחבטן כמ\"ש כאן וליתא כנ\"ל:\n\u0003 (ליקוט) או לחבטן. \u0004 צ\"ל לחבשן וכ\"ה בהגמ\"ר סוף סנהדרין (ע\"כ):","\u0003אלא כו'. \u0004 כמ\"ש בכמה מקומות שאפי' על עבירה קלה מדרבנן משמתינן וכמ\"ש בסי' שלד בי\"ד וכן מנגדינן וכמ\"ש בפ\"ד דפסחים וכן מ\"ש רב מנגיד כו':","\u0003וכ\"ז כו'. \u0004 כמ\"ש בפ\"ג דסנהדרין דאמר ר\"ג ליכהוייה כו' ועסי' ב':","\u0003ודוקא כו'. \u0004 בסוף ב\"ק שמטיה ר\"כ כו' וכן ברודף בסוף ברכות ברב שילא וכן במחתרת בסנהדרין ע\"ב ב' א\"ר כל דאתי עלאי במחתרתא כו' וז\"ש הרודף כו' הבא כו':","\u0003והזהירוהו. \u0004 ע\"ב ב' נימא מסייעא ליה א\"ל ראה כו' ועסי' שפח ס\"י בש\"ע והג\"ה:","\u0003אע\"פ כו'. \u0004 כמו בעובדא דרב שילא ועבה\"ג ועסי' שפח שם:","\u0003ואם ידוע כו'. \u0004 ע\"ב א\"ב:","\u0003מי שמסכן כו'. \u0004 אע\"פ שאין כוונתו לסכן כמו בעובדא דחמרא בסוף ב\"ק:","\u0003לפיכך כו'. \u0004 ל' מתני' מפני שחייה קודמין לחייו:","\u0003וזהו כו'. \u0004 גמ' שם ועבה\"ג וערש\"י שם ד\"ה יצא כו:","\u0003או אחר כו'. \u0004 ברייתא שם:","\u0003כיון שהערה כו'. \u0004 כמ\"ש ברפ\"ו דיבמות:","\u0003לעיני י' ישרא' כו'. \u0004 כמ\"ש בסנהדרין ע\"ד ב' אין כו' פשיטא כו':","\u0003ודוקא שהתרו כו'. \u0004 על מ\"ש הרמב\"ם אם פגעו בו קנאין הרי אלו משובחין וזריזין כ' הראב\"ד בד\"א שהתרו בו ולא פירש אבל לא התרו בו לא אמרינן הרי אלו משובחין ולמד בס\"א והזהירוהו כו':","\u0003אפיקורוס כו'. \u0004 ט\"ס הוא וצ\"ל כמ\"ש בש\"ע י\"ד סי' קנח ס\"ב מיני ישראל כו' ופ' כמ\"ד מין דר\"י ס\"ל כוותיה מפ' ברייתא בהוריות י\"א א' ועתוס' שם ד\"ה וח\"א כו' ע\"ש:","\u0003 (ליקוט) אם יש בידו כו'. \u0004 ר\"ל דמ\"ש מורידין היינו אם אין בידו כח להורגן דלא כר\"ח והג\"ה בסי' שפח סט\"ו (ע\"כ):","\u0003 (ליקוט) שאין כו'. \u0004 תוס' שם ד\"ה ולא כו' ע\"ש (ע\"כ):","\u0003בהמה דקה מישראל במקום כו'. \u0004 עסמ\"ע:","\u0003כגון כו'. \u0004 שם וגטין מז א':\n\u0003 (ליקוט) כגון אוכל כו'. \u0004 גמ' שם אני שונה כו' (ע\"כ):"]}],["הָרוֹאֶה אֶת חֲבֵרוֹ טוֹבֵעַ בַּיָּם, אוֹ לִסְטִים בָּאִין עָלָיו, אוֹ חַיָּה רָעָה בָּאָה עָלָיו, וְיָכוֹל לְהַצִּילוֹ הוּא בְּעַצְמוֹ \u0010y0\u0011 \u0010c0\u0011 אוֹ שֶׁיִּשְׂכֹּר אֲחֵרִים לְהַצִּיל, וְלֹא הִצִּיל; אוֹ שֶׁשָּׁמַע גּוֹיִם אוֹ מוֹסְרִים מְחַשְּׁבִים עָלָיו רָעָה, אוֹ טוֹמְנִים לוֹ פַּח וְלֹא גִלָּה אֹזֶן חֲבֵרוֹ וְהוֹדִיעוֹ; אוֹ שֶׁיָּדַע בְּגוֹי אוֹ בְּאַנָּס שֶׁהוּא בָּא עַל חֲבֵרוֹ, וְיָכוֹל לְפַיְּסוֹ בִּגְלַל חֲבֵרוֹ וּלְהָסִיר מַה שֶּׁבְּלִבּוֹ וְלֹא פִּיְּסוֹ, וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ, \u0010y1\u0011 עוֹבֵר עַל לֹא תַעֲמֹד עַל דַּם רֵעֶךָ \u0005(וַיִּקְרָא יט, טז)\u0006.",["\u0003שישכור אחרים. \u0004 דאילו להצילו בגופו מוהשבותו לו נפקא דאבידת גופו של חבירו צריך להשיב לו ומלא תעמוד על דם רעך מרבינן אפי' להוציא ממון ע\"י שישכור אחרים להצילו צריך. וכ' הרא\"ש והטור בסי' זה ז\"ל מיהו אם יש לו ממון להציל עצמו חייב לשלם לחבירו והביאו ברא\"ש ראיה לדבר ומהתימא שהשמיטו המחבר ומור\"ם ז\"ל:","\u0003עובר על לא תעמוד כו'. \u0004 ובהג\"מ כתבו דבירושלמי מסיק דצריך אפילו להכניס עצמו בספק סכנה עבור זה והביאו הב\"י וכ' ז\"ל ונראה שהטעם הוא מפני שהלה ודאי והוא ספק עכ\"ל גם זה השמיטו המחבר ומור\"ם ז\"ל ובזה י\"ל כיון שהפוסקים הרי\"ף והרמב\"ם והרא\"ש והטור לא הביאו בפסקיהן מ\"ה השמיטוהו ג\"כ:"],["\u0003 או שישכור אחרים כו' \u0004 עיין בסמ\"ע ס\"ק א' עד ומהתימה שהשמיטו המחבר ומור\"ם ז\"ל כו' כבר כתבו מור\"ם בי\"ד סי' רנ\"ג [רנ\"ב] ס\"ס י\"ב בהגהה בשם מרדכי ע\"ש וע\"ש בב\"י סכ\"ב בשם מהרי\"ו:"],"\u0010g0\u0011 הָרוֹאֶה אֶת חֲבֵרוֹ טוֹבֵעַ בַּיָּם, אוֹ לִסְטִים בָּאִין עָלָיו, \u0010r0\u0011 אוֹ חַיָּה רָעָה בָּאָה עָלָיו, וְיָכוֹל לְהַצִּילוֹ הוּא בְּעַצְמוֹ \u0010y0\u0011 \u0010c0\u0011 \u0010g1\u0011 אוֹ \u0010t0\u0011 שֶׁיִּשְׂכֹּר אֲחֵרִים לְהַצִּיל, וְלֹא הִצִּיל; אוֹ שֶׁשָּׁמַע גּוֹיִם אוֹ מוֹסְרִים מְחַשְּׁבִים עָלָיו רָעָה, אוֹ טוֹמְנִים לוֹ פַּח וְלֹא גִלָּה אֹזֶן חֲבֵרוֹ וְהוֹדִיעוֹ; אוֹ שֶׁיָּדַע בְּגוֹי אוֹ בְּאַנָּס שֶׁהוּא בָּא עַל חֲבֵרוֹ, וְיָכוֹל לְפַיְּסוֹ בִּגְלַל חֲבֵרוֹ וּלְהָסִיר מַה שֶּׁבְּלִבּוֹ וְלֹא פִּיְּסוֹ, וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ, \u0010y1\u0011 עוֹבֵר עַל לֹא תַעֲמֹד עַל דַּם רֵעֶךָ \u0005(וַיִּקְרָא יט, טז)\u0006.",{"g":["א) ל' הרמב\"ם בפ' א' מהלכות רוצח דין י\"ד בברייתא בפרק בן סורר ומורה ד\"ט דף ע\"ג","ב) אוקימתא דברייתא שם וכ' הרא\"ש ☜והניצול חייב לפרוע למציל מה שהוציא דאין אדם מחוייב להציל נפש חבירו בממונו היכא דאית ליה ממונא לניצול וכ\"כ הטור והסמ\"ע תמה בזה שהשמיטו המחבר והרמ\"א וכתבו הגמ\"יי ירושלמי מסיק אפילו להכניס עצמו בספק סכנה חייב וכ' בב\"י וכ\"מ ונראה שהטעם מפני שהלה ודאי והוא ספק וכתב הסמ\"ע שהשמיטו המחבר דין זה מאחר שהרי\"ף והרמב\"ם והרא\"ש וגם הטור לא כתבוהו ע\"כ וכל המקיים נפש אחת מישראל כאלו קיים עולם מלא"],"t":["\u0003שישכור. \u0004 כת' הש\"ך דמה שתמה הסמ\"ע על המחבר והרמ\"א שלא הביאו הדין דאם יש להמוצל ממון שחייב לשלם כבר כתבו הרמ\"א בי\"ד ס\"ס רנ\"ב בהג\"ה בשם המרדכי וע\"ש בב\"י סכ\"ב מ\"ש בשם מהרי\"ו עכ\"ל:"],"r":["\u0003 (ליקוט) או ח\"ר באה עליו. \u0004 דמש\"ש גוררתו ל\"ד וכמ\"ש בקדושין ח' ב' ופשוט הוא (ע\"כ):"]}],["\u0010y0\u0011 מִצְוֹת עֲשֵׂה לַעֲשׂוֹת אָדָם מַעֲקֶה לְגַגּוֹ, שֶׁנֶּאֱמַר: וְעָשִׂיתָ מַעֲקֶה לְגַגֶּךָ \u0010y1\u0011 \u0005(דְּבָרִים כב, ח)\u0006. וְהוּא שֶׁיִּהְיֶה בֵּית דִּירָה; אֲבָל בֵּית הָאוֹצָרוֹת וּבֵית הַבָּקָר וְכַיּוֹצֵא בָּהֶן, \u0010c0\u0011 אֵינוֹ זָקוּק לוֹ.\nכָּל בַּיִת \u0010y2\u0011 שֶׁאֵין בּוֹ ד' אַמּוֹת עַל ד' אַמּוֹת, פָּטוּר מִמַּעֲקֶה.\nבַּיִת \u0010y3\u0011 \u0010c1\u0011 שֶׁל שְׁנֵי שֻׁתָּפִים, חַיָּבִים בַּמַּעֲקֶה, שֶׁנֶּאֱמַר: כִּי יִפּוֹל הַנּוֹפֵל מִמֶּנּוּ \u0005(דְּבָרִים כב, ח)\u0006, לֹא תָּלָה אֶלָּא בַּנּוֹפֵל. אִם כֵּן לָמָּה נֶאֱמַר: גַּגֶּךָ \u0005(דְּבָרִים כב, ח)\u0006, לְמַעֵט בָּתֵּי כְּנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת, \u0010y4\u0011 לְפִי שֶׁאֵינָם עֲשׂוּיִים לְדִירָה.\nהָיְתָה \u0010y5\u0011 רְשׁוּת הָרַבִּים גָּבוֹהַּ מִגַּגּוֹ, \u0010y6\u0011 אֵינוֹ זָקוּק לְמַעֲקֶה, \u0010y7\u0011 שֶׁנֶּאֱמַר: כִּי יִפֹּל הַנוֹפֵל מִמֶּנּוּ \u0005(דְּבָרִים כב, ח)\u0006.\nגֹּבַהּ הַמַּעֲקֶה, אֵין פָּחוֹת \u0010y8\u0011 מִי' טְפָחִים, כְּדֵי שֶׁלֹּא יִפֹּל מִמֶּנּוּ הַנֹּפֵל. וְצָרִיךְ לִהְיוֹת הַמְּחִצָּה חֲזָקָה, כְּדֵי שֶׁיִּשָּׁעֵן אָדָם עָלֶיהָ וְלֹא תִּפֹּל.\nכָּל הַמַּנִּיחַ גַּגּוֹ בְּלֹא מַעֲקֶה בִּטֵּל מִצְוַת עֲשֵׂה; וְעָבַר עַל לֹא תַּעֲשֶׂה, שֶׁנֶּאֱמַר: וְלֹא תָשִׂים דָּמִים בְּבֵיתֶךָ \u0005(דְּבָרִים כב, ח)\u0006.\nאֶחָד הַגַּג \u0010y9\u0011 וְאֶחָד כָּל דָּבָר שֶׁיֵּשׁ בּוֹ סַכָּנָה וְרָאוּי שֶׁיִּכְשֹׁל בָּהּ אָדָם וְיָמוּת, כְּגוֹן שֶׁהָיְתָה לוֹ בְּאֵר \u0005(אוֹ בּוֹר)\u0006 בַּחֲצֵרוֹ, בֵּין שֶׁיֵּשׁ בּוֹ מַיִם בֵּין שֶׁאֵין בּוֹ מַיִם, חַיָּב לַעֲשׂוֹת חוּלְיָא גָבֹהַּ י' טְפָחִים, אוֹ לַעֲשׂוֹת לָהּ כִּסוּי, כְּדֵי שֶׁלֹּא יִפֹּל בָּהּ אָדָם וְיָמוּת.\nוְכֵן כָּל מִכְשׁוֹל שֶׁיֵּשׁ בּוֹ סַכָּנַת נְפָשׁוֹת, מִצְוַת עֲשֵׂה לַהֲסִירוֹ וּלְהִשָּׁמֵר מִמֶּנּוּ וּלְהִזָּהֵר בַּדָּבָר יָפֶה, שֶׁנֶּאֱמַר: הִשָּׁמֶר לְךָ וּשְׁמֹר נַפְשְׁךָ \u0005(דְּבָרִים ד, ט)\u0006. וְאִם לֹא הֵסִיר וְהִנִּיחַ הַמִּכְשׁוֹלוֹת הַמְבִיאִים לִידֵי סַכָּנָה בִּטֵּל מִצְוַת עֲשֵׂה \u0010y10\u0011 וְעָבַר בְּלֹא תָשִׂים דָּמִים \u0010y11\u0011 \u0005(דְּבָרִים ד, ט)\u0006.\nהַרְבֵּה דְּבָרִים אָסְרוּ חֲכָמִים מִפְּנֵי שֶׁיֵּשׁ בָּהֶם סַכָּנַת נְפָשׁוֹת, וּקְצָתָם נִתְבָּאֲרוּ בְּטוּר יו\"ד סִימָן קט\"ז, וְעוֹד יֵשׁ דְּבָרִים אֲחֵרִים, וְאֵלוּ הֵן: לֹא יַנִּיחַ פִּיו עַל הַסִילוֹן הַמְקַלֵּחַ וְיִשְׁתֶּה, וְלֹא יִשְׁתֶּה בַּלַּיְלָה מֵהַבְּאֵרוֹת וּמֵהָאֲגַמִּים, שֶׁמָּא יִבְלַע עֲלוּקָה וְהוּא אֵינוֹ רוֹאֶה. \u0005הַגָּה: וּכְבָר כָּתַבְתִּי דְבָרִים אֵלּוּ סִימָן קט\"ז בְּיוֹרֶה דֵעָה וע\"ש.\u0006\nכָּל הָעוֹבֵר עַל דְּבָרִים אֵלּוּ וְכַיּוֹצֵא בָּהֶם, וְאָמַר: הֲרֵינִי מְסַכֵּן בְּעַצְמִי וּמַה לַּאֲחֵרִים עָלַי בְּכָךְ, אוֹ: אֵינִי מַקְפִּיד בְּכָךְ, מַכִּין אוֹתוֹ מַכַּת מַרְדוּת. וְהַנִּזְהָר מֵהֶם, עָלָיו תָּבֹא בִּרְכַּת טוֹב:",["\u0003מצות עשה לעשות אדם מעקה. \u0004 כל סימן זה ליתא בטור והמחבר העתיקו מדברי הרמב\"ם שכ' סי' זה אות באות בפי\"א מהל' רוצח ושמירת נפש ומפני שדינים שבסימנים שלפני זה מיירי מדיני רציחה ושמירת נפש כתבן ג\"כ הרמב\"ם שם באותן הלכות מ\"ה סידר וקבע המחבר גם לזה כאן כמו שסידרם הרמב\"ם בהל' א' מ\"ש:","\u0003והוא שיהיה בית דירה \u0004 בסמוך ס\"ג יתבאר דלא נאמר בתורה גגך אלא להוציא בתים שאינם עשויים לדירה ע\"ש וכתב הכ\"מ שם על דברי הרמב\"ם אע\"ג דבספרי מרבינן להני מקרא דחייבים במעקה וכן כתוב הסמ\"ג מ\"מתנאי יש בדבר לענין אם מחוייבים המה במזוזה ופוסק הרמב\"ם כמ\"ד דפטורים המה במזוזה וס\"ל דה\"ה לענין מעקה דלא מקרי ביתך וס\"ל דבספרי דמחייבי אתיא כתנא דס\"ל דגם במזוזה חייב ולית הלכתא כוותיה עכ\"ל בקיצור ואם כן תימא על המחבר שבהל' מזוזה בי\"ד ר\"ס רפ\"ו סתם וכ' דרפת בקר ולולין ובית אוצרות שמן ויין חייבים במזוזה וכדעת הרי\"ף והרא\"ש ודלא כהרמב\"ם וכמ\"ש שם וכאן במעק' סתם המחבר וכתב דאין חייב במעקה ודין מעקה נלמד מדין מזוזה וכמ\"ש ונראה דהרמב\"ם [דהמחב'] הכריע וס\"ל דלענין מעקה כיון דאין דרך בני אדם להיות להן בית תשמיש ע\"ג דבית הבקר ובית האוצר ובית העצים מ\"ה אף אם לפעמים יקרה דידור שם אדם מ\"מ אין יוצאים ונכנסים כ\"כ שם למיחש שיפול משם להצטרך מעקה משא\"כ במזוזה דחייבה התורה בשביל הדר להיות מצות ה' נגד עיניו בביאתו וביציאתו בזה פסק דהדר שם צריך לקבוע מזוזה באותו פתח וק\"ל:","\u0003שאין בו ד' אמות כו'. \u0004 שאז אינו בית תשמיש ואינו ראוי לדירה:","\u0003של שני שותפין כו'. \u0004 פי' אע\"ג דכתיב לגגך מ\"מ מדתלה התורה טעם המעקה משום חשש דיפלו ממנו מה לי שהבית הוא של א' או של שנים:","\u0003לפי שאינם עשויה לדירה ואפילו המחייבים בית בקר ובית אוצרות במעקה וכנ\"ל מ\"מ מודים בזה מפני שבית הכנסת אין שום גגך שייך בו כלל דאף של הבאים מעבר לים היא וכן פירש\"י בפ' ראשית הגז:\u0004","\u0003ר\"ה גבוה כו'. \u0004 פי' ויש לחוש שיפלו מר\"ה ע\"ג הגג:","\u0003אינו זקוק למעקה. \u0004 פי' ול\"ת שיעשה מעקה ע\"ג גגו מלמטה למעלה עד שיהא י' טפחים גבוה מר\"ה דכיון דבני ר\"ה קדירא דבי שותפי נינהו פשיטא דאין עליהן לעשות מעקה לרה\"ר:","\u0003שנאמר כי יפול הנופל ממנו. \u0004 פי' ודרז\"ל ממנו ולא לתוכו וק\"ק ל\"ל מיעוטא דממנו ולא לתוכו הא בלה\"נ יכול הב\"ה לומר אי לא היה ביתי מכ\"ש שהיה נחבט וניזק או מת מנפילתו מגבהות ר\"ה לארץ ובדוחק י\"ל דה\"א דהיו צריכין למלאות במקום ביתו בעפר כדי להשותו ממטה לר\"ה:","\u0003מי' טפחים. \u0004 משמע מכל סביבו והיינו דלא כסמ\"ג ודלא כהראב\"ד בהשגותיו וע\"ש בכ\"מ דמפרש במאי פליגי:","\u0003ואחד כל דבר כו'. \u0004 בספרי מרבה כל הני מדכתי' ולא תשים דמים בביתך:","\u0003ועבר בלא תשים דמים \u0004 וז\"ל ד\"מ בסי' תכ\"ו כ' הרמב\"ם בהל' אבל בפי\"ד מצות עשה מדבריהם ללות אורחים ואמרו רז\"ל כל מי שאינו מלווה כאלו שופך דמים וכופין ללויה כדרך שכופין לצדקה כו' עד אפילו המלווה לחבירו ד' אמות יש לו שכר הרבה וכמה שיעור לויה שחייב אדם בה הרב לתלמיד עד עיבורה של עיר וא' לחבירו עד תחום שבת ותלמיד לרבו עד פרסה ואם היה רבו מובהק עד ג' פרסאות עכ\"ל רמב\"ם. ובילקוט מהר\"ש מצאתי האידנא אין נוהגין ללות תלמיד לרבו עד פרסה משום דבזמן הזה מוחלים על כבודם ויש לילך עמו או עם חבירו עד השער או לכל הפחות ד' אמות עכ\"ל וכ' הרמב\"ם עוד גמילות חסדים שבגופו שאין להן שיעור כגון ביקור חולים וניחום אבלים והוצאת המת והכנסת כלה והלוית אורחים אע\"פ שכל מצות אלו מדבריהם הרי הם בכלל ואהבת לרעך כמוך כל הדברים שאתה רוצה שיעשו אותן לך אחרים עשה אתה לאחיך בתורה ובמצות ושכר הלוית אורחים מרובה מן הכל והוא החוק שחקק אברהם אבינו ודרך החסד שנהג בהם מאכיל עוברי דרכים ומשקה אותן ומלווה אותן וגדולה הכנסת אורחים מקבלת פני השכינה שנאמר וירא והנה שלשה אנשים וירץ לקראתם ולוי תן יותר מהכנסתם עכ\"ל רמב\"ם וכן הוא במדרש בפרשת וירא עכ\"ל ד\"מ:","\u0003הרבה דברים אסרו כו'. \u0004 מדכתיב השמר לך ושמור נפשך מאוד:"],["\u0003 אינו זקוק לו כו'. \u0004 עיין בתשו' מבי\"ט ח\"ב סי' ק\"י:","\u0003 של שני שותפים כו'. \u0004 ובשותף עכו\"ם פסק ביש\"ש פי\"א דחולין דחייב ע\"ש אמנ' לפי מה שפסק מור\"ם בי\"ד סי' רפ\"ו ס\"א בהגה במזוזה דפטור' אפשר דהוא הדין במעקה ולפי המרדכי דע\"ז יש להסתפק:"],"\u0010y0\u0011 \u0010g0\u0011 \u0010r0\u0011 מִצְוֹת עֲשֵׂה לַעֲשׂוֹת אָדָם מַעֲקֶה לְגַגּוֹ, שֶׁנֶּאֱמַר: וְעָשִׂיתָ מַעֲקֶה לְגַגֶּךָ \u0010y1\u0011 \u0005(דְּבָרִים כב, ח)\u0006. וְהוּא שֶׁיִּהְיֶה בֵּית \u0010g1\u0011 \u0010t0\u0011 דִּירָה; אֲבָל בֵּית הָאוֹצָרוֹת וּבֵית הַבָּקָר וְכַיּוֹצֵא בָּהֶן, \u0010c0\u0011 אֵינוֹ זָקוּק לוֹ. \u0010g2\u0011\nכָּל בַּיִת \u0010y2\u0011 \u0010t1\u0011 שֶׁאֵין בּוֹ ד' אַמּוֹת עַל ד' אַמּוֹת, פָּטוּר מִמַּעֲקֶה. \u0010g3\u0011 \u0010r1\u0011\nבַּיִת \u0010y3\u0011 \u0010c1\u0011 שֶׁל שְׁנֵי \u0010t2\u0011 שֻׁתָּפִים, חַיָּבִים בַּמַּעֲקֶה, שֶׁנֶּאֱמַר: כִּי יִפּוֹל הַנּוֹפֵל מִמֶּנּוּ \u0005(דְּבָרִים כב, ח)\u0006, לֹא תָּלָה אֶלָּא בַּנּוֹפֵל. אִם כֵּן לָמָּה נֶאֱמַר: גַּגֶּךָ \u0005(דְּבָרִים כב, ח)\u0006, לְמַעֵט בָּתֵּי כְּנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת, \u0010y4\u0011 לְפִי שֶׁאֵינָם \u0010t3\u0011 עֲשׂוּיִים לְדִירָה. \u0010g4\u0011\nהָיְתָה \u0010y5\u0011 רְשׁוּת הָרַבִּים גָּבוֹהַּ מִגַּגּוֹ, \u0010y6\u0011 אֵינוֹ זָקוּק \u0010t4\u0011 לְמַעֲקֶה, \u0010y7\u0011 שֶׁנֶּאֱמַר: כִּי יִפֹּל הַנוֹפֵל \u0010t5\u0011 מִמֶּנּוּ \u0010g5\u0011 \u0010g6\u0011 \u0010r2\u0011 \u0005(דְּבָרִים כב, ח)\u0006.\nגֹּבַהּ הַמַּעֲקֶה, אֵין פָּחוֹת \u0010y8\u0011 מִי' \u0010t6\u0011 טְפָחִים, כְּדֵי שֶׁלֹּא יִפֹּל מִמֶּנּוּ \u0010g7\u0011 הַנֹּפֵל. וְצָרִיךְ לִהְיוֹת הַמְּחִצָּה חֲזָקָה, כְּדֵי שֶׁיִּשָּׁעֵן אָדָם עָלֶיהָ וְלֹא \u0010g8\u0011 \u0010r3\u0011 תִּפֹּל.\nכָּל הַמַּנִּיחַ גַּגּוֹ בְּלֹא מַעֲקֶה בִּטֵּל מִצְוַת עֲשֵׂה; וְעָבַר עַל לֹא תַּעֲשֶׂה, שֶׁנֶּאֱמַר: וְלֹא תָשִׂים דָּמִים בְּבֵיתֶךָ \u0010g9\u0011 \u0010r4\u0011 \u0005(דְּבָרִים כב, ח)\u0006.\nאֶחָד הַגַּג \u0010y9\u0011 וְאֶחָד כָּל דָּבָר שֶׁיֵּשׁ בּוֹ סַכָּנָה וְרָאוּי שֶׁיִּכְשֹׁל בָּהּ אָדָם וְיָמוּת, כְּגוֹן שֶׁהָיְתָה לוֹ בְּאֵר \u0010g10\u0011 \u0005(אוֹ בּוֹר)\u0006 בַּחֲצֵרוֹ, בֵּין שֶׁיֵּשׁ בּוֹ מַיִם בֵּין שֶׁאֵין בּוֹ מַיִם, חַיָּב לַעֲשׂוֹת חוּלְיָא גָבֹהַּ י' טְפָחִים, אוֹ לַעֲשׂוֹת לָהּ כִּסוּי, כְּדֵי שֶׁלֹּא יִפֹּל בָּהּ אָדָם וְיָמוּת. \u0010g11\u0011\nוְכֵן כָּל מִכְשׁוֹל שֶׁיֵּשׁ בּוֹ סַכָּנַת נְפָשׁוֹת, מִצְוַת עֲשֵׂה לַהֲסִירוֹ וּלְהִשָּׁמֵר מִמֶּנּוּ וּלְהִזָּהֵר בַּדָּבָר יָפֶה, \u0010r5\u0011 שֶׁנֶּאֱמַר: הִשָּׁמֶר לְךָ וּשְׁמֹר נַפְשְׁךָ \u0010r6\u0011 \u0005(דְּבָרִים ד, ט)\u0006. וְאִם לֹא הֵסִיר וְהִנִּיחַ הַמִּכְשׁוֹלוֹת הַמְבִיאִים לִידֵי סַכָּנָה בִּטֵּל מִצְוַת עֲשֵׂה \u0010y10\u0011 וְעָבַר בְּלֹא תָשִׂים \u0010g12\u0011 דָּמִים \u0010y11\u0011 \u0010g13\u0011 \u0010r7\u0011 \u0005(דְּבָרִים ד, ט)\u0006.\nהַרְבֵּה דְּבָרִים \u0010t7\u0011 אָסְרוּ חֲכָמִים מִפְּנֵי שֶׁיֵּשׁ בָּהֶם סַכָּנַת נְפָשׁוֹת, וּקְצָתָם נִתְבָּאֲרוּ בְּטוּר יו\"ד סִימָן קט\"ז, וְעוֹד יֵשׁ דְּבָרִים \u0010g14\u0011 אֲחֵרִים, וְאֵלוּ הֵן: לֹא יַנִּיחַ פִּיו עַל הַסִילוֹן הַמְקַלֵּחַ וְיִשְׁתֶּה, וְלֹא יִשְׁתֶּה בַּלַּיְלָה מֵהַבְּאֵרוֹת וּמֵהָאֲגַמִּים, שֶׁמָּא יִבְלַע \u0010g15\u0011 עֲלוּקָה וְהוּא אֵינוֹ רוֹאֶה. \u0005הַגָּה: וּכְבָר כָּתַבְתִּי דְבָרִים אֵלּוּ סִימָן קט\"ז בְּיוֹרֶה דֵעָה וע\"ש.\u0006 \u0010g16\u0011\nכָּל הָעוֹבֵר עַל דְּבָרִים אֵלּוּ וְכַיּוֹצֵא בָּהֶם, וְאָמַר: הֲרֵינִי מְסַכֵּן בְּעַצְמִי וּמַה לַּאֲחֵרִים עָלַי בְּכָךְ, אוֹ: אֵינִי מַקְפִּיד בְּכָךְ, \u0010g17\u0011 מַכִּין אוֹתוֹ מַכַּת מַרְדוּת. \u0010g18\u0011 וְהַנִּזְהָר מֵהֶם, עָלָיו תָּבֹא בִּרְכַּת טוֹב: \u0010g19\u0011",{"g":["א) ל' הרמב\"ם ריש פי\"א מהלכות רוצח ושמירת נפש","ב) כ' הכ\"מ והא דמחייב בספרי שם בית התבן ובית הבקר וכ\"כ הסמ\"ג אפשר שטעמו של רבינו משום דפ' קמא דיומא דף י\"א ע\"א לענין מזוזה אמרינן דתנאי היא ותנא דספרי סבר כמאן דמחייב ורבינו בהלכות מזוזה פוסק כמאן דפטור ע\"כ ונלע\"ד שטעמו משום דמאן דפוטר שם ביומא הוא מלתא דתנא קמא בסתמא ואמאן דמחייב איתא שם בברייתא ויש מחייבין משמע דמיעוטא נינהו:","\u0003ג) ברייתא בפ\"ק דסוכה דף ג' ע\"א:\u0004 ","\u0003ד) שם דין ב' מימרא דרבא ומודה ר' אלעאי וכו'\u0004 בפי\"א דחולין דף קל\"ו ע\"א ואע\"ג דאמר ר' חנינא מסורא (שם) דליתנהו להני כללי ופירש\"י להני כללי דאמר רבא וכו' אפשר שרבינו מפורש דלא קאי אלא לקצת דברים שאמר רבא ואין מעק' בכללן ובסמ\"ג כ' טעם אחר ואכמ\"ל","ה) שם בברייתא בפ\"ה דב\"ק דף נ\"א ע\"א","\u0003פירוש ולא לתוכו:\u0004 ","\u0003ו) שם פי\"א מהל' רוצח ושמירת נפש ד\"ג בספרי כמה מקום גבוה וכו'\u0004 וכפי' הסמ\"ג ויש להראב\"ד שם בהשגות פי' אחר בזה","ז) כ' הכ\"מ ופשוט הוא","ח) שם ושם בספרי ופשוט הוא","\u0003ט) שם ד\"ד ושם בספרי אין לי אלא גג מנין לרבות וכו'\u0004 ","י) כן הוא ברמב\"ם","כ) שם מעשה דחסיד בפ\"ה דברכות דף ל\"ג ע\"ב ומברייתא ר' נתן אומר מנין שלא יגדל אדם כלב רע וכו' בפ\"ק דב\"ק דף ק\"ו ע\"ב","ל) כ' הרמב\"ם בפי\"ד מה' אבל מצות עשה של דבריהם לבקר חולים (מבואר בי\"ד סימן של\"ה) ולנחם אבלים (מבואר שם בסימן שע\"ו) ולהוציא המת (מבואר שם בסי' שס\"א) ולהכניס הכל' (מבואר בא\"ה סי' ס\"ה) וללות האורחים ולהתעסק בכל צרכי הקבורה וכו' ואילו הן ג\"ח שבגופו שאין להם שיעור אע\"פ שכל מצות אלו מדבריהם הרי הם בכלל ואהבת לרעך כמוך כל הדברים שאתה רוצה שיעשו אותם לך אחרים עשה אתה אותן לאחיך בתורה ובמצות ☜ושכר הלוויה מרובה מן הכל והוא החק שחקק אברהם אבינו ודרך החסד שנהג בה מאכיל עוברי דרכים משקה אותן ומלוה אותן וגדולה הכנסת אורחים מהקבלת פני השכינה שנאמר וירא והנה שלשה אנשי' וגו' (שבת פי\"ח דף קל\"ו ע\"א) ולוויים יותר מהכנסתן חכמים אמרו כל שאינו מלוה כאלו שופך דמים (ברפ\"ט דסוטה דף מ\"ו ע\"ב) כופין ללויי' כדרך שכופין לצדקה ובית דין היו מתקנים שלוחים ללות אדם העובר ממקום למקום ואם נתעצלו בדבר זה מעלה עליהם באלו שפכו דמים אפילו המלוה את חבירו ד' אמות יש לו שכר הרבה כמה שיעור לויה שחייב האדם בה הרב לתלמיד וכו' (מבואר שם בגמרא) ובילקוט מהר\"ש מצאתי האידנא אין נוהגין ללות תלמיד לרבו עד פרסה משום דבזמן הזה מוחלין על כבודם ויש לילך עמו או עם חבירו עד השער או לכל הפחות ד' אמות עכ\"ל סמ\"ע בשם ד\"מ","מ) שם ד\"ה","נ) שם דין ו' ברייתא בפ\"ק דע\"א דף י\"ב ע\"א","כתבו התוס' בערוך גורס ערק' ופי' תולעת קטנה המצוייה במים ושהיא נופלת על הבשר ניתלת בו ומוצצה את הדם וכל זמן שהיא מוצצת היא נתמלאת מן הליחה שהיא מוצצת ומתנפח' עד שתהא כמו חבית קטנה וכשאדם בולעה בתוך המים מוצצת הליחה שבמיעיו ומתגדלת במעיו ונמצא כריסו צבה","ס) שם דין ה'","ע) ס\"ל דהם מדרבנן ואסמכינהו אקרא כדלעיל ס\"ט ומ\"מ מכין עליהם כמו שאר מצות דרבנן א\"נ קים להו שהם מדאורייתא ואין לוקין עליהם בדאשכחן חצי שיעור דאסור מן התורה ואין לוקין עליו ב\"י ביו\"ד סימן קט\"ז","פ) ל' המחבר כדי לסיים בדבר טוב","צ) נלע\"ד הטעם שהזהירה התורה על שמירת הנפש הוא מטעם שהקב\"ה ברא את העולם בחסדו להטיב להנבראים שיכירו גדולתו ולעבוד עבודתו בקיום מצותיו ותורתו כמו שאמר הכתוב כל הנקרא בשמי לכבודי בראתיו וכולי וליתן להם שכר טוב בעמלם והמסכן את עצמו כאלו מואס ברצון בוראו ואינו רוצה לא בעבודתו ולא במתן שכרו ואין לך זלזול אפקירותא יותר מזה ולשומעים יונעם ויהי נועם ה' אלהינו עלינו ומעשה ידינו כוננה עלינו בילא\"ו:"],"t":["\u0003דירה. \u0004 תימא על המחבר דגבי מזוזה ביו\"ד ר\"ס רפ\"ו סתם וכת' דרפת בקר ולולין ובית אוצרות שמן ויין חייבים במזוזה וכדעת הרי\"ף והרא\"ש ודלא כהרמב\"ם וכמ\"ש שם וכאן במעקה סתם דאינן חייבין במעקה ודין מעקה נלמד מדין מזוזה וכמ\"ש הכ\"מ ונראה דהמחבר הכריע וס\"ל דלענין מעקה כיון דאין דרך בני אדם להיות להן בית תשמיש ע\"ג בית הבקר ובית האוצר ובית העצים מש\"ה אף אם לפעמים יקרה דידור שם אדם מ\"מ אין שם יוצאים ונכנסים כל כך למיחש שיפול משם ולהצטרך מעקה משא\"כ במזוזה דחייבה התורה בשביל הדר להיות מצות ה' נגד עיניו בביאתו וביציאתו בזה פסק דהדר שם צריך לקבוע מזוזה באותו פתח עכ\"ל הסמ\"ע ועיין בתשובת מבי\"ט ח\"א סי' ק\"י:","\u0003שאין. \u0004 דאז אינו בית תשמיש ואינו ראוי לדירה. שם:","\u0003שותפים. \u0004 ובשותף עובד כוכבים פסק במהרש\"ל פי\"א דחולין סי' ב' דחייב ע\"ש אמנם לפי מה שפסק הרמ\"א בי\"ד סי' רפ\"ו ס\"א בהג\"ה דפטור במזוזה אפשר דה\"ה במעקה ולפי טעם המרדכי ספ\"ק דע\"ז יש להסתפק. ש\"ך:","\u0003לדירה. \u0004 אפילו המחייבים בית הבקר ובית האוצר במעקה כנ\"ל מ\"מ מודים בזה מפני שבה\"כ אין שום גגך שייך בו כלל דאף של הבאים מעבר לים הוא וכן פרש\"י בפרק ראשית הגז. סמ\"ע:","\u0003למעקה. \u0004 פירוש דל\"ת שיעשה מעקה ע\"ג גגו מלמטה למעלה עד שיהא גבוה י\"ט מר\"ה דכיון דבני ר\"ה קדירא דבי שותפי נינהו פשיטא דאין עליהן לעשות מעקה לר\"ה. שם:","\u0003ממנו. \u0004 ודרז\"ל ממנו ולא תוכו. וק\"ק ל\"ל מיעוטא דממנו הא בלאו הכי נמי יכול הבעל הבית לומר אי לאו ביתי מכ\"ש שהיה נחבט וניזק או מת מנפילתו מגבהות ר\"ה לארץ ובדוחק י\"ל דה\"א שיהא צריך למלאות במקום ביתו בעפר כדי להשוותו ממטה לר\"ה. שם:","\u0003טפחים. \u0004 משמע מכל סביבו ודלא כסמ\"ג ודלא כהראב\"ד בהשגותיו ועיין שם בכ\"מ דמפרש במאי פליגי. שם:","\u0003אסרו. \u0004 מדכתיב השמר לך ושמור נפשך מאד"],"r":["\u0003מ\"ע כו' והוא כו'. \u0004 ע' בליקוטים פ':\n\u0003 (ליקוט) והוא כו'. \u0004 בספרי אין לי אלא בית מנין לרבות הבונה את בית התבן בית הבקר ובית העצים ובית האוצרות ת\"ל לא תשים דמים בביתך יכול אף בונה בית שער אכסדרה ומרפסת ת\"ל בית מה בית מיוחד שהוא בית דירה יצאו אלו שאינן בית דירה וכ\"כ סמ\"ג אבל הרמב\"ם ס\"ל דהספרי אתי כמ\"ד בית התבן כו' חייבי' במזוזה והוא אזיל לשיטתו שפ' כמ\"ד שהם פטורין ממזוזה כמ\"ש בפ\"ו מה' מזוזה וטעמו לפי שהמסקנא שם כן אע\"ג דאיתותב רב יהודה מדאמרינן שם תניא רב שמואל בר יהודא קמיה דרבא כו' ומ' דרבא קבל מיניה דלא הקשה אלא פתחת כו' ולא איתות בר\"י אלא במ\"ש דסתמא ד\"ה חייב [פטור] ועבי\"ד סי' רפו ס\"ב שפ' שם כהחולקין על הרמב\"ם שפ' כרב כהנא דסתמא חייב וצ\"ע על המחבר שפ' כאן כהרמב\"ם וע' (ע\"כ):","\u0003בית כו'. \u0004 ס\"ל מש\"ש ליתנהו כו' היינו לכל הני כללי דכמה יוצאין מן הכלל והיינו דחשיב שם בכורה ומתנות ועוד דמ\"ש ליתנהו דהיינו ר' אלעאי חולק ולית הלכתא כוותיה דלא נהגו כוותיה אלא בראשית הגז:","\u0003גובה כו'. \u0004 כמ\"ש בב\"ב ולא את הגג בזמן שי\"ל מעקה כו' ובתוספתא פ\"ו דב\"ק חפר כו' ועשה לה חוליא גבוה י\"ט פטור כו' עשה לה חוליא פחות גובה מי\"ט חייב ודלא כסמ\"ג וכמ\"ש בס\"ז ועמ\"ש בליקו' שם:\n\u0003 (ליקוט) המעקה כו'. \u0004 הראב\"ד כ' דוקא ממקום דרשו והוא מקום הנמוך שבו אבל שאר צדדין ג\"ט ור\"ל משום דאמר בספרי כמה הוא מקום מעגלו ג\"ט בית דורסין עשרה וסמ\"ג פי' הספרי שבבור די בג\"ט וזהו מקום מעגלו אבל בבית י\"ט חבל הרמב\"ם לא ס\"ל כן וכמ\"ש בתוספתא בפ\"ו דב\"ק חפר כראוי וכסה כראוי עשה לה חוליא גבוה י\"ט כו' פטור עשה לה חוליא פחותה מי\"ט כו' חייב. וערפ\"ד דב\"ב במתני' (ע\"כ):\n\u0003 (ליקוט) גובה המעקה כו'. \u0004 בספרי פ' תצא כמה מקום מעגלו ג\"ט בית דורסין עשר ופי' סמ\"ג שבבור ג\"ט בבית י\"ט והראב\"ד שם פי' שממקום דרסו שהוא מקום הנמוך עשר אבל שאר צדדין ג\"ט אבל הרמב\"ם לא חילק כלל ואפשר שמפ' ג\"כ כפי' הראב\"ד אבל ס\"ל דגמ' פליג דקא' ברפ\"ד דב\"ב בזמן שי\"ל מעקה כו' וכן בירוש' שם (ע\"כ):","\u0003כל המניח כו'. \u0004 ספרי ועשית מעקה לגגך זו מ\"ע לא תשים דמים בביתך מל\"ת:","\u0003אחד כו'. \u0004 שם מעקה לגגך א\"ל אלא גג מנין לרבות בורות שיחין ומערות חריצין ונעיצין ת\"ל לא תשים דמים בביתך כו' ותוספתא כראוי וכסה כראוי עשה לה חוליא כו' וז\"ש כגון שהיתה כו' ודלא כסמ\"ג ועי' בליקוטים שם:","\u0003שנאמר השמר כו'. \u0004 פ\"ה דברכות:","\u0003ואם לא כו'. \u0004 כנ\"ל ס\"ו:","\u0003הרבה כו'. \u0004 ע' פ\"י דפסחים ובפ\"ק דחולין חמירא סכנתא כו' ובשבת קיג ב' אף בחול אסור:"]}]]};
